    private static boolean[] visited;         // DFS visited flag
    private static int[] marker;              // 0 = unprocessed, 1 = special (degree N‑1), 2 = visited (A)

    public static void main(String[] args) {
        /* try‑with‑resources guarantees proper closing of I/O streams */
        try (Scanner sc = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            readInput(sc);
            markDegreeNminus1Vertices();
            int root = findFirstNonSpecial();
            if (root >= 0) {
                dfs(root);
            }

            if (!isInducedSubgraphComplete()) {
                out.println("No");
                return;
            }

            assignFinalMarkers();
            out.println("Yes");
            for (int i = 0; i < n; ++i) {
                out.print(mapMarkerToChar(marker[i]));
            }
            out.println();

        }
    }

    /** Reads N, M and builds the adjacency matrix. */
    private static void readInput(Scanner sc) {
        n = sc.nextInt();
        int m = sc.nextInt();
        adj = new int[n][n];
        for (int i = 0; i < n; ++i) {
            Arrays.fill(adj[i], 0);
        }
        for (int i = 0; i < m; ++i) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            adj[u][v] = adj[v][u] = 1;
        }
    }

    /** Marks vertices whose degree equals N‑1 as “special” (future label B). */
    private static void markDegreeNminus1Vertices() {
        marker = new int[n];
        Arrays.fill(marker, 0);
        for (int v = 0; v < n; ++v) {
            if (degree(v) == n - 1) {
                marker[v] = 1;               // 1 denotes a special vertex
            }
        }
    }

    /** Returns the degree of a vertex (ignoring self‑loops). */
    private static int degree(int v) {
        int cnt = 0;
        for (int i = 0; i < n; ++i) {
            if (i != v && adj[v][i] == 1) {
                ++cnt;
            }
        }
        return cnt;
    }

    /** Finds the first vertex that is not special. */
    private static int findFirstNonSpecial() {
        for (int i = 0; i < n; ++i) {
            if (marker[i] == 0) {
                return i;
            }
        }
        return -1;
    }

    /** Depth‑first search that marks reachable non‑special vertices as visited. */
    private static void dfs(int start) {
        visited[start] = true;
        for (int i = 0; i < n; ++i) {
            if (adj[start][i] == 1 && !visited[i] && marker[i] == 0) {
                dfs(i);
            }
        }
    }

    /** Verifies that the subgraph induced by non‑special vertices is a clique. */
    private static boolean isInducedSubgraphComplete() {
        List<Integer> nonSpecial = new ArrayList<>();
        for (int i = 0; i < n; ++i) {
            if (marker[i] != 1) {                 // not a special vertex
                nonSpecial.add(i);
            }
        }

        for (int i = 0; i < nonSpecial.size(); ++i) {
            int u = nonSpecial.get(i);
            for (int j = i + 1; j < nonSpecial.size(); ++j) {
                int v = nonSpecial.get(j);
                if (adj[u][v] == 0) {
                    return false;                // missing edge → not a clique
                }
            }
        }
        return true;
    }

    /** Translates the internal markers into the final output letters. */
    private static void assignFinalMarkers() {
        // visited vertices become label A (temporarily store as marker = 2)
        for (int i = 0; i < n; ++i) {
            if (visited[i]) {
                marker[i] = 2;                  // 2 denotes visited → will map to 'a'
            }
        }
        // Vertices still marked 0 are non‑visited and non‑special → will map to 'c'
    }

    /** Maps a marker value to the character that must be printed. */
    private static char mapMarkerToChar(int markerValue) {
        return switch (markerValue) {
            case 1 -> OUT_B;                     // special → 'b'
            case 2 -> OUT_A;                     // visited   → 'a'
            default -> OUT_C;                    // others    → 'c'
        };
    }
}

import java.io.PrintStream;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored solution for CF_624C.
 *
 * <p>
 * The program reads an undirected graph, tries to assign each vertex one of the
 * letters {@code 'a'}, {@code 'b'}, or {@code 'c'} according to the problem's
 * constraints, and prints either {@code "Yes"} followed by the resulting string
 * or {@code "No"} if no valid assignment exists.
 * </p>
 */
public class CF_624C {

    // -------------------------------------------------------------------------
    // Constant definitions
    // -------------------------------------------------------------------------
    private static final char LETTER_B = 'b';
    private static final char LETTER_A = 'a';
    private static final char LETTER_C = 'c';
    private static final String NL = System.lineSeparator();

    // -------------------------------------------------------------------------
    // Entry point
    // -------------------------------------------------------------------------
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            solve(scanner);
        } catch (IllegalArgumentException e) {
            // Any parsing or input error results in an immediate "No"
            System.out.println("No");
        }
    }

    // -------------------------------------------------------------------------
    // Core algorithm
    // -------------------------------------------------------------------------
    private static void solve(Scanner scanner) {
        int vertexCount = scanner.nextInt();
        int edgeCount   = scanner.nextInt();

        // adjacency list
        @SuppressWarnings("unchecked")
        List<Integer>[] adjacency = (List<Integer>[]) new List[vertexCount];
        for (int i = 0; i < vertexCount; i++) {
            adjacency[i] = new ArrayList<>();
        }

        int[] degree = new int[vertexCount];

        // -----------------------------------------------------------------
        // Read edges
        // -----------------------------------------------------------------
        for (int i = 0; i < edgeCount; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            if (u < 0 || u >= vertexCount || v < 0 || v >= vertexCount) {
                throw new IllegalArgumentException("Vertex index out of range");
            }
            adjacency[u].add(v);
            adjacency[v].add(u);
            degree[u]++;
            degree[v]++;
        }

        // tentative label array, default unknown ('\0')
        char[] label = new char[vertexCount];
        java.util.Arrays.fill(label, '\0');

        // -----------------------------------------------------------------
        // Step 1: Vertices of degree (n‑1) must be labelled 'b'
        // -----------------------------------------------------------------
        for (int i = 0; i < vertexCount; i++) {
            if (degree[i] == vertexCount - 1) {
                label[i] = LETTER_B;
            }
        }

        // Variables that remember how many neighbours were already of type a / c
        int countA = -1;
        int countC = -1;

        // -----------------------------------------------------------------
        // Step 2: Assign 'a' or 'c' to the remaining vertices
        // -----------------------------------------------------------------
        for (int v = 0; v < vertexCount; v++) {
            if (label[v] != '\0') {
                continue; // already assigned (e.g., 'b')
            }

            // Determine which letter can be used for vertex v
            char chosenLetter;
            if (countA == -1) {
                chosenLetter = LETTER_A;
            } else if (countC == -1) {
                chosenLetter = LETTER_C;
            } else {
                // Both letters already decided – cannot assign a new distinct one
                System.out.println("No");
                printDebugInfo(v, label);
                return;
            }
            label[v] = chosenLetter;

            int sameLetterNeighbourCount = 0;
            for (int neighbour : adjacency[v]) {
                char neighbourLabel = label[neighbour];

                // Ignore neighbours that are still unlabelled or are 'b'
                if (neighbourLabel == '\0' || neighbourLabel == LETTER_B) {
                    continue;
                }

                // Any already labelled neighbour must have the same letter as v
                if (neighbourLabel != chosenLetter) {
                    System.out.println("No");
                    System.err.println(String.format(
                            "Vertex %d (%c) connects to vertex %d (%c)",
                            v, chosenLetter, neighbour, neighbourLabel));
                    return;
                }
                sameLetterNeighbourCount++;

                // Propagate the choice to an unlabelled neighbour if needed
                if (label[neighbour] == '\0') {
                    label[neighbour] = chosenLetter;
                }
            }

            // Store the count for later consistency checks
            if (chosenLetter == LETTER_A) {
                if (countA != -1 && countA != sameLetterNeighbourCount) {
                    System.out.println("No");
                    System.err.println(String.format(
                            "Expected %d A‑type neighbours, got %d",
                            countA, sameLetterNeighbourCount));
                    return;
                }
                countA = sameLetterNeighbourCount;
            } else { // LETTER_C
                if (countC != -1 && countC != sameLetterNeighbourCount) {
                    System.out.println("No");
                    System.err.println(String.format(
                            "Expected %d C‑type neighbours, got %d",
                            countC, sameLetterNeighbourCount));
                    return;
                }
                countC = sameLetterNeighbourCount;
            }
        }

        // -----------------------------------------------------------------
        // Final validation: each non‑'b' vertex must have at least one labelled neighbour
        // -----------------------------------------------------------------
        for (int v = 0; v < vertexCount; v++) {
            if (label[v] == LETTER_B) {
                continue;
            }
            boolean hasLabelledNeighbour = false;
            for (int neighbour : adjacency[v]) {
                if (label[neighbour] != '\0') {
                    hasLabelledNeighbour = true;
                    break;
                }
            }
            if (!hasLabelledNeighbour) {
                System.out.println("No");
                System.err.println("Vertex " + v + " is isolated after labelling");
                return;
            }
        }

        // If we reach this point the assignment is valid
        System.out.println("Yes");
        System.out.println(new String(label));
    }

    // -------------------------------------------------------------------------
    // Debug helper – prints current state when an error occurs
    // -------------------------------------------------------------------------
    private static void printDebugInfo(int vertex, char[] labels) {
        StringBuilder sb = new StringBuilder();
        sb.append("Debug at vertex ").append(vertex).append(NL);
        for (int i = 0; i < labels.length; i++) {
            sb.append("  ").append(i).append(": ")
              .append(labels[i] == '\0' ? '?' : labels[i]).append(NL);
        }
        System.err.print(sb.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 *
 * <p>What was refactored?
 *
 * <ul>
 *   <li>All I/O is handled by a dedicated {@link InputReader} that implements
 *       {@link AutoCloseable}.  Resources are released with try‑with‑resources.
 *   <li>Global mutable fields have been eliminated – the algorithm works on
 *       method parameters and local variables only.
 *   <li>Naming, constants and structure have been clarified (e.g. {@code group},
 *       {@code EDGE}, {@code SAME}, {@code OTHER} instead of magic numbers 1,2,3).
 *   <li>Algorithmic steps are split into small, well‑named private methods.
 *   <li>Error handling prints a concise message and aborts cleanly.
 *   <li>Duplication is removed (e.g. repeated tokenisation) and the code is
 *       now fully type‑safe.
 * </ul>
 *
 * <p>The functional behaviour – reading a graph, trying to assign one of the
 * three labels {@code 1, 2, 3} to each vertex and printing “Yes” together with the
 * resulting lowercase letter mapping or “No” – is preserved.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Constants that describe the three possible labels for a vertex       */
    /* --------------------------------------------------------------------- */
    private static final class Labels {
        static final int UNVISITED = 0;
        static final int SAME    = 1;   // corresponds to original “1”
        static final int OTHER   = 3;   // corresponds to original “3”
        static final int FREE    = 2;   // corresponds to original “2”
    }

    /* --------------------------------------------------------------------- */
    /*  Simple wrapper around a {@link BufferedReader} that provides tokenised  */
    /*  reading.  It implements {@link AutoCloseable} so it can be used in a   */
    /*  try‑with‑resources block.                                              */
    /* --------------------------------------------------------------------- */
    private static final class InputReader implements AutoCloseable {
        private final BufferedReader br;

        InputReader(BufferedReader br) {
            this.br = br;
        }

        /** Reads the next line, skipping empty ones. */
        String readNonEmptyLine() throws IOException {
            String line;
            do {
                line = br.readLine();
            } while (line != null && line.trim().isEmpty());
            return line;
        }

        /** Returns the next token from the current line, or {@code null} if EOF. */
        String nextToken() throws IOException {
            String line = readNonEmptyLine();
            if (line == null) {
                return null;
            }
            StringTokenizer st = new StringTokenizer(line, " \t");
            return st.hasMoreTokens() ? st.nextToken() : null;
        }

        /** Convenience wrappers for the primitive types. */
        int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
        long nextLong() throws IOException { return Long.parseLong(nextToken()); }
        double nextDouble() throws IOException { return Double.parseDouble(nextToken()); }
        String nextString() throws IOException { return nextToken(); }

        @Override public void close() throws IOException { br.close(); }
    }

    /* --------------------------------------------------------------------- */
    /*  Core solving logic – all heavy lifting lives here.                      */
    /* --------------------------------------------------------------------- */
    private static final class Solver {
        private final InputReader in;
        final StringBuilder out = new StringBuilder();

        Solver(InputReader in) {
            this.in = in;
        }

        /** Entry point used by {@link Main#main(String[])}. */
        void solve() throws IOException {
            int testCases = 1;                     // the original program used a fixed 1
            for (int t = 0; t < testCases; ++t) {
                // -----------------------------------------------------------------
                // 1) read the size of the graph
                // -----------------------------------------------------------------
                int n = readVertexCount();
                int m = readEdgeCount();

                // -----------------------------------------------------------------
                // 2) build the adjacency matrix (true = edge present)
                // -----------------------------------------------------------------
                boolean[][] adj = initAdjacencyMatrix(n);
                removeGivenEdges(adj, m);

                // -----------------------------------------------------------------
                // 3) assign a label (1,2,3) to each vertex
                // -----------------------------------------------------------------
                int[] group = new int[n];
                boolean possible = assignLabels(adj, group);

                // -----------------------------------------------------------------
                // 4) final validation that mirrors the original checks
                // -----------------------------------------------------------------
                if (possible) {
                    possible = validateConfiguration(adj, group);
                }

                // -----------------------------------------------------------------
                // 5) produce the required output
                // -----------------------------------------------------------------
                if (possible) {
                    out.append("Yes\n");
                    for (int label : group) {
                        out.append((char) ('a' + label - 1));
                    }
                } else {
                    out.append("No");
                }
            }
        }

        /** Reads N from the input stream. */
        private int readVertexCount() throws IOException {
            String token = in.nextToken();
            if (token != null && !token.isEmpty()) {
                return Integer.parseInt(token);
            }
            return in.nextInt();
        }

        /** Reads M from the input stream. */
        private int readEdgeCount() throws IOException {
            String token = in.nextToken();
            if (token != null && !token.isEmpty()) {
                return Integer.parseInt(token);
            }
            return in.nextInt();
        }

        /** Creates an N×N matrix filled with {@code true}. */
        private boolean[][] initAdjacencyMatrix(int n) {
            boolean[][] matrix = new boolean[n][n];
            for (boolean[] row : matrix) {
                Arrays.fill(row, true);
            }
            return matrix;
        }

        /** Removes the edges that are described later in the input. */
        private void removeGivenEdges(boolean[][] adj, int m) throws IOException {
            for (int i = 0; i < m; ++i) {
                String aToken = in.nextToken();
                String bToken = in.nextToken();
                int a = Integer.parseInt(aToken) - 1;
                int b = Integer.parseInt(bToken) - 1;
                adj[a][b] = false;
                adj[b][a] = false;
            }
        }

        /**
         * Tries to assign one of the three labels to every vertex respecting the
         * constraints encoded in {@code adj}.  Returns {@code true} iff a complete
         * assignment exists.
         */
        private boolean assignLabels(boolean[][] adj, int[] group) {
            final int UNVISITED = Labels.UNVISITED;
            final int SAME = Labels.SAME;
            final int OTHER = Labels.OTHER;
            final int FREE = Labels.FREE;

            Arrays.fill(group, UNVISITED);

            for (int v = 0; v < adj.length; ++v) {
                if (group[v] != UNVISITED) {
                    continue; // already processed
                }

                // -------------------------------------------------------------
                // Determine what label we must give to 'v' based on its neighbours.
                // -------------------------------------------------------------
                int requiredLabel = decideLabelForVertex(v, adj, group);
                if (requiredLabel == -1) {
                    // No explicit requirement – we can freely pick FREE.
                    group[v] = FREE;
                } else {
                    group[v] = requiredLabel;
                }

                // -------------------------------------------------------------
                // Propagate consequences to neighbours.
                // -------------------------------------------------------------
                propagateConsequences(v, adj, group);
            }

            // Fill any still‑unassigned vertices with FREE (label 2).
            for (int i = 0; i < group.length; ++i) {
                if (group[i] == UNVISITED) {
                    group[i] = FREE;
                }
            }
            return true; // at this point we only know whether a conflict arose
        }

        /**
         * Analyses the neighbourhood of {@code vertex} and decides which label
         * it must receive.  Returns {@code -1} if the vertex can stay unconstrained.
         */
        private int decideLabelForVertex(int vertex, boolean[][] adj, int[] group) {
            int sameNeighbourCount = 0;   // how many neighbours already have label 1 (SAME)
            int otherNeighbourCount = 0;  // how many neighbours already have label 3 (OTHER)
            boolean neighbourRequiresSame   = false;
            boolean neighbourRequiresOther  = false;

            for (int neighbour = vertex + 1; neighbour < adj.length; ++neighbour) {
                if (!adj[vertex][neighbour]) {
                    continue; // non‑edge – ignore for the constraint calculation
                }

                int gNeighbour = group[neighbour];
                switch (gNeighbour) {
                    case Labels.SAME:
                        if (neighbourRequiresSame) {
                            // two neighbours that force opposite constraints → conflict
                            return -1;
                        }
                        neighbourRequiresSame = true;
                        break;
                    case Labels.OTHER:
                        if (neighbourRequiresOther) {
                            return -1;
                        }
                        neighbourRequiresOther = true;
                        break;
                    case Labels.FREE:
                        // cannot infer anything yet
                        break;
                    default:
                        // UNVISITED – will be handled later during propagation
                        break;
                }

                // Count how many neighbours already carry each label
                if (gNeighbour == Labels.SAME) {
                    sameNeighbourCount++;
                } else if (gNeighbour == Labels.OTHER) {
                    otherNeighbourCount++;
                }
            }

            // -------------------------------------------------------------
            // Resolve the constraints that emerged from the neighbour analysis.
            // -------------------------------------------------------------
            if (neighbourRequiresSame && neighbourRequiresOther) {
                // Both constraints are active → impossible
                return -1;
            }

            if (neighbourRequiresSame) {
                // All neighbours that are already labelled force a SAME label.
                return Labels.SAME;
            }

            if (neighbourRequiresOther) {
                // All neighbours that are already labelled force an OTHER label.
                return Labels.OTHER;
            }

            // No explicit constraint – the vertex can stay FREE (label 2)
            return -1;
        }

        /**
         * Walks through the adjacency list of {@code start} and enforces the
         * consequences of the label that has been assigned to it.
         */
        private void propagateConsequences(int start, boolean[][] adj, int[] group) {
            final int SAME = Labels.SAME;
            final int OTHER = Labels.OTHER;
            final int FREE = Labels.FREE;

            Queue<Integer> queue = new ArrayDeque<>();
            queue.add(start);

            while (!queue.isEmpty()) {
                int v = queue.poll();
                int labelV = group[v];

                for (int to = 0; to < adj.length; ++to) {
                    if (v == to || !adj[v][to]) {
                        continue; // ignore self‑loops and non‑edges
                    }

                    int labelTo = group[to];
                    if (labelTo == Labels.UNVISITED) {
                        // Edge forces opposite label (SAME <-> OTHER)
                        group[to] = (labelV == SAME) ? OTHER : SAME;
                        queue.add(to);
                    } else if (labelTo == labelV) {
                        // Same label on an edge is forbidden
                        // We simply note the failure later in the validation step.
                    } else if (labelTo == FREE) {
                        // If the neighbour is still free, we can assign it the
                        // only label that does not break the edge constraint.
                        group[to] = (labelV == SAME) ? OTHER : SAME;
                        queue.add(to);
                    }
                }
            }
        }

        /**
         * Performs the final verification that mirrors the original program's
         * post‑processing checks.
         */
        private boolean validateConfiguration(boolean[][] adj, int[] group) {
            for (int i = 0; i < adj.length; ++i) {
                for (int j = i + 1; j < adj.length; ++j) {
                    boolean edge = adj[i][j];
                    int diff = Math.abs(group[i] - group[j]);

                    if (edge) {
                        if (diff > 1) {
                            return false; // edge forces labels to be at most 1 apart
                        }
                    } else {
                        if (diff > 1) {
                            return false; // non‑edge forces labels to be equal or differ by 0
                        }
                    }
                }
            }
            return true;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Program entry point                                                    */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        String filePath = (args.length > 0) ? args[0] : null;

        try (FileInputStream fis = (filePath == null)
                ? System.in
                : new FileInputStream(filePath);
             InputStreamReader isr = new InputStreamReader(fis);
             BufferedReader br = new BufferedReader(isr);
             InputReader reader = new InputReader(br)) {

            new Solver(reader).solve();
            System.out.print(((Solver) null).out); // just to print the collected output
        } catch (IOException e) {
            System.err.println("I/O error: " + e.getMessage());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Reads an undirected graph, checks whether it can be colored with at most two
 * colors such that adjacent vertices differ by at most one unit, and prints
 * the resulting coloring.
 *
 * <p>The program follows the same output contract as the original version:
 * <ul>
 *   <li>If the graph cannot be colored, it prints {@code No} and terminates.</li>
 *   <li>Otherwise it prints {@code Yes} followed by a string that represents
 *       the coloring (isolated vertices are represented by {@code 'b'}).</li>
 * </ul>
 */
public class GraphColoring {

    /** Uncolored state */
    private static final int UNCOLORED = -1;

    /** First color used for a vertex */
    private static final int COLOR_A = 0;

    /** Second color used for a vertex */
    private static final int COLOR_B = 1;

    /** Number of vertices */
    private final int vertexCount;

    /** Adjacency list representation of the graph */
    private final List<Integer>[] adjacency;

    /** Color of each vertex: {@code UNCOLORED}, {@code COLOR_A} or {@code COLOR_B} */
    private final int[] color;

    /**
     * Constructs a graph from the given vertex count and edge list.
     *
     * @param vertexCount number of vertices
     * @param edges       list of edges (each edge is a two‑element array)
     */
    public GraphColoring(int vertexCount, List<int[]> edges) {
        this.vertexCount = vertexCount;
        this.adjacency = new ArrayList[vertexCount];
        for (int i = 0; i < vertexCount; i++) {
            adjacency[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adjacency[u].add(v);
            adjacency[v].add(u);
        }
        this.color = new int[vertexCount];
        java.util.Arrays.fill(color, UNCOLORED);
    }

    /**
     * Attempts to color the component that contains {@code start}.
     *
     * @param start       vertex to start the BFS from
     * @return {@code true} if the component can be colored, {@code false} otherwise
     */
    private boolean bfsColorComponent(int start) {
        Deque<Integer> queue = new ArrayDeque<>();
        queue.add(start);
        color[start] = COLOR_A;

        boolean visitedAny = false;

        while (!queue.isEmpty()) {
            int u = queue.poll();
            visitedAny = true;

            for (int v : adjacency[u]) {
                if (color[v] == UNCOLORED) {
                    color[v] = opposite(color[u]);
                    queue.add(v);
                } else if (color[v] == color[u]) {
                    // adjacent vertices have the same color → impossible to satisfy constraints
                    return false;
                }
            }
        }

        // If the component is isolated, keep it uncolored (stay UNCOLORED)
        if (!visitedAny) {
            color[start] = UNCOLORED;
        }
        return true;
    }

    /** Returns the opposite color of the supplied one. */
    private static int opposite(int c) {
        return (c == COLOR_A) ? COLOR_B : COLOR_A;
    }

    /** Main driver – reads input, processes the graph, and prints the result. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer tk = new StringTokenizer(br.readLine());
            int vertexCount = Integer.parseInt(tk.nextToken());
            int edgeCount = Integer.parseInt(tk.nextToken());

            List<int[]> edgeList = new ArrayList<>(edgeCount);
            for (int i = 0; i < edgeCount; i++) {
                tk = new StringTokenizer(br.readLine());
                int u = Integer.parseInt(tk.nextToken()) - 1; // convert to 0‑based
                int v = Integer.parseInt(tk.nextToken()) - 1;
                edgeList.add(new int[]{u, v});
            }

            GraphColoring graph = new GraphColoring(vertexCount, edgeList);

            // Color each connected component
            for (int v = 0; v < vertexCount; v++) {
                if (graph.color[v] == UNCOLORED) {
                    if (!graph.bfsColorComponent(v)) {
                        System.out.println("No");
                        return;
                    }
                }
            }

            // Verify that adjacent vertices differ by at most one unit
            for (int u = 0; u < vertexCount; u++) {
                for (int v : graph.adjacency[u]) {
                    if (u < v) { // examine each edge once
                        if (graph.color[u] != UNCOLORED && graph.color[v] != UNCOLORED) {
                            if (Math.abs(graph.color[u] - graph.color[v]) > 1) {
                                System.out.println("No");
                                return;
                            }
                        }
                    }
                }
            }

            // Build the output string
            StringBuilder sb = new StringBuilder(vertexCount);
            for (int v = 0; v < vertexCount; v++) {
                if (graph.color[v] == UNCOLORED) {
                    sb.append('b');                 // isolated vertex representation
                } else {
                    sb.append((char) ('a' + graph.color[v])); // 0 → 'a', 1 → 'b'
                }
            }

            System.out.println("Yes");
            System.out.println(sb);
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Entry point of the application.
 * Handles I/O and delegates the core logic to {@link Solver}.
 */
public class Main {

    public static void main(String[] args) {
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            FastScanner scanner = new FastScanner(in);
            PrintWriter writer = new PrintWriter(out);

            Solver solver = new Solver();
            boolean result = solver.solve(scanner, writer);

            // Always close the writer (no exception is thrown inside Solver)
            writer.flush();
            writer.close();

            // The Solver already printed the answer, so we just exit.
        } catch (IOException e) {
            // In competitive programming this path is rarely taken,
            // but we keep it for completeness.
            throw new UncheckedIOException(e);
        }
    }
}

/**
 * Fast scanner based on {@link BufferedReader} and {@link StringTokenizer}.
 * Provides convenient methods used throughout the solution.
 */
final class FastScanner {

    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    FastScanner(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream));
    }

    /** Returns the next token or {@code null} if the stream is exhausted. */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Parses the next token as an {@code int}. */
    int nextInt() {
        return Integer.parseInt(next());
    }

    /** Closes the underlying reader. */
    void close() throws IOException {
        reader.close();
    }
}

/**
 * Core logic of the problem.
 * The class is deliberately stateless apart from the inputs it receives.
 */
final class Solver {

    /** Characters used for coloring vertices. */
    private static final char COLOR_B = 'b';
    private static final char COLOR_A = 'a';
    private static final char COLOR_C = 'c';

    /** Indicates whether the current coloring is still valid. */
    private boolean bipartite = true;

    /**
     * Executes the algorithm using the supplied scanner and writer.
     *
     * @param scanner input source
     * @param writer  output destination
     * @return {@code true} if the answer has been written (i.e. always {@code true})
     */
    boolean solve(FastScanner scanner, PrintWriter writer) {
        int n = scanner.nextInt();   // number of vertices
        int m = scanner.nextInt();   // number of edges to remove

        // ----- Graph construction -------------------------------------------------
        // Initially we have a complete undirected graph without self‑loops.
        boolean[][] adjacency = buildCompleteAdjacency(n);
        int[] degree = new int[n];

        // Fill degree array according to the complete adjacency.
        for (int i = 0; i < n; i++) {
            degree[i] = n - 1;
        }

        // Remove the given edges.
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            removeEdge(adjacency, degree, u, v);
        }

        // ----- Coloring attempt ---------------------------------------------------
        char[] colors = new char[n];
        Arrays.fill(colors, COLOR_B);

        // Start a DFS/BFS from every not‑yet‑colored vertex that still has neighbours.
        for (int i = 0; i < n; i++) {
            if (colors[i] == COLOR_B && degree[i] > 0) {
                dfs(i, adjacency, colors, COLOR_A);
            }
        }

        // If we discovered a conflict, answer "No" and stop.
        if (!bipartite) {
            writer.println("No");
            return true;
        }

        // ----- Consistency check ---------------------------------------------------
        // Verify that every present edge respects the allowed color pairs
        // (a↔c) and that absent edges correspond to the complement.
        for (int i = 0; i < n && bipartite; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) {
                    continue;
                }
                boolean adjacent = adjacency[i][j];
                boolean allowed = (colors[i] == COLOR_A && colors[j] == COLOR_C) ||
                                  (colors[i] == COLOR_C && colors[j] == COLOR_A);
                if (adjacent != allowed) {
                    writer.println("No");
                    bipartite = false;   // ensure we break out of outer loop
                }
            }
        }

        // ----- Output answer -------------------------------------------------------
        if (bipartite) {
            writer.println("Yes");
            writer.println(new String(colors));
        }
        return true;
    }

    /** Builds a complete adjacency matrix without self‑loops. */
    private static boolean[][] buildCompleteAdjacency(int n) {
        boolean[][] adj = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != j) {
                    adj[i][j] = true;
                }
            }
        }
        return adj;
    }

    /** Removes the undirected edge (u,v) from the adjacency matrix and updates degree. */
    private static void removeEdge(boolean[][] adjacency, int[] degree, int u, int v) {
        if (adjacency[u][v]) {
            adjacency[u][v] = false;
            adjacency[v][u] = false;
            degree[u]--;
            degree[v]--;
        }
    }

    /**
     * Depth‑first search that propagates alternating colors 'a' and 'c'.
     *
     * @param vertex   current vertex index
     * @param graph    adjacency matrix
     * @param colors   current coloring array (modified in‑place)
     * @param start    starting color for this component ('a' or 'c')
     */
    private void dfs(int vertex, boolean[][] graph, char[] colors, char start) {
        colors[vertex] = start;
        char opposite = opposite(start);

        for (int neighbor = 0; neighbor < graph.length; neighbor++) {
            if (!graph[vertex][neighbor]) {
                continue;               // not an edge => ignore
            }
            if (colors[neighbor] == COLOR_B) {
                dfs(neighbor, graph, colors, opposite);
            } else if (colors[neighbor] != opposite) {
                // Conflict detected – the component cannot be bipartite under our rule.
                bipartite = false;
            }
        }
    }

    /** Returns the complementary colour ('a' ↔ 'c'). */
    private static char opposite(char c) {
        return (c == COLOR_A) ? COLOR_C : COLOR_A;
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Main entry point.
 *
 * <p>This program reads graph data from standard input, tries to assign one of the
 * three colors {@code 'a', 'b', 'c'} to each vertex respecting adjacency constraints,
 * and prints either {@code "No"} if it is impossible or the coloring otherwise.
 */
public class Solution {

    /** characters used for the three colors */
    private static final char[] COLOR_CHARS = {'a', 'b', 'c'};

    /** possible colors (used internally as enum‑like values) */
    private enum Color {
        ONE(1), TWO(3), THREE(5); // actual values are irrelevant – only relative parity matters

        private final int value;

        Color(int value) {
            this.value = value;
        }

        int getValue() {
            return value;
        }
    }

    /** reader for fast input parsing */
    private static final class InputReader {
        private final BufferedReader br;

        InputReader(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** reads the next non‑empty line */
        private String readLine() throws IOException {
            String line;
            while ((line = br.readLine()) != null && line.trim().isEmpty()) {
                // skip blank lines
            }
            return line;
        }

        /** reads the next token */
        private String nextToken() throws IOException {
            String token;
            while (token == null || token.isEmpty()) {
                token = br.readLine();
            }
            return token;
        }

        /** reads an {@code int} */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** reads {@code int[]} of length {@code n} */
        int[] readIntArray(int n) throws IOException {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }

    /** holds the graph representation (adjacency list + matrix) */
    private static final class Graph {
        private final int n;               // number of vertices
        private final List<Integer>[] adj; // adjacency list
        private final int[][] matrix;      // adjacency matrix (0/1)

        Graph(int n) {
            this.n = n;
            this.adj = new ArrayList[n];
            for (int i = 0; i < n; i++) {
                adj[i] = new ArrayList<>();
            }
            this.matrix = new int[n][n];
        }

        /** adds an undirected edge (0‑based vertices) */
        void addEdge(int u, int v) {
            adj[u].add(v);
            adj[v].add(u);
            matrix[u][v] = matrix[v][u] = 1;
        }

        /** returns the adjacency list of a vertex */
        List<Integer> neighbours(int v) {
            return Collections.unmodifiableList(adj[v]);
        }

        /** checks whether an edge exists between {@code u} and {@code v} */
        boolean isAdjacent(int u, int v) {
            return matrix[u][v] == 1;
        }

        /** number of vertices with degree {@code n-1} (i.e. fully connected) */
        List<Integer> getFullyConnectedVertices() {
            List<Integer> fully = new ArrayList<>();
            for (int v = 0; v < n; v++) {
                if (adj[v].size() == n - 1) {
                    fully.add(v);
                }
            }
            return fully;
        }
    }

    /** orchestrates the coloring algorithm */
    private static final class ColorAssigner {
        private final Graph graph;
        private final int[] color;          // holds the assigned Color enum value for each vertex
        private final List<Integer> fullyConnected; // vertices that must receive Color.ONE

        ColorAssigner(Graph graph) {
            this.graph = graph;
            this.color = new int[graph.n];
            Arrays.fill(color, -1);
            this.fullyConnected = graph.getFullyConnectedVertices();
        }

        /** assigns colors and returns {@code true} if a valid coloring exists */
        boolean assign() {
            // All vertices of degree n‑1 are forced to color ONE
            for (int v : fullyConnected) {
                color[v] = Color.ONE.getValue();
            }

            int nextIndex = 0; // will hold the base index of the current DFS component
            for (int v = 0; v < graph.n; v++) {
                if (color[v] == -1) {
                    dfs(v, nextIndex);
                    nextIndex += 2; // the next component will need a different parity offset
                    if (nextIndex > 4) { // we only have three distinct colors
                        return false;
                    }
                }
            }
            return true;
        }

        /** depth‑first search that propagates a unique color label to the component */
        private void dfs(int src, int base) {
            color[src] = base;
            for (int nxt : graph.neighbours(src)) {
                if (color[nxt] == -1) {
                    dfs(nxt, base);
                }
            }
        }

        /** checks whether a pair of vertices respects the adjacency rule given their colors */
        boolean respects(int u, int v) {
            int cu = color[u];
            int cv = color[v];

            if (cu == cv || Math.abs(cu - cv) == 1) {
                // adjacent vertices are allowed only when colors differ by exactly 1 (including same)
                // but the original algorithm permits same colors as well – we keep the same rule.
                return graph.isAdjacent(u, v);
            }
            // non‑adjacent vertices must have colors that are equal or differ by 1
            return !graph.isAdjacent(u, v);
        }

        /** returns the final array of color indices (mapped to 'a'/'b'/'c') */
        char[] finalColors() {
            return Arrays.stream(color)
                    .mapToObj(idx -> COLOR_CHARS[idx % 3])
                    .collect(Collectors.toList())
                    .toArray(new char[0]);
        }
    }

    /** starting point */
    public static void main(String[] args) throws IOException {
        try (FastScanner fs = new FastScanner(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            int tests = 1; // we only process a single test case per program run
            while (tests-- > 0) {
                int n = fs.nextInt();
                int m = fs.nextInt();

                Graph graph = new Graph(n);
                for (int i = 0; i < m; i++) {
                    int u = fs.nextInt() - 1;
                    int v = fs.nextInt() - 1;
                    graph.addEdge(u, v);
                }

                ColorAssigner assigner = new ColorAssigner(graph);
                if (!assigner.assign()) {
                    out.println("No");
                    out.flush();
                    return;
                }

                // Verify all edges obey the rule – this mirrors the original validation step
                for (int i = 0; i < n; i++) {
                    for (int j = i + 1; j < n; j++) {
                        if (!assigner.respects(i, j)) {
                            out.println("No");
                            out.flush();
                            return;
                        }
                    }
                }

                // Build output string
                char[] ans = assigner.finalColors();
                out.println("Yes");
                for (char c : ans) {
                    out.print(c);
                }
                out.println();
            }
        }
    }

    /** tiny scanner wrapper used by the original code – kept for compatibility */
    private static final class FastScanner {
        private final BufferedReader br;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        String nextToken() throws IOException {
            String token;
            while (!isTokenAvailable()) {
                // block until something is available
                token = br.readLine();
                if (token == null) break;
            }
            // split on whitespace
            String[] tokens = token.split("\\s+");
            return tokens[0];
        }

        private boolean isTokenAvailable() throws IOException {
            // Very simple heuristic – in a real implementation you would use a StringTokenizer
            // but for brevity we reuse the original approach.
            return false;
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }
    }
}

/*  Refactored GraphString program  */
import java.util.*;
import java.util.stream.Collectors;

/**
 * Reads an undirected graph, attempts to partition its vertices into up to
 * three cliques (A, B, C) that satisfy the problem constraints, and prints a
 * coloring string composed of 'a', 'b' and 'c'. If no valid partition exists,
 * prints "No".
 *
 * The refactor focuses on readability, reuse, and Java‑idiomatic practices:
 *   – Clear separation of concerns (input, algorithm, output)
 *   – Immutable collections where appropriate
 *   – Descriptive method names and Javadoc
 *   – Use of modern Stream API and final constants
 */
public class GraphString {

    private static final char COLOR_A = 'a';
    private static final char COLOR_B = 'b';

    /* --------------------------------------------------------------------- */
    /* Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            Graph graph = readGraph(scanner);
            Optional<Partition> partition = findPartition(graph);

            if (partition.isPresent()) {
                printPartition(partition.get());
            } else {
                System.out.println("No");
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /* Input handling                                                       */
    /* --------------------------------------------------------------------- */
    private static Graph readGraph(Scanner scanner) {
        int vertexCount = scanner.nextInt();
        int edgeCount   = scanner.nextInt();

        List<Set<Integer>> adjacency = new ArrayList<>(vertexCount);
        for (int i = 0; i < vertexCount; i++) {
            adjacency.add(new HashSet<>());
        }

        for (int i = 0; i < edgeCount; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            addUndirectedEdge(adjacency, u, v);
        }
        return new Graph(adjacency);
    }

    private static void addUndirectedEdge(List<Set<Integer>> adjacency,
                                          int u, int v) {
        adjacency.get(u).add(v);
        adjacency.get(v).add(u);
    }

    /* --------------------------------------------------------------------- */
    /* Core algorithm                                                       */
    /* --------------------------------------------------------------------- */
    private static Optional<Partition> findPartition(Graph graph) {
        Set<Integer> setB = identifyUniversalVertices(graph);
        Set<Integer> remainingAfterB = graph.remaining(setB);

        /* Trivial case – every vertex is adjacent to every other vertex */
        if (setB.size() == graph.vertexCount()) {
            return Optional.of(new Partition(Collections.emptySet(),
                                            setB,
                                            Collections.emptySet()));
        }

        /* Find a maximal clique among the remaining vertices */
        Set<Integer> setA = findClique(remainingAfterB, graph);
        if (setA.size() + setB.size() == graph.vertexCount()) {
            return Optional.of(new Partition(setA, setB, Collections.emptySet()));
        }

        /* Look for a third clique */
        Set<Integer> remainingAfterA = remainingAfterB.stream()
                .filter(v -> !setA.contains(v))
                .collect(Collectors.toSet());

        Set<Integer> setC = findClique(remainingAfterA, graph);
        if (setA.size() + setB.size() + setC.size() != graph.vertexCount()) {
            return Optional.empty();
        }

        /* Verify that there are no missing edges between A and C */
        if (hasCrossEdgeBetween(setA, setC, graph)) {
            return Optional.empty();
        }

        return Optional.of(new Partition(setA, setB, setC));
    }

    /** Vertices that are adjacent to *all* other vertices. */
    private static Set<Integer> identifyUniversalVertices(Graph graph) {
        Set<Integer> universal = new HashSet<>();
        for (int v = 0; v < graph.vertexCount(); v++) {
            if (graph.isConnectedToAll(v)) {
                universal.add(v);
            }
        }
        return universal;
    }

    /** Returns true if any vertex of src is non‑adjacent to any vertex of dst. */
    private static boolean hasCrossEdgeBetween(Set<Integer> src,
                                               Set<Integer> dst,
                                               Graph graph) {
        for (int u : src) {
            for (int v : dst) {
                if (!graph.areAdjacent(u, v)) {
                    return true;      // missing edge → cross edge exists
                }
            }
        }
        return false;               // all edges present → no cross edge
    }

    /** Greedy extraction of a clique from the given candidate collection. */
    private static Set<Integer> findClique(Collection<Integer> candidates,
                                           Graph graph) {
        Set<Integer> clique = new HashSet<>();
        for (int vertex : candidates) {
            if (isAdjacentToAll(vertex, clique, graph)) {
                clique.add(vertex);
            }
        }
        return clique;
    }

    /** Checks adjacency of a vertex to every vertex in the provided set. */
    private static boolean isAdjacentToAll(int vertex,
                                           Set<Integer> otherSet,
                                           Graph graph) {
        for (int other : otherSet) {
            if (!graph.areAdjacent(vertex, other)) {
                return false;
            }
        }
        return true;
    }

    /* --------------------------------------------------------------------- */
    /* Output                                                               */
    /* --------------------------------------------------------------------- */
    private static void printPartition(Partition partition) {
        System.out.println("Yes");
        int n = partition.totalSize();
        char[] result = new char[n];

        partition.getA().forEach(v -> result[v] = COLOR_A);
        partition.getB().forEach(v -> result[v] = COLOR_B);
        partition.getC().forEach(v -> result[v] = 'c');

        System.out.println(new String(result));
    }

    /** Immutable container for the three resultant sets (A, B, C). */
    private static final class Partition {
        private final Set<Integer> a;
        private final Set<Integer> b;
        private final Set<Integer> c;

        Partition(Set<Integer> a, Set<Integer> b, Set<Integer> c) {
            this.a = Collections.unmodifiableSet(new HashSet<>(a));
            this.b = Collections.unmodifiableSet(new HashSet<>(b));
            this.c = Collections.unmodifiableSet(new HashSet<>(c));
        }

        Set<Integer> getA() { return a; }
        Set<Integer> getB() { return b; }
        Set<Integer> getC() { return c; }

        int totalSize() { return a.size() + b.size() + c.size(); }
    }

    /* --------------------------------------------------------------------- */
    /* Graph abstraction                                                      */
    /* --------------------------------------------------------------------- */
    private static final class Graph {
        private final List<Set<Integer>> adjacency;

        Graph(List<Set<Integer>> adjacency) {
            this.adjacency = Collections.unmodifiableList(
                    new ArrayList<>(adjacency));
        }

        int vertexCount() {
            return adjacency.size();
        }

        /** true iff `vertex` is adjacent to every other vertex */
        boolean isConnectedToAll(int vertex) {
            for (int other = 0; other < vertexCount(); other++) {
                if (other != vertex && !adjacency.get(other).contains(vertex)) {
                    return false;
                }
            }
            return true;
        }

        /** true iff `u` and `v` are adjacent */
        boolean areAdjacent(int u, int v) {
            return adjacency.get(u).contains(v);
        }

        /** Returns the vertex set of this graph minus the supplied collection. */
        Set<Integer> remaining(Collection<Integer> toRemove) {
            Set<Integer> remaining = new HashSet<>();
            for (int i = 0; i < vertexCount(); i++) {
                if (!toRemove.contains(i)) {
                    remaining.add(i);
                }
            }
            return remaining;
        }
    }
}

