import java.io.*;
import java.util.*;

// ---------------------------------------------------------------------------
// Fast I/O utilities
// ---------------------------------------------------------------------------

/** Simple wrapper around BufferedReader that returns the next token. */
final class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    FastScanner(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream));
        tokenizer = null;
    }

    boolean hasNext() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return false;
            tokenizer = new StringTokenizer(line);
        }
        return true;
    }

    /** Returns the next token, reading a new line if necessary. */
    String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }
}

/** Simple wrapper around PrintWriter that adds convenience methods. */
final class FastPrintWriter {
    private final PrintWriter writer;

    FastPrintWriter(OutputStream stream) {
        writer = new PrintWriter(new OutputStreamWriter(stream));
    }

    void println(String msg) {
        writer.println(msg);
    }

    void print(String msg) {
        writer.print(msg);
    }

    void flush() {
        writer.flush();
    }
}

// ---------------------------------------------------------------------------
// Graph validator – encapsulates the core algorithm
// ---------------------------------------------------------------------------

/**
 * Holds the adjacency structure and performs the validation described in the
 * original program.  All data members are deliberately private to enforce
 * encapsulation.
 */
final class GraphValidator {

    private final int vertexCount;
    private final List<Integer>[] adjacency;
    private final int[] visited;   // stores colour information: 0 = unvisited, 1/2/3 = colour
    private final int[] colour;    // final output colour (same as visited)

    GraphValidator(int vertexCount, List<Integer>[] adjacency) {
        this.vertexCount = vertexCount;
        this.adjacency = adjacency.clone();                 // defensive copy
        this.visited = new int[vertexCount];
        this.colour = new int[vertexCount];
    }

    /** Executes the validation and prints the required output. */
    void validate() {
        // 1️⃣  Mark vertices that are adjacent to all others (size == vertexCount)
        Arrays.fill(visited, 0);
        for (int i = 0; i < vertexCount; i++) {
            if (adjacency[i].size() == vertexCount) {
                visited[i] = 2;   // special status used by the original code
            }
        }

        // 2️⃣  First DFS attempt – colour with “1”
        for (int i = 0; i < vertexCount; i++) {
            if (visited[i] == 0) {
                if (!dfs(i, 1)) {
                    System.out.println("No");
                    return;
                }
                break;               // only one component needs this colour
            }
        }

        // 3️⃣  Second DFS attempt – colour remaining vertices with “3”
        for (int i = 0; i < vertexCount; i++) {
            if (visited[i] == 0) {
                if (!dfs(i, 3)) {
                    System.out.println("No");
                    return;
                }
                break;               // only one component needs this colour
            }
        }

        // 4️⃣  Any vertex still uncoloured → invalid graph
        for (int i = 0; i < vertexCount; i++) {
            if (visited[i] == 0) {
                System.out.println("No");
                return;
            }
        }

        // 5️⃣  All checks passed – output “Yes” and the letter representation
        System.out.println("Yes");
        for (int i = 0; i < vertexCount; i++) {
            System.out.print((char) ('a' + colour[i] - 1));
        }
    }

    /** Depth‑first search that checks the adjacency conditions and propagates colour. */
    private boolean dfs(int vertex, int currentColour) {
        visited[vertex] = currentColour;
        colour[vertex] = currentColour;

        for (int neighbour : adjacency[vertex]) {
            if (neighbour == vertex) continue;                     // self‑loop, ignore
            if (adjacency[neighbour].size() != vertexCount) continue; // only consider full‑adjacent vertices
            if (visited[neighbour] != 0) {
                if (visited[neighbour] != currentColour) return false; // colour conflict
                continue;
            }
            // Enforce that neighbour's adjacency set contains the current one identically
            if (adjacency[neighbour].size() != adjacency[vertex].size()
                    || !adjacency[neighbour].containsAll(adjacency[vertex])) {
                return false;
            }
            if (!dfs(neighbour, currentColour)) return false;
        }
        return true;
    }
}

// ---------------------------------------------------------------------------
// Entry point – orchestrates input, processing and output
