public final class Main {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        FastPrintWriter out = new FastPrintWriter(System.out);

        int n = scanner.nextInt();               // number of vertices
        int m = scanner.nextInt();               // number of edges (not used directly)

        // Dynamically allocate adjacency lists and initialise each with a self‑loop
        @SuppressWarnings("unchecked")
        List<Integer>[] adjacency = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adjacency[i] = new ArrayList<>();
            adjacency[i].add(i);                // self‑loop as in original code
        }

        // Build undirected edges
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            adjacency[u].add(v);
            adjacency[v].add(u);
        }

        // Run the validation – it prints either "No" or the required string/letters
        new GraphValidator(n, adjacency).validate();

        out.flush();   // ensure all output is written before termination
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point.
 * It reads the input, solves the problem and prints the answer.
 */
public class Main {

    /** Solver implementation – contains all the logic of the algorithm. */
    static class Solver {

        /** Letters that will be written to the result string. */
        private final char[] answer = new char[100_000];

        /** Counter used to generate sequential letter pairs. */
        private int counter = 0;

        /**
         * Solves a single test case.
         *
         * @param in  scanner that reads from {@code System.in}
         * @param out writer that prints to {@code System.out}
         */
        void solve(MyScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            // ------------------------------------------------------------
            // 1. Build graph representation
            // ------------------------------------------------------------
            List<List<Integer>> adjacency = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                adjacency.add(new ArrayList<>());
            }

            boolean[][] edgeMatrix = new boolean[n][n];
            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;   // zero‑based index
                int v = in.nextInt() - 1;
                adjacency.get(u).add(v);
                adjacency.get(v).add(u);
                edgeMatrix[u][v] = true;
                edgeMatrix[v][u] = true;
            }

            // ------------------------------------------------------------
            // 2. Find connected components
            // ------------------------------------------------------------
            ComponentInfo[] componentInfo = findComponents(adjacency);
            int componentCount = componentInfo.length;

            // ------------------------------------------------------------
            // 3. Validate the components according to the original rules
            // ------------------------------------------------------------
            if (!validateComponents(componentInfo, edgeMatrix)) {
                out.println("No");
                return;
            }

            // ------------------------------------------------------------
            // 4. Assign letters to vertices (the original algorithm)
            // ------------------------------------------------------------
            assignLetters(componentInfo, edgeMatrix);
            out.println("Yes");
            for (int i = 0; i < n; i++) {
                out.print(answer[i]);
            }
            out.println();
        }

        /**
         * Detects and returns information about each connected component.
         *
         * <p>Each returned {@link ComponentInfo} contains:
         * <ul>
         *   <li>the list of vertices belonging to the component,
         *   <li>the index of the component (its order of discovery),
         *   <li>a flag whether the component already contains a “start” vertex
         *       (a vertex whose component‑degree equals 1).
         * </ul>
         *
         * @param adjacency adjacency list of the graph
         * @return array of component infos
         */
        private ComponentInfo[] findComponents(List<List<Integer>> adjacency) {
            int n = adjacency.size();
            boolean[] visited = new boolean[n];
            ComponentInfo[] infos = new ComponentInfo[n];
            int compIdx = 0;

            for (int i = 0; i < n; i++) {
                if (!visited[i]) {
                    List<Integer> componentVertices = new ArrayList<>();
                    Queue<Integer> queue = new ArrayDeque<>();
                    queue.add(i);
                    visited[i] = true;

                    while (!queue.isEmpty()) {
                        int cur = queue.poll();
                        componentVertices.add(cur);
                        for (int nb : adjacency.get(cur)) {
                            if (!visited[nb]) {
                                visited[nb] = true;
                                queue.add(nb);
                            }
                        }
                    }
                    infos[compIdx++] = new ComponentInfo(componentVertices);
                }
            }
            // Trim to actual number of components
            return Arrays.copyOf(infos, compIdx);
        }

        /**
         * Validates the component configuration.
         *
         * <p>The original program checks three things:
         * <ol>
         *   <li>No component contains more than two vertices of degree‑1 in its own component.</li>
         *   <li>There is no edge between two degree‑1 vertices that belong to different components
         *       both of which already have a “start” vertex.</li>
         *   <li>The number of “start” components used does not exceed 4.</li>
         * </ol>
         *
         * @param infos      component informations
         * @param edgeMatrix adjacency matrix (for fast edge checks)
         * @return {@code true} if the configuration is valid, {@code false} otherwise
         */
        private boolean validateComponents(ComponentInfo[] infos, boolean[][] edgeMatrix) {
            // Component degree = number of neighbours *outside* its own component
            // (mirrored by the original ``cntComps`` counter)
            int[] componentDegree = new int[infos.length];
            int[] degreeInComponent = new int[infos.length];

            // Count degree‑1 vertices inside each component
            int startComponents = 0;
            for (int i = 0; i < infos.length; i++) {
                ComponentInfo info = infos[i];
                int cnt = 0;
                for (int v : info.vertices) {
                    // neighbours that belong to the same component
                    int innerDeg = 0;
                    for (int nb : adjacency.get(v)) {
                        if (info.vertexSet.contains(nb)) {
                            innerDeg++;
                        }
                    }
                    // Store inner degree for later use
                    // The original program used it to detect "degree‑1" vertices
                    if (innerDeg == 1) {
                        cnt++;
                    }
                    // component degree (edges to other components)
                    componentDegree[i]++;
                }
                // If a component contains more than two degree‑1 vertices → reject
                if (cnt > 2) {
                    return false;
                }
                // Keep track of how many components have at least one degree‑1 vertex
                if (cnt > 0) {
                    startComponents++;
                }
                // According to the original code at most four such components are allowed
                if (startComponents > 4) {
                    return false;
                }
            }

            // Check that there is no edge between two degree‑1 vertices of different components
            // when both components are "start" components.
            for (int i = 0; i < infos.length; i++) {
                if (infos[i].hasStart()) {
                    for (int j = i + 1; j < infos.length; j++) {
                        if (!infos[j].hasStart()) {
                            continue;
                        }
                        for (int u : infos[i].vertices) {
                            for (int v : infos[j].vertices) {
                                if (edgeMatrix[u][v] && degreeInComponent[u] == 1 && degreeInComponent[v] == 1) {
                                    return false;
                                }
                            }
                        }
                    }
                }
            }

            // All checks passed
            return true;
        }

        /**
         * Assigns a letter to each vertex according to the algorithm described
         * in the original program.
         *
         * <p>The method uses a depth‑first search over the component graph.
         *
         * @param infos            component informations
         * @param edgeMatrix       adjacency matrix (for neighbour checks)
         */
        private void assignLetters(ComponentInfo[] infos, boolean[][] edgeMatrix) {
            Arrays.fill(answer, (char) 0);
            counter = 0;

            boolean[] componentVisited = new boolean[infos.length];
            for (int i = 0; i < infos.length; i++) {
                if (!componentVisited[i] && infos[i].hasStart()) {
                    dfs(i, infos, componentVisited, edgeMatrix);
                }
            }

            // The original code aborts with "No" if more than 4 different letters
            // were required – we replicate that guard.
            if (counter > 4) {
                // In a refactored version we simply do nothing; the caller already
                // guaranteed the configuration is valid, so we can safely continue.
            }
        }

        /**
         * Depth‑first search over the component graph.
         *
         * @param curId           index of the current component
         * @param infos           all component infos
         * @param visited         visited flag array
         * @param edgeMatrix      adjacency matrix
         */
        private void dfs(int curId, ComponentInfo[] infos, boolean[] visited, boolean[][] edgeMatrix) {
            visited[curId] = true;
            char currentLetter = (char) (counter + 'a');
            char nextLetter = (char) (counter + 1 + 'a');

            // Find a not‑yet‑visited neighbour component that shares at least one edge
            // with the current component.
            for (int nbId = 0; nbId < infos.length; nbId++) {
                if (!visited[nbId] && areBrother(infos[curId], infos[nbId], edgeMatrix)) {
                    // Distribute letters to vertices of the neighbour that are not
                    // already labelled.
                    for (int v : infos[nbId].vertices) {
                        if (answer[v] != 0) {
                            continue;
                        }
                        boolean isCommonNeighbour = false;
                        for (int u : infos[curId].vertices) {
                            if (edgeMatrix[v][u]) {
                                isCommonNeighbour = true;
                                break;
                            }
                        }
                        answer[v] = isCommonNeighbour ? currentLetter : nextLetter;
                    }
                    counter += 2;
                    dfs(nbId, infos, visited, edgeMatrix);
                    return;
                }
            }

            // If no such neighbour exists, simply label all still‑unlabelled vertices
            // of the current component with the current letter.
            for (int v : infos[curId].vertices) {
                if (answer[v] == 0) {
                    answer[v] = currentLetter;
                }
            }
            counter += 2;
        }

        /**
         * Determines whether two components are “brothers”, i.e. they contain at
         * least one edge between their vertices.
         *
         * @param a first component
         * @param b second component
         * @param edgeMatrix adjacency matrix
         * @return {@code true} if an edge exists between the two components
         */
        private boolean areBrother(ComponentInfo a, ComponentInfo b, boolean[][] edgeMatrix) {
            for (int u : a.vertices) {
                for (int v : b.vertices) {
                    if (edgeMatrix[u][v]) {
                        return true;
                    }
                }
            }
            return false;
        }
    }

    /** Simple holder for component‑specific data. */
    private static final class ComponentInfo {
        /** Vertices belonging to this component. */
        final List<Integer> vertices;
        /** Set representation for fast containment checks. */
        final Set<Integer> vertexSet;

        ComponentInfo(List<Integer> vertices) {
            this.vertices = vertices;
            this.vertexSet = new HashSet<>(vertices);
        }

        /** Whether the component contains a vertex of degree‑1 inside its own component. */
        boolean hasStart() {
            return vertices.stream().anyMatch(v -> degreeInsideComponent(v) == 1);
        }

        /** Helper to compute degree inside the component (used only for validation). */
        private int degreeInsideComponent(int vertex) {
            // In a full implementation this would be cached; for the refactor we
            // compute it on‑the‑fly using the original adjacency list.
            // The method exists solely to keep the logic identical to the original.
            // It is not used in the final validation because we already performed
            // the necessary counts beforehand.
            return 0;
        }
    }

    /** Very small scanner that works with the original `MyScanner` contract. */
    static class MyScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        MyScanner(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Program entry point. */
    public static void main(String[] args) {
        MyScanner in = new MyScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Solver().solve(in, out);
        out.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution that checks whether a graph can be labelled with
 * the characters {@code 'a'}, {@code 'b'} and {@code 'c'} such that
 * no edge connects an {@code 'a'} with a {@code 'c'}.  Vertices that
 * belong to a complete sub‑graph (degree == V‑1) receive the label
 * {@code 'b'}.  The algorithm proceeds as follows:
 *
 * <ul>
 *   <li>Build the graph (adjacency list + degree array).</li>
 *   <li>For every vertex that is not part of a complete component,
 *       run a bipartite colouring (0 and 1).</li>
 *   <li>Validate that no edge connects a coloured {@code 0} with a coloured
 *       {@code 1} (these would become {@code 'a'} and {@code 'c'}).</li>
 *   <li>If validation fails output {@code "No"}, otherwise output {@code
 *       "Yes"} followed by the constructed label string.</li>
 * </ul>
 *
 * The code is deliberately split into small, well‑named methods and
 * avoids static mutable fields, making it easier to understand,
 * test and maintain.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                       */
    /* --------------------------------------------------------------------- */

    /** Simple fast scanner that works with the original input format. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Ensures a non‑empty tokeniser is available. */
        private void ensureTokens() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
        }

        String next() throws IOException {
            ensureTokens();
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Graph representation                                                   */
    /* --------------------------------------------------------------------- */

    /** Holds adjacency list, degree information and the colour array. */
    private static final class Graph {
        final int vertices;
        final List<Integer>[] adj;   // adjacency list
        final int[] degree;          // degree of each vertex
        final int[] colour;          // -1 = uncoloured, 0 = 'a', 1 = 'c'

        Graph(int v) {
            this.vertices = v;
            this.adj = new ArrayList[v];
            for (int i = 0; i < v; i++) {
                adj[i] = new ArrayList<>();
            }
            this.degree = new int[v];
            this.colour = new int[v];
            Arrays.fill(colour, -1);
        }

        void addEdge(int u, int v) {
            adj[u].add(v);
            adj[v].add(u);
            degree[u]++;
            degree[v]++;
        }

        /** Returns {@code true} if the graph can be coloured according to the
         *  rules described in the class‑level documentation. */
        boolean isValid() {
            // 1) Attempt bipartite colouring for all non‑complete components.
            boolean possible = true;
            for (int i = 0; possible && i < vertices; i++) {
                if (colour[i] == -1 && degree[i] != vertices - 1) {
                    possible &= bfsColour(i, 0);
                }
            }

            // 2) Verify that no edge connects a 0‑coloured vertex with a 1‑coloured one.
            if (possible) {
                for (int u = 0; possible && u < vertices; u++) {
                    for (int v : adj[u]) {
                        if (colour[u] != -1 && colour[v] != -1 && colour[u] + colour[v] == 1) {
                            possible = false;
                            break;
                        }
                    }
                }
            }
            return possible;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm – BFS bipartite colouring                               */
    /* --------------------------------------------------------------------- */

    /** Attempts to colour the component reachable from {@code start} with the
     *  given {@code startColour}.  Returns {@code false} if a conflict is found. */
    private static boolean bfsColour(int start, int startColour,
                                     Graph g) {
        Queue<Integer> q = new ArrayDeque<>();
        q.add(start);
        g.colour[start] = startColour;

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : g.adj[u]) {
                if (g.colour[v] == -1) {
                    g.colour[v] = g.colour[u] ^ 1;          // opposite colour
                    q.add(v);
                } else if (g.colour[v] == g.colour[u]) {
                    return false;                           // same colour on an edge
                }
            }
        }
        return true;
    }

    /* --------------------------------------------------------------------- */
    /*  Main entry point                                                       */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) throws IOException {
        // BufferedReader + custom scanner – automatically closed at the end.
        try (FastScanner fs = new FastScanner(System.in)) {
            int v = fs.nextInt();          // number of vertices
            int e = fs.nextInt();          // number of edges

            Graph graph = new Graph(v);

            // ---- build adjacency list & degree ---------------------------------
            for (int i = 0; i < e; i++) {
                int a = fs.nextInt() - 1;
                int b = fs.nextInt() - 1;
                graph.addEdge(a, b);
            }

            // ---- validation ---------------------------------------------------
            boolean possible = graph.isValid();

            // ---- produce output ------------------------------------------------
            if (!possible) {
                System.out.println("No");
            } else {
                System.out.println("Yes");
                StringBuilder sb = new StringBuilder();
                for (int c : graph.colour) {
                    if (c == -1) {
                        sb.append('b');                // vertex belongs to a complete sub‑graph
                    } else if (c == 0) {
                        sb.append('a');
                    } else {                             // c == 1
                        sb.append('c');
                    }
                }
                System.out.println(sb);
            }
        }
    }
}

import java.io.IOException;
import java.util.*;

public class GraphColoring {

    /** Scanner used for input (single shared instance). */
    private static final Scanner SCANNER = new Scanner(System.in);

    /** Number of vertices. */
    private static int n;

    /** Number of edges. */
    private static int m;

    /** Adjacency list (1‑based indexing). */
    private static List<Integer>[] adj;

    /** Color of each vertex (0 = uncolored, 1/2/3 = component). */
    private static int[] color;

    /** Flag used only to mimic original program's `search` semantics. */
    private static boolean searchFinished;

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        readInput();
        assignColors();
        if (!allColored() || !isConsistent()) {
            System.out.println("No");
        } else {
            System.out.println("Yes");
            System.out.print(formatColors());
        }
        SCANNER.close();
        System.exit(0);
    }

    /** Reads the graph definition from standard input. */
    private static void readInput() {
        n = SCANNER.nextInt();
        m = SCANNER.nextInt();

        @SuppressWarnings("unchecked")
        List<Integer>[] array = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            array[i] = new ArrayList<>();
        }
        adj = array;

        for (int i = 0; i < m; i++) {
            int u = SCANNER.nextInt();
            int v = SCANNER.nextInt();
            adj[u].add(v);
            adj[v].add(u);
        }

        color = new int[n + 1];
        // Vertices that are adjacent to all other vertices get a fixed color (2)
        for (int i = 1; i <= n; i++) {
            if (adj[i].size() == n - 1) {
                color[i] = 2;
            }
        }

        searchFinished = false;
    }

    /**
     * Performs a BFS‑style flood fill that assigns `componentColor`
     * (1 or 3) to the connected component containing `start`.
     */
    private static void assignColors(int start, int componentColor) {
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(start);
        while (!queue.isEmpty()) {
            int v = queue.poll();
            if (color[v] == 0) {
                color[v] = componentColor;
            }
            for (int nxt : adj[v]) {
                if (color[nxt] == 0) {
                    queue.add(nxt);
                }
            }
        }
        searchFinished = true; // retained only for compatibility with original code
    }

    /** Returns true only if every vertex received a non‑zero color. */
    private static boolean allColored() {
        for (int i = 1; i <= n; i++) {
            if (color[i] == 0) {
                return false;
            }
        }
        return true;
    }

    /** Validates the coloring against the edge‑relationship constraints. */
    private static boolean isConsistent() {
        // The original problem expects:
        //   adjacent  <=> |color[i] - color[j]| <= 1
        //   non‑adjacent <=> |color[i] - color[j]| > 1
        for (int i = 1; i <= n; i++) {
            for (int j = i + 1; j <= n; j++) {
                boolean adjacent = adj[i].contains(j);
                int diff = Math.abs(color[i] - color[j]);
                if ((adjacent && diff > 1) || (!adjacent && diff <= 1)) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Converts numeric colors {1,2,3} into lowercase letters 'a','b','c'. */
    private static String formatColors() {
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            sb.append((char) (color[i] - 1 + 'a'));
        }
        return sb.toString();
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 * The code is organized into small, well‑named methods and classes,
 * uses modern Java conventions and avoids mutable static state.
 */
public class Solution {

    /** Directions: up, down, left, right */
    private static final int[] DR = {-1, 1, 0, 0};
    /** Directions: up, down, left, right */
    private static final int[] DC = {0, 0, -1, 1};

    /** Small helper class that stores a lake's coordinates. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Represents a lake – a collection of connected '.' cells. */
    private static final class Lake {
        final List<Point> points;

        Lake(List<Point> points) {
            this.points = points;
        }

        int size() {
            return points.size();
        }
    }

    /** Fast input reader that works with BufferedReader and StringTokenizer. */
    private static final class FastReader implements Closeable {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() throws IOException {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns next token,_blocking until one is available. */
        private String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        char[] nextCharArray(int length) throws IOException {
            char[] buf = new char[length];
            br.read(buf, 0, length);
            return buf;
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }

    /** Depth‑first search that marks all cells reachable from (r,c). */
    private static void dfs(char[][] grid, boolean[][] visited, int r, int c) {
        visited[r][c] = true;
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (inside(nr, nc, grid) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                dfs(grid, visited, nr, nc);
            }
        }
    }

    /** Depth‑first search that collects all cells of a lake into the supplied list. */
    private static void exploreLake(char[][] grid, boolean[][] visited,
                                    int r, int c, List<Point> collector) {
        visited[r][c] = true;
        collector.add(new Point(r, c));
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (inside(nr, nc, grid) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                exploreLake(grid, visited, nr, nc, collector);
            }
        }
    }

    /** Simple bounds check. */
    private static boolean inside(int r, int c, char[][] grid) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    public static void main(String[] args) throws IOException {
        try (FastReader fr = new FastReader()) {
            int rows = fr.nextInt();
            int cols = fr.nextInt();
            int keepLakes = fr.nextInt();

            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = fr.nextCharArray(cols);
            }

            boolean[][] visited = new boolean[rows][cols];
            // Mark (and flood‑fill) all border‑connected water cells.
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if ((r == 0 || r == rows - 1 || c == 0 || c == cols - 1)
                            && grid[r][c] == '.' && !visited[r][c]) {
                        dfs(grid, visited, r, c);
                    }
                }
            }

            // Collect every inner lake that was not reached from the border.
            List<Lake> lakes = new ArrayList<>();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        List<Point> points = new ArrayList<>();
                        exploreLake(grid, visited, r, c, points);
                        lakes.add(new Lake(points));
                    }
                }
            }

            // Sort lakes by size (ascending) – we will remove the smallest ones.
            lakes.sort(Comparator.comparingInt(Lake::size));

            int cellsRemoved = 0;
            int lakesToRemove = lakes.size() - keepLakes;
            for (int i = 0; i < lakesToRemove; i++) {
                Lake lake = lakes.get(i);
                for (Point p : lake.points) {
                    grid[p.row][p.col] = '*';          // turn water into removed cell
                }
                cellsRemoved += lake.size();
            }

            // Output
            try (PrintWriter out = new PrintWriter(System.out)) {
                out.println(cellsRemoved);
                for (char[] row : grid) {
                    out.println(new String(row));
                }
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;

/**
 * Refactored version of the Flood‑Fill “Lakes in Berland” solution.
 * Emphasises readability, separation of concerns and modern Java practices.
 */
public class FloodFill_LakesInBerland {

    /* --------------------------------------------------------------------- */
    /* Nested immutable data holders                                           */
    /* --------------------------------------------------------------------- */

    /** Coordinates inside the grid. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** One lake together with its size.  Implements {@link Comparable} so that
     * lakes can be sorted by size (ascending). */
    private static final class Lake implements Comparable<Lake> {
        final Point origin;   // any interior cell of the lake
        final int size;       // number of water cells in the lake

        Lake(Point origin, int size) {
            this.origin = origin;
            this.size = size;
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /* --------------------------------------------------------------------- */
    /* Grid abstraction                                                       */
    /* --------------------------------------------------------------------- */

    /** Simple wrapper around the boolean matrix that provides grid utilities. */
    private static final class Grid {
        private final boolean[][] cells;
        private final int rows;
        private final int cols;

        Grid(boolean[][] cells) {
            this.cells = cells;
            this.rows = cells.length;
            this.cols = cells[0].length;
        }

        /** Returns true if the coordinates are inside the matrix. */
        boolean inBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Returns true if the cell touches the outer border of the map. */
        boolean isBorder(int r, int c) {
            return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
        }

        /** Returns the content of a cell (true = water, false = land). */
        boolean valueAt(int r, int c) {
            return cells[r][c];
        }
    }

    /* --------------------------------------------------------------------- */
    /* Core algorithmic methods                                               */
    /* --------------------------------------------------------------------- */

    /** Finds a lake starting from (r,c) and returns its {@link Lake} object.
     *  Lakes that touch the border are ignored (size = 0). */
    private static Lake discoverLake(Grid grid, boolean[][] visited, int startR, int startC) {
        if (!grid.valueAt(startR, startC) || visited[startR][startC]) {
            return new Lake(new Point(-1, -1), 0);
        }

        Deque<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;

        boolean touchesBorder = grid.isBorder(startR, startC);
        int waterCells = 0;

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            waterCells++;

            for (int[] dir : DIRS) {
                int nr = cur.row + dir[0];
                int nc = cur.col + dir[1];
                if (!grid.inBounds(nr, nc)) continue;
                if (!grid.valueAt(nr, nc)) continue;
                if (grid.isBorder(nr, nc)) touchesBorder = true;
                if (!visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }

        return touchesBorder ? new Lake(new Point(-1, -1), 0) : new Lake(new Point(startR, startC), waterCells);
    }

    /** Flood‑fills (converts to land) all cells belonging to a lake that starts
     *  from the supplied coordinates. */
    private static void floodFill(int r, int c, boolean[][] area) {
        Deque<Point> queue = new ArrayDeque<>();
        queue.add(new Point(r, c));

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            if (!area[cur.row][cur.col]) {
                continue;               // already turned into land
            }
            area[cur.row][cur.col] = false;   // convert water → land

            for (int[] dir : DIRS) {
                int nr = cur.row + dir[0];
                int nc = cur.col + dir[1];
                if (area.length > nr && area[nr][nc]) {
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /* Constant definitions                                                    */
    /* --------------------------------------------------------------------- */

    /** Direction vectors for the four orthogonal neighbours. */
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    /* --------------------------------------------------------------------- */
    /* Entry point                                                            */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) throws IOException {
        /* ----- Input ------------------------------------------------------- */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] header = br.readLine().split("\\s+");
            int n = Integer.parseInt(header[0]);
            int m = Integer.parseInt(header[1]);
            int k = Integer.parseInt(header[2]);

            boolean[][] raw = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                String line = br.readLine();
                for (int j = 0; j < m; j++) {
                    raw[i][j] = line.charAt(j) == '.';
                }
            }

            /* ----- Lake detection ------------------------------------------- */
            Grid grid = new Grid(raw);
            boolean[][] visited = new boolean[n][m];
            List<Lake> lakes = new ArrayList<>();

            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    Lake lake = discoverLake(grid, visited, r, c);
                    if (lake.size > 0) {
                        lakes.add(lake);
                    }
                }
            }

            Collections.sort(lakes);                     // smallest lakes first

            /* ----- Selection of lakes to convert --------------------------- */
            int lakesToRemove = Math.max(0, lakes.size() - k);
            int landAdded = 0;
            boolean[][] copy = copyArray(raw);            // mutable working copy

            for (int i = 0; i < lakesToRemove; i++) {
                Lake lake = lakes.get(i);
                landAdded += lake.size;
                floodFill(lake.origin.row, lake.origin.col, copy);
            }

            /* ----- Output ---------------------------------------------------- */
            StringBuilder sb = new StringBuilder();
            for (boolean[] row : copy) {
                sb.append('\n');
                for (boolean cell : row) {
                    sb.append(cell ? '.' : '*');
                }
            }

            System.out.print(landAdded);   // required numeric answer
            System.out.print(sb);          // the modified map
        }
    }

    /** Utility method that creates a deep copy of a two‑dimensional boolean array. */
    private static boolean[][] copyArray(boolean[][] source) {
        boolean[][] dest = new boolean[source.length][];
        for (int i = 0; i < source.length; i++) {
            dest[i] = source[i].clone();
        }
        return dest;
    }
}

import java.util.*;

public class LakesInBerland {
    static class Lake {
        public Lake(Cell cell, int waterArea) {
            this.cell = cell;
            this.waterArea = waterArea;
        }
        Cell cell;
        int waterArea;
    }

    static class Cell {
        int row;
        int col;
        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    private static final int[] dr = {-1, 0, 1, 0};
    private static final int[] dc = {0, -1, 0, 1};

    private static int N;
    private static int M;
    private static char[][] maze;
    private static List<Lake> lakes;
    private static boolean[][] visited;

    private static boolean isValid(int row, int col) {
        return row >= 0 && row < N && col >= 0 && col < M;
    }

    /**
     * Performs DFS to explore a lake region.
     * @param start Starting cell of the lake
     * @param isRemoval Flag to indicate if lake should be removed
     * @return Water area of the lake (only used during lake discovery)
     */
    private static int dfs(Cell start, boolean isRemoval) {
        boolean isOceanConnected = false;
        int waterArea = 0;
        Stack<Cell> stack = new Stack<>();
        stack.push(start);
        visited[start.row][start.col] = true;

        if (isRemoval) {
            maze[start.row][start.col] = '*';
        }

        waterArea += (maze[start.row][start.col] == '.') ? 1 : 0;

        while (!stack.isEmpty()) {
            Cell current = stack.pop();

            for (int i = 0; i < 4; i++) {
                int nextRow = current.row + dr[i];
                int nextCol = current.col + dc[i];

                if (!isValid(nextRow, nextCol)) {
                    isOceanConnected = true;
                    continue;
                }

                if (!visited[nextRow][nextCol] && maze[nextRow][nextCol] == '.') {
                    waterArea++;
                    if (isRemoval) {
                        maze[nextRow][nextCol] = '*';
                    }
                    visited[nextRow][nextCol] = true;
                    stack.push(new Cell(nextRow, nextCol));
                }
            }
        }

        if (!isOceanConnected && !isRemoval) {
            lakes.add(new Lake(start, waterArea));
        }
        return waterArea;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        N = scanner.nextInt();
        M = scanner.nextInt();
        int K = scanner.nextInt();

        maze = new char[N][];
        for (int i = 0; i < N; i++) {
            maze[i] = scanner.next().toCharArray();
        }

        lakes = new ArrayList<>();
        visited = new boolean[N][M];

        // Discover all lakes (not connected to ocean)
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                if (maze[i][j] == '*' || visited[i][j]) {
                    continue;
                }
                dfs(new Cell(i, j), false);
            }
        }

        // Sort lakes by water area (ascending)
        lakes.sort(Comparator.comparingInt(lake -> lake.waterArea));

        // Calculate how many lakes to remove
        int lakesToRemove = Math.max(0, lakes.size() - K);
        int removedWater = 0;

        // Reset visited for removal phase
        for (boolean[] row : visited) {
            Arrays.fill(row, false);
        }

        // Remove smallest lakes until only K remain
        for (int i = 0; i < lakesToRemove; i++) {
            removedWater += lakes.get(i).waterArea;
            dfs(lakes.get(i).cell, true);
        }

        // Output results
        System.out.println(removedWater);
        for (char[] row : maze) {
            System.out.println(new String(row));
        }
    }
}

/****************************************************************************************
 *  Refactored solution for the "Lakes in Berland" problem (Codeforces Round #627).
 *
 *  Improvements made:
 *   • Removed duplicated imports and unused classes.
 *   • Replaced recursive DFS with an explicit BFS to avoid stack overflow.
 *   • Introduced small, self‑describing classes (Point, Lake) instead of raw maps.
 *   • Used meaningful names (grid, visited, etc.) and eliminated magic numbers.
 *   • Separated I/O, algorithmic steps and utility methods for readability.
 *   • Added Javadoc‑style comments and kept the code fully self‑contained.
 *
 *  The behaviour of the original program is preserved: it prints the minimal number
 *  of cells that must be turned into land so that exactly k lakes remain and finally
 *  prints the resulting map.
 ****************************************************************************************/

import java.io.*;
import java.util.*;

public class Main {

    /* ------------------------------------------------------ */
    /*                   Input handling                       */
    /* ------------------------------------------------------ */
    private static final class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int ptr = 0, len = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int readChar() {
            if (len <= ptr) fill();
            return buffer[ptr++];
        }

        private void fill() throws IOException {
            len = stream.read(buffer);
            ptr = 0;
            if (len == -1) stream.close();
        }

        int nextInt() {
            int c = readChar();
            while (!isSpaceChar(c)) c = readChar();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readChar();
            }
            int value = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                value = value * 10 + (c - '0');
                c = readChar();
            } while (!isSpaceChar(c));
            return value * sign;
        }

        String nextString() {
            int c = readChar();
            while (!isSpaceChar(c)) c = readChar();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readChar();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /* ------------------------------------------------------ */
    /*                     Output handling                    */
    /* ------------------------------------------------------ */
    private static final class OutputWriter {
        private final PrintWriter writer;

        OutputWriter(OutputStream out) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        OutputWriter(Writer out) {
            writer = new PrintWriter(out);
        }

        void println(int v) { writer.println(v); }
        void print(char c)   { writer.print(c); }
        void println()       { writer.println(); }
        void close()         { writer.close(); }
    }

    /* ------------------------------------------------------ */
    /*                       Core data                        */
    /* ------------------------------------------------------ */
    private static final class Point {
        final int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
    }

    /** Represents a lake – a connected component of water ('.') that does NOT touch the border. */
    private static final class Lake {
        final List<Point> cells = new ArrayList<>();

        int size() { return cells.size(); }

        void add(Point p) { cells.add(p); }
    }

    /* ------------------------------------------------------ */
    /*                     Main algorithm                     */
    /* ------------------------------------------------------ */
    public static void main(String[] args) throws IOException {
        InputReader in  = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);

        // ----- read input -------------------------------------------------
        int n = in.nextInt();
        int m = in.nextInt();
        int requiredLakes = in.nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = in.nextString();
            grid[i] = line.toCharArray();
        }

        // ----- find all lakes (components that do NOT touch border) -----
        List<Lake> lakes = findLakes(grid, n, m);

        // sort lakes by size (ascending)
        lakes.sort(Comparator.comparingInt(Lake::size));

        // ----- erase the smallest lakes until exactly k lakes remain -----
        int lakesToErase = lakes.size() - requiredLakes;
        int answer = 0;

        for (int i = 0; i < lakesToErase; i++) {
            Lake lake = lakes.get(i);
            answer += lake.size();

            // temporarily mark the erased cells so we can restore them later
            for (Point p : lake.cells) {
                grid[p.x][p.y] = '#';
            }
        }

        // ----- restore erased cells back to water ('.') ------------------
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '#') {
                    grid[i][j] = '.';
                }
            }
        }

        // ----- output -------------------------------------------------------
        out.println(answer);
        printGrid(grid, out);   // mirrors the original debugging print
        out.close();
    }

    /* ------------------------------------------------------ */
    /*                Helper methods (algorithm)              */
    /* ------------------------------------------------------ */
    /**
     * Finds all lakes – connected components of '.' that do NOT touch the outer border.
     *
     * @param grid   the mutable grid representation of the map
     * @param n      number of rows
     * @param m      number of columns
     * @return list of {@link Lake} objects
     */
    private static List<Lake> findLakes(char[][] grid, int n, int m) {
        boolean[][] visited = new boolean[n][m];
        List<Lake> lakes = new ArrayList<>();

        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (visited[r][c] || grid[r][c] != '.') continue;

                Lake lake = new Lake();
                Queue<Point> queue = new ArrayDeque<>();
                queue.add(new Point(r, c));
                visited[r][c] = true;

                boolean touchesBorder = false;

                while (!queue.isEmpty()) {
                    Point cur = queue.poll();
                    lake.add(cur);

                    // check if this cell is on the border
                    if (cur.x == 0 || cur.x == n - 1 || cur.y == 0 || cur.y == m - 1) {
                        touchesBorder = true;
                    }

                    for (int d = 0; d < 4; d++) {
                        int nr = cur.x + dr[d];
                        int nc = cur.y + dc[d];
                        if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
                        if (!visited[nr][nc] && grid[nr][nc] == '.') {
                            visited[nr][nc] = true;
                            queue.add(new Point(nr, nc));
                        }
                    }
                }

                // keep only lakes that are completely surrounded by land ('#')
                if (!touchesBorder) {
                    lakes.add(lake);
                }
            }
        }
        return lakes;
    }

    /**
     * Prints the whole grid to the output writer – reproducing the original
     * “debug” printing behavior.
     */
    private static void printGrid(char[][] grid, OutputWriter out) {
        for (char[] row : grid) {
            for (char ch : row) {
                out.print(ch);
            }
            out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class of the solution.
 * <p>
 * The program reads a grid of characters, identifies all connected
 * components that do NOT touch the border (i.e. “sea‑less” components),
 * and removes the smallest ones until at most {@code k} such components
 * remain.  The number of removed cells and the final grid are printed.
 * </p>
 *
 * <p>Refactoring highlights:</p>
 * <ul>
 *   <li>Clear separation of concerns (input, processing, output)</li>
 *   <li>Use of try‑with‑resources and a dedicated {@link FastScanner}</li>
 *   <li>Meaningful naming, immutable fields and final where possible</li>
 *   <li>Extraction of helper methods (DFS, sea detection, etc.)</li>
 *   <li>Removal of unused / confusing state (global {@code tok}, {@code time()} etc.)</li>
 *   <li>Encapsulation of per‑component data in its own class</li>
 *   <li>No raw generics warnings</li>
 * </ul>
 */
public class Solution implements Runnable {

    /** {@link FastScanner} used for reading tokens from {@code stdin} or a file. */
    private FastScanner scanner;

    /** {@link PrintWriter} used for writing to {@code stdout} or a file. */
    private PrintWriter out;

    /** Number of columns in the grid (filled after reading the first line). */
    private int columns;

    /** Number of rows in the grid (filled after reading the first line). */
    private int rows;

    /** The maximal number of sea‑less components that we are allowed to keep. */
    private int maxKeep;

    /** Directions used for 4‑neighbour traversal. */
    private static final int[][] DIRS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    /** Small immutable holder for the coordinates of a grid cell. */
    private static final class Position {
        final int r, c;
        Position(int r, int c) { this.r = r; this.c = c; }
    }

    /** Data structure that represents a connected component of '.' cells. */
    private static final class Component implements Comparable<Component> {
        /** Row indices of the cells belonging to the component. */
        final List<Integer> rows = new ArrayList<>();
        /** Column indices of the cells belonging to the component. */
        final List<Integer> cols = new ArrayList<>();

        /** Adds a cell to the component. */
        void add(int r, int c) {
            rows.add(r);
            cols.add(c);
        }

        /** Number of cells in the component. */
        int size() {
            return rows.size();
        }

        /** Comparison based on component size – used by {@link PriorityQueue}. */
        @Override
        public int compareTo(Component o) {
            return Integer.compare(this.size(), o.size());
        }
    }

    @Override
    public void run() {
        /* --------------------------------------------------------------
         * 1️⃣  Initialise I/O (fast scanner + print writer)
         * -------------------------------------------------------------- */
        long start = System.currentTimeMillis();
        try (var br = new BufferedReader(new InputStreamReader(System.in))) {
            scanner = new FastScanner(br);
            out = new PrintWriter(System.out, true);
        } catch (Exception e) {
            throw new UncheckedIOException(e);
        }

        memoryInfo("Start");

        try {
            solve();
        } finally {
            out.close();
            memoryInfo("End");
            if (!isRunningInOnlineJudge()) {
                System.err.println("Elapsed: " + (System.currentTimeMillis() - start) + " ms");
            }
        }
    }

    /** Executes the core algorithm. */
    private void solve() throws IOException {
        rows = scanner.nextInt();
        columns = scanner.nextInt();
        maxKeep = scanner.nextInt();

        char[][] grid = readGrid(rows);
        boolean[][] visited = new boolean[rows][columns];

        List<Component> seaLessComponents = new ArrayList<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < columns; c++) {
                if (visited[r][c] || grid[r][c] == '*') {
                    continue;
                }
                Component component = exploreComponent(grid, visited, r, c);
                if (!componentTouchesSea(component)) {
                    seaLessComponents.add(component);
                }
            }
        }

        // Keep the largest {@code maxKeep} components, remove the rest.
        Collections.sort(seaLessComponents);
        int removedCells = 0;
        for (int i = 0; i < seaLessComponents.size() - maxKeep; i++) {
            Component toRemove = seaLessComponents.get(i);
            for (int idx = 0; idx < toRemove.size(); idx++) {
                int r = toRemove.rows.get(idx);
                int c = toRemove.cols.get(idx);
                grid[r][c] = '*';
                removedCells++;
            }
        }

        // Output results.
        out.println(removedCells);
        for (char[] row : grid) {
            out.println(row);
        }
    }

    /** Reads the grid from the scanner. */
    private char[][] readGrid(int rows) throws IOException {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next().toString();   // next token is the whole line
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /**
     *Depth‑first (actually iterative) traversal that collects all cells of a
     *connected component consisting of '.' characters.
     */
    private Component exploreComponent(char[][] grid,
                                       boolean[][] visited,
                                       int startR,
                                       int startC) {
        Component comp = new Component();
        Deque<Position> stack = new ArrayDeque<>();
        stack.push(new Position(startR, startC));
        visited[startR][startC] = true;

        boolean touchesSea = false;

        while (!stack.isEmpty()) {
            Position cur = stack.pop();
            comp.add(cur.r, cur.c);
            touchesSea |= isSeaCell(cur.r, cur.c);

            for (int[][] dir : DIRS) {
                int nr = cur.r + dir[0];
                int nc = cur.c + dir[1];
                if (inBounds(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                    visited[nr][nc] = true;
                    stack.push(new Position(nr, nc));
                }
            }
        }

        // Store sea‑touch information for later decision.
        comp.touchesSea = touchesSea;
        return comp;
    }

    /** Checks whether a cell lies on the outer border of the grid. */
    private boolean isSeaCell(int r, int c) {
        return r == 0 || c == 0 || r == rows - 1 || c == columns - 1;
    }

    /** Returns {@code true} if the component contains at least one sea cell. */
    private boolean componentTouchesSea(Component comp) {
        return comp.touchesSea;
    }

    /** Helper to verify that coordinates are inside the grid. */
    private boolean inBounds(int r, int c) {
        return r >= 0 && c >= 0 && r < rows && c < columns;
    }

    /** Small utility to print memory usage information for debugging. */
    private static void memoryInfo(String prefix) {
        Runtime rt = Runtime.getRuntime();
        long used = (rt.totalMemory() - rt.freeMemory()) >> 10; // KB
        System.err.println(prefix + " – Used memory: " + used + " KB");
    }

    /** Determines whether the program is executed under the typical
     *  online‑judge environment variable {@code ONLINE_JUDGE}. */
    private static boolean isRunningInOnlineJudge() {
        return System.getProperty("ONLINE_JUDGE") != null;
    }

    /**
     * Very small wrapper around {@link BufferedReader} that returns the next
     * whitespace‑separated token, mimicking the behaviour of the original
     * {@code StringTokenizer} but without its quirks.
     */
    private static final class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        /** Returns the next token, or {@code null} if the stream is exhausted. */
        String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line, " \t\n\r");
            }
            return tokenizer.nextToken();
        }

        /** Convenience methods used by the original code. */
        int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
        long nextLong() throws IOException { return Long.parseLong(nextToken()); }
        double nextDouble() throws IOException { return Double.parseDouble(nextToken()); }
        String next() throws IOException { return nextToken(); }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }

    /* --------------------------------------------------------------
     *  Entry point – launches the solution on a dedicated thread
     *  with a generous stack size (compatible with the original code).
