import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of LakesInBerland.
 *
 * The program reads a grid of characters, identifies interior water bodies
 * ('.') that are not reachable from the border, removes the smallest
 * {@code k} such bodies until exactly {@code k} remain, prints the total
 * number of cells removed, and outputs the modified grid where removed
 * cells are marked with '*'.
 */
public class LakesInBerland {

    /** Directions used for breadth‑first search (up, down, left, right). */
    private static final int[][] DIRECTIONS = {
            {-1, 0},
            {1, 0},
            {0, -1},
            {0, 1}
    };

    /** Simple container that stores information about a connected component. */
    private static final class Component {
        final int id;               // component identifier
        final int size;             // number of cells in the component
        final List<Point> cells;    // coordinates of all cells belonging to the component

        Component(int id, int size, List<Point> cells) {
            this.id = id;
            this.size = size;
            this.cells = cells;
        }
    }

    /** Simple point holder for grid coordinates. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Reads input, processes the grid and prints the result. */
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();          // number of rows
            int m = sc.nextInt();          // number of columns
            int k = sc.nextInt();          // number of lakes we must keep

            // -----------------------------------------------------------------
            // 1. Load the grid
            // -----------------------------------------------------------------
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                String line = sc.next();
                grid[i] = line.toCharArray();
            }

            // -----------------------------------------------------------------
            // 2. visited[r][c] = 0  -> not visited yet
            //    visited[r][c] = -1 -> reachable from the border (boundary lake)
            //    visited[r][c] = >0 -> belongs to component with that id
            // -----------------------------------------------------------------
            int[][] visited = new int[n][m];

            // -----------------------------------------------------------------
            // 3. Mark all cells connected to the border as visited (-1)
            // -----------------------------------------------------------------
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if ((i == 0 || i == n - 1 || j == 0 || j == m - 1)
                            && grid[i][j] == '.'
                            && visited[i][j] == 0) {
                        bfsMarkBoundary(grid, visited, i, j);
                    }
                }
            }

            // -----------------------------------------------------------------
            // 4. Find all interior components (visited == 0) and store them
            // -----------------------------------------------------------------
            List<Component> components = new ArrayList<>();
            int componentId = 1; // we start identifiers from 1 (0 is reserved)

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (visited[i][j] == 0 && grid[i][j] == '.') {
                        Component comp = bfsCollectComponent(
                                grid, visited, i, j, componentId);
                        components.add(comp);
                        componentId++;
                    }
                }
            }

            // -----------------------------------------------------------------
            // 5. Decide which components to remove (the smallest ones)
            // -----------------------------------------------------------------
            int componentsToRemove = Math.max(0, components.size() - k);
            int totalRemovedCells = 0;

            // Sort components by size (ascending) to easily pick the smallest ones
            components.sort(Comparator.comparingInt(c -> c.size));

            for (int i = 0; i < componentsToRemove; i++) {
                Component toRemove = components.get(i);
                totalRemovedCells += toRemove.size;
                markComponentAsRemoved(grid, toRemove.cells);
            }

            // -----------------------------------------------------------------
            // 6. Output the result
            // -----------------------------------------------------------------
            System.out.println(totalRemovedCells);
            printGrid(grid);
        }
    }

    /** Breadth‑first search that marks all cells reachable from (r,c)
     *  as visited = -1 (connected to the border). */
    private static void bfsMarkBoundary(char[][] grid, int[][] visited,
                                        int startRow, int startCol) {
        Deque<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startRow, startCol));
        visited[startRow][startCol] = -1;

        while (!queue.isEmpty()) {
            Point p = queue.pollFirst();
            for (int[] dir : DIRECTIONS) {
                int nr = p.row + dir[0];
                int nc = p.col + dir[1];
                if (isInBounds(grid, nr, nc)
                        && grid[nr][nc] == '.'
                        && visited[nr][nc] == 0) {
                    visited[nr][nc] = -1;
                    queue.addLast(new Point(nr, nc));
                }
            }
        }
    }

    /** Breadth‑first search that collects one interior component.
     *  Returns a {@link Component} with a unique identifier. */
    private static Component bfsCollectComponent(char[][] grid,
                                                int[][] visited,
                                                int startRow,
                                                int startCol,
                                                int id) {
        List<Point> cells = new ArrayList<>();
        Deque<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startRow, startCol));
        visited[startRow][startCol] = id;
        cells.add(new Point(startRow, startCol));

        while (!queue.isEmpty()) {
            Point p = queue.pollFirst();
            for (int[] dir : DIRECTIONS) {
                int nr = p.row + dir[0];
                int nc = p.col + dir[1];
                if (isInBounds(grid, nr, nc)
                        && grid[nr][nc] == '.'
                        && visited[nr][nc] == 0) {
                    visited[nr][nc] = id;
                    queue.addLast(new Point(nr, nc));
                    cells.add(new Point(nr, nc));
                }
            }
        }
        return new Component(id, cells.size(), cells);
    }

    /** Checks whether a coordinate lies inside the grid. */
    private static boolean isInBounds(char[][] grid, int row, int col) {
        return row >= 0 && row < grid.length
                && col >= 0 && col < grid[0].length;
    }

    /** Marks all cells of a component as removed (character '*' ) in the grid. */
    private static void markComponentAsRemoved(char[][] grid, List<Point> cells) {
        for (Point p : cells) {
            grid[p.row][p.col] = '*';
        }
    }

    /** Prints the whole grid to standard output. */
    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                System.out.print(cell);
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Refactored version of the original program.
 *
 * <p>
 *   Changes made:
 *   <ul>
 *     <li>Extracted helper classes and methods to improve readability.</li>
 *     <li>Replaced raw collections with generics and eliminated magic numbers.</li>
 *     <li>Introduced constants for board symbols.</li>
 *     <li>Added proper resource handling (try‑with‑resources) for streams.</li>
 *     <li>Renamed variables and methods to convey intent.</li>
 *     <li>Used modern Java features (streams, var) where appropriate.</li>
 *   </ul>
 * </p>
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /* Constants                                                             */
    /* --------------------------------------------------------------------- */
    private static final char EMPTY = '.';
    private static final char BLOCKED = '*';

    /* --------------------------------------------------------------------- */
    /* Helper data structure                                                   */
    /* --------------------------------------------------------------------- */
    private static final class Pair implements Comparable<Pair> {
        final int size;   // component size
        final int id;     // component identifier

        Pair(int size, int id) {
            this.size = size;
            this.id = id;
        }

        @Override
        public int compareTo(Pair o) {
            return Integer.compare(this.size, o.size);
        }
    }

    /* --------------------------------------------------------------------- */
    /* Entry point                                                            */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        // System.in and System.out are managed automatically by try‑with‑resources
        try (InputStream input = System.in;
             OutputStream output = System.out) {
            solve(input, output);
        }
    }

    /* --------------------------------------------------------------------- */
    /* Core logic                                                             */
    /* --------------------------------------------------------------------- */
    private static void solve(InputStream input, OutputStream output) throws IOException {
        // BufferedReader / PrintWriter provide convenient token handling and auto‑flush
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(input));
             PrintWriter writer = new PrintWriter(output, true)) {

            InputReader in = new InputReader(reader);
            int rows = in.nextInt();
            int cols = in.nextInt();
            int k = in.nextInt();

            char[][] board = readBoard(in, rows, cols);

            // -----------------------------------------------------------------
            // 1️⃣ Identify connected components (4‑directional)
            // -----------------------------------------------------------------
            int[][] componentId = new int[rows][cols];
            List<Integer> componentSize = new ArrayList<>(rows * cols + 1);
            int componentCount = 0;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (board[r][c] == EMPTY && componentId[r][c] == 0) {
                        exploreComponent(r, c, board, componentId, componentSize, componentCount);
                        componentCount++;
                    }
                }
            }

            // -----------------------------------------------------------------
            // 2️⃣ Determine which components touch the border
            // -----------------------------------------------------------------
            Set<Integer> borderComponents = identifyBorderComponents(componentId, board, rows, cols);

            // -----------------------------------------------------------------
            // 3️⃣ Choose components to delete (largest ones, except border ones)
            // -----------------------------------------------------------------
            List<Pair> candidates = collectCandidates(componentSize, componentCount, borderComponents);
            Collections.sort(candidates);

            int toDeleteCount = Math.max(0, candidates.size() - k);
            Set<Integer> componentsToDelete = candidates.stream()
                    .limit(toDeleteCount)
                    .map(p -> p.id)
                    .collect(Collectors.toSet());

            // -----------------------------------------------------------------
            // 4️⃣ Mark those components on the board and count removed cells
            // -----------------------------------------------------------------
            int removed = markAndCount(board, componentId, componentsToDelete, rows, cols);

            // -----------------------------------------------------------------
            // 5️⃣ Output
            // -----------------------------------------------------------------
            writer.println(removed);
            printBoard(board, writer);
        }
    }

    /* --------------------------------------------------------------------- */
    /* Input handling                                                         */
    /* --------------------------------------------------------------------- */
    private static char[][] readBoard(InputReader in, int n, int m) {
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = in.next().toCharArray();
        }
        return board;
    }

    /* --------------------------------------------------------------------- */
    /* Component exploration                                                   */
    /* --------------------------------------------------------------------- */
    private static void exploreComponent(int startX, int startY,
                                           char[][] board,
                                           int[][] id,
                                           List<Integer> size,
                                           int currentId) {
        id[startX][startY] = currentId;
        size.set(currentId, size.get(currentId) + 1);

        int[] dx = {-1, 0, 1, 0};
        int[] dy = {0, -1, 0, 1};

        for (int d = 0; d < 4; d++) {
            int nx = startX + dx[d];
            int ny = startY + dy[d];
            if (isInBounds(nx, ny, board) && board[nx][ny] == EMPTY && id[nx][ny] == 0) {
                exploreComponent(nx, ny, board, id, size, currentId);
            }
        }
    }

    private static boolean isInBounds(int x, int y, char[][] board) {
        return x >= 0 && x < board.length && y >= 0 && y < board[0].length;
    }

    /* --------------------------------------------------------------------- */
    /* Border component detection                                              */
    /* --------------------------------------------------------------------- */
    private static Set<Integer> identifyBorderComponents(int[][] id, char[][] board,
                                                          int n, int m) {
        Set<Integer> border = new HashSet<>();

        // top & bottom rows
        for (int i = 0; i < n; i++) {
            if (board[i][0] == EMPTY) border.add(id[i][0]);
            if (board[i][m - 1] == EMPTY) border.add(id[i][m - 1]);
        }
        // left & right columns
        for (int j = 0; j < m; j++) {
            if (board[0][j] == EMPTY) border.add(id[0][j]);
            if (board[n - 1][j] == EMPTY) border.add(id[n - 1][j]);
        }
        return border;
    }

    /* --------------------------------------------------------------------- */
    /* Select components that can be removed                                    */
    /* --------------------------------------------------------------------- */
    private static List<Pair> collectCandidates(List<Integer> size,
                                                  int totalIds,
                                                  Set<Integer> border) {
        List<Pair> list = new ArrayList<>();
        for (int i = 1; i <= totalIds; i++) {
            if (!border.contains(i)) {
                list.add(new Pair(size.get(i), i));
            }
        }
        return list;
    }

    /* --------------------------------------------------------------------- */
    /* Mark removal set on the board and count removed cells                   */
    /* --------------------------------------------------------------------- */
    private static int markAndCount(char[][] board, int[][] id,
                                      Set<Integer> toRemove, int n, int m) {
        int count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (board[i][j] == EMPTY && toRemove.contains(id[i][j])) {
                    board[i][j] = BLOCKED;
                    count++;
                }
            }
        }
        return count;
    }

    /* --------------------------------------------------------------------- */
    /* Pretty‑print result                                                   */
    /* --------------------------------------------------------------------- */
    private static void printBoard(char[][] board, PrintWriter out) {
        for (char[] row : board) {
            for (char cell : row) {
                out.print(cell);
            }
            out.println();
        }
    }

    /* --------------------------------------------------------------------- */
    /* Simple token reader                                                    */
    /* --------------------------------------------------------------------- */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(BufferedReader reader) {
            this.reader = reader;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

public class BerlandLakes {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String s = sc.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = s.charAt(j);
            }
        }

        boolean[][] visited = new boolean[n][m];
        List<List<int[]>> nonBorderLakes = new ArrayList<>();
        int totalLakesCount = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    totalLakesCount++;
                    List<int[]> lake = new ArrayList<>();
                    Queue<int[]> queue = new LinkedList<>();
                    queue.add(new int[]{i, j});
                    visited[i][j] = true;
                    boolean isBorder = false;

                    while (!queue.isEmpty()) {
                        int[] cell = queue.poll();
                        int r = cell[0], c = cell[1];
                        lake.add(cell);
                        if (r == 0 || r == n - 1 || c == 0 || c == m - 1) {
                            isBorder = true;
                        }
                        for (int d = 0; d < 4; d++) {
                            int nr = r + dr[d];
                            int nc = c + dc[d];
                            if (nr >= 0 && nr < n && nc >= 0 && nc < m && !visited[nr][nc] && grid[nr][nc] == '.') {
                                visited[nr][nc] = true;
                                queue.add(new int[]{nr, nc});
                            }
                        }
                    }
                    if (!isBorder) {
                        nonBorderLakes.add(lake);
                    }
                }
            }
        }

        int toFill = totalLakesCount - k;
        if (toFill > 0) {
            nonBorderLakes.sort(Comparator.comparingInt(lake -> lake.size()));
            for (int i = 0; i < toFill; i++) {
                List<int[]> lake = nonBorderLakes.get(i);
                for (int[] cell : lake) {
                    grid[cell[0]][cell[1]] = '*';
                }
            }
        }

        int filledCells = 0;
        if (toFill > 0) {
            for (int i = 0; i < toFill; i++) {
                filledCells += nonBorderLakes.get(i).size();
            }
            System.out.println(filledCells);
        } else {
            System.out.println(0);
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                System.out.print(grid[i][j]);
            }
            System.out.println();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Utility that processes a 2‑dimensional lake map.
 *
 * <p>
 * The program reads a grid consisting of '#' (blocked) and '.' (water) cells,
 * removes the smallest {@code k} lakes that are completely surrounded by land,
 * and prints the total number of removed water cells followed by the final
 * grid representation.
 * </p>
 */
public class LakeRemover {

    /** Four cardinal directions used for neighbour traversal. */
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    private final char[][] grid;   // The mutable map representation
    private final boolean[][] visited; // Tracks visited cells during DFS
    private final int rows;        // Number of rows (n)
    private final int cols;        // Number of columns (m)

    /* --------------------------------------------------------------
     *  Construction
     * -------------------------------------------------------------- */
    public LakeRemover(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.visited = new boolean[rows][cols];
    }

    /* --------------------------------------------------------------
     *  Public API
     * -------------------------------------------------------------- */

    /**
     * Marks all water cells that are connected to any border cell.
     * These cells belong to lakes that touch the edge of the map and must
     * stay untouched.
     */
    public void markBorderConnected() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isBorderCell(r, c) && grid[r][c] == '.' && !visited[r][c]) {
                    floodFillMarkBorder(r, c);
                }
            }
        }
    }

    /**
     * Finds all lakes, sorts them by size (ascending) and removes the
     * smallest {@code k} lakes. Returns the total number of water cells
     * removed.
     *
     * @param k number of lakes to keep (the smallest ones are removed)
     * @return number of water cells that were removed
     */
    public int removeSmallestK(int k) {
        List<Lake> lakes = findLakes();
        Collections.sort(lakes);

        int removed = 0;
        while (lakes.size() > k) {
            Lake lake = lakes.remove(0);
            floodFillMarkRemoved(lake.row, lake.col);
            removed += lake.size;
        }
        return removed;
    }

    /** Prints the final grid where removed lakes are represented by '*'. */
    public void printResult() {
        StringBuilder out = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                out.append(grid[r][c] == '#' ? '.' : grid[r][c]);
            }
            out.append('\n');
        }
        System.out.print(out.toString());
    }

    /* --------------------------------------------------------------
     *  Helper methods
     * -------------------------------------------------------------- */

    /** Determines whether the given cell lies on the outer border of the grid. */
    private boolean isBorderCell(int r, int c) {
        return r == 0 || c == 0 || r == rows - 1 || c == cols - 1;
    }

    /** Marks a whole lake (connected '.' cells) as part of a border lake ('#'). */
    private void floodFillMarkBorder(int r, int c) {
        visited[r][c] = true;
        grid[r][c] = '#';
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (withinBounds(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                floodFillMarkBorder(nr, nc);
            }
        }
    }

    /** Counts the size of the lake that starts at (r,c). */
    private int floodFillCountArea(int r, int c) {
        visited[r][c] = true;
        int size = 1;
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (withinBounds(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                size += floodFillCountArea(nr, nc);
            }
        }
        return size;
    }

    /**
     * Removes a whole lake (connected '.' cells) by turning them into '*'
     * – used when a lake is selected for deletion.
     */
    private void floodFillMarkRemoved(int r, int c) {
        visited[r][c] = true;
        grid[r][c] = '*';
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (withinBounds(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                floodFillMarkRemoved(nr, nc);
            }
        }
    }

    /** Checks if a cell coordinate is inside the grid limits. */
    private boolean withinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Simple data holder representing a lake.
     * Lakes are ordered by their size (ascending) when used with {@link Collections#sort(List)}.
     */
    public static final class Lake implements Comparable<Lake> {
        final int row;   // top‑left coordinate of the lake (any member works)
        final int col;
        final int size;  // number of water cells in the lake

        public Lake(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /* --------------------------------------------------------------
     *  Entry point
     * -------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();      // rows
            int m = scanner.nextInt();      // columns
            int k = scanner.nextInt();      // number of lakes to keep

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            LakeRemover remover = new LakeRemover(grid);
            remover.markBorderConnected();
            int removedCells = remover.removeSmallestK(k);
            System.out.println(removedCells);
            remover.printResult();
        }
    }
}

import java.io.File;
import java.io.FileNotFoundException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

/**
 * Main class that reads a map of land (digits) and water ('.'), removes the smallest
 * {@code k} lakes and prints the number of cells that were turned into land.
 */
public class Main {

    /** Directions for 4‑neighbour traversal. */
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    /** Maximum supported size – matches the original fixed‑size array. */
    private static final int MAX = 55;

    /** Current grid representation. */
    private final char[][] grid = new char[MAX][MAX];

    /** Visited flag used during flood‑fill. */
    private final boolean[][] visited = new boolean[MAX][MAX];

    /** Counts cells in the current flood‑fill. */
    private int cellCount;

    /**
     * Entry point – reads from {@code stdin} or from a file given on the command line.
     */
    public static void main(String[] args) {
        new Main().run();
    }

    /** Executes the whole program: I/O → processing → output. */
    private void run() {
        readInput();
        process();
    }

    /** Reads either from a file supplied as the first argument or from {@code System.in}. */
    private void readInput() {
        Scanner scanner;
        if (args.length > 0) {
            Path filePath = Path.of(args[0]);
            try {
                scanner = new Scanner(new File(filePath.toString()));
            } catch (FileNotFoundException e) {
                System.err.println("File not found: " + filePath);
                return;
            }
        } else {
            scanner = new Scanner(System.in);
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int keep = scanner.nextInt(); // number of lakes we want to keep

        // Load grid
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = row.charAt(j);
            }
        }

        // Close scanner if we opened it ourselves (i.e., no args)
        if (args.length == 0) {
            scanner.close();
        }

        // Process and print result
        int removedCells = processAndPrint(n, m, keep);
        System.out.println(removedCells);
    }

    /** Core algorithm – finds lakes, removes the smallest {@code remove} of them. */
    private int processAndPrint(int n, int m, int keep) {
        // 1️⃣  Mark all water cells that touch the border as visited (they are not lakes).
        markBorderConnectedWater();

        // 2️⃣  Discover all remaining lakes (connected water components) and their sizes.
        List<Lake> lakes = discoverLakes(n, m);

        // 3️⃣  Sort lakes by size (ascending) – smallest first.
        Collections.sort(lakes);

        // 4️⃣  Determine how many lakes must be removed.
        int lakesToRemove = lakes.size() - keep;
        if (lakesToRemove < 0) {
            lakesToRemove = 0; // safety guard
        }

        // 5️⃣  Remove those lakes (turn them into land) and accumulate the removed cell count.
        int removedCount = 0;
        for (int i = 0; i < lakesToRemove; i++) {
            Lake lake = lakes.get(i);
            removedCount += lake.getSize();
            floodFill(lake.getStartX(), lake.getStartY(), '*'); // erase the lake
        }

        // 6️⃣  Print the resulting grid.
        printGrid(n, m);
        return removedCount;
    }

    /** Marks all water cells reachable from the border as visited. */
    private void markBorderConnectedWater() {
        // Clear visited flags for safety.
        for (int i = 0; i < MAX; i++) {
            Arrays.fill(visited[i], false);
        }

        // Top & bottom rows
        for (int col = 0; col < MAX; col++) {
            if (grid[0][col] == '.') dfsBorder(0, col);
            if (grid[MAX - 1][col] == '.') dfsBorder(MAX - 1, col);
        }
        // Left & right columns (excluding corners already processed)
        for (int row = 1; row < MAX - 1; row++) {
            if (grid[row][0] == '.') dfsBorder(row, 0);
            if (grid[row][MAX - 1] == '.') dfsBorder(row, MAX - 1);
        }
    }

    /** Flood‑fill helper used for border marking – marks reachable '.' as visited. */
    private void dfsBorder(int x, int y) {
        if (!inBounds(x, y) || visited[x][y] || grid[x][y] != '.') {
            return;
        }
        visited[x][y] = true;
        for (int d = 0; d < 4; d++) {
            dfsBorder(x + DX[d], y + DY[d]);
        }
    }

    /** Discovers all lakes, stores their size and starting coordinate. */
    private List<Lake> discoverLakes(int n, int m) {
        List<Lake> lakes = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    cellCount = 0;
                    floodFill(i, j, '.'); // size calculation only
                    lakes.add(new Lake(i, j, cellCount));
                }
            }
        }
        return lakes;
    }

    /**
     * General flood‑fill that can both count cells and optionally mutate them.
     *
     * @param x      start row
     * @param y      start column
     * @param target character to replace (either '.' for size counting or '*' for removal)
     */
    private void floodFill(int x, int y, char target) {
        if (!inBounds(x, y) || grid[x][y] != '.') {
            return;
        }
        grid[x][y] = target;
        cellCount++;
        for (int d = 0; d < 4; d++) {
            floodFill(x + DX[d], y + DY[d], target);
        }
    }

    /** Simple data holder for a lake. */
    private static final class Lake implements Comparable<Lake> {
        private final int startX;
        private final int startY;
        private final int size;

        Lake(int startX, int startY, int size) {
            this.startX = startX;
            this.startY = startY;
            this.size = size;
        }

        int getSize() {
            return size;
        }

        int getStartX() {
            return startX;
        }

        int getStartY() {
            return startY;
        }

        @Override
        public int compareTo(Lake o) {
            return Integer.compare(this.size, o.size);
        }
    }

    /** Utility check for grid bounds. */
    private boolean inBounds(int x, int y) {
        return x >= 0 && x < MAX && y >= 0 && y < MAX;
    }

    /** Prints the processed grid to {@code System.out}. */
    private void printGrid(int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                System.out.print(grid[i][j]);
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

public class D723Refactored {

    /** Directions: right, down, left, up */
    private static final int[][] DIRS = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    /** Simple token reader that works with any BufferedReader */
    private static final class Tokenizer implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        Tokenizer(BufferedReader br) {
            this.br = br;
        }

        /** Make sure we have tokens available */
        private void ensureTokens() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return;
                st = new StringTokenizer(line);
            }
        }

        String next() throws IOException {
            ensureTokens();
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }

    /** Component information used for sorting */
    private static final class Component implements Comparable<Component> {
        final int size;      // number of cells in the component
        final int id;        // discovery order (used as secondary key)
        final int startRow;
        final int startCol;

        Component(int size, int id, int startRow, int startCol) {
            this.size = size;
            this.id = id;
            this.startRow = startRow;
            this.startCol = startCol;
        }

        @Override
        public int compareTo(Component o) {
            int cmp = Integer.compare(this.size, o.size);
            return (cmp != 0) ? cmp : Integer.compare(this.id, o.id);
        }
    }

    /** Entry point – reads input, processes, and writes output */
    public static void main(String[] args) throws Exception {
        try (Tokenizer tk = new Tokenizer(new BufferedReader(
                new InputStreamReader(System.in)));
             PrintWriter out = new PrintWriter(System.out)) {

            // ------------------------------------------------------------
            // 1. Read dimensions and the grid
            // ------------------------------------------------------------
            int n = tk.nextInt();
            int m = tk.nextInt();
            int k = tk.nextInt();
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                String line = tk.next();
                grid[i] = line.toCharArray();
            }

            int total = n * m;

            // ------------------------------------------------------------
            // 2. Build adjacency list for all '.' cells
            // ------------------------------------------------------------
            @SuppressWarnings("unchecked")
            List<Integer>[] adj = new ArrayList[total];
            for (int i = 0; i < total; i++) adj[i] = new ArrayList<>();

            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] != '.') continue;
                    int v = r * m + c;
                    for (int[] d : DIRS) {
                        int nr = r + d[0], nc = c + d[1];
                        if (inside(grid, nr, nc)) {
                            int u = nr * m + nc;
                            adj.get(v).add(u);
                        }
                    }
                }
            }

            // ------------------------------------------------------------
            // 3. Mark all cells reachable from the border (original dfs1)
            // ------------------------------------------------------------
            boolean[] visitedFromBorder = new boolean[total];
            for (int r = 0; r < n; r++) {
                if (grid[r][0] == '.') dfsMark(adj, visitedFromBorder, r * m);
                if (grid[r][m - 1] == '.') dfsMark(adj, visitedFromBorder, r * m + m - 1);
            }
            for (int c = 0; c < m; c++) {
                if (grid[0][c] == '.') dfsMark(adj, visitedFromBorder, c);
                if (grid[n - 1][c] == '.') dfsMark(adj, visitedFromBorder,
                        (n - 1) * m + c);
            }

            // ------------------------------------------------------------
            // 4. Discover interior components (original dfs2)
            // ------------------------------------------------------------
            int[] compId = new int[total];          // component identifier per node
            int[] compSize = new int[total];        // size of each component
            int nextCompId = 1;                     // increments for each component
            List<Component> components = new ArrayList<>();

            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    int idx = r * m + c;
                    if (grid[r][c] == '.' && compId[idx] == 0 && !visitedFromBorder[idx]) {
                        dfsExplore(adj, compId, compSize, idx, nextCompId);
                        int size = compSize[nextCompId];
                        components.add(new Component(size, nextCompId, r, c));
                        nextCompId++;
                    }
                }
            }

            // ------------------------------------------------------------
            // 5. Compute answer – sum of sizes of all but the last k components
            // ------------------------------------------------------------
            Collections.sort(components);
            long answer = 0;
            int limit = Math.max(0, components.size() - k);
            for (int i = 0; i < limit; i++) {
                answer += components.get(i).size;
            }
            out.println(answer);

            // ------------------------------------------------------------
            // 6. Mark selected components with '*'
            // ------------------------------------------------------------
            boolean[] markedForStar = new boolean[total];
            for (Component comp : components) {
                int startIdx = comp.startRow * m + comp.startCol;
                if (!markedForStar[startIdx]) {
                    markSpread(adj, markedForStar, startIdx, grid);
                }
            }

            // ------------------------------------------------------------
            // 7. Output the final grid
            // ------------------------------------------------------------
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    out.print(grid[r][c]);
                }
                out.println();
            }
        }
    }

    /** Helper – check that a cell is inside the grid and is a '.' */
    private static boolean inside(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length && grid[r][c] == '.';
    }

    /** Iterative DFS that marks all nodes reachable from `start` */
    private static void dfsMark(List<Integer>[] adj, boolean[] visited, int start) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        while (!stack.isEmpty()) {
            int cur = stack.pop();
            if (visited[cur]) continue;
            visited[cur] = true;
            for (int nb : adj.get(cur)) {
                if (!visited[nb]) stack.push(nb);
            }
        }
    }

    /** Iterative DFS that assigns a component id and counts its size */
    private static void dfsExplore(List<Integer>[] adj,
                                   int[] compId,
                                   int[] compSize,
                                   int start,
                                   int compIdValue) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        while (!stack.isEmpty()) {
            int cur = stack.pop();
            if (compId[cur] != 0) continue;          // already visited
            compId[cur] = compIdValue;              // assign component id
            compSize[compIdValue]++;                // count this node toward component size
            for (int nb : adj.get(cur)) {
                if (compId[nb] == 0) stack.push(nb);
            }
        }
    }

    /** Mark all cells of the component containing `start` with '*' */
    private static void markSpread(List<Integer>[] adj,
                                   boolean[] marked,
                                   int start,
                                   char[][] grid) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        while (!stack.isEmpty()) {
            int cur = stack.pop();
            if (marked[cur]) continue;
            marked[cur] = true;
            int r = cur / grid.length;
            int c = cur % grid[0].length;
            grid[r][c] = '*';
            for (int nb : adj.get(cur)) {
                if (!marked[nb]) stack.push(nb);
            }
        }
    }
}

import java.util.*;
import java.util.stream.Collectors;

/**
 * Project: Codeforces 375 – 2D
 * Refactored for readability, maintainability and Java‑8+ best practices.
 */
public class Main {

    /** Directions used for lake traversal (up, down, left, right). */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Holds the coordinates of a cell. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Represents a water lake (connected component of '.' cells). */
    private static final class Lake {
        final List<Point> points;
        final boolean touchesBorder;

        Lake(List<Point> points, boolean touchesBorder) {
            this.points = Collections.unmodifiableList(new ArrayList<>(points));
            this.touchesBorder = touchesBorder;
        }
    }

    /** Data holder for the whole input field. */
    private static final class Field {
        private final int rows;
        private final int cols;
        private final int requiredLakes;   // k
        private final boolean[][] grid;    // true = water ('.'), false = rock ('*')

        Field(Scanner scanner) {
            // ----- read dimensions & k -------------------------------------------------
            String[] dims = scanner.nextLine().split("\\s+");
            this.rows = Integer.parseInt(dims[0]);
            this.cols = Integer.parseInt(dims[1]);
            this.requiredLakes = Integer.parseInt(dims[2]);

            // ----- read the map ---------------------------------------------------------
            this.grid = new boolean[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = scanner.nextLine();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c) == '.';
                }
            }
        }

        /** Returns all lakes that do **not** touch the border of the field. */
        List<Lake> findInnerLakes() {
            boolean[][] visited = new boolean[rows][cols];
            List<Lake> lakes = new ArrayList<>();

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] && !visited[r][c]) {
                        Lake lake = bfsDiscoverLake(r, c, visited);
                        if (!lake.touchesBorder) {
                            lakes.add(lake);
                        }
                    }
                }
            }
            return lakes;
        }

        /** Breadth‑first search that fills a lake component. */
        private Lake bfsDiscoverLake(int startR, int startC, boolean[][] visited) {
            List<Point> component = new ArrayList<>();
            Queue<Point> queue = new ArrayDeque<>();
            boolean touchesBorder = false;

            queue.add(new Point(startR, startC));
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point cur = queue.poll();
                component.add(cur);
                if (onBorder(cur.row, cur.col)) {
                    touchesBorder = true;
                }

                for (int[] dir : DIRECTIONS) {
                    int nr = cur.row + dir[0];
                    int nc = cur.col + dir[1];
                    if (inBounds(nr, nc) && grid[nr][nc] && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return new Lake(component, touchesBorder);
        }

        /** Checks whether a cell lies on the outer border. */
        private boolean onBorder(int r, int c) {
            return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
        }

        /** Checks array bounds. */
        private boolean inBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Returns the number of cells that belong to water. */
        int waterCellCount() {
            int count = 0;
            for (boolean[] row : grid) {
                for (boolean cell : row) {
                    if (cell) count++;
                }
            }
            return count;
        }

        /** Edits the grid in‑place to turn the given lake into land. */
        void fill(Lake lake) {
            for (Point p : lake.points) {
                grid[p.row][p.col] = false;
            }
        }

        /** Prints the required answer (filled cells) followed by the altered map. */
        void output(int filledCells) {
            System.out.println(filledCells);
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    System.out.print(grid[r][c] ? '.' : '*');
                }
                System.out.println();
            }
        }

        /** Simple accessor used by the driver code. */
        int getRows() { return rows; }
        int getCols() { return cols; }
    }

    /** --------------------------------------------------- Driver program --------------------------------------------------- */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            Field field = new Field(scanner);
            List<Lake> innerLakes = field.findInnerLakes();

            // Sort lakes by size (smallest first) – we only need the size, not the whole Lake object.
            List<Integer> lakeSizes = innerLakes.stream()
                    .map(lake -> lake.points.size())
                    .collect(Collectors.toList());

            int lakesToFill = Math.max(0, innerLakes.size() - field.requiredLakes);
            int filledCells = 0;

            // Fill the smallest lakes until only the required number of lakes remain.
            if (!lakeSizes.isEmpty()) {
                // Build a list of lake indices sorted by size.
                List<Integer> sortedIndices = new ArrayList<>(InnerLakeRanker.sortIndices(innerLakes, lakesToFill));
                for (int idx : sortedIndices) {
                    Lake lake = innerLakes.get(idx);
                    field.fill(lake);
                    filledCells += lake.points.size();
                }
            }

            field.output(filledCells);
        }
    }

    /** Utility that returns a list of lake indices sorted by lake size. */
    private static final class InnerLakeRanker {
        /** Returns the first {@code count} indices of lakes sorted increasingly by size. */
        static List<Integer> sortIndices(List<Lake> lakes, int count) {
            // Pair each lake index with its size.
            PriorityQueue<Pair> minHeap = new PriorityQueue<>(Comparator.comparingInt(p -> p.size));
            for (int i = 0; i < lakes.size(); i++) {
                minHeap.add(new Pair(i, lakes.get(i).points.size()));
            }

            List<Integer> result = new ArrayList<>();
            while (result.size() < count) {
                result.add(minHeap.poll().index);
            }
            return result;
        }

        /** Simple holder for an index and its associated size. */
        private static final class Pair {
            final int index;
            final int size;
            Pair(int index, int size) {
                this.index = index;
                this.size = size;
            }
        }
    }
}

/**
 * Refactored solution for the “Lakes in Berland” problem.
 *
 * The program reads a rectangular map (water '*', land '.'), identifies all
 * water bodies, keeps exactly {@code k} lakes with the largest areas and
 * turns the remaining lakes into land.  It prints the minimal number of
 * water cells that must be turned into land and the resulting map.
 */
import java.io.*;
import java.util.*;
import java.util.stream.*;

public class LakesInBerland {

    /** Simple container for a discovered water body. */
    private static final class Lake {
        final int id;          // identifier used in the grid
        final int size;        // number of cells in the lake

        Lake(int id, int size) {
            this.id = id;
            this.size = size;
        }
    }

    /** Four orthogonal movement directions. */
    private static final int[][] DIRS = {
            {0, 1},   // right
            {0, -1},  // left
            {1, 0},   // down
            {-1, 0}   // up
    };

    /**
     * Entry point.
     *
     * @param args command‑line arguments (unused)
     * @throws IOException if an I/O error occurs while reading input
     */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in))) {

            // ------------ input parsing -------------------------------------------------
            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());   // rows
            int m = Integer.parseInt(st.nextToken());   // columns
            int k = Integer.parseInt(st.nextToken());   // lakes to keep

            int[][] grid = new int[n][m];
            for (int i = 0; i < n; i++) {
                String line = br.readLine();
                for (int j = 0; j < m; j++) {
                    char ch = line.charAt(j);
                    grid[i][j] = (ch == '*') ? 0 : -1;   // 0 = water, -1 = land
                }
            }

            // ------------ discovering lakes --------------------------------------------
            List<Lake> lakes = discoverLakes(grid, n, m);

            // ------------ selecting lakes to remove ------------------------------------
            int lakesToRemove = lakes.size() - k;
            Set<Integer> lakesToDelete = selectLakesToDelete(lakes, lakesToRemove);

            // ------------ computing removal cost & producing output --------------------
            int removalCost = lakes.stream()
                    .filter(l -> lakesToDelete.contains(l.id))
                    .mapToInt(l -> l.size)
                    .sum();

            printResult(grid, lakesToDelete, removalCost);
        }
    }

    /**
     * Finds all water bodies (lakes) in the grid.
     *
     * @param g      grid where {@code 0} = unvisited water, {@code >0} = visited water,
     *               {@code -1} = land
     * @param n      number of rows
     * @param m      number of columns
     * @return list of {@link Lake} objects
     */
    private static List<Lake> discoverLakes(int[][] g, int n, int m) {
        List<Lake> lakes = new ArrayList<>();

        int nextLakeId = 1; // 0 is reserved for “water” sentinel, ids start at 1

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (g[i][j] != 0) {
                    continue; // land or already visited water
                }

                // start a new component (BFS)
                Queue<int[]> queue = new ArrayDeque<>();
                queue.add(new int[]{i, j});
                g[i][j] = nextLakeId; // mark as belonging to this lake

                boolean touchesBorder = false;
                int componentSize = 0;

                while (!queue.isEmpty()) {
                    int[] cur = queue.poll();
                    int x = cur[0];
                    int y = cur[1];
                    componentSize++;

                    // check if current cell lies on the border
                    if (x == 0 || x == n - 1 || y == 0 || y == m - 1) {
                        touchesBorder = true;
                    }

                    // explore neighbours
                    for (int[] d : DIRS) {
                        int nx = x + d[0];
                        int ny = y + d[1];
                        if (isValidCell(nx, ny, n, m) && g[nx][ny] == 0) {
                            g[nx][ny] = nextLakeId;
                            queue.add(new int[]{nx, ny});
                        }
                    }
                }

                // If the component does NOT touch the border, it is a lake.
                if (!touchesBorder) {
                    lakes.add(new Lake(nextLakeId, componentSize));
                }

                nextLakeId++;
            }
        }
        return lakes;
    }

    /** Helper that checks whether a cell is inside the grid. */
    private static boolean isValidCell(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * Chooses the set of lake identifiers that should be turned into land.
     * The smallest lakes are removed first to minimise the total number of
     * converted cells.
     *
     * @param allLakes list of all discovered lakes
     * @param count    how many lakes must be removed
     * @return set of lake ids to delete
     */
    private static Set<Integer> selectLakesToDelete(List<Lake> allLakes, int count) {
        // Sort lakes by size in ascending order and remove the first {@code count}
        // ones – they are the smallest lakes.
        List<Lake> sorted = new ArrayList<>(allLakes);
        sorted.sort(Comparator.comparingInt(l -> l.size));

        Set<Integer> toDelete = new HashSet<>();
        for (int i = 0; i < count; i++) {
            toDelete.add(sorted.get(i).id);
        }
        return toDelete;
    }

    /**
     * Prints the minimal cost and the transformed map.
     *
     * @param grid     original grid (will be mutated with lake ids)
     * @param deleteIds set of lake ids that have to become land
     * @param cost     total number of cells that change from water to land
     */
    private static void printResult(int[][] grid, Set<Integer> deleteIds, int cost) {
        StringBuilder out = new StringBuilder();
        out.append(cost).append('\n');

        for (int i = 0; i < grid.length; i++) {
            StringBuilder row = new StringBuilder();
            for (int j = 0; j < grid[i].length; j++) {
                int cellId = grid[i][j];
                if (cellId == 0) {               // original water cell
                    row.append('*');
                } else if (deleteIds.contains(cellId)) {
                    row.append('*');             // lake that we turn into land
                } else {
                    row.append('.');             // land or lake we keep
                }
            }
            out.append(row).append('\n');
        }

        System.out.print(out);
    }
}

import java.io.*;
import java.util.*;

public class LakesInBerland {

    /** Size of the map */
    private static final int MAX_N = 1000;

    /** Directions used for neighbour searches */
    private static final int[][] NEIGHBOURS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // -----------------------------------------------------------------
            // 1️⃣  Read input
            // -----------------------------------------------------------------
            String[] header = br.readLine().split("\\s+");
            int rows = Integer.parseInt(header[0]);
            int cols = Integer.parseInt(header[1]);
            int lakesToKeep = Integer.parseInt(header[2]);

            char[][] map = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                map[r] = br.readLine().toCharArray();
            }

            // -----------------------------------------------------------------
            // 2️⃣  Identify ocean cells (connected to the border)
            // -----------------------------------------------------------------
            boolean[][] isOcean = new boolean[rows][cols];
            markOceanCells(map, isOcean, rows, cols);

            // -----------------------------------------------------------------
            // 3️⃣  Discover all lakes (components of '.' not belonging to the ocean)
            // -----------------------------------------------------------------
            List<Lake> lakes = discoverLakes(map, isOcean, rows, cols);

            // -----------------------------------------------------------------
            // 4️⃣  Sort lakes by size (ascending) – the smallest ones will be removed first
            // -----------------------------------------------------------------
            lakes.sort(Comparator.comparingInt(l -> l.size));

            // -----------------------------------------------------------------
            // 5️⃣  Remove lakes that exceed the allowed number (keeps the first `lakesToKeep` lakes)
            // -----------------------------------------------------------------
            int filledCells = 0;
            for (int i = lakesToKeep; i < lakes.size(); i++) {
                Lake lake = lakes.get(i);
                filledCells += fillLakeWithLand(map, lake);
            }

            // -----------------------------------------------------------------
            // 6️⃣  Restore the original ocean cells (they were temporarily marked)
            // -----------------------------------------------------------------
            restoreOceanCells(map, isOcean);

            // -----------------------------------------------------------------
            // 7️⃣  Output result
            // -----------------------------------------------------------------
            System.out.println(filledCells);
            printMap(map);
        }
    }

    /** Marks cells that are connected to any border cell (ocean). */
    private static void markOceanCells(char[][] grid, boolean[][] ocean, int n, int m) {
        Deque<Integer> queue = new ArrayDeque<>();

        // put all border cells that are water ('.') into the queue
        for (int c = 0; c < m; c++) {
            maybeAddBorderCell(queue, ocean, grid, 0, c);
            maybeAddBorderCell(queue, ocean, grid, n - 1, c);
        }
        for (int r = 1; r < n - 1; r++) {
            maybeAddBorderCell(queue, ocean, grid, r, 0);
            maybeAddBorderCell(queue, ocean, grid, r, m - 1);
        }

        // BFS over water cells that can reach the border
        while (!queue.isEmpty()) {
            int r = queue.removeFirst();
            int c = queue.removeLast(); // queue stores pairs as two ints, see below
            // The above line is only for illustration – in practice we store a Pair.
        }
    }

    /** Helper that enqueues a border cell if it is water and not already marked. */
    private static void maybeAddBorderCell(
            Deque<int[]> queue, boolean[][] ocean, char[][] grid, int r, int c) {
        if (isWater(grid[r][c]) && !ocean[r][c]) {
            ocean[r][c] = true;
            queue.add(new int[]{r, c});
        }
    }

    /** BFS that expands from a given cell, marking reachable water cells. */
    private static void bfsMarkWater(char[][] grid,
                                     boolean[][] visited,
                                     boolean[][] ocean,
                                     int startR, int startC,
                                     int n, int m) {
        Queue<int[]> q = new ArrayDeque<>();
        q.add(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];

            for (int[] dir : NEIGHBOURS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isWater(grid[nr][nc]) && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    if (!ocean[nr][nc]) {
                        ocean[nr][nc] = true;          // part of the ocean
                    }
                    q.add(new int[]{nr, nc});
                }
            }
        }
    }

    /** Returns true if the cell contains water ('.'). */
    private static boolean isWater(char ch) {
        return ch == '.';
    }

    /** Discovers every lake (connected '.' component not belonging to the ocean). */
    private static List<Lake> discoverLakes(char[][] grid,
                                            boolean[][] ocean,
                                            int n, int m) {
        List<Lake> lakes = new ArrayList<>();
        int lakeId = 0;

        boolean[][] visited = new boolean[n][m];

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (isWater(grid[r][c]) && !visited[r][c] && !ocean[r][c]) {
                    Lake lake = new Lake(lakeId++);
                    bfsExploreLake(grid, visited, lake, r, c, n, m);
                    lakes.add(lake);
                }
            }
        }
        return lakes;
    }

    /** Explores a single lake using BFS and fills its data structure. */
    private static void bfsExploreLake(char[][] grid,
                                       boolean[][] visited,
                                       Lake lake,
                                       int startR, int startC,
                                       int n, int m) {
        Queue<int[]> q = new ArrayDeque<>();
        q.add(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];
            lake.incrementSize();
            lake.addPosition(r, c);
            grid[r][c] = '*';              // temporarily mark as processed

            for (int[] dir : NEIGHBOURS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isInside(nr, nc, n, m)
                        && isWater(grid[nr][nc])
                        && !visited[nr][nc]
                        && !ocean[nr][nc]) {
                    visited[nr][nc] = true;
                    q.add(new int[]{nr, nc});
                }
            }
        }
    }

    /** Fills a lake with land ('*') and returns how many cells were changed. */
    private static int fillLakeWithLand(char[][] grid, Lake lake) {
        int count = 0;
        for (int idx = 0; idx < lake.posR.size(); idx++) {
            int r = lake.posR.get(idx);
            int c = lake.posC.get(idx);
            grid[r][c] = '*';
            count++;
        }
        return count;
    }

    /** Restores the original ocean cells (they were marked with '*' during processing). */
    private static void restoreOceanCells(char[][] grid, boolean[][] ocean) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (ocean[r][c]) {
                    grid[r][c] = '.';
                }
            }
        }
    }

    /** Simple pretty‑printer for the map. */
    private static void printMap(char[][] grid) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                System.out.print(grid[r][c]);
            }
            if (r != grid.length - 1) {
                System.out.println();
            }
        }
    }

    /** Utility class representing a lake. */
    private static class Lake {
        final int id;
        int size = 0;
        final List<Integer> rows = new ArrayList<>();
        final List<Integer> cols = new ArrayList<>();

        Lake(int id) {
            this.id = id;
        }

        void incrementSize() {
            size++;
        }

        void addPosition(int r, int c) {
            rows.add(r);
            cols.add(c);
        }

        @Override
        public String toString() {
            return "Lake{id=" + id + ", size=" + size + '}';
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original {@code Lakes_in_berland} program.
 *
 * <p>
 *   Changes made:
 *   <ul>
 *     <li>Extracted small, single‑purpose methods.</li>
 *     <li>Replaced the custom scanner with the standard {@link BufferedReader}
 *         (still fast enough for typical input sizes).</li>
 *     <li>Used a small {@code Point} record instead of the ad‑hoc {@code Pair}</li>
 *         class – it makes the intent clearer.</li>
 *     <li>Separated the lake‑detection logic from the main routine.</li>
 *     <li>Removed magic numbers and gave meaningful names to constant
 *         directions.</li>
 *     <li>Added JavaDoc comments and removed the unused {@code mod} field.</li>
 *     <li>Formatted the output using a {@code PrintWriter} that is closed with
 *         try‑with‑resources.</li>
 *   </ul>
 * </p>
 */
public final class LakesInBerland {

    /** Directions used for 4‑way (orthogonal) traversal of a grid. */
    private static final int[][] DIRS = {
            {-1, 0}, // up
            {1, 0},  // down
            {0, -1}, // left
            {0, 1}   // right
    };

    /** Simple immutable point used to represent a cell coordinate. */
    private record Point(int x, int y) implements Comparable<Point> {
        @Override
        public int compareTo(Point o) {
            int cmp = Integer.compare(this.x, o.x);
            return (cmp != 0) ? cmp : Integer.compare(this.y, o.y);
        }
    }

    /** Holds information about one lake (connected component of '.' cells). */
    private static final class Lake {
        final List<Point> cells;
        final int size;
        final boolean touchesBorder;

        Lake(List<Point> cells, boolean touchesBorder) {
            this.cells = cells;
            this.size = cells.size();
            this.touchesBorder = touchesBorder;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        // -----------------------------------------------------------------
        // 1️⃣  Input handling
        // -----------------------------------------------------------------
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            PrintWriter out = new PrintWriter(System.out, true);

            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());
            int wantedComponentCount = Integer.parseInt(st.nextToken());

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            // -----------------------------------------------------------------
            // 2️⃣  Discover interior lakes
            // -----------------------------------------------------------------
            List<Lake> interiorLakes = findInteriorLakes(grid, n, m);

            // -----------------------------------------------------------------
            // 3️⃣  Convert the required number of lakes into '*' cells
            // -----------------------------------------------------------------
            int lakesToConvert = interiorLakes.size() - wantedComponentCount;
            long answer = 0L;

            // The original program processes lakes in the order they were added
            // (by increasing size, then by insertion order).  We keep that order.
            for (int i = 0; i < lakesToConvert && i < interiorLakes.size(); i++) {
                Lake lake = interiorLakes.get(i);
                answer += lake.size;
                markAsDestroyed(lake, grid);
            }

            // -----------------------------------------------------------------
            // 4️⃣  Output
            // -----------------------------------------------------------------
            out.println(answer);
            for (char[] row : grid) {
                out.println(new String(row));
            }
        }
    }

    /**
     * Finds all lakes that are *completely* surrounded by '*' (i.e. they do not
     * touch the border of the grid).
     *
     * @param grid   the character grid
     * @param n      number of rows
     * @param m      number of columns
     * @return a list containing every interior lake, in the order they are
     *         discovered during the scan.
     */
    private static List<Lake> findInteriorLakes(char[][] grid, int n, int m) {
        boolean[][] visited = new boolean[n][m];
        List<Lake> lakes = new ArrayList<>();

        for (int r = 0; r < n; r++) {
            Arrays.fill(visited[r], false);
        }

        for (int r = 1; r < n - 1; r++) {          // skip the outer border
            for (int c = 1; c < m - 1; c++) {
                if (!visited[r][c] && grid[r][c] == '.') {
                    Lake lake = exploreLake(r, c, grid, visited, n, m);
                    if (!lake.touchesBorder) {
                        lakes.add(lake);
                    }
                }
            }
        }
        return lakes;
    }

    /**
     * Performs a BFS starting at {@code sr, sc} and returns a {@link Lake}
     * describing the connected component.
     *
     * @param sr     starting row
     * @param sc     starting column
     * @param grid   the grid
     * @param visited   matrix that records visited cells
     * @param n      number of rows
     * @param m      number of columns
     * @return a {@code Lake} object encapsulating the component data.
     */
    private static Lake exploreLake(int sr, int sc,
                                    char[][] grid,
                                    boolean[][] visited,
                                    int n,
                                    int m) {
        List<Point> cells = new ArrayList<>();
        Deque<Point> queue = new ArrayDeque<>();
        queue.add(new Point(sr, sc));
        visited[sr][sc] = true;

        boolean touchesBorder = false;

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            cells.add(cur);
            int x = cur.x;
            int y = cur.y;

            // If we reached any border cell, mark the whole component as such.
            if (x == 0 || x == n - 1 || y == 0 || y == m - 1) {
                touchesBorder = true;
            }

            // Explore the four orthogonal neighbours.
            for (int[] dir : DIRS) {
                int nx = x + dir[0];
                int ny = y + dir[1];
                if (isInside(nx, ny, n, m) && !visited[nx][ny] && grid[nx][ny] == '.') {
                    visited[nx][ny] = true;
                    queue.add(new Point(nx, ny));
                }
            }
        }
        return new Lake(cells, touchesBorder);
    }

    /** Helper that checks whether a coordinate lies inside the grid bounds. */
    private static boolean isInside(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * Marks every cell of {@code lake} with the character '*', mutating {@code grid}.
     *
     * @param lake the lake to destroy
     * @param grid the grid that will be updated
     */
    private static void markAsDestroyed(Lake lake, char[][] grid) {
        for (Point p : lake.cells) {
            grid[p.x][p.y] = '*';
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the "Mark component areas" problem.
 * The program reads a grid, identifies interior connected components,
 * selects the smallest components (keeping the k largest untouched),
 * marks them with '*', and prints the total size of marked cells.
 */
public class Main {

    /** Directions used for exploring neighbours (up, left, down, right). */
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, -1, 0, 1};

    /** Entry point – wires the I/O streams through try‑with‑resources. */
    public static void main(String[] args) throws Exception {
        try (InputStream in = System.in;
             PrintWriter out = new PrintWriter(System.out)) {

            new Solver().solve(in, out);
        }
    }

    /** -------------------------------------------------------
     *  Solver – encapsulates all logic of the original program.
     *  ------------------------------------------------------- */
    static class Solver {

        /** ---------------------------------------------------
         *  Simple container for a connected component.
         *  Implements Comparable so we can sort by size.
         *  --------------------------------------------------- */
        private static final class Component implements Comparable<Component> {
            final int id;   // identifier used by the visitation matrix
            final int size; // number of cells in the component

            Component(int id, int size) {
                this.id = id;
                this.size = size;
            }

            @Override
            public int compareTo(Component o) {
                return Integer.compare(this.size, o.size);
            }
        }

        /** ---------------------------------------------------
         *  Minimal input parser that works with BufferedReader.
         *  --------------------------------------------------- */
        private static final class InputReader {
            private final BufferedReader reader;
            private StringTokenizer tokenizer;

            InputReader(InputStream stream) {
                this.reader = new BufferedReader(new InputStreamReader(stream));
            }

            private void ensureTokenizer() throws IOException {
                while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                    String line = reader.readLine();
                    if (line != null) tokenizer = new StringTokenizer(line);
                }
            }

            String next() throws IOException {
                ensureTokenizer();
                return tokenizer.nextToken();
            }

            int nextInt() throws IOException {
                return Integer.parseInt(next());
            }
        }

        /** ---------------------------------------------------
         *  Grid representation – separates data from logic.
         *  --------------------------------------------------- */
        private static final class Grid {
            private final char[][] cells;
            private final int rows;
            private final int cols;

            Grid(int rows, int cols) {
                this.rows = rows;
                this.cols = cols;
                this.cells = new char[rows][cols];
            }

            /** Fill the grid from the input reader. */
            void readFrom(InputReader in) throws IOException {
                for (int r = 0; r < rows; ++r) {
                    String s = in.next();
                    System.arraycopy(s.toCharArray(), 0, cells[r], 0, cols);
                }
            }

            char get(int r, int c) {
                return cells[r][c];
            }

            /** Replace a cell with a new character (used for marking). */
            void set(int r, int c, char value) {
                cells[r][c] = value;
            }
        }

        /** ---------------------------------------------------
         *  Visitation matrix holder – tracks which component each
         *  visited cell belongs to.
         *  --------------------------------------------------- */
        private static final class Visited {
            final int[][] componentId;
            int nextId; // next component identifier

            Visited(int rows, int cols) {
                componentId = new int[rows][cols];
                for (int[] row : componentId) Arrays.fill(row, -1);
                nextId = 0;
            }

            /** Assign a component id to a cell and return the component size. */
            int assign(int r, int c, Grid grid, List<Component> components) {
                int id = nextId++;
                int size = explore(r, c, grid, componentId, id);
                if (size > 0) {
                    components.add(new Component(id, size));
                }
                return id;
            }

            /** Depth‑first exploration of a component. */
            private int explore(int r, int c, Grid grid,
                                int[][] compId, int id) {
                int size = 1;
                boolean touchesBorder = false;

                for (int dir = 0; dir < 4; ++dir) {
                    int nr = r + DX[dir];
                    int nc = c + DY[dir];

                    // Outside bounds → component touches the border.
                    if (nr < 0 || nr >= grid.rows || nc < 0 || nc >= grid.cols) {
                        touchesBorder = true;
                    }
                    // Unvisited empty cell → continue DFS.
                    else if (grid.get(nr, nc) == '.' && compId[nr][nc] == -1) {
                        int subSize = explore(nr, nc, grid, compId, id);
                        if (subSize == 0) {
                            touchesBorder = true;
                        } else {
                            size += subSize;
                        }
                    }
                }

                // Border‑touching components are considered “invalid” for marking.
                return touchesBorder ? 0 : size;
            }
        }

        /** ---------------------------------------------------
         *  Core algorithm implementation.
         *  --------------------------------------------------- */
        public void solve(InputReader in, PrintWriter out) throws IOException {
            // ----- read parameters -------------------------------------------------
            int n = in.nextInt();
            int m = in.nextInt();
            int k = in.nextInt();

            // ----- initialise data structures ---------------------------------------
            Grid grid = new Grid(n, m);
            grid.readFrom(in);

            Visited visited = new Visited(n, m);
            List<Component> components = new ArrayList<>();

            // ----- discover all interior components ---------------------------------
            for (int r = 0; r < n; ++r) {
                for (int c = 0; c < m; ++c) {
                    if (grid.get(r, c) == '.' && visited.componentId[r][c] == -1) {
                        visited.assign(r, c, grid, components);
                    }
                }
            }

            // ----- sort components by size (ascending) -----------------------------
            Collections.sort(components);

            // ----- decide which components will be marked -------------------------
            int[] componentMark = new int[visited.nextId]; // 0 = keep, 1 = mark
            Arrays.fill(componentMark, 0);

            int totalMarkedCells = 0;
            int keep = Math.min(k, components.size());                     // how many largest components to keep
            int componentsToMark = components.size() - keep;               // number of smallest components to mark

            for (int i = 0; i < componentsToMark; ++i) {
                Component comp = components.get(i);
                totalMarkedCells += comp.size;
                componentMark[comp.id] = 1;               // mark this component
            }

            // ----- paint the grid --------------------------------------------------
            for (int r = 0; r < n; ++r) {
                for (int c = 0; c < m; ++c) {
                    if (visited.componentId[r][c] >= 0 && componentMark[visited.componentId[r][c]] == 1) {
                        grid.set(r, c, '*');
                    }
                }
            }

            // ----- output -----------------------------------------------------------
            out.println(totalMarkedCells);
            for (char[] row : grid.cells) {
                out.println(new String(row));
            }
        }
    }
}

// Refactored Java program – fully self‑contained
// ------------------------------------------------
// 1. Position – a tiny immutable record that stores a cell coordinate.
// 2. Lake – represents a lake: its size and the cells that belong to it.
// 3. LakeFinder – discovers all lakes in the grid and provides methods to
//    process them (sort, sum smallest ones, mark them for removal).
// 4. Main – reads input, runs the finder and prints the required output.
// ------------------------------------------------

import java.util.*;
import java.util.stream.Collectors;

/** Simple immutable pair of row/column indices. */
record Position(int row, int col) {}

/** Represents a lake discovered in the grid. */
final class Lake {
    /** Number of cells belonging to the lake. */
    final long size;
    /** All cells that belong to the lake. */
    final List<Position> cells;

    Lake(long size, List<Position> cells) {
        this.size = size;
        this.cells = List.copyOf(cells);
    }
}

/** Utility class that encapsulates the whole lake‑finding algorithm. */
final class LakeFinder {
    /** Directions used for neighbour exploration (4‑connected). */
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    private final char[][] grid;
    private final boolean[][] visited;
    private final int rows;
    private final int cols;
    /** Collected lakes, unsorted. */
    private final List<Lake> lakes = new ArrayList<>();

    LakeFinder(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.visited = new boolean[rows][cols];
    }

    /** Public entry point – discovers all lakes in the grid. */
    List<Lake> findAllLakes() {
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (!visited[r][c] && grid[r][c] == '.') {
                    explored(r, c);
                }
            }
        }
        return lakes;
    }

    /** Flood‑fill starting at (r,c); the discovered component becomes a Lake. */
    private void explored(int startR, int startC) {
        List<Position> component = new ArrayList<>();
        boolean touchesBorder = false;
        Deque<Position> stack = new ArrayDeque<>();
        stack.push(new Position(startR, startC));
        visited[startR][startC] = true;

        while (!stack.isEmpty()) {
            Position p = stack.pop();
            component.add(p);
            // Border check
            if (p.row() == 0 || p.row() == rows - 1 || p.col() == 0 || p.col() == cols - 1) {
                touchesBorder = true;
            }
            // Expand neighbours
            for (int d = 0; d < 4; ++d) {
                int nr = p.row() + DR[d];
                int nc = p.col() + DC[d];
                if (isInside(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                    visited[nr][nc] = true;
                    stack.push(new Position(nr, nc));
                }
            }
        }

        if (!touchesBorder) {
            lakes.add(new Lake(component.size(), component));
        }
    }

    /** Checks whether a coordinate lies inside the grid. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Sorts lakes by size (ascending) and returns the sorted list. */
    List<Lake> sortedBySize() {
        return lakes.stream()
                .sorted(Comparator.comparingLong(l -> l.size))
                .collect(Collectors.toList());
    }

    /**
     * Removes the {@code keep} smallest lakes (i.e. keeps only the largest {@code k}
     * lakes) and returns the total number of cells that would be turned into '*',
     * while also mutating {@code grid} to reflect those removals.
     *
     * @param keep    number of lakes that will survive (the largest ones)
     * @param grid    the map that will be mutated in‑place
     * @return total size of the lakes that were removed
     */
    long removeSmallestAndMark(List<Lake> sorted, int keep, char[][] grid) {
        long removedCells = 0;
        // All lakes except the last {@code keep} ones are removed.
        for (int i = 0; i < sorted.size() - keep; ++i) {
            Lake lake = sorted.get(i);
            removedCells += lake.size;
            for (Position p : lake.cells) {
                grid[p.row()][p.col()] = '*';
            }
        }
        return removedCells;
    }
}

/** Main class – entry point, input handling and output. */
public class Main {
    public static void main(String[] args) {
        // ---------- Input ----------
        try (Scanner scanner = new Scanner(System.in)) {
            String[] first = scanner.nextLine().split("\\s+");
            int n = Integer.parseInt(first[0]);
            int m = Integer.parseInt(first[1]);
            int k = Integer.parseInt(first[2]);

            char[][] grid = new char[n][];
            for (int i = 0; i < n; ++i) {
                grid[i] = scanner.next().toCharArray();
            }

            // ---------- Process ----------
            LakeFinder finder = new LakeFinder(grid);
            List<Lake> lakes = finder.findAllLakes();

            // Sort lakes by size (ascending) – keep the smallest ones.
            List<Lake> sorted = finder.sortedBySize();

            // According to the original code we keep the largest {@code k} lakes,
            // therefore we remove all the others.
            long answer = finder.removeSmallestAndMark(sorted, k, grid);

            // ---------- Output ----------
            System.out.println(answer);
            for (char[] row : grid) {
                System.out.println(new String(row));
            }
        }
    }
}

import java.awt.Point;
import java.util.*;

public class Main {

    /* Constants used for path states */
    private static final int NOT_VISITED = -1;
    private static final int VISITED    = 0;
    private static final int TO_CLEAR   = 1;

    /* Direction vectors */
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    private final char[][] grid;      // input map
    private final int[][]   path;     // visitation state
    private final int rows;
    private final int cols;
    private final int keepLakes;      // number of lakes we want to keep

    /* --------------------------------------------------------------- */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        new Main(n, m, k).solve(sc);
    }

    /* --------------------------------------------------------------- */
    public Main(int rows, int cols, int keepLakes) {
        this.rows    = rows;
        this.cols    = cols;
        this.keepLakes = keepLakes;
        this.grid    = new char[rows][cols];
        this.path    = new int[rows][cols];
    }

    /* --------------------------------------------------------------- */
    private void solve(Scanner sc) {
        readInput(sc);
        initialisePath();
        markBorderReachable();
        List<Lake> interior = discoverInteriorLakes();
        Collections.sort(interior, Comparator.comparingInt(l -> l.points.size()));
        int lakesToClear = Math.max(0, interior.size() - keepLakes);
        int totalCleared = 0;

        for (int i = 0; i < lakesToClear; i++) {
            totalCleared += interior.get(i).points.size();
            markLakeForClearing(interior.get(i));
        }

        System.out.println(totalCleared);
        printResult();
    }

    /* --------------------------------------------------------------- */
    private void readInput(Scanner sc) {
        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
    }

    private void initialisePath() {
        for (int i = 0; i < rows; i++) {
            Arrays.fill(path[i], NOT_VISITED);
        }
    }

    private void markBorderReachable() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isOnEdge(i, j) && grid[i][j] == '.' && path[i][j] == NOT_VISITED) {
                    explore(i, j);
                }
            }
        }
    }

    private void explore(int sx, int sy) {
        Deque<Point> stack = new ArrayDeque<>();
        stack.push(new Point(sx, sy));
        path[sx][sy] = VISITED;
        while (!stack.isEmpty()) {
            Point cur = stack.pop();
            for (int d = 0; d < DX.length; d++) {
                int nx = cur.x + DX[d];
                int ny = cur.y + DY[d];
                if (inside(nx, ny) && path[nx][ny] == NOT_VISITED && grid[nx][ny] == '.') {
                    path[nx][ny] = VISITED;
                    stack.push(new Point(nx, ny));
                }
            }
        }
    }

    private List<Lake> discoverInteriorLakes() {
        List<Lake> lakes = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && path[i][j] == NOT_VISITED) {
                    lakes.add(exploreLake(i, j));
                }
            }
        }
        return lakes;
    }

    private Lake exploreLake(int sx, int sy) {
        List<Point> points = new ArrayList<>();
        Deque<Point> stack = new ArrayDeque<>();
        stack.push(new Point(sx, sy));
        path[sx][sy] = VISITED;
        points.add(new Point(sx, sy));

        while (!stack.isEmpty()) {
            Point cur = stack.pop();
            for (int d = 0; d < DX.length; d++) {
                int nx = cur.x + DX[d];
                int ny = cur.y + DY[d];
                if (inside(nx, ny) && path[nx][ny] == NOT_VISITED && grid[nx][ny] == '.') {
                    path[nx][ny] = VISITED;
                    stack.push(new Point(nx, ny));
                    points.add(new Point(nx, ny));
                }
            }
        }
        return new Lake(points);
    }

    private void markLakeForClearing(Lake lake) {
        for (Point p : lake.points) {
            path[p.x][p.y] = TO_CLEAR;
        }
    }

    private boolean isOnEdge(int x, int y) {
        return x == 0 || y == 0 || x == rows - 1 || y == cols - 1;
    }

    private boolean inside(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    private void printResult() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(path[i][j] == TO_CLEAR ? '*' : grid[i][j]);
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }

    /* --------------------------------------------------------------- */
    /** Simple container representing one lake component. */
    private static class Lake {
        final List<Point> points;
        Lake(List<Point> points) { this.points = points; }
    }
}

import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;
import java.util.Scanner;

public class Main {

    private static final char EMPTY = '.';
    private static final char BLOCKED = '*';

    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            int keep = scanner.nextInt();

            char[][] grid = readGrid(scanner, rows);
            boolean[][] visited = new boolean[rows][cols];
            List<Component> components = new ArrayList<>();

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == EMPTY && !visited[r][c]) {
                        exploreComponent(grid, visited, r, c, rows, cols, components);
                    }
                }
            }

            // Sort components by area (size) in ascending order
            Collections.sort(components);

            int toRemove = Math.max(0, components.size() - keep);
            int removedArea = 0;

            for (int i = 0; i < toRemove; i++) {
                clearComponent(grid, components.get(i));
                removedArea += components.get(i).area;
            }

            System.out.println(removedArea);
            printGrid(grid);
        }
    }

    private static char[][] readGrid(Scanner scanner, int rows) {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    private static void exploreComponent(char[][] grid,
                                          boolean[][] visited,
                                          int startRow,
                                          int startCol,
                                          int rows,
                                          int cols,
                                          List<Component> components) {
        Queue<Position> queue = new LinkedList<>();
        queue.add(new Position(startRow, startCol));
        visited[startRow][startCol] = true;

        int area = 0;
        boolean touchesBorder = false;

        while (!queue.isEmpty()) {
            Position cur = queue.poll();
            area++;

            for (int d = 0; d < DIRS.length; d++) {
                int nr = cur.row + DIRS[d][0];
                int nc = cur.col + DIRS[d][1];

                if (!inBounds(nr, nc, rows, cols)) {
                    touchesBorder = true;
                } else if (grid[nr][nc] == EMPTY && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Position(nr, nc));
                }
            }
        }

        // Store component only if it does NOT touch the border
        if (!touchesBorder) {
            components.add(new Component(startRow, startCol, area));
        }
    }

    private static void clearComponent(char[][] grid, Component comp) {
        Queue<Position> queue = new LinkedList<>();
        queue.add(new Position(comp.startRow, comp.startCol));
        grid[comp.startRow][comp.startCol] = BLOCKED;

        while (!queue.isEmpty()) {
            Position cur = queue.poll();
            for (int d = 0; d < DIRS.length; d++) {
                int nr = cur.row + DIRS[d][0];
                int nc = cur.col + DIRS[d][1];
                if (inBounds(nr, nc, grid.length, grid[0].length)
                        && grid[nr][nc] == EMPTY) {
                    grid[nr][nc] = BLOCKED;
                    queue.add(new Position(nr, nc));
                }
            }
        }
    }

    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            StringBuilder sb = new StringBuilder(row.length);
            for (char ch : row) {
                sb.append(ch);
            }
            System.out.println(sb);
        }
    }

    // -------------------------------------------------------------------------
    // Helper classes
    // -------------------------------------------------------------------------

    private static final int[][] DIRS = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};

    /** Simple container for a cell position */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Represents a connected component of empty cells */
    private static final class Component implements Comparable<Component> {
        final int startRow;
        final int startCol;
        final int area;

        Component(int startRow, int startCol, int area) {
            this.startRow = startRow;
            this.startCol = startCol;
            this.area = area;
        }

        @Override
        public int compareTo(Component o) {
            return Integer.compare(this.area, o.area);
        }
    }
}

import java.util.*;
import java.util.stream.Collectors;

/**
 * Utility class that contains all static helper methods.
 * The algorithm consists of three logical steps:
 *  1. Find every “lake” (connected component of '.') that does NOT touch the border.
 *  2. Sort the lakes by size and remove the smallest lakes until only K lakes stay.
 *  3. Delete the cells belonging to the removed lakes (replace them with '*')
 *     and report how many cells were removed.
 */
final class LakeCleaner {

    /* Direction vectors for the four orthogonal neighbours */
    private static final int[][] DIRECTIONS = {
            {0, -1}, {0, 1}, {-1, 0}, {1, 0}
    };

    private LakeCleaner() { /* unused */ }

    /** Simple immutable point used for coordinates. */
    private static final class Point {
        final int x; // column index
        final int y; // row index

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Executes the whole procedure.
     *
     * @param scan a {@link Scanner} positioned at the start of the input.
     * @throws IllegalArgumentException if the input format is invalid.
     */
    public static void process(Scanner scan) {
        parseDimensions(scan);
        char[][] grid = readGrid(scan);
        boolean[][] visited = new boolean[grid.length][grid[0].length];

        List<Set<Point>> lakes = discoverLakes(grid, visited);

        // Keep the K largest lakes; delete cells of all smaller lakes.
        deleteSmallestLakes(lakes, grid);

        // Output the required information.
        System.out.println(countDeletedCells(lakes) - K); // total removed cells before deletion
        printGrid(grid);
    }

    /** Reads N, M and K and validates them. */
    private static void parseDimensions(Scanner scan) {
        if (!scan.hasNextInt()) throw new IllegalArgumentException("Missing N");
        int n = scan.nextInt(); // number of rows (vertical)
        if (!scan.hasNextInt()) throw new IllegalArgumentException("Missing M");
        int m = scan.nextInt(); // number of columns (horizontal)
        if (!scan.hasNextInt()) throw new IllegalArgumentException("Missing K");
        K = scan.nextInt();

        N = n; // keep legacy field names for compatibility with the original code
        M = m;
    }

    /** Reads the grid from the scanner (the original code swaps X/Y while storing). */
    private static char[][] readGrid(Scanner scan) {
        char[][] grid = new char[M][N]; // rows = M, columns = N
        for (int col = 0; col < N; col++) {
            String line = scan.next();
            if (line.length() != M) {
                throw new IllegalArgumentException("Row length does not match declared dimensions");
            }
            for (int row = 0; row < M; row++) {
                grid[row][col] = line.charAt(col);
            }
        }
        return grid;
    }

    /** Finds all interior lakes using BFS. */
    private static List<Set<Point>> discoverLakes(char[][] grid, boolean[][] visited) {
        List<Set<Point>> lakes = new ArrayList<>();

        for (int y = 1; y < N - 1; y++) {
            for (int x = 1; x < M - 1; x++) {
                if (grid[x][y] == '.' && !visited[x][y]) {
                    Set<Point> lake = bfsCollectLake(grid, visited, x, y);
                    lakes.add(lake);
                }
            }
        }

        lakes.sort(Comparator.comparingInt(Set::size));
        return lakes;
    }

    /** Performs a BFS starting from (x,y) and returns the whole component. */
    private static Set<Point> bfsCollectLake(char[][] grid, boolean[][] visited, int startX, int startY) {
        Queue<Point> queue = new ArrayDeque<>();
        Set<Point> component = new HashSet<>();

        Point start = new Point(startX, startY);
        queue.add(start);
        visited[startX][startY] = true;
        component.add(start);

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            for (int[][] dir : DIRECTIONS) {
                int nx = cur.x + dir[0];
                int ny = cur.y + dir[1];
                if (isValidCell(nx, ny, grid) && grid[nx][ny] == '.' && !visited[nx][ny]) {
                    Point next = new Point(nx, ny);
                    queue.add(next);
                    visited[nx][ny] = true;
                    component.add(next);
                }
            }
        }
        return component;
    }

    /** Checks bounds and that the cell is not a border cell (i.e., interior only). */
    private static boolean isValidCell(int x, int y, char[][] grid) {
        return x >= 0 && x < M && y >= 0 && y < N && grid[x][y] == '.';
    }

    /** Deletes cells belonging to the smallest lakes until only K lakes remain. */
    private static void deleteSmallestLakes(List<Set<Point>> lakes, char[][] grid) {
        // Number of lakes that must disappear
        int lakesToDelete = lakes.size() - K;
        if (lakesToDelete > 0) {
            for (int i = 0; i < lakesToDelete; i++) {
                Set<Point> lake = lakes.get(i);
                for (Point p : lake) {
                    grid[p.x][p.y] = '*';
                }
            }
        }
    }

    /** Returns the total number of cells that would be removed (used for output). */
    private static int countDeletedCells(List<Set<Point>> lakes) {
        return lakes.stream()
                .limit(lakes.size() - K)   // only the lakes that will be deleted
                .mapToInt(Set::size)
                .sum();
    }

    /** Prints the resulting grid to stdout. */
    private static void printGrid(char[][] grid) {
        for (int col = 0; col < N; col++) {
            for (int row = 0; row < M; row++) {
                System.out.print(grid[row][col]);
            }
            System.out.println();
        }
    }

    // Legacy field names kept only to preserve original behaviour.
    private static int N;   // number of columns
    private static int M;   // number of rows
    private static int K;   // number of lakes that must stay

    /** Entry point – matches the original `public static void main(String[])`. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            process(scanner);
        }
    }
}

/**
 * Refactored solution for the “Lakes” problem.
 * The program reads a grid ('.' = water, '*' = land), identifies lakes that are not
 * connected to the border, sorts them by size and removes the smallest ones
 * until exactly k lakes remain.  The total area of the removed lakes is printed,
 * followed by the resulting grid.
 *
 * The refactor focuses on readability, separation of concerns and proper use of
 * Java language features (generics, final constants, small helper classes, etc.).
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Constants & small utility types                                        */
    /* --------------------------------------------------------------------- */

    /** Four‑direction move vectors (up, right, down, left). */
    private static final int[][] DIRECTIONS = {
            { -1, 0 }, { 0, 1 }, { 1, 0 }, { 0, -1 }
    };

    /** Simple generic pair used throughout the code. */
    private static final class Pair<F, S> {
        private final F first;
        private final S second;

        Pair(F first, S second) {
            this.first = first;
            this.second = second;
        }

        F getFirst()  { return first; }
        S getSecond() { return second; }
    }

    /** Information about a discovered lake (size and one interior cell). */
    private static final class LakeInfo implements Comparable<LakeInfo> {
        final int size;   // number of cells belonging to the lake
        final int x;      // row index of a representative cell
        final int y;      // column index of a representative cell

        LakeInfo(int size, int x, int y) {
            this.size = size;
            this.x = x;
            this.y = y;
        }

        @Override
        public int compareTo(LakeInfo o) {
            return Integer.compare(this.size, o.size);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core processing class                                                  */
    /* --------------------------------------------------------------------- */

    /** Encapsulates all operations that work on a grid. */
    private static final class LakeProcessor {
        private final int rows;
        private final int cols;
        private final boolean[][] grid;   // true → water ('.'), false → land ('*')
        private final boolean[][] visited; // used during BFS traversals
        private final boolean[][] ignored; // cells that must stay ignored (border‑connected)
        private final List<LakeInfo> lakes = new ArrayList<>();

        LakeProcessor(int rows, int cols, boolean[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.visited = new boolean[rows][cols];
            this.ignored = new boolean[rows][cols];
        }

        /** Marks cells that are connected to any border as “ignored”. */
        void markBorderConnected() {
            for (int i = 0; i < rows; i++) {
                if (grid[i][0]) bfsIgnore(i, 0);
                if (grid[i][cols - 1]) bfsIgnore(i, cols - 1);
            }
            for (int j = 0; j < cols; j++) {
                if (grid[0][j]) bfsIgnore(0, j);
                if (grid[rows - 1][j]) bfsIgnore(rows - 1, j);
            }
        }

        /** Breadth‑first search that expands the “ignored” region from (x,y). */
        private void bfsIgnore(int startX, int startY) {
            Queue<Pair<Integer, Integer>> queue = new ArrayDeque<>();
            queue.add(new Pair<>(startX, startY));
            ignored[startX][startY] = true;

            while (!queue.isEmpty()) {
                Pair<Integer, Integer> cur = queue.poll();
                int x = cur.getFirst();
                int y = cur.getSecond();

                for (int[] dir : DIRECTIONS) {
                    int nx = x + dir[0];
                    int ny = y + dir[1];
                    if (isInside(nx, ny) && grid[nx][ny] && !visited[nx][ny] && !ignored[nx][ny]) {
                        queue.add(new Pair<>(nx, ny));
                        ignored[nx][ny] = true;
                    }
                }
            }
        }

        /** Finds all lakes that are not ignored and not yet visited. */
        List<LakeInfo> findLakes() {
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (grid[i][j] && !visited[i][j] && !ignored[i][j]) {
                        int size = bfsCount(i, j, false);
                        lakes.add(new LakeInfo(size, i, j));
                    }
                }
            }
            lakes.sort(null); // natural ordering (sizeascending)
            return lakes;
        }

        /** Removes the smallest {@code count} lakes (sets their cells to land). */
        int removeLakes(int count) {
            int totalRemovedArea = 0;
            for (int i = 0; i < count; i++) {
                LakeInfo lake = lakes.get(i);
                bfsFill(lake.x, lake.y);
                totalRemovedArea += lake.size;
            }
            return totalRemovedArea;
        }

        /* ----------------------------------------------------------------- */
        /*  BFS helpers                                                          */
        /* ----------------------------------------------------------------- */

        /** Breadth‑first search that counts cells of a lake.
         *  @param fillWhenTrue if {@code true} the visited cells are turned into land.
         */
        private int bfsCount(int startX, int startY, boolean fillWhenTrue) {
            Queue<Pair<Integer, Integer>> queue = new ArrayDeque<>();
            queue.add(new Pair<>(startX, startY));
            visited[startX][startY] = true;
            grid[startX][startY] = !fillWhenTrue; // turn to land if required

            int cnt = 0;
            while (!queue.isEmpty()) {
                Pair<Integer, Integer> cur = queue.poll();
                int x = cur.getFirst();
                int y = cur.getSecond();
                cnt++;

                for (int[] dir : DIRECTIONS) {
                    int nx = x + dir[0];
                    int ny = y + dir[1];
                    if (isInside(nx, ny) && grid[nx][ny] && !visited[nx][ny]) {
                        queue.add(new Pair<>(nx, ny));
                        visited[nx][ny] = true;
                        if (fillWhenTrue) {
                            grid[nx][ny] = false;
                        }
                    }
                }
            }
            return cnt;
        }

        /** Convenience wrapper that fills a lake (turns it into land). */
        private void bfsFill(int startX, int startY) {
            bfsCount(startX, startY, true);
        }

        /** Returns a copy of the processed grid for output. */
        boolean[][] getResultGrid() {
            // The original {@code grid} reference is returned – callers must not modify it.
            return grid;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                       */
    /* --------------------------------------------------------------------- */

    /** Simple fast scanner used for competitive‑programming style input. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns next token, retrying until one is available. */
        private String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (Exception e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Output utilities                                                       */
    /* --------------------------------------------------------------------- */

    private static void printGrid(boolean[][] grid) {
        for (boolean[] row : grid) {
            for (boolean cell : row) {
                System.out.print(cell ? '.' : '*');
            }
            System.out.println();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Main entry point                                                       */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        // The original program processes exactly one test case.
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int requiredLakes = scanner.nextInt();

        // Read the grid ('.' → water, any other character → land)
        boolean[][] rawGrid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols; j++) {
                rawGrid[i][j] = line.charAt(j) == '.';
            }
        }

        // core processing
        LakeProcessor processor = new LakeProcessor(rows, cols, rawGrid);
        processor.markBorderConnected();
        List<LakeInfo> lakes = processor.findLakes();

        int lakesToRemove = lakes.size() - requiredLakes;
        int removedArea = 0;
        if (lakesToRemove > 0) {
            // Sort again by size to be explicit (natural order already applied,
            // but we want a fresh comparator for clarity).
            lakes.sort(Comparator.comparingInt(info -> info.size));
            removedArea = processor.removeLakes(lakesToRemove);
        }

        // Output
        System.out.println(removedArea);
        printGrid(processor.getResultGrid());
    }
}

import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored solution for the “Lakes” problem.
 * The program reads a grid, finds all water‑only components that are not
 * connected to the border, removes the smallest ones until only {@code k}
 * lakes remain, and prints the number of removed cells together with the
 * modified grid.
 */
public class Main {

    /** Four possible movement directions (up, right, down, left). */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {0, 1}, {1, 0}, {0, -1}
    };

    /** dimensions of the map */
    private static int rows, cols;
    /** number of lakes that must stay untouched */
    private static int lakesToKeep;

    /** grid read from input – mutable during the algorithm */
    private static char[][] grid;
    /** Visited flag for DFS */
    private static boolean[][] visited;

    /** Simple container for a water component */
    private static final class Lake {
        final int size;          // number of cells in the component
        final int startRow, startCol; // any cell of the component (used for flood‑fill)
        final boolean touchesBoundary; // does the component touch the outer border?

        Lake(int size, int startRow, int startCol, boolean touchesBoundary) {
            this.size = size;
            this.startRow = startRow;
            this.startCol = startCol;
            this.touchesBoundary = touchesBoundary;
        }
    }

    /** Entry point */
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            readInput(sc);
            List<Lake> lakes = discoverLakes();
            lakes.sort(Comparator.comparingInt(l -> l.size));

            int removedCells = 0;
            int lakesToRemove = lakes.size() - lakesToKeep;
            for (int i = 0; i < lakesToRemove; i++) {
                Lake lake = lakes.get(i);
                removedCells += lake.size;
                floodFill(lake.startRow, lake.startCol);
            }

            out.println(removedCells);
            printGrid(out);
        }
    }

    /** Parses the input and stores it in the mutable grid structure. */
    private static void readInput(Scanner sc) {
        rows = sc.nextInt();
        cols = sc.nextInt();
        lakesToKeep = sc.nextInt();

        grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = sc.next();
            grid[r] = line.toCharArray();   // mutable copy
        }
    }

    /** Finds all closed (non‑boundary) water components using DFS. */
    private static List<Lake> discoverLakes() {
        List<Lake> lakes = new ArrayList<>();
        visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    Lake lake = new Lake(0, r, c, false);
                    dfs(r, c, lake);
                    if (!lake.touchesBoundary) {
                        lakes.add(lake);
                    }
                }
            }
        }
        return lakes;
    }

    /** Depth‑first search that expands a water component and records its size / boundary status. */
    private static void dfs(int r, int c, Lake lake) {
        if (r < 0 || r >= rows || c < 0 || c >= cols) return;
        if (grid[r][c] != '.' || visited[r][c]) return;

        visited[r][c] = true;
        lake.size++;

        if (isOnBoundary(r, c)) {
            lake.touchesBoundary = true;          // component touches the outer border
        }

        for (int[] dir : DIRECTIONS) {
            dfs(dir[0] + r, dir[1] + c, lake);
        }
    }

    /** Checks whether a cell lies on the outermost row or column. */
    private static boolean isOnBoundary(int r, int c) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    /** Marks the whole connected component with ‘*’ (removing the lake). */
    private static void floodFill(int r, int c) {
        if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] != '.') return;
        grid[r][c] = '*';
        for (int[] dir : DIRECTIONS) {
            floodFill(dir[0] + r, dir[1] + c);
        }
    }

    /** Outputs the resulting grid to the console. */
    private static void printGrid(PrintWriter out) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }
}

import java.util.*;
import java.util.stream.Collectors;

/**
 * Reads a map consisting of water ('.'), rock ('*') and dimensions N×M,
 * keeps exactly K water‑connected lakes (the largest ones) and removes all
 * others.  The program prints the number of water cells that are turned
 * into rock and the resulting map.
 *
 * The implementation is split into small, single‑purpose classes / methods
 * to improve readability, testability and future maintainability.
 */
public class LakeMaintainer {

    /* -------------------------------------------------------------------------
     *  Constants & basic data structures
     * ------------------------------------------------------------------------- */

    private static final char WATER  = '.';
    private static final char ROCK   = '*';
    private static final int NOT_VISITED = -1;
    private static final int EDGE_CONNECTED = 0;   // water reachable from border
    private static final int REMOVED = 1;          // water that will become '*'

    /** Simple 2‑D point used for BFS/DFS */
    private static final class Point {
        final int row, col;
        Point(int r, int c) { this.row = r; this.col = c; }
        @Override public boolean equals(Object o) {
            return (o instanceof Point) && ((Point) o).row == row && ((Point) o).col == col;
        }
        @Override public int hashCode() { return Objects.hash(row, col); }
    }

    /** One connected component of water that is *not* edge‑connected */
    private static final class Lake {
        final List<Point> cells;
        Lake(List<Point> cells) { this.cells = Collections.unmodifiableList(new ArrayList<>(cells)); }
        int size() { return cells.size(); }
    }

    /* -------------------------------------------------------------------------
     *  Core algorithm
     * ------------------------------------------------------------------------- */

    /** Holds the immutable input configuration */
    private static final class Input {
        final char[][] grid;   // original characters
        final boolean[][] isBorder; // true for cells on the outer rim
        final int targetLakeCount; // K – how many lakes must stay

        Input(char[][] grid, boolean[][] isBorder, int targetLakeCount) {
            this.grid = grid;
            this.isBorder = isBorder;
            this.targetLakeCount = targetLakeCount;
        }
    }

    /** Entry point */
    public static void main(String[] args) {
        Input input = readInput();
        markEdgeReachableWater(input);
        List<Lake> allLakes = discoverAllLakes(input);
        removeSmallestLakesUntilK(input, allLakes);
        printResult(input);
    }

    /** -------------------------------------------------------------------------
     *  Input handling
     * ------------------------------------------------------------------------- */
    private static Input readInput() {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        sc.nextLine();               // consume end‑of‑line

        char[][] grid = new char[n][m];
        boolean[][] isBorder = new boolean[n][m];
        for (int r = 0; r < n; r++) {
            String line = sc.nextLine().trim();
            if (line.length() != m) {
                throw new IllegalArgumentException("Row length does not match declared columns.");
            }
            for (int c = 0; c < m; c++) {
                grid[r][c] = line.charAt(c);
                isBorder[r][c] = r == 0 || r == n - 1 || c == 0 || c == m - 1;
            }
        }
        sc.close();
        return new Input(grid, isBorder, k);
    }

    /** -------------------------------------------------------------------------
     *  Flood‑fill from every border water cell – marks all water that can flow
     *  to the edge as “edge‑connected”.
     * ------------------------------------------------------------------------- */
    private static void markEdgeReachableWater(Input in) {
        boolean[][] edgeConnected = new boolean[in.grid.length][in.grid[0].length];
        for (int r = 0; r < in.grid.length; r++) {
            for (int c = 0; c < in.grid[0].length; c++) {
                if (in.isBorder[r][c] && in.grid[r][c] == WATER) {
                    floodFrom(r, c, edgeConnected);
                }
            }
        }
        // expose the result via a static field for later use (simple for a short program)
        EdgeInfo.setMarked(edgeConnected);
    }

    private static void floodFrom(int startR, int startC, boolean[][] visited) {
        Deque<Point> stack = new ArrayDeque<>();
        stack.push(new Point(startR, startC));
        visited[startR][startC] = true;

        while (!stack.isEmpty()) {
            Point cur = stack.pop();
            for (int d = 0; d < DX.length; d++) {
                int nr = cur.row + DX[d];
                int nc = cur.col + DY[d];
                if (isInBounds(nr, nc) && !visited[nr][nc] && isWater(nr, nc)) {
                    visited[nr][nc] = true;
                    stack.push(new Point(nr, nc));
                }
            }
        }
    }

    /** -------------------------------------------------------------------------
     *  Discover every lake that is *not* edge‑connected.
     * ------------------------------------------------------------------------- */
    private static List<Lake> discoverAllLakes(Input in) {
        boolean[][] notSeen = new boolean[in.grid.length][in.grid[0].length];
        List<Lake> lakes = new ArrayList<>();

        for (int r = 0; r < in.grid.length; r++) {
            for (int c = 0; c < in.grid[0].length; c++) {
                if (!notSeen[r][c] && isWater(r, c) && !EdgeInfo.isMarked(r, c)) {
                    Lake lake = exploreLake(r, c, notSeen);
                    lakes.add(lake);
                }
            }
        }
        return lakes;
    }

    private static Lake exploreLake(int startR, int startC, boolean[][] seen) {
        List<Point> component = new ArrayList<>();
        Queue<Point> q = new ArrayDeque<>();
        q.add(new Point(startR, startC));
        seen[startR][startC] = true;

        while (!q.isEmpty()) {
            Point cur = q.poll();
            component.add(cur);
            for (int d = 0; d < DX.length; d++) {
                Point nxt = new Point(cur.row + DX[d], cur.col + DY[d]);
                if (isInBounds(nxt.row, nxt.col)
                        && !seen[nxt.row][nxt.col]
                        && isWater(nxt.row, nxt.col)
                        && !EdgeInfo.isMarked(nxt.row, nxt.col)) {
                    seen[nxt.row][nxt.col] = true;
                    q.add(nxt);
                }
            }
        }
        return new Lake(component);
    }

    /** -------------------------------------------------------------------------
     *  Remove the smallest lakes until at most K lakes remain.
     * ------------------------------------------------------------------------- */
    private static void removeSmallestLakesUntilK(Input in, List<Lake> lakes) {
        int lakesToErase = lakes.size() - in.targetLakeCount;
        if (lakesToErase <= 0) {
            EdgeInfo.setRemovedArea(0);
            return;
        }

        // Sort lakes by size (ascending) – smallest first.
        lakes.sort(Comparator.comparingInt(l -> l.size()));

        int erasedCells = 0;
        for (int i = 0; i < lakesToErase; i++) {
            Lake lake = lakes.get(i);
            erasedCells += lake.size();

            // Mark every cell of this lake as “to become rock”.
            for (Point p : lake.cells) {
                EdgeInfo.markRemoved(p.row, p.col);
            }
        }
        EdgeInfo.setRemovedArea(erasedCells);
    }

    /** -------------------------------------------------------------------------
     *  Output phase – prints the number of erased cells and the final map.
     * ------------------------------------------------------------------------- */
    private static void printResult(Input in) {
        System.out.println(EdgeInfo.getRemovedArea());

        for (int r = 0; r < in.grid.length; r++) {
            StringBuilder out = new StringBuilder();
            for (int c = 0; c < in.grid[0].length; c++) {
                if (in.grid[r][c] == ROCK) {
                    out.append(ROCK);
                } else if (EdgeInfo.isMarked(r, c)) {
                    out.append(WATER);          // water that stays (edge‑connected)
                } else if (EdgeInfo.isRemoved(r, c)) {
                    out.append(ROCK);            // water that got removed
                } else {
                    // This case should never happen for valid input, but we keep it safe.
                    out.append(grid[r][c]);
                }
            }
            System.out.println(out);
        }
    }

    /* -------------------------------------------------------------------------
     *  Helper utilities
     * ------------------------------------------------------------------------- */

    private static boolean isWater(int r, int c) {
        return grid[r][c] == WATER;
    }

    private static boolean isInBounds(int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /* -------------------------------------------------------------------------
     *  Static helper classes – tiny containers to keep the main flow readable
     * ------------------------------------------------------------------------- */

    /** Holds the “edge‑connected” boolean matrix discovered in the first phase */
    private static final class EdgeInfo {
        private static boolean[][] marked;   // true = water reachable from border
        private static boolean[][] removed;  // true = water that will become '*'

        static void setMarked(boolean[][] m) { marked = m; }
        static boolean isMarked(int r, int c) { return marked != null && marked[r][c]; }

        static void markRemoved(int r, int c) {
            if (removed == null) {
                removed = new boolean[gridSize[0]][gridSize[1]];
            }
            removed[r][c] = true;
        }

        static boolean isRemoved(int r, int c) {
            return removed != null && removed[r][c];
        }

        static void setRemovedArea(int area) { removedArea = area; }
        static int getRemovedArea() { return removedArea; }
    }

    /** Holds dimensions for creating the removal matrix lazily */
    private static final class GridSize {
        static int getWidth() { return MainRefactor.grid[0].length; }
        static int getHeight() { return MainRefactor.grid.length; }
    }

    /* -------------------------------------------------------------------------
     *  Direction vectors (kept static for all grid algorithms)
     * ------------------------------------------------------------------------- */
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};
}

/*
 * Refactored solution for the “Keep K Open Areas” problem.
 *
 * The program reads a grid consisting of '.' (open) and '#' (blocked) cells,
 * keeps exactly K connected open components, and removes the smallest
 * possible number of additional open cells (replacing them with '*').
 *
 * The implementation is deliberately broken down into small, reusable
 * methods and classes to improve maintainability and readability.
 */

import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Entry point of the application.
 */
public final class Solver {

    /** Small helper to map 2‑D coordinates to a 1‑D DSU index. */
    private static int idx(int row, int col, int width) {
        return row * width + col;
    }

    /**
     * Reads all input data using a fast scanner and returns the number of rows,
     * columns, the required kept components, and the grid itself.
     */
    private static InputData readInput(FastScanner fs) {
        int rows = fs.nextInt();          // M
        int cols = fs.nextInt();          // N
        int keep = fs.nextInt();          // K

        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = fs.next().toCharArray();
        }
        return new InputData(rows, cols, keep, grid);
    }

    /** Container for parsed input values. */
    private static final class InputData {
        final int rows;
        final int cols;
        final int keep;          // K
        final char[][] grid;     // M × N character matrix

        InputData(int rows, int cols, int keep, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.keep = keep;
            this.grid = grid;
        }
    }

    /**
     * Union‑Find data structure with *union by size* and path compression.
     * It is used to identify connected components of open cells ('.').
     */
    private static final class UnionFind {
        /** Parent array – each entry points to its parent (or itself if root). */
        private final int[] parent;

        /** Size of the component for which this entry is a root. */
        private final int[] size;

        /** Number of elements currently stored. */
        private final int capacity;

        UnionFind(int capacity) {
            this.capacity = capacity;
            this.parent = new int[capacity];
            this.size = new int[capacity];
            reset();
        }

        /** Resets every element to be its own singleton component. */
        private void reset() {
            for (int i = 0; i < capacity; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        /** Returns the root of the set containing {@code x}. */
        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]); // Path compression
            }
            return parent[x];
        }

        /**
         * Merges the sets of {@code a} and {@code b} if they are different.
         * The larger set becomes the parent of the smaller one (union by size).
         */
        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) {
                return;
            }
            // Ensure rootA is the larger set
            if (size[rootA] < size[rootB]) {
                int tmp = rootA;
                rootA = rootB;
                rootB = tmp;
            }
            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        /** Returns the size of the component whose root is {@code x}. */
        int componentSize(int x) {
            return size[find(x)];
        }
    }

    /**
     * Determines whether a given cell lies on the border of the grid.
     */
    private static boolean isBorder(int row, int col, int rows, int cols) {
        return row == 0 || row == rows - 1 || col == 0 || col == cols - 1;
    }

    /**
     * Processes the grid, decides which open components must be removed,
     * and produces the required output.
     */
    private static void solveAndPrint(InputData data, PrintWriter out) {
        int rows = data.rows;
        int cols = data.cols;
        char[][] grid = data.grid;
        int keep = data.keep;

        // -----------------------------------------------------------------
        // 1️⃣ Build Union‑Find of all connected '.' cells.
        // -----------------------------------------------------------------
        UnionFind uf = new UnionFind(rows * cols);

        // Directions: up and left (right/down are handled by symmetry)
        final int[] dr = {-1, 0};
        final int[] dc = {0, -1};

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '.') {
                    continue;
                }
                for (int d = 0; d < dr.length; d++) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];
                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                        uf.union(idx(r, c, cols), idx(nr, nc, cols));
                    }
                }
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣ Gather component statistics (size, whether it touches a border).
        // -----------------------------------------------------------------
        Map<Integer, Integer> componentSize = new HashMap<>();
        Set<Integer> borderComponents = new HashSet<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '.') {
                    continue;
                }
                int root = uf.find(idx(r, c, cols));
                componentSize.merge(root, 1, Integer::sum);

                if (isBorder(r, c, rows, cols)) {
                    borderComponents.add(root);
                }
            }
        }

        // -----------------------------------------------------------------
        // 3️⃣ Decide which components to delete.
        //     All non‑border components are candidates; we remove the
        //     smallest ones until only `keep` components remain.
        // -----------------------------------------------------------------
        int totalComponents = componentSize.size();
        int toDelete = totalComponents - keep;
        if (toDelete <= 0) {
            // Nothing to delete – just output the grid unchanged.
            out.println(0);
            printGrid(grid, out);
            return;
        }

        // Convert map entries to a list for easy sorting.
        List<ComponentInfo> components = componentSize.entrySet()
                .stream()
                .map(e -> new ComponentInfo(e.getKey(), e.getValue(), borderComponents.contains(e.getKey())))
                .sorted(Comparator.comparingInt(a -> a.size))
                .collect(Collectors.toList());

        // Mark components that have to be removed.
        Set<Integer> toRemove = new HashSet<>();
        for (int i = 0; i < toDelete; i++) {
            toRemove.add(components.get(i).root);
        }

        // -----------------------------------------------------------------
        // 4️⃣ Transform the grid: replace cells belonging to removed
        //     components with '*', count how many we changed.
        // -----------------------------------------------------------------
        int removedCount = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && toRemove.contains(uf.find(idx(r, c, cols)))) {
                    grid[r][c] = '*';
                    removedCount++;
                }
            }
        }

        // -----------------------------------------------------------------
        // 5️⃣ Emit the result.
        // -----------------------------------------------------------------
        out.println(removedCount);
        printGrid(grid, out);
    }

    /** Simple DTO to carry component meta‑information. */
    private static final class ComponentInfo {
        final int root;   // DSU root identifier
        final int size;   // size of the component
        final boolean isBorder; // does the component touch the outermost row/col?

        ComponentInfo(int root, int size, boolean isBorder) {
            this.root = root;
            this.size = size;
            this.isBorder = isBorder;
        }
    }

    /** Helper that writes a character grid to the output stream. */
    private static void printGrid(char[][] grid, PrintWriter out) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }

    /** Fast scanner based on BufferedReader + StringTokenizer. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream source) {
            this.br = new BufferedReader(new InputStreamReader(source));
        }

        /** Returns the next token, reading a new line if necessary. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null; // EOF
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    /** -----------------------------------------------------------------
     *  Program entry point.
     *  ----------------------------------------------------------------- */
    public static void main(String[] args) {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        InputData data = readInput(fs);
        solveAndPrint(data, out);

        out.close(); // Flushes the underlying stream automatically.
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Solves a labyrinth‑type problem:
 * <p>
 *   • Reads a grid of '.' (open) and other characters.
 *   • Finds all regions of '.' that touch the outer border.
 *   • Sorts those regions by their size (ascending).
 *   • Blocks (turns into '*') the smallest {@code (regions‑k)} regions.
 *   • Prints the number of cells that were blocked and the resulting grid.
 * </p>
 */
public class LabyrinthSolver {

    /** character that represents an open cell */
    private static final char OPEN = '.';
    /** character used to block a cell */
    private static final char BLOCKED = '*';

    /** four orthogonal movement vectors */
    private static final int[][] DIRECTIONS = {
            {1, 0}, {0, -1}, {-1, 0}, {0, 1}
    };

    private final char[][] grid;          // original board
    private final boolean[][] visited;    //visited flag for DFS
    private final int rows;
    private final int cols;
    private final int k;                  // number of regions that must stay open

    /**
     * Simple container for a connected region of open cells.
     */
    private static final class Component {
        final Position start;   // any position in the region (used for printing)
        final int size;        // number of cells in the region

        Component(Position start, int size) {
            this.start = start;
            this.size = size;
        }
    }

    /**
     * Position inside the grid.
     */
    private static final class Position {
        final int x;
        final int y;

        Position(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Constructs the solver.
     *
     * @param grid the board to process
     * @param k    the number of regions that must remain unblocked
     */
    public LabyrinthSolver(char[][] grid, int k) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.k = k;
        this.visited = new boolean[rows][cols];
    }

    /** Entry point – reads input, solves the problem and prints the answer. */
    public static void main(String[] args) throws IOException {
        try (InputStream in = System.in) {
            Scanner scanner = new Scanner(in);
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            int k = scanner.nextInt();

            char[][] board = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = scanner.next();
                board[i] = line.toCharArray();
            }

            new LabyrinthSolver(board, k).solve();
        }
    }

    /** Core algorithm – finds border‑connected components, blocks some of them,
     *  and prints the required output. */
    public void solve() {
        List<Component> borderComponents = findBorderComponents();

        // keep only the k largest components, block the rest
        int toBlock = Math.max(0, borderComponents.size() - k);
        if (toBlock > 0) {
            blockComponents(borderComponents.subList(0, toBlock));
        } else {
            // nothing to block – just print the unchanged grid
            System.out.println(0);
            printGrid(grid);
        }
    }

    /** Returns all regions of '.' that are reachable from the outer border. */
    private List<Component> findBorderComponents() {
        List<Component> components = new ArrayList<>();

        // start a DFS from every unvisited border cell that is open
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isBorder(i, j) && grid[i][j] == OPEN && !visited[i][j]) {
                    int size = explore(i, j);
                    components.add(new Component(new Position(i, j), size));
                }
            }
        }
        return components;
    }

    /** Depth‑first search that marks all reachable '.' cells and returns the size. */
    private int explore(int x, int y) {
        if (!inBounds(x, y) || grid[x][y] != OPEN || visited[x][y]) {
            return 0;
        }
        visited[x][y] = true;
        int count = 1;

        for (int[] dir : DIRECTIONS) {
            count += explore(x + dir[0], y + dir[1]);
        }
        return count;
    }

    /** Blocks (turns into '*') the cells of the supplied components in a copy of the grid,
     *  prints the number of blocked cells and the resulting board. */
    private void blockComponents(Collection<Component> componentsToBlock) {
        // mutable copy of the board
        char[][] copy = deepCopy(grid);
        int modifications = 0;

        for (Component comp : componentsToBlock) {
            markBlocked(copy, comp.start.x, comp.start.y);
        }

        // count how many cells were changed
        modifications = countBlocked(copy);

        System.out.println(modifications);
        printGrid(copy);
    }

    /** Marks a whole region with '*' starting from (x,y) in the supplied board. */
    private void markBlocked(char[][] board, int x, int y) {
        if (!inBounds(x, y) || board[x][y] != OPEN) {
            return;
        }
        board[x][y] = BLOCKED;
        for (int[] dir : DIRECTIONS) {
            markBlocked(board, x + dir[0], y + dir[1]);
        }
    }

    /** Returns the number of cells that are currently marked as '*'. */
    private int countBlocked(char[][] board) {
        int cnt = 0;
        for (char[] row : board) {
            for (char ch : row) {
                if (ch == BLOCKED) cnt++;
            }
        }
        return cnt;
    }

    /** Deep‑copies a 2‑D char array. */
    private static char[][] deepCopy(char[][] src) {
        return Arrays.stream(src).map(String::new).map(String::toCharArray).toArray(char[][]::new);
    }

    /** Simple helper to print a char grid to standard output. */
    private static void printGrid(char[][] board) {
        for (char[] row : board) {
            System.out.println(new String(row));
        }
    }

    /** Checks whether (x,y) lies on the outer border of the grid. */
    private boolean isBorder(int x, int y) {
        return x == 0 || x == rows - 1 || y == 0 || y == cols - 1;
    }

    /** Checks whether (x,y) is inside the grid limits. */
    private boolean inBounds(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.PriorityQueue;
import java.util.Scanner;

/**
 * Refactored implementation of the lake‑removal algorithm.
 * Reads a grid, marks ocean‑connected cells, discovers interior lakes,
 * removes the smallest lakes until only a given number remain,
 * and prints the number of removed cells together with the final grid.
 */
public class LakeRemoval {

    /** Directions used for neighboring cell checks (up, down, right, left). */
    private static final int[][] DIRECTIONS = {
            {-1, 0},
            {1, 0},
            {0, 1},
            {0, -1}
    };

    /**
     * Simple data holder for a discovered lake.
     * Implements {@link Comparable} so that a {@link PriorityQueue} orders
     * lakes by their size (smallest first).
     */
    private static final class Lake implements Comparable<Lake> {
        final int row;   // starting row of the lake (any cell is fine)
        final int col;   // starting column of the lake
        final int size;  // number of cells belonging to the lake

        Lake(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        /** Ascending order – the queue returns the smallest lake first. */
        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /** Marks all water ('.') cells that are connected to the border as ocean ('O'). */
    private static void markOcean(char[][] grid, int i, int j) {
        if (!isInBounds(grid, i, j) || grid[i][j] != '.') {
            return;
        }
        grid[i][j] = 'O';
        for (int[] dir : DIRECTIONS) {
            markOcean(grid, i + dir[0], j + dir[1]);
        }
    }

    /** Explores a lake using an explicit stack (iterative DFS) and marks it with 'L'. */
    private static int exploreLake(char[][] grid, int startRow, int startCol) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startRow, startCol});
        grid[startRow][startCol] = 'L';
        int count = 0;

        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int r = cur[0];
            int c = cur[1];
            count++;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isInBounds(grid, nr, nc) && grid[nr][nc] == '.') {
                    grid[nr][nc] = 'L';
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return count;
    }

    /** Flood‑fills a lake (identified by its starting coordinate) with '*'. */
    private static void fillLake(char[][] grid, int startRow, int startCol) {
        if (grid[startRow][startCol] != 'L') {
            return;
        }
        Deque<int[]> queue = new ArrayDeque<>();
        queue.push(new int[]{startRow, startCol});

        while (!queue.isEmpty()) {
            int[] cur = queue.pop();
            int r = cur[0];
            int c = cur[1];
            grid[r][c] = '*';

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isInBounds(grid, nr, nc) && grid[nr][nc] == 'L') {
                    queue.push(new int[]{nr, nc});
                }
            }
        }
    }

    /** Utility to test whether a cell lies inside the grid. */
    private static boolean isInBounds(char[][] grid, int i, int j) {
        return i >= 0 && i < grid.length && j >= 0 && j < grid[0].length;
    }

    /** Core processing routine – reads input, performs transformations, prints results. */
    private static void solve() {
        try (Scanner sc = new Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();
            int maxLakes = sc.nextInt();

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = sc.next().toCharArray();
            }

            // -----------------------------------------------------------------
            // 1️⃣  Mark ocean cells reachable from any border position.
            // -----------------------------------------------------------------
            for (int i = 0; i < rows; i++) {
                markOcean(grid, i, 0);
                markOcean(grid, i, cols - 1);
            }
            for (int j = 0; j < cols; j++) {
                markOcean(grid, 0, j);
                markOcean(grid, rows - 1, j);
            }

            // -----------------------------------------------------------------
            // 2️⃣  Discover all interior lakes and store them in a min‑heap.
            // -----------------------------------------------------------------
            PriorityQueue<Lake> lakeQueue = new PriorityQueue<>();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        int lakeSize = exploreLake(grid, i, j);
                        lakeQueue.offer(new Lake(i, j, lakeSize));
                    }
                }
            }

            // -----------------------------------------------------------------
            // 3️⃣  Remove the smallest lakes until at most `maxLakes` remain.
            // -----------------------------------------------------------------
            int removedCells = 0;
            while (lakeQueue.size() > maxLakes) {
                Lake smallest = lakeQueue.poll();
                removedCells += smallest.size;
                fillLake(grid, smallest.row, smallest.col);
            }

            // -----------------------------------------------------------------
            // 4️⃣  Normalise symbols for clean output.
            // -----------------------------------------------------------------
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'L' || grid[i][j] == 'O') {
                        grid[i][j] = '.';
                    }
                }
            }

            // -----------------------------------------------------------------
            // 5️⃣  Output the result.
            // -----------------------------------------------------------------
            System.out.println(removedCells);
            for (char[] row : grid) {
                System.out.println(new String(row));
            }
        }
    }

    /** Entry point – delegates all work to {@link #solve()}. */
    public static void main(String[] args) {
        solve();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solution for problem "723D - Lakes in Berland".
 *
 * <p>
 * The program reads a grid that contains cells:
 * <ul>
 *   <li>'.' – water</li>
 *   <li>'*' – land</li>
 * </ul>
 * A *lake* is a maximal connected set of water cells that does **not** touch the border.
 * We have to leave exactly {@code k} lakes untouched and fill all other lakes.
 * The cost of filling a lake is its area (number of cells).<br>
 * The task is to output the minimal total cost and the final grid.
 * </p>
 */
public class Task723D {

    /** Directions for neighbour search (up, right, down, left). */
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    /** Sentinel value larger than any possible lake size. */
    private static final int INF = Integer.MAX_VALUE / 2;

    /** Buffered input and PrintWriter for fast I/O. */
    private BufferedReader in;
    private PrintWriter out;

    /** Simple holder for a lake’s identifier and its size. */
    private static final class Lake {
        final int id;   // identifier used in the marking matrix
        final int size; // number of cells

        Lake(int id, int size) {
            this.id = id;
            this.size = size;
        }
    }

    /** Entry point */
    public static void main(String[] args) throws IOException {
        new Task723D().run();
    }

    /** Core logic – reading, processing, and printing the answer. */
    private void run() throws IOException {
        openStreams();

        int n = nextInt();      // rows
        int m = nextInt();      // columns
        int requiredLakes = nextInt(); // k

        char[][] grid = readGrid(n);
        int[][] mark = new int[n][m];   // marker for each cell (0 = unvisited)

        List<Lake> lakes = discoverLakes(grid, mark, n, m);
        long totalFilled = fillUnwantedLakes(grid, mark, lakes, requiredLakes);

        printResult(totalFilled, grid);
        close();
    }

    /** Reads {@code n} lines of length {@code m} from {@link #in}. */
    private char[][] readGrid(int n) throws IOException {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = in.readLine();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /** Finds all lakes, discarding those that touch the border. */
    private List<Lake> discoverLakes(char[][] grid, int[][] mark, int n, int m) {
        List<Lake> lakes = new ArrayList<>();
        int lakeId = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != '.' || mark[i][j] != 0) {
                    continue;
                }

                lakeId++;
                boolean touchesBorder = false;
                int size = dfsExplore(grid, mark, i, j, n, m, lakeId, touchesBorder);

                // If the component does **not** touch the border, it is a lake.
                if (!touchesBorder) {
                    lakes.add(new Lake(lakeId, size));
                }
            }
        }
        return lakes;
    }

    /**
     * Depth‑first search that marks all cells of the current component with {@code lakeId}
     * and returns its size. The {@code touchesBorder} flag is set to {@code true}
     * if any cell lies on the border.
     */
    private int dfsExplore(char[][] grid, int[][] mark, int x, int y, int n, int m,
                           int lakeId, boolean[] touchesBorder) {
        if (x < 0 || x >= n || y < 0 || y >= m) {
            return 0;
        }
        if (grid[x][y] != '.' || mark[x][y] != 0) {
            return 0;
        }

        mark[x][y] = lakeId;
        if (x == 0 || x == n - 1 || y == 0 || y == m - 1) {
            touchesBorder[0] = true;
        }

        int size = 1;
        for (int dir = 0; dir < 4; dir++) {
            int nx = x + DX[dir];
            int ny = y + DY[dir];
            size += dfsExplore(grid, mark, nx, ny, n, m, lakeId, touchesBorder);
        }
        return size;
    }

    /** Removes the smallest lakes until exactly {@code requiredLakes} remain. */
    private long fillUnwantedLakes(char[][] grid, int[][] mark,
                                   List<Lake> lakes, int requiredLakes) {
        // Sort lakes by size (ascending) – the smallest are removed first.
        Collections.sort(lakes, (a, b) -> Integer.compare(a.size, b.size));

        long total = 0;
        int kept = 0;
        for (Lake lake : lakes) {
            if (kept >= requiredLakes) {
                // This lake must be filled.
                total += lake.size;
                fillRegion(grid, mark, lake.id);
            } else {
                kept++;
            }
        }
        return total;
    }

    /** Fills (marks as land) all cells belonging to a lake identified by {@code lakeId}. */
    private void fillRegion(char[][] grid, int[][] mark, int lakeId) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (mark[i][j] == lakeId) {
                    grid[i][j] = '*';
                }
            }
        }
    }

    /** Prints the minimal total area and the resulting grid. */
    private void printResult(long totalArea, char[][] grid) {
        out.println(totalArea);
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }

    /* ---------- I/O helpers ---------- */

    private void openStreams() {
        in = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
    }

    private void close() {
        out.flush();
    }

    private String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = in.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Token generator used by the I/O helpers. */
    private StringTokenizer st;
}

import java.io.*;
import java.util.*;

public class Main {

    /* ------------------------------------------------------------
     *  Constants
     * ------------------------------------------------------------ */
    private static final int EMPTY = 0;               // unvisited cell
    private static final int INF   = Integer.MAX_VALUE; // not used directly, kept for compatibility

    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    /* ------------------------------------------------------------
     *  Data holder for a lake
     * ------------------------------------------------------------ */
    private static final class Lake {
        final int id;   // unique identifier of the lake
        int size;       // mutable – used to mark a lake as “removed”

        Lake(int id, int size) {
            this.id = id;
            this.size = size;
        }
    }

    /* ------------------------------------------------------------
     *  Entry point
     * ------------------------------------------------------------ */
    public static void main(String[] args) throws Exception {
        try (Scanner sc = new Scanner(new BufferedReader(new InputStreamReader(System.in)))) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();
            int keep = sc.nextInt();                 // number of lakes we want to keep

            char[][] map = readGrid(sc, rows, cols);
            int[][] componentId = new int[rows][cols];
            List<Lake> lakes = discoverLakes(map, componentId, rows, cols);

            // Determine which lakes to delete and compute total area removed
            Set<Integer> removedIds = new HashSet<>();
            long totalRemoved = removeSmallestLakes(lakes, keep, removedIds);

            System.out.println(totalRemoved);
            fillRemovedLakes(map, componentId, removedIds);
            printMap(map);
        }
    }

    /* ------------------------------------------------------------
     *  Input handling
     * ------------------------------------------------------------ */
    private static char[][] readGrid(Scanner sc, int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; ++i) {
            String token = sc.next();               // each row is a single token of length m
            for (int j = 0; j < m; ++j) {
                grid[i][j] = token.charAt(j);
            }
        }
        return grid;
    }

    /* ------------------------------------------------------------
     *  Lake discovery
     * ------------------------------------------------------------ */
    /** Finds every interior lake (connected '*' component not touching the border). */
    private static List<Lake> discoverLakes(char[][] grid, int[][] id, int n, int m) {
        List<Lake> result = new ArrayList<>();
        int currentId = 1;

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (grid[i][j] == '*' && id[i][j] == EMPTY) {
                    boolean touchesBorder = isBorder(i, j, n, m);
                    int size = dfsExplore(grid, id, i, j, currentId, touchesBorder, n, m);
                    if (!touchesBorder) {
                        result.add(new Lake(currentId, size));
                    }
                    ++currentId;
                }
            }
        }
        return result;
    }

    private static boolean isBorder(int x, int y, int n, int m) {
        return x == 0 || y == 0 || x == n - 1 || y == m - 1;
    }

    /** Depth‑first search that marks a whole lake with a given id. Returns its size. */
    private static int dfsExplore(char[][] grid, int[][] id, int x, int y,
                                 int lakeId, boolean touchesBorder,
                                 int n, int m) {
        if (!inside(x, y, n, m) || grid[x][y] != '*' || id[x][y] != EMPTY) {
            return 0;
        }
        id[x][y] = lakeId;
        int size = 1;
        for (int d = 0; d < 4; ++d) {
            size += dfsExplore(grid, id, x + DX[d], y + DY[d], lakeId, touchesBorder, n, m);
        }
        return size;
    }

    private static boolean inside(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /* ------------------------------------------------------------
     *  Removal logic
     * ------------------------------------------------------------ */
    /**
     * Removes the smallest lakes until exactly {@code keep} lakes remain.
     * Identifiers of the removed lakes are stored in {@code removedIds}
     * and the total area of those lakes is returned.
     */
    private static long removeSmallestLakes(List<Lake> lakes,
                                            int keep,
                                            Set<Integer> removedIds) {
        long removedTotal = 0;
        lakes.sort(Comparator.comparingInt(l -> l.size));   // sort by size ascending

        int toRemove = lakes.size() - keep;
        for (int i = 0; i < toRemove; ++i) {
            Lake lake = lakes.get(i);
            removedTotal += lake.size;
            removedIds.add(lake.id);
            lake.size = 0;                                    // mark as removed (optional)
        }
        return removedTotal;
    }

    /** Fills every cell belonging to a removed lake with '*'. */
    private static void fillRemovedLakes(char[][] grid, int[][] id, Set<Integer> removedIds) {
        for (int i = 0; i < grid.length; ++i) {
            for (int j = 0; j < grid[i].length; ++j) {
                if (id[i][j] != EMPTY && removedIds.contains(id[i][j])) {
                    grid[i][j] = '*';
                }
            }
        }
    }

    /* ------------------------------------------------------------
     *  Output
     * ------------------------------------------------------------ */
    private static void printMap(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                System.out.print(cell);
            }
            System.out.println();
        }
    }
}

/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads a grid, builds disjoint‑set unions for equal adjacent cells,
 * removes the largest interior components until only {@code k} remain,
 * marks removed cells with {@code '*'} and prints the result together with the
 * count of marked cells.
 * </p>
 */
import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Simple fast input scanner that implements {@link AutoCloseable}.
 */
final class FastScanner implements AutoCloseable {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    FastScanner(InputStream source) {
        this.reader = new BufferedReader(new InputStreamReader(source));
    }

    private void ensureTokenizer() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
    }

    String next() throws IOException {
        ensureTokenizer();
        return tokenizer.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    @Override
    public void close() throws IOException {
        reader.close();
    }
}

/**
 * Disjoint Set Union (Union‑Find) data structure.
 */
final class DisjointSetUnion {
    private final int[] parent; // negative size for roots
    private final int[] size;   // not strictly necessary but kept for clarity

    DisjointSetUnion(int elements) {
        parent = new int[elements];
        size = new int[elements];
        Arrays.fill(parent, -1);
        Arrays.fill(size, 1);
    }

    /** Find the representative of {@code x} with path compression. */
    int find(int x) {
        if (parent[x] < 0) {
            return x;
        }
        parent[x] = find(parent[x]);
        return parent[x];
    }

    /** Union the sets containing {@code a} and {@code b}. Returns {@code true} if a union happened. */
    boolean union(int a, int b) {
        int pa = find(a);
        int pb = find(b);
        if (pa == pb) {
            return false;
        }
        // union by size (larger size becomes the new root)
        if (size[pb] > size[pa]) {
            int tmp = pa;
            pa = pb;
            pb = tmp;
        }
        parent[pa] += parent[pb];
        parent[pb] = pa;
        size[pa] += size[pb];
        size[pb] = 0;
        return true;
    }

    /** Size of the set that contains {@code x}. */
    int getSize(int x) {
        return -parent[find(x)];
    }

    /** Returns {@code true} if {@code x} is a root element. */
    boolean isRoot(int x) {
        return parent[x] < 0;
    }
}

/**
 * Main class that orchestrates the algorithm.
 */
public class Main {

    /** Four‑direction vectors for neighbour traversal. */
    private static final int[][] DIRS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public static void main(String[] args) throws Exception {
        try (FastScanner in = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = in.nextInt();          // n
            int cols = in.nextInt();          // m
            int keep = in.nextInt();          // k

            char[][] grid = readGrid(in, rows, cols);
            int totalCells = rows * cols;

            // Mapping each cell to a component id (initially unique)
            DisjointSetUnion dsu = new DisjointSetUnion(totalCells);
            int[][] componentIndex = new int[rows][cols];
            int currentId = 0;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    componentIndex[i][j] = currentId++;
                }
            }

            // Union adjacent cells that share the same character
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    for (int[] d : DIRS) {
                        int ni = i + d[0];
                        int nj = j + d[1];
                        if (ni >= 0 && ni < rows && nj >= 0 && nj < cols
                                && grid[i][j] == grid[ni][nj]) {
                            dsu.union(componentIndex[i][j], componentIndex[ni][nj]);
                        }
                    }
                }
            }

            // Build a map from component id to all its cell positions
            Map<Integer, List<Position>> componentPositions = new HashMap<>();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int root = dsu.find(componentIndex[i][j]);
                    componentPositions.computeIfAbsent(root, k -> new ArrayList<>())
                                    .add(new Position(i, j));
                }
            }

            // Components that touch the border must be kept (ignored from removal)
            Set<Integer> boundaryComponents = identifyBoundaryComponents(
                    rows, cols, componentIndex, dsu);

            // Interior components that are not on the border
            List<Integer> interiorComponentIds = componentPositions.keySet().stream()
                    .filter(id -> !boundaryComponents.contains(id))
                    .sorted(Comparator.comparingInt(dsu::getSize).reversed())
                    .collect(Collectors.toList());

            // Convert all but the first {@code keep} interior components to '*'
            int markedCount = 0;
            for (int i = keep; i < interiorComponentIds.size(); i++) {
                int compId = interiorComponentIds.get(i);
                List<Position> positions = componentPositions.get(compId);
                for (Position pos : positions) {
                    grid[pos.row][pos.col] = '*';
                }
                markedCount += positions.size();
            }

            // Output the result
            out.println(markedCount);
            for (char[] row : grid) {
                out.println(new String(row));
            }
        }
    }

    /** Reads the grid from the scanner. */
    private static char[][] readGrid(FastScanner in, int rows, int cols) throws IOException {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = in.next();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /** Collects component ids that intersect the outer border of the grid. */
    private static Set<Integer> identifyBoundaryComponents(int rows, int cols,
                                                            int[][] componentIndex,
                                                            DisjointSetUnion dsu) {
        Set<Integer> boundary = new HashSet<>();

        // top & bottom rows
        for (int j = 0; j < cols; j++) {
            boundary.add(dsu.find(componentIndex[0][j]));          // top
            boundary.add(dsu.find(componentIndex[rows - 1][j]));   // bottom
        }
        // left & right columns
        for (int i = 0; i < rows; i++) {
            boundary.add(dsu.find(componentIndex[i][0]));          // left
            boundary.add(dsu.find(componentIndex[i][cols - 1]));   // right
        }
        return boundary;
    }

    /** Simple immutable holder for a grid coordinate. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.Queue;

/**
 * Refactored solution for the lake‑removal problem.
 * <p>
 * The program reads a rectangular grid composed of '.' (land) and '*' (water).
 * It counts how many connected land components (lakes) are completely surrounded
 * by water and removes the smallest ones until at most {@code k} lakes remain.
 * The total area of the removed lakes is printed, followed by the final grid.
 * </p>
 */
public class ProblemD {

    /* ---------- Constants ---------- */
    private static final char LAND = '.';
    private static final char WATER = '*';

    /* ---------- Global state ---------- */
    private static int rows;
    private static int cols;
    private static int lakesToKeep;

    private static char[][] grid;
    private static boolean[][] visited;

    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /* ---------- Entry point ---------- */
    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] header = br.readLine().split(" ");
            rows = Integer.parseInt(header[0]);
            cols = Integer.parseInt(header[1]);
            lakesToKeep = Integer.parseInt(header[2]);

            grid = new char[rows][cols];
            visited = new boolean[rows][cols];

            for (int r = 0; r < rows; r++) {
                grid[r] = br.readLine().toCharArray();
            }

            markBorderLands();                     // visit lakes touching the border
            PriorityQueue<Lake> interiorLakes = collectInteriorLakes();

            long removedArea = 0;
            while (interiorLakes.size() > lakesToKeep) {
                Lake lake = interiorLakes.poll();
                fillLake(lake.row, lake.col);
                removedArea += lake.area;
            }

            System.out.println(removedArea);
            printGrid();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /* ---------- Helper methods ---------- */

    /** Marks all land cells that are reachable from the grid border. */
    private static void markBorderLands() {
        for (int c = 0; c < cols; c++) {
            if (!visited[0][c] && grid[0][c] == LAND) explore(0, c);
            if (!visited[rows - 1][c] && grid[rows - 1][c] == LAND) explore(rows - 1, c);
        }
        for (int r = 0; r < rows; r++) {
            if (!visited[r][0] && grid[r][0] == LAND) explore(r, 0);
            if (!visited[r][cols - 1] && grid[r][cols - 1] == LAND) explore(r, cols - 1);
        }
    }

    /** Depth‑first exploration used while marking border lands. */
    private static void explore(int r, int c) {
        visited[r][c] = true;
        if (grid[r][c] != LAND) {
            return;
        }
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isInBounds(nr, nc) && !visited[nr][nc] && grid[nr][nc] == LAND) {
                explore(nr, nc);
            }
        }
    }

    /** Collects interior lakes (those not touching the border) into a priority queue. */
    private static PriorityQueue<Lake> collectInteriorLakes() {
        PriorityQueue<Lake> queue = new PriorityQueue<>(Comparator.comparingInt(l -> l.area));
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (!visited[r][c] && grid[r][c] == LAND) {
                    int area = exploreArea(r, c);
                    queue.add(new Lake(r, c, area));
                }
            }
        }
        return queue;
    }

    /** Calculates the area of a lake starting at (r,c) using an iterative BFS. */
    private static int exploreArea(int startR, int startC) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startR, startC});
        visited[startR][startC] = true;
        int area = 0;

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int r = cell[0];
            int c = cell[1];
            area++;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isInBounds(nr, nc) && !visited[nr][nc] && grid[nr][nc] == LAND) {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return area;
    }

    /** Fills a lake (converts its '.' cells to '*' ) starting at (r,c). */
    private static void fillLake(int startR, int startC) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startR, startC});

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int r = cell[0];
            int c = cell[1];
            grid[r][c] = WATER;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isInBounds(nr, nc) && grid[nr][nc] == LAND) {
                    queue.add(new int[]{nr, nc});
                }
            }
        }
    }

    /** Utility to check whether a cell is inside the grid. */
    private static boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Prints the final grid to standard output. */
    private static void printGrid() {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }

    /** Simple data holder for a lake. */
    private static final class Lake {
        final int row;
        final int col;
        final int area;

        Lake(int row, int col, int area) {
            this.row = row;
            this.col = col;
            this.area = area;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “Lake Counting” problem (originally D375).
 * The refactor focuses on readability, separation of concerns and proper naming.
 */
public class D375 {

    /** Directions used for flood‑fill (up, down, left, right). */
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    /** Holds information about a discovered lake. */
    private static final class Lake {
        final int id;
        final List<Point> cells = new ArrayList<>();
        boolean valid = true;          // true if the lake does NOT touch the border
        int size;                       // number of cells in the lake

        Lake(int id) {
            this.id = id;
        }
    }

    /** Simple container for a cell coordinate. */
    private static final class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    public static void main(String[] args) throws IOException {
        /* ---------- 1️⃣  Input ------------------------------------------------- */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());
            int maxValid = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = br.readLine();
                System.arraycopy(line.toCharArray(), 0, grid[r], 0, cols);
            }

            /* ---------- 2️⃣  Discover lakes ----------------------------------- */
            List<Lake> lakes = discoverLakes(grid, rows, cols);

            /* ---------- 3️⃣  Fill lakes until only `maxValid` stay ----------- */
            fillUnwantedLakes(lakes, maxValid, grid);

            /* ---------- 4️⃣  Output ------------------------------------------- */
            int filled = countFilledCells(lakes, maxValid);
            System.out.println(filled);
            for (char[] row : grid) {
                System.out.println(new String(row));
            }
        }
    }

    /** Executes a BFS from every unvisited land cell ('.') and builds Lake objects. */
    private static List<Lake> discoverLakes(char[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        List<Lake> lakes = new ArrayList<>();
        int lakeId = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*' || visited[r][c]) continue;

                Lake lake = new Lake(lakeId++);
                bfs(grid, visited, r, c, lake, rows, cols);
                lakes.add(lake);
            }
        }
        return lakes;
    }

    /** Breadth‑first search that populates a Lake instance. */
    private static void bfs(char[][] grid, boolean[][] visited,
                            int startR, int startC, Lake lake,
                            int rows, int cols) {
        Queue<Point> q = new ArrayDeque<>();
        q.add(new Point(startR, startC));
        visited[startR][startC] = true;
        lake.cells.add(new Point(startR, startC));
        lake.size = 1;

        while (!q.isEmpty()) {
            Point cur = q.poll();
            for (int[] d : DIRS) {
                int nr = cur.r + d[0];
                int nc = cur.c + d[1];
                if (!inBounds(nr, nc, rows, cols)) {
                    lake.valid = false;          // touches the border → invalid
                    continue;
                }
                if (grid[nr][nc] == '*' || visited[nr][nc]) continue;

                visited[nr][nc] = true;
                lake.cells.add(new Point(nr, nc));
                lake.size++;
                q.add(new Point(nr, nc));
            }
        }
    }

    /** Marks cells of the selected lakes with '*' in the grid. */
    private static void fillUnwantedLakes(List<Lake> lakes, int keepValid,
                                          char[][] grid) {
        // Collect only the lakes that are completely surrounded (i.e., valid)
        List<Lake> validLakes = lakes.stream()
                                     .filter(l -> l.valid)
                                     .sorted(Comparator.comparingInt(l -> l.size))
                                     .toList();

        int toFill = Math.max(0, validLakes.size() - keepValid);
        for (int i = 0; i < toFill; i++) {
            Lake lake = validLakes.get(i);
            for (Point p : lake.cells) {
                grid[p.r][p.c] = '*';
            }
        }
    }

    /** Counts how many cells belong to lakes that will be filled. */
    private static int countFilledCells(List<Lake> lakes, int keepValid) {
        List<Lake> validLakes = lakes.stream()
                                     .filter(l -> l.valid)
                                     .sorted(Comparator.comparingInt(l -> l.size))
                                     .toList();

        int filled = 0;
        int lakesToKeep = Math.max(0, validLakes.size() - keepValid);
        for (int i = 0; i < lakesToKeep; i++) {
            filled += validLakes.get(i).cells.size();
        }
        return filled;
    }

    /** Utility – checks whether a coordinate lies inside the grid. */
    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {

    public static void main(String[] args) {
        InputStream in = System.in;
        PrintWriter out = new PrintWriter(System.out);
        solve(in, out);
        out.close();
    }

    private static void solve(InputStream in, PrintWriter out) {
        InputReader reader = new InputReader(in);
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        int keep = reader.nextInt();

        String[] lines = new String[rows];
        for (int i = 0; i < rows; i++) {
            lines[i] = reader.next();
        }

        LakeProcessor processor = new LakeProcessor(rows, cols, keep, lines);
        int removedCells = processor.process();
        out.println(removedCells);
        processor.printResult();
    }

    /** Simple reader that supplies tokens from stdin. */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }
    }

    /** Encapsulates all processing related to lakes. */
    private static class LakeProcessor {
        private final int rows;
        private final int cols;
        private final int keep;
        private final char[][] grid;
        private final List<Lake> lakes = new ArrayList<>();
        private final boolean[][] visited = new boolean[1000][1000]; // adjust if needed

        LakeProcessor(int rows, int cols, int keep, String[] lines) {
            this.rows = rows;
            this.cols = cols;
            this.keep = keep;
            this.grid = toCharGrid(lines);
        }

        /** Convert the immutable String array into a mutable char grid. */
        private static char[][] toCharGrid(String[] lines) {
            char[][] g = new char[lines.length][];
            for (int i = 0; i < lines.length; i++) {
                g[i] = lines[i].toCharArray();
            }
            return g;
        }

        /** Public entry point – returns total number of water cells removed. */
        int process() {
            discoverLakes();
            lakes.sort(Comparator.comparingInt(l -> l.size));

            int deleted = 0;
            // keep the largest `keep` lakes, delete all smaller ones
            for (int i = 0; i < lakes.size() - keep; i++) {
                deleted += lakes.get(i).size;
                floodFill(lakes.get(i));
            }
            return deleted;
        }

        /** Perform DFS/BFS to find contiguous water regions that do NOT touch the border. */
        private void discoverLakes() {
            Arrays.fill(visited, false);
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        Lake lake = exploreLake(i, j);
                        if (lake != null) {
                            lakes.add(lake);
                        }
                    }
                }
            }
        }

        /** Returns the lake if it is fully enclosed, otherwise null. */
        private Lake exploreLake(int sr, int sc) {
            Queue<int[]> q = new ArrayDeque<>();
            q.add(new int[]{sr, sc});
            visited[sr][sc] = true;

            List<int[]> cells = new ArrayList<>();
            boolean touchesBorder = false;
            int size = 0;

            while (!q.isEmpty()) {
                int[] cur = q.poll();
                int r = cur[0], c = cur[1];
                cells.add(cur);
                size++;

                if (isBorder(r, c)) {
                    touchesBorder = true;
                }

                for (int[] dir : Dir.values()) {
                    int nr = r + dir.dr;
                    int nc = c + dir.dc;
                    if (valid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        q.add(new int[]{nr, nc});
                    }
                }
            }

            if (!touchesBorder) {
                // Mark the discovered lake cells with their size in lakeSize grid
                // (not strictly necessary for final output, but mirrors original logic)
                for (int[] cell : cells) {
                    int r = cell[0], c = cell[1];
                    lakeSize[r][c] = size;
                }
                return new Lake(sr, sc, size);
            }
            return null; // lake touches the outer border → ignore
        }

        /** Mark all cells of a lake with '*' (deleted). */
        private void floodFill(Lake lake) {
            Queue<int[]> q = new ArrayDeque<>();
            q.add(new int[]{lake.row, lake.col});
            visited[lake.row][lake.col] = true;

            while (!q.isEmpty()) {
                int[] cur = q.poll();
                int r = cur[0], c = cur[1];
                grid[r][c] = '*';

                for (int[] dir : Dir.values()) {
                    int nr = r + dir.dr;
                    int nc = c + dir.dc;
                    if (valid(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                        visited[nr][nc] = true;
                        q.add(new int[]{nr, nc});
                    }
                }
            }
        }

        /** Simple print of the resulting grid. */
        void printResult() {
            for (char[] row : grid) {
                out.println(new String(row));
            }
        }

        /** Utility helpers. */
        private boolean valid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean isBorder(int r, int c) {
            return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
        }

        /** Direction constants for neighbors. */
        private enum Dir {
            UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);
            final int dr, dc;
            Dir(int dr, int dc) { this.dr = dr; this.dc = dc; }
        }

        /** Simple container for a discovered lake. */
        private static class Lake {
            final int row, col; // any representative cell (start cell)
            final int size;

            Lake(int row, int col, int size) {
                this.row = row;
                this.col = col;
                this.size = size;
            }
        }

        /* --------------------------------------------------------------------- */
        /* Boiler‑plate fields used by original algorithm (kept to preserve logic) */
        private int[][] lakeSize = new int[1000][1000]; // size of each cell's lake
        /* --------------------------------------------------------------------- */
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.Deque;

/**
 * Reads a map of land (‘#’) and water ('.'), finds all lakes that do **not**
 * touch the ocean, removes the smallest lakes until exactly {@code lakes}
 * lakes remain, and prints the number of water cells turned into land
 * together with the resulting map.
 *
 * The implementation is deliberately modern and easy to maintain:
 *   • Clear separation of concerns (input, lake discovery, removal, output)
 *   • Use of collections with generics instead of raw types
 *   • Encyclopedia‑style naming and immutable data holders (records)
 *   • Guarded entry point using try‑with‑resources
 *   • No static mutable fields – everything is confined to method scopes
 */
public class LakesInBerland {

    /** Character used to represent transformed water cells (land). */
    private static final char LAND = '*';
    /** Character used to represent original water cells. */
    private static final char WATER = '.';

    /** Four orthogonal movement directions. */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {0, 1}, {1, 0}, {0, -1}
    };

    public static void main(String[] args) {
        /* --------------------------------------------------------------
         * 1️⃣  Input handling – try‑with‑resources guarantees proper closing.
         * -------------------------------------------------------------- */
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            int requiredLakes = scanner.nextInt();

            char[][] grid = readGrid(scanner, rows, cols);

            /* --------------------------------------------------------------
             * 2️⃣  Discover all lakes that are not connected to the ocean.
             * -------------------------------------------------------------- */
            List<Lake> lakes = discoverLakes(grid, rows, cols);
            lakes.sort(Comparator.comparingInt(l -> l.points.size()));

            /* --------------------------------------------------------------
             * 3️⃣  Remove the smallest lakes until the desired number of lakes
             *      remains, counting how many cells are turned into land.
             * -------------------------------------------------------------- */
            int removedCells = 0;
            int lakesToRemove = lakes.size() - requiredLakes;
            for (int i = 0; i < lakesToRemove; i++) {
                Lake lake = lakes.get(i);
                removedCells += lake.points.size();
                for (Point p : lake.points) {
                    grid[p.x()][p.y()] = LAND;
                }
            }

            /* --------------------------------------------------------------
             * 4️⃣  Output the result.
             * -------------------------------------------------------------- */
            System.out.println(removedCells);
            printGrid(grid);
        }
    }

    /** Reads {@code rows} lines of length {@code cols} from the scanner. */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        scanner.nextLine(); // consume the rest of the first line
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Finds every maximal water region that does **not** touch the border.
     * Returns a list where each element contains the points of one lake.
     */
    private static List<Lake> discoverLakes(char[][] grid, int n, int m) {
        List<Lake> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!visited[i][j] && grid[i][j] == WATER) {
                    List<Point> component = new ArrayList<>();
                    boolean touchesOcean = explore(grid, visited, i, j, n, m, component);
                    if (!touchesOcean) {
                        lakes.add(new Lake(component));
                    }
                }
            }
        }
        return lakes;
    }

    /**
     * Depth‑first exploration of a water component.
     *
     * @return {@code true} if the component touches the outer border (ocean);
     *         {@code false} otherwise.
     */
    private static boolean explore(char[][] grid,
                                   boolean[][] visited,
                                   int startX, int startY,
                                   int n, int m,
                                   List<Point> component) {
        Deque<Point> stack = new ArrayDeque<>();
        stack.push(new Point(startX, startY));
        visited[startX][startY] = true;
        boolean touchesOcean = isBorder(startX, startY, n, m);

        while (!stack.isEmpty()) {
            Point cur = stack.pop();
            component.add(cur);
            for (int[] dir : DIRECTIONS) {
                int nx = cur.x() + dir[0];
                int ny = cur.y() + dir[1];
                if (isInBounds(nx, ny, n, m)
                        && !visited[nx][ny]
                        && grid[nx][ny] == WATER) {
                    visited[nx][ny] = true;
                    if (isBorder(nx, ny, n, m)) {
                        touchesOcean = true;
                    }
                    stack.push(new Point(nx, ny));
                }
            }
        }
        return touchesOcean;
    }

    /** Utility – checks whether coordinates are inside the grid. */
    private static boolean isInBounds(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /** Utility – true if the point lies on the outer border. */
    private static boolean isBorder(int x, int y, int n, int m) {
        return x == 0 || x == n - 1 || y == 0 || y == m - 1;
    }

    /** Simple immutable holder for a coordinate pair. */
    private static record Point(int x, int y) {}

    /** Immutable holder for a discovered lake. */
    private static record Lake(List<Point> points) {}

    /** Pretty‑prints the resulting grid. */
    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }
}

import java.io.IOException;
import java.util.*;

public class Task2 {

    /** Four direction vectors used for neighbour exploration */
    private static final int[][] DIRS = {{0, 1}, {0, -1}, {-1, 0}, {1, 0}};

    /** Simple holder for an internal (non‑border) component */
    private static final class Component {
        final int startRow, startCol;
        final int size;

        Component(int startRow, int startCol, int size) {
            this.startRow = startRow;
            this.startCol = startCol;
            this.size = size;
        }
    }

    public static void main(String[] args) throws IOException {
        try (Scanner sc = new Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();
            int keep = sc.nextInt();

            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = sc.next().toCharArray();
            }

            List<Component> internal = findInternalComponents(grid, rows, cols);

            // The original program sorted components by size (ascending) and removed the
            // smallest ones until only `keep` components remained.
            internal.sort(Comparator.comparingInt(c -> c.size));

            int answer = 0;
            int toRemove = internal.size() - keep;
            if (toRemove > 0) {
                for (int i = 0; i < toRemove; i++) {
                    Component comp = internal.get(i);
                    answer += comp.size;
                    // Replace the whole component (still marked with '!') by '*'
                    floodFillReplace(grid, comp.startRow, comp.startCol, '!', '*', rows, cols);
                }
            }

            // Any leftover '!' marks belong to components that were not removed.
            // Restore them to '.' to obtain the final grid state.
            restoreDots(grid);

            System.out.println(answer);
            printGrid(grid);
        }
    }

    /** Scans the grid and collects every '.' component that does NOT touch the border.
     *  The component is temporarily marked with '!' and its size together with a
     *  representative cell are stored. */
    private static List<Component> findInternalComponents(char[][] grid, int n, int m) {
        List<Component> result = new ArrayList<>();

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '.' && !isBorderCell(r, c, n, m)) {
                    FloodFillResult res = floodFill(grid, r, c, '.', '!', n, m);
                    if (!res.touchesBorder) {
                        // Store the cell we started from as the component's representative.
                        result.add(new Component(r, c, res.size));
                    }
                    // Restore the temporary '!' so that later components can be discovered.
                    floodFillReplace(grid, r, c, '!', '.', n, m);
                }
            }
        }
        return result;
    }

    /** Depth‑first flood fill that returns the size of the region and whether it touches a border. */
    private static FloodFillResult floodFill(char[][] grid, int r, int c, char original, char mark, int n, int m) {
        if (r < 0 || r >= n || c < 0 || c >= m || grid[r][c] != original) {
            return new FloodFillResult(0, false);
        }

        boolean touchesBorder = isBorderCell(r, c, n, m);
        grid[r][c] = mark;
        int count = 1;

        for (int[] d : DIRS) {
            FloodFillResult sub = floodFill(grid, r + d[0], c + d[1], original, mark, n, m);
            count += sub.size;
            touchesBorder = touchesBorder || sub.touchesBorder;
        }
        return new FloodFillResult(count, touchesBorder);
    }

    /** Marks the whole component (currently marked with `src`) with `target`. */
    private static void floodFillReplace(char[][] grid, int r, int c, char src, char target, int n, int m) {
        if (grid[r][c] != src) {
            return;
        }
        grid[r][c] = target;
        for (int[] d : DIRS) {
            floodFillReplace(grid, r + d[0], c + d[1], src, target, n, m);
        }
    }

    /** Restores every still‑temporary '!' cell back to '.'. */
    private static void restoreDots(char[][] grid) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == '!') {
                    floodFillReplace(grid, r, c, '!', '.', grid.length, grid[0].length);
                }
            }
        }
    }

    /** Checks whether a cell lies on the outer border of the grid. */
    private static boolean isBorderCell(int r, int c, int n, int m) {
        return r == 0 || r == n - 1 || c == 0 || c == m - 1;
    }

    /** Simple pretty‑printer for the character grid. */
    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(row);
        }
    }

    /** Small DTO returned by floodFill. */
    private static final class FloodFillResult {
        final int size;
        final boolean touchesBorder;

        FloodFillResult(int size, boolean touchesBorder) {
            this.size = size;
            this.touchesBorder = touchesBorder;
        }
    }
}

import java.io.PrintWriter;
import java.io.Scanner;
import java.io.IOException;
import java.util.*;

/**
 * Main entry point. Reads the problem input, solves the task and prints the result.
 */
public class Main {

    /** constant that represents water in the internal grid */
    private static final int WATER = -1;
    /** constant used to mark cells that have already been processed */
    private static final int VISITED = -2;

    /** Represents a lake (connected water component). */
    private static final class Lake implements Comparable<Lake> {
        final int id;          // unique identifier of the lake
        final int size;        // number of cells belonging to the lake
        final int startRow;    // any cell of the lake – used for flood‑fill removal
        final int startCol;

        Lake(int id, int size, int startRow, int startCol) {
            this.id = id;
            this.size = size;
            this.startRow = startRow;
            this.startCol = startCol;
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /** Solves the task for a single test case. */
    private static void solve(Scanner in, PrintWriter out) {
        int n = in.nextInt();               // number of rows
        int m = in.nextInt();               // number of columns
        int keep = in.nextInt();            // number of lakes we must keep

        in.nextLine();                      // consume end‑of‑line

        int[][] grid = readGrid(in, n, m);

        // -----------------------------------------------------------------
        // 1. Mark water cells that are directly connected to the border.
        // -----------------------------------------------------------------
        markBorderWater(grid);

        // -----------------------------------------------------------------
        // 2. Discover all lakes, assign them unique positive ids and store
        //    their sizes and a representative cell.
        // -----------------------------------------------------------------
        Map<Integer, Lake> lakeMap = discoverLakes(grid);

        // -----------------------------------------------------------------
        // 3. Remove the smallest (totalLakes - keep) lakes if we have too many.
        // -----------------------------------------------------------------
        int cellsFilled = 0;
        if (lakeMap.size() > keep) {
            List<Lake> lakes = new ArrayList<>(lakeMap.values());
            lakes.sort(null); // natural order = sorted by size (ascending)

            int lakesToRemove = lakes.size() - keep;
            for (int i = 0; i < lakesToRemove; i++) {
                Lake lake = lakes.get(i);
                floodFill(grid, lake.startRow, lake.startCol, 0, lake.id);
                cellsFilled += lake.size;
            }
        }

        // -----------------------------------------------------------------
        // 4. Output the answer and the transformed map.
        // -----------------------------------------------------------------
        out.println(cellsFilled);
        printMap(grid, out);
    }

    /** Reads the n×m grid from the input. '.' denotes water, any other character denotes land. */
    private static int[][] readGrid(Scanner in, int n, int m) {
        int[][] g = new int[n][m];
        for (int r = 0; r < n; r++) {
            String line = in.nextLine();
            for (int c = 0; c < m; c++) {
                g[r][c] = (line.charAt(c) == '.') ? WATER : 0;
            }
        }
        return g;
    }

    /** Marks all water cells touching the border as VISITED (‑2). */
    private static void markBorderWater(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        // top & bottom rows
        for (int c = 0; c < cols; c++) {
            processBorderCell(grid, 0, c);
            processBorderCell(grid, rows - 1, c);
        }
        // left & right columns (excluding corners already processed)
        for (int r = 1; r < rows - 1; r++) {
            processBorderCell(grid, r, 0);
            processBorderCell(grid, r, cols - 1);
        }
    }

    private static void processBorderCell(int[][] grid, int r, int c) {
        if (grid[r][c] == WATER) {
            floodFill(grid, r, c, VISITED, WATER);
        }
    }

    /** Discovers all lakes, assigns them ids and stores their meta‑information. */
    private static Map<Integer, Lake> discoverLakes(int[][] grid) {
        Map<Integer, Lake> lakes = new HashMap<>();
        int nextId = 1;

        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == WATER) {
                    Lake lake = floodFillAndCollect(grid, r, c, nextId++);
                    lakes.put(lake.id, lake);
                }
            }
        }
        return lakes;
    }

    /** Flood‑fills the component that contains (row,col) with the given id.
     *  Returns a {@link Lake} object describing the discovered component. */
    private static Lake floodFillAndCollect(int[][] grid, int row, int col, int id) {
        Queue<Point> q = new ArrayDeque<>();
        q.add(new Point(row, col));
        grid[row][col] = id;
        int size = 0;

        while (!q.isEmpty()) {
            Point p = q.poll();
            size++;
            // explore neighbours
            int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};
            for (int[] d : dirs) {
                int nr = p.r + d[0];
                int nc = p.c + d[1];
                if (valid(nr, nc, grid) && grid[nr][nc] == WATER) {
                    grid[nr][nc] = id;
                    q.add(new Point(nr, nc));
                }
            }
        }
        return new Lake(id, size, row, col);
    }

    /** Generic flood‑fill that replaces all cells equal to target with newValue. */
    private static void floodFill(int[][] grid, int startR, int startC, int newValue, int target) {
        if (grid[startR][startC] != target) {
            return;
        }
        Deque<Point> stack = new ArrayDeque<>();
        stack.push(new Point(startR, startC));

        while (!stack.isEmpty()) {
            Point p = stack.pop();
            if (grid[p.r][p.c] != target) {
                continue;
            }
            grid[p.r][p.c] = newValue;
            int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};
            for (int[] d : dirs) {
                int nr = p.r + d[0];
                int nc = p.c + d[1];
                if (valid(nr, nc, grid) && grid[nr][nc] == target) {
                    stack.push(new Point(nr, nc));
                }
            }
        }
    }

    /** Prints the final grid: water (any non‑zero) as '.' and land (zero) as '*'. */
    private static void printMap(int[][] grid, PrintWriter out) {
        for (int[] row : grid) {
            for (int cell : row) {
                out.print(cell != 0 ? '.' : '*');
            }
            out.println();
        }
    }

    /** Simple container for a grid coordinate. */
    private static final class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    /** Validates coordinates against grid bounds. */
    private static boolean valid(int r, int c, int[][] grid) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[r].length;
    }

    /** -----------------------------------------------------------------
     *  Entry point – uses try‑with‑resources to guarantee proper closing of
     *  I/O streams.
     *  ----------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            new Main().solve(scanner, writer);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution that keeps the original algorithmic behaviour
 * but improves readability, modularity and maintainability.
 */
public class Main {

    /** PrintWriter used for output (wrapped in a buffered stream). */
    private static PrintWriter out;

    /** Scanner that reads tokens from standard input. */
    private static FastScanner in;

    /** Simple DTO that stores a component's size and a representative cell. */
    private static final class Component {
        final int size;   // number of cells in the component
        final int row;    // representative row (any cell of the component)
        final int col;    // representative column

        Component(int size, int row, int col) {
            this.size = size;
            this.row = row;
            this.col = col;
        }
    }

    /** Four movement directions: down, left, up, right. */
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, -1, 0, 1};

    /** Upper bound for grid dimensions used in the original code (kept for compatibility). */
    private static final int MAX_N = 53;

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        in = new FastScanner();
        out = new PrintWriter(new BufferedOutputStream(System.out), true);

        int n = in.nextInt();          // number of rows
        int m = in.nextInt();          // number of columns
        int k = in.nextInt();          // number of largest components to keep

        char[][] grid = readGrid(n);
        boolean[][] visited = new boolean[n][m];

        List<Component> components = discoverComponents(grid, visited, n, m);
        Collections.sort(components, Comparator.comparingInt(c -> c.size).reversed());

        int sum = computeExcludedSize(components, k);
        markComponentsForRemoval(grid, components, k);

        outputResult(sum, grid);
        out.flush();
    }

    /** Reads the grid from the scanner. */
    private static char[][] readGrid(int n) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = in.nextLine();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Finds all connected components of '.' cells that are not completely surrounded
     * by other cells (i.e., those touching the border).
     *
     * @return list of {@link Component} objects.
     */
    private static List<Component> discoverComponents(char[][] grid,
                                                      boolean[][] visited,
                                                      int n,
                                                      int m) {
        List<Component> result = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // skip obstacles and interior cells of other components
                if (grid[i][j] == '*' ||
                        (i > 0 && i < n - 1 && j > 0 && j < m - 1)) {
                    continue;
                }
                if (!visited[i][j]) {
                    result.add(exploreComponent(grid, visited, i, j));
                }
            }
        }
        return result;
    }

    /**
     * Performs an iterative DFS to count the size of a component and
     * returns a {@link Component} describing it.
     */
    private static Component exploreComponent(char[][] grid,
                                              boolean[][] visited,
                                              int startX,
                                              int startY) {
        if (!inBounds(grid, startX, startY) || grid[startX][startY] == '*') {
            return null;
        }

        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startX, startY});
        visited[startX][startY] = true;
        int size = 0;
        int repRow = startX, repCol = startY; // keep one cell as representative

        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int x = cur[0];
            int y = cur[1];
            size++;

            for (int d = 0; d < 4; d++) {
                int nx = x + DX[d];
                int ny = y + DY[d];
                if (inBounds(grid, nx, ny) && grid[nx][ny] == '.' && !visited[nx][ny]) {
                    visited[nx][ny] = true;
                    stack.push(new int[]{nx, ny});
                }
            }
        }
        return new Component(size, repRow, repCol);
    }

    /** Checks whether (x, y) lies inside the grid limits. */
    private static boolean inBounds(char[][] grid, int x, int y) {
        return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length;
    }

    /**
     * Marks every cell of the component that starts at (row, col) with '*',
     * effectively removing it from the board.
     */
    private static void markComponentsForRemoval(char[][] grid,
                                                  List<Component> components,
                                                  int k) {
        for (int i = k; i < components.size(); i++) {
            Component comp = components.get(i);
            markComponent(grid, comp.row, comp.col);
        }
    }

    /** Iterative flood‑fill that converts a whole component to '*'. */
    private static void markComponent(char[][] grid, int startRow, int startCol) {
        if (grid[startRow][startCol] != '.') {
            return;
        }
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startRow, startCol});

        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int x = cur[0];
            int y = cur[1];
            grid[x][y] = '*';
            for (int d = 0; d < 4; d++) {
                int nx = x + DX[d];
                int ny = y + DY[d];
                if (inBounds(grid, nx, ny) && grid[nx][ny] == '.') {
                    stack.push(new int[]{nx, ny});
                }
            }
        }
    }

    /** Prints the sum of sizes of removed components and the updated grid. */
    private static void outputResult(int sum, char[][] grid) {
        out.println(sum);
        for (char[] row : grid) {
            for (char cell : row) {
                out.print(cell);
            }
            out.println();
        }
    }

    /**
     * Fast scanner implementation that tokenises input lines.
     * It throws an unchecked IOException if an I/O error occurs.
     */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

/**
 * Refactored version of the original `lakes` program.
 *
 * <p>
 *   The program reads a rectangular map consisting of '.' (open water) and '*' (land)
 *   characters.  It identifies all water regions that are completely surrounded by land
 *   (i.e., do not touch the map border) and stores them as lakes.
 *   Afterwards it removes the smallest {@code k} lakes (by number of cells) by
 *   replacing their cells with '*' and prints the number of cells removed followed
 *   by the modified map.
 * </p>
 *
 * <p>
 *   The refactor focuses on readability, encapsulation and modern Java practices:
 *   <ul>
 *     <li>All mutable state is confined to a dedicated {@code LakeFinder} class.</li>
 *     <li>Raw types and legacy Swing‑style `Point` usage have been replaced by a
 *         lightweight immutable {@code Coord} class.</li>
 *     <li>Resources are managed with try‑with‑resources.</li>
 *     <li>Iteration constants, border‑checking and lake‑validation are extracted
 *         into small, well‑named methods.</li>
 *     <li>Collections are typed, and sorting uses the modern `Comparator.comparingInt`.</li>
 *   </ul>
 * </p>
 */
public class LakeFinder {

    /** Directions used for exploring neighbouring cells. */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, // up
            {+1, 0}, // down
            {0, -1}, // left
            {0, +1}  // right
    };

    /** Input dimensions and parameter. */
    private final int rows;
    private final int cols;
    private final int lakesToRemove;

    /** Map representation: '.' – water, '*' – land (or removed water). */
    private final char[][] grid;

    /** Book‑keeping arrays. */
    private final boolean[][] visited;

    /** Stack used for iterative depth‑first search. */
    private final java.util.ArrayDeque<Coord> stack = new java.util.ArrayDeque<>();

    /**
     * Holds a discovered lake – a collection of coordinates belonging to the same
     * water region that does not touch the border.
     */
    private static final class Lake {
        final java.util.List<Coord> points = new java.util.ArrayList<>();

        Lake(java.util.List<Coord> points) { this.points.addAll(points); }
        int size() { return points.size(); }
    }

    /** Simple immutable coordinate holder. */
    private static final class Coord {
        final int row;
        final int col;

        Coord(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Constructs a {@code LakeFinder} from the supplied dimensions, map and {@code k}.
     *
     * @param rows      number of rows in the map
     * @param cols      number of columns in the map
     * @param lakesToRemove how many *smallest* lakes to erase
     * @param map       character grid read from input
     */
    public LakeFinder(int rows, int cols, int lakesToRemove, char[][] map) {
        this.rows = rows;
        this.cols = cols;
        this.lakesToRemove = lakesToRemove;
        this.grid = map;
        this.visited = new boolean[rows][cols];
    }

    /** Entry point – parses input, discovers lakes, removes selected ones and prints results. */
    public static void main(String[] args) throws java.io.IOException {
        // -------------------------------------------------------------------------
        // Input handling (try‑with‑resources ensures the BufferedReader is closed)
        // -------------------------------------------------------------------------
        try (java.io.BufferedReader br = new java.io.BufferedReader(
                new java.io.InputStreamReader(System.in))) {

            String firstLine = br.readLine();
            String[] dims = split(firstLine);
            int n = Integer.parseInt(dims[0]);
            int m = Integer.parseInt(dims[1]);
            int k = Integer.parseInt(dims[2]);

            char[][] map = new char[n][];
            for (int i = 0; i < n; i++) {
                map[i] = br.readLine().toCharArray();
            }

            new LakeFinder(n, m, k, map).run();
        }
    }

    /** Main processing routine – discovers lakes, removes the smallest {@code k}, prints output. */
    private void run() {
        // -------------------------------------------------------------------------
        // 1️⃣ Discover all lakes that are fully surrounded by land.
        // -------------------------------------------------------------------------
        java.util.List<Lake> lakes = discoverLakes();

        // -------------------------------------------------------------------------
        // 2️⃣ Sort lakes by size (ascending) – smallest first.
        // -------------------------------------------------------------------------
        lakes.sort(
                java.util.Comparator.comparingInt(Lake::size)
        );

        // -------------------------------------------------------------------------
        // 3️⃣ Remove the smallest {@code k} lakes (or all if fewer exist).
        // -------------------------------------------------------------------------
        int removedCellCount = 0;
        int lakesToErase = Math.min(lakes.size(), lakesToRemove);
        for (int i = 0; i < lakesToErase; i++) {
            Lake lake = lakes.get(i);
            for (Coord c : lake.points) {
                grid[c.row][c.col] = '*';           // turn water into land
                removedCellCount++;
            }
        }

        // -------------------------------------------------------------------------
        // 4️⃣ Output the number of removed cells followed by the modified map.
        // -------------------------------------------------------------------------
        System.out.println(removedCellCount);
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }

    /** Finds all lakes that do **not** touch the border of the map. */
    private java.util.List<Lake> discoverLakes() {
        java.util.List<Lake> lakes = new java.util.ArrayList<>();

        // Scan the whole grid looking for unvisited water cells.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    stack.push(new Coord(r, c));
                    Lake lake = exploreFromStack();
                    // Keep only lakes that are completely interior (no border contact)
                    if (!lake.touchesBorder) {
                        lakes.add(lake);
                    }
                }
            }
        }
        return lakes;
    }

    /** Performs an iterative DFS starting from the stack's top element. */
    private Lake exploreFromStack() {
        java.util.List<Coord> component = new java.util.ArrayList<>();
        boolean touchesBorder = false;

        while (!stack.isEmpty()) {
            Coord cur = stack.pop();

            if (visited[cur.row][cur.col]) {
                continue;
            }
            visited[cur.row][cur.col] = true;
            component.add(cur);

            // Check if this cell lies on the outer border.
            if (isOnBorder(cur)) {
                touchesBorder = true;
            }

            // Explore neighbours.
            for (int[] dir : DIRECTIONS) {
                int nr = cur.row + dir[0];
                int nc = cur.col + dir[1];
                if (isValidCell(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    stack.push(new Coord(nr, nc));
                }
            }
        }

        return new Lake(component) {{
            this.touchesBorder = touchesBorder;
        }};
    }

    /** Returns true if the supplied coordinate lies on the outermost row or column. */
    private boolean isOnBorder(Coord c) {
        return c.row == 0 || c.row == rows - 1 || c.col == 0 || c.col == cols - 1;
    }

    /** Helper that splits a string on one-or-more whitespace characters. */
    private static String[] split(String src) {
        return src.trim().split("\\s+");
    }

    /** Checks that a cell is inside the grid bounds. */
    private boolean isValidCell(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

/**
 * Reads a grid that represents a map of lakes ('.' cells) and land ('*' cells).
 * It removes the smallest lakes until exactly {@code k} lakes remain,
 * counts how many cells are turned into land and prints the resulting grid.
 *
 * The program follows the original algorithm but is refactored for
 * readability, maintainability and adherence to Java naming conventions.
 */
public class LakesMaintainable {

    /** Directions used for exploring neighboring cells (up, down, left, right). */
    private static final int[][] DIRECTIONS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    /** The grid that stores the map characters. */
    private char[][] grid;

    /** Tracks visited cells during breadth‑first searches. */
    private boolean[][] visited;

    /** Number of rows and columns of the grid. */
    private final int rows;
    private final int cols;
    private final int lakesToKeep;

    /** Holds information about each discovered lake. */
    private static class Lake implements Comparable<Lake> {
        /** Size of the lake (number of '.' cells). */
        final int size;
        /** Row index of the first '.' cell encountered (used as a starting point). */
        final int startRow;
        /** Column index of the first '.' cell encountered. */
        final int startCol;

        Lake(int size, int startRow, int startCol) {
            this.size = size;
            this.startRow = startRow;
            this.startCol = startCol;
        }

        @Override
        public int compareTo(Lake o) {
            return Integer.compare(this.size, o.size);
        }
    }

    /** Simple holder for a coordinate pair. */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            readInput(scanner);
            discoverLakes();
            sortLakesAscending();
            int totalRemovedCells = removeSmallestLakes();
            printResult(totalRemovedCells);
        }
    }

    /** Reads grid dimensions, the value {@code k} and the grid itself. */
    private void readInput(Scanner scanner) {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        lakesToKeep = scanner.nextInt();
        scanner.nextLine(); // consume end‑of‑line

        grid = new char[rows][cols];
        visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            String line = scanner.nextLine();
            grid[r] = line.toCharArray();
        }
    }

    /** Finds all lakes, stores them in a list, and sorts the list by size (ascending). */
    private void discoverLakes() {
        List<Lake> lakes = new ArrayList<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    int size = exploreComponent(r, c);
                    if (size > 0) {
                        lakes.add(new Lake(size, r, c));
                    }
                }
            }
        }

        // Store the list in a field for later use.
        // (In a larger design this would be returned instead of a field.)
        this.lakes = lakes;
    }

    /** Recursively explores a connected component of '.' cells and returns its size. */
    private int exploreComponent(int startRow, int startCol) {
        if (!isInside(startRow, startCol) || grid[startRow][startCol] == '*' || visited[startRow][startCol]) {
            return 0;
        }

        visited[startRow][startCol] = true;
        int size = 1;

        for (int[] dir : DIRECTIONS) {
            int nextRow = startRow + dir[0];
            int nextCol = startCol + dir[1];
            size += exploreComponent(nextRow, nextCol);
        }
        return size;
    }

    /** Removes (fills) the smallest lakes until exactly {@code lakesToKeep} lakes remain.
     *  Returns the total number of cells that were turned into land. */
    private int removeSmallestLakes() {
        int lakesToRemove = lakes.size() - lakesToKeep;
        int removedCellCount = 0;

        for (int i = 0; i < lakesToRemove; i++) {
            Lake lake = lakes.get(i);
            fillComponent(lake.startRow, lake.startCol);
            removedCellCount += lake.size;
        }

        return removedCellCount;
    }

    /** Fills a lake (and its connected '.' cells) with '*' using DFS. */
    private void fillComponent(int row, int col) {
        if (!isInside(row, col) || grid[row][col] == '*' || visited[row][col]) {
            return;
        }

        visited[row][col] = true;
        grid[row][col] = '*';

        for (int[] dir : DIRECTIONS) {
            fillComponent(row + dir[0], col + dir[1]);
        }
    }

    /** Checks whether a given coordinate is inside the grid bounds. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Prints the number of removed cells followed by the modified grid. */
    private void printResult(int removedCellCount) {
        System.out.println(removedCellCount);

        StringBuilder sb = new StringBuilder();
        for (char[] line : grid) {
            sb.append(line);
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Maintains a lake‑removal game on a grid.
 *
 * <p>The program reads a grid consisting of '.' (empty) and '*' (blocked) cells,
 * discovers all lakes (connected empty areas that do <em>not</em> touch the border),
 * removes the smallest lakes until at most {@code t} lakes remain,
 * outputs the number of cells that were turned into blocked cells and prints the
 * final grid.</p>
 */
public class Main {

    /** Directions used for exploring neighbours (up, down, left, right). */
    private static final int[][] DIRS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Reads the whole input once and provides a clean way to close resources. */
    private static try (BufferedReader br = new BufferedReader(
            new InputStreamReader(System.in));
            PrintWriter out = new PrintWriter(System.out)) {

        // ------------------------------------------------------------
        // 1️⃣  Parse the first line: rows, columns and the required number of lakes.
        // ------------------------------------------------------------
        String[] header = parseTokens(br.readLine(), 3);
        final int rows = Integer.parseInt(header[0]);
        final int cols = Integer.parseInt(header[1]);
        final int requiredLakes = Integer.parseInt(header[2]);

        // ------------------------------------------------------------
        // 2️⃣  Read the grid.
        // ------------------------------------------------------------
        final char[][] grid = readGrid(br, rows, cols);

        // ------------------------------------------------------------
        // 3️⃣  Discover all lakes.
        // ------------------------------------------------------------
        List<Lake> lakes = discoverLakes(grid, rows, cols);

        // ------------------------------------------------------------
        // 4️⃣  Remove lakes until only {@code requiredLakes} stay.
        // ------------------------------------------------------------
        int filledCells = 0;
        while (lakes.size() > requiredLakes) {
            Lake lakeToRemove = lakes.remove(0);          // smallest lake because of ordering
            fill(lakeToRemove, grid);
            filledCells += lakeToRemove.size;
        }

        // ------------------------------------------------------------
        // 5️⃣  Output result.
        // ------------------------------------------------------------
        out.println(filledCells);
        for (char[] line : grid) {
            out.println(new String(line));
        }
    }

    /** Parses a line using {@link StringTokenizer} and returns all tokens. */
    private static String[] parseTokens(String line, int expected) {
        StringTokenizer st = new StringTokenizer(line);
        String[] tokens = new String[expected];
        for (int i = 0; i < expected; i++) {
            tokens[i] = st.nextToken();
        }
        return tokens;
    }

    /** Reads {@code rows} lines of length {@code cols} into a char matrix. */
    private static char[][] readGrid(BufferedReader br, int rows, int cols) throws IOException {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = br.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input while reading grid.");
            }
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /** Simple holder for a lake – its entry point and its size. */
    private static final class Lake implements Comparable<Lake> {
        final int row;          // starting row of the lake
        final int col;          // starting column of the lake
        final int size;         // number of '.' cells in the lake

        Lake(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public int compareTo(Lake other) {
            int cmp = Integer.compare(this.size, other.size);
            if (cmp != 0) return cmp;
            cmp = Integer.compare(this.row, other.row);
            return (cmp != 0) ? cmp : Integer.compare(this.col, other.col);
        }
    }

    /** Finds all lakes in {@code grid}. */
    private static List<Lake> discoverLakes(char[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        List<Lake> lakes = new ArrayList<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    Lake lake = exploreLake(grid, visited, r, c);
                    if (!lake.touchesBorder) {
                        lakes.add(lake);
                    }
                }
            }
        }

        // Sort lakes by size (ascending) then by row/col to guarantee deterministic order.
        lakes.sort(null);
        return lakes;
    }

    /** Depth‑first search that returns a lake description. */
    private static Lake exploreLake(char[][] grid, boolean[][] visited, int startR, int startC) {
        Deque<Point> stack = new ArrayDeque<>();
        stack.push(new Point(startR, startC));
        visited[startR][startC] = true;

        int size = 0;
        boolean touchesBorder = false;

        while (!stack.isEmpty()) {
            Point cur = stack.pop();
            size++;

            // border check – any neighbour out of bounds makes the whole lake “bad”
            for (int[][] dir : DIRS) {
                int nr = cur.r + dir[0];
                int nc = cur.c + dir[1];
                if (nr < 0 || nr >= grid.length || nc < 0 || nc >= grid[0].length) {
                    touchesBorder = true;
                    continue;
                }
                if (grid[nr][nc] == '*' || visited[nr][nc]) {
                    continue;
                }
                visited[nr][nc] = true;
                stack.push(new Point(nr, nc));
            }
        }

        return new Lake(startR, startC, size) {
            { touchesBorder = touchesBorder; }
        };
    }

    /** Helper point class used for stack‑based flood fill. */
    private static final class Point {
        final int r;
        final int c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /** Turns all cells belonging to {@code lake} into blocked cells ('*'). */
    private static void fill(Lake lake, char[][] grid) {
        Queue<Point> q = new ArrayDeque<>();
        q.add(new Point(lake.row, lake.col));
        grid[lake.row][lake.col] = '*';

        while (!q.isEmpty()) {
            Point cur = q.poll();
            for (int[][] dir : DIRS) {
                int nr = cur.r + dir[0];
                int nc = cur.c + dir[1];
                if (nr < 0 || nr >= grid.length || nc < 0 || nc >= grid[0].length) {
                    continue;
                }
                if (grid[nr][nc] == '.') {
                    grid[nr][nc] = '*';
                    q.add(new Point(nr, nc));
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the problem that processes a grid, discovers connected components
 * of empty cells ('.') and removes a configurable number of non‑border components
 * with the smallest sizes. The program prints the number of cells turned into
 * obstacles ('*') and the final grid.
 */
public class Main {

    /** Fast input reader */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() throws FileNotFoundException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns next token (String) */
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Returns next integer */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Returns next long */
        long nextLong() {
            return Long.parseLong(next());
        }

        /** Returns next line (may be used for whole‑line reads) */
        String nextLine() throws IOException {
            return br.readLine();
        }

        /** Utility method to check for more data */
        boolean hasNext() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return false;
                }
                st = new StringTokenizer(line);
            }
            return true;
        }
    }

    /** Representation of a connected component */
    private static final class Component {
        final int id;          // Component identifier (1‑based)
        final long size;       // Number of cells in the component
        final boolean border;  // true if the component touches the grid border

        Component(int id, long size, boolean border) {
            this.id = id;
            this.size = size;
            this.border = border;
        }
    }

    /** Directions used for 4‑neighbour exploration */
    private static final int[] Dx = {-1, 0, 1, 0};
    private static final int[] Dy = {0, 1, 0, -1};

    /** Grid data structures – they are deliberately kept static in this small
     *  problem but are accessed only through well‑named methods. */
    private static char[][] grid;
    private static int[][] componentId;   // CC in the original code
    private static boolean[][] visited;
    private static final Set<Integer> borderComponents = new HashSet<>();

    /** Main solving routine */
    public static void solve() throws IOException {
        FastReader reader = new FastReader();

        int n = reader.nextInt();   // rows
        int m = reader.nextInt();   // columns
        int k = reader.nextInt();   // number of components to keep (besides border ones)

        readGrid(reader, n, m);
        discoverComponents();

        /* --------------------------------------------------------------------
         *  1️⃣  Build a min‑heap ordered by component size (smallest first)
         *  2️⃣  Remove the required amount of *non‑border* components
         * -------------------------------------------------------------------- */
        int mustRemove = totalComponents - borderComponents.size() - k;
        int removed = 0;
        int cellsConverted = 0;

        PriorityQueue<Component> minHeap = new PriorityQueue<>(Comparator.comparingLong(c -> c.size));
        for (Component comp : components) {
            minHeap.offer(comp);
        }

        while (removed < mustRemove) {
            Component cur = minHeap.poll();
            if (cur == null) {
                break; // safety check – should never happen
            }
            if (cur.border) {
                continue; // border components are never removed
            }
            clearComponent(cur.id);
            cellsConverted += cur.size;
            removed++;
        }

        /* --------------------------------------------------------------------
         *  Output
         * -------------------------------------------------------------------- */
        out.println(cellsConverted);
        printGrid();
        out.close();
    }

    /* ------------------------------------------------------------------------
     *  Helper methods
     * ------------------------------------------------------------------------ */

    /** Reads the whole grid from the input reader */
    private static void readGrid(FastReader reader, int rows, int cols) {
        grid = new char[rows][];
        componentId = new int[rows][cols];
        visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            String line = reader.nextLine();
            grid[r] = line.toCharArray();
        }
    }

    /** Depth‑first search that fills `componentId`, computes component sizes
     *  and records border components. */
    private static void discoverComponents() {
        int compCount = 0;
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    compCount++;
                    dfs(r, c, compCount);
                }
            }
        }
        totalComponents = compCount;
    }

    /** Recursive DFS that marks a whole connected region. */
    private static void dfs(int startR, int startC, int id) {
        visited[startR][startC] = true;
        componentId[startR][startC] = id;

        boolean onBorder = startR == 0 || startR == grid.length - 1
                || startC == 0 || startC == grid[0].length - 1;
        if (onBorder) {
            borderComponents.add(id);
        }

        for (int dir = 0; dir < Dx.length; dir++) {
            int nr = startR + Dx[dir];
            int nc = startC + Dy[dir];
            if (isInBounds(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                dfs(nr, nc, id);
            }
        }
    }

    /** Clears every cell belonging to the given component (replaces '.' with '*') */
    private static void clearComponent(int componentIdToClear) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == '.' && componentId[r][c] == componentIdToClear) {
                    grid[r][c] = '*';
                }
            }
        }
    }

    /** Checks whether coordinates are inside the grid and the cell is unvisited '.' */
    private static boolean isInBounds(int x, int y) {
        return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length;
    }

    /** Utility to print the final grid */
    private static void printGrid() {
        for (char[] row : grid) {
            out.print(new String(row));
            out.println();
        }
    }

    /* ------------------------------------------------------------------------
     *  Entry point
     * ------------------------------------------------------------------------ */

    public static void main(String[] args) throws Exception {
        // Increase stack size for deep recursion
        new Thread(null, new Runnable() {
            @Override public void run() {
                try {
                    solve();
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        }, "solution", 1 << 26).start();
    }

    /* ------------------------------------------------------------------------
     *  Global mutable state used only by the algorithm (kept minimal)
     * ------------------------------------------------------------------------ */

    /** Number of discovered connected components */
    private static int totalComponents;

    /** Buffered output used throughout the program */
    private static final PrintWriter out = new PrintWriter(System.out, true);
}

import java.io.IOException;
import java.util.*;

public class Berland {

    /* -------------------------------------------------------------
     *  Constants
     * ------------------------------------------------------------- */
    private static final char LAND = '*';
    private static final char WATER = '.';

    /* -------------------------------------------------------------
     *  Direction vectors (up, down, left, right)
     * ------------------------------------------------------------- */
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    /* -------------------------------------------------------------
     *  Grid and auxiliary structures
     * ------------------------------------------------------------- */
    private static char[][] grid;          // input map with a one‑cell border
    private static boolean[][] visited;    // visited flag for BFS
    private static int rows, cols;         // original dimensions
    private static int lakesToRemove;      // how many lakes must become land

    /* -------------------------------------------------------------
     *  Simple data holder for a discovered lake
     * ------------------------------------------------------------- */
    private static final class Lake {
        final int size;                     // number of water cells
        final List<Point> points;           // coordinates of those cells

        Lake(int size, List<Point> points) {
            this.size = size;
            this.points = points;
        }
    }

    /* -------------------------------------------------------------
     *  Point wrapper used for coordinates
     * ------------------------------------------------------------- */
    private static final class Point {
        final int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
    }

    /* -------------------------------------------------------------
     *  Entry point
     * ------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (Scanner sc = new Scanner(System.in)) {
            readInput(sc);
            List<Lake> lakes = discoverAllLakes();

            // Sort lakes by size – smallest first (the ones we will drain)
            Collections.sort(lakes, Comparator.comparingInt(l -> l.size));

            // Determine which lakes will be turned into land
            List<Point> toConvert = collectLakePoints(lakes,
                    lakes.size() - lakesToRemove);

            // Convert selected lakes and count removed cells
            visited = new boolean[rows + 2][cols + 2];
            int convertedCells = drainLakes(toConvert);

            // Output
            System.out.println(convertedCells);
            printGrid();
        }
    }

    /* -------------------------------------------------------------
     *  Input handling
     * ------------------------------------------------------------- */
    private static void readInput(Scanner sc) {
        // original dimensions + extra border cells
        rows = sc.nextInt();
        cols = sc.nextInt();
        lakesToRemove = sc.nextInt();

        // grid with padding (rows+2 x cols+2) filled with LAND
        grid = new char[rows + 2][cols + 2];
        for (int i = 0; i < grid.length; i++) {
            Arrays.fill(grid[i], LAND);
        }

        // read water/land rows
        for (int r = 1; r <= rows; r++) {
            String line = sc.next();
            for (int c = 1; c <= cols; c++) {
                grid[r][c] = line.charAt(c - 1);
            }
        }

        // visited matrix (same size as padded grid)
        visited = new boolean[grid.length][grid[0].length];
    }

    /* -------------------------------------------------------------
     *  Lake discovery
     * ------------------------------------------------------------- */
    private static List<Lake> discoverAllLakes() {
        List<Lake> lakes = new ArrayList<>();
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] == WATER && !visited[r][c]) {
                    Lake lake = explore(r, c);
                    if (lake != null) {               // lake does NOT touch ocean
                        lakes.add(lake);
                    }
                }
            }
        }
        return lakes;
    }

    /** BFS that returns a Lake object for a water component that does NOT
     *  touch the ocean border. */
    private static Lake explore(int startR, int startC) {
        Queue<Point> q = new LinkedList<>();
        List<Point> component = new ArrayList<>();
        boolean touchesOcean = false;
        q.add(new Point(startR, startC));
        visited[startR][startC] = true;

        while (!q.isEmpty()) {
            Point cur = q.remove();
            component.add(cur);

            // border cells (row 1, row rows, col 1, col cols) are ocean
            if (cur.x == 1 || cur.x == rows || cur.y == 1 || cur.y == cols) {
                touchesOcean = true;
            }

            for (int d = 0; d < 4; d++) {
                int nr = cur.x + DX[d];
                int nc = cur.y + DY[d];
                if (!withinBounds(nr, nc) || visited[nr][nc]) continue;
                if (grid[nr][nc] != WATER) continue;

                visited[nr][nc] = true;
                q.add(new Point(nr, nc));
            }
        }

        // If the component touches the ocean it must stay unchanged.
        return touchesOcean ? null : new Lake(component.size(), component);
    }

    private static boolean withinBounds(int x, int y) {
        return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length;
    }

    /* -------------------------------------------------------------
     *  Collection of cells belonging to lakes that will be drained
     * ------------------------------------------------------------- */
    private static List<Point> collectLakePoints(List<Lake> lakes,
                                                 int numberToRemove) {
        List<Point> result = new ArrayList<>();
        for (int i = 0; i < numberToRemove; i++) {
            result.addAll(lakes.get(i).points);
        }
        return result;
    }

    /* -------------------------------------------------------------
     *  Convert collected water cells into land
     * ------------------------------------------------------------- */
    private static int drainLakes(List<Point> lakesToDrain) {
        visited = new boolean[grid.length][grid[0].length];
        int removed = 0;

        for (Point start : lakesToDrain) {
            if (!visited[start.x][start.y]) {
                bfsConvert(start);
                removed += lakesToDrain.size(); // all cells will be removed,
                                                // but we count per lake to keep
                                                // the semantics identical to the original.
            }
        }
        return removed;
    }

    /** Flood‑fill that marks a whole lake as LAND. */
    private static void bfsConvert(Point origin) {
        Queue<Point> q = new LinkedList<>();
        q.add(origin);
        visited[origin.x][origin.y] = true;
        grid[origin.x][origin.y] = LAND;

        while (!q.isEmpty()) {
            Point cur = q.remove();
            for (int d = 0; d < 4; d++) {
                int nr = cur.x + DX[d];
                int nc = cur.y + DY[d];
                if (withinBounds(nr, nc) && !visited[nr][nc] && grid[nr][nc] == WATER) {
                    visited[nr][nc] = true;
                    grid[nr][nc] = LAND;
                    q.add(new Point(nr, nc));
                }
            }
        }
    }

    /* -------------------------------------------------------------
     *  Output helper
     * ------------------------------------------------------------- */
    private static void printGrid() {
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                System.out.print(grid[r][c]);
            }
            System.out.println();
        }
    }
}

import java.io.PrintWriter;
import java.util.*;
import java.util.function.BiConsumer;
import java.util.stream.Collectors;

/**
 * Refactored version of the original program.
 * The logic is unchanged – it reads a grid, treats ponds as land,
 * groups connected ponds with Union‑Find, then removes the smallest
 * ponds until only {@code k} remain.  The resulting grid is printed.
 */
public class Main {

    /** Entry point – hides the original {@code main} method name. */
    public static void main(String[] args) {
        new Main().execute();
    }

    /** Executes the solution using a {@link Scanner} and a {@link PrintWriter}. */
    private void execute() {
        try (Scanner in = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            solve(1, in, out);
        }
    }

    /**
     * Solves a single test case.
     *
     * @param testNumber dummy – kept only for API compatibility
     * @param in         input source
     * @param out        output destination
     */
    public void solve(int testNumber, Scanner in, PrintWriter out) {
        /* ----- read parameters ------------------------------------------------ */
        final int n = in.nextInt();   // rows
        final int m = in.nextInt();   // columns
        final int k = in.nextInt();   // number of lakes to keep
        in.nextLine();                // consume end‑of‑line

        /* ----- read the grid --------------------------------------------------- */
        boolean[][] grid = readInputGrid(in, n, m);

        /* ----- prepare Union‑Find structure ------------------------------------ */
        UnionFind uf = buildUnionFind(n, m);

        /* ----- connect neighboring land cells --------------------------------- */
        connectLandNeighbors(grid, uf, n, m);

        /* ----- connect border cells to a special “sink” component ----------- */
        connectBordersToSink(grid, uf, n, m);

        /* ----- compute sizes of each component (lake) ------------------------ */
        int[] componentSizes = computeComponentSizes(uf, n, m);

        /* ----- remove the smallest lakes until only k remain ----------------- */
        int filledCount = removeSmallestLakes(grid, uf, componentSizes, k, n, m, out);

        /* ----- output ---------------------------------------------------------- */
        out.println(filledCount);
        printResultGrid(grid, out);
    }

    /* --------------------------- input helpers ------------------------------ */

    private boolean[][] readInputGrid(Scanner in, int rows, int cols) {
        boolean[][] map = new boolean[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = in.nextLine();
            for (int c = 0; c < cols; c++) {
                map[r][c] = line.charAt(c) == '.';
            }
        }
        return map;
    }

    private UnionFind buildUnionFind(int rows, int cols) {
        // n*m cells + 1 extra component used as a “sink”
        return new UnionFind(rows * cols + 1);
    }

    /* --------------------------- union‑find utilities ----------------------- */

    private static class UnionFind {
        private final int[] parent;
        private final int[] rank;

        UnionFind(int size) {
            this.parent = new int[size];
            this.rank   = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
            }
        }

        /** Path‑compressed find. */
        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        /** Union by rank. */
        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;

            if (rank[ra] > rank[rb]) {
                parent[rb] = ra;
            } else if (rank[ra] < rank[rb]) {
                parent[ra] = rb;
            } else {
                parent[rb] = ra;
                rank[ra]++;
            }
        }
    }

    /* --------------------------- graph construction ----------------------- */

    private void connectLandNeighbors(boolean[][] grid, UnionFind uf, int n, int m) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (!grid[r][c]) continue; // water cells are ignored here

                // down neighbour
                if (r + 1 < n && grid[r + 1][c]) {
                    uf.union(r * m + c, (r + 1) * m + c);
                }
                // right neighbour
                if (c + 1 < m && grid[r][c + 1]) {
                    uf.union(r * m + c, r * m + (c + 1));
                }
            }
        }
    }

    private void connectBordersToSink(boolean[][] grid, UnionFind uf, int n, int m) {
        final int SINK = n * m; // index reserved for the artificial sink

        // top & bottom rows
        for (int r = 0; r < n; r++) {
            unionToSink(r, 0, uf, SINK, n, m);
            unionToSink(r, m - 1, uf, SINK, n, m);
        }
        // left & right columns
        for (int c = 0; c < m; c++) {
            unionToSink(0, c, uf, SINK, n, m);
            unionToSink(n - 1, c, uf, SINK, n, m);
        }
    }

    private void unionToSink(int row, int col, UnionFind uf, int sinkIdx, int n, int m) {
        int cellId = row * m + col;
        uf.union(cellId, sinkIdx);
    }

    /* --------------------------- size computation -------------------------- */

    private int[] computeComponentSizes(UnionFind uf, int n, int m) {
        int[] size = new int[n * m + 1]; // +1 for sink component
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                size[uf.find(i * m + j)]++;
            }
        }
        // size[SINK] is irrelevant – we keep it for API simplicity
        return size;
    }

    /* --------------------------- lake removal logic ----------------------- */

    private int removeSmallestLakes(boolean[][] grid,
                                    UnionFind uf,
                                    int[] componentSizes,
                                    int keepCount,
                                    int n,
                                    int m,
                                    PrintWriter out) {

        // Build a map: component‑root -> size (ignore the sink component)
        Map<Integer, Integer> rootToSize = new HashMap<>();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                int root = uf.find(r * m + c);
                rootToSize.merge(root, 1, Integer::sum);
            }
        }
        rootToSize.remove(n * m); // delete sink entry

        // Sort components by size (ascending) – smallest lakes first
        List<Map.Entry<Integer, Integer>> sorted = new ArrayList<>(rootToSize.entrySet());
        sorted.sort(Map.Entry.<Integer, Integer>comparing(entry -> entry.getValue()));

        int lakesToErase = rootToSize.size() - keepCount;
        int filledCells = 0;

        for (Map.Entry<Integer, Integer> entry : sorted) {
            if (lakesToErase-- <= 0) break;

            int componentId = entry.getKey();

            // Fill every cell belonging to this component
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (uf.find(r * m + c) == componentId) {
                        grid[r][c] = false; // convert land → water (marked '*')
                        filledCells++;
                    }
                }
            }
        }

        return filledCells;
    }

    /* --------------------------- output helpers --------------------------- */

    private void printResultGrid(boolean[][] grid, PrintWriter out) {
        StringBuilder sb = new StringBuilder();
        for (boolean[] row : grid) {
            sb.setLength(0);
            for (boolean cell : row) {
                sb.append(cell ? '.' : '*');
            }
            out.println(sb);
        }
    }
}

/**
 * Lake Processor – reads a map of land ( '#' ) and water ( '.' ),
 * finds all lakes, removes the smallest ones until exactly k lakes
 * remain and prints the total number of cells removed.
 *
 * Refactored for readability, maintainability and proper encapsulation.
 */
import java.io.*;
import java.util.*;

public class LakeProcessor {

    /* --------------------------------------------------------------------- */
    /*  Constants & helpers                                                  */
    /* --------------------------------------------------------------------- */
    private static final int COL = 0;
    private static final int ROW = 1;
    private static final int SIZE = 2;

    /** 4‑direction vectors (up, down, left, right). */
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    /** Fast scanner / printer used by the original template. */
    private static BufferedReader reader;
    private static PrintWriter writer;

    /** Simple holder for a lake – stores its top‑left coordinate and size. */
    private static final class Lake implements Comparable<Lake> {
        final int row;               // row index of the first cell (y)
        final int col;               // column index of the first cell (x)
        final int size;              // number of cells belonging to the lake

        Lake(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public int compareTo(Lake o) {
            // sort lakes by size (ascending) – the smallest lakes first
            return Integer.compare(this.size, o.size);
        }
    }

    /** Reads the next token from {@link #reader}. */
    private static String nextToken() throws IOException {
        while (stoken == null || !stoken.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            stoken = new StringTokenizer(line);
        }
        return stoken.nextToken();
    }

    /** Convenience wrappers for the primitive type readers. */
    private static int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
    private static long nextLong() throws IOException { return Long.parseLong(nextToken()); }
    private static double nextDouble() throws IOException { return Double.parseDouble(nextToken()); }
    private static String next() throws IOException { return nextToken(); }
    private static String nextLine() throws IOException { return reader.readLine(); }

    /** Finds the lake that starts at (col, row) and floods it, marking visited
     *  cells with '*'. Returns a {@link Lake} object describing the flooded
     *  area, or {@code null} if the cell is out of bounds or already visited. */
    private static Lake flood(char[][] grid, int startCol, int startRow) {
        if (grid[startRow][startCol] != '.') {
            return null;
        }

        int rows = grid.length;
        int cols = grid[0].length;

        Deque<int[]> queue = new ArrayDeque<>();
        queue.addLast(new int[]{startCol, startRow});

        // mark the start cell as visited
        grid[startRow][startCol] = '*';

        Lake lake = new Lake(startRow, startCol, 0);

        while (!queue.isEmpty()) {
            int[] cur = queue.removeFirst();
            int r = cur[ROW];
            int c = cur[COL];
            lake.size++; // count current cell

            for (int[] d : DIRS) {
                int nr = r + d[ROW];
                int nc = c + d[COL];

                if (nc < 0 || nc >= cols || nr < 0 || nr >= rows) {
                    // stepping outside the grid – the whole lake is invalid
                    return null;
                }
                if (grid[nr][nc] == '.') {
                    grid[nr][nc] = '*';          // mark visited
                    queue.addLast(new int[]{nc, nr});
                }
            }
        }
        return lake;
    }

    /** Main algorithm driver. */
    public static void main(String[] args) throws Exception {
        // -----------------------------------------------------------------
        //  Input fast‑reader setup (mirrors the original template)
        // -----------------------------------------------------------------
        reader = new BufferedReader(new InputStreamReader(System.in));
        stoken = null;                     // tokeniser for the current line
        writer = new PrintWriter(new BufferedOutputStream(System.out));

        // -----------------------------------------------------------------
        //  Read problem parameters
        // -----------------------------------------------------------------
        int n = nextInt();                 // number of rows
        int m = nextInt();                 // number of columns
        int k = nextInt();                 // required number of lakes to keep

        // -----------------------------------------------------------------
        //  Read the map – store both the original (for printing later) and
        //  a mutable copy used for flood‑filling.
        // -----------------------------------------------------------------
        char[][] original = new char[n][];
        char[][] workCopy = new char[n][];

        for (int r = 0; r < n; r++) {
            String line = next();
            char[] row = line.toCharArray();
            original[r] = row;
            workCopy[r] = Arrays.copyOf(row, m);
        }

        // -----------------------------------------------------------------
        //  Discover all lakes and collect them in a list
        // -----------------------------------------------------------------
        List<Lake> lakes = new ArrayList<>();

        for (int r = 0; r < n; r++) {
            char[] row = workCopy[r];
            for (int c = 0; c < m; c++) {
                if (row[c] == '.') {
                    Lake lake = flood(workCopy, c, r);
                    if (lake != null) {
                        lakes.add(lake);
                    }
                }
            }
        }

        // -----------------------------------------------------------------
        //  Sort lakes by size (smallest first) and remove the excess ones
        // -----------------------------------------------------------------
        Collections.sort(lakes); // uses Lake#compareTo (size ascending)

        long removedCells = 0;
        while (lakes.size() > k) {
            Lake smallest = lakes.remove(0);
            removedCells += smallest.size;
        }

        // -----------------------------------------------------------------
        //  Output
        // -----------------------------------------------------------------
        writer.println(removedCells);
        for (char[] row : original) {
            writer.println(new String(row));
        }

        // -----------------------------------------------------------------
        //  Clean up
        // -----------------------------------------------------------------
        writer.flush();
        reader.close();
        System.err.println("\n[Time : " + (System.currentTimeMillis() - startTime) + " ms]");
    }

    // -----------------------------------------------------------------
    //  Boiler‑plate fast‑io helpers (kept identical to the original)
    // -----------------------------------------------------------------
    private static StringTokenizer stoken;

    /* The following print/println methods are only used by the original
       template for debugging / optional output; they are kept unchanged
       but are not required for the core algorithm. */
    private static void print(byte b) { print("" + b); }
    private static void print(int i) { print("" + i); }
    private static void print(long l) { print("" + l); }
    private static void print(double d) { print("" + d); }
    private static void print(char c) { print("" + c); }
    private static void print(Object o) {
        if (o instanceof int[]) { print(Arrays.toString((int[]) o)); }
        else if (o instanceof long[]) { print(Arrays.toString((long[]) o)); }
        else if (o instanceof char[]) { print(Arrays.toString((char[]) o)); }
        else if (o instanceof byte[]) { print(Arrays.toString((byte[]) o)); }
        else if (o instanceof short[]) { print(Arrays.toString((short[]) o)); }
        else if (o instanceof boolean[]) { print(Arrays.toString((boolean[]) o)); }
        else if (o instanceof float[]) { print(Arrays.toString((float[]) o)); }
        else if (o instanceof double[]) { print(Arrays.toString((double[]) o)); }
        else if (o instanceof Object[]) { print(Arrays.toString((Object[]) o)); }
        else { print("" + o); }
    }
    private static void print(String s) { writer.print(s); }
    private static void println() { println(""); }
    private static void println(byte b) { println("" + b); }
    private static void println(int i) { println("" + i); }
    private static void println(long l) { println("" + l); }
    private static void println(double d) { println("" + d); }
    private static void println(char c) { println("" + c); }
    private static void println(Object o) { print(o); println(); }
    private static void println(String s) { writer.println(s); }
    private static int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
    private static long nextLong() throws IOException { return Long.parseLong(nextToken()); }
    private static double nextDouble() throws IOException { return Double.parseDouble(nextToken()); }
    private static char nextChar() throws IOException { return (char) (reader.read()); }
    private static String next() throws IOException { return nextToken(); }
    private static String nextLine() throws IOException { return reader.readLine(); }
    private static int[] readInt(int size) throws IOException {
        int[] array = new int[size];
        for (int i = 0; i < size; i++) { array[i] = nextInt(); }
        return array;
    }
    private static long[] readLong(int size) throws IOException {
        long[] array = new long[size];
        for (int i = 0; i < size; i++) { array[i] = nextLong(); }
        return array;
    }
    private static double[] readDouble(int size) throws IOException {
        double[] array = new double[size];
        for (int i = 0; i < size; i++) { array[i] = nextDouble(); }
        return array;
    }
    private static String[] readLines(int size) throws IOException {
        String[] array = new String[size];
        for (int i = 0; i < size; i++) { array[i] = nextLine(); }
        return array;
    }

    private static int gcd(int a, int b) {
        return (b > 0) ? gcd(b, a % b) : a;
    }

    // -----------------------------------------------------------------
    //  static timer field used only for the optional debug message
    // -----------------------------------------------------------------
    private static long startTime = System.currentTimeMillis();
}

import java.awt.Point;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Reads a grid of land ( '*') and water ( '.' ), removes the smallest lakes
 * that are not connected to the border until only {@code k} lakes remain.
 * The total number of removed cells and the resulting grid are printed.
 */
public class LakeRemover {

    /** Symbol used for land after a lake is removed. */
    private static final char LAND = '*';
    /** Symbol used for water in the original input. */
    private static final char WATER = '.';

    /** Four movement directions (left, right, up, down). */
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {-1, 1, 0, 0};

    public static void main(String[] args) throws IOException {
        // ---- input -------------------------------------------------------------
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] header = br.readLine().split("\\s+");
            int rows = Integer.parseInt(header[0]);
            int cols = Integer.parseInt(header[1]);
            int lakesToRemove = Integer.parseInt(header[2]);

            char[][] grid = new char[rows][];
            boolean[][] visited = new boolean[rows][cols];

            for (int r = 0; r < rows; r++) {
                grid[r] = br.readLine().toCharArray();
            }

            // ---- discover all interior lakes ------------------------------------
            List<Lake> lakes = discoverInteriorLakes(grid, visited);
            Collections.sort(lakes); // smallest first

            // ---- remove the required number of lakes ----------------------------
            int removedCellCount = 0;
            int removedLakes = 0;
            for (Lake lake : lakes) {
                if (removedLakes >= lakesToRemove) {
                    break;
                }
                removedCellCount += lake.cells.size();
                for (Point p : lake.cells) {
                    grid[p.x][p.y] = LAND;
                }
                removedLakes++;
            }

            // ---- output -----------------------------------------------------------
            StringBuilder sb = new StringBuilder();
            sb.append(removedCellCount).append('\n');
            for (char[] row : grid) {
                sb.append(row).append('\n');
            }
            System.out.print(sb);
        }
    }

    /** Finds all lakes that do NOT touch the outer border. */
    private static List<Lake> discoverInteriorLakes(char[][] grid,
                                                    boolean[][] visited) {
        List<Lake> lakes = new ArrayList<>();
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (!visited[r][c] && grid[r][c] == WATER) {
                    List<Point> component = new ArrayList<>();
                    boolean touchesBorder = explore(r, c, grid, visited, component);
                    if (!touchesBorder) {
                        lakes.add(new Lake(component));
                    }
                }
            }
        }
        return lakes;
    }

    /** Depth‑first search that records visited cells and detects border contact. */
    private static boolean explore(int startR, int startC,
                                   char[][] grid,
                                   boolean[][] visited,
                                   List<Point> collector) {
        if (isBorder(startR, startC, grid.length, grid[0].length)) {
            return true;                 // lake touches the border
        }
        visited[startR][startC] = true;
        collector.add(new Point(startR, startC));

        for (int d = 0; d < DX.length; d++) {
            int nr = startR + DX[d];
            int nc = startC + DY[d];
            if (inBounds(nr, nc, grid.length, grid[0].length)
                    && !visited[nr][nc]
                    && grid[nr][nc] == WATER) {
                explore(nr, nc, grid, visited, collector);
            }
        }
        return false;                    // never hit a border cell
    }

    /** Checks whether a cell lies on the outermost rows or columns. */
    private static boolean isBorder(int r, int c, int rows, int cols) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    /** Simple bounds check. */
    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Minimal description of a lake. */
    private static final class Lake implements Comparable<Lake> {
        /** All coordinates belonging to the lake. */
        final List<Point> cells;
        /** Convenience shortcut to lake size. */
        final int size;

        Lake(List<Point> cells) {
            this.cells = cells;
            this.size = cells.size();
        }

        @Override
        public int compareTo(Lake o) {
            return Integer.compare(this.size, o.size);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final int[] DX = {-1, 0, 0, 1};
    private static final int[] DY = {0, -1, 1, 0};

    public static void main(String[] args) throws IOException {
        try (InputReader reader = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            new TaskB().solve(reader, out);
        }
    }

    static class TaskB {
        private char[][] grid;
        private boolean[][] visited;
        private int[][] componentId;
        private int rows, cols;
        private int nextId;
        private List<Component> components;
        private int k;

        public void solve(InputReader in, PrintWriter out) {
            readInput(in);
            markBorderComponents();
            discoverInnerComponents();
            List<Integer> idsToMark = selectIdsToMark();
            int markedCount = markCells(out, idsToMark);
            out.println(markedCount);
            printResultGrid(out);
        }

        private void readInput(InputReader in) {
            rows = in.nextInt();
            cols = in.nextInt();
            k = in.nextInt();
            grid = new char[rows];
            visited = new boolean[rows][];
            componentId = new int[rows][];
            for (int i = 0; i < rows; i++) {
                String line = in.next();
                grid[i] = line.toCharArray();
                visited[i] = new boolean[cols];
                componentId[i] = new int[cols];
            }
        }

        private void markBorderComponents() {
            for (int i = 0; i < rows; i++) {
                if (!visited[i][0] && grid[i][0] == '.') dfsMark(i, 0);
                if (!visited[i][cols - 1] && grid[i][cols - 1] == '.') dfsMark(i, cols - 1);
            }
            for (int j = 0; j < cols; j++) {
                if (!visited[0][j] && grid[0][j] == '.') dfsMark(0, j);
                if (!visited[rows - 1][j] && grid[rows - 1][j] == '.') dfsMark(rows - 1, j);
            }
        }

        private void dfsMark(int r, int c) {
            visited[r][c] = true;
            for (int d = 0; d < 4; d++) {
                int nr = r + DX[d];
                int nc = c + DY[d];
                if (inBounds(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                    dfsMark(nr, nc);
                }
            }
        }

        private void discoverInnerComponents() {
            components = new ArrayList<>();
            nextId = 1;
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (!visited[i][j] && grid[i][j] == '.') {
                        int size = dfsDiscover(i, j);
                        components.add(new Component(nextId++, size));
                    }
                }
            }
        }

        private int dfsDiscover(int r, int c) {
            visited[r][c] = true;
            componentId[r][c] = nextId;
            int size = 1;
            for (int d = 0; d < 4; d++) {
                int nr = r + DX[d];
                int nc = c + DY[d];
                if (inBounds(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                    size += dfsDiscover(nr, nc);
                }
            }
            return size;
        }

        private List<Integer> selectIdsToMark() {
            components.sort(Comparator.comparingInt(c -> c.size));
            int total = components.size();
            int keep = Math.max(0, total - k);
            List<Integer> toMark = new ArrayList<>();
            for (int i = 0; i < keep; i++) {
                toMark.add(components.get(i).id);
            }
            return toMark;
        }

        private int markCells(PrintWriter out, List<Integer> ids) {
            int marked = 0;
            char[][] result = cloneGrid();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] != '.' ) continue;
                    int cid = componentId[i][j];
                    if (cid != 0 && ids.contains(cid)) {
                        result[i][j] = '*';
                        marked++;
                    }
                }
            }
            System.arraycopy(result, 0, grid, 0, rows * cols);
            return marked;
        }

        private char[][] cloneGrid() {
            char[][] copy = new char[rows][];
            for (int i = 0; i < rows; i++) copy[i] = grid[i].clone();
            return copy;
        }

        private void printResultGrid(PrintWriter out) {
            for (char[] row : grid) {
                out.print(row);
                out.println();
            }
        }

        private boolean inBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private static class Component {
            final int id;
            final int size;
            Component(int id, int size) {
                this.id = id;
                this.size = size;
            }
        }
    }

    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(nextLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for Codeforces problem 375D – «Лаки».
 *
 * The program:
 *   1. Reads a grid of characters ('.' – water, '*' – land, '~' – border).
 *   2. Finds all lakes (maximal connected components of '.').
 *   3. Sorts lakes by size (ascending) and fills the smallest ones
 *      until exactly {@code k} lakes remain.
 *   4. Prints the total number of water cells that were turned into land
 *      and outputs the final map where filled lakes are represented by '*'
 *      and all other cells stay unchanged.
 *
 * The implementation uses clear naming, proper encapsulation and
 * avoids recursion, magic numbers and mutable global state.
 */
public class CF375D {

    /** Directions used for neighbour exploration (up, down, left, right). */
    private static final int[][] NEIGHBOURS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Temporary character that marks a cell visited during lake discovery. */
    private static final char MARK_VISITED = 'v';

    /** Temporary character that marks a cell that will become land later. */
    private static final char MARK_FILLED = ',';

    /** Final character used to represent land after filling lakes. */
    private static final char LAND = '*';

    /** Simple data class that stores information about a lake. */
    private static final class Lake {
        /** Size (number of water cells) of the lake. */
        final int size;
        /** Coordinate of any cell belonging to the lake – used for later filling. */
        final int row;
        final int col;

        Lake(int size, int row, int col) {
            this.size = size;
            this.row = row;
            this.col = col;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        final Scanner scanner = new Scanner(System.in);

        final int n = scanner.nextInt();   // number of rows
        final int m = scanner.nextInt();   // number of columns
        final int k = scanner.nextInt();   // required number of lakes

        scanner.nextLine();                  // consume end‑of‑line

        // -----------------------------------------------------------------
        // Build the grid with an additional border of '~' characters.
        // -----------------------------------------------------------------
        final char[][] grid = new char[n + 2][m + 2];
        fillBorder(grid, '~');

        for (int r = 1; r <= n; r++) {
            String line = scanner.nextLine();
            for (int c = 1; c <= m; c++) {
                grid[r][c] = line.charAt(c - 1);
            }
        }

        // -----------------------------------------------------------------
        // Discover all lakes (connected components consisting of '.').
        // -----------------------------------------------------------------
        final List<Lake> lakes = new ArrayList<>();
        final boolean[][] visited = new boolean[n + 2][m + 2];

        for (int r = 1; r <= n; r++) {
            for (int c = 1; c <= m; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    final Lake lake = exploreLake(grid, visited, r, c);
                    lakes.add(lake);
                }
            }
        }

        // -----------------------------------------------------------------
        // Sort lakes by size (ascending) – the smallest lakes will be filled first.
        // -----------------------------------------------------------------
        lakes.sort(Comparator.comparingInt(l -> l.size));

        // -----------------------------------------------------------------
        // Determine how many lakes must be converted to land.
        // -----------------------------------------------------------------
        final int totalLakes = lakes.size();
        final int toFill = Math.max(0, totalLakes - k);

        // -----------------------------------------------------------------
        // Compute answer and mark cells that become land.
        // -----------------------------------------------------------------
        long answer = 0;
        for (int i = 0; i < toFill; i++) {
            final Lake lake = lakes.get(i);
            answer += lake.size;
            fillLake(grid, lake.row, lake.col);
        }

        // -----------------------------------------------------------------
        // Output answer.
        // -----------------------------------------------------------------
        System.out.println(answer);

        // -----------------------------------------------------------------
        // Print the final map – filled lakes become '*', everything else stays the same.
        // -----------------------------------------------------------------
        for (int r = 1; r <= n; r++) {
            StringBuilder sb = new StringBuilder();
            for (int c = 1; c <= m; c++) {
                char ch = grid[r][c];
                sb.append(ch == MARK_FILLED ? LAND : ch);
            }
            System.out.println(sb);
        }
    }

    /** Fill the outer border of the grid with the given character. */
    private static void fillBorder(char[][] grid, char ch) {
        final int rows = grid.length;
        final int cols = grid[0].length;
        for (int r = 0; r < rows; r++) {
            grid[r][0] = ch;
            grid[r][cols - 1] = ch;
        }
        for (int c = 0; c < cols; c++) {
            grid[0][c] = ch;
            grid[rows - 1][c] = ch;
        }
    }

    /** Breadth‑first search that discovers a lake starting from (startR, startC). */
    private static Lake exploreLake(char[][] grid, boolean[][] visited, int startR, int startC) {
        final Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startR, startC});
        visited[startR][startC] = true;

        int size = 0;
        int savedR = startR;
        int savedC = startC;

        while (!queue.isEmpty()) {
            final int[] cur = queue.poll();
            final int r = cur[0];
            final int c = cur[1];
            size++;

            // Remember the first cell – any cell works for later filling.
            if (size == 1) {
                savedR = r;
                savedC = c;
            }

            // Explore neighbours.
            for (final int[] dir : NEIGHBOURS) {
                final int nr = r + dir[0];
                final int nc = c + dir[1];
                if (grid[nr][nc] != '.' || visited[nr][nc]) {
                    continue;
                }
                visited[nr][nc] = true;
                queue.add(new int[]{nr, nc});
            }
        }

        // Mark visited '.' cells with a temporary character so they are not processed again.
        markVisited(grid, visited);
        return new Lake(size, savedR, savedC);
    }

    /** Mark all visited water cells with {@link #MARK_VISITED}. */
    private static void markVisited(char[][] grid, boolean[][] visited) {
        for (int r = 1; r < visited.length - 1; r++) {
            for (int c = 1; c < visited[0].length - 1; c++) {
                if (grid[r][c] == '.' && visited[r][c]) {
                    grid[r][c] = MARK_VISITED;
                }
            }
        }
    }

    /** Turn an entire lake into land using iterative BFS. The start cell must belong to the lake. */
    private static void fillLake(char[][] grid, int startR, int startC) {
        final Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startR, startC});
        grid[startR][startC] = MARK_FILLED;

        while (!queue.isEmpty()) {
            final int[] cur = queue.poll();
            final int r = cur[0];
            final int c = cur[1];

            for (final int[] dir : NEIGHBOURS) {
                final int nr = r + dir[0];
                final int nc = c + dir[1];
                if (grid[nr][nc] == '.') {
                    grid[nr][nc] = MARK_FILLED;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
    }
}

import java.util.*;
import java.util.stream.Collectors;

/**
 * Refactored version of the original program.
 * The functionality is unchanged – it finds “lakes” (connected pools of '.'
 * that do not touch the border), removes the smallest lakes until only {@code keep}
 * lakes remain, counts the replaced cells and prints the resulting map.
 */
public class Main {

    /** Symbol used for land after a lake is removed. */
    private static final char LAND = '*';
    /** Symbol used for water in the input map. */
    private static final char WATER = '.';

    /**
     * Simple immutable pair that represents a cell coordinate.
     * Proper {@code equals} and {@code hashCode} are implemented so that
     * {@code Pair} instances can be stored in {@code Set}s and {@code HashSet}s.
     */
    private static final class Pair {
        private final int x;
        private final int y;

        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Pair)) return false;
            Pair pair = (Pair) o;
            return x == pair.x && y == pair.y;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }

        @Override
        public String toString() {
            return "(" + x + "," + y + ")";
        }
    }

    /**
     * Encapsulates the logic for discovering lakes in the grid.
     * All state related to a particular grid is kept here, keeping the
     * {@code main} method tidy.
     */
    private static final class LakeFinder {
        private final int rows;
        private final int cols;
        private final List<StringBuilder> grid;
        private final Set<Pair> visited = new HashSet<>();
        private final List<Set<Pair>> lakes = new ArrayList<>();

        LakeFinder(int rows, int cols, List<StringBuilder> grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /** Returns all lakes that do **not** touch the outer border. */
        List<Set<Pair>> findLakes() {
            // Collect every water cell once.
            List<Pair> waterPoints = new ArrayList<>();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid.get(i).charAt(j) == WATER) {
                        waterPoints.add(new Pair(i, j));
                    }
                }
            }

            // Run DFS from each unvisited water cell.
            for (Pair point : waterPoints) {
                if (visited.contains(point)) {
                    continue;
                }
                Set<Pair> currentLake = new HashSet<>();
                boolean touchesBorder = false;
                dfs(point, currentLake, touchesBorder);
                if (!touchesBorder) {
                    lakes.add(currentLake);
                }
            }
            return lakes;
        }

        /** Depth‑first search that fills {@code currentLake} and updates {@code touchesBorder}. */
        private void dfs(Pair cur, Set<Pair> currentLake, boolean[] borderFlag) {
            visited.add(cur);
            currentLake.add(cur);

            // If any cell of the lake lies on the border, the whole lake is considered a border lake.
            if (cur.x == 0 || cur.x == rows - 1 || cur.y == 0 || cur.y == cols - 1) {
                borderFlag[0] = true;
            }

            for (Pair neighbour : getNeighbours(cur)) {
                if (isWater(neighbour.x, neighbour.y) && !visited.contains(neighbour)) {
                    dfs(neighbour, currentLake, borderFlag);
                }
            }
        }

        /** Checks whether a given coordinate holds water ('.'). */
        private boolean isWater(int x, int y) {
            return grid.get(x).charAt(y) == WATER;
        }

        /** Returns the four orthogonal neighbours of a cell, bounded by the grid size. */
        private List<Pair> getNeighbours(Pair p) {
            int[] dx = {-1, 1, 0, 0};
            int[] dy = {0, 0, -1, 1};
            List<Pair> neighbours = new ArrayList<>(4);
            for (int i = 0; i < 4; i++) {
                int nx = p.x + dx[i];
                int ny = p.y + dy[i];
                if (nx >= 0 && nx < rows && ny >= 0 && ny < cols) {
                    neighbours.add(new Pair(nx, ny));
                }
            }
            return neighbours;
        }
    }

    /** Entry point – reads input, processes the map and prints the result. */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();          // number of rows
        int m = scanner.nextInt();          // number of columns
        int keep = scanner.nextInt();       // number of lakes we want to keep
        scanner.nextLine();                 // consume the rest of the line

        // Store the map in mutable StringBuilder objects so we can replace '.' with '*'.
        List<StringBuilder> grid = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            grid.add(new StringBuilder(scanner.nextLine()));
        }

        // Discover all interior lakes.
        LakeFinder finder = new LakeFinder(n, m, grid);
        List<Set<Pair>> lakes = finder.findLakes();

        // Repeatedly remove the smallest lake until only {@code keep} lakes remain.
        int removedCells = 0;
        while (lakes.size() > keep) {
            Set<Pair> smallestLake = lakes.stream()
                                        .min(Comparator.comparingInt(Set::size))
                                        .orElseThrow();

            removedCells += smallestLake.size();
            for (Pair cell : smallestLake) {
                grid.get(cell.x).setCharAt(cell.y, LAND);
            }
            lakes.remove(smallestLake);
        }

        // Output the number of replaced cells and the final map.
        System.out.println(removedCells);
        for (StringBuilder row : grid) {
            System.out.println(row);
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Entry point of the application.
 */
public class Lakes {

    public static void main(String[] args) {
        InputStream in = System.in;
        OutputStream out = System.out;

        try (BufferedReader br = new BufferedReader(new InputStreamReader(in))) {
            solve(br, new PrintWriter(out));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Solves one test case.
     *
     * @param br  a buffered reader that supplies the input
     * @param pw  a print writer that receives the output
     */
    private static void solve(BufferedReader br, PrintWriter pw) throws IOException {
        int n = nextInt(br);
        int m = nextInt(br);
        int k = nextInt(br);

        List<String> grid = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            grid.add(br.readLine());
        }

        LakeProcessor processor = new LakeProcessor(n, m, k, grid);
        int removedSum = processor.removeKSmallestLakes();

        pw.println(removedSum);
        List<String> outputGrid = processor.buildOutputGrid();
        outputGrid.forEach(pw::println);
    }

    /** Helper that reads the next token from a buffered reader. */
    private static String nextToken(BufferedReader br) throws IOException {
        String line;
        while (true) {
            line = br.readLine();
            if (line == null || !line.isBlank()) {
                break;
            }
        }
        StringTokenizer st = new StringTokenizer(line);
        return st.nextToken();
    }

    /** Helper that returns the next integer from a buffered reader. */
    private static int nextInt(BufferedReader br) throws IOException {
        return Integer.parseInt(nextToken(br));
    }
}

/**
 * Core logic for finding lakes, deciding which ones to remove and
 * producing the final grid representation.
 */
final class LakeProcessor {

    private final int rows;
    private final int cols;
    private final int lakesToRemove;
    private final List<String> originalGrid;
    private final char[][] processed;          // mutable view of the grid
    private final boolean[][] visited;

    // four cardinal directions
    private static final int[][] DIRS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    LakeProcessor(int rows, int cols, int lakesToRemove, List<String> originalGrid) {
        this.rows = rows;
        this.cols = cols;
        this.lakesToRemove = lakesToRemove;
        this.originalGrid = Objects.requireNonNull(originalGrid);
        this.processed = new char[rows][cols];
        this.visited = new boolean[rows][cols];
        copyGridToProcessed();
    }

    /**
     * Returns the sum of the sizes of the lakes that are removed
     * (the k smallest lakes that do not touch the border).
     */
    int removeKSmallestLakes() {
        List<Lake> lakes = discoverLakes();

        // keep only the lakes that are *not* border lakes
        List<Lake> nonBorderLakes = lakes.stream()
                .filter(lake -> !lake.isBorderLake())
                .sorted(Comparator.comparingInt(l -> l.size))
                .collect(Collectors.toList());

        // Determine which lakes are actually removed
        int limit = Math.min(lakesToRemove, nonBorderLakes.size());
        Set<Lake> removed = new HashSet<>();
        for (int i = 0; i < limit; i++) {
            removed.add(nonBorderLakes.get(i));
        }

        // Mark removed cells in the processed view
        for (Lake lake : removed) {
            lake.cells.forEach(coord -> processed[coord.row][coord.col] = '*');
        }

        // Store removal information for later reconstruction
        return removed.stream().mapToInt(l -> l.size).sum();
    }

    /** Creates a mutable copy of the original grid. */
    private void copyGridToProcessed() {
        for (int r = 0; r < rows; r++) {
            char[] rowCopy = originalGrid.get(r).toCharArray();
            for (int c = 0; c < cols; c++) {
                processed[r][c] = rowCopy[c];
            }
        }
    }

    /**
     * Scans the interior of the grid, discovers all lakes and returns them.
     */
    private List<Lake> discoverLakes() {
        List<Lake> lakes = new ArrayList<>();

        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isLand(r, c) && !visited[r][c]) {
                    Lake lake = exploreLake(r, c);
                    lakes.add(lake);
                }
            }
        }
        return lakes;
    }

    /** Returns true if the cell contains water ('.'). */
    private boolean isLand(int r, int c) {
        return processed[r][c] == '.';
    }

    /**
     * Depth‑first search that gathers all cells belonging to the same lake.
     *
     * @return a {@link Lake} object describing the discovered lake.
     */
    private Lake exploreLake(int startR, int startC) {
        Deque<Point> stack = new ArrayDeque<>();
        Set<Point> cells = new HashSet<>();
        boolean touchesBorder = false;

        stack.push(new Point(startR, startC));
        visited[startR][startC] = true;

        while (!stack.isEmpty()) {
            Point cur = stack.pop();
            cells.add(cur);
            if (onBorder(cur.row, cur.col)) {
                touchesBorder = true;
            }

            for (int[][] dir : DIRS) {
                int nr = cur.row + dir[0][0];
                int nc = cur.col + dir[0][1];
                if (!inBounds(nr, nc)) {
                    continue;
                }
                if (visited[nr][nc] || !isLand(nr, nc)) {
                    continue;
                }
                visited[nr][nc] = true;
                stack.push(new Point(nr, nc));
            }
        }
        return new Lake(cells, touchesBorder);
    }

    /** Simple helper class that stores the set of lake cells and
     *  whether the lake touches the outer border. */
    private static final class Lake {
        final Set<Point> cells;
        final boolean isBorderLake;

        Lake(Set<Point> cells, boolean isBorderLake) {
            this.cells = cells;
            this.isBorderLake = isBorderLake;
        }
    }

    /** Simple point holder with proper equals/hashCode for set handling. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            return (o instanceof Point) && ((Point) o).row == row && ((Point) o).col == col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    /** Returns true if the supplied coordinate is inside the matrix. */
    private boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Returns true if the coordinate lies on the outer rim of the matrix. */
    private boolean onBorder(int r, int c) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    /**
     * Constructs the final grid representation:
     *   - cells belonging to removed lakes become '*'
     *   - all other cells keep their original character
     */
    List<String> buildOutputGrid() {
        List<StringBuilder> builders = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            builders.add(new StringBuilder(cols));
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char ch = processed[r][c];
                if (ch == '*') {
                    builders.get(r).append('*');
                } else if (originalGrid.get(r).charAt(c) == '*') {
                    builders.get(r).append('*');
                } else {
                    builders.get(r).append('.');
                }
            }
        }

        return builders.stream()
                .map(StringBuilder::toString)
                .collect(Collectors.toList());
    }
}

import java.io.*;
import java.util.*;

public class P11_Div2_723D {

    /**
     * Represents a lake – a connected component of '.' cells that does NOT touch the border.
     * Lakes are compared by their size (ascending order).
     */
    private static final class Lake implements Comparable<Lake> {
        final int row;   // representative row of the lake
        final int col;   // representative column of the lake
        final int size;  // number of cells in the lake

        Lake(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public int compareTo(Lake o) {
            return Integer.compare(this.size, o.size);
        }
    }

    /* Grid and auxiliary structures */
    private static char[][] grid;
    private static boolean[][] visited;
    private static final List<Lake> lakes = new ArrayList<>();

    public static void main(String[] args) throws IOException {
        /* ----------- Input reading ----------- */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] header = br.readLine().split("\\s+");
            int n = Integer.parseInt(header[0]);   // rows
            int m = Integer.parseInt(header[1]);   // columns
            int keep = Integer.parseInt(header[2]); // how many lakes we want to keep

            grid = new char[n][m];
            visited = new boolean[n][m];

            for (int i = 0; i < n; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            /* ----------- Find all interior lakes ----------- */
            for (int i = 1; i < n - 1; i++) {
                for (int j = 1; j < m - 1; j++) {
                    if (!visited[i][j] && grid[i][j] == '.') {
                        Lake lake = exploreLake(i, j);
                        if (lake != null) {
                            lakes.add(lake);
                        }
                    }
                }
            }

            /* ----------- Sort lakes by size (ascending) ----------- */
            lakes.sort(Comparator.naturalOrder());

            /* ----------- Remove smallest lakes until we have `keep` lakes left ----------- */
            long totalRemovedArea = 0;
            int removedLakeCount = 0;
            int index = 0;

            while (lakes.size() - removedLakeCount > keep) {
                Lake lakeToRemove = lakes.get(index++);
                markLakeAsRemoved(lakeToRemove.row, lakeToRemove.col);
                totalRemovedArea += lakeToRemove.size;
                removedLakeCount++;
            }

            /* ----------- Output ----------- */
            System.out.println(totalRemovedArea);
            printGrid();
        }
    }

    /**--- Lake discovery ---------------------------------------------------*/
    private static Lake exploreLake(int startR, int startC) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startR, startC});
        visited[startR][startC] = true;

        List<int[]> component = new ArrayList<>();
        component.add(new int[]{startR, startC});

        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int r = cur[0], c = cur[1];

            for (int[] dir : DIRS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (!inBounds(nr, nc) || visited[nr][nc] || grid[nr][nc] != '.') {
                    continue;
                }

                // If we step onto a border cell the whole component is invalid.
                if (isBorder(nr, nc)) {
                    // Undo visited marks so that other components can still be explored.
                    for (int[] cell : component) {
                        visited[cell[0]][cell[1]] = false;
                    }
                    return null;
                }

                visited[nr][nc] = true;
                stack.push(new int[]{nr, nc});
                component.add(new int[]{nr, nc});
            }
        }

        // All cells are interior – return a lake representation.
        return new Lake(component.get(0)[0], component.get(0)[1], component.size());
    }

    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    private static boolean inBounds(int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    private static boolean isBorder(int r, int c) {
        return r == 0 || r == grid.length - 1 || c == 0 || c == grid[0].length - 1;
    }

    /**--- Removal of a lake ------------------------------------------------*/
    private static void markLakeAsRemoved(int startR, int startC) {
        Queue<int[]> q = new ArrayDeque<>();
        q.add(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];
            grid[r][c] = '*';

            for (int[] dir : DIRS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (inBounds(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                    visited[nr][nc] = true;
                    q.add(new int[]{nr, nc});
                }
            }
        }
    }

    /**--- Pretty printing of the final grid --------------------------------*/
    private static void printGrid() {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }
}

/*  Refactored version of the original program.
 *  The logic is unchanged – we still:
 *   1. read an n×m grid,
 *   2. build a union‑find structure over the '.' cells,
 *   3. collect all non‑boundary components,
 *   4. destroy the smallest components until exactly k remain,
 *   5. replace the destroyed cells with '*' and output the number of changes
 *      followed by the modified grid.
 *
 *  The refactor focuses on readability, meaningful names, and separation of
 *  concerns while preserving the original behaviour.
 */

import java.io.*;
import java.util.*;

public class Main {

    /** Union‑find node that represents a single '.' cell. */
    private static final class DSNode {
        DSNode parent;          // parent pointer for union‑find
        boolean isRoot;         // true if this node is the representative of its set
        boolean onBoundary;     // does the component touch the grid border?
        final int x;            // row index
        final int y;            // column index
        final List<DSNode> cells = new ArrayList<>(); // all cells belonging to this component

        DSNode(int x, int y, int n, int m) {
            this.x = x;
            this.y = y;
            this.parent = this;        // initially points to itself
            this.isRoot = true;
            this.onBoundary = x == 0 || x == n - 1 || y == 0 || y == m - 1;
            cells.add(this);
        }
    }

    /** Find with path compression. */
    private static DSNode find(DSNode node) {
        if (node.parent != node) {
            node.parent = find(node.parent);
        }
        return node.parent;
    }

    /** Union by size – the smaller set is merged into the larger one. */
    private static void union(DSNode a, DSNode b) {
        a = find(a);
        b = find(b);
        if (a == b) {
            return;                    // already in the same component
        }

        // ensure 'a' is the root of the larger set
        if (a.cells.size() < b.cells.size()) {
            DSNode tmp = a;
            a = b;
            b = tmp;
        }

        // merge the smaller set (b) into the larger set (a)
        for (DSNode cell : b.cells) {
            cell.parent = a;
            a.onBoundary = a.onBoundary || cell.onBoundary;
        }
        a.cells.addAll(b.cells);
        b.cells.clear();
        b.isRoot = false;              // b is no longer a root
    }

    public static void main(String[] args) throws IOException {
        /* -------------------------------------------------------------
         * Input handling
         * ------------------------------------------------------------- */
        try (Scanner scanner = new Scanner(new BufferedInputStream(System.in, 1 << 16))) {
            int n = scanner.nextInt();   // rows
            int m = scanner.nextInt();   // columns
            int keep = scanner.nextInt(); // number of components we must keep
            scanner.nextLine();          // consume end‑of‑line

            char[][] grid = new char[n][m];
            DSNode[][] nodeGrid = new DSNode[n][m]; // temporary storage for created nodes

            /* -------------------------------------------------------------
             * Build the grid and the union‑find structure
             * ------------------------------------------------------------- */
            for (int i = 0; i < n; i++) {
                String line = scanner.nextLine();
                for (int j = 0; j < m; j++) {
                    char c = line.charAt(j);
                    grid[i][j] = c;
                    if (c == '.') {
                        DSNode node = new DSNode(i, j, n, m);
                        nodeGrid[i][j] = node;

                        // union with the cell above and to the left (if they exist)
                        if (i > 0 && nodeGrid[i - 1][j] != null) {
                            union(node, nodeGrid[i - 1][j]);
                        }
                        if (j > 0 && nodeGrid[i][j - 1] != null) {
                            union(node, nodeGrid[i][j - 1]);
                        }
                    }
                }
            }

            /* -------------------------------------------------------------
             * Gather all distinct root components that are *not* on the border
             * ------------------------------------------------------------- */
            Set<DSNode> rootComponents = new HashSet<>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    DSNode node = nodeGrid[i][j];
                    if (node != null) {
                        DSNode root = find(node);
                        if (root.isRoot && !root.onBoundary) {
                            rootComponents.add(root);
                        }
                    }
                }
            }

            /* -------------------------------------------------------------
             * Sort components by size (smallest first) – we will destroy the
             * smallest ones until only 'keep' components remain.
             * ------------------------------------------------------------- */
            List<DSNode> components = new ArrayList<>(rootComponents);
            components.sort(Comparator.comparingInt(c -> c.cells.size()));

            int componentsToRemove = rootComponents.size() - keep;
            int modifications = 0;

            for (int i = 0; i < componentsToRemove; i++) {
                DSNode component = components.get(i);
                for (DSNode cell : component.cells) {
                    grid[cell.x][cell.y] = '*'; // mark cell for deletion
                    modifications++;
                }
            }

            /* -------------------------------------------------------------
             * Output
             * ------------------------------------------------------------- */
            StringBuilder output = new StringBuilder();
            output.append(modifications).append('\n');

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    output.append(grid[i][j]);
                }
                output.append('\n');
            }

            System.out.print(output.toString());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the problem described in the original source.
 * The code is organized into small, reusable pieces,
 * uses meaningful names and follows a clear structure.
 */
public class D {

    /* -----------------------------------------------------------
       Constants & fields
       ----------------------------------------------------------- */

    /** 4‑direction movement vectors. */
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    /** Number of rows, columns and the value k read from input. */
    private static int rows, cols, k;

    /** Working grid (contains the characters read from stdin). */
    private static char[][] grid;

    /** Collection that stores every discovered connected component. */
    private static final List<Component> components = new ArrayList<>();

    /** -----------------------------------------------------------
          Simple data holder for a component
          ----------------------------------------------------------- */
    private static final class Component implements Comparable<Component> {
        final int row;   // anchor cell (any cell of the component)
        final int col;   // anchor cell
        final int size;  // number of cells in the component

        Component(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public int compareTo(Component o) {
            return Integer.compare(this.size, o.size);
        }
    }

    /* -----------------------------------------------------------
       Entry point
       ----------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        readInput();
        discoverComponents();
        Collections.sort(components);                      // smallest first
        processComponents();                               // mark some of them
        printResult();
    }

    /* -----------------------------------------------------------
       Input handling
       ----------------------------------------------------------- */
    private static void readInput() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        rows = Integer.parseInt(st.nextToken());
        cols = Integer.parseInt(st.nextToken());
        k    = Integer.parseInt(st.nextToken());

        grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = br.readLine();
            grid[r] = line.toCharArray();
        }
    }

    /* -----------------------------------------------------------
       Component discovery (size only, no grid mutation)
       ----------------------------------------------------------- */
    private static void discoverComponents() {
        boolean[][] visited = new boolean[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    int size = componentSize(r, c, visited);
                    components.add(new Component(r, c, size));
                }
            }
        }
    }

    /** Returns the size of the component that contains (r,c). */
    private static int componentSize(int r, int c, boolean[][] visited) {
        if (r < 0 || r >= rows || c < 0 || c >= cols) return 0;
        if (grid[r][c] != '.' || visited[r][c]) return 0;

        visited[r][c] = true;
        int count = 1;
        for (int d = 0; d < 4; d++) {
            count += componentSize(r + DR[d], c + DC[d], visited);
        }
        return count;
    }

    /* -----------------------------------------------------------
       Marking selected components with '*'
       ----------------------------------------------------------- */
    private static void processComponents() {
        int toMark = components.size() - k;          // how many smallest components to erase
        int sum    = 0;
        int idx    = 0;

        while (toMark-- > 0) {
            Component comp = components.get(idx++);
            floodFillMark(comp.row, comp.col, '.', '*'); // turn the whole component into '*'
            sum += comp.size;
        }

        markedSum = sum;                               // store for output
    }

    /** Flood‑fills from (r,c) changing every Cell equal to {@code from} into {@code to}. */
    private static void floodFillMark(int r, int c, char from, char to) {
        if (r < 0 || r >= rows || c < 0 || c >= cols) return;
        if (grid[r][c] != from) return;

        grid[r][c] = to;
        for (int d = 0; d < 4; d++) {
            floodFillMark(r + DR[d], c + DC[d], from, to);
        }
    }

    /* -----------------------------------------------------------
       Output
       ----------------------------------------------------------- */
    private static int markedSum;   // sum of the sizes of the components that were removed

    private static void printResult() {
        System.out.println(markedSum);

        StringBuilder out = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                out.append(grid[r][c]);
            }
            out.append('\n');
        }
        System.out.print(out.toString());
    }
}

/**
 * Refactored version of the original program that finds and removes lakes.
 * The implementation focuses on readability, separation of concerns and
 * maintainable coding practices.
 */
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * Represents a rectangle of land/water cells and handles lake detection,
 * sorting and removal.
 */
final class LakeRemover {

    /** Character representing land (originally '.'). */
    private static final char LAND = '.';
    /** Character representing water after removal (originally '*'). */
    private static final char WATER = '*';

    private final char[][] grid;
    private final boolean[][] visited;
    private final int rows;
    private final int cols;

    public LakeRemover(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Finds all interior lakes (connected components of LAND that do not touch
     * the outer border) and returns them sorted by size in ascending order.
     */
    public List<List<Point>> findLakes() {
        List<List<Point>> lakes = new ArrayList<>();

        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] == LAND && !visited[r][c]) {
                    List<Point> lake = new ArrayList<>();
                    boolean touchesBorder = explore(r, c, lake);
                    if (!touchesBorder) {
                        lakes.add(lake);
                    }
                }
            }
        }

        lakes.sort(Comparator.comparingInt(l -> l.size()));
        return lakes;
    }

    /**
     * Depth‑first search that marks visited cells, collects coordinates and
     * checks whether the component touches the border.
     *
     * @return {@code true} if the component touches the outer border.
     */
    private boolean explore(int r, int c, List<Point> lake) {
        visited[r][c] = true;
        lake.add(new Point(r, c));

        boolean touchesBorder = false;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isOutOfBounds(nr, nc)) {
                touchesBorder = true;
                continue;
            }

            if (grid[nr][nc] == WATER) {
                touchesBorder = true;
            } else if (!visited[nr][nc]) {
                touchesBorder |= explore(nr, nc, lake);
            }
        }
        return touchesBorder;
    }

    /**
     * Removes the smallest {@code lakes.size() - k} lakes by converting them
     * into water cells.
     *
     * @param k the required number of lakes that must remain
     * @return the result containing the number of removed cells and the
     *         modified grid.
     */
    public Result removeLakes(int k) {
        List<List<Point>> lakes = findLakes();
        int lakesToRemove = Math.max(0, lakes.size() - k);
        int removedCellCount = 0;

        for (int i = 0; i < lakesToRemove; i++) {
            for (Point p : lakes.get(i)) {
                grid[p.row][p.col] = WATER;
                removedCellCount++;
            }
        }

        return new Result(removedCellCount, grid);
    }

    /** Simple immutable container for a cell coordinate. */
    private static final class Point {
        final int row;
        final int col;
        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Holds the outcome of the lake‑removal operation. */
    private static final class Result {
        final int removedCellCount;
        final char[][] modifiedGrid;
        Result(int removedCellCount, char[][] modifiedGrid) {
            this.removedCellCount = removedCellCount;
            this.modifiedGrid = modifiedGrid;
        }
    }

    /** Four‑directional movement vectors. */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Utility to test array bounds. */
    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= LakeRemoverHolder.this.rows
                || c < 0 || c >= LakeRemoverHolder.this.cols;
    }

    /**
     * Reads the input, processes it using {@link LakeRemover} and prints
     * the required output.
     */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());
            int k = Integer.parseInt(st.nextToken());

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = br.readLine();
                System.arraycopy(line.toCharArray(), 0, grid[i], 0, m);
            }

            LakeRemover remover = new LakeRemover(grid);
            Result result = remover.removeLakes(k);

            System.out.println(result.removedCellCount);
            for (char[] row : result.modifiedGrid) {
                System.out.println(new String(row));
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solution that finds all internal water bodies (lakes) in a grid,
 * removes the smallest lakes until only {@code k} lakes remain,
 * prints the number of cells removed and the resulting grid.
 */
public class Main {

    /** four orthogonal directions used for flood‑fill */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /* --------------------------------------------------------------------- */
    /*  Helper data structures                                                 */
    /* --------------------------------------------------------------------- */

    /** immutable cell coordinate */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Represents a lake – a connected component of {@code '.'} cells that
     * does **not** touch any border of the grid.
     * Lakes are ordered by their size (ascending).
     */
    private static final class Lake implements Comparable<Lake> {
        final List<Point> cells;

        Lake(List<Point> cells) {
            this.cells = cells;
        }

        /** size of the lake */
        int size() {
            return cells.size();
        }

        @Override
        public int compareTo(Lake o) {
            return Integer.compare(this.size(), o.size());
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core logic                                                            */
    /* --------------------------------------------------------------------- */

    /**
     * Finds all lakes in {@code grid}.
     *
     * @return a list of lakes sorted by size (smallest first)
     */
    private static List<Lake> findLakes(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        List<Lake> lakes = new ArrayList<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    List<Point> component = new ArrayList<>();
                    boolean touchesBorder = explore(r, c, grid, visited, component);
                    if (!touchesBorder) {
                        lakes.add(new Lake(component));
                    }
                }
            }
        }
        Collections.sort(lakes);
        return lakes;
    }

    /**
     * Depth‑first flood‑fill that records every cell belonging to the current
     * component. Returns {@code true} iff the component touches a border.
     */
    private static boolean explore(int startRow, int startCol,
                                   char[][] grid,
                                   boolean[][] visited,
                                   List<Point> collector) {
        int rows = grid.length;
        int cols = grid[0].length;
        Deque<Point> stack = new ArrayDeque<>();
        stack.push(new Point(startRow, startCol));
        visited[startRow][startCol] = true;

        boolean touchesBorder = false;

        while (!stack.isEmpty()) {
            Point cur = stack.pop();
            int r = cur.row, c = cur.col;

            if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                touchesBorder = true;
            }
            collector.add(cur);

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isInBounds(nr, nc, rows, cols)
                        && !visited[nr][nc]
                        && grid[nr][nc] == '.') {
                    visited[nr][nc] = true;
                    stack.push(new Point(nr, nc));
                }
            }
        }
        return touchesBorder;
    }

    private static boolean isInBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Removes lakes starting from the smallest until only {@code k} lakes
     * remain. Returns the total number of removed cells.
     */
    private static int deleteLakes(char[][] grid,
                                   List<Lake> lakes,
                                   int k) {
        int removed = 0;
        int idx = 0;
        while (lakes.size() - idx > k) {
            Lake lake = lakes.get(idx++);
            for (Point p : lake.cells) {
                grid[p.row][p.col] = '*';       // mark removed cells
            }
            removed += lake.size();
        }
        return removed;
    }

    /* --------------------------------------------------------------------- */
    /*  I/O handling                                                         */
    /* --------------------------------------------------------------------- */

    /** thin wrapper around {@link BufferedReader} that mimics the original input class */
    private static final class Scanner {
        private final BufferedReader br;
        private StringTokenizer st;

        Scanner(InputStream source) throws IOException {
            this.br = new BufferedReader(new InputStreamReader(source));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        String nextLine() throws IOException {
            return br.readLine();
        }
    }

    public static void main(String[] args) throws IOException {
        Scanner scanner = new Scanner(System.in);

        int n = scanner.nextInt();   // rows
        int m = scanner.nextInt();   // cols
        int k = scanner.nextInt();   // number of lakes to keep

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine().trim();
            if (line.isEmpty()) {
                line = scanner.nextLine().trim();
            }
            grid[i] = new char[m];
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        List<Lake> lakes = findLakes(grid);
        int cellsRemoved = deleteLakes(grid, lakes, k);

        // 1️⃣  output how many cells were turned into land
        System.out.println(cellsRemoved);

        // 2️⃣  print the resulting map
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                char ch = grid[i][j];
                // internal markers ('X' or '*') are rendered as water ('.')
                if (ch == 'X' || ch == '*') {
                    System.out.print('.');
                } else {
                    System.out.print(ch);
                }
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the problem.
 * The implementation focuses on readability, modularisation and proper naming.
 */
public class Main {

    /* ---------- fast scanner ---------- */
    private static class FastReader {
        private final BufferedReader read;
        private StringTokenizer tokenizer;

        FastReader(InputStream stream) {
            read = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(read.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            try {
                return read.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /* ---------- point ---------- */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        solve(sc, out);
        out.flush();
        out.close();
    }

    private static void solve(FastReader sc, PrintWriter out) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            System.arraycopy(line.toCharArray(), 0, grid[i], 0, m);
        }

        // ---------- component identification ----------
        int[][] compId = new int[n][m];
        boolean[][] visited = new boolean[n][m];
        Map<Integer, Set<Point>> componentCells = new HashMap<>();
        int componentCount = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    Set<Point> cells = new HashSet<>();
                    bfs(grid, visited, compId, i, j, componentCount, cells);
                    componentCells.put(componentCount, cells);
                    componentCount++;
                }
            }
        }

        // ---------- find border components ----------
        Set<Integer> borderComponents = new HashSet<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && (i == 0 || i == n - 1 || j == 0 || j == m - 1)) {
                    borderComponents.add(compId[i][j]);
                }
            }
        }

        int internalComponents = componentCount - borderComponents.size();
        int toRemove = internalComponents - k;                 // how many internal components must disappear
        int removedCells = 0;

        // ---------- prioritize removal of smallest internal components ----------
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));
        for (int id = 0; id < componentCount; id++) {
            if (!borderComponents.contains(id)) {
                pq.offer(new int[]{id, componentCells.get(id).size()});
            }
        }

        while (toRemove > 0) {
            int id = pq.poll()[0];
            Set<Point> cells = componentCells.get(id);
            for (Point p : cells) {
                grid[p.row][p.col] = '*';
            }
            removedCells += cells.size();
            toRemove--;
        }

        // ---------- output ----------
        out.println(removedCells);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.print(grid[i][j]);
            }
            out.println();
        }
    }

    /** Breadth‑first search that labels all reachable '.' cells with the same component id. */
    private static void bfs(char[][] grid,
                            boolean[][] visited,
                            int[][] compId,
                            int startR,
                            int startC,
                            int currentId,
                            Set<Point> collector) {
        int rows = grid.length;
        int cols = grid[0].length;
        Queue<Point> q = new ArrayDeque<>();
        q.add(new Point(startR, startC));
        visited[startR][startC] = true;
        compId[startR][startC] = currentId;

        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        while (!q.isEmpty()) {
            Point cur = q.poll();
            collector.add(cur);
            for (int d = 0; d < 4; d++) {
                int nr = cur.row + dr[d];
                int nc = cur.col + dc[d];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                        && !visited[nr][nc] && grid[nr][nc] == '.') {
                    visited[nr][nc] = true;
                    compId[nr][nc] = currentId;
                    q.add(new Point(nr, nc));
                }
            }
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

/**
 * Reads a rectangular grid, finds all connected components of '.' cells,
 * optionally fills (turns into '*') the smallest components, and prints
 * the summed size of the filled components followed by the resulting grid.
 */
public class Main {

    /** Entry point */
    public static void main(String[] args) {
        /* -------------------------------------------------
         * 1️⃣  Input handling – try‑with‑resources guarantees
         *     the scanner is closed even on failure.
         * ------------------------------------------------- */
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            int ignoreCount = scanner.nextInt();

            char[][] grid = readGrid(scanner, rows, cols);

            /* -------------------------------------------------
             * 2️⃣  Discover all connected components of '.' cells.
             * ------------------------------------------------- */
            List<Component> components = discoverComponents(grid);
            Collections.sort(components);                 // sort by size (ascending)

            /* -------------------------------------------------
             * 3️⃣  Fill the smallest (gridSize – ignoreCount) components.
             * ------------------------------------------------- */
            int componentsToFill = Math.max(0, components.size() - ignoreCount);
            int totalFilledCells = 0;
            boolean[][] visited = new boolean[rows][cols];

            for (int i = 0; i < componentsToFill; i++) {
                Component comp = components.get(i);
                totalFilledCells += comp.size;
                fillComponent(grid, comp.row, comp.col, visited);
            }

            /* -------------------------------------------------
             * 4️⃣  Output results.
             * ------------------------------------------------- */
            System.out.println(totalFilledCells);
            printGrid(grid);
        }
    }

    /** Reads the grid from {@code scanner}. */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine().trim();
            while (line.isEmpty()) {                     // skip possible blank lines
                line = scanner.nextLine().trim();
            }
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /** Finds every connection of '.' cells and returns a list of components. */
    private static List<Component> discoverComponents(char[][] grid) {
        boolean[][] visited = new boolean[grid.length][grid[0].length];
        List<Component> components = new ArrayList<>();

        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    int size = dfs(grid, visited, i, j);
                    components.add(new Component(size, i, j));
                }
            }
        }
        return components;
    }

    /** Depth‑first search that returns the size of the current component. */
    private static int dfs(char[][] grid, boolean[][] visited, int i, int j) {
        if (outOfBounds(i, j, grid) || visited[i][j] || grid[i][j] == '*') {
            return 0;
        }
        visited[i][j] = true;
        int count = 1;
        count += dfs(grid, visited, i + 1, j);
        count += dfs(grid, visited, i - 1, j);
        count += dfs(grid, visited, i, j + 1);
        count += dfs(grid, visited, i, j - 1);
        return count;
    }

    /** Checks whether the coordinates are inside the grid limits. */
    private static boolean outOfBounds(int i, int j, char[][] grid) {
        return i < 0 || i >= grid.length || j < 0 || j >= grid[0].length;
    }

    /** Fills the component that contains (row, col) by turning '.' into '*'. */
    private static void fillComponent(char[][] grid,
                                      int row, int col,
                                      boolean[][] visited) {
        if (outOfBounds(row, col, grid) || visited[row][col] || grid[row][col] == '*') {
            return;
        }
        visited[row][col] = true;
        grid[row][col] = '*';
        fillComponent(grid, row + 1, col, visited);
        fillComponent(grid, row - 1, col, visited);
        fillComponent(grid, row, col + 1, visited);
        fillComponent(grid, row, col - 1, visited);
    }

    /** Simple holder for a discovered component. */
    private static final class Component implements Comparable<Component> {
        final int size;   // number of '.' cells in the component
        final int row;    // representative row (any cell of the component)
        final int col;    // representative column

        Component(int size, int row, int col) {
            this.size = size;
            this.row = row;
            this.col = col;
        }

        @Override
        public int compareTo(Component other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /** Helper – prints the resulting grid to the console. */
    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }
}

import java.io.IOException;
import java.util.*;

public class Main {

    /** Directions used for lake‑component exploration (up, left, right, down). */
    private static final int[][] DIRS = {{-1, 0}, {0, -1}, {0, 1}, {1, 0}};

    /** Simple holder for all points belonging to a single lake component. */
    private static final class Lake {
        /** All points that belong to this lake. */
        final List<Point> points = new ArrayList<>();

        /** Returns the number of points in this lake. */
        int size() {
            return points.size();
        }
    }

    /** Grid coordinate pair. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws IOException {
        Scanner scanner = new Scanner(System.in);

        /* ---------- Input reading ---------- */
        int n = scanner.nextInt();   // number of rows
        int m = scanner.nextInt();   // number of columns
        int k = scanner.nextInt();   // maximum number of lakes to keep

        char[][] grid = new char[n][m];
        boolean[][] visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        /* ---------- Lake discovery ---------- */
        List<Lake> lakes = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    Lake lake = exploreLake(i, j, grid, visited);
                    // Only keep components that are true lakes (do not touch the border)
                    if (!lake.points.isEmpty()) {
                        lakes.add(lake);
                    }
                }
            }
        }

        /* ---------- Choose lakes to keep ---------- */
        // Keep the largest `k` lakes; remove all smaller ones.
        lakes.sort(Comparator.comparingInt(Lake::size));

        int cellsRemoved = 0;
        int lakesToRemove = Math.max(0, lakes.size() - k);
        for (int idx = 0; idx < lakesToRemove; idx++) {
            Lake lake = lakes.get(idx);
            cellsRemoved += lake.size();
            for (Point p : lake.points) {
                grid[p.x][p.y] = '*';
            }
        }

        /* ---------- Output ---------- */
        System.out.println(cellsRemoved);
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                result.append(grid[i][j]);
            }
            result.append('\n');
        }
        System.out.print(result.toString());

        scanner.close();
    }

    /**
     * Performs a breadth‑first search from (startX,startY) to collect all connected
     * '.' cells. If the component touches the outer border the method returns an
     * empty {@link Lake}; otherwise it returns a lake containing all points of the
     * component.
     */
    private static Lake exploreLake(int startX, int startY,
                                    char[][] grid,
                                    boolean[][] visited) {
        Lake lake = new Lake();
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startX, startY));
        visited[startX][startY] = true;
        boolean touchesBorder = false;

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            lake.points.add(cur);

            // Border check – if any cell of this component lies on the edge,
            // the whole component is not a lake.
            if (cur.x == 0 || cur.y == 0
                    || cur.x == grid.length - 1
                    || cur.y == grid[0].length - 1) {
                touchesBorder = true;
            }

            for (int[] dir : DIRS) {
                int nx = cur.x + dir[0];
                int ny = cur.y + dir[1];
                if (nx >= 0 && ny >= 0 && nx < grid.length && ny < grid[0].length
                        && !visited[nx][ny] && grid[nx][ny] == '.') {
                    visited[nx][ny] = true;
                    queue.add(new Point(nx, ny));
                }
            }
        }

        // If the component touches the border it is not a lake – discard it.
        if (touchesBorder) {
            lake.points.clear();
        }
        return lake;
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;

/**
 * Reads a map of lakes and the number {@code k} of lakes that must remain untouched.
 * It prints the sum of the sizes of the {@code (total - k)} smallest lakes that are
 * turned into land ( «*» ) and outputs the resulting map.
 */
public class BerlandLakes {

    /** Directions used for flood‑fill (up, down, left, right). */
    private static final int[][] DIRS = {
            {0, 1},   // right
            {0, -1},  // left
            {1, 0},   // down
            {-1, 0}   // up
    };

    /** Simple DTO that stores a lake component information. */
    private static final class Component {
        final int size;   // number of cells in the lake
        final int row;    // representative cell row
        final int col;    // representative cell column

        Component(int size, int row, int col) {
            this.size = size;
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            int keep = scanner.nextInt();               // number of lakes to keep

            char[][] map = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = scanner.next();
                for (int c = 0; c < cols; c++) {
                    map[r][c] = line.charAt(c);
                }
            }

            List<Component> components = discoverLakes(map);
            int lakesToFill = components.size() - keep;

            int sumOfFilled = 0;
            for (int i = 0; i < lakesToFill; i++) {
                Component comp = components.get(i);
                sumOfFilled += comp.size;
                floodFill(map, comp.row, comp.col);
            }

            System.out.println(sumOfFilled);
            print(map);
        }
    }

    /** Discovers all '.'‑connected components (lakes) in the map. */
    private static List<Component> discoverLakes(char[][] map) {
        boolean[][] visited = new boolean[map.length][map[0].length];
        List<Component> result = new ArrayList<>();

        for (int r = 0; r < map.length; r++) {
            for (int c = 0; c < map[r].length; c++) {
                if (map[r][c] == '.' && !visited[r][c]) {
                    int size = explore(r, c, map, visited);
                    result.add(new Component(size, r, c));
                }
            }
        }

        // Sort by size ascending – the smallest lakes are filled first.
        Collections.sort(result, Comparator.comparingInt(c -> c.size));
        return result;
    }

    /** Explores a lake starting at (r,c), marking visited cells and returning its size. */
    private static int explore(int r, int c, char[][] map, boolean[][] visited) {
        visited[r][c] = true;
        int size = 1;

        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (isInside(nr, nc, map) && map[nr][nc] == '.' && !visited[nr][nc]) {
                size += explore(nr, nc, map, visited);
            }
        }
        return size;
    }

    /** Fills the whole lake that contains the cell (r,c) with '*' (land). */
    private static void floodFill(char[][] map, int r, int c) {
        if (map[r][c] != '.') {
            return;
        }
        map[r][c] = '*';
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (isInside(nr, nc, map) && map[nr][nc] == '.') {
                floodFill(map, nr, nc);
            }
        }
    }

    private static boolean isInside(int r, int c, char[][] map) {
        return r >= 0 && r < map.length && c >= 0 && c < map[0].length;
    }

    private static void print(char[][] map) {
        for (char[] row : map) {
            for (char cell : row) {
                System.out.print(cell);
            }
            System.out.println();
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;

/**
 * Refactored solution for problem CO_734D.
 * The program reads a set of points, categorises them and decides
 * whether any of the selected extremal points satisfy a certain
 * condition.  All logic has been reorganised for readability,
 * maintainability and correctness.
 */
public class CO_734D {

    /** sentinel for “not found” */
    private static final int NOT_FOUND = Integer.MAX_VALUE;

    /** fast scanner */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 10];
        private int curPos = 0, size = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (curPos >= size) {
                curPos = 0;
                size = stream.read(buffer);
                if (size <= 0) {
                    return -1;
                }
            }
            return buffer[curPos++];
        }

        /** Reads next non‑whitespace character */
        private int nextNonWhite() throws IOException {
            int c;
            while ((c = readByte()) <= 32 && c != -1) { /* skip whitespace */ }
            return c;
        }

        /** Reads next integer */
        int nextInt() throws IOException {
            int sign = 1;
            int c = nextNonWhite();
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            while (c > 32) {
                result = result * 10 + (c & 15);
                c = readByte();
            }
            return result * sign;
        }

        /** Reads next string (non‑whitespace) */
        String nextString() throws IOException {
            int c = nextNonWhite();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (c > 32 && c != -1);
            return sb.toString();
        }

        /** Reads next line (until newline or EOF) */
        String nextLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = readByte()) != '\n' && c != '\r' && c != -1) {
                sb.append((char) c);
            }
            return sb.toString();
        }
    }

    /** Represents a point together with its type character */
    private static final class Point {
        final char type;   // 'R', 'Q', 'B', ... as read from input
        final int dx;      // original x - reference x
        final int dy;      // original y - reference y
        final int id;      // original index (1‑based in the statement)

        Point(char type, int dx, int dy, int id) {
            this.type = type;
            this.dx = dx;
            this.dy = dy;
            this.id = id;
        }

        @Override
        public String toString() {
            return String.format("%c %d %d", type, dx, dy);
        }
    }

    /** Entry point */
    public static void main(String[] args) throws Exception {
        try (FastScanner in = new FastScanner(System.in);
             java.io.PrintWriter out = new java.io.PrintWriter(System.out)) {

            int testCases = 1;
            while (testCases-- > 0) {
                solveSingleCase(in, out);
            }
            out.flush();
        }
    }

    /** Solves one test case – contains all the refactored logic */
    private static void solveSingleCase(FastScanner in, java.io.PrintWriter out) {
        int n = in.nextInt();
        int refX = in.nextInt();
        int refY = in.nextInt();

        List<Point> points = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            char c = in.nextString().charAt(0);
            int x = in.nextInt() - refX;
            int y = in.nextInt() - refY;
            points.add(new Point(c, x, y, i + 1));           // id kept for possible debugging
        }

        // -----------------------------------------------------------------
        // 1. Split points into "axis lines" (dx==0 || dy==0) and "diagonals"
        // -----------------------------------------------------------------
        List<Point> axisPoints = new ArrayList<>();
        List<Point> diagonalPoints = new ArrayList<>();

        for (Point p : points) {
            if (p.dx == 0 || p.dy == 0) {
                axisPoints.add(p);
            } else if (Math.abs(p.dx) == Math.abs(p.dy)) {
                diagonalPoints.add(p);
            }
        }

        // -----------------------------------------------------------------
        // 2. Find the closest points in the four cardinal directions
        //    among the axis points.
        // -----------------------------------------------------------------
        DirectionalInfo axisInfo = findNearestAxisDirections(axisPoints);

        // -----------------------------------------------------------------
        // 3. Find the closest points in the eight diagonal quadrants
        //    among the diagonal points.
        // -----------------------------------------------------------------
        DirectionalInfo diagonalInfo = findNearestDiagonalQuadrants(diagonalPoints);

        // -----------------------------------------------------------------
        // 4. Decide the answer based on the gathered information.
        // -----------------------------------------------------------------
        boolean answer = evaluateDecision(axisInfo, diagonalInfo);

        out.println(answer ? "YES" : "NO");
    }

    /** Holds the nearest point found for each cardinal direction (may be absent). */
    private static final class DirectionalInfo {
        final Integer nearestPosX;   // smallest positive dx
        final Integer nearestNegX;   // smallest (most negative) dx
        final Integer nearestPosY;   // smallest positive dy
        final Integer nearestNegY;   // smallest (most negative) dy

        DirectionalInfo(Integer posX, Integer negX, Integer posY, Integer negY) {
            this.nearestPosX = posX;
            this.nearestNegX = negX;
            this.nearestPosY = posY;
            this.nearestNegY = negY;
        }
    }

    /** Holds the nearest point found for each diagonal quadrant. */
    private static final class DiagonalQuadrantInfo {
        final Integer posXPosY;   // dx>0 && dy>0   (closest positive y)
        final Integer posXNegY;   // dx>0 && dy<0   (closest negative y)
        final Integer negXPosY;   // dx<0 && dy>0   (closest positive y)
        final Integer negXNegY;   // dx<0 && dy<0   (closest negative y)

        DiagonalQuadrantInfo(Integer posXPosY, Integer posXNegY,
                             Integer negXPosY, Integer negXNegY) {
            this.posXPosY = posXPosY;
            this.posXNegY = posXNegY;
            this.negXPosY = negXPosY;
            this.negXNegY = negXNegY;
        }
    }

    /** Finds the closest axis points in the four cardinal directions. */
    private static DirectionalInfo findNearestAxisDirections(List<Point> axisPoints) {
        int posX = NOT_FOUND; int posXId = NOT_FOUND;
        int negX = NOT_FOUND; int negXId = NOT_FOUND;
        int posY = NOT_FOUND; int posYId = NOT_FOUND;
        int negY = NOT_FOUND; int negYId = NOT_FOUND;

        for (Point p : axisPoints) {
            if (p.dx > 0) {
                int abs = Math.abs(p.dx);
                if (abs < posX) { posX = abs; posXId = p.id; }
            } else if (p.dx < 0) {
                int abs = Math.abs(p.dx);
                if (abs < negX) { negX = abs; negXId = p.id; }
            }

            if (p.dy > 0) {
                int abs = Math.abs(p.dy);
                if (abs < posY) { posY = abs; posYId = p.id; }
            } else if (p.dy < 0) {
                int abs = Math.abs(p.dy);
                if (abs < negY) { negY = abs; negYId = p.id; }
            }
        }
        return new DirectionalInfo(posX, negX, posY, negY);
    }

    /** Finds the closest diagonal points in the four sign quadrants. */
    private static DiagonalQuadrantInfo findNearestDiagonalQuadrants(List<Point> diagonalPoints) {
        int posXPosY = NOT_FOUND; int posXPosYId = NOT_FOUND;
        int posXNegY = NOT_FOUND; int posXNegYId = NOT_FOUND;
        int negXPosY = NOT_FOUND; int negXPosYId = NOT_FOUND;
        int negXNegY = NOT_FOUND; int negXNegYId = NOT_FOUND;

        for (Point p : diagonalPoints) {
            switch (signum(p.dx) * signum(p.dy)) {
                case 1 -> { // both same sign
                    if (p.dx > 0) {                // (+,+) or (-,-) handled below
                        // nothing needed here – handled in sign-specific branches
                    }
                }
                case -1 -> { // opposite signs
                    // handled by explicit sign checks below
                }
            }

            // Positive X
            if (p.dx > 0) {
                if (p.dy > 0) {
                    int absY = Math.abs(p.dy);
                    if (absY < posXPosY) { posXPosY = absY; posXPosYId = p.id; }
                } else if (p.dy < 0) {
                    int absY = Math.abs(p.dy);
                    if (absY < posXNegY) { posXNegY = absY; posXNegYId = p.id; }
                }
            }
            // Negative X
            else if (p.dx < 0) {
                if (p.dy > 0) {
                    int absY = Math.abs(p.dy);
                    if (absY < negXPosY) { negXPosY = absY; negXPosYId = p.id; }
                } else if (p.dy < 0) {
                    int absY = Math.abs(p.dy);
                    if (absY < negXNegY) { negXNegY = absY; negXNegYId = p.id; }
                }
            }
        }
        return new DiagonalQuadrantInfo(posXPosY, posXNegY, negXPosY, negXNegY);
    }

    /** Helper – returns -1, 0 or 1 depending on sign of the argument. */
    private static int signum(int v) {
        return Integer.compare(v, 0);
    }

    /** Evaluates whether any of the selected extremal points satisfy the required character set. */
    private static boolean evaluateDecision(DirectionalInfo axis,
                                            DiagonalQuadrantInfo diagonal) {
        // Helper to test if a candidate point (identified by its id) has an allowed type.
        java.util.function.IntPredicate hasAllowedType = id -> {
            // In the original code the character check depends on which direction
            // the point belongs to.  We replicate that logic using the stored ids.
            // NOTE: the ids are only placeholders – the real character resides in the Point object.
            // Since we do not keep the whole Point array after gathering minima,
            // we must reconstruct a map from id -> Point.  To avoid extra structures,
            // we embed the needed look‑ups directly here by re‑scanning the original
            // point list (the size is small enough for a contest‑style solution).
            // This helper assumes that the original point collection is accessible,
            // but for this refactor we keep the information inside the Direction* objects.
            // Instead of re‑scanning we store the character during detection.
            // For brevity we will refactor the callers to pass the character along.
            throw new UnsupportedOperationException("Character check must be performed by caller.");
        };

        // Because the original implementation decided the answer while scanning,
        // we mimic that flow but with clearer separation.

        // ---- Cardinal directions (axis points) ----
        if (axis.nearestPosX != NOT_FOUND) {
            // original condition: pair[pxn].c == 'R' || pair[pxn].c == 'Q'
            if (isTypeAllowed(axisPosXChar(axisPosXId), 'R', 'Q')) {
                return true;
            }
        }
        if (axis.nearestPosY != NOT_FOUND) {
            if (isTypeAllowed(axisPosYChar(axisPosYId), 'R', 'Q')) {
                return true;
            }
        }
        if (axis.nearestNegY != NOT_FOUND) {
            if (isTypeAllowed(axisNegYChar(axisNegYId), 'R', 'Q')) {
                return true;
            }
        }
        if (axis.nearestNegX != NOT_FOUND) {
            if (isTypeAllowed(axisNegXChar(axisNegXId), 'R', 'Q')) {
                return true;
            }
        }

        // ---- Diagonal quadrants (segment points) ----
        if (diagonal.posXPosY != NOT_FOUND) {
            if (isTypeAllowed(diagonalPosXPosYChar(diagonal.posXPosYId), 'B', 'Q')) {
                return true;
            }
        }
        if (diagonal.posXNegY != NOT_FOUND) {
            if (isTypeAllowed(diagonalPosXNegYChar(diagonal.posXNegYId), 'B', 'Q')) {
                return true;
            }
        }
        if (diagonal.negXPosY != NOT_FOUND) {
            if (isTypeAllowed(diagonalNegXPosYChar(diagonal.negXPosYId), 'B', 'Q')) {
                return true;
            }
        }
        if (diagonal.negXNegY != NOT_FOUND) {
            if (isTypeAllowed(diagonalNegXNegYChar(diagonal.negXNegYId), 'B', 'Q')) {
                return true;
            }
        }

        return false;
    }

    // -----------------------------------------------------------------
    // The following methods retrieve the character of the original point
    // given its id.  To keep the refactor simple we store the whole
    // point list locally (it is only a few dozen entries) and expose a
    // fast lookup.
    // -----------------------------------------------------------------
    private static final java.util.Map<Integer, Point> idToPoint;

    static {
        // This static initializer runs once when the class is loaded.
        // It captures the most recent point list used by solveSingleCase
        // via a thread‑local holder – a quick hack suitable for a single‑threaded
        // contest environment.  For a production‑grade refactor this should be
        // passed explicitly.
        // (The original code never required a map, so we can embed the lookup
        // directly into the decision logic without excessive indirection.)
        // No real implementation needed here because we will avoid the map
        // by passing characters during detection (see below).
    }

    // -----------------------------------------------------------------
    // To avoid the complexity of a map, we modify the detection methods
    // to directly return the character that satisfies the condition.
    // The original loops already compute the needed ids, so we simply
    // keep the character at that moment.
    // -----------------------------------------------------------------

    // Helper to fetch the character of the point identified by its stored id.
    private static char axisPosXChar(int id)   { return pointById(id).type; }
    private static char axisNegXChar(int id)   { return pointById(id).type; }
    private static char axisPosYChar(int id)   { return pointById(id).type; }
    private static char axisNegYChar(int id)   { return pointById(id).type; }

    private static char diagonalPosXPosYChar(int id) { return pointById(id).type; }
    private static char diagonalPosXNegYChar(int id) { return pointById(id).type; }
    private static char diagonalNegXPosYChar(int id) { return pointById(id).type; }
    private static char diagonalNegXNegYChar(int id) { return pointById(id).type; }

    /** Retrieves the Point object associated with a given id from the
     *  most‑recently processed list.  In this refactor we simply store the
     *  list in a static field before calling the decision routine.
     */
    private static Point pointById(int id) {
        // The id is guaranteed to be in the range 1..n, and the list
        // `currentPoints` holds exactly the points that were processed.
        return currentPoints.get(id - 1);
    }

    // -----------------------------------------------------------------
    // To keep the refactor self‑contained we store the last processed
    // point list in a thread‑local variable before invoking decision.
    // -----------------------------------------------------------------
    private static final java.lang.ThreadLocal<List<Point>> currentPoints = new java.lang.ThreadLocal<>();

    /** Modified solve method that captures the point list before decision. */
    private static void solveSingleCase(FastScanner in, java.io.PrintWriter out) {
        // ... (same reading code as before) ...

        // after building `points`:
        currentPoints.set(points);

        // now run the detection logic using the helpers above.
        DirectionalInfo axisInfo = findNearestAxisDirections(
                filterAxis(points));
        DiagonalQuadrantInfo diagonalInfo = findNearestDiagonalQuadrants(
                filterDiagonal(points));

        boolean answer = evaluateDecision(axisInfo, diagonalInfo);
        out.println(answer ? "YES" : "NO");
    }

    /** Returns only axis points from the given collection. */
    private static List<Point> filterAxis(List<Point> all) {
        List<Point> result = new ArrayList<>();
        for (Point p : all) {
            if (p.dx == 0 || p.dy == 0) {
                result.add(p);
            }
        }
        return result;
    }

    /** Returns only diagonal points (|dx| == |dy|, non‑zero). */
    private static List<Point> filterDiagonal(List<Point> all) {
        List<Point> result = new ArrayList<>();
        for (Point p : all) {
            if (p.dx != 0 && p.dy != 0 && Math.abs(p.dx) == Math.abs(p.dy)) {
                result.add(p);
            }
        }
        return result;
    }

    /** Checks whether a character is one of the allowed ones. */
    private static boolean isTypeAllowed(char actual, char... allowed) {
        for (char a : allowed) {
            if (a == actual) {
                return true;
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

public class AntonAndChess {

    /** Directions relative to the queen */
    private enum Direction { N, NE, E, SE, S, SW, W, NW }

    /** Simple holder for an obstacle together with its distance from the queen */
    private static final class Obstacle {
        final char type;          // 'R' or 'B' or 'Q'
        final int x, y;           // obstacle coordinates
        final long distance;      // steps from the queen (Manhattan distance)

        Obstacle(char type, int x, int y, long distance) {
            this.type = type;
            this.x = x;
            this.y = y;
            this.distance = distance;
        }
    }

    public static void main(String[] args) throws IOException {
        /* --------------------------------------------------------------
         * Input format (as in the original program):
         *   1st line  – number of obstacles (n)
         *   2nd line  – queen coordinates (xK yK)
         *   Next n lines – obstacle description: <type> <x> <y>
         * -------------------------------------------------------------- */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null) return;
            int numObstacles = Integer.parseInt(line.trim());

            // ----- read queen position -----
            String[] queenTokens = br.readLine().split("\\s+");
            int qx = Integer.parseInt(queenTokens[0]);
            int qy = Integer.parseInt(queenTokens[1]);

            // ----- track the closest obstacle in each direction -----
            Map<Direction, Optional<Obstacle>> nearest = new EnumMap<>(Direction.class);
            for (Direction d : Direction.values()) {
                nearest.put(d, Optional.empty());
            }

            // ----- process each obstacle -----
            for (int i = 0; i < numObstacles; i++) {
                String[] obsTokens = br.readLine().split("\\s+");
                char type = obsTokens[0].charAt(0);
                int ox = Integer.parseInt(obsTokens[1]);
                int oy = Integer.parseInt(obsTokens[2]);

                Direction dir = directionFromQueen(qx, qy, ox, oy);
                if (dir == null) {
                    continue;               // obstacle not aligned with the queen
                }

                long dist = Math.abs(qx - ox) + Math.abs(qy - oy); // steps to the queen
                Optional<Obstacle> current = nearest.get(dir);
                if (current.isEmpty() || dist < current.get().distance) {
                    nearest.put(dir, Optional.of(new Obstacle(type, ox, oy, dist)));
                }
            }

            // ----- determine if any opposing piece blocks the queen -----
            boolean blocked = nearest.values().stream()
                    .anyMatch(o -> o.type == 'R' || o.type == 'Q');

            System.out.println(blocked ? "YES" : "NO");
        }
    }

    /**
     * Returns the direction from the queen to the given cell, or {@code null}
     * if the cell is not on the same row, column or diagonal.
     */
    private static Direction directionFromQueen(int qx, int qy, int ox, int oy) {
        int dx = Integer.compare(ox, qx);
        int dy = Integer.compare(oy, qy);
        if (dx == 0 && dy == 0) {
            return null; // same square – should not occur for obstacles
        }

        if (dx == 0) {
            return dy > 0 ? Direction.N : Direction.S;
        }
        if (dy == 0) {
            return dx > 0 ? Direction.E : Direction.W;
        }
        if (Math.abs(dx) == Math.abs(dy)) {
            if (dx > 0 && dy > 0) return Direction.NE;
            if (dx > 0 && dy < 0) return Direction.SE;
            if (dx < 0 && dy < 0) return Direction.SW;
            return Direction.NW; // dx < 0 && dy > 0
        }
        return null; // not aligned
    }
}

import java.util.Optional;
import java.util.Scanner;

/**
 * Refactored solution for the “Queen’s Attack” problem.
 *
 * The program reads the board size, queen position and a list of opponent pieces.
 * It determines whether the queen can attack any opponent piece directly,
 * respecting the movement rules of rooks, bishops and queens.
 *
 * Maintainability improvements:
 *   • Meaningful naming and grouped constants.
 *   • Enum for the eight possible directions.
 *   • Small, single‑responsibility methods.
 *   • Removal of duplicated priority‑queues – a single map stores the closest piece per direction.
 *   • Clear separation of input parsing, movement analysis and output generation.
 */
public class D {

    /** Directions from the queen’s point of view. */
    private enum Direction {
        UP(0, 1),
        DOWN(0, -1),
        LEFT(-1, 0),
        RIGHT(1, 0),
        UP_RIGHT(1, 1),
        UP_LEFT(-1, 1),
        DOWN_RIGHT(1, -1),
        DOWN_LEFT(-1, -1);

        private final int dx;
        private final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        /** Returns the distance along this direction (always positive). */
        long distance(long dx, long dy) {
            return Math.abs(dx) == Math.abs(dy) ? Math.abs(dx) : Math.abs(dx) + Math.abs(dy);
        }

        /** Attempts to locate a piece that lies exactly on this direction. */
        static Optional<Direction> fromDelta(long dx, long dy) {
            for (Direction d : values()) {
                if (d.dx * dx >= 0 && d.dy * dy >= 0 && // same sign quadrant
                        (dx * d.dx == dy * d.dy) &&    // proportional (dx/dy == d.dx/d.dy)
                        Math.abs(dx) == Math.abs(dy) * (d.dx * d.dx) ) { // for straight lines both components are zero or equal magnitude
                    // The above logic collides; instead we test each direction explicitly:
                }
            }
            // Simpler approach: evaluate each direction explicitly.
            if (dx == 0 && dy > 0)        return Optional.of(UP);
            if (dx == 0 && dy < 0)        return Optional.of(DOWN);
            if (dx > 0 && dy == 0)        return Optional.of(RIGHT);
            if (dx < 0 && dy == 0)        return Optional.of(LEFT);
            if (dx > 0 && dy > 0 && dx == dy) return Optional.of(UP_RIGHT);
            if (dx < 0 && dy > 0 && -dx == dy) return Optional.of(UP_LEFT);
            if (dx > 0 && dy < 0 && dx == -dy) return Optional.of(DOWN_RIGHT);
            if (dx < 0 && dy < 0 && -dx == -dy) return Optional.of(DOWN_LEFT);
            return Optional.empty();
        }
    }

    /** Information about the closest piece found for a direction. */
    private static final class DirectionInfo {
        long distance = Long.MAX_VALUE; // distance of the nearest piece
        char pieceType;                  // 'R', 'B' or 'Q'

        void updateIfCloser(long distance, char type) {
            if (distance < this.distance) {
                this.distance = distance;
                this.pieceType = type;
            }
        }
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            long boardSize = sc.nextLong();          // unused – kept only to match input format
            long qx = sc.nextLong();
            long qy = sc.nextLong();

            // Store the nearest piece for each of the eight directions.
            DirectionInfo[] infos = new DirectionInfo[Direction.values().length];
            for (int i = 0; i < infos.length; i++) {
                infos[i] = new DirectionInfo();
            }

            int n = (int) boardSize;
            for (int i = 0; i < n; i++) {
                char type = sc.next().charAt(0);
                long x = sc.nextLong();
                long y = sc.nextLong();

                long dx = x - qx;
                long dy = y - qy;

                Direction dir = Direction.fromDelta(dx, dy);
                if (!dir.isPresent()) {
                    continue; // piece not aligned with the queen
                }

                long dist = dir.distance(dx, dy);
                infos[dir.get().ordinal()].updateIfCloser(dist, type);
            }

            boolean canAttack = checkAttack(infos);
            System.out.println(canAttack ? "YES" : "NO");
        }
    }

    /** Evaluates whether any direction contains a rook/queen (orthogonal) or bishop/queen (diagonal). */
    private static boolean checkAttack(DirectionInfo[] infos) {
        // orthogonal directions: UP, DOWN, LEFT, RIGHT
        if (any(infos[Direction.UP.ordinal()], 'R', 'Q') ||
            any(infos[Direction.DOWN.ordinal()], 'R', 'Q') ||
            any(infos[Direction.LEFT.ordinal()], 'R', 'Q') ||
            any(infos[Direction.RIGHT.ordinal()], 'R', 'Q')) {
            return true;
        }

        // diagonal directions: UP_RIGHT, UP_LEFT, DOWN_RIGHT, DOWN_LEFT
        return any(infos[Direction.UP_RIGHT.ordinal()], 'B', 'Q') ||
               any(infos[Direction.UP_LEFT.ordinal()], 'B', 'Q') ||
               any(infos[Direction.DOWN_RIGHT.ordinal()], 'B', 'Q') ||
               any(infos[Direction.DOWN_LEFT.ordinal()], 'B', 'Q');
    }

    /** Helper that returns true if the stored piece type matches one of the allowed types. */
    private static boolean any(DirectionInfo info, char... allowed) {
        return info.pieceType != 0 && java.util.Arrays.asList(allowed).contains(info.pieceType);
    }
}

/**
 * Refactored solution for the problem solved by the FastScanner.
 * The original logic has been reorganised into small, reusable pieces
 * that make the flow easier to follow and maintain.
 */
import java.io.*;
import java.util.*;
import java.util.regex.*;

public class Main {

    /** Direction vectors indexed 0‑7 */
    private static final int[] DX = { 1, 1, 0,-1,-1,-1, 0, 1 };
    private static final int[] DY = { 0, 1, 1, 1, 0,-1,-1, 0 };

    /** Minimum distance for each direction, filled with {@link Integer#MAX_VALUE} */
    private static final int[] MIN_DIST = new int[8];

    /** Symbol of the closest piece in each direction */
    private static final char[] CLOSEST_SYMBOL = new char[8];

    /** Marker for “no piece found yet” */
    private static final char NO_PIECE = '\u0000';

    /** Main entry point */
    public static void main(String[] args) {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new TaskD().solve(1, fs, out);
        out.close();
    }

    /** Core solving routine – unchanged signature required by the original template */
    static class TaskD {

        /** Entry point used by the original templates */
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            // ----- 1. read input -------------------------------------------------
            int n = in.nextInt();          // number of pieces
            int x0 = in.nextInt();          // rook position x
            int y0 = in.nextInt();          // rook position y
            int[] xs = new int[n];
            int[] ys = new int[n];
            char[] types = new char[n];

            String[] tokens = in.nextStringArray(); // array of three‑token rows

            for (int i = 0; i < n; i++) {
                tokens[i] = in.readToBuffer();          // obtain next line
                String[] parts = tokens[i].split("\\s+");
                types[i] = parts[0].charAt(0);
                xs[i] = Integer.parseInt(parts[1]);
                ys[i] = Integer.parseInt(parts[2]);
            }

            // ----- 2. initialise direction tables ---------------------------------
            Arrays.fill(MIN_DIST, Integer.MAX_VALUE);
            Arrays.fill(CLOSEST_SYMBOL, NO_PIECE);

            // ----- 3. find the closest piece in each of the 8 directions ---------
            for (int i = 0; i < n; i++) {
                int dx = xs[i] - x0;
                int dy = ys[i] - y0;

                // skip the rook square itself
                if (dx == 0 && dy == 0) {
                    continue;
                }

                // find the direction index (‑1 means “not one of the 8 directions”)
                int dirIdx = indexOfDirection(dx, dy);
                if (dirIdx == -1) {
                    continue;    // not on any of the 8 cardinal / diagonal lines
                }

                // distance to the piece – for axis directions it is |dx| (or |dy|),
                // for diagonal directions it is the absolute value of either component.
                int dist = (dx != 0) ? Math.abs(dx) : Math.abs(dy);

                if (dist < MIN_DIST[dirIdx]) {
                    MIN_DIST[dirIdx] = dist;
                    CLOSEST_SYMBOL[dirIdx] = types[i];
                }
            }

            // ----- 4. decide the answer -------------------------------------------
            boolean canCheckMate = false;
            for (int d = 0; d < 8; d++) {
                char piece = CLOSEST_SYMBOL[d];
                if (piece == NO_PIECE) {
                    continue;
                }
                // axis directions: 0,2,4,6  (right, up, left, down)
                if ((d & 1) == 0) {                 // even indices → axis direction
                    if (piece == 'Q' || piece == 'R') {
                        canCheckMate = true;
                        break;
                    }
                } else {                            // odd indices → diagonal direction
                    if (piece == 'Q' || piece == 'B') {
                        canCheckMate = true;
                        break;
                    }
                }
            }

            out.println(canCheckMate ? "YES" : "NO");
        }

        /**
         * Returns the direction index (0‑7) that corresponds to the vector (dx,dy)
         * or –1 if the vector does not lie exactly on one of the eight main
         * directions (horizontal, vertical, or diagonal).
         */
        private static int indexOfDirection(int dx, int dy) {
            // Normalise signs
            int signX = Integer.signum(dx);
            int signY = Integer.signum(dy);

            // Map (signX, signY) to a direction index
            switch (signX) {
                case 0: // vertical movement
                    if (signY > 0) return 2;   // up
                    if (signY < 0) return 6;   // down
                    return -1;               // should never happen (dx=dy=0 filtered earlier)
                case 1: // moving right
                    if (signY == 0) return 0;  // right (horizontal)
                    if (signY > 0) return 1;   // up‑right (diagonal)
                    if (signY < 0) return 7;   // down‑right (diagonal)
                    break;
                case -1: // moving left
                    if (signY == 0) return 4;  // left (horizontal)
                    if (signY > 0) return 3;   // up‑left (diagonal)
                    if (signY < 0) return 5;   // down‑left (diagonal)
                    break;
            }
            return -1; // not on a main direction
        }
    }

    /** Simple fast scanner that splits input on whitespace */
    static class FastScanner {
        private final BufferedReader reader;
        private String[] tokens;
        private int pos = 0;
        private static final Pattern WHITESPACE = Pattern.compile("\\s+");

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Reads the next line, splits it on whitespace and caches the array */
        private String[] fetchNextTokenArray() {
            try {
                return WHITESPACE.split(reader.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Returns the next token as an int */
        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        /** Returns the next raw token string (used to read a whole line) */
        String readToBuffer() {
            if (tokens == null || pos >= tokens.length) {
                tokens = fetchNextTokenArray();
                pos = 0;
            }
            return tokens[pos++];
        }

        /** Convenience method that reads a line and splits it (used for rows) */
        String[] nextStringArray() {
            return fetchNextTokenArray();
        }
    }
}

