/**
 * Refactored Chess threat detection.
 *
 * The program reads a board description from standard input and prints
 * "YES" if at least one opposing piece could capture the white king on the
 * next move, otherwise it prints "NO".
 *
 * Changes made for readability and maintainability:
 *  • Use meaningful class/enum names instead of many separate variables.
 *  • Extract helper methods for direction checks.
 *  • Replace magic numbers with named constants.
 *  • Use try‑with‑resources for I/O.
 *  • Group related state information in a small data holder.
 *  • Keep parsing logic separate from business logic.
 *
 * The original algorithm is preserved; only the structure and naming have
 * been improved.
 */
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;
import java.util.stream.Collectors;

/**
 * Holds information about a potential capturing piece.
 */
final class ThreatInfo {
    /** Manhattan distance to the king, {@link Integer#MAX_VALUE} indicates “unset”. */
    int distance;
    /** True if the piece can capture the king from this direction. */
    boolean threatens;

    ThreatInfo(int distance, boolean threatens) {
        this.distance = distance;
        this.threatens = threatens;
    }
}

/**
 * Represents the eight possible directions a piece may approach the king.
 */
enum Direction {
    NORTH(0, -1),
    SOUTH(0, 1),
    EAST(1, 0),
    WEST(-1, 0),
    NORTHEAST(1, -1),
    NORTHWEST(-1, -1),
    SOUTHEAST(1, 1),
    SOUTHWEST(-1, 1);

    private final int dx;
    private final int dy;

    Direction(int dx, int dy) {
        this.dx = dx;
        this.dy = dy;
    }

    /** Returns the distance (steps) from the king to the given coordinates. */
    int distance(int x, int y, int kingX, int kingY) {
        // Because dx/dy are never both zero, the absolute step count is max(|dx|,|dy|)
        // for diagonal moves and the sum of absolute deltas for orthogonal moves.
        return Math.max(Math.abs(dx), Math.abs(dy)); // for orthogonal moves this reduces to |dx|+|dy|
    }

    /** Helper to test if a move lies exactly in this direction from (kx,ky). */
    boolean isAlong(int kx, int ky, int x, int y) {
        int deltaX = x - kx;
        int deltaY = y - ky;
        if (deltaX == 0 && deltaY == 0) {
            return false;
        }
        return deltaX * dx >= 0 && deltaY * dy >= 0 &&   // same sign
               Math.abs(deltaX) == Math.abs(deltaY) ||  // diagonal
               (dx == 0 && deltaX == 0) ||               // vertical
               (dy == 0 && deltaY == 0);                  // horizontal
    }
}

/** Simple container for king coordinates. */
final class KingPosition {
    final int x;
    final int y;

    KingPosition(int x, int y) {
        this.x = x;
        this.y = y;
    }
}

/**
 * Main class that reads input, analyses threats and prints the result.
 */
public class Chess {
    /** sentinel value for “no threat recorded yet”. */
    private static final int UNSET = Integer.MAX_VALUE;

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // -----------------------------------------------------------------
            // 1️⃣  Parse board size and king position
            // -----------------------------------------------------------------
            String sizeLine = br.readLine();
            if (sizeLine == null || sizeLine.isBlank()) {
                return;
            }
            int pieceCount = Integer.parseInt(sizeLine.trim());

            String kingLine = br.readLine();
            KingPosition king = parseKingPosition(kingLine);

            // -----------------------------------------------------------------
            // 2️⃣  Initialise threat trackers (one per direction)
            // -----------------------------------------------------------------
            ThreatInfo[] threats = {
                    new ThreatInfo(UNSET, false), // north
                    new ThreatInfo(UNSET, false), // south
                    new ThreatInfo(UNSET, false), // east
                    new ThreatInfo(UNSET, false), // west
                    new ThreatInfo(UNSET, false), // north‑east
                    new ThreatInfo(UNSET, false), // north‑west
                    new ThreatInfo(UNSET, false), // south‑east
                    new ThreatInfo(UNSET, false)  // south‑west
            };

            // -----------------------------------------------------------------
            // 3️⃣  Process each piece
            // -----------------------------------------------------------------
            for (int i = 0; i < pieceCount; i++) {
                StringTokenizer st = new StringTokenizer(br.readLine());
                if (!st.hasMoreTokens()) {
                    continue;
                }
                String type = st.nextToken();
                int x = Integer.parseInt(st.nextToken());
                int y = Integer.parseInt(st.nextToken());

                // Only pieces that can move in straight lines can ever threaten the king.
                Direction dir = findDirection(king.x, king.y, x, y);
                if (dir == null) {
                    // Piece is not aligned with the king on any capture‑relevant line.
                    continue;
                }

                // Update the nearest piece in that direction.
                int distance = dir.distance(x, y, king.x, king.y);
                boolean threatens = !type.equals("B");          // original logic
                if (threatens) {
                    if (distance < threats[dir.ordinal()].distance) {
                        threats[dir.ordinal()] = new ThreatInfo(distance, true);
                    }
                }
            }

            // -----------------------------------------------------------------
            // 4️⃣  Determine if any threat exists
            // -----------------------------------------------------------------
            boolean captured = java.util.stream.Stream.of(threats)
                    .anyMatch(t -> t.threatens);

            System.out.println(captured ? "YES" : "NO");
        }
    }

    /** Parses a line like "3 5" into a {@link KingPosition}. */
    private static KingPosition parseKingPosition(String line) {
        String[] parts = line.trim().split("\\s+");
        int x = Integer.parseInt(parts[0].trim());
        int y = Integer.parseInt(parts[1].trim());
        return new KingPosition(x, y);
    }

    /**
     * Determines the {@link Direction} from the king to the given square.
     * Returns {@code null} if the square does not lie on any of the eight
     * capture‑relevant lines.
     */
    private static Direction findDirection(int kingX, int kingY, int x, int y) {
        int dx = x - kingX;
        int dy = y - kingY;

        // Diagonal lines
        if (Math.abs(dx) == Math.abs(dy) && dx != 0) {
            return (dx > 0) ? (dy > 0 ? Direction.SOUTHEAST : Direction.NORTHEAST)
                            : (dy > 0 ? Direction.SOUTHWEST : Direction.NORTHWEST);
        }

        // Horizontal / vertical lines
        if (dx == 0 && dy != 0) {
            return (dy > 0) ? Direction.SOUTH : Direction.NORTH;
        }
        if (dy == 0 && dx != 0) {
            return (dx > 0) ? Direction.EAST : Direction.WEST;
        }
        return null; // not aligned on a capture‑relevant line
    }
}

package;

import java.io.*;
import java.util.EnumMap;
import java.util.Map;

/**
 * Refactored solution for the “CheckMate” problem.
 *
 * <p>Original implementation performed a case‑by‑case scan of eight
 * directions around the king, keeping the nearest piece in each direction
 * and finally checking whether any of those pieces could give check.
 * The refactor replaces the manual switch‑based logic with an
 * {@link Direction} enum, an {@link Board} helper that stores the nearest
 * piece per direction, and a small {@link FastScanner} for fast input.
 *
 * <p>The public behaviour (reading from {@code System.in} and writing to
 * {@code System.out}) stays exactly the same.
 */
public class Main {

    /* --------------------------------------------------------------------- *
     *  Fast input utilities
     * --------------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Makes sure a {@link StringTokenizer} is ready and throws IOException on failure. */
        private void ensureTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        }

        String next() throws IOException {
            ensureTokenizer();
            return tokenizer.nextToken();
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    /* --------------------------------------------------------------------- *
     *  Core chess objects
     * --------------------------------------------------------------------- */
    /** Simple immutable representation of a piece on the board. */
    private static final class Piece {
        final char type;   // 'Q', 'R', 'B', …  (uppercase latin letters)
        final long x;
        final long y;

        Piece(char type, long x, long y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }

        /** Squared Euclidean distance to the given centre (no sqrt needed). */
        long squaredDistance(long cx, long cy) {
            long dx = x - cx;
            long dy = y - cy;
            return dx * dx + dy * dy;
        }
    }

    /** Eight compass directions around the king. */
    private enum Direction {
        NORTH(0, 1),
        NORTH_EAST(1, 1),
        EAST(1, 0),
        SOUTH_EAST(1, -1),
        SOUTH(0, -1),
        SOUTH_WEST(-1, -1),
        WEST(-1, 0),
        NORTH_WEST(-1, 1);

        final int dx;
        final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        /**
         * Determines the direction from {@code origin} to {@code target}.
         *
         * @throws IllegalArgumentException if the points are not aligned
         *         horizontally, vertically or diagonally.
         */
        static Direction fromDelta(long dx, long dy) {
            if (dx == 0 && dy > 0) return NORTH;
            if (dx > 0 && dy == 0) return EAST;
            if (dx == 0 && dy < 0) return SOUTH;
            if (dx < 0 && dy == 0) return WEST;
            if (dx > 0 && dy > 0 && dx == dy) return NORTH_EAST;
            if (dx > 0 && dy < 0 && dx == -dy) return SOUTH_EAST;
            if (dx < 0 && dy < 0 && -dx == -dy) return SOUTH_WEST;
            if (dx < 0 && dy > 0 && -dx == dy) return NORTH_WEST;
            throw new IllegalArgumentException("Invalid displacement: dx=" + dx + " dy=" + dy);
        }
    }

    /** Holds the king and the nearest piece in each of the eight directions. */
    private static final class Board {
        private final Piece king;
        /** Mapping direction → nearest piece found so far in that direction. */
        private final Map<Direction, Piece> nearest = new EnumMap<>(Direction.class);

        Board(char kingType, long kx, long ky) {
            // The problem statement always uses 'K' as the king's symbol.
            this.king = new Piece(kingType, kx, ky);
        }

        /** Adds a new black piece, updating the nearest map if it is closer. */
        void addPiece(char type, long x, long y) {
            Piece p = new Piece(type, x, y);
            Direction dir = Direction.fromDelta(x - king.x, y - king.y);
            Piece current = nearest.get(dir);
            if (current == null || p.squaredDistance(king.x, king.y) < current.squaredDistance(king.x, king.y)) {
                nearest.put(dir, p);
            }
        }

        /** Returns true if any adjacent piece can give check (i.e., the king is in checkmate). */
        boolean isCheckMate() {
            for (Piece p : nearest.values()) {
                if (canAttack(p)) {
                    return true;
                }
            }
            return false;
        }

        /** Checks whether a piece attacks the king according to standard chess rules. */
        private boolean canAttack(Piece p) {
            // Same file or rank → rook or queen
            if ((p.x == king.x || p.y == king.y) && (p.type == 'R' || p.type == 'Q')) {
                return true;
            }
            // Diagonal → bishop or queen
            long dx = Math.abs(p.x - king.x);
            long dy = Math.abs(p.y - king.y);
            if (dx == dy && (p.type == 'B' || p.type == 'Q')) {
                return true;
            }
            return false;
        }
    }

    /* --------------------------------------------------------------------- *
     *  Main driver
     * --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        long blackCount = fs.nextLong();               // number of black pieces
        long kingX = fs.nextLong();
        long kingY = fs.nextLong();

        Board board = new Board('K', kingX, kingY);

        for (long i = 0; i < blackCount; ++i) {
            char type = fs.next().charAt(0);
            long x = fs.nextLong();
            long y = fs.nextLong();
            board.addPiece(type, x, y);
        }

        out.println(board.isCheckMate() ? "YES" : "NO");
        out.close();
    }
}

import java.io.*;
import java.util.*;

public class Smell {

    /** Simple immutable holder for a chess piece. */
    private static final class Piece {
        final char id;          // piece identifier
        final long x, y;        // coordinates
        final PieceType type;   // logical type (ROOK, BISHOP, QUEEN)

        Piece(char id, long x, long y) {
            this.id = id;
            this.x = x;
            this.y = y;
            this.type = PieceType.of(id);
        }

        /** Convert a character identifier to its logical type. */
        private static PieceType of(char id) {
            return switch (id) {
                case 'R', 'Q' -> PieceType.ROOK;
                case 'B' -> PieceType.BISHOP;
                default -> PieceType.UNKNOWN;
            };
        }
    }

    /** Logical classification of a piece – used only for the final answer. */
    private enum PieceType { ROOK, BISHOP, QUEEN, UNKNOWN }

    /** Directional constants used to decide in which of the 8 rays a piece lies. */
    private enum Ray {
        NORTH(0, -1, 0),
        SOUTH(0, 1, 1),
        WEST(-1, 0, 2),
        EAST(1, 0, 3),
        NORTH_WEST(-1, -1, 4),
        NORTH_EAST(1, -1, 5),
        SOUTH_WEST(-1, 1, 6),
        SOUTH_EAST(1, 1, 7);

        final int index;   // 0‑7 as used in the original code
        final int dx, dy;  // step to move away from the reference point

        Ray(int dx, int dy, int index) {
            this.dx = dx;
            this.dy = dy;
            this.index = index;
        }
    }

    public static void main(String[] args) throws Exception {
        // Try‑with‑resources guarantees proper stream closure.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String nLine = br.readLine();
            int pieceCount = Integer.parseInt(nLine.trim());

            String[] originLine = br.readLine().split("\\s+");
            long originX = Long.parseLong(originLine[0]);
            long originY = Long.parseLong(originLine[1]);

            Piece[] pieces = new Piece[pieceCount];
            for (int i = 0; i < pieceCount; i++) {
                String[] tokens = br.readLine().split("\\s+");
                pieces[i] = new Piece(tokens[0].charAt(0),
                                      Long.parseLong(tokens[1]),
                                      Long.parseLong(tokens[2]));
            }

            ClosestTracker tracker = new ClosestTracker();
            for (Piece p : pieces) {
                tracker.consider(p, originX, originY);
            }

            System.out.println(tracker.hasRelevantClosest() ? "YES" : "NO");
        }
    }

    /** Euclidean distance used only for comparison – kept identical to the original. */
    private static double distance(long x1, long y1, long x2, long y2) {
        long dx = x1 - x2;
        long dy = y1 - y2;
        return Math.sqrt(dx * dx + dy * dy);
    }

    /** Tracks, for each of the eight rays, the closest piece that lies on that ray. */
    private static final class ClosestTracker {
        /** One entry per directional ray (0‑7). */
        private final Tracked[] entries = new Tracked[8];

        ClosestTracker() {
            for (int i = 0; i < 8; i++) {
                entries[i] = new Tracked();
            }
        }

        /** Examine a piece and, if it lies exactly on one of the eight rays, update the tracker. */
        void consider(Piece piece, long refX, long refY) {
            long dx = piece.x - refX;
            long dy = piece.y - refY;

            if (dx == 0) {                     // vertical ray
                int rayIdx = (dy < 0) ? Ray.NORTH.index : Ray.SOUTH.index;
                update(rayIdx, piece, Math.abs(dy));
            } else if (dy == 0) {                // horizontal ray
                int rayIdx = (dx < 0) ? Ray.WEST.index : Ray.EAST.index;
                update(rayIdx, piece, Math.abs(dx));
            } else if (Math.abs(dx) == Math.abs(dy)) {   // diagonal ray
                // Determine the exact diagonal direction.
                if (dx < 0 && dy < 0) {               // South‑West
                    update(Ray.SOUTH_WEST.index, piece, Math.abs(dx));
                } else if (dx > 0 && dy < 0) {        // South‑East
                    update(Ray.SOUTH_EAST.index, piece, Math.abs(dx));
                } else if (dx < 0 && dy > 0) {        // North‑West
                    update(Ray.NORTH_WEST.index, piece, Math.abs(dx));
                } else {                              // North‑East
                    update(Ray.NORTH_EAST.index, piece, Math.abs(dx));
                }
            }
            // Pieces that do not share a ray with the origin are ignored.
        }

        /** Update the entry for a given ray if the supplied distance is smaller. */
        private void update(int rayIdx, Piece piece, long distance) {
            Tracked cur = entries[rayIdx];
            if (distance < cur.minDist) {
                cur.minDist = distance;
                cur.closest = piece;
            }
        }

        /** Return true if any orthogonal ray (0‑3) contains a rook or queen that is the closest,
         *  or any diagonal ray (4‑7) contains a bishop or queen that is the closest. */
        boolean hasRelevantClosest() {
            // Orthogonal rays (rook / queen)
            for (int i = 0; i < 4; i++) {
                Tracked t = entries[i];
                if (t.closest != null && (t.closest.id == 'R' || t.closest.id == 'Q')) {
                    return true;
                }
            }
            // Diagonal rays (bishop / queen)
            for (int i = 4; i < 8; i++) {
                Tracked t = entries[i];
                if (t.closest != null && (t.closest.id == 'B' || t.closest.id == 'Q')) {
                    return true;
                }
            }
            return false;
        }

        /** Simple container for a tracked piece and its distance from the reference point. */
        private static final class Tracked {
            Piece closest;
            double minDist = Double.POSITIVE_INFINITY;

            Tracked() { }
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.function.Predicate;

/**
 * Refactored version of the original solution.
 *
 * <p>Changes made for maintainability and readability:
 *
 * <ul>
 *   <li>Small, single‑responsibility classes (FastScanner, OutputWriter, Chess, Direction).
 *   <li>Extracted core game logic into {@link GameSolver}.
 *   <li>Replaced duplicated line‑checking code with a generic direction‑based approach.
 *   <li>Used enumerated directions and reduced delta vectors to avoid magic numbers.
 *   <li>Added meaningful method names and Javadoc.
 *   <li>Removed unnecessary imports and duplicate fields.
 * </ul>
 *
 * The functionality is identical to the original program: it reads a board description,
 * determines whether the white king at position (kx, ky) can be captured by any rook,
 * bishop or queen placed on the board, and prints “YES” or “NO”.
 */
public class Main {

    /** Entry point – delegates work to {@link GameSolver}. */
    public static void main(String[] args) {
        var scanner = new FastScanner(System.in);
        var out = new OutputWriter(System.out);
        new GameSolver().solve(scanner, out);
        out.close();
    }

    /** Core logic that decides if the king is attackable. */
    static class GameSolver {
        /** Reads input, processes the board and writes the result. */
        void solve(FastScanner in, OutputWriter out) {
            int n = in.nextInt();          // number of pieces
            int kx = in.nextInt();         // king X
            int ky = in.nextInt();         // king Y

            // Group pieces by their type (character)
            Map<Character, List<Chess>> piecesByType = new HashMap<>();
            for (int i = 0; i < n; i++) {
                char type = in.nextToken();
                int x = in.nextInt();
                int y = in.nextInt();
                piecesByType.computeIfAbsent(type, k -> new ArrayList<>()).add(
                        new Chess(type, x, y));
            }

            boolean attacked = isAttackedByRookOrQueen(kx, ky, piecesByType) ||
                               isAttackedByBishopOrQueen(kx, ky, piecesByType);
            out.print(attacked ? "YES" : "NO");
        }

        /** Checks whether any rook or queen on the board can capture the king. */
        private boolean isAttackedByRookOrQueen(int kx, int ky,
                                                  Map<Character, List<Chess>> byType) {
            return findClosestInDirection(kx, ky, byType,
                    Chess::isRookOrQueen,
                    Chess::isHorizontalOrVertical);
        }

        /** Checks whether any bishop or queen on the board can capture the king. */
        private boolean isAttackedByBishopOrQueen(int kx, int ky,
                                                    Map<Character, List<Chess>> byType) {
            return findClosestInDirection(kx, ky, byType,
                    Chess::isBishopOrQueen,
                    Chess::isDiagonal);
        }

        /**
         * Generic scanner that looks along the eight directions emanating from the king.
         *
         * @param kx          king X coordinate
         * @param ky          king Y coordinate
         * @param byType      pieces grouped by type
         * @param typePredicate predicate that identifies a piece that can attack
         * @param linePredicate predicate that checks if a piece lies on a relevant line
         * @return {@code true} if the nearest piece in any direction satisfies the predicates
         */
        private boolean findClosestInDirection(int kx, int ky,
                                                Map<Character, List<Chess>> byType,
                                                Predicate<Chess> typePredicate,
                                                Predicate<Chess> linePredicate) {
            // Map each direction to the pieces that lie on that ray
            Map<Direction, List<Chess>> byDir = new EnumMap<>(Direction.class);

            for (List<Chess> list : byType.values()) {
                for (Chess p : list) {
                    int dx = p.x - kx;
                    int dy = p.y - ky;
                    if (dx == 0 && dy == 0) continue;               // ignore self
                    if (!linePredicate.test(p)) continue;           // not on a relevant line

                    Direction dir = Direction.fromDelta(dx, dy);
                    byDir.computeIfAbsent(dir, k -> new ArrayList<>()).add(p);
                }
            }

            // Examine each occupied direction – only the closest piece matters
            for (List<Chess> ray : byDir.values()) {
                // Sort by distance from the king (Manhattan works because we are on a straight line)
                ray.sort(Comparator.comparingInt(p -> Math.abs(p.x - kx) + Math.abs(p.y - ky)));
                Chess closest = ray.get(0);
                if (typePredicate.test(closest)) {
                    return true;
                }
            }
            return false;
        }
    }

    /** Simple immutable representation of a chess piece on the board. */
    static final class Chess {
        final char type;   // 'R', 'B', or 'Q'
        final int x, y;    // board coordinates

        Chess(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }

        /** Can this piece move like a rook or queen? */
        boolean isRookOrQueen() {
            return type == 'R' || type == 'Q';
        }

        /** Can this piece move like a bishop or queen? */
        boolean isBishopOrQueen() {
            return type == 'B' || type == 'Q';
        }

        /** Is the piece aligned horizontally or vertically with the king? */
        boolean isHorizontalOrVertical() {
            return x == this.x || y == this.y;
        }

        /** Is the piece aligned diagonally with the king? */
        boolean isDiagonal() {
            return Math.abs(x - this.x) == Math.abs(y - this.y) && (x != this.x);
        }

        @Override
        public String toString() {
            return String.format("Chess{type='%c', x=%d, y=%d}", type, x, y);
        }
    }

    /**
     * Represents one of the eight compass directions.
     * The {@code fromDelta} method creates a direction from a raw delta vector.
     */
    enum Direction {
        UP(0, 1),
        DOWN(0, -1),
        LEFT(-1, 0),
        RIGHT(1, 0),
        UP_RIGHT(1, 1),
        UP_LEFT(-1, 1),
        DOWN_RIGHT(1, -1),
        DOWN_LEFT(-1, -1);

        final int dx, dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        /** Convert a raw delta into a normalized direction (used by the solver). */
        static Direction fromDelta(int dx, int dy) {
            if (dx == 0) {
                return dy > 0 ? UP : DOWN;
            }
            if (dy == 0) {
                return dx > 0 ? RIGHT : LEFT;
            }
            if (Math.abs(dx) == Math.abs(dy)) {
                return switch (dx) {
                    case 1 -> dy == 1 ? UP_RIGHT : DOWN_RIGHT;
                    -1 -> dy == 1 ? UP_LEFT : DOWN_LEFT;
                    default -> throw new IllegalArgumentException();
                };
            }
            // Should never happen – callers guarantee diagonal or axis alignment.
            throw new IllegalArgumentException("Non‑axis‑aligned delta: (" + dx + "," + dy + ")");
        }
    }

    /** Fast scanner that works with large input without excessive buffering. */
    static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[16 * 1024];
        private int ptr = 0, len = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (len < 0) throw new IllegalStateException();
            if (ptr >= len) {
                len = stream.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** Reads next integer (supports negative numbers). */
        int nextInt() throws IOException {
            int c = skipUntilSpace();
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            int value = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                value = value * 10 + (c - '0');
                c = readByte();
            } while (!isSpaceChar(c));
            return neg ? -value : value;
        }

        /** Reads the next non‑space character (used for piece type). */
        char nextTokenChar() throws IOException {
            int c;
            do {
                c = readByte();
            } while (isSpaceChar(c));
            return (char) c;
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private int skipUntilSpace() throws IOException {
            int c;
            do {
                c = readByte();
            } while (!isSpaceChar(c));
            return c;
        }
    }

    /** Simple writer that prints tokens separated by spaces and flushes on demand. */
    static final class OutputWriter {
        private final PrintWriter writer;
        OutputWriter(OutputStream out) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        /** Prints a variable number of objects separated by spaces (no trailing space). */
        void print(Object... objs) {
            for (int i = 0; i < objs.length; i++) {
                if (i != 0) writer.print(' ');
                writer.print(objs[i]);
            }
            writer.flush();
        }

        /** Closes the underlying stream. */
        void close() {
            writer.close();
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.function.LongBinaryOperator;

/**
 * Refactored solution for the “check” problem.
 *
 * <p>Key improvements compared to the original source:
 *
 * <ul>
 *   <li>Input handling is isolated in a small helper class.
 *   <li>All variables have expressive names.
 *   <li>Direction limits (the “blocking distances”) are calculated once and stored in a
 *       dedicated data holder.
 *   <li>Piece‑type handling is delegated to an {@link Piece} enum.
 *   <li>Repeated checks are extracted into small, pure methods.
 *   <li>Method bodies are short and focused – making the code easier to test and maintain.
 * </ul>
 *
 * The functional behaviour is identical to the original program.
 */
public class Main {

    /** Simple holder for the eight directional limits used during the check test. */
    private static final class DirectionLimits {
        final long up, down, left, right;
        final long upRight, upLeft, downRight, downLeft;

        DirectionLimits(long up, long down, long left, long right,
                        long upRight, long upLeft, long downRight, long downLeft) {
            this.up = up;
            this.down = down;
            this.left = left;
            this.right = right;
            this.upRight = upRight;
            this.upLeft = upLeft;
            this.downRight = downRight;
            this.downLeft = downLeft;
        }
    }

    /** Types of pieces described in the problem statement. */
    private enum PieceType {
        FERZ("F"),
        ROOK("R"),
        KING("S");

        private final String token;

        PieceType(String token) {
            this.token = token;
        }

        String getToken() {
            return token;
        }
    }

    /** Holds the coordinates of a point on the board. */
    private static final class Point {
        final long x, y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Parser that reads tokens from {@link BufferedReader}. */
    private static final class InputParser {
        private final BufferedReader reader;
        private StringTokenizer currentTokenizer;

        InputParser(BufferedReader reader) {
            this.reader = reader;
        }

        /** Returns the next token, reading a new line when the current one is exhausted. */
        private String nextToken() throws IOException {
            while (currentTokenizer == null || !currentTokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null || line.isBlank()) {
                    return nextToken(); // continue until a non‑empty line is found
                }
                currentTokenizer = new StringTokenizer(line);
            }
            return currentTokenizer.nextToken();
        }

        /** Reads a fixed number of tokens from the input. */
        List<String> readTokens(int count) throws IOException {
            List<String> tokens = new ArrayList<>(count);
            for (int i = 0; i < count; i++) {
                tokens.add(nextToken());
            }
            return tokens;
        }
    }

    /** Holds the coordinates of the rook (the “king” in the original code). */
    private static final class RookPosition {
        final long x, y;

        RookPosition(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Simple wrapper around a piece together with its position. */
    private static final class PieceInstance {
        final PieceType type;
        final Point position;

        PieceInstance(PieceType type, Point position) {
            this.type = type;
            this.position = position;
        }
    }

    /** Limits for the eight directions used by the attack‑checking algorithm. */
    private static final class DirectionLimitsCalculator {
        /** Calculates the minimum distance to a blocker for each of the eight directions. */
        DirectionLimits calculate(
                long rookX, long rookY,
                List<PieceInstance> ferzs,
                List<PieceInstance> rooks,
                List<PieceInstance> kings) {

            long up = Long.MAX_VALUE;
            long down = Long.MAX_VALUE;
            long left = Long.MAX_VALUE;
            long right = Long.MAX_VALUE;
            long upRight = Long.MAX_VALUE;
            long upLeft = Long.MAX_VALUE;
            long downRight = Long.MAX_VALUE;
            long downLeft = Long.MAX_VALUE;

            // ----- vertical / horizontal blockers (kings) -----
            for (PieceInstance king : kings) {
                if (king.position.x == rookX) {
                    long dy = king.position.y > rookY ? king.position.y - rookY : rookY - king.position.y;
                    if (king.position.y > rookY) {
                        up = Math.min(up, dy);
                    } else {
                        down = Math.min(down, dy);
                    }
                }
                if (king.position.y == rookY) {
                    long dx = king.position.x > rookX ? king.position.x - rookX : rookX - king.position.x;
                    if (king.position.x > rookX) {
                        right = Math.min(right, dx);
                    } else {
                        left = Math.min(left, dx);
                    }
                }
            }

            // ----- diagonal blockers (rooks) -----
            for (PieceInstance rook : rooks) {
                // main diagonal (↘)
                if (rook.position.x - rook.position.y == rookX - rookY) {
                    long dx = rook.position.x > rookX ? rook.position.x - rookX : rookX - rook.position.x;
                    if (rook.position.x > rookX) {
                        upRight = Math.min(upRight, dx);
                    } else {
                        downLeft = Math.min(downLeft, dx);
                    }
                }
                // anti‑diagonal (↙)
                if (rook.position.x + rook.position.y == rookX + rookY) {
                    long dx = rook.position.x > rookX ? rook.position.x - rookX : rookX - rook.position.x;
                    if (rook.position.x > rookX) {
                        downRight = Math.min(downRight, dx);
                    } else {
                        upLeft = Math.min(upLeft, dx);
                    }
                }
            }

            return new DirectionLimits(up, down, left, right,
                    upRight, upLeft, downRight, downLeft);
        }
    }

    /** Determines whether the rook can be captured given the computed direction limits. */
    private static boolean canRookBeCaptured(
            long rookX, long rookY,
            List<PieceInstance> ferzs,
            List<PieceInstance> rooks,
            List<PieceInstance> kings,
            DirectionLimits limits) {

        // Helper that checks whether a candidate piece lies inside the allowed range for a given direction.
        LongBinaryOperator inRange = dx -> {
            // Diagonal cases
            if (dx == rookX - rookY) {
                long step = dx > 0 ? limits.upRight : limits.downLeft;
                return dx > 0 ? dx < step : -dx < step;
            }
            if (dx == rookX + rookY) {
                long step = dx > 0 ? limits.downRight : limits.upLeft;
                return dx > 0 ? dx < step : -dx < step;
            }
            // Orthogonal cases
            long absDx = Math.abs(dx);
            return absDx < (dx > 0 ? limits.up : limits.down);
        };

        // ----- check Ferz pieces -----
        for (PieceInstance p : ferzs) {
            long dx = p.position.x - rookX;
            long dy = p.position.y - rookY;

            boolean canCapture = false;
            // same file / rank
            if (dx == 0) {
                canCapture = dy > 0 ? dy < limits.up : -dy < limits.down;
            } else if (dy == 0) {
                canCapture = dx > 0 ? dx < limits.right : -dx < limits.left;
            }
            // diagonals
            else if (dx == dy) {
                canCapture = dx > 0 ? dx < limits.upRight : -dx < limits.downLeft;
            } else if (dx == -dy) {
                canCapture = dx > 0 ? dx < limits.downRight : -dx < limits.upLeft;
            }
            if (canCapture) {
                return true;
            }
        }

        // ----- check Rook pieces -----
        for (PieceInstance p : rooks) {
            long dx = p.position.x - rookX;
            long dy = p.position.y - rookY;

            boolean canCapture = false;
            if (dx == 0) {
                canCapture = dy > 0 ? dy < limits.up : -dy < limits.down;
            } else if (dy == 0) {
                canCapture = dx > 0 ? dx < limits.right : -dx < limits.left;
            }
            if (canCapture) {
                return true;
            }
        }

        // ----- check King pieces -----
        for (PieceInstance p : kings) {
            long dx = p.position.x - rookX;
            long dy = p.position.y - rookY;

            // King can move only one square orthogonally or diagonally.
            if (Math.abs(dx) <= 1 && Math.abs(dy) <= 1) {
                // The only extra condition is that there is no blocker closer in that direction.
                // Because the limits already represent the nearest blocker, we simply compare.
                boolean reachable = (dx == 0 && (dy > 0 ? dy < limits.up : -dy < limits.down)) ||
                                  (dy == 0 && (dx > 0 ? dx < limits.right : -dx < limits.left)) ||
                                  (Math.abs(dx) == Math.abs(dy) && ((dx > 0 && dx < limits.upRight) ||
                                                                    (dx < 0 && -dx < limits.upLeft) ||
                                                                    (dx > 0 && dx < limits.downRight) ||
                                                                    (dx < 0 && -dx < limits.downLeft)));

                if (reachable) {
                    return true;
                }
            }
        }

        return false;
    }

    /** Reads the whole test case from {@link InputParser}. */
    private static List<PieceInstance> readPieces(InputParser parser, int n) throws IOException {
        List<PieceInstance> pieces = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            String[] parts = parser.readTokens(3);
            PieceType type = PieceType.valueOf(parts[0]);
            long x = Long.parseLong(parts[1]);
            long y = Long.parseLong(parts[2]);
            pieces.add(new PieceInstance(type, new Point(x, y)));
        }
        return pieces;
    }

    /** Main driver – glues everything together. */
    private static void solve(BufferedReader reader) throws IOException {
        InputParser parser = new InputParser(reader);

        // header: n  x0  y0
        String[] header = parser.readTokens(3);
        int n = Integer.parseInt(header[0]);
        long x0 = Long.parseLong(header[1]);
        long y0 = Long.parseLong(header[2]);

        List<PieceInstance> ferzs = new ArrayList<>();
        List<PieceInstance> rooks = new ArrayList<>();
        List<PieceInstance> kings = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            String[] parts = parser.readTokens(3);
            PieceType type = PieceType.valueOf(parts[0]);
            long x = Long.parseLong(parts[1]);
            long y = Long.parseLong(parts[2]);
            switch (type) {
                case FERZ -> ferzs.add(new PieceInstance(type, new Point(x, y)));
                case ROOK -> rooks.add(new PieceInstance(type, new Point(x, y)));
                case KING -> kings.add(new PieceInstance(type, new Point(x, y)));
            }
        }

        DirectionLimitsCalculator calculator = new DirectionLimitsCalculator();
        DirectionLimits limits = calculator.calculate(x0, y0, ferzs, rooks, kings);

        boolean canCapture = canRookBeCaptured(x0, y0, ferzs, rooks, kings, limits);
        System.out.println(canCapture ? "YES" : "NO");
    }

    /** Entry point used by the original program. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            solve(br);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.EnumMap;
import java.util.Map;

/**
 * Determines whether any piece positioned on an 8×8 board can capture a
 * queen placed at (queenX, queenY) according to the rules of chess.
 *
 * <p>Refactorings performed:
 * <ul>
 *   <li>Extracted {@code Piece} into a {@link record} for immutability.</li>
 *   <li>Introduced a {@link Direction} enum to replace scattered direction logic.</li>
 *   <li>Created a {@link ClosestInfo} holder to keep the nearest piece per direction.</li>
 *   <li>Removed magic numbers, lengthy {@code if‑else} blocks and duplicated checks.</li>
 *   <li>Used {@code try‑with‑resources} for safe I/O handling.</li>
 *   <li>Extracted helper methods to keep {@code main} focused on program flow.</li>
 * </ul>
 */
public class Main {

    /** Direction on the board together with its movement vector. */
    private enum Direction {
        UP(0, 1),
        DOWN(0, -1),
        LEFT(-1, 0),
        RIGHT(1, 0),
        UP_RIGHT(1, 1),
        UP_LEFT(-1, 1),
        DOWN_RIGHT(1, -1),
        DOWN_LEFT(-1, -1);

        private final int deltaX;
        private final int deltaY;

        Direction(int deltaX, int deltaY) {
            this.deltaX = deltaX;
            this.deltaY = deltaY;
        }

        /** Returns the direction that matches the supplied delta, or {@code null} if none matches. */
        static Direction fromDelta(int deltaX, int deltaY) {
            if (deltaX == 0 && deltaY > 0) return UP;
            if (deltaX == 0 && deltaY < 0) return DOWN;
            if (deltaY == 0 && deltaX > 0) return RIGHT;
            if (deltaY == 0 && deltaX < 0) return LEFT;

            // Diagonal directions – magnitudes must be equal
            int absX = Math.abs(deltaX);
            int absY = Math.abs(deltaY);
            if (absX != absY) return null;

            if (deltaX > 0 && deltaY > 0) return UP_RIGHT;
            if (deltaX < 0 && deltaY > 0) return UP_LEFT;
            if (deltaX > 0 && deltaY < 0) return DOWN_RIGHT;
            if (deltaX < 0 && deltaY < 0) return DOWN_LEFT;
            return null;
        }

        /** Is this direction orthogonal (horizontal / vertical)? */
        boolean isOrthogonal() {
            return deltaX == 0 || deltaY == 0;
        }

        /** Is this direction diagonal? */
        boolean isDiagonal() {
            return !isOrthogonal();
        }
    }

    /** Simple container for the closest piece found in a given direction. */
    private static final class ClosestInfo {
        final int distance;   // Manhattan distance measured along the direction axis
        char piece;           // Name of the piece that occupies the closest square

        ClosestInfo(int distance, char piece) {
            this.distance = distance;
            this.piece = piece;
        }
    }

    public static void main(String[] args) throws IOException {
        // -----------------------------------------------------------------
        // 1️⃣  Read input safely
        // -----------------------------------------------------------------
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] firstLineTokens = br.readLine().split("\\s+");
            int pieceCount = Integer.parseInt(firstLineTokens[0]);

            String[] queenPosTokens = br.readLine().split("\\s+");
            int queenX = Integer.parseInt(queenPosTokens[0]);
            int queenY = Integer.parseInt(queenPosTokens[1]);

            // Map each direction to the nearest piece discovered so far
            Map<Direction, ClosestInfo> closestByDirection = new EnumMap<>(Direction.class);
            for (Direction dir : Direction.values()) {
                closestByDirection.put(dir, new ClosestInfo(Integer.MAX_VALUE, '\0'));
            }

            // -----------------------------------------------------------------
            // 2️⃣  Process every piece and update the nearest‑piece information
            // -----------------------------------------------------------------
            for (int i = 0; i < pieceCount; i++) {
                String[] pieceTokens = br.readLine().split("\\s+");
                char pieceName = pieceTokens[0].charAt(0);
                int px = Integer.parseInt(pieceTokens[1]);
                int py = Integer.parseInt(pieceTokens[2]);

                processPiece(closestByDirection, pieceName, px, py, queenX, queenY);
            }

            // -----------------------------------------------------------------
            // 3️⃣  Determine whether a capturing move exists
            // -----------------------------------------------------------------
            if (canCapture(closestByDirection)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Updates the {@code closestByDirection} map with the closest piece that lies
     * in the given {@code direction} relative to the queen.
     */
    private static void processPiece(
            Map<Direction, ClosestInfo> closestByDirection,
            char pieceName,
            int px,
            int py,
            int queenX,
            int queenY) {

        int deltaX = px - queenX;
        int deltaY = py - queenY;

        Direction dir = Direction.fromDelta(deltaX, deltaY);
        if (dir == null) {
            // Not aligned (neither orthogonal nor diagonal) – ignore
            return;
        }

        int distance;
        if (dir.isOrthogonal()) {
            // For orthogonal moves the distance is simply the absolute coordinate change.
            distance = Math.max(Math.abs(deltaX), Math.abs(deltaY));
        } else { // diagonal
            distance = Math.abs(deltaX); // |dx| == |dy| for a true diagonal
        }

        ClosestInfo current = closestByDirection.get(dir);
        if (distance < current.distance) {
            closestByDirection.put(dir, new ClosestInfo(distance, pieceName));
        }
    }

    /**
     * Checks whether any orthogonal direction contains a Rook or Queen,
     * or any diagonal direction contains a Bishop or Queen.
     *
     * @return {@code true} if capture is possible, {@code false} otherwise.
     */
    private static boolean canCapture(Map<Direction, ClosestInfo> closestByDirection) {
        // Orthogonal directions → Rook or Queen
        for (Direction dir : Direction.values()) {
            if (!dir.isOrthogonal()) {
                continue;
            }
            ClosestInfo info = closestByDirection.get(dir);
            if (info.distance != Integer.MAX_VALUE && (info.piece == 'R' || info.piece == 'Q')) {
                return true;
            }
        }

        // Diagonal directions → Bishop or Queen
        for (Direction dir : Direction.values()) {
            if (!dir.isDiagonal()) {
                continue;
            }
            ClosestInfo info = closestByDirection.get(dir);
            if (info.distance != Integer.MAX_VALUE && (info.piece == 'B' || info.piece == 'Q')) {
                return true;
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.EnumMap;
import java.util.StringTokenizer;

/**
 * Refactored version of the original {@code AntonAndChess} program.
 *
 * <p>The program reads a set of chess pieces (rook, bishop or queen) placed on an
 * infinite board together with the position of a white king. It determines
 * whether any of the given pieces can capture the king according to standard
 * chess movement rules (rooks on ranks/files, bishops on diagonals, queens on
 * both). The answer is printed as {@code "YES"} or {@code "NO"}.
 *
 * <p>The implementation uses an {@code EnumMap} keyed by the eight compass
 * directions to store the closest opponent piece in each direction. This
 * eliminates the large numeric arrays and tangled conditional logic from the
 * original code.
 */
public class AntonAndChess {

    /** The eight compass directions relative to the king. */
    private enum Direction {
        UP,          // (0,  +1)
        UP_RIGHT,    // (+1, +1)
        RIGHT,       // (+1, 0)
        DOWN_RIGHT,  // (+1, -1)
        DOWN,        // (0, -1)
        DOWN_LEFT,   // (-1, -1)
        LEFT,        // (-1, 0)
        UP_LEFT      // (-1, +1)
    }

    /**
     * Determines the {@link Direction} that corresponds to the given offset.
     *
     * @param dx horizontal offset (target – king)
     * @param dy vertical   offset (target – king)
     * @return a {@link Direction} if the offset lies on a straight line or
     *         a diagonal with equal magnitude; otherwise {@code null}.
     */
    private static Direction directionFromDelta(long dx, long dy) {
        if (dx == 0 && dy == 0) {
            return null;
        }
        if (dx == 0) {
            return (dy > 0) ? Direction.UP : Direction.DOWN;
        }
        if (dy == 0) {
            return (dx > 0) ? Direction.RIGHT : Direction.LEFT;
        }
        if (Math.abs(dx) == Math.abs(dy)) {
            if (dx > 0) {
                return (dy > 0) ? Direction.UP_RIGHT : Direction.DOWN_RIGHT;
            } else {
                return (dy > 0) ? Direction.UP_LEFT : Direction.DOWN_LEFT;
            }
        }
        // Not aligned with the king in any of the allowed ways.
        return null;
    }

    /** Simple immutable holder for a chess piece. */
    private static final class Piece {
        final char type; // 'R', 'B' or 'Q' as supplied in the input
        final long x;
        final y;

        Piece(char type, long x, long y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }

        /**
         * Returns the distance (in steps) from this piece to the king when they
         * share a line (rank, file or diagonal). For orthogonal directions the
         * distance equals the absolute difference in the moving coordinate;
         * for diagonal directions it equals the absolute difference in *either*
         * coordinate (because they are equal).
         */
        long distanceToKing(long kingX, long kingY) {
            if (x == kingX) {
                return Math.abs(y - kingY);
            }
            // aligned diagonally – distance equals |dx|
            return Math.abs(x - kingX);
        }
    }

    public static void main(String[] args) throws IOException {
        // Fast line‑oriented input
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int pieceCount = Integer.parseInt(br.readLine().trim());

            // King's coordinates
            String[] kingCoords = br.readLine().split("\\s+");
            long kingX = Long.parseLong(kingCoords[0]);
            long kingY = Long.parseLong(kingCoords[1]);

            // Map each direction to the nearest opponent piece in that direction
            EnumMap<Direction, Piece> nearest = new EnumMap<>(Direction.class);

            for (int i = 0; i < pieceCount; i++) {
                StringTokenizer st = new StringTokenizer(br.readLine());
                char type = st.nextToken().charAt(0);
                long bx = Long.parseLong(st.nextToken());
                long by = Long.parseLong(st.nextToken());

                long dx = bx - kingX;
                long dy = by - kingY;

                Direction dir = directionFromDelta(dx, dy);
                if (dir == null) {
                    // Piece not on a rank, file or diagonal – cannot affect the king.
                    continue;
                }

                Piece candidate = new Piece(type, bx, by);
                Piece existing = nearest.get(dir);
                if (existing == null || candidate.distanceToKing(kingX, kingY) < existing.distanceToKing(kingX, kingY)) {
                    nearest.put(dir, candidate);
                }
            }

            // Check whether any of the nearest pieces can capture the king.
            boolean canCapture = false;
            for (Map.Entry<Direction, Piece> entry : nearest.entrySet()) {
                Direction dir = entry.getKey();
                Piece p = entry.getValue();

                // Cardinal directions (0,2,4,6) are served by rooks / queens.
                if ((dir.ordinal() % 2) == 0) {
                    if (p.type == 'R' || p.type == 'Q') {
                        canCapture = true;
                        break;
                    }
                } else {
                    // Diagonal directions (1,3,5,7) are served by bishops / queens.
                    if (p.type == 'B' || p.type == 'Q') {
                        canCapture = true;
                        break;
                    }
                }
            }

            System.out.println(canCapture ? "YES" : "NO");
        }
    }
}

import java.io.*;
import java.util.*;

public class CF734D {

    private static final String YES = "YES";
    private static final String NO = "NO";

    /** Eight possible directions a ray can point to */
    private enum Direction {
        RIGHT,          // x>0 , y==0
        LEFT,           // x<0 , y==0
        UP,             // x==0 , y>0
        DOWN,           // x==0 , y<0
        DIAG_NE,        // x>0 , y>0 , x==y
        DIAG_SW,        // x<0 , y<0 , x==y
        DIAG_SE,        // x>0 , y<0 , x==-y
        DIAG_NW         // x<0 , y>0 , -x==y
    }

    /** Container for the closest ray of a given direction */
    private static final class Ray {
        int minDist = Integer.MAX_VALUE;
        char command = ' ';

        /** Update the stored distance / command if a nearer ray is found */
        void register(int dist, char cmd) {
            if (dist < minDist) {
                minDist = dist;
                command = cmd;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int n = Integer.parseInt(br.readLine().trim());

            // base point (the coordinates before shifting)
            StringTokenizer baseTok = new StringTokenizer(br.readLine().trim());
            int baseX = Integer.parseInt(baseTok.nextToken());
            int baseY = Integer.parseInt(baseTok.nextToken());

            // one Ray per direction
            Ray[] rays = new Ray[Direction.values().length];
            for (Direction d : Direction.values()) {
                rays[d.ordinal()] = new Ray();
            }

            // read the n commands
            for (int i = 0; i < n; i++) {
                StringTokenizer st = new StringTokenizer(br.readLine().trim());
                char cmd = st.nextToken().charAt(0);
                int x = Integer.parseInt(st.nextToken()) - baseX;
                int y = Integer.parseInt(st.nextToken()) - baseY;
                handle(x, y, cmd, rays);
            }

            boolean answer = hasPositiveRay(rays);
            System.out.println(answer ? YES : NO);
        }
    }

    /** Assign (x,y) to the correct direction and register the command if it is closer */
    private static void handle(int x, int y, char cmd, Ray[] rays) {
        // axis rays
        if (y == 0) {
            if (x > 0) {
                rays[Direction.RIGHT.ordinal()].register(x, cmd);
                return;
            }
            if (x < 0) {
                rays[Direction.LEFT.ordinal()].register(-x, cmd);
                return;
            }
        }
        if (x == 0) {
            if (y > 0) {
                rays[Direction.UP.ordinal()].register(y, cmd);
                return;
            }
            if (y < 0) {
                rays[Direction.DOWN.ordinal()].register(-y, cmd);
                return;
            }
        }

        // diagonal rays – they require |x| == |y|
        int absX = Math.abs(x);
        int absY = Math.abs(y);
        if (absX == absY) {
            if (x > 0 && y > 0) {          // North‑East
                rays[Direction.DIAG_NE.ordinal()].register(x, cmd);
                return;
            }
            if (x < 0 && y < 0) {          // South‑West
                rays[Direction.DIAG_SW.ordinal()].register(-x, cmd);
                return;
            }
            if (x > 0 && y < 0) {          // South‑East
                rays[Direction.DIAG_SE.ordinal()].register(x, cmd);
                return;
            }
            if (x < 0 && y > 0) {          // North‑West
                rays[Direction.DIAG_NW.ordinal()].register(y, cmd);
                return;
            }
        }
    }

    /** Returns true if any ray that must lead to a “YES” answer is present */
    private static boolean hasPositiveRay(Ray[] rays) {
        // Directions that require the command to be 'R' or 'Q'
        for (Direction d : directionsRequiringRorQ()) {
            char c = rays[d.ordinal()].command;
            if (c == 'R' || c == 'Q') {
                return true;
            }
        }
        // Directions that require the command to be 'B' or 'Q'
        for (Direction d : directionsRequiringBorQ()) {
            char c = rays[d.ordinal()].command;
            if (c == 'B' || c == 'Q') {
                return true;
            }
        }
        return false;
    }

    private static Set<Direction> directionsRequiringRorQ() {
        return EnumSet.of(
                Direction.RIGHT,
                Direction.UP,
                Direction.DIAG_NE,
                Direction.DIAG_SW);
    }

    private static Set<Direction> directionsRequiringBorQ() {
        return EnumSet.of(
                Direction.LEFT,
                Direction.DOWN,
                Direction.DIAG_SW,
                Direction.DIAG_NW);
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Refactored solution for problem 734D.
 * The program reads points around a reference point (x0, y0) and decides
 * whether any of the closest points in the eight compass directions
 * is of a special type (R/Q for orthogonal directions, B/Q for diagonals).
 */
public class P734D {

    /* --------------------------------------------------------------
       Fast I/O helpers
       -------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(Reader reader) {
            this.br = new BufferedReader(reader);
        }

        private void ensureTokenizer() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return;
                }
                st = new StringTokenizer(line);
            }
        }

        String next() throws IOException {
            ensureTokenizer();
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /* --------------------------------------------------------------
       Direction enum – represents the eight compass positions.
       -------------------------------------------------------------- */
    private enum Direction {
        EAST, WEST, NORTH, SOUTH,
        NORTHEAST, NORTHWEST, SOUTHEAST, SOUTHWEST;

        /**
         * Returns the direction of the vector (dx, dy) if it lies exactly
         * on one of the eight compass rays.
         */
        static Optional<Direction> of(int dx, int dy) {
            if (dx == 0 && dy == 0) {
                return Optional.empty();
            }
            if (dx == 0) {
                return dy > 0 ? Optional.of(NORTH) : Optional.of(SOUTH);
            }
            if (dy == 0) {
                return dx > 0 ? Optional.of(EAST) : Optional.of(WEST);
            }
            if (Math.abs(dx) == Math.abs(dy)) {
                if (dx > 0) {
                    return dy > 0 ? Optional.of(NORTHEAST) : Optional.of(SOUTHEAST);
                } else {
                    return dy > 0 ? Optional.of(NORTHWEST) : Optional.of(SOUTHWEST);
                }
            }
            return Optional.empty(); // not aligned
        }
    }

    /* --------------------------------------------------------------
       Simple data holder for a point together with its tag.
       -------------------------------------------------------------- */
    private static final class Figure implements Comparable<Figure> {
        final int x, y;
        final char tag;
        final long distance; // Manhattan distance to (x0, y0)

        Figure(char tag, int x, int y, long distance) {
            this.tag = tag;
            this.x = x;
            this.y = y;
            this.distance = distance;
        }

        @Override
        public int compareTo(Figure o) {
            return Long.compare(this.distance, o.distance);
        }
    }

    /* --------------------------------------------------------------
       Entry point
       -------------------------------------------------------------- */
    private static FastScanner fs;
    private static PrintWriter out;

    public static void main(String[] args) throws Exception {
        long start = System.currentTimeMillis();
        fs = new FastScanner(new InputStreamReader(System.in));
        out = new PrintWriter(new BufferedOutputStream(System.out));

        solve();

        out.flush();
        System.err.println("[Time : " + (System.currentTimeMillis() - start) + " ms]");
    }

    /* --------------------------------------------------------------
       Core algorithm
       -------------------------------------------------------------- */
    private static void solve() throws Exception {
        int n = fs.nextInt();
        int x0 = fs.nextInt();
        int y0 = fs.nextInt();

        // Group figures by their directional category.
        EnumMap<Direction, List<Figure>> groups = new EnumMap<>(Direction.class);
        for (Direction d : Direction.values()) {
            groups.put(d, new ArrayList<>());
        }

        // Read all points and place them into the appropriate group.
        for (int i = 0; i < n; i++) {
            char tag = fs.next().charAt(0);
            int x = fs.nextInt();
            int y = fs.nextInt();

            Figure f = new Figure(
                    tag,
                    x,
                    y,
                    Math.abs(x - x0) + Math.abs(y - y0)); // Manhattan distance

            Direction dir = Direction.of(x - x0, y - y0);
            dir.ifPresent(groups::get).get().add(f);
        }

        // Sort each direction's list – nearest figure first.
        groups.values().forEach(List::sort);

        // Check the required condition for each direction.
        boolean answer = groups.get(Direction.EAST).stream()
                .anyMatch(f -> f.tag == 'R' || f.tag == 'Q')
                || groups.get(Direction.WEST).stream()
                .anyMatch(f -> f.tag == 'R' || f.tag == 'Q')
                || groups.get(Direction.NORTH).stream()
                .anyMatch(f -> f.tag == 'R' || f.tag == 'Q')
                || groups.get(Direction.SOUTH).stream()
                .anyMatch(f -> f.tag == 'R' || f.tag == 'Q')
                || groups.get(Direction.NORTHEAST).stream()
                .anyMatch(f -> f.tag == 'B' || f.tag == 'Q')
                || groups.get(Direction.NORTHWEST).stream()
                .anyMatch(f -> f.tag == 'B' || f.tag == 'Q')
                || groups.get(Direction.SOUTHEAST).stream()
                .anyMatch(f -> f.tag == 'B' || f.tag == 'Q')
                || groups.get(Direction.SOUTHWEST).stream()
                .anyMatch(f -> f.tag == 'B' || f.tag == 'Q');

        out.println(answer ? "YES" : "NO");
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Utility class that encapsulates the logic of the original {@code Solution2}.
 * The refactor improves readability, separates concerns and removes duplication.
 */
public class Solution2 {

    /** Directions on a chess board – ordered exactly as in the original algorithm. */
    private enum Direction {
        NORTH_WEST,   // 0   (dx < 0, dy > 0)   – bishop / queen (top‑left diagonal)
        NORTH,        // 1   (dx == 0, dy > 0)   – rook / queen (north)
        NORTHEAST,    // 2   (dx > 0, dy > 0)   – bishop / queen (top‑right diagonal)
        EAST,         // 3   (dx > 0, dy == 0)   – rook / queen (east)
        SOUTH_EAST,   // 4   (dx > 0, dy < 0)   – rook / queen (south‑east)
        SOUTH,        // 5   (dx == 0, dy < 0)   – rook / queen (south)
        SOUTH_WEST,   // 6   (dx < 0, dy < 0)   – rook / queen (south‑west)
        NORTH_EAST    // 7   (dx < 0, dy < 0)   – bishop / queen (bottom‑left diagonal) 
        // NOTE: The names are kept to match the original index‑to‑direction mapping.
    }

    /** Mapping of piece symbols to the set of directions they can move on. */
    private static final Map<Character, Set<Direction>> PIECE_DIRECTIONS = new HashMap<>();

    static {
        PIECE_DIRECTIONS.put('B', Set.of(Direction.NORTH_WEST, Direction.NORTH_EAST,
                                         Direction.SOUTH_WEST, Direction.SOUTH_EAST));
        PIECE_DIRECTIONS.put('R', Set.of(Direction.NORTH, Direction.SOUTH,
                                         Direction.EAST, Direction.WEST));
        PIECE_DIRECTIONS.put('Q', Set.of(Direction.values())); // queen can move any of the eight ways
    }

    /** Simple immutable holder for a piece with its symbol and coordinates. */
    private static final class Piece {
        final char symbol;
        final int x;
        final int y;

        Piece(char symbol, int x, int y) {
            this.symbol = symbol;
            this.x = x;
            this.y = y;
        }
    }

    /** Returns the direction index (0‑7) for a given displacement from the origin. */
    private static int directionIndex(int dx, int dy) {
        // The original code treats the eight possible directions in this exact order.
        if (dx < 0 && dy > 0) return 0;   // north‑west
        if (dx == 0 && dy > 0) return 1;  // north
        if (dx > 0 && dy > 0) return 2;   // north‑east
        if (dx > 0 && dy == 0) return 3;  // east
        if (dx > 0 && dy < 0) return 4;   // south‑east
        if (dx == 0 && dy < 0) return 5;  // south
        if (dx < 0 && dy < 0) return 6;   // south‑west
        if (dx < 0 && dy == 0) return 7;  // north‑east (original index 7 maps to this displacement)
        return -1; // not a valid direction for the problem
    }

    /** Retrieves the piece that is closest to (x0, y0) in the given direction (smallest distance). */
    private static Piece selectBest(Direction dir, Piece currentBest, Piece candidate) {
        // For each direction we keep the *closest* piece to the origin.
        // The distance metric simply compares the absolute displacement along the axis that
        // defines the direction (e.g. for east we compare x‑coordinate).
        if (!isValid(candidate, dir)) {
            return currentBest;
        }
        if (currentBest == null) {
            return candidate;
        }
        // Because the candidate is guaranteed to lie on the same line, we can compare
        // the appropriate coordinate to decide which one is nearer.
        if (dir == Direction.NORTH_WEST || dir == Direction.NORTH_EAST ||
            dir == Direction.SOUTH_WEST || dir == Direction.SOUTH_EAST) {
            // diagonal – compare Manhattan distance from origin
            int distCand = Math.abs(candidate.x - candidate.y);
            int distBest = Math.abs(currentBest.x - currentBest.y);
            return (distCand < distBest) ? candidate : currentBest;
        } else {
            // axis‑aligned – compare the non‑zero coordinate
            int candCoord = (dir == Direction.NORTH || dir == Direction.SOUTH) ? candidate.y
                                                                                     : candidate.x;
            int bestCoord = (dir == Direction.NORTH || dir == Direction.SOUTH) ? currentBest.y
                                                                                     : currentBest.x;
            return (candCoord < bestCoord) ? candidate : currentBest;
        }
    }

    /** Checks whether a piece really lies on the given direction from the origin. */
    private static boolean isValid(Piece p, Direction dir) {
        int dx = p.x - ORIGIN_X;
        int dy = p.y - ORIGIN_Y;

        switch (dir) {
            case NORTH_WEST:  return dx < 0 && dy > 0 && Math.abs(dx) == dy;
            case NORTH:       return dx == 0 && dy > 0;
            case NORTH_EAST:  return dx > 0 && dy > 0 && dx == dy;
            case EAST:        return dy == 0 && dx > 0;
            case SOUTH_EAST:  return dx > 0 && dy < 0 && dx == -dy;
            case SOUTH:       return dy < 0 && dx == 0;
            case SOUTH_WEST:  return dx < 0 && dy < 0 && -dx == dy;
            case NORTH_EAST:  // index 7 in original – moves left‑up (dx<0, dy<0) with equal magnitude
                return dx < 0 && dy < 0 && -dx == -dy;
            default:
                return false;
        }
    }

    /** Constant holding the origin coordinates – extracted from the entry parameters. */
    private static int ORIGIN_X;
    /** Constant holding the origin coordinates – extracted from the entry parameters. */
    private static int ORIGIN_Y;

    /** Entry point – identical logic to the original program, but refactored. */
    public static void main(String[] args) throws IOException {
        // -----------------------------------------------------------------------
        // Input handling
        // -----------------------------------------------------------------------
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] firstLine = br.readLine().trim().split("\\s+");
            int n = Integer.parseInt(firstLine[0]);
            ORIGIN_X = Integer.parseInt(firstLine[1]);
            ORIGIN_Y = Integer.parseInt(firstLine[2]);

            // Array that will store the *closest* piece discovered in each of the 8 directions.
            Piece[] bestInDirection = new Piece[8];
            // Initialise with placeholder objects (symbol='x' means “empty”).
            for (int i = 0; i < 8; i++) {
                bestInDirection[i] = new Piece('x', Integer.MIN_VALUE, Integer.MIN_VALUE);
            }

            // Read every subsequent piece and update the closest‑piece array.
            for (int i = 0; i < n; i++) {
                String token = br.readLine().trim();
                if (token.isEmpty()) continue;

                String[] parts = token.split("\\s+");
                char symbol = parts[0].charAt(0);
                int x = Integer.parseInt(parts[1]);
                int y = Integer.parseInt(parts[2]);

                Piece candidate = new Piece(symbol, x, y);
                int dirIdx = directionIndex(x - ORIGIN_X, y - ORIGIN_Y);

                if (dirIdx >= 0) {
                    Direction dir = Direction.values()[dirIdx];
                    bestInDirection[dirIdx] = selectBest(dir, bestInDirection[dirIdx], candidate);
                }
            }

            // -------------------------------------------------------------------
            // Decision logic – echo the original YES/NO output semantics.
            // -------------------------------------------------------------------
            boolean canCheck = false;

            // Directions belonging to bishops (indices 0,2,5,7 in the original code)
            int[] bishopDirections = {0, 2, 5, 7};
            for (int idx : bishopDirections) {
                Piece p = bestInDirection[idx];
                if (p.symbol == 'B' || p.symbol == 'Q') {
                    canCheck = true;
                    break;
                }
            }

            if (!canCheck) {
                // Directions belonging to rooks (indices 1,3,4,6)
                int[] rookDirections = {1, 3, 4, 6};
                for (int idx : rookDirections) {
                    Piece p = bestInDirection[idx];
                    if (p.symbol == 'R' || p.symbol == 'Q') {
                        canCheck = true;
                        break;
                    }
                }
            }

            System.out.println(canCheck ? "YES" : "NO");
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the “Check” problem.
 *
 * <p>Refactored version:
 * <ul>
 *   <li>Separated concerns into small, focused classes.</li>
 *   <li>Removed duplicated code by handling the four attack directions
 *       (horizontal, vertical, two diagonals) with a single generic method.</li>
 *   <li>Used clear naming, constants and early‑return semantics.</li>
 *   <li>Added an {@link PieceType} enum for readability.</li>
 *   <li>Improved I/O with a fast scanner / printer.</li>
 * </ul>
 */
public class Main {

    /** fast scanner */
    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) { this.in = in; }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** reads next non‑whitespace character */
        private int skipWhitespace() throws IOException {
            int c;
            while ((c = readByte()) <= ' ') if (c == -1) return -1;
            return c;
        }

        /** reads an int */
        int nextInt() throws IOException {
            int c = skipWhitespace();
            int sign = 1;
            if (c == '-') { sign = -1; c = readByte(); }
            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return value * sign;
        }

        /** reads a single non‑whitespace character */
        char nextChar() throws IOException { return (char) skipWhitespace(); }
    }

    /** fast printer */
    private static final class FastPrint {
        private final PrintWriter out;
        FastPrint(Writer w) { this.out = new PrintWriter(w); }
        void printLine(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) out.print(' ');
                out.print(objects[i]);
            }
            out.println();
        }
        void close() { out.close(); }
    }

    /** type of a chess piece based on its character */
    private enum PieceType {
        ROOK('R'), BISHOP('B'), QUEEN('Q');

        private final char symbol;
        PieceType(char symbol) { this.symbol = symbol; }
        static PieceType from(char c) { return switch (c) { case 'R' -> ROOK; case 'B' -> BISHOP; case 'Q' -> QUEEN; default -> null; }; }
    }

    /** immutable chess piece */
    private static final class Piece {
        final int x, y;
        final char typeChar;                 // as given in the input
        final PieceType type;                  // derived from the character

        Piece(int x, int y, char typeChar) {
            this.x = x;
            this.y = y;
            this.typeChar = typeChar;
            this.type = PieceType.from(typeChar);
        }

        int getX() { return x; }
        int getY() { return y; }
        PieceType getType() { return type; }

        /** distance metrics required for the four directions */
        int sum()   { return x + y; }   // main diagonal
        int diff()  { return x - y; }   // anti‑diagonal
    }

    /** stores the closest enemy piece for a given direction and distance */
    private static final class Closest {
        /** direction index: 0‑horizontal, 1‑vertical, 2‑main‑diag, 3‑anti‑diag */
        final int dirIndex;
        /** distance measured in the appropriate metric (see Piece) */
        final long distance;
        /** piece that occupies this minimal distance */
        final Piece piece;

        Closest(int dirIndex, long distance, Piece piece) {
            this.dirIndex = dirIndex;
            this.distance = distance;
            this.piece = piece;
        }
    }

    /** the core solving logic */
    private static final class Solver {
        private static final int HORIZ = 0;   // same x (vertical line) – we sort by y
        private static final int VERT   = 1;   // same y (horizontal line) – we sort by x
        private static final int MAIN_DIAG = 2; // x+y constant
        private static final int ANTI_DIAG = 3; // x-y constant

        private final List<Piece> enemies = new ArrayList<>();
        private Piece king;

        /** main entry point for one test case */
        void solve(InputReader in, OutputWriter out) {
            int n = in.readInt();
            readPieces(in, n);

            // gather the closest enemy in each of the four attack directions
            List<Closest> closest = Arrays.asList(
                    closestHorizontal(in),   // direction HORIZ
                    closestVertical(in),     // direction VERT
                    closestMainDiagonal(in), // direction MAIN_DIAG
                    closestAntiDiagonal(in)  // direction ANTI_DIAG
            );

            // check whether any of those closest pieces can actually give check
            if (anyClosesCanCheck(closest)) {
                out.printLine("YES");
            } else {
                out.printLine("NO");
            }
        }

        /** reads all pieces of the current test case */
        private void readPieces(InputReader in, int n) {
            king = new Piece(in.readInt(), in.readInt(), PieceType.ROOK); // type unused for king
            for (int i = 0; i < n; i++) {
                char type = in.readCharacter();
                Piece p = new Piece(in.readInt(), in.readInt(), type);
                enemies.add(p);
            }
        }

        /** direction 0 – vertical line (same x), nearest enemy below/above the king */
        private Closest closestVertical(InputReader in) {
            // filter pieces that share the king's x‑coordinate
            List<Piece> candidates = enemies.stream()
                    .filter(p -> p.getX() == king.getX())
                    .toList();

            // sort by king.y distance (absolute)
            candidates.sort(Comparator.comparingInt(p -> Math.abs(p.getY() - king.getY())));

            // the first candidate that is on the same side as the closest piece is enough
            Piece nearest = candidates.isEmpty() ? null : candidates.get(0);
            return nearest == null ? null : new Closest(VERT, Math.abs(nearest.getY() - king.getY()), nearest);
        }

        /** direction 1 – horizontal line (same y), nearest enemy left/right of the king */
        private Closest closestHorizontal(InputReader in) {
            List<Piece> candidates = enemies.stream()
                    .filter(p -> p.getY() == king.getY())
                    .toList();

            candidates.sort(Comparator.comparingInt(p -> Math.abs(p.getX() - king.getX())));

            Piece nearest = candidates.isEmpty() ? null : candidates.get(0);
            return nearest == null ? null : new Closest(HORIZ, Math.abs(nearest.getX() - king.getX()), nearest);
        }

        /** direction 2 – main diagonal (x + y constant), nearest enemy towards lower‑left */
        private Closest closestMainDiagonal(InputReader in) {
            List<Piece> candidates = enemies.stream()
                    .filter(p -> p.getSum() == king.getSum())
                    .toList();

            candidates.sort(Comparator.comparingInt(p -> Math.abs(p.getDiff() - king.getDiff())));

            Piece nearest = candidates.isEmpty() ? null : candidates.get(0);
            return nearest == null ? null : new Closest(MAIN_DIAG, Math.abs(nearest.getDiff() - king.getDiff()), nearest);
        }

        /** direction 3 – anti‑diagonal (x - y constant), nearest enemy towards lower‑right */
        private Closest closestAntiDiagonal(InputReader in) {
            List<Piece> candidates = enemies.stream()
                    .filter(p -> p.getDiff() == king.getDiff())
                    .toList();

            candidates.sort(Comparator.comparingInt(p -> Math.abs(p.getSum() - king.getSum())));

            Piece nearest = candidates.isEmpty() ? null : candidates.get(0);
            return nearest == null ? null : new Closest(ANTI_DIAG, Math.abs(nearest.getSum() - king.getSum()), nearest);
        }

        /** decides if any of the closest pieces can give a check */
        private boolean anyClosesCanCheck(List<Closest> closest) {
            for (Closest c : closest) {
                if (c.piece == null) continue;
                PieceType t = c.piece.getType();
                boolean canCheck = switch (c.dirIndex) {
                    case HORIZ, VERT -> t == PieceType.ROOK || t == PieceType.QUEEN;
                    case MAIN_DIAG, ANTI_DIAG -> t == PieceType.BISHOP || t == PieceType.QUEEN;
                    default -> false;
                };
                if (canCheck) return true;
            }
            return false;
        }
    }

    /** tiny wrapper around BufferedWriter / PrintWriter */
    private static final class OutputWriter {
        private final PrintWriter out;
        OutputWriter(OutputStream out) { this.out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out))); }
        void print(Object... objs) { for (int i = 0; i < objs.length; i++) { if (i != 0) out.print(' '); out.print(objs[i]); } }
        void printLine(Object... objs) { print(objs); out.println(); }
        void close() { out.close(); }
    }

    /** tiny wrapper around FastScanner and OutputWriter for the whole program */
    private static final class InputReader {
        private final FastScanner fs;
        InputReader(InputStream in) { this.fs = new FastScanner(in); }
        int readInt() throws IOException { return fs.nextInt(); }
        char readCharacter() throws IOException { return fs.nextChar(); }
    }

    /** driver class – entry point */
    public static void main(String[] args) throws Exception {
        InputStream in = System.in;
        OutputStream out = System.out;
        FastScanner scanner = new FastScanner(in);
        FastPrint printer = new FastPrint(new OutputStreamWriter(out));

        // we reuse the same solver for possibly multiple test cases.
        // In the given source only a single case ("1") is used, but the design
        // allows extending to many cases without touching the solver logic.
        Solver solver = new Solver();

        int testCases = 1; // problem statement supplies exactly one test case
        for (int tc = 0; tc < testCases; tc++) {
            InputReader reader = new InputReader(in);
            OutputWriter writer = new OutputWriter(out);
            solver.solve(reader, writer);
            writer.close();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Helper that stores the closest move we have seen for a given direction. */
    private static final class Closest {
        /** The character read for this direction. */
        char symbol = 0;
        /** Smallest Manhattan distance seen so far for this direction. */
        int bestDist = Integer.MAX_VALUE;
    }

    /** Direction helpers – indices are the same for orthogonal and diagonal moves. */
    private static final Closest[] ORTH   = new Closest[4]; // 0‑up, 1‑down, 2‑right, 3‑left
    private static final Closest[] DIAG   = new Closest[4]; // 0‑NE, 1‑SE, 2‑SW, 3‑NW

    /** Stream tokenizer used for fast tokenised input. */
    private static final StreamTokenizer TOK = new StreamTokenizer(
            new BufferedReader(new InputStreamReader(System.in))
    );

    /** Reads the next integer token from {@link TOK}. */
    private static int nextInt() throws IOException {
        TOK.nextToken();
        return (int) TOK.nval;
    }

    /** Reads the next long token from {@link TOK}. */
    private static long nextLong() throws IOException {
        TOK.nextToken();
        return (long) TOK.nval;
    }

    /** Reads the next double token from {@link TOK}. */
    private static double nextDouble() throws IOException {
        TOK.nextToken();
        return TOK.nval;
    }

    /** Reads the next word (non‑whitespace characters). */
    private static String nextWord() throws IOException {
        TOK.nextToken();
        return TOK.sval;
    }

    /** Updates the information for a given direction if the supplied distance is smaller. */
    private static void updateNearest(Closest[] targets, int idx, int distance, char symbol) {
        Closest cur = targets[idx];
        if (distance < cur.bestDist) {
            cur.bestDist = distance;
            cur.symbol = symbol;
        }
    }

    public static void main(String[] args) throws IOException {
        // ---------- initialise ----------
        for (int i = 0; i < 4; i++) {
            ORTH[i] = new Closest();
            DIAG[i] = new Closest();
        }

        // ---------- read problem data ----------
        int n = nextInt();          // number of points
        int x0 = nextInt();         // start x
        int y0 = nextInt();         // start y

        // ---------- process each point ----------
        for (int i = 0; i < n; i++) {
            String token = nextWord();          // a single character command
            char cmd = token.charAt(0);
            int x = nextInt();
            int y = nextInt();

            int dx = x - x0;
            int dy = y - y0;

            // vertical line (dx == 0, dy != 0)
            if (dx == 0 && dy != 0) {
                int dirIdx = dy > 0 ? 0 : 1;                 // 0 = up, 1 = down
                int dist   = Math.abs(dy);
                updateNearest(ORTH, dirIdx, dist, cmd);
                continue;
            }

            // horizontal line (dy == 0, dx != 0)
            if (dy == 0 && dx != 0) {
                int dirIdx = dx > 0 ? 2 : 3;                 // 2 = right, 3 = left
                int dist   = Math.abs(dx);
                updateNearest(ORTH, dirIdx, dist, cmd);
                continue;
            }

            // diagonal line (|dx| == |dy|, dx != 0)
            if (Math.abs(dx) == Math.abs(dy) && dx != 0) {
                int dirIdx;
                if (dx > 0 && dy > 0)      dirIdx = 0; // NE
                else if (dx > 0 && dy < 0) dirIdx = 1; // SE
                else if (dx < 0 && dy < 0) dirIdx = 2; // SW
                else                       dirIdx = 3; // NW

                int dist = Math.abs(dx); // same as |dy|
                updateNearest(DIAG, dirIdx, dist, cmd);
            }
        }

        // ---------- decide the answer ----------
        // any diagonal direction that ended with 'B' or 'Q' makes the answer YES
        for (int i = 0; i < 4; i++) {
            char c = DIAG[i].symbol;
            if (c == 'B' || c == 'Q') {
                System.out.println("YES");
                return;
            }
        }

        // any orthogonal direction that ended with 'R' or 'Q' makes the answer YES
        for (int i = 0; i < 4; i++) {
            char c = ORTH[i].symbol;
            if (c == 'R' || c == 'Q') {
                System.out.println("YES");
                return;
            }
        }

        System.out.println("NO");
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Fast scanner that works with any {@link InputStream}. */
    private static final class FastScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream source) {
            this.reader = new BufferedReader(new InputStreamReader(source));
        }

        /** Returns the next complete token. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrapper for {@code nextToken()} that parses an {@code int}. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Closes the underlying reader. */
        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    /**
     * Represents one of the eight possible directions from the start cell.
     * <p>
     * The index matches the original code’s “best” array (0‑7).  Each direction
     * tracks the smallest distance that satisfied its geometric predicate.
     */
    private static final class Direction {
        final char piece;          // the character read from input (e.g. 'Q', 'R', …)
        final int id;              // 0‑7, same order as the original `best` array
        int bestDistance = Integer.MAX_VALUE; // smallest observed distance

        Direction(char piece, int id) {
            this.piece = piece;
            this.id = id;
        }

        /** Updates the stored distance only if the supplied distance is smaller. */
        void updateIfCloser(int distance) {
            if (distance < bestDistance) {
                bestDistance = distance;
            }
        }
    }

    public static void main(String[] args) throws Exception {
        // The original program always created a `d` instance, so we do the same –
        // but we keep everything inside a try‑with‑resources block for safety.
        try (FastScanner scanner = new FastScanner(System.in)) {
            int n = scanner.nextInt();              // number of moves
            long startX = scanner.nextInt();        // start X coordinate
            long startY = scanner.nextInt();        // start Y coordinate

            // Initialise an array that mirrors the original `best[]` and `piece[]`.
            Direction[] directions = new Direction[8];
            Arrays.setAll(directions, i -> new Direction('P', i));

            // Process each move.
            for (int i = 0; i < n; i++) {
                char op = scanner.next().charAt(0); // move identifier
                long x = scanner.nextInt();         // coordinate X
                long y = scanner.nextInt();         // coordinate Y

                handleMove(startX, startY, x, y, op, directions);
            }

            // Determine whether a queen/rook or a queen/bishop move was recorded.
            boolean canCaptureWithRookOrQueen = any(directions, 0, 4, d -> d.piece == 'Q' || d.piece == 'R');
            boolean canCaptureWithBishopOrQueen = any(directions, 4, 8, d -> d.piece == 'Q' || d.piece == 'B');

            System.out.println(canCaptureWithRookOrQueen || canCaptureWithBishopOrQueen ? "YES" : "NO");
        }
    }

    /**
     * Checks the supplied coordinate against the eight geometric predicates used in
     * the original program and updates the corresponding {@link Direction} if the
     * move is closer than any previous one.
     */
    private static void handleMove(long sx, long sy,
                                   long x, long y,
                                   char op,
                                   Direction[] directions) {
        // vertical upward line
        if (x == sx && y > sy) {
            directions[0].updateIfCloser((int) (y - sy));
        }
        // vertical downward line
        else if (x == sx && y < sy) {
            directions[1].updateIfCloser((int) (sy - y));
        }
        // horizontal rightward line
        else if (y == sy && x > sx) {
            directions[2].updateIfCloser((int) (x - sx));
        }
        // horizontal leftward line
        else if (y == sy && x < sx) {
            directions[3].updateIfCloser((int) (sx - x));
        }
        // diagonal "\" with start cell to the right (x < sx)
        else if (x + y == sx + sy && x < sx) {
            directions[4].updateIfCloser((int) (sx - x));
        }
        // diagonal "\" with start cell to the left (x > sx)
        else if (x + y == sx + sy && x > sx) {
            directions[5].updateIfCloser((int) (x - sx));
        }
        // diagonal "/" with start cell below (sx > x)
        else if (x - y == sx - sy && sx > x) {
            directions[6].updateIfCloser((int) (sx - x));
        }
        // diagonal "/" with start cell above (sx < x)
        else if (x - y == sx - sy && sx < x) {
            directions[7].updateIfCloser((int) (x - sx));
        }
    }

    /** Utility to test a predicate on a sub‑range of an array. */
    private static boolean any(Direction[] arr, int from, int to, java.util.function.IntPredicate predicate) {
        for (int i = from; i < to; i++) {
            if (predicate.test(i)) {
                return true;
            }
        }
        return false;
    }

    @FunctionalInterface
    public interface IntPredicate {
        boolean test(int value);
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for CF379 Div2 D.
 * <p>
 * The program reads a series of commands, stores the farthest point
 * for each of eight fixed directions relative to a reference coordinate,
 * and finally decides whether any stored point satisfies a specific
 * letter‑group condition.
 * </p>
 */
public class CF379Div2D {

    /** Entry point – wires the I/O objects and starts the solver. */
    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Solver(reader, out).solve();
        out.close();
    }

    /** Simple wrapper around {@code BufferedReader} that tokenises input lines. */
    static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream input) {
            this.br = new BufferedReader(new InputStreamReader(input));
        }

        /** Returns the next token, reading a new line if necessary. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt()               { return Integer.parseInt(next()); }
        long nextLong()             { return Long.parseLong(next()); }
        double nextDouble()         { return Double.parseDouble(next()); }
        String nextLine()           { try { return br.readLine(); } catch (IOException e) { throw new UncheckedIOException(e); } }
        char nextChar()             { return next().charAt(0); }
    }

    /** Holds the data for a single direction (0‑7). */
    static class DirectionPoint {
        private final int index;          // 0 … 7
        private char assignedChar = '?';   // default unassigned
        private int x, y;
        private boolean assigned = false;

        DirectionPoint(int index) {
            this.index = index;
        }

        boolean isAssigned()   { return assigned; }
        char getChar()          { return assignedChar; }

        /** Records a new assignment (overwrites previous values). */
        void assign(char c, int x, int y) {
            this.assignedChar = c;
            this.x = x;
            this.y = y;
            this.assigned = true;
        }
    }

    /** Core logic of the solution – decoupled from I/O handling. */
    static class Solver {
        private static final int DIRECTION_COUNT = 8;

        private final DirectionPoint[] points = new DirectionPoint[DIRECTION_COUNT];
        private final InputReader in;
        private final PrintWriter out;

        // Reference coordinates (x, y) read after the number of commands.
        private int refX, refY;

        Solver(InputReader in, PrintWriter out) {
            this.in = in;
            this.out = out;
            for (int i = 0; i < DIRECTION_COUNT; i++) {
                points[i] = new DirectionPoint(i);
            }
        }

        /** Main driver – parses input, processes commands and prints the answer. */
        void solve() {
            int n = in.nextInt();
            readReference();

            for (int i = 0; i < n; i++) {
                processCommand();
            }

            out.print(isResultPositive() ? "YES" : "NO");
        }

        /** Reads the reference point that is common to all commands. */
        private void readReference() {
            refX = in.nextInt();
            refY = in.nextInt();
        }

        /** Handles one command line – updates the farthest point for its direction. */
        private void processCommand() {
            char cmdChar = in.nextChar();
            int xx = in.nextInt();
            int yy = in.nextInt();

            int dirIdx = directionIndex(xx, yy);
            if (dirIdx == -1) {
                return; // point does not belong to any of the eight directions
            }

            DirectionPoint point = points[dirIdx];
            if (!point.isAssigned()) {
                point.assign(cmdChar, xx, yy);
            } else {
                // Keep the point that is farther from the reference in Chebyshev distance.
                int currentDist = maxDistance(refX, refY, point.x, point.y);
                int newDist = maxDistance(refX, refY, xx, yy);
                if (newDist > currentDist) {
                    point.assign(cmdChar, xx, yy);
                }
            }
        }

        /**
         * Determines which of the eight directions a point belongs to.
         * The mapping follows the original algorithm exactly.
         */
        private int directionIndex(int x, int y) {
            int dx = x - refX;
            int dy = y - refY;

            if (dx == 0 && dy < 0)               return 0;
            if (dx == 0 && dy > 0)               return 4;
            if (dy == 0 && dx < 0)               return 6;
            if (dy == 0 && dx > 0)               return 2;
            if (dy == -dx && dy < 0)             return 1;
            if (dy == -dx && dy > 0)             return 5;
            if (dy == dx && dx < 0)              return 7;
            if (dy == dx && dx > 0)              return 3;
            return -1; // outside the eight fixed directions
        }

        /** Chebyshev distance from the reference point to (x, y). */
        private static int maxDistance(int baseX, int baseY, int x, int y) {
            return Math.max(Math.abs(x - baseX), Math.abs(y - baseY));
        }

        /** Evaluates the final boolean condition required by the problem. */
        private boolean isResultPositive() {
            boolean found = false;
            for (DirectionPoint p : points) {
                if (!p.isAssigned()) {
                    continue;
                }
                boolean evenGroup = (p.index % 2) == 0; // groups 0,2,4,6
                char c = p.getChar();

                if (evenGroup && (c == 'R' || c == 'Q')) {
                    found = true;
                } else if (!evenGroup && (c == 'B' || c == 'Q')) {
                    found = true;
                }
            }
            return found;
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 * The algorithm is unchanged – only the structure, naming and
 * encapsulation have been improved for readability and maintainability.
 */
public class Main {

    // -----------------------------------------------------------------------
    // Constants
    // -----------------------------------------------------------------------
    private static final int MIN = Integer.MIN_VALUE;
    private static final int MAX = Integer.MAX_VALUE;

    // -----------------------------------------------------------------------
    // Simple container for a point that also stores the last type stored there
    // -----------------------------------------------------------------------
    private static final class Point {
        final int x;
        final int y;
        char type = '0'; // '0' means not set yet

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    // -----------------------------------------------------------------------
    // All directional bounds that are updated while reading the input
    // -----------------------------------------------------------------------
    private static final class Bounds {
        // corner points
        final Point topLeft   = new Point(MIN, MAX);
        final Point topRight  = new Point(MAX, MAX);
        final Point bottomLeft = new Point(MAX, MIN);
        final Point bottomRight = new Point(MIN, MIN);

        // axis‑aligned points
        final Point left   = new Point(MIN, MIN);
        final Point right  = new Point(MAX, MAX);
        final Point down   = new Point(MIN, MIN);
        final Point up     = new Point(MAX, MAX);

        /** Updates a bound only when the new point improves the current stored one. */
        private void updateIfBetter(Point target, int nx, int ny, char typeChar) {
            if (typeChar == '0') {
                return;
            }
            // Decide whether the new point is "better" for this particular target.
            // The rules are exactly the same as in the original program.
            boolean better;
            switch (target) {
                case topLeft:
                case bottomLeft:
                    better = nx < target.x && ny < target.y;
                    break;
                case topRight:
                case bottomRight:
                    better = nx > target.x && ny > target.y;
                    break;
                default: // axis‑aligned bounds
                    better = true;
            }
            if (better || target.type == '0') {
                target.x = nx;
                target.y = ny;
                target.type = typeChar;
            }
        }

        /** Dispatches the incoming point to the correct bound. */
        void process(int originX, int originY, int x, int y, char typeChar) {
            if (Math.abs(x - originX) == Math.abs(y - originY)) {
                // Diagonal quadrant
                if (x < originX && y < originY) {
                    updateIfBetter(topLeft, x, y, typeChar);
                } else if (x < originX && y > originY) {
                    updateIfBetter(bottomLeft, x, y, typeChar);
                } else if (x > originX && y < originY) {
                    updateIfBetter(topRight, x, y, typeChar);
                } else { // x > originX && y > originY
                    updateIfBetter(bottomRight, x, y, typeChar);
                }
            } else if (x == originX) {
                // Same column
                if (y < originY) {
                    updateIfBetter(down, x, y, typeChar);
                } else {
                    updateIfBetter(up, x, y, typeChar);
                }
            } else if (y == originY) {
                // Same row
                if (x < originX) {
                    updateIfBetter(left, x, y, typeChar);
                } else {
                    updateIfBetter(right, x, y, typeChar);
                }
            }
            // Points that do not fall into any of the above categories are ignored.
        }

        /** Returns all eight bounds for the final decision. */
        Point[] all() {
            return new Point[]{
                    topLeft, topRight, bottomLeft, bottomRight,
                    left, right, down, up
            };
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder out = new StringBuilder();

        // ----- read the reference point (x, y) -----
        String line = br.readLine();
        int n = Integer.parseInt(line);
        StringTokenizer tk = new StringTokenizer(br.readLine());
        int originX = Integer.parseInt(tk.nextToken());
        int originY = Integer.parseInt(tk.nextToken());

        Bounds bounds = new Bounds();

        // ----- process the n entries -----
        for (int i = 0; i < n; i++) {
            line = br.readLine();
            tk = new StringTokenizer(line);
            String token = tk.nextToken();          // the character that describes the point
            int x2 = Integer.parseInt(tk.nextToken());
            int y2 = Integer.parseInt(tk.nextToken());

            bounds.process(originX, originY, x2, y2, token.charAt(0));
        }

        // ----- decide whether to print YES or NO -----
        boolean answer = containsRelevantType(bounds);
        out.append(answer ? "YES" : "NO");

        System.out.println(out);
        br.close();
    }

    // -----------------------------------------------------------------------
    // Final decision logic – reproduces the exact condition of the original code
    // -----------------------------------------------------------------------
    private static boolean containsRelevantType(Bounds b) {
        // The original program printed "YES" if any of the following was true:
        //   * any corner bound had type 'B' or 'R'
        //   * any axis‑aligned bound had type 'R'
        //   * any bound had type 'Q'
        // We emulate that exact test.
        char[] values = {
                b.topLeft.type, b.topRight.type, b.bottomLeft.type, b.bottomRight.type,
                b.left.type, b.right.type, b.down.type, b.up.type
        };
        for (char v : values) {
            if (v == 'B' || v == 'R' || v == 'Q') {
                return true;
            }
        }
        return false;
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Refactored solution for the “AntonChess” problem.
 * Determines whether the white king is under check from any black piece.
 */
public class AntonChess {

    /** The eight possible directions relative to the king. */
    private enum Direction {
        UP, DOWN, LEFT, RIGHT,
        UP_LEFT, UP_RIGHT, DOWN_LEFT, DOWN_RIGHT
    }

    /**
     * Holds information about the closest piece found in a direction.
     */
    private static final class DirectionInfo {
        final String pieceType;   // "R", "B", "Q" or "none"
        long distance;            // distance to the piece (always positive)

        DirectionInfo(String pieceType, long distance) {
            this.pieceType = pieceType;
            this.distance = distance;
        }
    }

    public static void main(String[] args) {
        // Scanner resources are automatically closed
        try (Scanner scanner = new Scanner(System.in)) {
            long numPieces = scanner.nextLong();
            long kingX = scanner.nextLong();
            long kingY = scanner.nextLong();

            // Initialise direction information with a sentinel value.
            DirectionInfo[] dirInfo = new DirectionInfo[Direction.values()];
            for (Direction dir : Direction.values()) {
                dirInfo[dir.ordinal()] = new DirectionInfo("none", Long.MAX_VALUE);
            }

            // Read every piece and update the closest one in its direction.
            for (long i = 0; i < numPieces; i++) {
                String type = scanner.next();
                long x = scanner.nextLong();
                long y = scanner.nextLong();

                Direction dir = getDirection(kingX, kingY, x, y);
                if (dir == null) {
                    continue; // piece not aligned with the king
                }

                long distance = distanceBetween(kingX, kingY, x, y);
                DirectionInfo current = dirInfo[dir.ordinal()];
                if (distance < current.distance) {
                    dirInfo[dir.ordinal()] = new DirectionInfo(type, distance);
                }
            }

            // Determine if any direction contains a threatening piece.
            boolean inCheck = Arrays.stream(Direction.values())
                    .anyMatch(dir -> isThreatening(dirInfo[dir.ordinal()].pieceType));

            System.out.println(inCheck ? "YES" : "NO");
        }
    }

    /**
     * Returns the direction from the king to (x, y), or {@code null} if the
     * coordinates are not aligned (i.e., not sharing a row, column or diagonal).
     */
    private static Direction getDirection(long kingX, long kingY,
                                            long x, long y) {
        long dx = x - kingX;
        long dy = y - kingY;

        if (dx == 0 && dy == 0) {
            return null; // same square – should not occur per problem statement
        }
        if (dx == 0) {
            return dy > 0 ? Direction.UP : Direction.DOWN;
        }
        if (dy == 0) {
            return dx > 0 ? Direction.RIGHT : Direction.LEFT;
        }
        if (Math.abs(dx) == Math.abs(dy)) {
            // Diagonal movement.
            return (dx > 0)
                    ? (dy > 0 ? Direction.UP_RIGHT : Direction.DOWN_RIGHT)
                    : (dy > 0 ? Direction.UP_LEFT : Direction.DOWN_LEFT);
        }
        return null; // not aligned
    }

    /**
     * Checks whether a piece of the given type can attack along its direction.
     * Only Rook ('R'), Bishop ('B') and Queen ('Q') are considered threatening.
     */
    private static boolean isThreatening(String pieceType) {
        return "R".equals(pieceType) || "B".equals(pieceType) || "Q".equals(pieceType);
    }

    /**
     * Returns a positive distance metric between two points.
     * Manhattan distance is sufficient for ordering because only relative
     * magnitude matters.
     */
    private static long distanceBetween(long x1, long y1, long x2, long y2) {
        return Math.abs(x1 - x2) + Math.abs(y1 - y2);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored version of the original Codechef solution.
 * The program reads a king's position and a list of points,
 * updates a set of “bound” variables according to the kind of point,
 * and finally decides whether a certain condition holds.
 *
 * The refactor focuses on:
 *   • Meaningful names and separate logical sections
 *   • Clear initialization and update logic
 *   • Elimination of duplicated code
 *   • Straight‑forward flag computation that mirrors the original logic
 */
public class Codechef {

    /* --------------------------------------------------------------------- */
    /*  Bounds that are updated while scanning the input                       */
    /* --------------------------------------------------------------------- */
    private static int lbx = Integer.MIN_VALUE;   // B‑horizontal left  (x < kingX, y = kingY)
    private static int rbx = Integer.MAX_VALUE;   // B‑horizontal right (x > kingX, y = kingY)

    private static int lrx = Integer.MIN_VALUE;   // R‑horizontal left  (x < kingX, y = kingY)
    private static int rrx = Integer.MAX_VALUE;   // R‑horizontal right (x > kingX, y = kingY)

    private static int ubY = Integer.MAX_VALUE;   // Upper vertical bound for type B
    private static int dby = Integer.MIN_VALUE;   // Lower vertical bound for type B

    private static int ury = Integer.MAX_VALUE;   // Upper vertical bound for types R/Q
    private static int dry = Integer.MIN_VALUE;   // Lower vertical bound for types R/Q

    private static int lbd1 = Integer.MIN_VALUE;  // Diagonal‑1 (x+y = const) left side, type B/R/Q
    private static int rbd1 = Integer.MAX_VALUE;  // Diagonal‑1 right side, type B/R/Q
    private static int lrd1 = Integer.MIN_VALUE;  // Diagonal‑1 left side, type R/Q
    private static int rrd1 = Integer.MAX_VALUE;  // Diagonal‑1 right side, type R/Q

    private static int lbd2 = Integer.MIN_VALUE;  // Diagonal‑2 (x‑y = const) left side, type B/R/Q
    private static int rbd2 = Integer.MAX_VALUE;  // Diagonal‑2 right side, type B/R/Q
    private static int lrd2 = Integer.MIN_VALUE;  // Diagonal‑2 left side, type R/Q
    private static int rrd2 = Integer.MAX_VALUE;  // Diagonal‑2 right side, type R/Q
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new java.io.InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        // ---------- read king position ----------
        StringTokenizer tk = new StringTokenizer(br.readLine());
        int kingX = Integer.parseInt(tk.nextToken());
        int kingY = Integer.parseInt(tk.nextToken());

        // ---------- read number of points ----------
        int n = Integer.parseInt(br.readLine());

        // ---------- helper constants ----------
        final int sumKey = kingX + kingY;   // constant for diagonal x + y
        final int diffKey = kingX - kingY;  // constant for diagonal x - y

        // ---------- process each point ----------
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            if (line == null || line.isBlank()) {
                continue;
            }
            StringTokenizer pt = new StringTokenizer(line);
            char type = pt.nextToken().charAt(0);
            int x = Integer.parseInt(pt.nextToken());
            int y = Integer.parseInt(pt.nextToken());

            updateCounters(type, x, y, kingX, kingY, sumKey, diffKey);
        }

        // ---------- decide the answer ----------
        boolean canReach = canReach(kingX, kingY);
        out.println(canReach ? "YES" : "NO");

        // ---------- clean up ----------
        out.close();
        br.close();
    }

    /**
     * Updates all bound variables according to the type of the current point.
     * The method mirrors the original algorithm but uses clearer conditional
     * blocks and avoids duplicated code.
     */
    private static void updateCounters(char type,
                                       int x, int y,
                                       int kingX, int kingY,
                                       int sumKey, int diffKey) {
        // ---- same row (y equals kingY) -------------------------------------------------
        if (y == kingY && x != kingX) {
            if (x < kingX) {
                // B uses `lbx`, R uses `lrx`, Q also updates `lrx` (same variable)
                switch (type) {
                    case 'B' -> lbx = Math.max(lbx, x);
                    case 'R' -> lrx = Math.max(lrx, x);
                    case 'Q' -> lrx = Math.max(lrx, x);
                }
            } else { // x > kingX
                // B uses `rbx`, R uses `rrx`, Q also updates `rrx`
                switch (type) {
                    case 'B' -> rbx = Math.min(rbx, x);
                    case 'R' -> rrx = Math.min(rrx, x);
                    case 'Q' -> rrx = Math.min(rrx, x);
                }
            }
        }

        // ---- same column (x equals kingX) ----------------------------------------------
        if (x == kingX && y != kingY) {
            if (y < kingY) {
                // B updates `dby`, R/Q update `dry`
                switch (type) {
                    case 'B' -> dby = Math.max(dby, y);
                    case 'R' -> dry = Math.max(dry, y);
                    case 'Q' -> dry = Math.max(dry, y);
                }
            } else { // y > kingY
                // B updates `uby`, R/Q update `ury`
                switch (type) {
                    case 'B' -> ubY = Math.min(ubY, y);
                    case 'R' -> ury = Math.min(ury, y);
                    case 'Q' -> ury = Math.min(ury, y);
                }
            }
        }

        // ---- diagonal x + y = const ----------------------------------------------------
        if (x + y == sumKey && x != kingX) {
            if (x < kingX) {
                // B/R/Q all share the same left‑side variables (`lbd1` / `lrd1`)
                switch (type) {
                    case 'B' -> lbd1 = Math.max(lbd1, x);
                    case 'R' -> lrd1 = Math.max(lrd1, x);
                    case 'Q' -> lbd1 = Math.max(lbd1, x);
                }
            } else { // x > kingX
                // B/R/Q share the same right‑side variables (`rbd1` / `rrd1`)
                switch (type) {
                    case 'B' -> rbd1 = Math.min(rbd1, x);
                    case 'R' -> rrd1 = Math.min(rrd1, x);
                    case 'Q' -> rbd1 = Math.min(rbd1, x);
                }
            }
        }

        // ---- diagonal x - y = const ----------------------------------------------------
        if (x - y == diffKey && x != kingX) {
            if (x < kingX) {
                // B/R/Q share the same left‑side variables (`lbd2` / `lrd2`)
                switch (type) {
                    case 'B' -> lbd2 = Math.max(lbd2, x);
                    case 'R' -> lrd2 = Math.max(lrd2, x);
                    case 'Q' -> lbd2 = Math.max(lbd2, x);
                }
            } else { // x > kingX
                // B/R/Q share the same right‑side variables (`rbd2` / `rrd2`)
                switch (type) {
                    case 'B' -> rbd2 = Math.min(rbd2, x);
                    case 'R' -> rrd2 = Math.min(rrd2, x);
                    case 'Q' -> rbd2 = Math.min(rbd2, x);
                }
            }
        }
    }

    /**
     * Implements the exact condition that the original program used to set
     * the `flag` variable.  The boolean expression is kept identical, only the
     * variable names are the same as those declared at the top of the class.
     */
    private static boolean canReach(int kingX, int kingY) {
        // The original logic was:
        //   flag = (lbx < lrx) ||
        //          (rrx < rbx) ||
        //          (ury < ubY) ||
        //          (dry > dby) ||
        //          (lbd1 > lrd1) ||
        //          (rbd1 < rrd1) ||
        //          (lbd2 > lrd2) ||
        //          (rbd2 < rrd2);
        return (lbx < lrx) ||
               (rrx < rbx) ||
               (ury < ubY) ||
               (dry > dby) ||
               (lbd1 > lrd1) ||
               (rbd1 < rrd1) ||
               (lbd2 > lrd2) ||
               (rbd2 < rrd2);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored version of the original Chess‑Check detector.
 * The program reads the board size, the king's position and a list of pieces,
 * then decides whether the king is in check.
 * The code has been reorganised for readability, maintainability and
 * correctness while preserving the original functionality.
 */
public class Main {

    /** Simple container for the king’s coordinates. */
    private static final class Position {
        final int col;  // X‑coordinate (file)
        final int row;  // Y‑coordinate (rank)

        Position(int col, int row) {
            this.col = col;
            this.row = row;
        }
    }

    /** Holds the current best candidate (closest) piece for each of the 8 directions. */
    private static final class DirectionInfo {
        /** Minimal distance found so far in this direction (Integer.MAX_VALUE = none yet). */
        final int minDist;
        /** Does the nearest piece have a checking power in this direction? */
        final boolean threatens;

        DirectionInfo(int minDist, boolean threatens) {
            this.minDist = minDist;
            this.threatens = threatens;
        }
    }

    /** The eight possible directions around the king. */
    private enum Direction {
        NORTH(0, 1, 0), SOUTH(4, -1, 0),
        EAST(2, 0, 1), WEST(6, 0, -1),
        NORTH_EAST(1, 1, 1), SOUTH_EAST(3, -1, 1),
        SOUTH_WEST(5, -1, -1), NORTH_WEST(7, 1, -1);

        private final int index;
        private final int dX;
        private final int dY;

        Direction(int index, int dX, int dY) {
            this.index = index;
            this.dX = dX;
            this.dY = dY;
        }

        /** Convert a numeric index (used by the original code) to this enum. */
        static Direction fromIndex(int idx) {
            for (Direction d : values()) {
                if (d.index == idx) {
                    return d;
                }
            }
            throw new IllegalArgumentException("Invalid direction index: " + idx);
        }

        /** Vector from the king towards the piece. */
        Position offset() {
            return new Position(dX, dY);
        }
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // ----- read board size and king position -----
            int pieceCount = Integer.parseInt(br.readLine().trim());

            StringTokenizer tk = new StringTokenizer(br.readLine());
            int kingCol = Integer.parseInt(tk.nextToken());
            int kingRow = Integer.parseInt(tk.nextToken());
            Position king = new Position(kingCol, kingRow);

            // ----- initialise direction containers -----
            DirectionInfo[] directionInfos = new DirectionInfo[8];
            for (int i = 0; i < 8; i++) {
                directionInfos[i] = new DirectionInfo(Integer.MAX_VALUE, false);
            }

            // ----- process each piece -----
            for (int i = 0; i < pieceCount; i++) {
                String[] parts = br.readLine().trim().split("\\s+");
                if (parts.length < 3) {
                    continue; // ignore malformed lines
                }

                char pieceType = parts[0].charAt(0);
                int pieceCol = Integer.parseInt(parts[1]);
                int pieceRow = Integer.parseInt(parts[2]);

                evaluateAndUpdate(king, pieceType, pieceCol, pieceRow, directionInfos);
            }

            // ----- determine if the king is in check -----
            boolean inCheck = false;
            for (DirectionInfo info : directionInfos) {
                if (info.threatens) {
                    inCheck = true;
                    break;
                }
            }

            System.out.println(inCheck ? "YES" : "NO");
        }
    }

    /**
     * Evaluates whether a given piece can give check along the line that joins it
     * with the king, and updates the nearest candidate for that direction if appropriate.
     *
     * @param king        Position of the king
     * @param pieceType   Symbol of the piece ('R', 'B' or 'Q')
     * @param pieceCol    Column of the piece
     * @param pieceRow    Row of the piece
     * @param infos       Array of DirectionInfo indexed by direction number (0‑7)
     */
    private static void evaluateAndUpdate(Position king,
                                          char pieceType,
                                          int pieceCol,
                                          int pieceRow,
                                          DirectionInfo[] infos) {
        int dx = king.col - pieceCol;
        int dy = king.row - pieceRow;

        // No alignment → cannot give check
        if (dx == 0 && dy == 0) {
            return;
        }

        // Determine direction index (0‑7) or ignore if not straight/diagonal
        int dirIdx = computeDirectionIndex(dx, dy);
        if (dirIdx == -1) {
            return;
        }

        Direction dir = Direction.fromIndex(dirIdx);

        // Distance metric used by the original code
        int distance;
        if ((dirIdx & 1) == 0) {                     // orthogonal directions
            distance = Math.abs(dx) + Math.abs(dy);
        } else {                                     // diagonal directions
            distance = Math.abs(dx);                 // |dx| == |dy|
        }

        // Does the piece have checking power in this direction?
        boolean threatens = ( (dirIdx % 2 == 0 && (pieceType == 'R' || pieceType == 'Q'))
                              || (dirIdx % 2 == 1 && (pieceType == 'B' || pieceType == 'Q')) );

        // Keep only the closest piece per direction
        DirectionInfo current = infos[dirIdx];
        if (distance < current.minDist) {
            infos[dirIdx] = new DirectionInfo(distance, threatens);
        }
    }

    /**
     * Computes the direction index (0‑7) for a vector (dx, dy) or returns -1
     * if the vector is not strictly orthogonal or diagonal.
     *
     * @param dx horizontal offset (king – piece)
     * @param dy vertical   offset (king – piece)
     * @return direction index or -1 if not a valid checking direction
     */
    private static int computeDirectionIndex(int dx, int dy) {
        if (dx == 0) {                     // vertical
            return dy > 0 ? Direction.NORTH.index : Direction.SOUTH.index;
        }
        if (dy == 0) {                     // horizontal
            return dx > 0 ? Direction.EAST.index : Direction.WEST.index;
        }
        if (Math.abs(dx) == Math.abs(dy)) { // diagonal
            if (dx > 0) {
                return dy > 0 ? Direction.NORTH_EAST.index : Direction.SOUTH_EAST.index;
            } else {
                return dy > 0 ? Direction.NORTH_WEST.index : Direction.SOUTH_WEST.index;
            }
        }
        return -1; // not aligned
    }
}

