/**
 * Eight possible directions from the origin.
 * Each direction knows how to recognise a displacement that lies exactly on its ray.
 */
enum Direction {
    /** (0, +1) – straight up */
    UP(0, 1),

    /** (+1, +1) – up‑right diagonal */
    UP_RIGHT(1, 1),

    /** (+1, 0) – straight right */
    RIGHT(1, 0),

    /** (+1, ‑1) – down‑right diagonal */
    DOWN_RIGHT(1, -1),

    /** (0, ‑1) – straight down */
    DOWN(0, -1),

    /** (‑1, ‑1) – down‑left diagonal */
    DOWN_LEFT(-1, -1),

    /** (‑1, 0) – straight left */
    LEFT(-1, 0),

    /** (‑1, +1) – up‑left diagonal */
    UP_LEFT(-1, 1);

    private final int dx;
    private final int dy;

    Direction(int dx, int dy) {
        this.dx = dx;
        this.dy = dy;
    }

    /** Index of the direction (0‑7) – useful for array lookup. */
    int index() {
        return ordinal();
    }

    /**
     * Returns the {@link Direction} that matches the given displacement,
     * or {@code null} if the displacement is not aligned with any of the eight rays.
     */
    static Direction fromDisplacement(int dx, int dy) {
        if (dx == 0) {
            return dy > 0 ? UP : dy < 0 ? DOWN : null;
        }
        if (dy == 0) {
            return dx > 0 ? RIGHT : dx < 0 ? LEFT : null;
        }
        int absDiff = Math.abs(dx) - Math.abs(dy);
        if (absDiff == 0) {                     // |dx| == |dy|  → diagonal
            if (dx > 0 && dy > 0) return UP_RIGHT;
            if (dx > 0 && dy < 0) return DOWN_RIGHT;
            if (dx < 0 && dy < 0) return DOWN_LEFT;
            if (dx < 0 && dy > 0) return UP_LEFT;
        }
        return null;
    }
}

/**
 * Very small wrapper around {@code BufferedReader} that supplies tokens and integers.
 */
class InputReader {
    private final BufferedReader br;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        br = new BufferedReader(new InputStreamReader(stream));
    }

    /** Makes sure a {@code StringTokenizer} is ready and returns the next token. */
    private String nextToken() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = br.readLine();
                if (line == null) {
                    return null;                // EOF
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }

    String next() {
        return nextToken();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }
}

/**
 * Core algorithm – determines whether any piece can attack the origin.
 * The class is deliberately small and focused on a single responsibility.
 */
final class Solver {
    /** Number of directions we track (always 8). */
    private static final int DIRECTION_COUNT = Direction.values().length;

    /** For each direction we keep the closest piece and its type. */
    private final int[] minDistance = new int[DIRECTION_COUNT];
    private final char[] minPiece = new char[DIRECTION_COUNT];

    /** Entry point used by {@code Main}. */
    void solve(InputReader reader, PrintWriter out) {
        initializeArrays();
        readInput(reader);

        boolean canCapture = examineStoredPieces();

        out.println(canCapture ? "YES" : "NO");
    }

    /** Fills the distance / piece arrays with sentinel values. */
    private void initializeArrays() {
        Arrays.fill(minDistance, Integer.MAX_VALUE);
        Arrays.fill(minPiece, '\0');
    }

    /** Parses all pieces, remembering only the nearest one in each direction. */
    private void readInput(InputReader reader) {
        int n = reader.nextInt();          // number of pieces
        int ox = reader.nextInt();         // origin x
        int oy = reader.nextInt();         // origin y

        for (int i = 0; i < n; i++) {
            char type = reader.next().charAt(0);
            int x = reader.nextInt();
            int y = reader.nextInt();

            int dx = x - ox;
            int dy = y - oy;
            Direction dir = Direction.fromDisplacement(dx, dy);
            if (dir == null) {
                continue;                    // not on a straight line through the origin
            }

            int distance = Math.max(Math.abs(dx), Math.abs(dy)); // Chebyshev distance
            if (distance < minDistance[dir.index()]) {
                minDistance[dir.index()] = distance;
                minPiece[dir.index()] = type;
            }
        }
    }

    /** Checks whether the piece stored for any direction could capture the origin. */
    private boolean examineStoredPieces() {
        for (int dirIdx = 0; dirIdx < DIRECTION_COUNT; dirIdx++) {
            if (canCapture(dirIdx, minPiece[dirIdx])) {
                return true;
            }
        }
        return false;
    }

    /** Determines if a piece placed on a given direction is able to move along that line. */
    private boolean canCapture(int dirIdx, char piece) {
        // Directions with even indices are straight (rook‑like), odd indices are diagonal (bishop‑like)
        boolean straight = (dirIdx % 2) == 0;

        return switch (piece) {
            case 'Q' -> true;                 // queen can move anywhere
            case 'R' -> straight;             // rook only on straight lines
            case 'B' -> !straight;            // bishop only on diagonals
            default -> false;
        };
    }
}

/**
 * Chess board attack detector.
 *
 * The program reads a list of pieces placed on an infinite chess board.
 * It determines whether any piece can attack the king according to standard
 * chess movement rules.
 *
 * Refactored for readability, maintainability and extensibility.
 */
public final class ChessCheck {

    /** Input helper – wraps {@link BufferedReader} and {@link StringTokenizer}. */
    private static final class InputReader {
        private final BufferedReader br;

        InputReader(final java.io.InputStream source) {
            this.br = new BufferedReader(new java.io.InputStreamReader(source));
        }

        /** Returns the next token from the input stream. */
        private String nextToken() throws java.io.IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(br.readLine());
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrappers for primitive token types. */
        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        char nextChar() {
            return nextToken().charAt(0);
        }

        private StringTokenizer tokenizer;
    }

    /** The eight principal directions a piece can approach the king. */
    private enum Direction {
        UP(0, 1),
        DOWN(0, -1),
        LEFT(-1, 0),
        RIGHT(1, 0),
        UP_LEFT(-1, 1),
        UP_RIGHT(1, 1),
        DOWN_LEFT(-1, -1),
        DOWN_RIGHT(1, -1);

        private final int dx;
        private final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        /**
         * Returns the direction represented by the given delta,
         * or {@code null} if the delta does not correspond to a
         * straight or diagonal line.
         */
        static Direction fromDelta(int dx, int dy) {
            if (dx == 0 && dy == 0) {
                return null;
            }
            for (Direction d : values()) {
                if (d.dx == dx && d.dy == dy) {
                    return d;
                }
            }
            // Check axial lines (horizontal, vertical, diagonal)
            if (Math.abs(dx) == Math.abs(dy) || dx == 0 || dy == 0) {
                // Determine direction based on sign
                int signX = Integer.compare(dx, 0);
                int signY = Integer.compare(dy, 0);
                for (Direction d : values()) {
                    if (d.dx == signX && d.dy == signY) {
                        return d;
                    }
                }
            }
            return null;
        }
    }

    /** Simple immutable representation of a board position. */
    private static final class Position {
        final int x;
        final int y;

        Position(int x, int y) {
            this.x = x;
            this.y = y;
        }

        /** Euclidean distance to another position (used only for comparison). */
        int distanceTo(Position other) {
            final int dx = this.x - other.x;
            final int dy = this.y - other.y;
            return dx * dx + dy * dy; // squared distance avoids sqrt
        }
    }

    public static void main(String[] args) throws java.io.IOException {
        try (InputReader in = new InputReader(System.in)) {
            // -----------------------------------------------------------------
            // 1. Read input
            // -----------------------------------------------------------------
            int pieceCount = in.nextInt();
            int kingX = in.nextInt();
            int kingY = in.nextInt();
            Position king = new Position(kingX, kingY);

            // Closest piece per direction, keyed by Direction enum
            var closestByDirection = new java.util.EnumMap<Direction, Position>(Direction.class);
            // Token representing the piece type found at that closest position
            var pieceTypeByDirection = new java.util.EnumMap<Direction, Character>(Direction.class);

            // -----------------------------------------------------------------
            // 2. Process each piece
            // -----------------------------------------------------------------
            for (int i = 0; i < pieceCount; i++) {
                char pieceChar = in.nextChar();           // 'Q', 'R', 'B', 'N', etc.
                int px = in.nextInt();
                int py = in.nextInt();

                Position candidate = new Position(px, py);
                int deltaX = px - kingX;
                int deltaY = py - kingY;

                Direction dir = Direction.fromDelta(deltaX, deltaY);
                if (dir == null) {
                    // Piece is not aligned with the king – cannot attack directly.
                    continue;
                }

                // Keep only the nearest piece in each direction.
                Position currentClosest = closestByDirection.get(dir);
                if (currentClosest == null || candidate.distanceTo(king) < currentClosest.distanceTo(king)) {
                    closestByDirection.put(dir, candidate);
                    pieceTypeByDirection.put(dir, pieceChar);
                }
            }

            // -----------------------------------------------------------------
            // 3. Determine if any of the nearest pieces can attack the king
            // -----------------------------------------------------------------
            boolean underAttack = false;
            for (Direction dir : Direction.values()) {
                Position nearest = closestByDirection.get(dir);
                if (nearest == null) {
                    continue; // No piece in this direction.
                }
                char type = pieceTypeByDirection.get(dir);
                // Attack possibilities:
                //   * Queen attacks along any direction.
                //   * Rook attacks only along the four orthogonal directions (indices 0,2,4,6).
                //   * Bishop attacks only along the four diagonal directions (indices 1,3,5,7).
                boolean isRookDirection = (dir.ordinal() % 2 == 0); // 0,2,4,6 → even indices
                boolean isDiagonalDirection = !isRookDirection;   // 1,3,5,7 → odd indices

                boolean canAttack =
                        type == 'Q' ||
                        (isRookDirection && type == 'R') ||
                        (isDiagonalDirection && type == 'B');

                if (canAttack) {
                    underAttack = true;
                    break;
                }
            }

            // -----------------------------------------------------------------
            // 4. Output result
            // -----------------------------------------------------------------
            System.out.println(underAttack ? "YES" : "NO");
        }
    }
}

import java.util.Scanner;

/**
 * Determines whether any opponent piece can give check to the white king.
 *
 * <p>Input format (example):
 * <pre>
 * p               // number of pieces to consider
 * kx ky           // king position (1‑based)
 * type x y        // description of each piece (type and coordinates)
 * </pre>
 *
 * <p>The program prints {@code YES} if at least one piece placed on the board can
 * attack the king following chess movement rules, otherwise it prints {@code NO}.
 */
public class ChessCheck {

    /** Enum representing the eight possible directions from the king. */
    private enum Direction {
        UP(0, -1),
        DOWN(0, 1),
        LEFT(-1, 0),
        RIGHT(1, 0),
        UP_LEFT(-1, -1),
        UP_RIGHT(1, -1),
        DOWN_LEFT(-1, 1),
        DOWN_RIGHT(1, 1);

        final int dx;
        final int dy;
        final int index;               // 0‑7 order matches the original code

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
            this.index = ordinal();
        }

        /** Convenience helpers used later. */
        boolean isOrthogonal() {
            return dx == 0 || dy == 0;
        }

        boolean isDiagonal() {
            return Math.abs(dx) == Math.abs(dy);
        }

        /** Factory method that maps a step vector to one of the eight directions. */
        static Direction fromDelta(int dx, int dy) {
            for (Direction d : values()) {
                if (d.dx == dx && d.dy == dy) {
                    return d;
                }
            }
            throw new IllegalArgumentException("No direction matches dx=" + dx + " dy=" + dy);
        }
    }

    /** Holds the closest piece found in a given direction. */
    private static final class ClosestPiece {
        final char type;   // 'R', 'B', or 'Q'
        final int distance; // number of steps to the piece

        ClosestPiece(char type, int distance) {
            this.type = type;
            this.distance = distance;
        }
    }

    public static void main(String[] args) {
        try (Scanner in = new Scanner(System.in)) {
            int pieceCount = in.nextInt();          // p
            int kingX = in.nextInt();               // kx
            int kingY = in.nextInt();               // ky

            // Initialise container for the nearest piece in each direction.
            ClosestPiece[] closestByDirection = new ClosestPiece[Direction.values().length];

            for (int i = 0; i < pieceCount; i++) {
                char pieceType = in.next().charAt(0);
                int x = in.nextInt();
                int y = in.nextInt();

                int dx = x - kingX;
                int dy = y - kingY;

                // Pieces that are not aligned with the king are ignored.
                if (!isAligned(dx, dy)) {
                    continue;
                }

                // Determine direction and its "steps" away from the king.
                Direction dir = Direction.fromDelta(dx, dy);
                int steps = Math.max(Math.abs(dx), Math.abs(dy)); // equal for diagonals

                // Keep only the closest piece for this direction.
                if (closestByDirection[dir.index] == null
                        || steps < closestByDirection[dir.index].distance) {
                    closestByDirection[dir.index] = new ClosestPiece(pieceType, steps);
                }
            }

            // Determine whether any of the retained pieces can give check.
            boolean givesCheck = hasCheckingPiece(closestByDirection);
            System.out.println(givesCheck ? "YES" : "NO");
        }
    }

    /** Returns true if the supplied delta vector lies on a straight line with the axes. */
    private static boolean isAligned(int dx, int dy) {
        return dx == 0 || dy == 0 || Math.abs(dx) == Math.abs(dy);
    }

    /** Checks the stored closest pieces for a possible check. */
    private static boolean hasCheckingPiece(ClosestPiece[] closest) {
        for (int i = 0; i < closest.length; i++) {
            ClosestPiece cp = closest[i];
            if (cp == null) {
                continue;
            }

            Direction dir = Direction.values()[i];
            boolean canAttack = switch (dir) {
                case UP, DOWN, LEFT, RIGHT -> cp.type == 'R' || cp.type == 'Q';
                default -> cp.type == 'B' || cp.type == 'Q';
            };
            if (canAttack) {
                return true;
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a grid‑point description and decides whether a horizontal/vertical
 * or diagonal alignment with the origin belongs to the correct piece type.
 *
 * <p>Original program performed a rather tangled mask‑based search.
 * The refactor replaces that with a clear, step‑by‑step algorithm:
 *
 * <ol>
 *   <li>All points are stored together with their Manhattan distance
 *       from the origin.</li>
 *   <li>They are sorted by that distance.</li>
 *   <li>Each point is examined in order; the first point that
 *       <ul>
 *         <li>lies on the same row or column <strong>and</strong> is not a
 *             bishop ('B'), or</li>
 *         <li>lies on a diagonal <strong>and</strong> is not a rook ('R')
 *             triggers an immediate “YES”.</li>
 *       </ul>
 *   </li>
 *   <li>If no such point exists the answer is “NO”.</li>
 * </ol>
 *
 * <p>This version uses meaningful names, a small {@link Direction}
 * enum, and separates concerns into tiny private methods, making the
 * logic easy to follow and maintain.
 */
public class D {

    /** Simple container for a point together with its type and distance. */
    private static final class Point {
        final char type;   // 'B' – bishop, 'R' – rook, other letters are possible
        final int x;
        final int y;
        final long dist;   // Manhattan distance to the origin (x0,y0)

        Point(char type, int x, int y, long dist) {
            this.type = type;
            this.x = x;
            this.y = y;
            this.dist = dist;
        }
    }

    /** Directions that can be expressed relative to the origin. */
    private enum Direction {
        ROW,
        COLUMN,
        DIAGONAL;

        /** Returns true if the supplied coordinates belong to this direction. */
        boolean matches(int x, int y, int x0, int y0) {
            return switch (this) {
                case ROW -> x == x0;
                case COLUMN -> y == y0;
                case DIAGONAL -> Math.abs(x - x0) == Math.abs(y - y0);
            };
        }
    }

    /** Fast I/O helpers copied from the original code. */
    private final BufferedReader reader;
    private StringTokenizer tokenizer;
    private final PrintWriter out;

    /** Constructor – creates the I/O objects. */
    public D() {
        reader = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(new OutputStreamWriter(System.out));
    }

    /** Entry point required by the original `main`. */
    public static void main(String[] args) throws IOException {
        new D().run();
    }

    /** Core solving routine – mirrors the original `solve()` signature. */
    public void solve() throws IOException {
        // ----- 1️⃣  Input -------------------------------------------------
        String nToken = nextToken();
        int n = Integer.parseInt(nToken);
        int x0 = Integer.parseInt(nextToken());
        int y0 = Integer.parseInt(nextToken());

        List<Point> points = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            String token = nextToken();
            char type = token.charAt(0);
            int x = Integer.parseInt(nextToken());
            int y = Integer.parseInt(nextToken());

            long dist = Math.abs(x - x0) + Math.abs(y - y0);
            points.add(new Point(type, x, y, dist));
        }

        // ----- 2️⃣  Sort by Manhattan distance ---------------------------
        points.sort(Comparator.comparingLong(p -> p.dist));

        // ----- 3️⃣  Scan points in increasing distance -------------------
        for (Point p : points) {
            Direction dir = determineDirection(p.x, p.y, x0, y0);

            // Skip points that are not aligned (row, column or diagonal)
            if (dir == null) {
                continue;
            }

            // Row or column alignment – only a rook ('R') is *not* interesting.
            // The original logic fires when the point is **not** a bishop.
            if ((dir == Direction.ROW || dir == Direction.COLUMN) && p.type != 'B') {
                out.println("YES");
                return;
            }

            // Diagonal alignment – only a bishop ('B') is *not* interesting.
            // The original logic fires when the point is **not** a rook.
            if (dir == Direction.DIAGONAL && p.type != 'R') {
                out.println("YES");
                return;
            }
        }

        // ----- 4️⃣  No suitable point found -------------------------------
        out.println("NO");
    }

    /** Determines the direction of a point relative to the origin.
     *  Returns {@link Direction#ROW}, {@link Direction#COLUMN},
     *  {@link Direction#DIAGONAL} or {@code null} if none matches. */
    private Direction determineDirection(int x, int y, int x0, int y0) {
        if (x == x0 && y == y0) {
            return null; // same point – not relevant for the problem
        }
        if (x == x0) {
            return Direction.ROW;
        }
        if (y == y0) {
            return Direction.COLUMN;
        }
        if (Math.abs(x - x0) == Math.abs(y - y0)) {
            return Direction.DIAGONAL;
        }
        return null;
    }

    /* --------------------------------------------------------------
       5️⃣  Boiler‑plate fast‑scanner helpers (unchanged from original)
       -------------------------------------------------------------- */
    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    private long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    private double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    /** Required by the original `run()` method. */
    private void run() throws IOException {
        solve();
        reader.close();
        out.flush();
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Sentinel value used for “not yet set” distances. */
    private static final long NOT_SET = Long.MAX_VALUE / 4;

    /** Holds the nearest token found for one of the eight directions. */
    private static final class Nearest {
        final char symbol;
        long distance;

        Nearest(char symbol, long distance) {
            this.symbol = symbol;
            this.distance = distance;
        }
    }

    /** The eight possible directions from the reference point (x0, y0). */
    private enum Direction {
        RIGHT(1, 0),                 // →  (dx>0, dy==0)
        UPLEFT_DIAG( -1, 1),         // ↗ (dx<0, dy>0, -dx==dy)
        UP(0, 1),                     // ↑  (dx==0, dy>0)
        UPRIGHT_DIAG( 1, -1),         // ↘ (dx>0, dy<0, dx==-dy)
        LEFT( -1, 0),                 // ←  (dx<0, dy==0)
        DOWNLEFT_DIAG( 1, -1),         // ↙ (dx>0, dy<0, dx==-dy) – note the swapped signs in the original code
        DOWN(0, -1),                  // ↓  (dx==0, dy<0)
        UPRIGHT(1, 1);                // ↖  (dx>0, dy>0, dx==dy)

        final int dx, dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        /** Updates the {@link Nearest} holder if the given point belongs to this direction
         *  and is closer than the current best distance. */
        void update(long x, long y, char symbol, Nearest[] storage) {
            long relX = x - referenceX;
            long relY = y - referenceY;

            // The direction holds only if the vector matches the sign pattern and the magnitude relation.
            if (matchesDirection(relX, relY)) {
                long step = Math.abs(relX);     // all valid directions use the same magnitude step
                if (step < storage[ordinal].distance) {
                    storage[ordinal] = new Nearest(symbol, step);
                }
            }
        }

        /** Checks whether (dx,dy) conforms to this direction's geometric constraints. */
        private boolean matchesDirection(long dx, long dy) {
            // Simple sign checks – the magnitude relation is handled by the caller (see Direction.of(dx,dy) )
            return switch (this) {
                case RIGHT -> dx > 0 && dy == 0;
                case UPLEFT_DIAG -> dx < 0 && dy > 0 && -dx == dy;
                case UP -> dx == 0 && dy > 0;
                case UPRIGHT_DIAG -> dx > 0 && dy < 0 && dx == -dy;
                case LEFT -> dx < 0 && dy == 0;
                case DOWNLEFT_DIAG -> dx > 0 && dy < 0 && dx == -dy;
                case DOWN -> dx == 0 && dy < 0;
                case UPRIGHT -> dx > 0 && dy > 0 && dx == dy;
            };
        }
    }

    /** Helper to map a pair (dx,dy) to the appropriate {@link Direction}. */
    private static Direction of(long dx, long dy) {
        // The original code uses a mixture of inequalities; this mapping exactly reproduces them.
        if (dx > 0 && dy == 0) return Direction.RIGHT;
        if (dx > 0 && dx == dy) return Direction.UPRIGHT_DIAG;          // original: xi-x0 == yi-y0
        if (dx == 0 && dy > 0) return Direction.UP;
        if (dx < 0 && dx == -dy) return Direction.LEFT;                // original: x0-xi == y0-yi
        if (dx < 0 && dy == 0) return Direction.LEFT;                  // actually LEFT, but the original used dx<x0 && yi==y0
        if (dx < 0 && dx == dy) return Direction.DOWNLEFT_DIAG;        // original diagonal check
        if (dx == 0 && dy < 0) return Direction.DOWN;
        if (dx > 0 && dx == -dy) return Direction.UPRIGHT_DIAG;         // original diagonal check
        return null; // point does not belong to any of the eight considered directions
    }

    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
    }

    public static void main(String[] args) throws IOException {
        /* ---------- Input handling ------------------------------------------------- */
        InputStream source = (args.length > 0 && "devTesting".equals(args[0]))
                ? new FileInputStream(args[1])
                : System.in;

        try (InputStream in = source;
             OutputStream out = System.out) {

            InputReader in = new InputReader(in);
            PrintWriter out = new PrintWriter(out);

            new Solver().solve(in, out);
            out.flush();
        }
    }

    /** Core logic – formerly named `TaskD`. */
    private static final class Solver {

        private final Nearest[] nearest = new Nearest[Direction.values().length];
        private long x0, y0;           // reference point
        private char ch;               // current token

        void solve(InputReader in, PrintWriter out) {
            Arrays.fill(nearest, new Nearest(' ', NOT_SET));

            int pointCount = in.nextInt();
            x0 = in.nextInt();
            y0 = in.nextInt();

            for (int i = 0; i < pointCount; i++) {
                ch = in.next().charAt(0);
                long xi = in.nextLong();
                long yi = in.nextLong();

                Direction dir = Direction.of(xi - x0, yi - y0);
                if (dir != null) {
                    dir.update(xi, yi, ch, nearest);
                }
            }

            boolean namingOk = validateNames();
            out.println(namingOk ? "NO" : "YES");
        }

        /** Checks the naming constraints described in the original solution. */
        private boolean validateNames() {
            for (int i = 0; i < Direction.values().length; i++) {
                if (i % 2 == 0) { // even index → must not be 'Q' or 'R'
                    if (nearest[i].symbol == 'Q' || nearest[i].symbol == 'R') {
                        return false;
                    }
                } else {          // odd index → must not be 'B' or 'Q'
                    if (nearest[i].symbol == 'B' || nearest[i].symbol == 'Q') {
                        return false;
                    }
                }
            }
            return true;
        }
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Reads a board description from standard input and determines whether the
 * white king is in check after all pieces have been placed.
 */
public class Main {

    /** Maximum number of directions we track (N, NW, W, SW, S, SE, E, NE). */
    private static final int DIRECTION_COUNT = 8;
    /** Sentinel value for “no distance recorded yet”. */
    private static final long UNDEFINED_DISTANCE = Long.MAX_VALUE;

    public static void main(String[] args) throws IOException {
        /* ---------- input handling ---------- */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int pieceCount = Integer.parseInt(br.readLine());

            // The first piece described is the white king.
            String[] kingTokens = br.readLine().split("\\s+");
            King king = new King(
                    Integer.parseInt(kingTokens[0]),
                    Integer.parseInt(kingTokens[1])
            );

            // Nearest piece recorded for each of the 8 directions.
            DirectionalInfo[] nearest = new DirectionalInfo[DIRECTION_COUNT];
            Arrays.setAll(nearest, d -> new DirectionalInfo());

            // Process the remaining pieces.
            String line;
            while ((line = br.readLine()) != null) {
                String[] tokens = line.split("\\s+");
                ChessPiece piece = new ChessPiece(
                        Integer.parseInt(tokens[1]),
                        Integer.parseInt(tokens[2]),
                        tokens[0].charAt(0)
                );

                int direction = king.directionRelativeTo(piece);
                if (direction < 0) {
                    continue; // piece not aligned with the king
                }

                long distance = king.manhattanDistanceTo(piece);
                if (distance < nearest[direction].distance) {
                    nearest[direction].piece = piece;
                    nearest[direction].distance = distance;
                }
            }

            /* ---------- check detection ---------- */
            boolean isCheck = Arrays.stream(nearest)
                    .anyMatch(info -> info.piece != null &&
                            canCheck(info.piece, info.direction));

            System.out.println(isCheck ? "YES" : "NO");
        }
    }

    /** Returns true if the given piece can give check from its direction. */
    private static boolean canCheck(ChessPiece piece, int direction) {
        char type = piece.getType();
        // Orthogonal directions correspond to even indices, diagonals to odd.
        return type == 'Q' ||
                (type == 'R' && (direction % 2) == 0) ||
                (type == 'B' && (direction % 2) == 1);
    }

    /* ---------- data structures ---------- */

    /** Holds the nearest piece found for a particular direction. */
    private static final class DirectionalInfo {
        ChessPiece piece = null;
        long distance = UNDEFINED_DISTANCE;
    }

    /** Represents the white king and encapsulates direction‑detection logic. */
    private static final class King extends ChessPiece {
        King(int x, int y) {
            super(x, y, 'K');
        }

        /**
         * Determines the direction index (0‑7) of {@code other} relative to this king.
         * The mapping follows the original program:
         * <ul>
         *   <li>0 – north</li>
         *   <li>1 – north‑west</li>
         *   <li>2 – west</li>
         *   <li>3 – south‑west</li>
         *   <li>4 – south</li>
         *   <li>5 – south‑east</li>
         *   <li>6 – east</li>
         *   <li>7 – north‑east</li>
         * </ul>
         * @return direction index or -1 if the piece is not aligned.
         */
        int directionRelativeTo(ChessPiece other) {
            // Exact reproduction of the original direction logic for compatibility.
            if (this.x == other.x && this.y < other.y) {
                return 0;
            } else if (this.x < other.x && this.x - other.x == this.y - other.y) {
                return 1;
            } else if (this.x < other.x && this.y == other.y) {
                return 2;
            } else if (this.x < other.x && other.x - this.x == other.y - this.y) {
                return 3;
            } else if (this.x == other.x && this.y > other.y) {
                return 4;
            } else if (this.x > other.x && this.x - other.x == this.y - other.y) {
                return 5;
            } else if (this.x > other.x && this.y == other.y) {
                return 6;
            } else if (this.x > other.x && other.x - this.x == other.y - this.y) {
                return 7;
            }
            return -1;
        }

        /** Manhattan distance to another piece (used only for comparison). */
        long manhattanDistanceTo(ChessPiece other) {
            return (long) Math.abs(this.x - other.x) + Math.abs(this.y - other.y);
        }
    }

    /** Simple data holder for a chess piece. */
    private static final class ChessPiece {
        private final int x;
        private final int y;
        private final char type;

        ChessPiece(int x, int y, char type) {
            this.x = x;
            this.y = y;
            this.type = type;
        }

        int getX() { return x; }
        int getY() { return y; }
        char getType() { return type; }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Entry point of the application.
 */
public class Main {

    public static void main(String[] args) {
        solve();
    }

    /**
     * Reads input, processes it and prints the answer.
     */
    private static void solve() {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        int n = reader.nextInt();
        int baseX = reader.nextInt();
        int baseY = reader.nextInt();

        List<Point> points = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            char type = reader.next();
            int x = reader.nextInt();
            int y = reader.nextInt();
            points.add(new Point(type, x, y));
        }

        Solver solver = new Solver();
        boolean found = solver.hasAttacker(points, baseX, baseY);
        out.println(found ? "YES" : "NO");
    }

    /** Simple data holder for a point with its type and coordinates. */
    static final class Point {
        final char type;   // one of 'R', 'Q', 'B', … (used by the algorithm)
        final int x;
        final int y;

        Point(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Contains the business logic that decides whether an “attacker” exists.
     */
    static final class Solver {

        /** Main entry used by {@code solve()}. */
        boolean hasAttacker(List<Point> pts, int baseX, int baseY) {
            return checkHorizontal(pts, baseX, baseY)
                || checkVertical(pts, baseX, baseY)
                || checkDiagonalMain(pts, baseX, baseY)
                || checkDiagonalAnti(pts, baseX, baseY);
        }

        /** Checks the horizontal line y‑axis through (baseX, baseY). */
        private boolean checkHorizontal(List<Point> pts, int baseX, int baseY) {
            int maxIdx = -1;   // index of point with the greatest y  (y > baseY)
            int minIdx = -1;   // index of point with the smallest y  (y <= baseY)

            for (int i = 0; i < pts.size(); i++) {
                Point p = pts.get(i);
                if (p.x != baseX) continue;

                if (p.y > baseY) {
                    if (maxIdx < 0 || p.y > pts.get(maxIdx).y) {
                        maxIdx = i;
                    }
                } else {
                    if (minIdx < 0 || p.y < pts.get(minIdx).y) {
                        minIdx = i;
                    }
                }
            }

            if (maxIdx >= 0 && isROrQ(pts.get(maxIdx).type)) return true;
            if (minIdx >= 0 && isROrQ(pts.get(minIdx).type)) return true;
            return false;
        }

        /** Checks the vertical line x‑axis through (baseX, baseY). */
        private boolean checkVertical(List<Point> pts, int baseX, int baseY) {
            int maxIdx = -1;   // index of point with the greatest x  (x > baseX)
            int minIdx = -1;   // index of point with the smallest x  (x <= baseX)

            for (int i = 0; i < pts.size(); i++) {
                Point p = pts.get(i);
                if (p.y != baseY) continue;

                if (p.x > baseX) {
                    if (maxIdx < 0 || p.x > pts.get(maxIdx).x) {
                        maxIdx = i;
                    }
                } else {
                    if (minIdx < 0 || p.x < pts.get(minIdx).x) {
                        minIdx = i;
                    }
                }
            }

            if (maxIdx >= 0 && isROrQ(pts.get(maxIdx).type)) return true;
            if (minIdx >= 0 && isROrQ(pts.get(minIdx).type)) return true;
            return false;
        }

        /** Checks the diagonal with slope +1 (y - x = const). */
        private boolean checkDiagonalMain(List<Point> pts, int baseX, int baseY) {
            int maxIdx = -1;   // point with larger x (and thus larger y) on the line
            int minIdx = -1;   // point with smaller x on the line

            int constDiff = baseY - baseX;
            for (int i = 0; i < pts.size(); i++) {
                Point p = pts.get(i);
                if (p.y - p.x != constDiff) continue;

                if (p.x > baseX) {
                    if (maxIdx < 0 || p.x > pts.get(maxIdx).x) {
                        maxIdx = i;
                    }
                } else {
                    if (minIdx < 0 || p.x < pts.get(minIdx).x) {
                        minIdx = i;
                    }
                }
            }

            if (maxIdx >= 0 && isBOrQ(pts.get(maxIdx).type)) return true;
            if (minIdx >= 0 && isBOrQ(pts.get(minIdx).type)) return true;
            return false;
        }

        /** Checks the diagonal with slope –1 (y + x = const). */
        private boolean checkDiagonalAnti(List<Point> pts, int baseX, int baseY) {
            int maxIdx = -1;   // point with larger x on the line
            int minIdx = -1;   // point with smaller x on the line

            int constSum = baseX + baseY;
            for (int i = 0; i < pts.size(); i++) {
                Point p = pts.get(i);
                if (p.x + p.y != constSum) continue;

                if (p.x > baseX) {
                    if (maxIdx < 0 || p.x > pts.get(maxIdx).x) {
                        maxIdx = i;
                    }
                } else {
                    if (minIdx < 0 || p.x < pts.get(minIdx).x) {
                        minIdx = i;
                    }
                }
            }

            if (maxIdx >= 0 && isBOrQ(pts.get(maxIdx).type)) return true;
            if (minIdx >= 0 && isBOrQ(pts.get(minIdx).type)) return true;
            return false;
        }

        /** Helper: true for pieces that attack horizontally/vertically. */
        private static boolean isROrQ(char c) {
            return c == 'R' || c == 'Q';
        }

        /** Helper: true for pieces that attack on the two diagonals. */
        private static boolean isBOrQ(char c) {
            return c == 'B' || c == 'Q';
        }
    }

    /**
     * Fast tokenizer based on {@link BufferedReader}.
     * Keeps the original behaviour of the provided starter code.
     */
    static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream, 32768));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>This implementation improves readability, uses meaningful names,
 * separates concerns, and removes magic numbers while keeping the original
 * behaviour intact.</p>
 */
public class ChessMoveValidator {

    /** Offset that was added to input coordinates in the original code. */
    private static final long OFFSET = 1_000_000_000L;

    /** Sentinel distance used in the original program (≈ 2 000 000 001). */
    private static final long INIT_DIST = 2_000_000_001L;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {

            /* -------------------------------------------------
             * 1. Read input data
             * ------------------------------------------------- */
            long n = scanner.nextLong();

            long x = scanner.nextLong() + OFFSET;   // original start coordinates
            long y = scanner.nextLong() + OFFSET;

            /* -------------------------------------------------
             * 2. Variables that keep the closest piece in each
             *    direction (initialised with the same sentinel
             *    values as the original code).
             * ------------------------------------------------- */
            long minNorthDist   = INIT_DIST;
            String northPiece   = "*";

            long minSouthDist   = INIT_DIST;
            String southPiece   = "*";

            long minEastDist    = INIT_DIST;
            String eastPiece    = "*";

            long minWestDist    = INIT_DIST;
            String westPiece    = "*";

            long minNEQdist     = INIT_DIST;   // north‑east (dx>0, dy>0)
            String nePiece      = "*";

            long minNWQdist     = INIT_DIST;   // north‑west (dx<0, dy>0)
            String nwPiece      = "*";

            long minSEdist      = INIT_DIST;   // south‑east (dx>0, dy<0)
            String sePiece      = "*";

            long minSWdist      = INIT_DIST;   // south‑west (dx<0, dy<0)
            String swPiece      = "*";

            /* -------------------------------------------------
             * 3. Process each of the n moves
             * ------------------------------------------------- */
            for (long i = 0; i < n; i++) {
                String piece = scanner.next();                 // direction identifier
                long xf = scanner.nextLong() + OFFSET;         // target x
                long yf = scanner.nextLong() + OFFSET;         // target y

                long dx = xf - x;
                long dy = yf - y;

                // ----- Cardinal directions -------------------------------------------------
                if (dx == 0 && dy > 0) {          // north
                    if (dy < minNorthDist) {
                        minNorthDist = dy;
                        northPiece = piece;
                    }
                }
                if (dx == 0 && dy < 0) {          // south
                    long absDy = -dy;
                    if (absDy < minSouthDist) {
                        minSouthDist = absDy;
                        southPiece = piece;
                    }
                }
                if (dy == 0 && dx > 0) {          // east
                    if (dx < minEastDist) {
                        minEastDist = dx;
                        eastPiece = piece;
                    }
                }
                if (dy == 0 && dx < 0) {          // west
                    long absDx = -dx;
                    if (absDx < minWestDist) {
                        minWestDist = absDx;
                        westPiece = piece;
                    }
                }

                // ----- Diagonal directions -------------------------------------------------
                if (Math.abs(dx) == Math.abs(dy)) {
                    // south‑east  (dx>0, dy<0)
                    if (dx > 0 && dy < 0 && dx < minSEdist) {
                        minSEdist = dx;
                        sePiece = piece;
                    }
                    // south‑west  (dx<0, dy<0)
                    if (dx < 0 && dy < 0 && -dx < minSWdist) {
                        minSWdist = -dx;
                        swPiece = piece;
                    }
                    // north‑east  (dx>0, dy>0)
                    if (dx > 0 && dy > 0 && dx < minNEQdist) {
                        minNEQdist = dx;
                        nePiece = piece;
                    }
                    // north‑west  (dx<0, dy>0)
                    if (dx < 0 && dy > 0 && -dx < minNWQdist) {
                        minNWQdist = -dx;
                        nwPiece = piece;
                    }
                }
            }

            /* -------------------------------------------------
             * 4. Build the two strings that are examined for
             *    rook/queen (cardinal) and bishop/queen (diagonal)
             *    pieces.
             * ------------------------------------------------- */
            String cardinal = southPiece + westPiece + eastPiece + northPiece;
            String diagonal = sePiece + swPiece + nePiece + nwPiece;

            boolean hasRookOrQueen = cardinal.matches(".*[RQ].*");
            boolean hasBishopOrQueen = diagonal.matches(".*[BQ].*");

            /* -------------------------------------------------
             * 5. Output the result according to the original logic.
             * ------------------------------------------------- */
            System.out.print((hasRookOrQueen || hasBishopOrQueen) ? "YES" : "NO");
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the “Anton and Chess” problem.
 *
 * <p>
 * The program reads a king position on an infinite board and a set of pieces.
 * For each of the eight directions (horizontal, vertical, two diagonals) it keeps
 * the closest piece to the king. Afterwards it checks whether every kept piece
 * matches the expected colour pattern defined by {@code EXPECTED_PATTERN}.
 * The result is printed as “YES” or “NO” (the logic is deliberately opposite to
 * the usual one to preserve the original specification).
 * </p>
 */
public class AntonandChess {

    /** Expected colour pattern (3×3 board centred on the king). */
    private static final char[][] EXPECTED_PATTERN = {
            {'R', 'B', 'R'},
            {'B', '*', 'B'},
            {'R', 'B', 'R'}
    };

    /** Mapping from a direction to the cell in the 3×3 board where the piece is stored. */
    private enum Direction {
        UP        ((1, 2)),
        DOWN      ((1, 0)),
        LEFT      ((0, 1)),
        RIGHT     ((2, 1)),
        UP_RIGHT  ((2, 2)),
        DOWN_LEFT ((0, 0)),
        DOWN_RIGHT((2, 0)),
        UP_LEFT   ((0, 2));

        private final int row;
        private final int col;

        Direction(int row, int col) {
            this.row = row;
            this.col = col;
        }

        int row() { return row; }
        int col() { return col; }
    }

    /**
     * Entry point.
     *
     * @param in  Fast scanner used to read the input.
     * @param out Print writer used to output the answer.
     */
    private static void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();          // number of pieces
        int kingX = in.nextInt();      // king column
        int kingY = in.nextInt();      // king row

        // board[i][j] holds the closest piece in the direction mapped to cell (i,j)
        Pair[][] board = new Pair[3][3];
        // initialise with null (no piece found yet)

        for (int i = 0; i < n; i++) {
            Pair candidate = readPiece(in);
            if (candidate == null) {
                continue; // safety – should never happen
            }

            // Determine the direction of the candidate relative to the king
            Direction dir = directionOf(candidate, kingX, kingY);
            if (dir == null) {
                // Piece is not aligned with the king – ignore it
                continue;
            }

            // Keep only the closest piece in that direction
            Pair current = board[dir.row()][dir.col()];
            if (current == null || isCloser(candidate, kingX, kingY, current)) {
                board[dir.row()][dir.col()] = candidate;
            }
        }

        // Validate the board against the expected pattern
        boolean allMatch = true;
        for (int r = 0; r < 3; r++) {
            for (int c = 0; c < 3; c++) {
                Pair p = board[r][c];
                if (p != null && p.type != EXPECTED_PATTERN[r][c]) {
                    allMatch = false;
                    break;
                }
            }
            if (!allMatch) {
                break;
            }
        }

        // Original logic: if everything matches we output "NO", otherwise "YES"
        out.println(allMatch ? "NO" : "YES");
    }

    /** Reads a single piece (type, x, y) from the scanner. */
    private static Pair readPiece(FastScanner in) {
        char type = in.nextChar();
        int x = in.nextInt();
        int y = in.nextInt();
        return new Pair(type, x, y);
    }

    /**
     * Determines the direction of the given piece relative to the king.
     *
     * @return One of the {@link Direction} values, or {@code null} if the piece
     *         is not aligned horizontally, vertically or diagonally with the king.
     */
    private static Direction directionOf(Pair piece, int kx, int ky) {
        int dx = piece.x - kx;
        int dy = piece.y - ky;

        if (dx == 0) {                     // same file – vertical
            return dy > 0 ? Direction.UP : Direction.DOWN;
        }
        if (dy == 0) {                     // same rank – horizontal
            return dx > 0 ? Direction.RIGHT : Direction.LEFT;
        }
        if (dx == dy) {                    // main diagonal (slope 1)
            return dx > 0 ? Direction.UP_RIGHT : Direction.DOWN_LEFT;
        }
        if (dx == -dy) {                   // anti‑diagonal (slope -1)
            return dx > 0 ? Direction.DOWN_RIGHT : Direction.UP_LEFT;
        }
        return null; // not aligned
    }

    /** Returns {@code true} if {@code candidate} is closer to the king than {@code current}. */
    private static boolean isCloser(Pair candidate, int kx, int ky, Pair current) {
        int dxC = Math.abs(candidate.x - kx);
        int dyC = Math.abs(candidate.y - ky);
        int dxCur = Math.abs(current.x - kx);
        int dyCur = Math.abs(current.y - ky);

        // For non‑diagonal directions only one of dx/dy is non‑zero.
        if (dxC == 0 || dyC == 0) {
            return dxC + dyC < dxCur + dyCur;
        }
        // For diagonal directions dx and dy are equal in magnitude.
        return dxC < dxCur;
    }

    /** Simple container for a piece on the board. */
    static class Pair {
        final char type;
        final int x;
        final int y;

        Pair(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return "TYPE: " + type + " (" + x + ", " + y + ')';
        }
    }

    /** Fast input scanner (unchanged from the original submission). */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        char nextChar() {
            return next().charAt(0);
        }

        int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        // Additional convenience methods omitted for brevity (same as original)
        // …
        void close() {
            try {
                reader.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    /** Main method – reads input, runs the algorithm and prints the result. */
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter printer = new PrintWriter(
                new BufferedWriter(new OutputStreamWriter(System.out)), false);
        solve(scanner, printer);
        scanner.close();
        printer.close();
    }
}

import java.io.PrintWriter;
import java.io.UncheckedIOException;
import java.util.EnumMap;
import java.util.Map;

/**
 * Refactored solution for the “Rooks and Bishops” problem.
 *
 * The program reads a set of chess pieces, determines the nearest piece
 * in each of the eight directions around the reference rook at (x₀,y₀),
 * and decides whether any piece of the opposite type exists in a
 * direction that would allow a capture.
 *
 * The refactor focuses on readability, maintainability and explicit
 * intent by:
 *   • Using enums and small data holders instead of ad‑hoc classes.
 *   • Removing duplicated indexing logic.
 *   • Encapsulating I/O and algorithmic steps into dedicated classes.
 *   • Making extensive use of `final`, `private` members and meaningful
 *     names.
 *   • Using try‑with‑resources for guaranteed resource closure.
 */
public class Main {

    /** Directions relative to the reference rook. */
    private enum Direction {
        /** East  : ( +1,  0 ) */
        EAST(1, 0),
        /** WEST : ( -1,  0 ) */
        WEST(-1, 0),
        /** NORTH: ( 0, +1 ) */
        NORTH(0, 1),
        /** SOUTH: ( 0, -1 ) */
        SOUTH(0, -1),
        /** NORTHEAST : ( +1, +1 ) */
        NORTHEAST(1, 1),
        /** NORTHWEST : ( -1, +1 ) */
        NORTHWEST(-1, 1),
        /** SOUTHWEST : ( -1, -1 ) */
        SOUTHWEST(-1, -1),
        /** SOUTHEAST : ( +1, -1 ) */
        SOUTHEAST(1, -1);

        final long dx;
        final long dy;

        Direction(long dx, long dy) {
            this.dx = dx;
            this.dy = dy;
        }

        /** Whether this direction lies on one of the eight main axes (horizontal/vertical/diagonal). */
        boolean isAxis() {
            return dx == 0 || dy == 0;
        }

        /** Whether this direction lies on a diagonal (|dx| == |dy|). */
        boolean isDiagonal() {
            return Math.abs(dx) == Math.abs(dy);
        }

        /** Returns the matching {@code Direction} for the given delta, or {@code null} if it does not belong to the eight main directions. */
        static Direction fromDelta(long dx, long dy) {
            for (Direction d : values()) {
                if (d.dx == dx && d.dy == dy) {
                    return d;
                }
            }
            return null;
        }
    }

    /** Simple container that stores the nearest piece for a given direction. */
    private static final class Piece {
        final char type;                 // 'R' for rook, 'B' for bishop
        long relX, relY;                   // coordinates relative to the reference rook
        long manhattan;                    // |dx| + |dy|, used to keep the nearest piece

        Piece(char type) {
            this.type = type;
            this.manhattan = Long.MAX_VALUE;
        }

        /** Updates the stored piece if the new one is closer (smaller Manhattan distance). */
        void update(long dx, long dy, char type) {
            long newManhattan = Math.abs(dx) + Math.abs(dy);
            if (newManhattan < manhattan) {
                this.relX = dx;
                this.relY = dy;
                this.type = type;
                this.manhattan = newManhattan;
            }
        }
    }

    /** Fast scanner that works with the standard input stream. */
    private static final class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int bufferLength = 0;

        /** Reads the next printable character sequence (a token). */
        String next() {
            skipNonPrintable();
            StringBuilder sb = new StringBuilder();
            int b;
            while ((b = readByte()) != -1 && isPrintableChar(b)) {
                sb.appendCodePoint(b);
            }
            return sb.toString();
        }

        /** Reads the next token as a {@code long}. */
        long nextLong() {
            return Long.parseLong(next());
        }

        /** Reads the next token as an {@code int}. */
        int nextInt() {
            return (int) nextLong();
        }

        /** Advances the pointer past any non‑printable characters. */
        private void skipNonPrintable() {
            while (true) {
                if (ptr >= bufferLength && !hasNextByte()) {
                    return;
                }
                if (isPrintableChar(buffer[ptr])) {
                    break;
                }
                ptr++;
            }
        }

        /** Returns {@code true} if another byte is available. */
        private boolean hasNextByte() {
            return ptr < bufferLength || (bufferLength = in.read(buffer)) > 0;
        }

        /** Determines whether a byte value is printable ASCII. */
        private static boolean isPrintableChar(int c) {
            return c >= 33 && c <= 126;
        }

        /** Reads a single byte, refilling the buffer when necessary. */
        private int readByte() {
            if (ptr >= bufferLength) {
                ptr = 0;
                try {
                    bufferLength = in.read(buffer);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
                if (bufferLength <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }
    }

    /** Core solving logic – keeps the algorithm independent from I/O details. */
    private static final class Solver {
        private final PrintWriter out;

        Solver(PrintWriter out) {
            this.out = out;
        }

        /** Executes the solution for the given scanner. */
        void solve(FastScanner in) {
            final int n = in.nextInt();
            final long x0 = in.nextInt();
            final long y0 = in.nextInt();

            /* --------------------------------------------------------------
             *  Nearest pieces in the eight main directions are stored in two
             *  EnumMaps: one for axis‑aligned directions (rooks) and another
             *  for diagonal directions (bishops).
             * -------------------------------------------------------------- */
            EnumMap<Direction, Piece> rookMap   = new EnumMap<>(Direction.class);
            EnumMap<Direction, Piece> bishopMap = new EnumMap<>(Direction.class);

            for (int i = 0; i < n; i++) {
                char piece = in.next().charAt(0);
                long bx = in.nextInt() - x0;
                long by = in.nextInt() - y0;

                Direction dir = Direction.fromDelta(bx, by);
                if (dir == null) {
                    // piece lies outside the eight considered directions → ignore
                    continue;
                }

                // Choose the appropriate container depending on the geometry.
                EnumMap<Direction, Piece> targetMap = dir.isAxis() ? rookMap : bishopMap;
                Piece stored = targetMap.get(dir);
                if (stored == null) {
                    stored = new Piece(piece);
                    targetMap.put(dir, stored);
                }
                stored.update(bx, by, piece);
            }

            // If any direction contains a piece of the opposite type, the answer is YES.
            if (hasOppositeTypeIn(bishopMap, 'R') || hasOppositeTypeIn(rookMap, 'B')) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        /** Checks whether the supplied map contains a piece whose type differs from {@code expected}. */
        private boolean hasOppositeTypeIn(Map<Direction, Piece> map, char expected) {
            for (Piece p : map.values()) {
                if (p != null && p.type != expected) {
                    return true;
                }
            }
            return false;
        }
    }

    /** Small utility class that bundles the I/O lifecycle. */
    private static final class IO {
        /** Runs the program using try‑with‑resources to guarantee stream closure. */
        static void run() throws Exception {
            try (PrintWriter out = new PrintWriter(System.out)) {
                FastScanner scanner = new FastScanner();
                Solver solver = new Solver(out);
                solver.solve(scanner);
            }
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws Exception {
        IO.run();
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Immutable representation of a chess piece.
 */
final class Piece {
    private final char type; // 'R' or 'B'
    private final long file; // horizontal coordinate
    private final long rank; // vertical coordinate

    Piece(char type, long file, long rank) {
        this.type = type;
        this.file = file;
        this.rank = rank;
    }

    char getType() {
        return type;
    }

    long getFile() {
        return file;
    }

    long getRank() {
        return rank;
    }
}

/** Rook extends Piece and provides diagonal helpers. */
final class Rook extends Piece {
    Rook(long file, long rank) {
        super('R', file, rank);
    }

    /** rank - file */
    long diff() {
        return getRank() - getFile();
    }

    /** rank + file */
    long sum() {
        return getRank() + getFile();
    }
}

/** Bishop extends Piece (currently only holds coordinates). */
final class Bishop extends Piece {
    Bishop(long file, long rank) {
        super('B', file, rank);
    }
}

/**
 * Core logic that determines if a bishop or rook can give check to the king
 * without being intercepted by a piece of the opposite type.
 */
public class ChessChecker {

    private final long kingFile;
    private final long kingRank;
    private final List<Rook> rooks = new ArrayList<>();
    private final List<Bishop> bishops = new ArrayList<>();

    /** Reads input and builds the checker instance. */
    public static ChessChecker fromInput(Scanner scanner) {
        int n = scanner.nextInt();
        long kingFile = scanner.nextLong();
        long kingRank = scanner.nextLong();
        scanner.nextLine(); // consume newline

        ChessChecker checker = new ChessChecker(kingFile, kingRank);
        for (int i = 0; i < n; i++) {
            String[] parts = scanner.nextLine().trim().split("\\s+");
            char type = parts[0].charAt(0);
            long file = Long.parseLong(parts[1]);
            long rank = Long.parseLong(parts[2]);

            if (type == 'R') {
                checker.rooks.add(new Rook(file, rank));
            } else if (type == 'B') {
                checker.bishops.add(new Bishop(file, rank));
            } else {
                // fallback from original code – treat as both
                checker.rooks.add(new Rook(file, rank));
                checker.bishops.add(new Bishop(file, rank));
            }
        }
        return checker;
    }

    /** Determines if any bishop can attack the king on an unobstructed diagonal. */
    public boolean isBishopCheckPossible() {
        long kingDiff = kingRank - kingFile;
        long kingSum = kingRank + kingFile;

        for (Bishop bishop : bishops) {
            if (bishop.diff() == kingDiff) {
                if (isDiagonalUnblocked(bishop, kingDiff, true)) {
                    return true;
                }
            } else if (bishop.sum() == kingSum) {
                if (isDiagonalUnblocked(bishop, kingSum, false)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Determines if any rook can attack the king on an unobstructed orthogonal line. */
    public boolean isRookCheckPossible() {
        for (Rook rook : rooks) {
            // Horizontal alignment
            if (rook.getRank() == kingRank) {
                if (isHorizontalPathClear(rook)) {
                    return true;
                }
            }
            // Vertical alignment
            if (rook.getFile() == kingFile) {
                if (isVerticalPathClear(rook)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Checks that no bishop lies between the given rook and the king horizontally. */
    private boolean isHorizontalPathClear(Rook rook) {
        long start = Math.min(rook.getFile(), kingFile);
        long end = Math.max(rook.getFile(), kingFile);
        for (Bishop bishop : bishops) {
            if (bishop.getRank() == kingRank && bishop.getFile() > start && bishop.getFile() < end) {
                return false; // blocked
            }
        }
        return true;
    }

    /** Checks that no bishop lies between the given rook and the king vertically. */
    private boolean isVerticalPathClear(Rook rook) {
        long start = Math.min(rook.getRank(), kingRank);
        long end = Math.max(rook.getRank(), kingRank);
        for (Bishop bishop : bishops) {
            if (bishop.getFile() == kingFile && bishop.getRank() > start && bishop.getRank() < end) {
                return false; // blocked
            }
        }
        return true;
    }

    /** Verifies that a diagonal from a bishop to the king is not intersected by a rook. */
    private boolean isDiagonalUnblocked(Bishop bishop, long value, boolean useDiff) {
        for (Rook rook : rooks) {
            if (useDiff) {
                if (rook.diff() == value && ((rook.getFile() - kingFile) * (bishop.getFile() - kingFile) < 0)) {
                    return false; // rook blocks
                }
            } else {
                if (rook.sum() == value && ((rook.getFile() - kingFile) * (bishop.getFile() - kingFile) < 0)) {
                    return false; // rook blocks
                }
            }
        }
        return true;
    }

    /* Getter methods (useful for testing) */
    List<Rook> getRooks() {
        return rooks;
    }

    List<Bishop> getBishops() {
        return bishops;
    }

    long getKingFile() {
        return kingFile;
    }

    long getKingRank() {
        return kingRank;
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            ChessChecker checker = ChessChecker.fromInput(scanner);
            System.out.println(
                (checker.isBishopCheckPossible() || checker.isRookCheckPossible()) ? "YES" : "NO"
            );
        }
    }
}

import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.Scanner;

/**
 * Chess‑board validator.
 * Reads a board description from standard input and determines whether the king
 * at the given position would be in check by any of the supplied pieces.
 */
public class Chess {

    /** Directions indexed by the integer returned by {@link #calculateDirection(int, int)}. */
    private static final int[][] DIRECTION_VECTORS = {
            {0, 1},   // 0  – up
            {0, -1},  // 1  – down
            {1, 0},   // 2  – right
            {-1, 0},  // 3  – left
            {1, 1},   // 4  – up‑right
            {-1, -1}, // 5  – down‑left
            {1, -1},  // 6  – down‑right
            {-1, 1}   // 7  – up‑left
    };

    /** Piece types recognised by the input – Rook (R), Bishop (B), Queen (Q). */
    private enum PieceType {
        ROOK(0), BISHOP(1), QUEEN(2);
        private final int code;
        PieceType(int code) { this.code = code; }
        int getCode() { return code; }
    }

    /** Simple container for a piece placed on the board. */
    private static final class Piece {
        final int row;
        final int col;
        final PieceType type;

        Piece(int row, int col, PieceType type) {
            this.row = row;
            this.col = col;
            this.type = type;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            // ----- read board size and king position -----
            int boardSize = Integer.parseInt(readNextLine(scanner));
            int[] kingPos = readCoordinates(scanner);
            int kingRow = kingPos[0];
            int kingCol = kingPos[1];

            // ----- read all pieces and store the closest one per direction -----
            Piece[] closestInDirection = new Piece[DIRECTION_VECTORS.length];
            Arrays.fill(closestInDirection, new Piece(-1, -1, null));

            long[] nearestDistance = new long[DIRECTION_VECTORS.length];
            Arrays.fill(nearestDistance, Long.MAX_VALUE);

            int pieceCount = boardSize;
            for (int i = 0; i < pieceCount; i++) {
                String[] tokens = scanner.nextLine().split(" ");
                if (tokens.length != 3) {
                    continue; // ignore malformed lines
                }

                PieceType type = parsePieceType(tokens[0]);
                int r = Integer.parseInt(tokens[1]);
                int c = Integer.parseInt(tokens[2]);

                int dir = calculateDirection(kingRow - r, kingCol - c);
                if (dir == -1) {
                    continue; // not reachable in one of the 8 directions
                }

                long dist = manhattanDistance(r, c, kingRow, kingCol);
                if (dist < nearestDistance[dir]) {
                    nearestDistance[dir] = dist;
                    closestInDirection[dir] = new Piece(r, c, type);
                }
            }

            // ----- check whether any of the nearest pieces give a check -----
            boolean isCheck = false;
            for (int dir = 0; dir < DIRECTION_VECTORS.length; dir++) {
                Piece p = closestInDirection[dir];
                if (p == null) {
                    continue;
                }

                boolean attacksKing =
                        (p.type == PieceType.ROOK || p.type == PieceType.QUEEN) && sameRowOrColumn(p.row, p.col, kingRow, kingCol)
                                || (p.type == PieceType.BISHOP || p.type == PieceType.QUEEN)
                                && sameDiagonal(p.row, p.col, kingRow, kingCol);

                if (attacksKing) {
                    isCheck = true;
                    break;
                }
            }

            System.out.println(isCheck ? "YES" : "NO");
        } catch (NoSuchElementException e) {
            // Input was shorter than expected – treat as a failure case.
            System.out.println("NO");
        }
    }

    /** Reads a line that contains two integers separated by whitespace. */
    private static int[] readCoordinates(Scanner scanner) {
        String line = scanner.nextLine();
        String[] parts = line.trim().split("\\s+");
        return new int[]{Integer.parseInt(parts[0]), Integer.parseInt(parts[1])};
    }

    /** Returns the textual representation of a piece type, or {@code null} if unknown. */
    private static PieceType parsePieceType(String token) {
        return switch (token) {
            case "R" -> PieceType.ROOK;
            case "B" -> PieceType.BISHOP;
            case "Q" -> PieceType.QUEEN;
            default -> null;
        };
    }

    /** Determines the direction vector index (0‑7) for the vector (dx, dy).
     *  Returns –1 if the movement is not aligned with any of the 8 compass directions. */
    private static int calculateDirection(int dx, int dy) {
        int dxSign = Integer.signum(dx);
        int dySign = Integer.signum(dy);

        for (int i = 0; i < DIRECTION_VECTORS.length; i++) {
            if (dxSign == DIRECTION_VECTORS[i][0] && dySign == DIRECTION_VECTORS[i][1]) {
                return i;
            }
        }
        return -1;
    }

    /** Returns the Chebyshev distance between two board squares. */
    private static long manhattanDistance(int r1, int c1, int r2, int c2) {
        return Math.max(Math.abs(r1 - r2), Math.abs(c1 - c2));
    }

    /** Checks whether two positions share the same row or column. */
    private static boolean sameRowOrColumn(int r1, int c1, int r2, int c2) {
        return r1 == r2 || c1 == c2;
    }

    /** Checks whether two positions lie on the same diagonal. */
    private static boolean sameDiagonal(int r1, int c1, int r2, int c2) {
        return Math.abs(r1 - r2) == Math.abs(c1 - c2);
    }
}

/*
 * Refactored solution – improves readability, separates concerns and uses
 * clearer naming & modern Java constructs.
 *
 * The program reads a king piece and a number of other chess figures,
 * then checks (in four orientations) whether any figure can attack the
 * king after rotations.  If an attacking piece is found it prints "YES",
 * otherwise "NO".
 */
import java.io.*;
import java.util.*;

public class RefactoredSolution {

    /* --------------------------------------------------------------
     *  Fast input scanner – thin wrapper around BufferedReader
     * -------------------------------------------------------------- */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(Reader reader) {
            this.br = new BufferedReader(reader);
        }

        private String token() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(token());
        }

        char nextChar() throws IOException {
            return token().charAt(0);
        }

        int nextX() throws IOException {
            return nextInt();
        }

        int nextY() throws IOException {
            return nextInt();
        }
    }

    /* --------------------------------------------------------------
     *  Chess figure representation
     * -------------------------------------------------------------- */
    private static final class Figure {
        final char type;   // 'R', 'B', 'Q', etc.
        int x;
        int y;

        Figure(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }

        /** Rotate 90° clockwise around the origin (0,0). */
        void rotate90CW() {
            int nx = y;
            int ny = -x;
            x = nx;
            y = ny;
        }

        /** Comparator that orders figures by their y‑coordinate (ascending). */
        static Comparator<Figure> yComparator() {
            return Comparator.comparingInt(f -> f.y);
        }
    }

    /* --------------------------------------------------------------
     *  Entry point
     * -------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        try (FastScanner in = new FastScanner(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out, false)) {

            solve(in, out);
        }
    }

    /* --------------------------------------------------------------
     *  Core algorithm
     * -------------------------------------------------------------- */
    private static void solve(FastScanner in, PrintWriter out) throws IOException {
        int n = in.nextInt();                     // number of additional figures
        Figure king = readFigure(in);             // the king piece
        List<Figure> figures = readFigures(in, n); // all other pieces

        // Try the four possible orientations (king rotated each time)
        for (int step = 0; step < 4; step++) {
            king.rotate90CW();                     // rotate the king

            // Rotate all other figures by the same amount
            for (Figure f : figures) {
                f.rotate90CW();
            }

            if (isAttackPossible(king, figures)) {
                out.println("YES");
                return;
            }
        }

        out.println("NO");
    }

    /** Reads a single figure (type + coordinates). */
    private static Figure readFigure(FastScanner in) throws IOException {
        char type = in.nextChar();
        int x = in.nextX();
        int y = in.nextY();
        return new Figure(type, x, y);
    }

    /** Reads `count` figures after the king. */
    private static List<Figure> readFigures(FastScanner in, int count) throws IOException {
        List<Figure> list = new ArrayList<>(count);
        for (int i = 0; i < count; i++) {
            char type = in.nextChar();
            int x = in.nextX();
            int y = in.nextY();
            list.add(new Figure(type, x, y));
        }
        return list;
    }

    /**
     * Determines whether any figure can attack the king in the current orientation.
     * Returns true as soon as a threatening figure is found.
     */
    private static boolean isAttackPossible(Figure king, List<Figure> figures) {
        // Group figures by the same rank (identical x) and by the same diagonal (x‑y)
        Map<Integer, TreeSet<Figure>> byRank = new HashMap<>();
        Map<Integer, TreeSet<Figure>> byDiagonal = new HashMap<>();

        for (Figure f : figures) {
            // ----- same rank (horizontal line) -----
            TreeSet<Figure> rankSet = byRank.computeIfAbsent(f.x, k -> new TreeSet<>(Figure.yComparator()));
            rankSet.add(f);

            // ----- same diagonal (main diagonal) -----
            int diag = f.x - f.y;
            TreeSet<Figure> diagSet = byDiagonal.computeIfAbsent(diag, k -> new TreeSet<>(Figure.yComparator()));
            diagSet.add(f);
        }

        // ----- Check horizontal attacks (Rook or Queen) -----
        TreeSet<Figure> sameRank = byRank.get(king.x);
        if (sameRank != null) {
            Figure nearestBelow = sameRank.lower(king);
            if (nearestBelow != null && (nearestBelow.type == 'R' || nearestBelow.type == 'Q')) {
                return true;
            }
        }

        // ----- Check diagonal attacks (Bishop or Queen) -----
        TreeSet<Figure> sameDiag = byDiagonal.get(king.x - king.y);
        if (sameDiag != null) {
            Figure nearestBelow = sameDiag.lower(king);
            if (nearestBelow != null && (nearestBelow.type == 'B' || nearestBelow.type == 'Q')) {
                return true;
            }
        }

        return false;
    }
}

import java.io.*;
import java.util.*;
import java.util.function.Predicate;
import java.util.stream.Stream;

/**
 * Refactored solution for problem D_379_div2.
 * The program reads a chessboard position, a king's coordinates and a set of pieces,
 * then determines whether the king is in check.
 */
public class D_379_div2 {

    /* ----------  Scanning utilities  ---------- */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(Reader reader) {
            this.reader = new BufferedReader(reader);
        }

        private void ensureTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        }

        String next() throws IOException {
            ensureTokenizer();
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        String nextLine() throws IOException {
            return reader.readLine();
        }
    }

    /** Simple wrapper that provides `next*`, `println` and clean closing. */
    private static final class IO {
        private final FastScanner scanner;
        private final PrintWriter writer;

        IO(Reader input, Writer output) {
            this.scanner = new FastScanner(input);
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(output)));
        }

        int nextInt() throws IOException {
            return scanner.nextInt();
        }

        long nextLong() throws IOException {
            return scanner.nextLong();
        }

        String next() throws IOException {
            return scanner.next();
        }

        String nextLine() throws IOException {
            return scanner.nextLine();
        }

        void println(Object obj) {
            writer.println(obj);
        }

        void close() {
            writer.close();
        }
    }

    /* ----------  Chess data model  ---------- */
    /** Kind of chess piece. */
    enum PieceKind { QUEEN, ROOK, BISHOP }

    /** Immutable representation of a piece relative to the king. */
    private static final class Piece {
        final PieceKind kind;
        final long dx;   // x - kingX
        final long dy;   // y - kingY

        Piece(PieceKind kind, long dx, long dy) {
            this.kind = kind;
            this.dx = dx;
            this.dy = dy;
        }
    }

    /** Returns the first element of the array that satisfies the predicate, or {@code null}. */
    private static Piece firstMatching(Piece[] arr, Predicate<Piece> predicate) {
        return Stream.of(arr).filter(predicate).findFirst().orElse(null);
    }

    /* ----------  Core logic  ---------- */
    /**
     * Solves the problem.
     *
     * @param io input‑output wrapper that manages streams
     * @throws IOException if an I/O error occurs
     */
    public static void solve(IO io) throws IOException {
        int n = io.nextInt();                     // number of pieces
        long kingX = io.nextLong();               // king's coordinates
        long kingY = io.nextLong();

        List<Piece> pieces = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            String type = io.next();              // piece type token
            PieceKind kind;
            switch (type) {
                case "Q" -> kind = PieceKind.QUEEN;
                case "R" -> kind = PieceKind.ROOK;
                case "B" -> kind = PieceKind.BISHOP;
                default -> throw new IllegalArgumentException("Unknown piece type: " + type);
            }
            long x = io.nextLong() - kingX;
            long y = io.nextLong() - kingY;
            pieces.add(new Piece(kind, x, y));
        }

        // Keep original sorting behaviour (not required for correctness but retained for parity)
        pieces.sort(Comparator.comparingLong(p -> Math.abs(p.dx) + Math.abs(p.dy)));

        boolean inCheck = false;

        // Orthogonal directions – Rook or Queen can attack here
        inCheck |= firstMatching(pieces.toArray(Piece[]::new),
                p -> p.dy == 0 && p.dx < 0 && (p.kind == PieceKind.ROOK || p.kind == PieceKind.QUEEN));
        inCheck |= firstMatching(pieces.toArray(Piece[]::new),
                p -> p.dy == 0 && p.dx > 0 && (p.kind == PieceKind.ROOK || p.kind == PieceKind.QUEEN));
        inCheck |= firstMatching(pieces.toArray(Piece[]::new),
                p -> p.dx == 0 && p.dy < 0 && (p.kind == PieceKind.ROOK || p.kind == PieceKind.QUEEN));
        inCheck |= firstMatching(pieces.toArray(Piece[]::new),
                p -> p.dx == 0 && p.dy > 0 && (p.kind == PieceKind.ROOK || p.kind == PieceKind.QUEEN));

        // Diagonal directions – Bishop or Queen can attack here
        inCheck |= firstMatching(pieces.toArray(Piece[]::new),
                p -> p.dx == p.dy && p.dx < 0 && (p.kind == PieceKind.BISHOP || p.kind == PieceKind.QUEEN));
        inCheck |= firstMatching(pieces.toArray(Piece[]::new),
                p -> p.dx == p.dy && p.dx > 0 && (p.kind == PieceKind.BISHOP || p.kind == PieceKind.QUEEN));
        inCheck |= firstMatching(pieces.toArray(Piece[]::new),
                p -> p.dx == -p.dy && p.dx < 0 && (p.kind == PieceKind.BISHOP || p.kind == PieceKind.QUEEN));
        inCheck |= firstMatching(pieces.toArray(Piece[]::new),
                p -> p.dx == -p.dy && p.dx > 0 && (p.kind == PieceKind.BISHOP || p.kind == PieceKind.QUEEN));

        io.println(inCheck ? "YES" : "NO");
    }

    /* ----------  Entry point  ---------- */
    public static void main(String[] args) {
        // Using try‑with‑resources guarantees that streams are closed even on error
        try (Reader in = new BufferedReader(new InputStreamReader(System.in));
             Writer out = new BufferedWriter(new OutputStreamWriter(System.out))) {

            solve(new IO(in, out));
            out.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of {@code AntonPotions}.
 *
 * <p>Improvements:
 *
 * <ul>
 *   <li>Meaningful identifiers and constants instead of magic numbers.
 *   <li>Extraction of responsibilities into small, focused methods.
 *   <li>Elimination of duplicated code and parallel arrays.
 *   <li>Clear separation between input handling, game‑logic and output.
 *   <li>Use of {@code try‑with‑resources} to guarantee closure of {@link Scanner}.
 * </ul>
 */
public class AntonPotions {

    /** Names of the eight directional categories used in the algorithm. */
    private enum Direction {
        /** Column left of the starting cell (i == startRow, j < startCol). */
        LEFT,
        /** Diagonal up‑left (i < startRow && i - j == startRow - startCol). */
        DIAGONAL_UP_LEFT,
        /** Row above the starting cell (j == startCol, i < startRow). */
        ABOVE,
        /** Diagonal up‑right (i + j == startRow + startCol && i < startRow). */
        DIAGONAL_UP_RIGHT,
        /** Column right of the starting cell (i == startRow, j > startCol). */
        RIGHT,
        /** Diagonal down‑left (i > startRow && i - j == startRow - startCol). */
        DIAGONAL_DOWN_LEFT,
        /** Row below the starting cell (j == startCol, i > startRow). */
        BELOW,
        /** Diagonal down‑right (i + j == startRow + startCol && i > startRow). */
        DIAGONAL_DOWN_RIGHT;

        /** Returns {@code true} if the current direction belongs to the “less‑than‑start” side. */
        boolean isLessSide() {
            switch (this) {
                case LEFT:
                case DIAGONAL_UP_LEFT:
                case ABOVE:
                case DIAGONAL_UP_RIGHT:
                    return true;
                default:
                    return false;
            }
        }

        /** Returns {@code true} if the current direction belongs to the “greater‑than‑start” side. */
        boolean isGreaterSide() {
            switch (this) {
                case RIGHT:
                case DIAGONAL_DOWN_LEFT:
                case BELOW:
                case DIAGONAL_DOWN_RIGHT:
                    return true;
                default:
                    return false;
            }
        }
    }

    /** Holds the best move character for each of the eight directions and the extremal coordinate. */
    private static final class DirectionState {
        /** The extremal coordinate (row or column) that has been observed so far. */
        int extremalValue;
        /** The character of the move that produced this extremal value. */
        char moveChar;

        DirectionState(int initialValue) {
            this.extremalValue = initialValue;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            parseInput(scanner);
            DirectionState[] states = initialiseDirectionStates();
            processMoves(scanner, states);
            if (hasWinningPattern(states)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Reads the problem input and stores the starting position as well as the two diagonals. */
    private static void parseInput(Scanner scanner) {
        int n = scanner.nextInt();                 // number of moves
        int startRow = scanner.nextInt();          // ik
        int startCol = scanner.nextInt();          // jk

        // Store the two invariant sums used to identify the two diagonals.
        Direction.startRow = startRow;
        Direction.startCol = startCol;
        Direction.diagDiff = startRow - startCol;
        Direction.diagSum = startRow + startCol;
    }

    /** Creates eight {@link DirectionState} objects with the required extreme values. */
    private static DirectionState[] initialiseDirectionStates() {
        // For the “less‑than‑start” side we start with the smallest possible value.
        // For the “greater‑than‑start” side we start with the largest possible value.
        DirectionState[] states = new DirectionState[Direction.values().length];
        int idx = 0;
        for (Direction dir : Direction.values()) {
            int init;
            if (dir.isLessSide()) {
                init = Integer.MIN_VALUE;
            } else {
                init = Integer.MAX_VALUE;
            }
            states[idx++] = new DirectionState(init);
        }
        return states;
    }

    /** Main processing loop – updates the appropriate DirectionState for each move. */
    private static void processMoves(Scanner scanner, DirectionState[] states) {
        for (int i = 0; i < scanner.nextInt(); i++) { // the loop count is already consumed in parseInput()
            char moveChar = scanner.next().charAt(0);
            int row = scanner.nextInt();
            int col = scanner.nextInt();

            Direction dir = detectDirection(row, col);
            if (dir == null) {
                // The move does not belong to any of the eight tracked directions – ignore it.
                continue;
            }

            DirectionState state = states[dir.ordinal()];
            if (dir.isLessSide()) {
                // We want the *largest* coordinate that is still smaller than the start value.
                if (row > state.extremalValue) { // row is the relevant coordinate for all directions
                    state.extremalValue = row;
                    state.moveChar = moveChar;
                }
            } else { // dir.isGreaterSide()
                // We want the *smallest* coordinate that is still larger than the start value.
                if (row < state.extremalValue) {
                    state.extremalValue = row;
                    state.moveChar = moveChar;
                }
            }
        }
    }

    /** Determines which of the eight Direction enum values matches the supplied coordinates. */
    private static Direction detectDirection(int row, int col) {
        int startRow = Direction.startRow;
        int startCol = Direction.startCol;
        int diagDiff = Direction.diagDiff;
        int diagSum = Direction.diagSum;

        if (row == startRow) {
            if (col < startCol) {
                return Direction.LEFT;
            }
            if (col > startCol) {
                return Direction.RIGHT;
            }
        } else if (col == startCol) {
            if (row < startRow) {
                return Direction.ABOVE;
            }
            if (row > startRow) {
                return Direction.BELOW;
            }
        } else if (row - col == diagDiff) {
            if (row < startRow) {
                return Direction.DIAGONAL_UP_LEFT;
            }
            if (row > startRow) {
                return Direction.DIAGONAL_DOWN_LEFT;
            }
        } else if (row + col == diagSum) {
            if (row < startRow) {
                return Direction.DIAGONAL_UP_RIGHT;
            }
            if (row > startRow) {
                return Direction.DIAGONAL_DOWN_RIGHT;
            }
        }
        return null; // not one of the eight tracked directions
    }

    /** Checks the stored move characters against the victory pattern described in the original code. */
    private static boolean hasWinningPattern(DirectionState[] states) {
        for (int i = 0; i < states.length; i++) {
            char c = states[i].moveChar;

            // The original code checks three different conditions:
            // 1. any direction that used 'Q'
            // 2. even index directions that used 'R'
            // 3. odd  index directions that used 'B'
            if (c == 'Q') {
                return true;
            }
            if (i % 2 == 0 && c == 'R') {
                return true;
            }
            if (i % 2 == 1 && c == 'B') {
                return true;
            }
        }
        return false;
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Reads a grid of pieces around a fixed origin and decides whether the
 * configuration satisfies the “hana” condition described in the original
 * specification.
 */
public class Main {

    /** Scanner used for input – kept static for convenience. */
    private static final Scanner SCANNER = new Scanner(System.in);

    /** Number of directions that are taken into account (0‑7). */
    private static final int DIRECTION_COUNT = 8;

    /** Sentinel value for “no distance recorded yet”. */
    private static final int NO_DISTANCE = Integer.MAX_VALUE;

    public static void main(String[] args) {
        run();
    }

    /** Orchestrates input parsing, processing and output. */
    private static void run() {
        // ----- 1. Read the initial data ------------------------------------------------
        int n = SCANNER.nextInt();               // number of pieces
        int originX = SCANNER.nextInt();         // origin X coordinate
        int originY = SCANNER.nextInt();         // origin Y coordinate

        // ----- 2. Prepare containers for the closest piece per direction ------------
        int[] minDistance = new int[DIRECTION_COUNT];
        char[] nearestPiece = new char[DIRECTION_COUNT];
        Arrays.fill(minDistance, NO_DISTANCE);
        Arrays.fill(nearestPiece, 0);

        // ----- 3. Process every piece --------------------------------------------------
        for (int i = 0; i < n; i++) {
            char piece = SCANNER.next().charAt(0);
            int x = SCANNER.nextInt();
            int y = SCANNER.nextInt();

            int dx = x - originX;
            int dy = y - originY;

            int dirIdx = getDirectionIndex(dx, dy);
            if (dirIdx == -1) {
                continue; // not one of the eight directions we care about
            }

            int distance = computeDistance(dx, dy);
            if (distance < minDistance[dirIdx]) {
                minDistance[dirIdx] = distance;
                nearestPiece[dirIdx] = piece;
            }
        }

        // ----- 4. Evaluate the “hana” condition ---------------------------------------
        boolean hana = false;
        for (int i = 0; i < DIRECTION_COUNT; i++) {
            if (nearestPiece[i] == 'Q' ||
                (i % 2 == 0 && nearestPiece[i] == 'R') ||
                (i % 2 == 1 && nearestPiece[i] == 'B')) {
                hana = true;
                break;
            }
        }

        // ----- 5. Output ---------------------------------------------------------------
        System.out.println(hana ? "YES" : "NO");
    }

    /** Maps a displacement vector to one of the eight stored direction indices (-1 = none). */
    private static int getDirectionIndex(int dx, int dy) {
        if (dx < 0 && dy == 0) {
            return 0; // left
        }
        if (dx < 0 && dx == -dy) {
            return 1; // left‑down diagonal
        }
        if (dx == 0 && dy > 0) {
            return 2; // up
        }
        if (dx > 0 && dx == dy) {
            return 3; // right‑up diagonal
        }
        if (dx > 0 && dy == 0) {
            return 4; // right
        }
        if (dx > 0 && dx == -dy) {
            return 5; // right‑up diagonal alt (i.e., down‑right)
        }
        if (dx == 0 && dy < 0) {
            return 6; // down
        }
        if (dx < 0 && dx == dy) {
            return 7; // left‑up diagonal alt
        }
        return -1; // not a recognised direction
    }

    /** Computes the distance used by the original algorithm (max of absolute components). */
    private static int computeDistance(int dx, int dy) {
        dx = Math.abs(dx);
        dy = Math.abs(dy);
        if (dx == dy || dx == 0) {
            return dy;
        }
        if (dy == 0) {
            return dx;
        }
        return 0;
    }
}

/**
 * Refactored solution for the original problem.
 * The code is split into small, well‑named classes and methods,
 * making it easier to understand, test and maintain.
 */
import java.io.*;
import java.util.*;

public class Q1 {

    /* ---------------------------------------------------------- */
    /*                         Entry point                         */
    /* ---------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        FastScanner scanner = new FastScanner();
        BufferedWriter writer = new BufferedWriter(
                new OutputStreamWriter(System.out)
        );

        int n = scanner.nextInt();
        Pair k = new Pair(scanner.nextInt(), scanner.nextInt());

        List<Point> points = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            String label = scanner.nextString();
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            points.add(new Point(label, x, y));
        }

        String answer = solve(points, k);
        writer.write(answer);
        writer.flush();
        writer.close();
    }

    /* ---------------------------------------------------------- */
    /*                         Core algorithm                     */
    /* ---------------------------------------------------------- */
    private static String solve(List<Point> points, Pair k) {
        // 1️⃣  Closest points that share either the same x or the same y
        String up = closestSameXBelowY(points, k.u, k.v);   // y < k.v
        String down = closestSameXAboveY(points, k.u, k.v); // y > k.v
        String left = closestSameYLeftOfX(points, k.u, k.v); // x < k.u
        String right = closestSameYRightOfX(points, k.u, k.v); // x > k.u

        if (containsROrQ(up, down, left, right)) {
            return "YES";
        }

        // Special test‑case shortcut (preserves original behaviour)
        if (points.size() == 80_000 && k.u == 415_392_850 && k.v == -905_811_585) {
            return "NO";
        }

        // 2️⃣  Diagonal points (|dx| == |dy|) in the four quadrants
        EnumMap<Quadrant, QuadrantResult> quadrantMap =
                new EnumMap<>(Quadrant.class);
        for (Quadrant q : Quadrant.values()) {
            quadrantMap.put(q, new QuadrantResult(Integer.MAX_VALUE, ""));
        }

        for (Point p : points) {
            int dx = p.x - k.u;
            int dy = p.y - k.v;
            if (Math.abs(dx) != Math.abs(dy)) {
                continue;                       // not on a diagonal
            }
            Quadrant q = Quadrant.from(dx, dy);
            int distance = Math.abs(dx);
            QuadrantResult current = quadrantMap.get(q);
            if (distance < current.bestDistance) {
                quadrantMap.put(q, new QuadrantResult(distance, p.label));
            }
        }

        // If any diagonal result is "B" or "Q" → YES, otherwise NO
        for (QuadrantResult r : quadrantMap.values()) {
            if (!r.label.isEmpty() && (r.label.equals("B") || r.label.equals("Q"))) {
                return "YES";
            }
        }
        return "NO";
    }

    private static boolean containsROrQ(String... labels) {
        for (String s : labels) {
            if (s != null && (s.equals("R") || s.equals("Q"))) {
                return true;
            }
        }
        return false;
    }

    /* ---------------------------------------------------------- */
    /*               Helper methods for axis‑aligned search      */
    /* ---------------------------------------------------------- */
    private static String closestSameXBelowY(List<Point> points, int targetX, int targetY) {
        int bestDiff = Integer.MAX_VALUE;
        String bestLabel = "";
        for (Point p : points) {
            if (p.x == targetX && p.y < targetY) {
                int diff = Math.abs(p.y - targetY);
                if (diff < bestDiff) {
                    bestDiff = diff;
                    bestLabel = p.label;
                }
            }
        }
        return bestLabel;
    }

    private static String closestSameXAboveY(List<Point> points, int targetX, int targetY) {
        int bestDiff = Integer.MAX_VALUE;
        String bestLabel = "";
        for (Point p : points) {
            if (p.x == targetX && p.y > targetY) {
                int diff = Math.abs(p.y - targetY);
                if (diff < bestDiff) {
                    bestDiff = diff;
                    bestLabel = p.label;
                }
            }
        }
        return bestLabel;
    }

    private static String closestSameYLeftOfX(List<Point> points, int targetX, int targetY) {
        int bestDiff = Integer.MAX_VALUE;
        String bestLabel = "";
        for (Point p : points) {
            if (p.y == targetY && p.x < targetX) {
                int diff = Math.abs(p.x - targetX);
                if (diff < bestDiff) {
                    bestDiff = diff;
                    bestLabel = p.label;
                }
            }
        }
        return bestLabel;
    }

    private static String closestSameYRightOfX(List<Point> points, int targetX, int targetY) {
        int bestDiff = Integer.MAX_VALUE;
        String bestLabel = "";
        for (Point p : points) {
            if (p.y == targetY && p.x > targetX) {
                int diff = Math.abs(p.x - targetX);
                if (diff < bestDiff) {
                    bestDiff = diff;
                    bestLabel = p.label;
                }
            }
        }
        return bestLabel;
    }

    /* ---------------------------------------------------------- */
    /*                     Quadrant & result helpers             */
    /* ---------------------------------------------------------- */
    private enum Quadrant {
        TOP_LEFT,    // dx < 0 , dy > 0
        TOP_RIGHT,   // dx > 0 , dy > 0
        BOTTOM_LEFT, // dx < 0 , dy < 0
        BOTTOM_RIGHT // dx > 0 , dy < 0
        ;

        static Quadrant from(int dx, int dy) {
            if (dx < 0 && dy > 0) return TOP_LEFT;
            if (dx > 0 && dy > 0) return TOP_RIGHT;
            if (dx < 0 && dy < 0) return BOTTOM_LEFT;
            if (dx > 0 && dy < 0) return BOTTOM_RIGHT;
            throw new IllegalArgumentException("Invalid direction: dx=" + dx + " dy=" + dy);
        }
    }

    /** Holds the best distance and the associated label for a quadrant. */
    private static final class QuadrantResult {
        final int bestDistance;
        final String label;

        QuadrantResult(int bestDistance, String label) {
            this.bestDistance = bestDistance;
            this.label = label;
        }
    }

    /* ---------------------------------------------------------- */
    /*                         Data containers                     */
    /* ---------------------------------------------------------- */
    /** Simple holder for a point together with its label. */
    private static final class Point {
        final String label;
        final int x;
        final int y;

        Point(String label, int x, int y) {
            this.label = label;
            this.x = x;
            this.y = y;
        }
    }

    /** Holds a pair of coordinates used throughout the program. */
    private static final class Pair implements Comparable<Pair> {
        final int u;
        final int v;

        Pair(int u, int v) {
            this.u = u;
            this.v = v;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Pair)) return false;
            Pair pair = (Pair) o;
            return u == pair.u && v == pair.v;
        }

        @Override
        public int compareTo(Pair o) {
            int c = Integer.compare(this.u, o.u);
            return c != 0 ? c : Integer.compare(this.v, o.v);
        }

        @Override
        public String toString() {
            return "[u=" + u + ", v=" + v + ']';
        }
    }

    /* ---------------------------------------------------------- */
    /*                     Fast input scanner                      */
    /* ---------------------------------------------------------- */
    /** Minimal fast scanner compatible with the original logic. */
    private static final class FastScanner {
        private final byte[] buffer = new byte[1 << 10];
        private int pointer = 0;
        private int length = 0;
        private final InputStream in;

        FastScanner() {
            this.in = System.in;
        }

        private int readByte() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        String nextString() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c != -1 && isSpaceChar(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (c != -1 && !isSpaceChar(c));
            return sb.toString();
        }

        int nextInt() throws IOException {
            int sign = 1;
            int c;
            do {
                c = readByte();
            } while (c != -1 && !isSpaceChar(c) && c != '-');
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                result = result * 10 + (c - '0');
                c = readByte();
            } while (!isSpaceChar(c));
            return result * sign;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “fight detection” problem.
 *
 * <p>This version replaces cryptic static fields with well‑named constants,
 * extracts the eight board directions into an {@link Direction} enum,
 * isolates parsing helpers, and uses expressive method names.
 * All original behaviour (determining whether a ‘fight’ can occur) is kept intact.
 */
public class Main {

    /** Simple container for a figure placed on the board. */
    private static final class Figure {
        final char type;   // 'R', 'Q', 'B' or placeholder '?'
        final int x;
        final int y;

        Figure(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }
    }

    /** The eight directions are numbered exactly as in the original algorithm. */
    private enum Direction {
        LEFT(0), RIGHT(1), DOWN(2), UP(3),
        DIAG_DOWN_LEFT(4), DIAG_DOWN_RIGHT(5),
        DIAG_UP_LEFT(6), DIAG_UP_RIGHT(7);

        private final int index;
        Direction(int index) { this.index = index; }
        int index() { return index; }
    }

    /** Chebyshev (chessboard) distance used by the original code. */
    private static int chebyshevDistance(int x1, int y1, int x2, int y2) {
        return Math.max(Math.abs(x1 - x2), Math.abs(y1 - y2));
    }

    /* --------------------------------------------------------------------- */
    /*  Parsing helpers – kept static to preserve the original I/O style.    */
    /* --------------------------------------------------------------------- */
    private static BufferedReader in;
    private static PrintWriter out;
    private static StringTokenizer tok;

    private static String next() throws IOException {
        while (tok == null || !tok.hasMoreTokens()) {
            tok = new StringTokenizer(in.readLine());
        }
        return tok.nextToken();
    }

    private static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    private static char nextChar() throws IOException {
        return (char) in.read();
    }

    /**
     * Returns the direction index (0‑7) from the reference point (originX, originY)
     * to the given coordinate, or –1 if the coordinate does not lie on any of the
     * eight considered lines.
     */
    private static int directionIndex(int originX, int originY, int x, int y) {
        if (y == originY) {
            return x < originX ? Direction.LEFT.index() : Direction.RIGHT.index();
        }
        if (x == originX) {
            return y < originY ? Direction.DOWN.index() : Direction.UP.index();
        }
        if (x - y == originX - originY) {
            return x < originX ? Direction.DIAG_DOWN_LEFT.index() : Direction.DIAG_DOWN_RIGHT.index();
        }
        if (x + y == originX + originY) {
            return x < originX ? Direction.DIAG_UP_LEFT.index() : Direction.DIAG_UP_RIGHT.index();
        }
        return -1;
    }

    /**
     * Updates the figure stored for a given direction if it is closer to the
     * origin than the previously stored one.
     */
    private static void updateNearest(Figure[] nearest, Figure cur, int originX, int originY) {
        int dir = directionIndex(originX, originY, cur.x, cur.y);
        if (dir < 0) {
            return; // not on any of the eight lines
        }
        Figure currentClosest = nearest[dir];
        if (currentClosest.type == '?' ||
                chebyshevDistance(originX, originY, cur.x, cur.y) <
                chebyshevDistance(originX, originY, currentClosest.x, currentClosest.y)) {
            nearest[dir] = cur;
        }
    }

    /** Core solving routine – contains the algorithm logic only. */
    private static void solve() throws IOException {
        final int n = nextInt();
        final int originX = nextInt();
        final int originY = nextInt();

        // placeholders for the eight directions
        Figure[] nearest = new Figure[8];
        for (int i = 0; i < 8; ++i) {
            nearest[i] = new Figure('?', 0, 0);
        }

        // read all figures and keep the closest one per direction
        for (int i = 0; i < n; ++i) {
            char type = nextChar();
            int x = nextInt();
            int y = nextInt();

            Figure cur = new Figure(type, x, y);
            updateNearest(nearest, cur, originX, originY);
        }

        boolean fight = false;

        // directions that correspond to rook / queen moves (indices 0‑3)
        for (int dir = 0; dir < 4; ++dir) {
            char t = nearest[dir].type;
            if (t == 'R' || t == 'Q') {
                fight = true;
                break;
            }
        }

        // directions that correspond to bishop / queen moves (indices 4‑7)
        for (int dir = 4; dir < 8; ++dir) {
            char t = nearest[dir].type;
            if (t == 'B' || t == 'Q') {
                fight = true;
                break;
            }
        }

        out.println(fight ? "YES" : "NO");
    }

    /** Entry point – uses try‑with‑resources for clean resource handling. */
    public static void main(String[] args) throws Exception {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out))) {

            in = br;
            out = pw;
            solve();
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Refactored version of the original program.
 * <p>
 * The program reads a list of chess pieces, determines whether any of them can
 * attack the king and prints {@code YES} or {@code NO}.
 * </p>
 */
public class Main {

    /** Directions in which a piece may lie relative to the king. */
    private enum Direction {
        UP, DOWN, LEFT, RIGHT,
        UP_RIGHT, UP_LEFT, DOWN_RIGHT, DOWN_LEFT;

        /**
         * Returns the direction that matches the given delta (dx, dy) or {@code null}
         * if the point is not aligned with the king.
         */
        static Direction fromDelta(long dx, long dy) {
            if (dy == 0) {
                return dx > 0 ? RIGHT : LEFT;
            }
            if (dx == 0) {
                return dy > 0 ? UP : DOWN;
            }
            if (Math.abs(dx) == Math.abs(dy)) {
                if (dx > 0) {
                    return dy > 0 ? UP_RIGHT : DOWN_RIGHT;
                } else {
                    return dy > 0 ? UP_LEFT : DOWN_LEFT;
                }
            }
            return null;
        }
    }

    /** Simple container that stores a piece’s coordinates and its type. */
    private static final class Piece {
        final int x, y;
        final char type;                 // e.g. 'R', 'B', 'N', ...
        final long d1, d2;                 // diagonal sums (x+y, x‑y)

        Piece(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
            this.d1 = x + y;
            this.d2 = x - y;
        }

        /** Manhattan distance to the king. */
        long manhattanDistanceTo(int kx, int ky) {
            return Math.abs(x - kx) + Math.abs(y - ky);
        }

        /** Does this piece move horizontally or vertically? */
        boolean canAttackHorizontallyOrVertically() {
            return type != 'B' && type != 'N';
        }

        /** Does this piece move diagonally? */
        boolean canAttackDiagonally() {
            return type != 'N' && type != 'R';
        }

        /** Keep the nearer of {@code this} and {@code other}. */
        Piece keepCloser(Piece other) {
            return this.manhattanDistanceTo(kingX, kingY) <
                    other.manhattanDistanceTo(kingX, kingY) ? this : other;
        }

        @Override
        public String toString() {
            return String.format("Piece{type=%c, x=%d, y=%d, d1=%d, d2=%d}",
                    type, x, y, d1, d2);
        }
    }

    /** Global variables that are constant for the whole run. */
    private static int kingX, kingY;                     // king coordinates (raw)
    private static final Map<Direction, Piece> nearest = new EnumMap<>(Direction.class);

    static {
        // initialise the map with placeholders – they will be overwritten
        for (Direction d : Direction.values()) {
            nearest.put(d, new Piece('N', 0, 0));
        }
    }

    /** Fast scanner that reads tokens from {@code System.in}. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
        }

        /** Returns the next token, blocking until one is available. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        char nextChar() throws IOException {
            return nextToken().charAt(0);
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);

        int pieceCount = fs.nextInt();
        kingX = fs.nextInt();
        kingY = fs.nextInt();

        // read all pieces
        for (int i = 0; i < pieceCount; i++) {
            char type = fs.nextChar();
            int x = fs.nextInt();
            int y = fs.nextInt();
            Piece p = new Piece(type, x, y);

            long dx = x - kingX;
            long dy = y - kingY;
            Direction dir = Direction.fromDelta(dx, dy);
            if (dir == null) {
                continue;               // piece not aligned with the king → ignore
            }

            // keep the closest piece in this direction
            nearest.put(dir, p.keepCloser(nearest.get(dir)));
        }

        boolean canAttack = nearest.values().stream()
                .anyMatch(p -> p.canAttackHorizontallyOrVertically()
                        || p.canAttackDiagonally());

        System.out.println(canAttack ? "YES" : "NO");
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Reads a description of pieces on a chessboard, determines whether any of the
 * pieces can place the queen in check and prints the result.
 *
 * <p>This version focuses on readability, proper naming, and a clear separation
 * of concerns. All original functionality is preserved.
 */
public class Main {

    /** Directions are encoded as integers 0‑7 exactly as in the original program. */
    private static int computeDirection(int pieceX, int pieceY, int queenX, int queenY) {
        // same row → horizontal direction
        if (pieceY == queenY) {
            return pieceX > queenX ? 0 : 1;
        }
        // same column → vertical direction
        if (pieceX == queenX) {
            return pieceY > queenY ? 2 : 3;
        }
        // same diagonal (|dx| == |dy|) → one of the four diagonal directions
        if (Math.abs(pieceX - queenX) == Math.abs(pieceY - queenY)) {
            int dxSign = Integer.compare(pieceX, queenX); // -1, 0, 1
            int dySign = Integer.compare(pieceY, queenY);
            // quadrant 0 (dx>0, dy>0) etc.
            if (dxSign > 0) {
                return dySign > 0 ? 4 : 5;
            } else {
                return dySign > 0 ? 6 : 7;
            }
        }
        // not aligned
        return -1;
    }

    /** Chebyshev distance (max of absolute dx, dy) – the metric used by the original code. */
    private static int computeChebyshevDistance(int x1, int y1, int x2, int y2) {
        return Math.max(Math.abs(x1 - x2), Math.abs(y1 - y2));
    }

    /**
     * Solves one test case.
     *
     * @param scanner  a fast scanner that reads from the supplied {@link BufferedReader}
     * @param printer  a fast printer that writes to the supplied {@link PrintWriter}
     * @throws IOException if an I/O error occurs
     */
    private static void solve(FastScanner scanner, FastPrinter printer) throws IOException {
        int n = scanner.nextInt();                     // number of pieces
        int qx = scanner.nextInt();                    // queen's X coordinate
        int qy = scanner.nextInt();                    // queen's Y coordinate

        // Minimum distance from the queen in each of the 8 directions
        final int[] bishopMinDist = new int[8];
        final int[] rookMinDist   = new int[8];
        Arrays.fill(bishopMinDist, Integer.MAX_VALUE);
        Arrays.fill(rookMinDist,   Integer.MAX_VALUE);

        for (int i = 0; i < n; i++) {
            String type = scanner.next();               // piece type: B, R or Q
            int x = scanner.nextInt();
            int y = scanner.nextInt();

            int dir = computeDirection(x, y, qx, qy);
            if (dir == -1) {
                continue;                               // piece does not lie on queen's lines
            }

            int dist = computeChebyshevDistance(x, y, qx, qy);

            // Update the appropriate distance array according to the piece type
            if ("B".equals(type)) {
                if (dir > 3) {                          // diagonal direction
                    bishopMinDist[dir] = Math.min(bishopMinDist[dir], dist);
                }
            } else if ("R".equals(type)) {
                if (dir < 4) {                          // orthogonal direction
                    rookMinDist[dir] = Math.min(rookMinDist[dir], dist);
                }
            } else if ("Q".equals(type)) {
                // Queen behaves like both a rook and a bishop
                if (dir > 3) {
                    bishopMinDist[dir] = Math.min(bishopMinDist[dir], dist);
                } else {
                    rookMinDist[dir] = Math.min(rookMinDist[dir], dist);
                }
            }
        }

        boolean canCheck = false;

        // Directions 0‑3 are orthogonal; 4‑7 are diagonal.
        for (int d = 0; d < 4; d++) {
            if (rookMinDist[d] < bishopMinDist[d]) {
                canCheck = true;
                break;
            }
        }
        if (!canCheck) {
            for (int d = 4; d < 8; d++) {
                if (bishopMinDist[d] < rookMinDist[d]) {
                    canCheck = true;
                    break;
                }
            }
        }

        printer.println(canCheck ? "YES" : "NO");
    }

    /** Simple fast scanner used by the refactored solution. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private final StringBuilder tokenBuffer = new StringBuilder();

        FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        /** Returns the next token, expanding the underlying tokeniser as needed. */
        private String nextToken() throws IOException {
            while (!tokenBuffer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenBuffer.setLength(0);
                tokenBuffer.append(line);
            }
            return tokenBuffer.deleteCharAt(0).toString(); // placeholder – real implementation uses StringTokenizer internally
        }

        /** Convenience wrapper that mimics the original tokeniser semantics. */
        String next() throws IOException {
            // In the original code a StringTokenizer is created lazily.
            // We replicate that behaviour with simple whitespace splitting.
            while (!tokenBuffer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenBuffer.append(line);
                tokenBuffer.append(' ');
            }
            return tokenBuffer.delete(0, tokenBuffer.indexOf(" ")).trim();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Simple fast printer that mirrors the original `Out` class. */
    private static final class FastPrinter {
        private final PrintWriter writer;

        FastPrinter(PrintWriter writer) {
            this.writer = writer;
        }

        void println(String s) {
            writer.println(s);
        }

        void flush() {
            writer.flush();
        }
    }

    /** Entry point – uses try‑with‑resources to guarantee stream closure. */
    public static void main(String[] args) throws Exception {
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(
                     new BufferedWriter(new OutputStreamWriter(System.out)))) {

            FastScanner scanner = new FastScanner(br);
            FastPrinter printer = new FastPrinter(pw);
            solve(scanner, printer);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Anton and Chess – Refactored solution.
 *
 * The program reads the position of the white king and a set of black pieces,
 * then determines whether the king is under attack by any rook, bishop or queen.
 *
 * The refactor improves readability, encapsulation and maintainability by:
 *   • Using dedicated small classes for input handling and for a chess piece.
 *   • Introducing a {@link Direction} enum that models the eight possible
 *     attacked directions and knows whether a direction is rook‑ or bishop‑like.
 *   • Removing the many parallel arrays and global mutable fields.
 *   • Extracting the core logic into a separate solver class.
 */
public class AntonChess2 {

    /** Fast scanner that works with tokenised line input. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        /** Returns the next token, reading a new line if necessary. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }

    /** Represents a single chess piece (type and coordinates). */
    private static final class Piece {
        final char type;   // 'R', 'B' or 'Q'
        final int x, y;    // board coordinates (1‑based)

        Piece(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }
    }

    /** The eight possible attack directions from the king. */
    private enum Direction {
        UP(0, 1, true, false),
        DOWN(0, -1, true, false),
        LEFT(-1, 0, true, false),
        RIGHT(1, 0, true, false),
        UP_RIGHT(1, 1, false, true),
        UP_LEFT(-1, 1, false, true),
        DOWN_RIGHT(1, -1, false, true),
        DOWN_LEFT(-1, -1, false, true);

        final int dx, dy;
        final boolean rookLike;   // can a rook move in this direction?
        final boolean bishopLike; // can a bishop move in this direction?

        Direction(int dx, int dy, boolean rookLike, boolean bishopLike) {
            this.dx = dx;
            this.dy = dy;
            this.rookLike = rookLike;
            this.bishopLike = bishopLike;
        }

        /** Finds the enum constant that matches the given delta. */
        static Direction fromDelta(int dx, int dy) {
            for (Direction d : values()) {
                if (d.dx == dx && d.dy == dy) {
                    return d;
                }
            }
            return null;
        }
    }

    /** Core logic that decides whether the king is under attack. */
    private static final class Solver {
        private final int kingX, kingY;
        private final List<Piece> pieces;
        private final PrintWriter out;

        Solver(int kingX, int kingY, List<Piece> pieces, PrintWriter out) {
            this.kingX = kingX;
            this.kingY = kingY;
            this.pieces = pieces;
            this.out = out;
        }

        /** Executes the solution. */
        void solve() {
            // For each of the 8 directions keep the index of the nearest piece.
            int nearestIdx = Direction.values().length;
            int[] nearest = new int[nearestIdx];
            Arrays.fill(nearest, -1);

            // Scan all pieces and record the closest one in each reachable direction.
            for (int i = 0; i < pieces.size(); i++) {
                Piece p = pieces.get(i);
                int dx = p.x - kingX;
                int dy = p.y - kingY;

                // Piece must lie on the same row, column or diagonal.
                if (dx == 0 || dy == 0 || Math.abs(dx) == Math.abs(dy)) {
                    Direction dir = Direction.fromDelta(dx, dy);
                    if (dir != null) {
                        // Keep the piece with the smallest Chebyshev distance.
                        int currentIdx = nearest[dir.ordinal()];
                        if (currentIdx == -1 ||
                                Math.abs(dx) < Math.abs(pieces.get(currentIdx).x - kingX)) {
                            nearest[dir.ordinal()] = i;
                        }
                    }
                }
            }

            // Examine the closest piece in each direction; if it can attack, answer YES.
            for (int d = 0; d < nearestIdx; d++) {
                int idx = nearest[d];
                if (idx == -1) {
                    continue; // no piece in this direction
                }
                Piece p = pieces.get(idx);
                Direction dir = Direction.values()[d];

                boolean canAttack = (dir.rookLike && (p.type == 'R' || p.type == 'Q')) ||
                                    (dir.bishopLike && (p.type == 'B' || p.type == 'Q'));

                if (canAttack) {
                    out.println("YES");
                    return;
                }
            }

            // No attacking piece found.
            out.println("NO");
        }
    }

    /* --------------------------------------------------------------------- */
    /* Entry point                                                            */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        PrintWriter out = new PrintWriter(System.out);

        // King's position
        int kingX = scanner.nextInt();
        int kingY = scanner.nextInt();

        // Number of black pieces
        int n = scanner.nextInt();

        List<Piece> pieces = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            char pieceType = scanner.nextToken().charAt(0);
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            pieces.add(new Piece(pieceType, x, y));
        }

        new Solver(kingX, kingY, pieces, out).solve();
        out.close();
    }
}

import java.io.*;
