/**
 * Solution for CF round 15 – checks whether a piece can attack the king
 * from any of the eight directions using the closest piece in each direction.
 */
public class Main {

    /** Fast scanner that reads tokens from {@code System.in}. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
            st = new StringTokenizer("");
        }

        /** Fills the tokenizer with the next line if needed. */
        private void fillTokenizer() throws IOException {
            while (!st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
        }

        /** Reads the next token. */
        String next() throws IOException {
            while (!st.hasMoreTokens()) {
                fillTokenizer();
            }
            return st.nextToken();
        }

        /** Reads the next integer as {@code long}. */
        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        /** Reads the next integer as {@code int}. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Helper for building the output without repeatedly creating new writers. */
    private static class OutputBuilder {
        private final PrintWriter pw;

        OutputBuilder(OutputStream out) {
            pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) pw.print(' ');
                pw.print(objects[i]);
            }
        }

        void println(Object... objects) {
            print(objects);
            pw.println();
        }

        void flush() {
            pw.flush();
        }

        void close() {
            pw.close();
        }
    }

    /** Represents a chess piece placed relative to the reference point (x0, y0). */
    private static class ChessPiece implements Comparable<ChessPiece> {
        final long distance;   // Manhattan distance from the reference point
        final long x;
        final long y;
        final String type;     // one of "B", "Q", "R"

        ChessPiece(long x, long y, long distance, String type) {
            this.x = x;
            this.y = y;
            this.distance = distance;
            this.type = type;
        }

        @Override
        public int compareTo(ChessPiece o) {
            // Smaller distance should be considered "smaller" → poll first.
            return Long.compare(this.distance, o.distance);
        }
    }

    /**
     * Returns {@code true} if the closest piece in {@code queue} is of one of the
     * allowed types (e.g. "B" or "Q").
     */
    private static boolean hasThreateningPiece(PriorityQueue<ChessPiece> queue, String... allowedTypes) {
        if (queue.isEmpty()) {
            return false;
        }
        ChessPiece closest = queue.peek();
        for (String allowed : allowedTypes) {
            if (allowed.equals(closest.type)) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        OutputBuilder out = new OutputBuilder(System.out);

        int n = fs.nextInt();
        long x0 = fs.nextLong();
        long y0 = fs.nextLong();

        /* Queues that store the closest piece in each of the eight directions */
        PriorityQueue<ChessPiece> diagUpRight   = new PriorityQueue<>();
        PriorityQueue<ChessPiece> diagUpLeft    = new PriorityQueue<>();
        PriorityQueue<ChessPiece> diagDownRight = new PriorityQueue<>();
        PriorityQueue<ChessPiece> diagDownLeft  = new PriorityQueue<>();

        PriorityQueue<ChessPiece> horzLeft  = new PriorityQueue<>();
        PriorityQueue<ChessPiece> horzRight = new PriorityQueue<>();
        PriorityQueue<ChessPiece> vertDown  = new PriorityQueue<>();
        PriorityQueue<ChessPiece> vertUp    = new PriorityQueue<>();

        for (int i = 0; i < n; i++) {
            String type = fs.next();
            long x = fs.nextLong();
            long y = fs.nextLong();

            long dx = x - x0;
            long dy = y - y0;
            long dist = Math.abs(dx); // distance used for ordering

            /* Pieces lying exactly on a diagonal (|dx| == |dy|) */
            if (dx != 0 && dy != 0 && Math.abs(dx) == Math.abs(dy)) {
                if (dx > 0 && dy > 0) {
                    diagUpRight.add(new ChessPiece(x, y, dist, type));
                } else if (dx > 0 && dy < 0) {
                    diagDownRight.add(new ChessPiece(x, y, dist, type));
                } else if (dx < 0 && dy > 0) {
                    diagUpLeft.add(new ChessPiece(x, y, dist, type));
                } else { // dx < 0 && dy < 0
                    diagDownLeft.add(new ChessPiece(x, y, dist, type));
                }
            }

            /* Horizontal directions */
            if (dy == 0 && dx < 0) {
                horzLeft.add(new ChessPiece(x, y, Math.abs(dx), type));
            } else if (dy == 0 && dx > 0) {
                horzRight.add(new ChessPiece(x, y, Math.abs(dx), type));
            }

            /* Vertical directions */
            if (dx == 0 && dy < 0) {
                vertDown.add(new ChessPiece(x, y, Math.abs(dy), type));
            } else if (dx == 0 && dy > 0) {
                vertUp.add(new ChessPiece(x, y, Math.abs(dy), type));
            }
        }

        boolean canAttack = false;
        canAttack |= hasThreateningPiece(diagUpRight,   "B", "Q");
        canAttack |= hasThreateningPiece(diagUpLeft,    "B", "Q");
        canAttack |= hasThreateningPiece(diagDownRight, "B", "Q");
        canAttack |= hasThreateningPiece(diagDownLeft,  "B", "Q");
        canAttack |= hasThreateningPiece(horzLeft,      "R", "Q");
        canAttack |= hasThreateningPiece(horzRight,     "R", "Q");
        canAttack |= hasThreateningPiece(vertDown,      "R", "Q");
        canAttack |= hasThreateningPiece(vertUp,        "R", "Q");

        out.println(canAttack ? "YES" : "NO");
        out.flush();
        out.close();
    }
}

import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>
 *   The program reads the position of a white king and a set of black chess pieces,
 *   then determines whether any black piece can capture the white king on a square that
 *   has not been previously reserved by another black piece.
 *   <ul>
 *       <li>Black pieces are sorted by their Manhattan distance to the white king.</li>
 *       <li>For each piece we compute a directional code (1‑8) that represents the direction
 *           from the king to the piece.</li>
 *       <li>If the piece can capture the king and its directional code has not been used
 *           yet, the answer becomes {@code YES}.</li>
 *       <li>Otherwise, if the directional code is still unused it is marked as used.</li>
 *   </ul>
 * </p>
 *
 * The refactoring focuses on readability, explicit naming and modern Java idioms.
 */
public class ChessGameSolver {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            solve(scanner, writer);
        }
    }

    /** Main algorithm entry point. */
    private static void solve(Scanner scanner, PrintWriter writer) {
        parseInput(scanner);

        // Sort black pieces by distance to the white king (Manhattan distance)
        blackPieces.sort(Comparator
                .comparingLong(Chess::manhattanDistanceTo(king))
                .thenComparingInt((Chess p) -> p.x)
                .thenComparingInt(p -> p.y));

        // Set of directional codes that have already been taken
        Map<Integer, Boolean> taken = createTakenMap();

        boolean canCaptureOnFreeSquare = false;

        for (Chess blackPiece : blackPieces) {
            int direction = getDirectionCode(king, blackPiece);

            boolean canCapture = canCaptureKing(king, blackPiece);
            if (canCapture && direction != 0 && !taken.get(direction)) {
                canCaptureOnFreeSquare = true;
                taken.put(direction, true);
                break; // early exit – answer is already determined
            }

            // Even if the piece cannot capture, reserve its direction
            if (direction != 0 && !taken.get(direction)) {
                taken.put(direction, true);
            }
        }

        writer.println(canCaptureOnFreeSquare ? "YES" : "NO");
    }

    /** Reads and stores the initial board configuration. */
    private static void parseInput(Scanner scanner) {
        int n = scanner.nextInt();               // number of black pieces
        int kingX = scanner.nextInt();
        int kingY = scanner.nextInt();
        king = new Chess('K', kingX, kingY);

        blackPieces = new Chess[n];
        for (int i = 0; i < n; i++) {
            char role = scanner.next().charAt(0);
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            blackPieces[i] = new Chess(role, x, y);
        }
    }

    /** Determines if a black piece can capture the white king according to chess rules. */
    private static boolean canCaptureKing(Chess king, Chess piece) {
        return switch (piece.role) {
            case 'B' -> piece.isDiagonal(king);
            case 'R' -> piece.isHorizontalOrVertical(king);
            case 'Q' -> piece.isDiagonal(king) || piece.isHorizontalOrVertical(king);
            default -> false; // safety net – should never happen for valid input
        };
    }

    /** Returns a directional code (1‑8) describing where the piece lies relative to the king.
     *  Returns {@code 0} if the piece is not aligned horizontally, vertically or diagonally.
     */
    private static int getDirectionCode(Chess king, Chess piece) {
        if (king.x == piece.x) {
            return king.y < piece.y ? 4 : 8;
        }
        if (king.y == piece.y) {
            return king.x < piece.x ? 6 : 2;
        }
        if (Math.abs(king.x - piece.x) == Math.abs(king.y - piece.y)) {
            return (king.x < piece.x ? (king.y < piece.y ? 5 : 7) : (king.y < piece.y ? 3 : 1));
        }
        return 0;
    }

    /** Creates a map that tracks which directional codes have been used. */
    private static Map<Integer, Boolean> createTakenMap() {
        Map<Integer, Boolean> map = new HashMap<>();
        for (int i = 1; i <= 8; i++) {
            map.put(i, false);
        }
        return map;
    }

    /* --------------------------------------------------------------------------
       Data structures
       -------------------------------------------------------------------------- */

    /** Simple value object representing a chess piece on the board. */
    private static final class Chess {
        private final char role; // 'K', 'B', 'R', 'Q' (uppercase only)
        private final int x;
        private final int y;

        Chess(char role, int x, int y) {
            this.role = role;
            this.x = x;
            this.y = y;
        }

        /** Manhattan distance to the white king. */
        long manhattanDistanceTo(Chess other) {
            return Math.abs(x - other.x) + Math.abs(y - other.y);
        }

        /** True if the piece lies on the same diagonal as {@code other}. */
        boolean isDiagonal(Chess other) {
            return Math.abs(x - other.x) == Math.abs(y - other.y);
        }

        /** True if the piece shares a row or a column with {@code other}. */
        boolean isHorizontalOrVertical(Chess other) {
            return x == other.x || y == other.y;
        }
    }

    /* --------------------------------------------------------------------------
       State holders (static for simplicity)
       -------------------------------------------------------------------------- */

    private static Chess king;                     // white king
    private static Chess[] blackPieces;            // array of black pieces
}

