/**
 * Encapsulates a 4×4 board and all possible win‑lines.
 * The class knows how to collect every row, column and diagonal,
 * and whether any of those lines contains a winning pattern.
 */
final class GameBoard {
    private static final int SIZE = 4;
    private final char[][] board;
    /** All lines (row, column or diagonal) that can produce a win. */
    private final List<char[]> winLines = new ArrayList<>();

    GameBoard(char[][] board) {
        this.board = board;
        collectWinningLines();
    }

    /** Returns true if any three‑cell consecutive sequence matches the winning pattern. */
    boolean canWin() {
        for (char[] line : winLines) {
            if (isWinningLine(line)) {
                return true;
            }
        }
        return false;
    }

    /** Builds the list of all possible win‑lines for the current board. */
    private void collectWinningLines() {
        // rows
        for (char[] row : board) {
            winLines.add(row);
        }

        // columns
        for (int col = 0; col < SIZE; col++) {
            char[] column = new char[SIZE];
            for (int row = 0; row < SIZE; row++) {
                column[row] = board[row][col];
            }
            winLines.add(column);
        }

        // 4‑cell diagonals
        winLines.add(new char[]{
                board[0][0], board[1][1], board[2][2], board[3][3]   // main diagonal
        });
        winLines.add(new char[]{
                board[3][0], board[2][1], board[1][2], board[0][3]   // anti‑diagonal
        });

        // 3‑cell diagonals that start one step away from the edges
        winLines.add(new char[]{board[0][1], board[1][2], board[2][3]});
        winLines.add(new char[]{board[1][0], board[2][1], board[3][2]});
        winLines.add(new char[]{board[3][1], board[2][2], board[1][3]});
        winLines.add(new char[]{board[2][0], board[1][1], board[0][2]});
    }

    /** Checks every consecutive triple in a line for the winning pattern. */
    private static boolean isWinningLine(char[] line) {
        for (int i = 0; i <= line.length - 3; i++) {
            char a = line[i];
            char b = line[i + 1];
            char c = line[i + 2];
            if ((a == '.' && b == 'x' && c == 'x')
                    || (a == 'x' && b == '.' && c == 'x')
                    || (a == 'x' && b == 'x' && c == '.')) {
                return true;
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Main class that reads a 4×4 board, tries to place an 'x' in an empty cell
 * and checks whether that placement creates a line of exactly three 'x's.
 * The result is printed as "YES" or "NO".
 */
public class C1 {

    /** Size of the board (fixed 4×4). */
    private static final int BOARD_SIZE = 4;

    /** Representation of an empty cell. */
    private static final char EMPTY = '.';

    /** Symbol used for the tentative move. */
    private static final char MARK = 'x';

    /** Not used in the current algorithm but kept for compatibility. */
    private static final int MOD = (int) 1e9 + 7;

    public static void main(String[] args) throws IOException {
        /* Run the solver in a separate thread with a large stack to avoid
         * StackOverflowError on some judges. */
        new Thread(null, () -> solve(), "C1 solver", 1 << 26).start();
    }

    /** Core solving logic – reads input, processes the board and prints the answer. */
    private static void solve() {
        try (InputReader reader = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            char[][] board = readBoard(reader);
            boolean canWin = canWinByPlacingMark(board);
            out.println(canWin ? "YES" : "NO");
        }
    }

    /** Reads the four lines that constitute the board. */
    private static char[][] readBoard(InputReader reader) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = reader.nextLine().trim();
            if (line.length() != BOARD_SIZE) {
                throw new IllegalArgumentException(
                        "Each line must contain exactly " + BOARD_SIZE + " characters");
            }
            board[i] = line.toCharArray();
        }
        return board;
    }

    /** Determines whether placing a mark creates a line of exactly three marks. */
    private static boolean canWinByPlacingMark(char[][] board) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] == EMPTY) {
                    board[r][c] = MARK;                     // tentative move
                    boolean win = hasThreeInLine(board, r, c);
                    board[r][c] = EMPTY;                       // restore original state
                    if (win) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Checks all four directions from (row,col) for a consecutive triple of marks. */
    private static boolean hasThreeInLine(char[][] board, int row, int col) {
        return hasThreeInDirection(board, row, col, 0, 1)   // horizontal
            || hasThreeInDirection(board, row, col, 1, 0)   // vertical
            || hasThreeInDirection(board, row, col, 1, 1)    // diagonal \
            || hasThreeInDirection(board, row, col, 1, -1); // diagonal /
    }

    /**
     * Counts how many consecutive cells in the given direction are marks.
     * The checked cells are (row‑dr, col‑dc), (row, col) and (row+dr, col+dc).
     * Returns true if exactly three of them are marks.
     */
    private static boolean hasThreeInDirection(char[][] board, int row, int col,
                                               int dr, int dc) {
        int count = 0;
        for (int step = -1; step <= 1; step++) {
            int r = row + dr * step;
            int c = col + dc * step;
            if (isInside(r, c) && board[r][c] == MARK) {
                count++;
            }
        }
        return count == 3;
    }

    /** Helper that verifies whether a coordinate lies inside the 4×4 board. */
    private static boolean isInside(int r, int c) {
        return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
    }
}

/**
 * Simple input wrapper that provides convenient token‑based and line‑based
 * readers. It is used by {@link C1} to obtain the board data.
 */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    /** Constructs an {@link InputReader} that reads from the supplied {@link InputStream}. */
    InputReader(InputStream inputStream) {
        this.reader = new BufferedReader(new InputStreamReader(inputStream));
    }

    /** Returns the next complete line from the input. */
    String nextLine() {
        try {
            return reader.readLine();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    /** Returns the next token (word) from the input, expanding the tokenizer as needed. */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Convenience methods for primitive parsing. */
    long nextLong() { return Long.parseLong(next()); }
    int nextInt()   { return Integer.parseInt(next()); }
}

import java.util.Scanner;

/**
 * Utility class that validates a 4×4 board for a simple two‑player game.
 *
 * The game uses the characters:
 *   'x' – player X
 *   'o' – player O
 *   '.' – empty cell
 *
 * The program reads a board from {@code System.in}, determines whose turn it is,
 * and prints {@code "YES"} if placing that player's marker creates a winning line
 * (three in a row in any direction); otherwise it prints {@code "NO"}.
 */
public class Game {

    /** Symbol used for an empty cell. */
    private static final char EMPTY = '.';

    /** The minimum length required to win (the original code checks for 3). */
    private static final int WIN_LENGTH = 3;

    private Game() {
        // Utility class – no instances.
    }

    /**
     * Determines which player should move next based on the current board state.
     *
     * @param board the current board
     * @return 'x' or 'o' – the symbol of the next player
     * @throws IllegalStateException if the board contains an illegal Symbol
     */
    public static char nextPlayer(char[][] board) {
        int score = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == 'x') {
                    score++;
                } else if (cell == 'o') {
                    score--;
                } else if (cell != EMPTY) {
                    throw new IllegalStateException("Unexpected board symbol: " + cell);
                }
            }
        }

        // score == 1  → more 'x' than 'o' → next is 'o'
        // score == 0  → equal counts   → next is 'x'
        return (score == 1) ? 'o' : 'x';
    }

    /**
     * Checks whether the given player has a winning line that starts at (row, col).
     *
     * @param board   the board
     * @param row     starting row
     * @param col     starting column
     * @param player  player symbol ('x' or 'o')
     * @return {@code true} if a winning line is found from this position
     */
    private static boolean isWinningFrom(char[][] board, int row, int col, char player) {
        return countInDirection(board, row, col, player, 0, 1) >= WIN_LENGTH   // horizontal
            || countInDirection(board, row, col, player, 1, 0) >= WIN_LENGTH   // vertical
            || countInDirection(board, row, col, player, 1, 1) >= WIN_LENGTH   // diagonal down‑right
            || countInDirection(board, row, col, player, -1, 1) >= WIN_LENGTH; // diagonal up‑right
    }

    /**
     * Counts consecutive cells that match {@code player} moving in the direction
     * defined by {@code deltaRow} and {@code deltaCol}.
     *
     * @return the number of consecutive matching cells, including the start cell
     */
    private static int countInDirection(char[][] board,
                                         int startRow,
                                         int startCol,
                                         char player,
                                         int deltaRow,
                                         int deltaCol) {
        int count = 0;
        int row = startRow;
        int col = startCol;

        while (isInside(board, row, col) && board[row][col] == player) {
            count++;
            if (count >= WIN_LENGTH) {
                // No need to continue once we know we have at least 3.
                break;
            }
            row += deltaRow;
            col += deltaCol;
        }
        return count;
    }

    /** @return {@code true} if the supplied coordinates are within the board limits */
    private static boolean isInside(char[][] board, int row, int col) {
        return row >= 0 && row < board.length
                && col >= 0 && col < board[row].length;
    }

    /**
     * Executes the core algorithm:
     * <ol>
     *   <li>Read a 4×4 board from {@code System.in}.</li>
     *   <li>Determine the next player.</li>
     *   <li>Simulate placing that player's marker on each empty cell.</li>
     *   <li>If any placement yields a winning line, output {@code "YES"}; otherwise {@code "NO"}.</li>
     * </ol>
     */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = new char[4][4];
            for (int i = 0; i < 4; i++) {
                String line = scanner.nextLine().trim();
                if (line.length() != 4) {
                    throw new IllegalArgumentException(
                            "Each board row must contain exactly 4 characters, got: [" + line + "]");
                }
                board[i] = line.toCharArray();
            }

            char next = nextPlayer(board);

            for (int i = 0; i < board.length; i++) {
                for (int j = 0; j < board[i].length; j++) {
                    if (board[i][j] == EMPTY) {
                        board[i][j] = next;
                        if (isWinningFor(board, next)) {
                            System.out.println("YES");
                            return;
                        }
                        board[i][j] = EMPTY; // revert for next simulation
                    }
                }
            }

            System.out.println("NO");
        }
    }

    /**
     * Helper that checks whether placing {@code player} anywhere on the board
     * creates a winning line. It re‑uses {@link #isWinningFrom}.
     */
    private static boolean isWinningFor(char[][] board, char player) {
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (board[i][j] == player && isWinningFrom(board, i, j, player)) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Reads a 4×4 board and checks whether any of the predefined “x/.x” patterns exist.
 * The logic is extracted into small, well‑named methods to improve readability
 * and maintainability.
 */
public class Main {

    private static final Scanner SCANNER = new Scanner(System.in);
    private static final int BOARD_SIZE = 4;

    public static void main(String[] args) {
        char[][] board = readBoard();

        if (hasWinPattern(board)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads four lines from standard input, each containing exactly four characters,
     * and returns the resulting 4×4 character board.
     */
    private static char[][] readBoard() {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int row = 0; row < BOARD_SIZE; row++) {
            String line = SCANNER.nextLine().trim();
            if (line.length() != BOARD_SIZE) {
                throw new IllegalArgumentException(
                        "Each line must contain exactly " + BOARD_SIZE + " characters");
            }
            board[row] = line.toCharArray();
        }
        return board;
    }

    /**
     * Determines whether the board contains any of the required patterns.
     * A pattern is found when, from an 'x' cell, two consecutive cells in the same
     * direction form either "x .", ". x" or any of their mirrored variants.
     *
     * @return true if at least one pattern exists, false otherwise
     */
    private static boolean hasWinPattern(char[][] board) {
        // All eight possible directions (horizontal, vertical, two diagonals)
        final int[][] DIRECTIONS = {
                {1, 0},  {-1, 0},  {0, 1},  {0, -1},   // vertical / horizontal
                {1, 1},  {1, -1}, {-1, 1}, {-1, -1}    // diagonals
        };

        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] != 'x') {
                    continue; // only cells containing 'x' can start a pattern
                }

                for (int[] dir : DIRECTIONS) {
                    int di = dir[0];
                    int dj = dir[1];

                    int next1I = i + di;
                    int next1J = j + dj;
                    int next2I = i + 2 * di;
                    int next2J = j + 2 * dj;

                    if (!isInside(next1I, next1J) || !isInside(next2I, next2J)) {
                        continue; // outside the board – skip this direction
                    }

                    char firstNeighbour = board[next1I][next1J];
                    char secondNeighbour = board[next2I][next2J];

                    // Pattern: "x ." or ". x" (or the opposite order)
                    if ((firstNeighbour == 'x' && secondNeighbour == '.') ||
                        (firstNeighbour == '.' && secondNeighbour == 'x')) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Helper that checks whether a board coordinate lies inside the 4×4 grid. */
    private static boolean isInside(int row, int col) {
        return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE;
    }
}

import java.util.Scanner;

/**
 * Reads a 4×4 character grid from the console and reports whether any
 * horizontal, vertical or diagonal sequence of three identical characters
 * (the ones that sum to {@code REQUIRED_SUM}) exists.
 */
public class Main {

    /** Size of the square grid (4×4). */
    private static final int GRID_SIZE = 4;

    /**
     * The magical constant that represents the sum of three characters
     * appearing in the original input.  Keeping it as a named constant makes
     * the intent obvious and eases future changes.
     */
    private static final int REQUIRED_SUM = 286;

    public static void main(String[] args) {
        // Try‑with‑resources automatically closes the scanner.
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] grid = readGrid(scanner);
            if (hasThreeInARow(grid, REQUIRED_SUM)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Reads four lines from the scanner and builds a {@code 4×4} character grid.
     */
    private static char[][] readGrid(Scanner scanner) {
        String[] lines = new String[GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            lines[i] = scanner.nextLine();
        }

        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int row = 0; row < GRID_SIZE; row++) {
            String line = lines[row];
            for (int col = 0; col < GRID_SIZE; col++) {
                grid[row][col] = line.charAt(col);
            }
        }
        return grid;
    }

    /**
     * Determines whether any length‑3 sequence (horizontal, vertical,
     * main diagonal or anti‑diagonal) adds up to {@code targetSum}.
     */
    private static boolean hasThreeInARow(char[][] grid, int targetSum) {
        // Check rows and columns (both directions)
        if (checkLines(grid, true, false)) return true;   // horizontal
        if (checkLines(grid, false, true)) return true;   // vertical

        // Check the two diagonal directions
        if (checkDiagonals(grid, true))  return true;   // main diagonal (↘)
        if (checkDiagonals(grid, false)) return true;   // anti‑diagonal (↙)

        return false;
    }

    /**
     * Checks all length‑3 sequences that run either horizontally or vertically.
     *
     * @param rows        if {@code true} the sequences are horizontal,
     *                    otherwise vertical.
     * @param columns     if {@code true} the sequences are checked column‑wise,
     *                    otherwise row‑wise (used only when {@code rows} is {@code false}).
     */
    private static boolean checkLines(char[][] grid, boolean rows, boolean columns) {
        // Only the first two start positions can yield a length‑3 sequence
        // because the grid size is 4.
        for (int i = 0; i <= 1; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                int sum;
                if (rows) {
                    // Horizontal line starting at (i, j)
                    sum = grid[i][j] + grid[i][j + 1] + grid[i][j + 2];
                } else {
                    // Vertical line starting at (j, i)
                    sum = grid[i][j] + grid[i + 1][j] + grid[i + 2][j];
                }
                if (sum == targetSum) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks the two diagonal directions for a length‑3 sequence that sums
     * to {@code targetSum}.
     *
     * @param mainDiagonal if {@code true} checks the forward diagonal (↘),
     *                     otherwise the backward diagonal (↙).
     */
    private static boolean checkDiagonals(char[][] grid, boolean mainDiagonal) {
        for (int i = 0; i <= 1; i++) {
            for (int j = 0; j <= 1; j++) {
                int sum;
                if (mainDiagonal) {
                    // ↘ direction: (i,j) → (i+1,j+1) → (i+2,j+2)
                    sum = grid[i][j] + grid[i + 1][j + 1] + grid[i + 2][j + 2];
                } else {
                    // ↙ direction: (i,j+2) → (i+1,j+1) → (i+2,j)
                    sum = grid[i][j + 2] + grid[i + 1][j + 1] + grid[i + 2][j];
                }
                if (sum == targetSum) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Reads a 4×4 board (four lines of exactly four characters each) and determines
 * whether any 3‑character win pattern appears in a row, column or diagonal.
 *
 * <p>Win patterns are:</p>
 * <ul>
 *   <li>"xx." – three consecutive 'x'‑like marks with a placeholder '.'</li>
 *   <li>"x.x"</li>
 *   <li>".xx"</li>
 * </ul>
 * <p>The program prints "YES" if any such pattern is found, otherwise "NO".</p>
 */
public class TicTacToeValidator {

    private static final int BOARD_SIZE = 4;
    /** Patterns that indicate a winning configuration. */
    private static final List<String> WIN_PATTERNS = List.of("xx.", "x.x", ".xx");

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            List<String> rows = new ArrayList<>(BOARD_SIZE);
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = scanner.nextLine().trim();
                if (line.length() != BOARD_SIZE) {
                    throw new IllegalArgumentException(
                            "Each line must contain exactly " + BOARD_SIZE + " characters.");
                }
                rows.add(line);
            }

            System.out.println(isGameFinished(rows) ? "YES" : "NO");
        }
    }

    /** Returns {@code true} if any win pattern appears in the board. */
    private static boolean isGameFinished(List<String> rows) {
        // 1. Check rows
        for (String row : rows) {
            if (containsWinPattern(row)) {
                return true;
            }
        }

        // 2. Check columns
        for (int col = 0; col < BOARD_SIZE; col++) {
            StringBuilder column = new StringBuilder(BOARD_SIZE);
            for (int row = 0; row < BOARD_SIZE; row++) {
                column.append(rows.get(row).charAt(col));
            }
            if (containsWinPattern(column.toString())) {
                return true;
            }
        }

        // 3. Check all diagonal sequences (length‑3 slices)
        for (String diag : extractDiagonalStrings(rows)) {
            if (containsWinPattern(diag)) {
                return true;
            }
        }

        return false;
    }

    /** true if the given string contains any of the win patterns. */
    private static boolean containsWinPattern(String candidate) {
        for (String pattern : WIN_PATTERNS) {
            if (candidate.contains(pattern)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Produces every length‑3 sequence that lies on a diagonal of the 4×4 board.
     * The original program examined eight such sequences; this method reproduces
     * exactly those sequences in a clear, maintainable way.
     */
    private static List<String> extractDiagonalStrings(List<String> rows) {
        List<String> diagonals = new ArrayList<>();

        // main diagonal (top‑left → bottom‑right)
        diagonals.add(buildString(rows, new int[]{0, 1, 2}, new int[]{0, 1, 2}));
        diagonals.add(buildString(rows, new int[]{1, 2, 3}, new int[]{1, 2, 3}));

        // anti‑diagonal (top‑right → bottom‑left)
        diagonals.add(buildString(rows, new int[]{0, 1, 2}, new int[]{3, 2, 1}));
        diagonals.add(buildString(rows, new int[]{1, 2, 3}, new int[]{2, 1, 0}));

        // the remaining four length‑3 diagonals that start/stop one step inside the board
        diagonals.add(buildString(rows, new int[]{0, 1, 2}, new int[]{1, 2, 3}));
        diagonals.add(buildString(rows, new int[]{1, 2, 3}, new int[]{0, 1, 2}));
        diagonals.add(buildString(rows, new int[]{0, 1, 2}, new int[]{2, 1, 0}));
        diagonals.add(buildString(rows, new int[]{1, 2, 3}, new int[]{3, 2, 1}));

        return diagonals;
    }

    /**
     * Helper that builds a string of length three by reading characters at the
     * supplied row and column indices.
     */
    private static String buildString(List<String> rows, int[] rowIndices, int[] colIndices) {
        StringBuilder sb = new StringBuilder(3);
        for (int i = 0; i < rowIndices.length; i++) {
            int r = rowIndices[i];
            int c = colIndices[i];
            sb.append(rows.get(r).charAt(c));
        }
        return sb.toString();
    }
}

import java.util.List;

/**
 * Refactored version of the original program.
 *
 * <p>
 *   The program reads a partially‑filled 8×8 board, tries to place an "x" in any empty
 *   cell of the inner 4×4 region, and reports whether such a placement creates a
 *   three‑in‑a‑row line (horizontally, vertically or diagonally).
 * </p>
 */
public class Main {

    /** Direction vectors used to check 3‑in‑a‑row lines. */
    private enum Direction {
        RIGHT(0, 1), LEFT(0, -1),
        UP(1, 0), DOWN(-1, 0),
        UP_RIGHT(1, 1), UP_LEFT(1, -1),
        DOWN_RIGHT(-1, 1), DOWN_LEFT(-1, -1);

        final int dx;
        final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }
    }

    /** Constant board size (8×8). */
    private static final int BOARD_SIZE = 8;

    /** First (inclusive) index of the inner region to inspect. */
    private static final int INNER_START = 2;

    /** Last (exclusive) index of the inner region to inspect. */
    private static final int INNER_END = 6;

    /** Empty cell marker used in the input board. */
    private static final char EMPTY = '.';

    /** Marker placed by the solver to test for a winning line. */
    private static final char MARKER = 'x';

    /** All eight direction vectors – equivalent to the original `address` list. */
    private static final List<Direction> DIRECTIONS = List.of(
            new Direction(0, 1), new Direction(0, -1),
            new Direction(1, 0), new Direction(-1, 0),
            new Direction(1, 1), new Direction(1, -1),
            new Direction(-1, 1), new Direction(-1, -1)
    );

    /** Entry point. */
    public static void main(String[] args) {
        char[][] board = initialiseBoard();
        readInput(board);

        boolean canWin = canPlaceWinningMarker(board);
        System.out.println(canWin ? "YES" : "NO");
    }

    /** Creates an empty board and populates the fixed prefix (mirrors original behaviour). */
    private static char[][] initialiseBoard() {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (char[] row : board) {
            Arrays.fill(row, EMPTY);
        }
        // The original code added several {@code Pair} objects to a static list,
        // but those pairs were only used to iterate over direction vectors.
        // No actual board cells are filled here; the input later fills the relevant area.
        return board;
    }

    /** Reads the four‑character lines that fill the inner 4×4 region of the board. */
    private static void readInput(char[][] board) {
        try (Scanner scanner = new Scanner(System.in)) {
            for (int row = INNER_START; row < INNER_END; row++) {
                String line = scanner.nextLine().trim();
                for (int col = 0; col < 4; col++) {
                    board[row][col + INNER_START] = line.charAt(col);
                }
            }
        }
    }

    /** Determines whether placing a MARKER creates any three‑in‑a‑row line. */
    private static boolean canPlaceWinningMarker(char[][] board) {
        for (int row = INNER_START; row < INNER_END; row++) {
            for (int col = INNER_START; col < INNER_END; col++) {
                if (board[row][col] == EMPTY) {
                    board[row][col] = MARKER;                 // tentative move
                    boolean win = hasThreeInARow(board);
                    board[row][col] = EMPTY;                    // undo move
                    if (win) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Checks the entire board for any three‑in‑a‑row line composed of MARKER cells. */
    private static boolean hasThreeInARow(char[][] board) {
        for (int row = INNER_START; row < INNER_END; row++) {
            for (int col = INNER_START; col < INNER_END; col++) {
                if (isThreeInARowFrom(board, row, col)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks whether a line of three MARKER cells starts from {@code (row, col)}
     * and follows any of the predefined directions.
     */
    private static boolean isThreeInARowFrom(char[][] board, int startRow, int startCol) {
        for (Direction dir : DIRECTIONS) {
            boolean lineComplete = true;
            int r = startRow;
            int c = startCol;

            for (int step = 0; step < 3; step++) {
                if (board[r][c] != MARKER) {
                    lineComplete = false;
                    break;
                }
                r += dir.dx;
                c += dir.dy;
            }
            if (lineComplete) {
                return true;
            }
        }
        return false;
    }
}

