/**
 * Reads a 4×4 grid from standard input and checks whether any cell marked with 'x'
 * has a neighboring pair of cells that are respectively '1' and '0' (or '0' then '1')
 * in any of the eight possible directions.
 *
 * The logic of the original program is preserved, but the code has been refactored
 * to improve readability, maintainability and testability.
 */
public class Main {

    /** Size of the grid (fixed 4×4). */
    private static final int SIZE = 4;

    /** Characters used in the input. */
    private static final char EMPTY = '.';
    private static final char OBSTACLE = 'o';
    private static final char MARKED = 'x';

    /** Shared scanner for reading input. */
    private static final Scanner SCANNER = new Scanner(System.in);

    public static void main(String[] args) {
        System.out.println(hasValidPattern() ? "YES" : "NO");
    }

    /** Determines whether any 'x' participates in the required three‑cell pattern. */
    private static boolean hasValidPattern() {
        int[][] grid = readGrid();
        List<Position> markedPositions = collectMarkedPositions(grid);
        return markedPositions.stream()
                .anyMatch(Position::hasAdjacentSequence);
    }

    /** Parses the four input lines into an integer grid representation. */
    private static int[][] readGrid() {
        int[][] grid = new int[SIZE][SIZE];
        for (int row = 0; row < SIZE; row++) {
            String line = SCANNER.nextLine().trim();
            if (line.length() != SIZE) {
                throw new IllegalArgumentException(
                        "Each line must contain exactly " + SIZE + " characters");
            }
            for (int col = 0; col < SIZE; col++) {
                grid[row][col] = translate(line.charAt(col));
            }
        }
        return grid;
    }

    /** Converts an input character into its integer representation. */
    private static int translate(char ch) {
        return switch (ch) {
            case MARKED -> 1;
            case EMPTY -> 0;
            case OBSTACLE -> -1;
            default -> throw new IllegalArgumentException("Invalid character: " + ch);
        };
    }

    /** Gathers the coordinates of all cells that contain 'x' (value 1). */
    private static List<Position> collectMarkedPositions(int[][] grid) {
        List<Position> positions = new ArrayList<>();
        for (int row = 0; row < SIZE; row++) {
            for (int col = 0; col < SIZE; col++) {
                if (grid[row][col] == 1) {
                    positions.add(new Position(row, col));
                }
            }
        }
        return positions;
    }

    /** Simple record to store a grid coordinate. */
    private record Position(int row, int col) {
        /** Checks whether the position participates in a valid sequence of three cells. */
        boolean hasAdjacentSequence(int[][] grid) {
            // All possible directions: down, up, right, left, and the four diagonals
            int[][] directions = {
                    {1, 0},   // down
                    {-1, 0},  // up
                    {0, 1},   // right
                    {0, -1},  // left
                    {1, 1},   // down‑right
                    {-1, -1}, // up‑left
                    {1, -1},  // down‑left
                    {-1, 1}   // up‑right
            };

            for (int[] dir : directions) {
                if (hasTwoStepsInDirection(grid, dir[0], dir[1])) {
                    return true;
                }
            }
            return false;
        }

        /** Returns true if the two cells at (+dx,+dy) and (+2dx,+2dy) contain a 1 followed by a 0
         *  or a 0 followed by a 1, and all three positions are inside the 4×4 grid. */
        private boolean hasTwoStepsInDirection(int[][] grid, int dx, int dy) {
            int step1Row = row + dx;
            int step1Col = col + dy;
            int step2Row = row + 2 * dx;
            int step2Col = col + 2 * dy;

            if (!isInBounds(step1Row, step1Col) || !isInBounds(step2Row, step2Col)) {
                return false;
            }

            int val1 = grid[step1Row][step1Col];
            int val2 = grid[step2Row][step2Col];

            // The pattern we accept is (1,0) or (0,1) across the two steps.
            return (val1 == 1 && val2 == 0) || (val1 == 0 && val2 == 1);
        }

        /** Utility: checks bounds of a given row/column pair. */
        private boolean isInBounds(int r, int c) {
            return r >= 0 && r < SIZE && c >= 0 && c < SIZE;
        }
    }
}

import java.util.Scanner;

/**
 * Reads a 4×4 slice from an 8×8 board and checks whether it contains a
 * sequence of three identical marks ('x') with exactly one empty cell ('.')
 * in any straight line (horizontal, vertical or diagonal). The result is
 * printed as "YES" or "NO".
 */
public class TicketTake {

    /** Size of the underlying board (fixed to 8×8). */
    private static final int BOARD_SIZE = 8;

    /** The rows/columns that constitute the interesting sub‑grid (indices 2‑5). */
    private static final int WINDOW_START = 2;
    private static final int WINDOW_END   = BOARD_SIZE - 2; // 6

    /** Symbols used in the pattern detection. */
    private static final char MARK        = 'x'; // the number we are looking for
    private static final char EMPTY       = '.'; // empty cell

    public static void main(String[] args) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        try (Scanner scanner = new Scanner(System.in)) {

            // Read the four lines that contain the slice we are interested in.
            for (int row = WINDOW_START; row < WINDOW_END; row++) {
                String line = scanner.next();               // token = 4 chars long
                for (int col = WINDOW_START; col < WINDOW_END; col++) {
                    board[row][col] = line.charAt(col - WINDOW_START);
                }
            }
        }

        System.out.println(containsThreeMarksWithOneGap(board) ? "YES" : "NO");
    }

    /**
     * Scans the relevant part of the board for a pattern that consists of three
     * {@code MARK} symbols with exactly one {@code EMPTY} cell in between.
     *
     * @return {@code true} if such a pattern exists, {@code false} otherwise.
     */
    private static boolean containsThreeMarksWithOneGap(char[][] board) {
        for (int i = WINDOW_START; i < WINDOW_END; i++) {
            for (int j = WINDOW_START; j < WINDOW_END; j++) {
                if (matchesAnyPattern(board, i, j)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks whether the 3×3 neighbourhood of {@code (i, j)} contains a pattern
     * with three marks and one gap in any of the eight possible directions.
     *
     * @return {@code true} if a matching pattern is found.
     */
    private static boolean matchesAnyPattern(char[][] board, int i, int j) {
        // The eight possible “three‑in‑a‑row with one gap” configurations.
        // Each entry stores the expected symbols at positions (gapPos, fillPos).
        int[][] gapPositions = {
                {0, 1}, {1, 1}, {2, 1},               // horizontal
                {1, 0}, {1, 1}, {1, 2},               // vertical
                {0, 1}, {1, 1}, {2, 1},               // main diagonal (↘)
                {2, 1}, {1, 1}, {0, 1}                // anti‑diagonal (↙)
        };

        for (int[] offsets : gapPositions) {
            int aOffset = offsets[0];
            int bOffset = offsets[1];
            int cOffset = offsets[2];

            boolean match = isThreeWithOneGap(
                    board[i][j + aOffset],
                    board[i][j + bOffset],
                    board[i][j + cOffset],
                    MARK,
                    EMPTY);

            if (match) {
                return true;
            }
        }
        return false;
    }

    /**
     * Determines whether three cells contain exactly one “gap” (the symbol
     * {@code gapChar}) and two “fill” symbols (the symbol {@code fillChar}).
     *
     * @return {@code true} if the pattern matches.
     */
    private static boolean isThreeWithOneGap(char first,
                                             char second,
                                             char third,
                                             char fillChar,
                                             char gapChar) {
        return (first == gapChar && second == fillChar && third == fillChar) ||
               (first == fillChar && second == gapChar && third == fillChar) ||
               (first == fillChar && second == fillChar && third == gapChar);
    }
}

import java.io.*;
import java.util.*;

public class ProbB implements Runnable {

    /* ---------- constants ---------- */
    private static final int BOARD_SIZE = 4;
    private static final char EMPTY = '.';

    /* ---------- entry point ---------- */
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new ProbB(), "ProbB", 1 << 28);
        thread.start();
        thread.join();
    }

    /* ---------- fields ---------- */
    private static FastScanner fs;
    private static PrintWriter out;

    /* ---------- run method ---------- */
    @Override
    public void run() {
        solve();
        out.close();
    }

    /* ---------- solution ---------- */
    private static void solve() {
        // 1️⃣ Read the 4×4 board
        char[][] rawBoard = readBoard();

        // 2️⃣ Count how many 'x' and 'o' are present
        int countX = countOccurrences(rawBoard, 'x');
        int countO = countOccurrences(rawBoard, 'o');

        // 3️⃣ The character that must complete a three‑in‑a‑row
        char needed = (countX == countO) ? 'x' : 'o';

        // 4️⃣ Enlarge the board so triples that cross the border can be examined
        char[][] extended = enlargeBoard(rawBoard);

        // 5️⃣ Detect any three‑in‑a‑row pattern containing exactly two `needed` and one empty cell
        boolean hasWin = hasThreeInARow(extended, needed);

        // 6️⃣ Output result
        out.println(hasWin ? "YES" : "NO");
    }

    /* ---------- I/O helpers ---------- */
    private static char[][] readBoard() {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int r = 0; r < BOARD_SIZE; r++) {
            String line = fs.nextLine();
            board[r] = line.toCharArray();
        }
        return board;
    }

    private static char[][] enlargeBoard(char[][] board) {
        // Add a one‑cell border of '.' around the original 4×4 board → 6×6
        char[][] extended = new char[BOARD_SIZE + 2][BOARD_SIZE + 2];
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                extended[r + 1][c + 1] = board[r][c];
            }
        }
        return extended;
    }

    private static int countOccurrences(char[][] board, char ch) {
        int cnt = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == ch) cnt++;
            }
        }
        return cnt;
    }

    /* ---------- win detection ---------- */
    /**
     * Returns {@code true} if the enlarged board contains a line of three cells
     * that consist of exactly two occurrences of {@code target} and one {@code EMPTY}
     * cell, in any direction.
     */
    private static boolean hasThreeInARow(char[][] board, char target) {
        int rows = board.length;
        int cols = board[0].length;

        // Horizontal triples
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c + 2 < cols; c++) {
                if (isThreePattern(board[r], c, target)) {
                    return true;
                }
            }
        }

        // Vertical triples
        for (int c = 0; c < cols; c++) {
            for (int r = 0; r + 2 < rows; r++) {
                if (isThreePattern(columnAt(board, r, c), target)) {
                    return true;
                }
            }
        }

        // Main diagonal triples
        for (int r = 0; r + 2 < rows; r++) {
            for (int c = 0; c + 2 < cols; c++) {
                if (isThreePattern(diagonalMain(board, r, c), target)) {
                    return true;
                }
            }
        }

        // Anti‑diagonal triples
        for (int r = 0; r + 2 < rows; r++) {
            for (int c = 2; c < cols; c++) {
                if (isThreePattern(diagonalAnti(board, r, c), target)) {
                    return true;
                }
            }
        }

        return false;
    }

    /** Checks the pattern "..X", ".XX", or "X.." starting at `col` in the given line. */
    private static boolean isThreePattern(char[] line, int col, char target) {
        return (line[col] == EMPTY && line[col + 1] == target && line[col + 2] == target) ||
               (line[col] == target && line[col + 1] == target && line[col + 2] == EMPTY) ||
               (line[col] == target && line[col + 1] == EMPTY && line[col + 2] == target);
    }

    /** Extracts a vertical slice of length 3 starting at (row, col). */
    private static char[] columnAt(char[][] board, int row, int col) {
        char[] colVals = new char[3];
        for (int i = 0; i < 3; i++) {
            colVals[i] = board[row + i][col];
        }
        return colVals;
    }

    /** Extracts a main diagonal of length 3 starting at (row, col). */
    private static char[] diagonalMain(char[][] board, int row, int col) {
        char[] diag = new char[3];
        for (int i = 0; i < 3; i++) {
            diag[i] = board[row + i][col + i];
        }
        return diag;
    }

    /** Extracts an anti‑diagonal of length 3 starting at (row, col). */
    private static char[] diagonalAnti(char[][] board, int row, int col) {
        char[] diag = new char[3];
        for (int i = 0; i < 3; i++) {
            diag[i] = board[row + i][col - i];
        }
        return diag;
    }

    /* ---------- fast scanner ---------- */
    /**
     * Simple, high‑performance scanner that handles whitespace,
     * integers, longs, tokens and whole lines.
     */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (ptr >= len) {
                len = stream.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private boolean isSpace(int ch) {
            return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
        }

        /** Returns the next non‑whitespace token. */
        private String nextToken() {
            int c;
            do {
                c = readByte();
            } while (isSpace(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpace(c));
            return sb.toString();
        }

        /** Returns the next complete line (terminated by '\n' or EOF). */
        private String nextLine() {
            int c;
            do {
                c = readByte();
            } while (isSpace(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpace(c) && c != -1);
            return sb.toString();
        }

        /** Reads a line and parses it as an integer. */
        private int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }
}

import java.util.Scanner;

/**
 * Determines whether the current board configuration can be turned into a
 * winning state for player 'x' by placing a single 'x' into an empty cell ('.').
 *
 * The original logic has been refactored into small, self‑documenting methods.
 * This makes the code easier to test, extend and understand.
 */
public class RoundB {

    /** Size of the board (fixed 4×4). */
    private static final int BOARD_SIZE = 4;

    /** Character representing an empty cell. */
    private static final char EMPTY = '.';

    /** Character representing a placed token. */
    private static final char PLAYER = 'x';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = parseInput(scanner);
            if (canWinByPlacingOneX(board)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Reads 4 lines from {@code scanner}. Each line must contain exactly 4 characters.
     *
     * @return a 4×4 board where each cell is either {@code '.'} or {@code 'x'}.
     * @throws IllegalArgumentException if fewer or more than 4 characters are supplied per line.
     */
    private static char[][] parseInput(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int row = 0; row < BOARD_SIZE; row++) {
            String line = scanner.next();
            if (line.length() != BOARD_SIZE) {
                throw new IllegalArgumentException("Each input line must contain exactly " + BOARD_SIZE + " characters.");
            }
            for (int col = 0; col < BOARD_SIZE; col++) {
                board[row][col] = line.charAt(col);
            }
        }
        return board;
    }

    /**
     * Checks whether placing an 'x' into any empty cell results in a winning
     * configuration for that player.
     *
     * @param board current board state.
     * @return {@code true} if a winning placement exists, otherwise {@code false}.
     */
    private static boolean canWinByPlacingOneX(char[][] board) {
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                if (board[row][col] == EMPTY) {
                    board[row][col] = PLAYER;                 // simulate placement
                    if (hasThreeInRow(board, row, col)
                            || hasThreeInColumn(board, row, col)
                            || hasThreeInDiagonal(board, row, col)) {
                        board[row][col] = EMPTY;                 // restore before returning
                        return true;
                    }
                    board[row][col] = EMPTY;                     // restore board state
                }
            }
        }
        return false;
    }

    /** Checks whether the placed token creates a horizontal sequence of three 'x's. */
    private static boolean hasThreeInRow(char[][] board, int row, int col) {
        // Only need to test the three possible positions that could involve the new token.
        // The token can be the left, middle or right member of the winning trio.
        return (col > 0 && col < BOARD_SIZE - 1 &&                // token has neighbours on both sides
                board[row][col - 1] == PLAYER && board[row][col + 1] == PLAYER) ||
               (col > 1 && board[row][col - 1] == PLAYER && board[row][col - 2] == PLAYER) ||
               (col < BOARD_SIZE - 2 && board[row][col + 1] == PLAYER && board[row][col + 2] == PLAYER);
    }

    /** Checks whether the placed token creates a vertical sequence of three 'x's. */
    private static boolean hasThreeInColumn(char[][] board, int row, int col) {
        return (row > 0 && row < BOARD_SIZE - 1 &&                // token has neighbours above and below
                board[row - 1][col] == PLAYER && board[row + 1][col] == PLAYER) ||
               (row > 1 && board[row - 1][col] == PLAYER && board[row - 2][col] == PLAYER) ||
               (row < BOARD_SIZE - 2 && board[row + 1][col] == PLAYER && board[row + 2][col] == PLAYER);
    }

    /** Checks whether the placed token creates a diagonal (both directions) sequence of three 'x's. */
    private static boolean hasThreeInDiagonal(char[][] board, int row, int col) {
        // Main diagonal (top‑left to bottom‑right)
        boolean mainDiag = (row > 0 && row < BOARD_SIZE - 1 && col > 0 && col < BOARD_SIZE - 1 &&
                board[row - 1][col - 1] == PLAYER && board[row + 1][col + 1] == PLAYER) ||
                (row > 1 && board[row - 1][col - 1] == PLAYER && board[row - 2][col - 2] == PLAYER) ||
                (row < BOARD_SIZE - 2 && board[row + 1][col + 1] == PLAYER && board[row + 2][col + 2] == PLAYER);

        // Anti‑diagonal (top‑right to bottom‑left)
        boolean antiDiag = (row > 0 && row < BOARD_SIZE - 1 && col < BOARD_SIZE - 1 && col > 0 &&
                board[row - 1][col + 1] == PLAYER && board[row + 1][col - 1] == PLAYER) ||
                (row > 1 && board[row - 1][col + 1] == PLAYER && board[row - 2][col + 2] == PLAYER) ||
                (row < BOARD_SIZE - 2 && board[row + 1][col - 1] == PLAYER && board[row + 2][col - 2] == PLAYER);

        return mainDiag || antiDiag;
    }
}

/**
 * Simple wrapper around {@link BufferedReader}/{@link StringTokenizer}
 * that mimics the original {@code FastScanner} but lives in its own file.
 *
 * <p>It is deliberately kept minimal – only the operations used by the
 * refactored program are implemented.
 */
class FastScanner {

    private final BufferedReader br;

    FastScanner(InputStream is) {
        this.br = new BufferedReader(new InputStreamReader(is));
    }

    /** Reads the next token (word). */
    String next() throws IOException {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /** Reads the next line (used only to prime the tokenizer). */
    String nextLine() throws IOException {
        tokenizer = null;
        return br.readLine();
    }

    /** Reads the next integer. */
    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    /** Reads the next character. */
    char nextChar() throws IOException {
        return next().charAt(0);
    }

    // The following fields are package‑private to keep the class tiny.
    // They are reused across calls to {@code next()} without re‑instantiating.
    private StringTokenizer tokenizer;
}

import java.util.Scanner;

/**
 * Tic‑Tac‑Toe helper that checks whether a 4×4 board contains a
 * “potential win” for the player 'x' – i.e. three cells that consist of
 * exactly two 'x' characters and one empty cell ('.').
 * The program reads four lines of length 4 from standard input and prints
 * {@code YES} if such a line exists, otherwise {@code NO}.
 */
public class TicTacToe {

    /** Size of the board (always 4 for this problem). */
    private static final int BOARD_SIZE = 4;

    /** Number of consecutive cells that must form a potential win. */
    private static final int WIN_LENGTH = 3;

    public static void main(String[] args) {
        char[][] board = readBoard();
        boolean hasPotentialWin = hasPotentialWin(board);
        System.out.println(hasPotentialWin ? "YES" : "NO");
    }

    /**
     * Reads a 4×4 board from {@code System.in}.
     * Each line must contain exactly {@value #BOARD_SIZE} characters.
     */
    private static char[][] readBoard() {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        for (int r = 0; r < BOARD_SIZE; r++) {
            String line = scanner.nextLine().trim();
            if (line.length() != BOARD_SIZE) {
                throw new IllegalArgumentException(
                        "Line " + (r + 1) + " must contain exactly " + BOARD_SIZE + " characters");
            }
            for (int c = 0; c < BOARD_SIZE; c++) {
                board[r][c] = line.charAt(c);
            }
        }
        scanner.close();
        return board;
    }

    /**
     * Determines whether the board contains any three‑cell line
     * (horizontal, vertical or diagonal) that consists of exactly two 'x'
     * characters and one empty cell ('.').
     */
    private static boolean hasPotentialWin(char[][] board) {
        // Directions: right, down, down‑right, down‑left
        int[][] dirRow = {0, 1, 1, 1};
        int[][] dirCol = {1, 0, 1, -1};

        // Only start positions that allow a full length‑3 line
        for (int startR = 0; startR <= BOARD_SIZE - WIN_LENGTH; startR++) {
            for (int startC = 0; startC <= BOARD_SIZE - WIN_LENGTH; startC++) {
                for (int d = 0; d < dirRow.length; d++) {
                    if (isPotentialWinLine(board, startR, startC, dirRow[d], dirCol[d])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks a single 3‑cell line starting at {@code (row, col)} and moving
     * {@code (dr, dc)} steps. Returns {@code true} if the three characters
     * are exactly two 'x' and one '.' (in any order).
     */
    private static boolean isPotentialWinLine(char[][] board,
                                              int row, int col,
                                              int dr, int dc) {
        char[] triple = new char[WIN_LENGTH];
        for (int i = 0; i < WIN_LENGTH; i++) {
            triple[i] = board[row + i * dr][col + i * dc];
        }
        // Count 'x' and '.' – the line matches if we have exactly two 'x' and one '.'
        int xCount = 0, dotCount = 0;
        for (char c : triple) {
            if (c == 'x') {
                xCount++;
            } else if (c == '.') {
                dotCount++;
            }
        }
        return xCount == 2 && dotCount == 1;
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;

/**
 * Refactored solution that checks whether a 4×4 board contains a winning
 * pattern (".xx", "xx." or "x.x") on any row, column or diagonal.
 *
 * The code has been split into small, reusable methods to improve
 * readability, maintainability and testability.
 */
public class Solution {

    /** Entry point. */
    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        char[][] board = readBoard(reader);
        boolean hasWinningPattern = hasWinningPattern(board);

        out.println(hasWinningPattern ? "YES" : "NO");
        out.flush();
    }

    /** Reads the 4×4 board from standard input. */
    private static char[][] readBoard(InputReader reader) throws IOException {
        char[][] board = new char[4][4];

        for (int i = 0; i < 4; i++) {
            String line = reader.readLine();
            for (int j = 0; j < 4; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /** Determines whether the board contains any of the winning substrings. */
    private static boolean hasWinningPattern(char[][] board) {
        List<String> allTriples = collectAllTriples(board);

        for (String triple : allTriples) {
            if (containsWinningPattern(triple)) {
                return true;
            }
        }
        return false;
    }

    /** Generates every contiguous 3‑character sequence from rows, columns and diagonals. */
    private static List<String> collectAllTriples(char[][] board) {
        List<String> triples = new ArrayList<>();

        // Horizontal triples
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j <= 1; j++) {
                triples.add(new StringBuilder()
                        .append(board[i][j])
                        .append(board[i][j + 1])
                        .append(board[i][j + 2])
                        .toString());
            }
        }

        // Vertical triples
        for (int j = 0; j < 4; j++) {
            for (int i = 0; i <= 1; i++) {
                triples.add(new StringBuilder()
                        .append(board[i][j])
                        .append(board[i + 1][j])
                        .append(board[i + 2][j])
                        .toString());
            }
        }

        // Diagonal (down‑right) triples
        for (int i = 0; i <= 1; i++) {
            for (int j = 0; j <= 1; j++) {
                triples.add(new StringBuilder()
                        .append(board[i][j])
                        .append(board[i + 1][j + 1])
                        .append(board[i + 2][j + 2])
                        .toString());
            }
        }

        // Diagonal (down‑left) triples
        for (int i = 0; i <= 1; i++) {
            for (int j = 3; j >= 2; j--) {
                triples.add(new StringBuilder()
                        .append(board[i][j])
                        .append(board[i + 1][j - 1])
                        .append(board[i + 2][j - 2])
                        .toString());
            }
        }

        return triples;
    }

    /** Returns true if the given 3‑character string matches any winning pattern. */
    private static boolean containsWinningPattern(String triple) {
        return triple.contains(".xx") || triple.contains("xx.") || triple.contains("x.x");
    }

    /** Fast input helper used by the original code (kept unchanged). */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        int readInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                result = result * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return result * sign;
        }

        String readString() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        String readLine() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return sb.toString();
        }

        boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        // Additional convenience methods (unused here but kept for compatibility)
        double readDouble() { /* omitted for brevity */ }
        long readLong() { /* omitted for brevity */ }
        String next() { return readString(); }
        interface SpaceCharFilter { boolean isSpaceChar(int ch); }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Refactored solution for the “Acontest” problem.
 * <p>
 * The program reads a 4×4 board consisting of the characters ‘x’ and ‘.’.
 * It prints “YES” if there exists any straight line of three consecutive cells
 * that contains exactly two ‘x’ and one ‘.’ (in any order); otherwise it prints
 * “NO”.  The detection is performed for all four possible directions
 * (horizontal, vertical, and the two diagonals).
 * </p>
 */
public class Acontest {

    /** Size of the board (fixed to 4 × 4). */
    private static final int SIZE = 4;

    /** Symbol for a filled cell. */
    private static final char X = 'x';

    /** Symbol for an empty cell. */
    private static final char DOT = '.';

    /** Directions used for scanning the board. */
    private static final int[][] DIRS = {
            {0, 1},   // horizontal
            {1, 0},   // vertical
            {1, 1},   // diagonal down‑right
            {1, -1}   // diagonal down‑left
    };

    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee proper closing of I/O streams.
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            new Acontest().run(scanner, writer);
        }
    }

    /** Reads the whole board from the supplied {@link Scanner}. */
    private char[][] readBoard(Scanner scanner) {
        char[][] board = new char[SIZE][SIZE];
        for (int i = 0; i < SIZE; i++) {
            String line = scanner.next();
            for (int j = 0; j < SIZE; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /** Orchestrates the whole computation and writes the result. */
    public void run(Scanner in, PrintWriter out) {
        char[][] board = readBoard(in);
        boolean found = containsPattern(board);
        out.print(found ? "YES" : "NO");
        out.flush();                     // Ensure output is flushed before exiting.
    }

    /** Checks whether any 3‑cell line on the board matches the required pattern. */
    private boolean containsPattern(char[][] board) {
        for (int[] dir : DIRS) {
            int dx = dir[0];
            int dy = dir[1];

            for (int r = 0; r < SIZE; r++) {
                for (int c = 0; c < SIZE; c++) {
                    int r2 = r + 2 * dx;
                    int c2 = c + 2 * dy;

                    // Verify that the whole three‑cell segment stays inside the board.
                    if (r2 < 0 || r2 >= SIZE || c2 < 0 || c2 >= SIZE) {
                        continue;
                    }

                    char[] segment = {
                            board[r][c],
                            board[r + dx][c + dy],
                            board[r + 2 * dx][c + 2 * dy]
                    };

                    if (isTwoXOneDot(segment)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Determines whether the given three‑character segment contains exactly
     *  two ‘x’ characters and one ‘.’ character. */
    private boolean isTwoXOneDot(char[] segment) {
        int xCount = 0;
        int dotCount = 0;

        for (char ch : segment) {
            if (ch == X) {
                xCount++;
            } else if (ch == DOT) {
                dotCount++;
            }
        }
        return xCount == 2 && dotCount == 1;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Utility that checks whether a 4×4 board contains a winning pattern.
 *
 * <p>The program reads four lines from {@code System.in}, each line consisting of
 * exactly four characters (expected characters are {@code 'x'}, {@code 'o'} and
 * {@code '.'}).  If any horizontal, vertical or diagonal line of length at least
 * three satisfies the winning conditions, the program prints {@code "YES"},
 * otherwise it prints {@code "NO"}.</p>
 */
public class ConnectFourUtil {

    /** Size of the board (fixed 4×4). */
    private static final int BOARD_SIZE = 4;

    /** Entry point – reads the board and prints the result. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            if (hasWinningPattern(board)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Reads a 4×4 board from the supplied {@link Scanner}. */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][];
        for (int r = 0; r < BOARD_SIZE; r++) {
            board[r] = scanner.next().trim().toCharArray();
        }
        return board;
    }

    /** Determines whether any of the four directions contains a winning line. */
    private static boolean hasWinningPattern(char[][] board) {
        List<Character> line = new ArrayList<>(BOARD_SIZE);

        // Check horizontally
        if (checkRows(board, line)) return true;

        // Check vertically
        if (checkColumns(board, line)) return true;

        // Check diagonals that go down‑right
        if (checkDiagonalDownRight(board, line)) return true;

        // Check diagonals that go down‑left
        if (checkDiagonalDownLeft(board, line)) return true;

        return false;
    }

    /** Checks all rows for a winning pattern. */
    private static boolean checkRows(char[][] board, List<Character> line) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            line.clear();
            for (int c = 0; c < BOARD_SIZE; c++) {
                line.add(board[r][c]);
            }
            if (line.size() > 2 && isWinning(line)) {
                return true;
            }
        }
        return false;
    }

    /** Checks all columns for a winning pattern. */
    private static boolean checkColumns(char[][] board, List<Character> line) {
        for (int c = 0; c < BOARD_SIZE; c++) {
            line.clear();
            for (int r = 0; r < BOARD_SIZE; r++) {
                line.add(board[r][c]);
            }
            if (line.size() > 2 && isWinning(line)) {
                return true;
            }
        }
        return false;
    }

    /** Checks all down‑right diagonals. */
    private static boolean checkDiagonalDownRight(char[][] board, List<Character> line) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                line.clear();
                collectDownRight(board, r, c, line);
                if (line.size() > 2 && isWinning(line)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Checks all down‑left diagonals. */
    private static boolean checkDiagonalDownLeft(char[][] board, List<Character> line) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                line.clear();
                collectDownLeft(board, r, c, line);
                if (line.size() > 2 && isWinning(line)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Populates {@code collector} with the diagonal that goes down‑right
     *  starting at {@code (row, col)}. */
    private static void collectDownRight(char[][] board, int row, int col, List<Character> collector) {
        int r = row, c = col;
        while (isInside(r, c)) {
            collector.add(board[r][c]);
            r++;
            c++;
        }
    }

    /** Populates {@code collector} with the diagonal that goes down‑left
     *  starting at {@code (row, col)}. */
    private static void collectDownLeft(char[][] board, int row, int col, List<Character> collector) {
        int r = row, c = col;
        while (isInside(r, c)) {
            collector.add(board[r][c]);
            r++;
            c--;
        }
    }

    /** Returns {@code true} if the current line satisfies the winning conditions. */
    private static boolean isWinning(List<Character> line) {
        int xCount = 0, oCount = 0, dotCount = 0;
        for (char ch : line) {
            if (ch == 'x') {
                xCount++;
            } else if (ch == 'o') {
                oCount++;
            } else if (ch == '.') {
                dotCount++;
            }
        }

        int size = line.size();

        // Special case: exactly three cells, two 'x' and one empty ('.')
        if (size == 3 && xCount == 2 && dotCount == 1) {
            return true;
        }

        // General case for four‑cell lines
        if (size == 4 && oCount <= 1 && xCount >= 2) {
            // Positions 1 and 2 (0‑based) must not be 'o' – matches original logic
            if (!line.get(1).equals('o') && !line.get(2).equals('o')) {
                return true;
            }
            // If there is no 'o' at all, need an 'x' at position 1 or 2
            if (oCount == 0 && (line.get(1).equals('x') || line.get(2).equals('x'))) {
                return true;
            }
        }

        return false;
    }

    /** Utility method used by the diagonal collectors. */
    private static boolean isInside(int x, int y) {
        return x >= 0 && x < BOARD_SIZE && y >= 0 && y < BOARD_SIZE;
    }
}

import java.util.List;
import java.util.Scanner;
import java.util.stream.Collectors;

/**
 * Refactored solution for the “3‑in‑a‑row” checker.
 *
 * <p>
 *   • The input consists of four lines, each containing four characters (x or .).
 *   • A winning line is any contiguous three‑character substring that contains
 *     exactly two ‘x’ and one ‘.’ – i.e. the patterns {@code "xx."}, {@code "x.x"} or
 *     {@code ".xx"}.
 *   • The program checks all horizontal, vertical and diagonal triples and prints
 *     {@code "YES"} if any of them matches, otherwise {@code "NO"}.
 * </p>
 */
public class Main {

    /** Patterns that denote a winning triple. */
    private static final List<String> WINNING_PATTERNS = List.of("xx.", "x.x", ".xx");

    /** Compile a regex that matches any of the winning patterns. */
    private static final String WINNING_REGEX = String.join("|", WINNING_PATTERNS);

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            // Read exactly four lines; each line must be four characters long.
            List<String> rows = scanner.nextLines().stream()
                    .limit(4)
                    .collect(Collectors.toList());

            // Convert to a 4×4 character board for easier processing.
            char[][] board = rows.stream()
                    .map(String::toCharArray)
                    .toArray(char[][]::new);

            System.out.println(evaluate(board) ? "YES" : "NO");
        }
    }

    /**
     * Determines whether the supplied board contains a winning three‑in‑a‑row.
     *
     * @param board a 4×4 character grid
     * @return {@code true} if any horizontal, vertical or diagonal triple matches
     *         one of the winning patterns
     */
    private static boolean evaluate(char[][] board) {
        // Check all horizontal triples.
        if (checkDirection(board, 0, 1)) return true;

        // Check all vertical triples.
        if (checkDirection(board, 1, 0)) return true;

        // Check main diagonal direction (top‑left → bottom‑right).
        if (checkDirection(board, 1, 1)) return true;

        // Check anti‑diagonal direction (top‑right → bottom‑left).
        if (checkDirection(board, -1, 1)) return true;

        return false;
    }

    /**
     * Scans the board along a given direction for any 3‑character substring that
     * matches one of the winning patterns.
     *
     * @param board      the 4×4 grid
     * @param rowStep    step size when incrementing the row index (normally 0, 1 or -1)
     * @param colStep    step size when incrementing the column index (normally 0, 1 or -1)
     * @return {@code true} if a winning line is found
     */
    private static boolean checkDirection(char[][] board, int rowStep, int colStep) {
        // For each starting cell that can generate a length‑4 line in the given direction.
        for (int r = 0; r < 4; r++) {
            for (int c = 0; c < 4; c++) {
                // Verify that a full length‑4 line stays inside the board.
                int maxR = r + 3 * rowStep;
                int maxC = c + 3 * colStep;
                if (maxR < 0 || maxR >= 4 || maxC < 0 || maxC >= 4) {
                    continue;
                }

                // Build the 4‑character line.
                StringBuilder lineBuilder = new StringBuilder();
                for (int i = 0; i < 4; i++) {
                    int nr = r + i * rowStep;
                    int nc = c + i * colStep;
                    lineBuilder.append(board[nr][nc]);
                }
                String line = lineBuilder.toString();

                // Examine every length‑3 window of that line.
                for (int start = 0; start <= 1; start++) {
                    String window = line.substring(start, start + 3);
                    if (window.matches("(?=.*x)(?=.*x)(?=.*\\.)(.{3})")) {
                        // The regex above checks that the window contains exactly
                        // two 'x' and one '.' (order does not matter).
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** constant for the board size used in the problem */
    private static final int BOARD_SIZE = 4;
    /** character that represents an occupied cell */
    private static final char X = 'x';
    /** character that represents an empty cell */
    private static final char EMPTY = '.';

    public static void main(String[] args) throws Exception {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int t = reader.readInt();                     // number of test cases
        while (t-- > 0) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

            // read four lines, each containing four characters
            for (int r = 0; r < BOARD_SIZE; r++) {
                String line = reader.readString().trim();
                for (int c = 0; c < BOARD_SIZE; c++) {
                    board[r][c] = line.charAt(c);
                }
            }

            out.println(hasWinningPattern(board) ? "YES" : "NO");
        }

        out.flush();
        out.close();
    }

    /**
     * Detects whether the board contains any of the patterns required by the original
     * specification:
     * <ul>
     *   <li>When the examined cell is {@code X}, exactly one of the next two cells
     *       in a straight line must be {@code X} and the other must be {@code .}.</li>
     *   <li>When the examined cell is {@code .}, both of the next two cells must be
     *       {@code X}.</li>
     * </ul>
     *
     * @param b the current 4×4 board
     * @return {@code true} if at least one qualifying pattern is found
     */
    private static boolean hasWinningPattern(char[][] b) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                // explore all 8 directions (excluding the zero‑vector)
                for (int dr = -1; dr <= 1; dr++) {
                    for (int dc = -1; dc <= 1; dc++) {
                        if (dr == 0 && dc == 0) {
                            continue;
                        }
                        // make sure the whole 3‑cell sequence stays inside the board
                        if (!isInside(r + 2 * dr, c + 2 * dc)) {
                            continue;
                        }

                        char start = b[r][c];
                        char next1 = b[r + dr][c + dc];
                        char next2 = b[r + 2 * dr][c + 2 * dc];

                        if (start == X) {
                            // need exactly one more X among the following two cells
                            int xCount = (next1 == X ? 1 : 0) + (next2 == X ? 1 : 0);
                            if (xCount == 1 && (next1 == EMPTY || next2 == EMPTY)) {
                                return true;
                            }
                        } else if (start == EMPTY) {
                            // need both following cells to be X
                            if (next1 == X && next2 == X) {
                                return true;
                            }
                        }
                    }
                }
            }
        }
        return false;
    }

    /** Helper that checks whether a given coordinate lies inside the 4×4 board. */
    private static boolean isInside(int row, int col) {
        return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE;
    }
}

