        static boolean diag1Match(char[][] board, int r, int c) {
            if (!inBounds(r - 1, c - 1) || !inBounds(r + 1, c + 1)) {
                return false;
            }
            return isMatch(String.valueOf(board[r - 1][c - 1]), "x", String.valueOf(board[r + 1][c + 1]));
