import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.List;

/**
 * Reads a 4×4 board from standard input and reports whether any straight line
 * of length three contains exactly two 'x' characters and one '.' character.
 */
public class Checker {

    private static final int SIZE = 4;               // board dimension
    private static final int LINE_LENGTH = 3;        // how many cells we inspect
    private static final char MARK = 'x';            // character to count
    private static final char EMPTY = '.';           // character to count

    /** All eight directions in which a line of three cells can extend. */
    private enum Direction {
        VERTICAL_UP(-1, 0),
        VERTICAL_DOWN(1, 0),
        HORIZONTAL_LEFT(0, -1),
        HORIZONTAL_RIGHT(0, 1),
        DIAGONAL_UP_LEFT(-1, -1),
        DIAGONAL_UP_RIGHT(-1, 1),
        DIAGONAL_DOWN_LEFT(1, -1),
        DIAGONAL_DOWN_RIGHT(1, 1);

        private final int rowStep;
        private final int colStep;

        Direction(int rowStep, int colStep) {
            this.rowStep = rowStep;
            this.colStep = colStep;
        }

        int rowStep() { return rowStep; }
        int colStep() { return colStep; }
    }

    /** Simple bounds helper – keeps the main logic tidy. */
    private static final class Bounds {
        static boolean isInside(int row, int col) {
            return row >= 0 && row < SIZE && col >= 0 && col < SIZE;
        }
    }

    public static void main(String[] args) throws IOException {
        char[][] grid = readGrid();
        System.out.println(hasThreeMatching(grid) ? "YES" : "NO");
    }

    /** Reads exactly SIZE lines of input (each of at least SIZE characters). */
    private static char[][] readGrid() throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] grid = new char[SIZE][SIZE];
            for (int i = 0; i < SIZE; i++) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Expected " + SIZE + " lines of input.");
                }
                grid[i] = line.substring(0, SIZE).toCharArray(); // ignore extra chars
            }
            return grid;
        }
    }

    /** Determines whether any 3‑cell line contains exactly 2 'x' and 1 '.'. */
    private static boolean hasThreeMatching(char[][] grid) {
        for (int r = 0; r < SIZE; r++) {
            for (int c = 0; c < SIZE; c++) {
                if (checkFrom(grid, r, c)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Checks all eight directions starting from (row, col). */
    private static boolean checkFrom(char[][] grid, int startRow, int startCol) {
        for (Direction dir : Direction.values()) {
            int xCount = 0;
            int dotCount = 0;

            int r = startRow;
            int c = startCol;
            for (int step = 0; step < LINE_LENGTH; step++) {
                if (!Bounds.isInside(r, c)) {
                    break; // out of board – this direction is invalid from this start
                }
                char cell = grid[r][c];
                if (cell == MARK) {
                    xCount++;
                } else if (cell == EMPTY) {
                    dotCount++;
                }
                r += dir.rowStep();
                c += dir.colStep();
            }

            if (xCount == 2 && dotCount == 1) {
                return true; // found a qualifying line
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * The program reads a 4×4 board, tries to place an 'x' on every empty
 * cell (represented by '.') and checks whether such a placement creates
 * a line of three 'x's in any of the eight possible directions.
 * If it can, it prints "YES", otherwise it prints "NO".
 */
public class B {

    /** Size of the board (fixed 4×4). */
    private static final int BOARD_SIZE = 4;

    /** All eight directions used for line checking. */
    private static final int[][] DIRECTIONS = {
            {0, 1},   // right
            {1, 0},   // down
            {1, 1},   // down‑right
            {1, -1},  // down‑left
            {0, -1},  // left
            {-1, 0},  // up
            {-1, -1}, // up‑left
            {-1, 1}   // up‑right
    };

    /**
     * Entry point of the program.
     *
     * @param args command line arguments (not used)
     */
    public static void main(String[] args) throws Exception {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            if (canWinByPlacingX(board)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Reads a 4×4 board from the standard input. */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int r = 0; r < BOARD_SIZE; ++r) {
            String line = scanner.next();
            for (int c = 0; c < BOARD_SIZE; ++c) {
                board[r][c] = line.charAt(c);
            }
        }
        return board;
    }

    /**
     * Determines whether placing an 'x' on any empty cell yields three
     * consecutive 'x's in any direction.
     *
     * @param board the current board state
     * @return {@code true} if a winning move exists, otherwise {@code false}
     */
    private static boolean canWinByPlacingX(char[][] board) {
        for (int r = 0; r < BOARD_SIZE; ++r) {
            for (int c = 0; c < BOARD_SIZE; ++c) {
                if (board[r][c] == '.') {
                    if (placingCreatesThreeInLine(board, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Temporarily places an 'x' at (row, col), checks for a line of three
     * 'x's and then restores the original board state.
     *
     * @param board the board to test on
     * @param row   row index of the candidate move
     * @param col   column index of the candidate move
     * @return {@code true} if the placement creates a winning line
     */
    private static boolean placingCreatesThreeInLine(char[][] board, int row, int col) {
        board[row][col] = 'x';                     // place the move
        try {
            for (int[] dir : DIRECTIONS) {
                for (int startR = 0; startR < BOARD_SIZE; ++startR) {
                    for (int startC = 0; startC < BOARD_SIZE; ++startC) {
                        if (isThreeXSequence(board, startR, startC, dir)) {
                            return true;          // winning line found
                        }
                    }
                }
            }
            return false;                         // no winning line
        } finally {
            board[row][col] = '.';                 // restore original state
        }
    }

    /**
     * Checks whether starting at (startR, startC) and moving in the given
     * direction we encounter exactly three consecutive 'x' cells.
     *
     * @param board    the board under test
     * @param startR   starting row
     * @param startC   starting column
     * @param dir      direction vector (dx, dy)
     * @return {@code true} if the three cells are all 'x'
     */
    private static boolean isThreeXSequence(char[][] board,
                                            int startR, int startC,
                                            int[] dir) {
        for (int step = 0; step < 3; ++step) {
            int r = startR + step * dir[0];
            int c = startC + step * dir[1];
            if (r < 0 || r >= BOARD_SIZE || c < 0 || c >= BOARD_SIZE) {
                return false;                     // out of bounds
            }
            if (board[r][c] != 'x') {
                return false;                     // not an 'x'
            }
        }
        return true;                                // three 'x's found
    }
}

import java.io.*;
import java.util.*;

public class IlyaAndTicTacToeGame {
    private static final int BOARD_SIZE = 4;
    private static InputReader scanner;
    private static PrintWriter out;

    public static void main(String[] args) {
        scanner = new InputReader(System.in);
        out = new PrintWriter(System.out);
        char[][] board = readBoard();

        boolean canWin = false;
        for (int i = 0; i < BOARD_SIZE && !canWin; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == '.') {
                    board[i][j] = 'x';
                    if (isWinningPosition(board)) {
                        canWin = true;
                        break;
                    }
                    board[i][j] = '.';
                }
            }
        }
        out.println(canWin ? "YES" : "NO");
        out.close();
    }

    private static char[][] readBoard() {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            board[i] = scanner.readString().toCharArray();
        }
        return board;
    }

    private static boolean isWinningPosition(char[][] board) {
        int n = board.length;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                // horizontal
                if (c + 2 < n && hasThreeConsecutive(board, r, c, 0, 1)) {
                    return true;
                }
                // vertical
                if (r + 2 < n && hasThreeConsecutive(board, r, c, 1, 0)) {
                    return true;
                }
                // diagonal down‑right
                if (r + 2 < n && c + 2 < n && hasThreeConsecutive(board, r, c, 1, 1)) {
                    return true;
                }
                // diagonal down‑left
                if (r + 2 < n && c - 2 >= 0 && hasThreeConsecutive(board, r, c, 1, -1)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean hasThreeConsecutive(char[][] board, int startRow, int startCol, int dr, int dc) {
        if (board[startRow][startCol] != 'x') {
            return false;
        }
        for (int step = 1; step <= 2; step++) {
            int r = startRow + step * dr;
            int c = startCol + step * dc;
            if (r < 0 || r >= board.length || c < 0 || c >= board[0].length) {
                return false;
            }
            if (board[r][c] != 'x') {
                return false;
            }
        }
        return true;
    }

    /** Simple fast scanner for competitive programming */
    private static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int curPos = 0, bytesRead = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (curPos >= bytesRead) {
                bytesRead = stream.read(buffer);
                curPos = 0;
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[curPos++];
        }

        int nextInt() throws IOException {
            int c = readByte();
            while (isSpace(c)) c = readByte();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            while (!isSpace(c)) {
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return result * sign;
        }

        String readString() throws IOException {
            int c = readByte();
            while (isSpace(c)) c = readByte();
            StringBuilder sb = new StringBuilder();
            while (!isSpace(c)) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

/**
 * Checks whether a 4×4 sub‑grid of a 6×6 board contains a line of three or more
 * adjacent 'x' characters in any of the eight directions. An empty cell ('.')
 * may be used only once to break a non‑continuous sequence.
 *
 * The program reads a 6×6 board from standard input (each line may contain
 * additional whitespace) and prints {@code YES} if such a line exists,
 * otherwise {@code NO}.
 */
public final class Main {

    /** Size of the board (fixed 6×6) */
    private static final int BOARD_SIZE = 6;

    /** Directions: N, S, E, W, NE, NW, SE, SW */
    private static final int[][] DIRECTIONS = {
            {1, 0},   // down
            {-1, 0},  // up
            {0, 1},   // right
            {0, -1},  // left
            {1, 1},   // down‑right
            {1, -1},  // down‑left
            {-1, 1},  // up‑right
            {-1, -1}  // up‑left
    };

    /** Cell that represents an empty position on the board */
    private static final char EMPTY = '.';

    /** Character that represents a filled cell */
    private static final char FILLED = 'x';

    private Main() {
        // Utility class – no instances
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        char[][] board = readBoard(scanner);
        boolean found = containsThreeInRow(board);
        System.out.println(found ? "YES" : "NO");
    }

    /**
     * Reads a 6×6 board from the scanner. The board coordinates are
     * 1‑based in the original code; we keep that convention for clarity.
     */
    private static char[][] readBoard(FastScanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        for (int row = 1; row <= 4; row++) {
            String line = scanner.next();
            for (int col = 1; col <= 4; col++) {
                board[row][col] = line.charAt(col - 1);
            }
        }
        return board;
    }

    /**
     * Determines whether any 4×4 sub‑grid contains a sequence of three or more
     * adjacent <code>FILLED</code> cells. An <code>EMPTY</code> cell may be used
     * at most once to connect otherwise separated filled cells.
     *
     * @param board the full 6×6 board
     * @return {@code true} if a qualifying line exists
     */
    private static boolean containsThreeInRow(char[][] board) {
        for (int row = 1; row <= 4; row++) {
            for (int col = 1; col <= 4; col++) {
                for (int dirIdx = 0; dirIdx < DIRECTIONS.length; dirIdx++) {
                    if (looksForThree(board, row, col, dirIdx)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Recursively walks in a fixed direction looking for a run of filled cells.
     * An empty cell may be used only once to bridge a gap.
     *
     * @param board      the full board
     * @param y          current row (1‑based)
     * @param x          current column (1‑based)
     * @param dirIdx     index of the direction vector to follow
     * @param lengthSoFar number of filled cells seen consecutively (including
     *                    the start cell)
     * @param hasUsedEmpty whether an empty cell has already been consumed
     * @return {@code true} if a run of at least three filled cells is found
     */
    private static boolean looksForThree(char[][] board,
                                         int y, int x,
                                         int dirIdx,
                                         int lengthSoFar,
                                         boolean hasUsedEmpty) {
        // Success condition – we have gathered a run of three filled cells.
        if (lengthSoFar == 3) {
            return true;
        }

        // Out‑of‑bounds guard (the board is only 6×6, but we may step outside
        // while exploring).
        int ny = y + DIRECTIONS[dirIdx][0];
        int nx = x + DIRECTIONS[dirIdx][1];
        if (!isInside board, ny, nx) {
            return false;
        }

        char current = board[ny][nx];
        if (current == EMPTY) {
            // An empty cell can only be used once; if we already consumed it,
            // this path is invalid.
            if (hasUsedEmpty) {
                return false;
            }
            // Mark that we have used the empty cell and continue.
            return looksForThree(board, ny, nx, dirIdx, lengthSoFar, true);
        }

        // Only 'x' characters are allowed to continue the sequence.
        if (current != FILLED) {
            return false;
        }

        // Continue exploring in the same direction.
        return looksForThree(board, ny, nx, dirIdx, lengthSoFar + 1, hasUsedEmpty);
    }

    /** Simple bounds check for the 6×6 board. */
    private static boolean isInside(char[][] board, int y, int x) {
        return 0 <= y && y < BOARD_SIZE && 0 <= x && x < BOARD_SIZE;
    }
}

/**
 * Minimal scanner that skips non‑printable characters and provides fast
 * access to the next token. It is deliberately kept unchanged from the
 * original implementation to avoid altering the I/O behaviour.
 */
class FastScanner {
    private final InputStream in = System.in;
    private int ptr = 0;
    private int buflen = 0;
    private final byte[] buffer = new byte[1024];
    private boolean eos = false;
    private String debug; // can be set externally for testing

    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }
        ptr = 0;
        try {
            if (debug != null) {
                buflen = debug.length();
                buffer = debug.getBytes();
                debug = "";
                eos = true;
            } else {
                buflen = in.read(buffer);
            }
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
        if (buflen <= 0) {
            eos = true;
            return false;
        }
        return true;
    }

    private int readByte() {
        if (hasNextByte()) {
            return buffer[ptr++];
        }
        return -1;
    }

    private static boolean isPrintableChar(int c) {
        return 33 <= c && c <= 126;
    }

    private void skipUnprintable() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr])) {
            ptr++;
        }
    }

    public boolean isEOS() {
        return eos;
    }

    public boolean hasNext() {
        skipUnprintable();
        return hasNextByte();
    }

    public String next() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public int nextInt() {
        return (int) nextLong();
    }

    public long nextLong() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        long n = 0;
        boolean negative = false;
        int b = readByte();
        if (b == '-') {
            negative = true;
            b = readByte();
        }
        if (b < '0' || b > '9') {
            throw new NumberFormatException();
        }
        while (true) {
            if (b >= '0' && b <= '9') {
                n *= 10;
                n += b - '0';
            } else if (b == -1 || !isPrintableChar(b)) {
                return negative ? -n : n;
            } else {
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original PROBLEM_B.
 *
 * <p>
 *   Board representation:
 *   <ul>
 *     <li>'x'  → {@code PLAYER} (value {@code 1})</li>
 *     <li>'o'  → {@code OBSTRUCTOR} (value {@code 2}) – ignored by win checks</li>
 *     <li>any other character → {@code EMPTY} (value {@code 0})</li>
 *   </ul>
 *   The program tries to place a {@code PLAYER} mark in each {@code EMPTY} cell
 *   and checks whether that creates a line of three consecutive {@code PLAYER}
 *   marks. If such a line exists it prints {@code "YES"}, otherwise it prints
 *   {@code "NO"}.
 * </p>
 */
public class PROBLEM_B {

    /** Size of the square board (4 × 4). */
    private static final int SIZE = 4;

    /** Value used for a player's mark. */
    private static final int PLAYER = 1;

    /** Value used for an obstacle (the original 'o'). */
    private static final int OBSTRUCTOR = 2;

    /** Value used for an empty cell. */
    private static final int EMPTY = 0;

    /** The playing board. */
    private static int[][] board = new int[SIZE][SIZE];

    /** Entry point. */
    public static void main(String[] args) {
        // Scanner is used with try‑with‑resources to guarantee closure.
        try (Scanner sc = new Scanner(System.in)) {
            readBoard(sc);
            if (canCreateThreeInLine()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Reads four lines from {@code scanner} and fills {@code board}. */
    private static void readBoard(Scanner scanner) {
        for (int row = 0; row < SIZE; row++) {
            String line = scanner.next();
            for (int col = 0; col < SIZE; col++) {
                board[row][col] = map(line.charAt(col));
            }
        }
    }

    /** Maps a character read from input to its integer representation. */
    private static int map(char ch) {
        if (ch == 'x') {
            return PLAYER;
        }
        if (ch == 'o') {
            return OBSTRUCTOR;
        }
        return EMPTY;
    }

    /** Tries to place a {@code PLAYER} in each empty cell and checks for a win. */
    private static boolean canCreateThreeInLine() {
        for (int r = 0; r < SIZE; r++) {
            for (int c = 0; c < SIZE; c++) {
                if (board[r][c] == EMPTY) {
                    board[r][c] = PLAYER;                // tentative move
                    boolean win = hasThreeInLine(PLAYER);
                    board[r][c] = EMPTY;                 // undo move
                    if (win) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks whether there exists any three‑cell line that consists solely of
     * {@code PLAYER} marks. The method examines all possible horizontal,
     * vertical and diagonal triples that fit inside a 4×4 board.
     *
     * @return {@code true} if at least one such line exists.
     */
    private static boolean hasThreeInLine(int player) {
        // Directions: right, down, down‑right, down‑left and the opposite directions.
        int[] dr = {0, 1, 1, 1, 1, 0, -1, -1};
        int[] dc = {1, 0, 1, 1, 0, -1, -1, -1};

        for (int r = 0; r < SIZE; r++) {
            for (int c = 0; c < SIZE; c++) {
                for (int dir = 0; dir < dr.length; dir++) {
                    int r1 = r + dr[dir];
                    int c1 = c + dc[dir];
                    int r2 = r + 2 * dr[dir];
                    int c2 = c + 2 * dc[dir];

                    // Skip if the third cell would be outside the board.
                    if (r2 < 0 || r2 >= SIZE || c2 < 0 || c2 >= SIZE) {
                        continue;
                    }

                    int sum = board[r][c] + board[r1][c1] + board[r2][c2];
                    if (sum == 3) { // three PLAYER cells (each value = 1)
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.Locale;
import java.util.StringTokenizer;

/**
 * Refactored solution that checks whether any three‑character line
 * (horizontally, vertically or diagonally) on a 4×4 board has a
 * combined ASCII value of 286.
 *
 * The program keeps the original behaviour but is easier to read,
 * maintain and extend.
 */
public class Main {

    /** size of the square board */
    private static final int SIZE = 4;
    /** The required sum of three character codes */
    private static final int TARGET_SUM = 286;

    /** Buffered reader for fast input */
    private BufferedReader reader;
    /** Tokeniser for the current input line */
    private StringTokenizer tokenizer;
    /** Buffered writer for output */
    private PrintWriter out;

    public static void main(String[] args) throws IOException {
        Locale.setDefault(Locale.US);
        new Main().solve();
    }

    /** Main driver – parses input, runs the logic and prints the answer. */
    public void solve() throws IOException {
        initIO();

        int[][] grid = readGrid();
        if (hasTargetThreeSum(grid)) {
            out.println("YES");
        } else {
            out.println("NO");
        }

        out.flush();
    }

    /** Reads a 4×4 integer matrix where each cell is supplied as a 4‑character string. */
    private int[][] readGrid() throws IOException {
        int[][] grid = new int[SIZE][SIZE];
        for (int row = 0; row < SIZE; row++) {
            String token = nextToken();               // e.g. "1234"
            for (int col = 0; col < SIZE; col++) {
                grid[row][col] = token.charAt(col);     // store the ASCII code
            }
        }
        return grid;
    }

    /** Checks all possible 3‑character lines for the required sum. */
    private boolean hasTargetThreeSum(int[][] grid) {
        // Horizontal lines
        for (int r = 0; r < SIZE; r++) {
            for (int c = 0; c <= SIZE - 3; c++) {
                if (sumAt(grid, r, c, 0, 1) == TARGET_SUM) {
                    return true;
                }
            }
        }

        // Vertical lines
        for (int c = 0; c < SIZE; c++) {
            for (int r = 0; r <= SIZE - 3; r++) {
                if (sumAt(grid, r, c, 1, 0) == TARGET_SUM) {
                    return true;
                }
            }
        }

        // Main diagonals (top‑left → bottom‑right)
        for (int r = 0; r <= SIZE - 3; r++) {
            for (int c = 0; c <= SIZE - 3; c++) {
                if (sumAt(grid, r, c, 1, 1) == TARGET_SUM) {
                    return true;
                }
            }
        }

        // Anti‑diagonals (top‑right → bottom‑left)
        for (int r = 0; r <= SIZE - 3; r++) {
            for (int c = 2; c < SIZE; c++) {
                if (sumAt(grid, r, c, 1, -1) == TARGET_SUM) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Returns the sum of three consecutive cells starting at (row, col)
     * and moving (deltaRow, deltaCol) steps each time.
     */
    private int sumAt(int[][] grid, int row, int col, int deltaRow, int deltaCol) {
        int sum = 0;
        for (int i = 0; i < 3; i++) {
            int curRow = row + i * deltaRow;
            int curCol = col + i * deltaCol;
            sum += grid[curRow][curCol];
        }
        return sum;
    }

    /** Initializes the input and output streams. */
    private void initIO() throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
    }

    /** Fast tokeniser – returns the next token or {@code null} on EOF. */
    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Reads a 4×4 board from standard input and determines whether any
 * winning triple of three consecutive symbols exists around a cell.
 * The original logic that counted 'x' as +1 and 'o' as –1 and required
 * a balance of at least 2 is preserved.
 */
public class TicTacToeChecker {

    /** Size of the board (the program works with 4 rows and 4 columns). */
    private static final int BOARD_SIZE = 4;

    /**
     * Entry point of the program.
     *
     * @param args command‑line arguments (unused)
     * @throws IOException if an I/O error occurs while reading input
     */
    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee the reader is closed.
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in))) {

            char[][] board = readBoard(reader);
            if (hasWinningPattern(board)) {
                System.out.println("YES");
                System.exit(0);
            }
            System.out.println("NO");
        }
    }

    /**
     * Reads exactly {@code BOARD_SIZE} lines from the supplied reader,
     * converting each line to a character array that represents a row of the board.
     *
     * @param reader a {@link BufferedReader} supplying the board data
     * @return a 2‑dimensional {@code char}`[BOARD_SIZE][BOARD_SIZE]` array
     * @throws IOException if an I/O error occurs while reading
     */
    private static char[][] readBoard(BufferedReader reader) throws IOException {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = reader.readLine();
            board[i] = (line != null) ? line.toCharArray() : new char[BOARD_SIZE];
        }
        return board;
    }

    /**
     * Determines whether any cell on the board participates in a winning
     * triple (horizontal, vertical or diagonal) according to the original
     * counting semantics.
     *
     * @param board the game board
     * @return {@code true} if a winning pattern exists, {@code false} otherwise
     */
    private static boolean hasWinningPattern(char[][] board) {
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                if (isWinningAround(board, row, col)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks whether the cell at {@code (row, col)} is part of a winning
     * triple with its immediate neighbours in the four directions and the
     * two diagonals.
     *
     * @param board  the game board
     * @param row    row index of the current cell
     * @param col    column index of the current cell
     * @return {@code true} if a winning triple is found, {@code false} otherwise
     */
    private static boolean isWinningAround(char[][] board, int row, int col) {
        char centre = board[row][col];
        if (centre == ' ') {
            return false; // empty cells cannot start a winning pattern
        }

        // Check vertical neighbours (up & down)
        if (row > 0 && row < BOARD_SIZE - 1) {
            if (isWinningTriplet(centre,
                    board[row - 1][col],
                    board[row + 1][col])) {
                return true;
            }
        }

        // Check horizontal neighbours (left & right)
        if (col > 0 && col < BOARD_SIZE - 1) {
            if (isWinningTriplet(centre,
                    board[row][col - 1],
                    board[row][col + 1])) {
                return true;
            }
        }

        // Check both diagonal directions
        if (row > 0 && row < BOARD_SIZE - 1 && col > 0 && col < BOARD_SIZE - 1) {
            if (isWinningTriplet(centre,
                    board[row - 1][col - 1],
                    board[row + 1][col + 1])) {
                return true;
            }
            if (isWinningTriplet(centre,
                    board[row - 1][col + 1],
                    board[row + 1][col - 1])) {
                return true;
            }
        }

        return false;
    }

    /**
     * Evaluates a triple of cells using the original algorithm:
     * each 'x' increments a balance counter, each 'o' decrements it,
     * and the method returns {@code true} when the balance is at least 2.
     *
     * @param cells three characters to examine
     * @return {@code true} if the balance of 'x' and 'o' is ≥ 2
     */
    private static boolean isWinningTriplet(char... cells) {
        int balance = 0;
        for (char c : cells) {
            if (c == 'x') {
                balance++;
            } else if (c == 'o') {
                balance--;
            }
        }
        return balance >= 2;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* ------------------------------------------------------------ */
    /* Constants & global I/O objects                               */
    /* ------------------------------------------------------------ */
    private static final int N = 4;               // board size (4×4)
    private static final char X = 'x';            // mark
    private static final char EMPTY = '.';        // empty cell

    static BufferedReader in;
    static PrintWriter out;
    static StringTokenizer tok;

    /* ------------------------------------------------------------ */
    /* Entry point                                                   */
    /* ------------------------------------------------------------ */
    public static void main(String[] args) throws IOException {
        in = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        tok = new StringTokenizer("");          // initial empty tokenizer
        new Main().solve();
        out.close();
    }

    /* ------------------------------------------------------------ */
    /* Core solving routine                                            */
    /* ------------------------------------------------------------ */
    void solve() throws IOException {
        char[][] board = readBoard();
        out.println(hasWinningTriplet(board) ? "YES" : "NO");
    }

    /* ------------------------------------------------------------ */
    /* Input handling                                                */
    /* ------------------------------------------------------------ */
    private static char[][] readBoard() throws IOException {
        char[][] board = new char[N][N];
        for (int i = 0; i < N; i++) {
            board[i] = ns().toCharArray();      // each token is a 4‑char line
        }
        return board;
    }

    /* ------------------------------------------------------------ */
    /* Determines whether any length‑3 line contains exactly two   */
    /* 'x' and one '.' (the winning pattern)                        */
    /* ------------------------------------------------------------ */
    private static boolean hasWinningTriplet(char[][] board) {
        // Four directions: right, down, down‑right, down‑left
        final int[][] DIRS = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};

        for (int r = 0; r < N; r++) {
            for (int c = 0; c < N; c++) {
                for (int[] d : DIRS) {
                    int endR = r + 2 * d[0];
                    int endC = c + 2 * d[1];
                    if (endR >= N || endC >= N) {
                        continue;               // would go outside the board
                    }
                    if (countX(board, r, c, d[0], d[1]) == 2) {
                        return true;            // pattern 2 X's + 1 '.' found
                    }
                }
            }
        }
        return false;
    }

    /**
     * Counts how many ‘x’ cells appear in the three consecutive positions
     * starting at (r,c) and moving by (dr,dc). The method assumes that the
     * three cells contain only ‘x’ or '.'; therefore a count of 2 implies
     * the required pattern (2 X's and 1 '.').
     */
    private static int countX(char[][] board, int r, int c, int dr, int dc) {
        int cntX = 0;
        for (int i = 0; i < 3; i++) {
            char ch = board[r + i * dr][c + i * dc];
            if (ch == X) {
                cntX++;
            }
        }
        return cntX;
    }

    /* ------------------------------------------------------------ */
    /* Fast scanner utilities (unchanged, only relocated)           */
    /* ------------------------------------------------------------ */
    private static String ns() throws IOException {
        while (!tok.hasMoreTokens()) {
            tok = new StringTokenizer(in.readLine(), " ");
        }
        return tok.nextToken();
    }

    private static int ni() throws IOException {
        return Integer.parseInt(ns());
    }

    private static long nl() throws IOException {
        return Long.parseLong(ns());
    }

    private static double nd() throws IOException {
        return Double.parseDouble(ns());
    }

    private static String[] nsa(int n) throws IOException {
        String[] res = new String[n];
        for (int i = 0; i < n; i++) {
            res[i] = ns();
        }
        return res;
    }

    private static int[] nia(int n) throws IOException {
        int[] res = new int[n];
        for (int i = 0; i < n; i++) {
            res[i] = ni();
        }
        return res;
    }

    private static long[] nla(int n) throws IOException {
        long[] res = new long[n];
        for (int i = 0; i < n; i++) {
            res[i] = nl();
        }
        return res;
    }

    /* ------------------------------------------------------------ */
    /* Additional helper class (kept unchanged)                     */
    /* ------------------------------------------------------------ */
    static class INA {
        final int[][] a;

        INA(int n, int m) throws IOException {
            this(n, m, -1);
        }

        INA(int n, int m, int t) throws IOException {
            a = new int[m][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    a[j][i] = ni() + t;
                }
            }
        }

        int[] get(int i) {
            return a[i - 1];
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Determines whether a 4×4 Tic‑Tac‑Toe board contains a
 * three‑cell segment that consists of exactly two 'x' cells
 * (represented by 1) and one empty cell (represented by 0).
 *
 * The logic is kept identical to the original implementation,
 * but the code is reorganised for readability, maintainability
 * and extensibility.
 */
public class LlyaAndTicTacToeGame {

    /** Size of the board (4×4). */
    private static final int BOARD_SIZE = 4;

    /** Patterns that represent “two 1’s and one 0” in any order. */
    private static final String[] VALID_PATTERNS = {"110", "101", "011"};

    public static void main(String[] args) throws IOException {
        int[][] board = readBoard();

        if (containsWinningTriplet(board)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads four lines from {@code System.in} and builds an
     * {@code int[BOARD_SIZE][BOARD_SIZE]} board where:
     * <ul>
     *   <li>'x' → 1</li>
     *   <li>'o' → -1 (unused by the winning‑pattern check)</li>
     *   <li>any other character → 0</li>
     * </ul>
     */
    private static int[][] readBoard() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int[][] board = new int[BOARD_SIZE][BOARD_SIZE];

        for (int row = 0; row < BOARD_SIZE; row++) {
            String line = br.readLine();
            for (int col = 0; col < BOARD_SIZE; col++) {
                char ch = line.charAt(col);
                board[row][col] = switch (ch) {
                    case 'x' -> 1;
                    case 'o' -> -1;
                    default -> 0;
                };
            }
        }
        return board;
    }

    /**
     * Returns {@code true} if the board contains at least one
     * horizontal, vertical or diagonal segment of three cells that
     * holds exactly two 1’s and one 0 (i.e. the patterns “110”, “101”
     * or “011”).
     */
    private static boolean containsWinningTriplet(int[][] board) {
        // Check rows
        for (int row = 0; row < BOARD_SIZE; row++) {
            if (hasValidTriplet(board[row][0], board[row][1], board[row][2])
                    || hasValidTriplet(board[row][1], board[row][2], board[row][3])) {
                return true;
            }
        }

        // Check columns
        for (int col = 0; col < BOARD_SIZE; col++) {
            if (hasValidTriplet(board[0][col], board[1][col], board[2][col])
                    || hasValidTriplet(board[1][col], board[2][col], board[3][col])) {
                return true;
            }
        }

        // Check main and anti‑diagonals (all possible 3‑cell diagonals)
        return hasValidTriplet(board[0][0], board[1][1], board[2][2])
                || hasValidTriplet(board[1][0], board[2][1], board[3][2])
                || hasValidTriplet(board[0][1], board[1][2], board[2][3])
                || hasValidTriplet(board[1][1], board[2][2], board[3][3])
                || hasValidTriplet(board[0][2], board[1][1], board[2][0])
                || hasValidTriplet(board[0][3], board[1][2], board[2][1])
                || hasValidTriplet(board[1][2], board[2][1], board[3][0])
                || hasValidTriplet(board[1][3], board[2][2], board[3][1]);
    }

    /**
     * Determines whether three integer values correspond to one of the
     * valid patterns “110”, “101” or “011”.  The method works by counting
     * how many 1’s and 0’s are present – the pattern matches only when
     * there are exactly two 1’s and one 0.
     */
    private static boolean hasValidTriplet(int a, int b, int c) {
        int ones = 0;
        int zeros = 0;

        for (int v : new int[]{a, b, c}) {
            if (v == 1) {
                ones++;
            } else if (v == 0) {
                zeros++;
            }
        }
        return ones == 2 && zeros == 1;
    }
}

