import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 *
 * <p>
 *   The program checks whether placing an 'x' on an empty cell ('.') of a 4×4 board
 *   creates a line of three consecutive 'x's in any of the four diagonal/horizontal/
 *   vertical directions. If such a placement exists it prints "YES", otherwise "NO".
 * </p>
 *
 * <p>Key improvements:</p>
 * <ul>
 *   <li>Extracted constants (board size, symbols) making magic numbers explicit.</li>
 *   <li>Removed unused fields/methods (pair class, shuffle, gcd, MOD, etc.).</li>
 *   <li>Split responsibilities into small, well‑named methods.</li>
 *   <li>Used final fields and descriptive variable names.</li>
 *   <li>Improved I/O handling with a dedicated {@link FastScanner}</li>
 *   <li>Added JavaDoc and inline comments for clarity.</li>
 * </ul>
 */
public class Main {

    /** Board dimension – currently fixed to 4 × 4 */
    private static final int BOARD_SIZE = 4;

    /** Symbol representing an empty cell */
    private static final char EMPTY = '.';

    /** Symbol used for the candidate move */
    private static final char MARK = 'x';

    /** Length of the sequence we are looking for (hard‑coded to 3 in the original). */
    private static final int WIN_LENGTH = 3;

    /** Direction vectors for the four checks (right, down, down‑right, down‑left). */
    private static final int[] DR = {0, 1, 1, -1};
    private static final int[] DC = {1, 0, 1, 1};

    /** --------------------------------------------------------------------- */
    /** Entry point */
    public static void main(String[] args) {
        solve();
    }

    /** --------------------------------------------------------------------- */
    /** Core algorithm – reads the board, tries every empty cell and prints result. */
    private static void solve() {
        char[][] board = readBoard();

        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] == EMPTY) {
                    board[r][c] = MARK;
                    if (hasThreeInRow(board, r, c)) {
                        System.out.println("YES");
                        return;
                    }
                    board[r][c] = EMPTY; // undo move
                }
            }
        }

        System.out.println("NO");
    }

    /** --------------------------------------------------------------------- */
    /** Reads exactly BOARD_SIZE lines from standard input, each line representing a row. */
    private static char[][] readBoard() {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            board[i] = readLine().trim().toCharArray();
        }
        return board;
    }

    /** --------------------------------------------------------------------- */
    /** Checks whether placing MARK at (row, col) creates a line of WIN_LENGTH MARKs. */
    private static boolean hasThreeInRow(char[][] board, int row, int col) {
        for (int dir = 0; dir < DR.length; dir++) {
            boolean allSet = true;
            for (int step = 1; step < WIN_LENGTH; step++) {
                int r = row + DR[dir] * step;
                int c = col + DC[dir] * step;
                if (r < 0 || r >= BOARD_SIZE || c < 0 || c >= BOARD_SIZE
                        || board[r][c] != MARK) {
                    allSet = false;
                    break;
                }
            }
            if (allSet) {
                return true;
            }
        }
        return false;
    }

    /** --------------------------------------------------------------------- */
    /** Simple line reader helper used by {@link #readBoard()}. */
    private static String readLine() {
        try {
            return java.lang.System.in.readLine();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    /** --------------------------------------------------------------------- */
    /** Fast scanner used for future extensions – currently only {@code next()} is needed. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is), 32768);
        }

        /** Returns the next token, blocking until one is available. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience methods – can be expanded if the program grows. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class codeforces implements Runnable {

    /** Character representing an empty cell. */
    private static final char EMPTY = '.';
    /** Character used as the player's mark. */
    private static final char MARK = 'x';

    /* --------------------------------------------------------------------- */
    /* -------------------------- INPUT READER --------------------------- */
    /* --------------------------------------------------------------------- */
    private static final class InputReader implements Closeable {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int pos = 0, len = 0;
        private final SpaceCharFilter filter = new DefaultSpaceCharFilter();

        public InputReader(InputStream stream) { this.stream = stream; }

        private int read() throws IOException {
            if (pos >= len) {
                len = stream.read(buffer);
                pos = 0;
                if (len <= 0) return -1;
            }
            return buffer[pos++];
        }

        /** Returns the next token (lexical sequence of non‑space characters). */
        public String nextToken() {
            int c;
            do { c = read(); } while (filter.isSpaceChar(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = read();
            } while (!filter.isSpaceChar(c) && c != -1);
            return sb.toString();
        }

        public String next() { return nextToken(); }

        public int nextInt() { return (int) nextLong(); }

        public long nextLong() {
            int sign = 1;
            long result = 0;
            int c;
            do { c = read(); } while (filter.isSpaceChar(c));
            if (c == '-') { sign = -1; c = read(); }
            while (!filter.isSpaceChar(c) && c >= '0' && c <= '9') {
                result = result * 10 + (c - '0');
                c = read();
            }
            return result * sign;
        }

        public double nextDouble() { return Double.parseDouble(nextToken()); }

        public String readLine() {
            StringBuilder sb = new StringBuilder();
            int c;
            do { c = read(); } while (!filter.isSpaceChar(c) && c != '\n' && c != -1);
            while (!filter.isSpaceChar(c) && c != '\n' && c != -1) {
                sb.appendCodePoint(c);
                c = read();
            }
            return sb.toString();
        }

        public void close() { /* no resources to release */ }
        public interface SpaceCharFilter { boolean isSpaceChar(int ch); }
    }

    private static final class DefaultSpaceCharFilter implements InputReader.SpaceCharFilter {
        @Override public boolean isSpaceChar(int c) { return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1; }
    }

    /* --------------------------------------------------------------------- */
    /* --------------------------- BOARD READING --------------------------- */
    /* --------------------------------------------------------------------- */
    /** Reads the 4×4 board from standard input. */
    private static char[][] readBoard(InputReader in) {
        char[][] board = new char[4][4];
        String line = in.readLine();
        if (line == null) return board;

        // The problem supplies a single line with 16 characters (or whitespace separated rows)
        String[] tokens = line.replaceAll("\\s+", "").split("(?<=\\G.{" + 4 + "})");
        for (int i = 0; i < 4; i++) {
            String token = tokens[i];
            for (int j = 0; j < 4; j++) {
                board[i][j] = token.charAt(j);
            }
        }
        return board;
    }

    /* --------------------------------------------------------------------- */
    /* --------------------- WINNING‑MOVE CHECKLOGIC ----------------------- */
    /* --------------------------------------------------------------------- */
    /** Determines whether any empty cell can be turned into a winning move. */
    private static boolean hasWinningMove(char[][] board) {
        for (int r = 0; r < 4; r++) {
            for (int c = 0; c < 4; c++) {
                if (board[r][c] == EMPTY && isWinningPlacement(board, r, c, MARK)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Checks if placing `mark` at (r,c) creates a line of at least three marks. */
    private static boolean isWinningPlacement(char[][] board, int r, int c, char mark) {
        // Examine four line families (horizontal, vertical, two diagonals)
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (dr == 0 && dc == 0) continue;
                if (!isAdjacentMark(board, r, c, mark, dr, dc)) continue;

                int count = countInDirection(board, r, c, mark, dr, dc);
                count += countInDirection(board, r, c, mark, -dr, -dc);
                if (count >= 3) return true;
            }
        }
        return false;
    }

    /** Counts consecutive `mark` starting from (r,c) moving by (dr,dc). */
    private static int countInDirection(char[][] board, int r, int c, char mark, int dr, int dc) {
        int cnt = 0;
        int nr = r + dr, nc = c + dc;
        while (inBounds(nr, nc) && board[nr][nc] == mark) {
            cnt++;
            nr += dr;
            nc += dc;
        }
        return cnt;
    }

    /** True iff there is at least one `mark` right next to (r,c) in the given direction. */
    private static boolean isAdjacentMark(char[][] board, int r, int c, char mark, int dr, int dc) {
        int nr = r + dr, nc = c + dc;
        return inBounds(nr, nc) && board[nr][nc] == mark;
    }

    private static boolean inBounds(int r, int c) {
        return 0 <= r && r < 4 && 0 <= c && c < 4;
    }

    /* --------------------------------------------------------------------- */
    /* ------------------------------- MAIN ------------------------------- */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        new Thread(null, new codeforces(), "codeforces", 1 << 26).start();
    }

    @Override
    public void run() {
        try (InputReader in = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out, true)) {

            char[][] board = readBoard(in);
            boolean canWin = hasWinningMove(board);
            out.println(canWin ? "YES" : "NO");
        }
    }
}

import java.io.*;
import java.util.*;

public class CF390B {

    /** Constants that describe the relevant part of the 10×10 board */
    private static final int BOARD_SIZE = 10;
    private static final int START = 4;   // inclusive
    private static final int END   = 7;   // inclusive (4…7 => 4 cells)

    /** Directions used for the eight rays that are examined around a centre */
    private static final int[][] DIRECTIONS = {
            { 0,  1}, // right
            { 1,  1}, // down‑right
            { 1,  0}, // down
            { 1, -1}, // down‑left
            { 0, -1}, // left
            {-1, -1}, // up‑left
            {-1,  0}, // up
            {-1,  1}  // up‑right
    };

    public static void main(String[] args) throws Exception {
        // -----------------------------------------------------------------
        // 1️⃣  Input handling – use try‑with‑resources to guarantee closing
        // -----------------------------------------------------------------
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
             BufferedWriter writer = new BufferedWriter(
                new OutputStreamWriter(System.out))) {

            char[][] board = readBoard(reader);

            String answer = solve(board);
            writer.write(answer);
            writer.newLine();
        }
    }

    /** Reads the whole 10×10 board from the provided reader. */
    private static char[][] readBoard(BufferedReader reader) throws IOException {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        // The problem only cares about rows 4‑7 (inclusive) and columns 4‑7.
        // The original code started reading at line 4, therefore we keep that
        // behaviour: we read exactly four lines and fill the relevant slice.
        for (int r = START; r <= END; r++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            // Fill columns 4‑7, shifting the index because the original code used
            // `jj-4` as the column offset inside the line.
            for (int c = START; c <= END; c++) {
                board[r][c] = line.charAt(c - START);
            }
        }
        return board;
    }

    /** Core algorithm – returns "YES" if any centre contains the required pattern. */
    private static String solve(char[][] board) {
        String result = "NO";

        // Scan every possible centre (i, j) that lies inside the 4×4 region.
        for (int i = START; i <= END; i++) {
            for (int j = START; j <= END; j++) {
                if (board[i][j] != 'x') {
                    continue; // only cells that are 'x' can be a centre
                }

                // 8 counters: how many 'x' and how many '.' we have seen in each ray
                int[] xCounts = new int[DIRECTIONS.length];
                int[] dotCounts = new int[DIRECTIONS.length];

                // Examine each of the eight rays, stepping 0 … 2 cells along it.
                for (int d = 0; d < DIRECTIONS.length; d++) {
                    int dx = DIRECTIONS[d][0];
                    int dy = DIRECTIONS[d][1];

                    for (int step = 0; step < 3; step++) {
                        int ni = i + dx * step;
                        int nj = j + dy * step;
                        char cell = board[ni][nj];

                        if (cell == 'x') {
                            xCounts[d]++;
                        } else if (cell == '.') {
                            dotCounts[d]++;
                        }
                    }
                }

                // If any ray satisfies “exactly 2 x's and 1 '.'” we have found a match.
                for (int d = 0; d < DIRECTIONS.length; d++) {
                    if (xCounts[d] == 2 && dotCounts[d] == 1) {
                        result = "YES";
                        break;
                    }
                }

                // Early exit – once we know the answer is YES we can stop scanning.
                if ("YES".equals(result)) {
                    break;
                }
            }
            if ("YES".equals(result)) {
                break;
            }
        }
        return result;
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 * The functionality is unchanged:
 *   - reads a 4×4 board of '.' and 'x'
 *   - determines whether placing a single 'x' in any '.' cell
 *     creates a line of three contiguous 'x' cells (horizontal,
 *     vertical or either diagonal)
 *   - prints "YES" if such a move exists, otherwise "NO".
 *
 * Changes made for maintainability:
 *   • Constants replace magic numbers.
 *   • Meaningful method and variable names.
 *   • Separation of concerns (reading input, checking moves,
 *     counting pieces).
 *   • Use of try‑with‑resources for I/O objects.
 *   • Removed unnecessary static imports and the custom Scanner
 *     wrapper – Java’s built‑in Scanner is sufficient.
 */
public class B {

    private static final int BOARD_SIZE = 4;
    private static final char EMPTY = '.';
    private static final char PLAYER = 'x';

    public static void main(String[] args) throws Exception {
        // Input/output are automatically closed at the end of the block.
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            char[][] board = readBoard(scanner);
            boolean winningMoveExists = false;

            // Try placing an 'x' on each empty cell.
            for (int row = 0; row < BOARD_SIZE && !winningMoveExists; row++) {
                for (int col = 0; col < BOARD_SIZE && !winningMoveExists; col++) {
                    if (board[row][col] == EMPTY) {
                        board[row][col] = PLAYER;
                        winningMoveExists = createsThreeInARow(board, row, col);
                        board[row][col] = EMPTY;           // revert change
                    }
                }
            }

            out.println(winningMoveExists ? "YES" : "NO");
        }
    }

    /** Reads four lines from the scanner and stores them as a 4×4 char array. */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = scanner.next().trim();
            board[i] = line.toCharArray();
        }
        return board;
    }

    /** Determines whether the recent placement creates three consecutive PLAYER marks. */
    private static boolean createsThreeInARow(char[][] board, int placedRow, int placedCol) {
        // horizontal
        if (countInDirection(board, placedRow, placedCol, 0, 1)) return true;
        // vertical
        if (countInDirection(board, placedRow, placedCol, 1, 0)) return true;
        // diagonal down‑right
        if (countInDirection(board, placedRow, placedCol, 1, 1)) return true;
        // diagonal down‑left
        if (countInDirection(board, placedRow, placedCol, 1, -1)) return true;

        return false;
    }

    /**
     * Counts how many consecutive PLAYER marks exist starting from (row, col)
     * and moving {@code dRow} rows and {@code dCol} columns.
     * The loop stops after 3 steps or when the board border is reached.
     */
    private static boolean countInDirection(char[][] board, int row, int col,
                                            int dRow, int dCol) {
        int count = 0;
        for (int step = 0; step < 3; step++) {
            int r = row + dRow * step;
            int c = col + dCol * step;
            if (!isInsideBoard(r, c)) {
                break; // out of bounds – stop counting in this direction
            }
            if (board[r][c] == PLAYER) {
                count++;
            }
        }
        return count == 3;
    }

    /** Checks whether a given cell coordinate is inside the 4×4 board. */
    private static boolean isInsideBoard(int r, int c) {
        return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.List;

/**
 * Reads a 4×4 board and determines whether any straight line of three
 * cells contains exactly two 'x' characters and one '.' character.
 * The result is printed as "YES" or "NO".
 */
public class Main {

    /** Size of the square board (fixed to 4 for this problem). */
    private static final int BOARD_SIZE = 4;

    /** Characters used on the board. */
    private static final char EMPTY = '.';
    private static final char PLAYER = 'x';

    /** All possible directions in which a 3‑cell segment can be examined. */
    private static final List<int[]> DIRECTIONS = List.of(
            new int[]{1, 0},   // right
            new int[]{0, 1},   // down
            new int[]{1, 1},   // down‑right
            new int[]{-1, 1},  // down‑left
            new int[]{0, -1},  // up
            new int[]{-1, 0},  // left
            new int[]{-1, -1}, // up‑left
            new int[]{1, -1}   // up‑right
    );

    public static void main(String[] args) throws IOException {
        try (PrintWriter out = new PrintWriter(System.out)) {
            char[][] board = readBoard();
            boolean found = containsWinningPattern(board);
            out.println(found ? "YES" : "NO");
        }
    }

    /** Reads exactly four lines from standard input, each containing four characters. */
    private static char[][] readBoard() throws IOException {
        char[][] board = new char[BOARD_SIZE][];
        BufferedReader br = new BufferedReader(new java.io.InputStreamReader(System.in));

        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = br.readLine();
            if (line == null) {
                throw new IOException("Expected " + BOARD_SIZE + " lines of input");
            }
            board[i] = line.toCharArray();
        }
        return board;
    }

    /**
     * Checks whether any three‑cell straight line (starting at some cell and
     * extending in any of the eight directions) contains exactly two 'x' and
     * one '.' character.
     */
    private static boolean containsWinningPattern(char[][] board) {
        outerLoop:
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                for (int[] dir : DIRECTIONS) {
                    int dx = dir[0];
                    int dy = dir[1];

                    int xCount = (board[row][col] == PLAYER) ? 1 : 0;
                    int emptyCount = (board[row][col] == EMPTY) ? 1 : 0;

                    // Examine the next two cells in the chosen direction.
                    for (int step = 1; step <= 2; step++) {
                        int r = row + dx * step;
                        int c = col + dy * step;

                        if (!isInside(r, c)) {
                            break; // out of bounds → stop extending this line
                        }

                        char cell = board[r][c];
                        if (cell == PLAYER) {
                            xCount++;
                        } else if (cell == EMPTY) {
                            emptyCount++;
                        }
                    }

                    if (xCount == 2 && emptyCount == 1) {
                        return true; // pattern found
                    }
                }
            }
        }
        return false; // no pattern found
    }

    /** Returns true if the supplied coordinates are within the board limits. */
    private static boolean isInside(int r, int c) {
        return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
    }
}

import java.io.*;
import java.util.Locale;
import java.util.StringTokenizer;

/**
 * Refactored version of the original game‑checking program.
 * <p>
 * The program reads a 4×4 board, tries to place an 'x' on every empty
 * cell ('.') and reports “YES” if any placement creates a line of three
 * consecutive 'x's, otherwise it reports “NO”.
 * </p>
 */
public class Solution implements Runnable {

    /* --------------------------------------------------------------------- */
    /*  Constants – renamed for clarity                                        */
    /* --------------------------------------------------------------------- */
    private static final String YES = "YES";
    private static final String NO  = "NO";

    private static final char EMPTY   = '.';   // board cell without a mark
    private static final char MARK    = 'x';   // the mark we try to place
    private static final char OPPONENT = 'o';  // not used directly, kept for context

    private static final int BOARD_SIZE = 4;   // board is always 4×4
    private static final int WIN_LENGTH = 3;   // we need 3 consecutive MARKs

    /* --------------------------------------------------------------------- */
    /*  Direction vectors (8 possible directions)                             */
    /* --------------------------------------------------------------------- */
    private static final class Directions {
        static final int[] DR = {-1, -1, 0, 1, 1, 1, 0, -1};
        static final int[] DC = { 0,  1, 1, 1, 0,-1,-1,-1};
        static final int COUNT = 8;
    }

    /* --------------------------------------------------------------------- */
    /*  I/O fields                                                             */
    /* --------------------------------------------------------------------- */
    private final PrintStream out;
    private final BufferedReader in;
    private StringTokenizer tokenizer;

    /* --------------------------------------------------------------------- */
    /*  Constructor – chooses input source                                     */
    /* --------------------------------------------------------------------- */
    public Solution(String inputFile) throws IOException {
        Locale.setDefault(Locale.US);
        if (inputFile == null) {
            in = new BufferedReader(new InputStreamReader(System.in));
            out = System.out;
        } else {
            in = new BufferedReader(
                    new InputStreamReader(new FileInputStream(inputFile + ".in")));
            out = new PrintStream(
                    new BufferedOutputStream(new FileOutputStream(inputFile + ".out")));
        }
        tokenizer = new StringTokenizer("");
    }

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                            */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        new Thread(new Solution(null)).start();
    }

    /* --------------------------------------------------------------------- */
    /*  Public algorithm                                                       */
    /* --------------------------------------------------------------------- */
    @Override
    public void run() {
        try {
            solve();
            out.close();
        } catch (Throwable e) {
            throw new RuntimeException(e);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core logic                                                             */
    /* --------------------------------------------------------------------- */
    private void solve() throws IOException {
        char[][] board = readBoard();
        String result = determineResult(board);
        out.println(result);
    }

    /** Reads the 4 lines that form the board. */
    private char[][] readBoard() throws IOException {
        char[][] board = new char[BOARD_SIZE][];
        for (int i = 0; i < BOARD_SIZE; i++) {
            board[i] = next().toCharArray();
        }
        return board;
    }

    /** Checks every empty cell for a winning move. */
    private String determineResult(char[][] board) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] == EMPTY) {
                    board[r][c] = MARK;
                    if (hasWinningLine(board)) {
                        return YES;
                    }
                    board[r][c] = EMPTY; // revert
                }
            }
        }
        return NO;
    }

    /** Returns true if any direction from any cell contains three MARKs. */
    private boolean hasWinningLine(char[][] board) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                for (int d = 0; d < Directions.COUNT; d++) {
                    if (isWinFrom(board, r, c,
                            Directions.DR[d], Directions.DC[d])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Checks whether a line of length {@link #WIN_LENGTH} starts at (r,c)
     *  and proceeds in direction (dRow,dCol) consisting only of MARKs. */
    private boolean isWinFrom(char[][] board, int startRow, int startCol,
                              int dRow, int dCol) {
        for (int step = 0; step < WIN_LENGTH; step++) {
            int r = startRow + dRow * step;
            int c = startCol + dCol * step;
            if (!inBounds(r, c) || board[r][c] != MARK) {
                return false;
            }
        }
        return true;
    }

    /** Simple bounds check for the 4×4 board. */
    private boolean inBounds(int row, int col) {
        return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE;
    }

    /* --------------------------------------------------------------------- */
    /*  Fast input utilities                                                   */
    /* --------------------------------------------------------------------- */
    /** Returns the next token from the input stream, reading a new line when
     *  necessary. */
    public String next() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            String line = in.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }
}

import java.util.Scanner;

/**
 * Refactored version of CF390B.
 *
 * The program reads a 4×4 board (characters '.' or 'x'), tries to place an extra
 * 'x' on each empty cell and checks whether any such placement creates a line
 * of three consecutive 'x' cells horizontally, vertically or diagonally.
 */
public class CF390B {

    /** size of the board (fixed 4×4) */
    private static final int BOARD_SIZE = 4;
    /** character that represents an empty cell */
    private static final char EMPTY = '.';
    /** character that represents a placed move */
    private static final char MARK = 'x';

    public static void main(String[] args) {
        /* Try‑with‑resources guarantees the scanner is closed */
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            boolean canWin = canWin(board);
            System.out.println(canWin ? "YES" : "NO");
        }
    }

    /** Reads the 4 lines that describe the board. */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            board[i] = scanner.nextLine().toCharArray();
        }
        return board;
    }

    /** Determines whether any empty cell can be turned into a winning move. */
    private static boolean canWin(char[][] board) {
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                if (board[row][col] == EMPTY) {
                    board[row][col] = MARK;               // tentatively place 'x'
                    boolean win = hasThreeInRow(board);    // does it create a line?
                    board[row][col] = EMPTY;               // restore original state
                    if (win) {
                        return true;
                    }
                }
            }
        }
        return false; // no winning placement found
    }

    /** Checks all possible 3‑cell segments for a complete line of 'x'. */
    private static boolean hasThreeInRow(char[][] board) {
        // --- horizontal ---------------------------------------------------------
        if (hasThreeConsecutive(board, 0, 0, 0, 1) ||
            hasThreeConsecutive(board, 0, 1, 0, 1) ||
            hasThreeConsecutive(board, 1, 0, 1, 1) ||
            hasThreeConsecutive(board, 1, 1, 1, 1) ||
            hasThreeConsecutive(board, 2, 0, 2, 1) ||
            hasThreeConsecutive(board, 2, 1, 2, 1) ||
            hasThreeConsecutive(board, 3, 0, 3, 1) ||
            hasThreeConsecutive(board, 3, 1, 3, 1)) {
            return true;
        }

        // --- vertical -----------------------------------------------------------
        if (hasThreeConsecutive(board, 0, 0, 1, 0) ||
            hasThreeConsecutive(board, 0, 1, 1, 0) ||
            hasThreeConsecutive(board, 0, 2, 1, 0) ||
            hasThreeConsecutive(board, 0, 3, 1, 0) ||
            hasThreeConsecutive(board, 1, 0, 1, 0) ||
            hasThreeConsecutive(board, 1, 1, 1, 0) ||
            hasThreeConsecutive(board, 1, 2, 1, 0) ||
            hasThreeConsecutive(board, 1, 3, 1, 0) ||
            hasThreeConsecutive(board, 2, 0, 1, 0) ||
            hasThreeConsecutive(board, 2, 1, 1, 0) ||
            hasThreeConsecutive(board, 2, 2, 1, 0) ||
            hasThreeConsecutive(board, 2, 3, 1, 0) ||
            hasThreeConsecutive(board, 3, 0, 1, 0) ||
            hasThreeConsecutive(board, 3, 1, 1, 0) ||
            hasThreeConsecutive(board, 3, 2, 1, 0) ||
            hasThreeConsecutive(board, 3, 3, 1, 0)) {
            return true;
        }

        // --- diagonal down‑right -------------------------------------------------
        if (hasThreeConsecutive(board, 0, 0, 1, 1) ||
            hasThreeConsecutive(board, 0, 1, 1, 1) ||
            hasThreeConsecutive(board, 1, 0, 1, 1) ||
            hasThreeConsecutive(board, 1, 1, 1, 1)) {
            return true;
        }

        // --- diagonal up‑right ---------------------------------------------------
        if (hasThreeConsecutive(board, 2, 0, -1, 1) ||
            hasThreeConsecutive(board, 2, 1, -1, 1) ||
            hasThreeConsecutive(board, 3, 0, -1, 1) ||
            hasThreeConsecutive(board, 3, 1, -1, 1)) {
            return true;
        }

        return false; // no winning line found
    }

    /**
     * Checks whether three cells starting at {@code row, col} and moving by
     * {@code dr, dc} per step are all equal to {@code MARK}.
     *
     * @param board   the game board
     * @param row     starting row
     * @param col     starting column
     * @param dr      row delta per step
     * @param dc      column delta per step
     * @return {@code true} if the three cells are all {@code MARK}
     */
    private static boolean hasThreeConsecutive(char[][] board,
                                                int row,
                                                int col,
                                                int dr,
                                                int dc) {
        int count = 0;
        for (int i = 0; i < 3; i++) {
            int r = row + dr * i;
            int c = col + dc * i;
            if (board[r][c] == MARK) {
                count++;
            }
        }
        return count == 3;
    }
}

import java.util.Scanner;

/**
 * Tic‑Tac‑Toe validator.
 * The board is a 4×4 grid. A win is declared when any
 * row, column or diagonal contains exactly two 'x' marks and one empty
 * ('.') cell, irrespective of order.
 */
public class TicTacToeValidator {

    private static final int SIZE = 4;
    private static final char EMPTY = '.';
    private static final char PLAYER = 'x';

    public static void main(String[] args) {
        char[][] board = new char[SIZE][SIZE];
        readBoard(board);
        System.out.println(hasWinningLine(board) ? "YES" : "NO");
    }

    /** Reads four strings of length 4 and stores them into the board. */
    private static void readBoard(char[][] board) {
        Scanner scanner = new Scanner(System.in);
        for (int i = 0; i < SIZE; i++) {
            String line = scanner.next();
            for (int j = 0; j < SIZE; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        scanner.close();
    }

    /** Determines whether the board contains any winning line (row, column or diagonal). */
    private static boolean hasWinningLine(char[][] board) {
        return checkRows(board) || checkColumns(board) || checkDiagonals(board);
    }

    /** Checks all rows for a winning pattern. */
    private static boolean checkRows(char[][] board) {
        for (int row = 0; row < SIZE; row++) {
            if (isWinningCombo(board[row][0], board[row][1], board[row][2]) ||
                isWinningCombo(board[row][3], board[row][1], board[row][2])) {
                return true;
            }
        }
        return false;
    }

    /** Checks all columns for a winning pattern. */
    private static boolean checkColumns(char[][] board) {
        for (int col = 0; col < SIZE; col++) {
            if (isWinningCombo(board[0][col], board[1][col], board[2][col]) ||
                isWinningCombo(board[3][col], board[1][col], board[2][col])) {
                return true;
            }
        }
        return false;
    }

    /** Checks the diagonal directions for a winning pattern. */
    private static boolean checkDiagonals(char[][] board) {
        // down‑right diagonals (the original code covered all needed cases)
        if (isWinningCombo(board[2][0], board[1][1], board[0][2]) ||
            isWinningCombo(board[3][0], board[2][1], board[1][2]) ||
            isWinningCombo(board[0][3], board[2][1], board[1][2]) ||
            isWinningCombo(board[3][1], board[2][2], board[1][3]) ||
            isWinningCombo(board[0][1], board[1][2], board[2][3]) ||
            isWinningCombo(board[0][0], board[1][1], board[2][2]) ||
            isWinningCombo(board[3][3], board[1][1], board[2][2]) ||
            isWinningCombo(board[1][0], board[2][1], board[3][2])) {
            return true;
        }
        return false;
    }

    /**
     * Returns {@code true} if the three supplied characters contain exactly
     * two player marks ('x') and one empty cell ('.'), in any order.
     */
    private static boolean isWinningCombo(char a, char b, char c) {
        int playerCount = (a == PLAYER ? 1 : 0) +
                          (b == PLAYER ? 1 : 0) +
                          (c == PLAYER ? 1 : 0);
        int emptyCount = (a == EMPTY ? 1 : 0) +
                         (b == EMPTY ? 1 : 0) +
                         (c == EMPTY ? 1 : 0);
        return playerCount == 2 && emptyCount == 1;
    }
}

import java.io.*;

/**
 * Refactored version of the original {@code B} program.
 * <p>
 * The program reads a 4×4 grid from the supplied input source,
 * checks for a winning pattern (any row, column or diagonal containing
 * the substrings {@code "xx."}, {@code "x.x"} or {@code ".xx"}),
 * and prints {@code "YES"} if such a pattern exists, otherwise {@code "NO"}.
 * </p>
 */
public class Solver {

    /** Size of the grid – currently fixed to 4×4. */
    private static final int GRID_SIZE = 4;

    /** Number of test cases – kept at 1 to match the original behaviour. */
    private static final int TEST_CASES = 1;

    /** Underlying input reader (file or stdin). */
    private final BufferedReader reader;

    /** Holds the last line read from {@link #reader}. */
    private String currentLine;

    /**
     * Constructs a {@code Solver} that reads from the given {@link BufferedReader}.
     *
     * @param reader source of input data
     * @throws IllegalArgumentException if {@code reader} is {@code null}
     */
    public Solver(BufferedReader reader) {
        if (reader == null) {
            throw new IllegalArgumentException("Reader cannot be null");
        }
        this.reader = reader;
    }

    /** Reads the next line from the underlying reader. */
    private void readLine() throws IOException {
        currentLine = reader.readLine();
    }

    /**
     * Checks whether the supplied string contains any of the target substrings
     * that indicate a winning pattern.
     *
     * @param candidate text to inspect
     * @return {@code true} if the pattern matches, otherwise {@code false}
     */
    private static boolean matchesTarget(String candidate) {
        return candidate.contains("xx.") ||
               candidate.contains("x.x") ||
               candidate.contains(".xx");
    }

    /**
     * Determines whether the given string constitutes a winning configuration.
     *
     * @param candidate text to evaluate
     * @return {@code true} if it matches one of the required patterns
     */
    private boolean isWinning(String candidate) {
        return matchesTarget(candidate);
    }

    /**
     * Core processing routine – reads a grid, evaluates it and appends the result
     * to the output string.
     *
     * @throws IOException if an I/O error occurs while reading
     */
    public void solve() throws IOException {
        StringBuilder output = new StringBuilder();

        for (int testIdx = 0; testIdx < TEST_CASES; testIdx++) {
            // -----------------------------------------------------------------
            // 1️⃣  Read the four rows of the grid
            // -----------------------------------------------------------------
            String[] rows = new String[GRID_SIZE];
            for (int r = 0; r < GRID_SIZE; r++) {
                readLine();
                rows[r] = currentLine;
            }

            boolean hasWinningPattern = false;

            // -----------------------------------------------------------------
            // 2️⃣  Check each row directly
            // -----------------------------------------------------------------
            for (String row : rows) {
                if (isWinning(row)) {
                    hasWinningPattern = true;
                    break;
                }
            }

            // -----------------------------------------------------------------
            // 3️⃣  Check each column
            // -----------------------------------------------------------------
            for (int col = 0; col < GRID_SIZE; col++) {
                StringBuilder colBuilder = new StringBuilder();
                for (int row = 0; row < GRID_SIZE; row++) {
                    colBuilder.append(rows[row].charAt(col));
                }
                if (isWinning(colBuilder.toString())) {
                    hasWinningPattern = true;
                    break;
                }
            }

            // -----------------------------------------------------------------
            // 4️⃣  Build the three pieces of diagonal “d1” and test them
            // -----------------------------------------------------------------
            String[] d1 = new String[3];
            d1[0] = buildD1_0(rows);
            d1[1] = buildD1_1(rows);
            d1[2] = buildD1_2(rows);
            for (String part : d1) {
                if (isWinning(part)) {
                    hasWinningPattern = true;
                    break;
                }
            }

            // -----------------------------------------------------------------
            // 5️⃣  Build the three pieces of diagonal “d2” and test them
            // -----------------------------------------------------------------
            String[] d2 = new String[3];
            d2[0] = buildD2_0(rows);
            d2[1] = buildD2_1(rows);
            d2[2] = buildD2_2(rows);
            for (String part : d2) {
                if (isWinning(part)) {
                    hasWinningPattern = true;
                    break;
                }
            }

            // -----------------------------------------------------------------
            // 6️⃣  Append the result for this test case
            // -----------------------------------------------------------------
            output.append(hasWinningPattern ? "YES" : "NO");
        }

        System.out.print(output);
    }

    /** Helper that builds the first d1 component (rows[1][0] + rows[2][1] + rows[3][2]). */
    private static String buildD1_0(String[] rows) {
        return String.valueOf(rows[1].charAt(0))
                + rows[2].charAt(1)
                + rows[3].charAt(2);
    }

    /** Helper that builds the second d1 component (rows[0][0] … rows[3][3]). */
    private static String buildD1_1(String[] rows) {
        return String.valueOf(rows[0].charAt(0))
                + rows[1].charAt(1)
                + rows[2].charAt(2)
                + rows[3].charAt(3);
    }

    /** Helper that builds the third d1 component (rows[0][1] + rows[1][2] + rows[2][3]). */
    private static String buildD1_2(String[] rows) {
        return String.valueOf(rows[0].charAt(1))
                + rows[1].charAt(2)
                + rows[2].charAt(3);
    }

    /** Helper that builds the first d2 component (rows[1][3] + rows[2][2] + rows[3][1]). */
    private static String buildD2_0(String[] rows) {
        return String.valueOf(rows[1].charAt(3))
                + rows[2].charAt(2)
                + rows[3].charAt(1);
    }

    /** Helper that builds the second d2 component (rows[0][3] + rows[1][2] + rows[2][1] + rows[3][0]). */
    private static String buildD2_1(String[] rows) {
        return String.valueOf(rows[0].charAt(3))
                + rows[1].charAt(2)
                + rows[2].charAt(1)
                + rows[3].charAt(0);
    }

    /** Helper that builds the third d2 component (rows[0][2] + rows[1][1] + rows[2][0]). */
    private static String buildD2_2(String[] rows) {
        return String.valueOf(rows[0].charAt(2))
                + rows[1].charAt(1)
                + rows[2].charAt(0);
    }

    /**
     * Opens a {@link BufferedReader} either from the given file path or from
     * standard input when {@code path} is {@code null}.
     *
     * @param path file path supplied on the command line or {@code null}
     * @return a ready‑to‑use {@code BufferedReader}
     * @throws FileNotFoundException if the file cannot be opened
     */
    public static BufferedReader openReader(String path) throws FileNotFoundException {
        return (path == null)
                ? new BufferedReader(new InputStreamReader(System.in))
                : new BufferedReader(new FileReader(path));
    }

    /**
     * Entry point of the program.
     * <p>
     * If a command‑line argument is supplied it is treated as the input file
     * name; otherwise the program reads from standard input.
     * </p>
     */
    public static void main(String[] args) throws Exception {
        String inputPath = null;
        if (args.length > 0) {
            inputPath = args[0];
        }

        try (BufferedReader br = openReader(inputPath)) {
            new Solver(br).solve();
        }
    }
}

/**
 * Refinement of the original board‑checking program.
 *
 * <p>This version focuses on readability, maintainability and a clear
 * separation of concerns:
 *
 * <ul>
 *   <li>Constants replace magic numbers.</li>
 *   <li>Board‑initialisation and input handling are isolated.</li>
 *   <li>Win‑detection logic lives in dedicated, small methods.</li>
 *   <li>The mutable static flag {@code foundWin} is eliminated – the
 *       DFS now returns the result directly.</li>
 *   <li>Direction handling is expressed with a small lookup table,
 *       making future extensions trivial.</li>
 *   <li>Method names follow conventional Java style.</li>
 * </ul>
 *
 * The program expects four input strings (one per line) and prints
 * {@code YES} if any winning pattern of three adjacent {@code 'x'}
 * characters can be formed on an 8×8 board, otherwise {@code NO}.
 */
public final class Main {

    // -------------------------------------------------------------------------
    // Constants
    // -------------------------------------------------------------------------

    /** Size of the square board (8×8). */
    private static final int BOARD_SIZE = 8;

    /** Starting index of the playable area on the board. */
    private static final int PLAYGROUND_START = 2;

    /** Ending index (exclusive) of the playable area. */
    private static final int PLAYGROUND_END = 6;

    /** Length of a winning line. */
    private static final int WIN_LENGTH = 3;

    /** Character used for an empty cell. */
    private static final char EMPTY = '/';

    /** Character used for a planted seed. */
    private static final char SEED = 'x';

    // -------------------------------------------------------------------------
    // Entry point
    // -------------------------------------------------------------------------

    public static void main(String[] args) {
        String[] inputs = readInputs();
        char[][] board = initialiseBoard(inputs);
        boolean winFound = false;

        // Try to plant a seed at every empty cell and see if it creates a win.
        for (int row = PLAYGROUND_START; row < PLAYGROUND_END && !winFound; ++row) {
            for (int col = PLAYGROUND_START; col < PLAYGROUND_END && !winFound; ++col) {
                if (board[row][col] == EMPTY) {
                    board[row][col] = SEED;
                    winFound = dfsCheck(board, row, col);
                    board[row][col] = EMPTY;               // backtrack
                }
            }
        }

        System.out.println(winFound ? "YES" : "NO");
    }

    // -------------------------------------------------------------------------
    // Input handling
    // -------------------------------------------------------------------------

    private static String[] readInputs() {
        Scanner scanner = new Scanner(System.in);
        String[] lines = new String[4];
        for (int i = 0; i < 4; ++i) {
            lines[i] = scanner.next();
        }
        return lines;
    }

    // -------------------------------------------------------------------------
    // Board initialisation
    // -------------------------------------------------------------------------

    /**
     * Builds an 8×8 board filled with {@code EMPTY}.  The four input strings
     * are copied into the central 4×4 region (indices {@code 2..5}).
     */
    private static char[][] initialiseBoard(String[] inputs) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        fillBoard(board, EMPTY);

        // Populate the playable area.
        for (int i = PLAYGROUND_START; i < PLAYGROUND_END; ++i) {
            for (int j = PLAYGROUND_START; j < PLAYGROUND_END; ++j) {
                board[i][j] = inputs[i - PLAYGROUND_START].charAt(j - PLAYGROUND_START);
            }
        }
        return board;
    }

    private static void fillBoard(char[][] board, char value) {
        for (int i = 0; i < BOARD_SIZE; ++i) {
            java.util.Arrays.fill(board[i], value);
        }
    }

    // -------------------------------------------------------------------------
    // Depth‑first search for a winning configuration
    // -------------------------------------------------------------------------

    /**
     * Checks whether planting a seed at {@code (row, col)} results in any
     * winning line of {@code WIN_LENGTH} identical symbols.
     *
     * @return {@code true} if a winning line is found.
     */
    private static boolean dfsCheck(char[][] board, int row, int col) {
        // There are six possible directions that can extend a line forward.
        // We only need to test forward directions; looking backwards would be
        // redundant because we start from every cell.
        Direction[] directions = {
                Direction.RIGHT,
                Direction.DOWN,
                Direction.DOWN_RIGHT,
                Direction.UP_LEFT,
                Direction.UP_RIGHT,
                Direction.DOWN_LEFT
        };

        for (Direction dir : directions) {
            if (hasWinningRun(board, row, col, dir)) {
                return true;    // early exit – a win has been discovered.
            }
        }
        return false;
    }

    /**
     * Determines whether a run of {@code WIN_LENGTH} consecutive {@code SEED}
     * characters starts at {@code (row, col)} and proceeds in the given
     * {@code Direction}.
     */
    private static boolean hasWinningRun(char[][] board, int row, int col, Direction dir) {
        int steps = 0;
        int curRow = row;
        int curCol = col;

        while (steps < WIN_LENGTH) {
            curRow += dir.rowOffset;
            curCol += dir.colOffset;

            // Guard against out‑of‑bounds accesses.
            if (!isInsideBoard(curRow, curCol)) {
                return false;
            }
            if (board[curRow][curCol] != SEED) {
                return false;
            }
            ++steps;
        }
        return true;
    }

    private static boolean isInsideBoard(int row, int col) {
        return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE;
    }

    // -------------------------------------------------------------------------
    // Helper enum – encapsulates movement vectors
    // -------------------------------------------------------------------------

    /**
     * Encapsulates the eight cardinal directions that can be traversed on the
     * board.  Only the six directions needed for forward‑looking checks are
     * used; the enum makes the intent explicit.
     */
    private enum Direction {
        RIGHT(0, 1),
        DOWN(1, 0),
        DOWN_RIGHT(1, 1),
        UP_LEFT(-1, -1),
        UP_RIGHT(-1, 1),
        DOWN_LEFT(1, -1);

        final int rowOffset;
        final int colOffset;

        Direction(int rowOffset, int colOffset) {
            this.rowOffset = rowOffset;
            this.colOffset = colOffset;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintStream;

/**
 * Refactored version of the original program.
 *
 * <p>
 * The code now:
 * <ul>
 *   <li>Uses clear constants instead of magic numbers.</li>
 *   <li>Separates the win‑checking logic into small, reusable methods.</li>
 *   <li>Avoids duplicated loops and «break label» constructs.</li>
 *   <li>Keeps the original I/O handling (custom {@code MyScanner}) but makes it
 *       static and easier to read.</li>
 * </ul>
 * </p>
 */
public class Main {

    private static final int BOARD_SIZE = 4;
    private static final char PLAYER_X = 'x';
    private static final char OPPONENT_O = 'o';

    public static void main(String[] args) throws IOException {
        MyScanner scanner = new MyScanner();
        PrintStream out = System.out;

        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = scanner.next();
            board[i] = line.toCharArray();
        }

        scanner.close();
        out.println(hasXWin(board) ? "YES" : "NO");
        out.close();
    }

    /**
     * Returns {@code true} if player {@code X} can complete a line of three
     * consecutive marks, allowing {@code '.'} cells but requiring that the
     * line contains no opponent marks.
     */
    private static boolean hasXWin(char[][] board) {
        // Horizontal lines
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c <= BOARD_SIZE - 3; c++) {
                if (canWinLine(board, r, c, 0, 1)) {
                    return true;
                }
            }
        }

        // Vertical lines
        for (int c = 0; c < BOARD_SIZE; c++) {
            for (int r = 0; r <= BOARD_SIZE - 3; r++) {
                if (canWinLine(board, r, c, 1, 0)) {
                    return true;
                }
            }
        }

        // Diagonal down‑right
        for (int r = 0; r <= BOARD_SIZE - 3; r++) {
            for (int c = 0; c <= BOARD_SIZE - 3; c++) {
                if (canWinLine(board, r, c, 1, 1)) {
                    return true;
                }
            }
        }

        // Diagonal down‑left
        for (int r = 0; r <= BOARD_SIZE - 3; r++) {
            for (int c = BOARD_SIZE - 1; c >= 2; c--) {
                if (canWinLine(board, r, c, 1, -1)) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Checks a 3‑cell line that starts at {@code (startRow,startCol)} and moves
     * by {@code (dr,dc)}. The line can be completed by {@code X} if it contains
     * at least two {@code X} marks and no opponent marks.
     */
    private static boolean canWinLine(char[][] b, int startRow, int startCol,
                                      int dr, int dc) {
        int xCount = 0;
        for (int i = 0; i < 3; i++) {
            int r = startRow + i * dr;
            int c = startCol + i * dc;
            char cell = b[r][c];

            if (cell == OPPONENT_O) {
                // Opponent blocks the potential win.
                return false;
            }
            if (cell == PLAYER_X) {
                xCount++;
            }
        }
        // Need at least two X's to be able to win.
        return xCount >= 2;
    }

    /* --------------------------------------------------------------- */
    /*  Scanner utilities – kept identical to the original version    */
    /* --------------------------------------------------------------- */
    static class MyScanner {
        private final BufferedReader reader;

        MyScanner() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        void close() throws IOException {
            reader.close();
        }

        String next() throws IOException {
            return reader.readLine().trim();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for the “4×4 Tic‑Tac‑Toe” problem.
 * The program reads a 4×4 board consisting of '.', 'x' and 'o',
 * tries to place an extra ‘x’ in any empty cell and prints
 * “YES” if that creates a line of three consecutive ‘x’s,
 * otherwise prints “NO”.
 *
 * The refactor improves readability, separates concerns and removes
 * magic numbers by using constants and well‑named methods.
 */
public class Main {

    /** Size of the board (fixed 4×4). */
    private static final int BOARD_SIZE = 4;

    /** Entry point. */
    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        Solver solver = new Solver();
        solver.solve(reader, out);

        out.flush();      // no explicit close – easy for competitive environments
    }

    /** Simple fast scanner that works with whitespace‑separated tokens. */
    static class InputReader {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            br = new BufferedReader(new BufferedReader(new InputStreamReader(stream)));
        }

        /** Returns the next token, reading a new line if necessary. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }
    }

    /** Core logic of the problem. */
    static class Solver {

        /** Reads exactly four 4‑character tokens and builds the board. */
        private char[][] readBoard(InputReader in) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                board[i] = in.next().toCharArray();
            }
            return board;
        }

        /** Tries to place an ‘x’ in every empty cell and checks for a winning line. */
        void solve(InputReader in, PrintWriter out) {
            char[][] board = readBoard(in);
            out.println(canWinByPlacingX(board) ? "YES" : "NO");
        }

        /** Returns true if placing an ‘x’ in any ‘.’ position yields a line of three ‘x’s. */
        private boolean canWinByPlacingX(char[][] board) {
            for (int row = 0; row < BOARD_SIZE; row++) {
                for (int col = 0; col < BOARD_SIZE; col++) {
                    if (board[row][col] == '.') {
                        board[row][col] = 'x';
                        if (hasWinningThreeX(board)) {
                            board[row][col] = '.';
                            return true;
                        }
                        board[row][col] = '.';
                    }
                }
            }
            return false;
        }

        /** Checks whether the given board contains any line of three consecutive ‘x’s. */
        private boolean hasWinningThreeX(char[][] b) {
            int n = BOARD_SIZE;
            // four directions: right, down, down‑right, down‑left
            int[][] dirs = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};

            for (int[] d : dirs) {
                int dr = d[0], dc = d[1];
                for (int r = 0; r < n; r++) {
                    for (int c = 0; c < n; c++) {
                        int r2 = r + 2 * dr;
                        int c2 = c + 2 * dc;
                        if (r2 >= 0 && r2 < n && c2 >= 0 && c2 < n) {
                            StringBuilder line = new StringBuilder(3);
                            for (int k = 0; k < 3; k++) {
                                line.append(b[r + k * dr][c + k * dc]);
                            }
                            if (line.toString().equals("xxx")) {
                                return true;
                            }
                        }
                    }
                }
            }
            return false;
        }
    }
}

import java.io.*;

import java.util.Arrays;

/**
 * Tic‑Tac‑Toe (4×4) solver.
 *
 * Reads a 4 × 4 board from standard input where each cell contains
 * 'x', 'o' or '.' (empty).  The program decides whether the player
 * who *has to move* can create a line of three of his marks
 * (considering at most one empty cell in that line).  The answer
 * is printed as “YES” or “NO”.
 *
 * The code has been refactored for readability, maintainability
 * and testability.
 */
public class TicTacToe {

    private static final int BOARD_SIZE = 4;
    private static final char EMPTY = '.';
    private static final char PLAYER_X = 'x';
    private static final char PLAYER_O = 'o';

    /** The game board – rows are stored consecutively. */
    private static char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

    /** Direction vectors for all lines of length 3 that we need to examine. */
    private static final int[] DX = {1, 1, 1, 0};
    private static final int[] DY = {0, 1, -1, 1};

    public static void main(String[] args) throws Exception {
        readBoard();
        int countX = countOccurrences(PLAYER_X);
        int countO = countOccurrences(PLAYER_O);

        String answer;
        if (countX == countO) {
            answer = decideWinner(PLAYER_X) ? "YES" : "NO";
        } else {
            answer = decideWinner(PLAYER_O) ? "YES" : "NO";
        }

        System.out.println(answer);
    }

    /** Reads the 4 × 4 board from standard input. */
    private static void readBoard() throws IOException {
        // Using try‑with‑resources guarantees the stream is closed.
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in))) {
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = reader.readLine();
                if (line == null || line.isEmpty()) {
                    throw new IOException("Not enough input lines");
                }
                board[i] = line.toCharArray();
            }
        }
    }

    /** Count how many times the given symbol occurs on the board. */
    private static int countOccurrences(char symbol) {
        int cnt = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == symbol) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /** Returns true if the supplied player can complete a winning line. */
    private static boolean decideWinner(char player) {
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                if (isPotentialWin(row, col, player)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Checks whether a line of three starting at (row,col) can become a win
     *  for the given player, assuming at most one empty cell in that line. */
    private static boolean isPotentialWin(int row, int col, char player) {
        for (int dir = 0; dir < DX.length; dir++) {
            if (expand(row, col, player, DX[dir], DY[dir])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Simulates three consecutive steps in the direction (dx,dy) starting
     * from (row,col).  The method returns true if the line contains exactly
     * three relevant cells, of which at most one is empty and the rest are
     * the target player's marks.
     */
    private static boolean expand(int row, int col, char player,
                                  int dx, int dy) {
        int filled = 0;  // number of player's marks encountered
        int empty  = 0;  // number of empty cells encountered

        for (int step = 0; step < 3; step++) {
            int nx = row + dx * step;
            int ny = col + dy * step;

            if (!isInsideBoard(nx, ny)) {
                return false;                     // outside the board
            }

            char cell = board[nx][ny];
            if (cell == player) {
                filled++;
            } else if (cell == EMPTY) {
                empty++;
            } else {
                // Any other piece (including opponent) breaks the potential line.
                return false;
            }
        }

        // Valid winning pattern: total considered cells == 3 and <= 1 empty.
        return (filled + empty) == 3 && empty <= 1;
    }

    /** Helper to test whether a coordinate lies inside the 4×4 board. */
    private static boolean isInsideBoard(int r, int c) {
        return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
    }
}

import java.io.BufferedReader;
