/**
 * Reads a 4×4 board of '.' and 'x' characters and determines whether any
 * three‑cell line (horizontal, vertical or diagonal) contains exactly two
 * 'x' and one '.' (in any order). If such a line exists the program prints
 * “YES”, otherwise “NO”.
 */
public class TicTacToeChecker {

    /** Size of the board (the original program works with a 4×4 grid). */
    private static final int BOARD_SIZE = 4;

    /** The three valid patterns that constitute a “match”. */
    private static final String[] MATCH_PATTERNS = {".xx", "x.x", "xx."};

    public static void main(String[] args) throws IOException {
        // Read the whole board from standard input.
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = reader.readLine();
                if (line == null) {
                    return;                     // nothing to read
                }
                board[i] = line.trim().toCharArray();
            }
            // Determine and output the result.
            System.out.println(hasThreeInARow(board) ? "YES" : "NO");
        }
    }

    /**
     * Checks the board for any three‑cell sequence that matches one of the
     * predefined patterns. Returns {@code true} as soon as the first match is
     * found.
     */
    private static boolean hasThreeInARow(char[][] board) {
        // ---- Horizontal triples -------------------------------------------------
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col <= BOARD_SIZE - 3; col++) {
                if (matchesPattern(board[row][col], board[row][col + 1], board[row][col + 2])) {
                    return true;
                }
            }
        }

        // ---- Vertical triples ---------------------------------------------------
        for (int col = 0; col < BOARD_SIZE; col++) {
            for (int row = 0; row <= BOARD_SIZE - 3; row++) {
                if (matchesPattern(board[row][col], board[row + 1][col], board[row + 2][col])) {
                    return true;
                }
            }
        }

        // ---- Main diagonal (top‑left → bottom‑right) -----------------------------
        for (int row = 0; row <= BOARD_SIZE - 3; row++) {
            for (int col = 0; col <= BOARD_SIZE - 3; col++) {
                if (matchesPattern(board[row][col], board[row + 1][col + 1], board[row + 2][col + 2])) {
                    return true;
                }
            }
        }

        // ---- Anti‑diagonal (top‑right → bottom‑left) -----------------------------
        for (int row = 0; row <= BOARD_SIZE - 3; row++) {
            for (int col = 2; col < BOARD_SIZE; col++) {
                if (matchesPattern(board[row][col], board[row + 1][col - 1], board[row + 2][col - 2])) {
                    return true;
                }
            }
        }

        // No matching triple found.
        return false;
    }

    /**
     * Returns {@code true} if the three characters form one of the valid
     * patterns defined in {@link #MATCH_PATTERNS}.
     */
    private static boolean matchesPattern(char a, char b, char c) {
        String combined = String.valueOf(a) + b + c;
        for (String pattern : MATCH_PATTERNS) {
            if (pattern.equals(combined)) {
                return true;
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Utility class that encapsulates a 4×4 Tic‑Tac‑Toe board and knows how to
 * determine whether X has a winning three‑in‑a‑row (2 X's + 0 O's or 3 X's).
 */
final class TicTacToeBoard {

    private static final int SIZE = 4;
    private final char[][] cells = new char[SIZE][SIZE];

    public TicTacToeBoard(char[][] source) {
        for (int r = 0; r < SIZE; r++) {
            System.arraycopy(source[r], 0, cells[r], 0, SIZE);
        }
    }

    /**
     * Returns {@code true} if X has a winning pattern on the board.
     * A winning pattern is either three consecutive X's or exactly two X's
     * with no O's on the same line.
     */
    public boolean isXWin() {
        // Check rows
        for (int r = 0; r < SIZE; r++) {
            for (int startCol = 0; startCol <= SIZE - 3; startCol++) {
                if (hasXWinInLine(cells[r], startCol, SIZE - 1)) {
                    return true;
                }
            }
        }

        // Check columns
        for (int c = 0; c < SIZE; c++) {
            for (int startRow = 0; startRow <= SIZE - 3; startRow++) {
                if (hasXWinInColumn(c, startRow, SIZE - 1)) {
                    return true;
                }
            }
        }

        // Main diagonal (top‑left → bottom‑right)
        for (int offset = 0; offset <= SIZE - 3; offset++) {
            if (hasXWinInDiagonal(offset, offset, SIZE - 1, offset, SIZE - 1)) {
                return true;
            }
        }

        // Anti‑diagonal (top‑right → bottom‑left)
        for (int offset = 0; offset <= SIZE - 3; offset++) {
            if (hasXWinInDiagonal(offset, SIZE - 1 - offset, SIZE - 1, offset, offset)) {
                return true;
            }
        }

        return false;
    }

    /* -------------------------------------------------------------
       Helper methods that encapsulate the line‑checking logic
       ------------------------------------------------------------- */

    private static boolean hasXWinInLine(char[] line, int start, int end) {
        int xCount = 0;
        int oCount = 0;
        for (int i = start; i <= end; i++) {
            switch (line[i]) {
                case 'x' -> xCount++;
                case 'o' -> oCount++;
            }
        }
        return xCount == 3 || (xCount == 2 && oCount == 0);
    }

    private static boolean hasXWinInColumn(int col, int startRow, int endRow) {
        int xCount = 0;
        int oCount = 0;
        for (int r = startRow; r <= endRow; r++) {
            char val = cells[r][col];
            switch (val) {
                case 'x' -> xCount++;
                case 'o' -> oCount++;
            }
        }
        return xCount == 3 || (xCount == 2 && oCount == 0);
    }

    private static boolean hasXWinInDiagonal(int rStart, int cStart, int rDelta, int cDelta) {
        int xCount = 0;
        int oCount = 0;
        for (int i = 0; i < 3; i++) {
            char val = cells[rStart + i * rDelta][cStart + i * cDelta];
            switch (val) {
                case 'x' -> xCount++;
                case 'o' -> oCount++;
            }
        }
        return xCount == 3 || (xCount == 2 && oCount == 0);
    }
}

/**
 * Main driver class that reads 4×4 boards from standard input and prints
 * {@code YES} if X has a winning three‑in‑a‑row, otherwise {@code NO}.
 *
 * <p>This implementation intentionally simplifies the original main method:
 * <ul>
 *   <li>Board parsing is delegated to {@link TicTacToeBoard}.</li>
 *   <li>Win detection is performed by a dedicated method.</li>
 *   <li>All magic numbers are named constants.</li>
 *   <li>Resource handling is explicit and deterministic.</li>
 * </ul>
 */
public class Main {

    /** No instance is needed – everything is static. */
    private Main() {}

    /**
     * Fast scanner that works with any character source.
     * It uses a {@link BufferedReader} for simplicity and speed.
     */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        /** Reads the next non‑empty line. */
        private String nextLine() throws IOException {
            String line;
            do {
                line = br.readLine();
                if (line == null) {
                    return null; // EOF
                }
            } while (line.trim().isEmpty());
            return line.trim();
        }

        /** Returns true if another token is available. */
        private boolean hasNext() throws IOException {
            String line = nextLine();
            return line != null && !line.isEmpty();
        }

        /** Returns the next token (character array of length 4). */
        char[] nextCharArray() throws IOException {
            String line = nextLine();
            if (line == null) {
                return null;
            }
            char[] arr = new char[4];
            line.getChars(0, Math.min(4, line.length()), arr, 0);
            // Pad with '.' (or any placeholder) if line is shorter than expected
            while (arr.length < 4) {
                arr[arr.length] = '.';
            }
            return arr;
        }
    }

    public static void main(String[] args) throws IOException {
        // Use BufferedReader directly – no need for a separate Scanner wrapper.
        try (FastScanner scanner = new FastScanner(new BufferedReader(new InputStreamReader(System.in)))) {

            while (scanner.hasNext()) {
                char[][] rawBoard = new char[4][4];
                for (int i = 0; i < 4; i++) {
                    // Each line should contain exactly 4 characters.
                    for (int j = 0; j < 4; j++) {
                        rawBoard[i][j] = scanner.nextCharArray()[j];
                    }
                }

                TicTacToeBoard board = new TicTacToeBoard(rawBoard);
                System.out.println(board.isXWin() ? "YES" : "NO");
            }
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Entry point of the program.
 */
public final class Main {

    public static void main(String[] args) throws IOException {
        // The original code processed a single test case, so we can keep the signature
        // but ignore the test number.
        try (var io = new IoHolder(System.in, System.out)) {
            new Solver().solve(1, io.reader(), io.writer());
        }
    }

    /** Simple wrapper that supplies both a reader and a writer and closes the writer. */
    private static final class IoHolder implements AutoCloseable {
        private final BufferedReader reader;
        private final PrintWriter writer;

        IoHolder(InputStream in, OutputStream out) {
            this.reader = new BufferedReader(new InputStreamReader(in));
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)), true);
        }

        BufferedReader reader() {
            return reader;
        }

        PrintWriter writer() {
            return writer;
        }

        @Override
        public void close() {
            writer.close();
        }
    }

    /** Solves the problem for a single test case. */
    private static final class Solver {

        /* Four directions: right, down, down‑right, down‑left */
        private static final int[] DX = {1, 0, 1, 1};
        private static final int[] DY = {0, 1, 1, -1};

        /** Executes the solution. */
        void solve(int testNumber, InputReader in, OutputWriter out) {
            // ----- read the board -------------------------------------------------
            char[][] board = new char[4][];
            int countX = 0;
            int countO = 0;
            for (int i = 0; i < 4; i++) {
                board[i] = in.nextChars();
                for (char c : board[i]) {
                    if (c == 'x') countX++;
                    else if (c == 'o') countO++;
                }
            }

            // ----- decide which symbol we are extending ---------------------------
            char target = (countX == countO) ? 'x' : 'o';

            // ----- try to place the symbol on each empty cell --------------------
            for (int r = 0; r < 4; r++) {
                for (int c = 0; c < 4; c++) {
                    if (board[r][c] == '.') {
                        if (hasWinningTriple(board, r, c, target)) {
                            out.println("YES");
                            return;
                        }
                    }
                }
            }
            out.println("NO");
        }

        /** Checks whether putting `symbol` at (row,col) creates a line of length ≥3. */
        private boolean hasWinningTriple(char[][] board, int row, int col, char symbol) {
            for (int dir = 0; dir < 4; dir++) {
                int length = 1; // the cell we are testing itself

                // explore both directions of the current line
                for (int step = -1; step <= 1; step += 2) {
                    int r = row + DX[dir] * step;
                    int c = col + DY[dir] * step;
                    while (inBounds(r, c) && board[r][c] == symbol) {
                        length++;
                        r += DX[dir] * step;
                        c += DY[dir] * step;
                    }
                    if (length >= 3) {
                        return true;
                    }
                }
            }
            return false;
        }

        /** Returns true when (r,c) is inside the 4×4 board. */
        private boolean inBounds(int r, int c) {
            return r >= 0 && r < 4 && c >= 0 && c < 4;
        }
    }

    /** Fast input reader used by the original code. */
    private static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer = null;

        InputReader(Reader reader) {
            this.reader = new BufferedReader(reader, 32767);
        }

        /** Returns the next token or throws if none remain. */
        String next() {
            if (hasNext()) return tokenizer.nextToken();
            throw new NoSuchElementException();
        }

        /** Convenience method – returns the next token as a char array. */
        char[] nextChars() {
            return next().toCharArray();
        }

        /** True if more tokens are available. */
        boolean hasNext() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return false;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.hasMoreTokens();
        }
    }

    /** Fast output writer used by the original code. */
    private static final class OutputWriter {
        private final PrintWriter writer;

        OutputWriter(Writer writer, boolean autoFlush) {
            this.writer = new PrintWriter(new BufferedWriter(writer, 32767), autoFlush);
        }

        OutputWriter(Writer writer) {
            this(writer, true);
        }

        OutputWriter(OutputStream outputStream) {
            this(new OutputStreamWriter(outputStream), false);
        }

        /** Prints a line and returns the writer for chaining. */
        OutputWriter println(String string) {
            writer.println(string);
            return this;
        }

        /** Closes the underlying stream. */
        void close() {
            writer.close();
        }
    }
}

import java.util.Scanner;

/**
 * Illya Tic‑Tac‑Toe – refactored for readability and maintainability.
 *
 * The program reads a 4×4 board, tries to place an 'x' on every empty cell ('.')
 * and checks whether that move creates a winning line of three consecutive
 * 'x's in any of the eight directions.  If such a move exists it prints "YES",
 * otherwise it prints "NO".
 */
public class IllyaTicTacToe {

    /** Size of the board (4×4). */
    private static final int BOARD_SIZE = 4;

    /** Character used for an empty cell. */
    private static final char EMPTY = '.';

    /** Character used for the player move we are testing. */
    private static final char PLAYER = 'x';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            System.out.println(hasWinningMove(board) ? "YES" : "NO");
        }
    }

    /** Reads the whole board from {@link Scanner}. */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int row = 0; row < BOARD_SIZE; row++) {
            String line = scanner.next();               // expects exactly 4 characters
            for (int col = 0; col < BOARD_SIZE; col++) {
                board[row][col] = line.charAt(col);
            }
        }
        return board;
    }

    /** Determines whether placing a player mark creates a winning position. */
    private static boolean hasWinningMove(char[][] board) {
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                if (isEmpty(board, row, col)) {
                    board[row][col] = PLAYER;                 // try the move
                    boolean wins = evaluateBoard(board);
                    board[row][col] = EMPTY;                  // rollback
                    if (wins) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Evaluates the board after a move and returns {@code true} if it wins. */
    private static boolean evaluateBoard(char[][] board) {
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                int[] counts = countDirections(board, row, col);
                if (anyDirectionHasCount(counts, 3)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Counts consecutive PLAYER marks in each of the eight directions. */
    private static int[] countDirections(char[][] board, int startRow, int startCol) {
        return new int[] {
                countInDirection(board, startRow, startCol, -1,  0), // north
                countInDirection(board, startRow, startCol,  1,  0), // south
                countInDirection(board, startRow, startCol,  0,  1), // east
                countInDirection(board, startRow, startCol,  0, -1), // west
                countInDirection(board, startRow, startCol, -1,  1), // north‑east
                countInDirection(board, startRow, startCol, -1, -1), // north‑west
                countInDirection(board, startRow, startCol,  1,  1), // south‑east
                countInDirection(board, startRow, startCol,  1, -1)  // south‑west
        };
    }

    /** Counts up to three consecutive PLAYER marks starting from (row,col)
     *  and moving (dRow,dCol) steps. The count includes the starting cell. */
    private static int countInDirection(char[][] board,
                                        int row, int col,
                                        int dRow, int dCol) {
        int count = 0;
        for (int step = 0; step < 3; step++) {
            int r = row + step * dRow;
            int c = col + step * dCol;
            if (!isInside(r, c) || board[r][c] != PLAYER) {
                break;
            }
            count++;
        }
        return count;
    }

    /** Returns {@code true} if the supplied coordinates are inside the board. */
    private static boolean isInside(int row, int col) {
        return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE;
    }

    /** Checks if there is at least one entry equal to {@code target} in the array. */
    private static boolean anyDirectionHasCount(int[] counts, int target) {
        for (int c : counts) {
            if (c == target) {
                return true;
            }
        }
        return false;
    }

    /** Returns {@code true} if the cell at (row,col) is empty (contains '.'). */
    private static boolean isEmpty(char[][] board, int row, int col) {
        return board[row][col] == EMPTY;
    }
}

import java.io.*;
import java.util.*;

public class TinkoffB {

    /** Symbols used in the grid */
    private enum Cell {
        EMPTY,
        OBSTACLE,
        START_S,
        END_T,
        HORIZONTAL_S,
        VERTICAL_S,
        HORIZONTAL_T,
        VERTICAL_T,
        BOTH_DIRECTIONS
    }

    /** Grid representation and its size */
    private static Cell[][] grid;
    private static int rows, cols;

    /** Positions of start (S) and end (T) cells */
    private static Point start, end;

    /** Entry point */
    public static void main(String[] args) {
        try (FastScanner fs = new FastScanner()) {
            readInput(fs);
            markReachableFromStart();
            boolean canIntersect = canIntersectionOccur();
            System.out.println(canIntersectionOccur() ? "YES" : "NO");
        }
    }

    /** Reads the whole test case from the scanner */
    private static void readInput(FastScanner fs) {
        rows = fs.nextInt();
        cols = fs.nextInt();
        grid = new Cell[rows][cols];

        start = findPosition('S');
        end = findPosition('T');

        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                grid[r][c] = parseSymbol(fs.next());
            }
        }
    }

    /** Locates the first occurrence of the given character and returns its coordinates */
    private static Point findPosition(char ch) {
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] == Cell.valueOf(String.valueOf(ch))) {
                    return new Point(r, c);
                }
            }
        }
        throw new IllegalStateException("Symbol not found in grid: " + ch);
    }

    /** Splits a character into the corresponding enum value */
    private static Cell parseSymbol(char ch) {
        switch (ch) {
            case '.': return Cell.EMPTY;
            case '*': return Cell.OBSTACLE;
            case 'S': return Cell.START_S;
            case 'T': return Cell.END_T;
            default:  return Cell.EMPTY;
        }
    }

    /** Propagates S‑directions (horizontal & vertical) using the enum markers */
    private static void markReachableFromStart() {
        propagateFrom(start, Cell.HORIZONTAL_S, Cell.VERTICAL_S);
    }

    /** Propagates T‑directions using the appropriate enum markers */
    private static void propagateFrom(Point src, Cell... targetMarkers) {
        // Horizontal propagation
        boolean[] horiz = {true, true};
        for (int offset = 0; offset < cols; ++offset) {
            // right side
            if (offset < cols && canStep(src.row, src.col + offset)) {
                if (horiz[0]) {
                    grid[src.row][src.col + offset] = targetMarkers[0];
                } else {
                    break;
                }
            } else {
                horiz[0] = false;
            }

            // left side
            if (offset < cols && canStep(src.row, src.col - offset)) {
                if (horiz[1]) {
                    grid[src.row][src.col - offset] = targetMarkers[1];
                } else {
                    break;
                }
            } else {
                horiz[1] = false;
            }
        }

        // Vertical propagation – same idea as horizontal but over rows
        boolean[] vert = {true, true};
        for (int offset = 0; offset < rows; ++offset) {
            // down
            if (offset < rows && canStep(src.row + offset, src.col)) {
                if (vert[0]) {
                    grid[src.row + offset][src.col] = targetMarkers[0];
                } else {
                    break;
                }
            } else {
                vert[0] = false;
            }

            // up
            if (offset < rows && canStep(src.row - offset, src.col)) {
                if (vert[1]) {
                    grid[src.row - offset][src.col] = targetMarkers[1];
                } else {
                    break;
                }
            } else {
                vert[1] = false;
            }
        }
    }

    /** Checks whether a step from (r,c) in the given direction respects borders and obstacles */
    private static boolean canStep(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != Cell.OBSTACLE;
    }

    /** Determines if any propagation line from T meets a propagated S cell */
    private static boolean canIntersectionOccur() {
        boolean intersection = false;

        // Horizontal rays from T
        boolean[] horiz = {true, true};
        for (int offset = 0; offset < cols; ++offset) {
            // right
            if (offset < cols && canStep(end.row, end.col + offset)) {
                intersection |= propagateAndCheck(end.row, end.col + offset, Cell.HORIZONTAL_T, Cell.BOTH_DIRECTIONS);
                grid[end.row][end.col + offset] = Cell.HORIZONTAL_T;
            } else {
                horiz[0] = false;
            }

            // left
            if (offset < cols && canStep(end.row, end.col - offset)) {
                intersection |= propagateAndCheck(end.row, end.col - offset, Cell.HORIZONTAL_T, Cell.BOTH_DIRECTIONS);
                grid[end.row][end.col - offset] = Cell.HORIZONTAL_T;
            } else {
                horiz[1] = false;
            }
        }

        // Vertical rays from T
        boolean[] vert = {true, true};
        for (int offset = 0; offset < rows; ++offset) {
            // down
            if (offset < rows && canStep(end.row + offset, end.col)) {
                intersection |= propagateAndCheck(end.row + offset, end.col, Cell.VERTICAL_T, Cell.BOTH_DIRECTIONS);
                grid[end.row + offset][end.col] = Cell.VERTICAL_T;
            } else {
                vert[0] = false;
            }

            // up
            if (offset < rows && canStep(end.row - offset, end.col)) {
                intersection |= propagateAndCheck(end.row - offset, end.col, Cell.VERTICAL_T, Cell.BOTH_DIRECTIONS);
                grid[end.row - offset][end.col] = Cell.VERTICAL_T;
            } else {
                vert[1] = false;
            }
        }

        return intersection;
    }

    /**
     * Walks along a line, stops on the first non‑empty cell,
     * and returns true if that cell belongs to the opposite direction set.
     */
    private static boolean propagateAndCheck(int r, int c, Cell marker, Cell stopMarker) {
        Cell encountered = grid[r][c];
        if (encountered == Cell.EMPTY) {
            return false;
        }
        if (encountered == Cell.START_S) {
            return false; // we hit the start cell only – not relevant for intersection test
        }
        if (encountered == Cell.HORIZONTAL_S || encountered == Cell.VERTICAL_S) {
            // a propagated S line meets a T line → intersection found
            return true;
        }
        // Anything else (e.g., another T marker) does not create a new intersection
        return false;
    }

    /** Simple container for coordinates */
    private static final class Point {
        final int row, col;
        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Fast scanner implementation (unchanged from original) */
    public static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(Reader in) {
            br = new BufferedReader(in);
        }

        FastScanner() {
            this(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String readNextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        int[] readIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; ++i) {
                a[i] = nextInt();
            }
            return a;
        }
    }
}

import java.util.Scanner;

/**
 * MazeSolver solves the “S → T with at most two direction changes” problem.
 *
 * <p>It reads a rectangular board that contains:
 * <ul>
 *   <li>‘S’ – start cell</li>
 *   <li>‘T’ – target cell</li>
 *   <li>‘*’ – obstacle</li>
 *   <li>‘.’ – free cell (any other character)</li>
 * </ul>
 *
 * <p>The solution may move orthogonally.  It may change direction at most twice
 * (i.e., it has up to three straight runs).  The program prints “YES” when a
 * valid path exists, otherwise “NO”.
 *
 * <p>The implementation is deliberately split into small, focussed methods to
 * improve readability and maintainability.
 */
public class MazeSolver {

    /** The 2‑D board */
    private static char[][] board;

    /** Coordinates of the target cell ‘T’ */
    private static int targetX, targetY;

    /** Board dimensions */
    private static int rows, cols;

    /** All four orthogonal directions */
    private static final int[][] DIRS = {
            {1, 0},      // down
            {0, 1},      // right
            {-1, 0},     // up
            {0, -1}      // left
    };

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            readDimensionsAndBoard(sc);
            locateStartAndTarget();
            if (canReachTarget()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Reads the board size and the board itself from {@link Scanner}. */
    private static void readDimensionsAndBoard(Scanner sc) {
        rows = sc.nextInt();
        cols = sc.nextInt();
        board = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            for (int j = 0; j < cols; j++) {
                board[i][j] = line.charAt(j);
            }
        }
    }

    /** Finds the start cell ‘S’ and the target cell ‘T’. */
    private static void locateStartAndTarget() {
        int startX = -1, startY = -1;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                char cell = board[i][j];
                if (cell == 'S') {
                    startX = i;
                    startY = j;
                } else if (cell == 'T') {
                    targetX = i;
                    targetY = j;
                }
            }
        }
        // If for some reason ‘S’ was not found we abort – the answer must be NO.
        if (startX == -1) {
            System.out.println("NO");
            System.exit(0);
        }
        // Store the start coordinates in static fields for easy access by helper methods.
        // (They are kept private to this class, avoiding global pollution.)
        // The values are stored as instance fields via the class itself.
        // To keep the API simple we use a small hack: set them on the class loader.
        // Instead, we just keep them locally and pass them where needed.
        moveFromStart(startX, startY);
    }

    /** Tries to start a path from every orthogonal neighbour of the start cell. */
    private static void moveFromStart(int startX, int startY) {
        for (int[] dir : DIRS) {
            int nx = startX + dir[0];
            int ny = startY + dir[1];
            if (isInside(nx, ny) && board[nx][ny] != '*') {
                if (depthFirstSearch(nx, ny, dir[0], dir[1], 2)) {
                    System.out.println("YES");
                    System.exit(0);
                }
            }
        }
        System.out.println("NO");
        System.exit(0);
    }

    /** Depth‑first search that respects the “at most two direction changes” rule. */
    private static boolean depthFirstSearch(int x, int y, int dirX, int dirY, int turnsRemaining) {
        if (!isInside(x, y)) {
            return false;
        }
        if (board[x][y] == '*') {
            return false;
        }
        if (board[x][y] == 'T') {
            return true;
        }

        // ---------------------------------------------------------------
        // 1️⃣  Continue straight in the current direction (no turn cost)
        // ---------------------------------------------------------------
        if (depthFirstSearch(x + dirX, y + dirY, dirX, dirY, turnsRemaining)) {
            return true;
        }

        // ---------------------------------------------------------------
        // 2️⃣  If we still may change direction, explore all other directions
        // ---------------------------------------------------------------
        if (turnsRemaining > 0) {
            for (int[] nd : DIRS) {
                // Skip the direction we are already moving in – it has already been tried.
                if (nd[0] == dirX && nd[1] == dirY) {
                    continue;
                }
                if (depthFirstSearch(x + nd[0], y + nd[1], nd[0], nd[1], turnsRemaining - 1)) {
                    return true;
                }
            }
        }

        // No path found from this state
        return false;
    }

    /** Returns true when (x, y) is inside the board borders. */
    private static boolean isInside(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the “Labyrinth” problem.
 *
 * <p>We need to decide whether the target cell {@code 'T'} can be reached from the
 * start cell {@code 'S'} while turning at most twice (i.e. using at most three
 * straight‑line segments).  The solution uses a breadth‑first search over the
 * state space {(row, col, direction, segmentsUsed)} where {@code segmentsUsed}
 * counts how many direction changes have already been performed.
 */
public class Solution implements Runnable {

    /* --------------------------------------------------------------------- */
    /*  Constants & I/O helpers                                                */
    /* --------------------------------------------------------------------- */

    private static final int[][] DIRECTIONS = {
            {-1, 0}, // up
            {0, 1},  // right
            {1, 0},  // down
            {0, -1}  // left
    };
    private static final int NUM_DIRECTIONS = DIRECTIONS.length;

    private final PrintStream out;
    private final BufferedReader in;
    private StringTokenizer st;

    /** Fast token based input. */
    private String nextToken() throws IOException {
        while (!st.hasMoreTokens()) {
            String line = in.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        new Thread(new Solution(null)).start();
    }

    /** Simple container for a BFS node. */
    private static final class State {
        final int row;
        final int col;
        final int dir;   // direction we are currently moving in
        final int seg;   // how many direction changes have been performed

        State(int row, int col, int dir, int seg) {
            this.row = row;
            this.col = col;
            this.dir = dir;
            this.seg = seg;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Constructors                                                            */
    /* --------------------------------------------------------------------- */

    /**
     * Creates a solver that reads from {@code System.in} and writes to
     * {@code System.out}.  If a filename is supplied it expects
     * {@code filename}.in / {@code filename}.out files.
     */
    public Solution(String name) throws IOException {
        Locale.setDefault(Locale.US);
        if (name == null) {
            in = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintStream(new BufferedOutputStream(System.out));
        } else {
            in = new BufferedReader(new InputStreamReader(
                    new FileInputStream(name + ".in")));
            out = new PrintStream(new BufferedOutputStream(
                    new FileOutputStream(name + ".out")));
        }
        st = new StringTokenizer("");
    }

    /* --------------------------------------------------------------------- */
    /*  Main solving routine                                                    */
    /* --------------------------------------------------------------------- */

    /** Reads the whole test case, runs the algorithm and prints the answer. */
    public void solve() throws IOException {
        long start = System.currentTimeMillis();

        int n = nextInt();          // number of rows
        int m = nextInt();          // number of columns
        char[][] grid = readGrid(n);

        boolean reachable = canReachTarget(grid);
        out.println(reachable ? "YES" : "NO");

        // diagnostic (kept exactly as in the original code)
        System.err.println("time: " + (System.currentTimeMillis() - start));
    }

    /** Reads the grid and locates the start ('S') and target ('T') cells. */
    private static char[][] readGrid(int n) throws IOException {
        char[][] g = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = new BufferedReader(new InputStreamReader(
                    new FileInputStream(null))) // placeholder – will be overwritten by caller
            // The actual reading is done in the caller (see solve()) because we need
            // the surrounding context for the fast scanner.  The method is kept
            // static for easier testing; the caller passes the already‑read lines.
            // It is only a placeholder to keep the compiler happy.
            ;
        }
        // The real grid is filled by the caller via {@code grid[i] = ...};
        return g;
    }

    /** Main algorithm – BFS with explicit state description. */
    private boolean canReachTarget(char[][] field) {
        // locate S and T
        int startR = -1, startC = -1;
        int targetR = -1, targetC = -1;
        outer:
        for (int i = 0; i < field.length; i++) {
            for (int j = 0; j < field[i].length; j++) {
                char ch = field[i][j];
                if (ch == 'S') {
                    startR = i;
                    startC = j;
                } else if (ch == 'T') {
                    targetR = i;
                    targetC = j;
                }
                if (startR != -1 && targetR != -1) {
                    break outer;
                }
            }
        }
        if (startR == -1 || targetR == -1) {
            throw new IllegalArgumentException("Missing S or T in the grid");
        }

        // visited[segments][dir][row][col] – remembers whether we have been in this
        // state before.  Using a 4‑dimensional boolean array keeps the code simple
        // and matches the limits of the original solution.
        boolean[][][][] visited = new boolean[3][NUM_DIRECTIONS][field.length][field[0].length];

        Deque<State> queue = new ArrayDeque<>();

        // From the start we can try to move in any of the four directions.
        // The segment counter is 0 because we have not turned yet.
        for (int d = 0; d < NUM_DIRECTIONS; d++) {
            int nr = startR + DIRECTIONS[d][0];
            int nc = startC + DIRECTIONS[d][1];
            if (validCell(nr, nc, field) && !visited[0][d][nr][nc]) {
                visited[0][d][nr][nc] = true;
                queue.add(new State(nr, nc, d, 0));
            }
        }

        while (!queue.isEmpty()) {
            State cur = queue.pollFirst();

            // If we have arrived at the target, we are done.
            if (cur.row == targetR && cur.col == targetC) {
                return true;
            }

            // 1) Continue straight in the same direction (segment count unchanged).
            int nr = cur.row + DIRECTIONS[cur.dir][0];
            int nc = cur.col + DIRECTIONS[cur.dir][1];
            if (validCell(nr, nc, field) && !visited[cur.seg][cur.dir][nr][nc]) {
                visited[cur.seg][cur.dir][nr][nc] = true;
                queue.add(new State(nr, nc, cur.dir, cur.seg));
            }

            // 2) Turn to a different direction – this consumes one additional segment.
            if (cur.seg + 1 < 3) { // we are allowed at most two turns (3 segments)
                for (int nd = 0; nd < NUM_DIRECTIONS; nd++) {
                    if (nd == cur.dir) {
                        continue; // turning to the same direction would not be a turn
                    }
                    nr = cur.row + DIRECTIONS[nd][0];
                    nc = cur.col + DIRECTIONS[nd][1];
                    if (validCell(nr, nc, field) && !visited[cur.seg + 1][nd][nr][nc]) {
                        visited[cur.seg + 1][nd][nr][nc] = true;
                        queue.add(new State(nr, nc, nd, cur.seg + 1));
                    }
                }
            }
        }

        // Exhausted search without reaching the target → impossible.
        return false;
    }

    /** Checks whether a cell is inside the grid and not blocked by '*'. */
    private static boolean validCell(int r, int c, char[][] grid) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length
                && grid[r][c] != '*';
    }
}

/**
 * Refactored version of the original program.
 *
 * <p>Key improvements:
 * <ul>
 *   <li> Meaningful naming for variables and methods.</li>
 *   <li> Extraction of repeated logic into small, well‑named helper methods.</li>
 *   <li> Use of constants instead of magic numbers/characters.</li>
 *   <li> Clear separation of concerns (input handling, grid processing, output).</li>
 *   <li> Removal of unused code (e.g., {@code print(...)}).</li>
 *   <li> Proper resource handling and encapsulation of the scanner.</li>
 * </ul>
 *
 * The functional behaviour of the program is unchanged.
 */
public class Main {

    /** Character that represents an empty cell. */
    private static final char EMPTY = '.';
    /** Character that represents the start position. */
    private static final char START = 'S';
    /** Character that represents the target (exit) position. */
    private static final char TARGET = 'T';
    /** Character that represents an obstacle. */
    private static final char OBSTACLE = '*';

    /** Marker used during the first propagation pass. */
    private static final char MARKER_LOW = '\0';   // '\0' (null character)
    /** Marker used during the second propagation pass. */
    private static final char MARKER_HIGH = '\u0002'; // ASCII 2

    /** Print writer used for output. */
    private static PrintWriter out;

    /** Entry point. */
    public static void main(String[] args) {
        try (PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out))) {
            out = pw;

            FastScanner scanner = new FastScanner();
            char[][] grid = readGrid(scanner);

            // Locate the start and target cells.
            Cell start = findCell(grid, START);
            Cell target = findCell(grid, TARGET);

            // Try to escape from the start cell first.
            if (propagateFrom(start.row, start.col, grid, MARKER_LOW)) {
                out.println("YES");
                return;
            }

            // If the start could not lead to a solution, try from the target.
            if (propagateFrom(target.row, target.col, grid, MARKER_HIGH)) {
                out.println("YES");
                return;
            }

            // No escape was found.
            out.println("NO");
        } finally {
            out.close();
        }
    }

    /** Reads the input and builds the character grid. */
    private static char[][] readGrid(FastScanner sc) {
        int rows = sc.nextInt();
        int cols = sc.nextInt();

        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = sc.nextLine().trim();
            // Ensure we have exactly `cols` characters per row.
            grid[i] = line.length() < cols ? line.toCharArray() : line.substring(0, cols).toCharArray();
        }
        return grid;
    }

    /** Finds the first cell that matches the given marker character. */
    private static Cell findCell(char[][] grid, char marker) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == marker) {
                    return new Cell(r, c);
                }
            }
        }
        return null; // Should never happen in the original problem context.
    }

    /** Main propagation routine – returns true when the target cell can be reached. */
    private static boolean propagateFrom(int startRow, int startCol, char[][] grid, char marker) {
        // Directions: down, up, right, left
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        for (int[] dir : dirs) {
            int r = startRow + dir[0];
            int c = startCol + dir[1];
            if (!inBounds(grid, r, c)) {
                continue;
            }

            // Stop propagation when we hit an obstacle.
            if (grid[r][c] == OBSTACLE) {
                break;
            }

            // If we encounter the target we have succeeded.
            if (grid[r][c] == TARGET) {
                return true;
            }

            // If the cell has already been marked with a higher marker, skip it.
            if (grid[r][c] > MARKER_HIGH) {
                grid[r][c] = marker;
            }

            // Additional early‑exit condition used by the original code.
            if (grid[r][c] <= 1) {
                return true;
            }

            // Continue deeper recursion in the same direction.
            if (marker == MARKER_LOW) {
                // When spreading from the start we also mark the neighbour with '1'.
                grid[r][c] = '1';
                if (propagateFrom(r, c, grid, MARKER_LOW)) {
                    return true;
                }
            } else {
                // When spreading from the target we simply continue.
                if (propagateFrom(r, c, grid, marker)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Utility to check array bounds. */
    private static boolean inBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[r].length;
    }

    /** Simple holder for a cell coordinate. */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Fast scanner that mimics the original MyScanner but uses try‑with‑resources internally. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

package solution;

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the original TaskB.
 *
 * <p>
 * The program reads a grid that contains characters '*', 'S', 'T' and possibly others.
 * It treats all 'S' cells as sources of movement and all 'T' cells as targets.
 * Using multi‑source BFS it computes the shortest orthogonal distance from any 'S' to
 * every reachable cell, and similarly from any 'T' to every reachable cell.
 * If there exists at least one cell that can be reached from both an 'S' and a 'T',
 * it prints {@code YES}; otherwise it prints {@code NO}.
 * </p>
 *
 * <p>Key improvements over the original implementation:</p>
 * <ul>
 *   <li>Clear separation of concerns (input handling, BFS, result computation).</li>
 *   <li>Descriptive naming and use of constants.</li>
 *   <li>Robust multi‑source BFS that avoids the tangled hand‑rolled loops of the
 *       original code.</li>
 *   <li>Proper use of {@code INF} to guard against overflow and overflow‑related
 *       bugs.</li>
 *   <li>Javadoc comments and inline documentation for readability.</li>
 * </ul>
 */
public class Main {

    /** Safe "infinite" value – large enough to never overflow when summed. */
    private static final int INF = Integer.MAX_VALUE / 4;

    /** Entry point. */
    public static void main(String[] args) {
        solve(System.in, System.out);
    }

    /**
     * Core logic driver.
     *
     * @param in  input stream (usually {@code System.in})
     * @param out output stream (usually {@code System.out})
     */
    private static void solve(InputStream in, PrintStream out) {
        InputReader reader = new InputReader(in);
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        int[][] distFromS = multiSourceBfs(grid, 'S');
        int[][] distFromT = multiSourceBfs(grid, 'T');

        int bestCombined = INF;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (distFromS[r][c] < INF && distFromT[r][c] < INF) {
                    bestCombined = Math.min(bestCombined,
                                            distFromS[r][c] + distFromT[r][c]);
                }
            }
        }

        if (bestCombined < INF) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Performs a multi‑source breadth‑first search from every cell that contains
     * {@code startChar}.  The returned matrix holds the minimal number of steps
     * required to reach each cell, or {@link #INF} if the cell is unreachable.
     *
     * @param grid     the input grid
     * @param startChar character that marks source cells (e.g., 'S' or 'T')
     * @return distance matrix from the sources
     */
    private static int[][] multiSourceBfs(char[][] grid, char startChar) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }

        Queue<int[]> queue = new ArrayDeque<>();
        // Enqueue all source cells.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == startChar) {
                    dist[r][c] = 0;
                    queue.offer(new int[]{r, c});
                }
            }
        }

        // Four orthogonal directions.
        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];

            for (int[] dir : directions) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                // Bounds check.
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }
                // Obstacles are impassable.
                if (grid[nr][nc] == '*') {
                    continue;
                }
                // Already visited cell.
                if (dist[nr][nc] != INF) {
                    continue;
                }

                dist[nr][nc] = dist[r][c] + 1;
                queue.offer(new int[]{nr, nc});
            }
        }

        return dist;
    }

    /**
     * Simple tokenizer‑based input reader.
     * <p>
     * It reads line‑by‑line and tokenises on whitespace, providing a
     * convenient {@code next()} method that can be reused across the
     * program.
     * </p>
     */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next token, reading a new line when necessary. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrapper for {@code Integer.parseInt(next())}. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

package solution;

import java.io.*;
import java.util.*;

/**
 * Solves the problem of reaching a target 'T' from a start 'S' while
 * counting the number of direction changes (turns). The answer is
 * "YES" if it can be reached with at most two turns, otherwise "NO".
 */
public class Solution {

    /** Directions used throughout the program. */
    private enum Direction {
        UP( -1, 0 ),
        RIGHT( 0, 1 ),
        DOWN( 1, 0 ),
        LEFT( 0, -1 );

        private final int di;
        private final int dj;

        Direction(int di, int dj) {
            this.di = di;
            this.dj = dj;
        }

        /** Returns the numeric code of the direction (0‑3). */
        int code() {
            return ordinal();
        }

        /** Returns the opposite direction. */
        Direction opposite() {
            return values()[(code() + 2) % 4];
        }
    }

    /** Simple state holder for BFS. */
    private static final class Node {
        final int row;
        final int col;
        final Direction dir;
        final int turns;          // number of direction changes performed so far

        Node(int row, int col, Direction dir, int turns) {
            this.row = row;
            this.col = col;
            this.dir = dir;
            this.turns = turns;
        }
    }

    /** Fast scanner to read input data. */
    private static final class FastScanner implements AutoCloseable {
        private final ByteArrayInputStream buffer = new ByteArrayInputStream();
        private final DataInputStream din;
        private int ptr = 0;
        private int len = 0;

        FastScanner(InputStream stream) throws IOException {
            din = new DataInputStream(stream);
            fill();
        }

        /** Reads next non‑whitespace token as integer. */
        int nextInt() throws IOException {
            skipWhitespace();
            int sign = 1;
            if (buffer.read() == '-') {
                sign = -1;
            } else {
                buffer = new ByteArrayInputStream((byte) (ptr - 1));
            }
            int value = 0;
            while (true) {
                int b = readByte();
                if (b < '0' || b > '9') {
                    // token finished
                    return value * sign;
                }
                value = value * 10 + (b - '0');
            }
        }

        /** Moves the internal pointer forward. */
        private void fill() throws IOException {
            len = din.read(buffer);
            ptr = 0;
            if (len == -1) {
                buffer.close();
            }
        }

        /** Skips spaces, newlines, tabs, etc. */
        private void skipWhitespace() throws IOException {
            while (true) {
                if (ptr >= len) fill();
                if (ptr >= len) break;
                byte cur = buffer.readByte();
                if (cur > 32) {
                    // put back the non‑whitespace character
                    ptr++;
                    return;
                }
                ptr++;
            }
        }

        /** Reads a single byte from the underlying buffer. */
        private byte readByte() throws IOException {
            if (ptr >= len) fill();
            return buffer.readByte();
        }

        /** Reads a whole line (up to newline). */
        String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            while (true) {
                if (ptr >= len) fill();
                byte cur = buffer.readByte();
                if (cur == '\n') break;
                sb.append((char) cur);
                ptr++;
            }
            return sb.toString();
        }

        @Override
        public void close() throws IOException {
            din.close();
        }
    }

    /** Main entry point of the program. */
    public static void main(String[] args) throws Exception {
        // --------------------------------------------------------------
        // 1️⃣  Input handling
        // --------------------------------------------------------------
        try (FastScanner fs = new FastScanner(System.in)) {
            int n = fs.nextInt();
            int m = fs.nextInt();

            char[][] grid = new char[n][m];
            int startRow = -1, startCol = -1;

            for (int i = 0; i < n; ++i) {
                String line = fs.readLine();
                for (int j = 0; j < m; ++j) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    }
                }
            }

            // --------------------------------------------------------------
            // 2️⃣  BFS initialisation
            // --------------------------------------------------------------
            boolean reachedTarget = false;
            int[][][] visitedTurns = new int[n][m][Direction.values().length];
            for (int[][] a : visitedTurns) {
                for (int[] b : a) {
                    Arrays.fill(b, Integer.MAX_VALUE);
                }
            }

            Queue<Node> queue = new ArrayDeque<>();
            // Starting node can face any direction, but the first move does not count as a turn.
            for (Direction d : Direction.values()) {
                queue.add(new Node(startRow, startCol, d, 0));
                visitedTurns[startRow][startCol][d.code()] = 0;
            }

            // --------------------------------------------------------------
            // 3️⃣  BFS core
            // --------------------------------------------------------------
            while (!queue.isEmpty() && !reachedTarget) {
                Node cur = queue.poll();

                // If we have already exceeded the allowed number of turns, skip.
                if (cur.turns > 2) continue;

                // Skip processing if a better (or equal) turn count was already recorded.
                if (visitedTurns[cur.row][cur.col][cur.dir.code()] < cur.turns) continue;
                visitedTurns[cur.row][cur.col][cur.dir.code()] = cur.turns;

                // Target reached -> stop early.
                if (grid[cur.row][cur.col] == 'T') {
                    reachedTarget = true;
                    break;
                }

                // Explore four neighbours.
                for (Direction nextDirection : Direction.values()) {
                    int nxtRow = cur.row + nextDirection.di;
                    int nxtCol = cur.col + nextDirection.dj;

                    if (nxtRow < 0 || nxtRow >= n || nxtCol < 0 || nxtCol >= m) continue;
                    if (grid[nxtRow][nxtCol] == '*') continue;               // obstacle

                    int cost = 0;
                    if (nextDirection != cur.dir) {
                        cost = 1; // a turn is required
                    }
                    int newTurns = cur.turns + cost;
                    if (newTurns > 2) continue;

                    Node neighbour = new Node(nxtRow, nxtCol, nextDirection, newTurns);
                    // Only enqueue if we can improve the recorded turn count.
                    if (newTurns < visitedTurns[nxtRow][nxtCol][nextDirection.code()]) {
                        queue.add(neighbour);
                        visitedTurns[nxtRow][nxtCol][nextDirection.code()] = newTurns;
                    }
                }
            }

            // --------------------------------------------------------------
            // 4️⃣  Output result
            // --------------------------------------------------------------
            System.out.println(reachedTarget ? "YES" : "NO");
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the problem by propagating 'S' and 'T' cells through empty ('.') cells
 * and checking for a specific alternating pattern in rows and columns.
 */
public class Main implements Runnable {

    /** sentinel values used while scanning the grid */
    private static final int STAR  = -2;   // a star cell
    private static final int UNVISITED = -1;
    private static final int START_ID = 0; // identifier for an 'S' source
    private static final int TARGET_ID = 1; // identifier for a 'T' source

    private FastScanner in;
    private PrintWriter out;

    /** Fast scanner that wraps a BufferedReader with a StringTokenizer. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() throws IOException {
            br = new BufferedReader(new InputStreamReader(System.in));
            st = new StringTokenizer(br.readLine());
        }

        /** Returns the next token as a long. */
        long nextLong() {
            return Long.parseLong(next());
        }

        /** Returns the next token as an int. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Returns the next token as a String (may be empty when the line is exhausted). */
        String next() {
            if (st.hasMoreTokens()) {
                return st.nextToken();
            }
            // Load the next line
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            if (!st.hasMoreTokens()) {
                return "";
            }
            return st.nextToken();
        }
    }

    @Override
    public void run() {
        try {
            initIO();
            solve();
        } finally {
            out.flush();
            out.close();
        }
    }

    /** Initializes the input scanner and output writer. */
    private void initIO() {
        in = new FastScanner();
        out = new PrintWriter(System.out);
    }

    /** Entry point – starts the solution on a dedicated thread with a large stack. */
    public static void main(String[] args) {
        new Thread(null, new Main(), "solution", 1 << 26).start();
    }

    /** Finds all cells that can be reached from each 'S' or 'T' and records their ids. */
    private void solve() {
        int n = in.nextInt();
        int m = in.nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        int[][] ids = new int[n][m];
        initialiseIds(ids, grid);

        // Propagate identifiers from every 'S' or 'T' through adjacent '.' cells.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                char cell = grid[i][j];
                if (cell == 'S' || cell == 'T') {
                    propagate(grid, ids, i, j);
                }
            }
        }

        boolean conflict = false;

        // ---- Row checker ----------------------------------------------------
        for (int i = 0; i < n && !conflict; i++) {
            int status = STAR;
            for (int j = 0; j < m; j++) {
                int val = ids[i][j];
                if (val == STAR) {
                    status = STAR;
                } else if (val == UNVISITED) {
                    continue;
                } else if (val == START_ID) {
                    if (status == TARGET_ID) {
                        conflict = true;
                        break;
                    }
                    status = START_ID;
                } else { // val == TARGET_ID
                    if (status == START_ID) {
                        conflict = true;
                        break;
                    }
                    status = TARGET_ID;
                }
            }
        }

        // ---- Column checker -------------------------------------------------
        if (!conflict) {
            for (int j = 0; j < m && !conflict; j++) {
                int status = STAR;
                for (int i = 0; i < n; i++) {
                    int val = ids[i][j];
                    if (val == STAR) {
                        status = STAR;
                    } else if (val == UNVISITED) {
                        continue;
                    } else if (val == START_ID) {
                        if (status == TARGET_ID) {
                            conflict = true;
                            break;
                        }
                        status = START_ID;
                    } else { // val == TARGET_ID
                        if (status == START_ID) {
                            conflict = true;
                            break;
                        }
                        status = TARGET_ID;
                    }
                }
            }
        }

        out.println(conflict ? "YES" : "NO");
    }

    /** Marks all star cells and leaves every other cell as UNVISITED. */
    private void initialiseIds(int[][] ids, char[][] grid) {
        Arrays.fill(ids[0], UNVISITED);
        for (int i = 0; i < ids.length; i++) {
            Arrays.fill(ids[i], UNVISITED);
        }
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == '*') {
                    ids[i][j] = STAR;
                }
            }
        }
    }

    /**
     * Starting from (x, y) which contains 'S' or 'T', spreads the identifier
     * (0 for 'S', 1 for 'T') through adjacent '.' cells in the four cardinal
     * directions until a non‑empty cell is encountered.
     */
    private void propagate(char[][] grid, int[][] ids, int x, int y) {
        int id = (grid[x][y] == 'T') ? TARGET_ID : START_ID;
        ids[x][y] = id;

        // up
        for (int nx = x - 1; nx >= 0 && grid[nx][y] == '.'; nx--) {
            ids[nx][y] = id;
        }
        // down
        for (int nx = x + 1; nx < grid.length && grid[nx][y] == '.'; nx++) {
            ids[nx][y] = id;
        }
        // left
        for (int ny = y - 1; ny >= 0 && grid[x][ny] == '.'; ny--) {
            ids[x][ny] = id;
        }
        // right
        for (int ny = y + 1; ny < grid[0].length && grid[x][ny] == '.'; ny++) {
            ids[x][ny] = id;
        }
    }
}

import java.io.*;

public class Main {

    public static void main(String[] args) {
        try (InputStream in = System.in;
             OutputStream out = System.out) {
            InputReader reader = new InputReader(in);
            OutputWriter writer = new OutputWriter(out);
            new Solver().solve(reader, writer);
            writer.close();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Core algorithm – isolated for readability and testability. */
    private static final class Solver {
        private static final int[] DX = {-1, 0, 1, 0};
        private static final int[] DY = {0, -1, 0, 1};

        /** Reads the grid and performs the required checks, writing the result. */
        void solve(InputReader reader, OutputWriter writer) {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            // -----------------------------------------------------------------
            // 1️⃣  Mark cells reachable from 'S' (id = 0) and 'T' (id = 1)
            // -----------------------------------------------------------------
            boolean[][][] reachable = new boolean[2][n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    char cell = grid[i][j];
                    if (cell != 'S' && cell != 'T') {
                        continue;
                    }
                    int id = (cell == 'S') ? 0 : 1;
                    for (int d = 0; d < 4; d++) {
                        int ci = i, cj = j;
                        while (inside(ci, cj, n, m) && grid[ci][cj] != '*') {
                            reachable[id][ci][cj] = true;
                            ci += DX[d];
                            cj += DY[d];
                        }
                    }
                }
            }

            // -----------------------------------------------------------------
            // 2️⃣  Look for a cell reachable from both S and T along a straight line
            // -----------------------------------------------------------------
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (!reachable[0][i][j]) {
                        continue;               // only start from cells reachable from 'S'
                    }
                    for (int d = 0; d < 4; d++) {
                        int ci = i, cj = j;
                        while (inside(ci, cj, n, m) && grid[ci][cj] != '*') {
                            if (reachable[1][ci][cj]) {
                                writer.println("YES");
                                return;
                            }
                            ci += DX[d];
                            cj += DY[d];
                        }
                    }
                }
            }
            writer.println("NO");
        }

        /** Helper – checks whether (x,y) lies inside a matrix of given dimensions. */
        private boolean inside(int x, int y, int rows, int cols) {
            return x >= 0 && x < rows && y >= 0 && y < cols;
        }
    }

    /** Simple, fast scanner used by the original code. */
    private static final class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int offset = 0;
        private int length = 0;

        private InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (length == offset) {
                offset = 0;
                length = stream.read(buffer);
                if (length == -1) {
                    throw new EOFException();
                }
            }
            return buffer[offset++];
        }

        private int nextInt() throws IOException {
            int c, sign = 1, val = 0;
            do {
                c = readByte();
            } while (c <= ' ' && c != '-' && c != EOF);
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val * sign;
        }

        private String next() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c <= ' ');
            StringBuilder sb = new StringBuilder().append((char) c);
            while ((c = readByte()) > ' ') {
                sb.append((char) c);
            }
            return sb.toString();
        }
    }

    /** Minimal writer compatible with the original output format. */
    private static final class OutputWriter {
        private final PrintWriter writer;

        OutputWriter(OutputStream out) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        /** Prints the given objects separated by a space and ends with a newline. */
        void println(Object... args) {
            for (int i = 0; i < args.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(args[i]);
            }
            writer.println();
        }

        void close() {
            writer.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for problem B7932.
 * The program decides whether a path exists from 'S' to 'T' on a grid,
 * allowing direction changes but only a limited number of turns.
 */
public class B7932 {

    /* ---------- Constants & global configuration ---------- */
    private static final int MAX_TURNS = 2;                     // number of allowed direction changes
    private static final boolean[][][] VISITED;                 // runtime allocation

    /* ---------- Grid data ---------- */
    private static char[][] grid;                               // input grid
    private static int rows, cols;                              // dimensions

    /* ---------- Directions ---------- */
    private enum Direction {
        NORTH(-1, 0), EAST(0, 1), SOUTH(1, 0), WEST(0, -1);

        private final int dx, dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        int getDx() { return dx; }

        int getDy() { return dy; }
    }

    /** Holds the position, direction we came from and remaining turn budget. */
    private static final class State {
        final int x, y;
        final Direction dir;
        final int turnsRemaining;   // 0 … MAX_TURNS+1

        State(int x, int y, Direction dir, int turnsRemaining) {
            this.x = x;
            this.y = y;
            this.dir = dir;
            this.turnsRemaining = turnsRemaining;
        }
    }

    /* ---------- Entrypoint ---------- */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        rows = fs.nextInt();
        cols = fs.nextInt();

        initVisited();
        grid = readGrid(fs);

        int sx = -1, sy = -1, tx = -1, ty = -1;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                char cell = grid[i][j];
                if (cell == 'S') {
                    sx = i; sy = j;
                } else if (cell == 'T') {
                    tx = i; ty = j;
                }
            }
        }

        if (sx == -1 || sy == -1 || tx == -1 || ty == -1) {
            System.out.println("NO");
            return;
        }

        if (bfs(sx, sy, tx, ty)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /* ---------- BFS implementation ---------- */
    private static boolean bfs(int startX, int startY, int targetX, int targetY) {
        Queue<State> queue = new ArrayDeque<>();

        // From the start cell we can initially move in any of the four directions.
        for (Direction d : Direction.values()) {
            int nx = startX + d.getDx();
            int ny = startY + d.getDy();
            if (isInside(nx, ny) && grid[nx][ny] != '*') {
                // we start with a full turn‑budget (MAX_TURNS+1) to allow one move without counting a turn.
                queue.add(new State(nx, ny, d, MAX_TURNS + 1));
                VISITED[nx][ny][d.ordinal()][MAX_TURNS + 1] = true;
            }
        }

        while (!queue.isEmpty()) {
            State cur = queue.poll();

            if (cur.x == targetX && cur.y == targetY) {
                return true;              // reached the target
            }

            // Try moving in every compass direction.
            for (Direction next : Direction.values()) {
                int nx = cur.x + next.getDx();
                int ny = cur.y + next.getDy();

                if (!isInside(nx, ny) || grid[nx][ny] == '*') {
                    continue;
                }

                // Same direction – no turn, keep the same remaining budget.
                if (next == cur.dir) {
                    if (!VISITED[nx][ny][next.ordinal()][cur.turnsRemaining]) {
                        VISITED[nx][ny][next.ordinal()][cur.turnsRemaining] = true;
                        queue.add(new State(nx, ny, next, cur.turnsRemaining));
                    }
                }
                // Opposite direction – always forbidden.
                else if (next == opposite(cur.dir)) {
                    continue;
                }
                // Different direction but we still may turn.
                else if (cur.turnsRemaining > 0) {
                    if (!VISITED[nx][ny][next.ordinal()][cur.turnsRemaining - 1]) {
                        VISITED[nx][ny][next.ordinal()][cur.turnsRemaining - 1] = true;
                        queue.add(new State(nx, ny, next, cur.turnsRemaining - 1));
                    }
                }
            }
        }
        return false;   // target unreachable under the given constraints
    }

    /** Returns the direction opposite to the given one. */
    private static Direction opposite(Direction d) {
        return switch (d) {
            case NORTH -> Direction.SOUTH;
            case SOUTH -> Direction.NORTH;
            case EAST  -> Direction.WEST;
            case WEST  -> Direction.EAST;
        };
    }

    /** Simple bounds check. */
    private static boolean isInside(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /** Allocate and initialise the 4‑dimensional visited matrix. */
    private static void initVisited() {
        VISITED = new boolean[rows][cols][Direction.values().length][MAX_TURNS + 2];
        // +2 because we allow budgets from 0 up to MAX_TURNS+1 inclusive.
    }

    /** Reads the whole grid from the FastScanner. */
    private static char[][] readGrid(FastScanner fs) {
        char[][] result = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = fs.nextLine().trim();
            result[i] = line.toCharArray();
        }
        return result;
    }

    /* ---------- Fast input helper ---------- */
    /** Minimal scanner that mimics the original tokenisation behaviour. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * IgorAndHisWayToWork – refactored version.
 *
 * The program reads a rectangular grid, finds the starting cell 'S',
 * and determines whether a path that uses at most two turns can reach
 * the target cell 'T' (the original code treated reaching 'T' as a
 * successful outcome).  The search is performed with a breadth‑first
 * walk that slides in straight lines until a wall or a cell already
 * visited from the same direction is encountered.
 */
public class IgorAndHisWayToWork {

    /* --------------------------------------------------------------------- */
    /* Constants & static fields                                               */
    /* --------------------------------------------------------------------- */
    private static final char WALL = '*';
    private static final char EMPTY = '.';
    private static final char START = 'S';
    private static final char TARGET = 'T';

    /** Maximum number of allowed turns (the original program used depth < 3). */
    private static final int MAX_TURNS = 2;

    /** Directions we can move – stored as deltas. */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);
        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        /** Convert this direction to an index used in the visited array. */
        int ordinal() {
            switch (this) {
                case UP:    return 0;
                case DOWN:  return 1;
                case LEFT:  return 2;
                case RIGHT: return 3;
                default:    throw new IllegalStateException();
            }
        }
    }

    /** Grid representation. */
    private static char[][] labyrinth;

    /**
     * 3‑dimensional visited flags.
     * visited[row][col][direction] == true  ⇔  the cell (row,col) was already
     * reached moving in the given direction with an equal or fewer turns.
     */
    private static boolean[][][] visited;

    /* --------------------------------------------------------------------- */
    /* Entry point                                                           */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // ----- read dimensions ------------------------------------------------
        String[] sizeTokens = br.readLine().split("\\s+");
        int n = Integer.parseInt(sizeTokens[0]);
        int m = Integer.parseInt(sizeTokens[1]);

        // ----- read grid -------------------------------------------------------
        labyrinth = new char[n][m];
        visited = new boolean[n][m][Direction.values().length]; // one slot per direction

        int startRow = -1, startCol = -1;
        for (int r = 0; r < n; r++) {
            String line = br.readLine().trim();
            labyrinth[r] = line.toCharArray();
            for (int c = 0; c < m; c++) {
                if (labyrinth[r][c] == START) {
                    startRow = r;
                    startCol = c;
                }
            }
        }

        // ----- run BFS ---------------------------------------------------------
        State startState = new State(startRow, startCol, null, 0);
        System.out.println(bfs(startState, n, m) ? "YES" : "NO");
    }

    /* --------------------------------------------------------------------- */
    /* Core BFS logic                                                          */
    /* --------------------------------------------------------------------- */
    private static boolean bfs(State start, int n, int m) {
        Queue<State> queue = new ArrayDeque<>();
        queue.add(start);
        visited[start.row][start.col][0] = true; // dummy direction for the start cell

        while (!queue.isEmpty()) {
            State cur = queue.poll();

            // We cannot expand from a state that already used the maximum allowed turns.
            if (cur.turns >= MAX_TURNS) {
                continue;
            }

            // Try to "slide" in every direction from the current cell.
            for (Direction dir : Direction.values()) {
                // If we arrived via the same direction, we can keep moving straight
                // without incurring an extra turn.
                int nextTurns = cur.turns;
                if (cur.dir != null && cur.dir != dir) {
                    nextTurns++; // we turned
                }
                if (nextTurns > MAX_TURNS) {
                    continue; // exceed allowed budget – skip this direction
                }

                // Slide along `dir` until we hit a wall, the border, or a cell that
                // we have already visited in this exact direction with an equal or
                // better turn count.
                int r = cur.row;
                int c = cur.col;
                while (true) {
                    int nr = r + dir.dr;
                    int nc = c + dir.dc;
                    if (!inside(nr, nc, n, m)) break;               // out of bounds
                    if (labyrinth[nr][nc] == WALL) break;           // wall blocks movement
                    if (visited[nr][nc][dir.ordinal()] && ! (cur.dir == null && nextTurns < cur.turns)) break;

                    // We have successfully moved to (nr, nc)
                    r = nr;
                    c = nc;

                    // Reaching the target terminates the search successfully.
                    if (labyrinth[r][c] == TARGET) {
                        return true;
                    }

                    // Mark the cell as visited for this direction.
                    visited[r][c][dir.ordinal()] = true;

                    // Enqueue the new state (same direction keeps the same turn count,
                    // a different direction would increase it – already handled above).
                    queue.add(new State(r, c, dir, nextTurns));

                    // If we revisited the same cell with an equal or larger turn count,
                    // further sliding in this direction cannot improve the situation.
                    if (visited[r][c][dir.ordinal()] && nextTurns >= cur.turns) {
                        break;
                    }
                }
            }
        }
        return false; // queue exhausted without finding the target
    }

    /* --------------------------------------------------------------------- */
    /* Helper utilities                                                       */
    /* --------------------------------------------------------------------- */
    /** Checks whether a cell lies inside the grid. */
    private static boolean inside(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Simple container for a BFS node.
     *
     * @param row     row index in the grid.
     * @param col     column index in the grid.
     * @param dir     direction we arrived from (null for the start cell).
     * @param turns   number of turns already used.
     */
    private static final class State {
        final int row;
        final int col;
        final Direction dir;   // null for the starting position
        final int turns;       // how many direction changes have been performed

        State(int row, int col, Direction dir, int turns) {
            this.row = row;
            this.col = col;
            this.dir = dir;
            this.turns = turns;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the problem.
 *
 * The program reads a grid that contains:
 *   - 'S'   : start cell (exactly one)
 *   - 'T'   : target cells (several possible)
 *   - '*'   : obstacle cells
 *   - '.'   : free cells
 *
 * From the start cell we may walk on free cells, but we are allowed to
 * change direction at most twice.  A target cell is reachable if there
 * exists a path that respects this rule.
 *
 * The result for each 'T' cell is printed on its own line: "YES" or "NO".
 *
 * The implementation is split into small, focused classes and an
 * enum for the four cardinal directions, which makes the code easier
 * to understand, test and maintain.
 */
public class Main {

    /** Maximum number of direction changes allowed (0‑based up to 2). */
    private static final int MAX_CHANGES = 3;

    /** Directions used for movement – up, down, right, left. */
    private enum Direction {
        UP(0, -1), DOWN(0, 1), RIGHT(1, 0), LEFT(-1, 0);

        final int dx;
        final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }
    }

    /** Small container that represents a state while exploring the grid. */
    private static final class State {
        final int x;
        final int y;
        final Direction direction;
        final int changed;   // how many direction changes have been used

        State(int x, int y, Direction direction, int changed) {
            this.x = x;
            this.y = y;
            this.direction = direction;
            this.changed = changed;
        }
    }

    /** Utility class that handles all input parsing. */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Reads the next line (or throws an unchecked IOException on failure). */
        private String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Returns the next token from the input stream. */
        private String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(nextLine());
            }
            return st.nextToken();
        }

        /** Reads the next integer. */
        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        /** Reads a grid of the given row count and returns a char matrix. */
        char[][] readGrid(int rows) {
            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = nextLine().toCharArray();
            }
            return grid;
        }
    }

    /** Core algorithm that decides whether each 'T' cell is reachable. */
    private static final class Solver {
        /** Entry point used by {@code Main.main}. */
        void solve(InputReader in, PrintWriter out) {
            // ----- read dimensions and grid -------------------------------------------------
            int rows = in.nextInt();
            int cols = in.nextInt();
            char[][] grid = in.readGrid(rows);

            // locate the (only) start cell
            int startX = -1, startY = -1;
            for (int y = 0; y < rows; y++) {
                for (int x = 0; x < cols; x++) {
                    if (grid[y][x] == 'S') {
                        startX = x;
                        startY = y;
                    }
                }
            }
            if (startX == -1) {
                // No start cell – nothing to solve.
                return;
            }

            // visited[y][x][dir][changed]  –  has the cell been reached with given
            // direction and number of direction changes?
            boolean[][][][] visited = new boolean[rows][cols][Direction.values().length][MAX_CHANGES];

            Queue<State> queue = new LinkedList<>();

            // initialise the queue with every possible first direction
            for (Direction dir : Direction.values()) {
                visited[startY][startX][dir.ordinal()][0] = true;
                queue.add(new State(startX, startY, dir, 0));
            }

            // ----- breadth‑first search -------------------------------------------------------
            while (!queue.isEmpty()) {
                State cur = queue.poll();

                for (Direction dir : Direction.values()) {
                    int nx = cur.x + dir.dx;
                    int ny = cur.y + dir.dy;
                    int newChanges = cur.changed + (cur.direction == dir ? 0 : 1);

                    if (canMove(nx, ny, newChanges, grid, visited, dir)) {
                        visited[ny][nx][dir.ordinal()][newChanges] = true;
                        queue.add(new State(nx, ny, dir, newChanges));
                    }
                }
            }

            // ----- determine which 'T' cells are reachable ---------------------------------
            boolean[][] reachable = new boolean[rows][cols];
            for (int y = 0; y < rows; y++) {
                for (int x = 0; x < cols; x++) {
                    if (grid[y][x] != 'T') {
                        continue;
                    }
                    for (int d = 0; d < Direction.values().length; d++) {
                        for (int c = 0; c < MAX_CHANGES; c++) {
                            if (visited[y][x][d][c]) {
                                reachable[y][x] = true;
                                break;
                            }
                        }
                        if (reachable[y][x]) {
                            break;
                        }
                    }
                }
            }

            // ----- output the results -------------------------------------------------------
            for (int y = 0; y < rows; y++) {
                for (int x = 0; x < cols; x++) {
                    if (grid[y][x] == 'T') {
                        out.println(reachable[y][x] ? "YES" : "NO");
                    }
                }
            }
        }

        /** Checks whether a move to (x, y) with a given number of direction changes is legal. */
        private boolean canMove(int x, int y, int changes,
                                char[][] grid,
                                boolean[][][][] visited,
                                Direction dir) {
            // bounds
            if (!inside(x, y, grid[y].length, grid.length)) {
                return false;
            }
            // obstacle
            if (grid[y][x] == '*') {
                return false;
            }
            // direction‑change limit
            if (changes >= MAX_CHANGES) {
                return false;
            }
            // already visited in exactly this state
            if (visited[y][x][dir.ordinal()][changes]) {
                return false;
            }
            return true;
        }

        /** Simple bounds check. */
        private boolean inside(int x, int y, int colCount, int rowCount) {
            return x >= 0 && x < colCount && y >= 0 && y < rowCount;
        }
    }

    /** Program entry point. */
    public static void main(String[] args) throws Exception {
        try (InputReader reader = new InputReader(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {
            new Solver().solve(reader, writer);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point – reads the board, asks the solver and prints the answer.
 */
public final class Main {
    public static void main(String[] args) {
        new Solver().run();
    }
}

/**
 * Reads the board, computes whether a valid “S‑to‑T” path exists and prints
 * {@code YES} or {@code NO}.
 */
final class Solver {
    /** number of rows of the board */
    private int rows;
    /** number of columns of the board */
    private int cols;
    /** the board itself */
    private char[][] board;

    /** characters that mark walls */
    private static final char WALL = '*';
    /** start and target markers */
    private static final char START = 'S';
    private static final char TARGET = 'T';

    /** positions of the start and target cells */
    private Point startPos;
    private Point targetPos;

    /** cached sets of cells reachable by a single straight line from S/T */
    private Set<Point> reachableFromStart;
    private Set<Point> reachableFromTarget;

    /** -------------------------------------------------------------------- */
    /** Public entry point used by {@code Main} */
    public void run() {
        readInput();
        computeReachableSets();
        if (hasIntersection()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /** -------------------------------------------------------------------- */
    /** Reads the board from {@code System.in}. */
    private void readInput() {
        FastScanner fs = new FastScanner(System.in);
        rows = fs.nextInt();
        cols = fs.nextInt();
        board = new char[rows][];
        for (int r = 0; r < rows; r++) {
            board[r] = fs.nextLine().toCharArray();
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == START) {
                    startPos = new Point(c, r);
                } else if (board[r][c] == TARGET) {
                    targetPos = new Point(c, r);
                }
            }
        }
        if (startPos == null || targetPos == null) {
            throw new IllegalStateException("Both 'S' and 'T' must be present in the board.");
        }
    }

    /** -------------------------------------------------------------------- */
    /** Builds the two reachable‑from‑S / reachable‑from‑T sets. */
    private void computeReachableSets() {
        reachableFromStart = collectReachable(startPos);
        reachableFromTarget = collectReachable(targetPos);
    }

    /** -------------------------------------------------------------------- */
    /** Returns all cells that can be reached by moving in one of the four
     *  cardinal directions from {@code from} until a wall or the border is hit. */
    private Set<Point> collectReachable(Point from) {
        Set<Point> result = new HashSet<>();
        // up
        moveAndCollect(from, 0, -1, result);
        // down
        moveAndCollect(from, 0, 1, result);
        // left
        moveAndCollect(from, -1, 0, result);
        // right
        moveAndCollect(from, 1, 0, result);
        // include the start cell itself (it is considered reachable)
        result.add(from);
        return result;
    }

    /** -------------------------------------------------------------------- */
    /** Walks from {@code start} in direction {@code dx,dy} adding every
     *  traversed cell to {@code target} until a wall ('*') or the board edge
     *  is encountered. */
    private void moveAndCollect(Point start, int dx, int dy, Set<Point> target) {
        int x = start.x;
        int y = start.y;
        while (true) {
            x += dx;
            y += dy;
            if (!inBounds(x, y)) {
                break;
            }
            if (board[y][x] == WALL) {
                break;
            }
            target.add(new Point(x, y));
        }
    }

    /** -------------------------------------------------------------------- */
    /** Checks whether there exists a pair of cells (one from each reachable set)
     *  that lie on a common row or column without an intervening wall. */
    private boolean hasIntersection() {
        for (Point s : reachableFromStart) {
            // Same row -> look horizontally for any target cell
            if (searchHorizontalAlignment(s, reachableFromTarget)) {
                return true;
            }
            // Same column -> look vertically for any target cell
            if (searchVerticalAlignment(s, reachableFromTarget)) {
                return true;
            }
        }
        return false;
    }

    /** -------------------------------------------------------------------- */
    /** Scans the row of {@code base} left/right for a point contained in
     *  {@code candidates} without hitting a wall. */
    private boolean searchHorizontalAlignment(Point base, Collection<Point> candidates) {
        int y = base.y;
        // right
        for (int x = base.x + 1; x < cols; x++) {
            if (board[y][x] == WALL) {
                break;
            }
            if (candidates.stream().anyMatch(p -> p.x == x && p.y == y)) {
                return true;
            }
        }
        // left
        for (int x = base.x - 1; x >= 0; x--) {
            if (board[y][x] == WALL) {
                break;
            }
            if (candidates.stream().anyMatch(p -> p.x == x && p.y == y)) {
                return true;
            }
        }
        return false;
    }

    /** -------------------------------------------------------------------- */
    /** Scans the column of {@code base} upwards/downwards for a point contained
     *  in {@code candidates} without hitting a wall. */
    private boolean searchVerticalAlignment(Point base, Collection<Point> candidates) {
        int x = base.x;
        // down
        for (int y = base.y + 1; y < rows; y++) {
            if (board[y][x] == WALL) {
                break;
            }
            if (candidates.stream().anyMatch(p -> p.x == x && p.y == y)) {
                return true;
            }
        }
        // up
        for (int y = base.y - 1; y >= 0; y--) {
            if (board[y][x] == WALL) {
                break;
            }
            if (candidates.stream().anyMatch(p -> p.x == x && p.y == y)) {
                return true;
            }
        }
        return false;
    }
}

/**
 * Very small immutable point class – used only as a key in a {@code Set}.
 */
final class Point {
    final int x;
    final int y;

    Point(int x, int y) {
        this.x = x;
        this.y = y;
    }

    @Override public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Point)) return false;
        Point p = (Point) o;
        return x == p.x && y == p.y;
    }

    @Override public int hashCode() {
        return Objects.hash(x, y);
    }
}

/**
 * Fast scanner that works with the original input format.
 * (Keeps the same semantics as the original {@code FastScanner}.)
 */
final class FastScanner {
    private final BufferedReader reader;

    FastScanner(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
        tokenizer = null;
    }

    private StringTokenizer tokenizer;

    /** Returns the next single token (whitespace separated). */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Reads the next line (used to fetch whole board rows). */
    String nextLine() {
        try {
            return reader.readLine();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    /** Convenience methods for primitive types – keep compatibility. */
    int nextInt() {
        return Integer.parseInt(next());
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solver for the “Laser in a Maze” problem.
 *
 * <p>
 * The original implementation was functional but hard to follow.
 * This version isolates responsibilities, uses expressive names,
 * removes duplicated loops and makes the algorithm easier to test.
 * </p>
 */
public class Main {

    /** Simple container for a grid coordinate. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Fast token based scanner. */
    private final class TokenScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        TokenScanner(BufferedReader reader) {
            this.reader = reader;
        }

        /** Returns the next whole token, or {@code null} if input is exhausted. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }
    }

    /** Holds all mutable state needed for solving a single test case. */
    private static final class Solver {
        private final char[][] grid;         // original grid
        private final int[][] bin;            // marker grid (0 = empty, 1 = start line, 2 = target line)
        private final int n, m;                // dimensions
        private final int startR, startC;      // position of 'S'
        private final int targetR, targetC;    // position of 'T'

        Solver(char[][] grid, int[][] bin, int n, int m,
               int startR, int startC, int targetR, int targetC) {
            this.grid = grid;
            this.bin = bin;
            this.n = n;
            this.m = m;
            this.startR = startR;
            this.startC = startC;
            this.targetR = targetR;
            this.targetC = targetC;
        }

        /** Entry point – contains the whole algorithm flow. */
        void solve(TokenScanner ts) {
            readInput(ts);
            markStraightPaths();
            if (hasIntersection()) {
                return; // already printed YES inside the method
            }
            checkRowsAndColumns();
            checkColumnsAndRows();
            out.print("NO");
        }

        /** Reads the grid and extracts start / target coordinates. */
        private void readInput(TokenScanner ts) {
            n = ts.nextInt();
            m = ts.nextInt();
            grid = new char[n][];
            for (int i = 0; i < n; i++) {
                String line = ts.nextToken();
                grid[i] = line.toCharArray();
            }

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    char c = grid[i][j];
                    if (c == 'S') {
                        startR = i;
                        startC = j;
                    } else if (c == 'T') {
                        targetR = i;
                        targetC = j;
                    }
                }
            }
        }

        /** Marks all cells that are directly reachable from the start cell
         *  horizontally or vertically until a wall ('*') is encountered.
         *  The marker used is {@code 1}. */
        private void markStraightPaths() {
            markLine(startR, startC, 1, 0);  // down
            markLine(startR, startC, -1, 0); // up
            markLine(startR, startC, 0, 1);  // right
            markLine(startR, startC, 0, -1); // left

            // From the target cell we use marker {@code 2}.
            markLine(targetR, targetC, 1, 0);
            markLine(targetR, targetC, -1, 0);
            markLine(targetR, targetC, 0, 1);
            markLine(targetR, targetC, 0, -1);
        }

        /** Walks in the given direction until a wall or the grid border is hit,
         *  marking each visited cell with {@code marker} (1 for start‑lines,
         *  2 for target‑lines). If a cell already carries the opposite marker,
         *  the answer is printed immediately and the program terminates. */
        private void markLine(int r, int c, int dr, int dc) {
            int nr = r + dr;
            int nc = c + dc;
            while (inBounds(nr, nc) && grid[nr][nc] != '*') {
                if (grid[nr][nc] == 'T' && markerEquals2(nr, nc)) {
                    // Target line meets a previously marked start line → YES
                    out.print("YES");
                    System.exit(0);
                }
                bin[nr][nc] = markerValue(markerValueFromDirection(dr, dc));
                nr += dr;
                nc += dc;
            }
        }

        /** Helper – does the cell contain the start‑line marker (value 1)? */
        private boolean markerEquals1(int r, int c) {
            return bin[r][c] == 1;
        }

        /** Helper – does the cell contain the target‑line marker (value 2)? */
        private boolean markerEquals2(int r, int c) {
            return bin[r][c] == 2;
        }

        /** Returns the numeric marker that corresponds to a movement direction. */
        private int markerValueFromDirection(int dr, int dc) {
            // Directions that correspond to the start cell (marker 1)
            if (dr != 0 || dc != 0) { // always true here, kept for readability
                return 1;
            }
            return 2; // target cell uses marker 2
        }

        /** Marks a single step and proceeds; returns the new coordinate. */
        private Point step(int r, int c, int dr, int dc) {
            return new Point(r + dr, c + dc);
        }

        /** Returns {@code true} if the given coordinate lies inside the grid
         *  and is not a wall. */
        private boolean inBounds(int r, int c) {
            return r >= 0 && r < n && c >= 0 && c < m && grid[r][c] != '*';
        }

        /** Checks for a “YES” condition that appears when a row (or column)
         *  contains a marker, then later a wall, then another marker before the
         *  wall re‑appears. */
        private void checkRowsAndColumns() {
            // Examine every row that is neither the start nor the target row.
            for (int row = 0; row < n; row++) {
                if (row == startR || row == targetR) {
                    continue;
                }
                boolean afterMarker = false;
                for (int col = 0; col < m; col++) {
                    if (grid[row][col] == '*') {
                        afterMarker = false;          // wall resets the state
                        continue;
                    }
                    int mark = bin[row][col];
                    if (mark != 0) {
                        if (afterMarker) {
                            // We found a marker after we already passed one → YES
                            out.print("YES");
                            System.exit(0);
                        }
                        afterMarker = true;            // first marker seen
                    }
                }
            }
        }

        /** Checks the same pattern for every column that is neither the start
         *  nor the target column. */
        private void checkColumnsAndRows() {
            for (int col = 0; col < m; col++) {
                if (col == startC || col == targetC) {
                    continue;
                }
                boolean afterMarker = false;
                for (int row = 0; row < n; row++) {
                    if (grid[row][col] == '*') {
                        afterMarker = false;
                        continue;
                    }
                    int mark = bin[row][col];
                    if (mark != 0) {
                        if (afterMarker) {
                            out.print("YES");
                            System.exit(0);
                        }
                        afterMarker = true;
                    }
                }
            }
        }

        /** Placeholder for the global PrintWriter used to output the answer. */
        private final PrintWriter out = new PrintWriter(System.out);
    }

    /** Globals used by the original program – kept for compatibility with the
     *  original `run()` entry point. */
    private BufferedReader br;
    private StringTokenizer sc;
    private PrintWriter out;

    /** Main entry point – conforms to the original signature. */
    public static void main(String[] args) throws IOException {
        java.util.Locale.setDefault(java.util.Locale.US);
        new Main().run();
    }

    /** Orchestrates input, solving and output. */
    private void run() throws IOException {
        TokenScanner scanner = new TokenScanner(new BufferedReader(new InputStreamReader(System.in)));
        Solver solver = new Solver(new char[0][] , new int[0][] , 0, 0, 0, 0, 0, 0);
        // The Solver constructor parameters are placeholders; real values are set inside solve().
        // We call solve() directly on a temporary instance that will read the input.
        // To keep the original behaviour we invoke solve via reflection on a concrete subclass.
        // Instead, we simply instantiate an anonymous subclass that supplies the scanner.
        Solver solverInstance = new Solver(new char[0][] , new int[0][] , 0, 0, 0, 0, 0, 0) {
            @Override
            void solve(TokenScanner ts) {
                super.solve(ts);
            }
        };
        solverInstance.solve(scanner);
        out.close();
    }

    /** Adapter that allows the inner `Solver` class to access the scanner
     *  without exposing it publicly. */
    private void solve() throws IOException {
        TokenScanner scanner = new TokenScanner(br == null ? new BufferedReader(new InputStreamReader(System.in)) : br);
        Solver solver = new Solver(new char[0][] , new int[0][] , 0, 0, 0, 0, 0, 0);
        // The above dummy constructor is only a placeholder; real data will be filled
        // inside the overridden solve() method of the anonymous subclass created in `run()`.
        // To preserve original behaviour we simply delegate to the subclass logic.
        // For brevity, we rely on the anonymous subclass defined in `run()`.
    }
}

import java.io.*;
import java.util.Comparator;
import java.util.PriorityQueue;

/**
 * Solves a maze that contains a start cell 'S', a target cell 'T',
 * obstacles '*', and empty cells '.'.
 * The search prefers paths with fewer direction changes.
 */
public class MazeSolver {

    /* --------------------------------------------------------------------- */
    /* Constants – movement deltas                                               */
    /* --------------------------------------------------------------------- */
    private static final int[] DR = {0, 0, 1, -1};
    private static final int[] DC = {1, -1, 0, 0};

    /* --------------------------------------------------------------------- */
    /* Core fields                                                             */
    /* --------------------------------------------------------------------- */
    private final char[][] grid;          // maze representation
    private final boolean[][] visited;    // visited flags
    private final int rows;               // number of rows
    private final int cols;               // number of columns

    private final InputReader reader;     // input source
    private final OutputWriter writer;    // output destination

    /* --------------------------------------------------------------------- */
    /* Construction & entry point                                               */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        try (InputStream in = System.in;
             OutputStream out = System.out) {
            new MazeSolver(new InputReader(in), new OutputWriter(out)).solve();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    public MazeSolver(InputReader reader, OutputWriter writer) {
        this.reader = reader;
        this.writer = writer;
    }

    /** Orchestrates the whole solving process. */
    public void solve() {
        readDimensionParameters();
        readGrid();

        PriorityQueue<State> queue = new PriorityQueue<>(new StateComparator());
        // start from an artificial point (row = -1, col = -1) – direction unused
        queue.offer(new State(-1, -1, 0));

        while (!queue.isEmpty()) {
            State cur = queue.poll();

            // reached the target?
            if (grid[cur.row][cur.col] == 'T') {
                writer.print("YES");
                return;
            }

            if (visited[cur.row][cur.col]) {
                continue;               // already processed with a better cost
            }
            visited[cur.row][cur.col] = true;

            expandAndEnqueue(queue, cur);
        }

        // No path found
        writer.print("NO");
    }

    /* --------------------------------------------------------------------- */
    /* Input / grid handling                                                    */
    /* --------------------------------------------------------------------- */
    private void readDimensionParameters() {
        rows = reader.nextInt();
        cols = reader.nextInt();
    }

    private char[][] readGrid() {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = reader.next();
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /** Returns true if the cell is an obstacle ('*'). */
    private boolean isObstacle(int r, int c) {
        return grid[r][c] == '*';
    }

    /** Checks that (r,c) lies inside the grid. */
    private boolean isInBounds(int r, int c) {
        return 0 <= r && r < rows && 0 <= c && c < cols;
    }

    /* --------------------------------------------------------------------- */
    /* State expansion                                                          */
    /* --------------------------------------------------------------------- */
    /**
     * Expands the current {@link State} into neighbouring cells respecting
     * the direction‑change rule and enqueues them.
     */
    private void expandAndEnqueue(PriorityQueue<State> queue, State cur) {
        for (int dir = 0; dir < 4; dir++) {
            int nr = cur.row + DR[dir];
            int nc = cur.col + DC[dir];

            if (!isInBounds(nr, nc)
                    || isObstacle(nr, nc)
                    || visited[nr][nc]) {
                continue;   // cannot move here
            }

            int newPrevDirection = dir;
            int newTurnCost = cur.turnCost;

            if (cur.prevDirection != dir) {
                // a change of direction costs one turn, but only if we have
                // capacity left (turnCost must stay < 2)
                if (cur.turnCost < 2) {
                    newTurnCost = cur.turnCost + 1;
                } else {
                    continue;   // cannot turn any more
                }
            }

            queue.offer(new State(nr, nc, newPrevDirection, newTurnCost));
        }
    }

    /* --------------------------------------------------------------------- */
    /* Direction‑cost ordering                                                  */
    /* --------------------------------------------------------------------- */
    /**
     * Orders {@link State} objects by their accumulated {@code turnCost}
     * (lower cost first). This drives the priority‑queue behaviour.
     */
    private static final class StateComparator implements Comparator<State> {
        @Override
        public int compare(State o1, State o2) {
            return Integer.compare(o1.turnCost, o2.turnCost);
        }
    }

    /* --------------------------------------------------------------------- */
    /* Internal representation of a search node                                */
    /* --------------------------------------------------------------------- */
    /**
     * Captures a cell position together with the direction taken to reach it
     * and the number of direction changes incurred so far.
     */
    private static final class State {
        final int row;          // row index
        final int col;          // column index
        final int prevDirection; // direction used to arrive here
        final int turnCost;     // number of direction changes performed

        // Constructor used for the artificial start cell (row = -1, col = -1)
        State(int row, int col, int prevDirection) {
            this(row, col, prevDirection, 0);
        }

        // Full constructor for regular states
        State(int row, int col, int prevDirection, int turnCost) {
            this.row = row;
            this.col = col;
            this.prevDirection = prevDirection;
            this.turnCost = turnCost;
        }

        int row() { return row; }
        int col() { return col; }
        int prevDirection() { return prevDirection; }
        int turnCost() { return turnCost; }
    }
}

/* ------------------------------------------------------------------------- */
/* Input / Output helpers – unchanged from the original snippet                */
/* ------------------------------------------------------------------------- */
class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int currentByte;
    private int bytesRead;

    InputReader(InputStream stream) {
        this.stream = stream;
    }

    private int read() {
        if (bytesRead == -1) {
            throw new InputMismatchException();
        }
        if (currentByte >= bytesRead) {
            currentByte = 0;
            try {
                bytesRead = stream.read(buffer);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (bytesRead <= 0) {
                return -1;
            }
        }
        return buffer[currentByte++];
    }

    private boolean isSpace(int c) {
        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == 9;
    }

    private boolean isEnd(int c) {
        return c == -1 || c == '\n' || c == '\r';
    }

    public String next() {
        int c = read();
        while (isSpace(c)) {
            c = read();
        }
        StringBuilder sb = new StringBuilder();
        do {
            sb.appendCodePoint(c);
        } while (!isSpace(c = read()));
        return sb.toString();
    }

    public char nextChar() {
        int c = read();
        while (isSpace(c)) {
            c = read();
        }
        return (char) c;
    }

    public int nextInt() {
        int c = read();
        while (isSpace(c)) {
            c = read();
        }
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = read();
        }
        int value = 0;
        while (c >= '0' && c <= '9') {
            value *= 10;
            value += (c - '0');
            c = read();
            if (isSpace(c)) {
                return value * sign;
            }
        }
        throw new InputMismatchException();
    }

    public long nextLong() {
        int c = read();
        while (isSpace(c)) {
            c = read();
        }
        long sign = 1;
        if (c == '-') {
            sign = -1;
            c = read();
        }
        long value = 0;
        while (c >= '0' && c <= '9') {
            value *= 10;
            value += (c - '0');
            c = read();
            if (isSpace(c)) {
                return value * sign;
            }
        }
        throw new InputMismatchException();
    }

    public String nextLine() {
        int c = read();
        while (!isEnd(c)) {
            c = read();
        }
        StringBuilder sb = new StringBuilder();
        do {
            sb.appendCodePoint(c);
        } while (!isEnd(c = read()));
        return sb.toString();
    }
}

class OutputWriter {
    private final PrintWriter writer;

    OutputWriter(OutputStream outputStream) {
        writer = new PrintWriter(new BufferedWriter(
                new OutputStreamWriter(outputStream)));
    }

    OutputWriter(Writer writer) {
        this.writer = new PrintWriter(writer);
    }

    public void print(char c) {
        writer.print(c);
    }

    public void print(int i) {
        writer.print(i);
    }

    public void print(long l) {
        writer.print(l);
    }

    public void print(double d) {
        writer.print(d);
    }

    public void print(Object... objects) {
        for (Object obj : objects) {
            writer.print(obj);
        }
    }

    public void println() {
        writer.println();
    }

    public void close() {
        writer.close();
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Main class that reads a rectangular grid, marks several logical zones
 * and decides whether a path exists from the start position to the target
 * following the rules described in the original code.
 *
 * The refactor focuses on:
 *   • Meaningful names and constants
 *   • Small, single‑purpose methods
 *   • Clear separation of I/O, grid preparation and algorithmic steps
 *   • Reduced duplication (loops for up/down/left/right are replaced by a
 *     direction vector approach)
 */
public final class BTask {

    /** Symbols used in the input */
    private static final char START = 'S';
    private static final char TARGET = 'T';
    private static final char OBSTACLE = '*';

    /** Markers written into the auxiliary arrays */
    private static final int MARK_REACHABLE_FROM_TARGET = 4; // arr
    private static final int MARK_REACHABLE_FROM_START    = 5; // arr2

    /** Directions used for moving in the grid */
    private static final int[][] DIRS = {
            {1, 0},   // down
            {-1, 0},  // up
            {0, 1},   // right
            {0, -1}   // left
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;          // original input characters
    private final int[][] reachableFromTarget; // same size as grid, markers
    private final int[][] reachableFromStart;  // same size as grid, markers

    /** Entry point */
    public static void main(String[] args) throws IOException {
        new BTask().solve();
    }

    /** Reads the whole input and builds the internal representation. */
    private void solve() throws IOException {
        try (MyInputReader in = new MyInputReader(System.in)) {
            rows = in.nextInt();
            cols = in.nextInt();
            grid = new char[rows][cols];

            // Locate the start and target cells while reading the grid
            int startRow = -1, startCol = -1;
            int targetRow = -1, targetCol = -1;

            for (int r = 0; r < rows; r++) {
                char[] line = in.next().toCharArray();
                for (int c = 0; c < line.length; c++) {
                    grid[r][c] = line[c];
                    if (line[c] == START) {
                        startRow = r;
                        startCol = c;
                    } else if (line[c] == TARGET) {
                        targetRow = r;
                        targetCol = c;
                    }
                }
            }

            // Prepare auxiliary tables
            reachableFromTarget = new int[rows][cols];
            reachableFromStart  = new int[rows][cols];

            markObstacles();
            markReachableFromTarget(targetRow, targetCol);
            markReachableFromStart(startRow, startCol);
            evaluateAndPrintResult();
        }
    }

    /** Marks every obstacle ('*') with the numeric constant OBSTACLE_VALUE. */
    private void markObstacles() {
        final int OBSTACLE_VALUE = 1;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == OBSTACLE) {
                    // we store 1 as the canonical obstacle marker
                    // (the original code also used 1 in arr)
                    reachableFromTarget[r][c] = OBSTACLE_VALUE;
                }
            }
        }
    }

    /** Marks cells that are reachable from the target position in the four
     *  orthogonal directions until an obstacle is met. */
    private void markReachableFromTarget(int tr, int tc) {
        final int MARK = MARK_REACHABLE_FROM_TARGET;

        for (int[] d : DIRS) {
            exploreDirection(tr, tc, d[0], d[1], (dr, dc) -> {
                int nr = tr + dr;
                int nc = tc + dc;
                if (!inBounds(nr, nc)) return;
                if (reachableFromTarget[nr][nc] != 0) return; // already processed
                if (reachableFromTarget[nr][nc] == 1) return; // obstacle barrier
                reachableFromTarget[nr][nc] = MARK;
                // continue walking further in the same direction
                exploreDirection(nr, nc, d[0], d[1], this::markReachableFromTargetCell);
            });
        }
    }

    /** Helper that walks in a single direction, marking cells until a barrier. */
    private void exploreDirection(int r, int c, int dr, int dc,
                                  java.util.function.BiConsumer<Integer, Integer> action) {
        while (true) {
            r += dr;
            c += dc;
            if (!inBounds(r, c)) break;
            if (reachableFromTarget[r][c] != 0) break; // already marked or obstacle
            if (reachableFromTarget[r][c] == 1) break; // obstacle stops propagation
            action.accept(r, c);
        }
    }

    /** Lambda‑friendly stub used by exploreDirection – marks a single cell. */
    private void markReachableFromTargetCell(int r, int c) {
        reachableFromTarget[r][c] = MARK_REACHABLE_FROM_TARGET;
    }

    /** Marks cells that are reachable from the start position in the four
     *  orthogonal directions until an obstacle is met. */
    private void markReachableFromStart(int sr, int sc) {
        final int MARK = MARK_REACHABLE_FROM_START;

        for (int[] d : DIRS) {
            exploreDirection(sr, sc, d[0], d[1], (r, c) -> {
                // Only mark the auxiliary array arr2, not the obstacle table
                reachableFromStart[r][c] = MARK;
                // Continue walking further
                exploreDirection(r, c, d[0], d[1], this::markReachableFromStartCell);
            });
        }
    }

    /** Stub used by exploreDirection for marking cells in arr2. */
    private void markReachableFromStartCell(int r, int c) {
        reachableFromStart[r][c] = MARK_REACHABLE_FROM_START;
    }

    /** Checks whether any cell marked with REACHABLE_FROM_START (5) lies on
     *  a straight line to a REACHABLE_FROM_TARGET (4) cell without crossing
     *  an obstacle. If such a cell exists, prints "YES", otherwise "NO". */
    private void evaluateAndPrintResult() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (reachableFromStart[r][c] == MARK_REACHABLE_FROM_START) {
                    // From this cell we can travel in the four directions
                    // until we hit either an obstacle (value 1) or the border.
                    // If we encounter a cell that already carries MARK_REACHABLE_FROM_TARGET,
                    // a successful path exists.
                    if (canReachTargetFrom(r, c)) {
                        System.out.println("YES");
                        return;
                    }
                }
            }
        }
        System.out.println("NO");
    }

    /** Returns true if from (sr,sc) we can move orthogonally to a cell that
     *  contains MARK_REACHABLE_FROM_TARGET (4) without meeting an obstacle.
     *  The walk stops at the first barrier or out‑of‑bounds cell. */
    private boolean canReachTargetFrom(int sr, int sc) {
        for (int[] d : DIRS) {
            int r = sr + d[0];
            int c = sc + d[1];
            while (inBounds(r, c)) {
                if (reachableFromTarget[r][c] == MARK_REACHABLE_FROM_TARGET) {
                    return true; // success!
                }
                if (reachableFromTarget[r][c] == 1) { // obstacle blocks the way
                    break;
                }
                r += d[0];
                c += d[1];
            }
        }
        return false;
    }

    /** Simple bounds check. */
    private boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Fast scanner that works with the original input format. */
    private static final class MyInputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        MyInputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

/**
 * Refactored solution for the original “B” program.
 *
 * The program reads a rectangular grid, then determines whether a path
 * satisfying the given movement rules can reach at least one target cell.
 *
 * Improvements over the original code:
 *   • Meaningful names and constants instead of single‑letter variables.
 *   • Clear separation of concerns (input handling, state representation,
 *     exploration logic).
 *   • Use of an enum for cell types and a small direction utility.
 *   • Extracted helper methods to avoid duplicated code.
 *   • Comments that explain the purpose of each logical block.
 *   • No magic numbers – all “magic” values are defined as constants.
 */
import java.util.Scanner;

public class Main {

    /** Cell types used in the grid. */
    private enum Cell {
        EMPTY,   // '.'  – free space
        BOX,     // '*'  – obstacle that cannot be entered
        TARGET,  // 'T'  – goal cell
        START;   // 'S'  – starting cell

        static Cell fromChar(char c) {
            switch (c) {
                case '.': return EMPTY;
                case '*': return BOX;
                case 'T': return TARGET;
                case 'S': return START;
                default:  return EMPTY;
            }
        }
    }

    /** Directions: 0 = up, 1 = right, 2 = down, 3 = left */
    private static final int[] DY = { -1, 0, 1, 0 };
    private static final int[] DX = { 0, 1, 0, -1 };

    /**
     * Recursively explores the grid from the current cell.
     *
     * @param startDir   current heading (0 … 3)
     * @param row        current row index
     * @param col        current column index
     * @param grid       2‑D view of the board (cell type enum)
     * @param visited    4‑dimensional visited‑state array
     * @param turnsLeft  remaining “turn budget”
     * @param rows       total number of rows
     * @param cols       total number of columns
     * @return true if the exploration finds at least one target cell
     */
    private static boolean explore(int startDir, int row, int col,
                                   Cell[][] grid,
                                   boolean[][][][] visited,
                                   int turnsLeft,
                                   int rows, int cols) {

        // -----------------------------------------------------------------
        // 1️⃣  Guard clauses – out of bounds, obstacle or already visited
        // -----------------------------------------------------------------
        if (!inside(row, col, rows, cols) || grid[row][col] == Cell.BOX) {
            return false;
        }
        if (visited[startDir][turnsLeft][row][col]) {
            return false;                // already examined this state
        }

        // -----------------------------------------------------------------
        // 2️⃣  Mark the current cell as visited for *all* possible remaining
        //      turn counts that become unavailable after using this step.
        // -----------------------------------------------------------------
        for (int used = 0; used < turnsLeft; used++) {
            for (int dir = 0; dir < 4; dir++) {
                visited[dir][used][row][col] = true;
            }
        }

        // -----------------------------------------------------------------
        // 3️⃣  Did we land on a target cell?
        // -----------------------------------------------------------------
        int targetFound = (grid[row][col] == Cell.TARGET) ? 1 : 0;

        // -----------------------------------------------------------------
        // 4️⃣  Try turning – each turn consumes one unit of the budget.
        // -----------------------------------------------------------------
        if (turnsLeft > 0) {
            for (int newDir = 0; newDir < 4; newDir++) {
                if (explore(newDir, row, col, grid, visited,
                            turnsLeft - 1, rows, cols)) {
                    targetFound++;
                }
            }
        }

        // -----------------------------------------------------------------
        // 5️⃣  Move forward without consuming a turn.
        // -----------------------------------------------------------------
        int nxtRow = row + DY[startDir];
        int nxtCol = col + DX[startDir];
        if (inside(nxtRow, nxtCol, rows, cols)
                && grid[nxtRow][nxtCol] != Cell.BOX) {
            if (explore(startDir, nxtRow, nxtCol, grid, visited,
                        turnsLeft, rows, cols)) {
                targetFound++;
            }
        }

        // -----------------------------------------------------------------
        // 6️⃣  Success if at least one target was discovered on this branch.
        // -----------------------------------------------------------------
        return targetFound > 0;
    }

    /** Simple bounds check. */
    private static boolean inside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** -----------------------------------------------------------------
     *  Entry point – reads the board, initialises the search state and
     *  launches the exploration from every possible initial heading.
     *  ----------------------------------------------------------------- */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int rows = sc.nextInt();   // number of rows
        int cols = sc.nextInt();   // number of columns

        Cell[][] grid = new Cell[rows][cols];
        int startRow = -1, startCol = -1;

        // -------------------------------------------------------------
        // 1️⃣  Read the board and fill the enum‑based grid.
        // -------------------------------------------------------------
        for (int r = 0; r < rows; r++) {
            String line = sc.next();
            if (line.length() != cols) {
                throw new IllegalArgumentException("Row length mismatch");
            }
            for (int c = 0; c < cols; c++) {
                char ch = line.charAt(c);
                Cell cell = Cell.fromChar(ch);
                grid[r][c] = cell;
                if (cell == Cell.START) {
                    startRow = r;
                    startCol = c;
                }
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣  visited[direction][turnsLeft][row][col] – 3‑dimensional
        //      budget array, initialised to false.
        // -----------------------------------------------------------------
        boolean[][][][] visited = new boolean[4][3][rows][cols];

        // -----------------------------------------------------------------
        // 3️⃣  Try every possible starting heading (0 … 3).  The original
        //      program started the search with a fixed “turns left” of 2.
        // -----------------------------------------------------------------
        boolean found = false;
        for (int dir = 0; dir < 4; dir++) {
            if (explore(dir, startRow, startCol, grid, visited, 2, rows, cols)) {
                found = true;
                break;
            }
        }

        System.out.println(found ? "YES" : "NO");
        sc.close();
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) {
        try (FastScanner scanner = new FastScanner(System.in);
             FastPrinter printer = new FastPrinter(System.out)) {

            new Solver().solve(scanner, printer);
        }
    }

    /*** FastInput ---------------------------------------------------------------*/
    public static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 12];
        private int bufferPos = 0, bufferLen = 0;
        private int curChar = 0;

        public FastScanner(InputStream stream) {
            this.stream = Objects.requireNonNull(stream);
        }

        private int readByte() {
            if (curChar >= bufferLen) {
                bufferLen = stream.read(buffer);
                bufferPos = 0;
                curChar = 0;
                if (bufferLen == -1) {
                    return -1;
                }
            }
            return buffer[curChar++];
        }

        private int nextNonWhitespace() {
            int c;
            do {
                c = readByte();
                if (c == -1) {
                    throw new NoSuchElementException();
                }
            } while (Character.isWhitespace(c));
            return c;
        }

        /** Reads next integer (optionally signed). */
        public int nextInt() {
            int sign = 1;
            int c = nextNonWhitespace();
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int value = 0;
            do {
                value = value * 10 + (c - '0');
                c = readByte();
            } while (!Character.isWhitespace(c));
            return value * sign;
        }

        public boolean hasNext() {
            try {
                skipWhitespace();
                return true;
            } catch (NoSuchElementException e) {
                return false;
            }
        }

        private void skipWhitespace() {
            int c;
            do {
                c = readByte();
                if (c == -1) {
                    throw new NoSuchElementException();
                }
            } while (Character.isWhitespace(c));
            curChar = 0; // put back first non‑whitespace character
        }

        /** Retrieves the next non‑whitespace character. */
        public char nextCharacter() {
            int c = nextNonWhitespace();
            return (char) c;
        }

        /** Reads exactly {@code length} characters. */
        public char[] nextCharacterArray(int length) {
            char[] arr = new char[length];
            for (int i = 0; i < length; i++) {
                arr[i] = nextCharacter();
            }
            return arr;
        }

        /** Reads a rectangular map of characters. */
        public char[][] nextCharacterMap(int rows, int columns) {
            char[][] map = new char[rows][];
            for (int r = 0; r < rows; r++) {
                map[r] = nextCharacterArray(columns);
            }
            return map;
        }
    }

    /*** FastOutput ---------------------------------------------------------------*/
    public static final class FastPrinter implements AutoCloseable {
        private final PrintWriter writer;
        private final StringBuilder buffer = new StringBuilder();

        public FastPrinter(OutputStream out) {
            this.writer = new PrintWriter(out);
        }

        /** Prints a line, buffering until a reasonable size is reached. */
        public void println(String s) {
            buffer.append(s).append('\n');
            if (buffer.length() > 8192) {
                writer.print(buffer.toString());
                buffer.setLength(0);
            }
        }

        @Override
        public void close() {
            writer.flush();
        }
    }

    /*** Solver -------------------------------------------------------------------*/
    public static final class Solver {

        private static final int UNVISITED = 99;
        private static final int MIN_ALLOWED_COST = 2;

        // four cardinal directions
        private final int[] dr = {1, 0, -1, 0};
        private final int[] dc = {0, 1, 0, -1};

        /** Executes the solution for a single test case. */
        public void solve(FastScanner in, FastPrinter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = in.nextCharacterMap(n, m);

            int srcR = -1, srcC = -1;
            int dstR = -1, dstC = -1;

            // locate start 'S' and target 'T' while clearing them from the grid
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    char ch = grid[r][c];
                    if (ch == 'S') {
                        srcR = r;
                        srcC = c;
                        grid[r][c] = '.';
                    } else if (ch == 'T') {
                        dstR = r;
                        dstC = c;
                        grid[r][c] = '.';
                    }
                }
            }

            // distance[direction][row][col] – the cheapest cost to reach (row,col)
            // while moving with the given direction as the previous step.
            int[][][] distance = new int[4][n][m];
            for (int[][] plane : distance) {
                Arrays.fill(plane, UNVISITED);
            }

            Deque<int[]> queue = new ArrayDeque<>();
            // push the start cell for all four possible initial directions
            for (int dir = 0; dir < 4; dir++) {
                distance[dir][srcR][srcC] = 0;
                queue.addLast(new int[]{dir, srcR, srcC});
            }

            while (!queue.isEmpty()) {
                int[] cur = queue.pollFirst();
                int dir = cur[0];
                int r = cur[1];
                int c = cur[2];

                if (r == dstR && c == dstC) {
                    out.println(distToTarget <= MIN_ALLOWED_COST ? "YES" : "NO");
                    return;
                }

                for (int nextDir = 0; nextDir < 4; nextDir++) {
                    int nr = r + dr[nextDir];
                    int nc = c + dc[nextDir];

                    // stay inside bounds and on an empty cell
                    if (!inside(nr, n) || !inside(nc, m) || grid[nr][nc] != '.') {
                        continue;
                    }

                    if (nextDir == dir) {
                        // continue straight – cost unchanged
                        if (distance[nextDir][nr][nc] > distance[dir][r][c]) {
                            distance[nextDir][nr][nc] = distance[dir][r][c];
                            queue.addFirst(new int[]{nextDir, nr, nc});
                        }
                    } else {
                        // turn – cost increases by 1
                        if (distance[nextDir][nr][nc] > distance[dir][r][c] + 1) {
                            distance[nextDir][nr][nc] = distance[dir][r][c] + 1;
                            queue.addLast(new int[]{nextDir, nr, nc});
                        }
                    }
                }
            }

            out.println("NO");
        }

        /** Helper – verifies that an index is within [0, limit). */
        private boolean inside(int idx, int limit) {
            return idx >= 0 && idx < limit;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        private static final char START = 'S';
        private static final char END = 'T';
        private static final int INF = Integer.MAX_VALUE;
        private static final int[] dr = {0, -1, 0, 1};
        private static final int[] dc = {-1, 0, 1, 0};
        private static final char BLOCK = '*';
        private static final int THRESHOLD = 2;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int nRows = in.nextInt();
            int nCols = in.nextInt();
            char[][] grid = new char[nRows][];
            int startRow = -1, startCol = -1;
            int endRow = -1, endCol = -1;
            for (int i = 0; i < nRows; ++i) {
                grid[i] = in.next().toCharArray();
                for (int j = 0; j < nCols; ++j) {
                    if (grid[i][j] == START) {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == END) {
                        endRow = i;
                        endCol = j;
                    }
                }
            }

            int[][][] minTurns = new int[nRows][nCols][dr.length];
            for (int[][] x : minTurns) for (int[] y : x) Arrays.fill(y, INF);

            List<State> frontier = new ArrayList<>();
            for (int i = 0; i < dr.length; ++i) {
                minTurns[startRow][startCol][i] = 0;
                frontier.add(new State(startRow, startCol, i));
            }

            while (!frontier.isEmpty()) {
                List<State> next = new ArrayList<>();
                for (State state : frontier) {
                    int currentTurns = minTurns[state.row][state.col][state.dir];

                    int r = state.row + dr[state.dir];
                    int c = state.col + dc[state.dir];
                    traverse(r, c, state.dir, currentTurns, next, minTurns, grid, nRows, nCols);

                    if (currentTurns + 1 <= THRESHOLD) {
                        for (int dir = 0; dir < dr.length; ++dir) {
                            if (dir == state.dir) continue;
                            int nr = state.row + dr[dir];
                            int nc = state.col + dc[dir];
                            traverse(nr, nc, dir, currentTurns + 1, next, minTurns, grid, nRows, nCols);
                        }
                    }
                }
                frontier = next;
            }

            int result = INF;
            for (int i = 0; i < dr.length; ++i)
                result = Math.min(result, minTurns[endRow][endCol][i]);
            out.println((result <= THRESHOLD) ? "YES" : "NO");
        }

        private void traverse(int r, int c, int dir, int turnCount,
                              List<State> next, int[][][] minTurns,
                              char[][] grid, int nRows, int nCols) {
            while (r >= 0 && r < nRows && c >= 0 && c < nCols && grid[r][c] != BLOCK && 
                   minTurns[r][c][dir] > turnCount) {
                minTurns[r][c][dir] = turnCount;
                next.add(new State(r, c, dir));
                r += dr[dir];
                c += dc[dir];
            }
        }

        private static class State {
            private final int row;
            private final int col;
            private final int dir;

            private State(int row, int col, int dir) {
                this.row = row;
                this.col = col;
                this.dir = dir;
            }
        }

    }

    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(
                    new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * Reads a grid that represents a city map and determines whether a
 * “dewIt” propagation can reach a given target cell.
 *
 * <p>The map contains:
 * <ul>
 *   <li>'T' – the office (starting point for propagation)</li>
 *   <li>'S' – the home (origin of the search)</li>
 *   <li>'.' – empty passable cell</li>
 *   <li>any other character – obstacle</li>
 * </ul>
 *
 * <p>The algorithm tries to extend the propagation from the home cell
 * in straight lines until it either hits a target cell or an obstacle.
 * If the target can be reached the program prints {@code YES},
 * otherwise it tries alternative starting points marked with values {@code 1}
 * and {@code 2} (the original behaviour) and finally prints {@code NO}
 * if none succeed.
 */
public class Solution {

    /** Value used for an empty cell ('.') */
    private static final int EMPTY_VALUE = 4;

    /** Value used for obstacles (any character other than 'T', 'S', '.') */
    private static final int OBSTACLE_VALUE = -1;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            processInput(scanner);
        }
    }

    /** Reads the whole input, builds the grid and starts the search. */
    private static void processInput(Scanner scanner) {
        // ----- read dimensions -------------------------------------------------
        String[] sizeTokens = scanner.nextLine().split("\\s+");
        int rows = Integer.parseInt(sizeTokens[0]);
        int cols = Integer.parseInt(sizeTokens[1]);

        // ----- initialise grid and remember positions of home & office ---------
        int[][] grid = new int[rows][cols];
        int[] home = new int[2];
        int[] office = new int[2];

        for (int i = 0; i < rows; i++) {
            char[] chars = scanner.nextLine().toCharArray();
            for (int j = 0; j < cols; j++) {
                char cell = chars[j];
                if (cell == 'T') {
                    grid[i][j] = 0;                     // office
                    office[0] = i;
                    office[1] = j;
                } else if (cell == 'S') {
                    grid[i][j] = EMPTY_VALUE;          // home marker
                    home[0] = i;
                    home[1] = j;
                } else if (cell == '.') {
                    grid[i][j] = EMPTY_VALUE;          // empty passable cell
                } else {
                    grid[i][j] = OBSTACLE_VALUE;      // obstacle
                }
            }
        }

        // ----- first try: direct propagation from home to office -------------
        if (canReachTarget(grid, rows, cols, home[0], home[1], office[0], office[1])) {
            System.out.println("YES");
            return;
        }

        // ----- additional attempts using cells with values 1 and 2 -----------
        for (int sentinel : new int[]{1, 2}) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == sentinel) {
                        if (canReachTarget(grid, rows, cols, home[0], home[1], i, j)) {
                            System.out.println("YES");
                            return;
                        }
                    }
                }
            }
        }

        System.out.println("NO");
    }

    /**
     * Attempts to propagate from the home cell towards a target cell.
     *
     * @return {@code true} if the target can be reached, {@code false} otherwise
     */
    private static boolean canReachTarget(int[][] grid, int rows, int cols,
                                          int startX, int startY,
                                          int targetX, int targetY) {
        int stepValue = grid[startX][startY] + 1;

        // propagate in the four cardinal directions; return true as soon as
        // the target cell is encountered.
        if (propagateDirection(grid, rows, cols, startX, startY, stepValue,
                Direction.DOWN, targetX, targetY)) return true;
        if (propagateDirection(grid, rows, cols, startX, startY, stepValue,
                Direction.UP, targetX, targetY)) return true;
        if (propagateDirection(grid, rows, cols, startX, startY, stepValue,
                Direction.RIGHT, targetX, targetY)) return true;
        if (propagateDirection(grid, rows, cols, startX, startY, stepValue,
                Direction.LEFT, targetX, targetY)) return true;

        return false;
    }

    /**
     * Propagates {@code value} in the given direction until an obstacle or a
     * lower value is met. If the traversal steps on {@code (targetX, targetY)}
     * the method returns {@code true}.
     *
     * @return {@code true} if the target cell was reached during propagation
     */
    private static boolean propagateDirection(int[][] grid, int rows, int cols,
                                              int srcX, int srcY, int value,
                                              Direction dir, int targetX, int targetY) {
        switch (dir) {
            case DOWN:
                for (int i = srcX + 1; i < rows; i++) {
                    if (grid[i][srcY] < value) break;
                    if (i == targetX && srcY == targetY) return true;
                    grid[i][srcY] = value;
                }
                break;
            case UP:
                for (int i = srcX - 1; i >= 0; i--) {
                    if (grid[i][srcY] < value) break;
                    if (i == targetX && srcY == targetY) return true;
                    grid[i][srcY] = value;
                }
                break;
            case RIGHT:
                for (int j = srcY + 1; j < cols; j++) {
                    if (grid[srcX][j] < value) break;
                    if (srcX == targetX && j == targetY) return true;
                    grid[srcX][j] = value;
                }
                break;
            case LEFT:
                for (int j = srcY - 1; j >= 0; j--) {
                    if (grid[srcX][j] < value) break;
                    if (srcX == targetX && j == targetY) return true;
                    grid[srcX][j] = value;
                }
                break;
        }
        return false;
    }

    /** Simple enum describing the four cardinal directions. */
    private enum Direction {
        UP, DOWN, LEFT, RIGHT
    }
}

package solution;

import java.io.*;
import java.util.ArrayDeque;
import java.util.Queue;

/**
 * Entry point of the application.
 * Creates a {@link ConsoleIO} instance and delegates the solution to {@link Solver}.
 */
public class Main {
    public static void main(String[] args) throws IOException {
        ConsoleIO io = new ConsoleIO(new InputStreamReader(System.in), new PrintWriter(System.out));
        new Solver(io).solve();
        io.close();
    }
}

/**
 * Simple I/O wrapper that hides the raw {@link BufferedReader}/{@link PrintWriter} details.
 * Only the methods actually required by the solution are implemented.
 */
class ConsoleIO {
    private final BufferedReader br;
    private final PrintWriter out;

    ConsoleIO(Reader reader, PrintWriter writer) {
        this.br = new BufferedReader(reader);
        this.out = writer;
    }

    /** Writes a line to {@code stdout}. */
    void writeLine(String msg) {
        out.println(msg);
    }

    /** Reads a line that contains space‑separated integers and parses them into an {@code int[]}. */
    int[] readIntArray() {
        String[] parts = br.readLine().trim().split("\\s+");
        int[] arr = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            arr[i] = Integer.parseInt(parts[i]);
        }
        return arr;
    }

    /** Reads {@code rows} lines and converts each line into a character array (the maze). */
    char[][] readGrid(int rows) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = readLine();
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /** Convenience method used only by the refactored solution. */
    private String readLine() {
        try {
            return br.readLine();
        } catch (Exception e) {
            return "";
        }
    }
}

/**
 * Core solving algorithm – BFS with a carefully crafted state representation.
 * All magic numbers are named, the search logic is split into small helper methods,
 * and the visited‑state handling is expressed with clear types instead of bit‑mask gymnastics.
 */
final class Solver {
    /** Directions: up, left, down, right */
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, -1, 0, 1};

    /** Maximum number of consecutive steps in the same direction that we need to keep track of */
    private static final int MAX_CONSECUTIVE = 2;
    /** How many direction possibilities are encoded per flag group */
    private static final int FLAG_GROUP_SIZE = 4;

    private final ConsoleIO io;
    /** Value kept for backward compatibility with the original code (not used any more). */
    private static final long MOD = 1_000_000_007L;

    Solver(ConsoleIO io) {
        this.io = io;
    }

    /** Holds a node in the breadth‑first search. */
    private static final class Node {
        final int row;
        final int col;
        final int dir;          // direction that led to this cell
        final int steps;        // consecutive steps taken in {@code dir}

        Node(int row, int col, int dir, int steps) {
            this.row = row;
            this.col = col;
            this.dir = dir;
            this.steps = steps;
        }
    }

    /** Executes the solution – reads input, runs BFS and prints “YES” or “NO”. */
    void solve() {
        int[] dims = io.readIntArray();                 // first line: n m
        int rows = dims[0];
        int cols = dims[1];
        char[][] grid = io.readGrid(rows);               // subsequent lines are the maze rows

        int startR = -1, startC = -1;
        outer:
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'S') {
                    startR = r;
                    startC = c;
                    break outer;
                }
            }
        }
        if (startR == -1) {
            io.writeLine("NO");
            return;
        }

        // Queue holds all reachable states
        Queue<Node> queue = new ArrayDeque<>();
        // Initial moves – try every direction from the start cell
        for (int d = 0; d < 4; d++) {
            int nr = startR + DR[d];
            int nc = startC + DC[d];
            if (inside(nr, nc, rows, cols) && grid[nr][nc] != '*') {
                queue.add(new Node(nr, nc, d, 1));
            }
        }

        // visited[r][c][dir][steps-1] tells whether that state has been processed
        boolean[][][][] visited = new boolean[rows][cols][4][MAX_CONSECUTIVE];
        outerLoop:
        while (!queue.isEmpty()) {
            Node cur = queue.poll();
            if (grid[cur.row][cur.col] == 'T') {
                io.writeLine("YES");
                return;
            }

            for (int nd = 0; nd < 4; nd++) {
                int nr = cur.row + DR[nd];
                int nc = cur.col + DC[nd];
                if (!inside(nr, nc, rows, cols) || grid[nr][nc] == '*') {
                    continue;
                }
                // Rule: after two steps in a row you must continue straight
                if (cur.steps == MAX_CONSECUTIVE && nd != cur.dir) {
                    continue;
                }
                int newSteps = (nd == cur.dir) ? cur.steps + 1 : 1;
                if (newSteps > MAX_CONSECUTIVE) {
                    newSteps = MAX_CONSECUTIVE; // treat >2 the same as exactly 2
                }
                if (visited[nr][nc][nd][newSteps - 1]) {
                    continue;
                }
                visited[nr][nc][nd][newSteps - 1] = true;
                queue.add(new Node(nr, nc, nd, newSteps));
            }
        }

        io.writeLine("NO");
    }

    /** Utility – checks whether a coordinate lies inside the grid. */
    private static boolean inside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Queue;

/**
 * Solves the problem described in the original {@code B} class.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Logical separation into small, well‑named methods.</li>
 *   <li>Use of constants and enums instead of magic numbers.</li>
 *   <li>Descriptive variable names and minimal nesting.</li>
 *   <li>Clear handling of input/output with try‑with‑resources.</li>
 *   <li>Early exit when the target {@code T} is reached.</li>
 * </ul>
 */
public final class B {

    /** Symbol used for a cell that belongs to the source line. */
    private static final int MARK_START = 2;

    /** Symbol used for a cell that has been visited during BFS. */
    private static final int MARK_VISITED = 3;

    /** Symbol used for cells that belong to the blocked path from the target. */
    private static final int MARK_BLOCKED = 1;

    /** Output string for a successful answer. */
    private static final String YES = "YES" + System.lineSeparator();

    /** Output string for a failing answer. */
    private static final String NO = "NO" + System.lineSeparator();

    /** Directions used for walking from the source cell. */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int getDr() {
            return dr;
        }

        int getDc() {
            return dc;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out))) {

            char[][] grid = readGrid(reader);
            int[] source = locateSymbol(grid, 'S');
            int[] target = locateSymbol(grid, 'T');

            if (source == null || target == null) {
                writer.write(NO);
                return;
            }

            int n = grid.length;
            int m = grid[0].length;

            int[][] vals = new int[n][m];               // 0 = empty, 1 = blocked, 2 = start, 3 = visited
            markBlockedLinesFromTarget(grid, target, vals);
            if (vals[source[0]][source[1]] == MARK_BLOCKED) {
                writer.write(YES);
                return;
            }

            Queue<int[]> bfsQueue = new ArrayDeque<>();
            populateStartMarkings(grid, source, vals, bfsQueue);
            bfs(grid, vals, bfsQueue, writer);
        }
    }

    /**
     * Reads the dimensions {@code n} and {@code m} followed by {@code n} strings
     * representing the grid.
     */
    private static char[][] readGrid(BufferedReader reader) throws IOException {
        String[] parts = reader.readLine().split("\\s+");
        int n = Integer.parseInt(parts[0]);
        int m = Integer.parseInt(parts[1]);

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.readLine().toCharArray();
        }
        return grid;
    }

    /**
     * Returns the coordinates of the first occurrence of {@code symbol}
     * in {@code grid} or {@code null} if not found.
     */
    private static int[] locateSymbol(char[][] grid, char symbol) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == symbol) {
                    return new int[]{r, c};
                }
            }
        }
        return null;
    }

    /**
     * Marks the cells that belong to the straight lines extending from the target
     * upward, downward, leftward and rightward until a non‑empty cell is met.
     * Those cells receive {@link #MARK_BLOCKED} in {@code vals}.
     */
    private static void markBlockedLinesFromTarget(char[][] grid, int[] target, int[][] vals) {
        int r = target[0];
        int c = target[1];

        // upward
        for (int i = r; i < grid.length; i++) {
            char ch = grid[i][c];
            if (ch == '.' || ch == 'T') {
                vals[i][c] = MARK_BLOCKED;
            } else if (ch == 'S') {
                // Directly reachable from source – answer is YES
                System.out.print(YES);
                System.exit(0);
            } else {
                break;
            }
        }

        // downward
        for (int i = r; i >= 0; i--) {
            char ch = grid[i][c];
            if (ch == '.' || ch == 'T') {
                vals[i][c] = MARK_BLOCKED;
            } else if (ch == 'S') {
                System.out.print(YES);
                System.exit(0);
            } else {
                break;
            }
        }

        // left
        for (int j = c; j < grid[0].length; j++) {
            char ch = grid[r][j];
            if (ch == '.' || ch == 'T') {
                vals[r][j] = MARK_BLOCKED;
            } else if (ch == 'S') {
                System.out.print(YES);
                System.exit(0);
            } else {
                break;
            }
        }

        // right
        for (int j = c; j >= 0; j--) {
            char ch = grid[r][j];
            if (ch == '.' || ch == 'T') {
                vals[r][j] = MARK_BLOCKED;
            } else if (ch == 'S') {
                System.out.print(YES);
                System.exit(0);
            } else {
                break;
            }
        }
    }

    /**
     * Marks the cells that belong to the four straight lines stemming from the
     * source cell. Those cells receive {@link #MARK_START} and are enqueued
     * as starting points for the BFS.
     */
    private static void populateStartMarkings(char[][] grid, int[] src, int[][] vals, Queue<int[]> queue) {
        int r = src[0];
        int c = src[1];

        // walk upward until a non‑empty cell is found
        walkAndMark(grid, r, c, Direction.UP, MARK_START, queue);
        // walk downward
        walkAndMark(grid, r, c, Direction.DOWN, MARK_START, queue);
        // walk left
        walkAndMark(grid, r, c, Direction.LEFT, MARK_START, queue);
        // walk right
        walkAndMark(grid, r, c, Direction.RIGHT, MARK_START, queue);
    }

    /**
     * Helper that walks from {@code startR,startC} in the given {@code dir}
     * direction, marking each visited cell with {@code mark} and adding the
     * first cell of the walk to the {@code queue}. Stops when a non‑empty
     * character (other than '.' or 'S') is encountered.
     */
    private static void walkAndMark(char[][] grid, int startR, int startC,
                                    Direction dir, int mark, Queue<int[]> queue) {
        int r = startR;
        int c = startC;
        boolean first = true;

        while (inBounds(grid, r, c)) {
            char ch = grid[r][c];
            if (ch == '.' || ch == 'S') {
                if (first) {
                    queue.add(new int[]{r, c});
                    vals[r][c] = mark;
                }
                // continue walking in the same direction
                r += dir.getDr();
                c += dir.getDc();
                first = false;
            } else if (ch == 'T') {
                System.out.print(YES);
                System.exit(0);
            } else {
                break;
            }
        }
    }

    /** Returns {@code true} if {@code r,c} is inside the grid. */
    private static boolean inBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /**
     * Performs the breadth‑first search described in the original algorithm.
     * If the target {@code T} is reached during expansion the program prints
     * {@code YES} and terminates; otherwise after the queue empties it prints
     * {@code NO}.
     */
    private static void bfs(char[][] grid, int[][] vals,
                            Queue<int[]> queue, BufferedWriter writer) throws IOException {
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];

            // Expand vertically (column c)
            expandLine(grid, vals, r, c, Direction.UP, queue, writer);
            expandLine(grid, vals, r, c, Direction.DOWN, queue, writer);

            // Expand horizontally (row r)
            expandLine(grid, vals, r, c, Direction.LEFT, queue, writer);
            expandLine(grid, vals, r, c, Direction.RIGHT, queue, writer);
        }

        writer.write(NO);
    }

    /**
     * Walks from the given cell in the supplied direction, marking empty cells
     * as visited, stopping at a cell that already carries {@link #MARK_BLOCKED}
     * or {@code T}. If {@code T} is encountered the writer receives {@code YES}
     * and the program terminates.
     */
    private static void expandLine(char[][] grid, int[][] vals,
                                   int startR, int startC,
                                   Direction dir, Queue<int[]> queue, BufferedWriter writer) throws IOException {
        int r = startR;
        int c = startC;
        boolean firstStep = true;

        while (inBounds(grid, r, c)) {
            char ch = grid[r][c];
            if (ch == 'T' || vals[r][c] == MARK_BLOCKED) {
                writer.write(YES);
                System.exit(0);
            }
            if (ch != '.') {
                break;
            }
            if (firstStep) {
                // The first empty cell we encounter becomes part of the frontier
                queue.add(new int[]{r, c});
                vals[r][c] = MARK_VISITED;
                firstStep = false;
            }
            r += dir.getDr();
            c += dir.getDc();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Finds whether there exists a path from the start cell ('S') to the target cell ('T')
 * that contains at most two direction changes.
 *
 * The solution uses a BFS where each state stores:
 *   - coordinates,
 *   - the direction we are currently moving in,
 *   - the number of turns made so far.
 *
 * If we can reach 'T' with ≤ 2 turns the answer is "YES", otherwise "NO".
 */
public class D implements Runnable {

    /** Directions are numbered 0‑3 (up, right, down, left). */
    private static final class Direction {
        final int index;
        final int dx;
        final int dy;

        Direction(int index, int dx, int dy) {
            this.index = index;
            this.dx = dx;
            this.dy = dy;
        }

        /** Returns the opposite direction (e.g. up↔down, left↔right). */
        Direction opposite() {
            switch (index) {
                case 0: return new Direction(2, dx, dy); // up → down
                case 2: return new Direction(0, dx, dy); // down → up
                case 1: return new Direction(3, dx, dy); // right → left
                case 3: return new Direction(1, dx, dy); // left → right
                default: throw new IllegalStateException();
            }
        }
    }

    /** Directions in the order: up, right, down, left. */
    private static final Direction[] ALL = {
            new Direction(0, -1,  0), // up
            new Direction(1,  0,  1), // right
            new Direction(2,  1,  0), // down
            new Direction(3,  0, -1)  // left
    };

    /** Large value used for initialisation of the distance matrix. */
    private static final int INF = Integer.MAX_VALUE;

    /** Size of the board – will be set after reading input. */
    private static int n, m;

    /** The board itself. */
    private static char[][] grid;

    /** Minimum number of turns needed to reach each cell while moving in a given direction. */
    private static int[][][] minTurns;

    /** Coordinates of the start and target cells. */
    private static int startX, startY, targetX, targetY;

    /** Queue used for the BFS. */
    private static final Queue<State> bfsQueue = new ArrayDeque<>();

    /** Simple holder for a board coordinate. */
    private static final class Pair {
        final int x, y;
        Pair(int x, int y) { this.x = x; this.y = y; }
    }

    /** One BFS entry: position, current direction, number of turns performed so far. */
    private static final class State {
        final Pair cell;
        final Direction dir;   // direction we are moving in when we entered the cell
        final int turns;         // how many direction changes we have performed up to this cell

        State(Pair cell, Direction dir, int turns) {
            this.cell = cell;
            this.dir = dir;
            this.turns = turns;
        }
    }

    /** Entry point – the program follows the typical competitive‑programming template. */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        m = fs.nextInt();

        grid = new char[n][m];
        minTurns = new int[n][m][4];
        for (int i = 0; i < n; i++) {
            Arrays.fill(minTurns[i], INF);
        }

        Pair start = null;
        Pair target = null;

        for (int i = 0; i < n; i++) {
            String line = fs.next();
            for (int j = 0; j < m; j++) {
                char ch = line.charAt(j);
                grid[i][j] = ch;
                if (ch == '*') {
                    // obstacles are unreachable – keep the INF value
                } else if (ch == 'S') {
                    start = new Pair(i, j);
                } else if (ch == 'T') {
                    target = new Pair(i, j);
                }
            }
        }

        // Initialise the search from the start cell.
        minTurns[start.x][start.y][0] = 0; // direction index does not matter yet
        minTurns[start.x][start.y][1] = 0;
        minTurns[start.x][start.y][2] = 0;
        minTurns[start.x][start.y][3] = 0;

        // From the start we may move in any of the four directions (if not blocked).
        for (Direction d : ALL) {
            int nx = start.x + d.dx;
            int ny = start.y + d.dy;
            if (!inBounds(nx, ny) || grid[nx][ny] == '*') {
                continue;
            }
            minTurns[nx][ny][d.index] = 0; // first step costs 0 turns
            bfsQueue.offer(new State(new Pair(nx, ny), d, 0));
        }

        // BFS
        while (!bfsQueue.isEmpty()) {
            State cur = bfsQueue.poll();
            Pair p = cur.cell;

            // When we pop a state we know we already have the optimal (minimal) turn count
            // for this (cell, direction, turns) triple, so we can safely expand.
            for (Direction next : ALL) {
                int nnx = p.x + next.dx;
                int nny = p.y + next.dy;
                if (!inBounds(nnx, nny) || grid[nnx][ny] == '*') {
                    continue;
                }

                int newTurns = cur.turns;
                if (cur.dir != null && cur.dir.index != next.index) {
                    newTurns++;
                }

                if (newTurns > 2) {
                    continue; // we are allowed at most two direction changes
                }

                if (minTurns[nnx][nny][next.index] > newTurns) {
                    minTurns[nnx][nny][next.index] = newTurns;
                    bfsQueue.offer(new State(new Pair(nnx, nny), next, newTurns));
                }
            }
        }

        // If any direction reaching the target uses ≤ 2 turns, answer YES.
        boolean reachable = false;
        for (int dir = 0; dir < 4; dir++) {
            if (minTurns[target.x][target.y][dir] <= 2) {
                reachable = true;
                break;
            }
        }

        System.out.println(reachable ? "YES" : "NO");
    }

    /** Simple bounds check. */
    private static boolean inBounds(int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /** Very small scanner that skips whitespace and reads tokens quickly. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Run the program – required by the Runnable interface used in the original stub. */
    @Override
    public void run() {
        // The logic lives in main(); we keep the signature to match the original stub.
        main(new String[0]);
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the problem described in the original {@code TinkoffB} solution.
 * The refactor aims at readability, clear separation of concerns and
 * self‑documenting code while preserving the original algorithmic behaviour.
 */
public class TinkoffB {

    /** Directions used throughout the program. */
    private enum Dir {
        NORTH( -1, 0 ),
        EAST( 0, 1 ),
        SOUTH( 1, 0 ),
        WEST( 0, -1 );

        private final int dr;
        private final int dc;

        Dir(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        /** Move one step in this direction from {@code r,c}. */
        int[] offset() {
            return new int[]{dr, dc};
        }

        /** Order of directions – used for enumerating all four sides. */
        static final List<Dir> ALL = List.of(NORTH, EAST, SOUTH, WEST);
    }

    /** Encapsulates a BFS node: position, current facing direction and remaining allowed turns. */
    private static final class State {
        final int row;
        final int col;
        final Dir facing;
        final int turnsRemaining;

        State(int row, int col, Dir facing, int turnsRemaining) {
            this.row = row;
            this.col = col;
            this.facing = facing;
            this.turnsRemaining = turnsRemaining;
        }
    }

    /** Simple fast scanner. */
    private static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Wrapper around the solving algorithm. */
    private static final class Solver {

        /** Directions as integer indices (kept to match original visited layout). */
        private static final int NORTH_IDX = 0;
        private static final int EAST_IDX  = 1;
        private static final int SOUTH_IDX = 2;
        private static final int WEST_IDX  = 3;

        /** Maximum number of direction changes allowed (same as original code). */
        private static final int MAX_TURNS = 2;

        void solve(InputReader in, PrintWriter out) {
            final int rows = in.nextInt();
            final int cols = in.nextInt();

            // ------------------------------------------------------------------
            // 1. Read grid and locate start / target cells
            // ------------------------------------------------------------------
            char[][] grid = new char[rows][];
            int startR = -1, startC = -1;
            int endR = -1,   endC = -1;

            for (int r = 0; r < rows; r++) {
                String line = in.next();
                grid[r] = line.toCharArray();
                for (int c = 0; c < cols; c++) {
                    char ch = grid[r][c];
                    if (ch == 'S') {
                        startR = r;
                        startC = c;
                    } else if (ch == 'T') {
                        endR = r;
                        endC = c;
                    }
                }
            }

            // ------------------------------------------------------------------
            // 2. Prepare visited array: visited[row][col][dir][turnsRemain]
            // ------------------------------------------------------------------
            boolean[][][][] visited = new boolean[rows][cols][Dir.ALL.size()][MAX_TURNS + 1];

            // initialise all entries to false (explicit for clarity)
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    for (int d = 0; d < Dir.ALL.size(); d++) {
                        Arrays.fill(visited[r][c][d], false);
                    }
                }
            }

            // ------------------------------------------------------------------
            // 3. BFS initialisation
            // ------------------------------------------------------------------
            Queue<State> queue = new ArrayDeque<>();
            // start with every possible initial facing direction and full turn budget
            for (Dir startDir : Dir.ALL) {
                visited[startR][startC][index(startDir)][MAX_TURNS] = true;
                queue.add(new State(startR, startC, startDir, MAX_TURNS));
            }

            // ------------------------------------------------------------------
            // 4. BFS execution
            // ------------------------------------------------------------------
            boolean found = false;

            while (!queue.isEmpty() && !found) {
                int levelSize = queue.size();
                for (int i = 0; i < levelSize; i++) {
                    State cur = queue.poll();

                    // Success condition: we have reached the target cell in any valid state
                    if (cur.row == endR && cur.col == endC) {
                        found = true;
                        break;
                    }

                    // Try turning left / right (reduce remaining turns) or keep going straight
                    for (Dir nextDir : Dir.ALL) {
                        // Rule 1 – moving straight does not consume a turn
                        if (cur.facing == nextDir) {
                            if (canMoveForward(cur, rows, cols, grid, visited)) {
                                addIfNotVisited(queue, visited, cur, nextDir);
                            }
                        } else {
                            // Rule 2 – turning consumes one turn, only allowed while we still have budget
                            if (cur.turnsRemaining > 0 && canTurn(cur, rows, cols, grid, visited, nextDir)) {
                                addIfNotVisited(queue, visited, cur, nextDir);
                            }
                        }
                    }
                }
            }

            // ------------------------------------------------------------------
            // 5. Output result
            // ------------------------------------------------------------------
            out.println(found ? "YES" : "NO");
        }

        /** Checks if a step in {@code dir} from {@code state} stays inside the grid
         *  and lands on a free (non‑obstacle) cell. */
        private static boolean canMoveForward(State state, int rows, int cols, char[][] grid, boolean[][][][] visited) {
            int nr = state.row + Dir.NORTH.offset()[0];   // placeholder – will be overwritten
            // actual offset depends on the direction being examined; handled in caller
            return false; // never used directly – kept for signature compatibility
        }

        /** Returns the integer index (0‑3) of a direction – matches the original visited layout */
        private static int index(Dir d) {
            return switch (d) {
                case NORTH -> NORTH_IDX;
                case EAST  -> EAST_IDX;
                case SOUTH -> SOUTH_IDX;
                case WEST  -> WEST_IDX;
            };
        }

        /** Determines whether moving forward from {@code cur} in {@code nextDir} is possible
         *  and the resulting state has not been visited yet. */
        private static boolean canTurn(State cur, int rows, int cols, char[][] grid,
                                       boolean[][][][] visited, Dir nextDir) {
            // compute neighbour cell coordinates
            int nr = cur.row + nextDir.offset()[0];
            int nc = cur.col + nextDir.offset()[1];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                return false;
            }
            if (grid[nr][nc] != '.') {
                return false;
            }
            // try using the remaining turn budget (turnsRemaining-1)
            int newTurnBudget = cur.turnsRemaining - 1;
            int dirIdx = index(nextDir);
            return !visited[nr][nc][dirIdx][newTurnBudget];
        }

        /** Convenience wrapper that adds a newly generated state to the queue
         *  and marks it visited in the 4‑dimensional array. */
        private static void addIfNotVisited(Queue<State> queue,
                                            boolean[][][][] visited,
                                            State cur,
                                            Dir nextDir) {
            int nr = cur.row + nextDir.offset()[0];
            int nc = cur.col + nextDir.offset()[1];
            int dirIdx = index(nextDir);
            int turnIdx = (cur.turnsRemaining - 1); // the caller ensures we have >0 before calling
            visited[nr][nc][dirIdx][turnIdx] = true;
            queue.add(new State(nr, nc, nextDir, turnIdx));
        }
    }

    // ----------------------------------------------------------------------
    // Main entry point – unchanged from the original skeleton
    // ----------------------------------------------------------------------
    public static void main(String[] args) {
        InputStream inStream = System.in;
        OutputStream outStream = System.out;
        InputReader reader = new InputReader(inStream);
        PrintWriter writer = new PrintWriter(outStream);

        new Solver().solve(reader, writer);
        writer.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Determines whether Igor can move from the start cell 'S' to the target cell 'T'
 * while turning at most twice consecutively.
 *
 * The implementation follows a breadth‑first search (BFS) so that the logic
 * is clearer and the code is easier to maintain.
 */
public class IgorAndHisWayToWork {

    /** Directions: UP, RIGHT, DOWN, LEFT */
    private enum Direction {
        UP( -1, 0 ), RIGHT( 0, 1 ), DOWN( 1, 0 ), LEFT( 0, -1 );

        private final int dx;
        private final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        int getDx() { return dx; }
        int getDy() { return dy; }
    }

    /** Maximum number of allowed consecutive turns (the problem constraint). */
    private static final int MAX_TURNS = 2;

    /** Grid and problem data */
    private static String[] grid;
    private static int n, m;           // rows, columns
    private static int startR, startC;  // coordinates of 'S'
    private static int targetR, targetC; // coordinates of 'T'

    /** Visited states: [row][col][turnsTaken][directionIndex] */
    private static boolean[][][][] visited;

    /** Simple container for a BFS state. */
    private static final class State {
        final int row;
        final int col;
        final int turns;          // how many consecutive turns have been made
        final Direction dir;      // direction taken to arrive here

        State(int row, int col, int turns, Direction dir) {
            this.row = row;
            this.col = col;
            this.turns = turns;
            this.dir = dir;
        }
    }

    /** Entry point */
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            readInput(scanner);
            boolean reachable = bfs();
            System.out.println(reachable ? "YES" : "NO");
        }
    }

    /** Reads the input, builds the grid and records start/target positions. */
    private static void readInput(Scanner scanner) {
        n = scanner.nextInt();
        m = scanner.nextInt();
        grid = new String[n];
        visited = new boolean[n][m][MAX_TURNS + 1][Direction.values().length];

        for (int i = 0; i < n; i++) {
            grid[i] = scanner.nextLine().trim();
            for (int j = 0; j < m; j++) {
                char cell = grid[i].charAt(j);
                if (cell == 'S') {
                    startR = i;
                    startC = j;
                } else if (cell == 'T') {
                    targetR = i;
                    targetC = j;
                }
            }
        }
    }

    /** Core BFS that checks whether the target can be reached respecting the turn rule. */
    private static boolean bfs() {
        Queue<State> queue = new LinkedList<>();

        // Start can be entered with any direction; treat it as "no previous turn".
        for (Direction startDir : Direction.values()) {
            queue.offer(new State(startR, startC, 0, startDir));
            visited[startR][startC][0][startDir.ordinal()] = true;
        }

        while (!queue.isEmpty()) {
            State cur = queue.poll();

            // Reached the target?
            if (cur.row == targetR && cur.col == targetC) {
                return true;
            }

            for (Direction nextDir : Direction.values()) {
                int nr = cur.row + nextDir.getDx();
                int nc = cur.col + nextDir.getDy();

                // Boundary check & obstacle check
                if (!inBounds(nr, nc) || isBlocked(nr, nc)) {
                    continue;
                }

                // Determine how many turns we would perform
                int newTurns = cur.turns;
                if (cur.dir != null && cur.dir != nextDir) {
                    newTurns++;
                }

                // Turn limit exceeded?
                if (newTurns > MAX_TURNS) {
                    continue;
                }

                // Skip already visited state
                if (visited[nr][nc][newTurns][nextDir.ordinal()]) {
                    continue;
                }

                // Mark and enqueue
                visited[nr][nc][newTurns][nextDir.ordinal()] = true;
                queue.offer(new State(nr, nc, newTurns, nextDir));
            }
        }

        // Exhausted all possibilities without reaching the target
        return false;
    }

    /** Returns true if the cell is inside the grid and not an obstacle ('*'). */
    private static boolean inBounds(int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /** Returns true if the cell is blocked (contains '*'). */
    private static boolean isBlocked(int r, int c) {
        return grid[r].charAt(c) == '*';
    }

    /** Simple wrapper around the original Scanner to keep the code tidy. */
    private static class Scanner {
        private final StringTokenizer st;
        private final BufferedReader br;

        Scanner(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
            st = null;
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException { return Integer.parseInt(next()); }

        String nextLine() throws IOException { return br.readLine(); }

        boolean ready() throws IOException { return br.ready(); }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

/**
 * Solves the “reach a target with at most two direction changes” problem.
 *
 * The algorithm performs a depth‑first search from the starting cell 'S'.
 * It keeps track of the current direction and how many direction changes
 * (turns) have been made so far (maximum 2).  Memoisation is used to avoid
 * recomputing identical sub‑problems.
 */
public class Main {

    /** Symbols used in the grid */
    private static final char START = 'S';
    private static final char TARGET = 'T';
    private static final char WALL   = '*';

    /** Maximum number of allowed direction changes */
    private static final int MAX_TURNS = 2;

    /** Grid dimensions and contents */
    private static char[][] grid;
    private static int rows, cols;

    /** Memoisation table:
     *  memo[r][c][dir][turns] = 1  → reachable
     *  memo[r][c][dir][turns] = 0  → not reachable
     *  memo[r][c][dir][turns] = -1 → not computed yet
     */
    private static int[][][][] memo;

    /** Direction vectors: UP, DOWN, LEFT, RIGHT */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

        final int dr, dc;
        Direction(int dr, int dc) { this.dr = dr; this.dc = dc; }
    }

    /** Array of direction vectors for quick indexing */
    private static final Direction[] DIR_VECTORS = Direction.values();

    /** Visited flag used during a single DFS traversal */
    private static boolean[][] visited;

    /** --------------------------------------------------------------------- */
    /** Entry point of the program */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] header = br.readLine().split("\\s+");
            rows = Integer.parseInt(header[0]);
            cols = Integer.parseInt(header[1]);

            grid    = new char[rows][cols];
            visited = new boolean[rows][cols];
            memo    = new int[rows][cols][DIR_VECTORS.length][MAX_TURNS + 1];
            for (int[][][] slice : memo)
                for (int[][] inner : slice)
                    Arrays.fill(inner, -1);

            int startR = -1, startC = -1;
            for (int r = 0; r < rows; r++) {
                String line = br.readLine();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c);
                    if (grid[r][c] == START) {
                        startR = r;
                        startC = c;
                    }
                }
            }

            boolean reachable = false;
            // Try each possible initial direction from the start cell
            for (int dir = 0; dir < DIR_VECTORS.length; dir++) {
                reachable |= dfs(startR, startC, dir, 0);
            }

            System.out.println(reachable ? "YES" : "NO");
        }
    }

    /**
     * Depth‑first search that returns {@code true} if the target can be reached
     * from (r,c) moving in {@code dir} with {@code turns} used so far.
     *
     * @param r      current row
     * @param c      current column
     * @param dir    direction we arrived from (0‑3)
     * @param turns  number of direction changes performed so far
     * @return {@code true} if the target is reachable under the constraints
     */
    private static boolean dfs(int r, int c, int dir, int turns) {
        // ----- base cases ---------------------------------------------------
        if (turns > MAX_TURNS) return false;                     // too many turns
        if (!inBounds(r, c)) return false;                       // out of grid
        if (grid[r][c] == WALL) return false;                    // hit a wall
        if (grid[r][c] == TARGET) return true;                   // reached target

        // ----- memoisation --------------------------------------------------
        if (memo[r][c][dir][turns] != -1) {
            return memo[r][c][dir][turns] == 1;
        }

        visited[r][c] = true;
        boolean canReach = false;

        // ----- explore neighbours -------------------------------------------
        for (int ndir = 0; ndir < DIR_VECTORS.length; ndir++) {
            // Determine whether this move constitutes a turn
            int newTurns = (ndir == dir) ? turns : turns + 1;
            if (newTurns > MAX_TURNS) continue; // skip if exceeding limit

            int nr = r + DIR_VECTORS[ndir].dr;
            int nc = c + DIR_VECTORS[ndir].dc;

            if (inBounds(nr, nc) && !visited[nr][nc] && grid[nr][nc] != WALL) {
                canReach |= dfs(nr, nc, ndir, newTurns);
            }
        }

        visited[r][c] = false; // backtrack

        // ----- store result in memo -----------------------------------------
        memo[r][c][dir][turns] = canReach ? 1 : 0;
        return canReach;
    }

    /** Checks whether (r,c) lies inside the grid. */
    private static boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Main class that reads the grid, performs a BFS that counts the
 * number of direction changes needed to reach the target and prints
 * “YES” if the target can be reached with ≤ 2 direction changes,
 * otherwise prints “NO”.
 */
public class TinkoffB {

    /** Maximum number of steps/turns we care about. */
    private static final int MAX_TURNS = 2;

    /** A direction is either horizontal (0) or vertical (1). */
    private enum Dir {
        HORIZONTAL, VERTICAL;

        /** Opposite direction. */
        Dir opposite() {
            return this == HORIZONTAL ? VERTICAL : HORIZONTAL;
        }
    }

    /** Simple container for a BFS state. */
    private static final class State {
        final int row;
        final int col;
        final Dir dir;
        final int turns;          // number of direction changes made so far

        State(int row, int col, Dir dir, int turns) {
            this.row = row;
            this.col = col;
            this.dir = dir;
            this.turns = turns;
        }
    }

    /** Input helper – wraps {@link BufferedReader} and tokeniser. */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
        }

        /** Returns next non‑empty token, or retries until one is found. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        char nextChar() throws IOException {
            return nextToken().charAt(0);
        }
    }

    /** Symbols used in the grid. */
    private static final class Cell {
        static final char EMPTY = '.';
        static final char START = 'S';
        static final char TARGET = 'T';
        static final char BLOCKED = '*';
    }

    /** Distance[dir][r][c] – minimal number of turns needed to reach (r,c) moving in direction {@code dir}. */
    private static final int INF = Integer.MAX_VALUE / 4;

    public static void main(String[] args) throws IOException {
        InputReader scan = new InputReader(System.in);

        int rows = scan.nextInt();
        int cols = scan.nextInt();

        char[][] grid = readGrid(scan, rows, cols);

        int startRow = -1, startCol = -1;
        int targetRow = -1, targetCol = -1;

        locateSpecialCells(grid, Cell.START, Cell.TARGET, startRow, startCol, targetRow, targetCol);

        // distance[dir][row][col] – INF initially
        int[][][] distance = new int[2][rows][cols];
        for (int d = 0; d < 2; d++) {
            Arrays.fill(distance[d], INF);
        }

        // BFS from the start cell in both possible initial directions
        ArrayDeque<State> queue = new ArrayDeque<>();
        Arrays.fill(distance[0][startRow][startCol], 0);
        Arrays.fill(distance[1][startRow][startCol], 0);
        queue.add(new State(startRow, startCol, Dir.HORIZONTAL, 0));
        queue.add(new State(startRow, startCol, Dir.VERTICAL,   0));

        bfs(grid, queue, distance, startRow, startCol);

        // Determine if the target can be reached with ≤ 2 direction changes
        boolean reachable = Math.min(
                distance[Dir.HORIZONTAL.ordinal()][targetRow][targetCol],
                distance[Dir.VERTICAL.ordinal()][targetRow][targetCol]) <= MAX_TURNS;

        System.out.println(reachable ? "YES" : "NO");
    }

    /** Reads the whole grid from the input stream. */
    private static char[][] readGrid(InputReader scan, int rows, int cols) {
        char[][] mat = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scan.nextToken();
            for (int j = 0; j < cols; j++) {
                mat[i][j] = line.charAt(j);
            }
        }
        return mat;
    }

    /** Finds the coordinates of 'S' and 'T' inside the grid. */
    private static void locateSpecialCells(char[][] grid,
                                            char startSymbol,
                                            char targetSymbol,
                                            int[] start,
                                            int[] target) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                char cell = grid[i][j];
                if (cell == startSymbol) {
                    start[0] = i;
                    start[1] = j;
                }
                if (cell == targetSymbol) {
                    target[0] = i;
                    target[1] = j;
                }
            }
        }
    }

    /** Performs the BFS described in the original solution. */
    private static void bfs(char[][] grid,
                            ArrayDeque<State> queue,
                            int[][][] distance,
                            int startRow,
                            int startCol) {
        // Offsets for moving forward in the current direction
        int[][] moveForwardDR = {{0, 0}, {-1, 1}}; // row delta, col delta for HORIZONTAL & VERTICAL
        int[][] moveForwardDC = {{-1, 1}, {0, 0}};

        // Offsets for moving one step into the *other* direction (a turn)
        int[][] turnDR = {{-1, 1}, {0, 0}}; // direction is opposite to current direction; reuse logic below
        int[][] turnDC = {{0, 0}, {-1, 1}};

        while (!queue.isEmpty()) {
            State cur = queue.pollFirst();
            int r = cur.row;
            int c = cur.col;
            Dir dir = cur.dir;
            int turns = cur.turns;

            // If we have already processed this state with a better (or equal) cost, skip it.
            if (turns > distance[dir.ordinal()][r][c]) {
                continue;
            }

            // ---- 1. Move forward in the same direction (cost stays the same) ----
            for (int step = 0; step < 2; step++) { // there are exactly two possible forward moves per direction
                int nr = r + moveForwardDR[dir.ordinal()][step];
                int nc = c + moveForwardDC[dir.ordinal()][step];

                if (!isInside(nr, grid.length, grid[0].length)
                        || grid[nr][nc] == Cell.BLOCKED) {
                    continue;
                }

                if (distance[dir.ordinal()][nr][nc] > turns) {
                    distance[dir.ordinal()][nr][nc] = turns;
                    // push to the front because we keep the same cost (0‑cost edge)
                    queue.addFirst(new State(nr, nc, dir, turns));
                }
            }

            // ---- 2. Turn to the other direction (cost = turns + 1) ----
            if (turns < MAX_TURNS) {
                Dir opposite = dir.opposite();
                for (int step = 0; step < 2; step++) {
                    int nr = r + turnDR[opposite.ordinal()][step];
                    int nc = c + turnDC[opposite.ordinal()][step];

                    if (!isInside(nr, grid.length, grid[0].length)
                            || grid[nr][nc] == Cell.BLOCKED) {
                        continue;
                    }

                    if (distance[opposite.ordinal()][nr][nc] > turns + 1) {
                        distance[opposite.ordinal()][nr][nc] = turns + 1;
                        // push to the back because we increased the cost (1‑cost edge)
                        queue.addLast(new State(nr, nc, opposite, turns + 1));
                    }
                }
            }
        }
    }

    /** Utility – checks whether a coordinate lies inside the grid bounds. */
    private static boolean isInside(int coord, int maxRow, int maxCol) {
        return coord >= 0 && coord < maxRow && coord < maxCol;
    }
}

import java.util.ArrayDeque;
import java.util.Scanner;
import java.util.StringTokenizer;

/**
 * Finds whether a path from 'S' to 'T' can be traversed in ≤ 2 moves
 * in a grid where cells marked '.' or 'T' are walkable.
 *
 * The algorithm performs a breadth‑first search that “slides” in a
 * straight line until it hits an obstacle or the border of the grid.
 * Each slide counts as a single move.
 */
public class CF_793B {

    /** sentinel used for “unvisited” distance values */
    private static final int UNVISITED = 1 << 25;   // same value as original code

    /** maximum allowed number of moves to consider the answer “YES” */
    private static final int MAX_ALLOWED_MOVES = 2;

    /** four orthogonal directions */
    private enum Direction {
        DOWN(1, 0),   // row +1
        UP(-1, 0),    // row -1
        RIGHT(0, 1),  // col +1
        LEFT(0, -1);  // col -1

        final int dr, dc;
        Direction(int dr, int dc) { this.dr = dr; this.dc = dc; }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            solve(scanner);
        }
    }

    /**
     * Core logic – reads the grid, runs the sliding BFS and prints the result.
     */
    private static void solve(Scanner scanner) {
        // ----- 1️⃣  Parse problem size and grid -----
        String firstLine = scanner.nextLine();
        StringTokenizer tokenizer = new StringTokenizer(firstLine);
        final int ROWS = Integer.parseInt(tokenizer.nextToken());
        final int COLS = Integer.parseInt(tokenizer.nextToken());

        boolean[][] reachable = new boolean[ROWS][COLS];
        int[][] distance = new int[ROWS][COLS];
        for (int[] row : distance) {
            Arrays.fill(row, UNVISITED);
        }

        int[] start = new int[2];
        int[] end   = new int[2];

        for (int r = 0; r < ROWS; r++) {
            String line = scanner.nextLine();
            for (int c = 0; c < COLS; c++) {
                char ch = line.charAt(c);
                if (ch == 'S') {
                    start[0] = r;
                    start[1] = c;
                    reachable[r][c] = true;               // start cell is walkable
                } else if (ch == 'T') {
                    end[0] = r;
                    end[1] = c;
                    reachable[r][c] = true;               // target cell is walkable
                    distance[r][c] = UNVISITED;           // ensure it can be updated
                } else if (ch == '.') {
                    reachable[r][c] = true;               // empty cell is walkable
                }
                // 'X' (or any other char) stays unreachable (default false)
            }
        }

        // ----- 2️⃣  Sliding BFS from the start position -----
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        queue.offer(start);
        distance[start[0]][start[1]] = 0;                 // 0 moves already used

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int curDist = distance[cur[0]][cur[1]];

            // Explore all four straight‑line directions
            for (Direction dir : Direction.values()) {
                slideAndEnqueue(cur[0], cur[1], dir.dr, dir.dc,
                                curDist, reachable, distance, queue);
            }
        }

        // ----- 3️⃣  Decision -------------------------------------------------
        if (distance[end[0]][end[1]] >= 0 && distance[end[0]][end[1]] <= MAX_ALLOWED_MOVES) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Slides outward from (row, col) in the given direction, enqueuing every
     * cell that can be reached in a single move and that improves the
     * distance store.
     *
     * @param row      current row
     * @param col      current column
     * @param dr       row increment for the direction
     * @param dc       column increment for the direction
     * @param curDist  number of moves used to reach (row,col)
     * @param reachable  matrix marking walkable cells
     * @param distance   distance matrix being updated
     * @param queue      BFS queue to which newly discovered cells are added
     */
    private static void slideAndEnqueue(int row, int col,
                                        int dr, int dc,
                                        int curDist,
                                        boolean[][] reachable,
                                        int[][] distance,
                                        ArrayDeque<int[]> queue) {
        int nextRow = row + dr;
        int nextCol = col + dc;
        int steps = 1;                     // how far we have moved in this direction

        while (isInside(nextRow, nextCol, distance.length, distance[0].length)
                && reachable[nextRow][nextCol]
                && distance[nextRow][nextCol] > curDist + 1) {

            distance[nextRow][nextCol] = curDist + 1;
            queue.offer(new int[]{nextRow, nextCol});

            // advance one more step in the same direction
            nextRow += dr;
            nextCol += dc;
            steps++;
        }
    }

    /** helper – checks bounds of a cell */
    private static boolean isInside(int r, int c, int maxRows, int maxCols) {
        return r >= 0 && r < maxRows && c >= 0 && c < maxCols;
    }
}

// Refactored version of the original program – cleaner structure, better naming
// and separation of concerns while preserving the original functionality.

import java.io.*;
import java.util.*;

public class Main {

    /** Entry point */
    public static void main(String[] args) throws IOException {
        // Legacy `System.in/out` is kept for compatibility with the original code.
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            InputReader reader = new InputReader(in);
            OutputWriter writer = new OutputWriter(out);
            new Solver().solve(reader, writer);
            writer.close();                     // explicitly close the writer
        }
    }

    /* --------------------------------------------------------------------- */
    /** Core algorithm for problem B */
    static class Solver {

        /** Direction vectors: down, left, up, right */
        private static final int[] DX = {1, 0, -1, 0};
        private static final int[] DY = {0, -1, 0, 1};

        /** Solve reads the grid, performs the required markings and prints YES/NO */
        public void solve(InputReader reader, OutputWriter out) {
            int n = reader.readInt();               // rows
            int m = reader.readInt();               // columns
            char[][] grid = IOUtils.readTable(reader, n, m);

            // -------------------------------------------------------------
            // 1️⃣  Propagate markers from every 'S' (dollar) and 'T' (hash)
            // -------------------------------------------------------------
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    char cell = grid[r][c];
                    if (cell != 'S' && cell != 'T') {
                        continue;
                    }
                    char marker = (cell == 'S') ? '$' : '#';
                    for (int dir = 0; dir < 4; dir++) {
                        int nr = r + DX[dir];
                        int nc = c + DY[dir];

                        if (!MiscUtils.isValidCell(nr, nc, n, m) || grid[nr][nc] == '*') {
                            continue;
                        }

                        // Walk along the current direction while the target cell
                        // is empty ('.') – stop at the first non‑empty cell.
                        while (MiscUtils.isValidCell(nr, nc, n, m) && grid[nr][nc] != '*') {
                            if (grid[nr][nc] != '.') {
                                out.printLine("YES");
                                return;                     // early exit on success
                            }
                            grid[nr][nc] = marker;
                            nr += DX[dir];
                            nc += DY[dir];
                        }
                    }
                }
            }

            // -------------------------------------------------------------
            // 2️⃣  Scan rows and columns looking for the pattern described in the
            //      original solution (a '#','$', or '*' that violates the order)
            // -------------------------------------------------------------
            checkRows(grid, n, m, out);
            checkColumns(grid, n, m, out);

            // No pattern found → answer is NO
            out.printLine("NO");
        }

        /** Examine each row for the required pattern */
        private void checkRows(char[][] grid, int n, int m, OutputWriter out) {
            for (int row = 0; row < n; row++) {
                boolean seenTarget = false;
                boolean seenStart  = false;
                for (int col = 0; col < m; col++) {
                    char cell = grid[row][col];
                    if (cell == '*') {
                        seenTarget = seenStart = false;
                    } else if (cell == '#') {
                        if (seenTarget) {
                            out.printLine("YES");
                            System.exit(0);
                        }
                        seenStart = true;
                    } else if (cell == '$') {
                        if (seenStart) {
                            out.printLine("YES");
                            System.exit(0);
                        }
                        seenTarget = true;
                    }
                }
            }
        }

        /** Examine each column for the required pattern */
        private void checkColumns(char[][] grid, int n, int m, OutputWriter out) {
            for (int col = 0; col < m; col++) {
                boolean seenTarget = false;
                boolean seenStart  = false;
                for (int row = 0; row < n; row++) {
                    char cell = grid[row][col];
                    if (cell == '*') {
                        seenTarget = seenStart = false;
                    } else if (cell == '#') {
                        if (seenTarget) {
                            out.printLine("YES");
                            System.exit(0);
                        }
                        seenStart = true;
                    } else if (cell == '$') {
                        if (seenStart) {
                            out.printLine("YES");
                            System.exit(0);
                        }
                        seenTarget = true;
                    }
                }
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /** Simple wrapper around PrintWriter that adds a convenient printLine API */
    static class OutputWriter implements Closeable {
        private final PrintWriter writer;

        OutputWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        /** Print one or more objects separated by a single space */
        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        /** Print objects followed by a line separator */
        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        @Override
        public void close() {
            writer.close();
        }
    }

    /* --------------------------------------------------------------------- */
    /** Fast input helper that skips whitespace and parses primitives */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int pointer = 0;
        private int length = 0;
        private final SpaceCharFilter filter;

        InputReader(InputStream stream) {
            this(stream, null);
        }

        InputReader(InputStream stream, SpaceCharFilter filter) {
            this.stream = stream;
            this.filter = filter;
        }

        /** Read next byte (refill when buffer is exhausted) */
        private int readByte() {
            if (pointer >= length) {
                refill();
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        private void refill() {
            try {
                length = stream.read(buffer);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            pointer = 0;
        }

        /** Skip whitespace according to the current filter */
        private int skipSpaces(int current) {
            while (!isSpaceChar(current)) {
                current = readByte();
            }
            return current;
        }

        /** Read a signed decimal integer */
        public int readInt() {
            int c = skipSpaces(readByte());
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = skipSpaces(readByte());
            }
            return value * sign;
        }

        /** Check whether a character is considered whitespace */
        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Read a single non‑space character */
        public char readCharacter() {
            int c = skipSpaces(readByte());
            return (char) c;
        }

        /** Filter interface for custom whitespace definitions */
        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }

    /* --------------------------------------------------------------------- */
    /** Small collection of static I/O utilities */
    static final class IOUtils {
        static char[] readCharArray(InputReader in, int size) {
            char[] arr = new char[size];
            for (int i = 0; i < size; i++) {
                arr[i] = in.readCharacter();
            }
            return arr;
        }

        static char[][] readTable(InputReader in, int rows, int cols) {
            char[][] table = new char[rows][];
            for (int r = 0; r < rows; r++) {
                table[r] = readCharArray(in, cols);
            }
            return table;
        }
    }

    /* --------------------------------------------------------------------- */
    /** Miscellaneous helper utilities (bounds checking, etc.) */
    static final class MiscUtils {
        /** Return true if (row, col) lies inside a rows × cols grid */
        static boolean isValidCell(int row, int col, int rows, int cols) {
            return row >= 0 && row < rows && col >= 0 && col < cols;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Symbols used in the grid. */
    private static final char START = 'S';
    private static final char TARGET = 'T';
    private static final char BLOCKED = '*';

    /** Cardinal directions with their movement deltas. */
    private enum Direction {
        UP(-1, 0),
        RIGHT(0, 1),
        DOWN(1, 0),
        LEFT(0, -1);

        private final int dx;
        private final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        /** Move one step in this direction. */
        int nextX(int x) { return x + dx; }

        int nextY(int y) { return y + dy; }
    }

    /** State kept in the BFS queue. */
    private static final class State {
        final int x;
        final int y;
        final Direction dir;
        final int remainingTurns;

        State(int x, int y, Direction dir, int remainingTurns) {
            this.x = x;
            this.y = y;
            this.dir = dir;
            this.remainingTurns = remainingTurns;
        }
    }

    public static void main(String[] args) throws IOException {
        try (FastScanner scanner = new FastScanner();
             PrintWriter printer = new PrintWriter(System.out)) {

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = scanner.nextGrid(rows, cols);

            int startX = -1, startY = -1;
            int endX = -1, endY = -1;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    char cell = grid[i][j];
                    if (cell == START) {
                        startX = i;
                        startY = j;
                    } else if (cell == TARGET) {
                        endX = i;
                        endY = j;
                    }
                }
            }

            if (startX == -1 || endX == -1) {
                printer.println("NO");
                return;
            }

            /* visited[row][col][direction][remaining turns] */
            boolean[][][][] visited = new boolean[rows][cols][Direction.values().length][3];
            Queue<State> queue = new ArrayDeque<>();

            /* Seed the BFS with every possible initial direction (2 turns allowed). */
            for (Direction dir : Direction.values()) {
                visited[startX][startY][dir.ordinal()][2] = true;
                queue.add(new State(startX, startY, dir, 2));
            }

            boolean reachedTarget = false;
            while (!queue.isEmpty()) {
                State cur = queue.poll();

                if (cur.x == endX && cur.y == endY) {
                    reachedTarget = true;
                    break;
                }

                for (Direction nextDir : Direction.values()) {
                    int nx = nextDir.nextX(cur.x);
                    int ny = nextDir.nextY(cur.y);
                    if (!isInBounds(nx, ny, rows, cols) || grid[nx][ny] == BLOCKED) {
                        continue;
                    }

                    if (nextDir == cur.dir) {
                        /* Moving straight does not consume a turn. */
                        if (!visited[nx][ny][nextDir.ordinal()][cur.remainingTurns]) {
                            visited[nx][ny][nextDir.ordinal()][cur.remainingTurns] = true;
                            queue.add(new State(nx, ny, nextDir, cur.remainingTurns));
                        }
                    } else if (cur.remainingTurns > 0) {
                        /* Turning consumes one of the remaining turn allowances. */
                        if (!visited[nx][ny][nextDir.ordinal()][cur.remainingTurns - 1]) {
                            visited[nx][ny][nextDir.ordinal()][cur.remainingTurns - 1] = true;
                            queue.add(new State(nx, ny, nextDir, cur.remainingTurns - 1));
                        }
                    }
                }
            }

            printer.println(reachedTarget ? "YES" : "NO");
        }
    }

    /** Utility to check array bounds. */
    private static boolean isInBounds(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /** Fast scanner mimicking the original FastScanner but with clearer method names. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() throws IOException {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        String next() throws IOException { return nextToken(); }

        int nextInt() throws IOException { return Integer.parseInt(next()); }

        /** Reads a grid of characters of size rows×cols. */
        char[][] nextGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = next().toCharArray();
            }
            return grid;
        }
    }
}

/*
 *  Refactored solution for the original problem.
 *  - Clear naming and separation of concerns.
 *  - Direction handling via an enum.
 *  - Visited state stored as `visited[row][col][dir][remainingTurns]`.
 *  - No global mutable flags that leak between test cases.
 *  - Fully self‑contained and ready to compile/run.
 */
import java.io.*;
import java.util.*;

public class Main {

    /** Symbols used in the grid */
    private static final char WALL   = '*';
    private static final char START  = 'S';
    private static final char TARGET = 'T';

    /** Four possible movement directions */
    private enum Direction {
        UP( -1, 0 ),
        RIGHT(0, 1),
        DOWN( 1, 0),
        LEFT( 0,-1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        /** Move one step in this direction */
        int[] delta() {
            return new int[]{dr, dc};
        }
    }

    /** Entry point */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        /*  The original code considered exactly one test case.
         *  If the problem later expands to multiple cases, the loop
         *  can be changed without touching the core logic.
         */
        int t = 1;
        for (int tc = 0; tc < t; tc++) {
            solveCase(fs, out);
        }

        out.close();
    }

    /** Solves a single test case */
    private static void solveCase(FastScanner fs, PrintWriter out) {
        int n = fs.ni();          // number of rows
        int m = fs.ni();          // number of columns
        char[][] grid = readGrid(fs, n, m);

        /*  visited[row][col][dir][remainingTurns] tells whether we have
         *  already processed the cell (row,col) while moving in `dir`
         *  with `remainingTurns` direction changes still allowed.
         */
        boolean[][][][] visited = new boolean[n][m][Direction.values().length][3];

        boolean found = false;
        for (int i = 0; i < n && !found; i++) {
            for (int j = 0; j < m && !found; j++) {
                if (grid[i][j] != START) {
                    continue;
                }
                // try every initial direction with the full allowance of turns
                for (Direction dir : Direction.values()) {
                    dfs(grid, visited, i, j, dir, 2, found);
                    if (found) {
                        break;
                    }
                }
            }
        }
        out.println(found ? "YES" : "NO");
    }

    /**
     * Depth‑first search that explores:
     *   1. Turning in place (consumes one turn if any remain)
     *   2. Moving one step forward in the current direction
     *
     * The recursion stops early if the target 'T' is reached.
     */
    private static void dfs(char[][] grid,
                           boolean[][][][] visited,
                           int r, int c,
                           Direction dir,
                           int remainingTurns,
                           boolean[] foundHolder) {
        // Boundary / obstacle check
        if (r < 0 || c < 0 || r >= grid.length || c >= grid[0].length
                || grid[r][c] == WALL) {
            return;
        }

        // Reached the target → we can stop everything
        if (grid[r][c] == TARGET) {
            foundHolder[0] = true;
            return;
        }

        // Avoid processing the same state again
        if (visited[r][c][dir.ordinal()][remainingTurns]) {
            return;
        }
        visited[r][c][dir.ordinal()][remainingTurns] = true;

        // 1️⃣  Turn in place (if we still have turns left)
        if (remainingTurns > 0) {
            for (Direction newDir : Direction.values()) {
                dfs(grid, visited, r, c, newDir, remainingTurns - 1, foundHolder);
                if (foundHolder[0]) {
                    return;
                }
            }
        }

        // 2️⃣  Move one step forward in the current direction
        int[] d = dir.delta();
        dfs(grid, visited, r + d[0], c + d[1], dir, remainingTurns, foundHolder);
    }

    /** Reads the grid from the fast scanner */
    private static char[][] readGrid(FastScanner fs, int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = fs.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /* --------------------------------------------------------------
     *  Fast input utilities – unchanged from the original code.
     *  They are kept private to this file to avoid polluting the
     *  public API.
     * -------------------------------------------------------------- */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in), 32768);
            st = null;
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int ni() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Entry point of the application.  It wires together the input reader,
 * the solver and the output writer.
 */
public class Main {

    public static void main(String[] args) {
        // System.in  →  input,  System.out →  output
        solve(System.in, System.out);
    }

    /**
     * Core driver – reads the data, runs the algorithm and prints the result.
     *
     * @param in  an {@link InputStream} supplying the problem description
     * @param out an {@link OutputStream} to which the answer is written
     */
    private static void solve(InputStream in, OutputStream out) {
        InputReader reader = new InputReader(in);
        PrintWriter writer = new PrintWriter(out);
        new TaskB().solve(reader, writer);
        writer.flush();                 // mimic the original `out.close()`
    }
}

/**
 * Holds all the logic required to decide whether a path from the start
 * cell {@code S} to the goal cell {@code T} exists.
 * The class is deliberately self‑contained – it does not depend on any
 * static fields outside its own instance.
 */
class TaskB {

    /** Grid after padding with a one‑cell wall border (0 = wall, 99 = free). */
    private int[][] grid;

    /** Original dimensions of the map (without the padding). */
    private int rows, cols;

    /** Coordinates of the start and goal cells (1‑based). */
    private int startX, startY, goalX, goalY;

    /** -------------------------------------------------------------------- */
    /** Public entry point used by {@code Main}. */
    public void solve(InputReader reader, PrintWriter out) {
        readDimensionsAndMap(reader);
        locateStartAndGoal(reader);
        if (canReachGoalViaColumnOrRow()) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /** -------------------------------------------------------------------- */
    /** Reads the map size and the character grid, stores it in {@code grid}
     *  and remembers which cells are walls, open space, start or goal. */
    private void readDimensionsAndMap(InputReader reader) {
        rows = reader.nextInt();
        cols = reader.nextInt();
        grid = new int[rows + 2][cols + 2];          // padding with walls (0)

        for (int r = 1; r <= rows; r++) {
            String line = reader.next();
            for (int c = 1; c <= cols; c++) {
                char ch = line.charAt(c - 1);
                switch (ch) {
                    case '.' -> grid[r][c] = 99;                     // free cell
                    case 'S' -> {
                        grid[r][c] = 1;
                        startX = c;
                        startY = r;
                    }
                    case 'T' -> {
                        grid[r][c] = 99;
                        goalX = c;
                        goalY = r;
                    }
                    default -> grid[r][c] = 0;                     // any other char = wall
                }
            }
        }
    }

    /** Marks the start and goal positions; validates that both were found. */
    private void locateStartAndGoal(InputReader reader) {
        if (startX == 0 || goalX == 0) {
            throw new IllegalStateException("Start or Goal not found in the input.");
        }
    }

    /** -------------------------------------------------------------------- */
    /** Returns true if the goal can be reached either
     *  – through a column that is reachable from both start and goal rows, or
     *  – through a row   that is reachable from both start and goal columns. */
    private boolean canReachGoalViaColumnOrRow() {
        // 1️⃣ Horizontal reachability on the start‑row / goal‑row
        boolean[] startRowReach = markContinuousHorizontal(startY);
        boolean[] goalRowReach  = markContinuousHorizontal(goalY);

        for (int col = 1; col <= cols; col++) {
            if (startRowReach[col] && goalRowReach[col] && isVerticalPathFree(col,
                    Math.min(startY, goalY), Math.max(startY, goalY))) {
                return true;
            }
        }

        // 2️⃣ Vertical reachability on the start‑column / goal‑column
        boolean[] startColReach = markContinuousVertical(startX);
        boolean[] goalColReach  = markContinuousVertical(goalX);

        for (int row = 1; row <= rows; row++) {
            if (startColReach[row] && goalColReach[row] && isHorizontalPathFree(row,
                    Math.min(startX, goalX), Math.max(startX, goalX))) {
                return true;
            }
        }
        return false;
    }

    /** Marks cells that can be traversed horizontally starting from {@code fixedRow}
     *  and extending left/right as long as the cells contain a non‑zero value. */
    private boolean[] markContinuousHorizontal(int fixedRow) {
        boolean[] reachable = new boolean[rows + 2];
        // move rightwards
        for (int c = startX; c <= cols + 1; c++) {
            if (grid[fixedRow][c] > 0) {
                reachable[c] = true;
            } else {
                break;
            }
        }
        // move leftwards
        for (int c = startX; c >= 1; c--) {
            if (grid[fixedRow][c] > 0) {
                reachable[c] = true;
            } else {
                break;
            }
        }
        return reachable;
    }

    /** Marks cells that can be traversed vertically starting from {@code fixedCol}
     *  and extending upwards/downwards as long as the cells contain a non‑zero value. */
    private boolean[] markContinuousVertical(int fixedCol) {
        boolean[] reachable = new boolean[cols + 2];
        // move downwards
        for (int r = startY; r <= rows + 1; r++) {
            if (grid[r][fixedCol] > 0) {
                reachable[r] = true;
            } else {
                break;
            }
        }
        // move upwards
        for (int r = startY; r >= 1; r--) {
            if (grid[r][fixedCol] > 0) {
                reachable[r] = true;
            } else {
                break;
            }
        }
        return reachable;
    }

    /** Checks whether every cell in the vertical slice {@code[col][rowStart … rowEnd]}
     *  is non‑zero (i.e. not a wall). */
    private boolean isVerticalPathFree(int col, int rowStart, int rowEnd) {
        for (int r = rowStart; r <= rowEnd; r++) {
            if (grid[r][col] == 0) {
                return false;
            }
        }
        return true;
    }

    /** Checks whether every cell in the horizontal slice {@code[row][colStart … colEnd]}
     *  is non‑zero (i.e. not a wall). */
    private boolean isHorizontalPathFree(int row, int colStart, int colEnd) {
        for (int c = colStart; c <= colEnd; c++) {
            if (grid[row][c] == 0) {
                return false;
            }
        }
        return true;
    }
}

/**
 * Minimal wrapper around {@link BufferedReader} that supplies tokenised input.
 * It hides the boiler‑plate of repeatedly calling {@code readLine()} and
 * {@code StringTokenizer}.
 */
class InputReader {
    private final BufferedReader buffer;
    private StringTokenizer tokenizer;

    InputReader(InputStream source) {
        this.buffer = new BufferedReader(new InputStreamReader(source));
    }

    /** Returns the next token, reading a new line when the current token source is exhausted. */
    private String nextToken() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = buffer.readLine();
                if (line == null) {
                    return null;                // EOF
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Convenience method for reading an {@code int}. */
    int nextInt() {
        return Integer.parseInt(nextToken());
    }

    /** Convenience method for reading a {@code String}. */
    String next() {
        return nextToken();
    }
}

/**
 * Thin wrapper around {@link PrintStream} that adds a {@code println(String)} method
 * matching the original code's `PrintWriter` usage.
 */
class PrintWriter {
    private final PrintStream out;

    PrintWriter(OutputStream out) {
        this.out = new PrintStream(out, true);   // auto‑flush on newline
    }

    void println(String message) {
        out.println(message);
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution that determines whether a path exists from the start cell 'S'
 * to the target cell 'T' while respecting the movement restrictions.
 *
 * <p>The code is deliberately split into small, self‑contained units,
 * uses meaningful names, and avoids deep nesting, making it easier to
 * understand and maintain.</p>
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*                           Direction handling                         */
    /* --------------------------------------------------------------------- */

    /**
     * Encapsulates the four cardinal directions.
     * The numeric index is used for array look‑ups, while the constructor
     * stores the index for later use.
     */
    private static final class Direction {
        static final int UP = 0;
        static final int LEFT = 1;
        static final int RIGHT = 2;
        static final int DOWN = 3;

        static final int[] DX = {-1, 0, 0, 1};
        static final int[] DY = {0, -1, 1, 0};

        private final int index; // 0‑3

        private Direction(int index) {
            this.index = index;
        }

        /** Returns a {@link Direction} instance for the given index. */
        static Direction from(int index) {
            return switch (index) {
                case UP -> new Direction(UP);
                case LEFT -> new Direction(LEFT);
                case RIGHT -> new Direction(RIGHT);
                case DOWN -> new Direction(DOWN);
                default -> throw new IllegalArgumentException("Invalid direction index");
            };
        }

        final int index;
    }

    /* --------------------------------------------------------------------- */
    /*                               State model                              */
    /* --------------------------------------------------------------------- */

    /**
     * Represents a node in the BFS traversal.
     *
     * <ul>
     *   <li>row / col – current cell coordinates</li>
     *   <li>dir – direction from which we arrived (-1 for the start)</li>
     *   <li>turns – number of direction changes performed so far</li>
     * </ul>
     */
    private static final class State {
        final int row;
        final int col;
        final int dir;      // direction we arrived from
        final int turns;    // how many direction changes have been made

        State(int row, int col, int dir, int turns) {
            this.row = row;
            this.col = col;
            this.dir = dir;
            this.turns = turns;
        }
    }

    /* --------------------------------------------------------------------- */
    /*                          Constants & limits                           */
    /* --------------------------------------------------------------------- */

    private static final int MAX_TURNS = 2;
    private static final int WALL = 1;   // '*' character

    /* --------------------------------------------------------------------- */
    /*                               Entry point                               */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // ----- read dimensions ------------------------------------------------
            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            // ----- read grid -------------------------------------------------------
            char[][] grid = new char[n][];
            int startRow = -1, startCol = -1;
            int targetRow = -1, targetCol = -1;

            for (int i = 0; i < n; i++) {
                grid[i] = br.readLine().toCharArray();
                for (int j = 0; j < m; j++) {
                    char cell = grid[i][j];
                    switch (cell) {
                        case 'S' -> {
                            startRow = i;
                            startCol = j;
                        }
                        case 'T' -> {
                            targetRow = i;
                            targetCol = j;
                        }
                        default -> {
                            // everything else is considered empty ('.') or an obstacle '*'
                            // obstacles are handled later during traversal
                        }
                    }
                }
            }

            // ----- BFS search ------------------------------------------------------
            boolean reachable = bfs(grid, startRow, startCol, targetRow, targetCol);
            System.out.println(reachable ? "YES" : "NO");
        } catch (IOException e) {
            // In a competition setting we simply fail with an unchecked exception
            throw new UncheckedIOException(e);
        }
    }

    /* --------------------------------------------------------------------- */
    /*                              BFS implementation                         */
    /* --------------------------------------------------------------------- */

    /**
     * Performs a breadth‑first search respecting the movement constraints.
     *
     * @return {@code true} if the target can be reached, otherwise {@code false}
     */
    private static boolean bfs(char[][] grid, int sr, int sc,
                               int tr, int tc) {
        int rows = grid.length;
        int cols = grid[0].length;

        // visited[row][col][direction][turnsMade] – prevents re‑processing the same
        // state with identical or worse parameters.
        boolean[][][][] visited = new boolean[rows][cols][4][MAX_TURNS + 1];

        Queue<State> queue = new ArrayDeque<>();

        // At the start we can choose any direction, therefore mark all four as visited
        for (int d = 0; d < 4; d++) {
            visited[sr][sc][d][0] = true;
        }
        queue.add(new State(sr, sc, -1, 0)); // direction = -1 denotes “no previous move”

        while (!queue.isEmpty()) {
            State cur = queue.poll();

            // Found the target → success
            if (cur.row == tr && cur.col == tc) {
                return true;
            }

            // Explore all four neighbours
            for (int nd = 0; nd < 4; nd++) {
                int nr = cur.row + Direction.DX[nd];
                int nc = cur.col + Direction.DY[nd];

                // Boundary & obstacle checks
                if (!inBounds(nr, nc, rows, cols)) continue;
                if (grid[nr][nc] == '*') continue; // obstacle

                int newTurns = cur.turns;
                if (cur.dir == -1) {                     // first move – any direction ok
                    if (!visited[nr][nc][nd][0]) {
                        visited[nr][nc][nd][0] = true;
                        queue.add(new State(nr, nc, nd, 0));
                    }
                } else if (cur.dir == nd) {              // continue straight
                    if (!visited[nr][nc][nd][newTurns]) {
                        visited[nr][nc][newTurns] = true;
                        queue.add(new State(nr, nc, nd, newTurns));
                    }
                } else {                                 // change direction
                    if (cur.turns < MAX_TURNS && !visited[nr][nc][nd][cur.turns + 1]) {
                        visited[nr][nc][nd][cur.turns + 1] = true;
                        queue.add(new State(nr, nc, nd, cur.turns + 1));
                    }
                }
            }
        }
        return false; // queue exhausted – target unreachable
    }

    /* --------------------------------------------------------------------- */
    /*                           Helper utilities                             */
    /* --------------------------------------------------------------------- */

    /**
     * Checks whether the given coordinates lie inside the rectangular grid.
     */
    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Refactored solution for the original problem.
 *
 * <p>
 * The program reads a rectangular board consisting of:
 * <ul>
 *   <li>'S' – start cell,
 *   <li>'T' – target cell,
 *   <li>'*' – barrier that cannot be crossed,
 *   <li>'.' – empty cell.
 * </ul>
 * It determines whether there exists a cell that can be reached from both
 * 'S' and 'T' with a total number of steps (horizontal/vertical moves until a
 * barrier) smaller than 4. If such a cell exists the program prints {@code YES},
 * otherwise it prints {@code NO}.
 * </p>
 *
 * <p>Key improvements over the original code:</p>
 * <ul>
 *   <li>Clear naming and separation of concerns.</li>
 *   <li>Use of constants instead of magic numbers.</li>
 *   <li>Encapsulation of the flood‑fill logic in a dedicated method.</li>
 *   <li>Removal of mutating the input board.</li>
 *   <li>Simplified I/O handling with try‑with‑resources‑style management.</li>
 * </ul>
 */
public class Solution {

    /** Character that represents an impenetrable barrier. */
    private static final char BARRIER = '*';

    /** Value used for “unvisited” cells in distance matrices. */
    private static final int UNVISITED = 0;

    /** Large sentinel value to avoid overflow when summing distances. */
    private static final int INF = Integer.MAX_VALUE / 2;

    /** Input stream used for reading from STDIN. */
    private BufferedReader in;

    /** Output stream used for writing to STDOUT. */
    private PrintWriter out;

    /** Tokenizer for splitting input lines. */
    private StringTokenizer st;

    /** --------------------------------------------------------------------- */
    /** IO handling helpers */

    /** Initializes the input and output streams. */
    private void initIO() {
        in = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        st = null;
    }

    /** Returns the next token from STDIN, reading a new line if necessary. */
    private String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(in.readLine());
        }
        return st.nextToken();
    }

    /** Reads the next integer from the token stream. */
    private int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    /** Reads the whole board according to the given dimensions. */
    private char[][] readBoard(int rows, int cols) throws IOException {
        char[][] board = new char[rows][];
        for (int r = 0; r < rows; r++) {
            board[r] = next().toCharArray();
        }
        return board;
    }

    /** --------------------------------------------------------------------- */
    /** Core algorithm */

    /**
     * Performs a flood‑fill starting from the first occurrence of {@code startChar}
     * in {@code board}.  All reachable cells in the four cardinal directions are
     * marked with {@code startVal} in the supplied {@code distance} matrix,
     * stopping only at the board borders or at {@link #BARRIER}.
     *
     * @param board    the original board (must not be modified)
     * @param distance matrix that stores the step count for each cell;
     *                 cells with {@link #UNVISITED} are updated.
     * @param startChar character that marks the source cell ('S' or 'T')
     * @param startVal  the value to write for visited cells (1 for S, 2 for T)
     */
    private void floodFill(char[][] board, int[][] distance, char startChar, int startVal) {
        int n = board.length;
        int m = board[0].length;

        // Locate the first occurrence of the start marker.
        int srcRow = -1, srcCol = -1;
        outer:
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (board[r][c] == startChar) {
                    srcRow = r;
                    srcCol = c;
                    break outer;
                }
            }
        }
        if (srcRow == -1) {
            return; // Input guarantees that the character exists.
        }

        // Directions: right, left, down, up.
        final int[] dr = {0, 0, 1, -1};
        final int[] dc = {1, -1, 0, 0};

        // Propagate horizontally and vertically until a barrier or edge.
        for (int dir = 0; dir < 4; dir++) {
            for (int step = 1; ; step++) {
                int nr = srcRow + dr[dir] * step;
                int nc = srcCol + dc[dir] * step;

                // Boundary check.
                if (nr < 0 || nr >= n || nc < 0 || nc >= m) {
                    break;
                }
                // Stop at an impenetrable barrier.
                if (board[nr][nc] == BARRIER) {
                    break;
                }

                // Record the distance if the cell hasn't been visited yet.
                if (distance[nr][nc] == UNVISITED) {
                    distance[nr][nc] = startVal;
                }
            }
        }
    }

    /** Solves the problem and prints the result. */
    private void solve() throws IOException {
        int n = nextInt();          // number of rows
        int m = nextInt();          // number of columns
        char[][] board = readBoard(n, m);

        // Distance matrices: 0 = unvisited, 1 = reachable from 'S', 2 = reachable from 'T'.
        int[][] distFromS = new int[n][m];
        int[][] distFromT = new int[n][m];
        for (int r = 0; r < n; r++) {
            Arrays.fill(distFromS[r], UNVISITED);
            Arrays.fill(distFromT[r], UNVISITED);
        }

        // First pass – fill distances from the start cell 'S' (value = 1).
        floodFill(board, distFromS, 'S', 1);
        // Second pass – fill distances from the target cell 'T' (value = 2).
        floodFill(board, distFromT, 'T', 2);

        // Look for a cell reachable from both sources whose combined step count
        // is strictly less than 4.
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (distFromS[r][c] > 0 && distFromT[r][c] > 0) {
                    int combined = distFromS[r][c] + distFromT[r][c];
                    if (combined < 4) {
                        out.println("YES");
                        return;
                    }
                }
            }
        }
        out.println("NO");
    }

    /** Entry point */
    public static void main(String[] args) throws IOException {
        new Solution().run();
    }

    /** Starts the whole process (input → solve → output). */
    private void run() throws IOException {
        initIO();
        solve();
    }
}

/**
 * Refactored solution for the “Path with limited turns” problem.
 *
 * <p>The program reads a grid that contains
 * – ‘S’ : start cell,
 * – ‘T’ : target cell,
 * – ‘*’ : obstacle,
 * – '.' : empty cell.
 *
 * <p>It determines whether a path from ‘S’ to ‘T’ exists that contains
 * at most two direction changes (i.e. up to three straight segments).
 *
 * <p>The implementation focuses on readability, proper separation of concerns,
 * and maintainable code structure.
 */
public final class Main {

    /** Entry point. */
    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee proper stream closure.
        try (FastScanner input = new FastScanner(System.in);
             FastPrinter output = new FastPrinter(System.out)) {

            Solver solver = new Solver();
            solver.solve(input, output);
        }
    }

    /** Solver encapsulates the algorithmic logic of the problem. */
    private static final class Solver {

        /** Directions: down, right, up, left. */
        private static final int[] DX = {1, 0, -1, 0};
        private static final int[] DY = {0, 1, 0, -1};

        /** Maximum number of allowed direction changes (plus one). */
        private static final int MAX_TURNS = 3; // 0, 1, 2 turns => 3 allowed straight segments

        /**
         * Solves a single test case.
         *
         * @param scanner input that provides the grid
         * @param out    output where the answer is printed
         */
        public void solve(FastScanner scanner, FastPrinter out) {
            int n = scanner.nextInt();          // number of rows
            int m = scanner.nextInt();          // number of columns
            char[][] grid = scanner.readCharacterFieldTokens(n, m);

            // Locate start ('S') and target ('T') cells.
            Pos start = locateCell(grid, 'S');
            Pos target = locateCell(grid, 'T');

            if (start == null || target == null) {
                out.println("NO");
                return;
            }

            // BFS over states (turns used, moving direction, position).
            boolean[][][][] visited = new boolean[MAX_TURNS][4][n][m];
            // Use a simple queue of State objects – no manual encoding needed.
            var queue = new java.util.ArrayDeque<State>();
            for (int dir = 0; dir < 4; dir++) {
                State initial = new State(0, dir, start.x, start.y);
                visited[0][dir][start.x][start.y] = true;
                queue.add(initial);
            }

            while (!queue.isEmpty()) {
                State cur = queue.poll();

                // Destination reached?
                if (cur.x == target.x && cur.y == target.y) {
                    out.println("YES");
                    return;
                }

                // Explore neighbours.
                for (int ndir = 0; ndir < 4; ndir++) {
                    int newTurnCount = cur.turns + (ndir == cur.dir ? 0 : 1);
                    if (newTurnCount >= MAX_TURNS) {
                        continue; // too many direction changes
                    }

                    int nx = cur.x + DX[ndir];
                    int ny = cur.y + DY[ndir];

                    if (!inBounds(nx, ny, n, m)) {
                        continue;
                    }
                    if (grid[nx][ny] == '*') {
                        continue;
                    }
                    if (visited[newTurnCount][ndir][nx][ny]) {
                        continue;
                    }

                    visited[newTurnCount][ndir][nx][ny] = true;
                    queue.add(new State(newTurnCount, ndir, nx, ny));
                }
            }

            // Exhausted all possibilities without reaching the target.
            out.println("NO");
        }

        /** Utility to find the coordinates of a given cell character. */
        private static Pos locateCell(char[][] grid, char targetChar) {
            for (int i = 0; i < grid.length; i++) {
                for (int j = 0; j < grid[i].length; j++) {
                    if (grid[i][j] == targetChar) {
                        return new Pos(i, j);
                    }
                }
            }
            return null;
        }

        /** Checks whether a cell lies inside the grid. */
        private static boolean inBounds(int x, int y, int rows, int cols) {
            return x >= 0 && y >= 0 && x < rows && y < cols;
        }

        /** Simple DTO that packages a BFS state. */
        private static final class State {
            final int turns;   // number of direction changes performed so far
            final int dir;     // direction we are currently moving in (0‑3)
            final int x;       // row index
            final int y;       // column index

            State(int turns, int dir, int x, int y) {
                this.turns = turns;
                this.dir = dir;
                this.x = x;
                this.y = y;
            }
        }
    }

    /** Fast input utilities – thin wrapper around {@link BufferedReader}. */
    private static final class FastScanner extends BufferedReader {
        FastScanner(InputStream stream) {
            super(new InputStreamReader(stream));
        }

        /** Reads the next non‑whitespace token. */
        String next() {
            StringBuilder sb = new StringBuilder();
            int c = read();
            while (isWhiteSpace(c)) {
                c = read();
            }
            while (c >= 0 && !isWhiteSpace(c)) {
                sb.appendCodePoint(c);
                c = read();
            }
            return sb.toString();
        }

        /** Reads a single character, converting I/O exceptions to unchecked ones. */
        @Override
        public int read() {
            try {
                return super.read();
            } catch (IOException e) {
                throw new InputMismatchException();
            }
        }

        /** Reads the next integer from the input stream. */
        int nextInt() {
            int c = read();
            while (isWhiteSpace(c)) {
                c = read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int value = 0;
            while (c >= 0 && !isWhiteSpace(c)) {
                if (c < '0' || c > '9') {
                    throw new NumberFormatException();
                }
                value = value * 10 + (c - '0');
                c = read();
            }
            return value * sign;
        }

        /** Reads the remainder of the current line (not used here but kept for compatibility). */
        String readLine() {
            try {
                return super.readLine();
            } catch (IOException e) {
                return null;
            }
        }

        /** Reads a block of characters that represents a grid row. */
        char[][] readCharacterFieldTokens(int rows, int cols) {
            char[][] result = new char[rows][];
            for (int i = 0; i < rows; i++) {
                String token = next();
                if (token.length() != cols) {
                    throw new AssertionError("Row length mismatch: expected " + cols);
                }
                result[i] = token.toCharArray();
            }
            return result;
        }

        /** Utility: whitespace detection (covers ASCII space and control chars). */
        private static boolean isWhiteSpace(int c) {
            return c <= ' ';
        }
    }

    /** Fast output wrapper around {@link PrintWriter}. */
    private static final class FastPrinter extends PrintWriter {
        FastPrinter(OutputStream out) {
            super(out);
        }

        FastPrinter(Writer out) {
            super(out);
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored version of the original {@code IgorWayToWork} program.
 * The functionality is identical, but the code is now easier to read,
 * maintain and extend.
 */
public class IgorWayToWork {

    /* --------------------------------------------------------------------- */
    /*  Configuration constants                                                */
    /* --------------------------------------------------------------------- */
    private static final int TURN_LIMIT = 2;          // maximum allowed turns

    /* --------------------------------------------------------------------- */
    /*  Instance fields                                                       */
    /* --------------------------------------------------------------------- */
    private String outcome = "NO";                    // final answer ("YES"/"NO")
    private boolean[][][] visited;                    // [row][col][turnsCount]
    private int startX, startY;                       // start cell coordinates
    private int endX, endY;                           // target cell coordinates
    private int rows, cols;                           // board dimensions

    /* --------------------------------------------------------------------- */
    /*  Directions constants                                                   */
    /* --------------------------------------------------------------------- */
    private static final int[] DX = {-1, 0, 1, 0};    // up, stay, down, stay
    private static final int[] DY = {0, -1, 0, 1};    // stay, left, stay, right

    /* --------------------------------------------------------------------- */
    /*  Depth‑first search                                                    */
    /* --------------------------------------------------------------------- */
    private void dfs(int[][] board, int x, int y, int currentDir, int turns) {
        // Found the target → terminate early
        if (x == endX && y == endY) {
            outcome = "YES";
            return;
        }

        if (outcome.equals("YES")) {
            return;                                   // already succeeded elsewhere
        }

        visited[x][y][turns] = true;                  // mark current state

        // Explore the four neighbour cells
        for (int i = 0; i < 4; i++) {
            if (outcome.equals("YES")) {
                return;
            }

            int nx = x + DX[i];
            int ny = y + DY[i];

            // Boundary check
            if (!isInside(nx, ny)) {
                continue;
            }

            // Walkable cells are marked with 1 in the original board
            if (board[nx][ny] == 0) {
                continue;
            }

            // Skip already visited states with the same turn count
            if (visited[nx][ny][turns]) {
                continue;
            }

            // -----------------------------------------------------------------
            // Turn handling – reproduced verbatim from the original logic
            // -----------------------------------------------------------------
            boolean movingHorizontally = ny != y;
            boolean movingVertically   = nx != x;

            if (currentDir == 1) { // came from a horizontal move
                if (movingVertically) {
                    if (turns < TURN_LIMIT) {
                        dfs(board, nx, ny, 2, turns + 1);
                    }
                } else {
                    dfs(board, nx, ny, currentDir, turns);
                }
            } else if (currentDir == 2) { // came from a vertical move
                if (movingHorizontally) {
                    if (turns < TURN_LIMIT) {
                        dfs(board, nx, ny, 1, turns + 1);
                    }
                } else {
                    dfs(board, nx, ny, currentDir, turns);
                }
            } else { // starting cell (currentDir == 0)
                int newDir = movingHorizontally ? 1 : 2;
                dfs(board, nx, ny, newDir, turns);
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Helper utilities                                                       */
    /* --------------------------------------------------------------------- */
    private boolean isInside(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /* --------------------------------------------------------------------- */
    /*  Core solving routine                                                   */
    /* --------------------------------------------------------------------- */
    private void solve(BufferedReader br, PrintWriter pw) throws IOException {
        // ---- read dimensions -------------------------------------------------
        StringTokenizer st = new StringTokenizer(br.readLine());
        rows = Integer.parseInt(st.nextToken());
        cols = Integer.parseInt(st.nextToken());

        // ---- read board and locate 'S' and 'T' -------------------------------
        int[][] board = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = br.readLine();
            for (int j = 0; j < cols; j++) {
                char ch = line.charAt(j);
                if (ch != '*') {
                    board[i][j] = 1; // traversable cell
                    if (ch == 'S') {
                        startX = i;
                        startY = j;
                    } else if (ch == 'T') {
                        endX = i;
                        endY = j;
                    }
                }
            }
        }

        // ---- initialise visited array and launch DFS ------------------------
        visited = new boolean[rows][cols][TURN_LIMIT + 1];
        dfs(board, startX, startY, 0, 0);

        // ---- output answer ---------------------------------------------------
        pw.println(outcome);
    }

    /* --------------------------------------------------------------------- */
    /*  Public entry points                                                    */
    /* --------------------------------------------------------------------- */
    public void runStdIO() throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in);
             PrintWriter pw = new PrintWriter(System.out)) {
            solve(br, pw);
        }
    }

    public static void main(String[] args) throws IOException {
        new IgorWayToWork().runStdIO();
    }

    /* --------------------------------------------------------------------- */
    /*  Optional file‑IO helpers (kept for compatibility)                     */
    /* --------------------------------------------------------------------- */
    public void runFileIO(String filename) throws IOException {
        try (BufferedReader br = new BufferedReader(new FileReader(filename + ".in"));
             PrintWriter pw = new PrintWriter(new BufferedWriter(new FileWriter(filename + ".out")))) {
            solve(br, pw);
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program that searches for a path from 'S'
 * to 'T' with at most two direction changes.
 *
 * The refactoring focuses on:
 *   • Clear naming and separation of concerns
 *   • Use of an enum for the four cardinal directions
 *   • Small, single‑purpose methods
 *   • Removal of unused/misleading static fields
 *   • Consistent style and comments
 */
public class IgorToWork {

    private static final char START = 'S';
    private static final char TARGET = 'T';
    private static final char BLOCKED = '*';

    private static char[][] grid;
    private static int rows;
    private static int cols;
    private static int endRow;
    private static int endCol;

    /** Four cardinal directions with helper utilities. */
    private enum Direction {
        UP(-1, 0, true), /* isVertical */
        DOWN(1, 0, true),
        LEFT(0, -1, false), /* isHorizontal */
        RIGHT(0, 1, false);

        private final int dr;
        private final int dc;
        private final boolean horizontal;

        Direction(int dr, int dc, boolean horizontal) {
            this.dr = dr;
            this.dc = dc;
            this.horizontal = horizontal;
        }

        int deltaRow() { return dr; }
        int deltaCol() { return dc; }

        boolean isHorizontal() { return horizontal; }
        boolean isVertical()   { return !horizontal; }
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            readInput(sc);
            exploreFromStart();
            System.out.println("NO");
        }
    }

    /** Reads the matrix dimensions and the grid itself. */
    private static void readInput(Scanner sc) {
        rows = sc.nextInt();
        cols = sc.nextInt();
        grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            for (int j = 0; j < cols; j++) {
                char cell = line.charAt(j);
                grid[i][j] = cell;
                if (cell == TARGET) {
                    endRow = i;
                    endCol = j;
                }
            }
        }
    }

    /** Locates the start cell 'S' and launches depth‑first searches in all four directions. */
    private static void exploreFromStart() {
        int startRow = -1, startCol = -1;

        outer:
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == START) {
                    startRow = i;
                    startCol = j;
                    break outer;
                }
            }
        }

        // try moving one step in each of the four directions
        for (Direction dir : Direction.values()) {
            int nr = startRow + dir.deltaRow();
            int nc = startCol + dir.deltaCol();
            dfs(nr, nc, dir, 0);
        }
    }

    /**
     * Depth‑first search that respects the “at most two turns” rule.
     *
     * @param row     current row
     * @param col     current column
     * @param curDir  direction taken to reach this cell
     * @param turns   number of direction changes performed so far
     */
    private static void dfs(int row, int col, Direction curDir, int turns) {
        // 1️⃣ Boundary & obstacle check
        if (!inBounds(row, col)) {
            return;
        }
        if (grid[row][col] == BLOCKED) {
            return;
        }

        // 2️⃣ Early exit if we have already exceeded the turn limit
        if (turns > 2) {
            return;
        }

        // 3️⃣ Restriction that after exactly two turns we may only move
        //    along the axis that matches the target's row/column.
        if (turns == 2) {
            if (curDir.isHorizontal() && row != endRow) {
                return;
            }
            if (curDir.isVertical() && col != endCol) {
                return;
            }
        }

        // 4️⃣ Reached the destination
        if (grid[row][col] == TARGET) {
            System.out.println("YES");
            System.exit(0);
        }

        // 5️⃣ Explore neighbours in all four directions
        for (Direction nextDir : Direction.values()) {
            // compute the new turn count (increase only when direction changes)
            int newTurns = (nextDir == curDir) ? turns : turns + 1;
            if (newTurns > 2) {
                continue; // prune branches that already exceed the limit
            }

            // Additional restriction that mirrors the original early‑return logic
            if (newTurns == 2) {
                if (nextDir.isHorizontal() && row != endRow) continue;
                if (nextDir.isVertical() && col != endCol) continue;
            }

            int nextRow = row + nextDir.deltaRow();
            int nextCol = col + nextDir.deltaCol();
            dfs(nextRow, nextCol, nextDir, newTurns);
        }
    }

    /** Utility to test whether a coordinate lies inside the grid. */
    private static boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.IOException;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Scanner;

/**
 * PathFinder solves a grid‑traversal problem where the goal is to reach ‘T’
 * from ‘S’ while never using more than two direction changes.
 *
 * The algorithm uses BFS over the state (row, col, direction, turnsSoFar).
 * The original program’s behaviour (turn counting and movement rules) has
 * been simplified to an equivalent, clearer formulation.
 */
public class PathFinder {

    /** Maximum number of direction changes that are allowed. */
    private static final int MAX_TURNS = 2;

    /** Grid dimensions */
    private static int rows, cols;

    /** 2‑D view of the input grid */
    private static char[][] grid;

    /** For each cell and each possible arriving direction we store the
     *  minimum number of direction changes needed to reach it. */
    private static int[][][] bestTurns;   // [row][col][direction]

    /** Does the target cell become reachable within the turn limit? */
    private static boolean targetReached;

    /** The four cardinal directions plus a “none” direction for the start. */
    private enum Direction {
        NONE(0, 0),
        NORTH(-1, 0),
        SOUTH(1, 0),
        EAST(0, 1),
        WEST(0, -1);

        final int dr, dc;
        Direction(int dr, int dc) { this.dr = dr; this.dc = dc; }

        /** Convert a delta (dr, dc) to the corresponding Direction. */
        static Direction fromDelta(int dr, int dc) {
            for (Direction d : values()) {
                if (d.dr == dr && d.dc == dc) {
                    return d;
                }
            }
            throw new IllegalArgumentException("Invalid delta: (" + dr + "," + dc + ")");
        }
    }

    /** A node used by BFS – represents a position together with the
     *  direction we arrived from and how many turns we have already taken. */
    private static final class State {
        final int r, c;          // cell coordinates
        final int turns;         // number of direction changes performed so far
        final Direction dir;     // direction we entered this cell with

        State(int r, int c, int turns, Direction dir) {
            this.r = r;
            this.c = c;
            this.turns = turns;
            this.dir = dir;
        }
    }

    /** Entry point – reads input, runs BFS and prints the answer. */
    public static void main(String[] args) throws IOException {
        try (Scanner sc = new Scanner(System.in)) {
            readInput(sc);
            initialiseVisitedArray();
            runBfs();
            System.out.println(targetReached ? "YES" : "NO");
        }
    }

    /** Parses the problem description from standard input. */
    private static void readInput(Scanner sc) {
        rows = sc.nextInt();
        cols = sc.nextInt();
        grid = new char[rows][];
        int startR = -1, startC = -1;
        int endR = -1, endC = -1;

        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                char ch = grid[i][j];
                if (ch == 'S') {
                    startR = i;
                    startC = j;
                } else if (ch == 'T') {
                    endR = i;
                    endC = j;
                }
            }
        }

        // store the target coordinates in the outer class for easy access
        setEndCoordinates(endR, endC);
        setStartCoordinates(startR, startC);
    }

    /** Allocates the 3‑D visited‑turns array and fills it with a sentinel value. */
    private static void initialiseVisitedArray() {
        int dirCount = Direction.values().length;
        bestTurns = new int[rows][cols][dirCount];
        for (int[][] layer : bestTurns) {
            for (int[] row : layer) {
                Arrays.fill(row, Integer.MAX_VALUE);
            }
        }
    }

    /** Helper to store the target coordinates (used only for readability). */
    private static int endR, endC;

    private static void setEndCoordinates(int r, int c) {
        endR = r;
        endC = c;
    }

    /** Helper to store the start coordinates. */
    private static int startR, startC;

    private static void setStartCoordinates(int r, int c) {
        startR = r;
        startC = c;
    }

    /** Executes the BFS search. */
    private static void runBfs() {
        Deque<State> queue = new ArrayDeque<>();
        // start state: at 'S' with no direction and 0 turns taken
        queue.add(new State(startR, startC, 0, Direction.NONE));
        bestTurns[startR][startC][Direction.NONE.ordinal()] = 0;

        while (!queue.isEmpty()) {
            State cur = queue.poll();

            // Success – we arrived at the target cell
            if (cur.r == endR && cur.c == endC) {
                targetReached = true;
                break;
            }

            // Examine the four possible neighbour directions
            for (Direction ndir : Direction.values()) {
                if (ndir == Direction.NONE) { continue; } // cannot stay put

                int nr = cur.r + ndir.dr;
                int nc = cur.c + ndir.dc;

                // Boundary and obstacle check
                if (!inGrid(nr, nc) || grid[nr][nc] == '*') {
                    continue;
                }

                // Determine how many turns are needed for this move
                int newTurns = cur.turns;
                if (cur.dir != Direction.NONE && ndir != cur.dir) {
                    newTurns++;
                }
                if (newTurns > MAX_TURNS) {
                    continue;               // exceeds the allowed number of turns
                }

                int dirIdx = ndir.ordinal();
                if (newTurns < bestTurns[nr][nc][dirIdx]) {
                    bestTurns[nr][nc][dirIdx] = newTurns;
                    queue.add(new State(nr, nc, newTurns, ndir));
                }
            }
        }
    }

    /** Returns true if a cell lies inside the grid. */
    private static boolean inGrid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 *  A lightweight, fast input reader.
 */
final class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    FastScanner(InputStream in) {
        this.br = new BufferedReader(new InputStreamReader(in));
    }

    /** Returns the next non‑empty token. */
    String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    /** For convenience when the whole line is required. */
    String nextLine() throws IOException {
        return br.readLine();
    }
}

/**
 *  Main class – contains all logic of the problem.
 *
 *  The program checks whether there exists either
 *  • a column through which the start and target cells can be connected vertically, or
 *  • a row through which they can be connected horizontally.
 *
 *  All heavy lifting is delegated to small, well‑named methods,
 *  making the code easy to read, test and maintain.
 */
public class Abood2D {

    private static char[][] grid;
    private static int n, m;
    private static int startRow, startCol;
    private static int endRow,   endCol;

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        FastScanner in  = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        readInput(in);

        if (canConnectViaColumn() || canConnectViaRow()) {
            out.println("YES");
        } else {
            out.println("NO");
        }

        out.flush();
    }

    /** --------------------------------------------------------------
     *  Input reading
     *  -------------------------------------------------------------- */
    private static void readInput(FastScanner in) throws IOException {
        n = in.nextInt();                // number of rows
        m = in.nextInt();                // number of columns

        grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            String line = in.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);

                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (grid[i][j] == 'T') {
                    endRow = i;
                    endCol = j;
                }
            }
        }
    }

    /** --------------------------------------------------------------
     *  Horizontal analysis – can we meet in a column ?
     *  -------------------------------------------------------------- */
    private static boolean canConnectViaColumn() {
        // how far to the left / right the start cell can travel in its row
        int leftStart  = reachLeft(startRow, startCol);
        int rightStart = reachRight(startRow, startCol);

        // the same for the target cell
        int leftEnd  = reachLeft(endRow, endCol);
        int rightEnd = reachRight(endRow, endCol);

        // overlapping columns that both cells can reach
        int low  = Math.max(leftStart,  leftEnd);
        int high = Math.min(rightStart, rightEnd);

        for (int col = low; col <= high; col++) {
            if (columnIsClearVertically(col)) {
                return true;
            }
        }
        return false;
    }

    /** --------------------------------------------------------------
     *  Vertical analysis – can we meet in a row ?
     *  -------------------------------------------------------------- */
    private static boolean canConnectViaRow() {
        int upStart  = reachUp(startRow, startCol);
        int downStart = reachDown(startRow, startCol);

        int upEnd  = reachUp(endRow, endCol);
        int downEnd = reachDown(endRow, endCol);

        int low  = Math.max(upStart,  upEnd);
        int high = Math.min(downStart, downEnd);

        for (int row = low; row <= high; row++) {
            if (rowIsClearHorizontally(row)) {
                return true;
            }
        }
        return false;
    }

    /** --------------------------------------------------------------
     *  Helper: how far can we move left from a given cell ?
     *  -------------------------------------------------------------- */
    private static int reachLeft(int row, int col) {
        int reach = col;
        for (int c = col - 1; c >= 0; c--) {
            if (grid[row][c] == '.') {
                reach = c;
            } else {
                break;
            }
        }
        return reach;
    }

    /** --------------------------------------------------------------
     *  Helper: how far can we move right from a given cell ?
     *  -------------------------------------------------------------- */
    private static int reachRight(int row, int col) {
        int reach = col;
        for (int c = col + 1; c < m; c++) {
            if (grid[row][c] == '.') {
                reach = c;
            } else {
                break;
            }
        }
        return reach;
    }

    /** --------------------------------------------------------------
     *  Helper: how far can we move up from a given cell ?
     *  -------------------------------------------------------------- */
    private static int reachUp(int row, int col) {
        int reach = row;
        for (int r = row - 1; r >= 0; r--) {
            if (grid[r][col] == '.') {
                reach = r;
            } else {
                break;
            }
        }
        return reach;
    }

    /** --------------------------------------------------------------
     *  Helper: how far can we move down from a given cell ?
     *  -------------------------------------------------------------- */
    private static int reachDown(int row, int col) {
        int reach = row;
        for (int r = row + 1; r < n; r++) {
            if (grid[r][col] == '.') {
                reach = r;
            } else {
                break;
            }
        }
        return reach;
    }

    /** --------------------------------------------------------------
     *  Checks whether every cell of a given column between the two
     *  rows (inclusive) contains only '.', 'S' or 'T'.
     *  -------------------------------------------------------------- */
    private static boolean columnIsClearVertically(int col) {
        int r1 = Math.min(startRow, endRow);
        int r2 = Math.max(startRow, endRow);
        for (int r = r1; r <= r2; r++) {
            char cell = grid[r][col];
            if (cell != '.' && cell != 'S' && cell != 'T') {
                return false;
            }
        }
        return true;
    }

    /** --------------------------------------------------------------
     *  Checks whether every cell of a given row between the two
     *  columns (inclusive) contains only '.', 'S' or 'T'.
     *  -------------------------------------------------------------- */
    private static boolean rowIsClearHorizontally(int row) {
        int c1 = Math.min(startCol, endCol);
        int c2 = Math.max(startCol, endCol);
        for (int c = c1; c <= c2; c++) {
            char cell = grid[row][c];
            if (cell != '.' && cell != 'S' && cell != 'T') {
                return false;
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Directions: UP, DOWN, LEFT, RIGHT */
    private enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        private final int dRow;
        private final int dCol;

        Direction(int dRow, int dCol) {
            this.dRow = dRow;
            this.dCol = dCol;
        }

        int getDeltaRow() {
            return dRow;
        }

        int getDeltaCol() {
            return dCol;
        }

        /** Convert a delta movement to the corresponding enum constant */
        static Direction fromDelta(int dRow, int dCol) {
            for (Direction d : values()) {
                if (d.dRow == dRow && d.dCol == dCol) {
                    return d;
                }
            }
            throw new IllegalArgumentException("Invalid direction delta");
        }

        /** Return the opposite direction */
        Direction opposite() {
            switch (this) {
                case UP:    return DOWN;
                case DOWN:  return UP;
                case LEFT:  return RIGHT;
                case RIGHT: return LEFT;
                default: throw new IllegalStateException();
            }
        }
    }

    /** Maximum allowed direction changes (turns) */
    private static final int MAX_TURNS = 2;

    /** Holds the state of a BFS node: position, turns used, current moving direction */
    private static final class Node {
        final int row;
        final int col;
        final int turns;
        final Direction dir;

        Node(int row, int col, int turns, Direction dir) {
            this.row = row;
            this.col = col;
            this.turns = turns;
            this.dir = dir;
        }
    }

    /** Checks whether the supplied coordinates are inside the grid */
    private static boolean inside(int r, int rows, int c, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Reads the grid from the supplied BufferedReader */
    private static char[][] readGrid(BufferedReader br, int n, int m) throws IOException {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    public static void main(String[] args) throws IOException {
        /* ----------- Input handling ------------------------------------------------ */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            char[][] grid = readGrid(br, n, m);

            /* ---- Locate the start cell 'S' -------------------------------------- */
            int startRow = -1, startCol = -1;
            outer:
            for (int i = 0; i < n; i++) {
                String line = br.readLine();   // grid lines are already stored above,
                                                // but the outer loop reads them again.
                // In the original code the grid is built from stdin line by line.
                // To keep the same behaviour we read line again:
                // (the previous readGrid consumed exactly n lines, so we just continue.)
                // No extra action is required here; we simply locate 'S' in the already read grid.
            }

            // Because we already stored the grid while reading, we can now search it:
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                        break outer;
                    }
                }
            }

            if (startRow == -1) {
                System.out.println("NO");
                return;
            }

            /* ---- Initialise visited array (turns taken for each (row,col,direction)) - */
            int[][][] visited = new int[n][m][Direction.values().length];
            for (int[][] a : visited) {
                for (int[] b : a) {
                    Arrays.fill(b, Integer.MAX_VALUE);
                }
            }

            /* ---- BFS initialisation ------------------------------------------------- */
            Queue<Node> queue = new ArrayDeque<>();

            // From the start cell we may initally move in any direction whose neighbour is walkable
            for (Direction dir : Direction.values()) {
                int nr = startRow + dir.getDeltaRow();
                int nc = startCol + dir.getDeltaCol();
                if (inside(nr, n, nc, m) && grid[nr][nc] == '.') {
                    int dirIdx = dir.ordinal();
                    visited[nr][nc][dirIdx] = 0;
                    queue.add(new Node(nr, nc, 0, dir));
                }
            }

            /* ---- BFS main loop ------------------------------------------------------ */
            while (!queue.isEmpty()) {
                Node cur = queue.poll();

                for (Direction nextDir : Direction.values()) {
                    int nr = cur.row + nextDir.getDeltaRow();
                    int nc = cur.col + nextDir.getDeltaCol();
                    if (!inside(nr, n, nc, m)) {
                        continue;
                    }

                    // Determine if we are changing direction
                    boolean changedDirection = cur.dir != nextDir;
                    int newTurns = changedDirection ? cur.turns + 1 : cur.turns;

                    // Respect the maximum allowed number of turns
                    if (newTurns > MAX_TURNS) {
                        continue;
                    }

                    // If a direction change would exceed the limit, discard this move
                    if (changedDirection && cur.turns == MAX_TURNS) {
                        continue;
                    }

                    if (grid[nr][nc] == '.') {
                        int dirIdx = nextDir.ordinal();
                        if (newTurns < visited[nr][nc][dirIdx]) {
                            visited[nr][nc][dirIdx] = newTurns;
                            queue.add(new Node(nr, nc, newTurns, nextDir));
                        }
                    } else if (grid[nr][nc] == 'T') {
                        System.out.println("YES");
                        return;
                    }
                }
            }

            System.out.println("NO");
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Refactored solution for the “B_TinkOff_Eli” problem.
 * <p>
 * The program reads a grid containing walls ( '*'), a start cell ('S'),
 * and a target cell ('T'). From the start cell we may move in one of four
 * cardinal directions; changing direction consumes one “left” step.
 * We start with at most two direction changes (MAX_LEFT = 2) and try to
 * reach any 'T' cell. The answer is printed as “YES” or “NO”.
 * </p>
 */
public class B_TinkOff_Eli {

    /** Maximum number of allowed direction changes. */
    private static final int MAX_LEFT = 2;

    /** Movement vectors for the four directions (right, down, left, up). */
    private static final int[][] DIRS = {
            {0, 1},   // right
            {1, 0},   // down
            {0, -1},  // left
            {-1, 0}   // up
    };

    /** Memoisation table for visited states (x, y, dir, remainingLeft). */
    private static boolean[][][][] memo;

    public static void main(String[] args) {
        /* Try‑with‑resources guarantees proper closure of I/O streams. */
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            /* ----- Input parsing ----- */
            int n = scanner.nextInt();   // number of rows
            int m = scanner.nextInt();   // number of columns
            char[][] grid = new char[n][];
            int startX = -1, startY = -1;

            for (int i = 0; i < n; i++) {
                String row = scanner.next();
                grid[i] = row.toCharArray();
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'S') {
                        startX = i;
                        startY = j;
                    }
                }
            }

            /* ----- DP / DFS initialisation ----- */
            memo = new boolean[n][m][4][MAX_LEFT + 1];

            boolean reachable = false;
            for (int dir = 0; dir < 4 && !reachable; dir++) {
                reachable = dfs(startX, startY, dir, MAX_LEFT, grid);
            }

            out.println(reachable ? "YES" : "NO");
        }
    }

    /**
     * Depth‑first search that respects direction‑change budgeting.
     *
     * @param x        current row
     * @param y        current column
     * @param dir      direction we arrived from
     * @param remainingLeft  remaining direction‑change budget
     * @param grid     the whole map
     * @return {@code true} if a target ('T') can be reached from this state
     */
    private static boolean dfs(int x, int y, int dir, int remainingLeft, char[][] grid) {
        if (remainingLeft < 0) {
            return false;
        }
        if (grid[x][y] == 'T') {
            return true;
        }
        if (memo[x][y][dir][remainingLeft]) {
            return false;               // already processed
        }
        memo[x][y][dir][remainingLeft] = true;

        boolean found = false;
        for (int i = 0; i < 4 && !found; i++) {
            int nx = x + DIRS[i][0];
            int ny = y + DIRS[i][1];
            if (inside(nx, ny, grid) && grid[nx][ny] != '*') {
                int nextLeft = remainingLeft - (i == dir ? 0 : 1);
                found = dfs(nx, ny, i, nextLeft, grid);
            }
        }
        return found;
    }

    /** Helper that checks whether a cell lies inside the grid bounds. */
    private static boolean inside(int x, int y, char[][] grid) {
        return x >= 0 && y >= 0 && x < grid.length && y < grid[0].length;
    }
}

import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Scanner;

public class B793 {

    /** Directions used in the algorithm */
    private enum Direction {
        HORIZONTAL, VERTICAL
    }

    /** Maximum allowed extra turns before the path is considered impossible */
    private static final int LIMIT = 2;

    /** Distance table: [direction][row][col] */
    private int[][][] dist;
    /** Grid where true means a walkable cell */
    private boolean[][] grid;
    /** Board dimensions */
    private int rows, cols;

    /** Starting and target coordinates */
    private int startRow, startCol, targetRow, targetCol;

    /** Holds a cell together with the direction we arrived there */
    private static final class State {
        final int row;
        final int col;
        final Direction dir;

        State(int row, int col, Direction dir) {
            this.row = row;
            this.col = col;
            this.dir = dir;
        }
    }

    /** Entry point */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        PrintWriter printer = new PrintWriter(System.out);
        new B793().solve(scanner, printer);
        scanner.close();
        printer.close();
    }

    /** Solves the problem using a 0‑1 BFS */
    public void solve(Scanner in, PrintWriter out) {
        readInput(in);
        initializeDistanceTable();
        bfs();
        out.println(isAnswerGreaterThanLimit() ? "NO" : "YES");
    }

    /** Reads the board, finds 'S' and 'T' */
    private void readInput(Scanner in) {
        rows = in.nextInt();
        cols = in.nextInt();
        char[][] raw = new char[rows][];
        grid = new boolean[rows][];
        for (int r = 0; r < rows; ++r) {
            String line = in.next();
            raw[r] = line.toCharArray();
            grid[r] = new boolean[cols];
            for (int c = 0; c < cols; ++c) {
                grid[r][c] = raw[r][c] != '*';
                if (raw[r][c] == 'S') {
                    startRow = r;
                    startCol = c;
                } else if (raw[r][c] == 'T') {
                    targetRow = r;
                    targetCol = c;
                }
            }
        }
    }

    /** Fills the distance array with INF and sets the start cell to 0 */
    private void initializeDistanceTable() {
        dist = new int[2][rows][cols];
        for (int d = 0; d < 2; ++d) {
            Arrays.fill(dist[d], INF);
        }
        // Starting cell can be entered from either direction with cost 0
        dist[0][startRow][startCol] = 0;
        dist[1][startRow][startCol] = 0;
    }

    /** Executes the 0‑1 BFS */
    private void bfs() {
        Deque<State> queue = new ArrayDeque<>();
        queue.addLast(new State(startRow, startCol, Direction.HORIZONTAL));
        queue.addLast(new State(startRow, startCol, Direction.VERTICAL));

        while (!queue.isEmpty()) {
            State cur = queue.removeFirst();
            int curDirIdx = cur.dir == Direction.HORIZONTAL ? 0 : 1;
            int baseCost = dist[curDirIdx][cur.row][cur.col];

            // explore up
            relaxNeighbour(queue, cur.row - 1, cur.col, cur.dir, baseCost, true);
            // explore down
            relaxNeighbour(queue, cur.row + 1, cur.col, cur.dir, baseCost, true);
            // explore left
            relaxNeighbour(queue, cur.row, cur.col - 1, cur.dir, baseCost, false);
            // explore right
            relaxNeighbour(queue, cur.row, cur.col + 1, cur.dir, baseCost, false);
        }
    }

    /** Tries to relax distance to neighbour (nr,nc) */
    private void relaxNeighbour(Deque<State> queue,
                                int nr, int nc,
                                Direction fromDir,
                                int baseCost,
                                boolean verticalStep) {
        if (!isInBounds(nr, nc) || !grid[nr][nc]) {
            return;
        }
        Direction arrivalDir = verticalStep ? Direction.VERTICAL : Direction.HORIZONTAL;
        int cost = baseCost + (fromDir == arrivalDir ? 0 : 1);
        int idx = arrivalDir == Direction.VERTICAL ? 1 : 0;
        if (cost < dist[idx][nr][nc]) {
            dist[idx][nr][nc] = cost;
            // zero‑cost edges go to front, others to back
            if (cost == baseCost) {
                queue.addFirst(new State(nr, nc, arrivalDir));
            } else {
                queue.addLast(new State(nr, nc, arrivalDir));
            }
        }
    }

    /** Checks whether (r,c) is inside the board */
    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Returns true if the minimal number of required turns exceeds the allowed limit */
    private boolean isAnswerGreaterThanLimit() {
        int answer = Math.min(dist[0][targetRow][targetCol], dist[1][targetRow][targetCol]);
        return answer > LIMIT;
    }

    /** Constant used as INF */
    private static final int INF = Integer.MAX_VALUE / 4;
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “turn‑limited path” problem.
 *
 * <p>
 *   • Reads a grid from standard input.
 *   • Finds the start cell ‘S’ and the target cell ‘T’.
 *   • Performs a depth‑first search from the target towards the start,
 *     allowing at most three direction changes.
 *   • Prints “YES” if such a path exists, otherwise prints “NO”.
 * </p>
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Constants & symbols                                                   */
    /* --------------------------------------------------------------------- */
    private static final char WALL   = '*';
    private static final char START  = 'S';
    private static final char TARGET = 'T';

    /* --------------------------------------------------------------------- */
    /*  Grid & position information                                            */
    /* --------------------------------------------------------------------- */
    private static char[][] grid;
    private static int rows, cols;
    private static int startR, startC;
    private static int targetR, targetC;

    /* --------------------------------------------------------------------- */
    /*  Direction handling                                                    */
    /* --------------------------------------------------------------------- */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        /** movement deltas */
        int dr() { return dr; }
        int dc() { return dc; }

        /** convert an index (0‑3) to the enum value – handy for iteration */
        static Direction fromIndex(int i) {
            return values()[i];
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                            */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        /**
         * Reads the grid, locates ‘S’ and ‘T’, then launches the search.
         * The search starts from the target cell and tries to reach ‘S’
         * while respecting the turn limit.
         */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            rows = Integer.parseInt(st.nextToken());
            cols = Integer.parseInt(st.nextToken());

            grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                grid[r] = br.readLine().toCharArray();
            }

            locateCells();
            Search.searchFromTarget();
            System.out.println("NO");
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Helper methods                                                         */
    /* --------------------------------------------------------------------- */
    /** Finds the coordinates of ‘S’ and ‘T’ inside the grid. */
    private static void locateCells() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cell = grid[r][c];
                if (cell == START) {
                    startR = r;
                    startC = c;
                } else if (cell == TARGET) {
                    targetR = r;
                    targetC = c;
                }
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Search component                                                       */
    /* --------------------------------------------------------------------- */
    /**
     * Core DFS implementation that explores paths starting from the target
     * cell. The search stops as soon as the start cell is reached.
     *
     * <p>
     *   State consists of:
     *   <ul>
     *     <li>row / column</li>
     *     <li>current direction</li>
     *     <li>number of turns already made</li>
     *   </ul>
     * </p>
     */
    private static class Search {

        /** Tries to reach the start cell from (sr, sc) with at most 3 turns. */
        static void searchFromTarget() {
            // From the target we may launch in any of the four directions.
            for (int dIdx = 0; dIdx < Direction.values().length; dIdx++) {
                Direction startDir = Direction.fromIndex(dIdx);
                explore(targetR, targetC, startDir, 0);
            }
        }

        /** Recursive depth‑first search. */
        private static void explore(int r, int c,
                                    Direction curDir, int turns) {

            // Success condition – we have arrived at the start cell.
            if (r == startR && c == startC) {
                System.out.println("YES");
                System.exit(0);
            }

            // No more turns allowed.
            if (turns > 3) {
                return;
            }

            // Try every possible next direction.
            for (int nextIdx = 0; nextIdx < Direction.values().length; nextIdx++) {
                Direction nextDir = Direction.fromIndex(nextIdx);

                int nr = r + nextDir.dr();
                int nc = c + nextDir.dc();

                // Boundary / obstacle check.
                if (outOfBounds(nr, nc) || grid[nr][nc] == WALL) {
                    continue;
                }

                // If we change direction we incur a turn.
                int newTurns = turns + (nextDir != curDir ? 1 : 0);
                if (newTurns > 3) {
                    continue;
                }

                // Recurse.
                explore(nr, nc, nextDir, newTurns);
            }
        }

        /** Simple bounds check. */
        private static boolean outOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Maze explorer that determines whether the target 'T' can be reached
 * from the start 'S' using at most two direction changes.
 *
 * The implementation follows the original algorithm but improves
 * readability, naming, and modularity.
 */
public class Ideone {

    /** Maximum grid size used in the original solution. */
    private static final int MAX = 1005;

    /** Four cardinal directions. */
    private enum Direction {
        EAST(0, 1),
        WEST(0, -1),
        SOUTH(1, 0),
        NORTH(-1, 0);

        final int dx;
        final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }
    }

    /** The maze read from input. */
    private static char[][] maze = new char[MAX][MAX];

    /**
     * Minimum number of direction‑changes recorded for each
     * (row, col, direction) state.
     */
    private static int[][][] minTurns = new int[MAX][MAX][Direction.values().length];

    /** Global answer – either "YES" or "NO". */
    private static String answer;

    /** Program entry point. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();   // rows
            int m = scanner.nextInt();   // columns
            maze = new char[n][m];

            int startR = -1, startC = -1;

            // ----- read the whole maze -------------------------------------------------
            for (int i = 0; i < n; i++) {
                String line = scanner.next();
                for (int j = 0; j < m; j++) {
                    maze[i][j] = line.charAt(j);
                    if (maze[i][j] == 'S') {
                        startR = i;
                        startC = j;
                    }
                }
            }

            // ----- initialise visited array -------------------------------------------
            Arrays.fill(minTurns, Integer.MAX_VALUE);
            answer = "NO";

            // start the search; -1 means “no incoming direction” yet
            dfs(startR, startC, -1, -1);

            System.out.println(answer);
        }
    }

    /**
     * Depth‑first search that respects the “at most two turns” rule.
     *
     * @param row       current row index
     * @param col       current column index
     * @param incoming  index of the direction we arrived from
     *                  (‑1 for the very first step)
     * @param turns     number of direction changes performed so far
     */
    private static void dfs(int row, int col, int incoming, int turns) {
        // ----- boundary / obstacle / turn‑limit checks -----------------------------
        if (outOfBounds(row, col) || maze[row][col] == '*' || turns > 2) {
            return;
        }

        // ----- success condition ---------------------------------------------------
        if (maze[row][col] == 'T') {
            answer = "YES";
            return;                     // early exit – we already know the answer
        }

        // ----- prune already explored states --------------------------------------
        // If we have reached this cell before with an equal or smaller turn count,
        // there is no reason to continue this path.
        int dirIdx = (incoming == -1) ? 0 : incoming;   // map -1 … 0 for array lookup
        if (turns != -1 && turns >= minTurns[row][col][dirIdx]) {
            return;
        }
        // Record the best (smallest) turn count for this state.
        minTurns[row][col][dirIdx] = turns;

        // ----- explore neighbours --------------------------------------------------
        for (Direction dir : Direction.values()) {
            // When we are at the start we may pick any direction.
            // Otherwise we either continue straight (no extra turn) or turn
            // (increment turn count).
            if (incoming == -1 || dir.ordinal() != incoming) {
                dfs(row + dir.dx, col + dir.dy, dir.ordinal(), turns + 1);
            } else {
                dfs(row + dir.dx, col + dir.dy, dir.ordinal(), turns);
            }
        }
    }

    /** @return true if the given coordinates lie outside the maze borders. */
    private static boolean outOfBounds(int row, int col) {
        return row < 0 || row >= maze.length || col < 0 || col >= maze[0].length;
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point of the solution.
 *
 * The program reads a grid from {@code file.in} (or {@code System.in} if the file does not exist),
 * computes a temporary “score” for each cell according to the rules described in the original
 * code and prints {@code YES} or {@code NO} into {@code file.out} (or {@code System.out}).
 *
 * The refactor separates concerns into small, focused classes / methods, removes duplicated
 * logic, replaces magic numbers with named constants and uses clearer naming throughout.
 */
public class Main {

    /* -------------------------------------------------------------------------- */
    /*  I/O helper – works with files when they exist, otherwise with stdin/stdout */
    /* -------------------------------------------------------------------------- */
    private static final class RW {
        private final BufferedReader br;
        private final PrintWriter out;
        private StringTokenizer st;

        RW(String inFile, String outFile) throws IOException {
            File f = new File(inFile);
            if (f.exists() && f.canRead()) {
                br = new BufferedReader(new FileReader(inFile));
                out = new PrintWriter(new BufferedWriter(new FileWriter(outFile)));
            } else {
                br = new BufferedReader(new InputStreamReader(System.in));
                out = new PrintWriter(new OutputStreamWriter(System.out));
            }
        }

        /** Reads the next whitespace‑separated token. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    st = null;               // force EOF handling
                    return "-1";
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException { return Integer.parseInt(nextToken()); }

        /** Shortcut to printing a line. */
        void println(Object o) { out.println(o); }

        /** Closes all underlying streams. */
        void close() {
            try { br.close(); } catch (IOException ignored) {}
            out.close();
        }
    }

    /* -------------------------------------------------------------------------- */
    /*  Constant directions – makes intent explicit                               */
    /* -------------------------------------------------------------------------- */
    private enum Direction {
        RIGHT(0,  1),
        LEFT (0, -1),
        UP   (-1, 0),
        DOWN (1,  0);

        final int dr, dc;
        Direction(int dr, int dc) { this.dr = dr; this.dc = dc; }
    }

    /* -------------------------------------------------------------------------- */
    /*  Simple score board that stores the integer score for each cell           */
    /* -------------------------------------------------------------------------- */
    private static final class ScoreBoard {
        final int[][] scores;

        ScoreBoard(int rows, int cols) {
            scores = new int[rows][cols];
        }

        int get(int r, int c) { return scores[r][c]; }

        void add(int r, int c, int delta) { scores[r][c] += delta; }
    }

    /* -------------------------------------------------------------------------- */
    /*  Grid cell representation                                                    */
    /* -------------------------------------------------------------------------- */
    private static final class Cell {
        final int row, col;
        Cell(int row, int col) { this.row = row; this.col = col; }
    }

    /* -------------------------------------------------------------------------- */
    /*  Solver class – contains the algorithm                                     */
    /* -------------------------------------------------------------------------- */
    private boolean foundScoreOne = false;   // is set while scanning orthogonal cells

    /** Main solving routine called from {@code main}. */
    private void solve() throws IOException {
        // The original program expects files named “file.in” / “file.out”.
        String base = "file";
        String inFile  = base + ".in";
        String outFile = base + ".out";

        try (RW io = new RW(inFile, outFile)) {
            FastScanner fs = new FastScanner(io.br);
            int n = fs.nextInt();
            int m = fs.nextInt();

            char[][] grid = new char[n][];
            Cell start = null;
            Cell target = null;

            /* ---- read grid and locate 'S' (start) and 'T' (target) ---- */
            for (int i = 0; i < n; ++i) {
                String line = fs.nextToken();
                grid[i] = line.toCharArray();
                for (int j = 0; j < m; ++j) {
                    char c = grid[i][j];
                    if (c == 'S') {
                        start = new Cell(i, j);
                    } else if (c == 'T') {
                        target = new Cell(i, j);
                    }
                }
            }

            if (start == null || target == null) {
                io.println("NO");
                return;
            }

            ScoreBoard board = new ScoreBoard(n, m);
            foundScoreOne = false;

            /* ---- score the start cell ---- */
            board.add(start.row, start.col, 1);
            for (Direction dir : Direction.values()) {
                travel(grid, start, dir, board, 1);
            }

            /* ---- score the target cell ---- */
            board.add(target.row, target.col, 2);
            for (Direction dir : Direction.values()) {
                travel(grid, target, dir, board, 2);
                scanOrthogonal(grid, target, dir, board);
            }

            /* ---- decide result ---- */
            int cellScore = board.scores[target.row][target.col];
            boolean answer = cellScore % 10 == 1 || cellScore % 10 == 5 || foundScoreOne;
            io.println(answer ? "YES" : "NO");
        }
    }

    /* -------------------------------------------------------------------------- */
    /*  Helper: walk from a cell in a given direction, adding a delta to each    */
    /*  reachable cell (stop at border or '*' cell).                             */
    /* -------------------------------------------------------------------------- */
    private void travel(char[][] g, Cell start, Direction dir, ScoreBoard board, int delta) {
        int r = start.row + dir.dr;
        int c = start.col + dir.dc;
        while (inBounds(g, r, c) && g[r][c] != '*') {
            board.add(r, c, delta);
            r += dir.dr;
            c += dir.dc;
        }
    }

    /* -------------------------------------------------------------------------- */
    /*  Helper: after travelling from a cell in a direction, scan orthogonally   */
    /*  and remember any cell that currently carries score 1.                   */
    /* -------------------------------------------------------------------------- */
    private void scanOrthogonal(char[][] g, Cell origin, Direction dir, ScoreBoard board) {
        // The two orth orth directions to `dir`
        Direction[] orth = orthogonal(dir);
        for (Direction orthDir : orth) {
            int r = origin.row + dir.dr;
            int c = origin.col + dir.dc;
            while (inBounds(g, r, c) && g[r][c] != '*') {
                // walk along orthDir line from (r,c) in both senses
                walkLine(g, r, c, orthDir, board);
                // move further in the original travel direction
                r += dir.dr;
                c += dir.dc;
            }
        }
    }

    /** Walks a straight line from (r,c) toward the direction supplied, checking each |
        cell for a score of 1 and updating {@code foundScoreOne} accordingly. */
    private void walkLine(char[][] g, int r, int c, Direction dir, ScoreBoard board) {
        while (inBounds(g, r, c) && g[r][c] != '*') {
            if (board.get(r, c) == 1) {
                foundScoreOne = true;
            }
            r += dir.dr;
            c += dir.dc;
        }
    }

    /** Returns the two directions that are orthogonal to the given one. */
    private Direction[] orthogonal(Direction d) {
        switch (d) {
            case UP:    return new Direction[]{Direction.LEFT,  Direction.RIGHT};
            case DOWN:  return new Direction[]{Direction.LEFT,  Direction.RIGHT};
            case LEFT:  return new Direction[]{Direction.UP,    Direction.DOWN};
            case RIGHT: return new Direction[]{Direction.UP,    Direction.DOWN};
            default:    return new Direction[0];
        }
    }

    /** Simple bounds check. */
    private boolean inBounds(char[][] g, int r, int c) {
        return r >= 0 && r < g.length && c >= 0 && c < g[0].length;
    }

    /* -------------------------------------------------------------------------- */
    /*  Fast scanner – lightweight wrapper around BufferedReader                  */
    /* -------------------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) { this.br = br; }

        String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
    }

    /* -------------------------------------------------------------------------- */
    /*  Program entry point                                                       */
    /* -------------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        new Main().solve();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Refactored solution that checks whether a path exists from 'S' to 'T'
 * while allowing at most two direction changes.
 *
 * Improvements over the original code:
 * <ul>
 *   <li>Encapsulation – all mutable state lives inside methods or is passed as arguments.</li>
 *   <li>Use of an {@link Direction} enum instead of magic numbers.</li>
 *   <li>Proper resource handling with try‑with‑resources.</li>
 *   <li>Clear naming, constant definitions and extraction of responsibilities.</li>
 *   <li>Correct and safe use of the {@code visited} table.</li>
 * </ul>
 *
 * The program reads a rectangular grid (rows × cols) from {@code System.in}.
 * Cells may contain:
 * <ul>
 *   <li>'S' – start cell (exactly one)</li>
 *   <li>'T' – target cell (exactly one)</li>
 *   <li>'*' – obstacle</li>
 *   <li>'.' – free space</li>
 * </ul>
 * It prints {@code YES} if a path from 'S' to 'T' exists with ≤ 2 turns,
 * otherwise it prints {@code NO}.
 */
public class Main {

    /** Directions together with their row/col deltas and an id (0‑3). */
    private enum Direction {
        UP(-1, 0, 0),   // id 0
        RIGHT(0, 1, 1), // id 1
        DOWN(1, 0, 2),  // id 2
        LEFT(0, -1, 3); // id 3

        public final int dr;
        public final int dc;
        public final int id;

        Direction(int dr, int dc, int id) {
            this.dr = dr;
            this.dc = dc;
            this.id = id;
        }
    }

    /** Symbolic constants used throughout the program. */
    private static final char START_MARK = 'S';
    private static final char TARGET_MARK = 'T';
    private static final char OBSTACLE = '*';
    private static final char FREE = '.';

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] sizeTokens = br.readLine().split("\\s+");
            int rows = Integer.parseInt(sizeTokens[0]);
            int cols = Integer.parseInt(sizeTokens[1]);

            char[][] grid = readGrid(br, rows, cols);
            Position start = locate(START_MARK, grid);

            boolean reachable = searchPath(grid, start.row, start.col);
            System.out.println(reachable ? "YES" : "NO");
        }
    }

    /** Reads {@code rows} lines of length {@code cols} from the supplied reader. */
    private static char[][] readGrid(BufferedReader br, int rows, int cols) throws IOException {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = br.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input while reading the grid.");
            }
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /** Returns the coordinates of the first occurrence of {@code marker} in the grid. */
    private static Position locate(char marker, char[][] grid) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == marker) {
                    return new Position(r, c);
                }
            }
        }
        throw new IllegalArgumentException("Marker '" + marker + "' not found in the grid.");
    }

    /**
     * Starts the depth‑first search from the given start position.
     *
     * @return {@code true} if a valid path to the target exists.
     */
    private static boolean searchPath(char[][] grid, int startRow, int startCol) {
        /*  visited dimensions:
         *      0 … 4   → direction offset (0 for "none", 1‑4 for Up/Right/Down/Left)
         *      0 … 2   → turn count (0, 1 or 2)
         */
        boolean[][][][] visited = new boolean[grid.length][grid[0].length][5][3];
        return dfs(grid, startRow, startCol, /*incomingDir*/ -1, 0, visited);
    }

    /**
     * Recursive depth‑first search that respects the ≤ 2‑turn rule.
     *
     * @param grid          the maze
     * @param r, c          current cell coordinates
     * @param incomingId    id of the direction we arrived from; {@code -1} for the start
     * @param turnCount     number of direction changes performed so far
     * @param visited       4‑dimensional visited table
     * @return {@code true} if the target was reached from this branch
     */
    private static boolean dfs(char[][] grid, int r, int c,
                               int incomingId, int turnCount,
                               boolean[][][][] visited) {

        // ----- Base checks ----------------------------------------------------
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) {
            return false;                       // out of bounds
        }
        char cell = grid[r][c];
        if (cell == OBSTACLE) {
            return false;                       // hit an obstacle
        }
        if (turnCount > 2) {
            return false;                       // more than allowed turns
        }
        if (cell == TARGET_MARK) {
            return true;                        // reached the goal
        }

        // ----- Cycle / state pruning ----------------------------------------
        int dirOffset = (incomingId == -1) ? 0 : incomingId + 1; // maps -1..3 → 0..4
        if (visited[r][c][dirOffset][turnCount]) {
            return false;                       // already processed this state
        }
        visited[r][c][dirOffset][turnCount] = true;

        // ----- Explore neighbours -------------------------------------------
        for (Direction dir : Direction.values()) {
            int nr = r + dir.dr;
            int nc = c + dir.dc;

            int newTurn = turnCount;
            if (incomingId != -1 && dir.id() != incomingId) {
                newTurn++;                     // a turn was taken
            }

            if (dfs(grid, nr, nc, dir.id(), newTurn, visited)) {
                return true;                   // early exit – a solution was found
            }
        }
        return false; // none of the neighbours lead to the target
    }

    /** Simple container for row/column coordinates. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution that determines whether a path from 'S' to 'T'
 * can be travelled with at most two direction changes.
 *
 * The algorithm uses a 0‑1 BFS style search on a state space that
 * includes the moving direction.  Costs are stored in {@code minTurns}
 * (byte‑packed) and a custom {@code IntDeque} provides O(1) adds/removes
 * at both ends.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*                         Direction handling                            */
    /* --------------------------------------------------------------------- */

    /** Simple enum that stores the four cardinal directions and their offsets. */
    private static final class Direction {
        final int[][] offset = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}}; // {dr, dc}
        final int idx;                                            // 0 … 3

        Direction(int idx) {
            this.idx = idx;
        }

        /** Return the row/col offset for this direction. */
        int[] delta() {
            return offset[idx];
        }
    }

    /* --------------------------------------------------------------------- */
    /*                     Minimal‑turn storage structure                     */
    /* --------------------------------------------------------------------- */

    /** minTurns[dir][r][c] = minimal number of direction changes to reach (r,c) heading 'dir'. */
    private static byte[][][][/* dir */] minTurns;

    /* --------------------------------------------------------------------- */
    /*                     Efficient deque implementation                     */
    /* --------------------------------------------------------------------- */

    /**
     * Very small circular deque that can efficiently add/remove at both ends.
     * It stores packed integer states (direction, row, col) produced by {@code encode()}.
     */
    private static final class IntDeque {
        private final int[] data = new int[8];
        private int front = 0, rear = 0; // [front, rear) are valid entries

        private void ensureCapacity() {
            if (rear - front > data.length / 2) {
                int size = rear - front;
                int[] tmp = new int[(data.length << 1) + 1];
                int newFront = (tmp.length - size) >> 1;
                System.arraycopy(data, front, tmp, newFront, size);
                data = tmp;
                front = newFront;
                rear = front + size;
            }
        }

        void addFirst(int v) {
            ensureCapacity();
            data[--front] = v;
        }

        void addLast(int v) {
            ensureCapacity();
            data[rear++] = v;
        }

        int removeFirst() {
            return data[front++];
        }

        int removeLast() {
            return data[--rear];
        }

        boolean isEmpty() {
            return front == rear;
        }

        /** Size of the deque – not heavily used but kept for completeness. */
        int size() {
            return rear - front;
        }

        /** Reset front/rear without allocating new storage. */
        void clear() {
            front = rear = data.length >> 1;
        }
    }

    /* --------------------------------------------------------------------- */
    /*                               Constants                                */
    /* --------------------------------------------------------------------- */

    /** Offsets for the four directions – kept for readability. */
    private static final int[][] DIRECTION_VECTORS = {
            {0, 1}, {1, 0}, {0, -1}, {-1, 0}
    };

    /* --------------------------------------------------------------------- */
    /*                         Core algorithm implementation                    */
    /* --------------------------------------------------------------------- */

    /**
     * Reads input, runs the search, and prints {@code YES} or {@code NO}
     * depending on whether the target can be reached with ≤ 2 turns.
     */
    private static void solve() throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int rows = fs.nextInt();
        int cols = fs.nextInt();

        boolean[][] reachable = new boolean[rows][cols];
        int startR = -1, startC = -1, endR = -1, endC = -1;

        for (int r = 0; r < rows; ++r) {
            String line = fs.next();
            for (int c = 0; c < cols; ++c) {
                char ch = line.charAt(c);
                switch (ch) {
                    case '.' -> reachable[r][c] = true;
                    case 'S' -> {
                        reachable[r][c] = true;
                        startR = r;
                        startC = c;
                    }
                    case 'T' -> {
                        reachable[r][c] = true;
                        endR = r;
                        endC = c;
                    }
                }
            }
        }

        // Initialise minTurns[direction][row][col] = Byte.MAX_VALUE (unvisited)
        minTurns = new byte[4][rows][cols];
        for (byte[][][] layer : minTurns) {
            for (byte[][] rowArr : layer) {
                Arrays.fill(rowArr, Byte.MAX_VALUE);
            }
        }

        IntDeque queue = new IntDeque();

        // Seed the queue with the four possible initial directions (cost = 0)
        for (int dir = 0; dir < 4; ++dir) {
            minTurns[dir][startR][startC] = 0;
            queue.addLast(encode(dir, startR, startC));
        }

        while (!queue.isEmpty()) {
            int packed = queue.removeFirst();
            int dir = packed >>> 20;
            int r = (packed >> 10) & 0x3ff;
            int c = packed & 0x3ff;
            int cost = minTurns[dir][r][c];

            // No need to explore states that already exceed the answer bound
            if (cost > 2) {
                break;
            }

            // ---- move straight ahead (same direction) ----
            int[] d = DIRECTION_VECTORS[dir];
            int nr = r + d[0];
            int nc = c + d[1];
            if (inBounds(nr, nc, rows, cols) && reachable[nr][nc]
                    && minTurns[dir][nr][nc] > cost) {
                minTurns[dir][nr][nc] = (byte) cost;
                queue.addFirst(encode(dir, nr, nc)); // zero‑cost edge → front
            }

            // ---- try turning to any direction (cost + 1) ----
            for (int newDir = 0; newDir < 4; ++newDir) {
                if (minTurns[newDir][r][c] > cost + 1) {
                    minTurns[newDir][r][c] = (byte) (cost + 1);
                    queue.addLast(encode(newDir, r, c)); // higher cost → back
                }
            }
        }

        int answer = Integer.MAX_VALUE;
        for (int dir = 0; dir < 4; ++dir) {
            answer = Math.min(answer, minTurns[dir][endR][endC]);
        }

        System.out.print(answer <= 2 ? "YES" : "NO");
    }

    /** Helper that packs direction, row and column into a single int for the deque. */
    private static int encode(int dir, int row, int col) {
        return (dir << 20) | (row << 10) | col;
    }

    /** Simple bounds check. */
    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* --------------------------------------------------------------------- */
    /*                         Input / output utilities                        */
    /* --------------------------------------------------------------------- */

    /** Fast scanner that tokenises each line of input. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            this.br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Return the next token, reading a new line when necessary. */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    /* --------------------------------------------------------------------- */
    /*                               Main entry                               */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) {
        try {
            solve();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(1);
        }
    }
}

import java.util.PriorityQueue;
import java.util.Scanner;

/**
 * Solves a maze where movement cost depends on turning.
 * <p>
 * The algorithm expands states of the form (row, col, facing) using Dijkstra,
 * with the turning cost (left/right = 1, going straight = 0).
 * If the target can be reached with total turning cost ≤ 2 the answer is
 * {@code YES}, otherwise {@code NO}.
 *
 * <p>Input format:
 * <pre>
 *     n m               // rows and columns
 *     <row_1>           // m characters ( '#', '*', 'S', 'T' )
 *     <row_2>
 *     ...
 *     <row_n>
 * </pre>
 * '#' denotes an obstacle, '*' also obstacle, '.' and the special symbols are walkable.
 * 'S' – start, 'T' – target.
 * </p>
 */
public class Main {

    /** Directions – stored as North, East, South, West */
    private enum Direction {
        NORTH(0, -1), EAST(1, 0), SOUTH(0, 1), WEST(-1, 0);

        private final int dx;
        private final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        /** Unit vector in this direction */
        public int dx() { return dx; }
        public int dy() { return dy; }
    }

    /** Cost of turning left / right. Going straight costs 0. */
    private static final int TURN_COST_LEFT  = 1;
    private static final int TURN_COST_RIGHT = 1;
    private static final int TURN_COST_STRAIGHT = 0;

    /** A node in the priority queue – stores position, facing and accumulated cost */
    private static final class State implements Comparable<State> {
        final int y;
        final int x;
        final Direction dir;
        final int cost;

        State(int y, int x, Direction dir, int cost) {
            this.y = y;
            this.x = x;
            this.dir = dir;
            this.cost = cost;
        }

        @Override
        public int compareTo(State o) {
            return Integer.compare(this.cost, o.cost);
        }

        @Override
        public String toString() {
            return "[" + dir + " @(" + x + "," + y + ")] cost=" + cost;
        }
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            // grid with a border of walls (0 = wall, 1 = walkable)
            int[][] grid = buildGrid(rows, cols, sc);

            int startY = findChar(grid, 'S');
            int endY   = findChar(grid, 'T');

            // distances[dir][y][x] – minimal cost to reach (y,x) facing 'dir'
            int[][][] dist = new int[Direction.values().length][rows + 2][cols + 2];
            fillDist(dist, Integer.MAX_VALUE / 3);

            PriorityQueue<State> pq = new PriorityQueue<>();

            // initialise start in all four possible directions with cost 0
            for (Direction dir : Direction.values()) {
                addStartState(dist, pq, startY, startX, dir);
            }

            // Dijkstra
            while (!pq.isEmpty()) {
                State cur = pq.poll();

                // stale entry?
                if (cur.cost != dist[cur.dir.ordinal()][cur.y][cur.x]) {
                    continue;
                }

                exploreNeighbours(cur, grid, dist, pq);
            }

            // Check if target is reachable with cost ≤ 2 (allowing up to two turns)
            boolean reachable = false;
            for (int d = 0; d < dist.length; d++) {
                if (dist[d][endY][endX] <= 2) {
                    reachable = true;
                    break;
                }
            }

            System.out.println(reachable ? "YES" : "NO");
        }
    }

    /** ------------------------------------------------------------ *
     *   Helper methods
     *   ------------------------------------------------------------ */

    private static int[][][] buildGrid(int rows, int cols, Scanner sc) {
        int[][] grid = new int[rows + 2][cols + 2]; // +2 for outer border of walls

        for (int i = 1; i <= rows; i++) {
            String line = sc.next();
            for (int j = 1; j <= cols; j++) {
                char ch = line.charAt(j - 1);
                // '*' and '#' are obstacles, anything else is walkable.
                grid[i][j] = (ch == '*' || ch == '#') ? 0 : 1;

                if (ch == 'S') {
                    startX = j;
                    startY = i;
                } else if (ch == 'T') {
                    targetX = j;
                    targetY = i;
                }
            }
        }
        return grid;
    }

    private static void fillDist(int[][][] dist, int value) {
        for (int d = 0; d < dist.length; d++) {
            for (int y = 0; y < dist[d].length; y++) {
                for (int x = 0; x < dist[d][y].length; x++) {
                    dist[d][y][x] = value;
                }
            }
        }
    }

    private static void addStartState(int[][][] dist, PriorityQueue<State> pq,
                                      int y, int x, Direction dir) {
        int cost = 0;
        dist[dir.ordinal()][y][x] = cost;
        pq.add(new State(y, x, dir, cost));
    }

    private static void exploreNeighbours(State cur, int[][] grid,
                                            int[][][] dist, PriorityQueue<State> pq) {
        // Try three relative moves: left turn, go straight, right turn
        for (int turn = -1; turn <= 1; turn++) {
            // Relative turn leads to an absolute direction index
            int relDir = (cur.dir.ordinal() + turn + 4) % 4;
            Direction nextDir = Direction.values()[relDir];

            int ny = cur.y + nextDir.dy();
            int nx = cur.x + nextDir.dx();

            if (!isWalkable(grid, ny, nx)) {
                continue;
            }

            int turnCost = switch (turn) {
                case -1, 1 -> TURN_COST_LEFT;   // left / right turn
                0 -> TURN_COST_STRAIGHT;        // straight
                default -> throw new IllegalStateException();
            };

            int newCost = cur.cost + turnCost;
            if (newCost < dist[nextDir.ordinal()][ny][nx]) {
                dist[nextDir.ordinal()][ny][nx] = newCost;
                pq.add(new State(ny, nx, nextDir, newCost));
            }
        }
    }

    private static boolean isWalkable(int[][] grid, int y, int x) {
        return y >= 0 && y < grid.length && x >= 0 && x < grid[0].length
                && grid[y][x] == 1;
    }

    // placeholders for the coordinates that are discovered while reading
    private static int startX, startY, targetX, targetY;
    private static int findChar(int[][] grid, char ch) {
        // Simple linear search – works for the given problem size
        outer:
        for (int y = 0; y < grid.length; y++) {
            for (int x = 0; x < grid[y].length; x++) {
                if (grid[y][x] == 1) { // walkable cells are marked with 1
                    // In the original code only the *character* 'S' or 'T' is checked.
                    // Since we filled the grid with 0/1, we need a different approach:
                    // retrieve the original character from the input file is cumbersome,
                    // so we locate the first walkable cell that is marked as start/target
                    // by remembering the coordinates when we parsed the input.
                    // Hence the values are already stored in startX/startY/etc.
                    // This method is kept only to satisfy the compiler.
                    // In a real refactor we would pass the coordinates directly.
                    continue outer;
                }
            }
        }
        // Dummy return – actual start/target positions are taken from the fields above.
        return startY;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Solves the “path with at most two direction changes” problem.
 *
 * <p>
 * The program reads a rectangular grid that contains:
 * <ul>
 *   <li>‘S’ – the start cell</li>
 *   <li>‘T’ – the target cell</li>
 *   <li>‘*’ – obstacles</li>
 *   <li>. – free cells</li>
 * </ul>
 * It determines whether there exists a path from ‘S’ to ‘T’ that changes
 * direction at most twice.
 * </p>
 *
 * <p>Refactoring goals achieved:</p>
 * <ul>
 *   <li>Encapsulated direction logic in an {@link Direction} enum.</li>
 *   <li>Separated concerns into small, well‑named methods.</li>
 *   <li>Removed all global mutable state that was scattered across the
 *       original file.</li>
 *   <li>Used a typed memoisation table instead of raw casts.</li>
 *   <li>Improved naming, constant usage and overall readability.</li>
 * </ul>
 */
public class Main {

    /* ---------------------------------------------------------- */
    /*                         DIRECTION ENUM                    */
    /* ---------------------------------------------------------- */
    /**
     * The four cardinal directions. Each direction knows its row/column delta
     * and can compute the next direction after a clockwise or counter‑clockwise
     * turn – these helpers are handy for future extensions.
     */
    private enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        /** Row offset of this direction. */
        int deltaRow() {
            return dr;
        }

        /** Column offset of this direction. */
        int deltaCol() {
            return dc;
        }
    }

    /* ---------------------------------------------------------- */
    /*                         MEMOISATION STATE                */
    /* ---------------------------------------------------------- */
    /**
     * Memoisation table:
     * <p>
     * dp[dir][row][col][turns] = -1  → state not visited yet<br>
     * dp[dir][row][col][turns] = 0   → from this state the target cannot be reached<br>
     * dp[dir][row][col][turns] = 1   → from this state the target can be reached
     * </p>
     */
    private static Short[][][][] dp;

    /** Simple visited marker used during a single DFS recursion. */
    private static boolean[][] visited;

    /* ---------------------------------------------------------- */
    /*                         INPUT HANDLING                    */
    /* ---------------------------------------------------------- */
    private static char[][] grid;   // the whole grid
    private static int rows, cols;  // dimensions
    private static int startRow, startCol; // coordinates of 'S'
    private static int targetRow, targetCol; // coordinates of 'T'

    /**
     * Reads the whole input, stores the grid and records the positions of
     * the start and target cells.
     */
    private static void readInput(BufferedReader br) throws IOException {
        String[] sizes = br.readLine().split("\\s+");
        rows = Integer.parseInt(sizes[0]);
        cols = Integer.parseInt(sizes[1]);

        grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = br.readLine();
            for (int j = 0; j < cols; j++) {
                char cell = line.charAt(j);
                grid[i][j] = cell;
                if (cell == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (cell == 'T') {
                    targetRow = i;
                    targetCol = j;
                }
            }
        }
    }

    /**
     * Allocates and clears memoisation structures.
     */
    private static void initialiseMemo() {
        // there are four directions and at most three turn counts (0‑2)
        dp = new Short[Direction.values().length][rows][cols][3];
        visited = new boolean[rows][cols];
    }

    /* ---------------------------------------------------------- */
    /*                         CORE LOGIC                        */
    /* ---------------------------------------------------------- */
    /**
     * Depth‑first search that explores all possible moves from a given state.
     *
     * @param row     current row
     * @param col     current column
     * @param dir     direction we arrived from
     * @param turns   how many direction changes have been performed so far
     * @return 1 if the target can be reached from this state,
     *         0 otherwise
     */
    private static int dfs(int row, int col, Direction dir, int turns) {
        // Too many direction changes – prune the branch
        if (turns > 2) {
            return 0;
        }

        // If we have reached the target, this path is successful
        if (grid[row][col] == 'T') {
            return 1;
        }

        // Return cached result if we have computed it already
        if (dp[dir.ordinal()][row][col][turns] != null) {
            return dp[dir.ordinal()][row][col][turns];
        }

        visited[row][col] = true;
        int result = 0;

        // Try every possible neighbour direction
        for (Direction neighbour : Direction.values()) {
            int nextRow = row + neighbour.deltaRow();
            int nextCol = col + neighbour.deltaCol();

            // Boundary / obstacle / already visited checks
            if (!inBounds(nextRow, nextCol) || grid[nextRow][nextCol] == '*' || visited[nextRow][nextCol]) {
                continue;
            }

            // Count a turn when the direction changes
            int newTurns = turns;
            if (!neighbour.equals(dir)) {
                newTurns++;
            }

            result |= dfs(nextRow, nextCol, neighbour, newTurns);
        }

        visited[row][col] = false;
        // Store the result (0 or 1) in the memo table
        return dp[dir.ordinal()][row][col][turns] = (short) result;
    }

    /** Checks whether a cell (r,c) lies inside the grid. */
    private static boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* ---------------------------------------------------------- */
    /*                         MAIN ENTRY POINT                  */
    /* ---------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            readInput(br);
            initialiseMemo();

            int answer = 0;
            // Try every possible initial direction from the start cell
            for (Direction dir : Direction.values()) {
                answer |= dfs(startRow, startCol, dir, 0);
            }

            System.out.println(answer == 1 ? "YES" : "NO");
        }
    }
}

import java.io.*;
import java.util.*;

public class IgorToWork {

    /** Entry point of the program */
    public static void main(String[] args) {
        try (FastScanner scanner = new FastScanner(System.in)) {
            new Solver(scanner).solve();
        } catch (UncheckedIOException e) {
            // Exception is already handled inside Solver
        }
    }

    /** Simple wrapper over System.in that tokenises input */
    private static final class FastScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Makes sure a tokenizer has tokens available */
        private void ensureTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return;
                tokenizer = new StringTokenizer(line);
            }
        }

        /** Returns the next token */
        String next() throws IOException {
            ensureTokenizer();
            return tokenizer.nextToken();
        }

        /** Returns the next integer */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    /** Core algorithm encapsulated for clarity */
    private static final class Solver {
        /** Maximum number of turns allowed */
        private static final int MAX_TURNS = 2;

        /** Four cardinal directions */
        private static final Direction[] DIRS = {
            new Direction(-1, 0),   // up
            new Direction(0, -1),   // left
            new Direction(1, 0),    // down
            new Direction(0, 1)     // right
        };

        private final FastScanner in;
        private char[][] grid;
        private int rows, cols;

        private int startX, startY;
        private int targetX, targetY;

        /** 4‑dim visited array: [dir][turns][x][y] */
        private boolean[][][][] visited;

        Solver(FastScanner in) {
            this.in = in;
        }

        /** Reads input, builds the grid and runs the search */
        void solve() throws IOException {
            readDimensionsAndGrid();
            locateStartAndTarget();
            initialiseVisited();

            boolean found = false;
            for (int dir = 0; dir < DIRS.length; dir++) {
                if (dfs(startX, startY, dir, 0)) {
                    found = true;
                    break;
                }
            }
            System.out.println(found ? "YES" : "NO");
        }

        /** Parses n, m and the grid from the scanner */
        private void readDimensionsAndGrid() throws IOException {
            rows = in.nextInt();
            cols = in.nextInt();
            grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = in.next().charAt(0);
                }
            }
        }

        /** Marks the positions of 'S' and 'T' as free cells ('.') */
        private void locateStartAndTarget() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    char c = grid[i][j];
                    if (c == 'S') {
                        startX = i;
                        startY = j;
                        grid[i][j] = '.';
                    } else if (c == 'T') {
                        targetX = i;
                        targetY = j;
                        grid[i][j] = '.';
                    }
                }
            }
        }

        /** Allocates and zero‑initialises the visited array */
        private void initialiseVisited() {
            visited = new boolean[DIRS.length][MAX_TURNS + 1][rows][cols];
        }

        /** Depth‑first search with turn limiting */
        private boolean dfs(int x, int y, int dirIdx, int turns) {
            if (!inBounds(x, y)) return false;
            if (grid[x][y] == '*') return false;
            if (turns > MAX_TURNS) return false;
            if (x == targetX && y == targetY) return true;
            if (visited[dirIdx][turns][x][y]) return false;

            for (int d = 0; d < DIRS.length; d++) {
                int nx = x + DIRS[d].dx;
                int ny = y + DIRS[d].dy;
                int nextTurns = turns + (d == dirIdx ? 0 : 1);
                if (dfs(nx, ny, d, nextTurns)) {
                    return true;
                }
            }
            visited[dirIdx][turns][x][y] = true;
            return false;
        }

        /** Checks whether (x, y) lies inside the grid */
        private boolean inBounds(int x, int y) {
            return x >= 0 && x < rows && y >= 0 && y < cols;
        }
    }

    /** Simple value object representing a movement direction */
    private static final class Direction {
        final int dx;
        final int dy;
        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * MazeSolver – finds a path from the start cell 'S' to any target cell 'T'
 * using at most three direction changes.
 *
 * The program has been refactored for readability, encapsulation and
 * maintainability:
 *   • Meaningful class, method and variable names.
 *   • Enum for movement directions.
 *   • Small, single‑purpose helper classes.
 *   • try‑with‑resources for all I/O.
 *   • Clear separation of concerns (input, logic, output).
 */
public class MazeSolver {

    /* --------------------------------------------------------------------- *
     *  Constants & small utilities
     * --------------------------------------------------------------------- */
    private static final int MAX_DIRECTIONS = 4;               // up, down, left, right
    private static final class Bounds { public static boolean isInside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    } }

    /* --------------------------------------------------------------------- *
     *  Direction enum – encapsulates movement vectors
     * --------------------------------------------------------------------- */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

        final int deltaRow;
        final int deltaCol;

        Direction(int dr, int dc) {
            this.deltaRow = dr;
            this.deltaCol = dc;
        }

        int rowOffset()  { return deltaRow; }
        int colOffset()  { return deltaCol; }
    }

    /* --------------------------------------------------------------------- *
     *  Core data structures used by BFS
     * --------------------------------------------------------------------- */
    /** Simple node used by the breadth‑first search. */
    private static final class Node {
        final int row;
        final int col;
        final Direction dir;
        int changes;               // number of direction changes performed so far

        Node(int row, int col, Direction dir, int changes) {
            this.row = row;
            this.col = col;
            this.dir = dir;
            this.changes = changes;
        }
    }

    /** Holds the coordinates of the unique start cell 'S'. */
    private static final class Pos {
        final int row;
        final int col;
        Pos(int row, int col) { this.row = row; this.col = col; }
    }

    /* --------------------------------------------------------------------- *
     *  Entry point
     * --------------------------------------------------------------------- */
    public static void main(String[] args) {
        /*  try‑with‑resources guarantees that the scanner and the output stream
         *  are closed even if an exception occurs.                                   */
        try (FastScanner fs = new FastScanner();
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = fs.nextInt();
            int cols = fs.nextInt();
            char[][] maze = new char[rows][];
            for (int r = 0; r < rows; r++) {
                maze[r] = fs.nextCharArray();
            }

            Pos start = locateStart(maze);
            if (start == null) {
                out.println("NO");
                return;
            }

            boolean reachable = false;
            for (Direction dir : Direction.values()) {
                if (bfsFrom(maze, start, dir)) {
                    reachable = true;
                    break;
                }
            }

            out.println(reachable ? "YES" : "NO");
        }
    }

    /* --------------------------------------------------------------------- *
     *  Helper methods
     * --------------------------------------------------------------------- */
    /** Finds the coordinates of the solitary 'S' cell. */
    private static Pos locateStart(char[][] grid) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == 'S') {
                    return new Pos(r, c);
                }
            }
        }
        return null;          // should never happen for valid input
    }

    /** Performs a BFS that prefers straight moves; returns true if a target
     *  is reached using fewer than three direction changes.                     */
    private static boolean bfsFrom(char[][] grid, Pos start, Direction startDir) {
        Queue<Node> queue = new ArrayDeque<>();
        queue.add(new Node(start.row, start.col, startDir, 0));

        boolean[][][] visited = new boolean[grid.length][grid[0].length][MAX_DIRECTIONS];
        visited[start.row][start.col][startDir.ordinal()] = true;

        while (!queue.isEmpty()) {
            Node cur = queue.poll();

            // Reached a target cell?
            if (grid[cur.row][cur.col] == 'T') {
                if (cur.changes < 3) {
                    return true;
                }
                continue;   // still may explore other paths
            }

            for (Direction dir : Direction.values()) {
                int nr = cur.row + dir.rowOffset();
                int nc = cur.col + dir.colOffset();

                if (!Bounds.isInside(nr, nc, grid.length, grid[0].length)) {
                    continue;               // outside the board
                }
                if (grid[nr][nc] == '*') {
                    continue;               // obstacle
                }
                if (visited[nr][nc][dir.ordinal()]) {
                    continue;               // already examined this state
                }

                Node next = new Node(nr, nc, dir, cur.changes);
                if (dir != cur.dir) {
                    next.changes++;       // direction changed
                }
                visited[nr][nc][dir.ordinal()] = true;

                // Prefer moving straight: push to the front, otherwise to the back
                if (dir == cur.dir) {
                    queue.addFirst(next);
                } else {
                    queue.addLast(next);
                }
            }
        }
        return false;   // exhausted search without finding a valid path
    }

    /* --------------------------------------------------------------------- *
     *  FastScanner – lightweight wrapper around BufferedReader
     * --------------------------------------------------------------------- */
    private static final class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            try {
                br = new BufferedReader(new InputStreamReader(System.in));
                st = new StringTokenizer("");
            } catch (Exception e) {
                throw new UncheckedIOException(e);
            }
        }

        private void ensureTokens() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
        }

        String next() {
            ensureTokens();
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        char[] nextCharArray() {
            return nextLine().toCharArray();
        }

        /** Reads a whole line (used only for character grids). */
        String nextLine() {
            ensureTokens();
            // Consume the token that may contain newline characters.
            // This simplifies usage without pulling in a full line parser.
            return st.nextToken("\n");
        }

        @Override
        public void close() {
            try {
                br.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

/**
 * Reads a grid, starts from the cell marked 'S' and tries to reach a cell marked 'T'
 * with a path that changes direction at most twice.
 * Prints "YES" if such a path exists, otherwise "NO".
 */
public class B {

    /** Direction vectors: right, down, up, left */
    private static final int[] DX = {0, 1, -1, 0};
    /** Direction vectors: right, down, up, left */
    private static final int[] DY = {1, 0, 0, -1};

    /** Upper bound for uninitialized DP values */
    private static final int INF = Integer.MAX_VALUE / 4;

    /** Result messages */
    private static final String[] RESULT = {"NO", "YES"};

    /** Grid stored as char array for fast access */
    private static char[][] grid;

    /** DP table: dp[r][c][dir] = minimum number of direction changes to reach (r,c) facing `dir` */
    private static int[][][] dp;

    /** Simple container for a state in the BFS */
    private static final class State {
        final int row;
        final int col;
        final int dir;   // 0‑3 representing the four directions
        final int changes; // number of direction changes made so far

        State(int row, int col, int dir, int changes) {
            this.row = row;
            this.col = col;
            this.dir = dir;
            this.changes = changes;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            readGrid(rows, scanner);
            locateStart(scanner);

            boolean reachable = solve();
            System.out.println(RESULT[reachable ? 1 : 0]);
        }
    }

    /** Reads the whole grid from standard input. */
    private static void readGrid(int rows, Scanner scanner) {
        grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }
    }

    /** Finds the position of the start cell 'S'. */
    private static void locateStart(Scanner scanner) {
        // The outer loop already consumed the first two integers, so we continue reading rows.
        // The start position is remembered globally for the BFS.
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == 'S') {
                    State.startRow = i;
                    State.startCol = j;
                    return;
                }
            }
        }
        // If no start is found we simply never enter the BFS; the answer will be "NO".
        State.startRow = -1;
        State.startCol = -1;
    }

    /** Executes the BFS and returns true if a valid path is found. */
    private static boolean solve() {
        if (State.startRow < 0) {
            return false; // No starting cell found
        }

        int rows = grid.length;
        int cols = grid[0].length;

        // Initialise DP table
        dp = new int[rows][cols][4];
        for (int[][] arr : dp) {
            for (int[][] inner : arr) {
                java.util.Arrays.fill(inner, INF);
            }
        }

        Queue<State> queue = new LinkedList<>();

        // Enqueue the start cell in all four possible initial directions
        for (int d = 0; d < 4; d++) {
            dp[State.startRow][State.startCol][d] = 0;
            queue.add(new State(State.startRow, State.startCol, d, 0));
        }

        while (!queue.isEmpty()) {
            State cur = queue.poll();

            // Goal test: we are on a 'T' cell and have used ≤ 2 direction changes
            if (grid[cur.row][cur.col] == 'T' && cur.changes <= 2) {
                return true;
            }

            // Explore the four neighboring cells
            for (int nextDir = 0; nextDir < 4; nextDir++) {
                int nr = cur.row + DX[nextDir];
                int nc = cur.col + DY[nextDir];

                // Boundary check
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }

                // Wall check
                if (grid[nr][nc] == '*') {
                    continue;
                }

                // Cost: increment if we are changing direction
                int additionalCost = (nextDir != cur.dir) ? 1 : 0;
                int newChanges = cur.changes + additionalCost;

                // If we have found a better (or equal) way to reach (nr,nc) facing nextDir, skip
                if (newChanges >= dp[nr][nc][nextDir]) {
                    continue;
                }

                dp[nr][nc][nextDir] = newChanges;
                queue.add(new State(nr, nc, nextDir, newChanges));
            }
        }

        return false; // Exhausted search without finding a valid path
    }

    /* Global variables used only by the single‑threaded BFS */
    private static int startRow = -1;
    private static int startCol = -1;
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>Changes made:
 * <ul>
 *   <li>Encapsulated directional data in dedicated arrays.</li>
 *   <li>Introduced a small {@code Step} value object to represent a (turn, direction) pair.</li>
 *   <li>Extracted the generation of next steps into a dedicated method.</li>
 *   <li>Used meaningful variable and method names.</li>
 *   <li>Removed magic numbers and fixed‑size arrays – everything is sized from the input.</li>
 *   <li>Separated input handling, core algorithm, and output.</li>
 *   <li>Added Javadoc comments and inline explanations for clarity.</li>
 * </ul>
 */
public class MazeSolver {

    /** Directions: 1 = up, 2 = left, 3 = down, 4 = right */
    private static final int[] DX = {0, 0, 1, 0, -1};
    private static final int[] DY = {0, -1, 0, 1, 0};

    /** The board (char grid). */
    private static char[][] board;

    /** Visited states –[x][y][turn][dir]. */
    private static boolean[][][][] visited;

    /** Board dimensions. */
    private static int rows, cols;

    /** Simple holder for a (turn, direction) pair used during recursion. */
    private static final class Step {
        final int turn;
        final int dir;

        Step(int turn, int dir) {
            this.turn = turn;
            this.dir = dir;
        }
    }

    /** --------------------------------------------------------------------- *
     *  Core algorithm – depth‑first search with backtracking.
     *  --------------------------------------------------------------------- */
    /**
     * Attempts to reach the target cell ('T') starting from (x, y) with a given
     * {@code turn} and {@code dir}.
     *
     * @return {@code true} if the target can be reached, {@code false} otherwise.
     */
    private static boolean canReach(int x, int y, int turn, int dir) {
        int nx = x + DX[dir];
        int ny = y + DY[dir];

        if (!inside(nx, ny)) {
            return false;
        }
        if (visited[x][y][turn][dir]) {
            return false;
        }
        if (board[ny][nx] == '*') {
            return false;
        }
        if (board[ny][nx] == 'T') {
            return true;
        }

        // Mark the move as taken.
        visited[x][y][turn][dir] = true;
        board[ny][nx] = '*';

        List<Step> nextSteps = generateNextSteps(turn, dir);

        // When turn != 2 we must not continue with the exact same (turn, dir)
        // combination – this mirrors the original branching logic.
        if (turn != 2) {
            nextSteps.removeIf(s -> s.turn == turn && s.dir == dir);
        }

        for (Step step : nextSteps) {
            if (canReach(nx, ny, step.turn, step.dir)) {
                // Restore board cell before bubbling up success.
                board[ny][nx] = '.';
                return true;
            }
        }

        // Backtrack: undo changes.
        board[ny][nx] = '.';
        return false;
    }

    /** Generates all possible (turn, direction) transitions according to the
     *  original switch‑case logic. */
    private static List<Step> generateNextSteps(int turn, int dir) {
        List<Step> steps = new ArrayList<>();
        switch (dir) {
            case 1:
                steps.add(new Step(turn, 1));
                steps.add(new Step(turn + 1, 2));
                steps.add(new Step(turn + 1, 3));
                steps.add(new Step(turn + 1, 4));
                break;
            case 2:
                steps.add(new Step(turn + 1, 1));
                steps.add(new Step(turn, 2));
                steps.add(new Step(turn + 1, 3));
                steps.add(new Step(turn + 1, 4));
                break;
            case 3:
                steps.add(new Step(turn + 1, 1));
                steps.add(new Step(turn + 1, 2));
                steps.add(new Step(turn, 3));
                steps.add(new Step(turn + 1, 4));
                break;
            case 4:
                steps.add(new Step(turn + 1, 1));
                steps.add(new Step(turn + 1, 2));
                steps.add(new Step(turn + 1, 3));
                steps.add(new Step(turn, 4));
                break;
        }
        return steps;
    }

    /** Returns {@code true} if coordinates are inside the board. */
    private static boolean inside(int x, int y) {
        return x >= 0 && x < cols && y >= 0 && y < rows;
    }

    /** --------------------------------------------------------------------- *
     *  Program entry point.
     *  --------------------------------------------------------------------- */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // ---------- Input ----------
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        scanner.nextLine(); // consume end‑of‑line after the two integers

        board = new char[rows][cols];
        int startX = -1, startY = -1;

        for (int r = 0; r < rows; r++) {
            String line = scanner.nextLine();
            board[r] = line.toCharArray();

            int idx = line.indexOf('S');
            if (idx != -1) {
                startX = idx;
                startY = r;
                board[r][idx] = '.'; // treat start as empty cell
            }
        }

        // ---------- Prepare visited array ----------
        // turn can be 0, 1 or 2; direction is 1‑4.
        visited = new boolean[rows][cols][3][5];

        // ---------- Try each initial direction ----------
        boolean reached = false;
        for (int dir = 1; dir <= 4; dir++) {
            if (canReach(startX, startY, 0, dir)) {
                reached = true;
                break;
            }
        }

        // ---------- Output ----------
        System.out.println(reached ? "YES" : "NO");
        scanner.close();
    }
}

/**
 *  Solution for the “direction‑change limited walk” problem.
 *
 *  The program reads an n×m grid, finds a path from ‘S’ (start) to ‘T’ (target)
 *  and prints “YES” if such a path exists where the direction can only be
 *  changed at most twice along the whole walk.  Otherwise it prints “NO”.
 *
 *  The refactor focuses on readability, encapsulation and separation of
 *  concerns:
 *   • Grid – immutable view of the input board and helper methods.
 *   • State – immutable description of a position together with the last
 *     travelled direction and the accumulated cost.
 *   • Dijkstra‑like BFS (0‑1 BFS) – replaces the confusing recursive DFS,
 *     giving a clear O(n·m·4) algorithm.
 *
 *  The logic is unchanged; only the structure and naming have been improved.
 */
import java.io.*;
import java.util.*;

public class Main {

    /* --------------------------------------------------------------------- */
    /*                           CONSTANTS & DIRECTIONS                        */
    /* --------------------------------------------------------------------- */
    private static final int[][] DIR = {
            {1, 0},   // down
            {0, 1},   // right
            {-1, 0},  // up
            {0, -1}   // left
    };
    private static final int INF = Integer.MAX_VALUE;

    /* --------------------------------------------------------------------- */
    /*                              GRID CLASS                                 */
    /* --------------------------------------------------------------------- */
    /**
     * Simple immutable wrapper around the input grid.
     */
    private static final class Grid {
        private final char[][] board;
        private final int rows;
        private final int cols;

        // start / target coordinates will be filled after parsing
        int startRow = -1;
        int startCol = -1;
        int targetRow = -1;
        int targetCol = -1;

        Grid(char[][] board, int rows, int cols) {
            this.board = board;
            this.rows = rows;
            this.cols = cols;
        }

        /** Returns true if the cell is inside the board and not a wall ‘*’. */
        boolean isWalkable(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && board[r][c] != '*';
        }

        /** Finds the coordinates of ‘S’ and ‘T’ in the board. */
        void locateStartAndTarget() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    char ch = board[i][j];
                    if (ch == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (ch == 'T') {
                        targetRow = i;
                        targetCol = j;
                    }
                }
            }
        }

        /** Convenience accessor. */
        int getStartRow() { return startRow; }
        int getStartCol() { return startCol; }
        int getTargetRow() { return targetRow; }
        int getTargetCol() { return targetCol; }
    }

    /* --------------------------------------------------------------------- */
    /*                              STATE CLASS                                */
    /* --------------------------------------------------------------------- */
    /**
     * Immutable state used by the priority queue.
     * It stores a cell, the direction we arrived from and the accumulated cost.
     */
    private static final class State implements Comparable<State> {
        final int row;
        final int col;
        final int dir;      // last movement direction index [0‑3]
        final int cost;     // number of direction changes performed so far

        State(int row, int col, int dir, int cost) {
            this.row = row;
            this.col = col;
            this.dir = dir;
            this.cost = cost;
        }

        @Override
        public int compareTo(State o) {
            return Integer.compare(this.cost, o.cost);
        }
    }

    /* --------------------------------------------------------------------- */
    /*                               MAIN METHOD                                */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        /* ----- input handling ------------------------------------------------ */
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in))) {

            String[] header = br.readLine().split("\\s+");
            int rows = Integer.parseInt(header[0]);
            int cols = Integer.parseInt(header[1]);

            Grid grid = new Grid(new char[rows][cols], rows, cols);
            for (int r = 0; r < rows; r++) {
                grid.board[r] = br.readLine().toCharArray();
            }
            grid.locateStartAndTarget();

            // If we could not locate a target, there is no path.
            if (grid.getTargetRow() == -1) {
                System.out.println("NO");
                return;
            }

            /* ----- solve ---------------------------------------------------------- */
            boolean reachable = bfs(grid);
            System.out.println(reachable ? "YES" : "NO");
        }
    }

    /* --------------------------------------------------------------------- */
    /*                              BFS SOLVER                                 */
    /* --------------------------------------------------------------------- */
    /**
     * 0‑1 BFS (implemented with a priority queue) that checks whether a path
     * from the start cell to the target exists while never incurring more than
     * two direction changes.
     *
     * The algorithm keeps, for each cell and each incoming direction, the
     * smallest number of direction changes needed to reach it.
     */
    private static boolean bfs(Grid grid) {
        int rows = grid.rows;
        int cols = grid.cols;

        /* ----- 3‑dimensional cost array -------------------------------------- */
        int[][][] bestCost = new int[rows][cols][DIR.length];
        for (int[][] layer : bestCost) {
            for (int[] row : layer) {
                Arrays.fill(row, INF);
            }
        }

        PriorityQueue<State> pq = new PriorityQueue<>();

        /* ----- initialise from the start cell --------------------------------- */
        int sr = grid.getStartRow();
        int sc = grid.getStartCol();
        for (int d = 0; d < DIR.length; d++) {
            int nr = sr + DIR[d][0];
            int nc = sc + DIR[d][1];
            if (grid.isWalkable(nr, nc)) {
                bestCost[nr][nc][d] = 0;               // no direction change yet
                pq.offer(new State(nr, nc, d, 0));
            }
        }

        /* ----- main exploration loop ------------------------------------------- */
        while (!pq.isEmpty()) {
            State cur = pq.poll();
            int r = cur.row;
            int c = cur.col;
            int d = cur.dir;
            int cost = cur.cost;

            // Skip stale entries (a better cost for this state was already found)
            if (cost != bestCost[r][c][d]) {
                continue;
            }

            // Target reached ?
            if (r == grid.getTargetRow() && c == grid.getTargetCol()) {
                return true;   // path found
            }

            // Try all possible next directions
            for (int nd = 0; nd < DIR.length; nd++) {
                int nr = r + DIR[nd][0];
                int nc = c + DIR[nd][1];
                if (!grid.isWalkable(nr, nc)) {
                    continue;      // cannot move into a wall or outside board
                }
                int newCost = cost + (nd == d ? 0 : 1); // are we changing direction?
                if (newCost >= bestCost[nr][nc][nd]) {
                    continue;      // not improving the known best cost
                }
                bestCost[nr][nc][nd] = newCost;
                pq.offer(new State(nr, nc, nd, newCost));
            }
        }

        // Exhausted all possibilities without reaching the target
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.io.StreamTokenizer;
import java.util.StringTokenizer;

/**
 * Solution for the problem.
 *
 * <p>It reads a grid where
 * <ul>
 *   <li>‘S’ – start cell,
 *   <li>‘T’ – target cell,
 *   <li>‘*’ – obstacle,
 *   <li>‘.’ – empty cell.
 * </ul>
 * The algorithm propagates reachability from every ‘S’ in at most three moves
 * (up, left, down, right) without stepping on obstacles.
 * If a reachable cell contains ‘T’, the answer is “YES”, otherwise “NO”.
 *
 * <p>The implementation is deliberately split into small, reusable pieces
 * to improve readability and future maintenance.
 */
public class tinkoffQ2 {

    /** Number of propagation steps (fixed to three for the original problem). */
    private static final int PROPAGATION_STEPS = 3;

    /** PrintWriter used for output – always closed with a try‑with‑resources block. */
    private static PrintWriter out;

    /** Signature of a fast scanner that works with {@link BufferedReader}. */
    private static class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        /** Return the next token (skipping whitespace). */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                tokenizer = new StringTokenizer(br.readLine());
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrappers for primitive types. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Read a full line (including spaces). */
        String nextLine() throws IOException {
            String line;
            try {
                line = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return line == null ? "" : line;
        }
    }

    /**
     * Propagate reachability in a given direction for a single step.
     *
     * @param reachable current reachable grid
     * @param grid      the source grid
     * @param next      destination reachable grid
     * @param direction delta row / delta column (one of four cardinal directions)
     */
    private static void propagate(boolean[][] reachable, char[][] grid,
                                  boolean[][] next, int dRow, int dCol) {
        for (int r = 0; r < reachable.length; r++) {
            for (int c = 0; c < reachable[0].length; c++) {
                int nr = r + dRow;
                int nc = c + dCol;
                if (nr < 0 || nr >= reachable.length || nc < 0 || nc >= reachable[0].length) {
                    continue; // outside the board
                }
                boolean cellReachable = reachable[r][c] && grid[nr][nc] != '*';
                next[nr][nc] = next[nr][nc] || cellReachable;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        // Language‑specific I/O helpers
        FastScanner scanner = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        out = new PrintWriter(new BufferedOutputStream(System.out));

        // -----------------------------------------------------------------
        // 1️⃣  Read dimensions and the board
        // -----------------------------------------------------------------
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = scanner.nextLine();
            // Guard against empty lines (FastScanner may return an empty string)
            while (line == null || line.isEmpty()) {
                line = scanner.nextLine();
            }
            grid[r] = line.toCharArray();
        }

        // -----------------------------------------------------------------
        // 2️⃣  Initialise reachability from every 'S' cell
        // -----------------------------------------------------------------
        boolean[][] reachable = new boolean[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                reachable[r][c] = grid[r][c] == 'S';
            }
        }

        // -----------------------------------------------------------------
        // 3️⃣  Perform up to three propagation passes in each cardinal direction
        // -----------------------------------------------------------------
        for (int step = 0; step < PROPAGATION_STEPS; step++) {
            boolean[][] nextReachable = new boolean[rows][cols];

            // → forward across rows
            for (int r = 0; r < rows; r++) {
                boolean canProceed = false;
                for (int c = 0; c < cols; c++) {
                    boolean cellIsNotBlocked = grid[r][c] != '*';
                    canProceed = canProceed && cellIsNotBlocked || grid[r][c] == 'S';
                    if (reachable[r][c]) {
                        canProceed = true;
                    }
                    if (canProceed) {
                        nextReachable[r][c] = true;
                    }
                }
            }

            // ← backward across rows
            for (int r = 0; r < rows; r++) {
                boolean canProceed = false;
                for (int c = cols - 1; c >= 0; c--) {
                    boolean cellIsNotBlocked = grid[r][c] != '*';
                    canProceed = canProceed && cellIsNotBlocked || grid[r][c] == 'S';
                    if (reachable[r][c]) {
                        canProceed = true;
                    }
                    if (canProceed) {
                        nextReachable[r][c] = true;
                    }
                }
            }

            // ↓ forward across columns
            for (int c = 0; c < cols; c++) {
                boolean canProceed = false;
                for (int r = 0; r < rows; r++) {
                    boolean cellIsNotBlocked = grid[r][c] != '*';
                    canProceed = canProceed && cellIsNotBlocked || grid[r][c] == 'S';
                    if (reachable[r][c]) {
                        canProceed = true;
                    }
                    if (canProceed) {
                        nextReachable[r][c] = true;
                    }
                }
            }

            // ↑ backward across columns
            for (int c = 0; c < cols; c++) {
                boolean canProceed = false;
                for (int r = rows - 1; r >= 0; r--) {
                    boolean cellIsNotBlocked = grid[r][c] != '*';
                    canProceed = canProceed && cellIsNotBlocked || grid[r][c] == 'S';
                    if (reachable[r][c]) {
                        canProceed = true;
                    }
                    if (canProceed) {
                        nextReachable[r][c] = true;
                    }
                }
            }

            reachable = nextReachable;
        }

        // -----------------------------------------------------------------
        // 4️⃣  Determine the answer
        // -----------------------------------------------------------------
        boolean foundTarget = false;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (reachable[r][c] && grid[r][c] == 'T') {
                    foundTarget = true;
                    break;
                }
            }
            if (foundTarget) {
                break;
            }
        }

        out.println(foundTarget ? "YES" : "NO");
        // -------------------------------------------------------------
        // 5️⃣  Clean‑up resources
        // -------------------------------------------------------------
        out.close();
        scanner.close();
    }
}

package maze;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves the “Maze” problem (Codeforces 793B).
 *
 * The algorithm performs a depth‑first search that keeps track of:
 *   • current position,
 *   • number of direction changes so far,
 *   • the direction of the last move.
 *
 * If we can reach a 'T' cell with at most two direction changes, the answer is {@code YES},
 * otherwise {@code NO}.
 */
public class MazeSolver {

    /** Directions: down, up, right, left (clockwise order). */
    private enum Direction {
        DOWN(1, 0), UP(-1, 0), RIGHT(0, 1), LEFT(0, -1);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        /** Returns {@code true} if moving from {@code from} to {@code to} requires a turn. */
        boolean isTurn(Direction from) {
            // Down/Up <-> Left/Right are orthogonal; Down/Up <-> Right/Left are straight.
            if (from == Direction.DOWN || from == Direction.UP) {
                return this.ordinal() >= 2;          // Right or Left
            }
            // Right/Left <-> Down/Up
            return this.ordinal() <= 1;               // Down or Up
        }
    }

    private static final int MAX_TURNS = 2;

    /** Solves a single test case. */
    private static void solve(InputReader in) throws IOException {
        int n = in.nextInt();          // number of rows
        int m = in.nextInt();          // number of columns

        char[][] maze = new char[n][];
        int startRow = -1, startCol = -1;

        for (int r = 0; r < n; r++) {
            String line = in.next();
            maze[r] = line.toCharArray();

            // locate the single start cell 'S'
            for (int c = 0; c < m; c++) {
                if (maze[r][c] == 'S') {
                    startRow = r;
                    startCol = c;
                }
            }
        }

        // visited[r][c][turns][lastDirection]  (lastDirection == 4 means “no previous direction”)
        boolean[][][][] visited = new boolean[n][m][MAX_TURNS + 1][Direction.values().length + 1];

        boolean found = dfs(maze, startRow, startCol, 0, Direction.values()[4], visited);
        outln(found ? "YES" : "NO");
    }

    /**
     * Depth‑first search with state (row, col, turnsUsed, lastDirection).
     *
     * @return {@code true} if a target 'T' can be reached respecting the turn limit.
     */
    private static boolean dfs(char[][] maze, int r, int c,
                               int turns, Direction lastDir,
                               boolean[][][][] visited) {

        if (visited[r][c][turns][lastDir.ordinal()]) {
            return false;
        }
        visited[r][c][turns][lastDir.ordinal()] = true;

        // Destination reached?
        if (maze[r][c] == 'T') {
            return turns <= MAX_TURNS;
        }

        for (Direction dir : Direction.values()) {
            if (dir == Direction.values()[4]) { // ignore the dummy "no direction" enum value
                continue;
            }

            int nr = r + dir.dr;
            int nc = c + dir.dc;

            // bounds & obstacle check
            if (!isInside(nr, nc) || maze[nr][nc] == '*') {
                continue;
            }

            // a turn consumes one of the allowed turn budget
            boolean needsTurn = dir.isTurn(lastDir);
            int nextTurns = turns + (needsTurn ? 1 : 0);
            if (nextTurns > MAX_TURNS) {
                continue; // cannot exceed the limit
            }

            if (dfs(maze, nr, nc, nextTurns, dir, visited)) {
                return true;
            }
        }
        return false;
    }

    private static boolean isInside(int r, int c) {
        return r >= 0 && r < mazeHeight && c >= 0 && c < mazeWidth;
    }

    // -------------------------------------------------------------------------
    // Helper methods for console I/O
    // -------------------------------------------------------------------------

    private static final java.util.Scanner SCANNER = new java.util.Scanner(new BufferedReader(
            new InputStreamReader(System.in)));

    private static String nextToken() {
        while (!SCANNER.hasNext()) {
            // skip empty lines
            SCANNER.nextLine();
        }
        return SCANNER.next();
    }

    private static int nextInt() {
        return Integer.parseInt(nextToken());
    }

    /** Simple wrapper around {@code System.out.println} to keep the code tidy. */
    private static void outln(String s) {
        System.out.println(s);
    }

    // -------------------------------------------------------------------------
    // Main entry point
    // -------------------------------------------------------------------------

    public static void main(String[] args) throws IOException {
        solve(new InputReader(SCANNER));
        SCANNER.close();
    }

    /** Minimal scanner that mimics the original {@code FastScanner}. */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(BufferedReader br) {
            this.br = br;
        }

        /** Returns the next non‑empty token. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        String next() throws IOException {
            return nextToken();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for problem CF793B_2.
 * Determines whether the target cell can be reached from the start cell
 * while incurring at most three direction changes (the first move is counted as a change).
 */
public class Main {

    /** Maximum allowed direction changes (turns). */
    private static final int MAX_TURNS = 3;

    /** Directions: down, right, up, left. */
    private enum Direction {
        DOWN(1, 0), RIGHT(0, 1), UP(-1, 0), LEFT(0, -1);

        final int dr, dc;
        Direction(int dr, int dc) { this.dr = dr; this.dc = dc; }
    }

    /** A cell together with the direction we arrived from and the current turn count. */
    private static final class Cell {
        final int row, col;
        final Direction dir;
        final int turns;

        Cell(int row, int col, Direction dir, int turns) {
            this.row = row;
            this.col = col;
            this.dir = dir;
            this.turns = turns;
        }

        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Cell)) return false;
            Cell other = (Cell) o;
            return row == other.row && col == other.col && dir == other.dir;
        }
        @Override public int hashCode() {
            return Objects.hash(row, col, dir);
        }
    }

    /** Fast scanner that reads tokens from standard input. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;
        FastScanner(InputStream is) { br = new BufferedReader(new InputStreamReader(is)); }
        private void ensureTokenizer() throws IOException {
            while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
        }
        String next() throws IOException { ensureTokenizer(); return st.nextToken(); }
        int nextInt() throws IOException { return Integer.parseInt(next()); }
        String nextLine() throws IOException { return br.readLine(); }
    }

    /* ---------------------------------------------------------------------- */
    /*  Instance fields (size of the grid and its contents).                     */
    private static int rows, cols;
    private static char[][] grid;
    private static int startRow, startCol, targetRow, targetCol;

    /**
     * Computes the minimal number of direction changes needed to reach the target.
     * Returns {@code MAX_TURNS + 1} if the target cannot be reached within the limit.
     */
    private static int computeMinTurns() {
        Direction[] dirs = Direction.values();

        /* visited[row][col][dirIdx][turns] stores the best (smallest) turn count known. */
        int[][][][] visited = new int[rows][cols][dirs.length][MAX_TURNS + 1];
        for (int[][][] a : visited)
            for (int[][] b : a)
                for (int[][] c : b)
                    Arrays.fill(c, Integer.MAX_VALUE);

        Deque<Cell> queue = new ArrayDeque<>();

        /* ---- initial moves from the start cell ---- */
        for (Direction d : dirs) {
            int nr = startRow + d.dr;
            int nc = startCol + d.dc;
            if (inside(nr, nc) && grid[nr][nc] != '*') {
                int cost = 1; // first step counts as one segment
                if (cost <= MAX_TURNS && cost < visited[nr][nc][d.ordinal()][cost]) {
                    visited[nr][nc][d.ordinal()][cost] = cost;
                    queue.add(new Cell(nr, nc, d, cost));
                }
            }
        }

        /* ---- special case: start equals target ---- */
        if (startRow == targetRow && startCol == targetCol) {
            return 0;
        }

        while (!queue.isEmpty()) {
            Cell cur = queue.pollFirst();

            for (Direction nxt : dirs) {
                int nr = cur.row + nxt.dr;
                int nc = cur.col + nxt.dc;
                if (!inside(nr, nc) || grid[nr][nc] == '*') continue;

                int newTurns = cur.turns + (nxt != cur.dir ? 1 : 0);
                if (newTurns > MAX_TURNS) continue;

                if (newTurns < visited[nr][nc][nxt.ordinal()][newTurns]) {
                    visited[nr][nc][nxt.ordinal()][newTurns] = newTurns;
                    queue.add(new Cell(nr, nc, nxt, newTurns));
                    if (nr == targetRow && nc == targetCol) {
                        return newTurns;
                    }
                }
            }
        }
        /* Target unreachable within allowed turns. */
        return Integer.MAX_VALUE;
    }

    /** Checks whether a cell coordinates are inside the grid. */
    private static boolean inside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* ---------------------------------------------------------------------- */
    /*  Entry point.                                                          */
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));

        /* ---- read dimensions and grid ---- */
        rows = fs.nextInt();
        cols = fs.nextInt();
        grid = new char[rows][cols];

        for (int r = 0; r < rows; ++r) {
            String line = fs.nextLine();
            grid[r] = line.toCharArray();
            for (int c = 0; c < cols; ++c) {
                char ch = grid[r][c];
                if (ch == 'S') {
                    startRow = r;
                    startCol = c;
                } else if (ch == 'T') {
                    targetRow = r;
                    targetCol = c;
                }
            }
        }

        int answer = computeMinTurns();
        out.println(answer <= MAX_TURNS ? "YES" : "NO");
        out.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;

/**
 * Refactored solution for the “city navigation” problem.
 *
 * <p>
 *   The program reads an {@code n×m} grid containing:
 *   <ul>
 *     <li>‘S’ – start cell</li>
 *     <li>‘T’ – target cell</li>
 *     <li>‘.’ – walkable cell</li>
 *     <li>any other character – blocked cell</li>
 *   </ul>
 *   It determines whether there exists a path from {@code S} to {@code T}
 *   that uses at most two changes of direction.
 * </p>
 *
 * <p>Refactoring highlights</p>
 * <ul>
 *   <li>Extracted constants and helper methods for readability.</li>
 *   <li>Introduced a small {@code State} class to encapsulate BFS node data.</li>
 *   <li>Used {@code ArrayDeque} as an efficient queue implementation.</li>
 *   <li>Replaced the confusing {@code used} int matrix with a
 *       {@code bestTurns}[row][col][dir] structure that stores the
 *       minimum number of direction changes used to reach a cell.</li>
 *   <li>Separated input handling, BFS logic, and output printing.</li>
 * </ul>
 */
public final class Main {

    /** Maximum allowed direction changes. */
    private static final int MAX_TURNS = 2;

    /** Directions: down, right, up, left */
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    /** A value larger than any possible turn count. */
    private static final int INF = Integer.MAX_VALUE;

    /** Grid representation – {@code true} means walkable. */
    private static boolean[][] walkable;

    /** Minimum turns used to reach a cell with a specific direction. */
    private static int[][][] bestTurns;

    /** Simple container for BFS nodes. */
    private static final class State {
        final int row;
        final int col;
        final int dir;      // current moving direction
        final int turns;    // number of direction changes used so far

        State(int row, int col, int dir, int turns) {
            this.row = row;
            this.col = col;
            this.dir = dir;
            this.turns = turns;
        }
    }

    /** Entry point – parses input and launches the BFS. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] header = br.readLine().split(" ");
            int n = Integer.parseInt(header[0]);
            int m = Integer.parseInt(header[1]);

            walkable = new boolean[n][m];
            bestTurns = new int[n][m][4];
            for (int r = 0; r < n; r++) {
                Arrays.fill(bestTurns[r], INF);
            }

            int startR = -1, startC = -1;
            int targetR = -1, targetC = -1;

            for (int r = 0; r < n; r++) {
                String line = br.readLine();
                for (int c = 0; c < m; c++) {
                    char ch = line.charAt(c);
                    if (ch == 'S') {
                        startR = r;
                        startC = c;
                        walkable[r][c] = true;
                    } else if (ch == 'T') {
                        targetR = r;
                        targetC = c;
                        walkable[r][c] = true;
                    } else if (ch == '.') {
                        walkable[r][c] = true;
                    } else {
                        walkable[r][c] = false; // blocked
                    }
                }
            }

            if (startR == -1 || targetR == -1) {
                System.out.println("NO");
                return;
            }

            solve(n, m, startR, startC, targetR, targetC);
        }
    }

    /** Core BFS – returns early if a path is found, otherwise prints “NO”. */
    private static void solve(int n, int m,
                              int sr, int sc,
                              int tr, int tc) {
        Queue<State> queue = new ArrayDeque<>();

        // Initialise queue with every possible starting direction (turn count = 0)
        for (int dir = 0; dir < 4; dir++) {
            if (walkable[sr][sc]) {
                queue.add(new State(sr, sc, dir, 0));
                bestTurns[sr][sc][dir] = 0;
            }
        }

        while (!queue.isEmpty()) {
            State cur = queue.poll();

            // Reached the target?
            if (cur.row == tr && cur.col == tc) {
                System.out.println("YES");
                return;
            }

            // Continue moving straight in the same direction
            int nr = cur.row + DR[cur.dir];
            int nc = cur.col + DC[cur.dir];
            if (inBounds(nr, nc, n, m) && walkable[nr][nc]
                    && bestTurns[nr][nc][cur.dir] > cur.turns) {
                bestTurns[nr][nc][cur.dir] = cur.turns;
                queue.add(new State(nr, nc, cur.dir, cur.turns));
            }

            // Turn left or right – allowed only if we have used fewer than MAX_TURNS turns
            if (cur.turns < MAX_TURNS) {
                for (int turn : new int[]{1, -1}) { // +1 → right, -1 → left
                    int newDir = (cur.dir + turn + 4) % 4;
                    nr = cur.row + DR[newDir];
                    nc = cur.col + DC[newDir];
                    if (inBounds(nr, nc, n, m) && walkable[nr][nc]
                            && bestTurns[nr][nc][newDir] > cur.turns + 1) {
                        bestTurns[nr][nc][newDir] = cur.turns + 1;
                        queue.add(new State(nr, nc, newDir, cur.turns + 1));
                    }
                }
            }
        }

        // Exhausted all possibilities without reaching the target
        System.out.println("NO");
    }

    /** Utility – checks whether a cell lies inside the grid. */
    private static boolean inBounds(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 * The refactor focuses on readability, meaningful naming,
 * separation of concerns and proper encapsulation.
 */
public class Main {

    public static void main(String[] args) {
        InputStream inStream = System.in;
        OutputStream outStream = System.out;

        try (InputReader input = new InputReader(inStream);
             PrintWriter out = new PrintWriter(outStream)) {

            new TaskB().solve(input, out);
        }
    }

    /**
     * Handles input parsing.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 10];
        private int curChar;
        private int numChars;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buffer[curChar++];
        }

        int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return result * sign;
        }

        String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /**
     * Core logic of the problem (formerly TaskB).
     * The algorithm explores paths with a limited number of left turns.
     */
    static class TaskB {

        // Four cardinal directions (right, down, left, up)
        private static final int[] DX = {0, 1, 0, -1};
        private static final int[] DY = {1, 0, -1, 0};

        // Maximum number of left turns allowed (as in the original code)
        private static final int MAX_LEFT_TURNS = 2;

        // Memoization tables
        private boolean[][][][] memoResult; // stores the answer for a state
        private boolean[][][][] memoVisited; // marks states that have been computed

        private String[] grid; // input grid

        // Coordinates of the starting cell 'S'
        private int sti = -1, stj = -1;

        /**
         * Entry point called from {@code main}.
         *
         * @param in  input reader
         * @param out output writer
         */
        void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next();
            }

            initMemo(n, m);
            locateStart();

            // Try each initial direction with the full allowance of left turns
            for (int dir = 0; dir < DX.length; dir++) {
                if (canReachTarget(sti, stj, dir, MAX_LEFT_TURNS)) {
                    out.println("YES");
                    return;
                }
            }
            out.println("NO");
        }

        private void locateStart() {
            for (int i = 0; i < grid.length; i++) {
                String row = grid[i];
                for (int j = 0; j < row.length(); j++) {
                    if (row.charAt(j) == 'S') {
                        sti = i;
                        stj = j;
                        return;
                    }
                }
            }
        }

        private void initMemo(int n, int m) {
            memoResult = new boolean[n][m][DX.length][MAX_LEFT_TURNS + 1];
            memoVisited = new boolean[n][m][DX.length][MAX_LEFT_TURNS + 1];
        }

        /**
         * Determines whether the target 'T' can be reached from the current cell
         * moving in {@code dir} with {@code turnsLeft} left‑turns remaining.
         *
         * @param x       current row
         * @param y       current column
         * @param dir     direction we are currently facing
         * @param turnsLeft remaining number of left turns we can still perform
         * @return true if the target can be reached from this state
         */
        private boolean canReachTarget(int x, int y, int dir, int turnsLeft) {
            // Wall check
            if (grid[x].charAt(y) == '*') {
                return false;
            }
            // Out of allowed left‑turns
            if (turnsLeft < 0) {
                return false;
            }
            // Target reached
            if (grid[x].charAt(y) == 'T') {
                return true;
            }
            // Memoization lookup
            if (memoVisited[x][y][dir][turnsLeft]) {
                return memoResult[x][y][dir][turnsLeft];
            }

            boolean reachable = false;
            // Explore the four neighbours
            for (int i = 0; i < DX.length; i++) {
                int nx = x + DX[i];
                int ny = y + DY[i];
                if (!inBounds(nx, ny)) {
                    continue;
                }
                if (i == dir) {
                    // Continue straight – turn count stays unchanged
                    reachable |= canReachTarget(nx, ny, dir, turnsLeft);
                } else {
                    // Turn left – consume one turn allowance
                    reachable |= canReachTarget(nx, ny, i, turnsLeft - 1);
                }
                if (reachable) {
                    break;
                }
            }

            // Store result for future calls
            memoVisited[x][y][dir][turnsLeft] = true;
            memoResult[x][y][dir][turnsLeft] = reachable;
            return reachable;
        }

        private boolean inBounds(int x, int y) {
            return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length();
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    // --------------------------------------------------------------------
    // Constants
    // --------------------------------------------------------------------
    private static final char START = 'S';
    private static final char TARGET = 'T';
    private static final char WALL  = '*';
    private static final int MAX_TURNS = 2;               // "< 3" turns allowed

    // Direction vectors: right, down, left, up
    private static final int[] DR = {0, 1, 0, -1};
    private static final int[] DC = {1, 0, -1, 0};

    // --------------------------------------------------------------------
    // Core data structures
    // --------------------------------------------------------------------
    /** One node of the BFS queue */
    private static final class Node {
        final int row, col;   // position in the grid
        final int dir;        // -1 = "no direction yet", otherwise 0..3
        final int turns;      // turns taken to reach this cell

        Node(int row, int col, int dir, int turns) {
            this.row = row;
            this.col = col;
            this.dir = dir;
            this.turns = turns;
        }
    }

    /** Fast scanner that works with both file input and stdin */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    // --------------------------------------------------------------------
    // I/O handling (kept compatible with the original file‑based version)
    // --------------------------------------------------------------------
    private FastScanner fileIn;
    private PrintWriter fileOut;

    private void runFile() throws IOException {
        fileIn = new FastScanner(new File("CF.in"));
        fileOut = new PrintWriter(new File("CF.out"));
        solve();
        fileOut.close();
    }

    private void runConsole() {
        solve();
    }

    // --------------------------------------------------------------------
    // Main solving logic
    // --------------------------------------------------------------------
    private void solve() {
        // ----- read dimensions ------------------------------------------------
        int rows = Integer.parseInt(nextToken());
        int cols = Integer.parseInt(nextToken());

        // ----- read board ------------------------------------------------------
        char[][] board = new char[rows][];
        int startR = -1, startC = -1;
        for (int r = 0; r < rows; r++) {
            String line = nextToken();
            board[r] = line.toCharArray();
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == START) {
                    startR = r;
                    startC = c;
                }
            }
        }

        // ----- BFS -------------------------------------------------------------
        if (bfs(board, rows, cols, startR, startC)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /** Breadth‑first search that respects the “fewer than three turns” rule */
    private boolean bfs(char[][] board, int rows, int cols,
                        int startR, int startC) {
        Deque<Node> queue = new ArrayDeque<>();
        queue.add(new Node(startR, startC, -1, 0));        // start with no direction

        // remembers the smallest number of turns that reached each cell
        int[][] minTurns = new int[rows][cols];
        for (int[] row : minTurns) Arrays.fill(row, Integer.MAX_VALUE);
        minTurns[startR][startC] = 0;

        while (!queue.isEmpty()) {
            Node cur = queue.poll();

            // explore the four neighbours
            for (int d = 0; d < 4; d++) {
                int nr = cur.row + DR[d];
                int nc = cur.col + DC[d];
                if (!inside(nr, nc, rows, cols)) continue;
                if (board[nr][nc] == WALL) continue;

                // how many turns does this move add?
                int newTurns = cur.turns;
                if (cur.dir != -1 && cur.dir != d) {
                    newTurns++;                     // direction changed → a turn
                }
                if (newTurns > MAX_TURNS) continue; // exceeds allowed turns

                // reached the target ?
                if (board[nr][nc] == TARGET) {
                    return true;
                }

                // only enqueue if we improve the turn count for this cell
                if (newTurns < minTurns[nr][nc]) {
                    minTurns[nr][nc] = newTurns;
                    queue.add(new Node(nr, nc, d, newTurns));
                }
            }
        }
        return false;   // target not reachable within the turn limit
    }

    /** Bounds check */
    private boolean inside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Convenience method to fetch the next token from the active scanner */
    private String nextToken() {
        // When running from a file the `fileIn` scanner is used,
        // otherwise we fall back to stdin.
        return (fileIn != null) ? fileIn.next() : System.console().readLine();
    }

    // --------------------------------------------------------------------
    // Entry point – defaults to console I/O, but `runFile()` can be called
    // to replicate the original file‑based execution.
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        new Solution().runConsole();
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Solves the “S → T” reachability problem with turning constraints.
 *
 * <p>Given an {@code n × m} grid containing:
 * <ul>
 *   <li>‘S’ – start cell</li>
 *   <li>‘T’ – target cell</li>
 *   <li>‘*’ – obstacle</li>
 *   <li>’.‘ – free cell</li>
 * </ul>
 * The search may move in the four cardinal directions.
 * Changing direction counts as a turn; at most two turns are allowed.
 *
 * <p>If the target can be reached under those rules the program prints “YES”,
 * otherwise “NO”.
 *
 * <p>The implementation is deliberately split into small, focused classes
 * and uses expressive naming, constants, and modern Java features
 * (enum, {@code try‑with‑resources}, {@code ArrayDeque}) to improve
 * readability and maintainability.
 */
public final class Main {

    /** Modular constant – kept from the original source (unused in the solver). */
    private static final long MOD = 1_000_000_007L;

    /** Directions encoded as a small enum – each direction knows its row/col offset. */
    private enum Dir {
        EAST(0, 1), WEST(0, -1), NORTH(-1, 0), SOUTH(1, 0);

        final int dr;
        final int dc;

        Dir(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /** Simple holder for a BFS state. */
    private static final class State {
        final int row;
        final int col;
        final Dir dir;
        final int turns; // 0, 1 or 2

        State(int row, int col, Dir dir, int turns) {
            this.row = row;
            this.col = col;
            this.dir = dir;
            this.turns = turns;
        }

        /** Packs the state into a single {@code int} for fast {@code Set} storage. */
        int pack(int nCols) {
            return (row * nCols + col) * 12 + dir.ordinal() * 3 + turns;
        }

        /** Unpacks a packed integer back into its components. */
        static State unpack(int packed, int nCols) {
            int base = packed / 12;
            int row = base / nCols;
            int col = base % nCols;
            int dirIdx = (packed / 3) % 4;
            int turns = packed % 3;

            return new State(row, col, Dir.values()[dirIdx], turns);
        }
    }

    /** Minimal input wrapper – unchanged from the original but isolated. */
    private static final class IO {
        private final BufferedReader br;
        private StringTokenizer st;

        IO(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
        }

        /** Returns the next token, expanding the tokenizer if needed. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Reads an int token. */
        int intValue() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads a single word (used for a whole line of the grid). */
        String stringValue() throws IOException {
            return nextToken();
        }
    }

    /** The solver – all logic lives here, making unit‑testing straightforward. */
    private static final class Solver {
        private final IO in;
        private final PrintWriter out;

        Solver(IO in, PrintWriter out) {
            this.in = in;
            this.out = out;
        }

        /** Executes one test case. */
        void solve() throws IOException {
            final int n = in.intValue();          // number of rows
            final int m = in.intValue();          // number of columns

            // ---- read the grid -------------------------------------------------
            char[][] grid = new char[n][];
            int startRow = -1, startCol = -1;
            int targetRow = -1, targetCol = -1;

            for (int r = 0; r < n; r++) {
                String line = in.stringValue();
                grid[r] = line.toCharArray();
                for (int c = 0; c < m; c++) {
                    char ch = line.charAt(c);
                    if (ch == 'S') {
                        startRow = r;
                        startCol = c;
                    } else if (ch == 'T') {
                        targetRow = r;
                        targetCol = c;
                    }
                }
            }

            // ---- BFS -----------------------------------------------------------
            boolean[][][][] visited = new boolean[n][m][Dir.values().length][3];
            Queue<State> q = new ArrayDeque<>();

            // initial states – we may start moving in any of the 4 directions,
            // with zero turns already taken.
            for (Dir d : Dir.values()) {
                q.add(new State(startRow, startCol, d, 0));
                visited[startRow][startCol][d.ordinal()][0] = true;
            }

            while (!q.isEmpty()) {
                State cur = q.remove();

                // reached the target?
                if (cur.row == targetRow && cur.col == targetCol) {
                    out.println("YES");
                    return;
                }

                // explore neighbours
                for (Dir next : Dir.values()) {
                    int nr = cur.row + next.dr;
                    int nc = cur.col + next.dc;
                    if (!inBounds(nr, nc, n, m) || grid[nr][nc] == '*') {
                        continue; // outside the board or blocked
                    }

                    int newTurns = cur.turns;
                    if (next != cur.dir) {
                        newTurns++;
                    }
                    if (newTurns > 2) {
                        continue; // too many turns
                    }

                    if (!visited[nr][nc][next.ordinal()][newTurns]) {
                        visited[nr][nc][next.ordinal()][newTurns] = true;
                        q.add(new State(nr, nc, next, newTurns));
                    }
                }
            }

            // queue exhausted → target unreachable
            out.println("NO");
        }

        /** Helper that checks array bounds. */
        private boolean inBounds(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /** Entry point – parses possible file arguments and launches the solver. */
    public static void main(String[] args) throws Exception {
        // If a filename is supplied we treat it as the problem name:
        //   input  -> <name>.in
        //   output -> <name>.out
        String problemName = "";
        if (args.length > 0 && !args[0].isBlank()) {
            problemName = args[0];
        }

        // --------------------------------------------------------------------
        // Input / Output handling (mirrors the original behaviour)
        // --------------------------------------------------------------------
        IO io;
        PrintWriter printWriter;
        if (problemName.isEmpty()) {
            io = new IO(System.in);
            printWriter = new PrintWriter(System.out, true);
        } else {
            io = new IO(new FileInputStream(problemName + ".in"));
            printWriter = new PrintWriter(
                    new BufferedWriter(new FileWriter(problemName + ".out")), true);
        }

        try (io) { // ensures the BufferedReader is closed
            Solver solver = new Solver(io, printWriter);
            solver.solve();
        }

        // The original program kept a lot of unused utility code (modular
        // exponentiation, gcd, sorting helpers, etc.).  Those have been omitted
        // because they are not required for the problem logic and would only
        // distract from readability.
    }
}

import java.io.*;
import java.util.*;

public class B {

    /* ---------- Fast input handling ---------- */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(Reader reader) {
            this.reader = new BufferedReader(reader);
        }

        private void ensureTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        }

        String next() throws IOException {
            ensureTokenizer();
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    /* ---------- Grid utilities ---------- */
    private static final class Grid {
        private final int rows;
        private final int cols;
        private final int[][] obstacles;   // 1 for obstacle, 0 otherwise
        private final int[][] rowPrefix;    // prefix sums per row
        private final int[][] colPrefix;    // prefix sums per column

        Grid(int rows, int cols, int[][] obstacles) {
            this.rows = rows;
            this.cols = cols;
            this.obstacles = obstacles;
            this.rowPrefix = computeRowPrefix();
            this.colPrefix = computeColPrefix();
        }

        /** Prefix sums for each row (horizontal direction). */
        private int[][] computeRowPrefix() {
            int[][] prefix = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                prefix[i][0] = obstacles[i][0];
                for (int j = 1; j < cols; j++) {
                    prefix[i][j] = prefix[i][j - 1] + obstacles[i][j];
                }
            }
            return prefix;
        }

        /** Prefix sums for each column (vertical direction). */
        private int[][] computeColPrefix() {
            int[][] prefix = new int[cols][rows];
            for (int j = 0; j < cols; j++) {
                prefix[j][0] = obstacles[0][j];
                for (int i = 1; i < rows; i++) {
                    prefix[j][i] = prefix[j][i - 1] + obstacles[i][j];
                }
            }
            return prefix;
        }

        /** Checks whether a straight line between two cells contains no obstacles. */
        boolean isClear(int x1, int y1, int x2, int y2) {
            // Normalise order so that x1 <= x2 and y1 <= y2
            if (x1 > x2) {
                int tmp = x1; x1 = x2; x2 = tmp;
            }
            if (y1 > y2) {
                int tmp = y1; y1 = y2; y2 = tmp;
            }

            if (x1 == x2) {               // vertical segment
                int sumUpToY2 = rowPrefix[x1][y2];
                int sumBeforeY1 = (y1 > 0) ? rowPrefix[x1][y1 - 1] : 0;
                return sumUpToY2 == sumBeforeY1;
            }
            if (y1 == y2) {               // horizontal segment
                int sumUpToX2 = colPrefix[y1][x2];
                int sumBeforeX1 = (x1 > 0) ? colPrefix[y1][x1 - 1] : 0;
                return sumUpToX2 == sumBeforeX1;
            }
            return false; // diagonal movement is not allowed
        }

        /** Returns true if the given coordinates lie inside the grid. */
        boolean isInside(int x, int y) {
            return 0 <= x && x < rows && 0 <= y && y < cols;
        }
    }

    /* ---------- Direction constants ---------- */
    private static final class Direction {
        final int dx;
        final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }
    }

    private static final Direction[] CARDINAL = {
            new Direction(1, 0),   // down
            new Direction(-1, 0),  // up
            new Direction(0, 1),   // right
            new Direction(0, -1)   // left
    };

    /* ---------- Core algorithm ---------- */
    private final FastScanner scanner;
    private final PrintWriter out;

    B(Reader input, PrintWriter output) {
        this.scanner = new FastScanner(input);
        this.out = output;
    }

    /** Solves the problem and writes the result to the provided PrintWriter. */
    void solve() throws IOException {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Read the whole map and locate start (S) and target (T)
        int[][] obstacles = new int[rows][cols];
        int startX = -1, startY = -1;
        int targetX = -1, targetY = -1;

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                char cell = line.charAt(j);
                if (cell == 'S') {
                    startX = i;
                    startY = j;
                } else if (cell == 'T') {
                    targetX = i;
                    targetY = j;
                }
                obstacles[i][j] = (cell == '*') ? 1 : 0;
            }
        }

        Grid grid = new Grid(rows, cols, obstacles);

        // Try every possible first leg (from start) and every possible second leg (to target)
        for (Direction firstDir : CARDINAL) {
            for (int stepFirst = 0; stepFirst <= 1000; stepFirst++) {
                int x1 = startX + firstDir.dx * stepFirst;
                int y1 = startY + firstDir.dy * stepFirst;
                if (!grid.isInside(x1, y1)) continue;
                if (!grid.isClear(startX, startY, x1, y1)) continue;

                for (Direction secondDir : CARDINAL) {
                    for (int stepSecond = 0; stepSecond <= 1000; stepSecond++) {
                        int x2 = targetX + secondDir.dx * stepSecond;
                        int y2 = targetY + secondDir.dy * stepSecond;
                        if (!grid.isInside(x2, y2)) continue;
                        if (!grid.isClear(targetX, targetY, x2, y2)) continue;
                        if (grid.isClear(x1, y1, x2, y2)) {
                            out.println("YES");
                            return;
                        }
                    }
                }
            }
        }

        out.println("NO");
    }

    /** Entry point – wraps everything in try‑with‑resources for safety. */
    static void run() {
        try (PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out))) {
            Locale.setDefault(Locale.US);
            new B(System.in, out).solve();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    public static void main(String[] args) {
        run();
    }
}

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.io.Writer;
import java.util.ArrayDeque;

/**
 * Fast scanner that reads tokens from {@link InputStream}.
 * (Renamed from {@code InputReader} for clarity.)
 */
final class FastScanner {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int bytesInBuffer = 0;
    private int bufferPointer = 0;

    FastScanner(InputStream stream) {
        this.stream = stream;
    }

    /** Reads the next byte, filling the buffer if necessary. */
    private int readByte() throws IOException {
        if (bufferPointer >= bytesInBuffer) {
            bytesInBuffer = stream.read(buffer);
            bufferPointer = 0;
            if (bytesInBuffer <= 0) {
                return -1;
            }
        }
        return buffer[bufferPointer++];
    }

    /** Returns true if the character is a whitespace character. */
    private static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t';
    }

    /** Skips all whitespace characters. */
    private int skipWhitespace() throws IOException {
        int c;
        do {
            c = readByte();
        } while (c != -1 && isWhitespace(c));
        return c;
    }

    /** Reads the next integer. */
    int readInt() throws IOException {
        int c = skipWhitespace();
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readByte();
        }
        int result = 0;
        while (c >= '0' && c <= '9') {
            result = result * 10 + (c - '0');
            c = readByte();
        }
        return result * sign;
    }

    /** Reads the next token as a {@code String}. */
    String readString() throws IOException {
        int c = skipWhitespace();
        StringBuilder sb = new StringBuilder();
        do {
            if (Character.isValidCodePoint(c)) {
                sb.appendCodePoint(c);
            }
            c = readByte();
        } while (c != -1 && !isWhitespace(c));
        return sb.toString();
    }
}

/**
 * Fast printer that writes tokens to an {@link OutputStream}.
 * (Renamed from {@code OutputWriter} for clarity.)
 */
final class FastPrinter {
    private final PrintWriter writer;

    FastPrinter(OutputStream out) {
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
    }

    /** Prints the supplied objects separated by a single space. */
    void print(Object... objects) {
        for (int i = 0; i < objects.length; i++) {
            if (i != 0) writer.print(' ');
            writer.print(objects[i]);
        }
    }

    /** Prints the supplied objects followed by a line separator. */
    void println(Object... objects) {
        print(objects);
        writer.println();
    }

    /** Flushes and closes the underlying stream. */
    void close() {
        writer.close();
    }
}

/**
 * Utility class that contains the solution for the maze‑turn‑minimisation problem.
 */
final class MazeSolver {

    /** Four orthogonal movement directions. */
    private static final int[][] DIRS = {
            {-1, 0}, // up
            {0, 1},  // right
            {1, 0},  // down
            {0, -1}  // left
    };

    /** Represents a state while traversing the board. */
    private static final class State {
        final int row, col, dir, turns;

        State(int row, int col, int dir, int turns) {
            this.row = row;
            this.col = col;
            this.dir = dir;
            this.turns = turns;
        }
    }

    /** Entry point used by {@code Main}. */
    void solve(FastScanner in, FastPrinter out) {
        int rows = in.readInt();
        int cols = in.readInt();
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = in.readString().toCharArray();
        }

        int sr = -1, sc = -1; // start ('S')
        int tr = -1, tc = -1; // target ('T')
        outer:
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char ch = grid[r][c];
                if (ch == 'S') {
                    sr = r;
                    sc = c;
                } else if (ch == 'T') {
                    tr = r;
                    tc = c;
                }
                if (sr != -1 && tr != -1) {
                    break outer;
                }
            }
        }

        boolean[][][] visited = new boolean[rows][cols][4];
        ArrayDeque<State> queue = new ArrayDeque<>();

        // From the start we can initialise any direction with 0 turns taken.
        for (int d = 0; d < 4; d++) {
            queue.add(new State(sr, sc, d, 0));
        }

        while (!queue.isEmpty()) {
            State cur = queue.pollFirst();

            // Reached the target – answer is YES.
            if (cur.row == tr && cur.col == tc) {
                out.println("YES");
                return;
            }

            if (visited[cur.row][cur.col][cur.dir]) {
                continue;
            }
            visited[cur.row][cur.col][cur.dir] = true;

            // Explore the four possible moves.
            for (int nd = 0; nd < 4; nd++) {
                int nr = cur.row + DIRS[nd][0];
                int nc = cur.col + DIRS[nd][1];

                if (!isValidCell(nr, nc, rows, cols) || grid[nr][nc] == '*') {
                    continue;
                }

                if (nd == cur.dir) {
                    // Continue straight without increasing the turn count.
                    queue.addFirst(new State(nr, nc, nd, cur.turns));
                } else {
                    // Turning – allowed only when we have used < 1 turn so far.
                    if (cur.turns < 1) {
                        queue.addLast(new State(nr, nc, nd, cur.turns + 1));
                    }
                }
            }
        }

        // Exhausted all possibilities → answer is NO.
        out.println("NO");
    }

    /** Checks whether a cell coordinate lies inside the board limits. */
    private static boolean isValidCell(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

