        FastScanner scanner = new FastScanner(System.in);
        FastPrinter printer = new FastPrinter(System.out);
        new MazeSolver().solve(scanner, printer);
        printer.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “Maze with at most 2 turns” problem.
 *
 * <p>The program reads a grid where
 *   <ul>
 *     <li>'*' – obstacle</li>
 *     <li>'S' – start cell</li>
 *     <li>'T' – target cell</li>
 *     <li>any other character – free cell</li>
 *   </ul>
 * It determines whether there exists a path from {@code S} to {@code T}
 * that changes direction at most twice.
 *
 * <p>The implementation keeps the original algorithmic behaviour but
 * improves readability, removes unused code and follows modern Java
 * coding conventions.
 */
public final class MazeSolver {

    /** Maximum number of allowed direction changes. */
    private static final int MAX_TURNS = 2;

    /** Size of the visited array – one dimension for each possible turn count. */
    private static final int TURNS_DIM = MAX_TURNS + 1;

    /** Directions used by the original code (the same numeric values). */
    private static final int RIGHT = 1;
    private static final int LEFT = 2;
    private static final int UP = 3;
    private static final int DOWN = 4;

    /** Grid representation. */
    private char[][] grid;

    /** Dimensions of the grid. */
    private int rows, cols;

    /** Coordinates of the start and target cells. */
    private int startRow, startCol, targetRow, targetCol;

    /** 3‑dimensional visited flag [row][col][turns]. */
    private boolean[][][] visited;

    /** Global flag – 1 if a valid path was found. */
    private int answer = 0;

    /** Fast scanner used for input. */
    private final InputReader reader;

    public MazeSolver(InputReader reader) {
        this.reader = reader;
    }

    /** Entry point of the program. */
    public void solve() throws IOException {
        readInput();

        // Try every possible initial direction (right, left, up, down)
        dfs(startRow, startCol, 0, RIGHT);
        dfs(startRow, startCol, 0, LEFT);
        dfs(startRow, startCol, 0, UP);
        dfs(startRow, startCol, 0, DOWN);

        System.out.println(answer == 1 ? "YES" : "NO");
    }

    /**
     * Depth‑first search that explores the maze.
     *
     * @param row    current row
     * @param col    current column
     * @param turns  number of direction changes performed so far
     * @param dir    current moving direction (one of {@link #RIGHT, #LEFT, #UP, #DOWN})
     */
    private void dfs(int row, int col, int turns, int dir) {
        // Reached the target?
        if (row == targetRow && col == targetCol) {
            if (turns <= MAX_TURNS) {
                answer = 1;
            }
            return;
        }

        // Exceeded the allowed number of turns
        if (turns > MAX_TURNS) {
            return;
        }

        // State already processed
        if (visited[row][col][turns]) {
            return;
        }
        visited[row][col][turns] = true;

        // ---- Move to the right neighbour ----
        if (isSafe(row, col + 1)) {
            int newTurns = turns;
            if (dir != RIGHT && !(turns == 0 && dir == 0)) {
                newTurns++;
            }
            dfs(row, col + 1, newTurns, RIGHT);
        }

        // ---- Move downwards ----
        if (isSafe(row + 1, col)) {
            int newTurns = turns;
            if (dir != DOWN && !(turns == 0 && dir == 0)) {
                newTurns++;
            }
            dfs(row + 1, col, newTurns, DOWN);
        }

        // ---- Move to the left neighbour ----
        if (isSafe(row, col - 1)) {
            int newTurns = turns;
            if (dir != LEFT && !(turns == 0 && dir == 0)) {
                newTurns++;
            }
            dfs(row, col - 1, newTurns, LEFT);
        }

        // ---- Move upwards ----
        if (isSafe(row - 1, col)) {
            int newTurns = turns;
            if (dir != UP && !(turns == 0 && dir == 0)) {
                newTurns++;
            }
            dfs(row - 1, col, newTurns, UP);
        }
    }

    /** Resets the visited array before a new search from a given direction. */
    private void resetVisited() {
        for (int t = 0; t < TURNS_DIM; t++) {
            for (int i = 0; i < rows; i++) {
                Arrays.fill(visited[i], false);
            }
        }
    }

    /** Checks bounds and that the cell is not an obstacle. */
    private boolean isSafe(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '*';
    }

    /** Reads the whole input andlocates the start / target cells. */
    private void readInput() throws IOException {
        rows = reader.nextInt();
        cols = reader.nextInt();

        grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                char ch = line.charAt(j);
                grid[i][j] = ch;
                switch (ch) {
                    case 'S' -> {
                        startRow = i;
                        startCol = j;
                    }
                    case 'T' -> {
                        targetRow = i;
                        targetCol = j;
                    }
                    default -> {
                        // free cell – nothing to do
                    }
                }
            }
        }

        // visited[t][row][col] – have we been at (row,col) with exactly t turns?
        visited = new boolean[rows][cols][TURNS_DIM];
    }

    /** Simple tokenised input reader. */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream input) {
            br = new BufferedReader(new InputStreamReader(input));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Main method – keeps the original public‑static signature. */
    public static void main(String[] args) throws Exception {
        InputReader reader = new InputReader(System.in);
        new MazeSolver(reader).solve();
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Directions: left, up, right, down */
    private static final int[][] DIRS = {{0, -1}, {-1, 0}, {0, 1}, {1, 0}};
    private static final char WALL = '*';
    private static final char START = 'S';
    private static final char TARGET = 'T';

    /** State kept in the BFS queue */
    private static final class Node {
        final int x, y;          // current cell
        final int dir;           // 0‑left, 1‑up, 2‑right, 3‑down, -1‑start
        final int turns;         // number of direction changes performed

        Node(int x, int y, int dir, int turns) {
            this.x = x;
            this.y = y;
            this.dir = dir;
            this.turns = turns;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        while (fs.hasNext()) {
            int n = fs.nextInt();
            int m = fs.nextInt();
            char[][] maze = new char[n][m];
            int sx = -1, sy = -1, tx = -1, ty = -1;

            for (int i = 0; i < n; i++) {
                String line = fs.next();
                for (int j = 0; j < m; j++) {
                    maze[i][j] = line.charAt(j);
                    if (maze[i][j] == START) {
                        sx = i; sy = j;
                    } else if (maze[i][j] == TARGET) {
                        tx = i; ty = j;
                    }
                }
            }

            boolean reachable = bfs(maze, sx, sy, tx, ty);
            out.println(reachable ? "YES" : "NO");
            out.flush();
        }

        out.close();
    }

    /** Breadth‑first search that respects the “≤ 2 turns” constraint */
    private static boolean bfs(char[][] maze, int sx, int sy, int tx, int ty) {
        int n = maze.length, m = maze[0].length;

        /* visited[x][y][dir][turns] – have we been at (x,y) moving in 'dir' with 'turns' made? */
        boolean[][][][] visited = new boolean[n][m][DIRS.length][3];

        Queue<Node> q = new ArrayDeque<>();
        q.add(new Node(sx, sy, -1, 0));               // start cell
        visited[sx][sy][0][0] = true;                  // dummy index for start

        while (!q.isEmpty()) {
            Node cur = q.poll();

            if (cur.x == tx && cur.y == ty) {
                return true;                            // reached target
            }

            for (int d = 0; d < DIRS.length; d++) {
                int nx = cur.x + DIRS[d][0];
                int ny = cur.y + DIRS[d][1];

                if (!inBounds(nx, ny, n, m)) continue;   // outside board
                if (maze[nx][ny] == WALL) continue;       // wall blocks path

                int newTurns = cur.turns;
                if (cur.dir != -1 && cur.dir != d) {      // changed direction?
                    newTurns++;
                }
                if (newTurns > 2) continue;               // more than two turns → prune

                if (visited[nx][ny][d][newTurns]) continue;
                visited[nx][ny][d][newTurns] = true;
                q.add(new Node(nx, ny, d, newTurns));
            }
        }
        return false;                                   // target unreachable
    }

    /** Simple bounds check */
    private static boolean inBounds(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /** Fast scanner for competitive‑programming style input */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() throws IOException {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        boolean hasNext() throws IOException {
            return st != null && st.hasMoreElements() || br.ready();
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>It reads a 10×10 board, tries to place an 'X' on an empty '.' cell that has no
 * adjacent 'X', and checks whether such a move creates a line of five 'X's in any
 * direction (horizontal, vertical or diagonal). If it can, it prints "YES", otherwise
 * "NO".</p>
 */
public class MainBB {

    /** Board size – kept as a constant for easy adjustments. */
    private static final int SIZE = 10;

    /** Symbol for an empty cell. */
    private static final char EMPTY = '.';

    /** Symbol used for marking a move. */
    private static final char MARK = 'X';

    /** All eight directions used for neighbour checks and line scanning. */
    private static final int[][] DIRECTIONS = {
            {0, 1},   // right
            {1, 0},   // down
            {0, -1},  // left
            {-1, 0},  // up
            {1, 1},   // down‑right diagonal
            {1, -1},  // down‑left diagonal
            {-1, 1},  // up‑right diagonal
            {-1, -1}  // up‑left diagonal
    };

    public static void main(String[] args) {
        /* Try‑with‑resources guarantees the scanner is closed even on exceptions. */
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            if (canCreateFiveInRow(board)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Reads ten lines from {@code scanner}, each containing exactly {@code SIZE}
     * characters, and stores them into a 2‑D {@code char} array.
     */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[SIZE][SIZE];
        for (int i = 0; i < SIZE; i++) {
            String line = scanner.nextLine();
            if (line.length() != SIZE) {
                throw new IllegalArgumentException(
                        "Line " + (i + 1) + " must contain exactly " + SIZE + " characters.");
            }
            for (int j = 0; j < SIZE; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /**
     * Determines whether placing an 'X' on any empty '.' cell that has no adjacent
     * 'X' results in a line of five 'X's. Returns {@code true} as soon as such a
     * placement is found.
     */
    private static boolean canCreateFiveInRow(char[][] board) {
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (board[i][j] == EMPTY && !hasAdjacentMark(board, i, j)) {
                    board[i][j] = MARK;                 // tentatively place X
                    if (hasFiveInRow(board)) {
                        board[i][j] = EMPTY;             // cleanup before returning
                        return true;
                    }
                    board[i][j] = EMPTY;                 // revert change
                }
            }
        }
        return false;
    }

    /**
     * Checks the eight neighbours of {@code (x, y)} for the presence of a {@code MARK}.
     * Returns {@code true} if at least one neighbour contains {@code MARK},
     * meaning the cell is **not** alone.
     */
    private static boolean hasAdjacentMark(char[][] board, int x, int y) {
        for (int dx = -1; dx <= 1; dx++) {
            for (int dy = -1; dy <= 1; dy++) {
                if (dx == 0 && dy == 0) {
                    continue; // skip the cell itself
                }
                int nx = x + dx;
                int ny = y + dy;
                if (inside(nx, ny) && board[nx][ny] == MARK) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Scans the whole board for any line of five {@code MARK}s.
     * Returns {@code true} if such a line exists.
     */
    private static boolean hasFiveInRow(char[][] board) {
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (board[i][j] != MARK) {
                    continue;
                }
                // Examine each of the four axis‑aligned directions;
                // duplicate directions are harmless because the length check stops early.
                for (int[] dir : DIRECTIONS) {
                    int length = countConsecutive(board, i, j, dir[0], dir[1]);
                    if (length >= 5) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Counts how many consecutive {@code MARK}s are found starting at {@code (x, y)}
     * and moving repeatedly by {@code (dx, dy)}. The count stops when the border
     * of the board is reached or a non‑{@code MARK} cell is encountered.
     */
    private static int countConsecutive(char[][] board, int x, int y, int dx, int dy) {
        int length = 1; // the starting cell itself is MARK
        for (int step = 1; step < 5; step++) { // at most 5 steps needed
            int nx = x + step * dx;
            int ny = y + step * dy;
            if (!inside(nx, ny) || board[nx][ny] != MARK) {
                break;
            }
            length++;
        }
        return length;
    }

    /** Helper that checks whether coordinates are inside the board limits. */
    private static boolean inside(int x, int y) {
        return x >= 0 && x < SIZE && y >= 0 && y < SIZE;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class B {
    private static final int SIZE = 10;
    private static final int[][] DIRECTIONS = {
        {0, 1},   // east
        {0, -1},  // west
        {-1, 0},  // north
        {1, 0},   // south
        {1, 1},   // southEast
        {-1, 1},  // northEast
        {1, -1},  // southWest
        {-1, -1}  // northWest
    };

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        char[][] arr = new char[SIZE][SIZE];

        for (int i = 0; i < SIZE; i++) {
            String str = fs.next();
            for (int j = 0; j < SIZE; j++) {
                arr[i][j] = str.charAt(j);
            }
        }

        boolean found = false;
        for (int i = 0; i < SIZE && !found; i++) {
            for (int j = 0; j < SIZE && !found; j++) {
                for (int[] dir : DIRECTIONS) {
                    if (checkDirection(i, j, dir[0], dir[1], arr)) {
                        found = true;
                        break;
                    }
                }
            }
        }
        System.out.println(found ? "YES" : "NO");
    }

    private static boolean checkDirection(int i, int j, int dx, int dy, char[][] arr) {
        int count = 0;
        for (int k = 0; k < 4; k++) {
            if (i < 0 || i >= SIZE || j < 0 || j >= SIZE) {
                return false;
            }
            if (arr[i][j] == 'O') {
                return false;
            }
            if (arr[i][j] == 'X') {
                count++;
            }
            i += dx;
            j += dy;
        }
        return count == 4;
    }

    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Detects a specific pattern of 'X' and '.' on a 10×10 board.
 * The pattern is considered found when, from a starting 'X',
 * a line of up to four cells contains at least three 'X',
 * exactly one '.' and no 'O' before the first non‑'X' character.
 *
 * The program reads ten lines of input, each containing ten characters,
 * and prints "YES" if the pattern exists, otherwise "NO".
 */
public class Main {

    private static final int BOARD_SIZE = 10;

    public static void main(String[] args) throws IOException {
        char[][] board = readBoard();
        if (hasPattern(board)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /** Reads the 10×10 board from standard input. */
    private static char[][] readBoard() throws IOException {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line;
            int row = 0;
            while (row < BOARD_SIZE && (line = br.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty()) {
                    continue;               // skip empty lines
                }
                for (int col = 0; col < BOARD_SIZE; col++) {
                    board[row][col] = line.charAt(col);
                }
                row++;
            }
        }
        return board;
    }

    /** Entry point for pattern detection. */
    private static boolean hasPattern(char[][] board) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == 'X' && checkAllDirections(board, i, j)) {
                    return true;            // pattern found – stop early
                }
            }
        }
        return false;                       // no pattern on the whole board
    }

    /** Checks the eight possible directions from the given cell. */
    private static boolean checkAllDirections(char[][] board, int startI, int startJ) {
        // (di, dj) pairs for the eight directions
        int[][] directions = {
                {0, 1},   // right
                {1, 0},   // down
                {1, 1},   // down‑right
                {1, -1},  // down‑left
                {0, -1},  // left
                {-1, 0},  // up
                {-1, 1},  // up‑right
                {-1, -1}  // up‑left
        };

        for (int[] dir : directions) {
            // Check both forward and backward directions
            if (scanDirection(board, startI, startJ, dir[0], dir[1])
                    || scanDirection(board, startI, startJ, -dir[0], -dir[1])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Scans from the start cell in the given direction.
     * Returns {@code true} if the scanned segment satisfies:
     * <ul>
     *   <li>contains at least three 'X'</li>
     *   <li>contains exactly one '.' </li>
     *   <li>contains no 'O' before the first non‑'X' character</li>
     * </ul>
     */
    private static boolean scanDirection(char[][] board, int i, int j, int di, int dj) {
        int xCount = 0;
        int dotCount = 0;
        boolean encounteredOther = false;   // true if we meet 'O' or step out of bounds

        for (int step = 1; step <= 4; step++) {
            int ni = i + step * di;
            int nj = j + step * dj;
            if (!inBounds(ni, nj)) {
                encounteredOther = true;
                break;
            }
            char c = board[ni][nj];
            if (c == 'O') {
                encounteredOther = true;
                break;
            }
            if (c == 'X') {
                xCount++;
            } else if (c == '.') {
                if (dotCount == 0) {
                    dotCount = 1;            // first '.' is allowed
                } else {
                    // more than one '.' invalidates the pattern
                    encounteredOther = true;
                    break;
                }
            } else {
                // Any unexpected character breaks the pattern
                encounteredOther = true;
                break;
            }
        }

        // Pattern is valid only when we didn't encounter 'O' or out‑of‑bounds,
        // saw exactly one '.', and at least three 'X's.
        return !encounteredOther && dotCount == 1 && xCount >= 3;
    }

    /** Utility to check whether a cell lies inside the 10×10 board. */
    private static boolean inBounds(int i, int j) {
        return i >= 0 && i < BOARD_SIZE && j >= 0 && j < BOARD_SIZE;
    }
}

/**
 * Refactored version of the original Five‑In‑a‑Row checker.
 * The program reads a 10×10 board from standard input and reports
 * whether any horizontal, vertical or diagonal line of length 5
 * contains exactly four 'X' characters and one '.' character.
 */
public class Game {

    private static final int GRID_SIZE = 10;
    private static final int SEGMENT_LENGTH = 5;

    private static final Scanner SCANNER = new Scanner(System.in);

    public static void main(String[] args) {
        GameBoard board = new GameBoard();
        board.loadGrid();

        System.out.println(board.hasWinningPattern()
                ? "YES"
                : "NO");
    }
}

/**
 * Encapsulates the board and all validation logic.
 */
final class GameBoard {

    /** Fixed 10×10 board. */
    private final char[][] grid = new char[GRID_SIZE][GRID_SIZE];

    /** Loads the board from standard input. */
    void loadGrid() {
        for (int row = 0; row < GRID_SIZE; row++) {
            String token = SCANNER.next();               // read next token
            for (int col = 0; col < GRID_SIZE; col++) {
                grid[row][col] = token.charAt(col);
            }
        }
    }

    /** Checks the whole board for a winning segment. */
    boolean hasWinningPattern() {
        return hasHorizontalWin()
                || hasVerticalWin()
                || hasDiagonalMainWin()
                || hasDiagonalAntiWin();
    }

    /** Scans every possible horizontal line. */
    private boolean hasHorizontalWin() {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col <= GRID_SIZE - SEGMENT_LENGTH; col++) {
                if (isWinningSegment(
                        extractHorizontal(row, col))) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Scans every possible vertical line. */
    private boolean hasVerticalWin() {
        for (int col = 0; col < GRID_SIZE; col++) {
            for (int row = 0; row <= GRID_SIZE - SEGMENT_LENGTH; row++) {
                if (isWinningSegment(
                        extractVertical(col, row))) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Scans every possible main‑diagonal (top‑left → bottom‑right). */
    private boolean hasDiagonalMainWin() {
        for (int startRow = 0; startRow <= GRID_SIZE - SEGMENT_LENGTH; startRow++) {
            for (int startCol = 0; startCol <= GRID_SIZE - SEGMENT_LENGTH; startCol++) {
                if (isWinningSegment(
                        extractDiagonalMain(startRow, startCol))) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Scans every possible anti‑diagonal (top‑right → bottom‑left). */
    private boolean hasDiagonalAntiWin() {
        for (int startRow = 0; startRow <= GRID_SIZE - SEGMENT_LENGTH; startRow++) {
            for (int startCol = SEGMENT_LENGTH - 1; startCol < GRID_SIZE; startCol++) {
                if (isWinningSegment(
                        extractDiagonalAnti(startRow, startCol))) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Returns true if a 5‑cell segment contains exactly four 'X' and one '.'. */
    private boolean isWinningSegment(char[] cells) {
        int xCount = 0;
        int dotCount = 0;
        for (char c : cells) {
            if (c == 'X') {
                xCount++;
            } else if (c == '.') {
                dotCount++;
            } else {
                // Any other character makes the segment invalid.
                return false;
            }
        }
        return xCount == 4 && dotCount == 1;
    }

    /** Extracts a horizontal segment of length 5 starting at (row, col). */
    private char[] extractHorizontal(int row, int startCol) {
        char[] segment = new char[SEGMENT_LENGTH];
        System.arraycopy(grid[row], startCol, segment, 0, SEGMENT_LENGTH);
        return segment;
    }

    /** Extracts a vertical segment of length 5 starting at (row, col). */
    private char[] extractVertical(int col, int startRow) {
        char[] segment = new char[SEGMENT_LENGTH];
        for (int i = 0; i < SEGMENT_LENGTH; i++) {
            segment[i] = grid[startRow + i][col];
        }
        return segment;
    }

    /** Extracts a main‑diagonal segment of length 5 starting at (row, col). */
    private char[] extractDiagonalMain(int startRow, int startCol) {
        char[] segment = new char[SEGMENT_LENGTH];
        for (int i = 0; i < SEGMENT_LENGTH; i++) {
            segment[i] = grid[startRow + i][startCol + i];
        }
        return segment;
    }

    /** Extracts an anti‑diagonal segment of length 5 starting at (row, col). */
    private char[] extractDiagonalAnti(int startRow, int startCol) {
        char[] segment = new char[SEGMENT_LENGTH];
        for (int i = 0; i < SEGMENT_LENGTH; i++) {
            segment[i] = grid[startRow + i][startCol - i];
        }
        return segment;
    }
}

import java.util.Scanner;

/**
 * Reads a 10×10 board made of '.' (empty) and 'X' (ship) symbols.
 * Prints “YES” if some empty cell is adjacent to at least 5 consecutive
 * 'X' cells in any of the eight directions, otherwise prints “NO”.
 */
public class B825 {

    private static final int BOARD_SIZE = 10;
    private static final char EMPTY = '.';
    private static final char SHIP = 'X';
    private static final int REQUIRED_LENGTH = 5;

    public static void main(String[] args) {
        char[][] board = readBoard();
        int maxConnectedShips = computeMaximumConnectedShips(board);
        System.out.println(maxConnectedShips >= REQUIRED_LENGTH ? "YES" : "NO");
    }

    /** Reads ten lines from standard input and stores them in a char matrix. */
    private static char[][] readBoard() {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = scanner.nextLine();
            board[i] = line.toCharArray();
        }
        scanner.close();
        return board;
    }

    /**
     * Determines the largest number of consecutive 'X' cells that are
     * accessible from any '.' cell in any of the eight directions.
     * The result is the count of 'X' cells; the calling code adds 1 to
     * include the '.' itself (preserving original behaviour).
     */
    private static int computeMaximumConnectedShips(char[][] board) {
        int maxCount = 0;

        // eight possible directions (dx, dy)
        int[][] directions = {
                {0, 1},   // right
                {1, 0},   // down
                {1, 1},   // down‑right
                {1, -1},  // down‑left
                {0, -1},  // left
                {-1, 0},  // up
                {-1, -1}, // up‑left
                {-1, 1}   // up‑right
        };

        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] != EMPTY) {
                    continue;
                }

                for (int[] dir : directions) {
                    int dx = dir[0];
                    int dy = dir[1];
                    int count = 0;

                    // forward direction
                    int nr = r + dx;
                    int nc = c + dy;
                    while (isInBounds(nr, nc, BOARD_SIZE) && board[nr][nc] == SHIP) {
                        count++;
                        nr += dx;
                        nc += dy;
                    }

                    // backward direction
                    nr = r - dx;
                    nc = c - dy;
                    while (isInBounds(nr, nc, BOARD_SIZE) && board[nr][nc] == SHIP) {
                        count++;
                        nr -= dx;
                        nc -= dy;
                    }

                    maxCount = Math.max(maxCount, count);
                }
            }
        }
        return maxCount; // original program adds 1 after the loops
    }

    /** Helper that checks whether a coordinate lies inside an N×N board. */
    private static boolean isInBounds(int row, int col, int size) {
        return row >= 0 && col >= 0 && row < size && col < size;
    }
}

import java.util.Scanner;

/**
 * Determines whether a 10×10 grid already contains a line of five 'X' cells,
 * or whether placing a single 'X' in any '.' cell can create such a line.
 */
public class Main {

    /** Size of the square board (10×10). */
    private static final int BOARD_SIZE = 10;

    /** Direction vectors: right, down, down‑right, down‑left. */
    private static final int[] DR = {0, 1, 1, 1};
    private static final int[] DC = {1, 0, 1, -1};

    public static void main(String[] args) {
        System.out.println(new Solver().solve());
    }

    /** High‑level orchestrator of the algorithm. */
    private static class Solver {

        public String solve() {
            char[][] board = readBoard();

            if (alreadyHasFiveInARow(board)) {
                return "YES";
            }

            return canCreateFiveInARowByOnePlacement(board);
        }

        /** Reads exactly BOARD_SIZE lines of length BOARD_SIZE from the scanner. */
        private static char[][] readBoard() {
            try (Scanner scanner = new Scanner(System.in)) {
                char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
                for (int row = 0; row < BOARD_SIZE; ++row) {
                    String line = scanner.next();
                    for (int col = 0; col < BOARD_SIZE; ++col) {
                        board[row][col] = line.charAt(col);
                    }
                }
                return board;
            }
        }

        /** Checks if the board already contains a line of five consecutive 'X's. */
        private static boolean alreadyHasFiveInARow(char[][] board) {
            return hasFiveInARow(board);
        }

        /** Attempts to place an 'X' in every '.' cell and sees if that creates a line. */
        private static String canCreateFiveInARowByOnePlacement(char[][] board) {
            for (int row = 0; row < BOARD_SIZE; ++row) {
                for (int col = 0; col < BOARD_SIZE; ++col) {
                    if (board[row][col] != '.') {
                        continue;
                    }

                    board[row][col] = 'X';
                    if (hasFiveInARow(board)) {
                        board[row][col] = '.';   // restore before returning
                        return "YES";
                    }
                    board[row][col] = '.';       // restore original cell
                }
            }
            return "NO";
        }

        /** Determines whether there exists a straight line of exactly five 'X's. */
        private static boolean hasFiveInARow(char[][] board) {
            for (int row = 0; row < BOARD_SIZE; ++row) {
                for (int col = 0; col < BOARD_SIZE; ++col) {
                    for (int dir = 0; dir < 4; ++dir) {
                        if (startsFiveInDirection(board, row, col, dir)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /** Checks if a line of five 'X's starts at (row, col) moving in `dir`. */
        private static boolean startsFiveInDirection(char[][] board,
                                                     int row, int col, int dir) {
            for (int step = 0; step < 5; ++step) {
                int r = row + step * DR[dir];
                int c = col + step * DC[dir];
                if (!isInside(r, c) || board[r][c] != 'X') {
                    return false;
                }
            }
            return true;
        }

        /** Returns true if (row, col) lies inside the board boundaries. */
        private static boolean isInside(int row, int col) {
            return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE;
        }
    }
}

import java.util.Scanner;

public class ProblemB {

    private static final int BOARD_SIZE = 10;
    private static final int WIN_LENGTH = 5;

    private enum Cell { EMPTY, X, O }

    private static class Board {
        private final Cell[][] grid = new Cell[BOARD_SIZE][BOARD_SIZE];

        void place(int row, int col, Cell value) {
            grid[row][col] = value;
        }

        Cell get(int row, int col) {
            return grid[row][col];
        }

        boolean isEmpty(int row, int col) {
            return grid[row][col] == Cell.EMPTY;
        }

        /**
         * Checks whether placing an 'X' at (row, col) creates a line of {@value WIN_LENGTH}
         * consecutive 'X' cells in any direction.
         */
        boolean hasWinAt(int row, int col) {
            return checkHorizontal(row, col) ||
                   checkVertical(row, col) ||
                   checkDiagonalLeft(row, col) ||
                   checkDiagonalRight(row, col);
        }

        private boolean checkHorizontal(int row, int col) {
            // Look for a horizontal segment of WIN_LENGTH starting at any column.
            for (int start = 0; start <= BOARD_SIZE - WIN_LENGTH; start++) {
                boolean lineFull = true;
                for (int offset = 0; offset < WIN_LENGTH; offset++) {
                    if (grid[row][start + offset] != Cell.X) {
                        lineFull = false;
                        break;
                    }
                }
                if (lineFull) {
                    return true;
                }
            }
            return false;
        }

        private boolean checkVertical(int row, int col) {
            // Look for a vertical segment of WIN_LENGTH starting at any row.
            for (int start = 0; start <= BOARD_SIZE - WIN_LENGTH; start++) {
                boolean lineFull = true;
                for (int offset = 0; offset < WIN_LENGTH; offset++) {
                    if (grid[start + offset][col] != Cell.X) {
                        lineFull = false;
                        break;
                    }
                }
                if (lineFull) {
                    return true;
                }
            }
            return false;
        }

        private boolean checkDiagonalLeft(int row, int col) {
            // Move to the top‑leftmost cell of the possible diagonal segment.
            int r = row;
            int c = col;
            while (r > 0 && c > 0) {
                r--;
                c--;
            }

            // Slide along the diagonal until the end of the board.
            while (r + WIN_LENGTH - 1 < BOARD_SIZE && c + WIN_LENGTH - 1 < BOARD_SIZE) {
                boolean lineFull = true;
                for (int i = 0; i < WIN_LENGTH; i++) {
                    if (grid[r + i][c + i] != Cell.X) {
                        lineFull = false;
                        break;
                    }
                }
                if (lineFull) {
                    return true;
                }
                r++;
                c++;
            }
            return false;
        }

        private boolean checkDiagonalRight(int row, int col) {
            // Move to the top‑rightmost cell of the possible diagonal segment.
            int r = row;
            int c = col;
            while (r > 0 && c < BOARD_SIZE - 1) {
                r--;
                c++;
            }

            // Slide along the diagonal from bottom‑right to top‑left.
            while (r + WIN_LENGTH - 1 < BOARD_SIZE && c - WIN_LENGTH + 1 >= 0) {
                boolean lineFull = true;
                for (int i = 0; i < WIN_LENGTH; i++) {
                    if (grid[r + i][c - i] != Cell.X) {
                        lineFull = false;
                        break;
                    }
                }
                if (lineFull) {
                    return true;
                }
                r++;
                c--;
            }
            return false;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Board board = new Board();

        // Read the 10×10 board.
        for (int r = 0; r < BOARD_SIZE; r++) {
            String line = scanner.nextLine().trim();
            for (int c = 0; c < BOARD_SIZE; c++) {
                board.place(r, c, parseCell(line.charAt(c)));
            }
        }

        // Try placing an 'X' into every empty cell and check for a winning line.
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board.isEmpty(r, c)) {
                    board.place(r, c, Cell.X);
                    if (board.hasWinAt(r, c)) {
                        System.out.println("YES");
                        return;
                    }
                    // Undo the move for the next iteration.
                    board.place(r, c, Cell.EMPTY);
                }
            }
        }

        System.out.println("NO");
    }

    private static Cell parseCell(char ch) {
        switch (ch) {
            case 'X': return Cell.X;
            case 'O': return Cell.O;
            default:  return Cell.EMPTY;
        }
    }
}

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.io.Writer;
import java.io.OutputStreamWriter;
import java.util.InputMismatchException;

/**
 * Entry point of the application.
 */
public class Main {

    /** Solves the problem using the supplied I/O streams. */
    public static void main(String[] args) {
        // The problem does not use command‑line arguments.
        solve(System.in, System.out);
    }

    /** Solves the problem using the supplied I/O streams. */
    private static void solve(InputStream in, OutputStream out) {
        InputReader reader = new InputReader(in);
        OutputWriter writer = new OutputWriter(out);
        new Solver().execute(reader, writer);
        writer.close();
    }
}

/**
 * Solution logic for the problem.
 */
class Solver {

    /** Board dimension (10×10). */
    private static final int BOARD_SIZE = 10;

    /** Offsets for the eight possible directions. */
    private static final int[] DX = { -1, -1, -1, 0, 1, 1, 1, 0 };
    private static final int[] DY = { -1, 0, 1, 1, 1, 0, -1, -1 };

    /** Executes the solution using the reader and writer. */
    void execute(InputReader reader, OutputWriter writer) {
        char[][] board = IOUtils.readTable(reader, BOARD_SIZE, BOARD_SIZE);
        if (canMakeFiveInLine(board)) {
            writer.print("YES");
        } else {
            writer.print("NO");
        }
    }

    /** Determines whether placing an 'X' creates a line of five 'X's. */
    private boolean canMakeFiveInLine(char[][] field) {
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                if (field[row][col] == '.') {
                    field[row][col] = 'X';
                    if (hasFiveInLine(field)) {
                        // Restore the cell before returning – not strictly required
                        // but keeps the board untouched for possible further checks.
                        field[row][col] = '.';
                        return true;
                    }
                    field[row][col] = '.';
                }
            }
        }
        return false;
    }

    /** Checks if there exists any line of exactly five consecutive 'X's. */
    private boolean hasFiveInLine(char[][] field) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                for (int dir = 0; dir < DX.length; dir++) {
                    if (isFiveStartingAt(field, r, c, dir)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Checks whether a line of five consecutive 'X's starts at (x,y) moving in dir. */
    private boolean isFiveStartingAt(char[][] field, int x, int y, int dir) {
        for (int step = 0; step < 5; step++) {
            if (!inBounds(x, y) || field[x][y] != 'X') {
                return false;
            }
            x += DX[dir];
            y += DY[dir];
        }
        return true;
    }

    /** Returns true if the coordinates are inside the 10×10 board. */
    private boolean inBounds(int x, int y) {
        return 0 <= x && x < BOARD_SIZE && 0 <= y && y < BOARD_SIZE;
    }
}

/**
 * Small utility class that contains static I/O helpers.
 */
final class IOUtils {

    private IOUtils() { /* utility class – prevent instantiation */ }

    /** Reads a fixed‑size character array from the input stream. */
    static char[] readCharArray(InputReader in, int size) {
        char[] array = new char[size];
        for (int i = 0; i < size; i++) {
            array[i] = in.readCharacter();
        }
        return array;
    }

    /** Reads a rectangular table of characters. */
    static char[][] readTable(InputReader in, int rows, int columns) {
        char[][] table = new char[rows][];
        for (int i = 0; i < rows; i++) {
            table[i] = readCharArray(in, columns);
        }
        return table;
    }
}

/**
 * Input stream wrapper that efficiently reads characters.
 */
class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int currentByte;
    private int bytesRead;
    private SpaceCharFilter filter;

    InputReader(InputStream stream) {
        this.stream = stream;
    }

    /** Reads the next byte of input (or throws {@link InputMismatchException} on EOF). */
    private int read() {
        if (bytesRead == -1) {
            throw new InputMismatchException();
        }
        if (currentByte >= bytesRead) {
            currentByte = 0;
            try {
                bytesRead = stream.read(buffer);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (bytesRead <= 0) {
                return -1;
            }
        }
        return buffer[currentByte++];
    }

    /** Checks whether the given character is considered whitespace. */
    public boolean isSpaceChar(int c) {
        if (filter != null) {
            return filter.isSpaceChar(c);
        }
        return isWhitespace(c);
    }

    /** Default whitespace test. */
    private static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    /** Reads the next non‑whitespace character. */
    public char readCharacter() {
        int c;
        do {
            c = read();
        } while (isSpaceChar(c));
        return (char) c;
    }

    /** Filter that can be supplied by users to customize whitespace detection. */
    interface SpaceCharFilter {
        boolean isSpaceChar(int ch);
    }
}

/**
 * Output stream wrapper that buffers writes and prints multiple values.
 */
class OutputWriter {
    private final PrintWriter writer;

    /** Constructs a writer that outputs to the given {@link OutputStream}. */
    OutputWriter(OutputStream outputStream) {
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    /** Constructs a writer that outputs to the given {@link Writer}. */
    OutputWriter(Writer writer) {
        this.writer = new PrintWriter(writer);
    }

    /** Prints the supplied objects separated by a single space. */
    public void print(Object... objects) {
        for (int i = 0; i < objects.length; i++) {
            if (i != 0) {
                writer.print(' ');
            }
            writer.print(objects[i]);
        }
    }

    /** Flushes and closes the underlying writer. */
    public void close() {
        writer.close();
    }
}

import java.util.Scanner;

/**
 * Detects whether a 10×10 board contains a line of five cells that are either
 * completely filled with 'X' or consist of exactly four 'X' and one empty cell.
 *
 * The board is supplied via standard input – ten lines each containing ten
 * characters (either 'X' or '.').
 */
public class Main {

    /** Symbol that represents an occupied cell ('X'). */
    private static final int OCCUPIED = 1;

    /** Symbol that represents an empty cell ('.'). */
    private static final int EMPTY = 0;

    /** Length of the winning line we are looking for. */
    private static final int WIN_LENGTH = 5;

    public static void main(String[] args) {
        int[][] board = readBoard();
        boolean hasWinningPattern = hasWinningPattern(board);

        System.out.println(hasWinningPattern ? "YES" : "NO");
    }

    /**
     * Reads a 10×10 board from {@code System.in}.  Each line must contain exactly
     * ten characters, either 'X' (occupied) or '.' (empty).
     *
     * @return a 10×10 integer matrix where {@code OCCUPIED} marks an 'X' and
     *         {@code EMPTY} marks a '.'.
     */
    private static int[][] readBoard() {
        try (Scanner scanner = new Scanner(System.in)) {
            int[][] board = new int[10][10];
            for (int row = 0; row < 10; row++) {
                String line = scanner.next();
                for (int col = 0; col < 10; col++) {
                    char c = line.charAt(col);
                    board[row][col] = (c == 'X') ? OCCUPIED : EMPTY;
                }
            }
            return board;
        }
    }

    /**
     * Checks the board for any horizontal, vertical or diagonal sequence of
     * {@value #WIN_LENGTH} cells that is either completely filled with
     * {@code OCCUPIED} or contains exactly one {@code EMPTY} cell and four
     * {@code OCCUPIED} cells.
     *
     * @param board the 10×10 game board
     * @return {@code true} if such a pattern exists, otherwise {@code false}
     */
    private static boolean hasWinningPattern(int[][] board) {
        // Horizontal sequences
        for (int row = 0; row < 10; row++) {
            for (int col = 0; col <= 10 - WIN_LENGTH; col++) {
                if (examiningSegment(board, row, col, 0, 1, WIN_LENGTH)) {
                    return true;
                }
            }
        }

        // Vertical sequences
        for (int col = 0; col < 10; col++) {
            for (int row = 0; row <= 10 - WIN_LENGTH; row++) {
                if (examiningSegment(board, row, col, 1, 0, WIN_LENGTH)) {
                    return true;
                }
            }
        }

        // Diagonal down‑right sequences
        for (int row = 0; row <= 10 - WIN_LENGTH; row++) {
            for (int col = 0; col <= 10 - WIN_LENGTH; col++) {
                if (examiningSegment(board, row, col, 1, 1, WIN_LENGTH)) {
                    return true;
                }
            }
        }

        // Diagonal down‑left sequences
        for (int row = WIN_LENGTH - 1; row < 10; row++) {
            for (int col = 0; col <= 10 - WIN_LENGTH; col++) {
                if (examiningSegment(board, row, col, -1, 1, WIN_LENGTH)) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Inspects a line of {@value #WIN_LENGTH} cells that starts at
     * {@code (startRow, startCol)} and proceeds by {@code dRow}/{@code dCol}
     * each step.
     *
     * <p>The method counts how many cells are {@code OCCUPIED} and how many are
     * {@code EMPTY}.  It returns {@code true} if either
     * <ul>
     *   <li>all cells are {@code OCCUPIED}, or</li>
     *   <li>exactly one cell is {@code EMPTY} and the remaining {@code WIN_LENGTH‑1}
     *       cells are {@code OCCUPIED}.</li>
     * </ul>
     *
     * @param board    the game board
     * @param startRow row index of the first cell in the segment
     * @param startCol column index of the first cell in the segment
     * @param dRow     row delta for each step (e.g. 1 for down, -1 for up)
     * @param dCol     column delta for each step (e.g. 1 for right, -1 for left)
     * @param length   number of cells to examine (always {@value #WIN_LENGTH})
     * @return {@code true} if the segment satisfies the winning condition
     */
    private static boolean examiningSegment(int[][] board,
                                            int startRow,
                                            int startCol,
                                            int dRow,
                                            int dCol,
                                            int length) {
        int occupiedCount = 0;
        int emptyCount = 0;

        for (int i = 0; i < length; i++) {
            int r = startRow + i * dRow;
            int c = startCol + i * dCol;
            int cell = board[r][c];

            if (cell == OCCUPIED) {
                occupiedCount++;
            } else { // EMPTY
                emptyCount++;
            }
        }

        // Winning patterns:
        //  • all cells occupied
        //  • exactly one empty cell and the rest occupied
        return (occupiedCount == length) ||
               (occupiedCount == length - 1 && emptyCount == 1);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;

/**
 * Reads a 10×10 board from standard input and checks whether any of the
 * predefined patterns occurs in rows, columns or diagonals.
 */
public class Main {

    /** Board size – kept as a constant for easy maintainability. */
    private static final int SIZE = 10;

    /** Patterns that indicate a win; kept immutable and final. */
    private static final Set<String> TARGET_PATTERNS = Set.of(
            "XXXX.",   // four X's followed by any character
            ".XXXX",   // any character followed by four X's
            "XXX.X",   // three X's, a dot, one X
            "XX.XX",   // two X's, a dot, two X's
            "X.XXX"    // one X, a dot, three X's
    );

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            Board board = readBoard(br);
            System.out.println(searchBoard(board) ? "YES" : "NO");
        }
    }

    /** Reads exactly 10 lines from the supplied reader and builds an immutable board. */
    private static Board readBoard(BufferedReader br) throws IOException {
        List<String> rows = new ArrayList<>(SIZE);
        for (int i = 0; i < SIZE; i++) {
            rows.add(br.readLine());
        }
        return new Board(rows);
    }

    /** Returns {@code true} if any of the target patterns appear in the board. */
    private static boolean searchBoard(Board board) {
        List<String> allLines = new ArrayList<>();

        // 1. rows
        allLines.addAll(board.getRows());

        // 2. columns
        for (int col = 0; col < SIZE; col++) {
            allLines.add(board.getColumn(col));
        }

        // 3. forward diagonals (top‑left → bottom‑right)
        for (int start = 0; start < SIZE; start++) {
            allLines.add(board.getMainDiagonal(start));
        }

        // 4. backward diagonals (top‑right → bottom‑left)
        for (int start = 0; start < SIZE; start++) {
            allLines.add(board.getAntiDiagonal(start));
        }

        // 5. check each collected line for the presence of any target pattern
        for (String line : allLines) {
            if (containsAnyTarget(line)) {
                return true;
            }
        }
        return false;
    }

    /** Helper that determines whether a line contains any of the target patterns. */
    private static boolean containsAnyTarget(String line) {
        for (String pat : TARGET_PATTERNS) {
            if (line.contains(pat)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Simple wrapper that stores the 10×10 grid and provides convenient access
     * to rows, columns and the two diagonal families.
     */
    private static final class Board {
        private final List<String> rows; // immutable after construction

        Board(List<String> rows) {
            this.rows = Collections.unmodifiableList(new ArrayList<>(rows));
        }

        /** Returns an unmodifiable view of the stored rows. */
        List<String> getRows() {
            return rows;
        }

        /** Constructs a column string by taking the character at {@code index} from each row. */
        String getColumn(int index) {
            StringBuilder sb = new StringBuilder(SIZE);
            for (String row : rows) {
                sb.append(row.charAt(index));
            }
            return sb.toString();
        }

        /** Returns the diagonal that starts at row/col {@code startOffset} and proceeds down‑right. */
        String getMainDiagonal(int startOffset) {
            StringBuilder sb = new StringBuilder();
            for (int step = 0; step < SIZE - startOffset; step++) {
                int row = startOffset + step;
                int col = startOffset + step;
                sb.append(rows.get(row).charAt(col));
            }
            return sb.toString();
        }

        /** Returns the diagonal that starts at row/col {@code startOffset} and proceeds down‑left. */
        String getAntiDiagonal(int startOffset) {
            StringBuilder sb = new StringBuilder();
            for (int step = 0; step < SIZE - startOffset; step++) {
                int row = startOffset + step;
                int col = SIZE - 1 - startOffset - step;
                sb.append(rows.get(row).charAt(col));
            }
            return sb.toString();
        }
    }
}

import java.util.Scanner;

/**
 * Reads a 10×10 board of characters (‘X’ and ‘.’) and searches for a
 * sequence that satisfies the original logic.
 * If such a sequence exists the program prints "YES" and terminates,
 * otherwise it prints "NO".
 */
public class DarshJava {

    /** Board size – kept as a single source of truth. */
    private static final int SIZE = 10;

    /** Characters used on the board. */
    private static final char MARK = 'X';
    private static final char EMPTY = '.';

    /**
     * Direction indices used by the original program (1‑8).
     * They correspond to the eight possible moves.
     */
    private enum Direction {
        // (row offset, column offset)
        UP_LEFT(-1, -1),
        UP(-1, 0),
        UP_RIGHT(-1, 1),
        RIGHT(0, 1),
        DOWN_RIGHT(1, 1),
        DOWN(1, 0),
        DOWN_LEFT(1, -1),
        LEFT(0, -1);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        /** Retrieve a Direction by its 1‑based index used elsewhere. */
        static Direction fromIndex(int idx) {
            return values()[idx - 1];
        }

        /** Helper used when checking boundaries for the licence test. */
        boolean isInBounds(int r, int c) {
            return r >= 0 && r < SIZE && c >= 0 && c < SIZE;
        }
    }

    /**
     * Recursively explores a path starting from (row, col) moving in
     * {@code dirIdx} direction.
     *
     * @param board     the game board
     * @param row       current row
     * @param col       current column
     * @param dirIdx    direction index (1‑8)
     * @param xs        number of consecutive ‘X’ visited so far
     * @param point     flag indicating whether a '.' has already been used (0/1)
     * @param lic       “licence” flag – 1 if an adjacent '.' exists in the chosen direction
     * @return true if a successful path was found (prints “YES” and exits)
     */
    private static boolean explore(char[][] board, int row, int col,
                                   int dirIdx, int xs, int point, int lic) {
        // Success condition from the original code
        if (xs == 4 && (point == 1 || lic == 1)) {
            System.out.println("YES");
            System.exit(0);
        }

        Direction dir = Direction.fromIndex(dirIdx);
        int nextRow = row + dir.dr;
        int nextCol = col + dir.dc;

        // Out‑of‑bounds guard
        if (!dir.isInBounds(nextRow, nextCol)) {
            return false;
        }

        char cell = board[nextRow][nextCol];

        if (cell == MARK) {
            // Continue along ‘X’ cells, but only while we have not used up the '.' quota
            if (point < 2) {
                if (explore(board, nextRow, nextCol, dirIdx, xs + 1, point, lic)) {
                    return true;
                }
            }
        } else if (cell == EMPTY && point == 0) {
            // First time we step onto a '.' – mark it and continue
            if (explore(board, nextRow, nextCol, dirIdx, xs, 1, lic)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Determines the “licence” flag used by the original program.
     * It checks the neighbour cell in the given direction for a '.'.
     *
     * @param board   the game board
     * @param row     current row index
     * @param col     current column index
     * @param dirIdx  direction index (1‑8)
     * @return 1 if the neighbouring cell contains '.', otherwise 0
     */
    private static int computeLic(char[][] board, int row, int col, int dirIdx) {
        // The original logic inspected specific neighbour cells depending on dirIdx.
        // We reproduce that exact series of checks.
        switch (dirIdx) {
            case 1 -> {
                if (row + 1 < SIZE && col + 1 < SIZE && board[row + 1][col + 1] == EMPTY) {
                    return 1;
                }
            }
            case 2 -> {
                if (row + 1 < SIZE && board[row + 1][col] == EMPTY) {
                    return 1;
                }
            }
            case 3 -> {
                if (row + 1 < SIZE && col - 1 >= 0 && board[row + 1][col - 1] == EMPTY) {
                    return 1;
                }
            }
            case 4 -> {
                if (col - 1 >= 0 && board[row][col - 1] == EMPTY) {
                    return 1;
                }
            }
            case 5 -> {
                if (row - 1 >= 0 && col - 1 >= 0 && board[row - 1][col - 1] == EMPTY) {
                    return 1;
                }
            }
            case 6 -> {
                if (row - 1 >= 0 && board[row - 1][col] == EMPTY) {
                    return 1;
                }
            }
            case 7 -> {
                if (row - 1 >= 0 && col + 1 < SIZE && board[row - 1][col + 1] == EMPTY) {
                    return 1;
                }
            }
            case 8 -> {
                if (col + 1 < SIZE && board[row][col + 1] == EMPTY) {
                    return 1;
                }
            }
        }
        return 0;
    }

    /** Entry point – reads input, drives the search and prints the result. */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[SIZE][SIZE];

        // ---- input ---------------------------------------------------------
        for (int i = 0; i < SIZE; i++) {
            String line = scanner.next();
            for (int j = 0; j < SIZE; j++) {
                board[i][j] = line.charAt(j);
            }
        }

        // ---- search --------------------------------------------------------
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (board[i][j] == MARK) {
                    // Try all eight directions from this cell
                    for (int dirIdx = 1; dirIdx <= 8; dirIdx++) {
                        int lic = computeLic(board, i, j, dirIdx);
                        explore(board, i, j, dirIdx, 1, 0, lic);
                    }
                }
            }
        }

        // ---- no successful path found ---------------------------------------
        System.out.println("NO");
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Main entry point of the program.
 *
 * The program reads a 10×10 board consisting of 'X' and '.' characters.
 * It determines whether placing a single 'X' on any empty cell would create a
 * line of at least four consecutive 'X's horizontally, vertically or
 * diagonally.  If such a move exists the program prints "YES", otherwise it
 * prints "NO".
 */
public class Main {

    private static final int BOARD_SIZE = 10;

    public static void main(String[] args) {
        try {
            new Game().run();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }
}

/**
 * Reads the board and delegates the validation logic to {@link CharBoard}.
 */
class Game {

    private final CharBoard board = new CharBoard();

    /** Entry point called from {@code Main#main}. */
    void run() throws IOException {
        readBoard();
        if (board.hasFourInARowAfterPlacing()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    private void readBoard() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            board.setRow(i, line.toCharArray());
        }
    }
}

/**
 * Represents the 10×10 game board and encapsulates all logic related to
 * checking whether a new piece creates a line of four or more 'X's.
 */
class CharBoard {

    private static final int SIZE = 10;
    private final char[][] grid = new char[SIZE][SIZE];

    /** Populate a single row of the board. */
    void setRow(int index, char[] data) {
        System.arraycopy(data, 0, grid[index], 0, SIZE);
    }

    /**
     * Determines whether any empty cell contains a line of four or more 'X's
     * after placing an 'X' there.
     */
    boolean hasFourInARowAfterPlacing() {
        for (int r = 0; r < SIZE; r++) {
            for (int c = 0; c < SIZE; c++) {
                if (grid[r][c] == '.') {
                    if (canPlaceFourHere(r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Temporarily places an 'X' at (row, col) and checks the resulting board. */
    private boolean canPlaceFourHere(int row, int col) {
        grid[row][col] = 'X';          // place the piece
        boolean result = hasFourInLine(row, col);
        grid[row][col] = '.';          // undo the placement
        return result;
    }

    /** Checks all four directions for a line of four or more 'X's. */
    private boolean hasFourInLine(int startRow, int startCol) {
        return checkDirection(startRow, startCol, 0, 1)   // horizontal
                || checkDirection(startRow, startCol, 1, 0)   // vertical
                || checkDirection(startRow, startCol, 1, 1)   // diagonal down‑right
                || checkDirection(startRow, startCol, 1, -1); // diagonal down‑left
    }

    /** Counts consecutive 'X's starting from (row, col) moving (dr, dc). */
    private int countInDirection(int row, int col, int dr, int dc) {
        int count = 1; // the current cell is already 'X'
        int r = row + dr;
        int c = col + dc;
        while (isInside(r, c) && grid[r][c] == 'X') {
            count++;
            r += dr;
            c += dc;
        }
        // also examine the opposite direction
        r = row - dr;
        c = col - dc;
        while (isInside(r, c) && grid[r][c] == 'X') {
            count++;
            r -= dr;
            c -= dc;
        }
        return count;
    }

    /** Returns true if the line in the given direction contains at least four 'X's. */
    private boolean checkDirection(int row, int col, int dr, int dc) {
        return countInDirection(row, col, dr, dc) >= 4;
    }

    /** Checks whether the supplied coordinates are inside the board. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < SIZE && c >= 0 && c < SIZE;
    }
}

import java.io.*;
import java.util.*;
import java.util.regex.Pattern;

/**
 * Reads a 10×10 grid of strings and decides whether any row, column or diagonal
 * contains one of the following patterns:
 *   .XXXX , X.XXX , XX.XX , XXX.X , XXXX.
 *
 * These patterns are identified using a compiled regular expression, which makes
 * the detection logic easy to read and maintain.
 */
public class Solution {

    /** Size of the square board used in the problem. */
    private static final int BOARD_SIZE = 10;

    /** Regular expression that captures all required winning patterns. */
    private static final Pattern WIN_PATTERN =
            Pattern.compile("(?=\\.XXXX|X\\.XXX|XX\\.XX|XXX\\.|XXXX\\.)");

    /** All rows extracted from the input. */
    private final List<String> rows;

    /** All columns extracted from the rows. */
    private final List<String> columns;

    /** All main and anti‑diagonals extracted from the rows. */
    private final List<String> diagonals;

    /**
     * Constructs the analyzer for a board described by the supplied rows.
     *
     * @param rows list of 10 strings, each representing a row of the board
     */
    public Solution(List<String> rows) {
        this.rows = new ArrayList<>(rows);
        this.columns = extractColumns();
        this.diagonals = extractDiagonals();
    }

    /** Extracts the columns of the board. */
    private List<String> extractColumns() {
        List<String> cols = new ArrayList<>(BOARD_SIZE);
        for (int i = 0; i < BOARD_SIZE; i++) {
            StringBuilder sb = new StringBuilder(BOARD_SIZE);
            for (String row : rows) {
                sb.append(row.charAt(i));
            }
            cols.add(sb.toString());
        }
        return cols;
    }

    /** Extracts all main and anti‑diagonals of the board. */
    private List<String> extractDiagonals() {
        List<String> diags = new ArrayList<>();

        // Diagonals that start from the top row and go down‑right
        for (int offset = 0; offset < BOARD_SIZE; offset++) {
            StringBuilder sb = new StringBuilder();
            int i = 0, j = offset;
            while (i < BOARD_SIZE && j < BOARD_SIZE) {
                sb.append(rows.get(i).charAt(j));
                i++;
                j++;
            }
            diags.add(sb.toString());
        }

        // Diagonals that start from the top row and go down‑left
        for (int offset = 0; offset < BOARD_SIZE; offset++) {
            StringBuilder sb = new StringBuilder();
            int i = 0, j = BOARD_SIZE - 1 - offset;
            while (i < BOARD_SIZE && j >= 0) {
                sb.append(rows.get(i).charAt(j));
                i++;
                j--;
            }
            diags.add(sb.toString());
        }

        return diags;
    }

    /**
     * Checks whether any row, column or diagonal contains a winning pattern.
     *
     * @return {@code true} if a pattern is found, otherwise {@code false}
     */
    public boolean hasWinningPattern() {
        List<String> allLines = new ArrayList<>();
        allLines.addAll(rows);
        allLines.addAll(columns);
        allLines.addAll(diagonals);

        for (String line : allLines) {
            if (WIN_PATTERN.matcher(line).find()) {
                return true;
            }
        }
        return false;
    }

    /** Simple fast scanner used for competitive‑programming input. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next token or {@code null} if the input is exhausted. */
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Read exactly BOARD_SIZE tokens (the rows of the 10×10 board)
        List<String> rows = new ArrayList<>(BOARD_SIZE);
        for (int i = 0; i < BOARD_SIZE; i++) {
            rows.add(fs.next());
        }

        Solution analyzer = new Solution(rows);
        boolean found = analyzer.hasWinningPattern();
        out.println(found ? "YES" : "NO");
        out.flush();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Connect‑Five solver.
 *
 * Reads a 10×10 board consisting of '.' (empty) and 'X' (already placed).
 * Determines whether placing a single additional 'X' in any empty cell
 * creates a line of at least five consecutive 'X's (horizontally,
 * vertically or diagonally). If such a move exists, prints "YES",
 * otherwise prints "NO".
 */
public class ConnectFiveSolver {

    /** Board dimension – the problem guarantees a 10×10 board. */
    private static final int SIZE = 10;

    /** Length of a winning line. */
    private static final int WIN_LENGTH = 5;

    public static void main(String[] args) throws IOException {
        char[][] board = readBoard();

        // Try placing an 'X' at every empty cell.
        for (int row = 0; row < SIZE; row++) {
            for (int col = 0; col < SIZE; col++) {
                if (board[row][col] == '.' && isWinningMove(board, row, col)) {
                    System.out.println("YES");
                    return;
                }
            }
        }

        System.out.println("NO");
    }

    /** Reads exactly 10 lines from standard input and stores them into a char matrix. */
    private static char[][] readBoard() throws IOException {
        char[][] board = new char[SIZE][SIZE];
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            for (int i = 0; i < SIZE; i++) {
                String line = br.readLine();
                if (line == null) {
                    continue;
                }
                for (int j = 0; j < SIZE; j++) {
                    board[i][j] = line.charAt(j);
                }
            }
        }
        return board;
    }

    /**
     * Checks whether putting an 'X' at (row, col) creates a winning line.
     * The method temporarily modifies the board, validates the win,
     * then restores the original cell.
     */
    private static boolean isWinningMove(char[][] board, int row, int col) {
        board[row][col] = 'X';                // place the candidate move
        boolean win = hasFiveInARow(board);   // does it win?
        board[row][col] = '.';                // revert change
        return win;
    }

    /**
     * Scans the whole board for any horizontal, vertical or diagonal line
     * of exactly {@value WIN_LENGTH} consecutive 'X's.
     */
    private static boolean hasFiveInARow(char[][] board) {
        // Horizontal
        for (int r = 0; r < SIZE; r++) {
            for (int c = 0; c <= SIZE - WIN_LENGTH; c++) {
                if (matchesX(board, r, c, 0, 1)) {
                    return true;
                }
            }
        }
        // Vertical
        for (int c = 0; c < SIZE; c++) {
            for (int r = 0; r <= SIZE - WIN_LENGTH; r++) {
                if (matchesX(board, r, c, 1, 0)) {
                    return true;
                }
            }
        }
        // Diagonal down‑right
        for (int r = 0; r <= SIZE - WIN_LENGTH; r++) {
            for (int c = 0; c <= SIZE - WIN_LENGTH; c++) {
                if (matchesX(board, r, c, 1, 1)) {
                    return true;
                }
            }
        }
        // Diagonal down‑left
        for (int r = 0; r <= SIZE - WIN_LENGTH; r++) {
            for (int c = WIN_LENGTH - 1; c < SIZE; c++) {
                if (matchesX(board, r, c, 1, -1)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks whether the five cells starting at (startRow, startCol) and
     * extending by increments {@code dr}/{@code dc} are all 'X'.
     */
    private static boolean matchesX(char[][] b, int startRow, int startCol,
                                    int dr, int dc) {
        for (int i = 0; i < WIN_LENGTH; i++) {
            int r = startRow + i * dr;
            int c = startCol + i * dc;
            if (b[r][c] != 'X') {
                return false;
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original “Main” class.
 * The program reads a 10×10 board, temporarily places an ‘X’ on each empty cell
 * and checks whether any player now has five consecutive marks in any direction.
 * If such a sequence exists the output is “YES”, otherwise “NO”.
 */
public class Main {

    /** Board size (fixed by the problem). */
    private static final int SIZE = 10;
    /** Length of a winning line. */
    private static final int CONNECT = 5;
    /** Modulo constant kept from the original source (currently unused). */
    private static final int MOD = 1_000_000_007;

    /** Character used for an empty cell. */
    private static final char EMPTY = '.';
    /** Character used for the player mark we are testing. */
    private static final char PLAYER = 'X';

    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees the PrintWriter is closed.
        try (PrintWriter out = new PrintWriter(System.out)) {
            char[][] board = readBoard();
            boolean winExists = hasAnyFiveInARow(board, PLAYER);
            out.println(winExists ? "YES" : "NO");
        }
    }

    /**
     * Reads ten lines from standard input and stores them as a 10×10 char grid.
     */
    private static char[][] readBoard() throws IOException {
        char[][] board = new char[SIZE][SIZE];
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        for (int i = 0; i < SIZE; i++) {
            String line = br.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            board[i] = line.toCharArray();
        }
        return board;
    }

    /**
     * Determines whether the given player has any consecutive five‑mark line
     * on the board (horizontal, vertical or either diagonal).
     */
    private static boolean hasAnyFiveInARow(char[][] board, char player) {
        return hasSequence(board, player, 0, 1)   // horizontal
                || hasSequence(board, player, 1, 0)   // vertical
                || hasSequence(board, player, 1, 1)   // diagonal \
                || hasSequence(board, player, 1, -1); // diagonal /
    }

    /**
     * Checks whether there exists a run of {@value CONNECT} consecutive {@code player}
     * marks starting from any cell that fits the given step vector.
     */
    private static boolean hasSequence(char[][] b, char player, int dRow, int dCol) {
        for (int r = 0; r < SIZE; r++) {
            for (int c = 0; c < SIZE; c++) {
                if (canPlaceFiveFrom(r, c, dRow, dCol) && isFiveInDirection(b, r, c, dRow, dCol, player)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Returns {@code true} if a five‑cell segment starting at (r,c) with step (dr,dc)
     * stays completely inside the board. */
    private static boolean canPlaceFiveFrom(int r, int c, int dr, int dc) {
        int endR = r + (CONNECT - 1) * dr;
        int endC = c + (CONNECT - 1) * dc;
        return endR >= 0 && endR < SIZE && endC >= 0 && endC < SIZE;
    }

    /** Verifies that the five cells in the given direction equal {@code player}. */
    private static boolean isFiveInDirection(char[][] b, int startR, int startC,
                                             int dr, int dc, char player) {
        for (int i = 0; i < CONNECT; i++) {
            int r = startR + i * dr;
            int c = startC + i * dc;
            if (b[r][c] != player) {
                return false;
            }
        }
        return true;
    }
}

