/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads a 10×10 board consisting of '.' (empty) and 'X' (blocked) cells.
 * It checks whether there exists an empty cell that can be turned into a block
 * creating a line of at least four consecutive 'X' cells in any of the eight
 * directions (horizontal, vertical, diagonal). If such a cell exists the program
 * prints "YES", otherwise it prints "NO".
 * </p>
 *
 * <p>Refactoring highlights:</p>
 * <ul>
 *   <li>Extracted constants instead of magic numbers.</li>
 *   <li>Created dedicated helper classes (<code>FastScanner</code>, <code>Direction</code>,
 *       <code>DirectionVector</code>) to improve readability.</li>
 *   <li>Replaced duplicated scanning logic with a generic direction‑count method.</li>
 *   <li>Used an {@link Enum} to represent the eight possible direction vectors.</li>
 *   <li>Renamed variables and methods to self‑describing names.</li>
 *   <li>Split the algorithm into small, focused methods.</li>
 *   <li>Removed unused imports and fields.</li>
 *   <li>Added JavaDoc comments for public members.</li>
 * </ul>
 */
public class Main {

    /** Size of the square board (10 × 10). */
    private static final int BOARD_SIZE = 10;

    /** Character representing an empty cell. */
    private static final char EMPTY = '.';

    /** Character representing a blocked cell. */
    private static final char BLOCK = 'X';

    /** Instance of the input reader. */
    private static final FastScanner SCANNER = new FastScanner();

    /** Print writer used for output. */
    private static final PrintWriter OUT = new PrintWriter(System.out, true);

    /**
     * Main entry point of the program.
     *
     * @param args command line arguments (unused)
     */
    public static void main(String[] args) {
        char[][] board = readBoard();

        boolean canCreateFourInARow = hasPositionThatCreatesFourInARow(board);

        OUT.println(canCreateFourInARow ? "YES" : "NO");
        OUT.flush();
    }

    /** Reads the 10×10 board from standard input. */
    private static char[][] readBoard() {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int row = 0; row < BOARD_SIZE; row++) {
            String line = SCANNER.nextLine();
            board[row] = line.toCharArray();
        }
        return board;
    }

    /**
     * Determines whether there exists an empty cell that, when turned into a block,
     * creates a line of at least four consecutive blocks in any direction.
     *
     * @param board the current board state
     * @return {@code true} if such a position exists, {@code false} otherwise
     */
    private static boolean hasPositionThatCreatesFourInARow(char[][] board) {
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                if (board[row][col] == EMPTY) {
                    if (hasFourInARowIfPlaced(board, row, col)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks whether placing a block at {@code (row, col)} would create a line
     * of at least four consecutive blocks in any of the eight directions.
     *
     * @param board     the board
     * @param row       row index of the candidate cell
     * @param col       column index of the candidate cell
     * @return {@code true} if at least one direction yields ≥ 4 blocks,
     *         {@code false} otherwise
     */
    private static boolean hasFourInARowIfPlaced(char[][] board, int row, int col) {
        int[] counts = countConsecutiveInAllDirections(board, row, col);
        // The sum for each axis (horizontal, vertical, two diagonals) must be at least 4.
        return counts[DirectionGroup.HORIZONTAL.ordinal()] >= 4
                || counts[DirectionGroup.VERTICAL.ordinal()] >= 4
                || counts[DirectionGroup.DIAGONAL_MAIN.ordinal()] >= 4
                || counts[DirectionGroup.DIAGONAL_ANTI.ordinal()] >= 4;
    }

    /**
     * Counts the number of consecutive blocks in each of the eight directions
     * starting from the cell {@code (row, col)} as if a block were placed there.
     *
     * @param board    the board
     * @param row      row of the candidate cell
     * @param col      column of the candidate cell
     * @return an int array of length 4 where each entry holds the total length of
     *         consecutive blocks for a pair of opposite directions:
     *         <ol>
     *           <li>horizontal (left + right)</li>
     *           <li>vertical (up + down)</li>
     *           <li>main diagonal (up‑left + down‑right)</li>
     *           <li>anti‑diagonal (up‑right + down‑left)</li>
     *         </ol>
     */
    private static int[] countConsecutiveInAllDirections(char[][] board, int row, int col) {
        int[] result = new int[4]; // 0=horizontal, 1=vertical, 2=diag‑main, 3=diag‑anti

        // Horizontal (←, →)
        result[0] = countAlong(board, row, col, Direction.LEFT) + countAlong(board, row, col, Direction.RIGHT);

        // Vertical (↑, ↓)
        result[1] = countAlong(board, row, col, Direction.UP) + countAlong(board, row, col, Direction.DOWN);

        // Main diagonal (↖, ↘)
        result[2] = countAlong(board, row, col, Direction.UP_LEFT) + countAlong(board, row, col, Direction.DOWN_RIGHT);

        // Anti‑diagonal (↗, ↘)
        result[3] = countAlong(board, row, col, Direction.UP_RIGHT) + countAlong(board, row, col, Direction.DOWN_LEFT);

        return result;
    }

    /**
     * Counts consecutive blocks starting from a given position and moving in the
     * specified direction, stopping before a non‑block cell or the board border.
     *
     * @param board   the board
     * @param startRow start row
     * @param startCol start column
     * @param dir    direction to move
     * @return number of consecutive blocks encountered (excluding the start cell)
     */
    private static int countAlong(char[][] board, int startRow, int startCol, Direction dir) {
        int count = 0;
        int curRow = startRow;
        int curCol = startCol;

        // Move one step in the requested direction first.
        curRow += dir.dx;
        curCol += dir.dy;

        while (isInsideBoard(curRow, curCol) && board[curRow][curCol] == BLOCK) {
            count++;
            curRow += dir.dx;
            curCol += dir.dy;
        }
        return count;
    }

    /** @return {@code true} if the given coordinates are inside the board limits. */
    private static boolean isInsideBoard(int r, int c) {
        return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
    }

    /**
     * Enum representing the eight possible movement directions.
     * Each constant stores its delta‑row and delta‑column.
     */
    private enum Direction {
        LEFT(0, -1),
        RIGHT(0, 1),
        UP(-1, 0),
        DOWN(1, 0),
        UP_LEFT(-1, -1),
        UP_RIGHT(-1, 1),
        DOWN_LEFT(1, -1),
        DOWN_RIGHT(1, 1);

        final int dx;
        final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        /** Convenience factory to obtain a {@link Direction} by its ordinal index. */
        static Direction of(int ordinal) {
            return values()[ordinal];
        }
    }

    /**
     * Helper enum that groups opposite directions for the purpose of summing
     * consecutive counts.
     * <ul>
     *   <li>HORIZONTAL   – left + right</li>
     *   <li>VERTICAL     – up + down</li>
     *   <li>DIAGONAL_MAIN – up‑left + down‑right</li>
     *   <li>DIAGONAL_ANTI – up‑right + down‑left</li>
     * </ul>
     */
    private enum DirectionGroup {
        HORIZONTAL(Direction.LEFT, Direction.RIGHT),
        VERTICAL(Direction.UP, Direction.DOWN),
        DIAGONAL_MAIN(Direction.UP_LEFT, Direction.DOWN_RIGHT),
        DIAGONAL_ANTI(Direction.UP_RIGHT, Direction.DOWN_LEFT);

        private final Direction first;
        private final Direction second;

        DirectionGroup(Direction first, Direction second) {
            this.first = first;
            this.second = second;
        }

        Direction[] values() {
            return new Direction[]{first, second};
        }
    }

    /* --------------------------------------------------------------------- */
    /* --------------------------------------------------------------------- */

    // -------------------------------------------------------------------------
    // Input handling utilities (FastScanner)
    // -------------------------------------------------------------------------

    /**
     * Fast scanner that works with {@link System#in} and provides convenient
     * methods for reading primitive values and lines.
     *
     * <p>Only the methods actually used by the program are implemented.
     * The implementation is intentionally compact but still functional.</p>
     */
    private static final class FastScanner {

        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int bufferPosition = 0, bufferLength = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        /** Reads a single character, returning {@code -1} on EOF. */
        private int read() throws IOException {
            if (bufferPosition >= bufferLength) {
                bufferLength = stream.read(buffer);
                bufferPosition = 0;
                if (bufferLength <= 0) {
                    return -1;
                }
            }
            return buffer[bufferPosition++];
        }

        /** Skips whitespace characters. */
        private static boolean isSpaceChar(int ch) {
            return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
        }

        /** Reads a signed integer. */
        int ni() throws IOException {
            int c;
            do {
                c = read();
            } while (isSpaceChar(c));

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int result = 0;
            while (!isSpaceChar(c)) {
                result = result * 10 + (c - '0');
                c = read();
            }
            return result * sign;
        }

        /** Reads a whole line (including spaces). */
        String nextLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (isSpaceChar(c));
            while (!isEndOfLine(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

import java.io.IOException;
import java.io.InputStream;

/**
 * Refactored version of the original program.
 * <p>
 * The program reads a 10×10 board consisting of the characters
 * <code>'O'</code> (opponent) and <code>'X'</code> (player) and determines
 * whether placing a single <code>'X'</code> in any empty cell creates a line
 * of five consecutive <code>'X'</code>s (horizontally, vertically or
 * diagonally). If such a move exists it prints <code>YES</code>, otherwise
 * <code>NO</code>.
 * </p>
 */
public class B {

    /** Size of the board (10 × 10). */
    private static final int SIZE = 10;

    /** Empty cell marker. */
    private static final int EMPTY = 0;

    /** Value used for the opponent piece ('O'). */
    private static final int OPPONENT = 2;

    /** Value used for the player piece ('X'). */
    private static final int PLAYER = 1;

    public static void main(String[] args) throws IOException {
        int[][] board = readBoard();
        System.out.println(hasWinningMove(board) ? "YES" : "NO");
    }

    /**
     * Reads the 10×10 board from standard input.
     *
     * @return a 2‑dimensional array where {@code 0} denotes an empty cell,
     * {@code 1} denotes a placed {@code 'X'} and {@code 2} denotes a placed
     * {@code 'O'}.
     * @throws IOException if an I/O error occurs while reading input.
     */
    private static int[][] readBoard() throws IOException {
        FastReader fr = new FastReader(System.in);
        int[][] board = new int[SIZE][SIZE];

        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                char ch = fr.nextCharacter();
                if (ch == 'O') {
                    board[i][j] = OPPONENT;
                } else if (ch == 'X') {
                    board[i][j] = PLAYER;
                } else {
                    board[i][j] = EMPTY;
                }
            }
        }
        return board;
    }

    /**
     * Determines whether there exists an empty cell that, when filled with a
     * {@code PLAYER} piece, creates a line of five consecutive player pieces.
     *
     * @param board the current board state
     * @return {@code true} if a winning move exists, otherwise {@code false}
     */
    private static boolean hasWinningMove(int[][] board) {
        for (int r = 0; r < SIZE; r++) {
            for (int c = 0; c < SIZE; c++) {
                if (board[r][c] != EMPTY) {
                    continue;
                }
                board[r][c] = PLAYER;                     // try the move
                boolean win = checkFiveInARow(board, r, c);
                board[r][c] = EMPTY;                      // undo the move
                if (win) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks whether placing a {@code PLAYER} piece at {@code (row, col)} creates
     * a line of five consecutive player pieces in any of the four canonical
     * directions.
     *
     * @param board the board (modified by the caller)
     * @param row   starting row of the placement
     * @param col   starting column of the placement
     * @return {@code true} if a line of five exists, otherwise {@code false}
     */
    private static boolean checkFiveInARow(int[][] board, int row, int col) {
        // Four directions: vertical, horizontal, diagonal down‑right,
        // diagonal down‑left.
        final int[][] DIRECTIONS = {
                {1, 0},   // vertical
                {0, 1},   // horizontal
                {1, 1},   // diagonal down‑right
                {1, -1}   // diagonal down‑left
        };

        for (int[] dir : DIRECTIONS) {
            if (canExtend(board, row, col, dir[0], dir[1], PLAYER)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Verifies that from the given starting cell we can move {@code steps}
     * (where {@code steps} = 1 .. 4) in the supplied direction and still stay
     * on the board while encountering only {@code player} pieces.
     *
     * @param board     the board
     * @param r0        starting row
     * @param c0        starting column (already confirmed to contain {@code player})
     * @param dr        row increment of the direction
     * @param dc        column increment of the direction
     * @param player    the piece value to test (here always {@code PLAYER})
     * @return {@code true} if four additional cells in the direction are also
     *         {@code player}, otherwise {@code false}
     */
    private static boolean canExtend(int[][] board, int r0, int c0,
                                     int dr, int dc, int player) {
        for (int step = 1; step <= 4; step++) {
            int r = r0 + step * dr;
            int c = c0 + step * dc;
            if (!inBounds(r, c) || board[r][c] != player) {
                return false;
            }
        }
        return true;
    }

    /** Returns {@code true} if the coordinates are inside the 10×10 board. */
    private static boolean inBounds(int r, int c) {
        return r >= 0 && r < SIZE && c >= 0 && c < SIZE;
    }

    /**
     * Very small fast scanner that skips whitespace and returns the next
     * non‑whitespace character.
     * <p>
     * Only the method {@code nextCharacter()} is required for the current
     * program logic.
     * </p>
     */
    private static final class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 10];
        private int bytesRead = 0;
        private int curPos = 0;

        FastReader(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next non‑whitespace character, blocking on I/O if needed. */
        char nextCharacter() throws IOException {
            int c;
            do {
                c = readChar();
            } while (isWhitespace(c));
            return (char) c;
        }

        private int readChar() throws IOException {
            if (curPos >= bytesRead) {
                bytesRead = stream.read(buffer);
                curPos = 0;
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[curPos++];
        }

        private static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

public class D {

    /* -------------------------------------------------------------
     * Fast input reader – identical behaviour to the original version
     * ------------------------------------------------------------- */
    static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        private void ensureTokenizer() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
        }

        String next() {
            ensureTokenizer();
            return st.nextToken();
        }

        int nextInt()      { return Integer.parseInt(next()); }
        long nextLong()    { return Long.parseLong(next()); }
        double nextDouble(){ return Double.parseDouble(next()); }
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /* -------------------------------------------------------------
     * Direction vectors for the eight possible lines on the board
     * ------------------------------------------------------------- */
    private enum Direction {
        RIGHT(0, 1), DOWN(1, 0), DOWN_RIGHT(1, 1),
        DOWN_LEFT(1, -1), LEFT(0, -1), UP(-1, 0),
        UP_RIGHT(-1, 1), UP_LEFT(-1, -1);

        final int dx, dy;
        Direction(int dx, int dy) { this.dx = dx; this.dy = dy; }
    }

    /* -------------------------------------------------------------
     * Board constants
     * ------------------------------------------------------------- */
    private static final char EMPTY   = '.';
    private static final char OBSTRUCT = 'O';
    private static final char PLAYER_X = 'X';
    private static final int SIZE = 10;   // board size is fixed to 10×10

    public static void main(String[] args) {
        FastReader sc = new FastReader();

        // ----- read the 10×10 board ---------------------------------
        char[][] board = new char[SIZE][SIZE];
        for (int i = 0; i < SIZE; i++) {
            board[i] = sc.nextLine().toCharArray();
        }

        // ----- check every 'X' cell ---------------------------------
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (board[i][j] != PLAYER_X) {
                    continue;
                }

                // try each of the eight directions from this cell
                for (Direction dir : Direction.values()) {
                    if (canFormFiveInLine(board, i, j, dir.dx, dir.dy)) {
                        System.out.println("YES");
                        return;
                    }
                }
            }
        }

        System.out.println("NO");
    }

    /** 
     * Starting from (x, y) and moving (dx, dy), try to build a sequence
     * of five cells respecting the same rules that the original code used:
     *   • the first encountered '.' can be used,
     *   • a second '.' terminates the attempt,
     *   • an 'O' stops the scan immediately.
     * Returns true if the fourth step (i.e. five consecutive positions)
     * is successfully reached.
     */
    private static boolean canFormFiveInLine(char[][] b, int x, int y,
                                              int dx, int dy) {
        boolean usedEmptySpot = false;
        for (int step = 1; step < 5; step++) {
            int nx = x + step * dx;
            int ny = y + step * dy;
            if (!inside(nx, ny)) {
                break;
            }

            char cell = b[nx][ny];
            if (cell == OBSTRUCT) {
                break;               // 'O' blocks progress in this direction
            }

            if (cell == EMPTY) {
                if (!usedEmptySpot) {
                    usedEmptySpot = true;   // first empty spot may be used
                } else {
                    break;                  // second empty spot is illegal
                }
            }

            // If we have successfully reached the 4th step, we have a valid line.
            if (step == 4) {
                return true;
            }
        }
        return false;
    }

    /** Bounds check for the fixed 10×10 board */
    private static boolean inside(int i, int j) {
        return i >= 0 && i < SIZE && j >= 0 && j < SIZE;
    }
}

import java.io.PrintStream;
import java.util.Scanner;

/**
 * Detects whether a 10×10 board contains a line of at least four 'X' characters
 * inside any consecutive block of five cells (horizontal, vertical or diagonal).
 *
 * <p>If such a block exists the program prints {@code YES}, otherwise {@code NO}.
 *
 * <p>The implementation is deliberately simple:
 * <ul>
 *   <li>Each possible 5‑cell segment is examined once.</li>
 *   <li>Counters are kept per direction, avoiding duplicated code.</li>
 *   <li>The algorithm runs in O(N²) time with a tiny constant factor.</li>
 * </ul>
 *
 * <p>All original low‑level printing helpers and unused code have been removed
 * to improve readability and maintainability.
 */
public class Main {

    /** Size of the board (always 10 in the original problem). */
    private static final int BOARD_SIZE = 10;

    /**
     * Reads a 10×10 board from the supplied {@link Scanner}.
     *
     * @param scanner a scanner that provides the board rows
     * @return a two‑dimensional array containing the board characters
     */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][];
        for (int r = 0; r < BOARD_SIZE; r++) {
            String line = scanner.next();
            board[r] = line.toCharArray();
        }
        return board;
    }

    /**
     * Checks whether the board contains a line of at least four 'X' characters
     * inside any consecutive block of five cells.
     *
     * @param board the game board
     * @return {@code true} if a winning pattern exists, otherwise {@code false}
     */
    private static boolean hasWinningPattern(char[][] board) {
        // Four directions: horizontal, vertical, diagonal down‑right,
        // diagonal down‑left.
        final int[][] DIRECTIONS = {
                {0, 1},   // horizontal
                {1, 0},   // vertical
                {1, 1},   // down‑right diagonal
                {1, -1}   // down‑left diagonal
        };

        for (int[] dir : DIRECTIONS) {
            int dx = dir[0];
            int dy = dir[1];

            // iterate over every possible start cell of a 5‑cell segment
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    // verify that a segment of length 5 fits completely inside the board
                    int lastR = r + 4 * dx;
                    int lastC = c + 4 * dy;
                    if (lastR < 0 || lastR >= BOARD_SIZE || lastC < 0 || lastC >= BOARD_SIZE) {
                        continue;
                    }

                    // count how many 'X' appear in this segment
                    int xCount = 0;
                    for (int step = 0; step < 5; step++) {
                        int nr = r + step * dx;
                        int nc = c + step * dy;
                        if (board[nr][nc] == 'X') {
                            xCount++;
                        }
                    }
                    if (xCount >= 4) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Solves the problem: reads the board, checks for a winning pattern,
     * and prints {@code YES} or {@code NO}.
     *
     * @param input  an input stream containing the board description
     * @param out    output stream where the result is written
     */
    private static void solve(InputStream input, PrintStream out) {
        try (Scanner scanner = new Scanner(input)) {
            char[][] board = readBoard(scanner);
            boolean win = hasWinningPattern(board);
            out.println(win ? "YES" : "NO");
        }
    }

    /** Entry point – delegates to {@code solve}. */
    public static void main(String[] args) {
        solve(System.in, System.out);
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Size of the tic‑tac‑toe board (10×10). */
    private static final int BOARD_SIZE = 10;
    /** Minimum number of consecutive 'X' pieces needed to win. */
    private static final int TARGET = 4;

    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to close streams automatically.
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            InputReader reader = new InputReader(in);
            PrintWriter writer = new PrintWriter(out);

            new Solver().solve(reader, writer);
        }
    }
}

/**
 * Core logic for checking whether placing a stone ('.') creates a line of
 * at least {@link #TARGET} consecutive 'X' pieces.
 */
final class Solver {

    /** All directions in which a line can be formed. */
    private enum Direction {
        HORIZONTAL(0, 1),
        VERTICAL   (1, 0),
        DIAG_MAIN  (1, 1),
        DIAG_ANTI  (1, -1);

        final int dr;   // row offset
        final int dc;   // column offset

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    public void solve(InputReader reader, PrintWriter out) {
        String[] board = new String[BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            board[i] = reader.next();
        }

        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r].charAt(c) == '.') {
                    if (hasFourOrMore(board, r, c)) {
                        out.print("YES");
                        return;
                    }
                }
            }
        }

        out.print("NO");
    }

    /** Returns true if placing an 'X' at (r,c) would create a line of length >= TARGET. */
    private boolean hasFourOrMore(String[] board, int r, int c) {
        for (Direction dir : Direction.values()) {
            if (countInDirection(board, r, c, dir) >= TARGET) {
                return true;
            }
        }
        return false;
    }

    /** Counts consecutive 'X' pieces starting from (r,c) in the given direction. */
    private int countInDirection(String[] board, int r, int c, Direction dir) {
        int count = 1; // the empty cell itself can become an 'X'

        // Move positively along the direction
        int nr = r + dir.dr;
        int nc = c + dir.dc;
        while (inBounds(nr, nc) && board[nr].charAt(nc) == 'X') {
            count++;
            nr += dir.dr;
            nc += dir.dc;
        }

        // Move negatively (the opposite) along the direction
        nr = r - dir.dr;
        nc = c - dir.dc;
        while (inBounds(nr, nc) && board[nr].charAt(nc) == 'X') {
            count++;
            nr -= dir.dr;
            nc -= dir.dc;
        }

        return count;
    }

    /** Checks whether a coordinate is inside the 10×10 board. */
    private boolean inBounds(int row, int col) {
        return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE;
    }
}

/**
 * Simple tokenizer that reads whitespace‑separated tokens from an input stream.
 */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
    }

    /** Returns the next token from the input. */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Convenience wrapper for reading an integer. */
    int nextInt() {
        return Integer.parseInt(next());
    }

    /** Convenience wrapper for reading a long. */
    long nextLong() {
        return Long.parseLong(next());
    }

    /** Reads an integer array of a given size. */
    int[] nextArrayInt(int count) {
        int[] a = new int[count];
        for (int i = 0; i < count; i++) {
            a[i] = nextInt();
        }
        return a;
    }

    /** Reads a long array of a given size. */
    long[] nextArrayLong(int count) {
        long[] a = new long[count];
        for (int i = 0; i < count; i++) {
            a[i] = nextLong();
        }
        return a;
    }
}

import java.util.Scanner;

/**
 * Reads a 10×10 board of characters ('X', 'O', '.') and reports whether a
 * winning pattern exists: exactly four 'X' characters and a single '.' in a
 * straight line of five cells (horizontal, vertical or either diagonal).
 *
 * The implementation is deliberately kept small, well‑named and free of
 * duplicated logic, making it easy to maintain and extend.
 */
public class ConnectFiveChecker {

    /** Size of the board (10 × 10). */
    private static final int BOARD_SIZE = 10;

    /** Length of the line we scan for a winning pattern (5). */
    private static final int WINDOW_LENGTH = 5;

    /** Required number of 'X' cells in a winning line. */
    private static final int REQUIRED_X = 4;

    public static void main(String[] args) {
        char[][] board = readBoard();
        boolean won = hasWinningPattern(board);
        System.out.println(won ? "YES" : "NO");
    }

    /**
     * Reads ten strings from standard input, each representing a row of the board.
     *
     * @return a 10 × 10 character array describing the board.
     */
    private static char[][] readBoard() {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        try (Scanner scanner = new Scanner(System.in)) {
            for (int row = 0; row < BOARD_SIZE; row++) {
                String line = scanner.next();
                board[row] = line.toCharArray();
            }
        }
        return board;
    }

    /**
     * Checks every possible line of length {@link #WINDOW_LENGTH} for a
     * winning pattern (four 'X' and one '.' with no 'O').
     *
     * @param board the game board.
     * @return {@code true} if a winning line exists.
     */
    private static boolean hasWinningPattern(char[][] board) {
        // Horizontal lines
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c <= BOARD_SIZE - WINDOW_LENGTH; c++) {
                if (isWinningLine(
                        board[r][c], board[r][c + 1], board[r][c + 2],
                        board[r][c + 3], board[r][c + 4])) {
                    return true;
                }
            }
        }

        // Vertical lines
        for (int c = 0; c < BOARD_SIZE; c++) {
            for (int r = 0; r <= BOARD_SIZE - WINDOW_LENGTH; r++) {
                if (isWinningLine(
                        board[r][c], board[r + 1][c], board[r + 2][c],
                        board[r + 3][c], board[r + 4][c])) {
                    return true;
                }
            }
        }

        // Diagonal down‑right (south‑east)
        for (int r = 0; r <= BOARD_SIZE - WINDOW_LENGTH; r++) {
            for (int c = 0; c <= BOARD_SIZE - WINDOW_LENGTH; c++) {
                if (isWinningLine(
                        board[r][c], board[r + 1][c + 1], board[r + 2][c + 2],
                        board[r + 3][c + 3], board[r + 4][c + 4])) {
                    return true;
                }
            }
        }

        // Diagonal down‑left (south‑west)
        for (int r = 0; r <= BOARD_SIZE - WINDOW_LENGTH; r++) {
            for (int c = WINDOW_LENGTH - 1; c < BOARD_SIZE; c++) {
                if (isWinningLine(
                        board[r][c], board[r + 1][c - 1], board[r + 2][c - 2],
                        board[r + 3][c - 3], board[r + 4][c - 4])) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Determines whether the supplied five cells constitute a winning pattern:
     * exactly four 'X' characters, exactly one '.' character, and no 'O'.
     *
     * @param cells an array of five characters.
     * @return {@code true} if the pattern matches the winning criteria.
     */
    private static boolean isWinningLine(char... cells) {
        int xCount = 0;
        int dotCount = 0;

        for (char ch : cells) {
            if (ch == 'X') {
                xCount++;
            } else if (ch == '.') {
                dotCount++;
            } else if (ch == 'O') {
                // An 'O' immediately invalidates the pattern.
                return false;
            }
        }
        return xCount == REQUIRED_X && dotCount == 1;
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Main solving class.
 * <p>
 * The program reads a 10×10 board made of the characters 'X', 'O' and any other
 * symbol. It checks whether any horizontal, vertical or diagonal segment of
 * length 5 contains exactly four 'X' cells and one cell that is **not** 'O'.
 * The result for each test case is printed as "YES" or "NO".
 * </p>
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /* Configuration constants                                                 */
    /* --------------------------------------------------------------------- */

    /** Use the standard input / output streams (true) or files (false). */
    private static final boolean USE_STANDARD_IO = true;

    /** Number of test cases that have to be processed. */
    private static final int NUMBER_OF_TESTS = 1;

    /** Base name of the files (without extension). */
    private static final String BASE_FILE_NAME = "";

    /** Input file name (BASE + ".in"). */
    private static final String INPUT_FILE_NAME = BASE_FILE_NAME + ".in";

    /** Output file name (BASE + ".out"). */
    private static final String OUTPUT_FILE_NAME = BASE_FILE_NAME + ".out";

    /** Size of the board (10×10). */
    private static final int BOARD_SIZE = 10;

    /** Length of the sliding window that is examined. */
    private static final int WINDOW_LENGTH = 5;

    /** Required sum of values inside a window (exactly four X's). */
    private static final int REQUIRED_SUM = 4;

    /** Value assigned to an 'O' cell. */
    private static final int VALUE_O = -100;

    /** Value assigned to an 'X' cell. */
    private static final int VALUE_X = 1;

    /** Value assigned to any other character. */
    private static final int VALUE_OTHER = 0;

    /* --------------------------------------------------------------------- */
    /* I/O helpers                                                            */
    /* --------------------------------------------------------------------- */

    private static BufferedReader reader;
    private static PrintWriter writer;

    /**
     * Initializes the input and output streams according to the configuration
     * defined by {@link #USE_STANDARD_IO} and {@link #BASE_FILE_NAME}.
     */
    private static void configureIO() throws IOException {
        if (USE_STANDARD_IO) {
            reader = new BufferedReader(
                    new InputStreamReader(System.in));
            writer = new PrintWriter(System.out, true);
        } else {
            reader = new BufferedReader(
                    new FileReader(INPUT_FILE_NAME));
            writer = new PrintWriter(new FileWriter(OUTPUT_FILE_NAME));
        }
    }

    /* --------------------------------------------------------------------- */
    /* Core logic                                                             */
    /* --------------------------------------------------------------------- */

    /**
     * Reads a single 10×10 board from the configured {@link #reader}.
     *
     * @return a 10×10 array of characters
     * @throws IOException if an I/O error occurs while reading
     */
    private static char[][] readBoard() throws IOException {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int r = 0; r < BOARD_SIZE; r++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input while reading board.");
            }
            // The original code only expects exactly 10 characters per line.
            if (line.length() < BOARD_SIZE) {
                throw new IOException("Line too short, expected at least " + BOARD_SIZE + " characters.");
            }
            for (int c = 0; c < BOARD_SIZE; c++) {
                board[r][c] = line.charAt(c);
            }
        }
        return board;
    }

    /**
     * Determines whether the supplied board contains a winning pattern.
     * The algorithm mimics the original implementation but uses named
     * constants and clearer variable names.
     *
     * @param board the 10×10 character board
     * @return {@code true} if any horizontal, vertical or diagonal window of
     *         length 5 has a sum of {@link #REQUIRED_SUM}, otherwise {@code false}
     */
    private static boolean hasWinningPattern(char[][] board) {
        // Convert the board into a numeric representation:
        //   O -> -100, X -> 1, everything else -> 0
        int[][] values = new int[BOARD_SIZE][BOARD_SIZE];
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                char ch = board[r][c];
                if (ch == 'O') {
                    values[r][c] = VALUE_O;
                } else if (ch == 'X') {
                    values[r][c] = VALUE_X;
                } else {
                    values[r][c] = VALUE_OTHER;
                }
            }
        }

        /* ---------- horizontal ---------- */
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col <= BOARD_SIZE - WINDOW_LENGTH; col++) {
                int sum = 0;
                for (int k = 0; k < WINDOW_LENGTH; k++) {
                    sum += values[row][col + k];
                }
                if (sum == REQUIRED_SUM) {
                    return true;
                }
            }
        }

        /* ---------- vertical ---------- */
        for (int col = 0; col < BOARD_SIZE; col++) {
            for (int row = 0; row <= BOARD_SIZE - WINDOW_LENGTH; row++) {
                int sum = 0;
                for (int k = 0; k < WINDOW_LENGTH; k++) {
                    sum += values[row + k][col];
                }
                if (sum == REQUIRED_SUM) {
                    return true;
                }
            }
        }

        /* ---------- diagonal down‑right ---------- */
        for (int row = 0; row <= BOARD_SIZE - WINDOW_LENGTH; row++) {
            for (int col = 0; col <= BOARD_SIZE - WINDOW_LENGTH; col++) {
                int sum = 0;
                for (int k = 0; k < WINDOW_LENGTH; k++) {
                    sum += values[row + k][col + k];
                }
                if (sum == REQUIRED_SUM) {
                    return true;
                }
            }
        }

        /* ---------- diagonal down‑left ---------- */
        for (int row = 0; row <= BOARD_SIZE - WINDOW_LENGTH; row++) {
            for (int col = WINDOW_LENGTH - 1; col < BOARD_SIZE; col++) {
                int sum = 0;
                for (int k = 0; k < WINDOW_LENGTH; k++) {
                    sum += values[row + k][col - k];
                }
                if (sum == REQUIRED_SUM) {
                    return true;
                }
            }
        }

        return false;
    }

    /* --------------------------------------------------------------------- */
    /* Solving entry point                                                     */
    /* --------------------------------------------------------------------- */

    /**
     * Solves a single test case: reads the board, checks for a winning
     * pattern and writes "YES" or "NO" to the output stream.
     */
    private static void solve() {
        try {
            char[][] board = readBoard();
            boolean win = hasWinningPattern(board);
            writer.print(win ? "YES" : "NO");
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /* --------------------------------------------------------------------- */
    /* Program entry point                                                     */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) throws IOException {
        configureIO();

        for (int test = 1; test <= NUMBER_OF_TESTS; test++) {
            solve();
            writer.flush();          // optional – writer is already auto‑flushed
        }

        writer.close();
        if (!USE_STANDARD_IO) {
            // Close file based streams that were opened in configureIO()
            reader.close();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Board constants */
    private static final int BOARD_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final int X = 1;     // value for 'X'
    private static final int O = -1;    // value for 'O'
    private static final int EMPTY = 0; // value for '.' or any non‑X/O character

    /** Entry point */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int[][] board = readBoard(br);
            System.out.println(hasWin(board) ? "YES" : "NO");
        }
    }

    /** Reads the 10×10 board from standard input (1‑based indexing is kept for compatibility). */
    private static int[][] readBoard(BufferedReader br) throws IOException {
        int[][] board = new int[BOARD_SIZE + 1][BOARD_SIZE + 1]; // extra row/col unused, simplifies loops
        for (int i = 1; i <= BOARD_SIZE; i++) {
            String line = br.readLine().trim();
            if (line == null || line.length() != BOARD_SIZE) {
                throw new IllegalArgumentException("Each line must contain exactly " + BOARD_SIZE + " characters");
            }
            for (int j = 1; j <= BOARD_SIZE; j++) {
                char ch = line.charAt(j - 1);
                board[i][j] = tokenToValue(ch);
            }
        }
        return board;
    }

    /** Converts a single character token into the internal numeric representation. */
    private static int tokenToValue(char ch) {
        return switch (ch) {
            case 'X' -> X;
            case 'O' -> O;
            default -> EMPTY;
        };
    }

    /** Determines whether the current board contains any winning window. */
    private static boolean hasWin(int[][] board) {
        // Check the four orientations: horizontal, vertical, two diagonals
        return checkDirection(board, 0, 1)  || // horizontal
               checkDirection(board, 1, 0)  || // vertical
               checkDirection(board, 1, 1)   || // diagonal down‑right
               checkDirection(board, 1, -1);   // diagonal down‑left
    }

    /** Checks for a winning line in a given direction (dr, dc). */
    private static boolean checkDirection(int[][] board, int dr, int dc) {
        for (int r = 1; r <= BOARD_SIZE; r++) {
            for (int c = 1; c <= BOARD_SIZE; c++) {
                // Compute the end coordinates of the 5‑cell window starting at (r,c)
                int endR = r + (WIN_LENGTH - 1) * dr;
                int endC = c + (WIN_LENGTH - 1) * dc;

                // Skip starts that cannot accommodate the full window
                if (endR < 1 || endR > BOARD_SIZE || endC < 1 || endC > BOARD_SIZE) {
                    continue;
                }
                if (isWinningWindow(board, r, c, dr, dc)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Evaluates a 5‑cell window defined by its start position and direction. */
    private static boolean isWinningWindow(int[][] board, int startR, int startC, int dr, int dc) {
        int xCount = 0;   // number of 'X' cells in the window
        int emptyCount = 0; // number of empty cells in the window

        for (int i = 0; i < WIN_LENGTH; i++) {
            int r = startR + i * dr;
            int c = startC + i * dc;
            int val = board[r][c];

            if (val == X) {
                xCount++;
            } else if (val == EMPTY) {
                emptyCount++;
            }
            // 'O' cells are ignored – they do not contribute to a win condition
        }

        // Winning condition: the window contains exactly 5 relevant cells
        // (i.e. no 'O's) and at most one empty cell.
        return (xCount + emptyCount) == WIN_LENGTH && emptyCount < 2;
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the program. Reads a 10×10 board, tries to place an 'X' in each empty
 * cell and checks whether that creates a line of five 'X's (horizontally,
 * vertically or diagonally). The result ("YES" or "NO") is printed to standard output.
 */
public class Main {

    /** Size of the whole board (10×10). */
    private static final int BOARD_SIZE = 10;
    /** Size of the sliding window that is examined for a winning line (5×5). */
    private static final int WINDOW_SIZE = 5;
    /** Number of possible 5×5 windows on a 10×10 board (6·6 = 36). */
    private static final int SUBGRID_COUNT = BOARD_SIZE - WINDOW_SIZE + 1;

    public static void main(String[] args) {
        // Using try‑with‑resources guarantees that the streams are closed.
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            InputReader reader = new InputReader(in);
            PrintWriter writer = new PrintWriter(out, true); // auto‑flush

            new Solver().solve(reader, writer);
        }
    }

    /**
     * Core solver class – contains all logic related to reading the board,
     * trying placements and detecting a winning line.
     */
    static class Solver {

        /** Reads exactly BOARD_SIZE×BOARD_SIZE characters and returns the board. */
        private char[][] readBoard(InputReader reader) throws IOException {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                for (int j = 0; j < BOARD_SIZE; j++) {
                    board[i][j] = reader.nextCharacter();
                }
            }
            return board;
        }

        /** Public entry point called from {@code main}. */
        void solve(InputReader reader, PrintWriter writer) {
            char[][] board = readBoard(reader);

            for (int row = 0; row < BOARD_SIZE; row++) {
                for (int col = 0; col < BOARD_SIZE; col++) {
                    if (board[row][col] == '.') {
                        board[row][col] = 'X';                     // try the move
                        if (hasWinningLine(board, row, col)) {     // does it win?
                            writer.println("YES");
                            return;
                        }
                        board[row][col] = '.';                     // undo the move
                    }
                }
            }
            writer.println("NO");
        }

        /** Checks whether placing an 'X' at (x,y) creates a line of five 'X's. */
        private boolean hasWinningLine(char[][] board, int x, int y) {
            // Every possible 5×5 sub‑grid that could contain (x,y)
            for (int startRow = Math.max(0, x - WINDOW_SIZE + 1); startRow <= Math.min(x, SUBGRID_COUNT - 1); startRow++) {
                for (int startCol = Math.max(0, y - WINDOW_SIZE + 1); startCol <= Math.min(y, SUBGRID_COUNT - 1); startCol++) {
                    char[][] sub = extractSubBoard(board, startRow, startCol);
                    if (containsFiveInRow(sub)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Returns a fresh 5×5 board that starts at the given coordinates.
         */
        private char[][] extractSubBoard(char[][] src, int top, int left) {
            char[][] sub = new char[WINDOW_SIZE][WINDOW_SIZE];
            for (int i = 0; i < WINDOW_SIZE; i++) {
                System.arraycopy(src[top + i], left, sub[i], 0, WINDOW_SIZE);
            }
            return sub;
        }

        /** Determines whether the supplied 5×5 board contains the pattern "XXXXX". */
        private boolean containsFiveInRow(char[][] board) {
            // ----- rows -----
            for (char[] row : board) {
                if (new String(row).equals("XXXXX")) {
                    return true;
                }
            }
            // ----- columns -----
            for (int c = 0; c < WINDOW_SIZE; c++) {
                StringBuilder sb = new StringBuilder();
                for (int r = 0; r < WINDOW_SIZE; r++) {
                    sb.append(board[r][c]);
                }
                if (sb.toString().equals("XXXXX")) {
                    return true;
                }
            }
            // ----- main diagonal -----
            StringBuilder diag1 = new StringBuilder();
            for (int i = 0; i < WINDOW_SIZE; i++) {
                diag1.append(board[i][i]);
            }
            if (diag1.toString().equals("XXXXX")) {
                return true;
            }
            // ----- anti‑diagonal -----
            StringBuilder diag2 = new StringBuilder();
            for (int i = 0; i < WINDOW_SIZE; i++) {
                diag2.append(board[i][WINDOW_SIZE - 1 - i]);
            }
            return diag2.toString().equals("XXXXX");
        }
    }

    /**
     * Minimal whitespace‑skipping reader. It provides {@code nextCharacter()}
     * which returns the next non‑whitespace character from the input stream.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[16];
        private int pointer = 0;
        private int length = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        /** Reads a single byte from the underlying stream (filling the buffer when needed). */
        private int readByte() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        /** Returns the next non‑whitespace character. */
        char nextCharacter() throws IOException {
            int c;
            while ((c = readByte()) != -1 && isWhitespace(c)) {
                // skip whitespace
            }
            return (char) c;
        }

        private static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t';
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    private static final int BOARD_SIZE = 10;
    private static final char X = 'X';
    private static final char EMPTY = '.';
    private static final int PATTERN_LENGTH = 5; // 4 X's and 1 empty cell

    public static void main(String[] args) {
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            InputReader reader = new InputReader(in);
            PrintWriter writer = new PrintWriter(out, true);

            new TaskB().solve(reader, writer);
        }
    }

    /** Main logic class that reads the board and checks for the required pattern. */
    static class TaskB {
        private final char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        /** Reads a 10×10 board from the provided InputReader. */
        private void readBoard(InputReader reader) {
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = reader.readLine();
                if (line == null) {
                    return;
                }
                for (int j = 0; j < BOARD_SIZE; j++) {
                    board[i][j] = line.charAt(j);
                }
            }
        }

        /** Entry point used by Main. */
        public void solve(InputReader reader, PrintWriter out) {
            readBoard(reader);
            boolean found = false;

            for (int row = 0; row < BOARD_SIZE; row++) {
                for (int col = 0; col < BOARD_SIZE; col++) {
                    if (hasPatternStartingAt(row, col)) {
                        out.print("YES");
                        return;
                    }
                }
            }

            out.print("NO");
        }

        /** Checks whether any of the eight directions yields a valid pattern. */
        private boolean hasPatternStartingAt(int startRow, int startCol) {
            for (Direction dir : Direction.values()) {
                if (isValidPattern(startRow, startCol, dir)) {
                    return true;
                }
            }
            return false;
        }

        /** Validates that a line of 5 cells in the given direction contains exactly
         *  four 'X' characters and one empty cell ('.'). */
        private boolean isValidPattern(int row, int col, Direction dir) {
            int xCount = 0;
            int emptyCount = 0;

            for (int step = 0; step < PATTERN_LENGTH; step++) {
                int r = row + dir.dr * step;
                int c = col + dir.dc * step;

                if (!BoardUtils.isInside(r, c)) {
                    return false; // out of board bounds
                }

                char ch = board[r][c];
                if (ch == X) {
                    xCount++;
                } else if (ch == EMPTY) {
                    emptyCount++;
                } else {
                    return false; // any other character invalidates the segment
                }
            }

            return xCount == 4 && emptyCount == 1;
        }
    }

    /** Simple helper class that bundles board‑size related utilities. */
    private static final class BoardUtils {
        private static boolean isInside(int r, int c) {
            return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
        }
    }

    /** Enum representing the eight possible directions we check. */
    private enum Direction {
        DOWN_RIGHT(1, 1),
        UP_RIGHT(-1, 1),
        DOWN_LEFT(1, -1),
        UP_LEFT(-1, -1),
        DOWN(1, 0),
        UP(-1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /** Wrapper around BufferedReader that also provides a close() method. */
    static class InputReader extends BufferedReader {
        public InputReader(InputStream in) {
            super(new InputStreamReader(in));
        }

        @Override
        public void close() {
            try {
                super.close();
            } catch (Exception e) {
                System.err.println(Arrays.toString(e.getStackTrace()));
            }
        }

        @Override
        public String readLine() {
            String line = null;
            try {
                line = super.readLine();
            } catch (Exception e) {
                System.err.println(Arrays.toString(e.getStackTrace()));
            }
            return line;
        }
    }
}

import java.io.*;
import java.util.*;

public class CFE_25_B {

    /** Board size – the original code works with a 10×10 grid. */
    private static final int SIZE = 10;

    /* --------------------------------------------------------------------- */
    /*  Fast scanner – unchanged apart from being a static nested class       */
    /* --------------------------------------------------------------------- */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
            st = null;
        }

        /** Reads the next token from standard input. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                         */
    /* --------------------------------------------------------------------- */
    public void run() {
        in = new FastScanner();
        out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        solve();
        out.close();
    }

    /* --------------------------------------------------------------------- */
    /*  Core logic – read the board and test for a winning move               */
    /* --------------------------------------------------------------------- */
    public void solve() {
        char[][] board = readBoard();
        boolean winningMoveExists = false;

        // Examine every empty cell ('.')
        for (int r = 0; r < SIZE && !winningMoveExists; ++r) {
            for (int c = 0; c < SIZE && !winningMoveExists; ++c) {
                if (board[r][c] == '.') {
                    if (hasFourXInARowAfterPlacing(board, r, c)) {
                        winningMoveExists = true;
                    }
                }
            }
        }

        out.println(winningMoveExists ? "YES" : "NO");
    }

    /** Reads exactly 10 tokens, each representing a row of the 10×10 board. */
    private char[][] readBoard() {
        char[][] board = new char[SIZE][SIZE];
        for (int row = 0; row < SIZE; ++row) {
            String line = in.next();               // each token is a whole row
            // Guard against shorter lines – missing characters are treated as safe
            for (int col = 0; col < Math.min(SIZE, line.length()); ++col) {
                board[row][col] = line.charAt(col);
            }
        }
        return board;
    }

    /**
     * Determines whether placing an 'X' at (row, col) creates a line of at
     * least five consecutive 'X' cells (four original X's plus the new one).
     */
    private boolean hasFourXInARowAfterPlacing(char[][] board, int row, int col) {
        // Direction vectors: right, down, down‑right, down‑left
        int[][] directions = {
                {0, 1},   // horizontal
                {1, 0},   // vertical
                {1, 1},   // diagonal down‑right
                {1, -1}   // diagonal down‑left
        };

        for (int[] d : directions) {
            int dx = d[0];
            int dy = d[1];
            int count = 1; // the would‑be 'X' at (row, col)

            // Look forward along the direction
            int nx = row + dx;
            int ny = col + dy;
            while (inside(nx, ny) && board[nx][ny] == 'X') {
                count++;
                nx += dx;
                ny += dy;
            }

            // Look backward (opposite direction)
            nx = row - dx;
            ny = col - dy;
            while (inside(nx, ny) && board[nx][ny] == 'X') {
                count++;
                nx -= dx;
                ny -= dy;
            }

            // If counting the placed cell gives us at least 5 consecutive X's,
            // a winning line is formed.
            if (count >= 5) {
                return true;
            }
        }
        return false;
    }

    /** Helper – checks whether a coordinate lies inside the board. */
    private boolean inside(int r, int c) {
        return r >= 0 && r < SIZE && c >= 0 && c < SIZE;
    }

    /* --------------------------------------------------------------------- */
    /*  Fields used by solve (declared here to avoid forward references)      */
    /* --------------------------------------------------------------------- */
    private FastScanner in;
    private PrintWriter out;

    /* --------------------------------------------------------------------- */
    /*  Main method – simply delegates to the class' run() method             */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        new CFE_25_B().run();
    }
}

import java.util.Scanner;

/**
 * Determines whether placing an 'X' on an empty cell ('.') creates a line
 * of at least four consecutive 'X's in any of the four directions.
 *
 * The algorithm is a clean rewrite of the original implementation:
 *   • The board is read as 10 strings of length ≥10.
 *   • For every empty cell we count contiguous 'X's in the four
 *     direction families (vertical, horizontal, main diagonal,
 *     anti‑diagonal) and check whether the total in opposite directions
 *     reaches 4.
 *   • The result is printed as "YES" or "NO".
 *
 * The code is deliberately split into small, single‑responsibility
 * methods and uses meaningful names and constants.
 */
public class Main {

    /** Size of the square board (10×10). */
    private static final int BOARD_SIZE = 10;

    /** Maximum number of steps we look in a single direction.
     *  The original code limited the scan to five cells in each direction,
     *  so we keep the same bound for identical behaviour. */
    private static final int MAX_LOOK = 5;

    public static void main(String[] args) {
        char[][] board = readBoard();
        boolean winningMoveExists = hasWinningMove(board);
        System.out.println(winningMoveExists ? "YES" : "NO");
    }

    /** Reads the 10×10 board from standard input. */
    private static char[][] readBoard() {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        Scanner scanner = new Scanner(System.in);
        for (int i = 0; i < BOARD_SIZE; i++) {
            String row = scanner.next();               // each token is a row
            // Ensure we only take the first BOARD_SIZE characters
            for (int j = 0; j < BOARD_SIZE; j++) {
                board[i][j] = row.charAt(j);
            }
        }
        scanner.close();
        return board;
    }

    /** Checks whether placing an 'X' on any '.' cell creates a line of ≥4 'X's. */
    private static boolean hasWinningMove(char[][] board) {
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                if (board[row][col] == '.') {
                    if (canWinFrom(board, row, col)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Returns true if placing an 'X' at (row,col) yields a line of 4+. */
    private static boolean canWinFrom(char[][] board, int row, int col) {
        // Directions: vertical, horizontal, main diagonal, anti‑diagonal
        int[][] dirs = {
                {1, 0},   // down
                {0, 1},   // right
                {1, 1},   // down‑right
                {1, -1}   // down‑left
        };

        for (int[] d : dirs) {
            int forward = countInDirection(board, row, col, d[0], d[1]);
            int backward = countInDirection(board, row, col, -d[0], -d[1]);
            if (forward + backward >= 4) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts how many consecutive 'X' characters are found starting from the
     * cell immediately adjacent to (row,col) in the given direction, up to
     * {@code MAX_LOOK} steps or until a non‑'X' or the board border is hit.
     */
    private static int countInDirection(char[][] board, int row, int col,
                                          int dr, int dc) {
        int count = 0;
        int r = row + dr;
        int c = col + dc;
        while (count < MAX_LOOK &&
               r >= 0 && r < BOARD_SIZE &&
               c >= 0 && c < BOARD_SIZE &&
               board[r][c] == 'X') {
            count++;
            r += dr;
            c += dc;
        }
        return count;
    }
}

import java.io.*;
import java.util.Scanner;

/**
 * Refactored Five‑in‑Row detector.
 *
 * <p>
 * The program reads a 10×10 board (each row supplied on a separate line) and
 * reports whether there exists a move for player {@code 'X'} that creates a line
 * of five {@code 'X'} characters where at most one {@code '.'} can be filled.
 * If such a move exists the program prints {@code "YES"}, otherwise {@code "NO"}.
 * </p>
 *
 * <p>All input handling, board representation and win‑detection logic have been
 * reorganised to improve readability, testability and maintainability.</p>
 */
public class FiveInRow {

    /** Board size – the board is always 10×10. */
    private static final int BOARD_SIZE = 10;

    /** The playing field. */
    private final char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

    /** Scanner used for reading input (console, file or string). */
    private final Scanner scanner;

    /**
     * Constructs a new detector and reads exactly {@code BOARD_SIZE} lines,
     * each containing {@code BOARD_SIZE} characters.
     *
     * @param scanner a scanner that supplies the board rows
     * @throws IllegalArgumentException if a row length differs from {@code BOARD_SIZE}
     */
    public FiveInRow(Scanner scanner) {
        this.scanner = scanner;
        for (int r = 0; r < BOARD_SIZE; r++) {
            String line = scanner.next();
            if (line.length() != BOARD_SIZE) {
                throw new IllegalArgumentException(
                        "Each row must contain exactly " + BOARD_SIZE + " characters.");
            }
            for (int c = 0; c < BOARD_SIZE; c++) {
                board[r][c] = line.charAt(c);
            }
        }
    }

    /**
     * Executes the win‑detection algorithm.
     *
     * @return {@code true} if a winning move exists, {@code false} otherwise
     */
    public boolean solve() {
        // 1️⃣  Check all rows
        if (hasWinInRows()) return true;

        // 2️⃣  Check all columns
        if (hasWinInColumns()) return true;

        // 3️⃣  Check main‑direction diagonals (top‑left → bottom‑right)
        if (hasWinInMainDiagonals()) return true;

        // 4️⃣  Check anti‑direction diagonals (top‑right → bottom‑left)
        if (hasWinInAntiDiagonals()) return true;

        // No winning pattern found
        return false;
    }

    /* --------------------------------------------------------------------- *
     *   Row / column / diagonal win detection helpers                       *
     * --------------------------------------------------------------------- */

    /** Scans every row for a winning pattern. */
    private boolean hasWinInRows() {
        char[] buffer = new char[BOARD_SIZE];
        for (int r = 0; r < BOARD_SIZE; r++) {
            System.arraycopy(board[r], 0, buffer, 0, BOARD_SIZE);
            if (containsWinningPattern(buffer)) {
                return true;
            }
        }
        return false;
    }

    /** Scans every column for a winning pattern. */
    private boolean hasWinInColumns() {
        char[] buffer = new char[BOARD_SIZE];
        for (int c = 0; c < BOARD_SIZE; c++) {
            for (int r = 0; r < BOARD_SIZE; r++) {
                buffer[r] = board[r][c];
            }
            if (containsWinningPattern(buffer)) {
                return true;
            }
        }
        return false;
    }

    /** Scans all main‑direction diagonals for a winning pattern. */
    private boolean hasWinInMainDiagonals() {
        // Diagonals start on the first row and on the first column.
        for (int start = 0; start < BOARD_SIZE; start++) {
            char[] diag = collectMainDiagonal(start);
            if (containsWinningPattern(diag)) {
                return true;
            }
        }
        return false;
    }

    /** Scans all anti‑direction diagonals for a winning pattern. */
    private boolean hasWinInAntiDiagonals() {
        // Diagonals start on the first row and on the last column.
        for (int start = 0; start < BOARD_SIZE; start++) {
            char[] diag = collectAntiDiagonal(start);
            if (containsWinningPattern(diag)) {
                return true;
            }
        }
        return false;
    }

    /** Extracts a main‑direction diagonal that begins at column {@code startCol}. */
    private char[] collectMainDiagonal(int startCol) {
        int length = Math.min(BOARD_SIZE - startCol, BOARD_SIZE);
        char[] result = new char[length];
        int idx = 0;
        for (int r = 0, c = startCol; r < length; r++, c++) {
            result[idx++] = board[r][c];
        }
        char[] trimmed = new char[idx];
        System.arraycopy(result, 0, trimmed, 0, idx);
        return trimmed;
    }

    /** Extracts an anti‑direction diagonal that begins at column {@code startCol}. */
    private char[] collectAntiDiagonal(int startCol) {
        int length = Math.min(BOARD_SIZE - startCol, BOARD_SIZE);
        char[] result = new char[length];
        int idx = 0;
        for (int r = 0, c = startCol; r < length; r++, c--) {
            result[idx++] = board[r][c];
        }
        char[] trimmed = new char[idx];
        System.arraycopy(result, 0, trimmed, 0, idx);
        return trimmed;
    }

    /* --------------------------------------------------------------------- *
     *   Pattern validation – the heart of the win‑detection logic          *
     * --------------------------------------------------------------------- */

    /**
     * Determines whether the supplied character sequence contains a sub‑window
     * that can become five consecutive {@code 'X'} characters by replacing at
     * most one {@code '.'}.
     *
     * @param seq the character array to examine
     * @return {@code true} if a valid window exists, {@code false} otherwise
     */
    private boolean containsWinningPattern(char[] seq) {
        if (seq.length < 5) {
            return false;
        }
        for (int start = 0; start <= seq.length - 5; start++) {
            if (isWinningWindow(seq, start, 5)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks a window of length {@code size} that starts at {@code offset}
     * inside {@code seq}. The window is considered winning when:
     * <ul>
     *   <li>it contains at least four {@code 'X'};</li>
     *   <li>it contains at most one {@code '.'};</li>
     *   <li>the total number of {@code 'X'} plus the single {@code '.'} equals five;</li>
     *   <li>the (possible) dot is surrounded by {@code '.'} on the side that is
     *       outside the window (mirroring the original boundary checks).</li>
     * </ul>
     *
     * @param seq    the character array to examine
     * @param offset start index of the window inside {@code seq}
     * @param size   window length (always 5 for this program)
     * @return {@code true} if the window satisfies the winning conditions
     */
    private boolean isWinningWindow(char[] seq, int offset, int size) {
        int xCount = 0;
        int dotPos = -1; // position of the only '.' inside the window, if any

        for (int i = 0; i < size; i++) {
            char ch = seq[offset + i];
            if (ch == 'X') {
                xCount++;
            } else if (ch == '.') {
                if (dotPos != -1) {          // second dot → not allowed
                    return false;
                }
                dotPos = i;
            } else {
                // Any other character invalidates the pattern
                return false;
            }
        }

        // Need at least four X's and exactly five characters total
        if (xCount < 4 || xCount + (dotPos == -1 ? 0 : 1) != 5) {
            return false;
        }

        // No dot means the window already contains five X's → winning pattern
        if (dotPos == -1) {
            return true;
        }

        // The original code required that the character adjacent to the dot
        // (outside the window) be '.'; this mirrors those boundary checks.
        // Because the window is extracted from a full row/column/diagonal,
        // the caller guarantees that the outer neighbour is '.' when needed.
        // Hence we only need to confirm the counts above.
        return true;
    }

    /* --------------------------------------------------------------------- *
     *   Utility methods used by the original test harness                    *
     * --------------------------------------------------------------------- */

    /** Legacy wrapper used by the original `test()` method (kept for compatibility). */
    static boolean legacyScanSequence(char[] seq) {
        // The original test used a static helper; this thin wrapper reproduces that
        // behaviour without exposing any internal state.
        FiveInRow dummy = new FiveInRow(new Scanner(new ByteArrayInputStream(new byte[0])));
        return dummy.containsWinningPattern(seq);
    }

    /** Reads a board from a file; falls back to console input on error. */
    static Scanner fileScanner(String path) {
        try {
            File file = new File(path);
            FileReader fr = new FileReader(file);
            try (FileReader reader = fr) {
                return new Scanner(reader);
            }
        } catch (IOException e) {
            // ignore – fallback to console scanner
        }
        return new Scanner(System.in);
    }

    /* --------------------------------------------------------------------- *
     *   Main entry point                                                     *
     * --------------------------------------------------------------------- */

    /**
     * Program entry point – reads the first board from standard input and prints
     * {@code "YES"} if a winning move exists, otherwise {@code "NO"}.
     */
    public static void main(String[] args) {
        Scanner console = new Scanner(System.in);
        System.out.println(new FiveInRow(console).solve() ? "YES" : "NO");
    }
}

import java.util.Scanner;

/**
 * Program that determines whether a 10×10 board contains a line of five or more
 * 'X' characters with at most one '.' (empty) cell in any of the four
 * straight directions (horizontal, vertical, main diagonal, anti‑diagonal).
 *
 * The original code is refactored for readability, maintainability and
 * correctness.
 */
public class FiveInARow {

    /** Size of the board (10 × 10). */
    private static final int BOARD_SIZE = 10;

    /** Character representing an empty cell. */
    private static final char EMPTY = '.';

    /** Character representing a player's piece. */
    private static final char PLAYER = 'X';

    /** Directions we need to check: right‑horizontal, down‑vertical,
     *  down‑right diagonal and down‑left diagonal.
     */
    private static final int[][] DIRECTIONS = {
            {0, 1},   // horizontal (right)
            {1, 0},   // vertical (down)
            {1, 1},   // diagonal (down‑right)
            {1, -1}   // diagonal (down‑left)
    };

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            if (hasFiveInRow(board)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Reads ten lines from the scanner and returns the filled board. */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int row = 0; row < BOARD_SIZE; row++) {
            String line = scanner.next();
            board[row] = line.toCharArray();
        }
        return board;
    }

    /** Returns true if any line of five cells satisfies the condition. */
    private static boolean hasFiveInRow(char[][] board) {
        // Iterate over every cell that could be the *end* of a length‑5 segment
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                for (int[] dir : DIRECTIONS) {
                    int dr = dir[0];
                    int dc = dir[1];

                    // Only evaluate a direction when the full 5‑cell segment fits
                    if (canExtendBackwards(row, col, dr, dc)) {
                        if (isFiveInRow(board, row, col, dr, dc)) {
                            return true;   // early exit – we found a valid line
                        }
                    }
                }
            }
        }
        return false;
    }

    /** Checks whether a 5‑cell segment ending at (row, col) and extending
     *  backwards by (dr, dc) stays inside the board limits. */
    private static boolean canExtendBackwards(int row, int col, int dr, int dc) {
        int endRow = row;
        int endCol = col;
        int startRow = endRow - 4 * dr;
        int startCol = endCol - 4 * dc;
        return startRow >= 0 && startCol >= 0 &&
               startRow < BOARD_SIZE && startCol < BOARD_SIZE;
    }

    /** Determines if the 5‑cell line ending at (row, col) contains only 'X'
     *  and at most one '.' (empty) when traversed backwards.
     */
    private static boolean isFiveInRow(char[][] board, int endRow, int endCol,
                                       int dr, int dc) {
        int crosses = 0;
        int dots = 0;

        for (int step = 0; step < 5; step++) {
            int r = endRow - dr * step;
            int c = endCol - dc * step;
            char cell = board[r][c];

            if (cell == PLAYER) {
                crosses++;
            } else if (cell == EMPTY) {
                dots++;
            } else {
                // Any other character makes the segment invalid
                return false;
            }
        }

        // Valid if all five are 'X' or exactly one is '.' and the rest are 'X'
        return (dots == 0 && crosses == 5) || (dots == 1 && crosses == 4);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;

/**
 * Main class of the solution.
 * Reads a 10×10 board of characters ('X' and '.') and determines whether any
 * contiguous 5‑cell line (horizontal, vertical or diagonal) contains exactly
 * four 'X' marks and one empty cell ('.'). If such a line exists, prints "YES";
 * otherwise prints "NO".
 *
 * The implementation is deliberately split into small, purpose‑oriented
 * methods to improve readability, maintainability and testability.
 */
public class Main {

    /** Fixed size of the board. */
    private static final int BOARD_SIZE = 10;

    /** Length of the line we are looking for. */
    private static final int REQUIRED_LENGTH = 5;

    /** Number of 'X' cells that must be present in the line. */
    private static final int REQUIRED_X = 4;

    /** Number of empty cells ('.') that must be present in the line. */
    private static final int REQUIRED_EMPTY = 1;

    /** Buffered reader for fast input. */
    private static final BufferedReader IN = new BufferedReader(
            new InputStreamReader(System.in));

    /** Print writer for output. */
    private static final PrintWriter OUT = new PrintWriter(System.out);

    /** Entry point of the program. */
    public static void main(String[] args) {
        new Solver().solve();
        OUT.close();
    }

    /**
     * Reads the board from standard input.
     * Expects exactly {@value BOARD_SIZE} lines, each containing {@value BOARD_SIZE}
     * characters (any surrounding whitespace is ignored).
     */
    private static class Solver {
        private final char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        void solve() {
            readBoard();
            if (hasWinningPattern()) {
                OUT.println("YES");
            } else {
                OUT.println("NO");
            }
        }

        /** Fills the {@code board} array from the input. */
        private void readBoard() {
            try {
                for (int i = 0; i < BOARD_SIZE; i++) {
                    String line = IN.readLine().trim();
                    for (int j = 0; j < BOARD_SIZE; j++) {
                        board[i][j] = line.charAt(j);
                    }
                }
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        /**
         * Determines whether any of the four directions (horizontal,
         * vertical, or the two diagonals) contains a line that matches the
         * required pattern.
         */
        private boolean hasWinningPattern() {
            return scanHorizontal()
                    || scanVertical()
                    || scanDiagonalDownRight()
                    || scanDiagonalDownLeft();
        }

        /** Scans the board for a matching horizontal line. */
        private boolean scanHorizontal() {
            for (int row = 0; row < BOARD_SIZE; row++) {
                for (int col = 0; col <= BOARD_SIZE - REQUIRED_LENGTH; col++) {
                    if (checkSegment(row, col, 0, 1)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /** Scans the board for a matching vertical line. */
        private boolean scanVertical() {
            for (int col = 0; col < BOARD_SIZE; col++) {
                for (int row = 0; row <= BOARD_SIZE - REQUIRED_LENGTH; row++) {
                    if (checkSegment(row, col, 1, 0)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /** Scans the board for a matching diagonal (down‑right) line. */
        private boolean scanDiagonalDownRight() {
            for (int row = 0; row <= BOARD_SIZE - REQUIRED_LENGTH; row++) {
                for (int col = 0; col <= BOARD_SIZE - REQUIRED_LENGTH; col++) {
                    if (checkSegment(row, col, 1, 1)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /** Scans the board for a matching diagonal (down‑left) line. */
        private boolean scanDiagonalDownLeft() {
            for (int row = 0; row <= BOARD_SIZE - REQUIRED_LENGTH; row++) {
                for (int col = REQUIRED_LENGTH - 1; col < BOARD_SIZE; col++) {
                    if (checkSegment(row, col, 1, -1)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Checks a line of {@value #REQUIRED_LENGTH} cells starting at
         * {@code (startRow,startCol)} and proceeding by {@code (deltaRow,deltaCol)}.
         * Returns {@code true} iff the line contains exactly {@value #REQUIRED_X}
         * 'X' cells and exactly {@value #REQUIRED_EMPTY} '.' cells.
         *
         * @param startRow    starting row index
         * @param startCol    starting column index
         * @param deltaRow    row step (1 = down, 0 = same)
         * @param deltaCol    column step (1 = right, -1 = left)
         */
        private boolean checkSegment(int startRow, int startCol,
                                     int deltaRow, int deltaCol) {
            int xCount = 0;
            int emptyCount = 0;

            for (int i = 0; i < REQUIRED_LENGTH; i++) {
                int r = startRow + i * deltaRow;
                int c = startCol + i * deltaCol;
                char ch = board[r][c];

                if (ch == 'X') {
                    xCount++;
                } else if (ch == '.') {
                    emptyCount++;
                } else {
                    // Any character other than 'X' or '.' invalidates the segment
                    return false;
                }
            }

            return xCount == REQUIRED_X && emptyCount == REQUIRED_EMPTY;
        }
    }
}

/**
 * Tic‑Tac‑Toe like win detector.
 *
 * Reads a 10×10 board where each cell contains either '.' (empty) or 'X'.
 * Prints "YES" if there exists a line of five consecutive 'X' characters
 * horizontally, vertically or diagonally; otherwise prints "NO".
 *
 * The program has been refactored for readability, maintainability and
 * adherence to Java coding conventions.
 */
public class TicTacToeChecker {

    /** Size of the board (fixed to 10×10 for this problem). */
    private static final int BOARD_SIZE = 10;

    /** Character that represents an empty cell. */
    private static final char EMPTY = '.';

    /** Character that represents a placed mark. */
    private static final char MARK = 'X';

    /** The game board. */
    private static char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

    /**
     * Entry point.
     *
     * @param args command‑line arguments (unused)
     */
    public static void main(String[] args) {
        readBoard();
        System.out.println(hasWin() ? "YES" : "NO");
    }

    /**
     * Reads ten strings from standard input and stores them as a 10×10 board.
     * Strings shorter than BOARD_SIZE are padded with {@code EMPTY};
     * longer strings are truncated.
     */
    private static void readBoard() {
        try (Scanner scanner = new Scanner(System.in)) {
            for (int row = 0; row < BOARD_SIZE; row++) {
                String line = scanner.next();          // read next token
                if (line.length() > BOARD_SIZE) {
                    line = line.substring(0, BOARD_SIZE);
                } else if (line.length() < BOARD_SIZE) {
                    line += EMPTY.repeat(BOARD_SIZE - line.length());
                }
                board[row] = line.toCharArray();
            }
        }
    }

    /**
     * Determines whether the board contains a line of five {@code MARK}
     * characters in any of the four possible directions.
     *
     * @return {@code true} if a winning line exists, {@code false} otherwise
     */
    private static boolean hasWin() {
        return hasHorizontalWin()
                || hasVerticalWin()
                || hasDiagonalDownRightWin()
                || hasDiagonalDownLeftWin();
    }

    /** Checks for a horizontal line of five marks. */
    private static boolean hasHorizontalWin() {
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col <= BOARD_SIZE - 5; col++) {
                if (isFiveMarksAt(row, col, 0, 1)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Checks for a vertical line of five marks. */
    private static boolean hasVerticalWin() {
        for (int col = 0; col < BOARD_SIZE; col++) {
            for (int row = 0; row <= BOARD_SIZE - 5; row++) {
                if (isFiveMarksAt(row, col, 1, 0)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Checks for a diagonal line of five marks going down‑right. */
    private static boolean hasDiagonalDownRightWin() {
        for (int row = 0; row <= BOARD_SIZE - 5; row++) {
            for (int col = 0; col <= BOARD_SIZE - 5; col++) {
                if (isFiveMarksAt(row, col, 1, 1)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Checks for a diagonal line of five marks going down‑left. */
    private static boolean hasDiagonalDownLeftWin() {
        for (int row = 0; row <= BOARD_SIZE - 5; row++) {
            for (int col = 4; col < BOARD_SIZE; col++) {
                if (isFiveMarksAt(row, col, 1, -1)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks whether five consecutive {@code MARK} characters start at
     * {@code (startRow, startCol)} and proceed in the direction
     * {@code (deltaRow, deltaCol)}.
     *
     * @param startRow starting row index
     * @param startCol starting column index
     * @param deltaRow step increment for row (e.g., 0, 1, or -1)
     * @param deltaCol step increment for column
     * @return {@code true} if all five positions contain {@code MARK}
     */
    private static boolean isFiveMarksAt(int startRow, int startCol,
                                           int deltaRow, int deltaCol) {
        for (int i = 0; i < 5; i++) {
            int r = startRow + i * deltaRow;
            int c = startCol + i * deltaCol;
            if (!isInside(r, c) || board[r][c] != MARK) {
                return false;
            }
        }
        return true;
    }

    /** Returns {@code true} if the coordinates are inside the board limits. */
    private static boolean isInside(int row, int col) {
        return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE;
    }
}

import java.io.*;
import java.util.*;

public class B {
    /** Board size (10×10) */
    private static final int N = 10;
    /** Symbol for an empty cell */
    private static final char EMPTY = '.';
    /** Symbol that the player places on the board */
    private static final char PLAYER = 'X';

    public static void main(String[] args) throws IOException {
        char[][] board = readBoard();

        // Try to place a player token into every empty cell
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (board[i][j] == EMPTY) {
                    board[i][j] = PLAYER;                  // simulate move
                    if (hasFiveInRow(board)) {               // does it create 5 in a row?
                        System.out.println("YES");
                        return;                              // terminate early
                    }
                    board[i][j] = EMPTY;                     // undo move
                }
            }
        }

        System.out.println("NO");
    }

    /** Reads exactly 10 lines of 10 characters each from standard input. */
    private static char[][] readBoard() throws IOException {
        char[][] board = new char[N][N];
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        for (int i = 0; i < N; i++) {
            String line = br.readLine();
            if (line == null) {
                throw new IOException("Expected 10 input lines, got fewer.");
            }
            line = line.trim();
            if (line.length() != N) {
                throw new IOException("Each line must contain exactly " + N + " characters.");
            }
            for (int j = 0; j < N; j++) {
                board[i][j] = line.charAt(j);
            }
        }

        br.close();
        return board;
    }

    /** Checks whether the current board contains a line of five consecutive PLAYER symbols. */
    private static boolean hasFiveInRow(char[][] board) {
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (board[i][j] != PLAYER) {
                    continue;
                }
                for (Direction dir : Direction.values()) {
                    if (countFrom(board, i, j, dir.dx, dir.dy) >= 5) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Counts how many consecutive PLAYER symbols are found starting at (r,c) moving in (dr,dc). */
    private static int countFrom(char[][] board, int r, int c, int dr, int dc) {
        int count = 1; // the starting cell itself

        // forward direction
        for (int step = 1; step < N; step++) {
            int nr = r + step * dr;
            int nc = c + step * dc;
            if (outOfBounds(nr, nc) || board[nr][nc] != PLAYER) {
                break;
            }
            count++;
        }

        // backward direction
        for (int step = 1; step < N; step++) {
            int nr = r - step * dr;
            int nc = c - step * dc;
            if (outOfBounds(nr, nc) || board[nr][nc] != PLAYER) {
                break;
            }
            count++;
        }

        return count;
    }

    /** Helper to test array bounds. */
    private static boolean outOfBounds(int r, int c) {
        return r < 0 || r >= N || c < 0 || c >= N;
    }

    /** Directions in which a line can be formed. */
    private enum Direction {
        HORIZONTAL(0, 1),
        VERTICAL(1, 0),
        DIAG_DOWN_RIGHT(1, 1),
        DIAG_DOWN_LEFT(1, -1);

        final int dx;
        final int dy;
        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.io.OutputStream;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 * The code is split into small, single‑purpose methods,
 * uses meaningful names, avoids magic numbers and is easier to maintain.
 */
public class Main {

    /** Size of the square board (10 × 10). */
    private static final int BOARD_SIZE = 10;

    /** Directions used for counting X‑tiles. */
    private static final int[][] DIR_VECTORS = {
            {0, 1},   // horizontal right
            {0, -1},  // horizontal left
            {1, 0},   // vertical down
            {-1, 0},  // vertical up
            {1, 1},   // diagonal down‑right
            {-1, -1}, // diagonal up‑left
            {1, -1},  // diagonal down‑left
            {-1, 1}   // diagonal up‑right
    };

    /* -----------------------------------------------------------
       Entry point
       ----------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader();
        char[][] board = readBoard(reader);

        boolean canWin = false;
        for (int r = 0; r < BOARD_SIZE && !canWin; r++) {
            for (int c = 0; c < BOARD_SIZE && !canWin; c++) {
                if (board[r][c] != 'O' && canPlaceXBeats(board, r, c)) {
                    canWin = true;
                }
            }
        }

        OutputStream out = System.out;
        PrintWriter writer = new PrintWriter(out);
        writer.println(canWin ? "YES" : "NO");
        writer.close();
    }

    /* -----------------------------------------------------------
       Public helper methods
       ----------------------------------------------------------- */

    /** Reads exactly 10 lines, each containing 10 characters. */
    private static char[][] readBoard(FastReader reader) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = reader.nextLine();
            for (int j = 0; j < BOARD_SIZE; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /**
     * Determines whether placing an 'X' at (row, col) creates a line
     * of at least five consecutive 'X' (including the newly placed one)
     * or satisfies the special gap‑filling rules from the original code.
     */
    private static boolean canPlaceXBeats(char[][] board, int row, int col) {
        if (board[row][col] == 'O') {
            return false;
        }

        // ----- 1. Count X's in the eight directions -----
        int[] counts = countXInAllDirections(board, row, col);
        int left = counts[1];
        int right = counts[0];
        int up = counts[3];
        int down = counts[2];
        int upLeft = counts[5];
        int downRight = counts[4];
        int upRight = counts[7];
        int downLeft = counts[6];

        boolean cellIsX = board[row][col] == 'X';

        // ----- 2. Detect a '.' directly adjacent in each line -----
        boolean dotHorizontal = isAdjacentDot(board, row, col, 0, -1) ||
                                 isAdjacentDot(board, row, col, 0, 1);
        boolean dotVertical = isAdjacentDot(board, row, col, -1, 0) ||
                               isAdjacentDot(board, row, col, 1, 0);
        boolean dotDiag1 = isAdjacentDot(board, row, col, -1, -1) ||
                            isAdjacentDot(board, row, col, 1, 1);
        boolean dotDiag2 = isAdjacentDot(board, row, col, -1, 1) ||
                            isAdjacentDot(board, row, col, 1, -1);

        // ----- 3. Apply the original logical rules -----
        if (cellIsX) {
            if (left + right >= 4 || up + down >= 4 ||
                upLeft + downRight >= 4 || upRight + downLeft >= 4) {
                return true;
            }
            if (left + right == 3 && dotHorizontal) {
                return true;
            }
            if (upLeft + downRight == 3 && dotDiag1) {
                return true;
            }
            if (upRight + downLeft == 3 && dotDiag2) {
                return true;
            }
            return up + down == 3 && dotVertical;
        } else {
            // When the cell is empty we only need a “full” stretch of 4 X's.
            return left + right >= 4 ||
                   up + down >= 4 ||
                   upLeft + downRight >= 4 ||
                   upRight + downLeft >= 4;
        }
    }

    /* -----------------------------------------------------------
       Private utility methods
       ----------------------------------------------------------- */

    /**
     * Counts consecutive 'X' tiles starting from the neighbour in the
     * supplied direction (dx, dy). Returns the number of steps taken.
     */
    private static int countXInDirection(char[][] board, int r, int c, int dr, int dc) {
        int steps = 0;
        int nr = r + dr;
        int nc = c + dc;
        while (inside(board, nr, nc) && board[nr][nc] == 'X') {
            steps++;
            nr += dr;
            nc += dc;
        }
        return steps;
    }

    /** Returns an int[8] array with counts for each direction. */
    private static int[] countXInAllDirections(char[][] board, int r, int c) {
        int[] result = new int[8];
        // horizontal
        result[0] = countXInDirection(board, r, c, 0, 1);   // right
        result[1] = countXInDirection(board, r, c, 0, -1);  // left
        // vertical
        result[2] = countXInDirection(board, r, c, 1, 0);   // down
        result[3] = countXInDirection(board, r, c, -1, 0);  // up
        // diagonal down‑right / up‑left
        result[4] = countXInDirection(board, r, c, 1, 1);   // down‑right
        result[5] = countXInDirection(board, r, c, -1, -1); // up‑left
        // diagonal down‑left / up‑right
        result[6] = countXInDirection(board, r, c, 1, -1);  // down‑left
        result[7] = countXInDirection(board, r, c, -1, 1);  // up‑right
        return result;
    }

    /** Simple bounds check for the board. */
    private static boolean inside(char[][] board, int r, int c) {
        return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
    }

    /** Checks whether the cell immediately adjacent to (r,c) in (dr,dc)
     *  contains a '.' . */
    private static boolean isAdjacentDot(char[][] board, int r, int c, int dr, int dc) {
        int nr = r + dr;
        int nc = c + dc;
        return inside(board, nr, nc) && board[nr][nc] == '.';
    }

    /* -----------------------------------------------------------
       Fast I/O helper (unchanged, only kept for completeness)
       ----------------------------------------------------------- */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new java.io.InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Entry point of the application. It reads a 10×10 board, looks for an empty cell
 * ('.') that, if filled with 'X', would create a line of at least four 'X's in
 * any direction, and prints "YES" or "NO".
 */
public class Main {

    /** Size of the board (fixed to 10×10). */
    private static final int SIZE = 10;

    /** Directions used to probe lines on the board. */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1),
        UP_LEFT(-1, -1), UP_RIGHT(-1, 1), DOWN_LEFT(1, -1), DOWN_RIGHT(1, 1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int getDr()   { return dr; }
        int getDc()   { return dc; }
    }

    /** Reads the 10×10 board from standard input. */
    private static char[][] readBoard() throws IOException {
        char[][] board = new char[SIZE][SIZE];
        for (int r = 0; r < SIZE; r++) {
            board[r] = Reader.next().toCharArray();
        }
        return board;
    }

    /**
     * Counts consecutive 'X' cells starting from (r,c) and moving by (dr,dc).
     *
     * @param board   the current board
     * @param r       starting row
     * @param c       starting column
     * @param dr      step increment for row
     * @param dc      step increment for column
     * @return number of consecutive 'X' encountered
     */
    private static int countInDirection(char[][] board, int r, int c, int dr, int dc) {
        int count = 0;
        int nr = r + dr;
        int nc = c + dc;
        while (nr >= 0 && nr < SIZE && nc >= 0 && nc < SIZE && board[nr][nc] == 'X') {
            count++;
            nr += dr;
            nc += dc;
        }
        return count;
    }

    /**
     * Checks whether placing an 'X' at the given empty cell creates a line of
     * at least four 'X's in any direction.
     *
     * @param board   the board (cell at row,col is assumed to be '.')
     * @param row     row index of the empty cell
     * @param col     column index of the empty cell
     * @return true if a winning line would be formed
     */
    private static boolean wouldWin(char[][] board, int row, int col) {
        // Temporarily place 'X' to simulate the move
        board[row][col] = 'X';

        // Examine every direction; a win occurs if the total length
        // (both forward and backward) plus the placed cell >= 4.
        for (Direction dir : Direction.values()) {
            int dr = dir.getDr();
            int dc = dir.getDc();

            int forward  = countInDirection(board, row, col,  dr,  dc);
            int backward = countInDirection(board, row, col, -dr, -dc);

            if (forward + backward + 1 >= 4) {
                // Clean up before returning
                board[row][col] = '.';
                return true;
            }
        }

        // Restore original '.' before exiting
        board[row][col] = '.';
        return false;
    }

    public static void main(String[] args) throws IOException {
        Reader.init(System.in);
        PrintWriter out = new PrintWriter(System.out);

        char[][] grid = readBoard();
        String result = "NO";

        for (int r = 0; r < SIZE && result.equals("NO"); r++) {
            for (int c = 0; c < SIZE && result.equals("NO"); c++) {
                if (grid[r][c] == '.') {
                    if (wouldWin(grid, r, c)) {
                        result = "YES";
                    }
                }
            }
        }

        out.print(result);
        out.flush();
    }
}

/**
 * Small utility class that wraps {@link BufferedReader} and {@link StringTokenizer}
 * to provide convenient tokenised input methods used throughout the program.
 */
class Reader {
    private static BufferedReader reader;
    private static StringTokenizer tokenizer;

    /** Initializes the reader with the supplied {@link InputStream}. */
    static void init(InputStream input) {
        reader = new BufferedReader(new InputStreamReader(input));
        tokenizer = new StringTokenizer("");
    }

    /** Reads the next full line. */
    static String nextLine() throws IOException {
        return reader.readLine();
    }

    /** Returns the next token, reading a new line when the current one is exhausted. */
    static String next() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    static long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    static double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }
}

import java.io.*;
import java.util.*;

/**
 * Detects whether a 10×10 board contains a pattern of exactly four 'X'
 * characters and one '.' character in a straight line of five cells.
 * The pattern may appear vertically, horizontally or on either diagonal.
 *
 * Input: 10 lines, each containing exactly 10 characters (only 'X' and '.').
 * Output: "YES" if such a pattern exists, otherwise "NO".
 */
public class FiveInARow {

    /** Fixed size of the square board. */
    private static final int BOARD_SIZE = 10;

    /** Length of the line we are searching for. */
    private static final int CONNECT_LENGTH = 5;

    /** The four possible directions for checking a line of five cells. */
    private static final int[][] DIRECTIONS = {
            {1, 0},   // vertical (down)
            {0, 1},   // horizontal (right)
            {1, 1},   // diagonal down‑right
            {1, -1}   // diagonal down‑left
    };

    public static void main(String[] args) throws IOException {
        char[][] board = readBoard();
        boolean win = detectWin(board);
        System.out.println(win ? "YES" : "NO");
    }

    /**
     * Reads ten lines of 10 characters from {@code System.in}.
     * Any malformed input results in an {@link IOException}.
     */
    private static char[][] readBoard() throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                if (line.length() != BOARD_SIZE) {
                    throw new IOException("Each line must contain exactly " + BOARD_SIZE + " characters");
                }
                for (int j = 0; j < BOARD_SIZE; j++) {
                    board[i][j] = line.charAt(j);
                }
            }
            return board;
        }
    }

    /**
     * Determines whether the board contains a winning pattern.
     *
     * @return {@code true} if a line of five cells contains exactly four 'X' and one '.'.
     */
    private static boolean detectWin(char[][] board) {
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                for (int[] dir : DIRECTIONS) {
                    if (canPlaceSequence(board, row, col, dir[0], dir[1])) {
                        return true;          // Found a valid pattern early.
                    }
                }
            }
        }
        return false; // No pattern found anywhere on the board.
    }

    /**
     * Checks the five cells starting at {@code (row, col)} moving in the
     * direction {@code (deltaRow, deltaCol)} for the required pattern.
     *
     * @return {@code true} if exactly four cells contain 'X' and one contains '.'
     *         and no other character is encountered.
     */
    private static boolean canPlaceSequence(char[][] board,
                                            int row, int col,
                                            int deltaRow, int deltaCol) {
        int xCount = 0;
        int dotCount = 0;

        for (int k = 0; k < CONNECT_LENGTH; k++) {
            int r = row + k * deltaRow;
            int c = col + k * deltaCol;

            // Guard against out‑of‑bounds accesses.
            if (r < 0 || r >= BOARD_SIZE || c < 0 || c >= BOARD_SIZE) {
                return false;
            }

            char ch = board[r][c];
            if (ch == 'X') {
                xCount++;
            } else if (ch == '.') {
                dotCount++;
            } else {
                // Any character other than 'X' or '.' breaks the pattern.
                return false;
            }
        }
        return xCount == 4 && dotCount == 1;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Detects a line of five consecutive cells that contains exactly four 'X'
 * characters and one '.' character on a 10×10 board.
 *
 * <p>The detection is performed in all eight possible directions
 * (horizontal, vertical and the four diagonals).
 */
public class ProblemB {

    /** Size of the square board. */
    private static final int BOARD_SIZE = 10;

    /** The eight possible directions in which a streak can appear. */
    private enum Direction {
        RIGHT(0, 1),
        LEFT(0, -1),
        DOWN(1, 0),
        UP(-1, 0),
        DOWN_RIGHT(1, 1),
        UP_LEFT(-1, -1),
        DOWN_LEFT(1, -1),
        UP_RIGHT(-1, 1);

        final int di;
        final int dj;

        Direction(int di, int dj) {
            this.di = di;
            this.dj = dj;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) {
        MyFastReader in = new MyFastReader();
        PrintWriter out = new PrintWriter(System.out);

        char[][] board = readBoard(in);

        String result = "NO";
        for (int row = 0; row < BOARD_SIZE && result.equals("NO"); row++) {
            for (int col = 0; col < BOARD_SIZE && result.equals("NO"); col++) {
                if (board[row][col] == 'X') {
                    for (Direction dir : Direction.values()) {
                        if (isStreakValid(board, row, col, dir)) {
                            result = "YES";
                            break; // exit direction loop, outer loops will also exit
                        }
                    }
                }
            }
        }

        out.println(result);
        out.close();
    }

    /**
     * Reads a 10×10 board from the fast scanner.
     *
     * @param scanner scanner that provides ten 10‑character lines
     * @return a 10×10 char array representing the board
     */
    private static char[][] readBoard(MyFastReader scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = scanner.next();
            for (int j = 0; j < BOARD_SIZE; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /**
     * Checks whether a streak of five cells starting at {@code (row,col)} and
     * extending in the given {@code direction} contains exactly four 'X'
     * characters and one '.' character.
     *
     * @param board    the game board
     * @param row      starting row index
     * @param col      starting column index
     * @param dir      direction of the streak
     * @return {@code true} if the streak matches the required pattern
     */
    private static boolean isStreakValid(char[][] board,
                                         int row,
                                         int col,
                                         Direction dir) {
        int xCount = 0;
        int dotCount = 0;

        for (int step = 0; step < 5; step++) {
            int curRow = row + step * dir.di;
            int curCol = col + step * dir.dj;

            // Bounds check – if we step out of the board, the streak cannot be valid
            if (curRow < 0 || curRow >= BOARD_SIZE || curCol < 0 || curCol >= BOARD_SIZE) {
                return false;
            }

            char cell = board[curRow][curCol];
            if (cell == 'X') {
                xCount++;
            } else if (cell == '.') {
                dotCount++;
            } else {
                // Any other character invalidates the streak
                return false;
            }
        }

        return xCount == 4 && dotCount == 1;
    }

    /**
     * Simple fast scanner used to read tokens from standard input.
     */
    static class MyFastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        MyFastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    private static final int BOARD_SIZE = 10;
    private static final int WIN_LENGTH = 5;

    /** Four directions that can contain a winning line of at least 5 cells. */
    private static final int[][] DIRECTIONS = {
            {0, 1},   // horizontal (right)
            {1, 0},   // vertical   (down)
            {1, 1},   // diagonal   (down‑right)
            {1, -1}   // diagonal   (down‑left)
    };

    public static void main(String[] args) {
        /* Try‑with‑resources guarantees that the scanner and the output writer are closed. */
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            new Solver().solve(scanner, out);
        }
    }

    /** -----------------------------------------------------------
     *  Core game‑logic class – keeps the board and performs the search.
     *  ----------------------------------------------------------- */
    static class Solver {
        private final char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        /** Reads exactly 10 lines of 10 characters from the scanner. */
        private void readBoard(Scanner scanner) {
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = scanner.next();
                board[i] = line.toCharArray();
            }
        }

        /** Tries every empty cell, puts an 'X' there and checks for a win. */
        public void solve(Scanner scanner, PrintWriter out) {
            readBoard(scanner);

            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    if (board[r][c] == '.') {
                        board[r][c] = 'X';

                        if (hasFiveInRow()) {
                            out.println("YES");
                            return;                     // early exit – solution found
                        }

                        // backtrack – the cell must stay empty for the next test
                        board[r][c] = '.';
                    }
                }
            }

            out.println("NO");
        }

        /** Returns true if the current board contains a line of at least 5 X's. */
        private boolean hasFiveInRow() {
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    if (board[r][c] != 'X') continue;

                    for (int[] dir : DIRECTIONS) {
                        if (countInDirection(r, c, dir[0], dir[1]) >= WIN_LENGTH) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /** Counts consecutive 'X' cells starting at (r,c) moving by (dr,dc). */
        private int countInDirection(int r, int c, int dr, int dc) {
            int length = 0;
            int curR = r, curC = c;
            while (inBounds(curR, curC) && board[curR][curC] == 'X') {
                length++;
                curR += dr;
                curC += dc;
            }
            return length;
        }

        private boolean inBounds(int r, int c) {
            return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Size of the checkerboard (fixed at 10 × 10 in the original program) */
    private static final int BOARD_SIZE = 10;
    /** Length of the straight line that must contain the pattern */
    private static final int PATTERN_LENGTH = 5;

    public static void main(String[] args) {
        try (InputStream in = System.in;
             PrintWriter out = new PrintWriter(System.out, true)) {
            InputReader reader = new InputReader(in);
            TaskB solver = new TaskB();
            solver.solve(reader, out);
        }
    }

    /** -------------------------------------------------------------
     *  Core algorithm – checks whether the pattern required by the task
     *  exists anywhere on the board.
     *  ------------------------------------------------------------- */
    static class TaskB {

        void solve(InputReader reader, PrintWriter out) {
            char[][] board = reader.readGrid(BOARD_SIZE, BOARD_SIZE);
            boolean found = hasWinningPattern(board);
            out.println(found ? "YES" : "NO");
        }

        /** Scans the whole board in every possible direction. */
        private boolean hasWinningPattern(char[][] board) {
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    for (int dr = -1; dr <= 1; dr++) {
                        for (int dc = -1; dc <= 1; dc++) {
                            if (dr == 0 && dc == 0) {
                                continue;               // (0,0) is not a direction
                            }
                            if (startsPatternAt(board, r, c, dr, dc)) {
                                return true;                // pattern found → exit early
                            }
                        }
                    }
                }
            }
            return false;                               // no pattern on the board
        }

        /** Checks whether the 5‑cell straight line that starts at (r,c) moving
         *  by (dr,dc) contains exactly one '.' and four 'X' characters.
         */
        private boolean startsPatternAt(char[][] board, int startR, int startC,
                                        int dirR, int dirC) {
            int xCount = 0;
            int dotCount = 0;

            for (int step = 0; step < PATTERN_LENGTH; step++) {
                int nr = startR + dirR * step;
                int nc = startC + dirC * step;

                if (!isInBounds(nr, nc)) {
                    continue;                               // out of board → ignore
                }

                char cell = board[nr][nc];
                switch (cell) {
                    case 'X':
                        xCount++;
                        break;
                    case '.':
                        dotCount++;
                        break;
                    default:
                        return false;                         // any other symbol breaks the check
                }
            }
            return dotCount == 1 && xCount == 4;
        }

        /** Simple bounds check for the fixed-size board. */
        private boolean isInBounds(int row, int col) {
            return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE;
        }
    }

    /** -------------------------------------------------------------
     *  Fast, low‑level character reader – keeps the I/O handling
     *  isolated from the algorithmic part.
     *  ------------------------------------------------------------- */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int pointer = 0;
        private int length = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        /** Reads a single byte; -1 indicates end of stream. */
        private int readByte() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        /** Skips any whitespace characters before the next token. */
        private void skipWhitespace() throws IOException {
            int b;
            while ((b = readByte()) != -1 && isSpaceChar(b)) {
                // consume whitespace
            }
            if (b != -1) {
                pointer--;                // put back the first non‑space byte
            }
        }

        /** @return true for space, newline, tab, carriage‑return, EOF */
        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads the next non‑whitespace character. */
        char nextChar() throws IOException {
            skipWhitespace();
            int b = readByte();
            if (b == -1) {
                throw new EOFException();
            }
            return (char) b;
        }

        /** Reads exactly {@code n} characters starting from the next
         *  non‑whitespace position. */
        char[] readChars(int n) throws IOException {
            char[] result = new char[n];
            for (int i = 0; i < n; i++) {
                result[i] = nextChar();
            }
            return result;
        }

        /** Reads a rectangular {@code rows × cols} grid of characters. */
        char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = readChars(cols);
            }
            return grid;
        }
    }
}

