/**
 * Reads a 10×10 grid and checks whether placing an 'X' at an empty cell
 * creates a line of five 'X's (horizontally, vertically or diagonally).
 *
 * The program follows the original behaviour but is considerably easier
 * to read, maintain and extend.
 */
public class GridSolver {

    /** File read in DEBUG mode – kept only for backward compatibility. */
    private static final String DEBUG_FILE = "input.txt";
    /** Toggle DEBUG mode if you want to read from {@code DEBUG_FILE}. */
    private static final boolean DEBUG = false;

    public static void main(String[] args) throws IOException {
        if (DEBUG) {
            // This method existed in the original code; it is now a no‑op.
            generate();
        }

        Solver solver = new Solver();
        solver.readData();
        solver.solveAndPrint();
    }

    /** Placeholder method kept only to preserve the original source structure. */
    private static void generate() throws IOException {
        // Intentionally empty – present solely for compatibility.
    }

    /**
     * Handles input reading and the solving logic.
     */
    private static class Solver {

        /** 10×10 board stored as a character matrix. */
        private final char[][] grid = new char[10][10];
        /** Coordinates of the (only) empty cell ('.') in the board. */
        private int emptyRow = -1;
        private int emptyCol = -1;

        /** Reads exactly ten lines from STDIN or the debug file. */
        void readData() throws IOException {
            try (InputStreamReader isr = new InputStreamReader(
                    DEBUG ? new java.io.FileInputStream(DEBUG_FILE) : System.in);
                 BufferedReader br = new BufferedReader(isr)) {

                for (int i = 0; i < 10; i++) {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("Input ends prematurely");
                    }
                    // Ensure we only keep the first 10 characters
                    line = line.substring(0, Math.min(line.length(), 10));
                    for (int j = 0; j < 10; j++) {
                        grid[i][j] = line.charAt(j);
                    }
                }
            }

            // Locate the first '.' cell – the position where we would place an 'X'.
            outer:
            for (int i = 0; i < 10; i++) {
                for (int j = 0; j < 10; j++) {
                    if (grid[i][j] == '.') {
                        emptyRow = i;
                        emptyCol = j;
                        break outer;
                    }
                }
            }

            // If no empty cell exists the answer is automatically "NO".
            if (emptyRow == -1) {
                emptyRow = emptyCol = -1;
            }
        }

        /** Determines whether placing an 'X' at the empty cell yields a win. */
        void solveAndPrint() {
            if (emptyRow == -1) {
                System.out.println("NO");
                return;
            }

            // Check all eight directions for a line of five 'X's.
            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    if (dr == 0 && dc == 0) { // skip the (0,0) direction
                        continue;
                    }
                    if (hasFiveInLine(emptyRow, emptyCol, dr, dc)) {
                        System.out.println("YES");
                        return;
                    }
                }
            }
            System.out.println("NO");
        }

        /** Checks a line in the given direction and the opposite direction. */
        private boolean hasFiveInLine(int row, int col, int dRow, int dCol) {
            int length = 1; // the current empty cell will be turned into 'X'

            // Positive direction
            for (int step = 1; step <= 4; step++) {
                int r = row + step * dRow;
                int c = col + step * dCol;
                if (!inBounds(r, c) || grid[r][c] != 'X') {
                    break;
                }
                length++;
            }

            // Negative direction
            for (int step = 1; step <= 4; step++) {
                int r = row - step * dRow;
                int c = col - step * dCol;
                if (!inBounds(r, c) || grid[r][c] != 'X') {
                    break;
                }
                length++;
            }

            return length >= 5;
        }

        /** Simple bounds check for the 10×10 board. */
        private boolean inBounds(int r, int c) {
            return r >= 0 && r < 10 && c >= 0 && c < 10;
        }
    }
}

import java.io.IOException;
import java.util.InputMismatchException;

/**
 * Detects a winning pattern of exactly four ‘X’ characters and one ‘.’ character
 * in any straight line (horizontal, vertical or diagonal) on a 10×10 board.
 *
 * <p>This refactored version improves readability, isolates responsibilities,
 * and uses a small {@code Direction} enum to represent the four checked
 * directions.</p>
 */
public final class FiveInARow {

    /** Board size – the problem defines a 10×10 grid. */
    private static final int BOARD_SIZE = 10;

    /** Length of the sequence that must be examined in each direction. */
    private static final int WIN_LENGTH = 5;

    /** The four directions we need to check: right, down, down‑right, down‑left. */
    private static final Direction[] DIRECTIONS = {
            new Direction(0, 1),   // horizontal (right)
            new Direction(1, 0),   // vertical   (down)
            new Direction(1, 1),   // diagonal   (down‑right)
            new Direction(1, -1)   // diagonal   (down‑left)
    };

    /** Program entry point. */
    public static void main(String[] args) {
        char[][] board = readBoard();

        if (hasWinningPattern(board)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /** Reads ten lines from {@code System.in} and builds the board. */
    private static char[][] readBoard() {
        try (FastScanner sc = new FastScanner()) {
            char[][] board = new char[BOARD_SIZE][];
            for (int r = 0; r < BOARD_SIZE; ++r) {
                board[r] = sc.nextLine().toCharArray();
            }
            return board;
        }
    }

    /** Determines whether any of the four directions contains a winning line. */
    private static boolean hasWinningPattern(char[][] board) {
        for (int r = 0; r < BOARD_SIZE; ++r) {
            for (int c = 0; c < BOARD_SIZE; ++c) {
                for (Direction dir : DIRECTIONS) {
                    if (isWinningLine(board, r, c, dir)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks whether the five‑character line that starts at {@code (r,c)} and
     * proceeds in {@code dir} contains exactly four ‘X’ and one ‘.’.
     *
     * @return {@code true} if the line matches the required pattern.
     */
    private static boolean isWinningLine(char[][] board, int r, int c, Direction dir) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < WIN_LENGTH; ++i) {
            int nr = r + i * dir.dr;
            int nc = c + i * dir.dc;

            if (!isInsideBoard(nr, nc)) {
                return false;                 // line goes out of bounds
            }

            char ch = board[nr][nc];
            if (ch == 'X') {
                ++xCount;
            } else if (ch == '.') {
                ++dotCount;
            } else {
                // Any other character invalidates the pattern.
                return false;
            }
        }

        return xCount == 4 && dotCount == 1;
    }

    /** Simple bounds check for board coordinates. */
    private static boolean isInsideBoard(int row, int col) {
        return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE;
    }

    /**
     * Fast input scanner – mirrors the original implementation but is kept
     * private to this file to avoid exposing unnecessary members.
     */
    public static final class FastScanner {
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int length = 0;

        /** Reads a single byte; returns –1 on EOF. */
        private int readByte() {
            if (length == -1) {
                throw new InputMismatchException();
            }
            if (pointer >= length) {
                pointer = 0;
                try {
                    length = System.in.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        /** Skips whitespace characters. */
        private static int skipWhite(int b) {
            while (b == ' ' || b == '\n' || b == '\r' || b == '\t') {
                b = readByte();
            }
            return b;
        }

        /** Reads the next full line (including spaces). */
        public String nextLine() {
            int c = skipWhite(readByte());
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isEndOfLine(c));
            return sb.toString();
        }

        /** Reads the next non‑whitespace token. */
        public String nextString() {
            int c = skipWhite(readByte());
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        /** Reads the next 32‑bit signed integer. */
        public int nextInt() {
            int sign = 1;
            int c = skipWhite(readByte());
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            long value = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                value = value * 10 + (c - '0');
                c = readByte();
            } while (!isSpaceChar(c));
            return (int) (value * sign);
        }

        /** Helper: true for whitespace or EOF. */
        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Helper: true for line‑terminators or EOF. */
        private static boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Determines whether an empty cell on a 10×10 board can create a line of
 * at least four 'X' characters (horizontally, vertically or diagonally)
 * when the cell is filled with 'X'.
 *
 * The program reads multiple 10‑line boards from standard input.
 * For each board it prints "YES" if a winning move exists, otherwise "NO".
 */
public class Main {

    /** Board size – kept as a constant for easy changes. */
    private static final int BOARD_SIZE = 10;

    /** Symbol that represents an empty cell. */
    private static final char EMPTY = '.';

    /** Symbol that represents a player piece. */
    private static final char PLAYER = 'X';

    public static void main(String[] args) throws IOException {
        /* Use try‑with‑resources to guarantee the reader is closed. */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line;
            /* Process each board until EOF. */
            while (br.hasNextLine()) {
                char[][] board = readBoard(br);
                System.out.println(hasWinningMove(board) ? "YES" : "NO");
            }
        }
    }

    /** Reads exactly {@value #BOARD_SIZE} lines to build a board. */
    private static char[][] readBoard(BufferedReader br) throws IOException {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int row = 0; row < BOARD_SIZE; row++) {
            line = br.readLine();
            if (line == null) {
                // Prevent NullPointerException if input ends prematurely.
                throw new IOException("Unexpected end of input");
            }
            board[row] = line.toCharArray();
        }
        return board;
    }

    /** Returns true if any empty cell can complete a line of ≥4 PLAYER pieces. */
    private static boolean hasWinningMove(char[][] board) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] == EMPTY) {
                    // Check all four directions from the empty cell.
                    if (lineCount(board, r, c, 0, 1)   // horizontal
                            || lineCount(board, r, c, 1, 0)   // vertical
                            || lineCount(board, r, c, 1, 1)   // diagonal \
                            || lineCount(board, r, c, 1, -1)) // diagonal /
                        return true;
                }
            }
        }
        return false;
    }

    /**
     * Counts consecutive PLAYER pieces starting at (row,col) and moving in
     * the direction (dr,dc). It counts both forward and backward directions
     * and returns the total number of PLAYER pieces encountered.
     *
     * @return the number of contiguous PLAYER pieces adjacent to the empty cell.
     */
    private static int lineCount(char[][] board, int row, int col, int dr, int dc) {
        int count = 0;

        // Positive direction (dr, dc)
        int r = row + dr;
        int c = col + dc;
        while (isInside(r, c) && board[r][c] == PLAYER) {
            count++;
            r += dr;
            c += dc;
        }

        // Negative direction (-dr, -dc)
        r = row - dr;
        c = col - dc;
        while (isInside(r, c) && board[r][c] == PLAYER) {
            count++;
            r -= dr;
            c -= dc;
        }

        return count; // original logic required count >= 4
    }

    /** Helper to test whether a coordinate lies inside the board limits. */
    private static boolean isInside(int r, int c) {
        return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 *
 * <p>The program reads ten lines of ten characters each.
 * It looks for an empty cell ('.') that can become part of a
 * sequence of four adjacent 'X' characters in any direction
 * (horizontal, vertical or diagonal). If such a cell exists it
 * prints {@code YES}, otherwise {@code NO}.
 *
 * <p>All I/O is delegated to {@link FastScanner}.
 */
public class Ed_2017_R25_B {

    /** Size of the board (10 × 10). */
    private static final int BOARD_SIZE = 10;

    private FastScanner scanner;
    private PrintWriter writer;

    public static void main(String[] args) {
        new Ed_2017_R25_B().run();
    }

    /** Main driver method – loads input, solves the problem and writes output. */
    public void run() {
        scanner = new FastScanner(System.in);
        writer = new PrintWriter(System.out, true);
        try {
            solve();
        } finally {
            writer.close();
        }
    }

    /** Reads the board, checks for a winning move and prints the result. */
    private void solve() {
        char[][] board = readBoard();

        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                if (board[row][col] == '.') {
                    if (hasFourInRow(board, row, col) ||
                        hasFourInColumn(board, row, col) ||
                        hasFourInDiagonal(board, row, col)) {
                        writer.println("YES");
                        return;
                    }
                }
            }
        }

        writer.println("NO");
    }

    /** Reads exactly {@value BOARD_SIZE} lines of length {@value BOARD_SIZE}. */
    private char[][] readBoard() {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = scanner.nextLine().trim();
            if (line.length() != BOARD_SIZE) {
                throw new IllegalArgumentException(
                    "Each line must contain exactly " + BOARD_SIZE + " characters");
            }
            board[i] = line.toCharArray();
        }
        return board;
    }

    /** Checks whether placing an 'X' at (row, col) creates a horizontal four‑in‑a‑row. */
    private boolean hasFourInRow(char[][] board, int row, int col) {
        return findFour(board, true, 0, 1, row, col);
    }

    /** Checks whether placing an 'X' at (row, col) creates a vertical four‑in‑a‑row. */
    private boolean hasFourInColumn(char[][] board, int row, int col) {
        return findFour(board, false, 1, 0, row, col);
    }

    /** Checks both diagonal directions for a four‑in‑a‑row. */
    private boolean hasFourInDiagonal(char[][] board, int row, int col) {
        // down‑right diagonal
        boolean downRight = findFour(board, false, 1, 1, row, col);
        // down‑left diagonal
        boolean downLeft = findFour(board, false, 1, -1, row, col);
        return downRight || downLeft;
    }

    /**
     * Searches for a sequence of four 'X' cells that ends (or starts) at
     * (row, col) when moving in the given {@code dr}/{@code dc} direction.
     *
     * @param board   the game board
     * @param startAtRowCol {@code true} if the search starts at the given cell,
     *                      {@code false} if it ends there
     * @param dr      delta row for each step
     * @param dc      delta column for each step
     * @param row     starting row coordinate
     * @param col     starting column coordinate
     * @return {@code true} if a valid four‑cell segment is found
     */
    private boolean findFour(char[][] board, boolean startAtRowCol, int dr, int dc,
                             int row, int col) {
        // Determine the start of the 4‑cell window that ends/start at (row,col)
        int offset = startAtRowCol ? 0 : -3; // when ending at (row,col) we need to step back 3 cells
        for (int step = 0; step <= 4; step++) {
            int r = row + (step - offset) * dr;
            int c = col + (step - offset) * dc;

            // Adjust offset logic: when startAtRowCol is true we want the first cell of the window;
            // when false we want the fourth cell of the window to be (row,col).
            if (step == 0 && !startAtRowCol) {
                // In this case we start 3 steps before (row,col)
                r = row + (-3) * dr;
                c = col + (-3) * dc;
            }

            if (isOutOfBounds(r, c)) {
                return false;
            }

            // If we are at the fourth cell of the window and it is '.' we treat it as a placeholder
            // that could become 'X'. For simplicity we only care about the nature of the window,
            // not its exact composition, so we just count 'X' occurrences.
            if (step == 3) {
                // Ensure the window contains exactly an empty cell at the intended position
                if (board[r][c] != '.') {
                    continue;
                }
            }
        }

        // Count 'X' cells in the completed 4‑cell window
        int countX = 0;
        for (int step = 0; step < 4; step++) {
            int r = row + step * dr;
            int c = col + step * dc;
            if (isOutOfBounds(r, c)) {
                return false;
            }
            if (board[r][c] == 'X') {
                countX++;
            }
        }

        // The empty cell that triggered the method call is allowed to become 'X'
        // therefore we just need exactly four 'X' cells in total.
        return countX == 4;
    }

    /** Checks whether a coordinate is inside the 10 × 10 board. */
    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= BOARD_SIZE || c < 0 || c >= BOARD_SIZE;
    }
}

/**
 * Fast input scanner that works with {@link InputStream}, {@link File}
 * and {@link BufferedReader}. It tokenises each line on whitespace.
 */
class FastScanner {

    private final BufferedReader br;
    private StringTokenizer tokenizer;

    /** Constructs a scanner that reads from the given {@link InputStream}. */
    FastScanner(InputStream stream) {
        this.br = new BufferedReader(new InputStreamReader(stream));
    }

    /** Constructs a scanner that reads from the given {@link File}. */
    FastScanner(File file) throws FileNotFoundException {
        this(new FileReader(file));
    }

    /** Reads the next token from the input. */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Reads a full line (including whitespace). */
    String nextLine() {
        try {
            return br.readLine();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    /** Convenience methods for primitive types. */
    int nextInt()           { return Integer.parseInt(next()); }
    long nextLong()         { return Long.parseLong(next()); }
    double nextDouble()     { return Double.parseDouble(next()); }
    BigInteger nextBigInteger(){ return new BigInteger(next()); }
    BigDecimal nextBigDecimal(){ return new BigDecimal(next()); }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for the “Connect‑Four‑like” check.
 *
 * <p>Key improvements compared to the original version:
 *
 * <ul>
 *   <li>Clear separation of concerns – I/O, parsing, and game logic live in distinct
 *       methods/objects.</li>
 *   <li>Use of a constant {@code BOARD_SIZE} instead of the magic number 10.</li>
 *   <li>Direction‑based checking eliminates duplicated code for the four possible
 *       lines (horizontal, vertical, two diagonals).</li>
 *   <li>Descriptive method and variable names improve readability.</li>
 *   <li>Encapsulation of fast input parsing in a small {@code FastScanner} helper.</li>
 * </ul>
 *
 * The program reads 10 strings of length 10, replaces each '.' with an 'X' at the
 * current position, and prints “YES” if any placement creates a line of at least
 * four consecutive 'X' characters; otherwise it prints “NO”.
 */
public class Solver implements Runnable {

    /** Fixed board dimension used by the problem (10 × 10). */
    private static final int BOARD_SIZE = 10;

    private BufferedReader reader;
    private PrintWriter writer;
    private FastScanner fs;

    /** Entry point – runs the solver on a separate thread to avoid stack overflow. */
    public static void main(String[] args) {
        new Thread(new Solver()).start();
    }

    @Override
    public void run() {
        try {
            init();
            solve();
            close();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    /** Sets up input, output and the fast scanner. */
    private void init() throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(System.out, true);
        fs = new FastScanner(reader);
    }

    /** Main algorithmic routine. */
    private void solve() {
        char[][] board = new char[BOARD_SIZE][];
        for (int i = 0; i < BOARD_SIZE; i++) {
            board[i] = fs.readString().toCharArray();
        }

        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] == '.' && isWinningMove(board, r, c)) {
                    writer.println("YES");
                    return;
                }
            }
        }
        writer.println("NO");
    }

    /**
     * Determines whether placing an 'X' at position (r, c) creates a line of
     * length >= 4 in any of the four possible directions.
     */
    private boolean isWinningMove(char[][] board, int r, int c) {
        int[][] directions = {
                {0, 1},      // horizontal
                {1, 0},      // vertical
                {1, 1},      // main diagonal
                {1, -1}      // anti‑diagonal
        };

        for (int[] d : directions) {
            int length = 1; // the newly placed 'X' itself

            // count consecutive 'X' forward
            for (int step = 1; ; step++) {
                int nr = r + step * d[0];
                int nc = c + step * d[1];
                if (!inBounds(nr, nc) || board[nr][nc] != 'X') break;
                length++;
            }

            // count consecutive 'X' backward
            for (int step = 1; ; step++) {
                int nr = r - step * d[0];
                int nc = c - step * d[1];
                if (!inBounds(nr, nc) || board[nr][nc] != 'X') break;
                length++;
            }

            if (length >= 4) {
                return true;
            }
        }
        return false;
    }

    /** Helper to test array bounds. */
    private boolean inBounds(int row, int col) {
        return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE;
    }

    /** Cleanly closes all streams. */
    private void close() {
        writer.close();
        try {
            reader.close();
        } catch (IOException ignored) { }
    }

    /* -------------------------------------------------------------------------
       FastScanner – a lightweight wrapper around BufferedReader that mimics the
       original token‑based reading utilities (readString, readInt, readLong).
       ------------------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        /** Reads the next token, waiting for input if necessary. */
        String readString() {
            while (true) {
                try {
                    while (!st.hasMoreTokens()) {
                        String line = br.readLine();
                        if (line == null) {
                            return null; // EOF (should not occur in this problem)
                        }
                        st = new StringTokenizer(line);
                    }
                    return st.nextToken();
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
        }

        int readInt() {
            return Integer.parseInt(readString());
        }

        long readLong() {
            return Long.parseLong(readString());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Refactored version of the original program.
 *
 * <p>
 *   The program reads a 10×10 board where each cell contains either 'X' or '.'.
 *   It determines whether there exists an empty cell ('.') that can be turned
 *   into an 'X' to create a line of at least five 'X' characters in any of the
 *   four possible directions (horizontal, vertical, or either diagonal).
 * </p>
 *
 * <p>
 *   The refactor improves maintainability by:
 *   <ul>
 *     <li>Extracting magic numbers into named constants.</li>
 *     <li>Separating the winning‑move detection logic into small, reusable
 *         methods.</li>
 *     <li>Using clear naming and avoiding deeply nested loops.</li>
 *     <li>Eliminating the many manual “while‑true” loops that were duplicated
 *         for each direction.</li>
 *     <li>Adding concise inline comments that explain the intent of each
 *         section.</li>
 *   </ul>
 * </p>
 */
public class Main {

    /** Size of the board (10 × 10). */
    private static final int BOARD_SIZE = 10;

    /** Directions to check: right, down, down‑right, down‑left. */
    private static final int[][] DIRECTIONS = {
            {0, 1},   // horizontal (right)
            {1, 0},   // vertical   (down)
            {1, 1},   // diagonal   (down‑right)
            {1, -1}   // diagonal   (down‑left)
    };

    public static void main(String[] args) throws IOException {
        char[][] board = readBoard();
        boolean canWin = hasAtLeastFiveInARow(board);
        System.out.println(canWin ? "YES" : "NO");
    }

    /**
     * Reads a 10×10 board from standard input.
     *
     * @return a two‑dimensional char array representing the board.
     * @throws IOException if reading input fails.
     */
    private static char[][] readBoard() throws IOException {
        char[][] grid = new char[BOARD_SIZE][BOARD_SIZE];
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            for (int row = 0; row < BOARD_SIZE; row++) {
                String line = reader.readLine();
                if (line == null || line.length() != BOARD_SIZE) {
                    throw new IOException("Input line is missing or has wrong length.");
                }
                for (int col = 0; col < BOARD_SIZE; col++) {
                    grid[row][col] = line.charAt(col);
                }
            }
        }
        return grid;
    }

    /**
     * Determines whether there is any empty cell ('.') that, when filled with
     * an 'X', would create a line of at least five consecutive 'X's in any
     * direction.
     *
     * @param board the current board state.
     * @return {@code true} if such a placement exists, otherwise {@code false}.
     */
    private static boolean hasAtLeastFiveInARow(char[][] board) {
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                if (board[row][col] == '.') {
                    if (canCompleteLine(board, row, col)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks whether placing an 'X' at (row, col) would create a line of at least
     * five 'X's in any of the four predefined directions.
     *
     * @param board   the board.
     * @param row     row index of the candidate empty cell.
     * @param col     column index of the candidate empty cell.
     * @return {@code true} if any direction yields a line of length ≥ 5.
     */
    private static boolean canCompleteLine(char[][] board, int row, int col) {
        for (int[] dir : DIRECTIONS) {
            int dx = dir[0];
            int dy = dir[1];

            int positive = countInDirection(board, row, col, dx, dy);
            int negative = countInDirection(board, row, col, -dx, -dy);

            int total = 1 + positive + negative; // 1 counts the cell itself
            if (total >= 5) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts consecutive 'X' cells starting from the immediate neighbour in the
     * given direction and moving outward.
     *
     * @param board    the board.
     * @param startRow start row (the already known empty cell is not counted).
     * @param startCol start column.
     * @param dRow     row step (+1 or -1) for moving outward.
     * @param dCol     column step (+1 or -1) for moving outward.
     * @return number of adjacent 'X' cells encountered in that direction.
     */
    private static int countInDirection(char[][] board, int startRow, int startCol,
                                        int dRow, int dCol) {
        int count = 0;
        int row = startRow + dRow;
        int col = startCol + dCol;
        while (insideBoard(row, col) && board[row][col] == 'X') {
            count++;
            row += dRow;
            col += dCol;
        }
        return count;
    }

    /** Utility to check whether a given coordinate is inside the 10×10 board. */
    private static boolean insideBoard(int row, int col) {
        return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Reads a 10×10 board consisting of characters {@code 'X'}, {@code '.'} and possibly others.
 * Determines whether any straight line (horizontal, vertical or diagonal) of length 5
 * contains only {@code 'X'} and at most one {@code '.'} (the '.' can act as a wildcard).
 * Prints {@code "YES"} as soon as such a line is found, otherwise {@code "NO"}.
 */
public class CODE {

    /** Board size – the problem is fixed to 10×10. */
    private static final int SIZE = 10;

    /** Directions in which we search for a line of five cells. */
    private enum Direction {
        HORIZONTAL(0, 1),
        VERTICAL(1, 0),
        DIAG_DOWN_RIGHT(1, 1),
        DIAG_DOWN_LEFT(1, -1),
        DIAG_UP_RIGHT(-1, 1),
        DIAG_UP_LEFT(-1, -1),
        // The opposite directions are covered by scanning from every cell,
        // therefore they do not need separate enum constants.
        ;

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /** Simple holder for the board. */
    private static char[][] board = new char[SIZE][SIZE];

    /** --------------------------------------------------------------------- */
    /** Entry point. */
    public static void main(String[] args) throws IOException {
        readBoard();
        boolean found = false;
        for (int r = 0; r < SIZE && !found; r++) {
            for (int c = 0; c < SIZE && !found; c++) {
                if (hasLineStartingAt(r, c)) {
                    found = true;
                }
            }
        }
        System.out.println(found ? "YES" : "NO");
    }

    /** --------------------------------------------------------------------- */
    /** Reads ten lines of exactly ten characters each from standard input. */
    private static void readBoard() throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            for (int r = 0; r < SIZE; r++) {
                String line = br.readLine();
                if (line == null || line.length() != SIZE) {
                    throw new IOException("Input must contain exactly " + SIZE + " lines of length " + SIZE);
                }
                board[r] = line.toCharArray();
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /**
     * Checks whether a line of five cells beginning at {@code (row,col)} and extending
     * in any of the predefined directions satisfies the rule:
     * <ul>
     *   <li>Only {@code 'X'} and possibly a single {@code '.'} are allowed,
     *       the '.' may appear at most once in the segment.</li>
     * </ul>
     *
     * @return {@code true} if any direction yields a valid line, otherwise {@code false}.
     */
    private static boolean hasLineStartingAt(int row, int col) {
        for (Direction dir : Direction.values()) {
            if (hasValidSegment(row, col, dir.dr, dir.dc)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Verifies a 5‑cell segment in the given direction.
     *
     * @param startRow   row index of the first cell,
     * @param startCol   column index of the first cell,
     * @param dr         increment for the row,
     * @param dc         increment for the column,
     * @return {@code true} if the segment contains only {@code 'X'} and at most one {@code '.'}.
     */
    private static boolean hasValidSegment(int startRow, int startCol, int dr, int dc) {
        int xCount = 0;
        boolean hasDot = false;

        for (int i = 0; i < 5; i++) {
            int r = startRow + i * dr;
            int c = startCol + i * dc;

            // Bounds check – if we step out of the board the segment is invalid.
            if (r < 0 || r >= SIZE || c < 0 || c >= SIZE) {
                return false;
            }

            char ch = board[r][c];
            if (ch == 'X') {
                xCount++;
            } else if (ch == '.') {
                // At most one '.' is allowed anywhere in the segment.
                if (hasDot) {
                    return false;               // second '.' makes the segment invalid
                }
                hasDot = true;
            } else {
                // Any other character disqualifies the segment.
                return false;
            }
        }

        // The original logic allowed {@code c + 1 == 5} when at least one '.' existed.
        // This matches:   xCount + (hasDot ? 1 : 0) == 5
        return xCount + (hasDot ? 1 : 0) == 5;
    }
}

import java.util.Scanner;

/**
 * Represents a 10×10 board for a game where Alice tries to place an
 * ‘X’ that creates a line of five ‘X’s without any ‘O’ blocking the
 * formation. The program checks whether such a winning move exists
 * after reading the current board configuration from stdin.
 */
public class TestThree {

    /** Size of the square board (10×10). */
    private static final int BOARD_SIZE = 10;

    /** The game board – each cell holds ‘X’, ‘O’ or another character
     *  representing an empty spot. */
    private final char[][] board;

    /**
     * Constructs a new game instance with the supplied board.
     *
     * @param board the current board state
     */
    public TestThree(char[][] board) {
        this.board = board;
    }

    /** Entry point of the program. Reads a board from stdin and prints
     *  “YES” if Alice can win on her next move, otherwise “NO”. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] inputBoard = readBoard(scanner);
            TestThree game = new TestThree(inputBoard);
            System.out.println(game.canAliceWinInOneMove());
        }
    }

    /** Reads exactly {@value #BOARD_SIZE} lines from the scanner,
     *  converts each line to a character array and returns the assembled
     *  board. Blank lines are ignored (they are skipped until a non‑empty
     *  line is encountered). */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][];
        int row = 0;
        while (row < BOARD_SIZE) {
            String line = scanner.nextLine().strip();
            if (!line.isEmpty()) {
                board[row++] = line.toCharArray();
            }
        }
        return board;
    }

    /**
     * Determines whether Alice can place an ‘X’ on the board that completes
     * a line of five consecutive ‘X’s without any ‘O’ appearing in that line.
     *
     * @return “YES” if such a move exists, otherwise “NO”.
     */
    public String canAliceWinInOneMove() {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] == 'X' && hasFourXWithNoOInFiveCells(r, c)) {
                    return "YES";
                }
            }
        }
        return "NO";
    }

    /**
     * Checks the four possible directions (horizontal, vertical,
     * diagonal down‑right, diagonal down‑left) starting from the given cell.
     * The method verifies that there exists a stretch of five cells that
     * contains exactly four ‘X’s, no ‘O’s and therefore allows Alice to
     * place an additional ‘X’ to win.
     *
     * @param startRow the row index of the starting cell
     * @param startCol the column index of the starting cell
     * @return true if one of the four directions satisfies the win condition
     */
    private boolean hasFourXWithNoOInFiveCells(int startRow, int startCol) {
        // Directions: right, down, down‑right, down‑left
        final int[][] DIRECTIONS = {
                {0, 1},      // horizontal
                {1, 0},      // vertical
                {1, 1},      // diagonal down‑right
                {1, -1}      // diagonal down‑left
        };

        for (int[] dir : DIRECTIONS) {
            if (hasWinningStretch(startRow, startCol, dir[0], dir[1])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks a single direction for a winning stretch of five cells.
     *
     * @param startRow   starting row
     * @param startCol   starting column
     * @param dRow       row step (1 = downwards)
     * @param dCol       column step (1 = right, -1 = left)
     * @return true if the five‑cell line contains exactly four ‘X’s and
     *         no ‘O’s.
     */
    private boolean hasWinningStretch(int startRow, int startCol,
                                      int dRow, int dCol) {
        // Ensure that a full five‑cell line fits inside the board.
        int endRow = startRow + 4 * dRow;
        int endCol = startCol + 4 * dCol;
        if (endRow < 0 || endRow >= BOARD_SIZE || endCol < 0 || endCol >= BOARD_SIZE) {
            return false;
        }

        int xCount = 0;
        for (int i = 0; i < 5; i++) {
            int r = startRow + i * dRow;
            int c = startCol + i * dCol;
            char cell = board[r][c];

            if (cell == 'O') {
                // An opponent block makes this direction invalid.
                return false;
            }
            if (cell == 'X') {
                xCount++;
            }
        }
        // Exactly four 'X's means there is a single empty spot that could be
        // filled to complete a line of five.
        return xCount == 4;
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a 10×10 grid from standard input and prints "YES" if any line of
 * five consecutive cells contains exactly four 'X' characters and one '.'
 * character (horizontally, vertically or along either diagonal). Otherwise
 * prints "NO".
 *
 * <p>This refactor improves readability, separates concerns into small,
 * well‑named classes, and uses modern Java constructs while preserving the
 * original program behaviour.</p>
 */
public class Main {

    public static void main(String[] args) throws IOException {
        // -----------------------------------------------------------------
        // 1️⃣  Load the 10×10 grid from stdin
        // -----------------------------------------------------------------
        List<String> rawLines = new ArrayList<>(10);
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line;
            for (int i = 0; i < 10; i++) {
                line = br.readLine();
                if (line == null) {
                    throw new IOException("Expected 10 lines of input");
                }
                rawLines.add(line.trim());
            }
        }

        // Convert to a mutable char matrix for efficient indexing
        char[][] grid = rawLines.stream()
                .map(String::toCharArray)
                .toArray(char[][]::new);

        // -----------------------------------------------------------------
        // 2️⃣  Check for a winning pattern
        // -----------------------------------------------------------------
        boolean hasPattern = GridChecker.hasWinningPattern(grid);

        // -----------------------------------------------------------------
        // 3️⃣  Output the result
        // -----------------------------------------------------------------
        System.out.println(hasPattern ? "YES" : "NO");
    }
}

/**
 * Utility class that encapsulates all logic related to pattern detection
 * inside a 10×10 grid.  The class is deliberately static‑method‑heavy so
 * that it can be used without instantiation.
 */
final class GridChecker {

    /** Length of the line we are looking for. */
    private static final int LINE_LENGTH = 5;

    /** Character that must appear four times in the line. */
    private static final char TARGET = 'X';

    /** Character that must appear exactly once in the line. */
    private static final char EMPTY = '.';

    // Prevent instantiation – all methods are static.
    private GridChecker() { }

    /**
     * Determines whether the supplied grid contains a line of {@value LINE_LENGTH}
     * consecutive cells that consist of exactly four {@code 'X'} characters and
     * one {@code '.'} character.  The line may be horizontal, vertical,
     * diagonal down‑right, or diagonal down‑left.
     *
     * @param grid a 10×10 matrix of characters (expected size is enforced
     *             at runtime for safety)
     * @return {@code true} if a matching line exists, otherwise {@code false}
     */
    public static boolean hasWinningPattern(char[][] grid) {
        final int rows = grid.length;
        final int cols = grid[0].length;
        assert rows == 10 && cols == 10 : "Grid must be exactly 10×10";

        // --- Horizontal -------------------------------------------------
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c <= cols - LINE_LENGTH; c++) {
                if (isPattern(grid, r, c, 0, 1)) {
                    return true;
                }
            }
        }

        // --- Vertical ---------------------------------------------------
        for (int r = 0; r <= rows - LINE_LENGTH; r++) {
            for (int c = 0; c < cols; c++) {
                if (isPattern(grid, r, c, 1, 0)) {
                    return true;
                }
            }
        }

        // --- Diagonal down‑right ----------------------------------------
        for (int r = 0; r <= rows - LINE_LENGTH; r++) {
            for (int c = 0; c <= cols - LINE_LENGTH; c++) {
                if (isPattern(grid, r, c, 1, 1)) {
                    return true;
                }
            }
        }

        // --- Diagonal down‑left -----------------------------------------
        for (int r = 0; r <= rows - LINE_LENGTH; r++) {
            for (int c = LINE_LENGTH - 1; c < cols; c++) {
                if (isPattern(grid, r, c, 1, -1)) {
                    return true;
                }
            }
        }

        // No pattern found
        return false;
    }

    /**
     * Checks whether a line starting at {@code startRow,startCol} with the
     * given step increments {@code rowStep, colStep} matches the required
     * pattern (four 'X' and one '.').
     *
     * @param grid     the source matrix
     * @param row      starting row index
     * @param col      starting column index
     * @param dr       increment for row (1 = down)
     * @param dc       increment for column (1 = right, -1 = left)
     * @return {@code true} if the line satisfies the pattern
     */
    private static boolean isPattern(char[][] grid, int row, int col,
                                     int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int k = 0; k < LINE_LENGTH; k++) {
            char cell = grid[row + k * dr][col + k * dc];
            if (cell == TARGET) {
                xCount++;
            } else if (cell == EMPTY) {
                dotCount++;
            } else {
                // Any other character invalidates the pattern
                return false;
            }
        }
        return xCount == 4 && dotCount == 1;
    }
}

import java.io.IOException;
import java.io.InputStream;

/**
 * Fast input scanner that works with {@link InputStream} and provides
 * methods for reading tokens and primitive values without the overhead
 * of {@link Scanner}.
 */
final class FastScanner {
    private static final int BUFFER_SIZE = 1 << 16;          // 64 KB

    private final InputStream stream;
    private final byte[] buffer = new byte[BUFFER_SIZE];
    private int bufferPointer = 0;
    private int bytesRead = 0;

    FastScanner(InputStream stream) {
        this.stream = stream;
    }

    /** Fills the internal buffer from the underlying stream. */
    private void refill() throws IOException {
        bytesRead = stream.read(buffer);
        bufferPointer = 0;
        if (bytesRead == -1) {
            buffer[0] = 0; // keep a sentinel value
            bytesRead = 1;
        }
    }

    /** Reads the next non‑whitespace byte. */
    private int readByte() throws IOException {
        if (bufferPointer >= bytesRead) {
            refill();
        }
        return buffer[bufferPointer++];
    }

    /** Skips all whitespace characters. */
    private static byte skipWhitespace(int b) {
        while (b <= ' ') {
            b = b == '\n' ? ' ' : b; // treat newline as space for skipping
            b = b == '\r' ? ' ' : b;
            b = b == '\t' ? ' ' : b;
            b = b == '\f' ? ' ' : b;
            b = b == '\b' ? ' ' : b;
            b = b == ' ' ? ' ' : b;
            b = b <= ' ' ? ' ' : b; // stop when b > ' '
        }
        return (byte) b;
    }

    /** Reads the next character, optionally skipping leading whitespace. */
    char readChar(boolean skipWhitespace) throws IOException {
        int c;
        do {
            c = readByte();
        } while (skipWhitespace && (c <= ' '));
        return (char) c;
    }

    /** Reads next signed integer. */
    int readInt() throws IOException {
        int c = skipWhitespace(readByte());
        boolean negative = c == '-';
        if (negative) {
            c = readByte();
        }
        int result = 0;
        while (c >= '0' && c <= '9') {
            result = result * 10 + (c - '0');
            c = readByte();
        }
        return negative ? -result : result;
    }

    /** Reads next signed long. */
    long readLong() throws IOException {
        int c = skipWhitespace(readByte());
        boolean negative = c == '-';
        if (negative) {
            c = readByte();
        }
        long result = 0;
        while (c >= '0' && c <= '9') {
            result = result * 10 + (c - '0');
            c = readByte();
        }
        return negative ? -result : result;
    }

    /** Reads next double value. */
    double readDouble() throws IOException {
        int c = skipWhitespace(readByte());
        boolean negative = c == '-';
        if (negative) {
            c = readByte();
        }
        long integerPart = 0;
        int fractionalExponent = 0;
        boolean hasDecimal = false;

        for (; (c >= '0' && c <= '9') || c == '.'; c = readByte()) {
            if (c == '.') {
                hasDecimal = true;
            } else if (hasDecimal) {
                fractionalExponent++;
            } else {
                integerPart = integerPart * 10 + (c - '0');
            }
        }
        double value = integerPart / Math.pow(10, fractionalExponent);
        return negative ? -value : value;
    }

    /** Reads the next non‑whitespace character. */
    char readChar() throws IOException {
        return readChar(true);
    }

    /** Reads the next token (up to whitespace). */
    String readToken() throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        do {
            c = readByte();
        } while (c <= ' ');
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    /** Reads the next line (terminated by '\n' or EOF). */
    String readLine() throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        do {
            c = readByte();
        } while (c != '\n' && c != -1);
        while (c != '\n' && c != -1) {
            c = readByte();
            if (c == '\n' || c == -1) {
                break;
            }
            sb.append((char) c);
        }
        return sb.toString();
    }
}

/**
 * Validates a 10×10 board for a winning line of five identical marks.
 * The validator works on a mutable board and guarantees that the board
 * is restored to its original state after the check.
 */
final class BoardValidator {

    private static final int SIZE = 10;
    private static final int WIN_LENGTH = 5;

    // Direction vectors for the four diagonal/straight directions
    private static final int[][] DIRECTIONS = {
            {0, 1},   // horizontal right
            {1, 0},   // vertical down
            {1, 1},   // diagonal down‑right
            {1, -1}   // diagonal down‑left
    };

    /**
     * Checks whether placing a mark at {@code row},{@code col} creates a
     * line of {@WIN_LENGTH} consecutive marks.
     *
     * @param board the mutable board representation
     * @param row   row index of the attempted move (0‑based)
     * @param col   column index of the attempted move (0‑based)
     * @return {@code true} if the move yields a winning line, otherwise {@code false}
     */
    static boolean hasFiveInRow(char[][] board, int row, int col) {
        board[row][col] = 'X'; // the player we are testing
        try {
            return linesThrough(board, row, col);
        } finally {
            board[row][col] = '.'; // restore original state
        }
    }

    /** Tests all four directions from the given cell for a run of five. */
    private static boolean linesThrough(char[][] board, int startR, int startC) {
        for (int[] dir : DIRECTIONS) {
            int count = 1; // the piece we just placed
            // walk forward
            for (int step = 1; step < WIN_LENGTH; ++step) {
                int r = startR + step * dir[0];
                int c = startC + step * dir[1];
                if (inside(r, c) && board[r][c] == 'X') {
                    ++count;
                } else {
                    break;
                }
            }
            // walk backward
            for (int step = 1; step < WIN_LENGTH; ++step) {
                int r = startR - step * dir[0];
                int c = startC - step * dir[1];
                if (inside(r, c) && board[r][c] == 'X') {
                    ++count;
                } else {
                    break;
                }
            }
            if (count >= WIN_LENGTH) {
                return true;
            }
        }
        return false;
    }

    private static boolean inside(int r, int c) {
        return r >= 0 && r < SIZE && c >= 0 && c < SIZE;
    }
}

/**
 * Main program entry point. Reads a 10×10 character board from standard input
 * and determines whether there exists a single empty cell ('.') that, when
 * filled with 'X', creates a winning line of five consecutive marks.
 * Prints {@code "YES"} if such a move exists, otherwise {@code "NO"}.
 */
public class Main {

    /** Symbol used for an empty cell. */
    static final char EMPTY = '.';

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        char[][] board = new char[SIZE][SIZE];

        // Load the board
        for (int r = 0; r < SIZE; ++r) {
            for (int c = 0; c < SIZE; ++c) {
                board[r][c] = fs.readChar(true);
            }
        }

        // Try to place 'X' in every empty cell and check for a win
        for (int r = 0; r < SIZE; ++r) {
            for (int c = 0; c < SIZE; ++c) {
                if (board[r][c] == EMPTY) {
                    if (BoardValidator.hasFiveInRow(board, r, c)) {
                        System.out.println("YES");
                        return;
                    }
                }
            }
        }

        System.out.println("NO");
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 * The logic is unchanged – it checks whether placing an 'X' on an empty
 * cell can create a line of four or more 'X's horizontally, vertically,
 * or on either diagonal on a 10×10 board.
 *
 * The refactor focuses on readability, maintainability and separation
 * of concerns:
 *   • Constants instead of magic numbers.
 *   • Small, well‑named helper methods.
 *   • Enum‑based direction handling.
 *   • Clear variable names and reduced nesting.
 */
public class Main {

    /** Size of the board (10 × 10). */
    private static final int BOARD_SIZE = 10;

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        Task task = new Task();
        task.solve(reader, out);
        out.close();
    }

    /** --------------------------------------------------------------------
     *  Task – contains the core algorithm.
     *  ------------------------------------------------------------------- */
    static class Task {

        /** Reads the board from the input and decides whether a winning move exists. */
        public void solve(InputReader in, PrintWriter out) {
            char[][] board = readBoard(in);
            boolean canWin = hasWinningMove(board);
            out.println(canWin ? "YES" : "NO");
        }

        /** Reads exactly BOARD_SIZE tokens, each representing a row of the board. */
        private static char[][] readBoard(InputReader in) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                String token = in.next();
                // Guard against tokens shorter than BOARD_SIZE (unlikely in contest data).
                token = token.length() >= BOARD_SIZE ? token : token + ".".repeat(BOARD_SIZE);
                for (int j = 0; j < BOARD_SIZE; j++) {
                    board[i][j] = token.charAt(j);
                }
            }
            return board;
        }

        /** Returns true if placing an 'X' in any empty cell creates a line of ≥4 X's. */
        private static boolean hasWinningMove(char[][] board) {
            for (int row = 0; row < BOARD_SIZE; row++) {
                for (int col = 0; col < BOARD_SIZE; col++) {
                    if (board[row][col] == '.') {
                        board[row][col] = 'X';                     // simulate move
                        boolean wins = checkAllDirections(board, row, col);
                        board[row][col] = '.';                       // restore board
                        if (wins) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /** Checks whether the newly placed 'X' creates a line of four or more in any direction. */
        private static boolean checkAllDirections(char[][] board, int r, int c) {
            for (Direction dir : Direction.values()) {
                int length = totalLengthInDirection(board, r, c, dir.dr, dir.dc);
                if (length >= 4) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Counts consecutive 'X' characters starting from (r,c) and extending
         * in both the positive and negative direction defined by (dr,dc).
         */
        private static int totalLengthInDirection(char[][] board, int r, int c, int dr, int dc) {
            int length = 1; // the cell we just placed 'X' in

            // Positive direction
            for (int step = 1; step < BOARD_SIZE; step++) {
                int nr = r + dr * step;
                int nc = c + dc * step;
                if (!inBounds(nr, nc) || board[nr][nc] != 'X') {
                    break;
                }
                length++;
            }

            // Negative direction
            for (int step = 1; step < BOARD_SIZE; step++) {
                int nr = r - dr * step;
                int nc = c - dc * step;
                if (!inBounds(nr, nc) || board[nr][nc] != 'X') {
                    break;
                }
                length++;
            }
            return length;
        }

        /** Simple bounds check for board coordinates. */
        private static boolean inBounds(int r, int c) {
            return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
        }

        /** Directions we care about – horizontal, vertical and the two diagonals. */
        private enum Direction {
            HORIZONTAL(0, 1),
            VERTICAL(1, 0),
            DIAG_DOWN_RIGHT(1, 1),
            DIAG_DOWN_LEFT(1, -1);

            final int dr;
            final int dc;

            Direction(int dr, int dc) {
                this.dr = dr;
                this.dc = dc;
            }
        }
    }

    /** --------------------------------------------------------------------
     *  InputReader – a tiny fast scanner used for competitive‑programming style input.
     *  ------------------------------------------------------------------- */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.InputStream;
import java.util.Arrays;

/**
 * Detects a winning 5‑in‑a‑row configuration on a 10×10 board.
 * The board contains characters 'X', 'O' and '.'.
 */
public class FiveInARow {

    /** Size of the square board. */
    private static final int BOARD_SIZE = 10;

    /** Directions used to check lines (8 possible directions). */
    private enum Direction {
        UP_LEFT(-1, -1),   UP(0, -1),   UP_RIGHT(1, -1),
        LEFT(-1, 0),       RIGHT(1, 0),
        DOWN_RIGHT(1, 1),  DOWN(0, 1),  DOWN_LEFT(-1, 1);

        private final int dx;
        private final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        int getDx() { return dx; }
        int getDy() { return dy; }
    }

    /** Entry point. */
    public static void main(String[] args) {
        char[][] board = readBoard();
        boolean win = hasFiveInARow(board);
        System.out.println(win ? "YES" : "NO");
    }

    /** Reads a 10×10 board from standard input. */
    private static char[][] readBoard() {
        InputReader reader = new InputReader(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        for (int r = 0; r < BOARD_SIZE; r++) {
            String line = reader.next();                 // each line contains 10 characters
            for (int c = 0; c < BOARD_SIZE; c++) {
                board[r][c] = line.charAt(c);
            }
        }
        return board;
    }

    /** Checks whether the board contains a winning line for 'X'. */
    private static boolean hasFiveInARow(char[][] board) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] == 'X') {
                    for (Direction dir : Direction.values()) {
                        if (isWinningLine(board, r, c, dir)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Determines whether a line of five positions starting at (row,col)
     * and extending in {@code dir} satisfies the win condition:
     * <ul>
     *   <li>the cell immediately next to the start must also be 'X',</li>
     *   <li>the next three cells must not contain 'O',</li>
     *   <li>there may be at most one '.' among those three cells.</li>
     * </ul>
     */
    private static boolean isWinningLine(char[][] board,
                                         int startRow, int startCol,
                                         Direction dir) {
        int dx = dir.getDx();
        int dy = dir.getDy();

        // 1️⃣ The neighbour cell must be 'X'
        int nxtRow = startRow + dx;
        int nxtCol = startCol + dy;
        if (isOutOfBounds(nxtRow, nxtCol) || board[nxtRow][nxtCol] != 'X') {
            return false;
        }

        int step = 0;          // how many cells after the neighbour we have examined
        int emptyCount = 0;    // number of '.' encountered
        boolean possible = true;

        // We need to examine three more cells (total line length = 5)
        while (step < 3 && possible) {
            int curRow = nxtRow + step * dx;
            int curCol = nxtCol + step * dy;

            if (isOutOfBounds(curRow, curCol)) {
                possible = false;
                break;
            }

            char cell = board[curRow][curCol];
            if (cell == '.') {
                emptyCount++;
                if (emptyCount >= 2) {          // more than one empty spot invalidates the pattern
                    possible = false;
                }
            } else if (cell == 'O') {
                possible = false;               // an opponent piece stops any win
            }
            step++;
        }

        return possible && step == 3;           // all three steps completed without breaking
    }

    /** Helper – true when row/col are outside the board. */
    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= BOARD_SIZE || c < 0 || c >= BOARD_SIZE;
    }
}

/* -------------------------------------------------------------
 *  Light‑weight input reader (unchanged from the original code)
 * ------------------------------------------------------------- */
class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int bytesRead = 0;
    private int currentByte = 0;

    InputReader(InputStream stream) {
        this.stream = stream;
    }

    /** Reads the next non‑space character, returning -1 on EOF. */
    private int readByte() throws InputMismatchException {
        if (currentByte >= bytesRead) {
            currentByte = 0;
            try {
                bytesRead = stream.read(buffer);
            } catch (Exception e) {
                throw new InputMismatchException();
            }
            if (bytesRead <= 0) {
                return -1;
            }
        }
        return buffer[currentByte++];
    }

    private static boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t';
    }

    /** Returns the next token (a maximal sequence of non‑space characters). */
    public String next() {
        int c;
        do {
            c = readByte();
        } while (c != -1 && isSpaceChar(c));

        StringBuilder sb = new StringBuilder();
        while (c != -1 && !isSpaceChar(c)) {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    /** Reads the next integer from the input. */
    public int nextInt() {
        int sign = 1;
        int c = readByte();
        while (isSpaceChar(c)) {
            c = readByte();
        }
        if (c == '-') {
            sign = -1;
            c = readByte();
        }
        int result = 0;
        while (!isSpaceChar(c) && c != -1) {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            result = result * 10 + (c - '0');
            c = readByte();
        }
        return result * sign;
    }

    // Additional read methods (nextLong, nextDouble, etc.) can be added if required.
}

