        private boolean hasWinningEmptyCell(char[][] board) {
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    if (board[r][c] == '.') {
                        // Tentatively place an 'X'.
                        board[r][c] = 'X';
                        if (containsFourInLineStartingAt(board, r, c)) {
                            // Undo before returning.
                            board[r][c] = '.';
                            return true;
                        }
                        // Undo the tentative placement.
                        board[r][c] = '.';
                    }
                }
            }
            return false;
        }

        /**
         * Determines whether there exists a line of exactly {@value #REQUIRED_LENGTH}
         * consecutive 'X' cells that start at {@code (row, col)} and extend in any
         * of the eight directions.
         */
        private boolean containsFourInLineStartingAt(char[][] board, int row, int col) {
            for (int dir = 0; dir < DX.length; dir++) {
                int dx = DX[dir];
                int dy = DY[dir];
                boolean allX = true;

                // Verify the next 4 cells in this direction are also 'X'.
                for (int step = 1; step <= REQUIRED_LENGTH; step++) {
                    int nr = row + dx * step;
                    int nc = col + dy * step;
                    if (!isInsideBoard(nr, nc) || board[nr][nc] != 'X') {
                        allX = false;
                        break;
                    }
                }

                if (allX) {
                    return true;
                }
            }
            return false;
        }

        /** Returns {@code true} if {@code (r, c)} lies inside the board limits. */
        private boolean isInsideBoard(int r, int c) {
            return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
        }
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Refactored version of the original program.
 *
 * <p>It reads a 10×10 sub‑grid that is placed inside a 20×20 board,
 * then checks whether there is a straight line of five 'X' characters.
 * The result is printed as "YES" or "NO".</p>
 *
 * <p>The refactor improves readability, maintainability and testability by:
 * <ul>
 *   <li>Extracting magic numbers into named constants.</li>
 *   <li>Separating board creation, input handling and win‑checking into
 *       dedicated methods.</li>
 *   <li>Using a small {@code Board}‑like API to encapsulate board logic.</li>
 *   <li>Renaming variables to expressive names.</li>
 *   <li>Keeping the fast custom I/O (MyReader / MyWriter) but making it
 *       thinner and better documented.</li>
 * </ul></p>
 */
public class Main {

    /** Size of the whole board (fixed at 20×20). */
    private static final int BOARD_SIZE = 20;
    /** Size of the sub‑grid that is actually read from input (10×10). */
    private static final int SUB_SIZE = 10;
    /** Offset where the sub‑grid starts inside the big board. */
    private static final int OFFSET = 5;

    public static void main(String[] args) throws Exception {
        /* Try‑with‑resources guarantees that the reader and writer are closed. */
        try (MyReader reader = new MyReader(System.in);
             MyWriter writer = new MyWriter(System.out)) {
            new Main().run(reader, writer);
        }
    }

    /** Orchestrates the whole workflow: board creation → input → detection → output. */
    private void run(MyReader reader, MyWriter writer) throws IOException {
        char[][] board = buildEmptyBoard();
        readSubGrid(board, reader);
        if (containsFiveXInARow(board)) {
            writer.println("YES");
        } else {
            writer.println("NO");
        }
    }

    /** Creates a board filled with the placeholder character 'O'. */
    private static char[][] buildEmptyBoard() {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (char[] row : board) {
            Arrays.fill(row, 'O');
        }
        return board;
    }

    /** Fills the central 10×10 area of the board with characters from the input. */
    private static void readSubGrid(char[][] board, MyReader reader) throws IOException {
        for (int r = OFFSET; r < OFFSET + SUB_SIZE; r++) {
            String line = reader.nextString();
            for (int c = OFFSET; c < OFFSET + SUB_SIZE; c++) {
                board[r][c] = line.charAt(c - OFFSET);
            }
        }
    }

    /** Returns true if any horizontal, vertical or diagonal line of five 'X's exists. */
    private static boolean containsFiveXInARow(char[][] board) {
        for (int r = OFFSET; r < OFFSET + SUB_SIZE; r++) {
            for (int c = OFFSET; c < OFFSET + SUB_SIZE; c++) {
                if (looksForFiveX(board, r, c, 0, 1)   // horizontal
                        || looksForFiveX(board, r, c, 1, 0)   // vertical
                        || looksForFiveX(board, r, c, 1, 1)    // diagonal ↓↘
                        || looksForFiveX(board, r, c, 1, -1)) { // diagonal ↓↙
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks a line starting at (row, col) and moving (dRow, dCol) directions.
     * The method stops as soon as it encounters an 'O' (which invalidates the streak)
     * or when five consecutive 'X's have been found.
     *
     * @return true if a streak of at least five 'X's is present in the given direction.
     */
    private static boolean looksForFiveX(char[][] board, int row, int col, int dRow, int dCol) {
        int consecutive = 0;
        for (int step = 0; step < SUB_SIZE; step++) {
            int r = row + dRow * step;
            int c = col + dCol * step;
            char cell = board[r][c];
            if (cell == 'X') {
                consecutive++;
                if (consecutive == 5) {
                    return true;
                }
            } else if (cell == 'O') {
                // Any 'O' breaks a possible streak of 'X's.
                return false;
            }
        }
        return false;
    }

    /* --------------------------------------------------------------------- */
    /* --------------------------- I/O HELPERS --------------------------- */
    /* --------------------------------------------------------------------- */

    /** Simple fast scanner based on a buffered input stream. */
    static class MyReader {
        private final BufferedInputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        MyReader(InputStream source) {
            in = new BufferedInputStream(source);
        }

        /** Reads the next available byte, handling buffer refills automatically. */
        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        /** Reads the next integer (mirrors the original implementation). */
        int nextInt() throws IOException {
            return (int) nextLong();
        }

        /** Reads the next long value (used by nextInt as well). */
        long nextLong() throws IOException {
            int c;
            long value = 0;
            boolean negative = false;
            // skip whitespace
            while ((c = readByte()) <= ' ') {}
            if (c == '-') {
                negative = true;
                c = readByte();
            }
            while (c >= '0') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return negative ? -value : value;
        }

        /** Reads the next token (a non‑whitespace string). */
        String nextString() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            // skip whitespace
            while ((c = readByte()) <= ' ' && c != -1) {}
            if (c == -1) {
                return null;
            }
            // collect non‑whitespace characters
            while (c > ' ') {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        /** Convenience wrapper returning a char array for the current token. */
        char[] nextCharArray() throws IOException {
            return nextString().toCharArray();
        }
    }

    /** Simple fast printer that writes directly to a buffered output stream. */
    static class MyWriter {
        private final BufferedOutputStream out;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private static final String NEW_LINE = System.lineSeparator();

        MyWriter(OutputStream source) {
            out = new BufferedOutputStream(source);
        }

        /** Writes a single character into the output buffer. */
        private void writeByte(byte b) throws IOException {
            if (ptr == buffer.length) {
                flush();
            }
            buffer[ptr++] = b;
        }

        /** Guarantees that there is room for at least {@code size} bytes. */
        private void ensureCapacity(int size) throws IOException {
            if (ptr + size >= buffer.length) {
                flush();
            }
        }

        /** Flushes the buffer to the underlying file stream. */
        private void flush() throws IOException {
            out.write(buffer, 0, ptr);
            out.flush();
            ptr = 0;
        }

        /** Prints a long value as a sequence of characters. */
        void print(long v) throws IOException {
            for (char ch : Long.toString(v).toCharArray()) {
                writeByte((byte) ch);
            }
        }

        /** Prints a string (character by character). */
        void print(String s) throws IOException {
            for (int i = 0; i < s.length(); i++) {
                writeByte((byte) s.charAt(i));
            }
        }

        /** Prints a line separator and ends the current line. */
        void println(String s) throws IOException {
            print(s);
            print(NEW_LINE);
        }

        /** Convenience method for printing a single character. */
        void print(char c) throws IOException {
            writeByte((byte) c);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Reads a 10×10 board consisting of 'X' and '.' characters.
 * Determines whether any consecutive 5‑cell line (horizontal,
 * vertical or diagonal) contains exactly four 'X' and one '.'.
 * The check is performed on the original board and on the board
 * rotated 90° clockwise.
 */
public class BingoChecker {

    private static final int SIZE = 10;
    private static final int LINE_LENGTH = 5;
    private static final char MARK = 'X';
    private static final char EMPTY = '.';

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        char[][] board = readBoard();

        if (hasWinningPattern(board) || hasWinningPattern(rotate90Clockwise(board))) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /** Reads 10 lines from standard input, each representing a row of the board. */
    private static char[][] readBoard() throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = new char[SIZE][SIZE];
            for (int i = 0; i < SIZE; i++) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input.");
                }
                board[i] = line.toCharArray();
            }
            return board;
        }
    }

    /** Returns true if any horizontal or diagonal‑down‑right line of length 5
     *  contains exactly four MARKs and one EMPTY. */
    private static boolean hasWinningPattern(char[][] board) {
        // Horizontal
        if (checkHorizontal(board)) {
            return true;
        }
        // Vertical
        if (checkVertical(board)) {
            return true;
        }
        // Diagonal down‑right (↘)
        if (checkDiagonalDownRight(board)) {
            return true;
        }
        // Diagonal up‑right (↗)
        if (checkDiagonalUpRight(board)) {
            return true;
        }
        return false;
    }

    /** Checks all horizontal 5‑cell windows. */
    private static boolean checkHorizontal(char[][] board) {
        for (int row = 0; row < SIZE; row++) {
            for (int col = 0; col <= SIZE - LINE_LENGTH; col++) {
                if (matchingPattern(board[row], col, 0, 1)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Checks all vertical 5‑cell windows. */
    private static boolean checkVertical(char[][] board) {
        for (int col = 0; col < SIZE; col++) {
            for (int row = 0; row <= SIZE - LINE_LENGTH; row++) {
                if (matchingPattern(board, row, col, SIZE)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Checks all diagonal down‑right (↘) 5‑cell windows. */
    private static boolean checkDiagonalDownRight(char[][] board) {
        for (int row = 0; row <= SIZE - LINE_LENGTH; row++) {
            for (int col = 0; col <= SIZE - LINE_LENGTH; col++) {
                if (matchingPattern(board, row, col, 1)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Checks all diagonal up‑right (↗) 5‑cell windows. */
    private static boolean checkDiagonalUpRight(char[][] board) {
        for (int row = LINE_LENGTH - 1; row < SIZE; row++) {
            for (int col = 0; col <= SIZE - LINE_LENGTH; col++) {
                if (matchingPattern(board, row, col, -1)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks a line of length {@code LINE_LENGTH} starting at (startRow,startCol)
     * moving by {@code deltaRow, deltaCol} per step.
     *
     * @return true if the line contains exactly four MARKs and one EMPTY.
     */
    private static boolean matchingPattern(char[][] board,
                                            int startRow, int startCol,
                                            int deltaRow, int deltaCol) {
        int markCount = 0;
        int emptyCount = 0;

        for (int i = 0; i < LINE_LENGTH; i++) {
            int r = startRow + i * deltaRow;
            int c = startCol + i * deltaCol;
            char cell = board[r][c];
            if (cell == MARK) {
                markCount++;
            } else if (cell == EMPTY) {
                emptyCount++;
            } else {
                // Unexpected character – pattern cannot match.
                return false;
            }
        }
        return markCount == 4 && emptyCount == 1;
    }

    /**
     * Rotates the given board 90° clockwise and returns a new board.
     * The original board is left unchanged.
     */
    private static char[][] rotate90Clockwise(char[][] src) {
        char[][] rotated = new char[SIZE][SIZE];
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                rotated[i][j] = src[SIZE - 1 - j][i];
            }
        }
        return rotated;
    }
}

import java.util.Scanner;

/**
 * Main entry point for the CF825B problem.
 * Reads a 10×10 board where each cell is either 'X' (filled) or '.' (empty).
 * Determines whether there exists a cell from which we can extend in four
 * directions until we meet either an 'X' or the first '.' (according to the
 * original algorithm) and count at least {@value #LIMIT} characters in any
 * direction.
 */
public class CF825B {

    /** Size of the board (fixed to 10×10 for the original problem). */
    private static final int BOARD_SIZE = 10;

    /** Minimum number of cells that must be counted in a direction to succeed. */
    private static final int LIMIT = 5;

    public static void main(String[] args) {
        CF825BSolver solver = new CF825BSolver();
        char[][] board = readBoard();
        boolean found = solver.solve(board);
        System.out.println(found ? "YES" : "NO");
    }

    /**
     * Reads a single whitespace‑delimited token from {@code System.in}
     * and fills the 10×10 board row‑by‑row.
     *
     * @return the filled board
     */
    private static char[][] readBoard() {
        Scanner scanner = new Scanner(System.in);
        // The original code expects exactly one token containing BOARD_SIZE² characters.
        String token = scanner.next();
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        int index = 0;
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                board[row][col] = token.charAt(index++);
            }
        }
        return board;
    }
}

/**
 * Encapsulates the algorithm that decides whether a solution exists.
 * The logic mirrors the original implementation but is expressed with
 * clearer method names, early returns and no mutable shared state.
 */
class CF825BSolver {

    /**
     * Attempts to find a cell (y, x) such that extending in the four
     * diagonal/orthogonal directions yields at least {@value CF825BSolver#LIMIT}
     * consecutive cells according to {@link #countInDirection}.
     *
     * @param board the current board
     * @return {@code true} if a qualifying cell exists, otherwise {@code false}
     */
    public boolean solve(char[][] board) {
        for (int y = 0; y < CF825B.BOARD_SIZE; y++) {
            for (int x = 0; x < CF825B.BOARD_SIZE; x++) {
                if (checkAtPosition(y, x, board)) {
                    // As soon as we find one valid position we can stop.
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks whether placing a marker at (y, x) would satisfy the
     * “count ≥ LIMIT” condition in at least one of the four directions.
     *
     * @param y       row of the examined cell
     * @param x       column of the examined cell
     * @param board   the board to inspect
     * @return {@code true} if the condition is met, otherwise {@code false}
     */
    private boolean checkAtPosition(int y, int x, char[][] board) {
        int[] counters = new int[4];                 // counts in four directions
        // The original algorithm counts up to the first '.' in each direction,
        // but only one '.' per direction is considered.
        // The direction vectors are: east, south, southeast, southwest.
        Direction[] directions = {
                Direction.EAST,
                Direction.SOUTH,
                Direction.SOUTHEAST,
                Direction.SOUTHWEST
        };

        for (int dirIdx = 0; dirIdx < directions.length; dirIdx++) {
            Direction dir = directions[dirIdx];
            int count = countInDirection(board, y, x, dir);
            if (count >= CF825B.LIMIT) {
                return true; // early success – no need to check other directions
            }
        }
        return false;
    }

    /**
     * Counts cells from (y, x) moving in {@code dir} until either:
     * <ul>
     *   <li>the board boundary is reached, or</li>
     *   <li>an 'X' is encountered, or</li>
     *   <li>the first '.' is encountered (only one '.' per direction).</li>
     * </ul>
     *
     * @param board the board to scan
     * @param y     starting row
     * @param x     starting column
     * @param dir   direction to move
     * @return the number of cells counted
     */
    private int countInDirection(char[][] board, int y, int x, Direction dir) {
        boolean hasSkippedDot = false;
        int count = 0;
        int ny = y;
        int nx = x;

        switch (dir) {
            case EAST:
                for (int cx = x; cx < CF825B.BOARD_SIZE; cx++) {
                    char cell = board[y][cx];
                    if (cell == 'X') {
                        count++;
                    } else if (cell == '.' && !hasSkippedDot) {
                        count++;
                        hasSkippedDot = true;
                    } else {
                        break;
                    }
                }
                break;

            case SOUTH:
                for (int cy = y; cy < CF825B.BOARD_SIZE; cy++) {
                    char cell = board[cy][x];
                    if (cell == 'X') {
                        count++;
                    } else if (cell == '.' && !hasSkippedDot) {
                        count++;
                        hasSkippedDot = true;
                    } else {
                        break;
                    }
                }
                break;

            case SOUTHEAST:
                for (int step = 0; ; step++) {
                    int cy = y + step;
                    int cx = x + step;
                    if (cy >= CF825B.BOARD_SIZE || cx >= CF825B.BOARD_SIZE) {
                        break;
                    }
                    char cell = board[cy][cx];
                    if (cell == 'X') {
                        count++;
                    } else if (cell == '.' && !hasSkippedDot) {
                        count++;
                        hasSkippedDot = true;
                    } else {
                        break;
                    }
                }
                break;

            case SOUTHWEST:
                for (int step = 0; ; step++) {
                    int cy = y + step;
                    int cx = x - step;
                    if (cy >= CF825B.BOARD_SIZE || cx < 0) {
                        break;
                    }
                    char cell = board[cy][cx];
                    if (cell == 'X') {
                        count++;
                    } else if (cell == '.' && !hasSkippedDot) {
                        count++;
                        hasSkippedDot = true;
                    } else {
                        break;
                    }
                }
                break;
        }
        return count;
    }

    /** Simple wrapper around the four movement directions used by the algorithm. */
    private enum Direction {
        EAST,      // ( 0, +1)
        SOUTH,     // (+1, 0)
        SOUTHEAST, // (+1, +1)
        SOUTHWEST  // (+1, -1)
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Size of the square board (10×10). */
    private static final int BOARD_SIZE = 10;
    /** Minimum length of a line to win. */
    private static final int WIN_LENGTH = 5;

    /** Four directions: right, down, down‑left, down‑right */
    private static final int[][] DIRECTIONS = {
            {0, 1},          // right
            {1, 0},          // down
            {-1, 1},         // down‑left
            {1, 1}           // down‑right
    };

    public static void main(String[] args) {
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            FastScanner scanner = new FastScanner(in);
            OutputWriter printer = new OutputWriter(out);

            new Solver().solve(scanner, printer);

        } catch (Exception e) {
            throw new UncheckedExecutionException(e);
        }
    }

    /** Core logic of the problem. */
    static class Solver {

        /** Entry point used by the original code. */
        void solve(InputReader reader, OutputWriter writer) {
            char[][] board = readBoard(reader);

            for (int row = 0; row < BOARD_SIZE; row++) {
                for (int col = 0; col < BOARD_SIZE; col++) {
                    if (board[row][col] == '.') {
                        board[row][col] = 'X';

                        if (hasWinningLine(board, row, col)) {
                            writer.print("YES");
                            return;
                        }

                        board[row][col] = '.';
                    }
                }
            }

            writer.print("NO");
        }

        /** Reads the 10×10 board from the scanner. */
        private static char[][] readBoard(InputReader scanner) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = scanner.nextString();
                board[i] = line.toCharArray();
            }
            return board;
        }

        /** Checks whether placing an ‘X’ at (r,c) creates a line of
         *  at least WIN_LENGTH consecutive ‘X’s in any direction. */
        private boolean hasWinningLine(char[][] board, int r, int c) {
            for (int[] dir : DIRECTIONS) {
                if (countLine(board, r, c, dir[0], dir[1]) >= WIN_LENGTH) {
                    return true;
                }
                // also count the opposite direction
                if (countLine(board, r, c, -dir[0], -dir[1]) >= WIN_LENGTH) {
                    return true;
                }
            }
            return false;
        }

        /** Counts how many consecutive ‘X’s are present starting from (r,c)
         *  and moving (dr,dc). Counts both the placed ‘X’ and any existing
         *  ‘X’s before it. */
        private int countLine(char[][] board, int r, int c, int dr, int dc) {
            int count = 0;
            for (int step = 0; ; step++) {
                int nr = r + step * dr;
                int nc = c + step * dc;
                if (!isInBounds(nr, nc)) {
                    break;
                }
                if (board[nr][nc] != 'X') {
                    break;
                }
                count++;
            }
            return count;
        }

        /** Returns true if (row, col) lies inside the 10×10 board. */
        private boolean isInBounds(int row, int col) {
            return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE;
        }
    }

    /* ------------------------------------------------------------------ */
    /* Utility classes – they keep the original spirit but are cleaned up */
    /* ------------------------------------------------------------------ */

    /** Simple wrapper around {@link InputStream} that provides fast tokenised input. */
    static class FastScanner extends InputReader {
        FastScanner(InputStream stream) {
            super(stream);
        }

        @Override
        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }
    }

    /** Minimalistic Output class that mimics the original behaviour. */
    static class OutputWriter {
        private final PrintWriter writer;

        OutputWriter(OutputStream out) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        /** Prints the given objects separated by a single space. */
        void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) writer.print(' ');
                writer.print(objects[i]);
            }
            writer.flush();
        }

        /** Closes the underlying stream. */
        void close() {
            writer.close();
        }
    }

    /** Very small wrapper around {@link InputStream} used by the original code. */
    static class InputReader {
        private final InputStream stream;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte, returning -1 on EOF. */
        int read() {
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        /** Returns the next non‑whitespace token as a {@link String}. */
        String nextString() {
            int c;
            do {
                c = read();
            } while (isSpaceChar(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        /** Checks whether the character is considered whitespace. */
        private boolean isSpaceChar(int ch) {
            return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
        }

        /* Buffer used to speed up reading. */
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
    }
}

import java.util.*;
