public class TaskB {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        int n = 10;
        char[][] board = new char[n][n];
        for (int i = 0; i < n; i++) {
            board[i] = br.readLine().toCharArray();
        }

        final int LINE_LENGTH = 5;
        boolean poss = false;

        checkDirection(board, n, LINE_LENGTH, 0, 1);
        checkDirection(board, n, LINE_LENGTH, 1, 0);
        checkDirection(board, n, LINE_LENGTH, 1, 1);
        checkDirection(board, n, LINE_LENGTH, 1, -1);

        System.out.println(poss ? "YES" : "NO");
    }

    private static void checkDirection(char[][] board, int n, int LINE_LENGTH, int dx, int dy) {
        for (int i = 0; i <= n - LINE_LENGTH; i++) {
            for (int j = 0; j <= n - LINE_LENGTH; j++) {
                if (isWinningPattern(board, i, j, dx, dy)) {
                    System.out.println("YES");
                    System.exit(0);
                }
            }
        }
    }

    private static boolean isWinningPattern(char[][] board, int i, int j, int dx, int dy) {
        int nX = 0;
        int nD = 0;
        for (int k = 0; k < 5; k++) {
            char c = board[i + k * dx][j + k * dy];
            if (c == 'X') {
                nX++;
            } else if (c == 'O') {
                // Skip 'O' - not part of the pattern condition
            } else {
                nD++;
            }
        }
        return nX == 4 && nD == 1;
    }
}

