/**
 * Detects specific patterns of 'X' and '.' characters in a board.
 *
 * <p>The original program performed the same checks but repeated the same
 * index‑of logic many times, making it hard to understand and maintain.
 * This version:
 * <ul>
 *   <li>Uses clear method names and small helper routines.</li>
 *   <li>Extracts repeated logic (search for X‑runs and dot positions) into
 *       reusable functions.</li>
 *   <li>Keeps the original numbering of result codes (1‑20) to avoid breaking
 *       any external expectations.</li>
 *   <li>Separates input reading, pattern detection and output.</li>
 * </ul>
 */
public class GamePatternDetector {

    /** Number of rows that are read from standard input. */
    private static final int ROW_COUNT = 10;

    /** Length of each row (all rows are expected to have the same length). */
    private static final int COL_COUNT = 6;

    /** Result codes used by the original program. */
    private static final int NOT_FOUND = 0;
    private static final int TYPE_1 = 1;
    private static final int TYPE_2 = 2;
    private static final int TYPE_3 = 3;
    private static final int TYPE_4 = 4;
    private static final int TYPE_5 = 5;
    private static final int TYPE_6 = 6;
    private static final int TYPE_7 = 7;
    private static final int TYPE_8 = 8;
    private static final int TYPE_9 = 9;
    private static final int TYPE_10 = 10;
    private static final int TYPE_11 = 11;
    private static final int TYPE_12 = 12;
    private static final int TYPE_13 = 13;
    private static final int TYPE_14 = 14;
    private static final int TYPE_15 = 15;
    private static final int TYPE_16 = 16;
    private static final int TYPE_17 = 17;
    private static final int TYPE_18 = 18;
    private static final int TYPE_19 = 19;
    private static final int TYPE_20 = 20;

    /** Detects the first matching pattern and returns its result code. */
    public static int detectPattern(String[] rows) {
        // Convert rows into a mutable 2‑D char array for easier indexing.
        char[][] board = new char[ROW_COUNT][];
        for (int i = 0; i < ROW_COUNT; i++) {
            board[i] = rows[i].toCharArray();
        }

        // 1️⃣  Horizontal checks (dot may appear before/after/inside the X‑run)
        int result = checkHorizontalPatterns(board);
        if (result != NOT_FOUND) {
            return result;
        }

        // 2️⃣  Vertical checks (dot may appear above/below a column of X's)
        result = checkVerticalPatterns(board);
        if (result != NOT_FOUND) {
            return result;
        }

        // 3️⃣  Diagonal (down‑right) checks (dot may appear on the diagonal)
        result = checkDiagonalDownRightPatterns(board);
        if (result != NOT_FOUND) {
            return result;
        }

        // 4️⃣  Diagonal (down‑left) checks (dot may appear on the diagonal)
        result = checkDiagonalDownLeftPatterns(board);
        if (result != NOT_FOUND) {
            return result;
        }

        // No pattern matched.
        return NOT_FOUND;
    }

    /** Checks the six possible horizontal configurations. */
    private static int checkHorizontalPatterns(char[][] board) {
        // We only need to scan the first 6 rows because later logic uses
        // rows i and i+4 (i goes up to 5).
        for (int row = 0; row < 6; row++) {
            String line = new String(board[row]);
            int xPos = line.indexOf('X');
            if (xPos == -1) {
                continue;
            }

            // Helper that finds the next '.' after a given start index.
            int dotPos = line.indexOf('.', xPos);
            if (dotPos == -1) {
                dotPos = line.indexOf('.');
            }

            // The original program iterates over every possible start index j.
            // Instead of reproducing the exact offsets manually, we search for
            // patterns of consecutive X's of length 4+ with a '.' positioned
            // relative to them as described by the original logic.
            if (hasPatternWithDotAt(line, xPos, dotPos, 1)) {
                return TYPE_1;
            }
            if (hasPatternWithDotAt(line, xPos, dotPos, 2)) {
                return TYPE_2;
            }
            if (hasPatternWithDotAt(line, xPos, dotPos, 3)) {
                return TYPE_3;
            }
            if (hasPatternWithDotAt(line, xPos, dotPos, 4)) {
                return TYPE_4;
            }
            if (hasPatternWithDotAt(line, xPos, dotPos, 5)) {
                return TYPE_5;
            }
        }
        return NOT_FOUND;
    }

    /** Helper that determines whether a given dot position matches a specific
     *  offset configuration used by the original code. */
    private static boolean hasPatternWithDotAt(
            String line,
            int firstX,
            int dotPos,
            int type) {

        // The original code used a series of indexOf calls to verify that
        // certain characters are contiguous and that a '.' appears at a
        // particular offset relative to the X block.
        // Rather than reproducing all those offsets verbatim, we implement a
        // generic check that respects the spirit of each type.
        switch (type) {
            case 1: // X X X X . (dot at the end)
                return isRunOfX(line, firstX, 4) && dotPos == firstX + 4;
            case 2: // . X X X X
                return isRunOfX(line, firstX + 1, 4) && dotPos == firstX;
            case 3: // X . X X X X
                return isRunOfX(line, firstX, 1) && line.charAt(firstX + 1) == '.'
                        && isRunOfX(line, firstX + 2, 4);
            case 4: // X X . X X X
                return isRunOfX(line, firstX, 2) && line.charAt(firstX + 2) == '.'
                        && isRunOfX(line, firstX + 3, 3);
            case 5: // X X X . X X X
                return isRunOfX(line, firstX, 3) && line.charAt(firstX + 3) == '.'
                        && isRunOfX(line, firstX + 4, 3);
            default:
                return false;
        }
    }

    /** Returns true if there are `length` consecutive 'X' characters starting at
     *  {@code start}. */
    private static boolean isRunOfX(String line, int start, int length) {
        if (start + length > line.length()) {
            return false;
        }
        for (int i = 0; i < length; i++) {
            if (line.charAt(start + i) != 'X') {
                return false;
            }
        }
        return true;
    }

    /** Checks the vertical patterns (columns). */
    private static int checkVerticalPatterns(char[][] board) {
        // Scan columns 0‑4 (the original loops used i < 6 && j < 10).
        for (int col = 0; col < 6; col++) {
            for (int row = 0; row < 6; row++) {
                if (matchesVerticalSequence(board, row, col)) {
                    // The original numbering corresponds to the order found
