                    return switch (row) {
                        case 0 -> TYPE_6;
                        case 1 -> TYPE_7;
                        case 2 -> TYPE_8;
                        case 3 -> TYPE_9;
                        case 4 -> TYPE_10;
                        default -> NOT_FOUND;
