        return NOT_FOUND;
    }

    /** Determines whether a vertical line of four consecutive 'X's ends with a '.'
     *  according to the original logic. */
    private static boolean matchesVerticalSequence(char[][] board, int row, int col) {
        // This mirrors the original nested logic but expressed more clearly.
        // The original checked several offset combinations; we keep only the
        // ones that actually produced a non‑zero result.
        // For brevity and to stay faithful to the original behaviour we reuse
        // the same index calculations but wrap them in a dedicated method.
        char[][] tmp = board; // just to keep the same reference style as original
        // The original pattern #6: X X X X . (dot after the X block)
        if (isVerticalXXXXDot(tmp, row, col)) {
            return true;
        }
        // Pattern #7: X X X . X
        if (isVerticalXXXDotX(tmp, row, col)) {
