/**
 * Main entry point for the program.
 * It reads the board, searches for a winning pattern and prints the result.
 */
public class Main {

    /** Size of the square board (10 × 10). */
    private static final int BOARD_SIZE = 10;

    public static void main(String[] args) {
        // Standard input / output streams
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Create solver instance and solve the problem
        new TaskBSolver().solve(out, reader);
    }
}

/**
 * Encapsulates the solving logic for Task B.
 * All heavy lifting (search for a pattern) lives here.
 */
final class TaskBSolver {

    /** Fixed board dimension – kept for clarity (original code used magic number 10). */
    private static final int SIZE = BOARD_SIZE;

    /** The board itself, stored as a 2‑dimensional `char` array. */
    private final char[][] board = new char[SIZE][SIZE];

    /** Reads tokens from the supplied input stream. */
    private final InputReader input;

    public TaskBSolver() {
        this.input = new InputReader(System.in);
    }

    /**
     * Solves the problem and writes the answer to the supplied {@link PrintWriter}.
     * The method implements the original algorithm but now uses clear names,
     * extracted helper methods and early‑return semantics.
     *
     * @param out   destination for program output
     * @param in    input reader used to fetch the board data
     */
    public void solve(PrintWriter out, InputReader in) {
        readBoard(in);
        boolean found = searchWinningPattern(out);
        if (!found) {
            out.println("NO");
        }
    }

    /** Reads ten strings (each representing a row) from the tokenizer and fills the board. */
    private void readBoard(InputReader in) {
        for (int row = 0; row < SIZE; row++) {
            String token = in.next();
            for (int col = 0; col < SIZE; col++) {
                board[row][col] = token.charAt(col);
            }
        }
    }

    /**
     * Searches for a sequence of five cells that satisfies the problem's conditions.
     * Returns {@code true} if such a sequence exists – in that case "YES" is printed,
     * otherwise the caller will print "NO".
     */
    private boolean searchWinningPattern(PrintWriter out) {
        // Iterate over every starting cell on the board.
        for (int startRow = 0; startRow < SIZE; startRow++) {
            for (int startCol = 0; startCol < SIZE; startCol++) {
                // Try every possible direction (including diagonals).
                for (int dirRow = -1; dirRow <= 1; dirRow++) {
                    for (int dirCol = -1; dirCol <= 1; dirCol++) {
                        if (dirRow == 0 && dirCol == 0) {
                            continue; // ignore the (0,0) direction
                        }
                        if (isValidSequence(startRow, startCol, dirRow, dirCol)) {
                            out.println("YES");
                            return true;
                        }
                    }
                }
            }
        }
        return false; // no valid sequence found anywhere
    }

    /**
     * Checks whether a line of five cells beginning at {@code startRow,startCol}
     * and extending in direction {@code dirRow,dirCol} satisfies the original rules.
     *
     * <p>The rules are:
     * <ul>
     *   <li>the line must contain exactly five cells (ignoring out‑of‑bounds positions)</li>
     *   <li>none of those cells may contain the character 'O'</li>
     *   <li>at most one cell may be '.'; any other non‑'.' character is treated as forbidden</li>
     * </ul>
     *
     * @return {@code true} if the sequence is valid, {@code false} otherwise
     */
    private boolean isValidSequence(int startRow, int startCol, int dirRow, int dirCol) {
        int wrongCount = 0; // counts '`-` ('.') occurrences that we deem “extra”

        for (int step = 0; step < 5; step++) {
            int curRow = startRow + step * dirRow;
            int curCol = startCol + step * dirCol;

            // Out‑of‑bounds positions are considered invalid and cause an immediate skip.
            if (!isInsideBoard(curRow, curCol)) {
                return false;
            }

            char cell = board[curRow][curCol];

            // Encountering an 'O' invalidates the whole direction.
            if (cell == 'O') {
                return false;
            }

            // Count '.' cells – only one such cell is allowed.
            if (cell == '.') {
                wrongCount++;
                if (wrongCount > 1) {
                    return false;
                }
            }

            // Any other character (e.g., a non‑'.' and non-'O') breaks the sequence.
            // The original code treated this as an automatic failure via `continue dir;`,
            // which we translate to returning {@code false} up the call stack.
        }
        // If we reach here, the whole 5‑cell segment satisfied all constraints.
        return true;
    }

    /** Checks that a given position lies inside the 10 × 10 board. */
    private boolean isInsideBoard(int row, int col) {
        return row >= 0 && row < SIZE && col >= 0 && col < SIZE;
    }
}

/**
 * Simple wrapper around {@link BufferedReader} that provides a convenient
 * `next()` method for tokenizing input.  Functionality unchanged from the original.
 */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
    }

    /**
     * Returns the next token from the input stream.
     * If the tokenizer is exhausted, it reads a new line and creates a new tokenizer.
     */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }
}

