            for (int col = 0; col < SIZE; col++) {
                board[row][col] = valueOf(line.charAt(col));
            }
        }
    }

    /** Converts a character read from input into its numeric code. */
    private static int valueOf(char c) {
        return switch (c) {
            case 'X' -> PLAYER_X;
            case 'O' -> PLAYER_O;
            default -> EMPTY;
        };
    }

    /** Searches for an empty cell that would create a winning line. */
    private static boolean hasEmptyCellThatFormsWin() {
        for (int row = 0; row < SIZE; row++) {
            for (int col = 0; col < SIZE; col++) {
                if (board[row][col] == EMPTY && canCompleteWinningLine(row, col)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Checks, from a given empty cell, whether placing a piece there yields a sum of 40. */
    private static boolean canCompleteWinningLine(int row, int col) {
        // check horizontal, vertical and both diagonals (5 cells centered on the position)
        return checkStraightLine(row, col, 0, 1)   // horizontal
            || checkStraightLine(row, col, 1, 0)   // vertical
            || checkStraightLine(row, col, 1, 1)   // diagonal down‑right
            || checkStraightLine(row, col, 1, -1); // diagonal down‑left
    }

    /** Returns true if the sum of the five cells along the given direction equals 40. */
    private static boolean checkStraightLine(int centreRow, int centreCol,
                                             int directionRow, int directionCol) {
        int sum = 0;
        // The five cells are symmetric around the centre: offsets -2 .. +2
        for (int offset = -2; offset <= 2; offset++) {
            int r = centreRow + directionRow * offset;
            int c = centreCol + directionCol * offset;
            if (isInside(r, c)) {
                sum += board[r][c];
            }
        }
        return sum == 40; // matches the original condition
    }

    /** Utility to test whether coordinates lie within the board limits. */
    private static boolean isInside(int row, int col) {
        return row >= 0 && row < SIZE && col >= 0 && col < SIZE;
    }
}

import java.util.Scanner;

public class ConnectFiveChecker {

    private static final int BOARD_SIZE = 10;
    private static final int REQUIRED_LENGTH = 5;
    private static final char[] TARGET_PATTERN = {'.', 'X', 'X', 'X', 'X'};

    /** Four directions we need to examine from each cell */
    private static final int[][] DIRECTIONS = {
            {0, 1},   // horizontal (right)
            {1, 0},   // vertical   (down)
            {1, 1},   // diagonal   (down‑right)
            {-1, 1}   // diagonal   (down‑left)
    };

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            boolean win = false;

            for (int row = 0; row < BOARD_SIZE && !win; row++) {
                for (int col = 0; col < BOARD_SIZE && !win; col++) {
                    for (int[] dir : DIRECTIONS) {
                        if (hasFiveInDirection(board, row, col, dir[0], dir[1])) {
                            win = true;
                        }
                    }
                }
            }

            System.out.println(win ? "YES" : "NO");
        }
    }

    /** Reads exactly BOARD_SIZE lines of length BOARD_SIZE from the scanner. */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = scanner.next();
            if (line.length() != BOARD_SIZE) {
                throw new IllegalArgumentException(
                        "Each line must contain exactly " + BOARD_SIZE + " characters.");
            }
            for (int j = 0; j < BOARD_SIZE; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /**
     * Checks whether a line of length {@value #REQUIRED_LENGTH} starting at
     * (startRow,startCol) and moving (dr,dc) contains the pattern
     * one '.' and four 'X's (in any order).
     */
    private static boolean hasFiveInDirection(char[][] board,
                                               int startRow, int startCol,
                                               int dr, int dc) {
        char[] line = new char[REQUIRED_LENGTH];
        for (int step = 0; step < REQUIRED_LENGTH; step++) {
            int r = startRow + dr * step;
            int c = startCol + dc * step;
            if (!isInBounds(r, c)) {
                return false;                     // out of board → not a valid line
            }
            line[step] = board[r][c];
        }
        return matchesPattern(line);
    }

    private static boolean isInBounds(int row, int col) {
        return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE;
    }

    /** Returns true if the sequence contains exactly one '.' and four 'X's. */
    private static boolean matchesPattern(char[] seq) {
        int xCount = 0;
        int dotCount = 0;
        for (char ch : seq) {
            if (ch == 'X') {
                xCount++;
            } else if (ch == '.') {
                dotCount++;
            } else {
                // Any other character breaks the required pattern.
                return false;
            }
        }
        return xCount == 4 && dotCount == 1;
    }
}

import java.util.Scanner;

/**
 * Refactored solution for the “Edu Round 25 B” problem.
 * Improves readability, separates concerns and eliminates magic numbers.
 */
public class EduRound25B {

    /** Size of the square board (10 × 10). */
    private static final int BOARD_SIZE = 10;

    /** Directions in which we have to look for a line of 5 X's. */
    private static final int[][] DIRECTIONS = {
            {0, 1},   // horizontal (right)
            {1, 0},   // vertical   (down)
            {1, 1},   // diagonal down‑right
            {1, -1}   // diagonal down‑left
    };

    /** The board that stores the current configuration. */
    private static char[][] board;

    /** Entry point of the program. */
    public static void main(String[] args) {
        board = new char[BOARD_SIZE][BOARD_SIZE];
        readBoard();
        if (canPlaceWinningX()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads exactly BOARD_SIZE lines from {@code Scanner} and stores them
     * into the board array.
     */
    private static void readBoard() {
        Scanner scanner = new Scanner(System.in);
        for (int row = 0; row < BOARD_SIZE; row++) {
            String line = scanner.next();
            board[row] = line.toCharArray();
        }
        scanner.close();
    }

    /**
     * Tries to place an 'X' on every empty cell ('.') and checks whether
     * this creates a line of five 'X's in any direction. Returns {@code true}
     * as soon as a winning placement is found.
     */
    private static boolean canPlaceWinningX() {
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                if (board[row][col] == '.') {
                    board[row][col] = 'X';
                    if (hasFiveInARow(row, col)) {
                        board[row][col] = '.'; // restore before returning
                        return true;
                    }
                    board[row][col] = '.'; // restore for next iteration
                }
            }
        }
        return false;
    }

    /**
     * Checks whether placing an 'X' at {@code (row, col)} creates a line
     * consisting of at least five consecutive 'X's in any of the four
     * predefined directions.
     */
    private static boolean hasFiveInARow(int row, int col) {
        for (int[] dir : DIRECTIONS) {
            int dx = dir[0];
            int dy = dir[1];
            if (countConsecutiveX(row, col, dx, dy) >= 5) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts how many consecutive 'X's can be found starting from
     * {@code (row, col)} and moving in direction {@code (dx, dy)} and its
     * opposite direction. The count includes the cell itself.
     */
    private static int countConsecutiveX(int row, int col, int dx, int dy) {
        int count = 1; // the cell we just placed 'X' into

        // move forward
        for (int step = 1; step < 5; step++) {
            int nr = row + dx * step;
            int nc = col + dy * step;
            if (isInsideBoard(nr, nc) && board[nr][nc] == 'X') {
                count++;
            } else {
                break;
            }
        }

        // move backward
        for (int step = 1; step < 5; step++) {
            int nr = row - dx * step;
            int nc = col - dy * step;
            if (isInsideBoard(nr, nc) && board[nr][nc] == 'X') {
                count++;
            } else {
                break;
            }
        }

        return count;
    }

    /** Helper that checks whether a coordinate lies inside the 10 × 10 board. */
    private static boolean isInsideBoard(int r, int c) {
        return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Refactored version of the original Five‑in‑a‑row detector.
 * Improves readability, removes duplicated logic and uses
 * constants instead of magic numbers.
 */
public class FiveInARow {

    /** Size of the board (fixed at 10×10). */
    private static final int SIZE = 10;

    /** Length of the line we are looking for (always 5). */
    private static final int FIVE = 5;

    /**
     * Reads the 10×10 board from standard input.
     *
     * @return a 2‑dimensional char array representing the board
     * @throws IOException if reading from stdin fails
     */
    private static char[][] readBoard() throws IOException {
        char[][] board = new char[SIZE][SIZE];
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            for (int i = 0; i < SIZE; i++) {
                board[i] = br.readLine().toCharArray();
            }
        }
        return board;
    }

    /** Entry point – scans the board and prints "YES" if a pattern exists. */
    public static void main(String[] args) throws IOException {
        char[][] board = readBoard();

        for (int row = 0; row < SIZE; row++) {
            for (int col = 0; col < SIZE; col++) {
                // Skip the sentinel character used in the original code
                if (board[row][col] != '0') {
                    if (hasFiveInRow(board, row, col)) {
                        System.out.print("YES");
                        return;
                    }
                }
            }
        }
        System.out.println("NO");
    }

    /**
     * Determines whether any of the four directions from the given cell
     * contains exactly four 'X' characters and one empty '.' character.
     *
     * @param board   the game board
     * @param startR  starting row
     * @param startC  starting column
     * @return true if a winning pattern is found in any direction
     */
    private static boolean hasFiveInRow(char[][] board, int startR, int startC) {
        // Directions: right, down, down‑right, down‑left
        return checkDirection(board, startR, startC, 0, 1)   // horizontal
            || checkDirection(board, startR, startC, 1, 0)   // vertical
            || checkDirection(board, startR, startC, 1, 1)   // diagonal \
            || checkDirection(board, startR, startC, 1, -1); // anti‑diagonal /
    }

    /**
     * Checks a straight line of up to five cells beginning at (row, col)
     * and extending by (deltaRow, deltaCol) each step.
     *
     * @param board      the game board
     * @param row        starting row
     * @param col        starting column
     * @param dRow       row increment per step
     * @param dCol       column increment per step
     * @return true if the segment contains exactly four 'X' and one '.'
     */
    private static boolean checkDirection(char[][] board, int row, int col,
                                          int dRow, int dCol) {
        int occupied = 0; // count of 'X'
        int empty    = 0; // count of '.'

        for (int step = 0; step < FIVE; step++) {
            int r = row + dRow * step;
            int c = col + dCol * step;

            // Stop if we move outside the board limits
            if (r < 0 || r >= SIZE || c < 0 || c >= SIZE) {
                break;
            }

            char cell = board[r][c];
            if (cell == 'X') {
                occupied++;
            } else if (cell == '.') {
                empty++;
            } else {
                // Any other character (e.g., '0') breaks the pattern
                break;
            }
        }

        // A winning segment must have 4 X's and exactly 1 empty spot
        return occupied == FIVE - 1 && empty == 1;
    }
}

