/**
 * Reads a 10×10 board consisting of the characters 'X' and 'O' and reports whether
 * either player has a consecutive line of four symbols in any direction
 * (horizontal, vertical, or either diagonal).
 */
public class Main {

    /** Size of the board – kept as a single source of truth. */
    private static final int BOARD_SIZE = 10;

    public static void main(String[] args) {
        /* Use try‑with‑resources to guarantee the Scanner is closed. */
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            if (hasFourInARow(board, 'X') || hasFourInARow(board, 'O')) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /** Reads exactly BOARD_SIZE lines from the provided Scanner. */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = scanner.next();
            board[i] = line.toCharArray();   // each line is guaranteed to be of length 10
        }
        return board;
    }

    /** Determines if the given player possesses a line of four consecutive symbols. */
    private static boolean hasFourInARow(char[][] board, char player) {
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                if (hasFourInDirection(board, row, col, player, 0, 1)   // horizontal
                        || hasFourInDirection(board, row, col, player, 1, 0)   // vertical
                        || hasFourInDirection(board, row, col, player, 1, 1)   // down‑right diagonal
                        || hasFourInDirection(board, row, col, player, 1, -1)) { // down‑left diagonal
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks for four consecutive {@code player} symbols starting at (row, col) moving
     * {@code rowDelta, colDelta} steps.
     *
     * @return {@code true} if exactly four in a row are found in that direction.
     */
    private static boolean hasFourInDirection(char[][] board, int row, int col,
                                              char player, int rowDelta, int colDelta) {
        int count = 0;
        for (int step = 0; step < 4; step++) {
            int r = row + step * rowDelta;
            int c = col + step * colDelta;
            if (!isInside(r, c) || board[r][c] != player) {
                break; // gap or out of bounds ends the run
            }
            count++;
        }
        return count == 4;
    }

    /** Returns {@code true} if the given coordinates lie inside the board limits. */
    private static boolean isInside(int row, int col) {
        return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for the problem.
 * The code is organised into small, well‑named methods and avoids
 * duplicated logic, making it easier to understand and maintain.
 */
public class B {

    /** Size of the playing board (10 × 10). */
    private static final int BOARD_SIZE = 10;

    /** Minimum length of a winning line (5 consecutive 'X'). */
    private static final int WIN_LENGTH = 5;

    /** Directions to check: right, down, down‑right, down‑left. */
    private static final int[][] DIRECTIONS = {
            {0, 1},   // right
            {1, 0},   // down
            {1, 1},   // down‑right diagonal
            {1, -1}   // down‑left diagonal
    };

    /** Fast scanner used to read input (kept compatible with original). */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            try {
                br = new BufferedReader(new InputStreamReader(System.in));
                st = new StringTokenizer(br.readLine());
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        String next() {
            while (true) {
                if (st.hasMoreTokens()) {
                    return st.nextToken();
                }
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        char[][] nextGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                grid[r] = next().toCharArray();
            }
            return grid;
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        char[][] board = sc.nextGrid(BOARD_SIZE, BOARD_SIZE);

        boolean canWin = false;
        for (int r = 0; r < BOARD_SIZE && !canWin; r++) {
            for (int c = 0; c < BOARD_SIZE && !canWin; c++) {
                if (board[r][c] == '.') {
                    board[r][c] = 'X';
                    canWin = hasWinningLine(board);
                    board[r][c] = '.';
                }
            }
        }

        out.println(canWin ? "YES" : "NO");
        out.close();
    }

    /**
     * Determines whether the given board contains a line of at least
     * {@value #WIN_LENGTH} consecutive 'X' characters in any direction.
     *
     * @param board the game board
     * @return true if a winning line exists
     */
    private static boolean hasWinningLine(char[][] board) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] != 'X') {
                    continue;
                }
                for (int[] dir : DIRECTIONS) {
                    if (lineLength(board, r, c, dir[0], dir[1]) >= WIN_LENGTH) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Counts the total number of consecutive 'X' cells in a given direction
     * (both forward and backward) starting from the supplied cell.
     *
     * @param board     the game board
     * @param r         row of the starting cell
     * @param c         column of the starting cell
     * @param dr        row step (+1 or -1) for the forward direction
     * @param dc        column step (+1 or -1) for the forward direction
     * @return length of the consecutive 'X' line that passes through (r,c)
     */
    private static int lineLength(char[][] board, int r, int c, int dr, int dc) {
        int length = 1; // the cell itself

        // Move forward
        for (int step = 1; step < BOARD_SIZE; step++) {
            int nr = r + step * dr;
            int nc = c + step * dc;
            if (!inBounds(nr, nc) || board[nr][nc] != 'X') {
                break;
            }
            length++;
        }

        // Move backward
        for (int step = 1; step < BOARD_SIZE; step++) {
            int nr = r - step * dr;
            int nc = c - step * dc;
            if (!inBounds(nr, nc) || board[nr][nc] != 'X') {
                break;
            }
            length++;
        }

        return length;
    }

    /** Utility to check whether a coordinate is inside the board limits. */
    private static boolean inBounds(int row, int col) {
        return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE;
    }
}

/**
 * Refactored version of the original program.
 *
 * <p>The program reads a grid of characters ('.' represents an empty cell),
 * tries to place a single 'X' in each empty cell and checks whether that
 * placement creates a line of at least five 'X's horizontally, vertically,
 * or diagonally. If any placement yields a winning line the answer is
 * "YES", otherwise "NO".
 *
 * <p>The refactor focuses on:
 * <ul>
 *   <li>Clear separation of concerns (input, processing, validation).</li>
 *   <li>Descriptive naming and reduced magic numbers.</li>
 *   <li>Extraction of small helper methods to keep each operation focused.</li>
 *   <li>Use of constants for fixed values.</li>
 *   <li>Elimination of duplicated code and unnecessary flags.</li>
 *   <li>Improved readability through proper formatting and comments.</li>
 * </ul>
 */
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

    /** Fixed grid size for this problem. */
    private static final int GRID_SIZE = 10;

    /** Number of consecutive marks required to win. */
    private static final int WIN_LENGTH = 5;

    /** Character representing an empty cell. */
    private static final char EMPTY = '.';

    /** Character used to mark a move. */
    private static final char MARK = 'X';

    /** Valid characters read from input. */
    private static final charReader[] EMPTY_OR_MARK = {EMPTY, MARK};

    /** Buffered reader used for fast input. */
    private static final BufferedReader READER =
            new BufferedReader(new InputStreamReader(System.in));

    /** Buffered writer for output (writes to System.out). */
    private static final java.io.PrintWriter OUT = new java.io.PrintWriter(System.out);

    /** ----------------------------------------------------------- */
    /** Entry point. */
    public static void main(String[] args) throws IOException {
        solve();
        OUT.flush();
        OUT.close();
    }

    /** ----------------------------------------------------------- */
    /** Solves the problem by iterating over test cases. */
    private static void solve() throws IOException {
        // The original program used a constant number of test cases.
        // Adjust this if the real input contains multiple cases.
        solveSingleTestCase();
    }

    /** ----------------------------------------------------------- */
    /** Reads a grid of size N x N (where N == GRID_SIZE) and determines
     *  whether a winning move exists. */
    private static void solveSingleTestCase() throws IOException {
        // Read N from the first token; the original code hard‑coded 10.
        // Keeping the same behaviour for compatibility.
        String line;
        int n = GRID_SIZE;                     // grid dimension
        char[][] grid = new char[n][n];

        // Read exactly n lines, each containing n characters (ignoring whitespace).
        for (int i = 0; i < n; i++) {
            line = READER.readLine();
            if (line == null) {
                return; // No more input.
            }
            // Remove any whitespace and take the first n characters.
            StringBuilder sb = new StringBuilder(line.replaceAll("\\s+", ""));
            if (sb.length() < n) {
                // Pad missing characters with '.' to avoid ArrayIndexOutOfBounds.
                while (sb.length() < n) {
                    sb.append(EMPTY);
                }
            }
            for (int j = 0; j < n; j++) {
                grid[i][j] = sb.charAt(j);
            }
        }

        // Try placing an 'X' in each empty cell until a winning configuration is found.
        boolean foundWinningMove = false;
        for (int i = 0; i < n && !foundWinningMove; i++) {
            for (int j = 0; j < n && !foundWinningMove; j++) {
                if (grid[i][j] == EMPTY) {
                    grid[i][j] = MARK;
                    if (hasFiveInARow(grid)) {
                        foundWinningMove = true;
                    }
                    grid[i][j] = EMPTY; // restore for next iteration
                }
            }
        }

        OUT.println(foundWinningMove ? "YES" : "NO");
    }

    /** ----------------------------------------------------------- */
    /** Checks whether there exists a line of at least WIN_LENGTH MARKs.
     *  Checks horizontal, vertical and both diagonal directions. */
    private static boolean hasFiveInARow(char[][] grid) {
        int size = grid.length;

        // Helper lambda to evaluate consecutive marks in a given direction.
        // Directions are represented as (rowDelta, colDelta).
        int[][] directions = {
                {0, 1},   // horizontal
                {1, 0},   // vertical
                {1, 1},   // diagonal down‑right
                {1, -1}   // diagonal up‑right
        };

        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (grid[r][c] != MARK) {
                    continue;
                }
                for (int[] dir : directions) {
                    if (countInDirection(grid, r, c, dir[0], dir[1]) >= WIN_LENGTH) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** ----------------------------------------------------------- */
    /** Counts how many consecutive MARKs exist starting from (r,c) moving
     *  by (dr,dc) until a non‑MARK or the grid border is reached. */
    private static int countInDirection(char[][] grid, int r, int c,
                                        int dr, int dc) {
        int count = 1; // current cell is already MARK

        // Move forward along the direction.
        int nr = r + dr;
        int nc = c + dc;
        while (isInside(grid, nr, nc) && grid[nr][nc] == MARK) {
            count++;
            nr += dr;
            nc += dc;
        }

        // Move backward along the opposite direction.
        nr = r - dr;
        nc = c - dc;
        while (isInside(grid, nr, nc) && grid[nr][nc] == MARK) {
            count++;
            nr -= dr;
            nc -= dc;
        }

        return count;
    }

    /** ----------------------------------------------------------- */
    /** Returns true if (row, col) is a valid coordinate inside the grid. */
    private static boolean isInside(char[][] grid, int row, int col) {
        return row >= 0 && row < grid.length && col >= 0 && col < grid.length;
    }
}

import java.io.*;
