/**
 * Solves the problem of determining whether placing a single 'X' into an
 * empty cell (represented by '.') creates a line of exactly five consecutive
 * 'X's on a 10×10 board.
 *
 * The solution is split into small, focused methods that each perform a
 * single responsibility (reading input, checking rows, columns, diagonals,
 * etc.).  This makes the code self‑documenting and easy to maintain.
 */
public class B825 {

    /* ---------- I/O helpers ------------------------------------------------ */

    private final FastScanner fs = new FastScanner(System.in);
    private final PrintWriter out = new PrintWriter(System.out, true);

    /** Reads the whole 10×10 grid from stdin. */
    private char[][] readGrid() {
        char[][] grid = new char[10][];
        for (int r = 0; r < 10; r++) {
            grid[r] = fs.nextChars();          // one line of exactly 10 characters
        }
        return grid;
    }

    /** Executes the core algorithm and prints the answer. */
    public void solve() {
        char[][] grid = readGrid();

        boolean winningMoveExists = false;

        // Try every empty cell, place a tentative 'X' and test the board.
        for (int r = 0; r < 10 && !winningMoveExists; r++) {
            for (int c = 0; c < 10 && !winningMoveExists; c++) {
                if (grid[r][c] == '.') {
                    grid[r][c] = 'X';
                    winningMoveExists = hasFiveInARow(grid);
                    grid[r][c] = '.';               // backtrack
                }
            }
        }

        out.println(winningMoveExists ? "YES" : "NO");
    }

    /* ---------- Game‑logic --------------------------------------------------- */

    /** Determines whether the supplied grid contains a line of exactly 5 'X's. */
    private boolean hasFiveInARow(char[][] board) {
        return hasFiveConsecutiveHorizontally(board) ||
               hasFiveConsecutiveVertically(board) ||
               hasFiveConsecutiveDiagonalDown(board) ||
               hasFiveConsecutiveDiagonalUp(board);
    }

    /** Checks every horizontal line of length 5. */
    private boolean hasFiveConsecutiveHorizontally(char[][] board) {
        for (int r = 0; r < 10; r++) {
            int streak = 0;
            for (int c = 0; c < 10; c++) {
                if (board[r][c] == 'X') {
                    streak++;
                    if (streak == 5) return true;
                } else {
                    streak = 0;
                }
            }
        }
        return false;
    }

    /** Checks every vertical line of length 5. */
    private boolean hasFiveConsecutiveVertically(char[][] board) {
        for (int c = 0; c < 10; c++) {
            int streak = 0;
            for (int r = 0; r < 10; r++) {
                if (board[r][c] == 'X') {
                    streak++;
                    if (streak == 5) return true;
                } else {
                    streak = 0;
                }
            }
        }
        return false;
    }

    /** Checks the two diagonal directions (down‑right and up‑right). */
    private boolean hasFiveConsecutiveDiagonalDown(char[][] board) {
        // Down‑right diagonals start at the top row or the leftmost column.
        for (int startR = 0; startR < 10; startR++) {
            int streak = 0;
            for (int steps = 0; steps < 10 && startR + steps < 10; steps++) {
                int r = startR + steps;
                int c = steps;
                if (board[r][c] == 'X') {
                    streak++;
                    if (streak == 5) return true;
                } else {
                    streak = 0;
                }
            }
        }
        for (int startC = 1; startC < 10; startC++) {
            int streak = 0;
            for (int steps = 0; steps < 10 && startC + steps < 10; steps++) {
                int r = steps;
                int c = startC + steps;
                if (board[r][c] == 'X') {
                    streak++;
                    if (streak == 5) return true;
                } else {
                    streak = 0;
                }
            }
        }
        return false;
    }

    /** Checks the up‑right diagonal direction. */
    private boolean hasFiveConsecutiveDiagonalUp(char[][] board) {
        // Up‑right diagonals start at the bottom row or the leftmost column.
        for (int startR = 9; startR >= 0; startR--) {
            int streak = 0;
            for (int steps = 0; steps < 10 && startR - steps >= 0; steps++) {
                int r = startR - steps;
                int c = steps;
                if (board[r][c] == 'X') {
                    streak++;
                    if (streak == 5) return true;
                } else {
                    streak = 0;
                }
            }
        }
        for (int startC = 1; startC < 10; startC++) {
            int streak = 0;
            for (int steps = 0; steps < 10 && startC + steps < 10; steps++) {
                int r = steps;
                int c = startC + steps;
                if (board[r][c] == 'X') {
                    streak++;
                    if (streak == 5) return true;
                } else {
                    streak = 0;
                }
            }
        }
        return false;
    }

    /* ---------- Fast scanner ------------------------------------------------ */

    /** Simple fast scanner that reads raw bytes and exposes convenient methods. */
    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) { this.in = in; }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** Reads the next non‑whitespace byte. */
        private int nextNonSpace() throws IOException {
            int b;
            while ((b = readByte()) != -1 && isSpace(b)) ;
            return b;
        }

        /** Returns the next sequence of digits as an int. */
        int nextInt() throws IOException {
            int sign = 1, val = 0;
            int b = nextNonSpace();
            if (b == '-') {
                sign = -1;
                b = readByte();
            }
            while (b != -1 && !isSpace(b)) {
                if (b < '0' || b > '9') throw new InputMismatchException();
                val = val * 10 + (b - '0');
                b = readByte();
            }
            return val * sign;
        }

        /** Returns the next sequence of characters as a string. */
        String nextWord() throws IOException {
            StringBuilder sb = new StringBuilder();
            int b = nextNonSpace();
            while (b != -1 && !isSpace(b)) {
                sb.append((char) b);
                b = readByte();
            }
            return sb.toString();
        }

        /** Returns the next sequence of characters of the requested length. */
        char[] nextChars(int n) throws IOException {
            char[] arr = new char[n];
            for (int i = 0; i < n; i++) {
                int b = nextNonSpace();
                if (b == -1) throw new InputMismatchException();
                arr[i] = (char) b;
            }
            return arr;
        }

        private static boolean isSpace(int c) { return c <= ' '; }
    }

    /* ---------- Entry point --------------------------------------------------- */

    public static void main(String[] args) {
        new B825().solve();
    }
}

import java.io.*;
import java.util.*;

public class ConnectFiveChecker implements Runnable {

    /** Board size and win length are fixed for this problem. */
    private static final int BOARD_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final int THREAD_STACK_SIZE = 1 << 28;   // 256 MiB

    private final FastScanner scanner;
    private final PrintWriter out;

    public ConnectFiveChecker() {
        scanner = new FastScanner();
        out = new PrintWriter(System.out);
        System.err.println("Go!");
    }

    @Override
    public void run() {
        char[][] board = readBoard();

        if (canWinWithOneAdditionalX(board)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
        out.close();
    }

    /** Reads the 10×10 board from the fast scanner. */
    private char[][] readBoard() {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int row = 0; row < BOARD_SIZE; row++) {
            String line = scanner.next();
            board[row] = line.toCharArray();
        }
        return board;
    }

    /** Tries to place an 'X' on every empty cell and checks whether that yields a win. */
    private boolean canWinWithOneAdditionalX(char[][] board) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] == '.') {
                    board[r][c] = 'X';
                    boolean win = hasFiveInRow(board);
                    board[r][c] = '.';
                    if (win) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Checks all four directions for a consecutive run of exactly five 'X's. */
    private boolean hasFiveInRow(char[][] board) {
        return hasHorizontalFive(board) ||
               hasVerticalFive(board) ||
               hasDiagonalDownRightFive(board) ||
               hasDiagonalDownLeftFive(board);
    }

    /** Horizontal scan – left to right. */
    private boolean hasHorizontalFive(char[][] board) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c <= BOARD_SIZE - WIN_LENGTH; c++) {
                if (matches(board, r, c, 0, 1)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Vertical scan – top to bottom. */
    private boolean hasVerticalFive(char[][] board) {
        for (int c = 0; c < BOARD_SIZE; c++) {
            for (int r = 0; r <= BOARD_SIZE - WIN_LENGTH; r++) {
                if (matches(board, r, c, 1, 0)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Main diagonal (top‑left → bottom‑right). */
    private boolean hasDiagonalDownRightFive(char[][] board) {
        for (int r = 0; r <= BOARD_SIZE - WIN_LENGTH; r++) {
            for (int c = 0; c <= BOARD_SIZE - WIN_LENGTH; c++) {
                if (matches(board, r, c, 1, 1)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Anti diagonal (top‑right → bottom‑left). */
    private boolean hasDiagonalDownLeftFive(char[][] board) {
        for (int r = 0; r <= BOARD_SIZE - WIN_LENGTH; r++) {
            for (int c = WIN_LENGTH - 1; c < BOARD_SIZE; c++) {
                if (matches(board, r, c, 1, -1)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Utility that checks a line of length WIN_LENGTH starting at (row, col) moving by (dRow, dCol). */
    private boolean matches(char[][] board, int row, int col, int dRow, int dCol) {
        for (int k = 0; k < WIN_LENGTH; k++) {
            if (board[row + k * dRow][col + k * dCol] != 'X') {
                return false;
            }
        }
        return true;
    }

    /** Randomly shuffles an array 50 times and then sorts it – kept from the original sample. */
    private static void randomSort(int[] a) {
        int n = a.length;
        Random rng = new Random();
        for (int i = 0; i < 50; i++) {
            int x = rng.nextInt(n);
            int y = rng.nextInt(n);
            int tmp = a[x];
            a[x] = a[y];
            a[y] = tmp;
        }
        Arrays.sort(a);
    }

    /** Fast scanner implementation (unchanged logic, renamed fields for clarity). */
    private static class FastScanner {
        private static final int BUFFER_SIZE = 1 << 16;
        private final byte[] buffer = new byte[BUFFER_SIZE];
        private int index = 0, bytesRead = 0;
        private final InputStream in;

        FastScanner() {
            in = new BufferedInputStream(System.in, BUFFER_SIZE);
        }

        private int readByte() throws IOException {
            if (index >= bytesRead) {
                bytesRead = in.read(buffer);
                index = 0;
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[index++];
        }

        private String nextNonWhitespace() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c <= ' ');
            return Character.toString((char) c);
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }

        long nextLong() throws IOException {
            String token = nextNonWhitespace();
            boolean negative = token.charAt(0) == '-';
            if (negative) {
                token = token.substring(1);
            }
            long value = 0;
            for (char ch : token.toCharArray()) {
                value = value * 10 + (ch - '0');
            }
            return negative ? -value : value;
        }

        String next() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c <= ' ');
            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        String nextLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = readByte();
            } while (c <= '\n' && c != -1);
            while (c != -1 && c != '\n') {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        boolean hasNext() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c <= ' ');
            if (c == -1) {
                return false;
            }
            index--; // return the character to the stream
            return true;
        }
    }

    /** Entry point – launches the checker on a new thread with an enlarged stack. */
    public static void main(String[] args) {
        new Thread(null, new ConnectFiveChecker(), "_cf", THREAD_STACK_SIZE).start();
    }
}

import java.io.*;
import java.util.Random;

/**
 * Detects whether a 10×10 board contains a line of exactly five
 * adjacent ‘X’ symbols with precisely one empty ('.') cell in the middle.
 * The program reads 10 strings of length 10 from standard input and prints
 * “YES” if such a line exists, otherwise “NO”.
 */
public class Main {

    /** Size of the board – kept as a constant for easy tuning. */
    private static final int BOARD_SIZE = 10;

    /** Directions in which we have to look for a potential winning line.
     *  (right, down, down‑right, down‑left) correspond to the four
     *  diagonals/straight lines required by the original algorithm. */
    private enum Direction {
        HORIZONTAL(0, 1),
        VERTICAL(1, 0),
        DIAGONAL_DOWN_RIGHT(1, 1),
        DIAGONAL_DOWN_LEFT(1, -1);

        final int dx;
        final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }
    }

    public static void main(String[] args) throws IOException {
        // -----------------------------------------------------------------
        //  Input / output handling (try‑with‑resources guarantees proper close)
        // -----------------------------------------------------------------
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            InputReader reader = new InputReader(in);
            PrintWriter writer = new PrintWriter(out);

            char[][] board = readBoard(reader);

            boolean hasWinningLine = containsWinningSequence(board);

            writer.print(hasWinningLine ? "YES" : "NO");
            writer.flush();          // explicit flush for deterministic output
        }
    }

    /** Reads ten lines of length ten from the tokenizer and stores them
     *  into a char array representing the board. */
    private static char[][] readBoard(InputReader reader) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int row = 0; row < BOARD_SIZE; row++) {
            String line = reader.next();               // each line is exactly 10 chars
            for (int col = 0; col < BOARD_SIZE; col++) {
                board[row][col] = line.charAt(col);
            }
        }
        return board;
    }

    /** Determines whether the board contains a line of five adjacent cells
     *  that holds exactly four 'X' and one '.' (the '.' may be anywhere). */
    private static boolean containsWinningSequence(char[][] board) {
        // Check every start position for each of the four directions
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                for (Direction dir : Direction.values()) {
                    if (startsWinningSequence(board, row, col, dir.dx, dir.dy)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Checks whether a line of length five starting at (row,col) and moving
     *  by (dx,dy) contains exactly four 'X' and one '.' character. */
    private static boolean startsWinningSequence(char[][] board,
                                                 int startRow,
                                                 int startCol,
                                                 int dx,
                                                 int dy) {
        int xCount = 0;
        int dotCount = 0;

        int curRow = startRow;
        int curCol = startCol;

        // The first cell is always part of the sequence
        processCell(board[curRow][curCol], xCount, dotCount);

        // Continue for the remaining four cells of the line
        for (int step = 1; step < 5; step++) {
            curRow += dx;
            curCol += dy;
            if (!isInsideBoard(curRow, curCol)) {
                // If we step outside the board the sequence cannot be valid
                return false;
            }
            processCell(board[curRow][curCol], xCount, dotCount);
        }

        // Winning condition: exactly four X's and exactly one '.'.
        return xCount == 4 && dotCount == 1;
    }

    /** Helper that updates the counters based on a single cell value. */
    private static void processCell(char cell, int[] xCount, int[] dotCount) {
        if (cell == 'X') {
            xCount[0]++;
        } else if (cell == '.') {
            dotCount[0]++;
        }
        // Any other character is ignored – they never appear in the problem data.
    }

    /** Returns true if the given coordinates are inside the 0‑based board. */
    private static boolean isInsideBoard(int row, int col) {
        return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE;
    }

    // -----------------------------------------------------------------------
    //  Utility methods (kept because they existed in the original source,
    //  even though they are not used by the current algorithm).
    // -----------------------------------------------------------------------
    private static void shuffle(long[] arr) {
        int n = arr.length;
        Random rnd = new Random();
        for (int i = 0; i < n; ++i) {
            long tmp = arr[i];
            int randomPos = i + rnd.nextInt(n - i);
            arr[i] = arr[randomPos];
            arr[randomPos] = tmp;
        }
    }

    private static void shuffle(int[] arr) {
        int n = arr.length;
        Random rnd = new Random();
        for (int i = 0; i < n; ++i) {
            int tmp = arr[i];
            int randomPos = i + rnd.nextInt(n - i);
            arr[i] = arr[randomPos];
            arr[randomPos] = tmp;
        }
    }

    /** Euclidean algorithm – retained for completeness, though unused. */
    private static int gcd(int x, int y) {
        return y == 0 ? x : gcd(y, x % y);
    }

    /** Simple buffered‑reader wrapper used by the original program. */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.valueOf(next());
        }

        double nextDouble() {
            return Double.valueOf(next());
        }

        String nextLine() throws IOException {
            return reader.readLine();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Determines whether a player ('X') can win in a single move of a
 * five‑in‑a‑row game on a 10×10 board.  An empty cell ('.') may be treated
 * as a wildcard that can be turned into 'X' at most once per line.
 *
 * <p>Refactored for readability, maintainability and better separation of
 * concerns.</p>
 */
public class FiveInRow {

    /** Board size – both dimensions are equal. */
    private static final int BOARD_SIZE = 10;

    /** Symbols used on the board. */
    private static final char CROSS = 'X';
    private static final char ZERO  = 'O';
    private static final char EMPTY = '.';

    /** All possible directions on the board. */
    private enum Direction {
        LEFT(-1, 0), RIGHT(1, 0), UP(0, -1), DOWN(0, 1),
        LEFT_UP(-1, -1), RIGHT_UP(1, -1), LEFT_DOWN(-1, 1), RIGHT_DOWN(1, 1);

        private final int dx;
        private final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        /** Return the delta‑x component. */
        int getDx() { return dx; }

        /** Return the delta‑y component. */
        int getDy() { return dy; }
    }

    /** Directions in which we search for a possible win. */
    private static final Direction[] ALL_DIRECTIONS = Direction.values();

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = readBoard(reader);
            boolean canWin = false;

            for (int y = 0; y < BOARD_SIZE && !canWin; y++) {
                for (int x = 0; x < BOARD_SIZE && !canWin; x++) {
                    if (isCross(board, x, y) && canWinInOneMove(board, x, y)) {
                        canWin = true;
                    }
                }
            }

            System.out.println(canWin ? "YES" : "NO");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** Reads exactly {@value #BOARD_SIZE} lines, each containing {@value #BOARD_SIZE}
     *  characters, from the supplied reader.</p>
     */
    private static char[][] readBoard(BufferedReader reader) throws IOException {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int y = 0; y < BOARD_SIZE; y++) {
            String line = reader.readLine();
            if (line == null || line.length() != BOARD_SIZE) {
                throw new IOException("Invalid input: each line must contain exactly "
                        + BOARD_SIZE + " characters.");
            }
            for (int x = 0; x < BOARD_SIZE; x++) {
                board[y][x] = line.charAt(x);
            }
        }
        return board;
    }

    /** Checks whether the cell at (x, y) contains a cross ('X'). */
    private static boolean isCross(char[][] board, int x, int y) {
        return board[y][x] == CROSS;
    }

    /** Determines whether placing a cross at (x, y) creates a line of at least
     *  five consecutive crosses when at most one empty cell is allowed in that
     *  line. */
    private static boolean canWinInOneMove(char[][] board, int startX, int startY) {
        for (Direction dir : ALL_DIRECTIONS) {
            int length = countSequence(board, startX, startY, dir.getDx(), dir.getDy());
            if (length >= 5) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts the number of consecutive {@code CROSS} symbols when moving from
     * {@code (x, y)} in the direction {@code (dx, dy)}.  An {@code EMPTY}
     * symbol may be used once as a wildcard; it increments the count but marks
     * that the wildcard has been consumed.
     *
     * @param board    the game board
     * @param x        starting column (0‑based)
     * @param y        starting row (0‑based)
     * @param dx       step increment for the column
     * @param dy       step increment for the row
     * @return the length of the sequence that can be formed, respecting the
     *         at‑most‑one‑wildcard rule.
     */
    private static int countSequence(char[][] board, int x, int y, int dx, int dy) {
        int count = 0;
        boolean wildcardUsed = false;

        while (isInBounds(x, y)) {
            char cell = board[y][x];

            if (cell == ZERO) {
                break; // opponent blocks the sequence
            }

            if (cell == EMPTY) {
                if (wildcardUsed) {
                    break; // more than one wildcard not allowed
                }
                wildcardUsed = true;
                count++; // empty counts as a step toward the line
            } else { // CROSS
                count++;
            }

            x += dx;
            y += dy;
        }
        return count;
    }

    /** Guard against out‑of‑range indices. */
    private static boolean isInBounds(int x, int y) {
        return x >= 0 && y >= 0 && x < BOARD_SIZE && y < BOARD_SIZE;
    }
}

import java.io.*;
import java.util.*;

public class B425 {
    /** Board size (10 × 10) */
    private static final int N = 10;
    /** Length of the segment we are looking for */
    private static final int L = 5;
    /** The game board */
    private static char[][] board = new char[N][];
    /** Fast output stream */
    private static PrintWriter out;

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        out = new FastPrinter(System.out);

        // ----- read the board -------------------------------------------------
        for (int i = 0; i < N; i++) {
            board[i] = fs.next().toCharArray();
        }

        boolean found = false;

        // ----- check all possible length‑L segments ---------------------------
        // horizontal
        for (int r = 0; r < N && !found; r++) {
            for (int c = 0; c <= N - L; c++) {
                if (checkSegment(r, c, 0, 1)) {found = true; break;}
            }
        }

        // vertical
        if (!found) {
            for (int r = 0; r <= N - L; r++) {
                for (int c = 0; c < N; c++) {
                    if (checkSegment(r, c, 1, 0)) {found = true; break;}
                }
                if (found) break;
            }
        }

        // diagonal down‑right
        if (!found) {
            for (int r = 0; r <= N - L; r++) {
                for (int c = 0; c <= N - L; c++) {
                    if (checkSegment(r, c, 1, 1)) {found = true; break;}
                }
                if (found) break;
            }
        }

        // diagonal up‑right
        if (!found) {
            for (int r = L - 1; r < N; r++) {
                for (int c = 0; c <= N - L; c++) {
                    if (checkSegment(r, c, -1, 1)) {found = true; break;}
                }
                if (found) break;
            }
        }

        // ----- output result --------------------------------------------------
        out.println(found ? "YES" : "NO");
        out.close();
    }

    /** Checks a length‑L segment that starts at (r,c) and proceeds (dr,dc). */
    private static boolean checkSegment(int r, int c, int dr, int dc) {
        int empty = 0;
        for (int i = 0; i < L; i++) {
            char ch = board[r + i * dr][c + i * dc];
            if (ch == 'O') return false;          // forbidden cell
            if (ch == '.') empty++;               // count empty spots
        }
        return empty == 1;                         // exactly one empty spot
    }

    // -----------------------------------------------------------------
    /** Fast input scanner */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
    }

    /** Fast printer that also knows how to close the underlying stream */
    private static class FastPrinter extends PrintWriter {
        FastPrinter(OutputStream out) {
            super(out);
        }

        static void close() {
            out.flush();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* ---------- Constants ---------- */
    private static final int BOARD_SIZE = 10;
    private static final char EMPTY = '.';
    private static final char BLOCK = 'X';

    // 8 directions – pairs of opposite directions are processed together
    private static final int[] DX = {1, -1, 0, 0, 1, -1, -1, 1};
    private static final int[] DY = {0, 0, -1, 1, -1, 1, -1, 1};

    /* ---------- Entry point ---------- */
    public static void main(String[] args) throws IOException {
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            new Main().solve(scanner, out);
        }
    }

    /* ---------- Core logic ---------- */
    private void solve(FastScanner in, PrintWriter out) {
        char[][] board = readBoard(in);
        out.println(hasWinningSequence(board) ? "YES" : "NO");
    }

    private char[][] readBoard(FastScanner in) {
        char[][] board = new char[BOARD_SIZE][];
        for (int row = 0; row < BOARD_SIZE; row++) {
            board[row] = in.next().toCharArray();
        }
        return board;
    }

    /** Returns true if placing a block on an empty cell would create a line
     *  of at least five consecutive blocks in any of the considered directions. */
    private boolean hasWinningSequence(char[][] board) {
        for (int x = 0; x < BOARD_SIZE; x++) {
            for (int y = 0; y < BOARD_SIZE; y++) {
                if (board[x][y] != EMPTY) {
                    continue;
                }
                if (checkPotentialWin(board, x, y)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Checks all direction pairs originating from (x, y). */
    private boolean checkPotentialWin(char[][] board, int startX, int startY) {
        for (int dirIdx = 0; dirIdx < DX.length; dirIdx += 2) {
            int[] consecutive = {0, 0};

            // count blocks in each direction of the current pair
            for (int side = 0; side < 2; side++) {
                consecutive[side] = countInDirection(board, startX, startY,
                        DX[dirIdx + side], DY[dirIdx + side]);
                if (consecutive[side] >= 5) {
                    return true; // already long enough in one direction
                }
            }

            // need at least one block on each side plus the current cell
            if (consecutive[0] + consecutive[1] + 1 >= 5) {
                return true;
            }
        }
        return false;
    }

    /** Counts consecutive BLOCK cells starting from (x, y) moving by (dx, dy). */
    private int countInDirection(char[][] board, int x, int y, int dx, int dy) {
        int steps = 0;
        for (int c = 1; c < 5; c++) {          // look ahead at most 4 steps
            int nx = x + c * dx;
            int ny = y + c * dy;
            if (!inBounds(nx, ny) || board[nx][ny] != BLOCK) {
                break;
            }
            steps++;
        }
        return steps;
    }

    /** Simple bounds check for the fixed BOARD_SIZE. */
    private boolean inBounds(int x, int y) {
        return x >= 0 && y >= 0 && x < BOARD_SIZE && y < BOARD_SIZE;
    }

    /* ---------- Fast input reader ---------- */
    /** Minimal fast scanner that works with BufferedReader. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Detects whether a 10×10 board contains a line of five consecutive 'X' characters
 * (horizontally, vertically or diagonally). The line may contain a single '.' which
 * represents a missing cell – the original logic looked for substrings such as
 * ".XXXX", "X.XXX", "XX.XX", "XXX.X" or "XXXX.".
 *
 * <p>The refactor improves readability, separates concerns, avoids static mutable
 * fields and uses clear control‑flow constructs.</p>
 */
public class FiveInRow {

    /** Size of the board (10 × 10). */
    private static final int BOARD_SIZE = 10;

    /** Character that denotes an empty cell. */
    private static final char EMPTY = '.';

    /** Character that denotes a player's piece. */
    private static final char PLAYER = 'X';

    public static void main(String[] args) throws IOException {
        List<String> board = readBoardFromStdin();
        System.out.println(hasWinningLine(board) ? "YES" : "NO");
    }

    /** Reads exactly {@value #BOARD_SIZE} lines from standard input. */
    private static List<String> readBoardFromStdin() throws IOException {
        List<String> board = new ArrayList<>(BOARD_SIZE);
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line;
            while (board.size() < BOARD_SIZE && (line = br.readLine()) != null) {
                board.add(line.trim());
            }
        }
        return board;
    }

    /** Returns true if any horizontal, vertical or diagonal line contains five
     *  consecutive player pieces (allowing a single '.' placeholder). */
    private static boolean hasWinningLine(List<String> board) {
        // Horizontal scan
        for (String row : board) {
            if (containsFiveInARow(row)) {
                return true;
            }
        }

        // Vertical scan
        if (hasVerticalFive(board)) {
            return true;
        }

        // Diagonal scans
        if (hasDiagonalFive(board, Direction.UPWARD)) {
            return true;
        }
        if (hasDiagonalFive(board, Direction.DOWNWARD)) {
            return true;
        }

        return false;
    }

    /** Checks all columns for a vertical line of five. */
    private static boolean hasVerticalFive(List<String> board) {
        for (int col = 0; col < BOARD_SIZE; col++) {
            StringBuilder column = new StringBuilder(BOARD_SIZE);
            for (int row = 0; row < BOARD_SIZE; row++) {
                column.append(board.get(row).charAt(col));
            }
            if (containsFiveInARow(column.toString())) {
                return true;
            }
        }
        return false;
    }

    /** Checks diagonal lines in the given direction for a winning pattern. */
    private static boolean hasDiagonalFive(List<String> board, Direction dir) {
        switch (dir) {
            case UPWARD:
                return scanUpwardDiagonals(board);
            case DOWNWARD:
                return scanDownwardDiagonals(board);
        }
        return false; // unreachable
    }

    /** Scans "\" (upward) diagonals for the winning pattern. */
    private static boolean scanUpwardDiagonals(List<String> board) {
        // Diagonals starting from the left and top edges
        for (int start = 0; start < BOARD_SIZE; start++) {
            StringBuilder line = buildUpwardDiagonal(board, start);
            if (containsFiveInARow(line.toString())) {
                return true;
            }
        }
        // Diagonals starting from the bottom edge and moving upward
        for (int start = BOARD_SIZE - 1; start >= 0; start--) {
            StringBuilder line = buildUpwardDiagonalFromBottom(board, start);
            if (containsFiveInARow(line.toString())) {
                return true;
            }
        }
        return false;
    }

    /** Scans "/" (downward) diagonals for the winning pattern. */
    private static boolean scanDownwardDiagonals(List<String> board) {
        // Diagonals starting from the right edge and moving down‑left
        for (int start = 0; start < BOARD_SIZE; start++) {
            StringBuilder line = buildDownwardDiagonalFromRight(board, start);
            if (containsFiveInARow(line.toString())) {
                return true;
            }
        }
        // Diagonals starting from the upper edge and moving up‑right
        for (int start = 0; start < BOARD_SIZE; start++) {
            StringBuilder line = buildDownwardDiagonalFromTop(board, start);
            if (containsFiveInARow(line.toString())) {
                return true;
            }
        }
        return false;
    }

    /** Helper that builds a "\" diagonal starting from a given index on the left/top side. */
    private static StringBuilder buildUpwardDiagonal(List<String> board, int startCol) {
        StringBuilder sb = new StringBuilder(BOARD_SIZE);
        int row = startCol;
        int col = 0;
        while (row < BOARD_SIZE && col < BOARD_SIZE) {
            sb.append(board.get(row++).charAt(col++));
        }
        return sb;
    }

    /** Helper that builds a "\" diagonal that starts from the bottom edge. */
    private static StringBuilder buildUpwardDiagonalFromBottom(List<String> board, int startRow) {
        StringBuilder sb = new StringBuilder(BOARD_SIZE);
        int row = startRow;
        int col = 0;
        while (row < BOARD_SIZE && col < BOARD_SIZE) {
            sb.append(board.get(row++).charAt(col++));
        }
        return sb;
    }

    /** Helper that builds a "/" diagonal starting from a column on the top edge. */
    private static StringBuilder buildDownwardDiagonalFromTop(List<String> board, int startCol) {
        StringBuilder sb = new StringBuilder(BOARD_SIZE);
        int row = 0;
        int col = startCol;
        while (row < BOARD_SIZE && col < BOARD_SIZE) {
            sb.append(board.get(row++).charAt(col++));
        }
        return sb;
    }

    /** Helper that builds a "/" diagonal starting from a row on the right edge. */
    private static StringBuilder buildDownwardDiagonalFromRight(List<String> board, int startRow) {
        StringBuilder sb = new StringBuilder(BOARD_SIZE);
        int row = startRow;
        int col = 0;
        while (row < BOARD_SIZE && col < BOARD_SIZE) {
            sb.append(board.get(row++).charAt(col++));
        }
        return sb;
    }

    /** Checks whether a given line contains a substring that represents five
     *  player pieces possibly interrupted by a single empty cell.
     *
     *  <p>The original implementation matched the exact substrings
     *  ".XXXX", "X.XXX", "XX.XX", "XXX.X", or "XXXX.".</p> */
    private static boolean containsFiveInARow(String line) {
        return line.contains(".XXXX")
                || line.contains("X.XXX")
                || line.contains("XX.XX")
                || line.contains("XXX.X")
                || line.contains("XXXX.");
    }

    /** Simple direction enum to distinguish between the two diagonal families. */
    private enum Direction {
        UPWARD, DOWNWARD
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point of the application.
 *
 * The program reads a 10×N board from standard input (each row is given as a single token),
 * tries to place a single 'X' into an empty cell ('.') and checks whether this placement
 * creates a line of at least five consecutive 'X' characters in any of the eight directions.
 * The result ("YES" or "NO") is printed to standard output.
 */
public class Main {

    /** Program entry point. */
    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee that the output writer is closed.
        try (OutputWriter out = new OutputWriter(System.out)) {
            InputReader in = new InputReader(System.in);
            new GameSolver().solve(in, out);
        }
    }

    /**
     * Solves a single test case.
     *
     * @param in  input reader that supplies the board data
     * @param out output writer that receives the answer
     */
    static class GameSolver {

        /** Character that marks a "good" cell. */
        private static final char MARK = 'X';

        /** Entry point for the solving process. */
        public void solve(InputReader in, OutputWriter out) {
            char[][] board = readBoard(in);
            boolean canCreateFive = canCreateFiveInARow(board);
            out.printLine(canCreateFive ? "YES" : "NO");
        }

        /** Reads the 10 rows of the board from the input. */
        private char[][] readBoard(InputReader in) {
            char[][] board = new char[10][];
            for (int i = 0; i < board.length; i++) {
                board[i] = in.next().toCharArray();
            }
            return board;
        }

        /** Determines whether a placement of MARK can yield a line of five or more MARKs. */
        private boolean canCreateFiveInARow(char[][] board) {
            final int rows = board.length;
            final int cols = board[0].length;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (board[r][c] == '.') {
                        board[r][c] = MARK;
                        if (hasFiveInARow(board, r, c)) {
                            board[r][c] = '.';
                            return true;
                        }
                        board[r][c] = '.';
                    }
                }
            }
            return false;
        }

        /** Checks the eight directions from (startRow, startCol) for a line of five or more MARKs. */
        private boolean hasFiveInARow(char[][] board, int startRow, int startCol) {
            for (int dir = 0; dir < 8; dir++) {
                if (countConsecutive(board, startRow, startCol, dir) >= 5) {
                    return true;
                }
            }
            return false;
        }

        /** Counts how many consecutive MARK cells are present starting from (row, col) moving in direction dir. */
        private int countConsecutive(char[][] board, int row, int col, int dir) {
            int dr = DX8[dir];
            int dc = DY8[dir];
            int length = 0;

            while (isInside(board, row, col) && board[row][col] == MARK) {
                length++;
                row += dr;
                col += dc;
            }
            return length;
        }

        /** Returns true if the supplied coordinates are inside the board limits. */
        private boolean isInside(char[][] board, int r, int c) {
            return r >= 0 && r < board.length && c >= 0 && c < board[0].length;
        }

        /** Direction vectors for the eight possible directions. */
        private static final int[] DX8 = {1, 1, 1, 0, -1, -1, -1, 0};
        private static final int[] DY8 = {-1, 0, 1, 1, 1, 0, -1, -1};
    }

    /**
     * Fast buffered input reader.
     *
     * Reads tokens consisting of non‑whitespace characters from the underlying {@link InputStream}.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int length = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte from the underlying stream, filling the buffer when necessary. */
        private int readByte() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        /**
         * Returns the next token (a maximal sequence of non‑whitespace characters).
         *
         * @throws IOException if an I/O error occurs
         */
        String next() throws IOException {
            skipWhite();
            StringBuilder sb = new StringBuilder();
            int b;
            while (!isSpaceChar(b = readByte())) {
                sb.append((char) b);
            }
            return sb.toString();
        }

        /** Skips all leading whitespace characters. */
        private void skipWhite() throws IOException {
            int c;
            do {
                c = readByte();
            } while (isSpaceChar(c));
            pointer--; // step back to the first non‑space character
        }

        /** Checks whether a character code represents whitespace. */
        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /**
     * Simple wrapper around {@link PrintWriter} that supports printing multiple objects
     * on a single line separated by spaces.
     *
     * The class implements {@link Closeable} so that it can be used in a try‑with‑resources
     * statement.
     */
    static class OutputWriter implements Closeable {
        private final PrintWriter writer;

        OutputWriter(OutputStream out) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        /** Prints the provided objects separated by a single space, without a line break. */
        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        /** Prints the provided objects followed by a line break. */
        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        @Override
        public void close() {
            writer.close();
        }
    }
}

import java.util.Scanner;

/**
 * Detects whether a 10×10 board contains five identical pieces in a row,
 * column, or diagonal. The detection logic mirrors the original implementation
 * (a magic ASCII‑sum check) while improving readability, constants, and structure.
 */
public class FiveInARow {

    /** Board dimension – kept as a constant for easier changes. */
    private static final int BOARD_SIZE = 10;

    /** Length of the sequence that constitutes a win. */
    private static final int WIN_LENGTH = 5;

    /** Magic sum used by the original code to recognise a winning quintet. */
    private static final int WIN_SUM = 398;

    public static void main(String[] args) {
        /* Try‑with‑resources guarantees the scanner is closed promptly. */
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

            /* Read exactly BOARD_SIZE lines from standard input. */
            for (int i = 0; i < BOARD_SIZE; i++) {
                board[i] = scanner.nextLine().toCharArray();
            }

            System.out.println(hasFiveInARow(board) ? "YES" : "NO");
        }
    }

    /**
     * Checks the board for any occurrence of five equal pieces in a line.
     *
     * @param board the game board
     * @return true if a win exists, false otherwise
     */
    private static boolean hasFiveInARow(char[][] board) {
        /* ---- Horizontal scan ------------------------------------------------ */
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col <= BOARD_SIZE - WIN_LENGTH; col++) {
                if (isWinningQuintet(board[row][col], board[row][col + 1],
                                     board[row][col + 2], board[row][col + 3],
                                     board[row][col + 4])) {
                    return true;
                }
            }
        }

        /* ---- Vertical scan --------------------------------------------------- */
        for (int row = 0; row <= BOARD_SIZE - WIN_LENGTH; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                if (isWinningQuintet(board[row][col], board[row + 1][col],
                                     board[row + 2][col], board[row + 3][col],
                                     board[row + 4][col])) {
                    return true;
                }
            }
        }

        /* ---- Main diagonal (top‑left → bottom‑right) -------------------------- */
        for (int row = 0; row <= BOARD_SIZE - WIN_LENGTH; row++) {
            for (int col = 0; col <= BOARD_SIZE - WIN_LENGTH; col++) {
                if (isWinningQuintet(board[row][col], board[row + 1][col + 1],
                                     board[row + 2][col + 2], board[row + 3][col + 3],
                                     board[row + 4][col + 4])) {
                    return true;
                }
            }
        }

        /* ---- Anti diagonal (bottom‑left → top‑right) -------------------------- */
        for (int row = 0; row <= BOARD_SIZE - WIN_LENGTH; row++) {
            for (int col = WIN_LENGTH - 1; col < BOARD_SIZE; col++) {
                if (isWinningQuintet(board[row][col], board[row + 1][col - 1],
                                     board[row + 2][col - 2], board[row + 3][col - 3],
                                     board[row + 4][col - 4])) {
                    return true;
                }
            }
        }

        /* No winning pattern found. */
        return false;
    }

    /**
     * Determines whether the five supplied characters constitute a winning
     * quintet according to the original magic‑sum rule.
     *
     * @param cells five characters to examine
     * @return true if their ASCII‑code sum equals {@value WIN_SUM}
     */
    private static boolean isWinningQuintet(char... cells) {
        int sum = 0;
        for (char c : cells) {
            sum += c;
        }
        return sum == WIN_SUM;
    }
}

import java.util.*;

public class tr0 {
    private static final int GRID_SIZE = 10;
    private static final int REQUIRED_LENGTH = 5;

    private static int countInDirection(char[][] grid, int i, int j, int di, int dj) {
        int count = 0;
        while (i >= 0 && i < GRID_SIZE && j >= 0 && j < GRID_SIZE) {
            if (grid[i][j] != 'X') {
                break;
            }
            count++;
            i += di;
            j += dj;
        }
        return count;
    }

    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            grid[i] = sc.nextLine().toCharArray();
        }

        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                if (grid[i][j] != '.') {
                    continue;
                }
                for (int[] direction : DIRECTIONS) {
                    int count = 1;
                    count += countInDirection(grid, i + direction[0], j + direction[1], direction[0], direction[1]);
                    count += countInDirection(grid, i - direction[0], j - direction[1], -direction[0], -direction[1]);
                    if (count >= REQUIRED_LENGTH) {
                        System.out.println("YES");
                        return;
                    }
                }
            }
        }
        System.out.println("NO");
    }

    private static final int[][] DIRECTIONS = {
        {1, 0},   // down
        {0, 1},   // right
        {1, 1},   // down-right
        {1, -1}   // down-left
    };

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;

        public Scanner(InputStream system) {
            br = new BufferedReader(new InputStreamReader(system));
        }

        public Scanner(String file) throws Exception {
            br = new BufferedReader(new FileReader(file));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        public char nextChar() throws IOException {
            return next().charAt(0);
        }

        public Long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public int[] nextArrInt(int n) throws IOException {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        public long[] nextArrLong(int n) throws IOException {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }

        public boolean ready() throws IOException {
            return br.ready();
        }

        public void waitForInput() throws InterruptedException {
            Thread.sleep(3000);
        }
    }
}

