        for (int r = 0; r < SIZE; ++r) {
            String line = scanner.nextLine();
            for (int c = 0; c < SIZE; ++c) {
                board[r][c] = line.charAt(c);
            }
        }
        return board;
    }

    /** Determines whether placing an 'X' in any '.' cell yields a winning line. */
    private static boolean canWinByAddingX(char[][] board) {
        for (int r = 0; r < SIZE; ++r) {
            for (int c = 0; c < SIZE; ++c) {
                if (board[r][c] == '.') {
                    board[r][c] = 'X';
                    boolean win = hasFiveInLine(board);
                    board[r][c] = '.';
                    if (win) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Checks all possible lines (row, column, two diagonal directions) for five 'X's. */
    private static boolean hasFiveInLine(char[][] board) {
        // Horizontal lines
        for (char[] row : board) {
            if (match(lineFromArray(row))) {
                return true;
            }
        }

        // Vertical lines
        for (int col = 0; col < SIZE; ++col) {
            if (match(buildStringFromColumn(board, col))) {
                return true;
            }
        }

        // Main diagonals (top‑left → bottom‑right)
        for (int startRow = 0; startRow <= SIZE - 5; ++startRow) {
            for (int startCol = 0; startCol <= SIZE - 5; ++startCol) {
                if (match(diagonalFrom(board, startRow, startCol))) {
                    return true;
                }
            }
        }

        // Anti‑diagonals (top‑right → bottom‑left)
        for (int startRow = 0; startRow <= SIZE - 5; ++startRow) {
            for (int startCol = SIZE - 6; startCol < SIZE; ++startCol) {
                if (match(antiDiagonalFrom(board, startRow, startCol))) {
                    return true;
                }
            }
        }

        return false;
    }

    /** Converts a character array into a String. */
    private static String lineFromArray(char[] arr) {
        return new String(arr);
    }

    /** Builds a string from a specific column. */
    private static String buildStringFromColumn(char[][] board, int col) {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < SIZE; ++r) {
            sb.append(board[r][col]);
        }
        return sb.toString();
    }

    /** Builds a string for a diagonal starting at (row, col) moving down‑right. */
    private static String diagonalFrom(char[][] board, int startRow, int startCol) {
        StringBuilder sb = new StringBuilder();
        int r = startRow, c = startCol;
        while (r < SIZE && c < SIZE) {
            sb.append(board[r][c]);
            ++r;
            ++c;
        }
        return sb.toString();
    }

    /** Builds a string for an anti‑diagonal starting at (row, col) moving down‑left. */
    private static String antiDiagonalFrom(char[][] board, int startRow, int startCol) {
        StringBuilder sb = new StringBuilder();
        int r = startRow, c = startCol;
        while (r < SIZE && c >= 0) {
            sb.append(board[r][c]);
            ++r;
            --c;
        }
        return sb.toString();
    }

    /** Returns true if the supplied text matches the winning pattern. */
    private static boolean match(String candidate) {
        return WIN_PATTERN.matcher(candidate).matches();
    }
}

import java.io.*;
import java.util.*;

public class B {

    /** Board size (10×10) */
    private static final int SIZE = 10;

    /** Length of the examined straight line */
    private static final int LINE_LENGTH = 5;

    /** Required number of 'X' and '.' in a winning line */
    private static final int REQUIRED_X = 4;
    private static final int REQUIRED_DOT = 1;

    private Scanner scanner;
    private PrintWriter out;

    /** Returns true if the given 5‑character slice contains the winning pattern. */
    private boolean isWinningSlice(char[] slice) {
        int x = 0, dot = 0;
        for (char ch : slice) {
            if (ch == 'X') x++;
            else if (ch == '.') dot++;
        }
        return x == REQUIRED_X && dot == REQUIRED_DOT;
    }

    /** Checks all possible 5‑cell straight lines for the winning pattern. */
    private boolean hasWinningPattern(char[][] board) {
        // Four directions: right, down‑right, down, down‑left
        final int[][] DIRECTIONS = {
                {0, 1},   // horizontal (right)
                {1, 1},   // diagonal down‑right
                {1, 0},   // vertical (down)
                {1, -1}   // diagonal down‑left
        };

        for (int r = 0; r < SIZE; r++) {
            for (int c = 0; c < SIZE; c++) {
                for (int[] d : DIRECTIONS) {
                    int dr = d[0];
                    int dc = d[1];

                    // Verify that we can place 5 cells forward without leaving the board
                    int endR = r + (LINE_LENGTH - 1) * dr;
                    int endC = c + (LINE_LENGTH - 1) * dc;
                    if (endR < 0 || endR >= SIZE) continue;
                    if (dc > 0) {
                        if (endC >= SIZE) continue;
                    } else {
                        if (endC < 0) continue;
                    }

                    // Build the slice and count symbols
                    int x = 0, dot = 0;
                    for (int step = 0; step < LINE_LENGTH; step++) {
                        int nr = r + step * dr;
                        int nc = c + step * dc;
                        char ch = board[nr][nc];
                        if (ch == 'X') x++;
                        else if (ch == '.') dot++;
                        if (x > REQUIRED_X || dot > REQUIRED_DOT) break; // early exit
                    }
                    if (x == REQUIRED_X && dot == REQUIRED_DOT) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private void solve() throws Exception {
        char[][] board = new char[SIZE][];
        for (int i = 0; i < SIZE; i++) {
            String line = scanner.next();
            board[i] = line.toCharArray();
        }

        out.println(hasWinningPattern(board) ? "YES" : "NO");
    }

    private void init() throws Exception {
        scanner = new Scanner(System.in);
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }

    public static void main(String[] args) throws Exception {
        new B().init();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Detects whether a 10×10 board contains a line of exactly five cells that
 * consist of four 'X' marks and a single empty cell ('.').
 *
 * The algorithm scans the board in the four main directions (horizontal,
 * vertical, and the two diagonals). For each direction a sliding window of
 * length five is examined; if the window contains exactly four 'X' and one
 * '.', the function reports a win.
 *
 * The program reads the board from standard input and prints "YES" if such
 * a configuration exists, otherwise "NO".
 */
public class Solution {

    /** Board size (fixed at 10×10 for this problem). */
    private static final int SIZE = 10;

    /** Character representing an empty cell. */
    private static final char EMPTY = '.';

    /** Character representing a mark. */
    private static final char MARK = 'X';

    /** Direction vectors: right, down, down‑right, down‑left. */
    private static final int[][] DIRECTIONS = {
            {0, 1},   // horizontal (right)
            {1, 0},   // vertical   (down)
            {1, 1},   // diagonal down‑right
            {1, -1}   // diagonal down‑left
    };

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees the reader is closed promptly.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = readBoard(br);
            boolean win = hasWinningPattern(board);
            System.out.println(win ? "YES" : "NO");
        }
    }

    /** Reads exactly {@code SIZE} lines from the supplied reader to build the board. */
    private static char[][] readBoard(BufferedReader br) throws IOException {
        char[][] board = new char[SIZE][SIZE];
        for (int row = 0; row < SIZE; row++) {
            String line = br.readLine();
            if (line == null || line.isEmpty()) {
                throw new IOException("Not enough lines to fill the board.");
            }
            board[row] = line.toCharArray();
        }
        return board;
    }

    /** Determines whether any of the four directions contains the required pattern. */
    private static boolean hasWinningPattern(char[][] board) {
        for (int[] dir : DIRECTIONS) {
            int dx = dir[0];
            int dy = dir[1];

            // Slide a window of length five across the board.
            for (int x = 0; x < SIZE; x++) {
                for (int y = 0; y < SIZE; y++) {
                    int endX = x + dx * 4;
                    int endY = y + dy * 4;

                    // Skip positions where the window would go out of bounds.
                    if (endX >= SIZE || endY < 0 || endY >= SIZE) {
                        continue;
                    }

                    if (containsFourMarksAndOneEmpty(board, x, y, dx, dy)) {
                        return true; // Found a valid configuration.
                    }
                }
            }
        }
        return false; // No valid configuration found.
    }

    /**
     * Checks a line of five cells starting at (startX,startY) moving by (dx,dy).
     *
     * @return {@code true} if the line contains exactly four 'X' and one '.'.
     */
    private static boolean containsFourMarksAndOneEmpty(char[][] board,
                                                          int startX, int startY,
                                                          int dx, int dy) {
        int marks = 0;
        int empties = 0;

        for (int step = 0; step < 5; step++) {
            char cell = board[startX + dx * step][startY + dy * step];
            if (cell == MARK) {
                marks++;
            } else if (cell == EMPTY) {
                empties++;
            } else {
                // Any unexpected character invalidates the pattern.
                return false;
            }
        }
        return marks == 4 && empties == 1;
    }
}

import java.util.List;
import java.util.Scanner;

/**
 * Detects whether a 10×10 grid contains a line of at least four
 * adjacent 'X' characters in any of the eight directions when
 * evaluated from an empty cell ('.').
 *
 * <p>The program reads exactly ten lines from standard input,
 * each line being a string of length 10 consisting of 'X' or '.'.
 * If a qualifying line is found it prints {@code YES}, otherwise
 * {@code NO}.</p>
 */
public class Binaryprotocol {

    /** Size of the square grid (10 × 10). */
    private static final int SIZE = 10;

    /** Directions in which we search for consecutive 'X's.
     *  Each pair (dx, dy) represents a step from the current cell.
     */
    private enum Direction {
        LEFT(0, -1),
        RIGHT(0, 1),
        UP(-1, 0),
        DOWN(1, 0),
        LEFT_UP(-1, -1),
        RIGHT_DOWN(1, 1),
        LEFT_DOWN(1, -1),
        RIGHT_UP(-1, 1);

        final int dx;
        final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            List<String> rows = readMatrix(scanner);
            if (hasFourAdjacentX(rows)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Reads exactly {@code SIZE} lines from the scanner and returns them
     *  as an immutable list of strings. */
    private static List<String> readMatrix(Scanner scanner) {
        List<String> matrix = new java.util.ArrayList<>(SIZE);
        for (int i = 0; i < SIZE; i++) {
            String line = scanner.next();
            if (line.length() != SIZE) {
                throw new IllegalArgumentException(
                        "Each line must contain exactly " + SIZE + " characters");
            }
            matrix.add(line);
        }
        return java.util.Collections.unmodifiableList(matrix);
    }

    /**
     * Determines whether any empty cell ('.') has, in at least one
     * opposite‑pair of directions, a total of four or more consecutive
     * 'X' characters.
     *
     * @return {@code true} if such a configuration exists; otherwise {@code false}
     */
    private static boolean hasFourAdjacentX(List<String> matrix) {
        for (int x = 0; x < SIZE; x++) {
            String row = matrix.get(x);
            for (int y = 0; y < SIZE; y++) {
                if (!row.charAt(y) == '.') {
                    continue; // only empty cells are considered
                }
                // Check each opposite‑pair of directions
                if (countInDirection(matrix, x, y, Direction.LEFT) +
                        countInDirection(matrix, x, y, Direction.RIGHT) >= 4) {
                    return true;
                }
                if (countInDirection(matrix, x, y, Direction.UP) +
                        countInDirection(matrix, x, y, Direction.DOWN) >= 4) {
                    return true;
                }
                if (countInDirection(matrix, x, y, Direction.LEFT_UP) +
                        countInDirection(matrix, x, y, Direction.RIGHT_DOWN) >= 4) {
                    return true;
                }
                if (countInDirection(matrix, x, y, Direction.RIGHT_UP) +
                        countInDirection(matrix, x, y, Direction.LEFT_DOWN) >= 4) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Counts how many consecutive 'X' characters are found starting from
     * the cell (x, y) and moving step‑by‑step according to the supplied
     * {@link Direction}.
     *
     * @param matrix   the immutable grid of strings
     * @param x        starting row index
     * @param y        starting column index
     * @param dir      movement direction
     * @return number of adjacent 'X' cells reached before hitting a non‑'X'
     *         or the matrix border
     */
    private static int countInDirection(List<String> matrix, int x, int y, Direction dir) {
        int count = 0;
        int curX = x;
        int curY = y;
        curX += dir.dx;
        curY += dir.dy;
        while (insideBounds(curX, curY) &&
                matrix.get(curX).charAt(curY) == 'X') {
            count++;
            curX += dir.dx;
            curY += dir.dy;
        }
        return count;
    }

    /** Helper that checks whether a given coordinate lies inside the 10×10 grid. */
    private static boolean insideBounds(int x, int y) {
        return x >= 0 && x < SIZE && y >= 0 && y < SIZE;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Scanner;

/**
 * Reads a 10x10 grid where each cell contains either 'X' or '.'.
 * Determines whether any '.' cell is part of a line of at least four 'X' cells.
 * Lines may be horizontal, vertical, or on either diagonal.
 * Prints {@code YES} if such a line exists, otherwise {@code NO}.
 */
public final class TicTacToeDetector {

    private static final int GRID_SIZE = 10;
    private static final char EMPTY = '.';
    private static final char PIECE = 'X';

    private TicTacToeDetector() {
        // Utility class – prevent instantiation.
    }

    public static void main(String[] args) {
        String[] grid = readGrid();
        boolean found = hasWinningLine(grid);
        System.out.println(found ? "YES" : "NO");
    }

    /**
     * Reads exactly 10 lines from standard input, each representing a row
     * of the grid. Whitespace is preserved.
     *
     * @return array of 10 strings, each length {@code GRID_SIZE}
     * @throws IllegalArgumentException if fewer than 10 lines are provided
     */
    private static String[] readGrid() {
        String[] grid = new String[GRID_SIZE];
        Scanner scanner = new Scanner(System.in);
        for (int row = 0; row < GRID_SIZE; row++) {
            if (!scanner.hasNextLine()) {
                throw new IllegalArgumentException("Expected 10 input lines.");
            }
            grid[row] = scanner.nextLine();
        }
        if (scanner.hasNext()) {
            // Ignore any trailing input.
            scanner.nextLine();
        }
        return grid;
    }

    /**
     * Checks whether any empty cell ('.') participates in a line of at least
     * four consecutive pieces ('X') in any of the eight directions.
     *
     * @param grid the 10x10 character grid
     * @return true if a winning configuration exists
     */
    private static boolean hasWinningLine(String[] grid) {
        for (int row = 0; row < GRID_SIZE; row++) {
            String line = grid[row];
            for (int col = 0; col < GRID_SIZE; col++) {
                if (line.charAt(col) == EMPTY) {
                    if (countNeighbours(grid, row, col) >= 4) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Counts consecutive {@code PIECE} characters adjacent to the cell at
     * {@code (row, col)} in all eight directions.
     * The count stops when a non‑piece or grid boundary is reached.
     *
     * @param grid     the game board
     * @param row      row index of the current cell
     * @param col      column index of the current cell
     * @return the total number of adjacent pieces in any direction
     */
    private static int countNeighbours(String[] grid, int row, int col) {
        int left = countDirection(grid, row, col, 0, -1);
        int right = countDirection(grid, row, col, 0, 1);
        int up = countDirection(grid, row, col, -1, 0);
        int down = countDirection(grid, row, col, 1, 0);
        int upLeft = countDirection(grid, row, col, -1, -1);
        int downRight = countDirection(grid, row, col, 1, 1);
        int upRight = countDirection(grid, row, col, -1, 1);
        int downLeft = countDirection(grid, row, col, 1, -1);

        // Any pair of opposite directions creates a possible line.
        return Math.max(left + right,
                        Math.max(up + down,
                                 Math.max(upLeft + downRight,
                                          downLeft + upRight)));
    }

    /**
     * Counts consecutive {@code PIECE} characters starting from the cell
     * {@code (row, col)} and moving {@code dr} rows and {@code dc} columns.
     * Stops at the first non‑piece or out‑of‑bounds cell.
     *
     * @param grid     the board representation
     * @param row      starting row
     * @param col      starting column
     * @param dr       row offset for the direction (+1 / -1 / 0)
     * @param dc       column offset for the direction (+1 / -1 / 0)
     * @return number of consecutive pieces in that direction
     */
    private static int countDirection(String[] grid, int row, int col, int dr, int dc) {
        int count = 0;
        int currentRow = row + dr;
        int currentCol = col + dc;
        while (currentRow >= 0 && currentRow < GRID_SIZE &&
               currentCol >= 0 && currentCol < GRID_SIZE) {
            if (grid[currentRow].charAt(currentCol) == PIECE) {
                count++;
                currentRow += dr;
                currentCol += dc;
            } else {
                break;
            }
        }
        return count;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.Scanner;

/**
 * Determines whether a given N × M matrix of characters ('R', 'G', 'B')
 * consists exclusively of wide horizontal or vertical stripes of equal size.
 *
 * <p>The logic follows the original implementation but is now split into
 * small, well‑named methods, uses modern Java constructs and eliminates
 * duplicated code.</p>
 */
public class Test {

    /** Character that represents a stripe colour. */
    private enum Colour { R, G, B }

    /** Entry point of the program. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] matrix = readMatrix(scanner, rows, cols);

            if (isHorizontalStriped(matrix) || isVerticalStriped(matrix)) {
                System.out.println("YES");
                return;
            }
            System.out.println("NO");
        }
    }

    /** Reads N rows of length M from the scanner. */
    private static char[][] readMatrix(Scanner scanner, int rows, int cols) {
        char[][] matrix = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = line.charAt(j);
            }
        }
        return matrix;
    }

    /** Checks whether the matrix consists of horizontal colour stripes. */
    private static boolean isHorizontalStriped(char[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        List<Integer> redRows   = new ArrayList<>();
        List<Integer> greenRows = new ArrayList<>();
        List<Integer> blueRows  = new ArrayList<>();

        int processedRows = 0;
        while (processedRows < rows) {
            Colour colour = identifyStripeColour(matrix, processedRows, cols);
            if (colour == null) {
                return false; // unexpected colour
            }

            int stripeLength = getStripeLength(matrix, processedRows, colour);
            if (stripeLength != cols) { // stripe not full width
                return false;
            }

            // record the row index for later intersection test
            List<Integer> targetList;
            switch (colour) {
                case R -> targetList = redRows;
                case G -> targetList = greenRows;
                case B -> targetList = blueRows;
                default -> throw new IllegalStateException(); // never reached
            }
            targetList.add(processedRows);

            processedRows += stripeLength; // move to next stripe
        }

        // All three colours must be present
        if (redRows.isEmpty() || greenRows.isEmpty() || blueRows.isEmpty()) {
            return false;
        }

        // The three colour intervals must intersect pairwise in the required way
        int redStart   = redRows.get(0);
        int redEnd     = redRows.get(redRows.size() - 1);
        int greenStart = greenRows.get(0);
        int greenEnd   = greenRows.get(greenRows.size() - 1);
        int blueStart  = blueRows.get(0);
        int blueEnd    = blueRows.get(blueRows.size() - 1);

        boolean intersect(int firstStart, int firstEnd, int secondStart) {
            // a < c < b  -> false, otherwise true (mirrors original logic)
            return !(firstStart < secondStart && secondStart < firstEnd);
        }

        boolean coloursIntersectCorrectly = intersect(redStart, redEnd, greenStart)
                && intersect(redStart, redEnd, blueStart)
                && intersect(blueStart, blueEnd, redStart)
                && intersect(blueStart, blueEnd, greenStart)
                && intersect(greenStart, greenEnd, redStart)
                && intersect(greenStart, greenEnd, blueStart);

        return coloursIntersectCorrectly && redRows.size() == greenRows.size()
                && greenRows.size() == blueRows.size();
    }

    /** Checks whether the matrix consists of vertical colour stripes. */
    private static boolean isVerticalStriped(char[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        List<Integer> redCols   = new ArrayList<>();
        List<Integer> greenCols = new ArrayList<>();
        List<Integer> blueCols  = new ArrayList<>();

        int processedColumns = 0;
        while (processedColumns < cols) {
            Colour colour = identifyStripeColourVertical(matrix, processedColumns, rows);
            if (colour == null) {
                return false;
            }

            int stripeLength = getStripeLengthVertical(matrix, processedColumns, colour);
            if (stripeLength != rows) {
                return false;
            }

            List<Integer> targetList;
            switch (colour) {
                case R -> targetList = redCols;
                case G -> targetList = greenCols;
                case B -> targetList = blueCols;
                default -> throw new IllegalStateException();
            }
            targetList.add(processedColumns);

            processedColumns += stripeLength;
        }

        // All three colours must be present
        if (redCols.isEmpty() || greenCols.isEmpty() || blueCols.isEmpty()) {
            return false;
        }

        int redStart   = redCols.get(0);
        int redEnd     = redCols.get(redCols.size() - 1);
        int greenStart = greenCols.get(0);
        int greenEnd   = greenCols.get(greenCols.size() - 1);
        int blueStart  = blueCols.get(0);
        int blueEnd    = blueCols.get(blueCols.size() - 1);

        boolean intersect(int firstStart, int firstEnd, int secondStart) {
            return !(firstStart < secondStart && secondStart < firstEnd);
        }

        boolean coloursIntersectCorrectly = intersect(redStart, redEnd, greenStart)
                && intersect(redStart, redEnd, blueStart)
                && intersect(blueStart, blueEnd, redStart)
                && intersect(blueStart, blueEnd, greenStart)
                && intersect(greenStart, greenEnd, redStart)
                && intersect(greenStart, greenEnd, blueStart);

        return coloursIntersectCorrectly && redCols.size() == greenCols.size()
                && greenCols.size() == blueCols.size();
    }

    /** Determines the colour of a horizontal stripe starting at row `start`. */
    private static Colour identifyStripeColour(char[][] matrix, int row, int cols) {
        char colourChar = matrix[row][0];
        if (colourChar != 'R' && colourChar != 'G' && colourChar != 'B') {
            return null;
        }
        return Colour.valueOf(String.valueOf(colourChar));
    }

    /** Determines the colour of a vertical stripe starting at column `col`. */
    private static Colour identifyStripeColourVertical(char[][] matrix, int col, int rows) {
        char colourChar = matrix[0][col];
        if (colourChar != 'R' && colourChar != 'G' && colourChar != 'B') {
            return null;
        }
        return Colour.valueOf(String.valueOf(colourChar));
    }

    /** Length of a stripe that starts at the given row (horizontal case). */
    private static int getStripeLength(char[][] matrix, int startRow, Colour colour) {
        int length = 1;
        char expected = colour.name().charAt(0);
        for (int r = startRow + 1; r < matrix.length; r++) {
            if (matrix[r][0] == expected) {
                length++;
            } else {
                break;
            }
        }
        return length;
    }

    /** Length of a stripe that starts at the given column (vertical case). */
    private static int getStripeLengthVertical(char[][] matrix, int startCol, Colour colour) {
        int length = 1;
        char expected = colour.name().charAt(0);
        for (int c = startCol + 1; c < matrix[0].length; c++) {
            if (matrix[0][c] == expected) {
                length++;
            } else {
                break;
            }
        }
        return length;
    }
}

import java.io.IOException;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 * The program reads an n × m grid of characters and decides whether the first
 * row (or first column when appropriate) contains an equal number of the
 * three colours 'R', 'G' and 'B'.  The output is either "YES" or "NO".
 *
 * The implementation is deliberately split into small, well‑named methods
 * to improve readability, maintainability and testability.
 */
public final class GridValidator {

    private static final char RED   = 'R';
    private static final char GREEN = 'G';
    private static final char BLUE  = 'B';

    private GridValidator() {
        // utility class – no instances
    }

    public static void main(String[] args) throws IOException {
        // -----------------------------------------------------------------
        // 1. Input handling – use try‑with‑resources to guarantee closure
        // -----------------------------------------------------------------
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine();                       // consume end‑of‑line

            char[][] grid = readGrid(scanner, rows);
            analyse(grid, rows, cols);
        }
    }

    /** Reads the grid from the scanner. */
    private static char[][] readGrid(Scanner scanner, int rows) {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /** Executes the validation logic and prints the result. */
    private static void analyse(char[][] grid, int rows, int cols) {
        boolean rowHasVariation = hasVariationAcrossRows(grid);
        boolean colHasVariation = hasVariationDownColumns(grid);

        if (rowHasVariation && colHasVariation) {
            System.out.println("NO");
            return;
        }

        if (rowHasVariation) {
            System.out.println(evaluateFirstRow(grid[0], cols));
            return;
        }

        if (colHasVariation) {
            System.out.println(evaluateFirstColumn(grid, rows));
            return;
        }

        // Both dimensions are uniform – nothing to validate.
        System.out.println("NO");
    }

    /** Returns true if any row contains at least two distinct characters. */
    private static boolean hasVariationAcrossRows(char[][] grid) {
        for (char[] row : grid) {
            if (hasDistinctElements(row)) {
                return true;
            }
        }
        return false;
    }

    /** Returns true if any column contains at least two distinct characters. */
    private static boolean hasVariationDownColumns(char[][] grid) {
        for (int col = 0; col < grid[0].length; col++) {
            if (hasDistinctElements(columnFromGrid(grid, col))) {
                return true;
            }
        }
        return false;
    }

    /** Extracts a single column from the grid as a char array. */
    private static char[] columnFromGrid(char[][] grid, int colIndex) {
        char[] column = new char[grid.length];
        for (int i = 0; i < grid.length; i++) {
            column[i] = grid[i][colIndex];
        }
        return column;
    }

    /** Checks whether an array contains more than one distinct element. */
    private static boolean hasDistinctElements(char[] arr) {
        char first = arr[0];
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] != first) {
                return true;
            }
        }
        return false;
    }

    /** Counts occurrences of 'R','G','B' in the supplied data and validates the pattern. */
    private static String evaluateFirstRow(char[] row, int length) {
        int[] counts = countColors(row);
        if (counts[0] == counts[1] && counts[1] == counts[2] && counts[0] * 3 == length) {
            return "YES";
        }
        return "NO";
    }

    /** Counts occurrences of 'R','G','B' in the supplied column data. */
    private static String evaluateFirstColumn(char[][] grid, int rows) {
        char[] column = columnFromGrid(grid, 0);
        int[] counts = countColors(column);
        if (counts[0] == counts[1] && counts[1] == counts[2] && counts[0] * 3 == rows) {
            return "YES";
        }
        return "NO";
    }

    /**
     * Returns an int[3] where:
     *   index 0 → number of 'R'
     *   index 1 → number of 'G'
     *   index 2 → number of 'B'
     * If any other character is found, the method still returns the counts
     * but the final validation will reject the pattern.
     */
    private static int[] countColors(char[] data) {
        int[] counts = new int[3]; // 0:R, 1:G, 2:B
        for (char c : data) {
            switch (c) {
                case RED   -> counts[0]++;
                case GREEN -> counts[1]++;
                case BLUE  -> counts[2]++;
                default    -> /* ignore – will cause validation to fail */ ;
            }
        }
        return counts;
    }
}

import java.io.*;
import java.util.HashSet;
import java.util.Set;

/**
 * Solution for the “partition into three equal uniform blocks” problem.
 *
 * <p>
 * The program reads an {@code n × m} binary matrix and decides whether it can be
 * split into three equal‑size strips (either horizontally or vertically) such that
 * each strip consists of a single repeated value and the three values are all
 * different.
 * </p>
 *
 * <p>Refactorings performed:</p>
 * <ul>
 *   <li>Extracted the fast scanner into a separate class with a clear contract.</li>
 *   <li>Renamed all variables to expressive names and removed dead/unused fields.</li>
 *   <li>Separated input handling, validation logic and output into dedicated methods.</li>
 *   <li>Removed magic numbers, used {@code final} constants where appropriate.</li>
 *   <li>Added Javadoc comments and inline comments for readability.</li>
 *   <li>Kept the original algorithmic complexity (O(n·m)) but made it easier to test and maintain.</li>
 * </ul>
 */
public class Main {

    /** Fast scanner that reads from {@code System.in}. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream stream) {
            this.stream = new BufferedInputStream(stream);
        }

        /** Reads the next non‑whitespace token as a string. */
        String nextToken() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            // skip whitespace
            while ((c = read()) <= ' ') {
                if (c == -1) {
                    return "";
                }
            }
            do {
                sb.append((char) c);
            } while ((c = read()) >= '!');
            return sb.toString();
        }

        /** Reads the next integer token. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads the next double token. */
        double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }

        /** Reads the next line (including terminating newline). */
        String nextLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            // skip whitespace
            while ((c = read()) <= ' ') {
                if (c == -1) {
                    return "";
                }
            }
            do {
                sb.append((char) c);
            } while ((c = read()) != '\n' && c != -1);
            return sb.toString();
        }

        /** Peek next character, -1 on EOF. */
        private int read() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        var out = new PrintWriter(System.out);
        var solver = new Main();
        solver.solve(out);
        out.flush();
        out.close();
    }

    /**
     * Solves the problem and writes the answer to the supplied {@link PrintWriter}.
     */
    public void solve(PrintWriter out) throws IOException {
        FastScanner sc = new FastScanner(System.in);

        int n = sc.nextInt();   // number of rows
        int m = sc.nextInt();   // number of columns

        int[][] grid = readGrid(sc, n, m);

        // Try horizontal division (rows grouped in three equal parts)
        if (canPartitionHorizontally(grid, n, m)) {
            out.println("YES");
            return;
        }

        // Try vertical division (columns grouped in three equal parts)
        if (canPartitionVertically(grid, n, m)) {
            out.println("YES");
            return;
        }

        out.println("NO");
    }

    /**
     * Reads the binary matrix from the scanner.
     *
     * @param scanner input scanner
     * @param rows    number of rows
     * @param cols    number of columns
     * @return a 2‑D int array where each element is 0 or 1
     */
    private static int[][] readGrid(FastScanner scanner, int rows, int cols) throws IOException {
        int[][] grid = new int[rows][cols];
        for (int r = 0; r < rows; ++r) {
            String line = scanner.nextLine().trim();
            for (int c = 0; c < cols; ++c) {
                grid[r][c] = line.charAt(c) - '0';
            }
        }
        return grid;
    }

    /**
     * Determines whether the grid can be split into three equal horizontal strips
     * such that each strip consists of a single uniform value and the three values
     * are pairwise distinct.
     *
     * @param grid matrix to analyse
     * @param rows number of rows (for convenience)
     * @param cols number of columns
     * @return {@code true} if a valid partition exists, otherwise {@code false}
     */
    private static boolean canPartitionHorizontally(int[][] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }
        int blockSize = rows / 3;
        Set<Integer> blockValues = new HashSet<>();

        for (int blockIdx = 0; blockIdx < 3; ++blockIdx) {
            int startRow = blockIdx * blockSize;
            int expectedValue = grid[startRow][0]; // reference value for this block

            for (int r = startRow; r < startRow + blockSize; ++r) {
                for (int c = 0; c < cols; ++c) {
                    if (grid[r][c] != expectedValue) {
                        return false; // non‑uniform block
                    }
                }
            }
            // Store the block's uniform value – the set must end up with size 3.
            blockValues.add(expectedValue);
        }
        return blockValues.size() == 3;
    }

    /**
     * Determines whether the grid can be split into three equal vertical strips
     * such that each strip consists of a single uniform value and the three values
     * are pairwise distinct.
     *
     * @param grid matrix to analyse
     * @param rows number of rows
     * @param cols number of columns (for convenience)
     * @return {@code true} if a valid partition exists, otherwise {@code false}
     */
    private static boolean canPartitionVertically(int[][] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }
        int blockSize = cols / 3;
        Set<Integer> blockValues = new HashSet<>();

        for (int blockIdx = 0; blockIdx < 3; ++blockIdx) {
            int startCol = blockIdx * blockSize;
            int expectedValue = grid[0][startCol]; // reference value for this block

            for (int c = startCol; c < startCol + blockSize; ++c) {
                for (int r = 0; r < rows; ++r) {
                    if (grid[r][c] != expectedValue) {
                        return false; // non‑uniform block
                    }
                }
            }
            blockValues.add(expectedValue);
        }
        return blockValues.size() == 3;
    }
}

/**
 * Refactored solution for the “Flag” problem.
 * <p>
 * The program reads an {@code N × M} grid of characters and checks whether the flag
 * can be divided into three equal‑size stripes of a single colour each.
 * The stripes may be arranged horizontally (by rows) or vertically (by columns),
 * depending on which dimension is divisible by three.
 */
public class Main {

    /** Entry point of the application. */
    public static void main(String[] args) {
        // Using a single scanner that consumes the whole input stream.
        try (FastScanner scanner = new FastScanner()) {
            Solver solver = new Solver();
            String result = solver.solve(scanner);
            System.out.println(result);
        }
    }
}

/**
 * Handles all input parsing.  It is deliberately lightweight – it reads the
 * entire {@code InputStream} into a byte buffer and then supplies tokens
 * without the overhead of repeatedly calling {@code System.in.read()}.
 */
final class FastScanner {

    private static final int BUFFER_SIZE = 1 << 16; // 64 KiB
    private final InputStream in;
    private final byte[] buffer = new byte[BUFFER_SIZE];
    private int pointer = 0;
    private int length = 0;

    FastScanner(InputStream in) {
        this.in = in;
    }

    /** Reads the next non‑whitespace byte. */
    private int readByte() {
        if (pointer >= length) {
            // Fill buffer
            length = in.read(buffer);
            pointer = 0;
            if (length <= 0) {
                return -1;
            }
        }
        return buffer[pointer++];
    }

    /** Skips over whitespace characters. */
    private int skipWhitespace() {
        int b;
        while ((b = readByte()) != -1 && Character.isWhitespace((char) b)) {
            // continue skipping
        }
        return b;
    }

    /** Reads the next line‑delimited token as a {@code String} (e.g. an integer). */
    String readToken() {
        int b = skipWhitespace();
        if (b == -1) {
            throw new NoSuchElementException();
        }
        StringBuilder sb = new StringBuilder();
        while (b != -1 && !Character.isWhitespace((char) b)) {
            sb.append((char) b);
            b = readByte();
        }
        return sb.toString();
    }

    /** Reads the next integer from the input. */
    int nextInt() {
        return Integer.parseInt(readToken());
    }

    /**
     * Reads {@code rows} lines, each containing {@code cols} non‑whitespace characters.
     * The returned matrix stores characters row‑wise.
     */
    char[][] readCharMatrix(int rows, int cols) {
        char[][] matrix = new char[rows][];
        for (int r = 0; r < rows; r++) {
            matrix[r] = readNextCharArray(cols);
        }
        return matrix;
    }

    /** Reads exactly {@code length} non‑whitespace characters. */
    private char[] readNextCharArray(int length) {
        char[] arr = new char[length];
        for (int i = 0; i < length; i++) {
            arr[i] = (char) skipWhitespace();
            if (arr[i] == -1) {
                throw new NoSuchElementException();
            }
            // consume the character
            readByte();
        }
        return arr;
    }
}

/**
 * Core logic that decides whether the flag can be partitioned according to the rules.
 */
final class Solver {

    /** Result that will be printed to {@code System.out}. */
    private static final String YES = "YES";
    private static final String NO = "NO";

    /**
     * Reads the input using the supplied scanner, processes it and returns the answer.
     *
     * @param scanner a scanner that provides the input data
     * @return {@code "YES"} or {@code "NO"}
     */
    String solve(FastScanner scanner) {
        int n = scanner.nextInt();   // number of rows
        int m = scanner.nextInt();   // number of columns
        char[][] grid = scanner.readCharMatrix(n, m);

        if (n % 3 == 0 && m % 3 == 0) {
            return (isHorizontalPartitionValid(grid, n, m) ||
                    isVerticalPartitionValid(grid, n, m))
                    ? YES : NO;
        } else if (n % 3 == 0) {
            return isHorizontalPartitionValid(grid, n, m) ? YES : NO;
        } else if (m % 3 == 0) {
            return isVerticalPartitionValid(grid, n, m) ? YES : NO;
        } else {
            return NO;
        }
    }

    /** Checks whether the flag can be split into horizontal stripes of equal height. */
    private boolean isHorizontalPartitionValid(char[][] grid, int n, int m) {
        int stripeHeight = n / 3;
        boolean[] usedColors = new boolean[256]; // ASCII range

        for (int startRow = 0; startRow < n; startRow += stripeHeight) {
            char expectedColor = grid[startRow][0];
            if (expectedColor == 0) { // safety guard; should never happen
                return false;
            }
            if (usedColors[expectedColor]) {
                return false; // duplicate colour
            }
            usedColors[expectedColor] = true;

            for (int r = startRow; r < startRow + stripeHeight; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] != expectedColor) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /** Checks whether the flag can be split into vertical stripes of equal width. */
    private boolean isVerticalPartitionValid(char[][] grid, int n, int m) {
        int stripeWidth = m / 3;
        boolean[] usedColors = new boolean[256];

        for (int startCol = 0; startCol < m; startCol += stripeWidth) {
            char expectedColor = grid[0][startCol];
            if (expectedColor == 0) {
                return false;
            }
            if (usedColors[expectedColor]) {
                return false;
            }
            usedColors[expectedColor] = true;

            for (int c = startCol; c < startCol + stripeWidth; c++) {
                for (int r = 0; r < n; r++) {
                    if (grid[r][c] != expectedColor) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

/**
 * Refactored version of {@code FlagofBarland}.
 *
 * <p>
 * The program reads a flag represented by an {@code n × m} grid of uppercase letters.
 * It checks whether the flag can be divided into three equal stripes either
 * horizontally or vertically such that every stripe consists of a single,
 * distinct character repeated throughout its rows (or columns). If such a
 * configuration exists, the program prints {@code YES}; otherwise it prints
 * {@code NO}.
 * </p>
 *
 * <p>Key improvements over the original implementation:</p>
 * <ul>
 *   <li>Extracted helper methods to isolate reusable logic.</li>
 *   <li>Clear naming and reduced duplication.</li>
 *   <li>Removed the misleading {@code String#valueOf(char[])} usage; now
 *       each row/column is examined for uniformity explicitly.</li>
 *   <li>Used {@link String#repeat(int)} for generating a repeated‑character
 *       string.</li>
 *   <li>Early returns and flat control flow make the code easier to follow.</li>
 * </ul>
 */
public class FlagofBarland {

    public static void main(String[] args) {
        try (var scanner = new Scanner(System.in)) {
            int n = scanner.nextInt(); // number of rows
            int m = scanner.nextInt(); // number of columns
            char[][] grid = new char[n][m];

            // Read the grid row by row
            for (int r = 0; r < n; r++) {
                String line = scanner.next();
                grid[r] = line.toCharArray();
            }

            // Decide which orientation(s) are possible
            boolean bothDivisible = n % 3 == 0 && m % 3 == 0;
            boolean onlyRowsDivisible = n % 3 == 0 && m % 3 != 0;
            boolean onlyColsDivisible = m % 3 == 0 && n % 3 != 0;

            if (!bothDivisible && !onlyRowsDivisible && !onlyColsDivisible) {
                System.out.println("NO");
                return;
            }

            // Try horizontal stripes first (if allowed)
            if (onlyRowsDivisible || bothDivisible) {
                if (checkHorizontalStripePattern(grid)) {
                    System.out.println("YES");
                    return;
                }
            }

            // If vertical stripes are allowed, try them
            if (onlyColsDivisible || bothDivisible) {
                // Transpose the matrix to reuse the same stripe logic on columns
                char[][] transposed = transpose(grid);
                if (checkHorizontalStripePattern(transposed)) {
                    System.out.println("YES");
                    return;
                }
            }

            // No valid stripe pattern found
            System.out.println("NO");
        }
    }

    /** Checks whether the given matrix can be split into three equal blocks of rows,
     *  where each block consists of uniform rows that all contain the same character,
     *  and the three characters of the blocks are pairwise distinct. */
    private static boolean checkHorizontalStripePattern(char[][] grid) {
        if (grid.length == 0) {
            return false;
        }
        int totalRows = grid.length;
        int blockSize = totalRows / 3;

        // Character used in the first block
        Character firstChar = rowUniformChar(grid[0]);
        if (firstChar == null) {
            return false;
        }

        // Validate the three blocks
        for (int blockIdx = 0; blockIdx < 3; blockIdx++) {
            int blockStart = blockIdx * blockSize;
            Character expectedChar = rowUniformChar(grid[blockStart]);
            if (expectedChar == null || expectedChar != rowUniformChar(grid[blockStart])) {
                return false;
            }
            // Ensure that rows within the same block are all uniform with the same character
            for (int r = blockStart + 1; r < blockStart + blockSize; r++) {
                if (!expectedChar.equals(rowUniformChar(grid[r]))) {
                    return false;
                }
            }
            // Disallow reuse of a character that already appeared in a previous block
            if (blockIdx > 0 && expectedChar == firstChar) {
                return false;
            }
            // Prepare for next iteration: the character of this block becomes the reference
            firstChar = expectedChar;
        }
        return true;
    }

    /** Returns the repeated character of a row if the entire row consists of the same
     *  character; otherwise returns {@code null}. */
    private static Character rowUniformChar(char[] row) {
        if (row.length == 0) {
            return null;
        }
        char first = row[0];
        for (char c : row) {
            if (c != first) {
                return null;
            }
        }
        return first;
    }

    /** Returns the repeated character of a column if the entire column consists of the
     *  same character; otherwise returns {@code null}. */
    private static Character columnUniformChar(char[][] matrix, int colIdx) {
        if (matrix.length == 0) {
            return null;
        }
        char first = matrix[0][colIdx];
        for (char[] row : matrix) {
            if (row[colIdx] != first) {
                return null;
            }
        }
        return first;
    }

    /** Transposes the given matrix. The resulting matrix has dimensions
     *  {@code m × n} where {@code m} is the number of columns of the original matrix
     *  and {@code n} is the number of rows. */
    private static char[][] transpose(char[][] matrix) {
        int rows = matrix.length;      // original m
        int cols = matrix[0].length;   // original n
        char[][] transposed = new char[cols][rows];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                transposed[c][r] = matrix[r][c];
            }
        }
        return transposed;
    }
}

import java.io.*;
import java.util.*;

/**
 * Detects whether an N×M grid can be divided into three equal‑size stripes
 * (either horizontally or vertically) each filled with a single, distinct
 * colour among {@code R}, {@code B} and {@code G}.
 *
 * The implementation is deliberately split into small, pure functions so that
 * each step of the algorithm is easy to understand, test and maintain.
 */
public class Main {

    /** Colours that are allowed in a valid pattern. */
    private static final Set<Character> VALID_COLOURS = Set.of('R', 'B', 'G');

    /** Entry point */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();          // number of rows
        int m = fs.nextInt();          // number of columns
        char[][] grid = new char[n][]; // read the whole board

        for (int i = 0; i < n; i++) {
            grid[i] = fs.next().toCharArray();
        }

        boolean ok = false;
        if (n % 3 == 0) {
            ok = checkHorizontalStripes(grid);
        }
        if (!ok && m % 3 == 0) {
            ok = checkVerticalStripes(grid);
        }

        out.println(ok ? "YES" : "NO");
        out.flush();
    }

    /** Checks whether the board consists of three uniform horizontal stripes. */
    private static boolean checkHorizontalStripes(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        if (rows % 3 != 0) {
            return false;
        }

        int stripeHeight = rows / 3;
        Set<Character> seenColours = new HashSet<>();

        for (int s = 0; s < 3; s++) {
            int firstRow = s * stripeHeight;
            char colour = grid[firstRow][0];               // colour of this stripe
            if (!isUniform(colour, grid, firstRow, 0, stripeHeight, cols)) {
                return false;                              // not uniform
            }
            if (!VALID_COLOURS.contains(colour)) {
                return false;                              // illegal colour
            }
            seenColours.add(colour);
        }
        // three different colours must have been observed
        return seenColours.size() == 3;
    }

    /** Checks whether the board consists of three uniform vertical stripes. */
    private static boolean checkVerticalStripes(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        if (cols % 3 != 0) {
            return false;
        }

        int stripeWidth = cols / 3;
        Set<Character> seenColours = new HashSet<>();

        for (int s = 0; s < 3; s++) {
            int firstCol = s * stripeWidth;
            char colour = grid[0][firstCol];               // colour of this stripe
            if (!isUniform(colour, grid, 0, firstCol, rows, stripeWidth)) {
                return false;                              // not uniform
            }
            if (!VALID_COLOURS.contains(colour)) {
                return false;                              // illegal colour
            }
            seenColours.add(colour);
        }
        return seenColours.size() == 3;
    }

    /**
     * Verifies that a rectangular sub‑grid of the given size is filled entirely
     * with {@code colour}.
     *
     * @param colour  colour that the sub‑grid must contain
     * @param grid    the whole board
     * @param row0    starting row index (inclusive)
     * @param col0    starting column index (inclusive)
     * @param height  number of rows in the sub‑grid
     * @param width   number of columns in the sub‑grid
     * @return {@code true} if every cell equals {@code colour}
     */
    private static boolean isUniform(char colour, char[][] grid,
                                     int row0, int col0,
                                     int height, int width) {
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (grid[row0 + r][col0 + c] != colour) {
                    return false;
                }
            }
        }
        return true;
    }
}

