 * Fast I/O helpers – a tiny wrapper around BufferedReader that
 * behaves like the original `Reader` class but is more idiomatic.
 * -------------------------------------------------------------- */
class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    FastScanner(InputStream is) {
        br = new BufferedReader(new InputStreamReader(is));
    }

    /** Returns the next token or {@code null} if the input stream is exhausted. */
    String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    /** Convenience wrapper for {@link #next()} that expects an int. */
    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }
}

