class OutputWriter extends PrintWriter {
    OutputWriter(OutputStream out) {
        super(out, true);
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original FlagOfBerland837B solution.
 * The program validates whether a matrix contains a valid flag pattern
 * either horizontally or vertically.
 */
public class FlagOfBerland837B {

    /* --------------------  Enum & small data holders  -------------------- */

    /** Colors used in the flag. */
    private enum Color {
        R, G, B
    }

    /** Holds aggregated information for a set of rows (horizontal or vertical). */
    private static final class AggregatedInfo {
        /* per‑color statistics */
        final int[] minIdx = new int[3];   // first occurrence index
        final int[] maxIdx = new int[3];   // last occurrence index
        final int[] count = new int[3];    // how many rows contain the color

        AggregatedInfo() {
            Arrays.fill(minIdx, Integer.MAX_VALUE);
            Arrays.fill(maxIdx, Integer.MIN_VALUE);
        }

        /** Resets all fields – useful when re‑using the object. */
        void reset() {
            for (int i = 0; i < 3; i++) {
                minIdx[i] = Integer.MAX_VALUE;
                maxIdx[i] = Integer.MIN_VALUE;
                count[i] = 0;
            }
        }
    }

    /** Result of analysing a single row (or column) string. */
    private static final class RowValidation {
        final boolean valid;   // true if the row obeys the flag rules
        final boolean containsM; // true if the string contains the letter 'M'
        final List<Block> blocks = new ArrayList<>();

        RowValidation(boolean valid, boolean containsM) {
            this.valid = valid;
            this.containsM = containsM;
        }

        /** Simple holder for a contiguous block of equal characters. */
        final class Block {
            final char ch;
            final int start, end; // inclusive start / end positions

            Block(char ch, int start, int end) {
                this.ch = ch;
                this.start = start;
                this.end = end;
            }
        }
    }

    /* --------------------  Core solving logic  -------------------- */

    /**
     * Entry point used by {@code main}. Solves the problem given the matrix
     * rows and the column strings (queries).
     */
    private static String solve(List<String> matrixRows, List<String> columnStrings) {
        AggregatedInfo horizInfo = new AggregatedInfo(); // statistics for rows
        AggregatedInfo vertInfo  = new AggregatedInfo(); // statistics for columns

        validateHorizontalRows(matrixRows, horizInfo);
        validateVerticalRows(columnStrings, vertInfo);

        boolean horizontalOk = isPatternSatisfied(horizInfo);
        boolean verticalOk   = isPatternSatisfied(vertInfo);

        return (horizontalOk || verticalOk) ? "YES" : "NO";
    }

    /** Checks that all three colors appear the same number of times and are contiguous. */
    private static boolean isPatternSatisfied(AggregatedInfo info) {
        // equal frequencies
        if (!(info.count[0] == info.count[1] && info.count[1] == info.count[2])) {
            return false;
        }
        // each color must be present at least once
        if (info.count[0] == 0 || info.count[1] == 0 || info.count[2] == 0) {
            return false;
        }
        // contiguity check: max index - min index must equal count-1
        for (int i = 0; i < 3; i++) {
            if (info.maxIdx[i] - info.minIdx[i] != info.count[i] - 1) {
                return false;
            }
        }
        return true;
    }

    /** Analyses every horizontal row and updates {@code info} accordingly. */
    private static void validateHorizontalRows(List<String> rows, AggregatedInfo info) {
        boolean hFlag = true;
        for (int i = 0; i < rows.size(); i++) {
            RowValidation validation = analyseRow(rows.get(i));
            if (!validation.valid) {
                hFlag = false;
                break;
            }

            // map colour character to enum index (R→0, G→1, B→2)
            int idx = colourToIndex(validation.blocks.get(0).ch);
            info.minIdx[idx] = Math.min(info.minIdx[idx], i);
            info.maxIdx[idx] = Math.max(info.maxIdx[idx], i);
            info.count[idx]++;

            // after processing all rows we will later verify contiguity,
            // but we can also perform a quick sanity check now:
            if (validation.blocks.size() != 3) {
                hFlag = false;
                break;
            }
            // all three blocks must have the same length
            int expectedLen = validation.blocks.get(0).end - validation.blocks.get(0).start + 1;
            for (int b = 1; b < 3; b++) {
                if (validation.blocks.get(b).end - validation.blocks.get(b).start + 1 != expectedLen) {
                    hFlag = false;
                    break;
                }
            }
            if (!hFlag) {
                break;
            }
            // colours of the three blocks must be distinct
            Set<Character> seen = new HashSet<>();
            for (RowValidation.Block b : validation.blocks) {
                if (!seen.add(b.ch)) {
                    hFlag = false;
                    break;
                }
            }
            if (!hFlag) {
                break;
            }
        }

        // Final contiguity verification (mirrors the logic in the original code)
        if (hFlag) {
            for (int i = 0; i < 3; i++) {
                if (info.maxIdx[i] - info.minIdx[i] != info.count[i] - 1) {
                    hFlag = false;
                    break;
                }
            }
        }
    }

    /** Analyses every vertical string (column) and updates {@code info} accordingly. */
    private static void validateVerticalRows(List<String> cols, AggregatedInfo info) {
        boolean vFlag = true;
        for (int i = 0; i < cols.size(); i++) {
            RowValidation validation = analyseRow(cols.get(i));
            if (!validation.valid) {
                vFlag = false;
                break;
            }

            int idx = colourToIndex(validation.blocks.get(0).ch);
            info.minIdx[idx] = Math.min(info.minIdx[idx], i);
            info.maxIdx[idx] = Math.max(info.maxIdx[idx], i);
            info.count[idx]++;

            if (validation.blocks.size() != 3) {
                vFlag = false;
                break;
            }
            int expectedLen = validation.blocks.get(0).end - validation.blocks.get(0).start + 1;
            for (int b = 1; b < 3; b++) {
                if (validation.blocks.get(b).end - validation.blocks.get(b).start + 1 != expectedLen) {
                    vFlag = false;
                    break;
                }
            }
            if (!vFlag) {
                break;
            }
            Set<Character> seen = new HashSet<>();
            for (RowValidation.Block b : validation.blocks) {
                if (!seen.add(b.ch)) {
                    vFlag = false;
                    break;
                }
            }
            if (!vFlag) {
                break;
            }
        }

        if (vFlag) {
            for (int i = 0; i < 3; i++) {
                if (info.maxIdx[i] - info.minIdx[i] != info.count[i] - 1) {
                    vFlag = false;
                    break;
                }
            }
        }
    }

    /** Analyses a single string and returns its validation details. */
    private static RowValidation analyseRow(String s) {
        List<RowValidation.Block> blocks = new ArrayList<>();
        boolean containsM = false;
        int i = 0;
        while (i < s.length()) {
            char cur = s.charAt(i);
            if (cur == 'M') {
                containsM = true;
                i++;
                continue;
            }
            int start = i;
            while (i < s.length() && s.charAt(i) == cur) {
                i++;
            }
            blocks.add(new RowValidation.Block(cur, start, i - 1));
        }
        return new RowValidation(!containsM && !blocks.isEmpty(), containsM);
    }

    /** Translates a colour character to the enum index used by {@link Color}. */
    private static int colourToIndex(char ch) {
        return switch (ch) {
            case 'R' -> 0;
            case 'G' -> 1;
            case 'B' -> 2;
            default -> throw new IllegalStateException("Unexpected colour: " + ch);
        };
    }

    /* --------------------  Input utilities  -------------------- */

    /**
     * Reads the next non‑empty token from the given {@link BufferedReader}.
     * This mimics the behaviour of the original {@code next()} helper.
     */
    private static String readToken(BufferedReader br) throws IOException {
        String line;
        while ((line = br.readLine()) == null || line.isBlank()) {
            // skip empty lines
        }
        StringTokenizer st = new StringTokenizer(line);
        if (st.hasMoreTokens()) {
            return st.nextToken();
        }
        // If token exhausted, read the next line
        line = br.readLine();
        return line != null ? line.trim() : "";
    }

    /* --------------------  Main program  -------------------- */

    public static void main(String[] args) throws IOException {
        // BufferedReader is the primary source of input
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // Use a StringTokenizer to parse the first line (dimensions)
            StringTokenizer st = new StringTokenizer(br.readLine());
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            // Early exit for matrices that are too small to contain a flag
            if (rows < 3 || cols < 3) {
                System.out.println("NO");
                return;
            }

            // ----- read the matrix row by row -----
            List<String> matrixRows = new ArrayList<>(rows);
            for (int i = 0; i < rows; i++) {
                matrixRows.add(readToken(br));
            }

            // ----- build the column strings (the "queries") -----
            List<String> columnStrings = new ArrayList<>(cols);
            for (int c = 0; c < cols; c++) {
                StringBuilder sb = new StringBuilder(rows);
                for (int r = 0; r < rows; r++) {
                    sb.append(matrixRows.get(r).charAt(c));
                }
                columnStrings.add(sb.toString());
            }

            // ----- solve and output -----
            System.out.println(solve(matrixRows, columnStrings));
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point for the program.
 * Reads input, processes test cases and prints the result.
 */
public class Main {
    public static void main(String[] args) throws IOException {
        try (InputReader in = new InputReader();
             PrintWriter out = new PrintWriter(System.out)) {

            int testCases = 1;
            new Solver().process(testCases, in, out);
        }
    }
}

/**
 * Handles all solving logic.
 * The class is deliberately stateless – all behaviour is encapsulated in pure methods.
 */
class Solver {

    /** Entry point used by {@code Main}. */
    public void process(int testCases, InputReader in, PrintWriter out) throws IOException {
        for (int tc = 1; tc <= testCases; tc++) {
            solve(tc, in, out);
        }
    }

    /** Core logic for a single test case. */
    private void solve(int testNumber, InputReader in, PrintWriter out) throws IOException {
        int n = in.nextInt();          // number of rows
        int m = in.nextInt();          // number of columns
        char[][] board = readBoard(in, n, m);

        boolean ok = isRowStripePattern(board) || isColumnStripePattern(board);
        out.println(ok ? "YES" : "NO");
    }

    /** Reads the board from the input stream. */
    private char[][] readBoard(InputReader in, int rows, int cols) throws IOException {
        char[][] board = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = in.next();
            for (int c = 0; c < cols; c++) {
                board[r][c] = line.charAt(c);
            }
        }
        return board;
    }

    /** Checks whether the board consists of horizontal colour stripes. */
    private boolean isRowStripePattern(char[][] board) {
        if (board.length % 3 != 0) {
            return false;
        }
        return validateStripePattern(board, true);
    }

    /** Checks whether the board consists of vertical colour stripes. */
    private boolean isColumnStripePattern(char[][] board) {
        if (board[0].length % 3 != 0) {
            return false;
        }
        return validateStripePattern(board, false);
    }

    /** Validates a stripe pattern – either rows or columns – according to the rules. */
    private boolean validateStripePattern(char[][] board, boolean byRows) {
        final int pieceSize = byRows ? board.length / 3 : board[0].length / 3;
        final char[] expectedColors = {'R', 'G', 'B'}; // order does not matter, just the set

        // Determine which colour belongs to each logical piece (row block or column block)
        Map<Character, Integer> colourToIndex = new LinkedHashMap<>();
        for (int i = 0; i < 3; i++) {
            colourToIndex.put(expectedColors[i], i);
        }

        // Determine the expected colour for each piece
        char[] pieceColour = new char[3];
        for (int i = 0; i < 3; i++) {
            int pieceStart = i * pieceSize;
            int referenceIdx = byRows ? pieceStart : 0; // column index for vertical case
            pieceColour[i] = board[referenceIdx][referenceIdx];
            if (!colourToIndex.containsValue(pieceColour[i])) {
                return false; // illegal colour
            }
        }

        // Verify that each piece is uniformly coloured and does not repeat a colour
        Set<Character> seen = new HashSet<>();
        for (int i = 0; i < 3; i++) {
            char colour = pieceColour[i];
            if (seen.contains(colour)) {
                return false; // duplicate colour
            }
            seen.add(colour);

            int startIdx = i * pieceSize;
            int endIdx = (i + 1) * pieceSize;
            if (byRows) {
                // Horizontal stripes: validate each whole row block
                for (int r = startIdx; r < endIdx; r++) {
                    for (int c = 0; c < board[0].length; c++) {
                        if (board[r][c] != colour) {
                            return false;
                        }
                    }
                }
            } else {
                // Vertical stripes: validate each whole column block
                for (int c = startIdx; c < endIdx; c++) {
                    for (int r = 0; r < board.length; r++) {
                        if (board[r][c] != colour) {
                            return false;
                        }
                    }
                }
            }
        }
        return true;
    }
}

/**
 * Simple buffered input scanner.
 * Facilitates tokenised reading of integers, strings, etc.
 */
class InputReader {
    private final BufferedReader br;
    private StringTokenizer st;

    public InputReader() {
        this.br = new BufferedReader(new InputStreamReader(System.in));
    }

    /** Returns the next token, reading a new line if necessary. */
    private String nextToken() throws IOException {
        while (st == null || !st.hasMoreElements()) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    // Additional primitive readers can be added if required.
}

import java.io.BUFFEREDINPUTSTREAM;
import java.io.IOException;
import java.io.PRINTWRITER;
import java.io.InputStream;
import java.io.BufferedInputStream;

/**
 * Entry point of the application.  The solving routine is executed in a
 * dedicated thread with an enlarged stack size to avoid StackOverflowError
 * on large inputs.
 */
public class Main {

    /** Default thread‑stack size for the solver thread (64 MiB). */
    private static final int SOLVER_STACK_SIZE = 1 << 26;

    public static void main(String[] args) throws IOException {
        // Run the solver in a separate thread to keep the main thread lightweight.
        Thread solverThread = new Thread(
                () -> new Main().run(),
                "Flag‑Checker‑Solver",
                SOLVER_STACK_SIZE);
        solverThread.start();
    }

    /** Core solving routine – all heavy work lives inside this method. */
    private void run() throws IOException {
        // Try‑with‑resources guarantees that streams are closed exactly once.
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            solve(scanner, out);
        }
    }

    /**
     * Reads the problem data, applies the flag detection logic and prints the
     * result.
     */
    private void solve(FastScanner scanner, PrintWriter out) {
        int rows = scanner.nextInt();   // n
        int cols = scanner.nextInt();   // m
        char[][] grid = readGrid(scanner, rows);

        FlagChecker checker = new FlagChecker(grid);
        boolean isFlag = checker.isFlagPattern();

        out.println(isFlag ? "YES" : "NO");
    }

    /** Helper that reads the whole grid from the scanner. */
    private static char[][] readGrid(FastScanner scanner, int rows) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = scanner.nextString();
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Represents the algorithm that checks whether the grid can be split into
     * three equal sections (either horizontally or vertically) each consisting
     * of a single distinct character.
     */
    private static final class FlagChecker {

        private final char[][] grid;
        private final int rowCount, colCount;

        FlagChecker(char[][] grid) {
            this.grid = grid;
            this.rowCount = grid.length;
            this.colCount = grid[0].length;
        }

        /** Checks the horizontal division (three equal‑height bands). */
        private boolean isHorizontallyFlagged() {
            if (rowCount % 3 != 0) {
                return false;
            }
            final int band = rowCount / 3;

            // Reference characters for the three bands.
            char c1 = grid[0][0];
            char c2 = grid[band][0];
            char c3 = grid[2 * band][0];

            // They must be pairwise different.
            if (c1 == c2 || c2 == c3 || c3 == c1) {
                return false;
            }

            // Validate that every cell in a band equals its designated character.
            for (int r = 0; r < rowCount; r++) {
                char expected = currentBandChar(r, band);
                if (expected == 0) {
                    return false; // unreachable guard – kept for safety
                }
                for (int c = 0; c < colCount; c++) {
                    if (grid[r][c] != expected) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Returns the expected character for the band that contains the row. */
        private static char currentBandChar(int row, int bandSize) {
            if (row < bandSize) {
                return '1';
            } else if (row < 2 * bandSize) {
                return '2';
            } else {
                return '3';
            }
        }

        /** Checks the vertical division (three equal‑width columns). */
        private boolean isVerticallyFlagged() {
            if (colCount % 3 != 0) {
                return false;
            }
            final int band = colCount / 3;

            // Reference characters for the three vertical bands.
            char c1 = grid[0][0];
            char c2 = grid[0][band];
            char c3 = grid[0][2 * band];

            if (c1 == c2 || c2 == c3 || c3 == c1) {
                return false;
            }

            // Validate each column band.
            for (int c = 0; c < colCount; c++) {
                char expected = currentColumnBandChar(c, band);
                if (expected == 0) {
                    return false;
                }
                for (int r = 0; r < rowCount; r++) {
                    if (grid[r][c] != expected) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Determines which vertical band a column belongs to (1, 2 or 3). */
        private static char currentColumnBandChar(int col, int bandSize) {
            if (col < bandSize) {
                return '1';
            } else if (col < 2 * bandSize) {
                return '2';
            } else {
                return '3';
            }
        }

        /** Exposes the result of the flag detection. */
        public boolean isFlagPattern() {
            return isHorizontallyFlagged() || isVerticallyFlagged();
        }
    }

    /**
     * Fast scanner based on {@link BufferedInputStream} that efficiently reads
     * primitive values and tokens without the overhead of {@link Scanner}.
     */
    private static final class FastScanner implements AutoCloseable {

        private final BufferedInputStream in;
        private final byte[] buffer = new byte[1 << 12];
        private int ptr = 0;
        private int len = 0;

        FastScanner(InputStream source) {
            this.in = new BufferedInputStream(source);
        }

        /** Reads the next non‑whitespace byte. */
        private int readNonWhite() throws IOException {
            int b;
            do {
                b = read();
            } while (isWhiteSpace(b));
            return b;
        }

        /** Reads a single byte, filling the buffer when necessary. */
        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        /** Skips whitespace characters. */
        private static boolean isWhiteSpace(int b) {
            return b == ' ' || b == '\n' || b == '\r' || b == '\t' || b == -1;
        }

        /** Reads a signed integer. */
        int nextInt() throws IOException {
            int sign = 1;
            int c = readNonWhite();
            if (c == '-') {
                sign = -1;
                c = readNonWhite();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readNonWhite();
            }
            return value * sign;
        }

        /** Reads the next token (a non‑whitespace string). */
        String nextString() throws IOException {
            int c = readNonWhite();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readNonWhite();
            } while (!isWhiteSpace(c));
            return sb.toString();
        }

        /** Closes the underlying stream (called automatically by try‑with‑resources). */
        @Override
        public void close() throws IOException {
            in.close();
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution that determines whether a matrix consists of three
 * equal‑sized contiguous blocks of colours 'B', 'R' and 'G' either horizontally
 * (by rows) or vertically (by columns).  The output for each test case is
 * "YES" if at least one of the two directions satisfies the condition,
 * otherwise "NO".
 */
public class Main {

    private static final char BLUE  = 'B';
    private static final char RED   = 'R';
    private static final char GREEN = 'G';

    public static void main(String[] args) throws IOException {
        /*  Use try‑with‑resources to guarantee proper closing of streams  */
        try (BufferedReader reader = new BufferedReader(
                     new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out, true)) {

            String line;
            /*  Skip possible empty lines before each test case  */
            while ((line = skipEmptyLines(reader.readLine())) != null) {
                StringTokenizer tk = new StringTokenizer(line);
                int rows = Integer.parseInt(tk.nextToken());
                int cols = Integer.parseInt(tk.nextToken());

                char[][] matrix = readMatrix(reader, rows, cols);

                boolean okByRows = analyseDirection(matrix, true, rows, rows);
                boolean okByCols = analyseDirection(matrix, false, cols, cols);

                out.println((okByRows || okByCols) ? "YES" : "NO");
            }
        }
    }

    /** Removes leading empty lines and returns the first non‑empty line (or null). */
    private static String skipEmptyLines(String next) {
        while (next != null && next.trim().isEmpty()) {
            next = null;                // force termination when EOF is reached
        }
        return next;
    }

    /** Reads exactly {@code rows} lines, each containing at least {@code cols} characters. */
    private static char[][] readMatrix(BufferedReader br, int rows, int cols) throws IOException {
        char[][] matrix = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String row = br.readLine();
            if (row == null) {
                throw new IOException("Unexpected end of input while reading matrix");
            }
            for (int j = 0; j < Math.min(row.length(), cols); j++) {
                matrix[i][j] = row.charAt(j);
            }
        }
        return matrix;
    }

    /**
     * Analyses either the rows or the columns of the matrix.
     *
     * @param matrix       the source matrix
     * @param byRows       {@code true} to analyse rows, {@code false} to analyse columns
     * @param lineCount    number of lines to examine in the chosen direction
     * @param blockSize    size of the whole direction (rows or columns); the condition requires
     *                     three equal blocks that exactly fill this size
     * @return {@code true} if the examined direction consists of three consecutive,
     *         equally long blocks of colours {@code B}, {@code R} and {@code G}.
     */
    private static boolean analyseDirection(char[][] matrix, boolean byRows,
                                            int lineCount, int blockSize) {
        int blueLen = 0, redLen = 0, greenLen = 0;

        char currentColour = '\0';
        int currentRun = 0;

        for (int idx = 0; idx < lineCount; idx++) {
            char colour = uniformLineColour(matrix, byRows, idx, lineCount, blockSize);
            if (colour == '\0') {               // line is not uniform → break current block
                if (currentColour != '\0') {
                    storeRun(currentColour, currentRun, blueLen, redLen, greenLen);
                    currentRun = 0;
                }
                continue;
            }

            if (currentColour == '\0' || colour == currentColour) {
                currentRun++;
            } else {
                // finish previous block before starting a new one
                if (currentColour != '\0') {
                    storeRun(currentColour, currentRun, blueLen, redLen, greenLen);
                }
                currentColour = colour;
                currentRun = 1;
            }
        }

        // store the length of the last block, if any
        if (currentColour != '\0') {
            storeRun(currentColour, currentRun, blueLen, redLen, greenLen);
        }

        return hasThreeEqualBlocks(blueLen, redLen, greenLen, blockSize);
    }

    /** Returns the colour of the {@code idx}-th line (row or column) if it is uniform. */
    private static char uniformLineColour(char[][] matrix, boolean byRows,
                                          int lineIdx, int lineCount, int dim) {
        char first = '\0';
        for (int i = 0; i < dim; i++) {
            char c = byRows ? matrix[lineIdx][i] : matrix[i][lineIdx];
            if (first == '\0') {
                first = c;
            } else if (c != first) {
                return '\0';               // not uniform
            }
        }
        return first;
    }

    /** Stores the length of a finished colour block into the appropriate variable. */
    private static void storeRun(char colour, int length,
                                 int blue, int red, int green) {
        switch (colour) {
            case 'B' -> blue = length;
            case 'R' -> red = length;
            case 'G' -> green = length;
        }
    }

    /** Checks whether the three stored lengths represent three equal, non‑zero blocks
     *  that exactly fill the examined direction. */
    private static boolean hasThreeEqualBlocks(int blue, int red, int green, int size) {
        return blue != 0 && red != 0 && green != 0 &&
               blue == red && red == green && blue * 3 == size;
    }
}

import java.util.Scanner;

public class Main {

    /** Maximum allowed dimension – kept only as a safeguard. */
    private static final int MAX_SIZE = 1000 + 10;

    public static void main(String[] args) {
        // Scanner is used only in this method and will be closed automatically.
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();   // n
            int cols = scanner.nextInt();   // m
            char[][] grid = readGrid(scanner, rows, cols);
            boolean ok = hasUniformRowPattern(grid, rows, cols) ||
                         hasUniformColumnPattern(grid, rows, cols);
            System.out.println(ok ? "YES" : "NO");
        }
    }

    /** Reads n strings from the scanner and stores them as a char matrix. */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();            // each line represents one row
            grid[i] = line.toCharArray();              // keep the raw characters
        }
        return grid;
    }

    /**
     * Checks whether the grid can be partitioned into three consecutive horizontal
     * strips of equal height, each strip being a single colour and all three colours
     * different.
     */
    private static boolean hasUniformRowPattern(char[][] grid, int n, int m) {
        if (n % 3 != 0) {
            return false;                     // height must be divisible by 3
        }
        int partHeight = n / 3;

        // Colours of the three header cells (top‑left cell of each strip)
        char colorA = grid[0][0];
        char colorB = grid[partHeight][0];
        char colorC = grid[2 * partHeight][0];

        // The three colours must be pairwise different
        if (colorA == colorB || colorB == colorC || colorA == colorC) {
            return false;
        }

        // Verify uniformity inside each strip
        for (int part = 0; part < 3; part++) {
            char expected = switch (part) {
                case 0 -> colorA;
                case 1 -> colorB;
                default -> colorC;
            };
            int firstRow = part * partHeight;
            int lastRow = firstRow + partHeight;          // exclusive
            for (int r = firstRow; r < lastRow; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] != expected) {
                        return false;                     // non‑uniform cell found
                    }
                }
            }
        }
        return true;                                     // all strips are proper
    }

    /**
     * Checks whether the grid can be partitioned into three consecutive vertical
     * strips of equal width, each strip being a single colour and all three colours
     * different.
     */
    private static boolean hasUniformColumnPattern(char[][] grid, int n, int m) {
        if (m % 3 != 0) {
            return false;                     // width must be divisible by 3
        }
        int partWidth = m / 3;

        // Colours of the three header cells (top‑left cell of each vertical strip)
        char colorA = grid[0][0];
        char colorB = grid[0][partWidth];
        char colorC = grid[0][2 * partWidth];

        // The three colours must be pairwise different
        if (colorA == colorB || colorB == colorC || colorA == colorC) {
            return false;
        }

        // Verify uniformity inside each vertical strip
        for (int part = 0; part < 3; part++) {
            char expected = switch (part) {
                case 0 -> colorA;
                case 1 -> colorB;
                default -> colorC;
            };
            int firstCol = part * partWidth;
            int lastCol = firstCol + partWidth;          // exclusive
            for (int c = firstCol; c < lastCol; c++) {
                for (int r = 0; r < n; r++) {
                    if (grid[r][c] != expected) {
                        return false;                     // non‑uniform cell found
                    }
                }
            }
        }
        return true;                                     // all strips are proper
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Refactored solution that checks whether a given flag can be split into
 * three equal stripes of a single color each, with the three colors being
 * distinct. The stripes can be arranged either horizontally or vertically.
 *
 * The program follows modern Java coding practices:
 *  - Clear, expressive naming
 *  - Small, single‑responsibility methods
 *  - Early returns to simplify control flow
 *  - Constant‑time validation helpers
 *
 * Input format:
 *   row col
 *   row lines, each containing exactly col characters
 *
 * Output:
 *   "YES" if a valid arrangement exists, otherwise "NO"
 */
public class CodeForces {

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] header = br.readLine().split("\\s+");
            int rows = Integer.parseInt(header[0]);
            int cols = Integer.parseInt(header[1]);

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            System.out.println(isSolvable(grid, rows, cols) ? "YES" : "NO");
        }
    }

    /**
     * Determines whether the grid can be partitioned into three
     * equal stripes (horizontal or vertical) of a single color each,
     * where the three colors are all different.
     */
    private static boolean isSolvable(char[][] grid, int rows, int cols) {
        boolean rowDivisible = rows % 3 == 0;
        boolean colDivisible = cols % 3 == 0;

        // If neither dimension can host three equal stripes, it's impossible.
        if (!rowDivisible && !colDivisible) {
            return false;
        }

        // Try horizontal stripes if the number of rows permits.
        if (rowDivisible && tryHorizontalStripes(grid, rows, cols)) {
            return true;
        }

        // Try vertical stripes if the number of columns permits.
        return colDivisible && tryVerticalStripes(grid, rows, cols);
    }

    /**
     * Checks the horizontal‑stripe arrangement.
     */
    private static boolean tryHorizontalStripes(char[][] grid, int rows, int cols) {
        int subRow = rows / 3;
        char color1 = grid[0][0];
        char color2 = grid[subRow][0];
        char color3 = grid[2 * subRow][0];

        if (!areAllDifferent(color1, color2, color3)) {
            return false;
        }

        return stripeIsUniform(grid, 0, subRow, 0, cols, color1)
                && stripeIsUniform(grid, subRow, 2 * subRow, 0, cols, color2)
                && stripeIsUniform(grid, 2 * subRow, rows, 0, cols, color3);
    }

    /**
     * Checks the vertical‑stripe arrangement.
     */
    private static boolean tryVerticalStripes(char[][] grid, int rows, int cols) {
        int subCol = cols / 3;
        char color1 = grid[0][0];
        char color2 = grid[0][subCol];
        char color3 = grid[0][2 * subCol];

        if (!areAllDifferent(color1, color2, color3)) {
            return false;
        }

        return stripeIsUniform(grid, 0, rows, 0, subCol, color1)
                && stripeIsUniform(grid, 0, rows, subCol, 2 * subCol, color2)
                && stripeIsUniform(grid, 0, rows, 2 * subCol, cols, color3);
    }

    /**
     * Verifies that every cell in the given rectangular area contains the
     * same character as {@code expectedColor}.
     */
    private static boolean stripeIsUniform(char[][] grid,
                                           int start, int end,
                                           int startCol, int endCol,
                                           char expectedColor) {
        for (int r = start; r < end; r++) {
            for (int c = startCol; c < endCol; c++) {
                if (grid[r][c] != expectedColor) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Returns {@code true} if the three characters are pairwise distinct.
     */
    private static boolean areAllDifferent(char a, char b, char c) {
        return a != b && a != c && b != c;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored solution that checks whether a grid can be partitioned
 * into three equal groups, each using a distinct colour (R, G, B).
 */
public class Main {

    /** The three reference colour characters used to build the patterns. */
    private static final char[] COLORS = {'R', 'G', 'B'};

    public static void main(String[] args) {
        // Try‑with‑resources guarantees the scanner is closed automatically.
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();   // number of rows in the original grid
            int cols = scanner.nextInt();   // number of columns in the original grid

            // ---- Build the three reference patterns for rows and columns ----
            String[] rowPatterns = buildReferencePatterns(rows, cols);
            String[] colPatterns = buildReferencePatterns(cols, rows);

            // ---- Read the input grid (as rows) ----
            List<String> inputRows = readInputRows(rows, scanner);

            // Transpose the grid so we can also test the column‑oriented case.
            String[] transposed = transpose(inputRows);

            // ---- Validate either the original orientation or the transposed one ----
            if (isValidGrouping(inputRows, rowPatterns) ||
                isValidGrouping(transposed, colPatterns)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Creates three strings, each consisting of a single colour repeated {@code repeat} times. */
    private static String[] buildReferencePatterns(int length, int repeat) {
        String[] patterns = new String[3];
        for (int i = 0; i < 3; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < repeat; j++) {
                sb.append(COLORS[i]);
            }
            patterns[i] = sb.toString();
        }
        return patterns;
    }

    /** Reads {@code count} strings from the scanner – each represents a row of the grid. */
    private static List<String> readInputRows(int count, Scanner scanner) {
        List<String> rows = new ArrayList<>(count);
        for (int i = 0; i < count; i++) {
            rows.add(scanner.next());
        }
        return rows;
    }

    /** Transposes a grid that is supplied as a list of rows. */
    private static String[] transpose(List<String> rows) {
        int columnCount = rows.get(0).length();
        String[] result = new String[columnCount];
        for (int c = 0; c < columnCount; c++) {
            StringBuilder sb = new StringBuilder();
            for (String row : rows) {
                sb.append(row.charAt(c));
            }
            result[c] = sb.toString();
        }
        return result;
    }

    /**
     * Determines whether the supplied array can be split into three equal groups
     * that match the given reference patterns, with each group using a distinct colour.
     *
     * @return {@code true} if the arrangement satisfies the problem rules.
     */
    private static boolean isValidGrouping(String[] data, String[] patterns) {
        if (data.length % 3 != 0) {
            return false;                     // length must be divisible by three
        }

        int segmentSize = data.length / 3;
        String[] representatives = {
                data[0],
                data[segmentSize],
                data[2 * segmentSize]
        };

        // 1️⃣ The three representatives must contain each pattern exactly once
        //    and their first characters must be different.
        if (!containsAllPatterns(representatives, patterns)) {
            return false;
        }

        // 2️⃣ Every element in a segment must be identical to the segment's representative.
        for (int i = 0; i < data.length; i++) {
            int segmentIdx = i / segmentSize;
            if (!data[i].equals(representatives[segmentIdx])) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks that {@code candidates} contains each element of {@code patterns}
     * exactly once and that the first character of each used pattern is distinct.
     */
    private static boolean containsAllPatterns(String[] candidates, String[] patterns) {
        boolean[] found = new boolean[patterns.length];
        char[] leadingChars = new char[patterns.length];

        for (String cand : candidates) {
            boolean matched = false;
            for (int p = 0; p < patterns.length; p++) {
                if (cand.equals(patterns[p])) {
                    if (found[p]) {
                        // A pattern is used more than once → invalid.
                        return false;
                    }
                    found[p] = true;
                    matched = true;
                    leadingChars[p] = cand.charAt(0);
                    break;
                }
            }
            if (!matched) {
                return false; // candidate does not correspond to any pattern
            }
        }

        // Ensure the leading characters are all different.
        for (int i = 0; i < leadingChars.length; i++) {
            for (int j = i + 1; j < leadingChars.length; j++) {
                if (leadingChars[i] == leadingChars[j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;

/**
 * Refactored solution that checks whether a given character matrix can be split
 * into three equal‑sized uniform blocks either horizontally or vertically.
 *
 * The algorithm is identical to the original program, but the code has been
 * reorganised into small, well‑named methods, uses early returns and avoids the
 * mutable {@code is} flag, making it far easier to understand and maintain.
 */
public class PatternChecker {

    private static final Scanner SCANNER = new Scanner(System.in);

    /** Entry point – reads the data, runs the validation and prints the result. */
    public static void main(String[] args) {
        int rows = SCANNER.nextInt();
        int cols = SCANNER.nextInt();

        char[][] grid = readGrid(rows, cols);

        boolean ok = validatePattern(grid);
        System.out.println(ok ? "YES" : "NO");
    }

    /** Reads the {@code rows × cols} matrix from standard input. */
    private static char[][] readGrid(int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = SCANNER.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /** Main dispatcher – decides whether the matrix follows a horizontal or a
     *  vertical three‑stripe pattern. */
    private static boolean validatePattern(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;

        // t = length of the leading segment of the first row that consists of the
        // same character as the very first cell.
        int t = countLeadingUniformColumns(grid[0], grid[0][0]);

        // If the whole first row is uniform we are dealing with horizontal stripes,
        // otherwise we are dealing with vertical stripes.
        return (t == m) ? validateHorizontalStripes(grid, n, m)
                        : validateVerticalStripes(grid, n, m);
    }

    /** Returns the number of consecutive columns starting at index 0 that contain
     *  the same character as {@code target}. */
    private static int countLeadingUniformColumns(char[] row, char target) {
        int count = 1;                         // column 0 already matches
        for (int j = 1; j < row.length; j++) {
            if (row[j] == target) {
                count++;
            } else {
                break;
            }
        }
        return count;
    }

    /** Validates the “horizontal stripes” pattern – three equal‑height blocks,
     *  each filled with a single, distinct character. */
    private static boolean validateHorizontalStripes(char[][] grid, int n, int m) {
        // p = number of consecutive rows (starting at 0) whose first cell matches
        // the character of the first row.
        int p = countConsecutiveRowsStartingWith(grid, grid[0][0]);

        // We need exactly three blocks of equal height, therefore p must not
        // exceed one third of the total number of rows.
        if (p * 3 > n) {
            return false;
        }

        // k = number of following rows that are completely uniform with the
        // character found in row p (the second block's character).
        int k = countFollowingUniformRows(grid, p, grid[p][0]);

        // The second and third blocks must have the same size as the first one.
        if (k != p || n - k - p != p) {
            return false;
        }

        // All rows after the third block must be uniform with the character of
        // the third block.
        if (!verifyRemainingRowsUniform(grid, p + k, grid[p + k][0])) {
            return false;
        }

        // The character of the third block must differ from the first block's
        // character.
        if (grid[0][0] == grid[p + k][0]) {
            return false;
        }

        return true;
    }

    /** Counts how many consecutive rows starting at {@code startRow} are completely
     *  filled with {@code target}. The count stops at the first row that does not
     *  satisfy the condition. */
    private static int countFollowingUniformRows(char[][] grid, int startRow, char target) {
        int count = 0;
        for (int i = startRow; i < grid.length; i++) {
            if (grid[i][0] != target) {
                break;
            }
            if (!isRowUniform(grid[i], target)) {
                break;
            }
            count++;
        }
        return count;
    }

    /** Returns true if every cell of {@code row} equals {@code target}. */
    private static boolean isRowUniform(char[] row, char target) {
        for (char c : row) {
            if (c != target) {
                return false;
            }
        }
        return true;
    }

    /** Checks that all rows from {@code startRow} onward are uniform with
     *  {@code target}. */
    private static boolean verifyRemainingRowsUniform(char[][] grid, int startRow, char target) {
        for (int i = startRow; i < grid.length; i++) {
            if (!isRowUniform(grid[i], target)) {
                return false;
            }
        }
        return true;
    }

    /** Validates the “vertical stripes” pattern – three equal‑width blocks,
     *  each filled with a single, distinct character. */
    private static boolean validateVerticalStripes(char[][] grid, int n, int m) {
        // Re‑compute t – it is the length of the leading uniform segment of the
        // first row (the same value that the original program used).
        int t = countLeadingUniformColumns(grid[0], grid[0][0]);

        // The first t columns must be completely filled with the character
        // found at (0,0).
        if (!verifyFirstTColumnsUniform(grid, t, grid[0][0])) {
            return false;
        }

        // Every row must start with that character (i.e. the first column is
        // uniform across all rows).
        if (!allRowsStartWith(grid, grid[0][0])) {
            return false;
        }

        // We need at least three equal‑width blocks; the original code required
        // t*3 >= m, otherwise the pattern cannot be formed.
        if (t * 3 < m) {
            return false;
        }

        // Determine the size of the second block (k). It must be equal to t.
        int k = countFollowingUniformColumns(grid, t, grid[0][t]);

        // The three block sizes must be identical: t, k (=t), and the remaining
        // part.
        if (k != t || m - k - t != t) {
            return false;
        }

        // The remaining columns (after the third block) must be uniform with the
        // character at column t+k and must differ from the first column's
        // character.
        if (!verifyRemainingColumnsUniform(grid, t + k, grid[0][t + k])) {
            return false;
        }
        if (grid[0][0] == grid[0][t + k]) {
            return false;
        }

        return true;
    }

    /** Ensures that each of the first {@code t} columns is completely filled
     *  with {@code target}. */
    private static boolean verifyFirstTColumnsUniform(char[][] grid, int t, char target) {
        for (int col = 0; col < t; col++) {
            if (grid[0][col] != target) {
                return false;
            }
            if (!isColumnUniformWithTarget(grid, col, target)) {
                return false;
            }
        }
        return true;
    }

    /** Returns true if the whole column {@code col} consists of {@code target}. */
    private static boolean isColumnUniformWithTarget(char[][] grid, int col, char target) {
        for (int row = 0; row < grid.length; row++) {
            if (grid[row][col] != target) {
                return false;
            }
        }
        return true;
    }

    /** Counts how many consecutive columns starting at {@code startCol} are
     *  uniform with {@code target}. */
    private static int countFollowingUniformColumns(char[][] grid, int startCol, char target) {
        int count = 0;
        for (int col = startCol; col < grid[0].length; col++) {
            if (grid[0][col] != target) {
                break;
            }
            if (!isColumnUniformWithTarget(grid, col, target)) {
                break;
            }
            count++;
        }
        return count;
    }

    /** Checks that all columns from {@code startCol} onward are uniform with
     *  {@code target}. */
    private static boolean verifyRemainingColumnsUniform(char[][] grid, int startCol, char target) {
        for (int col = startCol; col < grid[0].length; col++) {
            if (!isColumnUniformWithTarget(grid, col, target)) {
                return false;
            }
        }
        return true;
    }

    /** Verifies that every row begins with the given {@code target} character. */
    private static boolean allRowsStartWith(char[][] grid, char target) {
        for (int row = 0; row < grid.length; row++) {
            if (grid[row][0] != target) {
                return false;
            }
        }
        return true;
    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;
import java.io.IOException;
import java.io.InputStream;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader sc, PrintWriter w) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] c = new char[n][m];
            for (int i = 0; i < n; i++) {
                c[i] = sc.next().toCharArray();
            }

            int total = n * m;
            if (total % 3 != 0) {
                w.println("NO");
                return;
            }
            int req = total / 3;

            int countR = 0, countG = 0, countB = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (c[i][j] == 'R') countR++;
                    else if (c[i][j] == 'G') countG++;
                    else if (c[i][j] == 'B') countB++;
                }
            }
            if (countR != countG || countR != countB) {
                w.println("NO");
                return;
            }

            if (n % 3 == 0) {
                int h = n / 3;
                if (isSolid(c, 0, h-1, 0, m-1) && 
                    isSolid(c, h, 2*h-1, 0, m-1) && 
                    isSolid(c, 2*h, 3*h-1, 0, m-1)) {
                    w.println("YES");
                    return;
                }
            }

            if (m % 3 == 0) {
                int w = m / 3;
                if (isSolid(c, 0, n-1, 0, w-1) && 
                    isSolid(c, 0, n-1, w, 2*w-1) && 
                    isSolid(c, 0, n-1, 2*w, 3*w-1)) {
                    w.println("YES");
                    return;
                }
            }

            w.println("NO");
        }

        private static boolean isSolid(char[][] grid, int r1, int r2, int c1, int c2) {
            char color = grid[r1][c1];
            for (int i = r1; i <= r2; i++) {
                for (int j = c1; j <= c2; j++) {
                    if (grid[i][j] != color) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();

            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }

                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();

            while (isSpaceChar(c))
                c = read();

            int sgn = 1;

            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            while (!isSpaceChar(c));

            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            }
            while (!isSpaceChar(c));

            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null)
                return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public String next() {
            return readString();
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the “Flag of Berland” checker.
 *
 * <p>This implementation focuses on readability, separation of concerns and
 * maintainability.  The algorithm is unchanged – it still verifies that the
 * input grid consists of exactly three equal‑sized stripes of the colours
 * Red, Blue and Green – but the code is now organized into small, well‑named
 * methods and uses expressive variable names.</p>
 */
public class FlagOfBerland {

    /** Scanner used for reading input. */
    private static final Scanner SCAN = new Scanner(System.in);

    /** Order of colours that must appear in the stripes (only used for counting). */
    private static final char[] EXPECTED_COLORS = {'R', 'B', 'G'};

    /** Entry point. */
    public static void main(String[] args) {
        int rows = readInt();
        int cols = readInt();
        char[][] grid = readGrid(rows);

        if (isHorizontalStripePattern(grid, rows, cols)) {
            System.out.println(evaluateOrientation(grid, rows, cols, true) ? "YES" : "NO");
        } else if (isVerticalStripePattern(grid, rows, cols)) {
            System.out.println(evaluateOrientation(grid, rows, cols, false) ? "YES" : "NO");
        } else {
            System.out.println("NO");
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Input handling helpers                                                */
    /* --------------------------------------------------------------------- */

    private static int readInt() {
        return SCAN.nextInt();
    }

    private static char[] readLineChars() {
        return SCAN.nextLine().toCharArray();
    }

    private static char[][] readGrid(int rows) {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = readLineChars();
        }
        return grid;
    }

    /* --------------------------------------------------------------------- */
    /*  Pattern detection                                                    */
    /* --------------------------------------------------------------------- */

    /** Checks whether the first row is completely uniform – a necessary condition
     *  for a horizontal‑stripe flag. */
    private static boolean isHorizontalStripePattern(char[][] grid, int rows, int cols) {
        char firstColor = grid[0][0];
        for (int c = 1; c < cols; c++) {
            if (grid[0][c] != firstColor) {
                return false;
            }
        }
        // Additional checks are performed later (equal height, correct colours)
        return true;
    }

    /** Checks whether the first column is completely uniform – a necessary condition
     *  for a vertical‑stripe flag. */
    private static boolean isVerticalStripePattern(char[][] grid, int rows, int cols) {
        char firstColor = grid[0][0];
        for (int r = 1; r < rows; r++) {
            if (grid[r][0] != firstColor) {
                return false;
            }
        }
        // Additional checks are performed later (equal width, correct colours)
        return true;
    }

    /* --------------------------------------------------------------------- */
    /*  Validation                                                            */
    /* --------------------------------------------------------------------- */

    /**
     * Determines whether the flag complies with the required stripe layout.
     *
     * @param grid       the whole grid
     * @param rows       number of rows
     * @param cols       number of columns
     * @param horizontal {@code true} if we are analysing a horizontal layout,
     *                   {@code false} for a vertical layout
     * @return {@code true} if the layout is valid, {@code false} otherwise
     */
    private static boolean evaluateOrientation(char[][] grid, int rows, int cols,
                                               boolean horizontal) {
        if (horizontal) {
            int stripeHeight = rows / 3;
            if (rows % 3 != 0) {
                return false;
            }
            return validateStripes(grid, rows, cols, stripeHeight, true);
        } else {
            int stripeWidth = cols / 3;
            if (cols % 3 != 0) {
                return false;
            }
            return validateStripes(grid, rows, cols, stripeWidth, false);
        }
    }

    /**
     * Validates that each stripe is monochrome, that the three stripe colours
     * are exactly {@code R}, {@code B} and {@code G} (each appearing once) and
     * that they appear in the required order.
     *
     * @param grid      the grid to validate
     * @param rows      total rows
     * @param cols      total columns
     * @param stripeSize size of a single stripe (height for horizontal, width for vertical)
     * @param isHorizontal {@code true} if stripes run horizontally
     * @return {@code true} when all conditions are satisfied
     */
    private static boolean validateStripes(char[][] grid, int rows, int cols,
                                           int stripeSize, boolean isHorizontal) {
        // Keep track of which colours we have already seen.
        boolean[] seen = new boolean[3];
        int colourIndex = 0; // maps to EXPECTED_COLORS

        for (int start = 0; start < (isHorizontal ? rows : cols); start += stripeSize) {
            char expectedColour = EXPECTED_COLORS[colourIndex % 3];
            if (!processStripe(grid, rows, cols, start, stripeSize,
                               isHorizontal, expectedColour, seen)) {
                return false;
            }
            colourIndex++;
        }

        // After three stripes each colour must have been seen exactly once.
        return seen[0] && seen[1] && seen[2];
    }

    /**
     * Checks a single stripe for uniformity and colour match.
     *
     * @return {@code true} if the stripe satisfies all rules, {@code false} otherwise
     */
    private static boolean processStripe(char[][] grid, int rows, int cols,
                                         int start, int stripeSize, boolean horizontal,
                                         char expectedColour, boolean[] seen) {
        if (horizontal) {
            // ----- Horizontal stripes -----
            // Each row belonging to the stripe must be uniform and equal to expectedColour.
            for (int r = start; r < start + stripeSize; r++) {
                char rowColour = grid[r][0];
                // The whole row must be the same colour.
                for (int c = 1; c < grid[r].length; c++) {
                    if (grid[r][c] != rowColour) {
                        return false;
                    }
                }
                if (rowColour != expectedColour) {
                    return false;
                }
                // Record that we have seen this colour.
                seen[expectedColour == 'R' ? 0 :
                     expectedColour == 'B' ? 1 : 2] = true;
            }
        } else {
            // ----- Vertical stripes -----
            // Each column belonging to the stripe must be uniform and equal to expectedColour.
            for (int c = start; c < start + stripeSize; c++) {
                char colColour = grid[0][c];
                for (int r = 1; r < rows; r++) {
                    if (grid[r][c] != colColour) {
                        return false;
                    }
                }
                if (colColour != expectedColour) {
                    return false;
                }
                seen[expectedColour == 'R' ? 0 :
                     expectedColour == 'B' ? 1 : 2] = true;
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.Objects;

/**
 * Entry point of the program. It reads a grid of characters, checks whether the grid can be
 * divided into three equal horizontal or vertical sections that each contain a single,
 * distinct character, and prints "YES" or "NO" accordingly.
 */
public class Main {

    /** Number of required sections (always 3 for this problem). */
    private static final int REQUIRED_SECTIONS = 3;

    /** Modulo constant kept for backward compatibility (not used in the current logic). */
    private static final long MOD = 1_000_000_007L;

    /** Console‑input / output helper. */
    private final ConsoleIO io;

    public Main(ConsoleIO io) {
        this.io = Objects.requireNonNull(io);
    }

    /** Program start – parses input, runs the checks and writes the result. */
    public static void main(String[] args) throws IOException {
        ConsoleIO io = new ConsoleIO(new InputStreamReader(System.in), new PrintWriter(System.out));
        new Main(io).solve();
        io.close();
    }

    /** Orchestrates the whole solution. */
    public void solve() {
        int[] dims = io.readIntArray();
        int rows = dims[0];
        int cols = dims[1];

        char[][] flag = readFlag(io, rows);

        if (canPartitionRows(flag, rows, cols)) {
            io.writeLine("YES");
            return;
        }

        if (canPartitionColumns(flag, rows, cols)) {
            io.writeLine("YES");
            return;
        }

        io.writeLine("NO");
    }

    /** Reads the character grid from the console. */
    private static char[][] readFlag(ConsoleIO io, int rows) throws IOException {
        char[][] flag = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = io.readLine().trim();
            flag[i] = line.toCharArray();
        }
        return flag;
    }

    /** Checks whether the grid can be split into three equal horizontal sections. */
    private static boolean canPartitionRows(char[][] flag, int rows, int cols) {
        if (rows % REQUIRED_SECTIONS != 0) {
            return false;
        }
        int sectionSize = rows / REQUIRED_SECTIONS;

        // Each section must consist of a single, distinct character.
        char[] sectionChar = new char[REQUIRED_SECTIONS];

        for (int sectionIdx = 0; sectionIdx < REQUIRED_SECTIONS; sectionIdx++) {
            int baseRow = sectionIdx * sectionSize;
            char expected = flag[baseRow][0];
            sectionChar[sectionIdx] = expected;

            for (int r = 0; r < rows; r++) {
                int curSection = r / sectionSize;
                if (flag[r][0] != expected) {
                    return false;                     // row does not belong to the expected character
                }
                // No other section may share the same character.
                for (int other = 0; other < REQUIRED_SECTIONS; other++) {
                    if (other != curSection && sectionChar[other] == expected) {
                        return false;                 // duplicate character between sections
                    }
                }
            }
        }
        return true;
    }

    /** Checks whether the grid can be split into three equal vertical sections. */
    private static boolean canPartitionColumns(char[][] flag, int rows, int cols) {
        if (cols % REQUIRED_SECTIONS != 0) {
            return false;
        }
        int sectionSize = cols / REQUIRED_SECTIONS;

        char[] sectionChar = new char[REQUIRED_SECTIONS];

        for (int sectionIdx = 0; sectionIdx < REQUIRED_SECTIONS; sectionIdx++) {
            int baseCol = sectionIdx * sectionSize;
            char expected = flag[0][baseCol];
            sectionChar[sectionIdx] = expected;

            for (int c = 0; c < cols; c++) {
                int curSection = c / sectionSize;
                if (flag[0][c] != expected) {
                    return false;                     // column does not belong to the expected character
                }
                // No other section may share the same character.
                for (int other = 0; other < REQUIRED_SECTIONS; other++) {
                    if (other != curSection && sectionChar[other] == expected) {
                        return false;                 // duplicate character between sections
                    }
                }
            }
        }
        return true;
    }
}

/**
 * Simple wrapper around {@link BufferedReader} and {@link PrintWriter} that provides
 * convenience methods used by {@link Main}.
 */
class ConsoleIO {
    private final BufferedReader br;
    private final PrintWriter out;

    public ConsoleIO(Reader reader, PrintWriter writer) {
        this.br = new BufferedReader(reader);
        this.out = writer;
    }

    public void flush() {
        out.flush();
    }

    public void close() {
        out.close();
    }

    public void writeLine(String s) {
        out.println(s);
    }

    public void writeInt(int a) {
        out.print(a);
        out.print(' ');
    }

    public void writeWord(String s) {
        out.print(s);
    }

    public void writeIntArray(int[] a, int k, String separator) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < k; i++) {
            if (i > 0) sb.append(separator);
            sb.append(a[i]);
        }
        writeLine(sb.toString());
    }

    public int read(char[] buf, int len) {
        try {
            return br.read(buf, 0, len);
        } catch (Exception e) {
            return -1;
        }
    }

    public String readLine() {
        try {
            return br.readLine();
        } catch (Exception e) {
            return "";
        }
    }

    public long[] readLongArray() {
        String[] parts = readLine().trim().split("\\s+");
        long[] arr = new long[parts.length];
        for (int i = 0; i < parts.length; i++) {
            arr[i] = Long.parseLong(parts[i]);
        }
        return arr;
    }

    public int[] readIntArray() {
        String[] parts = readLine().trim().split("\\s+");
        int[] arr = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            arr[i] = Integer.parseInt(parts[i]);
        }
        return arr;
    }

    public int[] readIntArray(int n) {
        int[] res = new int[n];
        char[] all = readLine().toCharArray();
        int cur = 0;
        boolean have = false;
        int k = 0;
        boolean neg = false;

        for (char ch : all) {
            if (ch >= '0' && ch <= '9') {
                cur = cur * 10 + (ch - '0');
                have = true;
            } else if (ch == '-') {
                neg = true;
            } else if (have) {
                res[k++] = neg ? -cur : cur;
                cur = 0;
                have = false;
                neg = false;
            }
        }
        if (have) {
            res[k++] = neg ? -cur : cur;
        }
        return res;
    }

    public int ri() {
        try {
            int r = 0;
            boolean start = false;
            boolean neg = false;
            while (true) {
                int c = br.read();
                if (c >= '0' && c <= '9') {
                    r = r * 10 + (c - '0');
                    start = true;
                } else if (!start && c == '-') {
                    start = true;
                    neg = true;
                } else if (start || c == -1) {
                    return neg ? -r : r;
                }
            }
        } catch (Exception e) {
            return -1;
        }
    }

    public long readLong() {
        try {
            long r = 0;
            boolean start = false;
            boolean neg = false;
            while (true) {
                int c = br.read();
                if (c >= '0' && c <= '9') {
                    r = r * 10 + (c - '0');
                    start = true;
                } else if (!start && c == '-') {
                    start = true;
                    neg = true;
                } else if (start || c == -1) {
                    return neg ? -r : r;
                }
            }
        } catch (Exception e) {
            return -1;
        }
    }

    public String readWord() {
        try {
            boolean start = false;
            StringBuilder sb = new StringBuilder();
            while (true) {
                int c = br.read();
                if (c != ' ' && c != '\r' && c != '\n' && c != '\t') {
                    sb.append((char) c);
                    start = true;
                } else if (start || c == -1) {
                    return sb.toString();
                }
            }
        } catch (Exception e) {
            return "";
        }
    }

    public char readSymbol() {
        try {
            while (true) {
                int c = br.read();
                if (c != ' ' && c != '\r' && c != '\n' && c != '\t') {
                    return (char) c;
                }
            }
        } catch (Exception e) {
            return 0;
        }
    }
}

import java.util.Scanner;

/**
 * BEdu – determines whether a given grid consists of uniform rows or columns
 * whose colours (R, B, G) are evenly distributed.
 *
 * The original program performed the same check but mixed I/O and processing
 * logic, used meaningless identifiers and hard‑coded magic numbers.  The
 * refactor separates concerns, introduces expressive names, removes duplication,
 * and adds minimal comments for clarity.
 */
public class BEdu {

    /** colours that are counted */
    private enum Colour {
        RED('R'),
        BLUE('B'),
        GREEN('G');

        private final char symbol;
        Colour(char symbol) { this.symbol = symbol; }
        public char getSymbol() { return symbol; }
        public static Colour fromChar(char c) {
            for (Colour v : values()) {
                if (v.symbol == c) return v;
            }
            throw new IllegalArgumentException("Unsupported colour: " + c);
        }
    }

    /** prints YES if either rows or columns satisfy the specification */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();   // n
            int cols = scanner.nextInt();   // m
            scanner.nextLine();             // consume end‑of‑line

            String[] grid = readRows(scanner, rows);

            boolean rowsAreConsistent = analyseRows(grid);
            boolean colsAreConsistent = analyseColumns(grid, rows, cols);

            System.out.println(rowsAreConsistent || colsAreConsistent ? "YES" : "NO");
        }
    }

    /** reads exactly {@code n} lines from the scanner, each representing a row. */
    private static String[] readRows(Scanner scanner, int n) {
        String[] rows = new String[n];
        for (int i = 0; i < n; i++) {
            rows[i] = scanner.nextLine();
        }
        return rows;
    }

    /**
     * Evaluates whether every row consists of a single repeated character,
     * the colour counts are equal, and the rows appear in grouped blocks
     * (i.e. all rows of the same colour are consecutive).
     * @return true if the described row condition holds
     */
    private static boolean analyseRows(String[] grid) {
        final int redRows = countUniformColour(grid, Colour.RED.symbol);
        final int blueRows = countUniformColour(grid, Colour.BLUE.symbol);
        final int greenRows = countUniformColour(grid, Colour.GREEN.symbol);

        boolean allRowsUniform = rowsHaveNoVariation(grid);
        boolean colourCountsEqualAndBalanced = redRows == blueRows && blueRows == greenRows;

        // Verify that rows of each colour appear in a single consecutive block.
        boolean blockStructureValid = verifyConsecutiveBlocks(grid, redRows, blueRows, greenRows);

        return allRowsUniform && colourCountsEqualAndBalanced && blockStructureValid;
    }

    /**
     * Analyses each column in the same fashion as {@code analyseRows()} but
     * treats columns as the primary structures.
     * @return true if the column condition holds
     */
    private static boolean analyseColumns(String[] grid, int rows, int cols) {
        final int redCols = countUniformColourByColumn(grid, rows, Colour.RED.symbol);
        final int blueCols = countUniformColourByColumn(grid, rows, Colour.BLUE.symbol);
        final int greenCols = countUniformColourByColumn(grid, rows, Colour.GREEN.symbol);

        boolean allColsUniform = columnsHaveNoVariation(grid, rows, cols);
        boolean colourCountsEqualAndBalanced = redCols == blueCols && blueCols == greenCols;

        boolean blockStructureValid = verifyConsecutiveBlocksByColumn(grid, rows, cols,
                redCols, blueCols, greenCols);

        return allColsUniform && colourCountsEqualAndBalanced && blockStructureValid;
    }

    /** Count how many rows start with the given colour symbol and consist of that symbol only. */
    private static int countUniformColour(String[] grid, char symbol) {
        int cnt = 0;
        for (String row : grid) {
            if (row.charAt(0) == symbol) {
                cnt++;
            }
        }
        return cnt;
    }

    /** Count how many columns start with the given colour symbol and consist of that symbol only. */
    private static int countUniformColourByColumn(String[] grid, int rows, char symbol) {
        int cnt = 0;
        for (int col = 0; col < grid[0].length(); col++) {
            if (grid[0].charAt(col) == symbol) {
                cnt++;
            }
        }
        return cnt;
    }

    /** Returns true if every row has identical characters throughout. */
    private static boolean rowsHaveNoVariation(String[] grid) {
        for (String row : grid) {
            for (int i = 0; i < row.length() - 1; i++) {
                if (row.charAt(i) != row.charAt(i + 1)) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Returns true if every column has identical characters throughout. */
    private static boolean columnsHaveNoVariation(String[] grid, int rows, int cols) {
        for (int col = 0; col < cols; col++) {
            for (int row = 0; row < rows - 1; row++) {
                if (grid[row].charAt(col) != grid[row + 1].charAt(col)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks that the rows of each colour appear in a single contiguous block.
     * The method mirrors the original “pattern verification” code.
     */
    private static boolean verifyConsecutiveBlocks(String[] grid,
                                                    int redCount,
                                                    int blueCount,
                                                    int greenCount) {
        int expectedRunLengths[] = { redCount, blueCount, greenCount };
        // The order of colours matters – we preserve the order they appear.
        return verifyPattern(grid, expectedRunLengths);
    }

    /**
     * Checks that the columns of each colour appear in a single contiguous block.
     * Mirrors column‑specific verification logic.
     */
    private static boolean verifyConsecutiveBlocksByColumn(String[] grid,
                                                             int rows,
                                                             int cols,
                                                             int redCount,
                                                             int blueCount,
                                                             int greenCount) {
        int expectedRunLengths[] = { redCount, blueCount, greenCount };
        return verifyPatternByColumn(grid, rows, expectedRunLengths);
    }

    /**
     * Replicates the original loop that validates a pattern of repeated
     * characters in a string.  It returns true if the observed runs match the
     * supplied expected run lengths.
     */
    private static boolean verifyPattern(String[] source, int[] expectedRuns) {
        if (expectedRuns == null || expectedRuns.length == 0) {
            return false;
        }

        // The pattern we validate must start at the first row.
        String current = source[0];
        int runIdx = 0;
        int runLen = 0;
        int pos = 0;

        while (pos < source.length) {
            char firstChar = source[pos].charAt(0);
            int sameCount = 0;
            while (pos < source.length && source[pos].charAt(0) == firstChar) {
                sameCount++;
                pos++;
            }

            if (runLen == 0) {
                // first run length computed
                runLen = sameCount;
            } else {
                // compare with the next expected run length (which is derived from the first run length)
                if (runLen != expectedRuns[runIdx]) {
                    return false;
                }
                runLen = sameCount;
                runIdx++;
            }
        }

        // Final comparison with the last expected run length
        return runIdx < expectedRuns.length && runLen == expectedRuns[runIdx];
    }

    /**
     * Replicates column‑specific verification of runs of identical characters.
     */
    private static boolean verifyPatternByColumn(String[] source,
                                                 int rows,
                                                 int[] expectedRuns) {
        // Build column strings (each column becomes a pseudo‑row)
        StringBuilder[] columns = new StringBuilder[source[0].length()];
        for (int i = 0; i < columns.length; i++) {
            columns[i] = new StringBuilder();
        }
        for (String row : source) {
            for (int col = 0; col < row.length(); col++) {
                columns[col].append(row.charAt(col));
            }
        }

        // Run verification mirrors the row version but works on each column string.
        int colIdx = 0;
        for (String colStr : columns) {
            if (!verifySinglePattern(colStr, expectedRuns, colIdx)) {
                return false;
            }
            colIdx++;
        }
        return true;
    }

    /** Helper for column pattern verification – similar to {@code verifyPattern}. */
    private static boolean verifySinglePattern(String pattern,
                                                int[] expectedRuns,
                                                int runIdx) {
        int runLen = 0;
        int pos = 0;
        while (pos < pattern.length()) {
            char first = pattern.charAt(pos);
            int count = 0;
            while (pos < pattern.length() && pattern.charAt(pos) == first) {
                count++;
                pos++;
            }
            if (runLen == 0) {
                runLen = count;
            } else if (runLen != expectedRuns[runIdx]) {
                return false;
            }
            runLen = count;
            runIdx++;
        }
        return runIdx < expectedRuns.length && runLen == expectedRuns[runIdx];
    }
}

import java.io.DataInputStream;
import java.io.IOException;

/**
 * Reads input quickly and solves the problem of checking whether a rectangular
 * flag can be divided into three equal bands of the same colour either
 * horizontally or vertically.
 *
 * The refactor focuses on readability, reduced duplication and clearer
 * separation of concerns.
 */
public class E26b {

    /** Fast I/O wrapper around {@link System.in}. */
    private static final class FastScanner {
        private final DataInputStream din;
        private final byte[] buffer;
        private int pointer, bytes;

        FastScanner() {
            din = new DataInputStream(System.in);
            buffer = new byte[1 << 16];
            pointer = bytes = 0;
        }

        /** Read next byte, filling the buffer when necessary. */
        private int readByte() throws IOException {
            if (pointer >= bytes) {
                bytes = din.read(buffer);
                pointer = 0;
                if (bytes <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        /** Reads a whitespace‑separated token as an {@code int}. */
        int nextInt() throws IOException {
            int value = 0;
            int sign = 1;
            int c;
            // skip whitespace
            while ((c = readByte()) <= ' ') {
                if (c == -1) return 0;
            }
            // handle sign
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            // read digits
            do {
                value = value * 10 + (c - '0');
            } while ((c = readByte()) >= '0' && c <= '9');
            return value * sign;
        }

        /** Reads the next whitespace‑separated token as a {@code String}. */
        String next() throws IOException {
            int c;
            // skip whitespace
            while ((c = readByte()) <= ' ') {
                if (c == -1) return "";
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
            } while ((c = readByte()) > ' ');
            return sb.toString();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int rows = fs.nextInt();
        int cols = fs.nextInt();

        String[] flag = new String[rows];
        for (int i = 0; i < rows; i++) {
            flag[i] = fs.next();
        }

        System.out.println(solve(rows, cols, flag) ? "YES" : "NO");
    }

    /** Main solving routine – returns true if a valid division exists. */
    private static boolean solve(int n, int m, String[] flag) {
        // Try horizontal split
        if (n % 3 == 0 && checkHorizontal(flag, n, m)) {
            return true;
        }
        // Try vertical split
        if (m % 3 == 0 && checkVertical(flag, n, m)) {
            return true;
        }
        return false;
    }

    /** Checks whether the flag can be split into three equal *horizontal* bands. */
    private static boolean checkHorizontal(String[] flag, int n, int m) {
        final int h = n / 3;
        final char[] colours = new char[3];

        colours[0] = flag[0].charAt(0);
        for (int r = 1; r < h; r++) {
            if (flag[r].charAt(0) != colours[0]) return false;
        }

        colours[1] = flag[h].charAt(0);
        for (int r = h + 1; r < 2 * h; r++) {
            if (flag[r].charAt(0) != colours[1]) return false;
        }

        colours[2] = flag[2 * h].charAt(0);
        for (int r = 2 * h + 1; r < n; r++) {
            if (flag[r].charAt(0) != colours[2]) return false;
        }

        // All three bands must have distinct colours
        return colours[0] != colours[1] &&
               colours[1] != colours[2] &&
               colours[2] != colours[0];
    }

    /** Checks whether the flag can be split into three equal *vertical* bands. */
    private static boolean checkVertical(String[] flag, int n, int m) {
        final int w = m / 3;
        final char[] colours = new char[3];

        colours[0] = flag[0].charAt(0);
        for (int c = 1; c < w; c++) {
            if (flag[0].charAt(c) != colours[0]) return false;
        }
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < w; c++) {
                if (flag[r].charAt(c) != colours[0]) return false;
            }
        }

        colours[1] = flag[0].charAt(w);
        for (int c = w + 1; c < 2 * w; c++) {
            if (flag[0].charAt(c) != colours[1]) return false;
        }
        for (int r = 0; r < n; r++) {
            for (int c = w; c < 2 * w; c++) {
                if (flag[r].charAt(c) != colours[1]) return false;
            }
        }

        colours[2] = flag[0].charAt(2 * w);
        for (int c = 2 * w + 1; c < m; c++) {
            if (flag[0].charAt(c) != colours[2]) return false;
        }
        for (int r = 0; r < n; r++) {
            for (int c = 2 * w; c < m; c++) {
                if (flag[r].charAt(c) != colours[2]) return false;
            }
        }

        // Distinctness of the three colours
        return colours[0] != colours[1] &&
               colours[1] != colours[2] &&
               colours[2] != colours[0];
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.EnumSet;
import java.util.Set;

/**
 * Verifies whether a given grid represents a valid Berland flag.
 * The flag consists of three equal‑size stripes (horizontal or vertical)
 * colored only with the three basic colors: R, G and B.
 */
public class BerlandFlag {

    /** The three allowed flag colors. */
    private enum Color {
        R, G, B;

        static Color fromChar(char c) {
            switch (c) {
                case 'R': return R;
                case 'G': return G;
                case 'B': return B;
                default:  throw new IllegalArgumentException("Invalid color: " + c);
            }
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String[] dimLine = readNonEmptyLine(reader);
            int rows = Integer.parseInt(dimLine[0]);
            int cols = Integer.parseInt(dimLine[1]);

            char[][] grid = readGrid(reader, rows);

            if (isValidFlag(grid, rows, cols)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Reads a non‑empty line from the reader (skips blank lines). */
    private static String readNonEmptyLine(BufferedReader reader) throws IOException {
        String line;
        while ((line = reader.readLine()) != null && line.trim().isEmpty()) {
            // ignore accidental blank lines
        }
        if (line == null) {
            throw new IOException("Unexpected end of input");
        }
        return line;
    }

    /** Reads exactly {@code rows} lines and converts each to a char array. */
    private static char[][] readGrid(BufferedReader reader, int rows) throws IOException {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = readNonEmptyLine(reader);
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /** Determines whether the given grid forms a valid flag. */
    private static boolean isValidFlag(char[][] grid, int rows, int cols) {
        // Flag dimensions must be divisible by 3 in at least one direction.
        boolean rowsDivisible = rows % 3 == 0;
        boolean colsDivisible = cols % 3 == 0;

        if (!rowsDivisible && !colsDivisible) {
            return false;
        }

        // Collect the set of colors that appear as stripe representatives.
        Set<Color> foundColors = EnumSet.noneOf(Color.class);

        // Try horizontal stripes first (if possible).
        if (rowsDivisible) {
            if (checkHorizontalStripePattern(grid, rows, cols, foundColors)) {
                return foundColors.equals(EnumSet.of(Color.R, Color.G, Color.B));
            }
            // If horizontal failed but columns are also divisible, try vertical.
            if (colsDivisible) {
                return checkVerticalStripePattern(grid, rows, cols, foundColors);
            }
        } else if (colsDivisible) {
            // Only vertical stripes are possible.
            return checkVerticalStripePattern(grid, rows, cols, foundColors);
        }

        return false; // unreachable but keeps the compiler happy
    }

    /**
     * Checks whether the grid consists of horizontal stripes of equal height.
     * The representative color of each stripe is recorded in {@code foundColors}.
     *
     * @return {@code true} if the pattern matches and all three colors are present.
     */
    private static boolean checkHorizontalStripePattern(
            char[][] grid, int rows, int cols, Set<Color> foundColors) {

        int stripeHeight = rows / 3;
        for (int start = 0; start < rows; start += stripeHeight) {
            Color stripeColor = determineStripeColor(grid, start, 0, stripeHeight, cols);
            // Validate that the whole stripe uses the same color.
            if (!validateStripeColor(grid, start, stripeHeight, stripeColor, cols)) {
                return false;
            }
            foundColors.add(stripeColor);
        }
        return true;
    }

    /**
     * Checks whether the grid consists of vertical stripes of equal width.
     * The representative color of each stripe is recorded in {@code foundColors}.
     *
     * @return {@code true} if the pattern matches and all three colors are present.
     */
    private static boolean checkVerticalStripePattern(
            char[][] grid, int rows, int cols, Set<Color> foundColors) {

        int stripeWidth = cols / 3;
        for (int start = 0; start < cols; start += stripeWidth) {
            Color stripeColor = determineStripeColor(grid, 0, start, rows, stripeWidth);
            // Validate that the whole stripe uses the same color.
            if (!validateStripeColor(grid, start, stripeWidth, stripeColor, rows)) {
                return false;
            }
            foundColors.add(stripeColor);
        }
        return true;
    }

    /**
     * Determines the expected color of a stripe.
     * The stripe is identified by its first cell (rowOffset, colOffset).
     *
     * @param grid        the whole flag array
     * @param rowOffset   row index of the first cell in the stripe
     * @param colOffset   column index of the first cell in the stripe
     * @param dim         dimension (height or width) of the stripe
     * @param otherDim    dimension orthogonal to the stripe (unused here)
     * @return the {@link Color} of the stripe's top‑left cell
     */
    private static Color determineStripeColor(char[][] grid, int rowOffset, int colOffset,
                                               int dim, int otherDim) {
        return Color.fromChar(grid[rowOffset][colOffset]);
    }

    /**
     * Verifies that an entire stripe consists of a single color.
     *
     * @param grid      the flag array
     * @param startIdx  starting index of the stripe (row or column)
     * @param stripeLen length of the stripe (height or width)
     * @param expected  the color that the stripe should have
     * @param size      number of cells that must match {@code expected}
     * @return {@code true} if every cell in the stripe matches {@code expected}
     */
    private static boolean validateStripeColor(char[][] grid, int startIdx,
                                                int stripeLen, Color expected,
                                                int size) {
        for (int i = 0; i < stripeLen; i++) {
            int index = startIdx + i;
            for (int j = 0; j < size; j++) {
                char actual = grid[index][j];
                if (actual != expected.name().charAt(0)) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

public class BerlandFlag {

    /** All colours that are allowed for a valid flag. */
    private static final Set<Character> ALLOWED_COLORS = Set.of('R', 'B', 'G');

    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees the BufferedReader is closed.
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in))) {

            // ----- read header -------------------------------------------------
            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            // ----- read the flag matrix ---------------------------------------
            char[][] flag = readFlag(br, n, m);

            if (!isFullyAllowed(flag)) {
                System.out.println("NO");
                return;
            }

            // ----- decide orientation of stripes ---------------------------------
            boolean horizontalPossible = n % 3 == 0;
            boolean verticalPossible   = m % 3 == 0;

            if (horizontalPossible && checkHorizontal(flag, n / 3)) {
                System.out.println("YES");
                return;
            }
            if (verticalPossible && checkVertical(flag, m / 3)) {
                System.out.println("YES");
                return;
            }
            System.out.println("NO");
        }
    }

    /** Reads exactly *n* lines of length *m* from the reader. */
    private static char[][] readFlag(BufferedReader br, int n, int m) throws IOException {
        char[][] flag = new char[n][m];
        String line;
        for (int i = 0; i < n; i++) {
            line = br.readLine();
            if (line == null || line.length() != m) {
                throw new IllegalArgumentException("Invalid input dimensions");
            }
            for (int j = 0; j < m; j++) {
                char ch = line.charAt(j);
                // Validate colour immediately – fails fast.
                if (!ALLOWED_COLORS.contains(ch)) {
                    throw new IllegalArgumentException();
                }
                flag[i][j] = ch;
            }
        }
        return flag;
    }

    /** Checks that every cell contains only the allowed colours. */
    private static boolean isFullyAllowed(char[][] flag) {
        for (char[] row : flag) {
            for (char ch : row) {
                if (!ALLOWED_COLORS.contains(ch)) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Validates three horizontal stripes of equal height. */
    private static boolean checkHorizontal(char[][] flag, int stripeHeight) {
        int rows = flag.length;
        int cols = flag[0].length;
        Set<Character> stripeColors = new HashSet<>();

        for (int k = 0; k < 3; k++) {
            int startRow = k * stripeHeight;
            char expected = flag[startRow][0];
            stripeColors.add(expected);
            if (!isUniform(flag, startRow, 0, startRow + stripeHeight, cols, expected)) {
                return false;
            }
        }
        return stripeColors.size() == 3; // three distinct colours
    }

    /** Validates three vertical stripes of equal width. */
    private static boolean checkVertical(char[][] flag, int stripeWidth) {
        int rows = flag.length;
        int cols = flag[0].length;
        Set<Character> stripeColors = new HashSet<>();

        for (int k = 0; k < 3; k++) {
            int startCol = k * stripeWidth;
            char expected = flag[0][startCol];
            stripeColors.add(expected);
            if (!isUniform(flag, 0, startCol, rows, startCol + stripeWidth, expected)) {
                return false;
            }
        }
        return stripeColors.size() == 3; // three distinct colours
    }

    /** Helper that verifies a sub‑rectangle contains only *expectedColor*. */
    private static boolean isUniform(char[][] flag,
                                     int startRow, int startCol,
                                     int endRow, int endCol,
                                     char expectedColor) {
        for (int r = startRow; r < endRow; r++) {
            for (int c = startCol; c < endCol; c++) {
                if (flag[r][c] != expectedColor) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for the flag‑pattern validation problem.
 *
 * <p>
 * The program reads the dimensions of a grid and the grid itself, then decides whether
 * it consists of exactly three contiguous stripes of equal colour, each stripe covering
 * the whole height or the whole width of the grid. The three colours must be 'R', 'G' and
 * 'B' (in any order) and each stripe must be monochromatic.
 * </p>
 */
public class Main {

    public static void main(String[] args) {
        // Using try‑with‑resources guarantees that resources are closed even on exceptions.
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            solve(reader, writer);
        }
    }

    /**
     * Core logic of the program – separated from {@code main} for easier testing and
     * maintainability.
     */
    private static void solve(BufferedReader reader, PrintWriter writer) throws IOException {
        // -------------------------------------------------------------------------
        // 1️⃣  Input reading
        // -------------------------------------------------------------------------
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        int rows = Integer.parseInt(tokenizer.nextToken());
        int cols = Integer.parseInt(tokenizer.nextToken());

        char[][] grid = readGrid(reader, rows, cols);

        // -------------------------------------------------------------------------
        // 2️⃣  Determine stripe dimensions
        // -------------------------------------------------------------------------
        int stripeHeight = determineStripeHeight(grid);
        int stripeWidth  = determineStripeWidth(grid);

        // -------------------------------------------------------------------------
        // 3️⃣  Validate the overall configuration
        // -------------------------------------------------------------------------
        if (!isValidStripeConfiguration(rows, cols, stripeHeight, stripeWidth)) {
            writer.println("NO");
            return;
        }

        // -------------------------------------------------------------------------
        // 4️⃣  Validate colour pattern and monochrome property of each stripe
        // -------------------------------------------------------------------------
        if (!isValidColourPattern(grid, stripeHeight, stripeWidth)) {
            writer.println("NO");
            return;
        }

        // -------------------------------------------------------------------------
        // 5️⃣  All checks passed
        // -------------------------------------------------------------------------
        writer.println("YES");
    }

    /** Reads the grid from the input stream. */
    private static char[][] readGrid(BufferedReader reader, int rows, int cols) throws IOException {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = reader.readLine();
            if (line == null || line.length() != cols) {
                throw new IllegalArgumentException("Invalid line length for row " + i);
            }
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /** Returns the height of a vertical stripe – the number of consecutive rows that
     * share the same colour as the first row in column 0. */
    private static int determineStripeHeight(char[][] grid) {
        char firstColour = grid[0][0];
        int height = 0;
        outerHeightLoop:
        for (int i = 0; i < grid.length; i++) {
            if (grid[i][0] != firstColour) {
                break outerHeightLoop;
            }
            height++;
        }
        return height;
    }

    /** Returns the width of a horizontal stripe – the number of consecutive columns that
     * share the same colour as the first column in row 0. */
    private static int determineStripeWidth(char[][] grid) {
        char firstColour = grid[0][0];
        int width = 0;
        outerWidthLoop:
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[0][j] != firstColour) {
                break outerWidthLoop;
            }
            width++;
        }
        return width;
    }

    /** Checks whether the stripe dimensions can fill the whole canvas with exactly three stripes. */
    private static boolean isValidStripeConfiguration(
            int totalRows, int totalCols, int height, int width) {

        // At least one dimension must span the entire canvas.
        boolean spansFullHeight   = height == totalRows;
        boolean spansFullWidth    = width  == totalCols;

        if (!(spansFullHeight || spansFullWidth)) {
            return false;
        }

        // The whole canvas must contain exactly three stripes of the computed size.
        long totalCellsExpected = 3L * height * width;
        return totalCellsExpected == (long) totalRows * totalCols;
    }

    /** Verifies that each stripe is monochromatic, that the three colours are distinct,
     * and that all three colours appear exactly once. */
    private static boolean isValidColourPattern(char[][] grid, int height, int width) {
        boolean seenRed    = false;
        boolean seenGreen  = false;
        boolean seenBlue   = false;

        for (int stripeIdx = 0; stripeIdx < 3; stripeIdx++) {
            // Starting cell of the current stripe.
            int startRow = (height == grid.length) ? 0 : stripeIdx * height;
            int startCol = (width  == grid[0].length) ? 0 : stripeIdx * width;

            char currentChar = grid[startRow][startCol];

            // Ensure the colour has not been used before.
            if (currentChar == 'R' && seenRed)    return false;
            if (currentChar == 'G' && seenGreen)  return false;
            if (currentChar == 'B' && seenBlue)   return false;
            seenRed  = seenRed  || currentChar == 'R';
            seenGreen= seenGreen|| currentChar == 'G';
            seenBlue = seenBlue || currentChar == 'B';

            // Verify monochrome property inside the stripe.
            for (int r = startRow; r < startRow + height; r++) {
                for (int c = startCol; c < startCol + width; c++) {
                    if (grid[r][c] != currentChar) {
                        return false;
                    }
                }
            }
        }

        // All three colours must be present.
        return seenRed && seenGreen && seenBlue;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads an {@code n × m} grid of characters (only R, G, B are relevant).
 * It then evaluates two different patterns:
 *
 * <ul>
 *   <li>Row‑first pattern – each row must consist of a single repeated character.
 *       If rows are uniform we examine the lengths of consecutive runs of the first
 *       character of each row.</li>
 *   <li>Column‑first pattern – if rows are not uniform we look at the columns.
 *       If a column contains different characters we perform a similar run‑length
 *       analysis on the first row.</li>
 * </ul>
 *
 * <p>If the computed run‑length list contains exactly three equal values and the
 * total counts of {@code 'R'}, {@code 'G'} and {@code 'B'} are all equal, the program
 * prints {@code "YES"}; otherwise it prints {@code "NO"}.</p>
 */
public class Main {

    /** Characters we are interested in. */
    private static final char RED = 'R';
    private static final char GREEN = 'G';
    private static final char BLUE = 'B';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rowsCount = scanner.nextInt();          // n
            int colsCount = scanner.nextInt();          // m (not used directly)
            scanner.nextLine();                         // consume remaining newline

            List<String> grid = readRows(rowsCount, scanner);
            long redCount = countChar(grid, RED);
            long greenCount = countChar(grid, GREEN);
            long blueCount = countChar(grid, BLUE);

            if (evaluateRowFirstPattern(grid, redCount, greenCount, blueCount)) {
                System.out.println("YES");
                return;
            }
            if (evaluateColumnFirstPattern(grid, redCount, greenCount, blueCount)) {
                System.out.println("YES");
                return;
            }
            System.out.println("NO");
        }
    }

    /** Reads exactly {@code count} lines from the scanner and stores them in a list. */
    private static List<String> readRows(int count, Scanner scanner) {
        List<String> lines = new ArrayList<>(count);
        for (int i = 0; i < count; i++) {
            String line = scanner.nextLine().trim();
            lines.add(line);
        }
        return lines;
    }

    /** Counts occurrences of {@code target} in the whole grid. */
    private static long countChar(List<String> grid, char target) {
        long cnt = 0;
        for (String row : grid) {
            for (int i = 0; i < row.length(); i++) {
                if (row.charAt(i) == target) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /**
     * Evaluates the *row‑first* pattern.
     *
     * <ul>
     *   <li>All rows must consist of a single repeated character.</li>
     *   <li>From these rows we build a list of run‑lengths of equal first characters
     *       of consecutive rows.</li>
     *   <li>The pattern is valid only when the run‑length list contains exactly three
     *       equal values and the colour counts are equal.</li>
     * </ul>
     */
    private static boolean evaluateRowFirstPattern(List<String> grid,
                                                    long red, long green, long blue) {
        if (!allRowsUniform(grid)) {
            // Row uniformity failed – switch to column‑first analysis.
            return evaluateColumnFirstPattern(grid, red, green, blue);
        }

        List<Integer> runLengths = computeRowRunLengths(grid);
        boolean adjacentRunsDiffer = hasAdjacentDifferent(runLengths);
        return !adjacentRunsDiffer && runLengths.size() == 3 && red == green && green == blue;
    }

    /**
     * Evaluates the *column‑first* pattern.
     *
     * <ul>
     *   <li>Each column must contain identical characters vertically.</li>
     *   <li>If any column breaks this uniformity we fall back to a run‑length
     *       analysis on the first row (mirroring the original program).</li>
     *   <li>Validation works the same way as in the row‑first case.</li>
     * </ul>
     */
    private static boolean evaluateColumnFirstPattern(List<String> grid,
                                                       long red, long green, long blue) {
        int maxColumn = grid.get(0).length(); // assume rectangular input

        // Verify column uniformity
        for (int col = 0; col < maxColumn; col++) {
            for (int row = 0; row < grid.size() - 1; row++) {
                if (grid.get(row).charAt(col) != grid.get(row + 1).charAt(col)) {
                    // Non‑uniform column – perform column‑based run analysis
                    return analyzeColumnRunPattern(grid, red, green, blue);
                }
            }
        }

        // All columns uniform – use the first row for run‑length computation
        List<Integer> runLengths = computeRowRunLengthsFromFirstRow(grid);
        boolean adjacentRunsDiffer = hasAdjacentDifferent(runLengths);
        return !adjacentRunsDiffer && runLengths.size() == 3 && red == green && green == blue;
    }

    /** Checks whether every row consists of a single repeated character. */
    private static boolean allRowsUniform(List<String> grid) {
        for (String row : grid) {
            if (!isUniform(row)) {
                return false;
            }
        }
        return true;
    }

    /** Returns {@code true} if the row contains identical adjacent characters only. */
    private static boolean isUniform(String row) {
        for (int i = 0; i < row.length() - 1; i++) {
            if (row.charAt(i) != row.charAt(i + 1)) {
                return false;
            }
        }
        return true;
    }

    /** Computes run‑lengths of equal first characters among consecutive rows. */
    private static List<Integer> computeRowRunLengths(List<String> grid) {
        List<Integer> lengths = new ArrayList<>();
        int currentRun = 1;
        for (int i = 1; i < grid.size(); i++) {
            if (grid.get(i).charAt(0) == grid.get(i - 1).charAt(0)) {
                currentRun++;
            } else {
                lengths.add(currentRun);
                currentRun = 1;
            }
        }
        lengths.add(currentRun);
        return lengths;
    }

    /** Computes run‑lengths on the first row (used when columns are uniform). */
    private static List<Integer> computeRowRunLengthsFromFirstRow(List<String> grid) {
        String firstRow = grid.get(0);
        List<Integer> lengths = new ArrayList<>();
        int run = 1;
        for (int i = 1; i < firstRow.length(); i++) {
            if (firstRow.charAt(i) == firstRow.charAt(i - 1)) {
                run++;
            } else {
                lengths.add(run);
                run = 1;
            }
        }
        lengths.add(run);
        return lengths;
    }

    /** True if the list contains at least one pair of adjacent values that differ. */
    private static boolean hasAdjacentDifferent(List<Integer> values) {
        for (int i = 0; i < values.size() - 1; i++) {
            if (!values.get(i).equals(values.get(i + 1))) {
                return true;
            }
        }
        return false;
    }

    /** Analyzes column runs (fallback when a column is non‑uniform). */
    private static boolean analyzeColumnRunPattern(List<String> grid,
                                                    long red, long green, long blue) {
        // The original logic examined the first row's character runs;
        // we replicate that here.
        String reference = grid.get(0);
        List<Integer> lengths = new ArrayList<>();
        int run = 1;
        for (int i = 1; i < reference.length(); i++) {
            if (reference.charAt(i) == reference.charAt(i - 1)) {
                run++;
            } else {
                lengths.add(run);
                run = 1;
            }
        }
        lengths.add(run);

        boolean adjacentDifferent = false;
        for (int i = 0; i < lengths.size() - 1; i++) {
            if (!lengths.get(i).equals(lengths.get(i + 1))) {
                adjacentDifferent = true;
                break;
            }
        }
        return !adjacentDifferent && lengths.size() == 3 && red == green && green == blue;
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Reads a matrix of characters (only ‘R’, ‘G’, ‘B’) and decides whether the
 * cells of each colour can be grouped together either by whole rows or by
 * whole columns.  The original algorithm is kept, but the code has been
 * reorganised for readability, maintainability and proper naming.
 */
public class BannerChecker {

    /** Scanner used for fast input reading. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer;
        private final char[] charBuffer;
        private int ptr = 0;          // next position in {@code buffer}
        private int bytes = 0;         // number of valid bytes in {@code buffer}
        private static final byte EOF = -1;

        public FastScanner(InputStream stream) {
            this(stream, 1 << 16, 1 << 8);
        }

        private void fill() throws IOException {
            if (ptr >= bytes) {
                ptr = 0;
                bytes = stream.read(buffer);
                if (bytes <= 0) {
                    bytes = EOF;
                }
            }
        }

        /** Skips over characters until a byte larger than {@code limit} is found. */
        private void skip(byte limit) throws IOException {
            while (true) {
                fill();
                if (bytes == EOF) return;
                while (ptr < bytes && buffer[ptr] <= limit) {
                    ptr++;
                }
            }
        }

        /** Reads the next whitespace‑separated token as a {@code char[]}. */
        public char[] nextArr() throws IOException {
            skip(' ');
            if (bytes == EOF) return null;

            int len = 0;
            while (true) {
                fill();
                if (bytes == EOF) break;
                while (ptr < bytes && buffer[ptr] > ' ') {
                    if (len == charBuffer.length) expand();
                    charBuffer[len++] = (char) buffer[ptr++];
                }
                break;
            }
            return Arrays.copyOf(charBuffer, len);
        }

        /** Reads the next line as a {@code char[]}. */
        public char[] nextLineArr() throws IOException {
            int len = 0;
            while (true) {
                fill();
                if (bytes == EOF) break;
                while (ptr < bytes && buffer[ptr] != '\n') {
                    if (len == charBuffer.length) expand();
                    charBuffer[len++] = (char) buffer[ptr++];
                }
                if (ptr < bytes && buffer[ptr] == '\n') {
                    ptr++;                       // consume '\n'
                }
                break;
            }
            return Arrays.copyOf(charBuffer, len);
        }

        /** Reads the next integer from the input. */
        public int nextInt() throws IOException {
            skip(' ');
            if (bytes == EOF) throw new IOException();

            boolean negative = buffer[ptr] == '-';
            if (negative) ptr++;

            int value = 0;
            while (true) {
                fill();
                if (bytes == EOF) break;
                while (ptr < bytes && buffer[ptr] >= '0' && buffer[ptr] <= '9') {
                    value = value * 10 + (buffer[ptr] - '0');
                    ptr++;
                }
                if (!(ptr < bytes && buffer[ptr] >= '0' && buffer[ptr] <= '9')) {
                    break;
                }
            }
            return negative ? -value : value;
        }

        private void expand() {
            char[] larger = new char[charBuffer.length << 1];
            System.arraycopy(charBuffer, 0, larger, 0, charBuffer.length);
            charBuffer = larger;
        }
    }

    /** Returns the first position of {@code ch} inside {@code matrix}. */
    private static int[] firstPosition(char[][] matrix, char ch) {
        for (int r = 0; r < matrix.length; r++) {
            for (int c = 0; c < matrix[r].length; c++) {
                if (matrix[r][c] == ch) {
                    return new int[]{r, c};
                }
            }
        }
        return null;                // never reached for valid input
    }

    /**
     * Checks whether a rectangular block that starts at {@code startRow},
     * {@code startCol} and consists of the character {@code target}
     * contains exactly {@code required} cells before any other character appears.
     * The scan follows row‑major order.
     */
    private static boolean isTargetBlockValid(char[][] matrix,
                                              int startRow,
                                              int startCol,
                                              char target,
                                              int required) {
        int found = 0;
        for (int r = startRow; r < matrix.length; r++) {
            for (int c = 0; c < matrix[r].length; c++) {
                char cur = matrix[r][c];
                if (cur == target) {
                    found++;
                    if (found == required) {
                        return true;          // collected the needed amount
                    }
                } else {
                    return false;           // unexpected colour before we gathered enough
                }
            }
        }
        return false;                       // ran out of cells
    }

    /** Validates the “row‑wise” grouping condition. */
    private static boolean validateRows(char[][] grid,
                                        int[][] colourStarts,
                                        int count) {
        // The three colour‑start entries are used in the fixed order R → G → B
        return isTargetBlockValid(grid, colourStarts[0][0], 0, 'R', count) &&
               isTargetBlockValid(grid, colourStarts[1][0], 0, 'G', count) &&
               isTargetBlockValid(grid, colourStarts[2][0], 0, 'B', count);
    }

    /** Validates the “column‑wise” grouping condition. */
    private static boolean validateColumns(char[][] grid,
                                           int[][] colourStarts,
                                           int count) {
        // R → G → B again, now scanning column‑wise
        return isTargetBlockValid(grid, 0, colourStarts[0][1], 'R', count) &&
               isTargetBlockValid(grid, 0, colourStarts[1][1], 'G', count) &&
               isTargetBlockValid(grid, 0, colourStarts[2][1], 'B', count);
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);

        int rows = fs.nextInt();
        int cols = fs.nextInt();

        char[][] board = new char[rows][];
        int countR = 0, countG = 0, countB = 0;

        for (int r = 0; r < rows; r++) {
            String line = new String(fs.nextArr());
            board[r] = line.toCharArray();
            for (char ch : board[r]) {
                switch (ch) {
                    case 'R' -> countR++;
                    case 'G' -> countG++;
                    case 'B' -> countB++;
                }
            }
        }

        // All three colours must occur the same number of times.
        if (countR != countG || countG != countB) {
            System.out.println("NO");
            return;
        }
        int commonCount = countR;               // number of cells of each colour

        int[] rPos = firstPosition(board, 'R');
        int[] gPos = firstPosition(board, 'G');
        int[] bPos = firstPosition(board, 'B');

        boolean byRows = validateRows(board,
                                      new int[][]{rPos, gPos, bPos},
                                      commonCount);
        boolean byCols = validateColumns(board,
                                         new int[][]{rPos, gPos, bPos},
                                         commonCount);

        System.out.println((byRows || byCols) ? "YES" : "NO");
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point – reads input, runs the solution and prints the result.
 */
public class Main {

    public static void main(String[] args) {
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            FastScanner scanner = new FastScanner(in);
            PrintWriter writer = new PrintWriter(out);

            TaskB solver = new TaskB();
            solver.solve(scanner, writer);

            writer.flush();   // close is delegated to the PrintWriter's try‑with‑resources
        }
    }

    /** Simple fast scanner that works with the original input format. */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokeniser;

        FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        private void ensureTokeniser() throws IOException {
            while (tokeniser == null || tokeniser.hasMoreTokens()) {
                tokeniser = new StringTokenizer(reader.readLine());
            }
        }

        int nextInt() throws IOException {
            ensureTokeniser();
            return Integer.parseInt(tokeniser.nextToken());
        }

        String next() throws IOException {
            ensureTokeniser();
            return tokeniser.nextToken();
        }
    }

    /**
     * Core logic – validates the matrix against the required stripe pattern.
     */
    private static class TaskB {

        /** Order in which the three colours must appear in a valid stripe. */
        private static final List<Character> EXPECTED_ORDER = List.of('R', 'G', 'B');

        /** Checks whether a collection of rows forms a valid horizontal stripe pattern. */
        private boolean isValidHorizontalPattern(char[][] grid, int rows, int cols) {
            int stripeSize = rows / EXPECTED_ORDER.size();
            if (stripeSize * EXPECTED_ORDER.size() != rows) {
                return false; // number of rows must be divisible by 3
            }

            int colourIndex = 0;
            for (int r = 0; r < rows; r++) {
                char expectedColour = EXPECTED_ORDER.get(colourIndex);
                if (!isRowUniform(grid[r], expectedColour)) {
                    return false;
                }
                // after stripeSize rows we must move to the next colour in the order
                if ((r + 1) % stripeSize == 0 && ++colourIndex == EXPECTED_ORDER.size()) {
                    colourIndex = 0; // start over only when we have processed all three stripes
                }
            }
            // All colours must have been used exactly the same number of times
            return colourIndex == 0;
        }

        /** Checks whether a collection of columns forms a valid vertical stripe pattern. */
        private boolean isValidVerticalPattern(char[][] grid, int rows, int cols) {
            int stripeSize = cols / EXPECTED_ORDER.size();
            if (stripeSize * EXPECTED_ORDER.size() != cols) {
                return false; // number of columns must be divisible by 3
            }

            int colourIndex = 0;
            for (int c = 0; c < cols; c++) {
                char expectedColour = EXPECTED_ORDER.get(colourIndex);
                // traverse the whole column and verify uniform colour
                for (int r = 0; r < rows; r++) {
                    if (grid[r][c] != expectedColour) {
                        return false;
                    }
                }
                if ((c + 1) % stripeSize == 0 && ++colourIndex == EXPECTED_ORDER.size()) {
                    colourIndex = 0;
                }
            }
            return colourIndex == 0;
        }

        /** Returns true iff every element of the row is equal to {@code expected}. */
        private static boolean isRowUniform(char[] row, char expected) {
            for (char cell : row) {
                if (cell != expected) {
                    return false;
                }
            }
            return true;
        }

        /** Solves the problem – reads input, validates and prints YES/NO. */
        void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();          // number of rows
            int m = in.nextInt();          // number of columns

            char[][] grid = readGrid(in, n, m);

            boolean horizontalOk = isValidHorizontalPattern(grid, n, m);
            boolean verticalOk   = isValidVerticalPattern(grid, n, m);

            out.println((horizontalOk && verticalOk) ? "YES" : "NO");
        }

        /** Reads an n×m grid of characters from the scanner. */
        private static char[][] readGrid(FastScanner in, int n, int m) {
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = in.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }
    }
}

import java.io.*;
import java.util.*;

public class E26_B {

    /* -------------------------------------------------------------
     *  Entry point
     * ------------------------------------------------------------- */
    public static void main(String[] args) {
        new E26_B().run();
    }

    /* -------------------------------------------------------------
     *  Core workflow
     * ------------------------------------------------------------- */
    private FastScanner scanner;
    private PrintWriter printer;

    private static final char LETTER_A = 'A';

    private void run() {
        try (FastScanner fs = new FastScanner();
             PrintWriter out = new PrintWriter(
                     new BufferedWriter(new OutputStreamWriter(System.out)))) {
            scanner = fs;
            printer = out;
            solve();
        }
    }

    private void solve() {
        int rows = scanner.nextInt();   // n
        int cols = scanner.nextInt();   // m
        String[] grid = readGrid(rows);

        if (areAllRowsUniform(grid)) {
            processHorizontalPattern(grid);
            return;
        }

        if (areAllColumnsUniform(grid)) {
            processVerticalPattern(grid);
            return;
        }

        printer.println("NO");
    }

    /* -------------------------------------------------------------
     *  Input handling
     * ------------------------------------------------------------- */
    private String[] readGrid(int rows) {
        String[] grid = new String[rows];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next();
        }
        return grid;
    }

    /* -------------------------------------------------------------
     *  Uniform‑row / uniform‑column detection
     * ------------------------------------------------------------- */
    private boolean areAllRowsUniform(String[] grid) {
        for (String row : grid) {
            if (!isRowUniform(row)) {
                return false;
            }
        }
        return true;
    }

    private boolean areAllColumnsUniform(String[] grid) {
        int rows = grid.length;
        int cols = grid[0].length();

        for (int col = 0; col < cols; col++) {
            if (!isColumnUniform(grid, col)) {
                return false;
            }
        }
        return true;
    }

    private boolean isRowUniform(String row) {
        for (int i = 1; i < row.length(); i++) {
            if (row.charAt(i) != row.charAt(i - 1)) {
                return false;
            }
        }
        return true;
    }

    private boolean isColumnUniform(String[] grid, int col) {
        for (int r = 1; r < grid.length; r++) {
            if (grid[r - 1].charAt(col) != grid[r].charAt(col)) {
                return false;
            }
        }
        return true;
    }

    /* -------------------------------------------------------------
     *  Pattern validation (horizontal & vertical)
     * ------------------------------------------------------------- */
    private void processHorizontalPattern(String[] grid) {
        if (!isDivisibleByThree(grid.length)) {
            printer.println("NO");
            return;
        }

        int segmentSize = grid.length / 3;
        boolean[] used = new boolean[26];
        boolean failure = false;

        for (int start = 0; start < grid.length; start += segmentSize) {
            char expected = grid[start].charAt(0);
            if (used[expected - LETTER_A]) {
                failure = true;
                break;
            }
            for (int i = start; i < start + segmentSize; i++) {
                if (grid[i].charAt(0) != expected) {
                    failure = true;
                    break;
                }
            }
            used[expected - LETTER_A] = true;
        }

        printer.println(failure ? "NO" : "YES");
    }

    private void processVerticalPattern(String[] grid) {
        int totalCols = grid[0].length();
        if (!isDivisibleByThree(totalCols)) {
            printer.println("NO");
            return;
        }

        int segmentSize = totalCols / 3;
        boolean[] used = new boolean[26];
        boolean failure = false;

        for (int start = 0; start < totalCols; start += segmentSize) {
            char expected = grid[0].charAt(start);
            if (used[expected - LETTER_A]) {
                failure = true;
                break;
            }
            for (int j = start; j < start + segmentSize; j++) {
                if (grid[0].charAt(j) != expected) {
                    failure = true;
                    break;
                }
            }
            used[expected - LETTER_A] = true;
        }

        printer.println(failure ? "NO" : "YES");
    }

    private boolean isDivisibleByThree(int value) {
        return value % 3 == 0;
    }

    /* -------------------------------------------------------------
     *  Fast scanner utilities
     * ------------------------------------------------------------- */
    private static class FastScanner {
        private StringTokenizer st;
        private BufferedReader br;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Scanner;

/**
 * Validates a rectangular grid of characters.
 *
 * <p>The grid is valid when:
 *
 * <ul>
 *   <li>All rows have the same length.</li>
 *   <li>The total number of 'R', 'G' and 'B' characters are equal.</li>
 *   <li>The grid consists either of horizontal or vertical stripes where
 *       each stripe is a single uniform colour and at most three distinct
 *       colours are used, each colour occupying the same number of stripes.</li>
 * </ul>
 *
 * <p>If the conditions are met the program prints {@code YES}, otherwise
 * {@code NO}.
 */
public class GridValidator {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = readInt(scanner, "Number of rows: ");
            String[] inputGrid = readRows(scanner, rows);
            if (validate(inputGrid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Reads {@code n} complete lines from the scanner. */
    private static String[] readRows(Scanner scanner, int n) {
        String[] rows = new String[n];
        for (int i = 0; i < n; i++) {
            rows[i] = scanner.nextLine();
        }
        return rows;
    }

    /** Reads a non‑negative integer from the scanner. */
    private static int readInt(Scanner scanner, String prompt) {
        while (true) {
            String token = scanner.next();
            try {
                return Integer.parseInt(token);
            } catch (NumberFormatException ignored) {
                System.out.print("Please enter a valid integer: ");
            }
        }
    }

    /**
     * Core validation routine.
     *
     * @param grid array of strings representing the grid
     * @return {@code true} if the grid satisfies all rules
     */
    private static boolean validate(String[] grid) {
        if (!consistentLength(grid)) {
            return false;
        }
        if (!balancedColours(grid)) {
            return false;
        }
        return isHorizontalStripes(grid) || isVerticalStripes(grid);
    }

    /** All rows must have the same number of columns. */
    private static boolean consistentLength(String[] grid) {
        int cols = grid[0].length();
        for (String row : grid) {
            if (row.length() != cols) {
                return false;
            }
        }
        return true;
    }

    /** The whole grid must contain the same amount of R, G and B. */
    private static boolean balancedColours(String[] grid) {
        int r = 0, g = 0, b = 0;
        for (String row : grid) {
            for (int i = 0; i < row.length(); i++) {
                switch (row.charAt(i)) {
                    case 'R' -> r++;
                    case 'G' -> g++;
                    case 'B' -> b++;
                    default -> {
                        // any other character makes the grid invalid
                        return false;
                    }
                }
            }
        }
        return r == g && g == b;
    }

    /** Checks for a pattern of horizontal uniform stripes. */
    private static boolean isHorizontalStripes(String[] grid) {
        int cols = grid[0].length();
        Map<Character, Integer> colourRowCount = new LinkedHashMap<>();

        // first stripe
        char firstColour = grid[0].charAt(0);
        if (!isUniformRow(grid[0], cols, firstColour)) {
            return false;
        }
        colourRowCount.put(firstColour, 1);

        // subsequent stripes
        for (int i = 1; i < grid.length; i++) {
            String row = grid[i];
            char colour = row.charAt(0);
            if (!isUniformRow(row, cols, colour)) {
                return false;
            }
            colourRowCount.merge(colour, 1, Integer::sum);
            if (colourRowCount.size() > 3) {
                return false;   // more than three distinct colours are not allowed
            }
        }

        // exactly three colours and each occupies the same number of rows
        return colourRowCount.size() == 3 && equalValues(colourRowCount);
    }

    /** Checks for a pattern of vertical uniform stripes. */
    private static boolean isVerticalStripes(String[] grid) {
        int rows = grid.length;
        int cols = grid[0].length();

        // Build column strings
        StringBuilder[] columns = new StringBuilder[cols];
        for (int c = 0; c < cols; c++) {
            columns[c] = new StringBuilder();
        }
        for (String row : grid) {
            for (int c = 0; c < cols; c++) {
                columns[c].append(row.charAt(c));
            }
        }

        // Apply the same logic as for horizontal stripes on the column view
        Map<Character, Integer> colourRowCount = new LinkedHashMap<>();

        char firstColour = columns[0].charAt(0);
        if (!isUniformRow(columns[0].toString(), rows, firstColour)) {
            return false;
        }
        colourRowCount.put(firstColour, 1);

        for (int c = 1; c < cols; c++) {
            String col = columns[c].toString();
            char colour = col.charAt(0);
            if (!isUniformRow(col, rows, colour)) {
                return false;
            }
            colourRowCount.merge(colour, 1, Integer::sum);
            if (colourRowCount.size() > 3) {
                return false;
            }
        }

        return colourRowCount.size() == 3 && equalValues(colourRowCount);
    }

    /** True if a string consists of the same character repeated {@code length} times. */
    private static boolean isUniformRow(String candidate, int length, char expected) {
        return candidate.equals(String.valueOf(expected).repeat(length));
    }

    /** Returns {@code true} if all values in the map are equal. */
    private static boolean equalValues(Map<?, ?> map) {
        java.util.Iterator<?> it = map.values().iterator();
        if (!it.hasNext()) {
            return false;
        }
        int first = (int) it.next();
        while (it.hasNext()) {
            if (first != (int) it.next()) {
                return false;
            }
        }
        return true;
    }
}

import java.util.Scanner;

/**
 * Refactored solution that checks whether the input grid satisfies
 * either the row‑wise or column‑wise “three‑block” pattern described in the
 * original program.  The logic is now split into small, well‑named methods,
 * making the code easier to read, test, and maintain.
 */
public class Solution {

    public static void main(String[] args) {
        // Try‑with‑resources ensures the scanner is closed automatically.
        try (Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();   // number of strings (rows)
            int m = sc.nextInt();   // length of each string (columns)

            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next();
            }

            boolean rowsOk = validateRows(grid);
            boolean colsOk = validateColumns(grid, m);

            System.out.print((rowsOk || colsOk) ? "YES" : "NO");
        }
    }

    /**
     * Checks the row condition:
     * <ul>
     *   <li>the number of rows must be a multiple of 3;</li>
     *   <li>the first character of the first string of each third must be distinct;</li>
     *   <li>every character in the corresponding block must match the expected character.</li>
     * </ul>
     *
     * @return {@code true} if the row condition holds, otherwise {@code false}.
     */
    private static boolean validateRows(String[] rows) {
        if (rows.length % 3 != 0) {
            return false;
        }
        final int term = rows.length / 3;

        // Expected characters for the three blocks (must be pairwise distinct)
        char exp0 = rows[term - 1].charAt(0);
        char exp1 = rows[2 * term - 1].charAt(0);
        char exp2 = rows[3 * term - 1].charAt(0);

        if (exp0 == exp1 || exp1 == exp2 || exp2 == exp0) {
            return false;
        }

        // Verify each block contains only its expected character
        return allCharsInBlock(rows, 0, term, exp0) &&
               allCharsInBlock(rows, term, term, exp1) &&
               allCharsInBlock(rows, 2 * term, term, exp2);
    }

    /**
     * Checks the column condition in the same spirit as {@link #validateRows}
     * but operates on columns of the grid.
     *
     * @param rows   the array of strings (each string is a row)
     * @param cols   the length of each string (number of columns)
     * @return {@code true} if the column condition holds, otherwise {@code false}.
     */
    private static boolean validateColumns(String[] rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }
        final int term = cols / 3;

        // Expected characters for the three column blocks (must be distinct)
        char exp0 = rows[0].charAt(term - 1);
        char exp1 = rows[0].charAt(2 * term - 1);
        char exp2 = rows[0].charAt(3 * term - 1);

        if (exp0 == exp1 || exp1 == exp2 || exp2 == exp0) {
            return false;
        }

        // Verify each column block contains only its expected character
        return allCharsInColumn(rows, 0, term, exp0) &&
               allCharsInColumn(rows, term, term, exp1) &&
               allCharsInColumn(rows, 2 * term, term, exp2);
    }

    /**
     * Checks that every character in the specified block of rows equals
     * {@code expectedChar}.
     *
     * @param rows       array of strings representing the grid
     * @param startRow   first row index of the block (inclusive)
     * @param blockSize  number of consecutive rows in the block
     * @param expectedChar character that all cells in the block must have
     * @return {@code true} if the block is uniform with respect to {@code expectedChar}
     */
    private static boolean allCharsInBlock(String[] rows, int startRow, int blockSize, char expectedChar) {
        for (int i = startRow; i < startRow + blockSize; i++) {
            String row = rows[i];
            for (int j = 0; j < row.length(); j++) {
                if (row.charAt(j) != expectedChar) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks that every character in the specified block of columns equals
     * {@code expectedChar}.
     *
     * @param rows       array of strings representing the grid
     * @param startCol   first column index of the block (inclusive)
     * @param blockSize  number of consecutive columns in the block
     * @param expectedChar character that all cells in the block must have
     * @return {@code true} if the block is uniform with respect to {@code expectedChar}
     */
    private static boolean allCharsInColumn(String[] rows, int startCol, int blockSize, char expectedChar) {
        for (int j = startCol; j < startCol + blockSize; j++) {
            for (int i = 0; i < rows.length; i++) {
                if (rows[i].charAt(j) != expectedChar) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;

/**
 * Reads a matrix of characters and decides whether it can be split into three
 * equal blocks that satisfy the following rules:
 *
 * <ul>
 *   <li>If the first row (or column) consists of a single repeated character,
 *       the dimension that varies (row‑wise or column‑wise) must be divisible
 *       by 3.</li>
 *   <li>Each of the three blocks must contain a distinct colour on its
 *       outermost element (first column for row‑wise, first row for column‑wise).</li>
 *   <li>All elements inside a block must be identical.</li>
 * </ul>
 *
 * The program prints {@code YES} when the matrix fulfills the conditions,
 * otherwise {@code NO}.
 */
public class Main {

    /** Entry point. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = readGrid(scanner, rows, cols);

            // The problem only makes sense when at least one dimension is a multiple of 3.
            if (!isDivisibleByThree(rows, cols)) {
                System.out.println("NO");
                return;
            }

            if (isRowConstant(grid)) {
                if (!validateGroupedGrid(grid, true)) {
                    System.out.println("NO");
                    return;
                }
                System.out.println("YES");
            } else {
                if (!validateGroupedGrid(grid, false)) {
                    System.out.println("NO");
                    return;
                }
                System.out.println("YES");
            }
        }
    }

    /** Reads {@code rows × cols} characters from the scanner. */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /** Returns {@code true} if either rows or cols (or both) is divisible by 3. */
    private static boolean isDivisibleByThree(int... values) {
        for (int v : values) {
            if (v % 3 == 0) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks whether the first row is made of a single repeated character.
     * This signals a row‑wise analysis.
     */
    private static boolean isRowConstant(char[][] grid) {
        char first = grid[0][0];
        for (int c = 1; c < grid[0].length; c++) {
            if (grid[0][c] != first) {
                return false;
            }
        }
        return true;
    }

    /**
     * Validates the three block constraints assuming the scan direction is
     * {@code rowBased} (true → row‑wise, false → column‑wise).
     */
    private static boolean validateGroupedGrid(char[][] grid, boolean rowBased) {
        final int blockSize = rowBased ? grid.length / 3 : grid[0].length / 3;
        final boolean isColumnCheck = !rowBased; // when rowBased is false we look at columns

        // ---- 1. Outer‑most element of each block must be distinct ----
        char block0 = outerElement(grid, rowBased, 0, blockSize);
        char block1 = outerElement(grid, rowBased, 1, blockSize);
        char block2 = outerElement(grid, rowBased, 2, blockSize);

        if (block0 == block1 || block0 == block2 || block1 == block2) {
            return false; // colours must be pairwise different
        }

        // ---- 2. Every element inside each block must be identical ----
        return verifyUniformBlocks(grid, rowBased, blockSize);
    }

    /**
     * Retrieves the character that represents the outermost element of a block.
     * <p>
     * For a row‑based scan the outer element is the last element of each block
     * in the first column; for a column‑based scan it is the last element of
     * each block in the first row.
     */
    private static char outerElement(char[][] grid, boolean rowBased,
                                     int blockIndex, int blockSize) {
        if (rowBased) {
            int row = blockIndex * blockSize + blockSize - 1; // last row of the block
            return grid[row][0];
        } else {
            int col = blockIndex * blockSize + blockSize - 1; // last column of the block
            return grid[0][col];
        }
    }

    /**
     * Checks that all cells inside each block are identical.
     * It iterates over each block and ensures every cell equals its predecessor.
     */
    private static boolean verifyUniformBlocks(char[][] grid,
                                               boolean rowBased,
                                               int blockSize) {
        int totalBlocks = 3;

        for (int b = 0; b < totalBlocks; b++) {
            int start = b * blockSize;
            int end = start + blockSize; // exclusive

            if (rowBased) {
                // iterate over columns inside the block
                for (int c = start + 1; c < end; c++) {
                    if (grid[start][c] != grid[start][c - 1]) {
                        return false;
                    }
                }
            } else {
                // iterate over rows inside the block
                for (int r = start + 1; r < end; r++) {
                    if (grid[r][start] != grid[r - 1][start]) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.HashSet;
import java.util.Set;

/**
 * Entry point of the application.
 */
public class Main {

    public static void main(String[] args) {
        InputStream in = System.in;
        PrintWriter out = new PrintWriter(System.out);
        InputScanner scanner = new InputScanner(in);
        Solver solver = new Solver();

        solver.solve(scanner, out);
        out.close();
    }
}

/**
 * Simple scanner that reads tokens from an {@link InputStream}.
 */
final class InputScanner {

    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputScanner(InputStream source) {
        this.reader = new BufferedReader(new InputStreamReader(source));
    }

    /** Reads the next line from the underlying reader (named for clarity). */
    private String readLine() {
        try {
            return reader.readLine();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Returns {@code true} if there are still unread tokens. */
    boolean hasNext() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = readLine();
            if (line == null) {
                return false;
            }
            tokenizer = new StringTokenizer(line);
        }
        return true;
    }

    /** Retrieves the next token. */
    String next() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        return tokenizer.nextToken();
    }

    /** Reads the next integer token. */
    int nextInt() {
        return Integer.parseInt(next());
    }

    /**
     * Reads a rectangular character table of the given dimensions.
     *
     * @param rows    number of rows
     * @param columns number of columns per row
     * @return a 2‑dimensional {@code char}`[][] array representing the table
     */
    char[][] nextCharTable(int rows, int columns) {
        char[][] table = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = next();
            table[r] = line.toCharArray();
            if (table[r].length != columns) {
                throw new IllegalArgumentException(
                        "Row " + r + " length (" + table[r].length +
                                ") does not match expected columns (" + columns + ")");
            }
        }
        return table;
    }
}

/**
 * Contains the core solving logic.
 */
final class Solver {

    /**
     * Entry point used by {@link Main}.
     *
     * @param scanner input scanner
     * @param out     output writer
     */
    void solve(InputScanner scanner, PrintWriter out) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = scanner.nextCharTable(rows, cols);

        if (isHorizontalPartitionPossible(grid)) {
            out.print("YES");
            return;
        }
        if (isVerticalPartitionPossible(grid)) {
            out.print("YES");
            return;
        }
        out.print("NO");
    }

    /**
     * Determines whether the grid can be split into three *horizontal* strips
     * of equal height, each filled with a unique character.
     *
     * @return {@code true} if such a partition exists
     */
    private boolean isHorizontalPartitionPossible(char[][] grid) {
        int totalRows = grid.length;
        int totalCols = grid[0].length;

        if (totalRows % 3 != 0) {
            return false;
        }
        final int blockHeight = totalRows / 3;
        final Set<Character> usedColors = new HashSet<>();

        for (int blockIdx = 0; blockIdx < 3; blockIdx++) {
            // Expected colour is taken from the first cell of the block.
            char expectedColor = grid[blockIdx * blockHeight][0];
            if (!usedColors.add(expectedColor)) {          // duplicate colour ?
                return false;
            }
            // Verify that every cell inside the block matches the expected colour.
            for (int r = blockIdx * blockHeight; r < (blockIdx + 1) * blockHeight; r++) {
                for (int c = 0; c < totalCols; c++) {
                    if (grid[r][c] != expectedColor) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Determines whether the grid can be split into three *vertical* strips
     * of equal width, each filled with a unique character.
     *
     * @return {@code true} if such a partition exists
     */
    private boolean isVerticalPartitionPossible(char[][] grid) {
        int totalRows = grid.length;
        int totalCols = grid[0].length;

        if (totalCols % 3 != 0) {
            return false;
        }
        final int blockWidth = totalCols / 3;
        final Set<Character> usedColors = new HashSet<>();

        for (int blockIdx = 0; blockIdx < 3; blockIdx++) {
            // Expected colour is taken from the first cell of the block.
            char expectedColor = grid[0][blockIdx * blockWidth];
            if (!usedColors.add(expectedColor)) {          // duplicate colour ?
                return false;
            }
            // Verify that every cell inside the block matches the expected colour.
            for (int c = blockIdx * blockWidth; c < (blockIdx + 1) * blockWidth; c++) {
                for (int r = 0; r < totalRows; r++) {
                    if (grid[r][c] != expectedColor) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Entry point of the application.
 * Reads a grid of uppercase letters and determines whether it can be divided
 * into three equal vertical or three equal horizontal stripes, each stripe
 * consisting of a single distinct color. Prints "YES" if such a configuration
 * exists, otherwise prints "NO".
 */
public class Main {

    public static void main(String[] args) {
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            boolean result = new PatternValidator().validate(scanner);
            out.println(result ? "YES" : "NO");
        }
    }

    /**
     * Core validator that contains the logic for checking the required pattern.
     */
    static final class PatternValidator {

        /**
         * Executes the validation algorithm.
         *
         * @param scanner scanner that supplies the input tokens
         * @return {@code true} if the grid matches one of the allowed patterns
         */
        boolean validate(FastScanner scanner) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            // ----- vertical three‑stripe check -----
            if (cols % 3 == 0) {
                int segment = cols / 3;
                char[] colors = extractColorsFromFirstRow(grid, segment);
                if (areDistinct(colors) && isVerticalStripePattern(grid, colors, segment)) {
                    return true;
                }
            }

            // ----- horizontal three‑stripe check -----
            if (rows % 3 == 0) {
                int segment = rows / 3;
                char[] colors = extractColorsFromFirstColumn(grid, segment);
                if (areDistinct(colors) && isHorizontalStripePattern(grid, colors, segment)) {
                    return true;
                }
            }

            return false;
        }

        /** Extracts three candidate colors from the first row (left, middle, right). */
        private char[] extractColorsFromFirstRow(char[][] grid, int segment) {
            return new char[]{
                    grid[0][0],
                    grid[0][segment],
                    grid[0][2 * segment]
            };
        }

        /** Extracts three candidate colors from the first column (top, middle, bottom). */
        private char[] extractColorsFromFirstColumn(char[][] grid, int segment) {
            return new char[]{
                    grid[0][0],
                    grid[segment][0],
                    grid[2 * segment][0]
            };
        }

        /** Returns {@code true} if the three supplied colors are pairwise distinct. */
        private boolean areDistinct(char[] cs) {
            return cs[0] != cs[1] && cs[1] != cs[2] && cs[2] != cs[0];
        }

        /**
         * Verifies that the grid consists of three vertical stripes of equal width,
         * each stripe being filled exclusively with one of the supplied colors.
         *
         * @param grid      the input grid
         * @param colors    expected colors for stripe 0, 1 and 2
         * @param segment   width of a single stripe
         */
        private boolean isVerticalStripePattern(char[][] grid, char[] colors, int segment) {
            for (int stripe = 0; stripe < 3; stripe++) {
                int colStart = stripe * segment;
                char expected = colors[stripe];

                for (int col = colStart; col < colStart + segment; col++) {
                    for (int row = 0; row < grid.length; row++) {
                        if (grid[row][col] != expected) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        /**
         * Verifies that the grid consists of three horizontal stripes of equal height,
         * each stripe being filled exclusively with one of the supplied colors.
         *
         * @param grid      the input grid
         * @param colors    expected colors for stripe 0, 1 and 2
         * @param segment   height of a single stripe
         */
        private boolean isHorizontalStripePattern(char[][] grid, char[] colors, int segment) {
            for (int stripe = 0; stripe < 3; stripe++) {
                int rowStart = stripe * segment;
                char expected = colors[stripe];

                for (int row = rowStart; row < rowStart + segment; row++) {
                    for (int col = 0; col < grid[row].length; col++) {
                        if (grid[row][col] != expected) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }
    }

    /**
     * Simple scanner implementation that mimics the behaviour of the original
     * {@code InputReader} while keeping the class name expressive.
     */
    static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored program that checks whether a given matrix represents a happy
 * Flag of Berland. The flag is considered happy if it consists of three
 * equal‑size vertical stripes or three equal‑size horizontal stripes, each
 * stripe being a solid colour and the three colours being distinct.
 *
 * The implementation is split into small, focused methods and uses clear
 * naming, early returns and modern Java constructs to improve readability
 * and maintainability.
 */
public class FlagOfBerland {

    /** Entry point of the program. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            List<String> matrix = readMatrix(scanner, rows, cols);

            boolean verticalHappy  = isVerticallyHappy(matrix, rows, cols);
            boolean horizontalHappy = isHorizontallyHappy(matrix, rows, cols);

            System.out.println((verticalHappy || horizontalHappy) ? "YES" : "NO");
        }
    }

    /**
     * Reads {@code rows} strings from the scanner, each expected to have exactly
     * {@code cols} characters. Returns a list containing the read rows.
     *
     * @param scanner input scanner
     * @param rows    number of rows to read
     * @param cols    expected column count for each row
     * @return list of matrix rows
     */
    private static List<String> readMatrix(Scanner scanner, int rows, int cols) {
        List<String> matrix = new ArrayList<>(rows);
        for (int i = 0; i < rows; i++) {
            String line = scanner.next().trim();
            if (line.length() != cols) {
                throw new IllegalArgumentException(
                        "Row " + i + " does not contain exactly " + cols + " characters."
                );
            }
            matrix.add(line);
        }
        return matrix;
    }

    /**
     * Determines whether the matrix is happy when interpreted as vertical stripes.
     *
     * @param matrix       matrix of strings
     * @param rows         number of rows
     * @param cols         number of columns
     * @return true if the vertical‑stripe condition holds
     */
    private static boolean isVerticallyHappy(List<String> matrix, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }
        int blockSize = rows / 3;

        for (String row : matrix) {
            if (!isUniform(row.substring(0, blockSize)) ||
                !isUniform(row.substring(blockSize, 2 * blockSize)) ||
                !isUniform(row.substring(2 * blockSize))) {
                return false;
            }

            char colour0 = row.charAt(0);
            char colour1 = row.charAt(blockSize);
            char colour2 = row.charAt(2 * blockSize);

            if (colour0 == colour1 || colour0 == colour2 || colour1 == colour2) {
                return false;
            }
        }
        return true;
    }

    /**
     * Determines whether the matrix is happy when interpreted as horizontal stripes.
     *
     * @param matrix       matrix of strings
     * @param rows         number of rows
     * @param cols         number of columns
     * @return true if the horizontal‑stripe condition holds
     */
    private static boolean isHorizontallyHappy(List<String> matrix, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }
        int blockSize = cols / 3;

        for (int col = 0; col < cols; col++) {
            StringBuilder column = new StringBuilder();
            for (String row : matrix) {
                column.append(row.charAt(col));
            }

            if (!isUniform(column.substring(0, blockSize)) ||
                !isUniform(column.substring(blockSize, 2 * blockSize)) ||
                !isUniform(column.substring(2 * blockSize))) {
                return false;
            }

            char colour0 = column.charAt(0);
            char colour1 = column.charAt(blockSize);
            char colour2 = column.charAt(2 * blockSize);

            if (colour0 == colour1 || colour0 == colour2 || colour1 == colour2) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks whether all characters in the given string are identical.
     *
     * @param s input string
     * @return true if every character equals the first one
     */
    private static boolean isUniform(String s) {
        if (s.isEmpty()) {
            return true;
        }
        char first = s.charAt(0);
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) != first) {
                return false;
            }
        }
        return true;
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

/**
 * Reads an n×m grid of uppercase letters (R, B, G) and decides whether
 *   1. every row consists of a single, identical character, and
 *   2. every column also consists of a single, identical character, and
 *   3. the numbers of rows (and of columns) that are coloured Red, Blue
 *      and Green are all equal.
 * If all three conditions hold, prints "YES", otherwise prints "NO".
 */
public class GridValidator {

    private static final char RED = 'R';
    private static final char BLUE = 'B';
    private static final char GREEN = 'G';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            // Read the whole grid as a 2‑dimensional char array
            char[][] grid = readGrid(scanner, rows, cols);

            // Validate rows first; if any row is not uniform we can abort early.
            if (!rowsAreUniform(grid, rows, cols)) {
                System.out.println("NO");
                return;
            }

            // Validate columns; again abort early on the first non‑uniform column.
            if (!columnsAreUniform(grid, rows, cols)) {
                System.out.println("NO");
                return;
            }

            // At this point every row and every column is uniform.
            // Count how many rows (and columns) use each colour.
            int[] rowColourCounts = countUniformSegments(grid, true);
            int[] colColourCounts = countUniformSegments(grid, false);

            // Both colour‑counts must contain exactly the three colours
            // and each count must be identical.
            if (areCountsEqual(rowColourCounts) && areCountsEqual(colourCounts(cols, colColourCounts))) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Reads {@code rows} strings of length {@code cols} from the scanner
     * and stores them into a {@code char[][]} array.
     */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            // Guard against malformed input – each line must be exactly cols long.
            if (line.length() != cols) {
                throw new IllegalArgumentException(
                        "Row " + i + " does not contain exactly " + cols + " characters.");
            }
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Checks that every row of {@code grid} consists of a single repeated character.
     * Returns {@code true} if all rows are uniform, {@code false} otherwise.
     */
    private static boolean rowsAreUniform(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            char first = grid[r][0];
            for (int c = 1; c < cols; c++) {
                if (grid[r][c] != first) {
                    return false; // row not uniform
                }
            }
        }
        return true;
    }

    /**
     * Checks that every column of {@code grid} consists of a single repeated character.
     * Returns {@code true} if all columns are uniform, {@code false} otherwise.
     */
    private static boolean columnsAreUniform(char[][] grid, int rows, int cols) {
        for (int c = 0; c < cols; c++) {
            char first = grid[0][c];
            for (int r = 1; r < rows; r++) {
                if (grid[r][c] != first) {
                    return false; // column not uniform
                }
            }
        }
        return true;
    }

    /**
     * Counts how many uniformly‑coloured rows (or columns) of each colour exist.
     *
     * @param grid        the complete grid
     * @param isRowScan   {@code true} → scan rows, {@code false} → scan columns
     * @return an int[3] where the indices correspond to {@code RED}, {@code BLUE}, {@code GREEN}
     *         counts respectively.
     */
    private static int[] countUniformSegments(char[][] grid, boolean isRowScan) {
        int[] counts = new int[3]; // order: RED, BLUE, GREEN
        int segmentIndex = 0;      // index of the colour currently being counted

        for (int i = 0; i < (isRowScan ? grid.length : grid[0].length); i++) {
            char first = isRowScan ? grid[i][0] : grid[0][i];
            // All cells in this line must already be verified as uniform by the caller.
            switch (first) {
                case RED:
                    counts[0]++;
                    break;
                case BLUE:
                    counts[1]++;
                    break;
                case GREEN:
                    counts[2]++;
                    break;
                default:
                    // Defensive: the input should only contain R, B, G.
                    throw new IllegalArgumentException("Unexpected character: " + first);
            }
        }
        return counts;
    }

    /**
     * Returns a new int[3] containing the colour‑segment counts extracted from the
     * supplied {@code counts} array – only used to reuse the {@code areCountsEqual}
     * logic on the column‑wise counts.
     */
    private static int[] colourCounts(int size, int[] counts) {
        // The method simply maps the three colour positions back to a new array.
        // This helper exists only to keep {@code areCountsEqual} signature clean.
        return counts;
    }

    /**
     * Checks whether the three entries of {@code arr} are equal and non‑zero.
     */
    private static boolean areCountsEqual(int[] arr) {
        return arr[0] == arr[1] && arr[1] == arr[2] && arr[0] != 0;
    }
}

/**
 * Refactored solution that checks whether a given grid consists of three
 * equal‑sized stripes of a single, distinct character each.
 *
 * The original program was functional but hard to read and maintain.
 * This version improves readability, separates concerns and follows
 * modern Java coding conventions.
 */
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.StringBuilder;

public class Main {

    /** Print writer used to output the answer. */
    private static final PrintWriter OUT = new PrintWriter(System.out);

    /** Input stream reader used for fast integer / token reading. */
    private static final InputReader SCANNER = new InputReader(System.in);

    /** Entry point. */
    public static void main(String[] args) {
        int rows = SCANNER.ni();          // n
        int cols = SCANNER.ni();          // m
        char[][] grid = readGrid(rows);

        if (isHorizontalStripePattern(grid, rows, cols)) {
            OUT.println("YES");
        } else if (isVerticalStripePattern(grid, rows, cols)) {
            OUT.println("YES");
        } else {
            OUT.println("NO");
        }
        OUT.close();
    }

    /** Reads `rows` lines from the scanner and returns a char matrix. */
    private static char[][] readGrid(int rows) {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = SCANNER.nextLine();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Checks the horizontal‑stripe pattern:
     * <ul>
     *   <li>The first row must be made of a single repeated character.</li>
     *   <li>The grid height must be divisible by 3.</li>
     *   <li>Each consecutive block of {@code rows/3} rows must be filled
     *       with exactly one distinct character.</li>
     *   <li>All three characters must be different.</li>
     * </ul>
     */
    private static boolean isHorizontalStripePattern(char[][] grid, int n, int m) {
        if (!isFirstRowUniform(grid[0])) {
            return false;
        }
        if (n % 3 != 0) {
            return false;
        }

        final int blockHeight = n / 3;
        final char[] expectedChar = new char[3];

        // Determine the expected character for each block and verify uniformity.
        for (int block = 0; block < 3; block++) {
            int startRow = block * blockHeight;
            expectedChar[block] = grid[startRow][0];
            for (int r = startRow; r < startRow + blockHeight; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] != expectedChar[block]) {
                        return false; // Not uniform inside the block.
                    }
                }
            }
        }

        // All three characters must be different.
        return expectedChar[0] != expectedChar[1]
                && expectedChar[0] != expectedChar[2]
                && expectedChar[1] != expectedChar[2];
    }

    /**
     * Checks the vertical‑stripe pattern:
     * <ul>
     *   <li>The first column must be made of a single repeated character.</li>
     *   <li>The grid width must be divisible by 3.</li>
     *   <li>Each consecutive block of {@code cols/3} columns must be filled
     *       with exactly one distinct character.</li>
     *   <li>All three characters must be different.</li>
     * </ul>
     */
    private static boolean isVerticalStripePattern(char[][] grid, int n, int m) {
        if (!isFirstColumnUniform(grid, n)) {
            return false;
        }
        if (m % 3 != 0) {
            return false;
        }

        final int blockWidth = m / 3;
        final char[] expectedChar = new char[3];

        // Determine the expected character for each block and verify uniformity.
        for (int block = 0; block < 3; block++) {
            int startCol = block * blockWidth;
            expectedChar[block] = grid[0][startCol];
            for (int c = startCol; c < startCol + blockWidth; c++) {
                for (int r = 0; r < n; r++) {
                    if (grid[r][c] != expectedChar[block]) {
                        return false; // Not uniform inside the block.
                    }
                }
            }
        }

        // All three characters must be different.
        return expectedChar[0] != expectedChar[1]
                && expectedChar[0] != expectedChar[2]
                && expectedChar[1] != expectedChar[2];
    }

    /** Helper: true iff the whole first row consists of the same character. */
    private static boolean isFirstRowUniform(char[] firstRow) {
        char first = firstRow[0];
        for (char ch : firstRow) {
            if (ch != first) {
                return false;
            }
        }
        return true;
    }

    /** Helper: true iff the whole first column consists of the same character. */
    private static boolean isFirstColumnUniform(char[][] grid, int rows) {
        char first = grid[0][0];
        for (int r = 1; r < rows; r++) {
            if (grid[r][0] != first) {
                return false;
            }
        }
        return true;
    }

    /* -------------------------------------------------------------------------
     *  Fast input utilities – unchanged from the original implementation.
     * ------------------------------------------------------------------------- */
    private static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int bytesInBuffer = 0, pos = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (bytesInBuffer == -1) {
                throw new java.io.InputMismatchException();
            }
            if (pos >= bytesInBuffer) {
                pos = 0;
                bytesInBuffer = stream.read(buffer);
            }
            if (bytesInBuffer <= 0) {
                return -1;
            }
            return buffer[pos++];
        }

        /** Reads next token as an int (supports negative numbers). */
        int ni() throws IOException {
            int c = readByte();
            while (isSpaceChar(c)) {
                c = readByte();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            do {
                result = result * 10 + (c - '0');
                c = readByte();
            } while (!isSpaceChar(c));
            return result * sign;
        }

        /** Returns a whole line as a string (excluding line‑break characters). */
        String nextLine() throws IOException {
            int c = readByte();
            while (isSpaceChar(c)) {
                c = readByte();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = readByte();
            } while (!isEndOfLine(c));
            return sb.toString();
        }

        /** Checks whether a character is a whitespace character used for token separation. */
        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Checks whether a character marks the end of a line. */
        private static boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

/**
 * Determines whether a rectangular grid of characters consists of
 * either:
 *   1. uniform columns (each column contains a single colour), or
 *   2. uniform rows  (each row    contains a single colour).
 *
 * In both cases the three valid colours – 'R', 'G' and 'B' –
 * must appear an equal number of times and exactly once each
 * if the grid is to be considered valid.
 */
public class Task837b {

    private static final char RED = 'R';
    private static final char GREEN = 'G';
    private static final char BLUE = 'B';
    private static final char[] VALID_COLOURS = {RED, GREEN, BLUE};

    /**
     * Reads the input, evaluates the grid and prints {@code YES}
     * if it satisfies the conditions, otherwise {@code NO}.
     */
    public void run() {
        try (Scanner scanner = new Scanner(System.in)) {
            int height = scanner.nextInt();   // number of rows
            int width  = scanner.nextInt();   // number of columns

            // Store the grid as a list of rows (each row is a String)
            String[] rows = new String[height];
            for (int r = 0; r < height; r++) {
                rows[r] = scanner.next();
            }

            boolean valid = isValidByColumns(rows, width) ||
                            isValidByRows(rows, height);

            System.out.println(valid ? "YES" : "NO");
        }
    }

    /**
     * Checks whether every column contains a single colour and the
     * colour distribution meets the required constraints.
     */
    private boolean isValidByColumns(String[] rows, int width) {
        // Map colour → number of columns that consist exclusively of that colour
        Map<Character, Integer> columnColourCount = new HashMap<>();

        for (int c = 0; c < width; c++) {
            char colour = rows[0].charAt(c);               // colour of the first row of this column
            if (!isColumnUniform(rows, c, colour)) {
                continue;                                   // column not uniform → ignore
            }

            columnColourCount.merge(colour, 1, Integer::sum);
        }

        return validateColourDistribution(columnColourCount);
    }

    /**
     * Checks whether every row contains a single colour and the
     * colour distribution meets the required constraints.
     */
    private boolean isValidByRows(String[] rows, int height) {
        Map<Character, Integer> rowColourCount = new HashMap<>();

        for (int r = 0; r < height; r++) {
            char colour = rows[r].charAt(0);               // colour of the first column of this row
            if (!isRowUniform(rows, r, colour)) {
                continue;                                   // row not uniform → ignore
            }

            rowColourCount.merge(colour, 1, Integer::sum);
        }

        return validateColourDistribution(rowColourCount);
    }

    /** Determines if a column consists of a single colour. */
    private boolean isColumnUniform(String[] rows, int columnIndex, char expectedColour) {
        for (String row : rows) {
            if (row.charAt(columnIndex) != expectedColour) {
                return false;
            }
        }
        return true;
    }

    /** Determines if a row consists of a single colour. */
    private boolean isRowUniform(String[] rows, int rowIndex, char expectedColour) {
        String row = rows[rowIndex];
        for (int col = 0; col < row.length(); col++) {
            if (row.charAt(col) != expectedColour) {
                return false;
            }
        }
        return true;
    }

    /**
     * Validates that the supplied colour → count map satisfies:
     *   • Exactly three colours are present.
     *   • Each colour appears the same number of times.
     *
     * This method is reused for both rows and columns.
     */
    private boolean validateColourDistribution(Map<Character, Integer> colourCount) {
        // All three colours must be present
        if (colourCount.size() != VALID_COLOURS.length) {
            return false;
        }

        // All colours must have the same count
        int firstCount = colourCount.get(VALID_COLOURS[0]);
        for (int count : colourCount.values()) {
            if (count != firstCount) {
                return false;
            }
        }

        // Additionally, each colour must appear exactly once in the pattern
        // (the original logic required “times” to be 3, i.e., three distinct colours).
        return firstCount == 1;
    }

    /* -----------------------------------------------------------------------
       Main entry point – unchanged from the original submission
       ----------------------------------------------------------------------- */
    public static void main(String[] args) {
        new Task837b().run();
    }
}

import java.util.*;

public class FlagOfBerland {

    public static void main(String[] args) throws IOException {
        // Using Scanner simplifies resource handling (try‑with‑resources)
        try (Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();            // number of rows
            int m = sc.nextInt();            // number of columns
            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next();           // each row of the flag
            }

            System.out.println(possibleFlag(grid, n, m) ? "YES" : "NO");
        }
    }

    /**
     * Determines whether the given grid can be a valid flag of Berland.
     * The flag can be split either horizontally or vertically into three
     * equal‑size blocks, each of which is painted with a single colour
     * and the three colours are exactly ‘R’, ‘G’ and ‘B’ (any order).
     */
    private static boolean possibleFlag(String[] grid, int n, int m) {
        boolean rowsDivisible = (n % 3 == 0);
        boolean colsDivisible = (m % 3 == 0);

        // Neither dimension can be partitioned into three equal parts.
        if (!rowsDivisible && !colsDivisible) {
            return false;
        }

        // If both dimensions are divisible we must test both orientations.
        if (rowsDivisible && colsDivisible) {
            return validateRowBlocks(grid, n, m) || validateColumnBlocks(grid, n, m);
        }

        // Only one orientation is possible.
        return rowsDivisible ? validateRowBlocks(grid, n, m)
                             : validateColumnBlocks(grid, n, m);
    }

    /**
     * Checks the horizontal (row) orientation.
     * The grid is divided into three blocks of {@code n/3} rows each.
     * Each block must be uniformly coloured, and the three distinct colours
     * must be exactly ‘R’, ‘G’, and ‘B’.
     */
    private static boolean validateRowBlocks(String[] grid, int n, int m) {
        int blockRows = n / 3;
        Set<Character> colours = new LinkedHashSet<>();   // preserves discovery order

        for (int start = 0; start < n; start += blockRows) {
            char blockColour = '\0';
            for (int r = start; r < start + blockRows; r++) {
                String row = grid[r];
                for (int c = 0; c < m; c++) {
                    if (blockColour == '\0') {
                        blockColour = row.charAt(c);
                    } else if (row.charAt(c) != blockColour) {
                        return false;                       // non‑uniform block
                    }
                }
            }
            // Duplicate colour across different blocks → invalid flag
            if (!colours.add(blockColour)) {
                return false;
            }
        }
        // Exactly three distinct colours and they are R, G, B
        return colours.size() == 3 &&
               colours.contains('R') && colours.contains('G') && colours.contains('B');
    }

    /**
     * Checks the vertical (column) orientation.
     * The grid is divided into three blocks of {@code m/3} columns each.
     * Same rules as {@link #validateRowBlocks} apply, only the scanning order
     * is column‑wise.
     */
    private static boolean validateColumnBlocks(String[] grid, int n, int m) {
        int blockCols = m / 3;
        Set<Character> colours = new LinkedHashSet<>();

        for (int start = 0; start < m; start += blockCols) {
            char blockColour = '\0';
            for (int c = start; c < start + blockCols; c++) {
                for (int r = 0; r < n; r++) {
                    char ch = grid[r].charAt(c);
                    if (blockColour == '\0') {
                        blockColour = ch;
                    } else if (grid[r].charAt(c) != blockColour) {
                        return false;                       // non‑uniform block
                    }
                }
            }
            if (!colours.add(blockColour)) {
                return false;
            }
        }
        return colours.size() == 3 &&
               colours.contains('R') && colours.contains('G') && colours.contains('B');
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Refactored solution for the “Two out of Three” pattern check.
 * The program reads a matrix and determines whether it can be split
 * into three equal horizontal or vertical bands that consist of a
 * single distinct character each.
 *
 * The refactor improves readability, separates concerns, and follows
 * modern Java conventions.
 */
public class Main {

    /** Entry point */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            solve(scanner, out);
        }
    }

    /**
     * Reads the input, evaluates the pattern and prints the answer.
     *
     * @param scanner scanner tied to {@code System.in}
     * @param out     printer tied to {@code System.out}
     */
    private static void solve(Scanner scanner, PrintWriter out) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine();                     // consume remaining newline

        char[][] grid = readMatrix(scanner, rows, cols);

        if (rows % 3 == 0) {
            out.println(isHorizontalBandPattern(grid) ? "YES" : "NO");
        } else if (cols % 3 == 0) {
            out.println(isVerticalBandPattern(grid) ? "YES" : "NO");
        } else {
            out.println("NO");
        }
    }

    /**
     * Reads {@code rows} lines of length {@code cols} and stores them
     * into a 2‑dimensional {@code char} array.
     *
     * @param scanner scanner tied to {@code System.in}
     * @param rows    number of rows
     * @param cols    number of columns
     * @return the read matrix
     */
    private static char[][] readMatrix(Scanner scanner, int rows, int cols) {
        char[][] matrix = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.nextLine();
            for (int c = 0; c < cols; c++) {
                matrix[r][c] = line.charAt(c);
            }
        }
        return matrix;
    }

    /**
     * Checks whether the matrix can be divided into three equal horizontal
     * bands, each filled with a single distinct character.
     *
     * @param grid the input matrix
     * @return {@code true} if the horizontal band condition holds
     */
    private static boolean isHorizontalBandPattern(char[][] grid) {
        final int bandSize = grid.length / 3;

        // Characters that each band must contain
        char band1Char = grid[0][0];
        char band2Char = grid[bandSize][0];
        char band3Char = grid[2 * bandSize][0];

        // All three colors must be different
        if (band1Char == band2Char || band2Char == band3Char || band3Char == band1Char) {
            return false;
        }

        // Validate each band
        for (int band = 0; band < 3; band++) {
            int startRow = band * bandSize;
            char expected = switch (band) {
                case 0 -> band1Char;
                case 1 -> band2Char;
                default -> band3Char;
            };

            for (int r = startRow; r < startRow + bandSize; r++) {
                for (int c = 0; c < grid[0].length; c++) {
                    if (grid[r][c] != expected) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Checks whether the matrix can be divided into three equal vertical
     * bands, each filled with a single distinct character.
     *
     * @param grid the input matrix
     * @return {@code true} if the vertical band condition holds
     */
    private static boolean isVerticalBandPattern(char[][] grid) {
        final int bandSize = grid[0].length / 3;

        // Characters that each band must contain
        char band1Char = grid[0][0];
        char band2Char = grid[0][bandSize];
        char band3Char = grid[0][2 * bandSize];

        // All three colors must be different
        if (band1Char == band2Char || band2Char == band3Char || band3Char == band1Char) {
            return false;
        }

        // Validate each band
        for (int band = 0; band < 3; band++) {
            int startCol = band * bandSize;
            char expected = switch (band) {
                case 0 -> band1Char;
                case 1 -> band2Char;
                default -> band3Char;
            };

            for (int r = 0; r < grid.length; r++) {
                for (int c = startCol; c < startCol + bandSize; c++) {
                    if (grid[r][c] != expected) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Determines whether a given grid can be divided into three equal‑size
 * stripes (either horizontally or vertically) each filled with a single
 * distinct colour – {@code 'R'}, {@code 'G'} or {@code 'B'}.
 *
 * The program follows these rules:
 * <ul>
 *   <li>If the number of rows {@code n} is a multiple of three, each stripe
 *       consists of {@code n/3} consecutive rows. All cells in a stripe must
 *       have the same colour and the three stripe colours must be exactly
 *       {@code 'R','G','B'} in any order.</li>
 *   <li>If only the number of columns {@code m} is a multiple of three, a
 *       similar check is performed for vertical stripes (each stripe is
 *       {@code m/3} columns wide).</li>
 *   <li>If neither dimension is divisible by three, the answer is always
 *       {@code "NO"}.</li>
 * </ul>
 */
public class FlagOfBerland {

    /** Names of the three required colours. */
    private static final char[] REQUIRED_COLOURS = {'R', 'G', 'B'};

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in))) {

            // ----- read dimensions and grid -------------------------------------------------
            StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
            int rows = Integer.parseInt(tokenizer.nextToken());
            int cols = Integer.parseInt(tokenizer.nextToken());

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.readLine().toCharArray();
            }

            // ----- evaluate possibilities ----------------------------------------------------
            if (rows % 3 == 0 && isHorizontalFlag(grid, rows, cols)) {
                System.out.println("YES");
                return;
            }

            if (cols % 3 == 0 && isVerticalFlag(grid, rows, cols)) {
                System.out.println("YES");
                return;
            }

            System.out.println("NO");
        }
    }

    /**
     * Checks the horizontal (row‑wise) stripe configuration.
     *
     * @return {@code true} if the grid consists of three equal‑height rows
     *         each filled with a distinct colour from {@code {'R','G','B'}}.
     */
    private static boolean isHorizontalFlag(char[][] grid, int rows, int cols) {
        final int stripeHeight = rows / 3;
        char[] stripeColours = new char[3];   // colour of each stripe in order

        for (int stripeIdx = 0; stripeIdx < 3; stripeIdx++) {
            int startRow = stripeIdx * stripeHeight;
            char expectedColour = grid[startRow][0];

            // Verify that this colour is one of the required three.
            if (!isOneOfRequired(expectedColour)) {
                return false;
            }
            stripeColours[stripeIdx] = expectedColour;

            // Ensure every cell inside this stripe matches the expected colour.
            for (int r = startRow; r < startRow + stripeHeight; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != expectedColour) {
                        return false;
                    }
                }
            }
        }

        // All three stripe colours must be exactly {'R','G','B'} (order irrelevant).
        return coloursArePermutation(stripeColours);
    }

    /**
     * Checks the vertical (column‑wise) stripe configuration.
     *
     * @return {@code true} if the grid consists of three equal‑width columns
     *         each filled with a distinct colour from {@code {'R','G','B'}}.
     */
    private static boolean isVerticalFlag(char[][] grid, int rows, int cols) {
        final int stripeWidth = cols / 3;
        char[] stripeColours = new char[3];   // colour of each stripe in order

        for (int stripeIdx = 0; stripeIdx < 3; stripeIdx++) {
            int startCol = stripeIdx * stripeWidth;
            char expectedColour = grid[0][startCol];

            if (!isOneOfRequired(expectedColour)) {
                return false;
            }
            stripeColours[stripeIdx] = expectedColour;

            // Verify every cell inside this stripe.
            for (int c = startCol; c < startCol + stripeWidth; c++) {
                for (int r = 0; r < rows; r++) {
                    if (grid[r][c] != expectedColour) {
                        return false;
                    }
                }
            }
        }

        return coloursArePermutation(stripeColours);
    }

    /** @return {@code true} if the character is either {@code 'R'}, {@code 'G'} or {@code 'B'} */
    private static boolean isOneOfRequired(char ch) {
        return ch == 'R' || ch == 'G' || ch == 'B';
    }

    /** @return {@code true} if {@code arr} contains exactly the three required colours
     *         (order does not matter) */
    private static boolean coloursArePermutation(char[] arr) {
        // Sort copy to compare with the constant array.
        char[] sorted = arr.clone();
        java.util.Arrays.sort(sorted);
        return java.util.Arrays.equals(sorted, REQUIRED_COLOURS);
    }
}

package solution;

import java.io.*;
