/**
 * Refactored solution that checks whether three colored regions in a grid
 * form equal rectangular bounding boxes.
 *
 * The program mimics the original behaviour but uses clearer naming,
 * proper encapsulation and modern Java practices.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                       */
    /* --------------------------------------------------------------------- */

    /** Fast scanner used for competitive‑programming style input. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(Reader reader) {
            this.br = new BufferedReader(reader);
        }

        /** Reads the next token, loading more lines when necessary. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Domain entities                                                       */
    /* --------------------------------------------------------------------- */

    /** Enum representing the three colors used in the problem. */
    private enum Color {
        RED('R'), BLUE('B'), GREEN('G');

        private final char symbol;

        Color(char symbol) {
            this.symbol = symbol;
        }

        static Color fromChar(char c) {
            for (Color color : values()) {
                if (color.symbol == c) {
                    return color;
                }
            }
            throw new IllegalArgumentException("Unknown color: " + c);
        }
    }

    /** Holds the bounding rectangle of a colour. */
    private static final class Bounds {
        final int top;      // smallest row index
        final int bottom;   // largest row index
        final int left;     // smallest column index
        final int right;    // largest column index
        final boolean present; // whether the colour appears in the grid

        Bounds(int top, int bottom, int left, int right, boolean present) {
            this.top = top;
            this.bottom = bottom;
            this.left = left;
            this.right = right;
            this.present = present;
        }
    }

    /** Writer used for program output. */
    private static final PrintWriter out = new PrintWriter(System.out);

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                           */
    /* --------------------------------------------------------------------- */

    /** Starts the solving process in a dedicated thread (mirrors original setup). */
    public static void main(String[] args) {
        new Thread(null, () -> {
            try {
                solve();
            } catch (Exception e) {
                e.printStackTrace();
            } finally {
                out.close();
            }
        }, "Solver-Thread", 1 << 26).start();
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm                                                       */
    /* --------------------------------------------------------------------- */

    /** Reads input, analyses the grid and prints "YES"/"NO". */
    private static void solve() throws IOException {
        FastScanner fs = new FastScanner(new InputStreamReader(System.in));

        int rows = fs.nextInt();
        int cols = fs.nextInt();

        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = fs.next();
            grid[i] = line.toCharArray();
        }

        /* ---- 1. Compute bounding boxes for each colour ------------------- */
        Bounds[] bounds = new Bounds[3];
        // initialise with "invalid" values
        Arrays.fill(bounds, new Bounds(rows, -1, cols, -1, false));

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                Color colour = Color.fromChar(grid[i][j]);
                int idx = colour.ordinal();                 // 0 = RED, 1 = BLUE, 2 = GREEN
                bounds[idx].present = true;
                bounds[idx].top = Math.min(bounds[idx].top, i);
                bounds[idx].bottom = Math.max(bounds[idx].bottom, i);
                bounds[idx].left = Math.min(bounds[idx].left, j);
                bounds[idx].right = Math.max(bounds[idx].right, j);
            }
        }

        /* ---- 2. Validate presence of all three colours ------------------- */
        for (Bounds b : bounds) {
            if (!b.present) {
                out.println("NO");
                return;
            }
        }

        /* ---- 3. Check that all bounding boxes have identical dimensions -- */
        int expectedWidth  = bounds[0].right - bounds[0].left;
        int expectedHeight = bounds[0].bottom - bounds[0].top;

        for (int i = 1; i < 3; i++) {
            if ((bounds[i].right - bounds[i].left) != expectedWidth ||
                (bounds[i].bottom - bounds[i].top) != expectedHeight) {
                out.println("NO");
                return;
            }
        }

        /* ---- 4. Verify each bounding rectangle contains only its colour ---- */
        boolean allValid = true;
        for (int i = 0; i < 3; i++) {
            if (!rectangleIsUniform(grid,
                    bounds[i].top, bounds[i].bottom,
                    bounds[i].left, bounds[i].right,
                    Color.values()[i])) {
                allValid = false;
                break;
            }
        }

        out.println(allValid ? "YES" : "NO");
    }

    /** Returns true if the sub‑rectangle defined by the given bounds consists
     *  exclusively of the supplied colour. */
    private static boolean rectangleIsUniform(char[][] grid,
                                              int top, int bottom,
                                              int left, int right,
                                              Color expected) {
        char target = expected.symbol;
        for (int i = top; i <= bottom; i++) {
            for (int j = left; j <= right; j++) {
                if (grid[i][j] != target) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a table of characters (only 'R', 'G', 'B') and decides whether it satisfies one of the
 * following patterns:
 *
 * 1. The rows can be divided into three equal groups, each group having a uniform colour and the
 *    three groups using the three distinct colours.
 * 2. The columns can be divided into three equal groups, each group using a distinct colour and
 *    all rows are identical uniform strings.
 *
 * If either condition is true the program prints "YES", otherwise it prints "NO".
 */
public class Main {

    /** Mapping of colour character to an index (0‑2). */
    private static final Map<Character, Integer> COLOR_INDEX = Map.of('R', 0, 'G', 1, 'B', 2);
    /** Shortcut array for the same mapping. */
    private static final char[] COLORS = {'R', 'G', 'B'};

    public static void main(String[] args) throws IOException {
        /* --------------------------------------------------------------
         *  Input handling – try‑with‑resources guarantees the stream is closed.
         * -------------------------------------------------------------- */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int rows = 0;
            int cols = 0;
            String[] header = parseHeader(br);
            rows = Integer.parseInt(header[0]);
            cols = Integer.parseInt(header[1]);

            List<String> board = readBoard(br, rows);
            boolean ok = false;

            if (rows % 3 == 0) {
                ok = checkRowPattern(board, cols);
            }
            if (!ok && cols % 3 == 0) {
                ok = checkColumnPattern(board, rows);
            }

            System.out.println(ok ? "YES" : "NO");
        }
    }

    /** Parses the first line of the input and returns the two integer dimensions. */
    private static String[] parseHeader(BufferedReader br) throws IOException {
        String line = br.readLine();
        if (line == null) {
            throw new IllegalArgumentException("Input is empty");
        }
        StringTokenizer tok = new StringTokenizer(line);
        return new String[]{tok.nextToken(), tok.nextToken()};
    }

    /** Reads exactly {@code rows} lines from the reader and returns them as a list. */
    private static List<String> readBoard(BufferedReader br, int rows) throws IOException {
        List<String> board = new ArrayList<>(rows);
        for (int i = 0; i < rows; i++) {
            String line = br.readLine();
            if (line == null) {
                throw new IllegalArgumentException("Missing board rows");
            }
            board.add(line);
        }
        return board;
    }

    /** Verifies the row‑based pattern described above. */
    private static boolean checkRowPattern(List<String> board, int cols) {
        final int groupSize = board.size() / 3;
        boolean[] usedColors = new boolean[3];

        for (int group = 0; group < 3; group++) {
            int startRow = group * groupSize;
            char expectedColor = board.get(startRow).charAt(0);
            int idx = COLOR_INDEX.get(expectedColor);
            if (usedColors[idx]) {
                return false;                 // colour already used
            }
            usedColors[idx] = true;

            String expectedLine = repeat(expectedColor, cols);
            for (int r = 0; r < groupSize; r++) {
                int rowIdx = startRow + r;
                if (!board.get(rowIdx).equals(expectedLine)) {
                    return false;                 // row not uniform
                }
            }
        }
        return true;
    }

    /** Verifies the column‑based pattern described above. */
    private static boolean checkColumnPattern(List<String> board, int rows) {
        final int groupSize = board.get(0).length() / 3;
        boolean[] usedColors = new boolean[3];

        for (int group = 0; group < 3; group++) {
            int startCol = group * groupSize;
            char expectedColor = board.get(0).charAt(startCol);
            int idx = COLOR_INDEX.get(expectedColor);
            if (usedColors[idx]) {
                return false;
            }
            usedColors[idx] = true;

            for (int c = 0; c < groupSize; c++) {
                int col = startCol + c;
                if (board.get(0).charAt(col) != expectedColor) {
                    return false;                     // column not uniform
                }
            }
        }

        // All rows must be identical uniform strings (the whole board is a single colour per column group)
        String reference = repeat(board.get(0).charAt(0), board.get(0).length());
        for (String line : board) {
            if (!line.equals(reference)) {
                return false;
            }
        }
        return true;
    }

    /** Utility: creates a string of length {@code count} consisting of the character {@code ch}. */
    private static String repeat(char ch, int count) {
        char[] arr = new char[count];
        Arrays.fill(arr, ch);
        return new String(arr);
    }
}

package solution;

import java.io.*;
import java.util.*;

/**
 * Main solution class for the colour‑grid checker.
 * The program reads a matrix of characters ('R', 'G', 'B'), checks whether it
 * satisfies a specific colour‑distribution rule either in the original rows
 * or in the transposed columns, and prints "YES" or "NO".
 */
public class Main {

    /* --------------------------------------------------------------- */
    /*                         Fast I/O utilities                      */
    /* --------------------------------------------------------------- */

    /**
     * Simple fast scanner that works with {@link BufferedReader}.
     */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            this.reader = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns the next token from the underlying stream. */
        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        char nextChar() throws IOException {
            return next().charAt(0);
        }
    }

    /**
     * Fast printer that extends {@link PrintWriter}.
     */
    private static final class FastPrinter extends PrintWriter {
        FastPrinter(OutputStream out) {
            super(out);
        }
    }

    /* --------------------------------------------------------------- */
    /*                         Domain constants & helpers               */
    /* --------------------------------------------------------------- */

    /**
     * Small utility class that stores colour‑index mappings.
     */
    private static final class Colors {
        /** Map of character to a stable integer index (0‑R, 1‑G, 2‑B). */
        static int toIndex(char c) {
            return switch (c) {
                case 'R' -> 0;
                case 'G' -> 1;
                default  -> 2; // 'B'
            };
        }
    }

    /* --------------------------------------------------------------- */
    /*                         Validation logic                         */
    /* --------------------------------------------------------------- */

    /**
     * Determines whether the given grid satisfies the required colour condition.
     *
     * <p>The validation consists of three steps:</p>
     * <ol>
     *   <li>Every row must consist of a single repeated character.</li>
     *   <li>The number of rows of each colour must be equal.</li>
     *   <li>Rows of the same colour must appear in one contiguous block,
     *       and the size of each such block must equal the expected block size.</li>
     * </ol>
     *
     * @param grid the matrix to validate
     * @return {@code true} if the grid satisfies the condition
     */
    private static boolean isValid(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        // 1. Ensure each row is uniform (all cells contain the same character)
        int[] rowColourCount = new int[3];
        for (int i = 0; i < rows; i++) {
            char first = grid[i][0];
            for (int j = 1; j < cols; j++) {
                if (grid[i][j] != first) {
                    return false; // row not uniform
                }
            }
            rowColourCount[Colors.toIndex(first)]++;
        }

        // 2. The colours must appear equally many times across rows
        if (rowColourCount[0] != rowColourCount[1] ||
            rowColourCount[1] != rowColourCount[2]) {
            return false;
        }

        // 3. Contiguity check – each colour must occupy exactly
        //    rowColourCount[x] consecutive rows.
        int expectedRowsPerColour = rowColourCount[0];
        int[] consecutiveCount = new int[3];
        int currentColourIdx = -1;

        for (int i = 0; i < rows; i++) {
            int colourIdx = Colors.toIndex(grid[i][0]);

            if (colourIdx != currentColourIdx) {
                // finish previous colour block
                if (currentColourIdx >= 0 && consecutiveCount[currentColourIdx] != expectedRowsPerColour) {
                    return false;
                }
                currentColourIdx = colourIdx;
                consecutiveCount[colourIdx] = 1;
            } else {
                consecutiveCount[colourIdx]++;
            }
        }

        // final block check
        return consecutiveCount[currentColourIdx] == expectedRowsPerColour;
    }

    /* --------------------------------------------------------------- */
    /*                         Matrix utilities                         */
    /* --------------------------------------------------------------- */

    /** Transposes the supplied matrix (rows become columns). */
    private static char[][] transpose(char[][] src) {
        int originalRows = src.length;
        int originalCols = src[0].length;
        char[][] transposed = new char[originalCols][originalRows];

        for (int i = 0; i < originalRows; i++) {
            for (int j = 0; j < originalCols; j++) {
                transposed[j][i] = src[i][j];
            }
        }
        return transposed;
    }

    /* --------------------------------------------------------------- */
    /*                         Core algorithm                           */
    /* --------------------------------------------------------------- */

    /**
     * Reads input, runs the validation on rows and columns, and prints the result.
     */
    private static void solve(FastScanner in, FastPrinter out) throws Exception {
        int n = in.nextInt();  // rows
        int m = in.nextInt();  // columns

        char[][] rows = new char[n][];
        for (int i = 0; i < n; i++) {
            rows[i] = in.next().toCharArray();
        }

        char[][] cols = transpose(rows);

        out.print(isValid(rows) || isValid(cols) ? "YES" : "NO");
    }

    /* --------------------------------------------------------------- */
    /*                          Program entry point                      */
    /* --------------------------------------------------------------- */

    /**
     * Starts the program. All resources are wrapped in try‑with‑resources
     * to guarantee a clean shutdown.
     */
    public static void main(String[] args) throws Exception {
        try (FastScanner scanner = new FastScanner(System.in);
             FastPrinter printer = new FastPrinter(System.out)) {
            solve(scanner, printer);
        } catch (Throwable ex) {
            ex.printStackTrace();
            System.exit(1);
        }
    }
}

import java.io.*;
import java.util.*;

public class GridValidator {

    /** Characters that must appear exactly once in each row and column of a 3×3 block. */
    private static final char[] COLORS = {'R', 'G', 'B'};

    public static void main(String[] args) {
        /* --------------------------------------------------------------
         *  Input handling – use try‑with‑resources to guarantee closing.
         * -------------------------------------------------------------- */
        try (Scanner scanner = new Scanner(new BufferedReader(
                new InputStreamReader(System.in)))) {

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            /* --------------------------------------------------------------
             *  Read the whole grid into a char matrix.
             * -------------------------------------------------------------- */
            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = scanner.next();
                grid[r] = line.toCharArray();
            }

            /* --------------------------------------------------------------
             *  Quick reject: if either dimension is not a multiple of 3 the
             *  grid cannot be partitioned into 3×3 blocks.
             * -------------------------------------------------------------- */
            if (rows % 3 != 0 || cols % 3 != 0) {
                System.out.println("NO");
                return;
            }

            /* --------------------------------------------------------------
             *  Validate every 3×3 block.  If any block fails the test we can
             *  stop early and report “NO”.
             * -------------------------------------------------------------- */
            boolean allBlocksValid = true;
            for (int r = 0; r < rows; r += 3) {
                for (int c = 0; c < cols; c += 3) {
                    if (!isValidBlock(grid, r, c)) {
                        allBlocksValid = false;
                        break;
                    }
                }
                if (!allBlocksValid) {
                    break;
                }
            }

            System.out.println(allBlocksValid ? "YES" : "NO");
        }
    }

    /**
     * Checks whether the 3×3 sub‑grid starting at (startRow, startCol)
     * contains each colour 'R', 'G' and 'B' exactly once in every row
     * and every column of the block.
     *
     * @param grid       the whole game board
     * @param startRow   top‑left row index of the block
     * @param startCol   top‑left column index of the block
     * @return true if the block satisfies the permutation property
     */
    private static boolean isValidBlock(char[][] grid, int startRow, int startCol) {
        /* ---- Verify rows of the block ---- */
        for (int dr = 0; dr < 3; dr++) {
            int[] counts = new int[3];           // index 0→R, 1→G, 2→B
            int r = startRow + dr;
            for (int dc = 0; dc < 3; dc++) {
                char ch = grid[r][startCol + dc];
                if (ch == 'R') counts[0]++;
                else if (ch == 'G') counts[1]++;
                else if (ch == 'B') counts[2]++;
            }
            if (!Arrays.equals(counts, new int[]{1, 1, 1})) {
                return false;
            }
        }

        /* ---- Verify columns of the block ---- */
        for (int dc = 0; dc < 3; dc++) {
            int[] counts = new int[3];
            for (int dr = 0; dr < 3; dr++) {
                char ch = grid[startRow + dr][startCol + dc];
                if (ch == 'R') counts[0]++;
                else if (ch == 'G') counts[1]++;
                else if (ch == 'B') counts[2]++;
            }
            if (!Arrays.equals(counts, new int[]{1, 1, 1})) {
                return false;
            }
        }

        return true;
    }
}

import java.util.Scanner;

/**
 * Reads a rectangular flag and determines whether it consists of three
 * horizontal stripes of equal height, each stripe being a single colour,
 * and all three colours being distinct. The flag may be examined in its
 * original orientation or after a 90° rotation (up to two rotations).
 *
 * The implementation is deliberately modular to improve readability and
 * maintainability.
 */
public class FlagValidator {

    /** Character used as a placeholder for “no colour yet”. */
    private static final char EMPTY = '-';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int columns = scanner.nextInt();
            char[][] flag = readFlag(scanner, rows, columns);

            if (isThreeUniformStripes(flag, rows, columns)) {
                System.out.println("YES");
                return;
            }

            // Rotate up to two times (90° each) and test again.
            for (int rotation = 0; rotation < 2; rotation++) {
                flag = rotate(flag);
                int tmp = rows;
                rows = columns;
                columns = tmp;

                if (isThreeUniformStripes(flag, rows, columns)) {
                    System.out.println("YES");
                    return;
                }
            }

            System.out.println("NO");
        }
    }

    /**
     * Reads the flag matrix from the supplied {@link Scanner}.
     *
     * @param scanner a scanner positioned at the first two integer inputs
     * @param rows    expected number of rows
     * @param columns expected number of columns
     * @return a newly allocated 2‑D {@code char}`[rows]` array
     */
    private static char[][] readFlag(Scanner scanner, int rows, int columns) {
        char[][] flag = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            if (line.length() != columns) {
                throw new IllegalArgumentException(
                    "Row " + r + " does not contain the expected " + columns + " characters."
                );
            }
            flag[r] = line.toCharArray();
        }
        return flag;
    }

    /**
     * Determines whether the supplied flag consists of three horizontal
     * stripes of equal height, each stripe having a uniform character,
     * and all three characters being distinct.
     *
     * @param flag      the flag matrix
     * @param rows      number of rows in the matrix
     * @param columns   number of columns in the matrix
     * @return {@code true} if the condition is satisfied
     */
    private static boolean isThreeUniformStripes(char[][] flag, int rows, int columns) {
        if (rows % 3 != 0) {
            return false;
        }
        final int stripeHeight = rows / 3;

        final char colour0 = uniformColour(flag, 0, stripeHeight);
        final char colour1 = uniformColour(flag, stripeHeight, stripeHeight);
        final char colour2 = uniformColour(flag, 2 * stripeHeight, stripeHeight);

        // All three colours must be defined and mutually distinct.
        return colour0 != EMPTY
                && colour1 != EMPTY
                && colour2 != EMPTY
                && colour0 != colour1
                && colour1 != colour2
                && colour2 != colour0;
    }

    /**
     * Checks that all characters in the rows spanning {@code startRow}
     * (inclusive) to {@code startRow + height} (exclusive) are identical.
     *
     * @param flag      the flag matrix
     * @param startRow  starting row index of the stripe
     * @param height    height of the stripe
     * @return the uniform character if the stripe is uniform; otherwise {@code EMPTY}
     */
    private static char uniformColour(char[][] flag, int startRow, int height) {
        char expected = EMPTY;

        for (int r = startRow; r < startRow + height; r++) {
            for (int c = 0; c < flag[r].length; c++) {
                char ch = flag[r][c];
                if (expected == EMPTY) {
                    expected = ch;
                } else if (ch != expected) {
                    return EMPTY; // stripe not uniform
                }
            }
        }
        return expected;
    }

    /**
     * Rotates the given matrix 90 degrees clockwise.
     *
     * @param matrix the matrix to rotate
     * @return a new matrix representing the rotated view
     */
    private static char[][] rotate(char[][] matrix) {
        int rows = matrix.length;
        int columns = matrix[0].length;
        char[][] rotated = new char[columns][rows];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < columns; c++) {
                rotated[c][rows - 1 - r] = matrix[r][c];
            }
        }
        return rotated;
    }
}

import java.io.*;
import java.util.*;

public class FlagOfBerland {

    /* --------------------------------------------------------------------- */
    /* I/O helpers – keep them tiny so they can be replaced easily if needed   */
    /* --------------------------------------------------------------------- */
    private static final class FastInput {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastInput(Reader source) {
            this.reader = new BufferedReader(source);
        }

        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
        char nextChar() throws IOException { return nextToken().charAt(0); }
        String nextLine() throws IOException { return reader.readLine(); }
    }

    private static final class FastOutput {
        private final PrintWriter writer;

        FastOutput(Writer sink) {
            this.writer = new PrintWriter(sink, false);
        }

        void print(Object o) { writer.print(o); }
        void println(Object o) { writer.println(o); }
        void close() { writer.close(); }
    }

    /* --------------------------------------------------------------------- */
    /* Core game logic                                                       */
    /* --------------------------------------------------------------------- */
    /** Simple immutable container for a rectangular bounding box. */
    private static final class Bounds {
        final int top, left, bottom, right;   // inclusive coordinates

        Bounds(int top, int left, int bottom, int right) {
            this.top = top;
            this.left = left;
            this.bottom = bottom;
            this.right = right;
        }

        /** Width and height of the rectangle (size of the flag). */
        int width()  { return right - left + 1; }
        int height() { return bottom - top + 1; }
    }

    /**
     * Tries to locate a rectangular region that consists exclusively of {@code colour}
     * and returns its bounding box. Returns {@code null} if the colour does not form
     * a valid flag (i.e. it is not a solid rectangle without extra cells of the same
     * colour outside the rectangle).
     */
    private static Bounds findFlag(char colour, char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        // --- find first occurrence (top‑left corner) ---------------------------------
        int minRow = -1, minCol = -1;
        outer1:
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == colour) {
                    minRow = r;
                    minCol = c;
                    break outer1;
                }
            }
        }
        if (minRow == -1) {                     // colour not present at all
            return null;
        }

        // --- find last occurrence (bottom‑right corner) -----------------------------
        int maxRow = -1, maxCol = -1;
        outer2:
        for (int r = rows - 1; r >= 0; r--) {
            for (int c = cols - 1; c >= 0; c--) {
                if (grid[r][c] == colour) {
                    maxRow = r;
                    maxCol = c;
                    break outer2;
                }
            }
        }

        // sanity check – should never happen with the loops above, but keep it safe
        if (maxRow < minRow || maxCol < minCol) {
            return null;
        }

        // --- verify that the rectangle is completely filled with the colour ----------
        for (int r = minRow; r <= maxRow; r++) {
            for (int c = minCol; c <= maxCol; c++) {
                if (grid[r][c] != colour) {
                    return null;
                }
            }
        }

        // --- ensure no cell outside the rectangle contains the colour -----------------
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (r < minRow || r > maxRow || c < minCol || c > maxCol) {
                    if (grid[r][c] == colour) {
                        return null;
                    }
                }
            }
        }

        // All checks passed → return a size‑only description (width & height)
        return new Bounds(minRow, minCol, maxRow, maxCol);
    }

    /**
     * Reads one test case, processes it and prints the answer.
     */
    private static void solve(FastInput in, FastOutput out) throws IOException {
        int n = in.nextInt();            // rows
        int m = in.nextInt();            // columns

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = in.nextLine();
            grid[i] = line.toCharArray();
        }

        // Find the flag for each colour
        Bounds r = findFlag('R', grid);
        Bounds g = findFlag('G', grid);
        Bounds b = findFlag('B', grid);

        // If any colour does not form a proper flag → answer is NO
        if (r == null || g == null || b == null) {
            out.println("NO");
            return;
        }

        // According to the original specification the three flags must have identical
        // dimensions (width and height).  Their top‑left coordinates are not required
        // to match – only the size matters for the YES verdict.
        boolean sameSize = r.width() == g.width() && r.width() == b.width()
                         && r.height() == g.height() && r.height() == b.height();

        out.println(sameSize ? "YES" : "NO");
    }

    /* --------------------------------------------------------------------- */
    /* Entry point – thin wrapper around the I/O helpers                        */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        try (FastInput  reader = new FastInput(new InputStreamReader(System.in));
             FastOutput writer = new FastOutput(new OutputStreamWriter(System.out))) {

            solve(reader, writer);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.Set;

/**
 * Reads a matrix of characters (R, G, B) and determines whether it forms a
 * valid flag consisting of three equal‑size horizontal or vertical stripes,
 * each stripe being a single colour and all three colours being different.
 */
public class Main {

    /** Entry point */
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] flag = new char[rows][];
        for (int r = 0; r < rows; r++) {
            flag[r] = in.next().toCharArray();
        }

        boolean isFlag = isHorizontal(flag) || isVertical(flag);
        out.print(isFlag ? "YES" : "NO");
        out.flush();
        out.close();
    }

    /** Checks the matrix for a valid horizontal striped flag. */
    private static boolean isHorizontal(char[][] grid) {
        return analyseStripes(grid, true);
    }

    /** Checks the matrix for a valid vertical striped flag. */
    private static boolean isVertical(char[][] grid) {
        // Transpose the matrix conceptually – we can reuse the same logic
        // by swapping rows/columns.
        int rows = grid.length;
        int cols = grid[0].length;
        char[][] transposed = new char[cols][rows];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                transposed[c][r] = grid[r][c];
            }
        }
        return analyseStripes(transposed, false);
    }

    /**
     * Generic stripe analyser.
     *
     * @param grid           matrix to examine (rows × cols)
     * @param treatRowsAsStripes  true → analyse rows as stripes,
     *                           false → analyse columns as stripes.
     * @return true if the matrix forms a valid three‑stripe flag.
     */
    private static boolean analyseStripes(char[][] grid, boolean treatRowsAsStripes) {
        int size = treatRowsAsStripes ? grid.length : grid[0].length;
        int expectedStripCount = 3;

        char expectedColor = ' ';
        int stripLength = 0;
        int stripCount = 0;

        for (int i = 0; i < size; i++) {
            char colour = treatRowsAsStripes
                    ? grid[i][0]                 // row i (first column is enough)
                    : grid[0][i];                // column i (first row is enough)

            // Verify that the whole stripe has the same colour.
            for (int j = 0; j < (treatRowsAsStripes ? grid[i].length : grid.length); j++) {
                char current = treatRowsAsStripes
                        ? grid[i][j]
                        : grid[j][i];
                if (current != colour) {
                    return false; // stripe contains more than one colour.
                }
            }

            // Count how many consecutive stripes we have seen.
            if (colour != expectedColor) {
                // New stripe started.
                if (expectedColor != ' ') { // not the first one
                    if (stripLength != expectedStripCount) {
                        return false; // previous stripe length mismatch.
                    }
                    expectedColor = colour;
                    stripCount++;
                } else {
                    // Initialise first stripe.
                    expectedColor = colour;
                }
                stripLength = 1;
            } else {
                // Still inside the same stripe.
                stripLength++;
            }
        }

        // Final sanity checks.
        if (stripCount != expectedStripCount - 1) {
            return false; // we didn't encounter exactly three stripes.
        }
        // The last stripe length must also equal the others.
        return stripLength == expectedStripCount && stripCount == expectedStripCount - 1;
    }

    /** Fast scanner used for competitive‑programming style input. */
    private static class FastScanner {
        private final BufferedReader reader;

        FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next token (word) from the input. */
        String next() {
            try {
                while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new java.util.StringTokenizer(line);
                }
                return tokenizer.nextToken();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Reads an int from the input. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        // Additional convenience methods can be added here if needed.
        java.util.StringTokenizer tokenizer;
    }
}

/*  -------------------------------------------------------------
    Maintainable refactor of the original “Tripartite Partition”
    checker.  The algorithm is unchanged – it only verifies whether
    the board can be split into three equal contiguous rows or three
    equal contiguous columns that are each filled with a single
    character.  The implementation focuses on readability,
    separation of concerns and removal of dead code.
   ------------------------------------------------------------- */

import java.io.*;
import java.util.*;

public class Main {

    /** Entry point – delegates all work to a dedicated validator. */
    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        new Main().run(in, out);

        out.close();
    }

    /** Reads input, runs the checks and prints “YES” or “NO”. */
    private void run(FastScanner in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] board = readBoard(in, rows);

        boolean answer = canBeTriPartitioned(rows, cols, board);
        out.println(answer ? "YES" : "NO");
    }

    /** Reads the board data from the scanner. */
    private static char[][] readBoard(FastScanner in, int rows) {
        char[][] board = new char[rows][];
        for (int i = 0; i < rows; i++) {
            board[i] = in.next().toCharArray();
        }
        return board;
    }

    /** Determines whether a valid 3‑row or 3‑column tripartite partition exists. */
    private static boolean canBeTriPartitioned(int rows, int cols, char[][] board) {
        // Horizontal (row‑wise) tripartition
        if (rows % 3 == 0) {
            if (hasHorizontalTripartition(rows, cols, board)) {
                return true;
            }
        }

        // Vertical (column‑wise) tripartition
        if (cols % 3 == 0) {
            if (hasVerticalTripartition(rows, cols, board)) {
                return true;
            }
        }

        return false;
    }

    /** Checks whether the board can be split into three equal contiguous rows,
        each filled with a single character. */
    private static boolean hasHorizontalTripartition(int rows, int cols, char[][] board) {
        final int blockSize = rows / 3;          // size of each contiguous row block
        final char[] expectedChar = new char[3]; // character that each block must use

        // 1️⃣ Verify that the first character of each intended block is distinct.
        for (int i = 0; i < 3; i++) {
            expectedChar[i] = board[i * blockSize][0];
        }
        if (!areDistinct(expectedChar)) {
            return false;
        }

        // 2️⃣ Verify that every cell in a block matches the block’s own character.
        for (int block = 0; block < 3; block++) {
            int startRow = block * blockSize;
            char blockChar = expectedChar[block];

            for (int r = startRow; r < startRow + blockSize; r++) {
                for (int c = 0; c < cols; c++) {
                    if (board[r][c] != blockChar) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /** Checks whether the board can be split into three equal contiguous columns,
        each filled with a single character. */
    private static boolean hasVerticalTripartition(int rows, int cols, char[][] board) {
        final int blockSize = cols / 3;          // size of each contiguous column block
        final char[] expectedChar = new char[3]; // character that each block must use

        // 1️⃣ Verify that the first character of each intended block is distinct.
        for (int i = 0; i < 3; i++) {
            expectedChar[i] = board[0][i * blockSize];
        }
        if (!areDistinct(expectedChar)) {
            return false;
        }

        // 2️⃣ Verify that every cell in a block matches the block’s own character.
        for (int block = 0; block < 3; block++) {
            int startCol = block * blockSize;
            char blockChar = expectedChar[block];

            for (int c = startCol; c < startCol + blockSize; c++) {
                for (int r = 0; r < rows; r++) {
                    if (board[r][c] != blockChar) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /** Returns true if the supplied array contains three distinct values. */
    private static boolean areDistinct(char[] values) {
        return values[0] != values[1] && values[0] != values[2] && values[1] != values[2];
    }

    /* -----------------------------------------------------------------
       Fast scanner implementation – kept deliberately small and self‑contained.
       ----------------------------------------------------------------- */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns the next token, expanding the tokenizer lazily. */
        private String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a rectangular board of characters and determines whether it consists of
 * three horizontal bands of a single distinct colour each (R, G or B) or the
 * same property holds after transposing the board.
 *
 * <p>Refactored version of the original {@code P837B} solution – the public API
 * is unchanged but the implementation has been split into small, well‑named
 * methods, unused imports removed and global mutable state eliminated.</p>
 */
public class CubeValidator {

    /** The three colours that must appear exactly once among the bands. */
    private static final Set<Character> REQUIRED_COLORS = Set.of('R', 'G', 'B');

    private final BufferedReader reader;
    private final PrintWriter writer;
    private StringTokenizer tokenizer;

    /** Creates a validator that reads from the given {@link Reader} and writes to
     *  the given {@link Writer}. */
    public CubeValidator(Reader input, Writer output) {
        this.reader = new BufferedReader(input);
        this.writer = new PrintWriter(new BufferedWriter(output));
    }

    /** Entry point used by the original program – kept private to avoid exposing
     *  the old static I/O handling code. */
    private void solve() throws IOException {
        int n = nextInt();   // number of rows
        int m = nextInt();   // number of columns (unused beyond validation)
        char[][] board = readBoard(n);

        boolean ok = hasUniformBands(board) || hasUniformBands(transpose(board));
        writer.println(ok ? "YES" : "NO");
    }

    /** Reads {@code n} lines, each containing {@code m} characters, into a
     *  {@code char[][]} array. */
    private char[][] readBoard(int n) throws IOException {
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = next().toCharArray();
        }
        return board;
    }

    /**
     * Determines whether the board consists of three horizontal bands of equal
     * height, each filled with a single colour, and that the three colours are
     * exactly {@code 'R'}, {@code 'G'} and {@code 'B'} with no repetitions.
     */
    private boolean hasUniformBands(char[][] board) {
        int totalRows = board.length;
        int cols = board[0].length;

        if (totalRows % 3 != 0) {
            return false;
        }
        int bandHeight = totalRows / 3;

        // Store the colour of each band; we need exactly three distinct colours.
        List<Character> colours = new ArrayList<>(3);
        for (int band = 0; band < 3; band++) {
            int startRow = band * bandHeight;
            char expected = board[startRow][0];

            // Colour must belong to the allowed set.
            if (!REQUIRED_COLORS.contains(expected)) {
                return false;
            }

            // Verify that the whole band uses the same colour.
            for (int r = startRow; r < startRow + bandHeight; r++) {
                for (int c = 0; c < cols; c++) {
                    if (board[r][c] != expected) {
                        return false;
                    }
                }
            }
            colours.add(expected);
        }

        // Ensure the three colours are pairwise different.
        return colours.size() == 3 &&
               colours.get(0) != colours.get(1) &&
               colours.get(1) != colours.get(2) &&
               colours.get(0) != colours.get(2);
    }

    /** Returns a transposed copy of the supplied matrix. */
    private static char[][] transpose(char[][] src) {
        int h = src.length;
        int w = src[0].length;
        char[][] dst = new char[w][h];
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                dst[j][i] = src[i][j];
            }
        }
        return dst;
    }

    /** Simple token reader used by the original program. */
    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    private String next() throws IOException {
        return nextToken();
    }

    /** Original program entry point – now delegates to the refactored instance. */
    public static void main(String[] args) throws Exception {
        try (CubeValidator validator = new CubeValidator(
                new InputStreamReader(System.in),
                new OutputStreamWriter(System.out))) {
            validator.solve();
        }
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Main entry point of the solution.
 *
 * The problem checks whether a given n×m grid of characters can be split
 * into three equal‑height horizontal stripes (or three equal‑width vertical
 * stripes after transposition) that are each filled with a single colour,
 * and that the three colours are exactly 'R', 'G' and 'B' in any order.
 */
public class Main {

    public static void main(String[] args) {
        // Single test case as described in the original source.
        solve(System.in, System.out);
    }

    /**
     * Reads from the supplied {@code InputStream} and writes the answer to the
     * supplied {@code PrintWriter}.
     */
    private static void solve(InputStream in, PrintWriter out) {
        FastScanner fs = new FastScanner(in);
        // The original code processes only one test case.
        processTestCase(fs, out);
        out.close();
    }

    /** Handles the logic for one test case. */
    private static void processTestCase(FastScanner fs, PrintWriter out) throws IOException {
        int n = fs.nextInt();       // number of rows
        int m = fs.nextInt();       // number of columns

        char[][] grid = fs.readCharMatrix(n, m);

        boolean verticalPattern = isVerticalStripedPattern(grid);
        boolean horizontalPattern = isVerticalStripedPattern(transpose(grid));

        out.println((verticalPattern || horizontalPattern) ? "YES" : "NO");
    }

    /**
     * Determines whether the matrix consists of three equal‑height horizontal
     * stripes, each uniformly coloured with one of the three colours 'R', 'G',
     * 'B'. The order of the colours does not matter.
     *
     * @param matrix the matrix to validate
     * @return {@code true} if the matrix matches the required striped pattern
     */
    private static boolean isVerticalStripedPattern(char[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        // Must be divisible into three equal stripes.
        if (rows % 3 != 0) {
            return false;
        }
        int stripeHeight = rows / 3;
        boolean hasRed = false, hasGreen = false, hasBlue = false;

        for (int i = 0; i < 3; i++) {
            int stripeStart = i * stripeHeight;
            char expectedColour = matrix[stripeStart][0];

            // Verify that every cell in this stripe has the expected colour.
            if (!allEqual(matrix, stripeStart, stripeHeight, expectedColour)) {
                return false;
            }

            // Record which colour we have seen.
            switch (expectedColour) {
                case 'R' -> hasRed = true;
                case 'G' -> hasGreen = true;
                case 'B' -> hasBlue = true;
                default -> return false;   // unexpected character
            }
        }
        // All three required colours must have been seen.
        return hasRed && hasGreen && hasBlue;
    }

    /** Helper that checks whether a rectangular block of the matrix is filled
     *  entirely with a specific character. */
    private static boolean allEqual(char[][] m, int startRow, int height, char ch) {
        for (int r = startRow; r < startRow + height; r++) {
            if (!Arrays.equals(m[r], new char[m[r].length])) { // ensure length is known
                // The array is already allocated, just compare each element.
                for (int c = 0; c < m[r].length; c++) {
                    if (m[r][c] != ch) {
                        return false;
                    }
                }
            }
            // Simpler loop without Arrays.equals for primitive char[].
            for (int c = 0; c < m[r].length; c++) {
                if (m[r][c] != ch) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Returns the transpose of the given matrix (rows ↔ columns). */
    private static char[][] transpose(char[][] src) {
        int rows = src.length;
        int cols = src[0].length;
        char[][] dst = new char[cols][rows];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                dst[c][r] = src[r][c];
            }
        }
        return dst;
    }

    /**
     * Fast scanner that works with character streams and tokenises integers,
     * characters and whole matrices efficiently.
     */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[16 * 1024];
        private int ptr = 0, len = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next non‑whitespace byte. */
        private int readByte() throws IOException {
            if (ptr >= len) {
                len = stream.read(buffer);
                ptr = 0;
                if (len <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        /** Skips over whitespace characters. */
        private int skipWhite() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c <= ' ');
            return c;
        }

        /** Reads the next integer (supports optional leading ‘-’). */
        int nextInt() throws IOException {
            int c = skipWhite();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return value * sign;
        }

        /** Reads a single non‑whitespace character. */
        char readChar() throws IOException {
            int c = skipWhite();
            return (char) c;
        }

        /** Reads a matrix of the requested size (row‑major order). */
        char[][] readCharMatrix(int rows, int cols) throws IOException {
            char[][] mat = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    mat[r][c] = readChar();
                }
            }
            return mat;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Enum representing the three allowed colors. */
    private enum Color {
        R('R'), G('G'), B('B');

        private final char symbol;
        Color(char symbol) { this.symbol = symbol; }
        public char symbol() { return symbol; }
    }

    public static void main(String[] args) throws IOException {
        /* -------------------------------------------------------------
         *  Read dimensions and grid from standard input
         * ------------------------------------------------------------- */
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in))) {

            String[] dims = reader.readLine().split("\\s+");
            int rows = Integer.parseInt(dims[0]);
            int cols = Integer.parseInt(dims[1]);

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                String line = reader.readLine();
                grid[i] = line.toCharArray();
            }

            /* ---------------------------------------------------------
             *  Early exit if neither dimension can be divided by 3
             * --------------------------------------------------------- */
            if (!canBePartitioned(rows, cols)) {
                System.out.println("NO");
                return;
            }

            /* ---------------------------------------------------------
             *  Check horizontal partitions (rows divisible by 3)
             * --------------------------------------------------------- */
            if (rows % 3 == 0 && checkHorizontalPartitions(grid, rows, cols)) {
                System.out.println("YES");
                return;
            }

            /* ---------------------------------------------------------
             *  Check vertical partitions (columns divisible by 3)
             * --------------------------------------------------------- */
            if (cols % 3 == 0 && checkVerticalPartitions(grid, rows, cols)) {
                System.out.println("YES");
                return;
            }

            System.out.println("NO");
        }
    }

    /** Returns true if at least one dimension is divisible by 3. */
    private static boolean canBePartitioned(int rows, int cols) {
        return rows % 3 == 0 || cols % 3 == 0;
    }

    /** Validates three horizontal strips of equal height. */
    private static boolean checkHorizontalPartitions(char[][] grid, int rows, int cols) {
        int blockHeight = rows / 3;
        Set<Character> colors = new HashSet<>();

        for (int i = 0; i < 3; i++) {
            int startRow = i * blockHeight;
            if (!isUniformRowBlock(grid, startRow, blockHeight, cols)) {
                return false; // a strip is not uniform
            }
            colors.add(grid[startRow][0]); // colour of this strip
        }

        // The three strips must use exactly the three allowed colours
        return colors.equals(Set.of(Color.R.symbol(), Color.G.symbol(), Color.B.symbol()));
    }

    /** Validates three vertical strips of equal width. */
    private static boolean checkVerticalPartitions(char[][] grid, int rows, int cols) {
        int blockWidth = cols / 3;
        Set<Character> colors = new HashSet<>();

        for (int i = 0; i < 3; i++) {
            int startCol = i * blockWidth;
            if (!isUniformColumnBlock(grid, startCol, blockWidth, rows)) {
                return false; // a strip is not uniform
            }
            colors.add(grid[0][startCol]); // colour of this strip
        }

        return colors.equals(Set.of(Color.R.symbol(), Color.G.symbol(), Color.B.symbol()));
    }

    /** Checks that every cell in a rectangular row block is equal to the first cell’s value. */
    private static boolean isUniformRowBlock(char[][] grid, int startRow, int height, int width) {
        char expected = grid[startRow][0];
        for (int r = startRow; r < startRow + height; r++) {
            for (int c = 0; c < width; c++) {
                if (grid[r][c] != expected) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Checks that every cell in a rectangular column block is equal to the first cell’s value. */
    private static boolean isUniformColumnBlock(char[][] grid, int startCol, int width, int height) {
        char expected = grid[0][startCol];
        for (int c = startCol; c < startCol + width; c++) {
            for (int r = 0; r < height; r++) {
                if (grid[r][c] != expected) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Utility that checks whether a given grid can be interpreted as a
 * “flag” (three equal‑size stripes) either horizontally or vertically,
 * and that the three colours (R, G, B) appear the same number of times.
 *
 * The program reads:
 *   - the dimensions {@code n} (rows) and {@code m} (columns)
 *   - {@code n} strings, each exactly {@code m} characters long,
 *     representing the rows of the grid.
 *
 * It prints {@code YES} if the grid satisfies the flag conditions,
 * otherwise {@code NO}.
 */
public final class FlagValidator {

    private FlagValidator() {
        // Utility class – no instances
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();   // n
            int cols = scanner.nextInt();   // m

            // Defensive reading – each row must contain exactly {@code cols} characters
            List<String> grid = new ArrayList<>(rows);
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                if (line.length() != cols) {
                    System.out.println("NO");
                    return;
                }
                grid.add(line);
            }

            if (isValidFlag(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Determines whether the supplied grid represents a valid flag. */
    private static boolean isValidFlag(List<String> grid) {
        if (!hasBalancedColours(grid)) {
            return false;
        }
        return hasHorizontalFlag(grid) || hasVerticalFlag(grid);
    }

    /** Checks that each of the three colours appears the same number of times. */
    private static boolean hasBalancedColours(List<String> grid) {
        int red = 0, green = 0, blue = 0;
        for (String row : grid) {
            for (char c : row.toCharArray()) {
                switch (c) {
                    case 'R' -> red++;
                    case 'G' -> green++;
                    case 'B' -> blue++;
                }
            }
        }
        return red == green && green == blue;
    }

    /** Detects a horizontal flag: each row is identical and consists of three
     *  equal‑width stripes, each stripe using a single distinct colour. */
    private static boolean hasHorizontalFlag(List<String> grid) {
        if (grid.isEmpty()) {
            return false;
        }
        String firstRow = grid.get(0);
        int cols = firstRow.length();

        // Width of a stripe must be an integer divisor of the total width
        if (cols % 3 != 0) {
            return false;
        }
        int stripeWidth = cols / 3;

        // Verify that every row is identical to the first row
        for (String row : grid) {
            if (!row.equals(firstRow)) {
                return false;
            }
        }

        // Extract the three colour blocks from the first row
        String block1 = firstRow.substring(0, stripeWidth);
        String block2 = firstRow.substring(stripeWidth, 2 * stripeWidth);
        String block3 = firstRow.substring(2 * stripeWidth);

        // Each block must be composed of a single repeated character
        if (!isUniform(block1) || !isUniform(block2) || !isUniform(block3)) {
            return false;
        }

        // The three colours must be distinct
        char c1 = block1.charAt(0);
        char c2 = block2.charAt(0);
        char c3 = block3.charAt(0);
        return c1 != c2 && c2 != c3 && c1 != c3;
    }

    /** Detects a vertical flag: each column is identical and consists of three
     *  equal‑height stripes, each stripe using a single distinct colour. */
    private static boolean hasVerticalFlag(List<String> grid) {
        int rows = grid.size();
        int cols = grid.get(0).length();

        // Height of a stripe must be an integer divisor of the total height
        if (rows % 3 != 0) {
            return false;
        }
        int stripeHeight = rows / 3;

        // Verify that every column is identical to the first column
        char[] referenceColumn = new char[rows];
        for (int r = 0; r < rows; r++) {
            referenceColumn[r] = grid.get(r).charAt(0);
        }

        for (int c = 0; c < cols; c++) {
            for (int r = 0; r < rows; r++) {
                if (grid.get(r).charAt(c) != referenceColumn[r]) {
                    return false;
                }
            }
        }

        // Extract the three colour blocks from the first column
        StringBuilder verticalBlock = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            verticalBlock.append(grid.get(r).charAt(0));
        }

        String block1 = verticalBlock.substring(0, stripeHeight);
        String block2 = verticalBlock.substring(stripeHeight, 2 * stripeHeight);
        String block3 = verticalBlock.substring(2 * stripeHeight);

        // Each block must be uniform
        if (!isUniform(block1) || !isUniform(block2) || !isUniform(block3)) {
            return false;
        }

        // The three colours must be distinct
        char c1 = block1.charAt(0);
        char c2 = block2.charAt(0);
        char c3 = block3.charAt(0);
        return c1 != c2 && c2 != c3 && c1 != c3;
    }

    /** Returns {@code true} if the supplied string consists of a single repeated character. */
    private static boolean isUniform(String s) {
        if (s.isEmpty()) {
            return false;
        }
        char first = s.charAt(0);
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) != first) {
                return false;
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solver for the problem checking whether the board can be divided into three
 * uniform row blocks or three uniform column blocks each containing exactly
 * one distinct character, and those three characters are all different.
 */
public final class Main {

    private static final String YES = "YES";
    private static final String NO = "NO";

    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public Main(BufferedReader reader) {
        this.reader = reader;
    }

    /** Entry point used by {@link Solver}. */
    public void solve() throws IOException {
        tokenizer = null;
        int n = readInt();          // number of rows
        int m = readInt();          // number of columns

        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = readToken().toCharArray();
        }

        boolean possible = canBePartitioned(board, n, m);
        System.out.println(possible ? YES : NO);
    }

    /** Reads an {@code int} from the current tokenizer (or the next line). */
    private int readInt() throws IOException {
        return Integer.parseInt(readToken());
    }

    /** Reads the next non‑empty token from the input stream. */
    private String readToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    /**
     * Determines whether the board can be partitioned either by rows or by
     * columns into three contiguous blocks each containing a single distinct
     * character, with the three characters being different from each other.
     *
     * @param board the character board
     * @param rows  number of rows
     * @param cols  number of columns
     * @return {@code true} if such a partition exists
     */
    private boolean canBePartitioned(char[][] board, int rows, int cols) {
        // ----- check possible row partition -----
        if (rows % 3 == 0) {
            int segment = rows / 3;
            Set<Character> first = collectSet(board, 0, segment, true);
            Set<Character> second = collectSet(board, segment, 2 * segment, true);
            Set<Character> third = collectSet(board, 2 * segment, rows, true);

            if (first.size() == 1 && second.size() == 1 && third.size() == 1
                    && first != second && second != third && first != third) {
                return true; // all three row segments are uniform and distinct
            }
        }

        // ----- check possible column partition -----
        if (cols % 3 == 0) {
            int segment = cols / 3;
            Set<Character> first = collectSet(board, 0, segment, false);
            Set<Character> second = collectSet(board, segment, 2 * segment, false);
            Set<Character> third = collectSet(board, 2 * segment, cols, false);

            if (first.size() == 1 && second.size() == 1 && third.size() == 1
                    && first != second && second != third && first != third) {
                return true; // all three column segments are uniform and distinct
            }
        }

        return false; // no valid partition found
    }

    /**
     * Collects the distinct characters appearing in a contiguous range of rows
     * or columns.
     *
     * @param board   the board
     * @param start   start index (inclusive)
     * @param end     end index (exclusive)
     * @param rows    {@code true} to iterate over rows, {@code false} for columns
     * @return a set of distinct characters
     */
    private Set<Character> collectSet(char[][] board, int start, int end, boolean rows) {
        Set<Character> result = new HashSet<>();
        if (rows) {
            for (int i = start; i < end; i++) {
                for (char c : board[i]) {
                    result.add(c);
                }
            }
        } else {
            for (int i = start; i < end; i++) {
                for (char[] row : board) {
                    result.add(row[i]);
                }
            }
        }
        return result;
    }
}

