import java.io.PrintWriter;
import java.io.IOException;
import java.util.*;

public class Main {

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        new Solver().solve(fs, out);
        out.close();
    }

    /**--------------------------------------------------------------
     *  Solver – contains the logic for checking the required pattern.
     * --------------------------------------------------------------*/
    private static class Solver {

        /** Checks whether a string consists of a single repeated character. */
        private static boolean isUniform(String s) {
            for (int i = 1; i < s.length(); i++) {
                if (s.charAt(i) != s.charAt(i - 1)) {
                    return false;
                }
            }
            return true;
        }

        /**
         * Returns {@code true} if the array can be split into three equal
         * blocks where each block contains identical strings, every string
         * inside a block is uniform and the three block strings are pairwise
         * distinct.
         */
        private boolean isTripleBlockCondition(String[] rows) {
            int total = rows.length;
            if (total % 3 != 0) {
                return false;
            }
            int blockSize = total / 3;

            // representatives of the three blocks
            String block0 = rows[0];
            String block1 = rows[blockSize];
            String block2 = rows[2 * blockSize];

            // each representative must be uniform
            if (!isUniform(block0) || !isUniform(block1) || !isUniform(block2)) {
                return false;
            }

            // every string in a block must equal its block's representative
            for (int i = 0; i < blockSize; i++) {
                if (!rows[i].equals(block0)) return false;
                if (!rows[blockSize + i].equals(block1)) return false;
                if (!rows[2 * blockSize + i].equals(block2)) return false;
            }

            // all three representatives must be distinct
            return !block0.equals(block1) && !block1.equals(block2) && !block2.equals(block0);
        }

        /** Transposes a matrix represented by rows of strings. */
        private String[] transpose(String[] rows, int columnCount) {
            String[] transposed = new String[columnCount];
            for (int c = 0; c < columnCount; c++) {
                StringBuilder sb = new StringBuilder();
                for (String r : rows) {
                    sb.append(r.charAt(c));
                }
                transposed[c] = sb.toString();
            }
            return transposed;
        }

        /** Main entry point for a single test case. */
        public void solve(FastScanner in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            String[] data = new String[rows];
            for (int i = 0; i < rows; i++) {
                data[i] = in.next();
            }

            // 1️⃣  Check pattern in the original orientation.
            if (isTripleBlockCondition(data)) {
                out.println("YES");
                return;
            }

            // 2️⃣  If possible, check pattern after transposition.
            if (cols % 3 == 0) {
                String[] transposed = transpose(data, cols);
                if (isTripleBlockCondition(transposed)) {
                    out.println("YES");
                    return;
                }
            }

            // No valid pattern found.
            out.println("NO");
        }
    }

    /**--------------------------------------------------------------
     *  FastScanner – lightweight scanner for competitive programming.
     * --------------------------------------------------------------*/
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int ptr = 0, len = 0;

        FastScanner() {
            this.stream = System.in;
        }

        private int readByte() throws IOException {
            if (len == -1) return -1;
            if (ptr >= len) {
                len = stream.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** Reads the next non‑whitespace character. */
        private int readChar() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c <= ' ' && c != -1);
            return c;
        }

        /** Reads next integer. */
        int nextInt() throws IOException {
            int sign = 1;
            int c = readChar();
            if (c == '-') {
                sign = -1;
                c = readChar();
            }
            int result = 0;
            do {
                result = result * 10 + (c - '0');
                c = readChar();
            } while (c >= '0' && c <= '9');
            return result * sign;
        }

        /** Reads next token (sequence of non‑whitespace characters). */
        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c = readChar();
            while (c > ' ') {
                sb.append((char) c);
                c = readChar();
            }
            return sb.toString();
        }
    }
}

import java.io.IOException;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 * The logic is unchanged, but the code is now split into small,
 * well‑named methods, uses early returns and avoids magic numbers.
 */
public class Main {

    private static final Scanner SCANNER = new Scanner(System.in);

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            solve(sc);
        }
    }

    private static void solve(Scanner sc) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        sc.nextLine();                     // consume the line‑break

        char[][] grid = new char[n][];
        int red = 0, green = 0, blue = 0;

        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            grid[i] = line.toCharArray();
            for (char ch : line.toCharArray()) {
                switch (ch) {
                    case 'R' -> red++;
                    case 'G' -> green++;
                    case 'B' -> blue++;
                }
            }
        }

        // Basic validation – the three colours must appear equally often
        if (red != green || red != blue) {
            System.out.println("NO");
            return;
        }

        char baseColour = grid[0][0];
        int blockWidth = lastIndexOfConsecutive(baseColour, grid[0]);
        int blockHeight = lastIndexOfConsecutive(baseColour, column(grid, 0));

        // Remove the top‑left rectangle that consists of the base colour
        clearRectangle(grid, 0, 0, blockHeight, blockWidth, baseColour);

        // Depending on whether the first row occupies the whole width,
        // we either have vertical or horizontal stripes.
        if (blockWidth == m - 1) {                     // vertical stripes
            if (!processVerticalStripe(grid, blockWidth, blockHeight, n, m)) {
                System.out.println("NO");
                return;
            }
        } else {                                        // horizontal stripes
            if (!processHorizontalStripe(grid, blockWidth, blockHeight, n, m)) {
                System.out.println("NO");
                return;
            }
        }

        System.out.println(isAllEmpty(grid) ? "YES" : "NO");
    }

    /** Returns the last index (inclusive) of `target` starting at position 0. */
    private static int lastIndexOfConsecutive(char target, char[] array) {
        int lastIdx = array.length - 1;
        for (int i = 0; i < array.length; i++) {
            if (array[i] != target) {
                return i - 1;
            }
            lastIdx = i;
        }
        return lastIdx;
    }

    /** Extracts a single column from a 2‑D char array. */
    private static char[] column(char[][] grid, int col) {
        char[] col = new char[grid.length];
        for (int i = 0; i < grid.length; i++) {
            col[i] = grid[i][col];
        }
        return col;
    }

    /** Clears a rectangular region filled with `target` to the character '.'. */
    private static void clearRectangle(char[][] grid,
                                       int rowStart, int colStart,
                                       int rowEndInclusive, int colEndInclusive,
                                       char target) {
        for (int i = rowStart; i <= rowEndInclusive; i++) {
            for (int j = colStart; j <= colEndInclusive; j++) {
                if (grid[i][j] == target) {
                    grid[i][j] = '.';
                }
            }
        }
    }

    /** Handles the case where the pattern consists of vertical colour blocks. */
    private static boolean processVerticalStripe(char[][] grid,
                                                  int width,
                                                  int height,
                                                  int n,
                                                  int m) {
        // The three blocks must fit completely inside the grid.
        if (height + 1 >= n || 2 * height + 2 >= n) {
            return false;
        }

        char secondColour = grid[height + 1][0];
        clearRectangle(grid, height + 1, 0, 2 * height + 1, width, secondColour);

        char thirdColour = grid[2 * height + 2][0];
        clearRectangle(grid, 2 * height + 2, 0, 3 * height + 2, width, thirdColour);

        return true;
    }

    /** Handles the case where the pattern consists of horizontal colour blocks. */
    private static boolean processHorizontalStripe(char[][] grid,
                                                    int width,
                                                    int height,
                                                    int n,
                                                    int m) {
        // The three blocks must fit completely inside the grid.
        if (width + 1 >= m || 2 * width + 2 >= m) {
            return false;
        }

        char secondColour = grid[0][width + 1];
        clearRectangle(grid, 0, width + 1, height, 2 * width + 1, secondColour);

        char thirdColour = grid[0][2 * width + 2];
        clearRectangle(grid, 0, 2 * width + 2, height, 3 * width + 2, thirdColour);

        return true;
    }

    /** Returns true iff every cell of the grid is the character '.'. */
    private static boolean isAllEmpty(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell != '.') {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for the colour‑grid validation problem.
 *
 * <p>
 * The program reads an {@code n × m} grid consisting of the characters
 * {@code 'R'}, {@code 'G'} and {@code 'B'}.  It checks whether the total
 * number of each colour is the same and, additionally, whether the grid
 * consists of three equal‑sized stripes (either horizontally or vertically)
 * where each stripe is filled with a single colour.
 * </p>
 *
 * <p>Refactoring goals:</p>
 * <ul>
 *   <li>Descriptive naming of variables and methods.</li>
 *   <li>Extraction of logical parts into small, reusable helpers.</li>
 *   <li>Use of {@code try‑with‑resources} for automatic resource handling.</li>
 *   <li>Clear separation of concerns (input, validation, output).</li>
 * </ul>
 */
public class Main {

    /** PrintWriter used for output – closed automatically. */
    private static final PrintWriter OUT = createPrintWriter();

    /** BufferedReader wrapper that reads from standard input. */
    private static final BufferedReader IN = createBufferedReader();

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        try {
            solve();
        } finally {
            /* Resources are closed in the finally‑block to guarantee closure
               even when an exception is thrown. */
            close(IN);
            close(OUT);
        }
    }

    /** Orchestrates the whole solution. */
    private static void solve() throws IOException {
        int rows = readInt();
        int cols = readInt();

        char[][] grid = readGrid(rows);

        CountResult counts = countColours(grid);
        if (!counts.areEqual()) {
            OUT.println("NO");
            return;
        }

        if (isUniformByRows(grid, rows, cols) || isUniformByColumns(grid, rows, cols)) {
            OUT.println("YES");
            return;
        }

        OUT.println("NO");
    }

    /** Reads the grid dimensions and the grid itself. */
    private static char[][] readGrid(int rows) throws IOException {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = IN.readLine();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /** Counts occurrences of {@code 'R'}, {@code 'G'} and {@code 'B'}. */
    private static CountResult countColours(char[][] grid) {
        int r = 0, g = 0, b = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                switch (cell) {
                    case 'R' -> r++;
                    case 'G' -> g++;
                    case 'B' -> b++;
                }
            }
        }
        return new CountResult(r, g, b);
    }

    /** Checks whether three horizontal blocks of equal height are monochrome. */
    private static boolean isUniformByRows(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }
        final int blockSize = rows / 3;
        for (int block = 0; block < 3; block++) {
            int startRow = block * blockSize;
            char expected = grid[startRow][0];           // first cell of the block
            for (int r = startRow; r < startRow + blockSize; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != expected) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /** Checks whether three vertical blocks of equal width are monochrome. */
    private static boolean isUniformByColumns(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }
        final int blockSize = cols / 3;
        for (int block = 0; block < 3; block++) {
            int startCol = block * blockSize;
            char expected = grid[0][startCol];           // first cell of the block
            for (int r = 0; r < rows; r++) {
                for (int c = startCol; c < startCol + blockSize; c++) {
                    if (grid[r][c] != expected) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /** Utility class that holds the three colour counts and a helper method. */
    private static final class CountResult {
        private final int red;
        private final int green;
        private final int blue;

        CountResult(int red, int green, int blue) {
            this.red = red;
            this.green = green;
            this.blue = blue;
        }

        /** Returns {@code true} if the three counts are equal. */
        boolean areEqual() {
            return red == green && green == blue;
        }
    }

    /** Creates a {@link PrintWriter} that writes to standard output. */
    private static PrintWriter createPrintWriter() {
        return new PrintWriter(
                new BufferedWriter(
                        new OutputStreamWriter(System.out)));
    }

    /** Creates a {@link BufferedReader} that reads from standard input. */
    private static BufferedReader createBufferedReader() {
        return new BufferedReader(new InputStreamReader(System.in));
    }

    /** Safely closes a {@link Closeable}. */
    private static void close(Closeable c) {
        if (c != null) {
            try {
                c.close();
            } catch (IOException ignored) {
            }
        }
    }

    /** Reads the next token from the input stream and parses it as {@code int}. */
    private static int readInt() throws IOException {
        String token = nextToken();
        return Integer.parseInt(token);
    }

    /** Reads the next token from the input stream. */
    private static String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(IN.readLine());
        }
        return st.nextToken();
    }

    /* --------------------------------------------------------------------- */
    /*  Supporting fields for tokenising input                               */
    /* --------------------------------------------------------------------- */
    private static StringTokenizer st = null;
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Reads a matrix from standard input and checks whether it can be split
 * into three equal horizontal strips or three equal vertical strips such that
 * each strip consists of a single repeating character and the three characters
 * are all different.
 * Outputs "YES" if either condition holds, otherwise "NO".
 */
public class Rextester {

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in))) {

            StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
            int rows = Integer.parseInt(tokenizer.nextToken());
            int columns = Integer.parseInt(tokenizer.nextToken());

            char[][] flag = new char[rows][];
            for (int i = 0; i < rows; i++) {
                flag[i] = reader.readLine().toCharArray();
            }

            PrintWriter out = new PrintWriter(System.out, true);
            if (isValidHorizontalPattern(flag) || isValidVerticalPattern(flag)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
            out.flush();
        }
    }

    /** Checks the horizontal‑strip condition. */
    private static boolean isValidHorizontalPattern(char[][] flag) {
        int rows = flag.length;
        int cols = flag[0].length;

        if (rows % 3 != 0) {
            return false;
        }
        int blockSize = rows / 3;

        // three row‑colors must differ
        char color0 = flag[0][0];
        char color1 = flag[blockSize][0];
        char color2 = flag[2 * blockSize][0];
        if (!areColorsDistinct(color0, color1, color2)) {
            return false;
        }

        // each strip must be uniform and equal to its designated color
        return isBlockUniform(flag, 0, blockSize, color0)
                && isBlockUniform(flag, blockSize, blockSize, color1)
                && isBlockUniform(flag, 2 * blockSize, blockSize, color2);
    }

    /** Checks the vertical‑strip condition. */
    private static boolean isValidVerticalPattern(char[][] flag) {
        int rows = flag.length;
        int cols = flag[0].length;

        if (cols % 3 != 0) {
            return false;
        }
        int blockSize = cols / 3;

        // three column‑colors must differ
        char color0 = flag[0][0];
        char color1 = flag[0][blockSize];
        char color2 = flag[0][2 * blockSize];
        if (!areColorsDistinct(color0, color1, color2)) {
            return false;
        }

        // each strip must be uniform and equal to its designated color
        return isBlockUniformByColumn(flag, 0, blockSize, color0)
                && isBlockUniformByColumn(flag, blockSize, blockSize, color1)
                && isBlockUniformByColumn(flag, 2 * blockSize, blockSize, color2);
    }

    /** Returns true if the three supplied colors are all different. */
    private static boolean areColorsDistinct(char... colors) {
        return colors[0] != colors[1] && colors[0] != colors[2] && colors[1] != colors[2];
    }

    /** Checks that a rectangular block of rows is filled with the same character. */
    private static boolean isBlockUniform(char[][] flag, int startRow, int height, char expected) {
        int endRow = startRow + height;
        for (int r = startRow; r < endRow; r++) {
            for (int c = 0; c < flag[r].length; c++) {
                if (flag[r][c] != expected) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Checks that a rectangular block of columns is filled with the same character. */
    private static boolean isBlockUniformByColumn(char[][] flag, int startCol, int width, char expected) {
        for (char[] row : flag) {
            for (int c = startCol; c < startCol + width; c++) {
                if (row[c] != expected) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    private static final PrintWriter OUT = new PrintWriter(System.out);
    private static final int ALPHABET_SIZE = 26;

    public static void main(String[] args) throws IOException {
        Reader.init(System.in);

        int rows = Reader.nextInt();
        int cols = Reader.nextInt();

        char[][] grid = new char[rows][cols];
        boolean[] stopped = new boolean[ALPHABET_SIZE];   // characters that may not re‑appear
        int[] counts = new int[ALPHABET_SIZE];             // frequency of each character
        boolean failed = false;

        /* ---------- Row validation ---------- */
        char previousRowChar = 0;
        for (int i = 0; i < rows; i++) {
            String line = Reader.next();

            // 1) Every character in the row must be identical
            if (!allEqual(line, line.charAt(0))) {
                failed = true;
            }

            // 2) A character can appear only once across rows.
            //    When a new row‑character appears, mark the previous one as “stopped”.
            if (i > 0 && line.charAt(0) != previousRowChar) {
                stopped[previousRowChar - 'A'] = true;
            }
            if (stopped[line.charAt(0) - 'A']) {
                failed = true;                     // re‑use of a stopped character → reject
            }

            if (!failed) {
                counts[line.charAt(0) - 'A']++;      // count only when we are still valid
                previousRowChar = line.charAt(0);
                grid[i] = line.toCharArray();        // keep the row for the column pass
            }
        }

        boolean answer = !failed &&
                counts['R' - 'A'] == counts['G' - 'A'] &&
                counts['G' - 'A'] == counts['B' - 'A'];

        if (answer) {
            OUT.println("YES");
            OUT.close();
            return;
        }

        /* ---------- Column validation (reset state) ---------- */
        Arrays.fill(stopped, false);
        Arrays.fill(counts, 0);
        failed = false;
        char previousColChar = 0;

        for (int j = 0; j < cols; j++) {
            char first = grid[0][j];

            // Whole column must be constant
            for (int i = 0; i < rows; i++) {
                if (grid[i][j] != first) {
                    failed = true;
                    break;
                }
            }
            if (failed) {
                break;
            }

            // Same ordering constraint as for rows
            if (j > 0 && first != previousColChar) {
                stopped[previousColChar - 'A'] = true;
            }
            if (stopped[first - 'A']) {
                failed = true;
                break;
            }
            if (!failed) {
                counts[first - 'A']++;               // reuse the same array for column counts
                previousColChar = first;
            }
        }

        answer = !failed &&
                counts['R' - 'A'] == counts['G' - 'A'] &&
                counts['G' - 'A'] == counts['B' - 'A'];

        OUT.println(answer ? "YES" : "NO");
        OUT.close();
    }

    /** Checks whether all characters of the string are equal to {@code expected}. */
    private static boolean allEqual(String s, char expected) {
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != expected) {
                return false;
            }
        }
        return true;
    }

    /** Simple fast scanner used by the original program. */
    static class Reader {
        private static BufferedReader reader;
        private static StringTokenizer tokenizer;

        static void init(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = new StringTokenizer("");
        }

        static String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        static int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a matrix of characters, checks whether it (or its 90° rotation)
 * consists of three equal‑height horizontal strips, each filled with a single
 * distinct character. Prints "YES" if the condition is satisfied, otherwise
 * "NO".
 *
 * The implementation is deliberately split into small, well‑named methods
 * and uses a fast scanner to keep I/O code clean and maintainable.
 */
public class Solution {

    /** Fast, low‑level scanner that avoids the overhead of {@link Scanner}. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        /** Reads a single byte, filling the buffer when necessary. */
        private int readByte() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        private boolean isSpace(int ch) {
            return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
        }

        /** Reads the next integer from the input. */
        int nextInt() throws IOException {
            int c = readByte();
            while (isSpace(c)) c = readByte();

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            long value = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                value = value * 10 + (c - '0');
                c = readByte();
            } while (!isSpace(c));

            return (int) (sign * value);
        }

        /** Reads the rest of the current line (trimmed). */
        String nextLine() throws IOException {
            int c = readByte();
            while (isSpace(c)) c = readByte();

            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpace(c));

            return sb.toString().trim();
        }
    }

    /** Rotates a matrix 90° clockwise. */
    private static char[][] rotate(char[][] src) {
        int rows = src.length;
        int cols = src[0].length;
        char[][] dst = new char[cols][rows];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                dst[c][r] = src[r][c];
            }
        }
        return dst;
    }

    /**
     * Determines whether the given matrix consists of three horizontal strips
     * of equal height, each strip containing a single distinct character.
     *
     * @return {@code true} if the condition holds, {@code false} otherwise.
     */
    private static boolean isThreeUniformHorizontalStrips(char[][] mat) {
        int rows = mat.length;
        int cols = mat[0].length;

        // The number of rows must be divisible by three.
        if (rows % 3 != 0) {
            return false;
        }

        int stripHeight = rows / 3;
        Set<Character> distinctChars = new HashSet<>();

        for (int strip = 0; strip < 3; strip++) {
            Set<Character> stripChars = new HashSet<>();

            int firstRow = strip * stripHeight;
            for (int r = firstRow; r < firstRow + stripHeight; r++) {
                for (int c = 0; c < cols; c++) {
                    stripChars.add(mat[r][c]);
                }
            }

            // Each strip must be uniform.
            if (stripChars.size() != 1) {
                return false;
            }

            distinctChars.add(stripChars.iterator().next());
        }

        // All three characters must be different.
        return distinctChars.size() == 3;
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        int n = fs.nextInt();   // number of rows
        int m = fs.nextInt();   // number of columns

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = fs.nextLine().toCharArray();
        }

        char[][] rotated = rotate(grid);

        if (isThreeUniformHorizontalStrips(grid) || isThreeUniformHorizontalStrips(rotated)) {
            out.println("YES");
        } else {
            out.println("NO");
        }

        out.close();
    }
}

import java.io.*;
import java.util.*;

public final class Main {

    /* -------------------------------------------------------------
     *  FastScanner – a lightweight replacement for java.util.Scanner
     * ------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() throws IOException {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        FastScanner(String fileName) throws IOException {
            br = new BufferedReader(new FileInputStream(fileName));
        }

        private String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        String nextLine() throws IOException {
            String line = br.readLine();
            if (line == null) line = "";
            return line;
        }

        void close() throws IOException {
            br.close();
        }
    }

    /* -------------------------------------------------------------
     *  Utility methods
     * ------------------------------------------------------------- */
    private static boolean isUniform(String s) {
        for (int i = 0; i < s.length() - 1; i++) {
            if (s.charAt(i) != s.charAt(i + 1)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Analyzes an array of rows (each row is treated as a single element).
     * Returns "YES" if the pattern described in the original program holds,
     * otherwise "NO".
     */
    private static String analyzeRows(String[] rows) {
        int cr = 0, cg = 0, cb = 0;
        boolean seenR = false, seenG = false, seenB = false;
        int flag = 0;

        for (int i = 0; i < rows.length; i++) {
            char ch = rows[i].charAt(0);

            // count occurrences of each colour
            if (ch == 'R') cr++;
            else if (ch == 'G') cg++;
            else if (ch == 'B') cb++;

            // transition handling
            if (i > 0) {
                char prev = rows[i - 1].charAt(0);
                if (prev == ch) continue;

                // if the previous colour has already been marked as "seen"
                // after a transition, the pattern is invalid
                if ((prev == 'R' && seenR) ||
                    (prev == 'G' && seenG) ||
                    (prev == 'B' && seenB)) {
                    flag = 1;
                    break;
                }
                // mark the previous colour as seen
                if (prev == 'R' && !seenR) seenR = true;
                if (prev == 'G' && !seenG) seenG = true;
                if (prev == 'B' && !seenB) seenB = true;
            }
        }

        return (flag == 0 && cr == cb && cb == cg) ? "YES" : "NO";
    }

    /**
     * Analyzes the first row as a sequence of characters (used when all
     * rows are uniform but columns may still need checking).
     */
    private static String analyzeColumnPattern(String row) {
        int cr = 0, cg = 0, cb = 0;
        boolean seenR = false, seenG = false, seenB = false;
        int flag = 0;

        for (int i = 0; i < row.length(); i++) {
            char ch = row.charAt(i);

            // count occurrences of each colour
            if (ch == 'R') cr++;
            else if (ch == 'G') cg++;
            else if (ch == 'B') cb++;

            // transition handling
            if (i > 0) {
                char prev = row.charAt(i - 1);
                if (prev == ch) continue;

                if ((prev == 'R' && seenR) ||
                    (prev == 'G' && seenG) ||
                    (prev == 'B' && seenB)) {
                    flag = 1;
                    break;
                }
                if (prev == 'R' && !seenR) seenR = true;
                if (prev == 'G' && !seenG) seenG = true;
                if (prev == 'B' && !seenB) seenB = true;
            }
        }

        return (flag == 0 && cr == cb && cb == cg) ? "YES" : "NO";
    }

    /* -------------------------------------------------------------
     *  Main program
     * ------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();          // number of rows
        int m = fs.nextInt();          // number of columns
        fs.nextLine();                 // consume the rest of the line

        String[] rows = new String[n];
        for (int i = 0; i < n; i++) {
            rows[i] = fs.nextLine();
        }

        // f == 1  → at least one row is non‑uniform
        // f == 0  → all rows are uniform
        boolean allRowsUniform = Arrays.stream(rows).allMatch(Main::isUniform);
        int f = allRowsUniform ? 0 : 1;
        int g = 0;                       // g == 1 → at least one column is non‑uniform

        // If any row is non‑uniform, check column uniformity
        if (!allRowsUniform) {
            for (int col = 0; col < m; col++) {
                StringBuilder colBuilder = new StringBuilder();
                for (int row = 0; row < n; row++) {
                    colBuilder.append(rows[row].charAt(col));
                }
                if (!isUniform(colBuilder.toString())) {
                    g = 1;
                    break;
                }
            }
        }

        // Output according to the original decision matrix
        if (f == 1 && g == 1) {
            System.out.println("NO");
        } else if (f == 0) {
            System.out.println(analyzeRows(rows));
        } else if (g == 0) {
            System.out.println(analyzeColumnPattern(rows[0]));
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for CF Edu 26B.
 *
 * <p>It checks whether the given grid can be split either
 * horizontally or vertically into three equal blocks,
 * each block being uniformly coloured with one of {@code 'R'}, {@code 'G'}, {@code 'B'}.
 * The three colours must appear exactly once across the blocks.
 */
public class Main {

    /** The three required colours. */
    private static final char RED = 'R';
    private static final char GREEN = 'G';
    private static final char BLUE = 'B';
    /** Set containing the three colours. */
    private static final Set<Character> ALL_COLOURS = Set.of(RED, GREEN, BLUE);

    public static void main(String[] args) throws IOException {
        try (InputReader reader = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            out.println(eval(grid) ? "YES" : "NO");
        }
    }

    /** Main evaluation routine – returns true if the condition is satisfied. */
    private static boolean eval(char[][] grid) {
        // Horizontal partition check
        if (grid.length % 3 == 0) {
            if (checkRowPartition(grid, grid.length / 3)) {
                return true;
            }
        }

        // Vertical partition check
        if (grid[0].length % 3 == 0) {
            if (checkColumnPartition(grid, grid[0].length / 3)) {
                return true;
            }
        }

        return false;
    }

    /** Verifies a horizontal split into three equal rows. */
    private static boolean checkRowPartition(char[][] grid, int blockHeight) {
        int n = grid.length;

        for (int block = 0; block < 3; block++) {
            int start = block * blockHeight;
            int end = start + blockHeight;

            Set<Character> colours = collectColours(grid, start, end, 0, grid[0].length);
            if (colours.size() != 1) {                     // block not uniform
                return false;
            }
        }

        // All three blocks together contain exactly the three required colours
        Set<Character> seen = new HashSet<>();
        for (int block = 0; block < 3; block++) {
            int start = block * blockHeight;
            int end = start + blockHeight;
            seen.addAll(collectColours(grid, start, end, 0, grid[0].length));
        }
        return seen.equals(ALL_COLOURS);
    }

    /** Verifies a vertical split into three equal columns. */
    private static boolean checkColumnPartition(char[][] grid, int blockWidth) {
        int m = grid[0].length;

        for (int block = 0; block < 3; block++) {
            int start = block * blockWidth;
            int end = start + blockWidth;

            Set<Character> colours = collectColours(grid, 0, grid.length, start, end);
            if (colours.size() != 1) {                     // block not uniform
                return false;
            }
        }

        // All three blocks together contain exactly the three required colours
        Set<Character> seen = new HashSet<>();
        for (int block = 0; block < 3; block++) {
            int start = block * blockWidth;
            int end = start + blockWidth;
            seen.addAll(collectColours(grid, 0, grid.length, start, end));
        }
        return seen.equals(ALL_COLOURS);
    }

    /**
     * Collects distinct characters from a rectangular sub‑grid.
     *
     * @param grid       the full grid
     * @param rowStart   inclusive start row index
     * @param rowEndExcl exclusive end row index
     * @param colStart   inclusive start column index
     * @param colEndExcl exclusive end column index
     * @return a set of characters found in that region
     */
    private static Set<Character> collectColours(char[][] grid,
                                                  int rowStart,
                                                  int rowEndExcl,
                                                  int colStart,
                                                  int colEndExcl) {
        Set<Character> set = new HashSet<>();
        for (int i = rowStart; i < rowEndExcl; i++) {
            for (int j = colStart; j < colEndExcl; j++) {
                set.add(grid[i][j]);
            }
        }
        return set;
    }

    /**
     * Simple buffered‑reader wrapper that implements {@link AutoCloseable}.
     */
    private static class InputReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.Map;

/**
 * Determines whether a rectangular flag can be divided into three equal‑width
 * horizontal stripes or three equal‑height vertical stripes, each stripe being a
 * single colour and each of the three colours (R, G, B) occupying exactly the
 * same number of cells.
 */
public class B {

    // -----------------------------------------------------------------------
    // Constants for the three colours used in the flag
    // -----------------------------------------------------------------------
    private static final char RED   = 'R';
    private static final char GREEN = 'G';
    private static final char BLUE  = 'B';

    // -----------------------------------------------------------------------
    // Entry point
    // -----------------------------------------------------------------------
    public static void main(String[] args) throws IOException {
        // Try‑with‑resources automatically closes the reader
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // 1. Read dimensions
            String[] dimTokens = readTokens(br, 2);
            int rows = Integer.parseInt(dimTokens[0]);
            int cols = Integer.parseInt(dimTokens[1]);

            // 2. If neither dimension is a multiple of 3 the flag cannot be split into
            //    three equal stripes → answer is immediately "NO".
            if (rows % 3 != 0 && cols % 3 != 0) {
                skipRemainingLines(br, rows);
                System.out.println("NO");
                return;
            }

            // 3. Read the flag matrix
            char[][] flag = readFlagMatrix(br, rows);

            // 4. Test horizontal or vertical stripes (whichever dimension allows it)
            boolean valid = false;
            if (rows % 3 == 0) {
                valid = isHorizontal(flag, rows, cols);
            }
            if (!valid && cols % 3 == 0) {
                valid = isVertical(flag, rows, cols);
            }

            // 5. Output the answer
            System.out.println(valid ? "YES" : "NO");
        }
    }

    // -----------------------------------------------------------------------
    // Utility helpers
    // -----------------------------------------------------------------------
    /** Reads exactly `count` whitespace‑separated tokens from the reader. */
    private static String[] readTokens(BufferedReader br, int count) throws IOException {
        String line = br.readLine();
        String[] parts = line.split("\\s+");
        if (parts.length < count) {
            throw new IOException("Not enough numbers on the first line");
        }
        return parts;
    }

    /** Reads the flag matrix consisting of `rows` lines. */
    private static char[][] readFlagMatrix(BufferedReader br, int rows) throws IOException {
        char[][] matrix = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = br.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input while reading flag");
            }
            matrix[i] = line.toCharArray();
        }
        return matrix;
    }

    /** Skips `rows` lines of input that are no longer needed. */
    private static void skipRemainingLines(BufferedReader br, int rows) throws IOException {
        for (int i = 0; i < rows; i++) {
            br.readLine();
        }
    }

    // -----------------------------------------------------------------------
    // Core validation logic
    // -----------------------------------------------------------------------
    /** Checks for three horizontal stripes of equal height. */
    private static boolean isHorizontal(char[][] flag, int rows, int cols) {
        int stripeHeight = rows / 3;
        Map<Character, Integer> colourCount = initialiseColourCounter();

        for (int s = 0; s < 3; s++) {
            int startRow = s * stripeHeight;
            char stripeColour = flag[startRow][0]; // expected colour of this stripe

            // Verify that the whole stripe is uniformly coloured
            for (int r = startRow; r < startRow + stripeHeight; r++) {
                for (int c = 0; c < cols; c++) {
                    if (flag[r][c] != stripeColour) {
                        return false;
                    }
                }
            }

            // Accumulate the size of this stripe
            colourCount.put(stripeColour, colourCount.get(stripeColour) + stripeHeight * cols);
        }

        return equalCounts(colourCount);
    }

    /** Checks for three vertical stripes of equal width. */
    private static boolean isVertical(char[][] flag, int rows, int cols) {
        int stripeWidth = cols / 3;
        Map<Character, Integer> colourCount = initialiseColourCounter();

        for (int s = 0; s < 3; s++) {
            int startCol = s * stripeWidth;
            char stripeColour = flag[0][startCol]; // expected colour of this stripe

            // Verify that the whole stripe is uniformly coloured
            for (int c = startCol; c < startCol + stripeWidth; c++) {
                for (int r = 0; r < rows; r++) {
                    if (flag[r][c] != stripeColour) {
                        return false;
                    }
                }
            }

            // Accumulate the size of this stripe
            colourCount.put(stripeColour, colourCount.get(stripeColour) + rows * stripeWidth);
        }

        return equalCounts(colourCount);
    }

    /** Builds a counter that initially holds zero for each of the three colours. */
    private static Map<Character, Integer> initialiseColourCounter() {
        Map<Character, Integer> counter = new HashMap<>();
        counter.put(RED,   0);
        counter.put(GREEN, 0);
        counter.put(BLUE,  0);
        return counter;
    }

    /** Returns true iff each of R, G and B appears the same number of times. */
    private static boolean equalCounts(Map<Character, Integer> counts) {
        Integer r = counts.get(RED);
        Integer g = counts.get(GREEN);
        Integer b = counts.get(BLUE);
        return r != null && g != null && b != null && r.equals(g) && g.equals(b);
    }
}

import java.util.Scanner;

/**
 * Utility class that checks whether a given flag pattern complies with the
 * “stripe” definition used in the original problem statement.
 *
 * <p>The flag is considered valid when it consists of three equally‑sized
 * vertical or horizontal stripes whose colours are all different.</p>
 */
public class FlagValidator {

    // -------------------------------------------------------------------------
    // Constants
    // -------------------------------------------------------------------------

    /** The minimum number of colours required to form a valid stripe pattern. */
    private static final int REQUIRED_STRIPES = 3;

    // -------------------------------------------------------------------------
    // Public API
    // -------------------------------------------------------------------------

    /**
     * Entry point of the program.
     *
     * <p>Reads a rectangular grid of characters (the flag) from {@code STDIN}
     * and prints {@code "YES"} if the flag satisfies the stripe condition,
     * otherwise {@code "NO"}.</p>
     *
     * @param args command‑line arguments (unused)
     */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();   // n
            int cols = scanner.nextInt();   // m

            char[][] flag = readFlag(scanner, rows, cols);

            boolean isValid = checkPattern(flag);
            System.out.println(isValid ? "YES" : "NO");
        }
    }

    // -------------------------------------------------------------------------
    // Private helpers
    // -------------------------------------------------------------------------

    /**
     * Reads {@code rows} strings of length {@code cols} from the supplied scanner
     * and stores them as a 2‑dimensional {@code char} array.
     *
     * @param scanner scanner providing the input
     * @param rows   number of rows in the flag
     * @param cols   number of columns in the flag
     * @return       a {@code char[][]} representing the flag
     */
    private static char[][] readFlag(Scanner scanner, int rows, int cols) {
        char[][] flag = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                flag[i][j] = line.charAt(j);
            }
        }
        return flag;
    }

    /**
     * Determines whether the provided flag pattern consists of three
     * equally‑sized stripes in either orientation that have distinct colours.
     *
     * @param flag the flag to validate
     * @return {@code true} if the pattern is a valid flag, {@code false} otherwise
     */
    private static boolean checkPattern(char[][] flag) {
        boolean vertical = checkHorizontalStripes(flag);
        boolean horizontal = checkVerticalStripes(flag);
        return vertical || horizontal;
    }

    /**
     * Checks the flag for three vertical stripes (i.e. the rows act as boundaries)
     * each having a uniform colour and all three colours being different.
     *
     * @param flag the flag grid
     * @return {@code true} if a valid vertical stripe configuration exists
     */
    private static boolean checkHorizontalStripes(char[][] flag) {
        if (flag[0].length % REQUIRED_STRIPES != 0) {
            return false; // width not divisible by 3 → cannot form three equal stripes
        }
        int stripeWidth = flag[0].length / REQUIRED_STRIPES;
        return areStripesDifferent(
                flag[0][0],                     // colour of first stripe
                flag[0][stripeWidth],           // colour of second stripe
                flag[0][2 * stripeWidth],       // colour of third stripe
                stripeWidth,
                flag
        );
    }

    /**
     * Checks the flag for three horizontal stripes (i.e. the columns act as boundaries)
     * each having a uniform colour and all three colours being different.
     *
     * @param flag the flag grid
     * @return {@code true} if a valid horizontal stripe configuration exists
     */
    private static boolean checkVerticalStripes(char[][] flag) {
        int rows = flag.length;
        if (rows % REQUIRED_STRIPES != 0) {
            return false; // height not divisible by 3 → cannot form three equal stripes
        }
        int stripeHeight = rows / REQUIRED_STRIPES;
        return areStripesDifferent(
                flag[0][0],
                flag[stripeHeight][0],
                flag[2 * stripeHeight][0],
                flag,
                stripeHeight
        );
    }

    /**
     * Verifies that three consecutive stripes of the given width/height are
     * uniformly coloured and that the three colours are pairwise different.
     *
     * @param firstColour   colour of the first stripe (e.g. top‑left pixel)
     * @param secondColour  colour of the second stripe
     * @param thirdColour   colour of the third stripe
     * @param size          width or height of a single stripe
     * @param flag          the flag grid
     * @return {@code true} if the stripes are of equal size and all colours differ
     */
    private static boolean areStripesDifferent(char firstColour, char secondColour,
                                               char thirdColour, int size, char[][] flag) {
        return areAllDifferent(firstColour, secondColour, thirdColour)
                && isUniformStripe(flag, 0, 0, size, flag[0].length)   // vertical slice
                && isUniformStripe(flag, size, 0, size, flag[0].length)
                && isUniformStripe(flag, 2 * size, 0, size, flag[0].length);
    }

    /**
     * Verifies that a sub‑rectangle of a given width consists of a single,
     * repeating character.
     *
     * @param flag       the full flag grid
     * @param startRow   row index where the stripe starts (inclusive)
     * @param startCol   column index where the stripe starts (inclusive)
     * @param stripeSize size of the stripe (width or height, depending on context)
     * @param length     total length of the dimension being scanned (number of columns or rows)
     * @return {@code true} if the stripe is uniformly coloured
     */
    private static boolean isUniformStripe(char[][] flag, int startRow, int startCol,
                                           int stripeSize, int length) {
        char expected = flag[startRow][startCol];
        for (int i = startRow; i < startRow + stripeSize; i++) {
            for (int j = startCol; j < startCol + length; j++) {
                if (flag[i][j] != expected) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Determines whether three characters are pairwise different.
     *
     * @param a first character
     * @param b second character
     * @param c third character
     * @return {@code true} if {@code a}, {@code b} and {@code c} are all distinct
     */
    private static boolean areAllDifferent(char a, char b, char c) {
        return a != b && b != c && c != a;
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Refactored solution for {@code TaskB}.
 *
 * <p>
 * The original program read a matrix, tried to detect whether it could be split
 * into three equal horizontal or vertical blocks that each contain a single
 * distinct character, and printed {@code YES} if such a pattern existed.
 * </p>
 *
 * <p>
 * This version improves maintainability by:
 * <ul>
 *   <li>Extracting responsibilities into small, well‑named methods.</li>
 *   <li>Using meaningful variable names and avoiding deep nesting.</li>
 *   <li>Encapsulating I/O with try‑with‑resources.</li>
 *   <li>Adding short, focused Javadoc comments.</li>
 * </ul>
 * </p>
 */
public class Main {

    public static void main(String[] args) {
        /**
         * Entry point. Reads input, runs the algorithm and writes the result.
         * All resources are closed automatically via {@link AutoCloseable}.
         */
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter printer = new PrintWriter(System.out)) {
            solve(scanner, printer);
            printer.flush();           // ensure output is sent before JVM exit
        }
    }

    /**
     * Orchestrates the solution: reads data, tests possible patterns and prints
     * {@code YES} or {@code NO}.
     *
     * @param in  scanner that provides the input tokens
     * @param out printer that receives the answer
     */
    private static void solve(Scanner in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] grid = readGrid(in, rows, cols);

        if (rows % 3 == 0 && isRowPattern(grid)) {
            out.println("YES");
            return;
        }
        if (cols % 3 == 0 && isColumnPattern(grid)) {
            out.println("YES");
            return;
        }
        out.println("NO");
    }

    /**
     * Reads {@code rows × cols} characters from {@code scanner}, expecting each
     * row to be supplied as a single string.
     *
     * @return a 2‑dimensional {@code char}`[rows][cols]` matrix
     */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /**
     * Determines whether the matrix can be divided into three equal horizontal
     * blocks that each contain a single distinct character.
     *
     * @return {@code true} if such a pattern exists, {@code false} otherwise
     */
    private static boolean isRowPattern(char[][] grid) {
        int blockSize = grid.length / 3;          // number of rows per block
        boolean ok = true;

        for (int r = 0; r < grid.length; r++) {
            int blockIdx = r / blockSize;
            int blockBase = blockIdx * blockSize;
            char blockReference = grid[blockBase][0];

            // each cell in the current block must equal its block's reference char
            if (grid[r][0] != blockReference) {
                ok = false;
                break;
            }

            // no other block may share the same reference character
            for (int otherBase = 0; otherBase < grid.length; otherBase += blockSize) {
                if (otherBase == blockBase) continue;
                if (grid[otherBase][0] == blockReference) {
                    ok = false;
                    break;
                }
            }
            if (!ok) break;

            // validate that the whole block consists of the reference character
            for (int i = blockBase; i < blockBase + blockSize; i++) {
                for (int c = 0; c < grid[i].length; c++) {
                    if (grid[i][c] != blockReference) {
                        ok = false;
                        break;
                    }
                }
                if (!ok) break;
            }
        }
        return ok;
    }

    /**
     * Determines whether the matrix can be divided into three equal vertical
     * blocks that each contain a single distinct character.
     *
     * @return {@code true} if such a pattern exists, {@code false} otherwise
     */
    private static boolean isColumnPattern(char[][] grid) {
        int blockSize = grid[0].length / 3;       // number of columns per block
        boolean ok = true;

        for (int c = 0; c < grid[0].length; c++) {
            int blockIdx = c / blockSize;
            int blockBase = blockIdx * blockSize;
            char blockReference = grid[0][blockBase];

            if (grid[0][c] != blockReference) {
                ok = false;
                break;
            }

            for (int otherBase = 0; otherBase < grid[0].length; otherBase += blockSize) {
                if (otherBase == blockBase) continue;
                if (grid[0][otherBase] == blockReference) {
                    ok = false;
                    break;
                }
            }
            if (!ok) break;

            // verify the entire block is filled with the reference character
            for (int j = blockBase; j < blockBase + blockSize; j++) {
                for (int r = 0; r < grid.length; r++) {
                    if (grid[r][j] != blockReference) {
                        ok = false;
                        break;
                    }
                }
                if (!ok) break;
            }
        }
        return ok;
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    private static final char[] COLORS = {'R', 'G', 'B'};

    /** Entry point – creates the output writer and runs the solution. */
    public static void main(String[] args) {
        try (PrintWriter out = createPrintWriter(args)) {
            new Solution().run(out);
        } catch (IOException e) {
            System.err.println("I/O error: " + e.getMessage());
        }
    }

    /** Returns a PrintWriter that writes either to a file (derived from the input name) or to stdout. */
    private static PrintWriter createPrintWriter(String[] args) throws IOException {
        if (args.length > 0) {
            String inputFile = args[0];
            String outputFile = inputFile.replaceFirst("\\.in$", ".out");
            return new PrintWriter(new BufferedWriter(new FileWriter(outputFile)));
        }
        return new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
    }

    /** Executes the core logic using the supplied PrintWriter for output. */
    private void run(PrintWriter out) throws IOException {
        try (FastScanner fs = new FastScanner()) {
            int n = fs.nextInt();
            int m = fs.nextInt();

            char[][] grid = readGrid(fs, n, m);

            if (isHorizontalValid(grid, n, m) || isVerticalValid(grid, n, m)) {
                out.println("YES");
            } else {
                out.println("No");
            }
        }
    }

    /** Reads the grid from the scanner. */
    private char[][] readGrid(FastScanner fs, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = fs.nextLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /** Checks whether a horizontal partition into three equal strips works. */
    private boolean isHorizontalValid(char[][] grid, int n, int m) {
        if (n % 3 != 0) {
            return false;
        }
        int sliceHeight = n / 3;
        char[] sliceColors = new char[3];

        for (int s = 0; s < 3; s++) {
            int startRow = s * sliceHeight;
            char expected = grid[startRow][0];
            if (!allRowsSame(grid, startRow, sliceHeight, m, expected)) {
                return false;
            }
            // all three slices must use distinct colours
            for (int t = 0; t < 3; t++) {
                if (t != s && sliceColors[t] == expected) {
                    return false;
                }
            }
            sliceColors[s] = expected;
        }
        return true;
    }

    /** Checks whether a vertical partition into three equal strips works. */
    private boolean isVerticalValid(char[][] grid, int n, int m) {
        if (m % 3 != 0) {
            return false;
        }
        int sliceWidth = m / 3;
        char[] sliceColors = new char[3];

        for (int s = 0; s < 3; s++) {
            int startCol = s * sliceWidth;
            char expected = grid[0][startCol];
            if (!allColumnsSame(grid, n, startCol, sliceWidth, expected)) {
                return false;
            }
            // all three slices must use distinct colours
            for (int t = 0; t < 3; t++) {
                if (t != s && sliceColors[t] == expected) {
                    return false;
                }
            }
            sliceColors[s] = expected;
        }
        return true;
    }

    /** Verifies that every cell in the given block of rows contains {@code expected}. */
    private boolean allRowsSame(char[][] grid, int startRow, int height, int width, char expected) {
        for (int i = startRow; i < startRow + height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[i][j] != expected) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Verifies that every cell in the given block of columns contains {@code expected}. */
    private boolean allColumnsSame(char[][] grid, int rows, int startCol, int width, char expected) {
        for (int i = 0; i < rows; i++) {
            for (int j = startCol; j < startCol + width; j++) {
                if (grid[i][j] != expected) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Scanner that works with both a file (provided as the first argument) and standard input. */
    private static class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        /** Default constructor – reads from standard input. */
        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Constructor that reads from a named file (may throw FileNotFoundException). */
        FastScanner(String path) throws FileNotFoundException {
            this.br = new BufferedReader(new FileReader(path));
        }

        /** Returns the next token, blocking until one is available. */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        /** Returns the next raw line (useful for reading whole rows of the grid). */
        String nextLine() throws IOException {
            return br.readLine();
        }

        /** Ensures the underlying reader is closed. */
        @Override
        public void close() throws IOException {
            br.close();
        }
    }
}

import java.io.*;
import java.util.Scanner;
import java.util.StringTokenizer;

/**
 * Main class for competitive‑programming entry point.
 * Reads input, runs the solution and writes the answer.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Solver().solve(scanner, out);
        out.flush();               // ensure all output is written
    }

    /**
     * Encapsulates the algorithm for the problem.
     * The public method reads the test case from the supplied scanner
     * and writes the result (YES/NO) to the supplied PrintWriter.
     */
    static class Solver {

        /** Entry point for one test case. */
        public void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();          // number of rows
            int m = in.nextInt();          // number of columns
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            boolean firstRowUniform = isFirstRowUniform(grid, m);

            if (firstRowUniform) {
                if (!handleVerticalStripeCase(grid, n, m, out)) {
                    return;
                }
            } else {
                if (!handleHorizontalStripeCase(grid, n, m, out)) {
                    return;
                }
            }

            out.print("YES");
        }

        /** Checks whether all characters in the first row are identical. */
        private boolean isFirstRowUniform(char[][] grid, int m) {
            char first = grid[0][0];
            for (int col = 1; col < m; col++) {
                if (grid[0][col] != first) {
                    return false;
                }
            }
            return true;
        }

        /** Handles the case where the first row is uniform (vertical stripes). */
        private boolean handleVerticalStripeCase(char[][] grid, int n, int m, PrintWriter out) {
            if (n % 3 != 0) {
                out.print("NO");
                return false;
            }

            String reference = buildColumnString(grid, 0);

            if (!Validator.isBalancedTriplet(reference)) {
                out.print("NO");
                return false;
            }

            for (int col = 0; col < m; col++) {
                if (!reference.equals(buildColumnString(grid, col))) {
                    out.print("NO");
                    return false;
                }
            }
            return true;
        }

        /** Handles the case where the first row is NOT uniform (horizontal stripes). */
        private boolean handleHorizontalStripeCase(char[][] grid, int n, int m, PrintWriter out) {
            if (m % 3 != 0) {
                out.print("NO");
                return false;
            }

            String reference = buildRowString(grid[0]);

            if (!Validator.isBalancedTriplet(reference)) {
                out.print("NO");
                return false;
            }

            for (int row = 0; row < n; row++) {
                if (!reference.equals(buildRowString(grid[row]))) {
                    out.print("NO");
                    return false;
                }
            }
            return true;
        }

        /** Concatenates the characters of a given column. */
        private String buildColumnString(char[][] grid, int colIdx) {
            StringBuilder sb = new StringBuilder(n);
            for (char[] row : grid) {
                sb.append(row[colIdx]);
            }
            return sb.toString();
        }

        /** Returns the string representation of a row (already a char array). */
        private String buildRowString(char[] row) {
            return new String(row);
        }
    }

    /**
     * Utility class that validates whether a string consists of exactly three
     * consecutive blocks of equal length, each block formed by a single
     * distinct character (R, G or B).
     */
    static final class Validator {
        /** @return true if the string matches the required pattern. */
        static boolean isBalancedTriplet(String s) {
            int blockSize = s.length() / 3;
            return isBlock(s, 'R', blockSize) &&
                   isBlock(s, 'G', blockSize) &&
                   isBlock(s, 'B', blockSize);
        }

        /** Checks that the expected character occupies exactly one contiguous block
         *  of the given size. */
        private static boolean isBlock(String s, char expected, int blockSize) {
            int first = s.indexOf(expected);
            int last  = s.lastIndexOf(expected);
            return last - first + 1 == blockSize;
        }
    }

    /**
     * Simple fast scanner used for competitive programming.
     * It hides the boilerplate of handling large input streams.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in), 1 << 20);
        }

        /** Returns the next token from the input. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Reads the next integer from the input. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Reads a grid of characters and checks whether all rows or all columns consist
 * of identical strings. If one of those conditions holds, the associated string
 * is validated against a “balanced pattern” rule and the result (YES/NO) is printed.
 *
 * <p>The implementation is deliberately split into small, single‑purpose methods
 * to improve readability, testability, and maintainability.</p>
 */
public class FlagOfBerland {

    /** Shared scanner instance – everything reads from {@code System.in}. */
    private static final Scanner SCANNER = new Scanner(System.in);

    public static void main(String[] args) {
        int rows = readInt();
        int cols = readInt();

        // 1️⃣  Read the vertical strings (the rows of the matrix)
        List<String> verticalLines = readVerticalLines(rows);

        // 2️⃣  Build the matrix and the corresponding horizontal strings
        char[][] matrix = readMatrix(rows, cols);
        List<String> horizontalLines = buildHorizontalLines(matrix, rows, cols);

        // 3️⃣  Determine whether all rows or all columns are identical
        boolean allRowsIdentical = areAllEqual(verticalLines);
        boolean allColsIdentical = areAllEqual(horizontalLines);

        // 4️⃣  Output decision
        if (!allRowsIdentical && !allColsIdentical) {
            System.out.println("NO");
            return;
        }

        // Preference is given to rows when both are identical – mirrors original logic
        String patternToCheck = allRowsIdentical ? verticalLines.get(0) : horizontalLines.get(0);
        evaluatePattern(patternToCheck);
    }

    /* --------------------------------------------------------------
     *  Input helpers
     * -------------------------------------------------------------- */

    private static int readInt() {
        return Integer.parseInt(SCANNER.next());
    }

    private static List<String> readVerticalLines(int n) {
        List<String> lines = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            lines.add(SCANNER.next());
        }
        return lines;
    }

    private static char[][] readMatrix(int rows, int cols) {
        char[][] matrix = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String row = SCANNER.next();
            matrix[r] = row.toCharArray();
        }
        return matrix;
    }

    private static List<String> buildHorizontalLines(char[][] matrix, int rows, int cols) {
        List<String> horizontals = new ArrayList<>(cols);
        for (int c = 0; c < cols; c++) {
            StringBuilder sb = new StringBuilder(rows);
            for (int r = 0; r < rows; r++) {
                sb.append(matrix[r][c]);
            }
            horizontals.add(sb.toString());
        }
        return horizontals;
    }

    /* --------------------------------------------------------------
     *  Utility helpers
     * -------------------------------------------------------------- */

    /** Returns true iff every element of the list is equal to the first one. */
    private static boolean areAllEqual(List<String> list) {
        if (list.isEmpty()) {
            return true;
        }
        String first = list.get(0);
        for (int i = 1; i < list.size(); i++) {
            if (!first.equals(list.get(i))) {
                return false;
            }
        }
        return true;
    }

    /** Analyzes a pattern and prints YES/NO according to the specification. */
    private static void evaluatePattern(String pattern) {
        PatternInfo info = analyzePattern(pattern);
        if (!info.isBalanced()) {
            System.out.println("NO");
            return;
        }
        int gaps = countGaps(pattern, info);
        System.out.println(gaps == 0 ? "YES" : "NO");
    }

    /** Splits the pattern into three colour groups and checks size equality. */
    private static PatternInfo analyzePattern(String pattern) {
        List<Integer> red = new ArrayList<>();
        List<Integer> green = new ArrayList<>();
        List<Integer> blue = new ArrayList<>();

        for (int i = 0; i < pattern.length(); i++) {
            switch (pattern.charAt(i)) {
                case 'R' -> red.add(i);
                case 'G' -> green.add(i);
                case 'B' -> blue.add(i);
                default -> throw new IllegalArgumentException("Invalid character: " + pattern.charAt(i));
            }
        }
        return new PatternInfo(red, green, blue);
    }

    /** Counts how many colour groups contain a gap larger than one position. */
    private static int countGaps(String pattern, PatternInfo info) {
        int gaps = 0;
        gaps += countGaps(info.red);
        gaps += countGaps(info.green);
        gaps += countGaps(info.blue);
        return gaps;
    }

    /** Helper that counts gaps inside a sorted list of indices. */
    private static int countGaps(List<Integer> indices) {
        if (indices.size() < 2) {
            return 0;
        }
        int gaps = 0;
        for (int i = 1; i < indices.size(); i++) {
            if (indices.get(i) - indices.get(i - 1) > 1) {
                gaps++;
            }
        }
        return gaps;
    }

    /** Simple DTO that holds the three index lists derived from a pattern. */
    private static final class PatternInfo {
        final List<Integer> red;
        final List<Integer> green;
        final List<Integer> blue;

        PatternInfo(List<Integer> red, List<Integer> green, List<Integer> blue) {
            this.red = red;
            this.green = green;
            this.blue = blue;
        }

        /** All three colour groups must have the same size. */
        boolean isBalanced() {
            return red.size() == green.size()
                    && green.size() == blue.size()
                    && blue.size() == red.size();
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Reads a rectangular grid of characters and decides whether it can represent
 * a valid flag of Berland – i.e. three equal‑sized stripes of distinct colors
 * either horizontally or vertically aligned.
 *
 * <p>All I/O is delegated to the injected {@link InputReader} and {@link PrintWriter}
 * instances, making the class easy to test and to reuse.</p>
 */
public final class FlagOfBerland implements Closeable {

    /** Fast tokeniser that reads from the supplied {@link InputStream}. */
    private final InputReader reader;

    /** Destination for the result output. */
    private final PrintWriter writer;

    /**
     * Constructs a new solver that will read from {@code input} and write to {@code output}.
     *
     * @param input  the source of data (normally {@code System.in})
     * @param output the destination for the answer (normally {@code System.out})
     */
    public FlagOfBerland(InputStream input, PrintWriter output) {
        this.reader = new InputReader(input);
        this.writer = output;
    }

    /** Entry point used by {@code main}. */
    public void solve() {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        // ----- read the whole grid ------------------------------------------------
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = reader.next().toCharArray();
        }

        // ----- check horizontal and vertical possibilities -----------------------
        boolean valid = isHorizontalFlag(grid) || isVerticalFlag(grid);
        writer.println(valid ? "YES" : "NO");
    }

    /** Returns {@code true} iff the flag consists of three equal‑height horizontal stripes. */
    private boolean isHorizontalFlag(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        if (rows % 3 != 0) {
            return false;                     // stripe height must be integral
        }
        final int stripeHeight = rows / 3;

        // Colours of the three stripes – taken from the first row of each stripe
        final char firstColor  = grid[0][0];
        final char secondColor = grid[stripeHeight][0];
        final char thirdColor  = grid[2 * stripeHeight][0];

        // All three colours must be different
        if (firstColor == secondColor || secondColor == thirdColor || thirdColor == firstColor) {
            return false;
        }

        // Verify uniform colour inside each stripe
        for (int r = 0; r < rows; r++) {
            char expected = stripeColorForHorizontalRow(r, stripeHeight,
                    firstColor, secondColor, thirdColor);
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != expected) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Returns the colour that the row {@code r} must have in a horizontal layout. */
    private static char stripeColorForHorizontalRow(
            int r, int stripeHeight,
            char first, char second, char third) {

        int stripeIndex = r / stripeHeight; // 0, 1 or 2
        return switch (stripeIndex) {
            case 0 -> first;
            case 1 -> second;
            case 2 -> third;
            default -> throw new IllegalStateException("Row index out of expected range");
        };
    }

    /** Returns {@code true} iff the flag consists of three equal‑width vertical stripes. */
    private boolean isVerticalFlag(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        if (cols % 3 != 0) {
            return false;                     // stripe width must be integral
        }
        final int stripeWidth = cols / 3;

        // Colours of the three stripes – taken from the first column of each stripe
        final char firstColor  = grid[0][0];
        final char secondColor = grid[0][stripeWidth];
        final char thirdColor  = grid[0][2 * stripeWidth];

        // All three colours must be different
        if (firstColor == secondColor || secondColor == thirdColor || thirdColor == firstColor) {
            return false;
        }

        // Verify uniform colour inside each vertical stripe
        for (int c = 0; c < cols; c++) {
            char expected = stripeColorForVerticalColumn(c, stripeWidth,
                    firstColor, secondColor, thirdColor);
            for (int r = 0; r < rows; r++) {
                if (grid[r][c] != expected) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Returns the colour that the column {@code c} must have in a vertical layout. */
    private static char stripeColorForVerticalColumn(
            int c, int stripeWidth,
            char first, char second, char third) {

        int stripeIndex = c / stripeWidth; // 0, 1 or 2
        return switch (stripeIndex) {
            case 0 -> first;
            case 1 -> second;
            case 2 -> third;
            default -> throw new IllegalStateException("Column index out of expected range");
        };
    }

    @Override
    public void close() throws IOException {
        reader.close();
        writer.close();
    }

    /** Minimal tokeniser used by {@link FlagOfBerland}. */
    private static final class InputReader implements Closeable {
        private final BufferedReader buffer;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            this.buffer = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        /** Returns the next non‑empty token from the input. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(buffer.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Convenience wrapper for reading a single word (the next token). */
        char[] nextCharArray() {
            return next().toCharArray();
        }

        @Override
        public void close() throws IOException {
            buffer.close();
        }
    }

    /** Simple driver that wires everything together. */
    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees that streams are closed properly.
        try (FlagOfBerland solver = new FlagOfBerland(System.in, new PrintWriter(System.out))) {
            solver.solve();
        }
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Entry point of the program.
 *
 * Reads the board dimensions and the board itself, checks whether each of the three
 * colours (R, G, B) occupies a single contiguous rectangle without gaps,
 * and prints "YES" or "NO".
 */
public class Main {

    /** Constant for the characters we are interested in. */
    private static final char[] COLORS = {'R', 'G', 'B'};

    public static void main(String[] args) {
        // Try‑with‑resources guarantees proper closing of the streams.
        try (InputStream in = System.in;
             PrintWriter out = new PrintWriter(System.out, true)) {

            new Solver().run(in, out);
        }
    }
}

/**
 * Handles all I/O and orchestrates the solving process.
 */
class Solver {

    /** Reads input, processes the board, and writes the result. */
    public void run(InputStream input, PrintWriter output) {
        InputReader reader = new InputReader(input);
        int n = reader.nextInt();
        int m = reader.nextInt();

        char[][] board = readBoard(reader, n);

        boolean result = isValidPattern(board, n, m);
        output.println(result ? "YES" : "NO");
    }

    /** Reads the board after the dimensions have been parsed. */
    private static char[][] readBoard(InputReader reader, int n) {
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = reader.next().toCharArray();
        }
        return board;
    }

    /**
     * Determines whether the board contains exactly one rectangle of each of the
     * three colours R, G and B with no empty cells.
     *
     * @return true if the pattern is valid, false otherwise.
     */
    private static boolean isValidPattern(char[][] board, int rows, int cols) {
        for (char colour : COLORS) {
            int[] size = computeSize(board, colour);
            if (size[0] == -1) {
                // Not found – impossible to form a rectangle.
                return false;
            }
        }

        // All three colours must have equal cell count.
        int[][] sizes = {
                computeSize(board, 'R'),
                computeSize(board, 'G'),
                computeSize(board, 'B')
        };
        int countPerColour = sizes[0][0];
        return Arrays.equals(sizes[0], sizes[1])
                && Arrays.equals(sizes[1], sizes[2])
                && countPerColour > 0;
    }

    /**
     * Computes the height and width of the minimal axis‑aligned rectangle that
     * contains all cells of the given colour.
     *
     * @return an int[2] where {@code [0]} = height, {@code [1]} = width.
     *         Returns {@code [-1, -1]} if the colour does not occupy a perfect
     *         rectangle (i.e. the cells are fragmented).
     */
    private static int[] computeSize(char[][] board, char colour) {
        int top = Integer.MAX_VALUE;
        int left = Integer.MAX_VALUE;
        int bottom = Integer.MIN_VALUE;
        int right = Integer.MIN_VALUE;
        int cellCount = 0;

        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                if (board[r][c] == colour) {
                    cellCount++;
                    top = Math.min(top, r);
                    left = Math.min(left, c);
                    bottom = Math.max(bottom, r);
                    right = Math.max(right, c);
                }
            }
        }

        // If the colour was never seen we treat it as invalid.
        if (cellCount == 0) {
            return new int[]{-1, -1};
        }

        int height = bottom - top + 1;
        int width = right - left + 1;

        // Verify that the rectangle contains exactly the same number of cells.
        if (height * width != cellCount) {
            return new int[]{-1, -1};
        }

        return new int[]{height, width};
    }

    /**
     * Simple wrapper around {@link BufferedReader} and {@link StringTokenizer}
     * that provides convenient parsing methods.
     */
    static class InputReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        /** Returns the next token, fetching a new line when needed. */
        private String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrapper for {@link #next()} that parses an {@code int}. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Closes the underlying reader. */
        @Override
        public void close() {
            try {
                reader.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

