/**
 * Simple wrapper around a {@link BufferedReader} that supplies tokenized input.
 * The class implements {@link Closeable} so it can be used in a try‑with‑resources block.
 */
final class ScannerProvider implements Closeable {

    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    /**
     * Constructs a scanner that reads from the given {@link InputStream}.
     *
     * @param source the input stream to read from
     */
    ScannerProvider(InputStream source) {
        this.reader = new BufferedReader(new InputStreamReader(source));
    }

    /**
     * Returns the next token available in the input, or {@code null} if the stream is exhausted.
     */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    return null; // EOF
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /**
     * Parses the next token as an {@link Integer}.
     *
     * @return the parsed integer
     */
    int nextInt() {
        return Integer.parseInt(next());
    }

    @Override
    public void close() throws IOException {
        reader.close();
    }
}

/**
 * Validation logic that determines whether a character matrix satisfies the problem's
 * condition: it can be divided into three equal‑width strips, each strip filled with a
 * distinct character, and every cell inside a strip contains that same character.
 * The check is performed both on the original matrix and on its transpose.
 */
final class GridValidator {

    /** Checks the pattern on the supplied grid (vertical strips). */
    boolean isPattern(char[][] grid) {
        if (!isRowCountDivisibleByThree(grid.length)) {
            return false;
        }
        return hasDistinctStripStartChars(grid) && isEachStripUniform(grid);
    }

    /** Checks the same pattern on the transposed grid (horizontal strips). */
    boolean isPatternOnTranspose(char[][] grid) {
        char[][] transposed = transpose(grid);
        try {
            return isPattern(transposed);
        } finally {
            // No explicit cleanup required for plain char[][], but keep the promise.
        }
    }

    /** @return true if the number of rows is a multiple of three */
    private static boolean isRowCountDivisibleByThree(int rows) {
        return rows % 3 == 0;
    }

    /** @return true if the first column character of each third segment are distinct */
    private boolean hasDistinctStripStartChars(char[][] grid) {
        int stripSize = grid.length / 3;
        int[] segmentStarts = {0, stripSize, 2 * stripSize};

        Set<Integer> seenCodes = new HashSet<>();
        for (int start : segmentStarts) {
            char c = grid[start][0];
            int code = c; // store as int for proper set semantics
            if (!seenCodes.add(code)) {
                return false; // duplicate across segments
            }
        }
        return true;
    }

    /** @return true if every cell in a segment matches the first cell of that segment */
    private boolean isEachStripUniform(char[][] grid) {
        int stripSize = grid.length / 3;
        for (int segment = 0; segment < 3; segment++) {
            int baseRow = segment * stripSize;
            char expected = grid[baseRow][0];
            for (int r = baseRow; r < baseRow + stripSize; r++) {
                for (int c = 0; c < grid[r].length; c++) {
                    if (grid[r][c] != expected) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /** Returns a new matrix that is the transpose of the given matrix. */
    private static char[][] transpose(char[][] source) {
        int rows = source.length;
        int cols = source[0].length;
        char[][] target = new char[cols][rows];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                target[c][r] = source[r][c];
            }
        }
        return target;
    }
}

/**
 * Orchestrates the whole solving process: reading input, invoking validation,
 * and writing the result.
 */
final class Solver {

    /** Constant kept for compatibility with the original single‑test‑case layout. */
    private static final int TEST_CASE_INDEX = 1;

    /**
     * Main driver method.
     *
     * @param scanner provides tokenized input
     * @param out    prints the answer
     */
    void process(ScannerProvider scanner, PrintWriter out) {
        int n = scanner.nextInt();
        // The original program consumed one extra token after reading n; we replicate that behavior.
        scanner.next(); // discard the next token (often a stray newline or unused value)

        char[][] grid = readMatrix(scanner, n);
        if (new GridValidator().isPattern(grid) ||
                new GridValidator().isPatternOnTranspose(grid)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /** Reads {@code n} tokens, each representing a row of the matrix. */
    private static char[][] readMatrix(ScannerProvider scanner, int n) {
        char[][] matrix = new char[n][];
        for (int i = 0; i < n; i++) {
            String token = scanner.next();
            matrix[i] = token.toCharArray(); // preserve original conversion to char[]
        }
        return matrix;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

/**
 * Reads a grid of characters and checks whether it can be divided into three
 * equal regions (either horizontally or vertically) that each consist of a
 * single uniform colour. The three colours must be exactly Red, Green and
 * Blue (in any order). The program prints "YES" if the condition is satisfied,
 * otherwise it prints "NO".
 */
public class Main {

    /** Sentinel returned when a region is not uniform. */
    private static final char INVALID = '-';

    /** Required set of colours. */
    private static final Set<Character> REQUIRED_COLOURS = Set.of('R', 'G', 'B');

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int[][] dims = readTwoInts(br.readLine());
            int rows = dims[0];
            int cols = dims[1];

            if (rows * cols % 3 != 0) {
                System.out.println("NO");
                return;
            }

            char[][] grid = readGrid(br, rows);

            if (isFirstRowUniform(grid)) {
                processHorizontalSplits(grid, rows, cols);
            } else {
                processVerticalSplits(grid, rows, cols);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /** Reads two integers from a line of input. */
    private static int[] readTwoInts(String line) {
        String[] parts = line.trim().split("\\s+");
        return new int[]{Integer.parseInt(parts[0]), Integer.parseInt(parts[1])};
    }

    /** Reads the grid of characters from the remaining input lines. */
    private static char[][] readGrid(BufferedReader br, int rows) throws IOException {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = br.readLine().trim().toCharArray();
        }
        return grid;
    }

    /** Determines whether every character in the first row is identical. */
    private static boolean isFirstRowUniform(char[][] grid) {
        char first = grid[0][0];
        for (int c = 0; c < grid[0].length; c++) {
            if (grid[0][c] != first) {
                return false;
            }
        }
        return true;
    }

    /** Handles the case where the grid is split horizontally into three equal bands. */
    private static void processHorizontalSplits(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            System.out.println("NO");
            return;
        }

        int segmentHeight = rows / 3;
        char top    = getRegionChar(grid, 0, cols, 0, segmentHeight);
        char middle = getRegionChar(grid, 0, cols, segmentHeight, segmentHeight * 2);
        char bottom = getRegionChar(grid, 0, cols, segmentHeight * 2, segmentHeight * 3);

        validateColours(top, middle, bottom);
    }

    /** Handles the case where the grid is split vertically into three equal bands. */
    private static void processVerticalSplits(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            System.out.println("NO");
            return;
        }

        int segmentWidth = cols / 3;
        char left    = getRegionChar(grid, 0, segmentWidth, 0, rows);
        char middle  = getRegionChar(grid, segmentWidth, segmentWidth * 2, 0, rows);
        char right   = getRegionChar(grid, segmentWidth * 2, segmentWidth * 3, 0, rows);

        validateColours(left, middle, right);
    }

    /**
     * Returns the character that occupies the rectangular region defined by
     * {@code [startX, endX) × [startY, endY)} if it is uniform; otherwise returns
     * {@code INVALID}.
     */
    private static char getRegionChar(char[][] grid, int startX, int endX,
                                      int startY, int endY) {
        char expected = grid[startY][startX];
        for (int x = startX; x < endX; x++) {
            for (int y = startY; y < endY; y++) {
                if (grid[y][x] != expected) {
                    return INVALID;
                }
            }
        }
        return expected;
    }

    /**
     * Checks whether the three supplied colours form exactly the set
     * {@code {R, G, B}}. If they do, prints "YES", otherwise prints "NO".
     */
    private static void validateColours(char... colours) {
        Set<Character> unique = new HashSet<>();
        for (char c : colours) {
            unique.add(c);
        }

        if (unique.size() == 3 && REQUIRED_COLOURS.equals(unique)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }
}

import java.io.*;
import java.util.HashMap;
import java.util.Map;

/**
 * Solution for the SPOJ “ANDCC” problem.
 *
 * <p>
 * The task is to decide whether an {@code n × m} grid that contains only the
 * characters {@code 'R'}, {@code 'G'} and {@code 'B'} can be divided into three
 * equal‑sized parts such that each part contains exactly the same number of
 * each colour. The division can be performed either by rows (three horizontal
 * strips) or by columns (three vertical strips).
 * </p>
 *
 * <p>This implementation focuses on readability, separation of concerns and
 * reuse of code.  All magic numbers are replaced by named constants and the
 * core logic is extracted into small, well‑named methods.</p>
 */
public class SpojAndccSolver {

    /** characters that appear in the grid */
    private static final char RED = 'R';
    private static final char GREEN = 'G';
    private static final char BLUE = 'B';

    /** IO helpers */
    private final FastScanner fs;
    private final PrintWriter out;

    /** Creates a new solver that reads from {@code input} and writes to {@code output}. */
    public SpojAndccSolver(InputStream input, PrintWriter output) {
        this.fs = new FastScanner(input);
        this.out = output;
    }

    /** Entry point for the program. */
    public static void main(String[] args) throws Exception {
        try (PrintWriter out = new PrintWriter(System.out)) {
            new SpojAndccSolver(System.in, out).solve();
        }
    }

    /** Main solving routine – called once. */
    public void solve() {
        int rows = fs.nextInt();
        int cols = fs.nextInt();

        char[][] grid = readGrid(rows);

        boolean canPartitionByRows = rows % 3 == 0;
        boolean canPartitionByCols = cols % 3 == 0;

        boolean possible = canPartitionRows(grid) || canPartitionColumns(grid);

        out.println(possible ? "YES" : "NO");
    }

    /** Reads {@code rows} strings from the scanner, each of length {@code cols}. */
    private char[][] readGrid(int rows) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = fs.next();          // length is exactly {@code cols}
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /** Determines whether the grid can be split into three equal horizontal strips. */
    private boolean canPartitionRows(char[][] grid) {
        int blockHeight = grid.length / 3;
        int targetCount = (grid.length * grid[0].length) / 3;

        return isBalancedBlock(grid, 0, blockHeight, targetCount) &&
                isBalancedBlock(grid, blockHeight, 2 * blockHeight, targetCount) &&
                isBalancedBlock(grid, 2 * blockHeight, grid.length, targetCount);
    }

    /** Determines whether the grid can be split into three equal vertical strips. */
    private boolean canPartitionColumns(char[][] grid) {
        int blockWidth = grid[0].length / 3;
        int targetCount = (grid.length * grid[0].length) / 3;

        return isBalancedBlockColumns(grid, 0, blockWidth, targetCount) &&
                isBalancedBlockColumns(grid, blockWidth, 2 * blockWidth, targetCount) &&
                isBalancedBlockColumns(grid, 2 * blockWidth, grid[0].length, targetCount);
    }

    /** Checks that a rectangular region contains exactly {@code target} of each colour. */
    private boolean isBalancedBlock(char[][] grid, int rowStart, int rowEnd, int target) {
        int rCount = 0, gCount = 0, bCount = 0;

        for (int r = rowStart; r < rowEnd; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                switch (grid[r][c]) {
                    case RED -> rCount++;
                    case GREEN -> gCount++;
                    case BLUE -> bCount++;
                }
            }
        }
        return rCount == target && gCount == target && bCount == target;
    }

    /** Checks that a rectangular region contains exactly {@code target} of each colour. */
    private boolean isBalancedBlockColumns(char[][] grid, int colStart, int colEnd, int target) {
        int rCount = 0, gCount = 0, bCount = 0;

        for (int c = colStart; c < colEnd; c++) {
            for (int r = 0; r < grid.length; r++) {
                switch (grid[r][c]) {
                    case RED -> rCount++;
                    case GREEN -> gCount++;
                    case BLUE -> bCount++;
                }
            }
        }
        return rCount == target && gCount == target && bCount == target;
    }

    /** Minimal scanner that splits on whitespace and returns tokens lazily. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        /** Returns the next non‑empty token or {@code null} when the input ends. */
        private String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * The program reads a grid of characters and checks whether it consists of three
 * equal‑sized blocks that are each filled with a single distinct character.
 * The blocks can be arranged either horizontally or vertically.
 */
public class Main {

    private static final char UNDEFINED = '\0';

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] grid = readGrid(sc, n, m);

            if (n % 3 == 0 && checkHorizontalBlocks(grid)) {
                System.out.println("YES");
