import java.util.Scanner;

/**
 * Refactored version of B887.
 *
 * <p>
 * The program reads a number {@code n} (1‑3) followed by {@code 6} digits for each row.
 * It then determines the smallest positive integer that cannot be formed using the
 * digits supplied for each row according to the original specification.
 * </p>
 */
public class B887Refactored {

    /** Maximum values for 1‑, 2‑ and 3‑digit numbers. */
    private static final int MAX_ONE_DIGIT = 9;
    private static final int MAX_TWO_DIGIT = 99;
    private static final int MAX_THREE_DIGIT = 999;

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int rowCount = sc.nextInt();                     // number of rows (1‑3)
            boolean[][] digitPresence = new boolean[rowCount][MAX_ONE_DIGIT + 1];
            int[] maxSeenInRow = new int[rowCount];

            readAllRows(sc, digitPresence, maxSeenInRow, rowCount);

            // If no digit was seen in any row, the answer is trivially 0.
            if (allMaximumDigitsZero(maxSeenInRow)) {
                System.out.println(0);
                return;
            }

            // Dispatch to the appropriate handler based on the number of rows.
            if (rowCount == 1) {
                handleSingleRow(digitPresence[0]);
            } else if (rowCount == 2) {
                handleTwoRows(digitPresence[0], digitPresence[1]);
            } else { // rowCount == 3
                handleThreeRows(digitPresence[0], digitPresence[1], digitPresence[2]);
            }
        }
    }

    /**
     * Reads the input digits for each row and records which digits are present.
     *
     * @param sc            scanner reading the input
     * @param presence      matrix that will hold digit presence per row
     * @param maxSeen       array that will store the maximum digit seen per row
     * @param rowCount      number of rows to read
     */
    private static void readAllRows(Scanner sc,
                                    boolean[][] presence,
                                    int[] maxSeen,
                                    int rowCount) {
        for (int row = 0; row < rowCount; row++) {
            int currentMax = -1;
            for (int column = 0; column < 6; column++) {
                int digit = sc.nextInt();               // each row provides 6 digits
                presence[row][digit] = true;
                if (digit > currentMax) {
                    currentMax = digit;
                }
            }
            maxSeen[row] = currentMax;
        }
    }

    /** Checks whether every entry in {@code maxSeen} is zero. */
    private static boolean allMaximumDigitsZero(int[] maxSeen) {
        for (int value : maxSeen) {
            if (value != 0) {
                return false;
            }
        }
        return true;
    }

    /** Handles the case where only a single row of digits is supplied. */
    private static void handleSingleRow(boolean[] row) {
        // Find the smallest missing digit (1‑9).  If none are missing, output 9.
        for (int d = 1; d <= MAX_ONE_DIGIT; d++) {
            if (!row[d]) {
                System.out.println(d - 1);   // matches original behaviour
                return;
            }
        }
        System.out.println(MAX_ONE_DIGIT);
    }

    /** Handles the case with exactly two rows of digits. */
    private static void handleTwoRows(boolean[] row0, boolean[] row1) {
        // 1‑digit numbers: need the digit to be present in *both* rows.
        for (int d = 1; d <= MAX_ONE_DIGIT; d++) {
            if (!row0[d] && !row1[d]) {
                System.out.println(d - 1);
                return;
            }
        }

        // 2‑digit numbers: tens and units may come from either row, but one must be from each.
        for (int number = 10; number <= MAX_TWO_DIGIT; number++) {
            int tens = number / 10;
            int units = number % 10;
            boolean canForm = (row0[tens] && row1[units]) || (row1[tens] && row0[units]);
            if (!canForm) {
                System.out.println(number - 1);
                return;
            }
        }
        System.out.println(MAX_TWO_DIGIT);
    }

    /** Handles the case with three rows of digits. */
    private static void handleThreeRows(boolean[] row0,
                                        boolean[] row1,
                                        boolean[] row2) {
        // 1‑digit numbers: digit must appear in at least one row.
        for (int d = 1; d <= MAX_ONE_DIGIT; d++) {
            if (!row0[d] && !row1[d] && !row2[d]) {
                System.out.println(d - 1);
                return;
            }
        }

        // 2‑digit numbers: any permutation of the two rows is acceptable.
        for (int number = 10; number <= MAX_TWO_DIGIT; number++) {
            int tens = number / 10;
            int units = number % 10;
            boolean canForm = (row0[tens] && row1[units]) || (row1[tens] && row0[units])
                            || (row0[tens] && row2[units]) || (row2[tens] && row0[units])
                            || (row1[tens] && row2[units]) || (row2[tens] && row1[units]);
            if (!canForm) {
                System.out.println(number - 1);
                return;
            }
        }

        // 3‑digit numbers: any permutation of the three rows is acceptable.
        for (int number = 100; number <= MAX_THREE_DIGIT; number++) {
            int hundreds = number / 100;
            int tens = (number / 10) % 10;
            int units = number % 10;

            boolean canForm = (row0[hundreds] && row1[tens] && row2[units]) ||
                              (row0[hundreds] && row2[tens] && row1[units]) ||
                              (row1[hundreds] && row0[tens] && row2[units]) ||
                              (row1[hundreds] && row2[tens] && row0[units]) ||
                              (row2[hundreds] && row0[tens] && row1[units]) ||
                              (row2[hundreds] && row1[tens] && row0[units]);

            if (!canForm) {
                System.out.println(number - 1);
                return;
            }
        }
        System.out.println(MAX_THREE_DIGIT);
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution – entry point of the application.
 *
 * <p>This class reads the input, stores the data in a dedicated {@link SetStorage},
 * asks {@link MaxFinder} for the largest integer that can be represented, and prints
 * the result.
 *
 * <p>The implementation separates concerns into small, reusable classes, uses
 * meaningful names, eliminates unused global state and makes the algorithm
 * easier to test and maintain.
 */
public final class Solution {

    public static void main(String[] args) {
        InputReader reader = new InputReader();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int n = reader.nextInt();
        SetStorage storage = new SetStorage(n);
        storage.read(reader, 6);                     // each set contains 6 integers

        int answer = MaxFinder.findMaximum(storage.getSets());
        out.println(answer);
        out.close();
    }
}

/**
 * Holds the list of HashSet<Integer> that are read from the input.
 *
 * <p>Provides an immutable view of the stored sets so the caller cannot
 * accidentally modify them.
 */
final class SetStorage {
    private final List<Set<Integer>> sets;

    SetStorage(int size) {
        this.sets = new ArrayList<>(size);
        for (int i = 0; i < size; i++) {
            sets.add(new HashSet<>(6));
        }
    }

    /** Reads {@code elementsPerSet} integers for each set. */
    void read(InputReader reader, int elementsPerSet) {
        for (Set<Integer> set : sets) {
            for (int i = 0; i < elementsPerSet; i++) {
                set.add(reader.nextInt());
            }
        }
    }

    /** Unmodifiable access to the underlying sets. */
    List<Set<Integer>> getSets() {
        return Collections.unmodifiableList(sets);
    }
}

/**
 * Determines the largest integer {@code i} (greater than 0) that can be
 * assembled from digits taken from distinct sets.
 *
 * <p>For a given candidate integer we need:
 * <ul>
 *   <li>its first digit to appear in some set,
 *   <li>its second digit (if any) to appear in a different set,
 *   <li>its third digit (if any) to appear in yet another set.
 * </ul>
 *
 * <p>The search stops at {@code 999} because the problem definition limits us
 * to three‑digit numbers.
 */
final class MaxFinder {

    private static final int UPPER_BOUND = 999;   // exclusive upper limit

    /** Finds the maximal integer that satisfies the digit‑availability rule. */
    static int findMaximum(List<Set<Integer>> sets) {
        int max = 0;
        for (int candidate = 1; candidate < UPPER_BOUND; candidate++) {
            if (isCandidatePossible(candidate, sets)) {
                max = candidate;
            } else {
                break; // first failure terminates the search
            }
        }
        return max;
    }

    /** Checks whether the decimal representation of {@code candidate}
     * can be built from three distinct sets. */
    private static boolean isCandidatePossible(int candidate, List<Set<Integer>> sets) {
        String digits = String.valueOf(candidate);
        switch (digits.length()) {
            case 1 -> return anySetContains(sets, digits.charAt(0) - '0');
            case 2 -> return containsPair(sets,
                    digits.charAt(0) - '0',
                    digits.charAt(1) - '0');
            case 3 -> return containsTriplet(sets,
                    digits.charAt(0) - '0',
                    digits.charAt(1) - '0',
                    digits.charAt(2) - '0');
            default -> false; // candidates longer than three digits are never examined
        }
    }

    /** Returns true if at least one set contains the first digit and another
     * (different) set contains the second digit. */
    private static boolean containsPair(List<Set<Integer>> sets, int first, int second) {
        for (int i = 0; i < sets.size(); i++) {
            if (!sets.get(i).contains(first)) {
                continue;
            }
            for (int j = 0; j < sets.size(); j++) {
                if (i == j) {
                    continue;
                }
                if (sets.get(j).contains(second)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Returns true if there exist three distinct sets containing the three
     * digits respectively. */
    private static boolean containsTriplet(List<Set<Integer>> sets,
                                           int first, int second, int third) {
        for (int i = 0; i < sets.size(); i++) {
            if (!sets.get(i).contains(first)) {
                continue;
            }
            for (int j = 0; j < sets.size(); j++) {
                if (i == j) {
                    continue;
                }
                if (!sets.get(j).contains(second)) {
                    continue;
                }
                for (int k = 0; k < sets.size(); k++) {
                    if (k == i || k == j) {
                        continue;
                    }
                    if (sets.get(k).contains(third)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Convenience wrapper used by {@link #isCandidatePossible} for a single digit. */
    private static boolean anySetContains(List<Set<Integer>> sets, int digit) {
        return sets.stream().anyMatch(set -> set.contains(digit));
    }
}

/* -------------------------------------------------------------------------
 * Utility / legacy classes – kept only for completeness and possible future
 * reuse; they do not interfere with the core algorithm.
 * ------------------------------------------------------------------------- */

final class Util {
    private Util() { }

    /** Counts trailing zeroes in {@code n!}. */
    static int trailingZerosInFactorial(int n) {
        int count = 0;
        for (int divisor = 5; divisor <= n; divisor *= 5) {
            count += n / divisor;
        }
        return count;
    }

    /** Euclidean algorithm for the greatest common divisor. */
    static int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}

final class UnionFind {
    private final int[] parent;
    private final int[] size;
    private int maxSize;

    UnionFind(int n) {
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
        maxSize = 1;
    }

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    void unite(int x, int y) {
        int xp = find(x);
        int yp = find(y);
        if (xp == yp) {
            return;
        }
        // union by size
        if (size[xp] < size[yp]) {
            int tmp = xp; xp = yp; yp = tmp;
        }
        parent[yp] = xp;
        size[xp] += size[yp];
        maxSize = Math.max(maxSize, size[xp]);
    }

    int getMaxSize() {
        return maxSize;
    }

    int componentCount() {
        int cnt = 0;
        for (int i = 0; i < parent.length; i++) {
            if (parent[i] == i) {
                cnt++;
            }
        }
        return cnt;
    }
}

final class Pair implements Comparable<Pair> {
    final int a;
    final int b;

    Pair(int a, int b) {
        this.a = a;
        this.b = b;
    }

    @Override
    public int compareTo(Pair other) {
        if (other.a != this.a) {
            return Integer.compare(this.a, other.a);
        }
        return Integer.compare(this.b, other.b);
    }
}

/**
 * Simple wrapper around {@code BufferedReader} that tokenises input lines.
 */
final class InputReader {
    private final BufferedReader br;
    private StringTokenizer st;

    InputReader() {
        this.br = new BufferedReader(new InputStreamReader(System.in));
    }

    /** Returns the next token, reading a new line if necessary. */
    String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return st.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }

    double nextDouble() {
        return Double.parseDouble(next());
    }

    long nextLong() {
        return Long.parseLong(next());
    }

    /** Returns the rest of the line (not heavily used but kept for compatibility). */
    String nextLine() {
        try {
            return br.readLine();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads several six‑sided dice, each with six integer faces.
 * Determines the largest consecutive integer (starting from 1) that can be
 * formed by concatenating faces of distinct dice in any order.
 * The result is the last integer of that consecutive sequence.
 *
 * The program follows the same semantics as the original version but is
 * organized into small, reusable pieces, uses meaningful names and avoids
 * duplicated logic.
 */
public class Main {

    /** Simple container for a die with six faces. */
    private static final class Die {
        final int[] faces = new int[6];

        Die() { /* no‑op */ }
    }

    /** Fast input scanner used by the original code – kept unchanged. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        public String nextLine() {
            int c = read();
            while (isEndline(c)) c = read();
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return sb.toString();
        }
    }

    /** Entry point – orchestrates input, processing and output. */
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        int n = scanner.nextInt();

        // ---- read the dice -------------------------------------------------
        List<Die> dice = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            Die d = new Die();
            for (int j = 0; j < 6; j++) {
                d.faces[j] = scanner.nextInt();
            }
            dice.add(d);
        }

        // ---- generate all numbers that can be built -----------------------
        Set<Integer> representable = new HashSet<>();
        explore(0, 0, dice, representable);

        // ---- find the largest consecutive integer starting from 1 ----------
        int candidate = 1;
        while (candidate < 1000) {
            if (!representable.contains(candidate)) {
                System.out.println(candidate - 1);
                return;
            }
            candidate++;
        }
        // all numbers 1 … 999 are present → output the last one
        System.out.println(999);
    }

    /**
     * Recursively builds every possible integer by selecting distinct dice
     * and any of their faces. The current numeric value is extended by
     * appending the chosen face as a new least‑significant digit.
     *
     * @param usedMask   bitmask of already used dice
     * @param currentNum value formed so far
     * @param dice       list of all dice
     * @param result     set collecting every obtainable integer
     */
    private static void explore(int usedMask, int currentNum,
                               List<Die> dice, Set<Integer> result) {
        // Record the number if at least one die contributed to it
        if (usedMask != 0) {
            result.add(currentNum);
        }

        // Try to add another die that has not been used yet
        for (int idx = 0; idx < dice.size(); idx++) {
            if ((usedMask & (1 << idx)) == 0) {
                Die d = dice.get(idx);
                for (int face : d.faces) {
                    explore(usedMask | (1 << idx),
                            currentNum * 10 + face,
                            dice,
                            result);
                }
            }
        }
    }
}

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

/**
 * Reads several rows of six digits each and builds all possible numbers that can be
 * formed by picking at most one digit from each row (preserving order) and optionally
 * concatenating them. The program then prints the length of the longest consecutive
 * sequence of positive integers starting from 1 that can be built from those numbers.
 *
 * The implementation is deliberately small, well‑structured and easy to maintain.
 */
public class Main {

    /** Maximum number of digits that may be taken from a single row. */
    private static final int DIGITS_PER_ROW = 6;

    /** Fast scanner wrapper around {@link InputStream}. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int cursor = 0;
        private int length = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readChar() {
            if (length == -1) {
                throw new IOException();
            }
            if (cursor >= length) {
                cursor = 0;
                length = stream.read(buffer);
                if (length <= 0) {
                    length = -1;
                }
            }
            return buffer[cursor++];
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private String nextToken() {
            int ch = readChar();
            while (!isSpace(ch)) {
                ch = readChar();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) ch);
                ch = readChar();
            } while (!isSpace(ch));
            return sb.toString();
        }

        /** Convenience methods used by the driver code. */
        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        long nextLong() {
            return Long.parseLong(nextToken());
        }
    }

    /**
     * Reads {@code n} rows, each containing exactly {@value #DIGITS_PER_ROW} integers,
     * and stores them as a list of digit lists.
     */
    private static List<List<Integer>> readInputRows(int n, FastScanner sc) {
        List<List<Integer>> rows = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            int[] digits = new int[DIGITS_PER_ROW];
            for (int d = 0; d < DIGITS_PER_ROW; d++) {
                digits[d] = sc.nextInt();
            }
            rows.add(toIntegerList(digits));
        }
        return rows;
    }

    /** Utility to convert an int[] to a mutable List<Integer>. */
    private static List<Integer> toIntegerList(int[] arr) {
        List<Integer> list = new ArrayList<>(arr.length);
        for (int v : arr) {
            list.add(v);
        }
        return list;
    }

    /**
     * Builds a {@link Set} of all numbers that can be formed by selecting at most one
     * digit from each supplied row. The algorithm respects the original behaviour:
     * <ul>
     *   <li>for 1 row – single digits and possible two‑digit concatenations,
     *   <li>for 2 rows – all permutations of a digit from each row,
     *   <li>for 3 rows – all permutations of up to three digits.
     * </ul>
     */
    private static Set<Integer> buildAllPossibleNumbers(List<List<Integer>> rows) {
        Set<Integer> numbers = new TreeSet<>();

        int rowCount = rows.size();
        switch (rowCount) {
            case 1 -> addNumbersFromSingleRow(numbers, rows.get(0));
            case 2 -> addNumbersFromTwoRows(numbers, rows.get(0), rows.get(1));
            case 3 -> addNumbersFromThreeRows(numbers, rows.get(0), rows.get(1), rows.get(2));
            default -> {
                // For n > 3 the original program silently produces no numbers.
                // The behaviour is left unchanged for backward compatibility.
            }
        }
        return numbers;
    }

    /** Handles the n = 1 case. */
    private static void addNumbersFromSingleRow(Set<Integer> numbers, List<Integer> row) {
        for (int i = 0; i < DIGITS_PER_ROW; i++) {
            int d = row.get(i);
            if (d != 0) numbers.add(d);

            if (i + 1 < DIGITS_PER_ROW) {
                int next = row.get(i + 1);
                if (d != 0 && next != 0) {
                    numbers.add(d * 10 + next);
                    numbers.add(next * 10 + d);
                }
            }
        }
    }

    /** Handles the n = 2 case. */
    private static void addNumbersFromTwoRows(Set<Integer> numbers,
                                              List<Integer> first,
                                              List<Integer> second) {
        for (int i = 0; i < DIGITS_PER_ROW; i++) {
            int a = first.get(i);
            for (int j = 0; j < DIGITS_PER_ROW; j++) {
                int b = second.get(j);
                if (a != 0) numbers.add(a);
                if (b != 0) numbers.add(b);
                if (a != 0 && b != 0) {
                    numbers.add(a * 10 + b);
                    numbers.add(b * 10 + a);
                }
            }
        }
    }

    /** Handles the n = 3 case. */
    private static void addNumbersFromThreeRows(Set<Integer> numbers,
                                                List<Integer> first,
                                                List<Integer> second,
                                                List<Integer> third) {
        for (int i = 0; i < DIGITS_PER_ROW; i++) {
            int a = first.get(i);
            for (int j = 0; j < DIGITS_PER_ROW; j++) {
                int b = second.get(j);
                for (int k = 0; k < DIGITS_PER_ROW; k++) {
                    int c = third.get(k);

                    // single digits
                    if (a != 0) numbers.add(a);
                    if (b != 0) numbers.add(b);
                    if (c != 0) numbers.add(c);

                    // two‑digit permutations
                    if (a != 0) {
                        numbers.add(a * 10 + b);
                        numbers.add(a * 10 + c);
                    }
                    if (b != 0) {
                        numbers.add(b * 10 + a);
                        numbers.add(b * 10 + c);
                    }
                    if (c != 0) {
                        numbers.add(c * 10 + a);
                        numbers.add(c * 10 + b);
                    }

                    // three‑digit permutations
                    if (a != 0) {
                        numbers.add(a * 100 + b * 10 + c);
                        numbers.add(a * 100 + c * 10 + b);
                    }
                    if (b != 0) {
                        numbers.add(b * 100 + a * 10 + c);
                        numbers.add(b * 100 + c * 10 + a);
                    }
                    if (c != 0) {
                        numbers.add(c * 100 + a * 10 + b);
                        numbers.add(c * 100 + b * 10 + a);
                    }
                }
            }
        }
    }

    /** Finds the length of the longest consecutive sequence starting at 1. */
    private static int longestPrefix(Set<Integer> numbers) {
        int prefixLength = 0;
        for (int value : numbers) {
            if (value != prefixLength + 1) {
                break;
            }
            prefixLength++;
        }
        return prefixLength;
    }

    /** Program entry point. */
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        int rowsCount = scanner.nextInt();

        List<List<Integer>> digitRows = readInputRows(rowsCount, scanner);
        Set<Integer> allNumbers = buildAllPossibleNumbers(digitRows);
        int answer = allNumbers.isEmpty() ? 0 : longestPrefix(allNumbers);

        System.out.println(answer);
    }
}

