/**
 * Simple wrapper around {@link BufferedReader} that makes tokenising input
 * painless and expressive.
 */
final class InputReader {

    private final BufferedReader br;
    private StringTokenizer st;

    InputReader(InputStream source) {
        this.br = new BufferedReader(new InputStreamReader(source));
    }

    /** Returns the next whole token from standard input. */
    private String nextToken() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return st.nextToken();
    }

    /** Convenience shortcut for {@link #nextToken()} → {@code int}. */
    int nextInt() {
        return Integer.parseInt(nextToken());
    }

    /**
     * Reads {@code n} rows of exactly six integer values each and stores them
     * into a {@code boolean[n][10]} matrix. The matrix entry {@code [i][d]}
     * becomes {@code true} when digit {@code d} is present in row *i*.
     *
     * @param n number of rows to read
     * @return matrix where each row is a 10‑length boolean vector
     */
    boolean[][] readPatternMatrix(int n) {
        boolean[][] matrix = new boolean[n][10];
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < 6; ++j) {
                int digit = nextInt();
                matrix[i][digit] = true;
            }
        }
        return matrix;
    }
}

