import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {

    /** Upper bound (inclusive) for the numbers we need to test. */
    private static final int MAX_VALUE = 999;   // original code used 1010 but only checked up to 999

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        Solver solver = new Solver();

        solver.solve(scanner, out);
        out.close();
    }

    /** Holds all logic that solves the problem. */
    static class Solver {

        /** Entry point called from {@link Main}. */
        public void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();                     // number of digit‑sets
            @SuppressWarnings("unchecked")
            Set<Integer>[] digitSets = (Set<Integer>[]) new HashSet[n];

            // read six integers for each of the n sets
            for (int i = 0; i < n; i++) {
                digitSets[i] = new HashSet<>();
                for (int j = 0; j < 6; j++) {
                    digitSets[i].add(in.nextInt());
                }
            }

            int answer = 0;
            // test every candidate number from 1 up to MAX_VALUE
            for (int candidate = 1; candidate <= MAX_VALUE; candidate++) {
                if (!hasValidAssignment(candidate, digitSets, n)) {
                    break;               // no permutation works → stop
                }
                answer = candidate;      // keep the largest successful candidate
            }
            out.println(answer);
        }

        /** Determines whether the decimal representation of {@code number}
         * can be matched injectively to the supplied digit‑sets. */
        private boolean hasValidAssignment(int number,
                                            Set<Integer>[] sets,
                                            int totalSets) {
            List<Integer> digits = extractDigits(number);   // most‑significant → least
            int digitCount = digits.size();

            // all injections from digit positions → set indices
            List<List<Integer>> injections = generateInjections(totalSets, digitCount);
            int successfulAssignments = 0;

            for (List<Integer> perm : injections) {
                boolean ok = true;
                for (int pos = 0; pos < digitCount; pos++) {
                    int setIdx = perm.get(pos);
                    if (!sets[setIdx].contains(digits.get(pos))) {
                        ok = false;
                        break;
                    }
                }
                if (ok) {
                    successfulAssignments++;
                }
            }
            // Mirrors original semantics: break only when no assignment works.
            return successfulAssignments > 0;
        }

        /** Returns the decimal digits of {@code number} from most to least significant. */
        private static List<Integer> extractDigits(int number) {
            List<Integer> digits = new ArrayList<>();
            while (number > 0) {
                digits.add(0, number % 10);   // prepend
                number /= 10;
            }
            return digits;
        }

        /** Generates every injective mapping from {0,…,k‑1} to {0,…,n‑1}. */
        private static List<List<Integer>> generateInjections(int n, int k) {
            List<List<Integer>> result = new ArrayList<>();
            boolean[] used = new boolean[n];
            List<Integer> current = new ArrayList<>(k);
            injectRecursive(n, k, 0, used, current, result);
            return result;
        }

        private static void injectRecursive(int n, int k,
                                            int depth,
                                            boolean[] used,
                                            List<Integer> current,
                                            List<List<Integer>> result) {
            if (depth == k) {
                result.add(new ArrayList<>(current));
                return;
            }
            for (int i = 0; i < n; i++) {
                if (!used[i]) {
                    used[i] = true;
                    current.add(i);
                    injectRecursive(n, k, depth + 1, used, current, result);
                    current.remove(current.size() - 1);
                    used[i] = false;
                }
            }
        }
    }

    /** Simple, fast scanner that reads whitespace‑separated integers. */
    static class FastScanner {

        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int bytesRead = 0;
        private int currentByte = 0;
        private int pointer = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (currentByte == -1) {
                throw new IllegalStateException();
            }
            if (pointer >= bytesRead) {
                currentByte = -1;
                bytesRead = stream.read(buffer);
                pointer = 0;
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        /** Skips whitespace and returns the next non‑whitespace character. */
        private int nextNonWhitespaceChar() {
            int c;
            do {
                c = readByte();
            } while (isSpaceChar(c));
            return c;
        }

        /** Parses the next integer from the input stream. */
        int nextInt() {
            int c = nextNonWhitespaceChar();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            while (c >= '0' && c <= '9') {
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return result * sign;
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the “Cube faced numbers” problem.
 *
 * The program reads a set of cubes, each having six numbers on its faces.
 * It enumerates all possible numbers that can be formed by picking one
 * face from each cube in some order and concatenating the digits.
 * The answer is the smallest positive integer that cannot be formed.
 *
 * The implementation follows a clean, modular design:
 *   • Input parsing is isolated in {@link FastScanner}.
 *   • Cube data is stored in a simple {@code int[][]} matrix.
 *   • All permutations of cube selections are generated by back‑tracking.
 *   • Numbers are generated from a permutation and stored in a {@code Set<Integer>}.
 *   • The search for the first missing positive integer is performed in {@code findAnswer}.
 *
 * The code is deliberately kept deliberately free of advanced language features
 * (no streams, no external libraries) so that it remains easy to understand and
 * maintain for a wide audience.
 */
public class Main implements Runnable {

    /* ----------  INPUT HANDLING  ---------- */

    /** Fast, minimialistic scanner that works with {@link System.in}. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 10];
        private int bufferPos = 0, bufferLen = -1;
        private final BufferedReader lineReader = new BufferedReader(new InputStreamReader(System.in));

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte, -1 if EOF. */
        private int readByte() throws IOException {
            if (bufferPos >= bufferLen) {
                bufferLen = stream.read(buffer);
                bufferPos = 0;
                if (bufferLen <= 0) {
                    return -1;
                }
            }
            return buffer[bufferPos++];
        }

        /** Skips whitespace characters. */
        private static boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads next line (used only for debugging). */
        String nextLine() {
            try {
                return lineReader.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Reads next non‑space character. */
        int nextNonSpace() throws IOException {
            int c;
            do {
                c = readByte();
            } while (isSpace(c));
            return c;
        }

        /** Reads a signed integer. */
        int nextInt() throws IOException {
            int sign = 1;
            int c = nextNonSpace();
            if (c == '-') {
                sign = -1;
                c = nextNonSpace();
            }
            long value = 0;
            while (!isSpace(c)) {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return (int) (sign * value);
        }

        /** Reads a signed long. */
        long nextLong() throws IOException {
            int sign = 1;
            int c = nextNonSpace();
            if (c == '-') {
                sign = -1;
                c = nextNonSpace();
            }
            long value = 0;
            while (!isSpace(c)) {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return sign * value;
        }

        /** Reads next string token (stops at whitespace). */
        String nextToken() throws IOException {
            int c = nextNonSpace();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpace(c));
            return sb.toString();
        }
    }

    /* ----------  CORE LOGIC  ---------- */

    /** Maximum value we need to check – the answer is always < 1 000 000. */
    private static final int MAX_CHECK = 1_000_000;

    /** Cube faces: cube[i][f] = number on face f of cube i. */
    private int[][] cube;

    /** Number of cubes. */
    private int n;

    /** Permutation state used during back‑tracking. */
    private final boolean[] visited;

    /** Holds the numbers produced from a particular permutation of cubes. */
    private final Set<Integer> currentNumbers = new HashSet<>();

    /** Populates {@link #currentNumbers} with all values that can be built
     *  from the cubes indicated by {@code list}. */
    private void generateNumbersFromPermutation(List<Integer> list) {
        currentNumbers.clear();

        switch (list.size()) {
            case 1 -> computeSingle(list.get(0));
            case 2 -> computePair(list.get(0), list.get(1));
            case 3 -> computeTriple(list.get(0), list.get(1), list.get(2));
            default -> throw new IllegalStateException("Unsupported permutation size: " + list.size());
        }
    }

    /** One‑cube case: all six faces become separate numbers. */
    private void computeSingle(int idx) {
        for (int face = 0; face < 6; face++) {
            int val = cube[idx][face];
            if (val != 0) {
                currentNumbers.add(val);
            }
        }
    }

    /** Two‑cube case: concatenate one face of the first cube with one face of the second. */
    private void computePair(int idxA, int idxB) {
        for (int faceA = 0; faceA < 6; faceA++) {
            int numA = cube[idxA][faceA];
            if (numA == 0) {
                continue;
            }
            for (int faceB = 0; faceB < 6; faceB++) {
                int combined = numA * 10 + cube[idxB][faceB];
                if (cube[idxB][faceB] != 0) { // ignore leading zero combinations
                    currentNumbers.add(combined);
                }
            }
        }
    }

    /** Three‑cube case: concatenate three faces in order. */
    private void computeTriple(int idxA, int idxB, int idxC) {
        for (int faceA = 0; faceA < 6; faceA++) {
            int numA = cube[idxA][faceA];
            if (numA == 0) {
                continue;
            }
            for (int faceB = 0; faceB < 6; faceB++) {
                int numAB = numA * 10 + cube[idxB][faceB];
                for (int faceC = 0; faceC < 6; faceC++) {
                    int combined = numAB * 10 + cube[idxC][faceC];
                    if (cube[idxB][faceB] != 0 && cube[idxC][faceC] != 0) {
                        currentNumbers.add(combined);
                    }
                }
            }
        }
        // The original code also added numbers formed by the first two cubes only.
        computePair(idxA, idxB);
        computePair(idxA, idxC);
        computePair(idxB, idxC);
    }

    /** Recursively builds permutations of cube indices of length {@code maxLen}
     *  and feeds each permutation to {@link #generateNumbersFromPermutation}. */
    private void backtrack(int depth, int maxLen, List<Integer> current) {
        if (depth == maxLen) {
            generateNumbersFromPermutation(current);
            return;
        }

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                visited[i] = true;
                current.add(i);
                backtrack(depth + 1, maxLen, current);
                current.remove(current.size() - 1);
                visited[i] = false;
            }
        }
    }

    /** Finds the smallest positive integer that is **not** present in the set of generated numbers. */
    private int findAnswer() {
        for (int i = 1; i <= MAX_CHECK; i++) {
            if (!currentNumbers.contains(i)) {
                return i - 1;
            }
        }
        // If every number up to MAX_CHECK is present, the answer is MAX_CHECK.
        return MAX_CHECK;
    }

    /* ----------  PROGRAM ENTRY POINT  ---------- */

    @Override
    public void run() {
        try (FastScanner sc = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            // ---- read input -------------------------------------------------
            n = sc.nextInt();
            cube = new int[n][6];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    cube[i][j] = sc.nextInt();
                }
            }

            // ---- generate all possible numbers -----------------------------
            visited = new boolean[n];
            // We need to consider permutations of length 1, 2 and 3.
            for (int size = 1; size <= 3 && size <= n; size++) {
                backtrack(0, size, new ArrayList<>());
            }

            // ---- determine answer -----------------------------------------
            int answer = findAnswer();
            out.print(answer);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Launches the program in its own thread (required for some online judges). */
    public static void main(String[] args) {
        new Thread(null, new Main(), "Main", 1 << 26).start();
    }
}

import java.io.*;
import java.util.Arrays;
import java.util.BitSet;

/**
 * Refactored version of the original P887B solution.
 * The program reads several 6‑digit groups, builds all possible
 * numbers that can be formed by concatenating up to three distinct
 * groups, stores them in a BitSet and prints the smallest positive
 * integer that is not present.
 *
 * The refactor focuses on readability, maintainability and proper
 * separation of concerns:
 *   • Input handling is encapsulated in dedicated methods.
 *   • The generation of numbers is isolated in its own method.
 *   • Meaningful variable and method names are used.
 *   • Unused imports and helper print methods have been removed.
 */
public class P887B {

    /** Buffered reader used for fast input. */
    private static BufferedReader reader;

    /** PrintWriter used for output. */
    private static PrintWriter writer;

    /** Tokenizer for splitting input lines. */
    private static StringTokenizer tokenizer;

    /** Start time (used only for diagnostic messages). */
    private static final long START_TIME = System.currentTimeMillis();

    /** --------------------------------------------------------------------- */
    /** Entry point. */
    public static void main(String[] args) throws Exception {
        initIo();

        new P887B().solve();

        writer.close();
        System.err.println("\n[Time : " + (System.currentTimeMillis() - START_TIME) + " ms]");
    }

    /** Initializes the static I/O objects. */
    private static void initIo() throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(new BufferedOutputStream(System.out));
    }

    /** --------------------------------------------------------------------- */
    /** Main solving routine. */
    private void solve() throws IOException {
        int n = nextInt();                     // number of groups
        int[][] groups = readGroups(n);        // each group contains 6 digits

        BitSet numbers = generateNumbers(groups, n);

        int answer = numbers.nextClearBit(1) - 1; // smallest missing positive integer
        writer.println(answer);
    }

    /** --------------------------------------------------------------------- */
    /** Reads `n` groups of six integers each. */
    private static int[][] readGroups(int n) throws IOException {
        int[][] groups = new int[n][];
        for (int i = 0; i < n; i++) {
            groups[i] = readInt(6);
        }
        return groups;
    }

    /** --------------------------------------------------------------------- */
    /** Generates all numbers obtainable by concatenating up to three distinct
     *  groups. The result is stored in a BitSet where each set bit corresponds
     *  to a generated integer.
     */
    private static BitSet generateNumbers(int[][] groups, int n) {
        BitSet bitSet = new BitSet();

        for (int i = 0; i < n; i++) {
            int[] srcI = groups[i];
            for (int di = 0; di < 6; di++) {
                int a = srcI[di];
                bitSet.set(a);

                for (int j = 0; j < n; j++) {
                    if (j == i) continue;
                    int[] srcJ = groups[j];
                    for (int dj = 0; dj < 6; dj++) {
                        int b = srcJ[dj];
                        bitSet.set(concatenate(a, b));

                        if (n >= 3) {
                            for (int k = 0; k < n; k++) {
                                if (k == i || k == j) continue;
                                int[] srcK = groups[k];
                                for (int dk = 0; dk < 6; dk++) {
                                    int c = srcK[dk];
                                    bitSet.set(concatenate(concatenate(a, b), c));
                                }
                            }
                        }
                    }
                }
            }
        }

        return bitSet;
    }

    /** Concatenates two decimal digits (or numbers) into a two‑digit integer. */
    private static int concatenate(int x, int y) {
        return x * 10 + y;
    }

    /** --------------------------------------------------------------------- */
    /** Utility methods for fast token based input. */
    private static String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    private static int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    private static long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    private static double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    // The following helpers are kept only to preserve the exact behaviour of
    // the original program (they are not used in the refactored logic).
    private static String readLine() throws IOException {
        return reader.readLine();
    }

    // No custom print/println overloads are required any more; the standard
    // PrintWriter methods are sufficient.
}

import java.io.InputStream;
import java.io.PrintStream;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

/**
 * Refactored version of the original program.
 *
 * <p>Changes made for maintainability and readability:
 *
 * <ul>
 *   <li>Extracted concerns into small, well‑named methods.</li>
 *   <li>Replaced cryptic variable names with expressive ones.</li>
 *   <li>Removed the misuse of labeled {@code continue} and replaced it with a
 *       clear {@code isValidTriplet} helper.</li>
 *   <li>Encapsulated the cube data in a dedicated {@code Cube} class.</li>
 *   <li>Added Javadoc comments and inline comments to explain the algorithm.</li>
 *   <li>Kept the original input‑output contract unchanged.</li>
 * </ul>
 */
public class Main {

    /** Entry point – delegates work to {@code solve}. */
    public static void main(String[] args) {
        new Main().solve(System.in, System.out);
    }

    /** Reads the whole input, processes it and prints the result. */
    public void solve(InputStream source, PrintStream out) {
        Scanner scanner = new Scanner(source);
        List<Cube> cubes = readCubes(scanner);
        int missing = findMissingDigit(cubes, out);
        if (missing >= 0) {
            out.println(missing);
            return;
        }

        int answer = findFirstValidThreeDigitNumber(cubes);
        out.println(answer);
    }

    /** Parses the list of cubes from the scanner. */
    private static List<Cube> readCubes(Scanner scanner) {
        int count = scanner.nextInt();
        List<Cube> cubes = new ArrayList<>();

        for (int i = 0; i < count; i++) {
            Cube cube = new Cube();
            for (int j = 0; j < 6; j++) {
                int face = scanner.nextInt();
                cube.add(face);
            }
            cubes.add(cube);
        }
        return cubes;
    }

    /**
     * Looks for a digit that never appears on any cube.
     *
     * <p>If a digit 1‑9 is missing, the original program printed
     * {@code digit‑1}. If only digit {@code 0} is missing it printed {@code 9}.
     *
     * @return the value to be printed, or {@code -1} if no such digit exists.
     */
    private static int findMissingDigit(List<Cube> cubes, PrintStream out) {
        Set<Integer> allSeen = new HashSet<>();
        for (Cube cube : cubes) {
            allSeen.addAll(cube.faces());
        }

        // Digits 1‑9
        for (int d = 1; d <= 9; d++) {
            if (!allSeen.contains(d)) {
                return d - 1;               // original behaviour
            }
        }

        // Digit 0
        return allSeen.contains(0) ? -1 : 9;
    }

    /** Finds the first (i, j, k) triplet that satisfies the original algorithm. */
    private static int findFirstValidThreeDigitNumber(List<Cube> cubes) {
        for (int i = 0; i < 10; i++) {
            for (int j = 0; j < 10; j++) {
                for (int k = 0; k < 10; k++) {
                    if (isValidTriplet(i, j, k, cubes)) {
                        // The original code subtracted 1 from the constructed number.
                        return 100 * i + 10 * j + k - 1;
                    }
                }
            }
        }
        // Should never be reached under the problem constraints.
        return 0;
    }

    /**
     * Determines whether the triplet (i, j, k) can be placed on three *distinct*
     * cubes according to the rules encoded in the original program.
     *
     * <p>If such an assignment exists the method returns {@code false},
     * causing the outer loops to continue.  When no assignment exists it
     * returns {@code true}, which triggers the original printing logic.
     */
    private static boolean isValidTriplet(int i, int j, int k, List<Cube> cubes) {
        // Try every possible assignment of the three digits to three distinct cubes.
        for (int l = 0; l < 3; l++) {
            if (!cubes.get(l).contains(i)) {
                continue; // digit i not present on this cube
            }
            for (int m = 0; m < 3; m++) {
                if (m == l) {
                    continue; // cubes must be distinct
                }
                if (!cubes.get(m).contains(j)) {
                    continue; // digit j not present on this cube
                }
                // Special case from the original code: when i==0 && j==0 the condition
                // is a bit relaxed – we simply keep the original behaviour.
                if (i == 0 && j == 0 && (m == 0 || m == 1)) {
                    continue;
                }
                for (int o = 0; o < 3; o++) {
                    if (o == l || o == m) {
                        continue; // cubes must stay distinct
                    }
                    if (cubes.get(o).contains(k)) {
                        // All three digits can be covered by three distinct cubes.
                        // This matches the labelled {@code continue Breakpoint;} in the
                        // original source, so we skip this (i, j, k) combination.
                        return false;
                    }
                }
            }
        }
        // If we fall out of the loops, no distinct assignment exists → triplet is valid.
        return true;
    }

    /** Simple container for a cube's faces. */
    private static final class Cube {
        private final Set<Integer> faces = new HashSet<>();

        void add(int face) {
            faces.add(face);
        }

        boolean contains(int digit) {
            return faces.contains(digit);
        }

        Set<Integer> faces() {
            return faces;
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Task887B {

    public static void main(String[] args) throws IOException {
        try (FastScanner fs = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            solve(fs, out);
        }
    }

    private static void solve(FastScanner fs, PrintWriter out) {
        long diceCount = fs.nextLong();                     // 1, 2 or 3 dice sets
        DiceSet[] diceSets = new DiceSet[(int) diceCount];

        for (int i = 0; i < diceCount; i++) {
            diceSets[i] = loadDiceSet(fs);
        }

        Set<Integer> reachable = generateAllNumbers(diceSets);
        int answer = smallestMissingPositive(reachable);
        out.println(answer);
    }

    /** Reads the six faces of a single die. */
    private static DiceSet loadDiceSet(FastScanner fs) throws IOException {
        int[] faces = new int[6];
        for (int i = 0; i < 6; i++) {
            faces[i] = fs.nextInt();
        }
        return new DiceSet(faces);
    }

    /** Generates every integer that can be formed by using one, two or three dice. */
    private static Set<Integer> generateAllNumbers(DiceSet[] dice) {
        Set<Integer> numbers = new HashSet<>();

        // ----- single‑digit numbers -------------------------------------------------
        for (int face : dice[0].faces()) {
            if (face != 0) numbers.add(face);
        }
        if (dice.length > 1) {
            for (int face : dice[1].faces()) {
                if (face != 0) numbers.add(face);
            }
        }
        if (dice.length > 2) {
            for (int face : dice[2].faces()) {
                if (face != 0) numbers.add(face);
            }
        }

        // ----- two‑digit numbers ----------------------------------------------------
        if (dice.length >= 2) {
            for (int a : dice[0].faces()) {
                for (int b : dice[1].faces()) {
                    if (a != 0) numbers.add(a * 10 + b);
                    if (b != 0) numbers.add(b * 10 + a);
                }
            }
        }
        if (dice.length >= 3) {
            for (int a : dice[1].faces()) {
                for (int b : dice[2].faces()) {
                    if (a != 0) numbers.add(a * 10 + b);
                    if (b != 0) numbers.add(b * 10 + a);
                }
            }
            for (int a : dice[0].faces()) {
                for (int b : dice[2].faces()) {
                    if (a != 0) numbers.add(a * 10 + b);
                    if (b != 0) numbers.add(b * 10 + a);
                }
            }
        }

        // ----- three‑digit numbers --------------------------------------------------
        if (dice.length == 3) {
            for (int a : dice[0].faces()) {
                for (int b : dice[1].faces()) {
                    for (int c : dice[2].faces()) {
                        if (a != 0) {
                            numbers.add(a * 100 + b * 10 + c);
                            numbers.add(a * 100 + c * 10 + b);
                        }
                        if (b != 0) {
                            numbers.add(b * 100 + a * 10 + c);
                            numbers.add(b * 100 + c * 10 + a);
                        }
                        if (c != 0) {
                            numbers.add(c * 100 + a * 10 + b);
                            numbers.add(c * 100 + b * 10 + a);
                        }
                    }
                }
            }
        }

        return numbers;
    }

    /** Finds the smallest positive integer that is **not** present in the set. */
    private static int smallestMissingPositive(Set<Integer> set) {
        int candidate = 0;
        while (set.contains(candidate + 1)) {
            candidate++;
        }
        return candidate;
    }

    /** Simple holder for a die with six faces. */
    private static final class DiceSet {
        private final int[] faces;

        DiceSet(int[] faces) {
            this.faces = Objects.requireNonNull(faces);
        }

        /** Stream over the six face values. */
        IntStream faces() {
            return Arrays.stream(faces);
        }
    }

    /** Fast token scanner based on BufferedReader. */
    private static final class FastScanner implements Closeable {
        private final BufferedReader br;
        private String[] tokenBuffer;
        private int tokenIndex;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
            tokenBuffer = new String[0];
            tokenIndex = 0;
        }

        private String[] splitLine() throws IOException {
            String line = br.readLine();
            return (line == null) ? new String[0] : line.split("\\s+");
        }

        private void ensureTokens(int required) throws IOException {
            while (tokenIndex >= tokenBuffer.length) {
                tokenBuffer = splitLine();
                tokenIndex = 0;
            }
            if (tokenIndex + required > tokenBuffer.length) {
                tokenIndex = 0;
                ensureTokens(required);
            }
        }

        int nextInt() throws IOException {
            ensureTokens(1);
            return Integer.parseInt(tokenBuffer[tokenIndex++]);
        }

        long nextLong() throws IOException {
            ensureTokens(1);
            return Long.parseLong(tokenBuffer[tokenIndex++]);
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 * <p>
 * The program reads an {@code n × 6} matrix of strings and counts how many
 * target values can be found:
 * <ul>
 *   <li>Digits {@code 1} … {@code 9} as single entries.</li>
 *   <li>The string {@code "10"} formed by concatenating two different rows.</li>
 *   <li>The string {@code "100"} formed by concatenating three different rows.</li>
 * </ul>
 * The implementation is deliberately split into small, well‑named methods,
 * uses {@link Scanner#try (java.lang.CharSequence)} for safe resource handling,
 * and avoids the deeply‑nested “break‑by‑flag” pattern of the original code.
 */
public class Solution {

    /** Target strings that are searched for, in order. */
    private static final String[] TARGETS = {"1", "10", "100"};

    public static void main(String[] args) {
        /* -------------------------------------------------------------
         * 1️⃣  Input handling – safe and concise
         * ------------------------------------------------------------- */
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();                     // number of rows
            List<String[]> rows = new ArrayList<>(n);      // store the matrix

            for (int i = 0; i < n; i++) {
                String[] row = new String[6];
                for (int j = 0; j < 6; j++) {
                    row[j] = scanner.next();
                }
                rows.add(row);
            }

            /* -------------------------------------------------------------
             * 2️⃣  Core logic – count occurrences of the targets
             * ------------------------------------------------------------- */
            int answer = 0;

            /* ----- single‑digit targets (1‑9) ----- */
            answer += searchSingleDigitTargets(rows);

            /* ----- "10" formed by concatenating two distinct rows ----- */
            if (foundConcatenation(rows, TARGETS[1], 2)) {
                answer++;
            }

            /* ----- "100" formed by concatenating three distinct rows ----- */
            if (foundConcatenation(rows, TARGETS[2], 3)) {
                answer++;
            }

            /* -------------------------------------------------------------
             * 3️⃣  Output
             * ------------------------------------------------------------- */
            System.out.println(answer);
        }
    }

    /**
     * Searches sequentially for the numbers {@code 1} … {@code 9} in any cell of the matrix.
     * The search stops as soon as a digit cannot be found – exactly the behaviour of the
     * original program (which breaks when the value {@code 10} would be reached).
     *
     * @return the number of single‑digit matches found before reaching {@code 10}
     */
    private static int searchSingleDigitTargets(List<String[]> rows) {
        int matches = 0;
        int current = 1;                     // start with "1"

        while (current < 10) {
            String target = Integer.toString(current);
            boolean found = false;

            for (String[] row : rows) {
                for (String cell : row) {
                    if (target.equals(cell)) {
                        matches++;
                        found = true;
                        break;
                    }
                }
                if (found) {
                    break;
                }
            }

            if (!found) {
                break;   // missing digit → stop, mimicking the original break
            }
            current++;
        }
        return matches;
    }

    /**
     * Checks whether the given {@code target} can be obtained by concatenating
     * exactly {@code parts} distinct rows of the matrix.
     *
     * @param rows      the matrix of input strings
     * @param target    the string we are looking for (e.g. "10" or "100")
     * @param parts     number of rows that must be combined (2 or 3)
     * @return {@code true} if at least one valid concatenation exists
     */
    private static boolean foundConcatenation(List<String[]> rows, String target, int parts) {
        int rowCount = rows.size();

        switch (parts) {
            case 2:
                for (int i = 0; i < rowCount; i++) {
                    for (int j = 0; j < rowCount; j++) {
                        if (i == j) continue;
                        if (concatTwo(rows.get(i), rows.get(j)).equals(target)) {
                            return true;
                        }
                    }
                }
                break;

            case 3:
                for (int i = 0; i < rowCount; i++) {
                    for (int j = 0; j < rowCount; j++) {
                        if (j == i) continue;
                        for (int k = 0; k < rowCount; k++) {
                            if (k == i || k == j) continue;
                            if (concatThree(
                                    rows.get(i), rows.get(j), rows.get(k))
                                    .equals(target)) {
                                return true;
                            }
                        }
                    }
                }
                break;

            default:
                throw new IllegalArgumentException(
                        "Unsupported number of parts: " + parts);
        }
        return false;
    }

    /** Concatenates any cell from {@code row1} with any cell from {@code row2}. */
    private static String concatTwo(String[] row1, String[] row2) {
        for (String s1 : row1) {
            for (String s2 : row2) {
                if (s1 != null && s2 != null) {
                    return s1 + s2;
                }
            }
        }
        return "";
    }

    /** Concatenates any cell from {@code row1} with any cell from {@code row2}
     *  and then with any cell from {@code row3}. */
    private static String concatThree(String[] row1, String[] row2, String[] row3) {
        for (String s1 : row1) {
            for (String s2 : row2) {
                for (String s3 : row3) {
                    if (s1 != null && s2 != null && s3 != null) {
                        return s1 + s2 + s3;
                    }
                }
            }
        }
        return "";
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Fixed size for digit arrays */
    private static final int DIGITS = 10;
    /** Number of integers read per group */
    private static final int INPUTS_PER_GROUP = 6;
    /** Product values that indicate a perfect square (2², 3², 5²) */
    private static final int[] PERFECT_SQUARES = {4, 9, 25};

    public static void main(String[] args) throws IOException {
        /* --------------------------------------------------------------
         *  Input handling – using a fast custom scanner
         * -------------------------------------------------------------- */
        try (InputReader reader = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int groups = reader.nextInt();

            int[] frequency = new int[DIGITS];
            boolean[] visited = new boolean[DIGITS];

            // All digits start with a multiplier of 1
            Arrays.fill(frequency, 1);
            Arrays.fill(visited, false);

            int multiplier = 2; // default multiplier for the first group

            for (int groupIdx = 0; groupIdx < groups; groupIdx++) {
                // Update multiplier for specific groups (1→3, 2→5)
                if (groupIdx == 1) {
                    multiplier = 3;
                } else if (groupIdx == 2) {
                    multiplier = 5;
                }

                // Process the six digits of the current group
                for (int i = 0; i < INPUTS_PER_GROUP; i++) {
                    int digit = reader.nextInt();
                    if (!visited[digit]) {
                        frequency[digit] *= multiplier;
                        visited[digit] = true;
                    }
                }

                // Reset the visited flags for the next group
                Arrays.fill(visited, false);
            }

            /* --------------------------------------------------------------
             *  Core logic – find the smallest two‑digit answer
             * -------------------------------------------------------------- */
            int answer = findSmallestTwoDigitAnswer(frequency);
            out.println(answer);
        }
    }

    /**
     * Implements the original search order:
     *   1. If the first digit of the pair is 0 and the second digit has frequency 1,
     *      answer = (second digit) – 1.
     *   2. Else if frequency[0] == 1, answer = 9.
     *   3. Otherwise, search for the first pair (i, j) whose product of frequencies
     *      equals 4, 9 or 25 → answer = (i*10 + j) – 1.
     *
     * @param freq frequency array after all groups have been processed
     * @return the required answer
     */
    private static int findSmallestTwoDigitAnswer(int[] freq) {
        // 1️⃣  i == 0  &&  j > 0  &&  freq[j] == 1  →  answer = j - 1
        for (int tens = 0; tens < DIGITS; tens++) {
            for (int units = 0; units < DIGITS; units++) {
                if (tens == 0 && units > 0 && freq[units] == 1) {
                    return tens * 10 + units - 1;
                }
                // 3️⃣  product must be one of the allowed perfect squares
                if (containsPerfectSquare(freq[tens] * freq[units])) {
                    return tens * 10 + units - 1;
                }
            }
        }

        // 2️⃣  If we reach here, freq[0] == 1 (the only remaining case)
        // Original program returns 9 in this situation.
        return freq[0] == 1 ? 9 : -1;
    }

    /** Checks whether the supplied value equals any of the allowed perfect squares. */
    private static boolean containsPerfectSquare(int value) {
        for (int square : PERFECT_SQUARES) {
            if (value == square) {
                return true;
            }
        }
        return false;
    }

    /** Simple high‑performance input reader used by the program. */
    private static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int currentByte;
        private int bytesInBuffer = 0;
        private int currentChar;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte from the underlying stream. */
        private int readByte() throws IOException {
            if (currentByte >= bytesInBuffer) {
                bytesInBuffer = stream.read(buffer);
                currentByte = 0;
                if (bytesInBuffer <= 0) {
                    return -1;
                }
            }
            return buffer[currentByte++];
        }

        /** Skips whitespace characters before the next token. */
        private int skipWhiteSpace() throws IOException {
            int c;
            do {
                c = readByte();
            } while (isWhiteSpace(c));
            return c;
        }

        /** Determines whether a character is considered whitespace. */
        private boolean isWhiteSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads the next integer from the input stream. */
        int nextInt() throws IOException {
            int c = skipWhiteSpace();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = readByte();
            } while (!isWhiteSpace(c));
            return result * sign;
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** Maximum number of rows we ever keep (the original code used only the first 3). */
    private static final int MAX_ROWS = 3;
    /** Number of possible digits (0‑9). */
    private static final int MAX_DIGIT = 10;

    /** Number of rows that are really used – either the value read from input
     *  or {@code MAX_ROWS}, whichever is smaller. */
    private static int usedRows;

    /** For each used row, which digits (0‑9) are allowed. */
    private static boolean[][] allowed = new boolean[MAX_ROWS][MAX_DIGIT];

    /** --------------------------------------------------------------------- *
     *  Entry point.                                                             *
     *  --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            readInput(scanner);
        }

        int missingDigit = findFirstMissingDigit();
        int result;

        // -----------------------------------------------------------------
        // 1‑digit case – the smallest digit that is missing in any row.
        // -----------------------------------------------------------------
        if (missingDigit == 0) {
            result = missingDigit;
        } else {
            result = missingDigit - 1;                     // value to print
            if (missingDigit < MAX_DIGIT) {
                // single‑digit output path – nothing else to do
                System.out.println(result);
                return;
            }

            // -------------------------------------------------------------
            // 2‑digit numbers (10 … 99) – the largest number whose two
            // digits can be assigned to *different* allowed rows.
            // -------------------------------------------------------------
            result = findLargestValidNumber(2);
            if (missingDigit < 100) {
                System.out.println(result);
                return;
            }

            // -------------------------------------------------------------
            // 3‑digit numbers (100 … 999) – the largest number whose three
            // digits can be assigned to three *different* allowed rows.
            // -------------------------------------------------------------
            result = findLargestValidNumber(3);
            System.out.println(result);
        }
    }

    /** --------------------------------------------------------------------- *
     *  Reads the input and populates {@code allowed}.                         *
     *  --------------------------------------------------------------------- */
    private static void readInput(Scanner scanner) {
        int n = scanner.nextInt();               // number of rows to follow
        usedRows = Math.min(n, MAX_ROWS);

        // initialise the matrix (in the original code the first index starts at 1)
        for (int r = 0; r < usedRows; r++) {
            allowed[r] = new boolean[MAX_DIGIT];
        }

        for (int row = 0; row < n; row++) {
            // Each row consists of 6 tokens; we keep only the first character
            // of each token, which should be a digit.
            for (int col = 0; col < 6; col++) {
                String token = scanner.next();
                char digitChar = token.charAt(0);
                int digit = digitChar - '0';
                if (row < MAX_ROWS) {
                    allowed[row][digit] = true;
                }
            }
        }
    }

    /** --------------------------------------------------------------------- *
     *  Returns the smallest digit (1‑9) that is **not** present in any of the
     *  first {@code usedRows} rows. If every digit 1‑9 appears somewhere,
     *  the method returns {@code 10}.                                         *
     *  --------------------------------------------------------------------- */
    private static int findFirstMissingDigit() {
        // We look at digits 1‑9 (the original loop started at 1 and stopped at 9).
        for (int d = 1; d < MAX_DIGIT; d++) {
            boolean presentInAnyRow = false;
            for (int r = 0; r < usedRows; r++) {
                if (allowed[r][d]) {
                    presentInAnyRow = true;
                    break;
                }
            }
            if (!presentInAnyRow) {
                return d;                 // first missing digit
            }
        }
        // All digits 1‑9 are present – treat it as “missing” after the last digit.
        return MAX_DIGIT;
    }

    /** --------------------------------------------------------------------- *
     *  Finds the largest integer of a given length (2 or 3) such that each
     *  digit can be mapped to a *different* allowed row.                       *
     *  --------------------------------------------------------------------- */
    private static int findLargestValidNumber(int length) {
        int start = (int) Math.pow(10, length - 1);   // 10 for two‑digit, 100 for three‑digit
        int end   = (int) Math.pow(10, length);      // 100 or 1000

        // Scan upwards; the first number that cannot be validated stops the loop.
        // The value just before it is the answer.
        int i = start;
        for (; i < end; i++) {
            if (!isValidNumber(i)) {
                break;
            }
        }
        return i - 1;        // the last number that satisfied the constraints
    }

    /** --------------------------------------------------------------------- *
     *  Checks whether a numeric value can be built from the allowed rows.
     *  For a two‑digit number the two digits must be assignable to two
     *  *different* rows; for a three‑digit number they must be assignable
     *  to three distinct rows.                                                *
     *  --------------------------------------------------------------------- */
    private static boolean isValidNumber(int number) {
        String digits = Integer.toString(number);
        if (digits.length() != usedRows) {
            return false;        // length must match the number of rows we are testing
        }

        // Try every permutation of row assignments to the digits.
        // The permutations are generated on‑the‑fly using recursion.
        List<Integer> rowOrder = new ArrayList<>(usedRows);
        for (int r = 0; r < usedRows; r++) rowOrder.add(r);
        return hasPermutation(rowOrder, digits, 0);
    }

    /** Recursive helper that attempts to assign rows to each digit position. */
    private static boolean hasPermutation(List<Integer> rows, String digits, int pos) {
        if (pos == digits.length()) {
            return true;   // all positions satisfied a distinct row
        }

        int neededDigit = digits.charAt(pos) - '0';
        // Iterate over remaining rows that have not been used yet.
        for (int i = 0; i < rows.size(); i++) {
            int rowIdx = rows.get(i);
            if (allowed[rowIdx][neededDigit]) {
                // Choose this row, remove it from the candidate list, continue.
                List<Integer> nextRows = new ArrayList<>(rows.subList(0, i));
                nextRows.addAll(rows.subList(i + 1, rows.size()));
                if (hasPermutation(nextRows, digits, pos + 1)) {
                    return true;
                }
            }
        }
        return false;   // no viable row for this digit
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) {
        // Using try‑with‑resources ensures streams are closed properly.
        try (FastReader reader = new FastReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            new Solver().solve(reader, out);
        }
    }

    /** Execution logic for a single test case. */
    static class Solver {
        /** The problem states that at most six flavors are used. */
        private static final int MAX_FLAVORS = 6;

        /** Stores the flavor codes for the current test case. */
        private int[][] flavorCodes;

        /** Number of flavors actually present. */
        private int flavorCount;

        /** Solves one test case. */
        public void solve(FastReader reader, PrintWriter out) {
            flavorCount = reader.nextInt();

            // Read exactly `flavorCount` rows, each containing `MAX_FLAVORS` integers.
            flavorCodes = new int[flavorCount][MAX_FLAVORS];
            for (int i = 0; i < flavorCount; i++) {
                int[] tmp = reader.nextIntArray(MAX_FLAVORS);
                System.arraycopy(tmp, 0, flavorCodes[i], 0, MAX_FLAVORS);
            }

            // Find the largest index `i` that can be represented under the rules.
            int answerIndex = 0;
            while (canBuildNumber(answerIndex)) {
                answerIndex++;
            }
            out.println(answerIndex - 1);
        }

        /** Determines whether the current candidate can be built recursively. */
        private boolean canBuildNumber(int candidate) {
            // Recursive helper tries to place digits at each flavor position.
            return placeDigit(candidate, false, false, false);
        }

        /** Recursive back‑tracking that places digits according to the allowed flavor order.
         *
         * @param remaining   The part of the number still to be placed (divided by 10 each step).
         * @param placed0     Whether the first flavor slot has already been used.
         * @param placed1     Whether the second flavor slot (if it exists) has already been used.
         * @param placed2     Whether the third flavor slot (if it exists) has already been used.
         * @return true if the whole number can be constructed, false otherwise.
         */
        private boolean placeDigit(int remaining, boolean placed0, boolean placed1, boolean placed2) {
            if (remaining == 0) {
                // All digits have been placed successfully.
                return true;
            }

            // Try to place the current least‑significant digit at the first flavor slot.
            if (!placed0 && containsDigit(flavorCodes[0], remaining % 10)) {
                if (placeDigit(remaining / 10, true, placed1, placed2)) {
                    return true;
                }
            }

            // Try the second flavor slot (only if at least two flavors are defined).
            if (flavorCount >= 2 && !placed1 && containsDigit(flavorCodes[1], remaining % 10)) {
                if (placeDigit(remaining / 10, placed0, true, placed2)) {
                    return true;
                }
            }

            // Try the third flavor slot (only when exactly three flavors are defined).
            if (flavorCount >= 3 && !placed2 && containsDigit(flavorCodes[2], remaining % 10)) {
                if (placeDigit(remaining / 10, placed0, placed1, true)) {
                    return true;
                }
            }

            return false; // No placement succeeded.
        }

        /** Checks whether a given flavor code contains the specified digit. */
        private boolean containsDigit(int[] flavor, int digit) {
            for (int code : flavor) {
                if (code == digit) {
                    return true;
                }
            }
            return false;
        }
    }

    /** Fast input reader optimized for competitive‑programming style workloads. */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int bytesRead = 0;
        private int currentByte = 0;

        FastReader(InputStream stream) {
            this.stream = stream;
        }

        /** Reads a single byte, returning −1 on EOF. */
        private int readByte() throws IOException {
            if (bytesRead == -1) {
                return -1;
            }
            if (currentByte >= bytesRead) {
                int count = stream.read(buffer);
                if (count <= 0) {
                    bytesRead = -1;
                    return -1;
                }
                bytesRead = count;
                currentByte = 0;
            }
            return buffer[currentByte++];
        }

        /** Reads the next integer (handles an optional leading minus sign). */
        int nextInt() {
            int c;
            do {
                c = readByte();
            } while (isWhitespace(c));

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            int result = 0;
            while (true) {
                if (!isDigit(c)) {
                    break;
                }
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return result * sign;
        }

        /** Reads exactly `n` integers and returns them as an array. */
        int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        private boolean isDigit(int c) {
            return c >= '0' && c <= '9';
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.*;

public class Main {

    private static final Scanner SCANNER = new Scanner(System.in);
    private static final int SINGLE_MAX = 10;
    private static final int GENERAL_MAX = 1000;

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();
            if (n == 1) {
                int result = processSingleArray(sc);
                System.out.println(Math.max(0, result));
                return;
            }

            int[][] rows = readRows(sc, n);
            int result;
            switch (n) {
                case 2 -> result = processTwoRows(rows);
                case 3 -> result = processThreeRows(rows);
                default -> {
                    System.err.println("Unsupported value of n: " + n);
                    return;
                }
            }
            System.out.println(Math.max(0, result));
        }
    }

    private static int processSingleArray(Scanner sc) {
        int[] digits = readSixDigits(sc);
        boolean[] present = new boolean[SINGLE_MAX + 1];
        for (int d : digits) {
            if (0 <= d && d <= SINGLE_MAX) {
                present[d] = true;
            }
        }
        int missing = findFirstMissing(present, 1, SINGLE_MAX);
        return missing - 1;
    }

    private static int[][] readRows(Scanner sc, int n) {
        int[][] rows = new int[n][6];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                rows[i][j] = sc.nextInt();
            }
        }
        return rows;
    }

    private static int processTwoRows(int[][] rows) {
        boolean[] present = new boolean[GENERAL_MAX + 1];
        // single digits
        for (int digit : rows[0]) present[digit] = true;
        for (int digit : rows[1]) present[digit] = true;
        // two‑digit combinations
        for (int a : rows[0]) {
            for (int b : rows[1]) {
                int num1 = a * 10 + b;
                int num2 = b * 10 + a;
                if (num1 <= GENERAL_MAX) present[num1] = true;
                if (num2 <= GENERAL_MAX) present[num2] = true;
            }
        }
        int missing = findFirstMissing(present, 1, GENERAL_MAX);
        return missing - 1;
    }

    private static int processThreeRows(int[][] rows) {
        boolean[] present = new boolean[GENERAL_MAX + 1];
        // single digits from any row
        for (int[] row : rows) {
            for (int digit : row) {
                present[digit] = true;
            }
        }
        // two‑digit numbers between any two distinct rows
        for (int i = 0; i < rows.length; i++) {
            for (int j = i + 1; j < rows.length; j++) {
                for (int a : rows[i]) {
                    for (int b : rows[j]) {
                        int num1 = a * 10 + b;
                        int num2 = b * 10 + a;
                        if (num1 <= GENERAL_MAX) present[num1] = true;
                        if (num2 <= GENERAL_MAX) present[num2] = true;
                    }
                }
            }
        }
        // three‑digit numbers using one digit from each row in any order
        for (int i = 0; i < 6; i++) {
            for (int j = 0; j < 6; j++) {
                for (int k = 0; k < 6; k++) {
                    int d1 = rows[0][i];
                    int d2 = rows[1][j];
                    int d3 = rows[2][k];
                    present[hundreds(d1, d2, d3)] = true;
                    present[hundreds(d1, d3, d2)] = true;
                    present[hundreds(d2, d1, d3)] = true;
                    present[hundreds(d2, d3, d1)] = true;
                    present[hundreds(d3, d1, d2)] = true;
                    present[hundreds(d3, d2, d1)] = true;
                }
            }
        }
        int missing = findFirstMissing(present, 1, GENERAL_MAX);
        return missing - 1;
    }

    private static int hundreds(int h, int t, int u) {
        return h * 100 + t * 10 + u;
    }

    private static int findFirstMissing(boolean[] present, int from, int to) {
        for (int i = from; i <= to; i++) {
            if (!present[i]) {
                return i;
            }
        }
        return to + 1; // all numbers from 'from' to 'to' are present
    }

    private static int[] readSixDigits(Scanner sc) {
        int[] arr = new int[6];
        for (int i = 0; i < 6; i++) {
            arr[i] = sc.nextInt();
        }
        return arr;
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Entry point of the program.
 * It creates a {@link FastScanner} for fast input,
 * a {@link PrintWriter} for output and delegates the actual solving
 * to {@link TaskB}.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);
        int testCase = 1;                     // the original code always used testNumber = 1
        new TaskB().solve(testCase, scanner, out);
    }

    /**
     * Contains the logic for the three supported test cases.
     * The class is deliberately static and final to avoid unnecessary instantiation.
     */
    private static final class TaskB {

        /** Dispatches to the appropriate case implementation. */
        void solve(int testNumber, FastScanner in, PrintWriter out) {
            switch (testNumber) {
                case 1 -> solveCase1(in, out);
                case 2 -> solveCase2(in, out);
                case 3 -> solveCase3(in, out);
                default -> throw new IllegalArgumentException("Unsupported case: " + testNumber);
            }
        }

        /* --------------------------------------------------------------------- *
         *  CASE 1 – one list of six digits
         *  --------------------------------------------------------------------- */
        private void solveCase1(FastScanner in, PrintWriter out) {
            int[] digits = in.nextIntArray(6);
            // Find the smallest positive digit (1‑9) that does not appear.
            boolean[] present = new boolean[10];
            for (int d : digits) {
                if (d >= 0 && d <= 9) {
                    present[d] = true;
                }
            }
            int missing = 1;
            while (missing < present.length && present[missing]) {
                missing++;
            }
            out.println(missing);
        }

        /* --------------------------------------------------------------------- *
         *  CASE 2 – two independent lists of six digits each
         *  --------------------------------------------------------------------- */
        private void solveCase2(FastScanner in, PrintWriter out) {
            int[] first = in.nextIntArray(6);
            int[] second = in.nextIntArray(6);

            // All digits that can be used by themselves.
            Set<Integer> singleDigits = new HashSet<>();
            singleDigits.addAll(Arrays.stream(first).boxed().collect(Collectors.toSet()));
            singleDigits.addAll(Arrays.stream(second).boxed().collect(Collectors.toSet()));

            // All two‑digit numbers that can be built by taking one digit from each list.
            Set<Integer> twoDigitNumbers = new HashSet<>();
            addTwoDigitNumbers(twoDigitNumbers, first, second);
            addTwoDigitNumbersReverse(twoDigitNumbers, first, second);

            // Scan from 1 up to 99 and stop at the first missing value.
            int limit = 99;
            for (int i = 1; i <= limit; i++) {
                if (!isRepresentable(i, singleDigits, twoDigitNumbers)) {
                    out.println(i - 1);
                    return;
                }
            }
            out.println(limit);
        }

        /** Adds all tens‑unit combinations where the tens digit comes from {@code tensArray}
         *  and the units digit comes from {@code unitsArray}. */
        private void addTwoDigitNumbers(Set<Integer> target, int[] tensArray, int[] unitsArray) {
            for (int tens : tensArray) {
                for (int units : unitsArray) {
                    target.add(tens * 10 + units);
                }
            }
        }

        /** Adds the reversed combinations (units becomes tens). */
        private void addTwoDigitNumbersReverse(Set<Integer> target, int[] unitsArray, int[] tensArray) {
            for (int units : unitsArray) {
                for (int tens : tensArray) {
                    target.add(units * 10 + tens);
                }
            }
        }

        /** Returns {@code true} if {@code value} can be formed using a single digit
         *  or a two‑digit number built from the supplied sets. */
        private boolean isRepresentable(int value, Set<Integer> single, Set<Integer> twoDigits) {
            return single.contains(value) || twoDigits.contains(value);
        }

        /* --------------------------------------------------------------------- *
         *  CASE 3 – three independent lists of six digits each
         *  --------------------------------------------------------------------- */
        private void solveCase3(FastScanner in, PrintWriter out) {
            int[] a = in.nextIntArray(6);
            int[] b = in.nextIntArray(6);
            int[] c = in.nextIntArray(6);

            // Digits that can be used on their own.
            Set<Integer> singleDigits = new HashSet<>();
            singleDigits.addAll(Arrays.stream(a).boxed().collect(Collectors.toSet()));
            singleDigits.addAll(Arrays.stream(b).boxed().collect(Collectors.toSet()));
            singleDigits.addAll(Arrays.stream(c).boxed().collect(Collectors.toSet()));

            // All two‑digit numbers formed by picking one digit from two *different* arrays.
            Set<Integer> twoDigits = new HashSet<>();
            addTwoDigitNumbers(twoDigits, a, b);
            addTwoDigitNumbersReverse(twoDigits, a, b);
            addTwoDigitNumbers(twoDigits, a, c);
            addTwoDigitNumbersReverse(twoDigits, a, c);
            addTwoDigitNumbers(twoDigits, b, c);
            addTwoDigitNumbersReverse(twoDigits, b, c);

            // All three‑digit numbers that can be built by taking one digit from each list
            // and permuting them arbitrarily.
            Set<Integer> threeDigits = generateThreeDigitNumbers(a, b, c);

            int limit = 999;
            for (int i = 1; i <= limit; i++) {
                if (!isRepresentable(i, singleDigits, twoDigits, threeDigits)) {
                    out.println(i - 1);
                    return;
                }
            }
            out.println(limit);
        }

        /** Generates every three‑digit number that can be obtained by using one digit
         *  from each of {@code a}, {@code b} and {@code c} in any order. */
        private Set<Integer> generateThreeDigitNumbers(int[] a, int[] b, int[] c) {
            Set<Integer> result = new HashSet<>();
            for (int x : a) {
                for (int y : b) {
                    for (int z : c) {
                        int[] digits = {x, y, z};
                        // six permutations of three distinct positions
                        result.add(hundreds(digits[0], digits[1], digits[2]));
                        result.add(tens(digits[0], digits[1], digits[2]));   // not used in original logic – kept for symmetry
                        result.add(unit(digits[0], digits[1], digits[2]));   // same comment
                        // The six explicit permutations:
                        result.add(permute(digits, 0, 1, 2));
                        result.add(permute(digits, 0, 2, 1));
                        result.add(permute(digits, 1, 0, 2));
                        result.add(permute(digits, 1, 2, 0));
                        result.add(permute(digits, 2, 0, 1));
                        result.add(permute(digits, 2, 1, 0));
                    }
                }
            }
            return result;
        }

        /** Helper that builds a three‑digit number where {@code d0} is the hundreds,
         *  {@code d1} the tens and {@code d2} the units place. */
        private int hundreds(int d0, int d1, int d2) {
            return d0 * 100 + d1 * 10 + d2;
        }

        /** Helper that builds a three‑digit number where the order of digits is
         *  passed explicitly (used only for readability; the original code used many
         *  ad‑hoc formulas). */
        private int tens(int d0, int d1, int d2) {
            // Not needed for the core algorithm – kept to preserve original intent.
            return -1;
        }

        private int unit(int d0, int d1, int d2) {
            // Not needed for the core algorithm – kept to preserve original intent.
            return -1;
        }

        /** Returns the three‑digit number formed by the supplied permutation indices. */
        private int permute(int[] d, int i, int j, int k) {
            // Map (i,j,k) → (hundreds, tens, units)
            return d[i] * 100 + d[j] * 10 + d[k];
        }

        /** Returns {@code true} if {@code value} can be formed using a single digit,
         *  a two‑digit number, or any three‑digit number supplied in the respective sets. */
        private boolean isRepresentable(int value, Set<Integer> single, Set<Integer> twoDigits, Set<Integer> threeDigits) {
            return single.contains(value) || twoDigits.contains(value) || threeDigits.contains(value);
        }
    }

    /** Very small wrapper around {@link InputStream} that mimics the original
     *  {@code FastReader} but with clearer naming and Javadoc comments. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte from the underlying input, expanding the buffer
         *  when it becomes empty. */
        private int readByte() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        /** Reads the next integer token, skipping leading whitespace. */
        int nextInt() throws IOException {
            int c;
            do {
                c = readByte();
            } while (isWhitespace(c));
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            while (!isWhitespace(c) && c != -1) {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return result * sign;
        }

        /** Reads an array of {@code n} integers. */
        int[] nextIntArray(int n) throws IOException {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        /** Simple whitespace test used by the scanner. */
        private static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Utility class that holds the core logic for solving the problem.
 */
final class DiceGame {

    private DiceGame() { /* utility class – no instances */ }

    /** Convert a String array of six faces into a sorted {@code int[]}. */
    private static int[] parseFaces(String[] faces) {
        int[] result = new int[6];
        for (int i = 0; i < faces.length; i++) {
            result[i] = Integer.parseInt(faces[i]);
        }
        return result;
    }

    /**
     * Checks whether a given {@code number} can be displayed using the supplied boards.
     *
     * <p>The logic matches the original implementation:
     * <ul>
     *   <li>For a single‑digit number the digit must appear on at least one board.</li>
     *   <li>For a two‑digit number the two digits must appear on two different boards.</li>
     * </ul>
     *
     * @param number the integer to test
     * @param boards an array where each element contains the six faces of a board
     * @return {@code true} if the number can be formed, {@code false} otherwise
     */
    private static boolean canFormNumber(int number, String[][] boards) {
        String num = Integer.toString(number);
        List<Set<Integer>> digitBoards = new ArrayList<>();

        // collect the set of boards that contain each digit
        for (char digit : num.toCharArray()) {
            Set<Integer> boardsWithDigit = new HashSet<>();
            for (int b = 0; b < boards.length; b++) {
                if (binarySearch(boards[b], digit)) {
                    boardsWithDigit.add(b);
                }
            }
            digitBoards.add(boardsWithDigit);
        }

        // single‑digit case – just need one board that holds the digit
        if (digitBoards.size() == 1) {
            return !digitBoards.get(0).isEmpty();
        }

        // two‑digit case – need two distinct boards
        Set<Integer> firstDigitBoards = digitBoards.get(0);
        Set<Integer> secondDigitBoards = digitBoards.get(1);

        for (int i : firstDigitBoards) {
            for (int j : secondDigitBoards) {
                if (i != j) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Binary search that works on a sorted {@code String[]}. */
    private static boolean binarySearch(String[] sortedArray, char key) {
        return Arrays.binarySearch(sortedArray, String.valueOf(key)) >= 0;
    }

    /** Entry point – reads input, decides which case to run and prints the answer. */
    public static void main(String[] args) throws IOException {
        // --- input handling ----------------------------------------------------
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int caseType = Integer.parseInt(br.readLine().trim());   // 1, 2 or 3

        // a convenient upper bound used by the original solutions
        final int BOUND = 1000;
        int answer = 0;

        // --- case 1: single die ------------------------------------------------
        if (caseType == 1) {
            String[] faces = br.readLine().split("\\s+");
            int[] sortedFaces = parseFaces(faces);
            Arrays.sort(sortedFaces);

            // find the smallest positive integer that is NOT listed on the die
            for (int i = 1; i < BOUND; i++) {
                if (Arrays.binarySearch(sortedFaces, i) < 0) {
                    answer = i - 1;
                    System.out.println(answer);
                    return;
                }
            }

        // --- case 2: two dice --------------------------------------------------
        } else if (caseType == 2) {
            // first die
            String[] faceArray1 = br.readLine().split("\\s+");
            int[] face1 = parseFaces(faceArray1);
            // second die
            String[] faceArray2 = br.readLine().split("\\s+");
            int[] face2 = parseFaces(faceArray2);

            // boards are the original string representations (sorted for binary search)
            String[][] boards = new String[2][6];
            boards[0] = faceArray1.clone();
            boards[1] = faceArray2.clone();
            for (int i = 0; i < 2; i++) {
                Arrays.sort(boards[i]);
            }

            // look for the smallest integer that cannot be displayed
            for (int i = 1; i < BOUND; i++) {
                String num = Integer.toString(i);
                if (num.length() == 1) {
                    // single digit – must be absent from BOTH dice
                    if (Arrays.binarySearch(boards[0], num.charAt(0)) < 0 &&
                        Arrays.binarySearch(boards[1], num.charAt(0)) < 0) {
                        answer = i - 1;
                        System.out.println(answer);
                        return;
                    }
                } else { // two‑digit number
                    if (!canFormNumber(i, boards)) {
                        answer = i - 1;
                        System.out.println(answer);
                        return;
                    }
                }
            }

        // --- case 3: three boards -----------------------------------------------
        } else if (caseType == 3) {
            String[][] boards = new String[3][6];
            for (int i = 0; i < 3; i++) {
                boards[i] = br.readLine().split("\\s+");
                Arrays.sort(boards[i]);
            }

            // smallest integer that cannot be built using the three boards
            for (int i = 1; i < BOUND; i++) {
                if (!canFormNumber(i, boards)) {
                    answer = i - 1;
                    System.out.println(answer);
                    return;
                }
            }
        }

        // fallback (should never be reached with the original constraints)
        System.out.println(answer);
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

/**
 * Refactored version of B887.
 *
 * <p>
 * The program reads an integer {@code n} followed by {@code 6 * n} integers.
 * Three sets (representing three digit positions) are filled with those
 * integers. Starting from 1 it checks each number up to {@code LIMIT} for a
 * property: none of the six possible permutations of its non‑zero decimal
 * digits can be mapped to the three sets in order. The first index that fails
 * the test is printed; if no such index is found within {@code LIMIT} the
 * program prints {@code 0}.
 * </p>
 */
public class Main {

    /** Upper bound of the search – matches the original hard‑coded value (1000). */
    private static final int LIMIT = 1_000;

    /** Modulo constant kept for compatibility with the original source. */
    private static final int MOD = 1_000_000_007;

    /** Simple fast scanner that reads ints from {@code System.in}. */
    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) { this.in = in; }

        /** Reads the next byte, expanding the buffer when necessary. */
        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        /** Reads the next integer (skipping whitespace). */
        int nextInt() throws IOException {
            int c, sign = 1, val = 0;
            // Skip whitespace
            do {
                c = readByte();
            } while (c <= ' ' && c != -1);

            // Handle optional sign
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            // Build the number
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val * sign;
        }
    }

    /** Extracts the three lowest decimal digits of {@code number} into {@code out[0..2]}. */
    private static void extractDigits(int number, int[] out) {
        out[0] = number % 10;
        number /= 10;
        out[1] = number % 10;
        number /= 10;
        out[2] = number % 10;

        // Replace zeroes with the sentinel value -1 (as in the original code)
        for (int i = 0; i < 3; i++) {
            if (out[i] == 0) {
                out[i] = -1;
            }
        }
    }

    /** Checks whether a digit can be placed into a given set. */
    private static boolean canPlace(Set<Integer> set, int digit) {
        return set.contains(digit);
    }

    /**
     * Determines whether any of the six permutations of {@code digits}
     * can be matched against the three supplied sets.
     *
     * @return {@code true} if at least one permutation fits, {@code false} otherwise.
     */
    private static boolean canPlacePermutation(int[] digits,
                                               Set<Integer> set1,
                                               Set<Integer> set2,
                                               Set<Integer> set3) {
        // Six possible assignments – written explicitly for readability
        if (canPlace(set1, digits[0]) && canPlace(set2, digits[1]) && canPlace(set3, digits[2])) return true;
        if (canPlace(set1, digits[0]) && canPlace(set3, digits[1]) && canPlace(set2, digits[2])) return true;
        if (canPlace(set2, digits[0]) && canPlace(set1, digits[1]) && canPlace(set3, digits[2])) return true;
        if (canPlace(set2, digits[0]) && canPlace(set3, digits[1]) && canPlace(set1, digits[2])) return true;
        if (canPlace(set3, digits[0]) && canPlace(set1, digits[1]) && canPlace(set2, digits[2])) return true;
        if (canPlace(set3, digits[0]) && canPlace(set2, digits[1]) && canPlace(set1, digits[2])) return true;
        return false;
    }

    /** Entry point – mirrors the logic of the original program but with clean structure. */
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        int n = scanner.nextInt();

        // Three collections correspond to the three positions (1, 2, 3)
        Set<Integer>[] allowed = new Set[3];
        for (int i = 0; i < 3; i++) {
            allowed[i] = new HashSet<>(Collections.singleton(-1));
        }

        // Populate the sets: each block of 6 numbers belongs to the set whose index
        // is determined by the block number modulo 3.
        for (int block = 1; block <= n; block++) {
            int setIndex = (block - 1) % 3;
            Set<Integer> target = allowed[setIndex];
            for (int i = 0; i < 6; i++) {
                target.add(scanner.nextInt());
            }
        }

        // Search for the smallest positive integer whose digit permutation cannot be
        // satisfied by the three sets. The loop limit matches the original hard‑coded
        // value of 1000.
        for (int candidate = 1; candidate <= LIMIT; candidate++) {
            int[] digits = new int[3];
            extractDigits(candidate, digits);

            // Attempt all six permutations; if none fit, we have found the answer.
            if (!canPlacePermutation(digits, allowed[0], allowed[1], allowed[2])) {
                out.println(candidate - 1);
                return;
            }
        }

        // No candidate satisfied the condition within the limit.
        out.println(0);
        out.close();
    }
}

import java.io.*;
import java.util.*;

public class Rextester {

    /** Upper bound for the numeric ranges that are examined. */
    private static final int SINGLE_DIGIT_MAX   = 10;   // 0‑9
    private static final int TWO_DIGIT_MAX       = 100;  // 0‑99

    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee the stream is closed.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {

            // -----------------------------------------------------------------
            // 1️⃣  Parse input
            // -----------------------------------------------------------------
            int n = Integer.parseInt(br.readLine().trim());

            // digitPresence[i][d] == true  ⇔  digit *d* occurs in the i‑th number
            boolean[][] digitPresence = new boolean[n][10];
            for (int i = 0; i < n; i++) {
                StringTokenizer st = new StringTokenizer(br.readLine());
                for (int j = 0; j < 6; j++) {
                    int digit = Integer.parseInt(st.nextToken());
                    digitPresence[i][digit] = true;
                }
            }

            // -----------------------------------------------------------------
            // 2️⃣  Compute the required answer
            // -----------------------------------------------------------------
            int answer = computeSmallestMissingNumber(n, digitPresence);
            System.out.println(answer);
        }
    }

    /** Dispatches to the appropriate algorithm based on the number of inputs. */
    private static int computeSmallestMissingNumber(int n, boolean[][] digitPresence) {
        if (n == 1) {
            return findMissingSingleDigit(digitPresence[0]);
        }
        if (n == 2) {
            return findMissingTwoDigits(digitPresence[0], digitPresence[1]);
        }
        // The original program only handles the case n == 3.
        return findMissingThreeDigits(digitPresence);
    }

    /** Looks for the first single‑digit that is absent from the given set. */
    private static int findMissingSingleDigit(boolean[] digits) {
        for (int d = 1; d < SINGLE_DIGIT_MAX; d++) {
            if (!digits[d]) {
                // The original code prints *d‑1* when digit *d* is missing.
                return d - 1;
            }
        }
        // Fallback – never reached for valid input, but required for compilation.
        return 0;
    }

    /** Checks two‑digit candidates against two digit‑presence arrays. */
    private static int findMissingTwoDigits(boolean[] a, boolean[] b) {
        for (int value = 1; value < TWO_DIGIT_MAX; value++) {
            if (value < SINGLE_DIGIT_MAX) {
                // Single‑digit case: both numbers must contain the digit.
                if (!a[value] && !b[value]) {
                    return value - 1;
                }
            } else {
                // Two‑digit case: tens and units can appear in either order.
                int unit  = value % 10;
                int ten   = (value / 10) % 10;

                boolean order1 = a[unit] && b[ten];
                boolean order2 = a[ten] && b[unit];

                if (!order1 && !order2) {
                    return value - 1;
                }
            }
        }
        // Fallback – unreachable for valid input.
        return 0;
    }

    /** Checks three‑digit candidates using the *isPossible* helper. */
    private static int findMissingThreeDigits(boolean[][] digits) {
        // 1️⃣  Single‑digit candidates – all three numbers must contain the digit.
        for (int d = 1; d < SINGLE_DIGIT_MAX; d++) {
            if (!digits[0][d] && !digits[1][d] && !digits[2][d]) {
                return d - 1;
            }
        }

        // 2️⃣  Two‑digit candidates.
        for (int value = 1; value < TWO_DIGIT_MAX; value++) {
            if (value < SINGLE_DIGIT_MAX) {
                continue; // already handled above.
            }

            int unit  = value % 10;
            int ten   = (value / 10) % 10;

            if (!isPossible(unit, ten, digits)) {
                return value - 1;
            }
        }

        // 3️⃣  If every candidate up to 99 is possible, the original program prints 100.
        return 100;
    }

    /**
     * Replicates the original {@code isPossible} logic but with clearer naming.
     *
     * @param firstDigit  digit that must be present in *some* of the three numbers.
     * @param secondDigit digit that must be present in *another* number.
     * @return true if the combination can be formed according to the problem rules.
     */
    private static boolean isPossible(int firstDigit, int secondDigit, boolean[][] digitSets) {
        if (digitSets[0][firstDigit]) {
            if (digitSets[1][secondDigit] || digitSets[2][secondDigit]) {
                return true;
            }
        }
        if (digitSets[1][firstDigit]) {
            if (digitSets[0][secondDigit] || digitSets[2][secondDigit]) {
                return true;
            }
        }
        if (digitSets[2][firstDigit]) {
            if (digitSets[0][secondDigit] || digitSets[1][secondDigit]) {
                return true;
            }
        }
        return false;
    }
}

import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

/**
 * Reads a matrix of integers and prints the smallest positive integer that is
 * missing from a set constructed from the matrix values and their concatenations.
 *
 * <p>Behavior is identical to the original program but the implementation is
 * refactored for readability, testability and maintainability.</p>
 */
public class MissingValueFinder {

    private static final Scanner SCANNER = new Scanner(System.in);

    public static void main(String[] args) {
        int rowCount = readRowCount();
        int[][] matrix = readMatrix(rowCount);
        int missing = determineMissingValue(matrix);
        System.out.println(missing);
        SCANNER.close();
    }

    /** Reads the number of rows (1‑3) from standard input. */
    private static int readRowCount() {
        return SCANNER.nextInt();
    }

    /** Reads the matrix data – each row contains exactly six integers. */
    private static int[][] readMatrix(int rows) {
        int[][] data = new int[rows][6];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < 6; c++) {
                data[r][c] = SCANNER.nextInt();
            }
        }
        return data;
    }

    /** Dispatches to the appropriate logic based on the number of rows. */
    private static int determineMissingValue(int[][] rows) {
        return switch (rows.length) {
            case 1 -> missingFromSingle(rows[0]);
            case 2 -> missingFromDouble(rows[0], rows[1]);
            case 3 -> missingFromTriple(rows[0], rows[1], rows[2]);
            default -> throw new IllegalStateException("Unsupported row count.");
        };
    }

    /** ---- Single‑row processing ------------------------------------------- */

    private static int missingFromSingle(int[] row) {
        Set<Integer> set = buildSingleSet(row);
        return findFirstMissing(set, 7);
    }

    private static Set<Integer> buildSingleSet(int[] row) {
        Set<Integer> set = new HashSet<>();
        for (int v : row) {
            set.add(v);
        }
        return set;
    }

    /** ---- Two‑row processing ---------------------------------------------- */

    private static int missingFromDouble(int[] a, int[] b) {
        Set<Integer> set = new HashSet<>();
        addAllDigits(set, a, b);
        addTwoDigitNumbers(set, a, b);
        return findFirstMissing(set, 1000);
    }

    private static void addAllDigits(Set<Integer> set, int[]... rows) {
        for (int[] row : rows) {
            for (int digit : row) {
                set.add(digit);
            }
        }
    }

    private static void addTwoDigitNumbers(Set<Integer> set, int[] a, int[] b) {
        for (int i = 0; i < a.length; i++) {
            for (int j = 0; j < b.length; j++) {
                set.add(a[i] * 10 + b[j]);
                set.add(b[i] * 10 + a[j]);
            }
        }
    }

    /** ---- Three‑row processing -------------------------------------------- */

    private static int missingFromTriple(int[] r0, int[] r1, int[] r2) {
        Set<Integer> set = new HashSet<>();
        addAllDigits(set, r0, r1, r2);
        addThreeDigitNumbers(set, r0, r1, r2);
        return findFirstMissing(set, 1000);
    }

    private static void addThreeDigitNumbers(Set<Integer> set,
                                               int[] a, int[] b, int[] c) {
        for (int i = 0; i < a.length; i++) {
            for (int j = 0; j < b.length; j++) {
                for (int k = 0; k < c.length; k++) {
                    // six permutations of the three selected digits
                    set.add(a[i] * 100 + b[j] * 10 + c[k]);
                    set.add(a[i] * 100 + c[j] * 10 + b[k]);
                    set.add(b[i] * 100 + a[j] * 10 + c[k]);
                    set.add(b[i] * 100 + c[j] * 10 + a[k]);
                    set.add(c[i] * 100 + a[j] * 10 + b[k]);
                    set.add(c[i] * 100 + b[j] * 10 + a[k]);
                }
            }
        }
    }

    /** ---- Helper to locate the first missing positive integer --------------- */

    private static int findFirstMissing(Set<Integer> set, int upperBound) {
        for (int i = 1; i <= upperBound; i++) {
            if (!set.contains(i)) {
                return i - 1;
            }
        }
        return upperBound;
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class B {

    /** Number of possible digit‑positions (max size of the input). */
    private static final int MAX_SET_SIZE = 3;

    /** Permutations of column indices for each possible size. */
    private static final int[][] ALL_PERMUTATIONS = {
            {}, // size 0 – unused
            {}, // size 1 – unused (no permutation needed)
            {0, 1}, {1, 0},
            {0, 1, 2}, {0, 2, 1}, {1, 0, 2}, {1, 2, 0}, {2, 0, 1}, {2, 1, 0}
    };

    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees proper closing of the streams.
        try (Scanner scanner = new Scanner(new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            final int n = scanner.nextInt();
            List<Set<Integer>> digitSets = readDigitSets(scanner, n);
            out.println(findSmallestMissingPositive(digitSets));
        }
    }

    /** Reads ``n`` sets each containing exactly six integers from ``in``. */
    private static List<Set<Integer>> readDigitSets(Scanner in, int n) {
        List<Set<Integer>> sets = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            Set<Integer> set = new HashSet<>();
            for (int j = 0; j < 6; j++) {
                set.add(in.nextInt());
            }
            sets.add(set);
        }
        return sets;
    }

    /** Core algorithm – returns the smallest positive integer that cannot be built
     *  from the supplied digit‑sets according to the rules described in the original
     *  implementation. */
    private static int findSmallestMissingPositive(List<Set<Integer>> digitSets) {
        final int size = digitSets.size();

        // 1‑digit numbers
        for (int value = 1; value < 10; value++) {
            if (isMissingFromAll(value, digitSets)) {
                return value - 1;               // matches original behaviour
            }
        }

        // Multi‑digit numbers (up to the maximum supported size)
        // The outer loop iterates over numbers with 2, 3, … digits.
        // We stop scanning a particular digit‑length once we have found a gap.
        for (int digits = 2; digits <= size; digits++) {
            // Determine the range of numbers that have exactly ``digits`` decimal digits.
            int lower = (int) Math.pow(10, digits - 1);
            int upper = (int) Math.pow(10, digits) - 1;

            for (int value = lower; value <= upper; value++) {
                if (!isRepresentable(value, digitSets, permutationsForSize(digits))) {
                    return value - 1;               // matches original behaviour
                }
            }
        }

        // Fallback – should never be reached for valid inputs.
        return 0;
    }

    /** Checks whether ``value`` is missing from *all* sets in ``digitSets``. */
    private static boolean isMissingFromAll(int value, List<Set<Integer>> digitSets) {
        return digitSets.stream().anyMatch(set -> !set.contains(value));
    }

    /**
     * Determines whether ``value`` can be built using the supplied ``digitSets``
     * respecting the permutation order defined by ``permutations``.
     *
     * @param value          the integer to test
     * @param digitSets      list of digit‑sets (one per column)
     * @param permutations   permutations of column indices for the current length
     * @return {@code true} if at least one permutation can assign each digit
     *         to a distinct set that contains that digit.
     */
    private static boolean isRepresentable(int value,
                                            List<Set<Integer>> digitSets,
                                            int[][] permutations) {
        String digits = Integer.toString(value);
        int[] digitArray = new int[digits.length()];
        for (int i = 0; i < digits.length(); i++) {
            digitArray[i] = digits.charAt(i) - '0';
        }

        return IntStream.range(0, permutations.length)
                .anyMatch(pIdx -> {
                    int[] perm = permutations[pIdx];
                    boolean ok = true;
                    for (int pos = 0; pos < digitArray.length; pos++) {
                        int digit = digitArray[pos];
                        if (!digitSets.get(perm[pos]).contains(digit)) {
                            ok = false;
                            break;
                        }
                    }
                    return ok;
                });
    }

    /**
     * Returns the appropriate permutation matrix for the given number of digits.
     * The matrices are pre‑computed and stored in ``ALL_PERMUTATIONS``.
     */
    private static int[][] permutationsForSize(int digitCount) {
        if (digitCount <= MAX_SET_SIZE) {
            // Skip the first empty entry; indices start at 1.
            return ALL_PERMUTATIONS[digitCount];
        }
        // For sizes larger than our predefined constants we fall back to an empty array.
        // The original code only supports up to three sets, so this case is never hit.
        return new int[0][];
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the Codeforces‑style digit‑set problem.
 *
 * The program reads an integer {@code n} (1, 2 or 3) that indicates how many
 * digit groups will follow. Each group contains exactly six digits.
 *
 * <p>For {@code n = 1} the smallest positive integer that cannot be formed
 * using any of the six digits is printed.
 *
 * <p>For {@code n = 2} the smallest positive integer that cannot be formed
 * using one digit from the first set and one digit from the second set is
 * printed.
 *
 * <p>For {@code n = 3} the smallest positive integer that cannot be formed
 * using one digit from each of the three sets is printed.
 *
 * The refactor focuses on readability, separation of concerns and reuse of
 * common logic.
 */
public class Codeforces {

    /** Print writer used for all output. */
    private static final PrintWriter OUT = new PrintWriter(new BufferedOutputStream(System.out));

    /**
     * Simple scanner that can be constructed with {@link System#in} or with a
     * {@link FileReader} for file‑based input. It provides typed {@code next*}
     * methods that throw {@link IOException} on I/O errors.
     */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        /** Creates a scanner that reads from standard input. */
        FastScanner() {
            this(new InputStreamReader(System.in));
        }

        /** Creates a scanner that reads from a supplied {@link FileReader}. */
        FastScanner(FileReader fileReader) {
            this.br = new BufferedReader(fileReader);
        }

        /** Reads the next token from the input stream. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(br.readLine());
            }
            return tokenizer.nextToken();
        }

        /** Reads the next integer token. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads the next long token. */
        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        /** Reads the next double token. */
        double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }
    }

    /* -----------------------------------------------------------------------
     *  Helper methods that encapsulate the core algorithmic checks.
     * ----------------------------------------------------------------------- */

    /** Returns {@code true} if {@code number} can be built using a single digit set. */
    private static boolean canFormWithOne(int number, Set<Integer> digits) {
        return digits.contains(number);
    }

    /**
     * Returns {@code true} if {@code number} can be built using exactly two digit
     * sets. The two sets represent the tens and units positions.
     */
    private static boolean canFormWithTwo(int number,
                                           Set<Integer> lowSet,
                                           Set<Integer> highSet) {
        if (number < 10) {
            return canFormWithOne(number, lowSet) || canFormWithOne(number, highSet);
        }

        int units  = number % 10;
        int tens   = number / 10;

        return (lowSet.contains(units) && highSet.contains(tens))
            || (lowSet.contains(tens) && highSet.contains(units));
    }

    /**
     * Returns {@code true} if {@code number} can be built using exactly three digit
     * sets. The three sets represent the hundreds, tens and units positions.
     */
    private static boolean canFormWithThree(int number,
                                            Set<Integer> setA,
                                            Set<Integer> setB,
                                            Set<Integer> setC) {
        if (number < 100) {
            // Numbers below 100 can be handled with the two‑set logic on any pair.
            return canFormWithTwo(number, setA, setB)
                || canFormWithTwo(number, setA, setC)
                || canFormWithTwo(number, setB, setC);
        }

        int units    = number % 10;
        int tens     = (number / 10) % 10;
        int hundreds = number / 100;

        // Test every permutation of assigning the three sets to the three positions.
        return permutationCheck(units, tens, hundreds, setA, setB, setC) ||
               permutationCheck(units, hundreds, tens, setA, setC, setB) ||
               permutationCheck(tens, units, hundreds, setB, setA, setC) ||
               permutationCheck(tens, hundreds, units, setB, setC, setA) ||
               permutationCheck(hundreds, units, tens, setC, setA, setB) ||
               permutationCheck(hundreds, tens, units, setC, setB, setA);
    }

    /** Utility that checks a single permutation of digit‑set assignment. */
    private static boolean permutationCheck(int d1,
                                            int d2,
                                            int d3,
                                            Set<Integer> s1,
                                            Set<Integer> s2,
                                            Set<Integer> s3) {
        return s1.contains(d1) && s2.contains(d2) && s3.contains(d3);
    }

    /* -----------------------------------------------------------------------
     *  Problem‑specific solving methods.
     * ----------------------------------------------------------------------- */

    /** Solves the case where exactly one digit set is provided. */
    private static void solveOne(FastScanner sc) {
        Set<Integer> digits = new HashSet<>();
        for (int i = 0; i < 6; i++) {
            digits.add(sc.nextInt());
        }

        // Find the smallest positive integer that cannot be represented.
        for (int candidate = 1; ; candidate++) {
            if (!canFormWithOne(candidate, digits)) {
                OUT.println(candidate);
                break;
            }
        }
    }

    /** Solves the case where two digit sets are provided. */
    private static void solveTwo(FastScanner sc) {
        Set<Integer> firstSet  = new HashSet<>();
        Set<Integer> secondSet = new HashSet<>();
        for (int i = 0; i < 6; i++) firstSet.add(sc.nextInt());
        for (int i = 0; i < 6; i++) secondSet.add(sc.nextInt());

        // Search up to 99 (the largest two‑digit number).
        for (int candidate = 1; candidate < 100; candidate++) {
            if (!canFormWithTwo(candidate, firstSet, secondSet)) {
                OUT.println(candidate);
                break;
            }
        }
    }

    /** Solves the case where three digit sets are provided. */
    private static void solveThree(FastScanner sc) {
        Set<Integer> set1 = new HashSet<>();
        Set<Integer> set2 = new HashSet<>();
        Set<Integer> set3 = new HashSet<>();
        for (int i = 0; i < 6; i++) set1.add(sc.nextInt());
        for (int i = 0; i < 6; i++) set2.add(sc.nextInt());
        for (int i = 0; i < 6; i++) set3.add(sc.nextInt());

        // Search up to 999 (the largest three‑digit number).
        for (int candidate = 1; candidate < 1000; candidate++) {
            if (!canFormWithThree(candidate, set1, set2, set3)) {
                OUT.println(candidate);
                break;
            }
        }
    }

    /* -----------------------------------------------------------------------
     *  Entry point.
     * ----------------------------------------------------------------------- */

    /**
     * Program entry point.
     *
     * @param args command‑line arguments (unused)
     * @throws IOException if an I/O error occurs while reading input.
     */
    public static void main(String[] args) throws IOException {
        try (FastScanner sc = new FastScanner()) {
            int n = sc.nextInt(); // number of digit groups (1‑3)

            switch (n) {
                case 1 -> solveOne(sc);
                case 2 -> solveTwo(sc);
                case 3 -> solveThree(sc);
                default -> throw new IllegalArgumentException("Unsupported n value: " + n);
            }
        }
        OUT.flush();
    }
}

import java.util.*;
import java.util.stream.Collectors;

/**
 * B_444_2 – Dice‑Cube problem.
 *
 * The program reads a number of cubes (1‑3) where each cube has six faces.
 * For each given configuration it computes the greatest positive integer N
 * such that every number from 1 to N can be displayed by using the shown
 * faces on distinct cubes (each digit occupies its own cube).
 *
 * The refactor introduces a dedicated {@link Cube} value object, extracted
 * helper methods and a simple back‑tracking routine that checks whether a
 * concrete number can be formed.  All duplicated logic from the original
 * implementation has been removed, making the code easier to understand,
 * test and extend.
 */
public class B_444_2 {

    /** ------------------------------------------------------------------- *
     *  Value object that represents a single six‑sided die (cube).          *
     *  ------------------------------------------------------------------- */
    private static final class Cube {
        /** All faces of the cube kept in a {@link Set} for O(1) lookup. */
        private final Set<Integer> faces = new HashSet<>(6);

        /** Reads the six faces of the cube from the provided {@link Scanner}. */
        Cube(Scanner scanner) {
            for (int i = 0; i < 6; i++) {
                faces.add(scanner.nextInt());
            }
        }

        /** Returns {@code true} if the given digit can be placed on this cube. */
        boolean contains(int digit) {
            return faces.contains(digit);
        }
    }

    /** ------------------------------------------------------------------- *
     *  Utility methods – core logic that was previously scattered throughout *
     *  ------------------------------------------------------------------- */

    /**
     * Splits an integer into its decimal digits.
     *
     * @param number non‑negative integer (the program only uses 1 … 999)
     * @return array with the digits in left‑to‑right order
     */
    private static int[] digits(int number) {
        String s = Integer.toString(number);
        int[] d = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            d[i] = s.charAt(i) - '0';
        }
        return d;
    }

    /**
     * Determines whether a given number can be displayed using the supplied
     * cubes.  Each digit must be placed on a *different* cube.
     *
     * @param number   the integer to test (1 … 999)
     * @param cubes    list of cubes that may be used
     * @return {@code true} if the number can be built
     */
    private static boolean canForm(int number, List<Cube> cubes) {
        int[] d = digits(number);
        int needed = d.length;
        int available = cubes.size();

        if (needed > available) {
            return false;                     // not enough distinct cubes
        }

        // Simple back‑tracking: try to assign each digit to a still‑unused cube.
        return assign(0, d, new boolean[available], cubes);
    }

    /** Recursive helper for {@link #canForm}. */
    private static boolean assign(int idx, int[] digits,
                                  boolean[] usedCubes,
                                  List<Cube> cubes) {
        if (idx == digits.length) {
            return true;                      // all digits placed successfully
        }

        int neededDigit = digits[idx];
        for (int i = 0; i < cubes.size(); i++) {
            if (!usedCubes[i] && cubes.get(i).contains(neededDigit)) {
                usedCubes[i] = true;
                if (assign(idx + 1, digits, usedCubes, cubes)) {
                    return true;
                }
                usedCubes[i] = false;        // backtrack
            }
        }
        return false;                         // no cube fits the current digit
    }

    /**
     * Returns the maximal consecutive integer N such that every value
     * 1 … N can be formed with the given set of cubes.
     *
     * @param cubes list of cubes that may be used
     * @return the greatest N (0 if 1 cannot be formed)
     */
    private static int maxConsecutive(List<Cube> cubes) {
        int candidate = 1;
        while (true) {
            if (!canForm(candidate, cubes)) {
                break;
            }
            candidate++;
        }
        return candidate - 1;                 // last successful number
    }

    /** ------------------------------------------------------------------- *
     *  Public helpers that mimic the original overloaded static methods      *
     *  ------------------------------------------------------------------- */

    /** Max number achievable with a single cube. */
    private static int maxUsingOne(List<Cube> cubes) {
        return maxConsecutive(cubes);
    }

    /** Max number achievable with exactly two distinct cubes (order irrelevant). */
    private static int maxUsingTwo(List<Cube> a, List<Cube> b) {
        // Build a temporary list containing the two cubes.
        List<Cube> pair = new ArrayList<>(2);
        pair.addAll(a);
        pair.addAll(b);
        return maxConsecutive(pair);
    }

    /** Max number achievable with the supplied collection of cubes. */
    private static int maxUsing(List<Cube> cubes) {
        return maxConsecutive(cubes);
    }

    /** ------------------------------------------------------------------- *
     *  Program entry point                                                    *
     *  ------------------------------------------------------------------- */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();                     // number of cubes (1‑3)

        // Read all cubes into a list preserving the order of input.
        List<Cube> cubes = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            cubes.add(new Cube(sc));
        }

        int result;

        switch (n) {
            case 1 -> { // only a single cube is available
                result = maxUsingOne(cubes);
            }
            case 2 -> { // two cubes – we have to consider each single cube
                         // and the pair together, then pick the best outcome.
                int single0 = maxUsingOne(Arrays.asList(cubes.get(0)));
                int single1 = maxUsingOne(Arrays.asList(cubes.get(1)));
                int pair    = maxUsingTwo(Arrays.asList(cubes.get(0)),
                                          Arrays.asList(cubes.get(1)));
                result = Math.max(Math.max(single0, single1), pair);
            }
            case 3 -> { // three cubes – the original specification only
                        // examined cubes[0], cubes[1] and the whole set.
                int single0 = maxUsingOne(Arrays.asList(cubes.get(0)));
                int single1 = maxUsingOne(Arrays.asList(cubes.get(1)));
                int pair01  = maxUsingTwo(Arrays.asList(cubes.get(0)),
                                          Arrays.asList(cubes.get(1)));
                result = Math.max(Math.max(single0, single1), pair01);
                result = Math.max(result, maxUsing(cubes)); // all three cubes
            }
            default -> result = 0; // problem guarantees 1‑3 cubes, but keep safety.
        }

        System.out.println(result);
    }
}

import java.io.IOException;
import java.util.*;

public class probB {

    public static void main(String[] args) throws IOException {
        try (Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();
            List<int[]> dice = readDice(sc, n);
            List<Integer> numbers = generateNumbers(dice);
            int answer = computeResult(numbers);
            System.out.println(answer);
        }
    }

    /** Reads the dice faces from standard input. */
    private static List<int[]> readDice(Scanner sc, int n) {
        List<int[]> dice = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int[] faces = new int[6];
            for (int k = 0; k < 6; k++) {
                faces[k] = sc.nextInt();
            }
            dice.add(faces);
        }
        return dice;
    }

    /** Generates all numbers that can be formed from the supplied dice. */
    private static List<Integer> generateNumbers(List<int[]> dice) {
        List<Integer> numbers = new ArrayList<>();
        switch (dice.size()) {
            case 1 -> addSingleDigit(dice, numbers);
            case 2 -> addTwoDigitNumbers(dice, numbers);
            case 3 -> addThreeDigitNumbers(dice, numbers);
            default -> addSingleDigit(dice, numbers); // fallback for future extensions
        }
        Collections.sort(numbers);
        return numbers;
    }

    /** Adds all single‑digit values (the raw faces) to the collection. */
    private static void addSingleDigit(List<int[]> dice, List<Integer> numbers) {
        for (int[] f : dice) {
            for (int v : f) {
                numbers.add(v);
            }
        }
    }

    /** Adds two‑digit numbers formed by using both dice in either order. */
    private static void addTwoDigitNumbers(List<int[]> dice, List<Integer> numbers) {
        addSingleDigit(dice, numbers);                     // keep original duplicates
        for (int i = 0; i < 2; i++) {
            for (int k = 0; k < 6; k++) {
                numbers.add(10 * dice[i][k] + dice[(i + 1) % 2][k]);
                numbers.add(10 * dice[(i + 1) % 2][k] + dice[i][k]);
            }
        }
    }

    /** Adds three‑digit numbers according to the original algorithm, but with clearer structure. */
    private static void addThreeDigitNumbers(List<int[]> dice, List<Integer> numbers) {
        addSingleDigit(dice, numbers);                     // keep original duplicates

        // two‑digit numbers from adjacent dice pairs
        for (int a = 0; a < 3; a++) {
            for (int i = 0; i < 6; i++) {
                for (int k = 0; k < 6; k++) {
                    numbers.add(10 * dice[a][i] + dice[(a + 1) % 3][k]);
                    numbers.add(10 * dice[(a + 1) % 3][k] + dice[a][i]);
                }
            }
        }

        // three‑digit numbers – every permutation of the three dice faces
        // combined with every permutation of the multipliers {1,10,100}
        int[][] multipliers = {
                {100, 10, 1},
                {100, 1, 10},
                {10, 100, 1},
                {10, 1, 100},
                {1, 100, 10},
                {1, 10, 100}
        };
        for (int i = 0; i < 6; i++) {
            for (int j = 0; j < 6; j++) {
                for (int k = 0; k < 6; k++) {
                    for (int[] m : multipliers) {
                        int value = m[0] * dice[0][i] + m[1] * dice[1][j] + m[2] * dice[2][k];
                        numbers.add(value);
                    }
                }
            }
        }
    }

    /** Determines the required output based on the generated numbers. */
    private static int computeResult(List<Integer> nums) {
        if (!nums.contains(1)) {
            return 0;
        }
        Collections.sort(nums);
        int a;
        for (a = 1; a < nums.size(); a++) {
            if (nums.get(a) != nums.get(a - 1) + 1 && nums.get(a) != nums.get(a - 1)) {
                break;
            }
        }
        return nums.get(a - 1);
    }
}

import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

/**
 * Refactored version of the original program.
 *
 * <p>The program reads {@code n} rows, each containing six integers.
 * It then searches for:
 * <ul>
 *   <li>the smallest missing single digit (1‑9);</li>
 *   <li>the smallest missing two‑digit number (10‑99);</li>
 *   <li>the smallest missing three‑digit number (100‑999);</li>
 * </ul>
 * and prints the corresponding value before exiting.
 *
 * <p>All logic is extracted into small, well‑named methods so that the
 * {@code main} method reads like a high‑level story.
 */
public class A {

    /** Entry point – reads input and delegates to the appropriate finder. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            List<Set<Integer>> rows = readRows(scanner);
            findAndPrintMissingDigit(out, rows);
            findAndPrintMissingTwoDigit(out, rows);
            findAndPrintMissingThreeDigit(out, rows);

        } catch (Exception e) {
            // The original program abandoned on any unexpected exception,
            // so we keep the same behaviour.
            System.exit(1);
        }
    }

    /** Reads {@code n} rows, each containing six integers, and stores them as sets. */
    private static List<Set<Integer>> readRows(Scanner scanner) {
        int n = scanner.nextInt();
        List<Set<Integer>> rows = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            Set<Integer> row = new java.util.HashSet<>();
            for (int j = 0; j < 6; j++) {
                row.add(scanner.nextInt());
            }
            rows.add(row);
        }
        return rows;
    }

    /** Finds the smallest missing digit (1‑9) and prints it‑1 before exiting. */
    private static void findAndPrintMissingDigit(PrintWriter out,
                                                  List<Set<Integer>> rows) {
        for (int digit = 1; digit <= 9; digit++) {
            if (!digitExistsInAnyRow(digit, rows)) {
                out.print(digit - 1);
                out.flush();
                System.exit(0);
            }
        }
    }

    /** Finds the smallest missing two‑digit number (10‑99) and prints it‑1. */
    private static void findAndPrintMissingTwoDigit(PrintWriter out,
                                                      List<Set<Integer>> rows) {
        for (int tens = 1; tens <= 9; tens++) {
            for (int ones = 0; ones <= 9; ones++) {
                int candidate = 10 * tens + ones;
                if (isCandidateMissing(candidate, rows)) {
                    out.print(candidate - 1);
                    out.flush();
                    System.exit(0);
                }
            }
        }
    }

    /** Finds the smallest missing three‑digit number (100‑999) and prints it‑1. */
    private static void findAndPrintMissingThreeDigit(PrintWriter out,
                                                        List<Set<Integer>> rows) {
        for (int hundreds = 1; hundreds <= 9; hundreds++) {
            for (int tens = 0; tens <= 9; tens++) {
                for (int ones = 0; ones <= 9; ones++) {
                    int candidate = 100 * hundreds + 10 * tens + ones;
                    if (isCandidateMissing(candidate, rows)) {
                        out.print(candidate - 1);
                        out.flush();
                        System.exit(0);
                    }
                }
            }
        }
    }

    /** Checks whether a given digit occurs in at least one of the rows. */
    private static boolean digitExistsInAnyRow(int digit, List<Set<Integer>> rows) {
        for (Set<Integer> row : rows) {
            if (row.contains(digit)) {
                return true;
            }
        }
        return false;
    }

    /** Determines whether a two‑ or three‑digit candidate is missing from the rows. */
    private static boolean isCandidateMissing(int candidate, List<Set<Integer>> rows) {
        // Convert the candidate into its constituent digits.
        int[] digits = digitArray(candidate);
        // For a two‑digit number the hundreds digit is 0, for a three‑digit it is non‑zero.
        boolean[] present = new boolean[rows.size()];
        for (int i = 0; i < rows.size(); i++) {
            Set<Integer> row = rows.get(i);
            // A digit is “present” if any row contains that digit.
            present[i] = row.contains(digits[0]) && row.contains(digits[1])
                       && (digits.length == 3 ? row.contains(digits[2]) : true);
        }

        // The candidate is missing if we can pick three distinct rows that
        // contain the required digits simultaneously.
        // The original code looked for the *first* triple of indices that
        // satisfied all conditions and broke out when it reached the last
        // possible index, printing the candidate‑1.  The semantics have been
        // preserved by checking the same condition.
        for (int i = 0; i < rows.size(); i++) {
            for (int j = 0; j < rows.size(); j++) {
                for (int k = 0; k < rows.size(); k++) {
                    if (i == j || i == k || j == k) {
                        continue;
                    }
                    if (present[i] && present[j] && present[k]) {
                        // The same exit condition as the original program.
                        if (i == rows.size() - 1 && j == rows.size() - 1 && k == rows.size() - 1) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /** Extracts the decimal digits of a non‑negative integer (up to three digits). */
    private static int[] digitArray(int number) {
        // We only need up to three digits for the problem domain.
        int units = number % 10;
        int tens = (number / 10) % 10;
        int hundreds = (number / 100) % 10;
        return new int[]{hundreds, tens, units};
    }
}

/**
 * Fast input utilities --------------------------------------------------------
 */
final class FastScanner {
    private final byte[] buffer = new byte[4 * 1024];
    private int bufPos = 0;
    private int bufLen = 0;
    private final InputStream in;

    FastScanner(InputStream in) {
        this.in = in;
    }

    /** Reads the next non‑whitespace byte. */
    private int readByte() {
        if (bufPos >= bufLen) {
            bufPos = 0;
            bufLen = in.read(buffer);
            if (bufLen <= 0) {
                return -1;
            }
        }
        return buffer[bufPos++];
    }

    /** Skips whitespace characters. */
    private int skipWhiteSpace(int b) {
        while (!isWhiteSpace(b)) {
            b = readByte();
        }
        return b;
    }

    /** True if the byte is a whitespace character or EOF. */
    private static boolean isWhiteSpace(int b) {
        return b == ' ' || b == '\n' || b == '\r' || b == '\t' || b == -1;
    }

    /** Fast integer scanner. */
    int nextInt() {
        int sign = 1;
        int c = skipWhiteSpace(readByte());

        if (c == '-') {
            sign = -1;
            c = readByte();
        }

        int result = 0;
        while (!isWhiteSpace(c) && c != -1) {
            if (c >= '0' && c <= '9') {
                result = result * 10 + (c - '0');
            }
            c = readByte();
        }
        return sign * result;
    }
}

/**
 * Tiny wrapper around PrintWriter to avoid repeated allocation. ---------------
 */
final class FastOutput {
    private final PrintWriter writer;

    FastOutput(OutputStream out) {
        this.writer = new PrintWriter(out);
    }

    void println(int value) {
        writer.println(value);
    }

    void close() {
        writer.close();
    }
}

/**
 * Core algorithm -------------------------------------------------------------
 * The original program read up to 1000 possibilities, filled a boolean flag
 * array and finally counted how many of the first 1000 integers were ever
 * touched.  All costly work is performed inside {@link CoreSolver}.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        FastOutput out = new FastOutput(System.out);

        // The solver does not need the test case number – it works on the data
        // read from the scanner.
        new CoreSolver().run(scanner, out);

        out.close();
    }

    /**
     * Simple façade that decouples I/O from the algorithm.
     */
    static class CoreSolver {

        /** Entry point used by {@code main}. */
        void run(FastScanner in, FastOutput out) {
            int n = in.nextInt();                     // number of rows
            int[][] values = readArray(n, in);          // 2‑dimensional source

            boolean[] seen = markAllCombinations(values); // core marking logic
            int answer = countConsecutiveFromOne(seen);   // how many leading ints are true

            out.println(answer);
        }

        /**
         * Reads {@code n} rows, each containing exactly six integers.
         */
        private static int[][] readArray(int n, FastScanner in) {
            int[][] arr = new int[n][6];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    arr[i][j] = in.nextInt();
                }
            }
            return arr;
        }

        /**
         * Marks every integer that can be built from the given numbers by:
         *   • simple products of two digits (tens place)   →  a*b*10
         *   • simple sums turned into two‑digit numbers   →  a + b*10
         *   • products of three digits (hundreds, tens, units) in every permutation.
         * <p>
         * The boolean array is sized to cover the whole search space used in the
         * original program (0 … 999).  Anything larger would be irrelevant because
         * the final count stops at the first missing value.
         */
        private static boolean[] markAllCombinations(int[][] data) {
            boolean[] flags = new boolean[1000];

            // Pairwise combinations (two numbers, one digit from each)
            markTwoDigitCombinations(data, flags);

            // Triple combinations (three numbers, three digits)
            markThreeDigitCombinations(data, flags);

            return flags;
        }

        /** Mark two‑digit numbers that can be built from two different rows. */
        private static void markTwoDigitCombinations(int[][] data, boolean[] flags) {
            for (int i = 0; i < data.length; i++) {
                for (int j = i + 1; j < data.length; j++) {
                    for (int a = 0; a < 6; a++) {
                        for (int b = 0; b < 6; b++) {
                            int tens = data[i][a] * 10 + data[j][b];
                            int units = data[i][a] + data[j][b] * 10;
                            if (tens < flags.length) flags[tens] = true;
                            if (units < flags.length) flags[units] = true;
                        }
                    }
                }
            }
        }

        /** Mark three‑digit numbers built from three distinct rows. */
        private static void markThreeDigitCombinations(int[][] data, boolean[] flags) {
            for (int i = 0; i < data.length; i++) {
                for (int j = i + 1; j < data.length; j++) {
                    for (int k = j + 1; k < data.length; k++) {
                        for (int a = 0; a < 6; a++) {
                            for (int b = 0; b < 6; b++) {
                                for (int c = 0; c < 6; c++) {
                                    int number1 = data[i][a] * 100 + data[j][b] * 10 + data[k][c];
                                    int number2 = data[i][a] * 100 + data[k][c] * 10 + data[j][b];
                                    int number3 = data[j][b] * 100 + data[i][a] * 10 + data[k][c];
                                    int number4 = data[j][b] * 100 + data[k][c] * 10 + data[i][a];
                                    int number5 = data[k][c] * 100 + data[i][a] * 10 + data[j][b];
                                    int number6 = data[k][c] * 100 + data[j][b] * 10 + data[i][a];

                                    if (number1 < flags.length) flags[number1] = true;
                                    if (number2 < flags.length) flags[number2] = true;
                                    if (number3 < flags.length) flags[number3] = true;
                                    if (number4 < flags.length) flags[number4] = true;
                                    if (number5 < flags.length) flags[number5] = true;
                                    if (number6 < flags.length) flags[number6] = true;
                                }
                            }
                        }
                    }
                }
            }
        }

        /** Count how many integers beginning from 1 are present in the flag array. */
        private static int countConsecutiveFromOne(boolean[] flags) {
            int count = 0;
            for (int i = 1; i < flags.length; i++) {
                if (flags[i]) {
                    count = i;
                } else {
                    break;
                }
            }
            return count;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point of the program.
 * Reads input, processes it and prints the result.
 */
public class Main {

    /** Program entry point */
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        solve(scanner, out);
        out.flush();
    }

    /**
     * Core solving routine.
     *
     * @param scanner input scanner
     * @param out     output writer
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        int groupsCount = scanner.nextInt();               // original variable “n”
        List<Set<Integer>> groups = new ArrayList<>();

        // Read up to three groups, each consisting of exactly six integers.
        for (int g = 0; g < Math.min(groupsCount, 3); g++) {
            Set<Integer> set = new HashSet<>();
            for (int i = 0; i < 6; i++) {
                set.add(scanner.nextInt());
            }
            groups.add(set);
        }

        int count = 0;

        // ---------- 1‑digit numbers (1 … 9) ----------
        for (int digit = 1; digit <= 9; digit++) {
            if (groups.stream().anyMatch(set -> set.contains(digit))) {
                count++;
            } else {
                out.println(count);
                return;
            }
        }

        // ---------- 2‑digit numbers (10 … 99) ----------
        if (groups.size() >= 2) {
            for (int num = 10; num <= 99; num++) {
                String s = Integer.toString(num);
                int d1 = s.charAt(0) - '0';
                int d2 = s.charAt(1) - '0';

                boolean valid = false;
                // Try every ordered pair of distinct groups.
                for (int i = 0; i < groups.size(); i++) {
                    for (int j = 0; j < groups.size(); j++) {
                        if (i == j) continue;
                        if (groups.get(i).contains(d1) && groups.get(j).contains(d2)) {
                            valid = true;
                            break;
                        }
                    }
                    if (valid) break;
                }
                if (!valid) {
                    out.println(count);
                    return;
                }
                count++;
            }
        }

        // ---------- 3‑digit numbers (100 … 999) ----------
        if (groups.size() == 3) {
            for (int num = 100; num <= 999; num++) {
                String s = Integer.toString(num);
                int[] digits = new int[3];
                for (int k = 0; k < 3; k++) {
                    digits[k] = s.charAt(k) - '0';
                }

                boolean valid = false;
                // Generate all permutations of the three group indices.
                int[] perm = {0, 1, 2};
                do {
                    if (groups.get(perm[0]).contains(digits[0])
                            && groups.get(perm[1]).contains(digits[1])
                            && groups.get(perm[2]).contains(digits[2])) {
                        valid = true;
                        break;
                    }
                } while (nextPermutation(perm));

                if (!valid) {
                    out.println(count);
                    return;
                }
                count++;
            }
        }

        out.println(count);
    }

    /** Generates the next lexicographic permutation of the array (in‑place). */
    private static boolean nextPermutation(int[] array) {
        int n = array.length;
        int i = n - 2;
        while (i >= 0 && array[i] >= array[i + 1]) {
            i--;
        }
        if (i < 0) {
            return false;
        }
        int j = n - 1;
        while (array[j] <= array[i]) {
            j--;
        }
        swap(array, i, j);
        reverse(array, i + 1, n - 1);
        return true;
    }

    private static void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    private static void reverse(int[] arr, int from, int to) {
        while (from < to) {
            swap(arr, from++, to--);
        }
    }

    /** Fast scanner based on a buffered byte array. */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        /** Skips whitespace characters. */
        private int skipWhitespace(int c) {
            while (!isSpaceChar(c)) {
                c = readByte();
            }
            return c;
        }

        public int nextInt() {
            int c = readByte();
            while (isSpaceChar(c)) {
                c = readByte();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            do {
                result = result * 10 + (c - '0');
                c = readByte();
            } while (!isSpaceChar(c));
            return result * sign;
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.IOException;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 * The refactor focuses on readability, maintainability and proper structure:
 * <ul>
 *   <li>Separated concerns (input, processing, output)</li>
 *   <li>Used meaningful names and constants</li>
 *   <li>Extracted repeated logic into well‑named methods</li>
 *   <li>Avoided mixing {@code Scanner} and {@code StreamTokenizer}</li>
 *   <li>Replaced magic numbers with symbolic constants</li>
 *   <li>Added short comments explaining each step</li>
 * </ul>
 */
public class Main {

    /** Maximum possible concatenated value for the original algorithm (3‑digit numbers) */
    private static final int MAX_CONCATENATED_VALUE = 1_000;

    /** Number of columns each input row contains */
    private static final int COLUMNS = 6;

    public static void main(String[] args) throws IOException {
        // try‑with‑resources guarantees the scanner is closed correctly
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();                 // number of rows
            int[][] matrix = readMatrix(scanner, n);   // read the matrix

            int[] counts = new int[MAX_CONCATENATED_VALUE];

            // Apply the special logic that depends on the value of n
            if (n == 2) {
                processTwoRows(matrix, counts);
            } else if (n == 3) {
                processThreeRows(matrix, counts);
            }

            // Find the first missing positive integer and print it
            findFirstMissing(counts);
        }
    }

    /**
     * Reads {@code n} rows of six integers each from the supplied {@link Scanner}.
     */
    private static int[][] readMatrix(Scanner scanner, int rows) {
        int[][] matrix = new int[rows][COLUMNS];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < COLUMNS; j++) {
                matrix[i][j] = scanner.nextInt();
            }
        }
        return matrix;
    }

    /** Handles the case when exactly two rows are present. */
    private static void processTwoRows(int[][] matrix, int[] counts) {
        // Every ordered pair of elements taken from different rows
        for (int i = 0; i < COLUMNS; i++) {
            for (int j = 0; j < COLUMNS; j++) {
                counts[concatenate(matrix[0][i], matrix[1][j])]++;
                counts[concatenate(matrix[1][j], matrix[0][i])]++;
            }
        }
    }

    /** Handles the case when exactly three rows are present. */
    private static void processThreeRows(int[][] matrix, int[] counts) {
        // Permutations of picking one element from each row and concatenating them in all orders
        for (int i = 0; i < COLUMNS; i++) {
            for (int j = 0; j < COLUMNS; j++) {
                for (int k = 0; k < COLUMNS; k++) {
                    counts[concatenate(matrix[0][i], matrix[1][j], matrix[2][k])]++;
                    counts[concatenate(matrix[0][i], matrix[2][k], matrix[1][j])]++;
                    counts[concatenate(matrix[1][j], matrix[0][i], matrix[2][k])]++;
                    counts[concatenate(matrix[1][j], matrix[2][k], matrix[0][i])]++;
                    counts[concatenate(matrix[2][k], matrix[0][i], matrix[1][j])]++;
                    counts[concatenate(matrix[2][k], matrix[1][j], matrix[0][i])]++;
                }
            }
        }

        // Additionally process the 2‑row combinations that also appear in the original code
        processTwoRows(matrix, counts);
    }

    /**
     * Concatenates the supplied integers in the order they are given and returns the resulting value.
     * The method assumes the resulting number fits into {@link #MAX_CONCATENATED_VALUE}.
     */
    private static int concatenate(int... values) {
        StringBuilder sb = new StringBuilder(values.length * 2);
        for (int v : values) {
            sb.append(v);
        }
        return Integer.parseInt(sb.toString());
    }

    /**
     * Scans {@code counts} for the first index {@code i} such that {@code counts[i] == 0}
     * and prints {@code i‑1}. If no such index is found, prints {@code MAX_CONCATENATED_VALUE‑1}.
     */
    private static void findFirstMissing(int[] counts) {
        for (int value = 1; value < counts.length; value++) {
            if (counts[value] == 0) {
                System.out.println(value - 1);
                return;
            }
        }
        // Fall‑through case (mirrors original behaviour)
        System.out.println(MAX_CONCATENATED_VALUE - 1);
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution that preserves the original behaviour while improving
 * readability, naming, structure and resource handling.
 */
public class Main {

    /** Buffered reader used for input. */
    private static final BufferedReader IN = new BufferedReader(
            new InputStreamReader(System.in));

    /** Buffered writer used for output. */
    private static final BufferedWriter OUT = new BufferedWriter(
            new OutputStreamWriter(System.out));

    /** Accumulator for the final answer. */
    private static final StringBuilder ANSWER = new StringBuilder();

    /** Tokeniser used to split a line into integer tokens. */
    private static StringTokenizer tokenizer;

    /** Reads the next line and creates a fresh tokenizer. */
    private static void prepareTokenizer() throws IOException {
        String line = IN.readLine();
        if (line == null || line.isEmpty()) {
            throw new IOException("Unexpected end of input");
        }
        tokenizer = new StringTokenizer(line);
    }

    /** Reads a single integer from {@link #IN}. */
    private static int nextInt() throws IOException {
        return Integer.parseInt(IN.readLine());
    }

    /** Reads the next token from the current tokenizer (must be prepared first). */
    private static int nextTokenInt() {
        return Integer.parseInt(tokenizer.nextToken());
    }

    /**
     * Builds a matrix {@code presence}[digit][listIndex] where
     * {@code presence[d][i]} is {@code 1} iff digit {@code d} occurs in
     * {@code lists.get(i)}.
     */
    private static int[][] buildPresenceMatrix(List<Integer> digit,
                                               List<Integer>[] lists) {
        int rows = digit.size();
        int cols = lists.length;
        int[][] presence = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            int d = digit.get(i);
            for (int j = 0; j < cols; j++) {
                presence[i][j] = lists[j].contains(d) ? 1 : 0;
            }
        }
        return presence;
    }

    /**
     * Counts how many rows of {@code matrix} contain at least one {@code 1}.
     */
    private static int countNonEmptyRows(int[][] matrix) {
        int count = 0;
        for (int[] row : matrix) {
            int sum = 0;
            for (int val : row) {
                sum += val;
            }
            if (sum > 0) {
                count++;
            }
        }
        return count;
    }

    /**
     * Counts how many columns of {@code matrix} contain at least one {@code 1}.
     */
    private static int countNonEmptyColumns(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int count = 0;
        for (int c = 0; c < cols; c++) {
            int sum = 0;
            for (int r = 0; r < rows; r++) {
                sum += matrix[r][c];
            }
            if (sum > 0) {
                count++;
            }
        }
        return count;
    }

    /**
     * Determines whether the digit set represented by {@code digit}
     * satisfies the original “continue” condition.
     */
    private static boolean shouldContinue(List<Integer> digit,
                                          List<Integer>[] lists) {
        int[][] presence = buildPresenceMatrix(digit, lists);
        int rowsWithPresence = countNonEmptyRows(presence);
        int colsWithPresence = countNonEmptyColumns(presence);
        int digitSize = digit.size();

        // The original logic: keep looping while both counts are >= digit size
        return rowsWithPresence >= digitSize && colsWithPresence >= digitSize;
    }

    /** Core algorithm – executed from {@code main}. */
    private static void solve() throws IOException {
        // ----- 1. Read input -------------------------------------------------
        int n = nextInt();                 // number of lists
        prepareTokenizer();                // first line already consumed

        // Store the six numbers of each of the n lines
        List<Integer>[] digitLists = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            digitLists[i] = new ArrayList<>();
        }

        for (int i = 0; i < n; i++) {
            prepareTokenizer();            // tokenise the i‑th line
            for (int j = 0; j < 6; j++) {
                digitLists[i].add(nextTokenInt());
            }
        }

        // ----- 2. Search the breaking value -----------------------------------
        // Upper bound: 10^n (exclusive)
        final int upperBound = (int) Math.pow(10, n);
        int x = 1;

        while (x < upperBound) {
            // Extract decimal digits of x
            List<Integer> currentDigits = new ArrayList<>();
            int tmp = x;
            while (tmp > 0) {
                int d = tmp % 10;
                currentDigits.add(d);
                tmp /= 10;                 // simpler than (tmp - d) / 10
            }

            // Check the original condition
            if (!shouldContinue(currentDigits, digitLists)) {
                break;
            }
            x++;
        }

        // ----- 3. Output the answer -----------------------------------------
        ANSWER.append(x - 1).append('\n');
        OUT.write(ANSWER.toString());
        OUT.flush();
        OUT.close();            // close the writer (mirrors original behaviour)
    }

    /** Entry point – delegates to {@code solve()}. */
    public static void main(String[] args) throws IOException {
        solve();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.io.BufferedWriter;
import java.io.OutputStreamWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution that is easier to read, test and maintain.
 * The algorithm is identical to the original program:
 * <ul>
 *   <li>Read {@code n} rows, each containing six integers (0 – 999).</li>
 *   <li>Mark every single integer that appears.</li>
 *   <li>For every unordered pair of rows, concatenate each value from the first
 *       row with each value from the second row (both orders) and mark the
 *       resulting numbers.</li>
 *   <li>Find the smallest positive integer (≤ 1000) that was never marked.
 *       Output that integer minus one; if every number 1…1000 is marked,
 *       output nothing.</li>
 * </ul>
 */
public class Solution {

    /* --------------------------------------------------------------------- */
    /*  Fast scanner – a tiny wrapper around BufferedReader                    */
    /* --------------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new BufferedReader(
                    new InputStreamReader(stream)));
        }

        /** Returns the next token, reading a new line when necessary. */
        private void reloadTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    tokenizer = null;
                } else {
                    tokenizer = new StringTokenizer(line);
                }
            }
        }

        String next() throws IOException {
            reloadTokenizer();
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        int[] readIntArray(int size) throws IOException {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Utility math helpers                                                  */
    /* --------------------------------------------------------------------- */
    private static long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    private static long modPow(long base, long exp) {
        if (exp == 0) {
            return 1;
        }
        if (exp % 2 == 0) {
            long half = modPow(base, exp / 2);
            return half * half;
        }
        return base * modPow(base, exp - 1);
    }

    private static long lcm(long a, long b) {
        return a / gcd(a, b) * b;          // avoid overflow by dividing first
    }

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                           */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(
                new BufferedWriter(new OutputStreamWriter(System.out))
        );

        solve(scanner, out);

        out.close();
    }

    /* --------------------------------------------------------------------- */
    /*  Core solving method                                                     */
    /* --------------------------------------------------------------------- */
    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();                     // number of rows
        int[][] rows = new int[n][6];                  // each row has 6 integers
        boolean[] reachable = new boolean[1_001];      // index == value

        // -----------------------------------------------------------------
        // 1. read data and mark every single integer that appears
        // -----------------------------------------------------------------
        for (int i = 0; i < n; i++) {
            rows[i] = scanner.readIntArray(6);
            for (int v : rows[i]) {
                if (v <= 1_000) {
                    reachable[v] = true;
                }
            }
        }

        // -----------------------------------------------------------------
        // 2. combine values from different rows and mark concatenations
        // -----------------------------------------------------------------
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                for (int a : rows[i]) {
                    for (int b : rows[j]) {
                        // concatenate a then b
                        int concatAb = Integer.parseInt(String.format("%d%d", a, b));
                        if (concatAb <= 1_000) {
                            reachable[concatAb] = true;
                        }
                        // concatenate b then a
                        int concatBa = Integer.parseInt(String.format("%d%d", b, a));
                        if (concatBa <= 1_000) {
                            reachable[concatBa] = true;
                        }
                    }
                }
            }
        }

        // -----------------------------------------------------------------
        // 3. find the smallest positive integer that was never marked
        // -----------------------------------------------------------------
        for (int candidate = 1; candidate <= 1_000; candidate++) {
            if (!reachable[candidate]) {
                out.println(candidate - 1);   // same output as original program
                return;
            }
        }

        // If every number 1…1000 is reachable, the original program prints
        // nothing – we keep that behaviour.
    }
}

/**
 * Refactored version of the original program.
 *
 * The refactor focuses on:
 *  • Clear naming and Java‑style conventions
 *  • Encapsulation of responsibilities (I/O, data model, algorithm)
 *  • Use of final where possible and avoidance of unnecessary static fields
 *  • Removing duplicated/clarity‑poor loops
 *  • Adding helpful comments and small utility classes
 *
 * The program’s behaviour is unchanged: it reads a number {@code n}
 * and {@code n} cubes (each cube supplies six integers).  It then
 * records all values that can be produced by a single face,
 * a pair of faces from two different cubes, or a triple of faces
 * from three different cubes.  Finally it prints the smallest
 * non‑negative integer that was **not** recorded.
 *
 * The matrix‑related code from the original source has been kept
 * only as a separate utility class (MatrixUtil) because it was
 * unrelated to the main algorithm but still present in the original
 * source.
 */
import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {

    /* --------------------------------------------------------------------- */
    /* 1️⃣  Data model – representation of a cube                              */
    /* --------------------------------------------------------------------- */
    public static final class Cube {
        private final int[] faces = new int[6];

        /**
         * Reads exactly six integers from the supplied {@link BufferedReader}.
         *
         * @throws IOException if the input ends prematurely
         */
        public Cube(BufferedReader br) throws IOException {
            String line = br.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input while reading a cube");
            }
            StringTokenizer tk = new StringTokenizer(line);
            for (int i = 0; i < 6; i++) {
                faces[i] = Integer.parseInt(tk.nextToken());
            }
        }

        /** Returns the six face values of the cube. */
        public int[] getFaces() {
            return faces;
        }

        @Override
        public String toString() {
            return Arrays.toString(faces);
        }
    }

    /* --------------------------------------------------------------------- */
    /* 2️⃣  Small helper utilities                                            */
    /* --------------------------------------------------------------------- */
    public static final class MathUtil {

        /** Multiply two long matrices under a modulus. */
        public static long[][] multiply(long[][] a, long[][] b, long mod) {
            Objects.requireNonNull(a);
            Objects.requireNonNull(b);
            int rows = a.length;
            int cols = b[0].length;
            int inner = a[0].length;
            long[][] result = new long[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    long sum = 0;
                    for (int k = 0; k < inner; k++) {
                        sum = (sum + (a[i][k] * b[k][j]) % mod) % mod;
                    }
                    result[i][j] = sum;
                }
            }
            return result;
        }

        /** Multiply two double matrices (no modulus). */
        public static double[][] multiply(double[][] a, double[][] b) {
            Objects.requireNonNull(a);
            Objects.requireNonNull(b);
            int rows = a.length;
            int cols = b[0].length;
            int inner = a[0].length;
            double[][] result = new double[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    double sum = 0;
                    for (int k = 0; k < inner; k++) {
                        sum += a[i][k] * b[k][j];
                    }
                    result[i][j] = sum;
                }
            }
            return result;
        }

        /** Integer exponentiation with modulus (binary exponentiation). */
        public static long pow(long base, long exponent, long mod) {
            base %= mod;
            long result = 1;
            while (exponent > 0) {
                if ((exponent & 1L) == 1L) {
                    result = (result * base) % mod;
                }
                base = (base * base) % mod;
                exponent >>= 1;
            }
            return result;
        }

        /** Floating‑point exponentiation (binary exponentiation). */
        public static double pow(double base, long exponent) {
            double result = 1.0;
            while (exponent > 0) {
                if ((exponent & 1L) == 1L) {
                    result *= base;
                }
                base *= base;
                exponent >>= 1;
            }
            return result;
        }

        /** Pow, Pow‑matrix implementations omitted here – they are not used. */
    }

    /* --------------------------------------------------------------------- */
    /* 3️⃣  Core algorithm – solves the problem                              */
    /* --------------------------------------------------------------------- */
    public static final class Solver {
        /** Maximum size of the tracking array (original program used 100 000). */
        private static final int TRACKING_LIMIT = 100_000;

        /** All cubes read from input. */
        private final List<Cube> cubes = new ArrayList<>();

        /** Boolean flag array: {@code true} if a number has been produced. */
        private final boolean[] seen = new boolean[TRACKING_LIMIT + 1];

        /**
         * Constructs the solver.
         *
         * @param scanner a {@link Scanner} that reads from {@code System.in}
         * @param n       the number of cubes that will follow
         */
        public Solver(Scanner scanner, int n) {
            // 1️⃣  Read every cube and mark each individual face value.
            for (int i = 0; i < n; i++) {
                Cube cube = new Cube(scanner);
                cubes.add(cube);
                for (int face : cube.getFaces()) {
                    if (face <= TRACKING_LIMIT) {
                        seen[face] = true;
                    }
                }
            }

            // 2️⃣  Mark all combinations of two faces from two different cubes.
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == j) continue;
                    combineTwo(cubes.get(i), cubes.get(j));
                }
            }

            // 3️⃣  Mark all combinations of three faces from three different cubes.
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < n; k++) {
                        if (i == j || j == k || i == k) continue;
                        combineThree(cubes.get(i), cubes.get(j), cubes.get(k));
                    }
                }
            }
        }

        /** Record every number formed by a face of {@code a} followed by a face of {@code b}. */
        private void combineTwo(Cube a, Cube b) {
            for (int av : a.getFaces()) {
                for (int bv : b.getFaces()) {
                    int combined = av * 10 + bv;
                    if (combined <= TRACKING_LIMIT) {
                        seen[combined] = true;
                    }
                }
            }
        }

        /** Record every number formed by a face of {@code a}, then {@code b}, then {@code c}. */
        private void combineThree(Cube a, Cube b, Cube c) {
            for (int av : a.getFaces()) {
                for (int bv : b.getFaces()) {
                    for (int cv : c.getFaces()) {
                        int combined = av * 100 + bv * 10 + cv;
                        if (combined <= TRACKING_LIMIT) {
                            seen[combined] = true;
                        }
                    }
                }
            }
        }

        /**
         * Returns the smallest non‑negative integer that has **not** been recorded.
         * The original program stopped at the first missing value + 1, which is
         * replicated here.
         */
        public int solve() {
            // Scan forward until we find a gap in the recorded values.
            for (int i = 1; i <= TRACKING_LIMIT; i++) {
                if (!seen[i]) {
                    return i;
                }
            }
            // If no gap up to the limit, return limit + 1 (mirrors original exit).
            return TRACKING_LIMIT + 1;
        }
    }

    /* --------------------------------------------------------------------- */
    /* 4️⃣  Entry point                                                       */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        // Using Scanner is simpler than the original hand‑rolled tokenizer.
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();          // number of cubes
            Solver solver = new Solver(scanner, n);
            int answer = solver.solve();
            System.out.println(answer);
            // Scanner automatically closes the underlying input stream.
        }
    }
}

import java.util.*;
import java.util.stream.*;

public class DigitCubePermutation {

    /** highest value we need to test (the problem guarantees it fits in 3 digits) */
    private static final int MAX_CHECKED_VALUE = 999;

    /** each cube has exactly six faces */
    private static final int FACES_PER_CUBE = 6;

    /** --------------------------------------------------------------
     *  Represents a single cube – it stores which digits (0‑9) are present
     *  on any of its faces.
     *  -------------------------------------------------------------- */
    private static final class DigitCube {
        private final boolean[] present = new boolean[10]; // digit → present?

        DigitCube(int[] faces) {
            Arrays.fill(present, false);
            for (int face : faces) {
                if (face >= 0 && face <= 9) {
                    present[face] = true;
                }
            }
        }

        /** true if the cube contains the given digit */
        boolean contains(int digit) {
            return present[digit];
        }
    }

    /** --------------------------------------------------------------
     *  Entry point.
     *  -------------------------------------------------------------- */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();                         // number of cubes
            List<DigitCube> cubes = readCubes(scanner, n);
            List<int[]> permutations = generatePermutations(n);
            int answer = findMaximumRepresentableNumber(cubes, permutations);
            System.out.println(answer);
        }
    }

    /** --------------------------------------------------------------
     *  Reads the faces of all cubes from the scanner.
     *  -------------------------------------------------------------- */
    private static List<DigitCube> readCubes(Scanner scanner, int count) {
        List<DigitCube> cubes = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            int[] faces = new int[FACES_PER_CUBE];
            for (int j = 0; j < FACES_PER_CUBE; j++) {
                faces[j] = scanner.nextInt();
            }
            cubes.add(new DigitCube(faces));
        }
        return cubes;
    }

    /** --------------------------------------------------------------
     *  Generates every possible ordering of cube indices (permutations).
     *  -------------------------------------------------------------- */
    private static List<int[]> generatePermutations(int count) {
        if (count == 1) {
            return List.of(new int[]{0});
        }
        if (count == 2) {
            return List.of(new int[]{0, 1}, new int[]{1, 0});
        }
        // count == 3 – the only remaining case required by the problem
        return List.of(
                new int[]{0, 1, 2},
                new int[]{0, 2, 1},
                new int[]{1, 0, 2},
                new int[]{1, 2, 0},
                new int[]{2, 0, 1},
                new int[]{2, 1, 0}
        );
    }

    /** --------------------------------------------------------------
     *  Finds the largest integer (≤ 999) that **cannot** be displayed with
     *  the given cubes respecting the permutation rules.
     *  -------------------------------------------------------------- */
    private static int findMaximumRepresentableNumber(
            List<DigitCube> cubes, List<int[]> permutations) {

        for (int value = 1; value <= MAX_CHECKED_VALUE; value++) {
            String digits = String.valueOf(value);
            if (!canRepresent(digits, cubes, permutations)) {
                return value - 1;               // the last value that *can* be formed
            }
        }
        return MAX_CHECKED_VALUE;               // all values 1‑999 are representable
    }

    /** --------------------------------------------------------------
     *  Determines whether the decimal representation of `number` can be
     *  built using the cubes according to one of the supplied permutations.
     *  -------------------------------------------------------------- */
    private static boolean canRepresent(String number,
                                          List<DigitCube> cubes,
                                          List<int[]> permutations) {
        return permutations.stream().anyMatch(perm -> {
            boolean[] used = new boolean[cubes.size()];
            int usedCount = 0;

            for (char ch : number.toCharArray()) {
                int digit = Character.digit(ch, 10);
                boolean found = false;
                for (int i = 0; i < perm.length; i++) {
                    int cubeIdx = perm[i];
                    if (!used[cubeIdx] && cubes.get(cubeIdx).contains(digit)) {
                        used[cubeIdx] = true;
                        usedCount++;
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    return false;                 // this permutation fails for this digit
                }
            }
            return usedCount == number.length();   // all digits consumed exactly once
        });
    }
}

