/**
 * Entry point – reads the “type” (1, 2 or 3) and delegates to the appropriate
 * solver method. All resources are closed with try‑with‑resources.
 */
public class Main {
    public static void main(String[] args) {
        try (InputStream in = System.in;
             PrintWriter out = new PrintWriter(System.out)) {

            InputReader reader = new InputReader(in);
            new Solver(reader, out).solve();
        }
    }
}

/**
 * Simple wrapper around {@link BufferedReader} that provides tokenised input.
 */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
    }

    /** Returns the next token or creates a new one from the next line. */
    private String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Convenience method for reading an {@code int}. */
    int nextInt() {
        return Integer.parseInt(next());
    }
}

/**
 * Core logic – handles the three different problem flavours (1‑set, 2‑sets,
 * 3‑sets).  The implementation is deliberately split into small, well‑named
 * methods making the code easy to test and maintain.
 */
class Solver {
    private final InputReader reader;
    private final PrintWriter out;

    Solver(InputReader reader, PrintWriter out) {
        this.reader = reader;
        this.out = out;
    }

    /** Dispatches to the appropriate handling routine. */
    void solve() {
        int type = reader.nextInt();          // 1, 2 or 3
        switch (type) {
            case 1 -> handleOneSet();
            case 2 -> handleTwoSets();
            case 3 -> handleThreeSets();
            default -> throw new IllegalArgumentException("Unsupported type: " + type);
        }
    }

    /** --------------------------------------------------------------
     *  1‑set case
     *  --------------------------------------------------------------
     */
    private void handleOneSet() {
        Set<Integer> set = readSixNumbers();
        int answer = findLastConsecutivePresent(set);
        out.println(answer);
    }

    /** --------------------------------------------------------------
     *  2‑set case
     *  --------------------------------------------------------------
     */
    private void handleTwoSets() {
        Set<Integer> setA = readSixNumbers();
        Set<Integer> setB = readSixNumbers();

        // 1. Find the first missing digit (1‑9). If it exists we output the
        //    last present digit – exactly what the original code did.
        Set<Integer> union = union(setA, setB);
        int missing = findMissingDigit(union);
        if (missing <= 9) {
            out.println(missing - 1);
            return;
        }

        // 2. Otherwise, compute the largest two‑digit number that can be built
        //    using one digit from each set (order may be swapped).
        int answer = computeLargestTwoDigit(setA, setB);
        out.println(answer);
    }

    /** --------------------------------------------------------------
     *  3‑set case
     *  --------------------------------------------------------------
     */
    private void handleThreeSets() {
        Set<Integer> setA = readSixNumbers();
        Set<Integer> setB = readSixNumbers();
        Set<Integer> setC = readSixNumbers();

        // 1. Same missing‑digit early‑exit as the two‑set case.
        Set<Integer> union = union(setA, setB, setC);
        int missing = findMissingDigit(union);
        if (missing <= 9) {
            out.println(missing - 1);
            return;
        }

        // 2. Compute the maximal three‑digit number that can be formed using
        //    exactly one digit from each set (any permutation of the sets is
        //    allowed).
        int answer = computeLargestThreeDigit(setA, setB, setC);
        out.println(answer);
    }

    /** --------------------------------------------------------------
     *  Helper methods – shared across all cases
     *  --------------------------------------------------------------
     */

    /** Reads exactly six integers from the input and stores them in a set. */
    private Set<Integer> readSixNumbers() {
        Set<Integer> set = new HashSet<>();
        for (int i = 0; i < 6; i++) {
            set.add(reader.nextInt());
        }
        return set;
    }

    /** Returns the union of all supplied sets. */
    private static Set<Integer> union(Set<Integer>... sets) {
        Set<Integer> result = new HashSet<>();
        for (Set<Integer> s : sets) {
            result.addAll(s);
        }
        return result;
    }

    /** Finds the smallest digit 1‑9 that is *not* present in the union set.
     *  Returns 10 when all digits 1‑9 are present. */
    private static int findMissingDigit(Set<Integer> union) {
        for (int i = 1; i <= 9; i++) {
            if (!union.contains(i)) {
                return i;
            }
        }
        return 10; // sentinel meaning “all present”
    }

    /** Replicates the original “last consecutive present digit” logic. */
    private static int findLastConsecutivePresent(Set<Integer> set) {
        int last = 0;
        for (int i = 1; i <= 9; i++) {
            if (set.contains(i)) {
                last = i;
            } else {
                break;
            }
        }
        return last;
    }

    /** Computes the largest two‑digit number whose tens digit comes from one
     *  set and the units digit from the other (order may be swapped). */
    private static int computeLargestTwoDigit(Set<Integer> a, Set<Integer> b) {
        int max = 0;
        for (int tens = 1; tens <= 9; tens++) {
            for (int units = 0; units <= 9; units++) {
                if ((a.contains(tens) && b.contains(units)) ||
                    (b.contains(tens) && a.contains(units))) {
                    max = tens * 10 + units;
                }
            }
        }
        return max;
    }

    /** Computes the largest three‑digit number that can be built using one
     *  digit from each of the three supplied sets, where any permutation of
     *  the sets over the hundreds‑, tens‑ and units‑places is allowed. */
    private static int computeLargestThreeDigit(Set<Integer> a, Set<Integer> b, Set<Integer> c) {
        int max = 0;
        int[] sets = {a, b, c};

        // Generate all permutations of {0,1,2} to try every assignment of sets
        // to the three positional groups.
        int[] perm = {0, 1, 2};
        do {
            Set<Integer> hundreds = sets[perm[0]];
            Set<Integer> tens = sets[perm[1]];
            Set<Integer> units = sets[perm[2]];

            for (int h = 1; h <= 9; h++) {
                if (!hundreds.contains(h)) continue;
                for (int t = 0; t <= 9; t++) {
                    if (!tens.contains(t)) continue;
                    for (int u = 0; u <= 9; u++) {
                        if (!units.contains(u)) continue;
                        int candidate = h * 100 + t * 10 + u;
                        max = Math.max(max, candidate);
                    }
                }
            }
        } while (nextPermutation(perm));

        return max;
    }

    /** Generates the next lexicographic permutation of the given array.
     *  Returns {@code false} if the current arrangement is the last one. */
    private static boolean nextPermutation(int[] arr) {
        int i = arr.length - 2;
        while (i >= 0 && arr[i] >= arr[i + 1]) i--;
        if (i < 0) return false;

        int j = arr.length - 1;
        while (arr[j] <= arr[i]) j--;
        swap(arr, i, j);
        reverse(arr, i + 1, arr.length - 1);
        return true;
    }

    private static void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    private static void reverse(int[] a, int from, int to) {
        while (from < to) {
            swap(a, from++, to--);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 * The logic is unchanged, but the code has been reorganised
 * for readability, maintainability and proper resource handling.
 */
public class Main {

    /** Upper bound of the search – the original program used 999 as a magic value. */
    private static final int MAX_ITER = 999;

    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees that both reader and writer are closed.
        try (InputReader reader = new InputReader(System.in);
             OutputWriter writer = new OutputWriter(System.out)) {
            new TaskB().solve(reader, writer);
        }
    }

    /** --------------------------------------------------------------
     *  Core solving class – contains all methods that implement the
     *  algorithm described in the original source.
     *  --------------------------------------------------------------
     */
    static class TaskB {

        private static final int ROWS = 6;   // The matrix always has 6 rows.

        /** Entry point used by {@code main}. */
        public void solve(InputReader reader, OutputWriter out) {
            int n = reader.nextInt();                     // size of each dimension
            int[][] matrix = readMatrix(reader, n);       // 6 × n integer matrix
            int answer = findAnswer(matrix, n);           // compute the result
            out.print(answer);                            // output the answer
        }

        /** Reads the 6 × n matrix from the input stream. */
        private int[][] readMatrix(InputReader reader, int n) {
            int[][] data = new int[ROWS][n];
            for (int col = 0; col < n; col++) {
                for (int row = 0; row < ROWS; row++) {
                    data[row][col] = reader.nextInt();
                }
            }
            return data;
        }

        /** Determines the answer according to the original algorithm. */
        private int findAnswer(int[][] matrix, int n) {
            Set<Integer> presentDigits = computePresentDigits(matrix);

            for (int candidate = 1; candidate <= MAX_ITER; candidate++) {
                if (!isCandidateValid(candidate, presentDigits, matrix, n)) {
                    return candidate - 1;   // the first failing candidate – 1
                }
            }
            return MAX_ITER;                // never failed within the loop
        }

        /** Collects every digit (0‑9) that appears anywhere in the matrix. */
        private Set<Integer> computePresentDigits(int[][] matrix) {
            Set<Integer> digits = new HashSet<>();
            for (int[] row : matrix) {
                for (int value : row) {
                    for (char c : Integer.toString(value).toCharArray()) {
                        try {
                            digits.add(c - '0');
                        } catch (NumberFormatException ignored) {
                            // Non‑digit characters cannot appear here, but keep it safe.
                        }
                    }
                }
            }
            return digits;
        }

        /** Checks whether the candidate number satisfies all constraints. */
        private boolean isCandidateValid(int candidate,
                                          Set<Integer> presentDigits,
                                          int[][] matrix,
                                          int n) {
            String s = String.valueOf(candidate);
            int length = s.length();

            // Flags that indicate whether each digit of the candidate was found.
            boolean[] digitFound = new boolean[length];
            // For each column we count how many of the candidate's digits match.
            int[] columnMatchCount = new int[n];

            for (int pos = 0; pos < length; pos++) {
                int digit = s.charAt(pos) - '0';
                boolean foundInMatrix = false;

                // Scan every column – a match in any column increments the counter.
                for (int col = 0; col < n; col++) {
                    if (matrixHasDigit(matrix, digit, col)) {
                        columnMatchCount[col]++;   // record a match in this column
                        foundInMatrix = true;
                    }
                }
                digitFound[pos] = foundInMatrix;
            }

            // All digits of the candidate must be present somewhere in the matrix.
            boolean allDigitsPresent = Arrays.stream(digitFound).allTrue();

            // The number of columns that have at least one match must be >= length.
            long columnsWithMatches = Arrays.stream(columnMatchCount)
                                          .filter(c -> c > 0)
                                          .count();

            return allDigitsPresent && columnsWithMatches >= length;
        }

        /** Returns true if the supplied digit appears in the given column
         *  (across any of the six rows). */
        private boolean matrixHasDigit(int[][] matrix, int digit, int column) {
            for (int row = 0; row < ROWS; row++) {
                if (matrix[row][column] == digit) {
                    return true;
                }
            }
            return false;
        }
    }

    /** --------------------------------------------------------------
     *  Very small wrapper around {@link PrintWriter} that can be closed.
     *  --------------------------------------------------------------
     */
    static class OutputWriter {
        private final PrintWriter writer;

        OutputWriter(OutputStream out) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        void print(int value) {
            writer.print(value);
        }

        void close() {
            writer.close();
        }
    }

    /** --------------------------------------------------------------
     *  Fast scanner based on {@link InputStream}.  It reads bytes in
     *  chunks and converts them into integers without the overhead of
     *  {@link Scanner}.
     *  --------------------------------------------------------------
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int bytesRead = 0;
        private int curPos = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (curPos >= bytesRead) {
                bytesRead = stream.read(buffer);
                curPos = 0;
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[curPos++];
        }

        /** Reads the next integer (supports negative numbers). */
        int nextInt() {
            int c = skipNonDigit();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return value * sign;
        }

        /** Skips characters that are not digits. */
        private int skipNonDigit() {
            int c;
            while ((c = readByte()) != -1 && !isDigit(c)) {}
            return c;
        }

        private boolean isDigit(int c) {
            return c >= '0' && c <= '9';
        }

        /** Closes the underlying stream. */
        void close() throws IOException {
            stream.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the original program.
 *
 * The refactor focuses on readability, maintainability and separation of concerns:
 * <ul>
 *   <li>Descriptive class and method names.</li>
 *   <li>Extraction of reusable helper methods.</li>
 *   <li>Use of collections and constants instead of raw arrays where appropriate.</li>
 *   <li>Removal of unused code and magic numbers.</li>
 * </ul>
 */
public class Solution {

    /** Upper bound for the search space (exclusive). */
    private static final int MAX_VISITED = 100_000;

    private final BufferedReader reader;
    private final PrintWriter writer;
    private StringTokenizer tokenizer;

    /** Constructor – creates the solver and starts the solving process. */
    public Solution() throws IOException {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
        this.writer = new PrintWriter(System.out);
        solve();
        writer.close();
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        new Solution();
    }

    /** Main solving routine. */
    private void solve() throws IOException {
        int n = readInt();                              // number of rows
        List<int[]> rows = new ArrayList<>(n);          // store each row of six digits

        for (int i = 0; i < n; i++) {
            rows.add(readSixInts());
        }

        BooleanArray visited = new BooleanArray(MAX_VISITED);
        visited.set(0, true);                           // 0 is always considered reachable

        switch (n) {
            case 1 -> markDigits(rows.get(0), visited);
            case 2 -> markAllPairs(rows.get(0), rows.get(1), visited);
            default -> markAllTriples(
                    rows.get(0),
                    rows.get(1),
                    rows.get(2),
                    visited);
        }

        int firstMissing = findFirstMissing(visited);
        writer.println(firstMissing - 1);
    }

    /** Reads exactly six integers from the input tokenizer. */
    private int[] readSixInts() throws IOException {
        int[] arr = new int[6];
        for (int i = 0; i < 6; i++) {
            arr[i] = readInt();
        }
        return arr;
    }

    /** Marks all single digits from a row as visited. */
    private void markDigits(int[] row, BooleanArray visited) {
        for (int digit : row) {
            visited.set(digit, true);
        }
    }

    /** Marks numbers formed from two rows (single digits and concatenations). */
    private void markAllPairs(int[] a, int[] b, BooleanArray visited) {
        for (int x : a) {
            for (int y : b) {
                visited.set(x, true);
                visited.set(y, true);
                visited.set(concatenate(x, y), true);
                visited.set(concatenate(y, x), true);
            }
        }
    }

    /** Marks numbers formed from three rows (up to three‑digit concatenations and pairs). */
    private void markAllTriples(int[] a, int[] b, int[] c, BooleanArray visited) {
        for (int x : a) {
            for (int y : b) {
                for (int z : c) {
                    // three‑digit combinations
                    visited.set(concatenate(x, y, z), true);
                    visited.set(concatenate(x, z, y), true);
                    visited.set(concatenate(y, x, z), true);
                    visited.set(concatenate(y, z, x), true);
                    visited.set(concatenate(z, x, y), true);
                    visited.set(concatenate(z, y, x), true);

                    // two‑digit combinations
                    visited.set(concatenate(x, y), true);
                    visited.set(concatenate(y, x), true);
                    visited.set(concatenaFreee(x, z), true);
                    visited.set(concatenate(z, x), true);
                    visited.set(concatenate(y, z), true);
                    visited.set(concatenate(z, y), true);

                    // single digits
                    visited.set(x, true);
                    visited.set(y, true);
                    visited.set(z, true);
                }
            }
        }
    }

    /** Concatenates two decimal digits into a number (e.g., 3 and 5 -> 35). */
    private static int concatenate(int d1, int d2) {
        return d1 * 10 + d2;
    }

    /** Concatenates three decimal digits into a number (e.g., 1,2,3 -> 123). */
    private static int concatenate(int d1, int d2, int d3) {
        return d1 * 100 + d2 * 10 + d3;
    }

    /** Concatenates two digits (used inside the triple loop for readability). */
    private static int concatenaFreee(int d1, int d2) {
        return concatenate(d1, d2);
    }

    /** Finds the smallest positive integer that has not been marked as visited. */
    private static int findFirstMissing(BooleanArray visited) {
        for (int i = 1; i < MAX_VISITED; i++) {
            if (!visited.get(i)) {
                return i;
            }
        }
        return MAX_VISITED;
    }

    /**
     * Simple wrapper around a primitive {@code boolean[]} that provides
     * expressive {@code set} and {@code get} methods.
     */
    private static final class BooleanArray {
        private final boolean[] data;

        BooleanArray(int size) {
            this.data = new boolean[size];
        }

        void set(int index, boolean value) {
            data[index] = value;
        }

        boolean get(int index) {
            return data[index];
        }
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner input = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        int n = input.nextInt();
        int[][] sets = new int[n][6];

        // Read input data
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                sets[i][j] = input.nextInt();
            }
        }

        // Generate all valid permutations of set indices
        List<List<Integer>> permutations = generateAllPermutations(n);

        // Collect all possible numbers formed by permutations
        Set<Integer> numberSet = new HashSet<>();
        for (List<Integer> permutation : permutations) {
            generateNumbers(permutation, 0, sets, new StringBuilder(), numberSet);
        }

        // Find smallest positive integer not in the set
        int missing = 1;
        while (numberSet.contains(missing)) {
            missing++;
        }
        System.out.println(missing);
    }

    private static List<List<Integer>> generateAllPermutations(int n) {
        List<Integer> indices = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            indices.add(i);
        }
        return generatePermutations(indices, 0, new ArrayList<>());
    }

    private static List<List<Integer>> generatePermutations(List<Integer> indices, int pos, List<Integer> current) {
        List<List<Integer>> result = new ArrayList<>();
        if (pos == indices.size()) {
            result.add(new ArrayList<>(current));
            return result;
        }

        for (int i = 0; i < indices.size(); i++) {
            if (!current.contains(indices.get(i))) {
                current.add(indices.get(i));
                result.addAll(generatePermutations(indices, pos + 1, current));
                current.remove(current.size() - 1);
            }
        }
        return result;
    }

    private static void generateNumbers(List<Integer> permutation, int pos, int[][] sets, StringBuilder current, Set<Integer> result) {
        if (pos == permutation.size()) {
            try {
                result.add(Integer.parseInt(current.toString()));
            } catch (NumberFormatException e) {
                // Handle empty string case (shouldn't occur)
            }
            return;
        }

        int setIndex = permutation.get(pos);
        for (int num : sets[setIndex]) {
            int startLength = current.length();
            current.append(num);
            generateNumbers(permutation, pos + 1, sets, current, result);
            current.setLength(startLength); // Backtrack
        }
    }
}

package com.example;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

/**
 * Reads a collection of digit‑sets and determines the largest integer
 * (0 … 1000) that can be formed by assigning each of its digits to a distinct set.
 *
 * The original implementation was functional but hard to follow.
 * The refactor separates concerns, uses expressive names, removes magic numbers,
 * and adds comments for future maintenance.
 */
public class TaskB {

    /** Upper bound used by the original algorithm (inclusive). */
    private static final int MAX_CANDIDATE = 999;

    /** Maximum number of digit‑sets that can be processed. */
    private static final int MAX_SETS = 100;   // safe upper bound; not a hard limit

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();                     // number of sets
            List<Set<Integer>> digitSets = readDigitSets(scanner, n);

            int answer = largestValidNumber(digitSets);
            System.out.println(answer);
        }
    }

    /** Reads `n` lines, each containing six integers, and stores them as sets of digits. */
    private static List<Set<Integer>> readDigitSets(Scanner scanner, int n) {
        List<Set<Integer>> sets = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            Set<Integer> set = new HashSet<>();
            for (int j = 0; j < 6; j++) {
                set.add(scanner.nextInt());
            }
            sets.add(set);
        }
        return sets;
    }

    /**
     * Finds the greatest integer (in the range 0 … 1000) that can be mapped
     * to the supplied digit‑sets respecting the problem constraints.
     *
     * @return the largest successful candidate, or {@code MAX_CANDIDATE + 1}
     *         when *all* numbers up to {@code MAX_CANDIDATE} succeed.
     */
    private static int largestValidNumber(List<Set<Integer>> digitSets) {
        int candidate = 1;          // start checking from 1
        int lastAccepted = 0;       // will hold the last number that passed

        while (candidate <= MAX_CANDIDATE) {
            if (!canAssignDigits(candidate, digitSets)) {
                break;              // first failure – stop the search
            }
            lastAccepted = candidate;
            candidate++;
        }

        // If we never broke out of the loop, every number up to MAX_CANDIDATE succeeded.
        // The original program would output 1000 in that case, so we mimic that behaviour.
        return (candidate > MAX_CANDIDATE) ? MAX_CANDIDATE + 1 : lastAccepted;
    }

    /**
     * Determines whether the decimal representation of {@code number}
     * can be mapped bijectively onto the supplied digit‑sets.
     *
     * @param number the integer to test
     * @param digitSets collection of allowed digits for each set
     * @return {@code true} if a valid assignment exists
     */
    private static boolean canAssignDigits(int number, List<Set<Integer>> digitSets) {
        // Convert the number into a list of its digits (most‑significant first)
        List<Integer> digits = digitList(number);
        boolean[] used = new boolean[digitSets.size()];
        Arrays.fill(used, true);               // initially all sets are “available”

        return backtrack(number, digits, digitSets, used, 0);
    }

    /**
     * Recursive back‑tracking routine that tries to assign each digit of {@code digits}
     * to an unused set that contains the digit.
     *
     * @return {@code true} if a complete assignment exists
     */
    private static boolean backtrack(int originalNumber,
                                     List<Integer> digits,
                                     List<Set<Integer>> digitSets,
                                     boolean[] used,
                                     int digitIndex) {
        // All digits have been placed successfully
        if (digitIndex == digits.size()) {
            return true;
        }

        int currentDigit = digits.get(digitIndex);
        int remainingDigits = digits.size() - digitIndex - 1;

        // Try every set that still has the required digit and has not been used yet
        for (int setIdx = 0; setIdx < digitSets.size(); setIdx++) {
            if (!used[setIdx] || !digitSets.get(setIdx).contains(currentDigit)) {
                continue;
            }

            // Mark this set as used for the next level
            used[setIdx] = false;

            // Proceed to the next digit
            if (backtrack(originalNumber, digits, digitSets, used, digitIndex + 1)) {
                // Restore the state before returning
                used[setIdx] = true;
                return true;
            }

            // Backtrack
            used[setIdx] = true;
        }
        return false;   // no suitable set found for the current digit
    }

    /** Returns the decimal digits of {@code value} in most‑significant‑first order. */
    private static List<Integer> digitList(int value) {
        // Special case: 0 → [0]
        if (value == 0) {
            return Collections.singletonList(0);
        }

        List<Integer> digits = new ArrayList<>();
        while (value > 0) {
            digits.add(value % 10);
            value /= 10;
        }
        Collections.reverse(digits);
        return digits;
    }
}

