/**
 * Handles all the logic for reading input and determining the required number.
 */
final class NumberFinder {

    /** No meaningful magic numbers – keep only those that are truly required. */
    private static final int COLLECTED_PER_LINE = 6;

    private NumberFinder() { /* utility class – no instances needed */ }

    /**
     * Reads the input, evaluates the conditions and prints the smallest positive
     * integer {@code x} that does NOT satisfy any of them.
     */
    void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();

        // three sets that collect the integers read from the input
        Set<Integer>[] sets = new Set[3];
        for (int i = 0; i < sets.length; i++) {
            sets[i] = new TreeSet<>();
        }

        // read 6 numbers for each of the three lines
        for (int line = 0; line < n; line++) {
            for (int i = 0; i < COLLECTED_PER_LINE; i++) {
                int value = in.nextInt();
                sets[line].add(value);
            }
        }

        int candidate = 1;
        while (isCoveredByAnySet(candidate, sets) ||
               hasTwoDigitPairCovered(candidate, sets) ||
               hasThreeDigitConditionMet(candidate, sets)) {
            candidate++;
        }
        out.print(candidate - 1);
    }

    /** Checks whether {@code x} appears in any of the three supplied sets. */
    private static boolean isCoveredByAnySet(int x, Set<Integer>... sets) {
        for (Set<Integer> set : sets) {
            if (set.contains(x)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Returns {@code true} if {@code x} can be expressed as a two‑digit number
     * whose tens digit belongs to one set and units digit to another set,
     * considering both orders.
     */
    private static boolean hasTwoDigitPairCovered(int x, Set<Integer>... sets) {
        int tens = x / 10;
        int units = x % 10;
        // tens must be a single digit (0‑9) to be meaningful in a set lookup
        if (tens < 0 || tens > 9 || units < 0 || units > 9) {
            return false;
        }
        // two possible orientations of the pair
        return (sets[0].contains(tens) && sets[1].contains(units)) ||
               (sets[1].contains(tens) && sets[0].contains(units)) ||
               (sets[0].contains(tens) && sets[2].contains(units)) ||
               (sets[2].contains(tens) && sets[0].contains(units)) ||
               (sets[1].contains(tens) && sets[2].contains(units)) ||
               (sets[2].contains(tens) && sets[1].contains(units));
    }

    /**
     * Checks the more complex third‑digit condition.
     * It verifies whether any of the three digits (hundreds, tens, units)
     * belongs to a distinct set and the remaining two‑digit part satisfies
     * the pair‑cover rule described in {@link #hasTwoDigitPairCovered}.
     */
    private static boolean hasThreeDigitConditionMet(int x, Set<Integer>... sets) {
        int hundreds = x / 100;
        int remainder = x % 100;

        // explore each possible set that could contain the hundreds digit
        for (int i = 0; i < 3; i++) {
            if (!sets[i].contains(hundreds)) {
                continue;
            }
            int a = (i + 1) % 3;
            int b = (i + 2) % 3;
            if (hasTwoDigitPairCovered(remainder, sets[a], sets[b])) {
                return true;
            }
            // also try the swapped orientation of the two remaining sets
            if (hasTwoDigitPairCovered(remainder, sets[b], sets[a])) {
                return true;
            }
        }
        return false;
    }
}

/**
 * Simple buffered input reader with token support.
 */
class InputReader {
    private final BufferedReader bufferedReader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        this.bufferedReader = new BufferedReader(new InputStreamReader(stream, 32768));
    }

    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(bufferedReader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }

    long nextLong() {
        return Long.parseLong(next());
    }

    int[] nextArrayInt(int count) {
        int[] arr = new int[count];
        for (int i = 0; i < count; i++) {
            arr[i] = nextInt();
        }
        return arr;
    }

    long[] nextArrayLong(int count) {
        long[] arr = new long[count];
        for (int i = 0; i < count; i++) {
            arr[i] = nextLong();
        }
        return arr;
    }
}

import java.io.*;
import java.util.HashSet;
import java.util.Set;

/**
 * Reads a matrix of digits and determines how many consecutive positive
 * integers (starting from 1) can be formed by concatenating exactly one digit
 * from each row. The result is printed to standard output.
 *
 * The implementation is deliberately split into small, well‑named methods,
 * uses a clean scanner utility, and avoids tangled recursion with obscure
 * bit‑tricks from the original source.
 */
public class Main {

    /** Simple fast scanner that works with any {@link InputStream}. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next non‑whitespace code point. */
        private int read() {
            if (pointer >= length) {
                // fill buffer
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        /** Checks whether the current character is whitespace. */
        private static boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Consumes characters until a whitespace is encountered. */
        private String nextNonWhitespace() {
            int c;
            do {
                c = read();
            } while (isSpace(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = read();
            } while (!isSpace(c));
            return sb.toString();
        }

        int nextInt() {
            return Integer.parseInt(nextNonWhitespace());
        }

        long[] readIntArray(int size) {
            long[] result = new long[size];
            for (int i = 0; i < size; i++) {
                result[i] = readLong();
            }
            return result;
        }

        long readLong() {
            return Long.parseLong(nextNonWhitespace());
        }
    }

    /**
     * Recursively builds all numbers that can be obtained by picking exactly
     * one digit from each row of the matrix.
     *
     * @param rows      the digit matrix
     * @param rowIdx    current row being processed
     * @param current   StringBuilder holding the partially built number
     * @param resultSet set that collects the completed numbers
     */
    private static void backtrack(int[][] rows, int rowIdx, StringBuilder current, Set<Long> resultSet) {
        if (rowIdx == rows.length) {
            // All rows have been processed – store the formed number
            resultSet.add(Long.parseLong(current.toString()));
            return;
        }

        for (int digit : rows[rowIdx]) {
            current.append(digit);
            backtrack(rows, rowIdx + 1, current, resultSet);
            // Undo the change for the next iteration
            current.deleteCharAt(current.length() - 1);
        }
    }

    /** Determines how many consecutive positive integers (starting from 1) are present. */
    private static int countInitialConsecutive(Set<Long> numbers) {
        int count = 0;
        while (numbers.contains((long) (count + 1))) {
            count++;
        }
        return count;
    }

    /** Entry point of the program. */
    public static void main(String[] args) {
        // Try‑with‑resources guarantees the scanner is closed promptly.
        try (FastScanner scanner = new FastScanner(System.in)) {
            int n = scanner.nextInt();                     // number of rows
            int[][] rows = new int[n][];                     // digit matrix

            // Each row contains exactly six digits.
            for (int i = 0; i < n; i++) {
                rows[i] = scanner.readIntArray(6);
            }

            Set<Long> generatedNumbers = new HashSet<>();
            backtrack(rows, 0, new StringBuilder(), generatedNumbers);

            int answer = countInitialConsecutive(generatedNumbers);
            System.out.println(answer);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

public class DigitRepresentable {
    private static int[][] digits;

    public static void main(String[] args) throws IOException {
        readInput();
        int result = findLargestRepresentableNumber();
        System.out.println(result);
    }

    private static void readInput() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(reader.readLine().trim());
        digits = new int[n][6];

        for (int i = 0; i < n; i++) {
            String[] parts = reader.readLine().split("\\s+");
            for (int j = 0; j < 6; j++) {
                digits[i][j] = Integer.parseInt(parts[j].trim());
            }
        }
    }

    private static int findLargestRepresentableNumber() {
        int result = 0;
        for (int num = 1; num <= 999; num++) {
            if (isUnrepresentable(num)) {
                break;
            }
            result = num;
        }
        return result;
    }

    private static boolean isUnrepresentable(int number) {
        String numberStr = String.valueOf(number);
        if (numberStr.length() > digits.length) {
            return true;
        }

        int totalSubsets = 1 << digits.length;
        for (int subsetMask = 1; subsetMask < totalSubsets; subsetMask++) {
            if (Integer.bitCount(subsetMask) != numberStr.length()) {
                continue;
            }

            int[] selectedIndices = new int[numberStr.length()];
            int indexCount = 0;
            for (int i = 0; i < digits.length; i++) {
                if ((subsetMask & (1 << i)) != 0) {
                    selectedIndices[indexCount++] = i;
                }
            }

            char[] permutation = new char[selectedIndices.length];
            for (int i = 0; i < selectedIndices.length; i++) {
                permutation[i] = (char) ('0' + selectedIndices[i]);
            }

            Arrays.sort(permutation);
            if (isPermutationValid(permutation, numberStr)) {
                return false;
            }

            while (nextPermutation(permutation)) {
                if (isPermutationValid(permutation, numberStr)) {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean isPermutationValid(char[] permutation, String numberStr) {
        for (int i = 0; i < permutation.length; i++) {
            int digitIndex = permutation[i] - '0';
            int requiredDigit = numberStr.charAt(i) - '0';
            if (!containsDigit(digitIndex, requiredDigit)) {
                return false;
            }
        }
        return true;
    }

    private static boolean containsDigit(int digitIndex, int digit) {
        for (int j = 0; j < 6; j++) {
            if (digits[digitIndex][j] == digit) {
                return true;
            }
        }
        return false;
    }

    private static boolean nextPermutation(char[] array) {
        int i = array.length - 2;
        while (i >= 0 && array[i] >= array[i + 1]) {
            i--;
        }
        if (i < 0) {
            return false;
        }

        int j = array.length - 1;
        while (array[j] <= array[i]) {
            j--;
        }
        swap(array, i, j);
        reverse(array, i + 1, array.length - 1);
        return true;
    }

    private static void swap(char[] array, int i, int j) {
        char temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    private static void reverse(char[] array, int start, int end) {
        while (start < end) {
            swap(array, start++, end--);
        }
    }
}

import java.io.PrintStream;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Determines the smallest positive integer that **cannot** be shown on any
 * combination of the given dice. Each die is represented by six face values.
 *
 * <p>For example, with two dice that have faces {1,2,3,4,5,6} and {1,2,3,4,5,6},
 * the program finds that the number 7 cannot be formed and therefore prints
 * {@code 6}.</p>
 */
public final class Main887B {

    /** Upper bound for the search – numbers up to 99 are sufficient for this problem. */
    private static final int MAX_VALUE = 100;

    private Main887B() {
        // Utility class – prevent instantiation.
    }

    /** Entry point – delegates to {@code run} for easier testing. */
    public static void main(String[] args) {
        run(System.in, System.out);
    }

    /**
     * Core execution routine that reads input, processes it and writes the answer.
     *
     * @param in  input stream (normally {@code System.in})
     * @param out output stream (normally {@code System.out})
     */
    public static void run(InputStream in, PrintStream out) {
        try (Scanner scanner = new Scanner(in)) {
            // -----------------------------------------------------------------
            // 1. Parse the input
            // -----------------------------------------------------------------
            int numberOfDice = scanner.nextInt();
            List<int[]> dice = new ArrayList<>(numberOfDice);
            for (int i = 0; i < numberOfDice; i++) {
                int[] faces = new int[6];
                for (int j = 0; j < 6; j++) {
                    faces[j] = scanner.nextInt();
                }
                dice.add(faces);
            }

            // -----------------------------------------------------------------
            // 2. Find the smallest missing number
            // -----------------------------------------------------------------
            int answer = findSmallestMissing(dice);
            out.print(answer);
        }
    }

    /**
     * Scans upward from {@code 1} until it discovers a number that cannot be
     * generated with the supplied dice. Returns that number; if every integer up
     * to {@value #MAX_VALUE} can be generated, the method returns {@code 0}.
     *
     * @param dice list of dice, each represented by an array of six face values
     * @return smallest positive integer that cannot be displayed, or {@code 0}
     *         if all numbers up to {@value #MAX_VALUE} are representable.
     */
    private static int findSmallestMissing(List<int[]> dice) {
        // Test numbers from 1 up to 99 (two‑digit numbers are enough for the problem)
        for (int candidate = 1; candidate < MAX_VALUE; candidate++) {
            if (!canBeGenerated(candidate, dice)) {
                return candidate - 1;
            }
        }

        // Edge case when only a single digit can ever be produced (e.g., only one die)
        if (dice.size() == 1) {
            return 0;
        }
        return 0;
    }

    /**
     * Determines whether a given integer can be represented using the supplied dice.
     * Each digit of the number must be matched with a distinct die.
     *
     * @param number the integer to test
     * @param dice   list of available dice
     * @return {@code true} if the number can be generated, otherwise {@code false}
     */
    private static boolean canBeGenerated(int number, List<int[]> dice) {
        String digits = String.valueOf(number);
        int requiredDice = digits.length();

        // Not enough dice to assign a distinct die to each digit.
        if (dice.size() < requiredDice) {
            return false;
        }

        // Try every permutation of dice assignments.
        return hasMatchingPermutation(dice, digits);
    }

    /**
     * Checks whether any permutation of the given dice can be assigned to the
     * positions of {@code pattern} such that each digit appears on the corresponding
     * die’s face set.
     *
     * @param dice   list of dice
     * @param pattern string representing the digits of the candidate number
     * @return {@code true} if a matching permutation exists, otherwise {@code false}
     */
    private static boolean hasMatchingPermutation(List<int[]> dice, String pattern) {
        boolean[] used = new boolean[dice.size()];
        return backtrack(dice, pattern, 0, used);
    }

    /**
     * Recursive back‑tracking helper that attempts to assign a die to each digit
     * position while respecting the “used” constraint.
     *
     * @param dice      list of dice
     * @param pattern   digits to match
     * @param index     current digit index being processed
     * @param used      flags indicating which dice have already been assigned
     * @return {@code true} if a full assignment can be found, otherwise {@code false}
     */
    private static boolean backtrack(List<int[]> dice, String pattern, int index, boolean[] used) {
        if (index == pattern.length()) {
            return true; // all digits matched
        }

        char neededDigit = pattern.charAt(index);
        int digit = Character.digit(neededDigit, 10);

        for (int i = 0; i < dice.size(); i++) {
            if (!used[i] && containsDigit(dice.get(i), digit)) {
                used[i] = true;
                if (backtrack(dice, pattern, index + 1, used)) {
                    return true;
                }
                used[i] = false; // backtrack
            }
        }
        return false;
    }

    /**
     * Checks whether a given die contains a specific face value.
     *
     * @param die    the die face values
     * @param value  the digit to look for
     * @return {@code true} if the value is present on the die
     */
    private static boolean containsDigit(int[] die, int value) {
        for (int face : die) {
            if (face == value) {
                return true;
            }
        }
        return false;
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * Refactored solution for problem R444b.
 * The program reads a variable number of integer arrays,
 * builds a collection of derived numbers, sorts them,
 * looks for the first gap larger than 1 and prints the
 * appropriate result according to the original specification.
 */
public class R444b {

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        solve(fs, out);
        out.close();
    }

    /** Orchestrates the whole solving process. */
    private static void solve(FastScanner fs, PrintWriter out) {
        int n = fs.nextInt();                     // selector for the case
        List<Integer> numbers = collectNumbers(n, fs);
        int result = computeResult(numbers);
        out.println(result);
    }

    /** Populates a list with numbers according to the selected case (1, 2 or 3+). */
    private static List<Integer> collectNumbers(int n, FastScanner fs) {
        List<Integer> list = new ArrayList<>();

        switch (n) {
            case 1 -> {
                int[] a = fs.nextIntArray(6);
                list.addAll(Arrays.asList(a));          // directly add the six values
            }
            case 2 -> {
                int[] a = fs.nextIntArray(6);
                int[] b = fs.nextIntArray(6);
                for (int i = 0; i < 6; i++) {
                    list.add(a[i]);
                    list.add(b[i]);
                    for (int j = 0; j < 6; j++) {
                        list.add(a[i] + 10 * b[j]);       // two‑digit combos
                        list.add(b[i] + 10 * a[j]);
                    }
                }
            }
            default -> {                                 // case 3 and any higher value
                int[] a = fs.nextIntArray(6);
                int[] b = fs.nextIntArray(6);
                int[] c = fs.nextIntArray(6);
                for (int i = 0; i < 6; i++) {
                    list.add(a[i]);
                    list.add(b[i]);
                    list.add(c[i]);

                    for (int j = 0; j < 6; j++) {
                        // three‑digit combos with different positions
                        list.add(a[i] + 10 * b[j]);
                        list.add(b[i] + 10 * a[j]);
                        list.add(a[i] + 10 * c[j]);
                        list.add(c[i] + 10 * a[j]);
                        list.add(b[i] + 10 * c[j]);
                        list.add(c[i] + 10 * b[j]);

                        for (int k = 0; k < 6; k++) {
                            list.add(a[i] + 10 * b[j] + 100 * c[k]);
                            list.add(a[i] + 10 * b[k] + 100 * c[j]);
                            list.add(a[j] + 10 * b[i] + 100 * c[k]);
                            list.add(a[j] + 10 * b[k] + 100 * c[i]);
                            list.add(a[k] + 10 * b[i] + 100 * c[j]);
                            list.add(a[k] + 10 * b[j] + 100 * c[i]);
                        }
                    }
                }
            }
        }
        return list;
    }

    /** Determines the value that must be printed according to the original algorithm. */
    private static int computeResult(List<Integer> values) {
        Collections.sort(values);
        int chosen = -1;
        for (int i = 0; i < values.size() - 1; i++) {
            if (values.get(i + 1) - values.get(i) > 1) {
                chosen = values.get(i);
                break;
            }
            chosen = values.get(i + 1);
        }

        boolean firstIsAcceptable = values.get(0) == 0 || values.get(0) == 1;
        return (chosen == -1 || !firstIsAcceptable) ? 0 : chosen;
    }

    /**
     * Fast scanner that mirrors the functionality of the original {@code InputReader}
     * but with a smaller, more focused API.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int cursor = 0;
        private int length = -1;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (length <= cursor) {
                cursor = 0;
                try {
                    length = stream.read(buffer);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[cursor++];
        }

        private int peek() {
            return readByte();
        }

        /** Reads the next integer token from the input. */
        int nextInt() {
            int c;
            do {
                c = peek();
            } while (isSpace(c));

            boolean negative = false;
            if (c == '-') {
                negative = true;
                readByte();
                c = peek();
            }

            int value = 0;
            while (!isSpace(c) && c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                readByte();
                c = peek();
            }
            return negative ? -value : value;
        }

        /** Reads a fixed amount of integers into an array. */
        int[] nextIntArray(int size) {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        /** Utility to skip whitespace characters. */
        private static boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

