/**
 * Core logic for the “cubes” problem.
 *
 * <p>
 * The program determines the largest positive integer that can be displayed using a
 * collection of cubes, where each cube can show exactly one of the digits printed on
 * its faces.  Cubes that are not needed are represented by '.' placeholders.
 * </p>
 */
class TaskD {

    /**
     * Computes the maximal integer that can be formed with the given cubes.
     *
     * @param presence matrix where {@code presence[i][d] == 1} iff digit {@code d}
     *                 is printed on cube {@code i}
     * @return the largest representable number
     */
    public int maxNumber(int[][] presence) {
        int cubeCount = presence.length;

        // Try numbers starting from 1 until the first one that cannot be formed.
        int candidate = 1;
        while (true) {
            if (!canForm(candidate, cubeCount, presence)) {
                break;
            }
            candidate++;
        }
        return candidate - 1;
    }

    /**
     * Checks whether a specific integer can be assembled from the supplied cubes.
     *
     * @param number      the integer to test
     * @param cubeCount   total number of available cubes
     * @param presence    presence matrix
     * @return {@code true} if the number can be represented, {@code false} otherwise
     */
    private boolean canForm(int number, int cubeCount, int[][] presence) {
        // Pad the number on the left with '.' until it reaches {@code cubeCount} characters.
        String padded = String.format("%" + cubeCount + "s", number).replace(' ', '.');
        if (padded.length() > cubeCount) {
            // Number needs more digits than we have cubes – impossible.
            return false;
        }
        // Start a back‑tracking search for a valid digit‑to‑cube assignment.
        return assignDigits(padded, 0, new boolean[cubeCount], presence);
    }

    /**
     * Recursive digit‑to‑cube assignment.
     *
     * @param target   string representation of the number (may contain '.' placeholders)
     * @param pos      current position in {@code target}
     * @param used     flags indicating which cubes are already used
     * @param presence presence matrix
     * @return {@code true} if a valid assignment exists
     */
    private boolean assignDigits(String target, int pos, boolean[] used, int[][] presence) {
        if (pos == target.length()) {
            // All positions have been successfully matched.
            return true;
        }

        char required = target.charAt(pos);
        if (required == '.') {
            // Wildcard position – try any unused cube.
            for (int i = 0; i < used.length; i++) {
                if (!used[i]) {
                    used[i] = true;
                    if (assignDigits(target, pos + 1, used, presence)) {
                        return true;
                    }
                    used[i] = false;
                }
            }
            return false;
        }

        int digit = required - '0';
        // Try to place the digit on an unused cube that actually carries it.
        for (int cubeIdx = 0; cubeIdx < used.length; cubeIdx++) {
            if (!used[cubeIdx] && carriesDigit(digit, cubeIdx, presence)) {
                used[cubeIdx] = true;
                if (assignDigits(target, pos + 1, used, presence)) {
                    return true;
                }
                used[cubeIdx] = false;
            }
        }
        return false; // No cube can satisfy this digit.
    }

    /**
     * Determines whether a given cube contains the specified digit.
     *
     * @param digit   digit to look for (0‑9)
     * @param cubeIdx index of the cube in {@code presence}
     * @param presence presence matrix
     * @return {@code true} if the cube has the digit printed on it
     */
    private boolean carriesDigit(int digit, int cubeIdx, int[][] presence) {
        // In the input format each cube entry stores 1 in the column that matches a digit.
        return presence[cubeIdx][digit] == 1;
    }

    /**
     * Reads one test case, solves it, and prints the result.
     *
     * @param testNumber dummy test number (kept for compatibility with the original template)
     * @param scanner    input source
     * @param out        output writer
     */
    public void solve(int testNumber, Scanner scanner, PrintWriter out) {
        int cubeCount = scanner.nextInt();                 // number of cubes
        int[][] cubes = new int[cubeCount][10];            // presence matrix

        // Each cube contributes up to six faces; read the digits printed on them.
        for (int i = 0; i < cubeCount; i++) {
            for (int j = 0; j < 6; j++) {
                int digit = scanner.nextInt();
                if (digit >= 0 && digit <= 9) {
                    cubes[i][digit] = 1;
                }
            }
        }

        out.println(maxNumber(cubes));
    }
}

/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads a collection of dice‑like cubes, each exposing six integer faces.
 * It then determines the largest consecutive integer (starting from 1) that can be
 * assembled by picking one face from each cube at most once and concatenating the
 * resulting digits. The search stops at {@value #SEARCH_LIMIT} (the original code
 * stopped at 1000).
 * </p>
 */
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Entry point of the application.
 */
public class B {

    /** Upper bound for the search – the original code stopped at 1000. */
    private static final int SEARCH_LIMIT = 1000;

    public static void main(String[] args) {
        InputReader reader = new InputReader();
        int cubeCount = reader.nextInt();
        Cube[] cubes = new Cube[cubeCount];
        for (int i = 0; i < cubeCount; i++) {
            cubes[i] = new Cube(reader);
        }

        int lastConstructible = 0;
        for (int i = 1; i <= SEARCH_LIMIT; i++) {
            if (!canConstruct(i, cubes)) {
                lastConstructible = i - 1;
                break;
            }
        }
        System.out.println(lastConstructible);
    }

    /**
     * Checks whether the decimal representation of {@code number} can be built
     * using the faces of the supplied {@code cubes}. Each cube may be used at
     * most once.
     *
     * @param number the positive integer to test
     * @param cubes  array of {@link Cube} instances
     * @return {@code true} if the number can be assembled, {@code false} otherwise
     */
    private static boolean canConstruct(int number, Cube[] cubes) {
        String digits = Integer.toString(number);
        return canBuild(digits, cubes, 0);
    }

    /**
     * Recursive back‑tracking routine that tries to match the remaining digits
     * using an unused cube.
     *
     * @param remaining   the part of the digit string that still needs to be placed
     * @param cubes       all available cubes
     * @param usedMask    bitmask indicating which cubes have already been consumed
     * @return {@code true} if the remaining digits can be satisfied, {@code false} otherwise
     */
    private static boolean canBuild(String remaining, Cube[] cubes, int usedMask) {
        if (remaining.isEmpty()) {
            return true; // all digits placed successfully
        }

        char neededChar = remaining.charAt(0);
        int neededDigit = neededChar - '0';

        for (int idx = 0; idx < cubes.length; idx++) {
            if ((usedMask & (1 << idx)) != 0) {
                continue; // cube already used
            }
            Cube cube = cubes[idx];
            for (int face : cube.faces) {
                if (face == neededDigit) {
                    if (canBuild(
                            remaining.substring(1), // consume matched digit
                            cubes,
                            usedMask | (1 << idx))) { // mark cube as used
                        return true;
                    }
                }
            }
        }
        return false; // no combination works
    }

    /** Simple container for a cube's six faces. */
    private static final class Cube {
        /** The six integer face values of the cube. */
        final int[] faces;

        Cube(InputReader reader) {
            faces = new int[6];
            for (int i = 0; i < faces.length; i++) {
                faces[i] = reader.nextInt();
            }
        }
    }

    /** Minimal input parser – reads whitespace‑separated tokens from standard input. */
    private static final class InputReader {
        private final BufferedReader br;

        InputReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token from {@code System.in}. */
        String next() {
            try {
                while (true) {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    StringTokenizer tokenizer = new StringTokenizer(line);
                    if (tokenizer.hasMoreTokens()) {
                        return tokenizer.nextToken();
                    }
                }
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Convenience wrapper returning the next token as an {@code int}. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Refactored solution for the original "round_444_b" problem.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Encapsulated input handling in a dedicated {@link InputReader} class.</li>
 *   <li>Removed all static mutable global fields – everything is passed explicitly.</li>
 *   <li>Extracted helper methods with expressive names.</li>
 *   <li>Used meaningful variable names and added comments.</li>
 *   <li>Eliminated unused imports and unnecessary classes.</li>
 * </ul>
 */
public final class Round444B {

    /** Simple tokenizer that reads tokens from a {@link BufferedReader}. */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(BufferedReader br) {
            this.br = br;
        }

        /** Returns the next token or reads a new line if the current one is exhausted. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Convenience wrapper for {@code nextInt()}. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }
    }

    /** Entry point – delegates all work to {@link #solve(InputReader, PrintWriter)}. */
    public static void main(String[] args) throws Exception {
        try (InputReader reader = new InputReader(new BufferedReader(new java.io.InputStreamReader(
                System.in)));
             PrintWriter out = new PrintWriter(System.out)) {

            solve(reader, out);
        }
    }

    /** Core solving routine. */
    private static void solve(InputReader sc, PrintWriter out) {
        final int n = sc.nextInt();

        // allowedDigits[group][digit] == true  ⇔  digit is permitted for that group
        final boolean[][] allowedDigits = new boolean[n][10];
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < 6; ++j) {
                int digit = sc.nextInt();
                allowedDigits[i][digit] = true;
            }
        }

        // Upper bound = 10^n (the original program used a loop that multiplied by 10 n times)
        final int upperBound = (int) Math.pow(10, n);

        // Permutation of group indices (0 … n‑1)
        final List<Integer> order = new ArrayList<>();
        for (int i = 0; i < n; ++i) {
            order.add(i);
        }

        int best = 0;
        for (int candidate = 1; candidate < upperBound; ++candidate) {
            boolean found = false;
            do {
                if (canRepresent(candidate, order, allowedDigits)) {
                    found = true;
                    break;
                }
            } while (nextPermutation(order));

            if (found) {
                best = candidate;          // remember the largest successful candidate
            } else {
                // No permutation works for this candidate → all larger numbers will also fail
                break;
            }
        }

        out.println(best);
    }

    /**
     * Checks whether {@code number} can be represented by some ordering of groups.
     *
     * @param number      the candidate number to test
     * @param order       a permutation of group indices (0 … n‑1)
     * @param allowedDigits allowed digit‑to‑group mapping
     * @return {@code true} if all digits of {@code number} can be matched in order
     */
    private static boolean canRepresent(int number, List<Integer> order, boolean[][] allowedDigits) {
        char[] digits = Integer.toString(number).toCharArray();

        int digitIdx = 0;   // current digit position in the number
        int groupIdx = 0;   // current position inside the permutation

        while (digitIdx < digits.length && groupIdx < order.size()) {
            int digit = digits[digitIdx] - '0';
            if (allowedDigits[order.get(groupIdx)][digit]) {
                ++digitIdx;   // successfully matched this digit, move to the next one
            }
            ++groupIdx;       // always advance through the permutation
        }

        // If we consumed every digit, the number can be represented with this ordering
        return digitIdx == digits.length;
    }

    /**
     * Generates the next lexicographic permutation of {@code list}.
     *
     * @param list the mutable list that currently holds a permutation
     * @return {@code true} if the list was transformed into its next permutation,
     *         {@code false} if the current permutation was the last one
     */
    private static boolean nextPermutation(List<Integer> list) {
        int i = list.size() - 2;
        while (i >= 0 && list.get(i) >= list.get(i + 1)) {
            i--;
        }
        if (i < 0) {
            return false; // no next permutation
        }

        int j = list.size() - 1;
        while (list.get(j) <= list.get(i)) {
            j--;
        }
        swap(list, i, j);

        int left = i + 1;
        int right = list.size() - 1;
        while (left < right) {
            swap(list, left++, right--);
        }
        return true;
    }

    private static void swap(List<Integer> list, int i, int j) {
        int tmp = list.get(i);
        list.set(i, list.get(j));
        list.set(j, tmp);
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original competitive‑programming solution.
 *
 * <p>This rewrite focuses on readability, maintainability and proper encapsulation.
 * It keeps the original algorithmic behaviour while replacing the tangled
 * collection of static fields and custom input classes with well‑structured
 * helper methods and clear naming.
 */
public class Main {

    /* ----------  Constants  ---------- */
    private static final long MOD_PRIME = 998_244_353L;   // used in power()
    private static final long MOD       = 1_000_000_007L; // used in bit‑tree ops (kept for compatibility)

    /* ----------  Input handling  ---------- */
    /**
     * Fast scanner based on {@link BufferedReader}.  It hides the repetitive
     * {@code StringTokenizer} logic from the rest of the code.
     */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        /** Returns the next token from the input stream. */
        private String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Reads an {@code int}. */
        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        /** Reads a {@code long}. */
        long nextLong() {
            return Long.parseLong(nextToken());
        }

        /** Reads a {@code double}. */
        double nextDouble() {
            return Double.parseDouble(nextToken());
        }

        /** Reads a full line (may be {@code null} at EOF). */
        String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /* ----------  Utility classes  ---------- */

    /** Simple pair used only for sorting (if needed). */
    private static final class Pair implements Comparable<Pair> {
        final int first;
        final int second;

        Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public int compareTo(Pair o) {
            return Integer.compare(this.first, o.first);
        }
    }

    /** Helper for modular exponentiation used by the original program. */
    private static long modPow(long base, long exp, long modulus) {
        long result = 1L;
        base %= modulus;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % modulus;
            }
            base = (base * base) % modulus;
            exp >>= 1;
        }
        return result;
    }

    /* ----------  Core algorithm  ---------- */

    /**
     * Determines the smallest non‑negative integer that satisfies the problem’s
     * constraints.
     *
     * @param setA numbers that belong to the “a” set
     * @param setB numbers that belong to the “b” set
     * @param setC numbers that belong to the “c” set
     * @return the value that must be printed
     */
    private static int findAnswer(Set<Integer> setA, Set<Integer> setB, Set<Integer> setC) {
        int candidate = 0;
        while (true) {
            candidate++;

            // 1️⃣  Skip candidates that appear directly in any of the three digit‑position sets
            if (setA.contains(candidate) || setB.contains(candidate) || setC.contains(candidate)) {
                continue;
            }

            // 2️⃣  Skip candidates whose last digit belongs to one set and the tens digit to another
            if (setA.contains(candidate % 10) &&
                    (setB.contains((candidate / 10) % 10) || setC.contains((candidate / 10) % 10))) {
                continue;
            }
            if (setB.contains(candidate % 10) &&
                    (setA.contains((candidate / 10) % 10) || setC.contains((candidate / 10) % 10))) {
                continue;
            }
            if (setC.contains(candidate % 10) &&
                    (setB.contains((candidate / 10) % 10) || setA.contains((candidate / 10) % 10))) {
                continue;
            }

            // 3️⃣  Skip candidates that realise any of the six permutations of three distinct digits
            int d1 = candidate % 10;
            int d2 = (candidate / 10) % 10;
            int d3 = candidate / 100;
            if (setA.contains(d1) && setB.contains(d2) && setC.contains(d3)) continue;
            if (setA.contains(d1) && setB.contains(d3) && setC.contains(d2)) continue;
            if (setA.contains(d2) && setB.contains(d1) && setC.contains(d3)) continue;
            if (setA.contains(d2) && setB.contains(d3) && setC.contains(d1)) continue;
            if (setA.contains(d3) && setB.contains(d1) && setC.contains(d2)) continue;
            if (setA.contains(d3) && setB.contains(d2) && setC.contains(d1)) continue;

            // If we reach this point the candidate fulfills all constraints
            return candidate - 1;
        }
    }

    /* ----------  Program entry point  ---------- */
    public static void main(String[] args) throws IOException {
        // Use a single, shared scanner for the whole program
        FastScanner scanner = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));

        // ---- read the three logical groups of integers ----
        Set<Integer> setA = new HashSet<>();
        for (int i = 0; i < 6; i++) {
            setA.add(scanner.nextInt());          // exactly six numbers are expected here
        }

        Set<Integer> setB = new HashSet<>();
        // Up to six more integers belong to setB; stop when we run out of tokens
        while (setB.size() < 6 && scanner.hasNextInt()) {
            setB.add(scanner.nextInt());
        }

        Set<Integer> setC = new HashSet<>();
        while (setC.size() < 6 && scanner.hasNextInt()) {
            setC.add(scanner.nextInt());
        }

        // ---- compute and output the answer ----
        int answer = findAnswer(setA, setB, setC);
        System.out.println(answer);
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a matrix of integers, finds the smallest positive integer that cannot be
 * represented by picking one column index for each digit of the number such that
 * the digit exists in the selected row, and prints that number.
 */
public class Main {

    /** Reads the whole input and returns the filled matrix. */
    private static int[][] readMatrix(BufferedReader br) throws IOException {
        int n = Integer.parseInt(br.readLine().trim());
        int[][] matrix = new int[n][6];

        for (int i = 0; i < n; i++) {
            StringTokenizer tokenizer = new StringTokenizer(br.readLine());
            for (int j = 0; j < 6; j++) {
                matrix[i][j] = Integer.parseInt(tokenizer.nextToken());
            }
            Arrays.sort(matrix[i]);               // rows are sorted for binary search
        }
        return matrix;
    }

    /**
     * Determines whether the given number (as a string) can be formed from the matrix.
     *
     * @param digits the decimal representation of the candidate number
     * @param matrix sorted rows of six integers each
     * @return true if the number can be formed, false otherwise
     */
    private static boolean canForm(String digits, int[][] matrix) {
        // For each digit, store the rows where this digit appears.
        @SuppressWarnings("unchecked")
        List<Integer>[] digitRows = new List[digits.length()];
        for (int i = 0; i < digitRows.length; i++) {
            digitRows[i] = new ArrayList<>();
        }

        for (int pos = 0; pos < digits.length(); pos++) {
            int digit = Character.digit(digits.charAt(pos), 10);
            for (int row = 0; row < matrix.length; row++) {
                if (Arrays.binarySearch(matrix[row], digit) >= 0) {
                    digitRows[pos].add(row);
                }
            }
            // A missing digit makes the whole number impossible.
            if (digitRows[pos].isEmpty()) {
                return false;
            }
        }

        // Trivial cases.
        if (digits.length() == 1) {
            return true;
        }
        if (digits.length() == 2) {
            List<Integer> first = digitRows[0];
            List<Integer> second = digitRows[1];

            // Exactly one candidate in each column and they differ → valid.
            if (first.size() == 1 && second.size() == 1 && !first.get(0).equals(second.get(0))) {
                return true;
            }
            // If either column has more than one candidate, we can choose distinct rows.
            if (first.size() > 1 || second.size() > 1) {
                return true;
            }
            return false;
        }

        // For longer numbers collect all distinct row indices that can be used.
        Set<Integer> usedRows = new HashSet<>();
        for (List<Integer> rows : digitRows) {
            usedRows.addAll(rows);
        }
        // If we can cover at least n distinct rows, we can assign a unique row per digit.
        return usedRows.size() >= matrix.length;
    }

    /**
     * Finds the smallest positive integer that cannot be formed from the matrix.
     *
     * @param matrix sorted rows of six integers each
     * @return the smallest missing positive integer
     */
    private static int findSmallestMissingNumber(int[][] matrix) {
        int candidate = 1;
        while (true) {
            if (!canForm(Integer.toString(candidate), matrix)) {
                return candidate;
            }
            candidate++;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws Exception {
        // BufferedReader + try‑with‑resources guarantees proper closing.
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            int[][] matrix = readMatrix(reader);
            int answer = findSmallestMissingNumber(matrix);
            System.out.println(answer);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Finds the smallest positive integer that cannot be written using the faces
 * of a given set of cubes. Each cube shows six digits; a digit of the target
 * number must be placed on a distinct cube, and the order of the digits does
 * not matter (the algorithm checks digits from least‑significant to most‑
 * significant). The program reads the input, builds the cube data structure
 * and then searches for the first missing number.
 */
public final class ProblemB {

    /** Represents a single cube – six faces, each holding an integer digit. */
    private static final class Cube {
        /** All distinct digits that appear on the cube (kept in a {@link Set} for O(1) lookup). */
        private final Set<Integer> faces;

        Cube(Set<Integer> faces) {
            this.faces = faces;
        }

        /** Returns {@code true} if the supplied digit occurs on this cube. */
        boolean contains(int digit) {
            return faces.contains(digit);
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            int cubeCount = Integer.parseInt(reader.readLine().trim());

            // Parse the six digits of each cube and store them in a list of {@link Cube}s.
            List<Cube> cubes = new ArrayList<>(cubeCount);
            for (int i = 0; i < cubeCount; i++) {
                String[] tokens = reader.readLine().split("\\s+");
                Set<Integer> faces = new HashSet<>();
                for (int j = 0; j < 6; j++) {
                    faces.add(Integer.parseInt(tokens[j]));
                }
                cubes.add(new Cube(faces));
            }

            // Starting from 1, look for the first positive integer that cannot be formed.
            int candidate = 1;
            while (canFormNumber(candidate, cubes, new boolean[cubeCount])) {
                candidate++;
            }
            System.out.println(candidate - 1);
        }
    }

    /**
     * Determines whether the supplied number can be assembled from the given cubes.
     * <p>
     * The method works recursively, consuming the least‑significant digit first.
     * It guarantees that each digit uses a distinct cube (tracked via the
     * {@code used} boolean array).
     *
     * @param number      the integer we are trying to represent
     * @param cubes       list of all available cubes
     * @param used        flags indicating which cubes have already been used
     * @return {@code true} if the number can be built, otherwise {@code false}
     */
    private static boolean canFormNumber(int number, List<Cube> cubes, boolean[] used) {
        if (number == 0) {
            return true; // all digits have been satisfied
        }

        int currentDigit = number % 10;          // least‑significant digit
        int remaining      = number / 10;        // the rest of the number

        for (int idx = 0; idx < cubes.size(); idx++) {
            if (!used[idx] && cubes.get(idx).contains(currentDigit)) {
                used[idx] = true;                // mark cube as used
                boolean canBuildRest = canFormNumber(remaining, cubes, used);
                used[idx] = false;               // backtrack
                if (canBuildRest) {
                    return true;
                }
            }
        }
        return false; // no suitable cube found for the current digit
    }
}

/**
 * Reads numbers from standard input and determines the largest consecutive
 * integer (starting from 1) whose decimal digits can be assigned to distinct
 * input lines containing those digits.
 *
 * <p>This refactor improves readability, reduces the coupling of responsibilities,
 * and makes the intent of each method explicit.</p>
 */
public class Main {

    /** Upper bound for the search – 1000 is enough for the problem constraints. */
    private static final int MAX_CANDIDATE = 1000;

    public static void main(String[] args) {
        // Using try‑with‑resources guarantees that the streams are closed even on
        // exceptions.  A single Scanner and PrintWriter are shared with the solver.
        try (var scanner = new Scanner(System.in);
             var printer = new PrintWriter(System.out)) {

            solve(1, scanner, printer);
        }
    }

    /**
     * Runs one test case. The solver is kept separate from {@code main} to make
     * unit‑testing straightforward.
     *
     * @param testNumber the (unused) test case identifier – kept only to match the
     *                   original API
     * @param scanner    source of input data
     * @param printer    destination for output
     */
    static void solve(int testNumber, Scanner scanner, PrintWriter printer) {
        int rowCount = scanner.nextInt();                 // n
        boolean[][] rowHasDigit = buildRowHasDigitMatrix(rowCount, scanner);

        int answer = findLargestConsecutiveNumber(rowHasDigit);
        printer.println(answer);
    }

    /**
     * Constructs a matrix where {@code rowHasDigit[row][d]} is {@code true}
     * iff the digit {@code d} appears somewhere in the integers read for that
     * row.
     */
    private static boolean[][] buildRowHasDigitMatrix(int rows, Scanner scanner) {
        boolean[][] matrix = new boolean[rows][10];       // digits 0‑9

        for (int row = 0; row < rows; ++row) {
            for (int slot = 0; slot < 6; ++slot) {        // each row has up to 6 numbers
                int value = scanner.nextInt();
                matrix[row][value] = true;
            }
        }
        return matrix;
    }

    /**
     * Returns the greatest integer {@code k} such that every number from
     * {@code 1} up to and including {@code k} can be represented by assigning
     * each of its decimal digits to a distinct row that contains that digit.
     *
     * @param rowHasDigit matrix describing which digits each row contains
     * @return the largest consecutive number satisfying the condition
     */
    private static int findLargestConsecutiveNumber(boolean[][] rowHasDigit) {
        boolean[] usedRow = new boolean[rowHasDigit.length]; // tracks which rows are taken

        for (int candidate = 1; candidate < MAX_CANDIDATE; ++candidate) {
            List<Integer> digits = digitsOf(candidate);
            if (canAssignDigits(digits, rowHasDigit, usedRow)) {
                // Current candidate works – keep going
                continue;
            }
            // The first failure breaks the streak
            return candidate - 1;
        }
        // All candidates up to MAX_CANDIDATE‑1 succeeded
        return MAX_CANDIDATE - 1;
    }

    /**
     * Extracts the decimal digits of {@code number} into a list (least‑significant
     * digit first). The order does not matter for the assignment logic.
     */
    private static List<Integer> digitsOf(int number) {
        List<Integer> digits = new ArrayList<>();
        while (number > 0) {
            digits.add(number % 10);
            number /= 10;
        }
        // Guard against the number 0 (the problem never queries 0, but for
        // completeness we could handle it separately)
        if (digits.isEmpty()) {
            digits.add(0);
        }
        return digits;
    }

    /**
     * Attempts to assign each digit in {@code digits} to a distinct row that
     * contains that digit.  The method uses simple back‑tracking.
     *
     * @param digits        digits to be placed
     * @param rowMatrix     rows × digit presence information
     * @param usedRows      array indicating which rows are already taken
     * @return {@code true} if a valid assignment exists
     */
    private static boolean canAssignDigits(List<Integer> digits,
                                           boolean[][] rowMatrix,
                                           boolean[] usedRows) {
        // Reset usage flags for each candidate number
        Arrays.fill(usedRows, false);
        return backtrack(digits, 0, rowMatrix, usedRows);
    }

    /**
     * Recursive back‑tracking routine that tries to place the {@code startIdx}
     *‑th digit of the current candidate into any unused row that supports it.
     *
     * @param digits      the digit list of the current number
     * @param startIdx    index of the digit we are trying to place now
     * @param rowMatrix   digit‑presence matrix
     * @param usedRows    rows that have already been assigned
     * @return {@code true} if a complete placement is possible
     */
    private static boolean backtrack(List<Integer> digits,
                                     int startIdx,
                                     boolean[][] rowMatrix,
                                     boolean[] usedRows) {
        if (startIdx == digits.size()) {
            return true; // all digits placed
        }

        int digit = digits.get(startIdx);
        for (int row = 0; row < rowMatrix.length; ++row) {
            if (!usedRows[row] && rowMatrix[row][digit]) {
                usedRows[row] = true;
                if (backtrack(digits, startIdx + 1, rowMatrix, usedRows)) {
                    return true;
                }
                usedRows[row] = false; // backtrack
            }
        }
        return false; // no row can accommodate this digit
    }
}

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

/**
 * Finds the smallest positive integer that cannot be formed from the given input.
 *
 * <p>
 * The original program handled three specific cases (n = 1, 2, 3) with a lot of
 * duplicated code.  The refactored version abstracts the common logic:
 * <ul>
 *   <li>reading all integers,
 *   <li>building a set of digits for each logical “line”,
 *   <li>checking whether a candidate number {@code k} can be represented,
 *   <li>searching for the smallest missing {@code k}.
 * </ul>
 * This makes the code easier to understand, maintain and extend.
 */
public class CF {

    /** Separator used when reading a whole line of integers (kept for compatibility). */
    private static final Scanner SCANNER = new Scanner(System.in);

    /** Number of integers that belong to a single logical line. */
    private static final int INTEGERS_PER_LINE = 6;

    public static void main(String[] args) {
        int n = Integer.parseInt(readLine().trim());
        int[] rawData = readIntegers(INTEGERS_PER_LINE * n);
        int answer = smallestMissingPositive(rawData, n);
        System.out.println(answer);
    }

    /** Reads exactly {@code count} integers from {@link #SCANNER}. */
    private static int[] readIntegers(int count) {
        int[] data = new int[count];
        for (int i = 0; i < count; i++) {
            data[i] = Integer.parseInt(SCANNER.next());
        }
        return data;
    }

    /** Reads a whole line as a single integer (the original program used this pattern). */
    private static String readLine() {
        return SCANNER.nextLine();
    }

    /**
     * Determines the smallest positive integer {@code k} that cannot be represented
     * by the input.  The representation rules are identical to the original program:
     * <ul>
     *   <li>If {@code k} < 10, it must appear in at least one line.
     *   <li>If {@code k} ≥ 10, its tens and units digits must appear in two *different*
     *       lines (order does not matter).
     * </ul>
     *
     * @param rawData all integers read from input
     * @param n       number of logical lines (each line consists of 6 integers)
     * @return the smallest missing integer
     */
    private static int smallestMissingPositive(int[] rawData, int n) {
        // Convert each block of 6 integers into a set of characters representing its digits.
        List<Set<Character>> lines = buildLines(rawData, n);

        // Starting from 1, look for the first integer that cannot be represented.
        int k = 1;
        while (isRepresentable(k, lines)) {
            k++;
        }
        return k - 1;          // the last representable integer
    }

    /**
     * Builds a list where each element is the set of distinct digit characters
     * appearing in a logical line of the input.
     */
    private static List<Set<Character>> buildLines(int[] data, int n) {
        List<Set<Character>> lines = new ArrayList<>(n);
        for (int lineIdx = 0; lineIdx < n; lineIdx++) {
            Set<Character> digits = new HashSet<>();
            int base = lineIdx * INTEGERS_PER_LINE;
            for (int i = 0; i < INTEGERS_PER_LINE; i++) {
                int number = data[base + i];
                // Convert each digit of the number into a character and add to the set.
                for (char c : Integer.toString(number).toCharArray()) {
                    digits.add(c);
                }
            }
            lines.add(digits);
        }
        return lines;
    }

    /**
     * Checks whether the integer {@code k} can be represented according to the rules:
     * <ul>
     *   <li>Single‑digit numbers need to be present in any line.
     *   <li>Two‑digit numbers need the tens and units digits to be present in two
     *       distinct lines (order does not matter).
     * </ul>
     *
     * @param k      candidate integer
     * @param lines  collection of digit sets, one per logical line
     * @return {@code true} if {@code k} can be represented, {@code false} otherwise
     */
    private static boolean isRepresentable(int k, List<Set<Character>> lines) {
        if (k < 10) {
            // Single‑digit case – simply check if any line contains the digit.
            char digit = Character.forDigit(k, 10);
            return lines.stream().anyMatch(set -> set.contains(digit));
        }

        // Two‑digit case – we need two *different* lines that together contain the
        // tens and units digits.
        char tens = Character.forDigit(k / 10, 10);
        char units = Character.forDigit(k % 10, 10);

        // Brute‑force search over all ordered pairs of distinct lines.
        outer:
        for (int i = 0; i < lines.size(); i++) {
            for (int j = 0; j < lines.size(); j++) {
                if (i == j) {
                    continue;
                }
                if (lines.get(i).contains(tens) && lines.get(j).contains(units)) {
                    // Found a pair of lines that realize the two‑digit number.
                    continue outer;
                }
            }
            // If we fall out of the inner loops without a match, the number is not representable.
            return false;
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 * Reads digit‑sets from standard input and prints the largest consecutive
 * integer that can be formed by concatenating one digit from each set.
 */
public class Main {

    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee stream closure
        try (InputStream in = System.in;
             PrintWriter out = new PrintWriter(System.out, true)) {

            InputNumbersReader reader = new InputNumbersReader(in);
            NumberGenerator generator = new NumberGenerator();

            // The problem limits the check up to 999
            int limit = 999;
            int answer = generator.findLargestPrefix(reader.readAllDigitSets(), limit);

            out.println(answer);
        }
    }

    /**
     * Reads the number of digit‑sets and then each of the six integers per set.
     * Returns a list where each element represents one set of possible digits.
     */
    private static class InputNumbersReader implements Closeable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputNumbersReader(InputStream source) {
            this.reader = new BufferedReader(new InputStreamReader(source), 65536 / 2);
            this.tokenizer = null;
        }

        /** Reads all digit‑sets from the input stream. */
        List<Set<Integer>> readAllDigitSets() throws IOException {
            int n = Integer.parseInt(nextToken());            // number of sets
            List<Set<Integer>> sets = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                Set<Integer> digits = new TreeSet<>();
                for (int j = 0; j < 6; j++) {
                    digits.add(Integer.parseInt(nextToken()));
                }
                sets.add(digits);
            }
            return sets;
        }

        /** Provides tokenised input, reading a new line when needed. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new EOFException();
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    /**
     * Core logic that builds all possible numbers from the supplied digit‑sets
     * and determines the largest consecutive prefix (1 … answer) that can be formed.
     */
    private static class NumberGenerator {

        /** Finds the largest integer m such that every number 1 … m exists in the generated set,
         *  stopping at {@code maxCheck}. */
        int findLargestPrefix(List<Set<Integer>> digitSets, int maxCheck) {
            Set<Integer> allNumbers = generateAllNumbers(digitSets);
            int prefix = 0;
            for (int i = 1; i <= maxCheck; i++) {
                if (allNumbers.contains(i)) {
                    prefix = i;
                } else {
                    break;
                }
            }
            return prefix;
        }

        /** Constructs every number that can be obtained by picking exactly one digit
         *  from each set and concatenating them in order. */
        private Set<Integer> generateAllNumbers(List<Set<Integer>> digitSets) {
            Set<Integer> result = new HashSet<>();

            // Start with an empty prefix and iteratively extend it.
            List<Integer> current = Collections.singletonList(0);
            for (Set<Integer> digitSet : digitSets) {
                List<Integer> nextLevel = new ArrayList<>();
                for (int prefix : current) {
                    for (int digit : digitSet) {
                        int newNumber = (prefix == 0) ? digit : prefix * 10 + digit;
                        nextLevel.add(newNumber);
                    }
                }
                current = nextLevel;
            }

            // Populate the result set with the final numbers.
            result.addAll(current);
            return result;
        }
    }
}

import java.io.BufferedInputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Fast scanner that reads integers from an underlying {@link InputStream}.
 */
final class FastScanner {
    private final byte[] buffer = new byte[4 * 1024];
    private int bufferIndex;
    private int bufferLength;
    private final BufferedInputStream stream;

    FastScanner(final java.io.InputStream input) {
        this.stream = new BufferedInputStream(input);
    }

    /** Reads the next byte, returning -1 on EOF. */
    private int readByte() {
        if (bufferIndex >= bufferLength) {
            bufferIndex = 0;
            try {
                bufferLength = stream.read(buffer);
            } catch (final java.io.IOException e) {
                throw new RuntimeException(e);
            }
            if (bufferLength <= 0) {
                return -1;
            }
        }
        return buffer[bufferIndex++];
    }

    /** Returns true for whitespace characters. */
    private static boolean isWhiteSpace(final int b) {
        return b == ' ' || b == '\n' || b == '\r' || b == '\t' || b == -1;
    }

    /** Skips leading whitespace. */
    private int skipWhitespace(int b) {
        while (!isWhiteSpace(b)) {
            b = readByte();
        }
        return b;
    }

    /** Reads next signed integer. */
    int scanInt() {
        int c = skipWhitespace(readByte());
        final int sign = (c == '-') ? -1 : 1;
        if (c == '-' || c == '+') {
            c = readByte();
        }
        int value = 0;
        while (!isWhiteSpace(c) && c != -1) {
            if (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
            }
            c = readByte();
        }
        return sign * value;
    }
}

/**
 * Simple wrapper that stores the colours on a single cube.
 * The colours are stored as a {@link Set} of digits (0‑9).
 */
final class CubeFaces {
    private final Set<Integer> faces = new HashSet<>();

    void addFace(final int digit) {
        faces.add(digit);
    }

    /** Returns {@code true} if the cube contains the given digit. */
    boolean contains(final int digit) {
        return faces.contains(digit);
    }
}

/**
 * Core solver for the “Masha’s cubes” problem.
 * It reads the cube data, then finds the largest natural number that can be
 * represented using each cube at most once.
 */
final class CubeSolver {
    private final List<CubeFaces> cubes;
    private static final int MAX_SEARCH_MULTIPLIER = 10; // used to bound enumeration

    CubeSolver(final int cubeCount) {
        cubes = new ArrayList<>(cubeCount);
        for (int i = 0; i < cubeCount; i++) {
            cubes.add(new CubeFaces());
        }
    }

    /** Reads the six faces of each cube from the supplied scanner. */
    void readFrom(final FastScanner scanner, final int cubeCount) {
        for (int i = 0; i < cubeCount; i++) {
            for (int j = 0; j < 6; j++) {
                cubes.get(i).addFace(scanner.scanInt());
            }
        }
    }

    /** Returns true if the given number can be formed using distinct cubes. */
    private boolean canRepresent(final int number) {
        final List<Integer> digits = collectDigits(number);
        if (digits.size() > cubes.size()) {
            return false; // not enough cubes
        }
        final boolean[] used = new boolean[cubes.size()];
        return assignDigits(0, used, digits);
    }

    /** Recursive back‑tracking assignment of cubes to digits. */
    private boolean assignDigits(final int position,
                                 final boolean[] used,
                                 final List<Integer> digits) {
        if (position == digits.size()) {
            return true; // all digits placed
        }
        final int neededDigit = digits.get(position);
        for (int cubeIdx = 0; cubeIdx < cubes.size(); cubeIdx++) {
            if (!used[cubeIdx] && cubes.get(cubeIdx).contains(neededDigit)) {
                used[cubeIdx] = true;
                if (assignDigits(position + 1, used, digits)) {
                    return true;
                }
                used[cubeIdx] = false;
            }
        }
        return false;
    }

    /** Extracts digits of a positive integer, least‑significant first. */
    private List<Integer> collectDigits(final int value) {
        final List<Integer> digits = new ArrayList<>();
        while (value > 0) {
            digits.add(value % 10);
            value /= 10;
        }
        return digits;
    }

    /** Finds the answer according to the original specification. */
    int solve() {
        final int maxSearch = (int) Math.pow(10, cubes.size());
        int i = 1;
        while (i <= maxSearch) {
            if (!canRepresent(i)) {
                break;
            }
            i++;
        }
        // The problem expects the last representable number.
        return i - 1;
    }
}

/** Entry point – reads input, runs the solver and prints the result. */
public final class Main {
    public static void main(final String[] args) {
        final FastScanner scanner = new FastScanner(System.in);
        FinalAnswerHolder holder = readProblemSize(scanner);
        if (holder == null) {
            // No input – nothing to do.
            return;
        }

        CubeSolver solver = new CubeSolver(holder.cubeCount);
        solver.readFrom(scanner, holder.cubeCount);
        final int answer = solver.solve();
        new PrintWriter(System.out, true).println(answer);
    }

    /** Helper that extracts the number of cubes from the first token of input. */
    private static FinalAnswerHolder readProblemSize(final FastScanner scanner) {
        // The first integer is the count of cubes.
        final int n = scanner.scanInt();
        if (n <= 0) {
            return null;
        }
        return new FinalAnswerHolder(n);
    }

    /** Simple DTO to keep the extracted size together with potential future data. */
    private static final class FinalAnswerHolder {
        final int cubeCount;
        FinalAnswerHolder(final int cubeCount) {
            this.cubeCount = cubeCount;
        }
    }
}

import java.util.*;
import java.util.stream.Collectors;

/**
 * Reads a grid with a start cell 'S' and an end cell 'E' and a command string.
 * For every permutation of the four movement directions (l/r/u/d) it checks
 * whether following the commands (0‑3) using that permutation leads to 'E'.
 * The program prints the number of successful permutations.
 */
public class Solution {

    /** The four possible movement directions. */
    private static final char[] ALL_DIRECTIONS = {'l', 'r', 'u', 'd'};

    /** Directions mapped to row/column deltas. */
    private enum Direction {
        l(-1, 0),   // left  → column -1
        r( 1, 0),   // right → column +1
        u( 0,-1),   // up    → row -1
        d( 0, 1);   // down  → row +1

        private final int deltaRow;
        private final int deltaCol;

        Direction(int deltaRow, int deltaCol) {
            this.deltaRow = deltaRow;
            this.deltaCol = deltaCol;
        }

        int getDeltaRow() { return deltaRow; }
        int getDeltaCol() { return deltaCol; }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        /* ----- read dimensions and grid ----- */
        int rows = scanner.nextInt();          // n
        int cols = scanner.nextInt();          // m
        String[] grid = new String[rows];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next();
        }
        String commandString = scanner.next(); // the command string

        /* ----- locate start (S) and end (E) cells ----- */
        int startRow = -1, startCol = -1;
        int endRow = -1, endCol = -1;
        outer:
        for (int r = 0; r < rows; r++) {
            String line = grid[r];
            for (int c = 0; c < line.length(); c++) {
                char ch = line.charAt(c);
                if (ch == 'S') {
                    startRow = r;
                    startCol = c;
                } else if (ch == 'E') {
                    endRow = r;
                    endCol = c;
                }
            }
            if (startRow != -1 && endRow != -1) {
                break;
            }
        }
        if (startRow == -1 || endRow == -1) {
            System.out.println(0);
            return;
        }

        /* ----- evaluate every permutation of directions ----- */
        int successfulPermutations = 0;
        List<char[]> permutations = generatePermutations(ALL_DIRECTIONS);

        for (char[] perm : permutations) {
            if (canReachEnd(grid, rows, cols,
                    startRow, startCol,
                    commandString,
                    perm)) {
                successfulPermutations++;
            }
        }

        System.out.println(successfulPermutations);
    }

    /**
     * Generates all permutations of the given array.
     *
     * @param array the array to permute
     * @return list of all possible permutations
     */
    private static List<char[]> generatePermutations(char[] array) {
        List<char[]> result = new ArrayList<>();
        permute(array, 0, result);
        return result;
    }

    /** Recursive helper that builds permutations. */
    private static void permute(char[] array, int start, List<char[]> result) {
        if (start == array.length) {
            result.add(array.clone());
            return;
        }
        for (int i = start; i < array.length; i++) {
            swap(array, start, i);
            permute(array, start + 1, result);
            swap(array, start, i); // backtrack
        }
    }

    private static void swap(char[] array, int i, int j) {
        char tmp = array[i];
        array[i] = array[j];
        array[j] = tmp;
    }

    /**
     * Simulates movement according to {@code commandString} using the supplied
     * direction permutation. Returns {@code true} if the path reaches 'E'
     * before hitting a wall ('#') or leaving the board.
     *
     * @param grid        the grid representation
     * @param rows        number of rows
     * @param cols        number of columns
     * @param startRow    row index of 'S'
     * @param startCol    column index of 'S'
     * @param commands    string of commands '0'‑'3'
     * @param directionPerm permutation that maps command indices to directions
     * @return {@code true} if 'E' is reached during the walk
     */
    private static boolean canReachEnd(String[] grid,
                                       int rows, int cols,
                                       int startRow, int startCol,
                                       String commands,
                                       char[] directionPerm) {
        int curRow = startRow;
        int curCol = startCol;

        /* map command char → direction */
        for (int i = 0; i < commands.length(); i++) {
            char cmd = commands.charAt(i);
            Direction dir = directionFromChar(directionPerm[cmd - '0']);

            curRow += dir.getDeltaRow();
            curCol += dir.getDeltaCol();

            // out of bounds?
            if (curRow < 0 || curRow >= rows || curCol < 0 || curCol >= cols) {
                return false;
            }

            char cell = grid[curRow].charAt(curCol);
            if (cell == '#') {
                return false;
            }

            if (cell == 'E') {
                return true; // reached the target
            }
            // otherwise continue with next command
        }
        return false; // never hit 'E' during the whole command sequence
    }

    /**
     * Translates a direction character ('l','r','u','d') into its {@link Direction}
     * enum value.
     */
    private static Direction directionFromChar(char ch) {
        return switch (ch) {
            case 'l' -> Direction.l;
            case 'r' -> Direction.r;
            case 'u' -> Direction.u;
            case 'd' -> Direction.d;
            default -> throw new IllegalArgumentException("Unknown direction: " + ch);
        };
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 *
 * <p>
 *   This class reads a grid from standard input, finds the start ('S') and end ('E') cells,
 *   and counts how many distinct assignments of the four movement digits {@code 0,1,2,3}
 *   allow traversing from the start to the end while following the instruction string {@code s}.
 *   Each digit maps to a distinct movement direction (down, up, right, left). The program
 *   outputs the total number of valid assignments.
 * </p>
 */
public class GridGame {

    /** Fast scanner utilities (kept from the original implementation). */
    private final InputReader reader = new InputReader();
    private PrintWriter writer = new PrintWriter(System.out, true);

    /** Grid dimensions. */
    private int rows, cols;

    /** 2‑D character grid. */
    private char[][] board;

    /** Position of the start cell. */
    private int startRow, startCol;

    /** Position of the end cell. */
    private int endRow, endCol;

    /** Instruction string. */
    private String instructions;

    /** --------------------------------------------------------------------- */
    /** Core algorithm ------------------------------------------------------ */

    /**
     * Determines whether a given mapping of movement digits to directions can
     * transport the player from the start to the end when following {@code instructions}.
     *
     * @param downDigit   digit that represents moving down one cell
     * @param upDigit     digit that represents moving up one cell
     * @param rightDigit  digit that represents moving right one cell
     * @param leftDigit   digit that represents moving left one cell
     * @return {@code true} if the path ends exactly at the end cell, {@code false} otherwise
     */
    private boolean canReach(int downDigit, int upDigit, int rightDigit, int leftDigit) {
        int r = startRow;
        int c = startCol;

        for (int i = 0; i < instructions.length(); i++) {
            char ch = instructions.charAt(i);
            int digit = ch - '0';

            if (digit == downDigit) {
                r++;
            } else if (digit == upDigit) {
                r--;
            } else if (digit == rightDigit) {
                c++;
            } else if (digit == leftDigit) {
                c--;
            }

            // Step outside the board or hit a blocked cell → path invalid.
            if (!insideBounds(r, c) || board[r][c] == '#') {
                return false;
            }
        }

        // Final position must match the target.
        return r == endRow && c == endCol;
    }

    /** Counts all valid digit permutations that lead from start to end. */
    private int countValidAssignments() {
        int validCount = 0;

        // Permute the four digits (0‑3) and assign each to a distinct movement.
        int[] digits = {0, 1, 2, 3};
        do {
            int down = digits[0];
            int up   = digits[1];
            int right = digits[2];
            int left = digits[3];

            if (canReach(down, up, right, left)) {
                validCount++;
            }
        } while (nextPermutation(digits));

        return validCount;
    }

    /** Generates the next lexicographic permutation of the supplied array. */
    private boolean nextPermutation(int[] array) {
        int i = array.length - 2;
        while (i >= 0 && array[i] >= array[i + 1]) {
            i--;
        }
        if (i < 0) {
            return false;
        }

        int j = array.length - 1;
        while (array[j] <= array[i]) {
            j--;
        }
        swap(array, i, j);
        reverse(array, i + 1, array.length - 1);
        return true;
    }

    private void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    private void reverse(int[] arr, int from, int to) {
        while (from < to) {
            swap(arr, from++, to--);
        }
    }

    /** --------------------------------------------------------------------- */
    /** Input handling ------------------------------------------------------- */

    /**
     * Reads the whole input, builds the board, extracts the start/end positions,
     * reads the instruction string, and prints the answer.
     */
    private void solve() {
        rows = reader.nextInt();
        cols = reader.nextInt();

        board = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = reader.next();
            board[r] = line.toCharArray();
        }

        instructions = reader.next();

        // Locate start ('S') and end ('E') cells.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cell = board[r][c];
                if (cell == 'S') {
                    startRow = r;
                    startCol = c;
                } else if (cell == 'E') {
                    endRow = r;
                    endCol = c;
                }
            }
        }

        int answer = countValidAssignments();
        writer.println(answer);
    }

    /** --------------------------------------------------------------------- */
    /** Utility methods ------------------------------------------------------- */

    /** Checks whether a coordinate lies inside the grid. */
    private boolean insideBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** --------------------------------------------------------------------- */
    /** Fast input reader (copied from the original code for compatibility). */
    /** --------------------------------------------------------------- */
    private static final class InputReader {
        private final byte[] buffer = new byte[1024];
        private int inputLen = 0, inputPtr = 0;

        private int readByte() throws IOException {
            if (inputPtr >= inputLen) {
                inputPtr = 0;
                inputLen = System reads(buffer);
                if (inputLen <= 0) {
                    return -1;
                }
            }
            return buffer[inputPtr++];
        }

        private boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }

        private int skip() {
            int b;
            do {
                b = readByte();
            } while (b != -1 && isSpaceChar(b));
            return b;
        }

        /** Reads next non‑space character. */
        private char nc() {
            return (char) skip();
        }

        /** Reads next token (non‑space characters). */
        private String ns() {
            StringBuilder sb = new StringBuilder();
            int b = skip();
            while (!isSpaceChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        /** Reads next integer. */
        private int ni() {
            int num = 0;
            boolean neg = false;
            int b = skip();
            while ((b < '0' || b > '9') && b != '-') {
                b = skip();
            }
            if (b == '-') {
                neg = true;
                b = readByte();
            }
            while (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
                b = readByte();
            }
            return neg ? -num : num;
        }

        /** Reads next double. */
        private double nd() {
            return Double.parseDouble(ns());
        }
    }

    /** --------------------------------------------------------------------- */
    /** Entry point ----------------------------------------------------------- */
    /** --------------------------------------------------------------- */
    public static void main(String[] args) {
        new GridGame().run();
    }

    private void run() {
        solve();
        writer.flush();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;

/**
 * Reads a grid that contains a start cell 'S' and an end cell 'E',
 * an instruction string consisting of digits 1‑4, and counts how many
 * different permutations of the four movement directions lead from
 * start to end when the instructions are applied in the permuted order.
 */
public class Codeforces {

    /** Movement vectors: left, right, up, down */
    private static final int[] DR = {0, 0, -1, 1};
    private static final int[] DC = {-1, 1, 0, 0};

    /** Input data ---------------------------------------------------------- */
    private char[][] grid;
    private int rows, cols;
    private int startRow, startCol;
    private int endRow, endCol;
    private String instructionSeq;

    /** Result -------------------------------------------------------------- */
    private int successfulPermutations = 0;

    public static void main(String[] args) throws IOException {
        new Codeforces().solve();
    }

    /** Entry point that ties everything together. */
    private void solve() throws IOException {
        readInput();
        generateAllPermutations(this::evaluatePermutation);
        System.out.println(successfulPermutations);
    }

    /** Reads the grid and the instruction string from STDIN. */
    private void readInput() throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // --- grid dimensions -------------------------------------------------
            String[] dims = br.readLine().split("\\s+");
            rows = Integer.parseInt(dims[0]);
            cols = Integer.parseInt(dims[1]);

            // --- read the grid ---------------------------------------------------
            grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                String line = br.readLine();
                grid[r] = line.toCharArray();
                int s = line.indexOf('S');
                int e = line.indexOf('E');
                if (s >= 0) {
                    startRow = r;
                    startCol = s;
                }
                if (e >= 0) {
                    endRow = r;
                    endCol = e;
                }
            }

            // --- instruction sequence --------------------------------------------
            instructionSeq = br.readLine();
        }
    }

    /** Generates every permutation of [0,1,2,3] and validates it. */
    private void generateAllPermutations(Consumer<int[]> permutationConsumer) {
        boolean[] used = new boolean[4];
        List<Integer> current = new ArrayList<>(4);
        buildPermutations(0, used, current, permutationConsumer);
    }

    /** Recursive helper that constructs permutations. */
    private void buildPermutations(int depth,
                                   boolean[] used,
                                   List<Integer> current,
                                   Consumer<int[]> permutationConsumer) {
        if (depth == 4) {
            // Convert the list of indices to an int[] for the consumer
            int[] asArray = current.stream().mapToInt(Integer::intValue).toArray();
            permutationConsumer.accept(asArray);
            return;
        }

        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                current.add(i);
                buildPermutations(depth + 1, used, current, permutationConsumer);
                current.remove(current.size() - 1);
                used[i] = false;
            }
        }
    }

    /** Tests a single permutation of direction indices against the instruction string. */
    private void evaluatePermutation(int[] perm) {
        boolean reached = simulatePath(perm);
        if (reached) {
            successfulPermutations++;
        }
    }

    /** Simulates moving according to the instruction string while using the supplied permutation. */
    private boolean simulatePath(int[] perm) {
        int r = startRow;
        int c = startCol;
        int instrLen = instructionSeq.length();

        for (int pos = 0; pos < instrLen; pos++) {
            char digit = instructionSeq.charAt(pos);
            int directionIndex = digit - '1';               // 0‑based direction id (0..3)
            int dr = DR[perm[directionIndex]];
            int dc = DC[perm[directionIndex]];

            r += dr;
            c += dc;

            // out‑of‑bounds check
            if (r < 0 || r >= rows || c < 0 || c >= cols) {
                return false;
            }

            char cell = grid[r][c];
            if (cell == '#') {
                return false;
            }

            // destination reached exactly at the last instruction?
            if (pos == instrLen - 1 && r == endRow && c == endCol) {
                return true;
            }
        }
        // If we exit the loop without landing on 'E', the path failed.
        return false;
    }
}

/**
 * Maze solver that counts how many distinct permutations of the movement
 * keys {a, d, s, w} can guide the start cell to the exit.
 *
 * The code is deliberately split into small, self‑contained pieces so that
 * each responsibility (input handling, maze representation, permutation
 * generation, navigation test) has its own clearly named method or class.
 */
import java.util.*;

public class Main {

    /** Directions used by the puzzle. */
    private enum Dir {
        LEFT('a'), RIGHT('d'), DOWN('s'), UP('w');

        private final char symbol;

        Dir(char symbol) {
            this.symbol = symbol;
        }

        /** Return the character representation used in the input. */
        char symbol() {
            return symbol;
        }
    }

    /** Small immutable container for a cell coordinate. */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Reads the maze and the move sequence from stdin. */
    private static class InputReader {
        private final Scanner scanner;

        InputReader() {
            this.scanner = new Scanner(System.in);
        }

        /** Reads rows, columns and the maze grid. Returns a 2‑D char array. */
        static char[][] readMaze(Scanner sc) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();
            char[][] maze = new char[rows][];
            Optional<Cell> start = Optional.empty();
            Optional<Cell> end = Optional.empty();

            for (int r = 0; r < rows; r++) {
                String line = sc.next();
                maze[r] = line.toCharArray();
                for (int c = 0; c < cols; c++) {
                    char ch = maze[r][c];
                    if (ch == 'S') {
                        start = Optional.of(new Cell(r, c));
                    } else if (ch == 'E') {
                        end = Optional.of(new Cell(r, c));
                    }
                }
            }

            if (!start.isPresent() || !end.isPresent()) {
                throw new IllegalArgumentException("Maze must contain exactly one 'S' and one 'E'.");
            }

            // store the coordinates for later use (they are package‑private for brevity)
            maze[rows - 1] = null; // temporary hack to keep row index
            maze[start.get().row][start.get().col] = 'S';
            maze[end.get().row][end.get().col] = 'E';
            System.out.println(rows + " " + cols); // not needed any more – kept for compatibility
            return maze;
        }

        /** Reads the numeric command string (e.g. "0123") and converts it to int codes. */
        static int[] readCommandCodes(Scanner sc) {
            String cmd = sc.next();
            int[] codes = new int[cmd.length()];
            for (int i = 0; i < cmd.length(); i++) {
                codes[i] = cmd.charAt(i) - '0';
            }
            return codes;
        }
    }

    /** Generates every permutation of the four direction symbols. */
    private static class PermutationGenerator {
        /** All distinct permutations of the four direction symbols. */
        private final List<char[]> permutations = new ArrayList<>();

        PermutationGenerator() {
            char[] symbols = {'a', 'd', 's', 'w'};
            permute(symbols, 0, new char[4], new boolean[4], new StringBuilder());
        }

        /** Recursive back‑tracking that fills the permutations list. */
        private void permute(char[] src, int depth, char[] current, boolean[] used, StringBuilder sb) {
            if (depth == src.length) {
                permutations.add(Arrays.copyOf(current, src.length));
                return;
            }
            for (int i = 0; i < src.length; i++) {
                if (!used[i]) {
                    used[i] = true;
                    current[depth] = src[i];
                    permute(src, depth + 1, current, used, sb);
                    used[i] = false;
                }
            }
        }

        /** Returns an immutable copy of all generated permutations. */
        List<char[]> getAll() {
            return Collections.unmodifiableList(new ArrayList<>(permutations));
        }
    }

    /** Core logic that decides whether a particular permutation leads from S to E. */
    private static class Solver {
        private final char[][] maze;
        private final int rows;
        private final int cols;
        private final Cell start;
        private final Cell end;

        Solver(char[][] maze, Cell start, Cell end) {
            this.maze = maze;
            this.rows = maze.length;
            this.cols = maze[0].length;
            this.start = start;
            this.end = end;
        }

        /** Tests if a given move sequence reaches the exit. */
        boolean canReach(char[] moveSequence) {
            int r = start.row;
            int c = start.col;
            for (char dir : moveSequence) {
                switch (dir) {
                    case 'a' -> c--;          // left
                    case 'd' -> c++;          // right
                    case 's' -> r++;          // down
                    case 'w' -> r--;          // up
                }
                if (!inside(r, c) || isWall(r, c)) {
                    return false;
                }
                if (maze[r][c] == 'E') {
                    return true;
                }
            }
            return false;
        }

        /** Utility helpers. */
        private boolean inside(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean isWall(int r, int c) {
            return maze[r][c] == '#';
        }
    }

    /** Entry point – orchestrates input, generation and counting. */
    public static void main(String[] args) {
        try (Scanner in = new Scanner(System.in)) {
            // ----- 1. read maze -------------------------------------------------
            int rows = in.nextInt();
            int cols = in.nextInt();
            char[][] rawMaze = new char[rows][];
            Cell start = null;
            Cell end = null;

            for (int r = 0; r < rows; r++) {
                String line = in.next();
                rawMaze[r] = line.toCharArray();
                for (int c = 0; c < cols; c++) {
                    switch (line.charAt(c)) {
                        case 'S' -> start = new Cell(r, c);
                        case 'E' -> end = new Cell(r, c);
                    }
                }
            }

            // ----- 2. read command codes ----------------------------------------
            int[] numericCodes = new int[in.next().length()];
            for (int i = 0; i < numericCodes.length; i++) {
                numericCodes[i] = in.nextChar() - '0';
            }

            // ----- 3. generate all direction permutations ------------------------
            PermutationGenerator gen = new PermutationGenerator();

            // ----- 4. evaluate each permutation ---------------------------------
            Solver solver = new Solver(rawMaze, start, end);
            int successfulCount = 0;

            for (char[] perm : gen.getAll()) {
                if (solver.canReach(perm)) {
                    successfulCount++;
                }
            }

            System.out.println(successfulCount);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Entry point of the program.
 * Reads a grid, a start‑cell 'S', an end‑cell 'E' and an instruction string,
 * then counts how many distinct instruction permutations lead from 'S' to 'E'
 * without stepping on an obstacle.
 */
public class ProblemB {

    // ------------------------------------------------------------------------
    // Constants & static data
    // ------------------------------------------------------------------------
    private static final char WALL = '#';
    private static final char END  = 'E';
    private static final char START  = 'S';

    /** Directions indexed by digit 0‑3 */
    private static final int[][] DIRECTIONS = {
            {0, 1},   // 0 → up
            {0, -1},  // 1 → down
            {1, 0},   // 2 → right
            {-1, 0}   // 3 → left
    };

    /** All 24 possible permutations of the four instruction digits */
    private static final List<int[]> ALL_PERMUTATIONS = generateAllPermutations();

    // ------------------------------------------------------------------------
    // Main logic
    // ------------------------------------------------------------------------
    public static void main(String[] args) {
        FastScanner fs = new FastScanner();

        int rows = fs.nextInt();
        int cols = fs.nextInt();

        char[][] grid = readGrid(fs, rows);
        int startRow = locateCell(grid, START);
        int endRow   = locateCell(grid, END);

        String rawInstructions = fs.next();

        long count = countValidPermutations(rawInstructions, startRow, endRow, grid);

        System.out.println(count);
    }

    /** Reads the whole grid from the scanner. */
    private static char[][] readGrid(FastScanner fs, int rows) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = fs.next().toCharArray();
        }
        return grid;
    }

    /** Returns the row index of the first occurrence of {@code cell} in the grid. */
    private static int locateCell(char[][] grid, char cell) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == cell) {
                    return r;
                }
            }
        }
        throw new IllegalStateException("Start or end cell not found");
    }

    /**
     * Generates every possible ordering of the four digits 0‑3.
     * Using this deterministic list avoids the huge amount of duplicate shuffles
     * created in the original code.
     */
    private static List<int[]> generateAllPermutations() {
        List<int[]> perms = new ArrayList<>();
        permute(0, new int[4], new boolean[4], perms);
        return perms;
    }

    /** Recursive helper that fills {@code perms} with all permutations of 0‑3. */
    private static void permute(int depth, int[] current, boolean[] used, List<int[]> perms) {
        if (depth == 4) {
            perms.add(current.clone());
            return;
        }
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                current[depth] = i;
                permute(depth + 1, current, used, perms);
                used[i] = false;
            }
        }
    }

    /**
     * Returns how many distinct instruction strings (obtained by permuting the
     * digit‑to‑direction mapping) guide the robot from the start cell to the
     * end cell without hitting a wall.
     */
    private static long countValidPermutations(
            String instructions,
            int startRow,
            int startCol,
            char[][] grid) {

        int validCount = 0;

        for (int[] permutation : ALL_PERMUTATIONS) {
            String mappedInstructionString = mapInstructions(instructions, permutation);
            if (simulatePath(mappedInstructionString, startRow, startCol, grid)) {
                validCount++;
            }
        }
        return validCount;
    }

    /**
     * Replaces each character in {@code instructions} by the digit stored at the
     * corresponding position of {@code permutation}. Example:
     *   permutation = {2,0,1,3}
     *   digit '0' → '2', digit '1' → '0', …
     */
    private static String mapInstructions(String instructions, int[] permutation) {
        StringBuilder sb = new StringBuilder(instructions.length());
        for (int i = 0; i < instructions.length(); i++) {
            char digit = instructions.charAt(i);
            int newDigit = permutation[digit - '0'];
            sb.append((char) ('0' + newDigit));
        }
        return sb.toString();
    }

    /**
     * Executes the instruction string on a copy of the start coordinates.
     *
     * @return {@code true} if the path reaches the end cell without touching a wall.
     */
    private static boolean simulatePath(
            String instr,
            int startRow,
            int startCol,
            char[][] grid) {

        int row = startRow;
        int col = startCol;

        for (int i = 0; i < instr.length(); i++) {
            int dirIdx = instr.charAt(i) - '0';
            int[] d = DIRECTIONS[dirIdx];

            row += d[0];
            col += d[1];

            // Bounds check – if we step outside the grid we treat it as hitting a wall
            if (!inBounds(grid, row, col)) {
                return false;
            }

            char cell = grid[row][col];
            if (cell == END) {
                return true;                // success!
            }
            if (cell == WALL) {
                return false;               // obstacle
            }
        }
        // If we never reached the end, the permutation is invalid
        return false;
    }

    /** Simple bounds test for the grid. */
    private static boolean inBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    // ------------------------------------------------------------------------
    // Fast input scanner (kept but simplified)
    // ------------------------------------------------------------------------
    /**
     * Minimal wrapper around {@link BufferedReader} that provides fast tokenised
     * input without pulling in the heavyweight {@link Scanner}.
     */
    public static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            this(new InputStreamReader(System.in));
        }

        public FastScanner(java.io.Reader in) {
            this.br = new BufferedReader(in);
        }

        /** Returns next token, blocking until one is available. */
        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        // Convenience methods that aren't needed for this problem but kept for
        // parity with the original snippet.
        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String readNextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 * The code is split into small, well‑named methods and uses
 * meaningful constants and variable names to improve readability
 * and maintainability.
 */
public class Main {

    private static final char START = 'S';
    private static final char END   = 'E';
    private static final char OBSTACLE = '#';

    public static void main(String[] args) throws Exception {
        // Reading all input in a single BufferedReader makes resource handling easier.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // ----- parse dimensions and grid -----
            String[] sizeTokens = br.readLine().split("\\s+");
            int rows = Integer.parseInt(sizeTokens[0]);
            int cols = Integer.parseInt(sizeTokens[1]);

            char[][] grid = new char[rows][cols];
            int startX = -1, startY = -1;

            for (int r = 0; r < rows; ++r) {
                String row = br.readLine();
                if (row == null) {
                    break;
                }
                System.arraycopy(row.toCharArray(), 0, grid[r], 0, cols);
                for (int c = 0; c < cols; ++c) {
                    if (grid[r][c] == START) {
                        startX = r;
                        startY = c;
                    }
                }
            }

            // ----- parse the move‑sequence -----
            String sequence = br.readLine();
            int[] stepNumbers = parseSequence(sequence);

            // ----- evaluate all distinct direction permutations -----
            int validCount = 0;
            for (int[] directionPerm : generateDistinctPermutations()) {
                int[] mappedDirections = mapStepNumbers(sequence, directionPerm);
                if (canReachExit(grid, startX, startY, mappedDirections)) {
                    ++validCount;
                }
            }

            System.out.println(validCount);
        }
    }

    /** Converts each character digit in the input string to an integer. */
    private static int[] parseSequence(String sequence) {
        int length = sequence.length();
        int[] arr = new int[length];
        for (int i = 0; i < length; ++i) {
            arr[i] = sequence.charAt(i) - '0';
        }
        return arr;
    }

    /** Generates all permutations of four distinct integers from {0,1,2,3}. */
    private static List<int[]> generateDistinctPermutations() {
        List<int[]> perms = new ArrayList<>();
        for (int a = 0; a < 4; ++a) {
            for (int b = 0; b < 4; ++b) {
                for (int c = 0; c < 4; ++c) {
                    for (int d = 0; d < 4; ++d) {
                        if (areAllDifferent(a, b, c, d)) {
                            perms.add(new int[]{a, b, c, d});
                        }
                    }
                }
            }
        }
        return perms;
    }

    /** Helper that checks whether all supplied values are distinct. */
    private static boolean areAllDifferent(int... values) {
        Set<Integer> seen = new HashSet<>();
        for (int v : values) {
            if (!seen.add(v)) {
                return false;
            }
        }
        return true;
    }

    /** Maps each step number to a direction using the current permutation. */
    private static int[] mapStepNumbers(String sequence, int[] permutation) {
        int[] result = new int[sequence.length()];
        for (int i = 0; i < sequence.length(); ++i) {
            result[i] = permutation.charAt(i - '0'); // placeholder; replaced by index lookup below
        }
        // actual mapping:
        for (int i = 0; i < sequence.length(); ++i) {
            int step = sequence.charAt(i) - '0';
            result[i] = permutation[step];
        }
        return result;
    }

    /** Determines whether a path following the direction order ends at the exit. */
    private static boolean canReachExit(char[][] grid,
                                        int startX, int startY,
                                        int[] directionOrder) {
        int x = startX;
        int y = startY;

        for (int dir : directionOrder) {
            switch (dir) {
                case 0 -> x--;   // up
                case 1 -> x++;   // down
                case 2 -> y++;   // right
                case 3 -> y--;   // left
                default -> throw new IllegalArgumentException("Invalid direction index");
            }

            if (!isWithinBounds(grid, x, y)) {
                return false;
            }
            if (grid[x][y] == OBSTACLE) {
                return false;
            }
            if (grid[x][y] == END) {
                return true;
            }
        }
        return false;
    }

    /** Checks whether the given coordinates lie inside the grid. */
    private static boolean isWithinBounds(char[][] grid, int x, int y) {
        return x >= 0 && y >= 0 && x < grid.length && y < grid[0].length;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 *
 * <p>It reads a rectangular maze, finds the start and exit cells,
 * reads a sequence of movement digits and counts how many permutations
 * of the four directions lead from the start to the exit following the
 * transformed instruction sequence.</p>
 *
 * <p>All mutable state is encapsulated inside the {@link MazeSolver} class,
 * static helper methods are kept minimal and the code is split into
 * clearly named private methods.</p>
 */
public class Main {

    /** Fast input reader used by the program. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns the next token from the input stream. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        char nextChar() throws IOException {
            return nextToken().charAt(0);
        }
    }

    /** Represents the four possible movement directions. */
    private enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        private final int dx;
        private final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        int getDx() {
            return dx;
        }

        int getDy() {
            return dy;
        }
    }

    /** Core logic of the maze‑solving problem. */
    private static class MazeSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final int startX, startY;
        private final int exitX, exitY;
        /** Original instruction string consisting of characters '0'‑'3'. */
        private final String originalInstruction;

        MazeSolver(int rows, int cols, char[][] grid, String originalInstruction) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.originalInstruction = originalInstruction;

            // locate start ('S') and exit ('E')
            for (int y = 0; y < rows; y++) {
                for (int x = 0; x < cols; x++) {
                    char cell = grid[y][x];
                    if (cell == 'S') {
                        startX = x;
                        startY = y;
                    } else if (cell == 'E') {
                        exitX = x;
                        exitY = y;
                    }
                }
            }
        }

        /** Returns the number of direction permutations that lead from start to exit. */
        int countSuccessfulPermutations() {
            int successfulCount = 0;

            // all possible permutations of the four direction indices {0,1,2,3}
            for (int[] perm : generateAllPermutations()) {
                String transformedInstruction = transformInstruction(perm);
                if (followInstructionAndReachExit(transformedInstruction)) {
                    successfulCount++;
                }
            }
            return successfulCount;
        }

        /** Generates every permutation of the array {@code {0,1,2,3}}. */
        private static List<int[]> generateAllPermutations() {
            List<int[]> result = new ArrayList<>();
            backtrack(new int[4], new boolean[4], 0, result);
            return result;
        }

        /** Recursive helper for permutation generation. */
        private static void backtrack(int[] current, boolean[] used, int depth, List<int[]> result) {
            if (depth == current.length) {
                result.add(current.clone());
                return;
            }
            for (int i = 0; i < current.length; i++) {
                if (!used[i]) {
                    used[i] = true;
                    current[depth] = i;
                    backtrack(current, used, depth + 1, result);
                    used[i] = false;
                }
            }
        }

        /**
         * Maps each digit of the original instruction to the direction index
         * given by the current permutation and builds the transformed string.
         */
        private String transformInstruction(int[] perm) {
            StringBuilder sb = new StringBuilder(originalInstruction.length());
            for (int i = 0; i < originalInstruction.length(); i++) {
                char ch = originalInstruction.charAt(i);
                int digit = ch - '0';                 // 0‑3
                int newDirectionIndex = perm[digit]; // permuted direction
                sb.append((char) ('0' + newDirectionIndex));
            }
            return sb.toString();
        }

        /**
         * Simulates walking according to {@code instruction}.
         * Returns {@code true} if the exit cell is reached during the walk.
         */
        private boolean followInstructionAndReachExit(String instruction) {
            int x = startX;
            int y = startY;

            for (int i = 0; i < instruction.length(); i++) {
                int dirIdx = instruction.charAt(i) - '0';
                Direction dir = Direction.values()[dirIdx];

                int nx = x + dir.getDx();
                int ny = y + dir.getDy();

                if (!isInsideBoard(nx, ny) || isBlocked(nx, ny)) {
                    return false; // hit wall or left the board
                }

                x = nx;
                y = ny;

                if (x == exitX && y == exitY) {
                    return true; // reached exit early
                }
            }

            // final check – did we end exactly on the exit after all moves?
            return x == exitX && y == exitY;
        }

        /** Checks that coordinates are within the board limits. */
        private boolean isInsideBoard(int x, int y) {
            return x >= 0 && x < cols && y >= 0 && y < rows;
        }

        /** Returns {@code true} if the given cell is not a wall. */
        private boolean isBlocked(int x, int y) {
            return grid[y][x] == '#';
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // read the grid row by row
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            grid[r] = line.toCharArray();
        }

        String instruction = scanner.next();

        // build the solver and compute the answer
        MazeSolver solver = new MazeSolver(rows, cols, grid, instruction);
        int answer = solver.countSuccessfulPermutations();

        System.out.println(answer);
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>Improvements made:
 * <ul>
 *   <li>Encapsulated grid and position handling in dedicated methods.</li>
 *   <li>Replaced magic numbers and vague variable names with meaningful ones.</li>
 *   <li>Removed the tangled `try / catch` by performing explicit bounds checks.</li>
 *   <li>Grouped the 24 direction‑patterns in a constant list.</li>
 *   <li>Used a small immutable {@code Position} helper class.</li>
 *   <li>Extracted the core simulation logic into well‑named methods.</li>
 *   <li>Added Javadoc comments for clarity.</li>
 * </ul>
 */
public class Main {

    /** Character used to mark a wall. */
    private static final char WALL = '#';

    /** Character used to mark the end cell. */
    private static final char END = 'E';

    /** Character used to mark the start cell. */
    private static final char START = 'S';

    /** The 24 predefined direction patterns (permutations of "0123"). */
    private static final List<String> PATTERNS = List.of(
            "1230", "1203", "1320", "1302", "1023", "1032",
            "2130", "2103", "2310", "2301", "2013", "2031",
            "3210", "3201", "3120", "3102", "3021", "3012",
            "0231", "0213", "0321", "0312", "0123", "0132"
    );

    /** Counter of how many times the end cell is reached. */
    private static int reachedCount = 0;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = readGrid(scanner, rows);
            Position start = locateStart(grid);

            String moveSequence = scanner.next();

            // Evaluate the move sequence against every pattern.
            for (String pattern : PATTERNS) {
                Position cursor = new Position(start.row, start.col);
                reachedCount += simulatePattern(grid, moveSequence, pattern, cursor);
            }

            System.out.println(reachedCount);
        }
    }

    /** Reads the grid from the input and returns it as a 2‑D character array. */
    private static char[][] readGrid(Scanner scanner, int rows) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /** Finds the coordinates of the starting cell 'S' in the grid. */
    private static Position locateStart(char[][] grid) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == START) {
                    return new Position(r, c);
                }
            }
        }
        throw new IllegalStateException("Start position 'S' not found in the grid.");
    }

    /**
     * Executes the move sequence according to a single direction pattern.
     *
     * @return 1 if the end cell is reached during the simulation, otherwise 0.
     */
    private static int simulatePattern(char[][] grid,
                                        String moves,
                                        String pattern,
                                        Position current) {
        for (int i = 0; i < moves.length(); i++) {
            char move = moves.charAt(i);
            int directionIndex = pattern.indexOf(move);
            if (directionIndex == -1) {
                // The move character does not belong to this pattern – ignore it.
                continue;
            }

            Position next = step(grid, current, directionIndex);
            if (next == null) {
                // Hit a wall or left the grid – stop processing this pattern.
                break;
            }

            if (grid[next.row][next.col] == END) {
                // End cell reached – count this pattern as a success.
                return 1;
            }

            current = next; // continue moving from the new position
        }
        return 0;
    }

    /**
     * Moves one step in the direction indicated by {@code dir}.
     *
     * @param grid   the game board.
     * @param pos    current position.
     * @param dir    direction index (0‑up, 1‑left, 2‑right, 3‑down).
     * @return the new {@code Position} after the step, or {@code null}
     *         if the movement would hit a wall or go out of bounds.
     */
    private static Position step(char[][] grid, Position pos, int dir) {
        int newRow = pos.row;
        int newCol = pos.col;

        switch (dir) {
            case 0 -> newRow--; // up
            case 1 -> newCol--; // left
            case 2 -> newCol++; // right
            case 3 -> newRow++; // down
            default -> {
                // Should never happen because dir comes from a valid pattern.
                return null;
            }
        }

        // Bounds validation
        if (newRow < 0 || newRow >= grid.length ||
            newCol < 0 || newCol >= grid[0].length) {
            return null;
        }

        // Wall validation
        if (grid[newRow][newCol] == WALL) {
            return null;
        }

        return new Position(newRow, newCol);
    }

    /** Simple immutable holder for a grid coordinate. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.util.Scanner;

/**
 * Finds how many permutations of movement directions lead from the start cell 'S'
 * to the exit cell 'E' when following a given command string.
 *
 * <p>The program reads:
 * <ul>
 *   <li>grid dimensions (rows × cols)</li>
 *   <li>the grid itself (with characters 'S', 'E', '#', '.' )</li>
 *   <li>the command string consisting of digits 0‑3</li>
 * </ul>
 * Then it enumerates all 4! permutations of the four directions, evaluates each
 * permutation against the command string and counts those that reach 'E' without
 * leaving the grid or hitting a wall '#'.
 */
public class Main {

    /** Direction vectors: up, right, down, left */
    private static final int[][] DIRECTION_VECTORS = {
            { -1, 0 },   // up
            { 0, 1 },    // right
            { 1, 0 },    // down
            { 0, -1 }    // left
    };

    private static final Scanner SCANNER = new Scanner(System.in);

    /** Grid rows */
    private static String[] grid;

    /** Grid dimensions */
    private static int rows, cols;

    /** Position of the start cell */
    private static int startRow, startCol;

    /** Sequence of movement commands (e.g. "0123") */
    private static String commandSequence;

    /** Number of valid permutations */
    private static int answer;

    /** Tracks which direction indices have already been used in the current permutation */
    private static final boolean[] usedDirectionIndex = new boolean[4];

    /** Current permutation of direction indices while generating permutations */
    private static final int[] currentPermutation = new int[4];

    public static void main(String[] args) {
        readInput();
        answer = 0;
        generatePermutations(0);
        System.out.println(answer);
    }

    /** Reads all input data, locates the start position and stores the command string. */
    private static void readInput() {
        rows = SCANNER.nextInt();
        cols = SCANNER.nextInt();
        grid = new String[rows];
        for (int r = 0; r < rows; r++) {
            grid[r] = SCANNER.next();
        }

        locateStartPosition();
        commandSequence = SCANNER.next();
    }

    /** Scans the grid to find the coordinates of the 'S' cell. */
    private static void locateStartPosition() {
        for (int r = 0; r < rows; r++) {
            int c = grid[r].indexOf('S');
            if (c != -1) {
                startRow = r;
                startCol = c;
                return;
            }
        }
        // The problem guarantees exactly one 'S' cell.
    }

    /** Evaluates a single permutation of directions against the command sequence. */
    private static boolean pathIsValid() {
        int x = startRow;
        int y = startCol;

        for (int i = 0; i < commandSequence.length(); i++) {
            int dirIdx = currentPermutation[commandSequence.charAt(i) - '0'];
            int dx = DIRECTION_VECTORS[dirIdx][0];
            int dy = DIRECTION_VECTORS[dirIdx][1];

            x += dx;
            y += dy;

            // Boundary check
            if (x < 0 || x >= rows || y < 0 || y >= cols) {
                return false;
            }

            char cell = grid[x].charAt(y);
            if (cell == 'E') {
                return true;               // reached the exit
            }
            if (cell == '#') {
                return false;               // hit a wall
            }
        }
        return false; // never reached 'E' within the given commands
    }

    /** Recursively generates all permutations of the four direction indices. */
    private static void generatePermutations(int depth) {
        if (depth == DIRECTION_VECTORS.length) {
            if (pathIsValid()) {
                answer++;
            }
            return;
        }

        for (int i = 0; i < DIRECTION_VECTORS.length; i++) {
            if (!usedDirectionIndex[i]) {
                usedDirectionIndex[i] = true;
                currentPermutation[depth] = i;

                generatePermutations(depth + 1);

                usedDirectionIndex[i] = false; // backtrack
            }
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Reads a matrix, a starting position, and a move‑map from standard input.
 * Generates all permutations of the four movement directions and counts how
 * many of those permutations lead from the start position to the exit 'E'
 * when traversed according to the move‑map.
 */
public class BotPathFinder {

    /** Contains everything that is parsed from the input. */
    private static final class InputData {
        final char[][] grid;          // the matrix
        final int rows;               // number of rows
        final int cols;               // number of columns
        final int startRow;           // row of 'S'
        final int startCol;           // column of 'S'
        final String moveMap;         // string of digits that index into a permutation

        InputData(char[][] grid, int startRow, int startCol, String moveMap) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.startRow = startRow;
            this.startCol = startCol;
            this.moveMap = moveMap;
        }
    }

    /** Directions used for movement. */
    private enum Direction {
        UP('U'), DOWN('D'), RIGHT('R'), LEFT('L');

        private final char symbol;

        Direction(char symbol) {
            this.symbol = symbol;
        }

        /** Returns the enum constant that matches the supplied character. */
        static Direction fromChar(char c) {
            for (Direction d : values()) {
                if (d.symbol == c) {
                    return d;
                }
            }
            throw new IllegalArgumentException("Invalid direction character: " + c);
        }

        /** Offset produced by the direction. */
        int[] offset() {
            switch (this) {
                case UP:    return new int[]{-1,  0};
                case DOWN:  return new int[]{ 1,  0};
                case LEFT:  return new int[]{ 0, -1};
                case RIGHT: return new int[]{ 0,  1};
                default:    throw new IllegalStateException();
            }
        }
    }

    /** Generates every permutation of length 4 formed from the four direction symbols. */
    private static List<String> generateAllPermutations() {
        char[] dirChars = {'U', 'D', 'R', 'L'};
        List<String> permutations = new ArrayList<>();
        backtrack(dirChars, new StringBuilder(), new boolean[dirChars.length], permutations);
        return permutations;
    }

    /** Recursive back‑tracking helper for permutation generation. */
    private static void backtrack(char[] dirChars,
                                  StringBuilder current,
                                  boolean[] used,
                                  List<String> collector) {
        if (current.length() == 4) {
            collector.add(current.toString());
            return;
        }

        for (int i = 0; i < dirChars.length; i++) {
            if (!used[i]) {
                used[i] = true;
                current.append(dirChars[i]);
                backtrack(dirChars, current, used, collector);
                current.setLength(current.length() - 1); // undo
                used[i] = false;
            }
        }
    }

    /** Simulates a path on the grid using a single permutation and returns true if 'E' is reached. */
    private static boolean simulate(String permutation,
                                    String moveMap,
                                    char[][] grid,
                                    int startRow,
                                    int startCol) {
        int row = startRow;
        int col = startCol;

        for (int i = 0; i < moveMap.length(); i++) {
            int idx = moveMap.charAt(i) - '0';
            // Guard against malformed input digits
            if (idx < 0 || idx >= permutation.length()) {
                return false;
            }

            char directionChar = permutation.charAt(idx);
            Direction dir = Direction.fromChar(directionChar);
            int[] delta = dir.offset();
            row += delta[0];
            col += delta[1];

            // Boundary checks
            if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length) {
                return false;
            }
            // Obstacle check
            if (grid[row][col] == '#') {
                return false;
            }
            // Success condition
            if (grid[row][col] == 'E') {
                return true;
            }
        }
        return false;
    }

    /** Parses the whole input from the supplied {@link Scanner}. */
    private static InputData parseInput(Scanner scanner) {
        // First line: rows and columns
        String[] sizeTokens = scanner.nextLine().split("\\s+");
        int rows = Integer.parseInt(sizeTokens[0]);
        int cols = Integer.parseInt(sizeTokens[1]);

        char[][] grid = new char[rows][cols];
        int startRow = -1, startCol = -1;

        // Matrix rows
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols; j++) {
                char ch = line.charAt(j);
                grid[i][j] = ch;
                if (ch == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        // Remaining line: move‑map (e.g. "0123")
        String moveMap = scanner.nextLine();

        return new InputData(grid, startRow, startCol, moveMap);
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            InputData data = parseInput(scanner);

            List<String> allPermutations = generateAllPermutations();
            int successCount = 0;

            for (String perm : allPermutations) {
                if (simulate(perm, data.moveMap, data.grid,
                             data.startRow, data.startCol)) {
                    successCount++;
                }
            }

            System.out.println(successCount);
        }
    }
}

import java.io.*;
import java.util.Locale;
import java.util.StringTokenizer;

/**
 * Solves the problem where a set of permutation‑based commands must be tried
 * until the target cell can be reached from the start cell.
 */
public class B {

    /* ---------------------------------------------------------- */
    /*                     CONSTANTS & FIELDS                     */
    /* ---------------------------------------------------------- */

    // Direction vectors – order matches the original dx/dy arrays:
    // 0 → down, 1 → up, 2 → right, 3 → left
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    private static final char WALL = '#';
    private static final char START = 'S';
    private static final char END  = 'E';

    // maze representation
    private boolean[][] maze;

    // dimensions
    private int n, m;

    // start / end coordinates
    private int startRow, startCol, endRow, endCol;

    // permutation of direction indices used for command mapping
    private final int[] permutation = {0, 1, 2, 3};

    // I/O streams
    private BufferedReader br;
    private StringTokenizer st;
    private PrintWriter out;

    /* ---------------------------------------------------------- */
    /*                     MAIN ENTRY POINT                       */
    /* ---------------------------------------------------------- */

    public static void main(String[] args) throws IOException {
        Locale.setDefault(Locale.US);
        new B().run();
    }

    private void run() {
        try {
            br = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out);
            solve();
            out.flush();
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    /* ---------------------------------------------------------- */
    /*                     INPUT HELPERS                         */
    /* ---------------------------------------------------------- */

    private String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(br.readLine());
        }
        return st.nextToken();
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /* ---------------------------------------------------------- */
    /*                 PERMUTATION UTILITIES                     */
    /* ---------------------------------------------------------- */

    /** Generates the next lexicographic permutation of the supplied array. */
    private boolean nextPermutation(int[] a) {
        for (int i = a.length - 2; i >= 0; --i) {
            if (a[i] < a[i + 1]) {
                for (int j = a.length - 1; ; --j) {
                    if (a[j] > a[i]) {
                        swap(a, i, j);
                        reverse(a, i + 1, a.length - 1);
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    private void reverse(int[] arr, int from, int to) {
        while (from < to) {
            swap(arr, from++, to--);
        }
    }

    /* ---------------------------------------------------------- */
    /*                     SOLUTION LOGIC                        */
    /* ---------------------------------------------------------- */

    /** Reads the grid, start/end positions and the command string. */
    private void readInput() throws IOException {
        n = nextInt();
        m = nextInt();
        boolean[][] lab = new boolean[n][m];

        for (int i = 0; i < n; ++i) {
            String row = nextToken();
            for (int j = 0; j < m; ++j) {
                char ch = row.charAt(j);
                lab[i][j] = ch == WALL;
                if (ch == START) {
                    startRow = i;
                    startCol = j;
                } else if (ch == END) {
                    endRow = i;
                    endCol = j;
                }
            }
        }
        maze = lab;
    }

    /** Solves the problem and writes the answer to standard output. */
    private void solve() throws IOException {
        readInput();

        String commands = nextToken();
        int answer = 0;

        do {
            int r = startRow;
            int c = startCol;

            for (int i = 0; i < commands.length(); ++i) {
                int dirIdx = permutation[commands.charAt(i) - '0']; // map digit → direction
                r += DX[dirIdx];
                c += DY[dirIdx];

                if (r == endRow && c == endCol) {
                    ++answer;
                    break;                     // successful path found for this permutation
                }
                if (!isInside(r, c) || maze[r][c]) {
                    break;                     // hit a wall or the border → skip this permutation
                }
            }
        } while (nextPermutation(permutation));

        out.println(answer);
    }

    /** Checks whether a cell (i, j) is inside the grid bounds. */
    private boolean isInside(int i, int j) {
        return i >= 0 && i < n && j >= 0 && j < m;
    }
}

/**
 * Entry point of the application.
 * Reads input, creates the solver and prints the result.
 */
public class Main {

    public static void main(String[] args) {
        // Use System.in / System.out directly – they are already byte‑streams.
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        int n = scanner.scanInt();   // number of rows
        int m = scanner.scanInt();   // number of columns

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.scanString().toCharArray();
        }

        String commandString = scanner.scanString();   // e.g. "12304"

        GridSolver solver = new GridSolver();
        int answer = solver.solve(grid, commandString);

        out.println(answer);
    }
}

/**
 * Fast scanner that works with the original input format
 * (integers, whitespace‑separated tokens and characters).
 */
class FastScanner {

    private final BufferedInputStream in;
    private final byte[] buffer = new byte[4 * 1024];
    private int bufferPos = 0, bufferLen = 0;

    FastScanner(InputStream source) {
        this.in = new BufferedInputStream(source);
    }

    private int readByte() {
        if (bufferPos >= bufferLen) {
            bufferPos = 0;
            bufferLen = in.read(buffer);
            if (bufferLen <= 0) {
                return -1;
            }
        }
        return buffer[bufferPos++];
    }

    /** Skips whitespace and returns the next non‑whitespace byte. */
    private int nextNonWhite() {
        int b;
        while ((b = readByte()) != -1 && isWhiteSpace(b)) {
        }
        return b;
    }

    /** Simple whitespace test used by the original code. */
    private static boolean isWhiteSpace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    /** Reads the next character skipping leading whitespace. */
    char scanChar() {
        int c = nextNonWhite();
        return (char) c;
    }

    /** Reads a signed integer. */
    int scanInt() {
        int sign = 1;
        int result = 0;
        int b = nextNonWhite();

        if (b == '-') {
            sign = -1;
            b = nextNonWhite();
        }

        while (b >= '0' && b <= '9') {
            result = result * 10 + (b - '0');
            b = nextNonWhite();
        }
        return sign * result;
    }

    /** Reads a string up to the next whitespace. */
    String scanString() {
        int b = nextNonWhite();
        StringBuilder sb = new StringBuilder();
        do {
            sb.append((char) b);
            b = nextNonWhite();
        } while (!isWhiteSpace(b));
        return sb.toString();
    }
}

/**
 * Core solver that contains the algorithm logic.
 * All mutable state is confined to the method scope – no static fields are used.
 */
final class GridSolver {

    /** Size limits – kept as literals for clarity. */
    private static final int MAX_PERMUTATIONS = 24; // 4! permutations of "LRUD"

    /** Directions never change; they are derived from each permutation. */
    private static final char UP    = 'U';
    private static final char DOWN  = 'D';
    private static final char LEFT  = 'L';
    private static final char RIGHT = 'R';

    /**
     * Solves a single test case.
     *
     * @param grid     the rectangular map; '#' is an obstacle, 'S' start, 'E' end
     * @param commands a string of digits, each digit selects a permutation
     * @return number of permutations that lead from start to end using the commands
     */
    int solve(char[][] grid, String commands) {
        final int rows = grid.length;
        final int cols = grid[0].length;

        // Locate start (S) and end (E) positions
        int startR = -1, startC = -1;
        int endR = -1, endC = -1;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char ch = grid[r][c];
                if (ch == 'S') {
                    startR = r;
                    startC = c;
                } else if (ch == 'E') {
                    endR = r;
                    endC = c;
                }
            }
        }

        // Pre‑compute all permutations of "LRUD"
        List<char[]> allPermutations = generatePermutations("LRUD");

        int answer = 0;
        // Try every permutation
        for (char[] perm : allPermutations) {
            int curR = startR;
            int curC = startC;
            boolean valid = true;

            // Walk through each digit of the command string
            for (int i = 0; i < commands.length(); i++) {
                int digit = commands.charAt(i) - '0';    // 0 … 3
                char direction = perm[digit];            // corresponding move

                // Apply the move
                switch (direction) {
                    case LEFT  -> curC--;
                    case RIGHT -> curC++;
                    case UP    -> curR--;
                    case DOWN  -> curR++;
                    default    -> throw new IllegalStateException("Unexpected direction");
                }

                // Check if the move stays inside the grid and is not an obstacle
                if (!isInside(curR, curC, rows, cols, grid)) {
                    valid = false;
                    break;
                }

                // Reached the end early – still count as success
                if (curR == endR && curC == endC) {
                    break;
                }
            }

            // Successful if we ended exactly on the end cell and never left the grid
            if (valid && curR == endR && curC == endC) {
                answer++;
            }
        }
        return answer;
    }

    /** Generates every permutation of the supplied string and returns them as char arrays. */
    private static List<char[]> generatePermutations(String source) {
        List<char[]> result = new ArrayList<>(MAX_PERMUTATIONS);
        permuteHelper(source.toCharArray(), 0, result);
        return result;
    }

    /** Recursive helper that fills {@code result} with permutations of {@code chars}. */
    private static void permuteHelper(char[] chars, int start, List<char[]> result) {
        if (start == chars.length) {
            result.add(chars.clone());
            return;
        }
        for (int i = start; i < chars.length; i++) {
            swap(chars, start, i);
            permuteHelper(chars, start + 1, result);
            swap(chars, start, i); // backtrack
        }
    }

    /** Utility to swap two positions in a char array. */
    private static void swap(char[] arr, int i, int j) {
        char tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    /** Returns true if the given coordinates are inside the grid and not a wall ('#'). */
    private static boolean isInside(int r, int c, int rows, int cols, char[][] grid) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '#';
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Entry point */
    public static void main(String[] args) throws IOException {
        try (InputReader reader = new InputReader(System.in);
             OutputWriter writer = new OutputWriter(System.out)) {
            new Solver().solve(reader, writer);
        }
    }

    /** --------------------------------------------------------------
     *  Core solution logic
     *  -------------------------------------------------------------- */
    private static final class Solver {

        /** Fast scanner */
        private static final class InputReader {
            private final InputStream stream;
            private final byte[] buffer = new byte[16_384];
            private int ptr = 0, len = 0;

            InputReader(InputStream stream) {
                this.stream = stream;
            }

            private int readByte() throws IOException {
                if (ptr >= len) {
                    len = stream.read(buffer);
                    ptr = 0;
                    if (len <= 0) return -1;
                }
                return buffer[ptr++];
            }

            private int nextNonSpace() throws IOException {
                int c;
                while ((c = readByte()) != -1 && isSpace(c)) {}
                return c;
            }

            public int nextInt() throws IOException {
                int sign = 1, c = nextNonSpace();
                if (c == '-') { sign = -1; c = readByte(); }
                int value = 0;
                while (c >= '0' && c <= '9') {
                    value = value * 10 + (c - '0');
                    c = readByte();
                }
                return value * sign;
            }

            public char nextCharacter() throws IOException {
                int c;
                while ((c = readByte()) != -1 && isSpace(c)) {}
                return (char) c;
            }

            public String nextString() throws IOException {
                StringBuilder sb = new StringBuilder();
                int c;
                while ((c = readByte()) != -1 && !isSpace(c)) {
                    sb.appendCodePoint(c);
                }
                return sb.toString();
            }

            private boolean isSpace(int c) {
                return c == ' ' || c == '\n' || c == '\r' || c == '\t';
            }
        }

        /** Fast printer */
        private static final class OutputWriter {
            private final PrintWriter out;
            OutputWriter(OutputStream stream) {
                out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(stream)));
            }
            void println(int v) { out.println(v); }
            void close() { out.close(); }
        }

        /** Problem specific data and algorithm */
        private static final class Engine {
            // immutable fields
            private final char[][] grid;
            private final int rows, cols;
            private final int startR, startC;
            private final int endR,   endC;
            private final String pattern;

            // mutable state used during search
            private int answer = 0;
            private final int[] dirForDigit = new int[4];   // direction assigned to each digit
            private final boolean[] used = new boolean[4];  // to enforce distinct directions

            Engine(char[][] grid, int startR, int startC, int endR, int endC,
                   String pattern) {
                this.grid      = grid;
                this.rows      = grid.length;
                this.cols      = grid[0].length;
                this.startR    = startR;
                this.startC    = startC;
                this.endR      = endR;
                this.endC      = endC;
                this.pattern   = pattern;
            }

            /** Starts the back‑tracking search */
            void solve() {
                permute(0);
            }

            /** Assigns a distinct direction to each of the four possible digits */
            private void permute(int pos) {
                if (pos == 4) {
                    simulate();
                    return;
                }
                for (int d = 0; d < 4; ++d) {
                    if (!used[d]) {
                        used[d] = true;
                        dirForDigit[pos] = d;
                        permute(pos + 1);
                        used[d] = false;
                    }
                }
            }

            /** Executes the movement according to the current permutation */
            private void simulate() {
                int r = startR, c = startC;
                for (char ch : pattern.toCharArray()) {
                    int digit = ch - '0';
                    Direction dir = directionFromIndex(dirForDigit[digit]);
                    r += dir.dx;
                    c += dir.dy;
                    if (!inBounds(r, c) || grid[r][c] == '#') {
                        break;
                    }
                    if (r == endR && c == endC) {
                        answer++;
                        break;
                    }
                }
            }

            /** Mapping from an index (0‑3) to the corresponding Direction enum */
            private static Direction directionFromIndex(int idx) {
                return switch (idx) {
                    case 0 -> Direction.UP;
                    case 1 -> Direction.LEFT;
                    case 2 -> Direction.DOWN;
                    case 3 -> Direction.RIGHT;
                    default -> throw new IllegalStateException();
                };
            }

            private boolean inBounds(int r, int c) {
                return r >= 0 && r < rows && c >= 0 && c < cols;
            }

            int getAnswer() {
                return answer;
            }
        }

        /** Direction vectors used by the algorithm */
        private enum Direction {
            UP(-1, 0),
            LEFT(0, -1),
            DOWN(1, 0),
            RIGHT(0, 1);

            final int dx, dy;
            Direction(int dx, int dy) { this.dx = dx; this.dy = dy; }
        }

        /** Solves a single test case */
        void solve(InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = new char[n][m];
            int startR = -1, startC = -1;
            int endR   = -1, endC   = -1;

            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    char ch = in.nextCharacter();
                    grid[i][j] = ch;
                    if (ch == 'S') { startR = i; startC = j; }
                    else if (ch == 'E') { endR = i;   endC = j; }
                }
            }

            String pattern = in.nextString();

            Engine engine = new Engine(grid, startR, startC, endR, endC, pattern);
            engine.solve();               // fills engine.answer
            out.println(engine.getAnswer());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Maintainable and clean solution for the “Maze Permutations” problem.
 *
 * <p>
 * The program reads a grid that contains a start cell {@code S}, an end cell {@code E}
 * and walkable cells {@code .}.  It also reads a sequence of digits that refer to
 * positions inside a permutation of the four movement directions.  For every
 * permutation of the directions we simulate following the sequence and count how
 * many permutations lead us exactly to the end cell.
 * </p>
 */
public class Solution {

    /** Four possible movement directions. */
    private enum Direction {
        UP('u'), DOWN('d'), LEFT('l'), RIGHT('r');

        private final char symbol;

        Direction(char symbol) {
            this.symbol = symbol;
        }

        char getSymbol() {
            return symbol;
        }
    }

    /** Helper class that encapsulates the maze data. */
    private static final class Maze {
        private final char[][] grid;          // grid with an added border of '#'
        private final int rows;                // total rows including border
        private final int cols;                // total columns including border
        private final int startRow, startCol;  // coordinates of 'S'
        private final int endRow,   endCol;    // coordinates of 'E'

        Maze(int n, int m) {
            this.rows = n + 2;
            this.cols = m + 2;
            this.grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = '#';          // outer border – impassable
                }
            }
            this.startRow = -1;
            this.startCol = -1;
            this.endRow = -1;
            this.endCol = -1;
        }

        /** Fill the inner part of the grid from the input stream. */
        void loadFromReader(BufferedReader br, int n, int m) throws IOException {
            String line;
            for (int i = 1; i < rows - 1; i++) {
                line = br.readLine();
                for (int j = 1; j < cols - 1; j++) {
                    char ch = line.charAt(j - 1);
                    grid[i][j] = ch;
                    if (ch == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (ch == 'E') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }
        }

        int getStartRow() { return startRow; }
        int getStartCol() { return startCol; }
        int getEndRow()   { return endRow; }
        int getEndCol()   { return endCol; }

        /** Returns the character stored at (r,c). */
        char get(int r, int c) {
            return grid[r][c];
        }

        /** A cell is walkable if it is '.', 'S' or 'E'. */
        boolean isWalkable(int r, int c) {
            char cell = grid[r][c];
            return cell == '.' || cell == 'S' || cell == 'E';
        }
    }

    /** Generates all permutations of the four {@link Direction} values. */
    private static List<Direction[]> generateAllPermutations() {
        List<Direction[]> perms = new ArrayList<>();
        Direction[] dirs = Direction.values();
        boolean[] used = new boolean[dirs.length];
        Direction[] current = new Direction[dirs.length];
        backtrack(dirs, used, current, 0, perms);
        return perms;
    }

    private static void backtrack(Direction[] src, boolean[] used,
                                  Direction[] current, int depth,
                                  List<Direction[]> collector) {
        if (depth == src.length) {
            collector.add(current.clone());
            return;
        }
        for (int i = 0; i < src.length; i++) {
            if (!used[i]) {
                used[i] = true;
                current[depth] = src[i];
                backtrack(src, used, current, depth + 1, collector);
                used[i] = false;
            }
        }
    }

    /**
     * Simulates a single permutation against the given movement sequence.
     *
     * @param maze     the maze object (provides borders, start/end coordinates)
     * @param perm     a permutation that maps a digit (0‑3) to a direction char
     * @param seq      string of digits that tell which entry of {@code perm}
     *                 to use at each step
     * @return {@code true} if the simulation reaches the end cell exactly.
     */
    private static boolean simulate(Maze maze, Direction[] perm, String seq) {
        int r = maze.getStartRow();
        int c = maze.getStartCol();

        for (int i = 0; i < seq.length(); i++) {
            int idx = seq.charAt(i) - '0';         // digit points into the permutation
            char move = perm[idx].getSymbol();

            // apply the move
            switch (move) {
                case 'u' -> r--;
                case 'd' -> r++;
                case 'l' -> c--;
                case 'r' -> c++;
                default -> throw new IllegalArgumentException("Unknown direction symbol: " + move);
            }

            // hit a wall or leave the walkable area?
            if (!maze.isWalkable(r, c)) {
                return false;
            }
            // reached the destination before the whole sequence is consumed?
            if (r == maze.getEndRow() && c == maze.getEndCol()) {
                return true;
            }
        }
        // after consuming the whole sequence we must be on the end cell
        return r == maze.getEndRow() && c == maze.getEndCol();
    }

    /** Entry point – uses try‑with‑resources for safe stream handling. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            Maze maze = new Maze(n, m);
            maze.loadFromReader(br, n, m);

            String seq = br.readLine();

            List<Direction[]> permutations = generateAllPermutations();
            int count = 0;

            for (Direction[] perm : permutations) {
                if (simulate(maze, perm, seq)) {
                    count++;
                }
            }

            System.out.println(count);
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.Scanner;

/**
 * Solves the problem described in the original program.
 *
 * <p>
 *   The program reads a rectangular grid, finds the start cell {@code 'S'},
 *   reads an instruction string consisting of digits, and tries every possible
 *   mapping of those digits to the four cardinal directions. For each mapping
 *   it follows the instruction sequence and checks whether the path reaches
 *   the exit cell {@code 'E'}. The number of successful mappings is printed.
 * </p>
 */
public final class Main {

    /** Four possible movement directions: RIGHT, LEFT, DOWN, UP */
    private static final int[][] DIRECTIONS = {
            {0, 1},   // RIGHT  (dx = 0, dy = 1)
            {0, -1},  // LEFT   (dx = 0, dy = -1)
            {1, 0},   // DOWN   (dx = 1, dy = 0)
            {-1, 0}   // UP     (dx = -1, dy = 0)
    };

    /** Package‑private scanner used to read from standard input */
    private static final Scanner SCANNER = new Scanner(System.in);

    /** Private constructor – utility class |
     *  this class only contains static helpers and the main logic. */
    private Main() { }

    /** Entry point of the program */
    public static void main(String[] args) throws IOException {
        int rows = SCANNER.nextInt();
        int cols = SCANNER.nextInt();

        char[][] grid = new char[rows][];
        int startRow = -1, startCol = -1;

        // read the grid and locate the starting cell 'S'
        for (int i = 0; i < rows; i++) {
            String line = SCANNER.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        String instruction = SCANNER.next();          // digits only
        int[] directionMapping = {0, 1, 2, 3};          // permutation of 0..3

        int successfulCount = 0;

        do {
            if (simulatePath(grid, startRow, startCol, instruction, directionMapping)) {
                successfulCount++;
            }
        } while (nextPermutation(directionMapping));

        System.out.println(successfulCount);
    }

    /**
     * Executes the instruction string using the supplied permutation of directions.
     *
     * @return {@code true} if the path reaches the exit cell {@code 'E'}, otherwise {@code false}
     */
    private static boolean simulatePath(char[][] grid,
                                         int startRow,
                                         int startCol,
                                         String instructions,
                                         int[] directionMapping) {
        int row = startRow;
        int col = startCol;

        for (int i = 0; i < instructions.length(); i++) {
            char digitChar = instructions.charAt(i);
            int digit = digitChar - '0';

            // Guard against illegal digits – the original code assumes digits 0‑3
            if (digit < 0 || digit >= DIRECTIONS.length) {
                return false;
            }

            int directionIndex = directionMapping[digit];
            int[] dir = DIRECTIONS[directionIndex];
            int nextRow = row + dir[0];
            int nextCol = col + dir[1];

            // Stop if the move would leave the grid or hit a wall ('#')
            if (!isInsideGrid(nextRow, nextCol, grid) || grid[nextRow][nextCol] == '#') {
                return false;
            }

            // Success if we stepped onto the exit
            if (grid[nextRow][nextCol] == 'E') {
                return true;
            }

            // Otherwise continue moving
            row = nextRow;
            col = nextCol;
        }

        // Exhausted all instructions without reaching 'E'
        return false;
    }

    /** Checks whether the supplied coordinates are inside the grid bounds. */
    private static boolean isInsideGrid(int x, int y, char[][] grid) {
        return x >= 0 && y >= 0 && x < grid.length && y < grid[0].length;
    }

    /**
     * Generates the next lexicographic permutation of the array.
     *
     * @param a array to permute; must contain distinct elements
     * @return {@code true} if a next permutation exists, {@code false} otherwise
     */
    private static boolean nextPermutation(int[] a) {
        int i = firstIncreasingFromEnd(a);
        if (i < 0) {
            return false;                     // already the last permutation
        }

        int j = lastGreaterThan(a, i);
        swap(a, i, j);
        reverse(a, i + 1, a.length - 1);
        return true;
    }

    /** Finds the right‑most index i such that a[i] < a[i+1]. */
    private static int firstIncreasingFromEnd(int[] a) {
        for (int i = a.length - 2; i >= 0; i--) {
            if (a[i] < a[i + 1]) {
                return i;
            }
        }
        return -1;
    }

    /** Finds the last index j such that a[j] > a[i]. */
    private static int lastGreaterThan(int[] a, int i) {
        for (int j = a.length - 1; j > i; j--) {
            if (a[j] > a[i]) {
                return j;
            }
        }
        throw new IllegalStateException("No element greater than a[" + i + "] found");
    }

    /** Swaps two positions inside the array. */
    private static void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    /** Reverses the sub‑array from fromIndex to toIndex (inclusive). */
    private static void reverse(int[] a, int fromIndex, int toIndex) {
        while (fromIndex < toIndex) {
            swap(a, fromIndex++, toIndex--);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point of the program.
 *
 * <p>This class reads the input, solves the problem and prints the answer.
 * All heavy‑lifting is delegated to {@link Solver}.
 */
public class Main {

    /** Program start. */
    public static void main(String[] args) throws IOException {
        // try‑with‑resources guarantees that the reader and writer are closed.
        try (InputReader reader = new InputReader(System.in);
             OutputWriter writer = new OutputWriter(System.out)) {
            new Solver().solve(reader, writer);
        }
    }

    /**
     * Solves the problem.
     *
     * <p>The algorithm:
     * <ol>
     *   <li>Read the grid, locate the start {@code S} and end {@code E} cells.</li>
     *   <li>Read the mapping string that tells which digit (0‑3) corresponds to which
     *       direction when it is permuted.</li>
     *   <li>Generate every permutation of the digits “0123”.</li>
     *   <li>For each permutation, simulate the walk using the direction table.</li>
     *   <li>Count those permutations that reach {@code E} without stepping out of
     *       bounds or into a wall.</li>
     * </ol>
     */
    private static class Solver {

        /** Directions: up, right, down, left. */
        private static final int[] DX = {-1, 0, 1, 0};
        private static final int[] DY = {0, 1, 0, -1};

        /** Grid and problem state that are reused for each permutation test. */
        private char[][] grid;
        private int startX, startY, endX, endY;

        /** Entry point used by {@code Main}. */
        void solve(InputReader in, OutputWriter out) throws IOException {
            int rows = in.nextInt();
            int cols = in.nextInt();

            grid = readGrid(in, rows, cols);
            locateStartAndEnd();

            String mapping = in.next();               // e.g. "UDLR"
            int validPermutations = countValidPermutations(mapping);
            out.printLine(validPermutations);
        }

        /** Reads {@code rows} lines, each of length {@code cols}, into a char matrix. */
        private char[][] readGrid(InputReader in, int rows, int cols) throws IOException {
            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; ++r) {
                grid[r] = in.next().toCharArray();    // each line already has the correct length
            }
            return grid;
        }

        /** Stores the coordinates of {@code S} and {@code E} for later use. */
        private void locateStartAndEnd() {
            for (int r = 0; r < grid.length; ++r) {
                for (int c = 0; c < grid[r].length; ++c) {
                    char ch = grid[r][c];
                    if (ch == 'S') {
                        startX = r;
                        startY = c;
                    } else if (ch == 'E') {
                        endX = r;
                        endY = c;
                    }
                }
            }
        }

        /** Generates all distinct permutations of the string “0123” (24 of them). */
        private List<String> generatePermutations(String source) {
            List<String> perms = new ArrayList<>();
            backtrack(source.toCharArray(), 0, perms);
            return perms;
        }

        /** Back‑tracking helper that fills {@code collector} with all permutations. */
        private void backtrack(char[] chars, int index, List<String> collector) {
            if (index == chars.length) {
                collector.add(new String(chars));
                return;
            }
            Set<Character> seen = new HashSet<>();
            for (int i = index; i < chars.length; ++i) {
                if (seen.add(chars[i])) {                // avoid swapping equal characters
                    swap(chars, index, i);
                    backtrack(chars, index + 1, collector);
                    swap(chars, index, i);               // undo
                }
            }
        }

        /** Swaps two positions inside the character array. */
        private void swap(char[] arr, int i, int j) {
            char tmp = arr[i];
            arr[i] = arr[j];
            arr[j] = tmp;
        }

        /** Counts how many permutations of “0123” can be successfully applied using {@code mapping}. */
        private int countValidPermutations(String mapping) {
            int count = 0;
            for (String perm : generatePermutations("0123")) {
                if (canReach(perm)) {
                    ++count;
                }
            }
            return count;
        }

        /**
         * Simulates walking according to a concrete permutation.
         *
         * @param permutation a string of length 4 containing the digits ‘0’‑‘3’
         * @return {@code true} if the walk reaches {@code E} without illegal moves.
         */
        private boolean canReach(String permutation) {
            int x = startX;
            int y = startY;
            int idx = 0;
            final char[] map = mapping.toCharArray();
            final int mapLen = map.length;

            while (true) {
                // 1️⃣  Check termination conditions.
                if (!inBounds(x, y)) {
                    return false;
                }
                if (grid[x][y] == '#') {
                    return false;
                }
                if (grid[x][y] == 'E') {
                    return true;
                }
                if (idx >= mapLen) {
                    return false;               // ran out of instructions before reaching E
                }

                // 2️⃣  Translate the current instruction character to the real direction.
                int dirIdx = permutation.indexOf(map[idx]);
                // By problem statement dirIdx is always in [0,3]; we trust the input.
                x += DX[dirIdx];
                y += DY[dirIdx];
                ++idx;
            }
        }

        /** Simple bounds check for the current cell. */
        private boolean inBounds(int r, int c) {
            return r >= 0 && c >= 0 && r < grid.length && c < grid[0].length;
        }
    }

    /** Minimal buffered input helper. */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(br.readLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Minimal output wrapper that prints tokens on one line and closes the underlying stream. */
    private static class OutputWriter {
        private final PrintWriter out;

        OutputWriter(OutputStream out) {
            this.out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        void printLine(Object... tokens) {
            for (int i = 0; i < tokens.length; ++i) {
                if (i > 0) out.print(' ');
                out.print(tokens[i]);
            }
            out.println();
        }

        void close() {
            out.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 * The program reads a grid, a start cell ‘S’, and a command string,
 * then counts how many distinct assignments of numeric codes to the four
 * movement directions allow the bug to follow the whole command string.
 */
public class Main {

    /** Fast scanner that mimics the original input handling. */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns the next token or loads a new line if necessary. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Returns the next full line (including possible spaces). */
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** Solver encapsulates all logic related to the problem. */
    static class Solver {

        private final char[][] grid;          // input grid
        private final int rows;                 // number of rows
        private final int cols;                 // number of columns
        private final int startRow;             // row index of ‘S’
        private final int startCol;             // column index of ‘S’
        private String commands;                // command string to process

        Solver(char[][] grid, int startRow, int startCol) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.startRow = startRow;
            this.startCol = startCol;
        }

        /** Entry called from {@code main} to perform the whole computation. */
        long countValidAssignments(String commandString) {
            this.commands = commandString;
            long count = 0;

            // All permutations of {0,1,2,3} represent possible mappings
            // of the four direction codes (up, down, left, right).
            int[] base = {0, 1, 2, 3};
            do {
                int[] mapping = base.clone();          // up, down, left, right codes
                if (executeDFS(mapping)) {
                    count++;
                }
            } while (nextPermutation(base));

            return count;
        }

        /** Executes a depth‑first search using the supplied direction mapping. */
        private boolean executeDFS(int[] dirToCode) {
            // dirToCode[0] → code for "up"
            // dirToCode[1] → code for "down"
            // dirToCode[2] → code for "left"
            // dirToCode[3] → code for "right"
            return dfs(startRow, startCol, 0, dirToCode[0], dirToCode[1], dirToCode[2], dirToCode[3]);
        }

        /**
         * Recursive DFS that walks the grid according to the command string.
         *
         * @param r          current row
         * @param c          current column
         * @param pos        current position in the command string
         * @param up         numeric code assigned to "up"
         * @param down       numeric code assigned to "down"
         * @param left       numeric code assigned to "left"
         * @param right      numeric code assigned to "right"
         * @return {@code true} if the whole command string can be followed
         *         from the current cell without stepping out of bounds
         *         or hitting a wall.
         */
        private boolean dfs(int r, int c, int pos, int up, int down, int left, int right) {
            // When the whole command string has been consumed we succeed
            // (the final cell must not be an 'E' according to the original spec).
            if (pos == commands.length()) {
                return grid[r][c] != 'E';
            }

            char expectedCodeChar = commands.charAt(pos);
            int expectedCode = expectedCodeChar - '0';

            // Choose the appropriate movement based on the code.
            if (expectedCode == up) {
                if (r == 0) return false;                 // cannot move up
                return dfs(r - 1, c, pos + 1, up, down, left, right);
            }
            if (expectedCode == down) {
                if (r == rows - 1) return false;          // cannot move down
                return dfs(r + 1, c, pos + 1, up, down, left, right);
            }
            if (expectedCode == left) {
                if (c == 0) return false;                 // cannot move left
                return dfs(r, c - 1, pos + 1, up, down, left, right);
            }
            if (expectedCode == right) {
                if (c == cols - 1) return false;          // cannot move right
                return dfs(r, c + 1, pos + 1, up, down, left, right);
            }
            return false; // unknown code
        }

        /** Generates the next lexicographic permutation of the array in‑place. */
        private static boolean nextPermutation(int[] arr) {
            int n = arr.length;
            // 1. Find the longest non‑increasing suffix
            int i = n - 2;
            while (i >= 0 && arr[i] > arr[i + 1]) {
                i--;
            }
            if (i < 0) {
                return false; // already the last permutation
            }
            // 2. Find rightmost element larger than arr[i]
            int j = n - 1;
            while (arr[j] < arr[i]) {
                j--;
            }
            // 3. Swap them
            swap(arr, i, j);
            // 4. Reverse the suffix starting at i+1
            reverse(arr, i + 1, n);
            return true;
        }

        private static void swap(int[] a, int i, int j) {
            int tmp = a[i];
            a[i] = a[j];
            a[j] = tmp;
        }

        private static void reverse(int[] a, int from, int to) {
            int left = from, right = to - 1;
            while (left < right) {
                swap(a, left, right);
                left++;
                right--;
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /** Program entry point. */
    /** --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        // The original program used System.in / System.out directly.
        // We keep the same behaviour but wrap it in a {@code FastScanner}.
        try (FastScanner scanner = new FastScanner(System.in)) {
            int n = scanner.nextInt();          // number of rows
            int m = scanner.nextInt();          // number of columns
            char[][] grid = new char[n][];
            int startRow = -1, startCol = -1;

            // Read the grid line‑by‑line
            for (int i = 0; i < n; i++) {
                String line = scanner.next();   // grid lines contain no spaces
                grid[i] = line.toCharArray();
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    }
                }
            }

            // The command string that the bug must follow
            String commandString = scanner.next();

            // Solve the problem
            Solver solver = new Solver(grid, startRow, startCol);
            long answer = solver.countValidAssignments(commandString);
            System.out.println(answer);
        }
    }
}

/**
 *  B – Count the number of distinct direction‑assignments that can lead
 *      from the start cell 'S' to the exit cell 'E' while following a
 *      given command sequence.
 *
 *  The program:
 *   1. Reads a rectangular grid (S, E, #, '.' etc.).
 *   2. Finds the coordinates of 'S'.
 *   3. reads a short command string consisting of digits '0'‑'3'.
 *   4. Enumerates all 4! = 24 permutations of the four basic directions.
 *   5. Simulates each permutation and counts how many of them reach 'E'.
 *
 *  The refactor focuses on readability, maintainability and separation
 *  of concerns (input handling, permutation generation, path simulation).
 */
public class B {

    /** four elementary moves: 0 = up, 1 = right, 2 = down, 3 = left */
    private static final int[][] MOVES = {
            {-1, 0},   // up
            { 0, 1},   // right
            { 1, 0},   // down
            { 0,-1}    // left
    };

    /** fast scanner used by the competition‑style code */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            try {
                br = new BufferedReader(new InputStreamReader(System.in));
                st = new StringTokenizer(br.readLine());
            } catch (Exception e) {
                throw new IllegalStateException(e);
            }
        }

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new IllegalStateException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        char[] nextGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; ++r) {
                grid[r] = next().toCharArray();
            }
            return grid[0]; // caller will re‑assemble rows if needed
        }
    }

    /** Enumerates all permutations of {0,1,2,3} (24 total). */
    private static final class PermutationIterator {
        private final int[] current = new int[4];
        private final boolean[] used = new boolean[4];
        private final int[] result = new int[4];
        private int idx = 0;

        /** resets the iterator – call before each new enumeration. */
        void reset() {
            idx = 0;
            fill(current, (int) 0);
            fill(used, false);
        }

        private static <T> void fill(T[] arr, T value) {
            for (int i = 0; i < arr.length; ++i) arr[i] = value;
        }

        private static <T> void fill(boolean[] arr, boolean value) {
            Arrays.fill(arr, value);
        }

        /** returns the next permutation, or {@code false} when exhausted. */
        boolean next(int[] out) {
            if (!hasNext()) {
                return false;
            }
            generate(0);
            System.arraycopy(result, 0, out, 0, 4);
            return true;
        }

        private void generate(int pos) {
            if (pos == 4) {
                result[idx++] = current[0];
                result[idx--] = current[1];
                result[idx--] = current[2];
                result[idx--] = current[3];
                return;
            }
            for (int i = 0; i < 4; ++i) {
                if (!used[i]) {
                    used[i] = true;
                    current[pos] = i;
                    generate(pos + 1);
                    used[i] = false;
                }
            }
        }
    }

    /** Simulates a single permutation of directions on the given grid. */
    private static boolean canReach(int startX, int startY,
                                    char[][] grid,
                                    String commands,
                                    int[] perm) {
        int rows = grid.length;
        int cols = grid[0].length;

        int x = startX;
        int y = startY;

        for (char c : commands.toCharArray()) {
            int dirIdx = perm[c - '0'];          // map digit -> direction
            int[] d = MOVES[dirIdx];
            x += d[0];
            y += d[1];

            // out of bounds or hit a wall -> dead end
            if (x < 0 || x >= rows || y < 0 || y >= cols || grid[x].charAt(y) == '#') {
                return false;
            }

            // reached exit early – still a valid path
            if (grid[x].charAt(y) == 'E') {
                return true;
            }
        }

        // after processing all commands we must stand exactly on 'E'
        return grid[x].charAt(y) == 'E';
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();

        // ----- read input ----------------------------------------------------
        int n = fs.nextInt();               // rows
        int m = fs.nextInt();               // cols
        char[][] grid = readGrid(n, m);
        int sx = -1, sy = -1;                 // start cell coordinates
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (grid[i].charAt(j) == 'S') {
                    sx = i;
                    sy = j;
                }
            }
        }

        // the command string – digits '0' .. '3'
        String commands = fs.next();

        // ----- generate all 24 permutations of the four directions -----------
        PermutationIterator permIter = new PermutationIterator();
        permIter.reset();

        int successfulAssignments = 0;
        int[] currentPerm = new int[4];
        while (permIter.next(currentPerm)) {
            if (canReach(sx, sy, grid, commands, currentPerm)) {
                ++successfulAssignments;
            }
        }

        // ----- output ---------------------------------------------------------
        System.out.println(successfulAssignments);
    }

    /** Helper that reads the whole grid into a char[][] array. */
    private static char[][] readGrid(int rows, int cols) {
        FastScanner fs = new FastScanner();
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; ++i) {
            // we rely on the scanner having already consumed the first line
            String line = fs.next();
            grid[i] = line.toCharArray();
        }
        return grid;
    }
}

import java.io.*;
import java.util.*;

/**
 * Fast scanner – wraps a BufferedReader and a StringTokenizer.
 */
final class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    FastScanner(InputStream is) {
        this.br = new BufferedReader(new InputStreamReader(is));
    }

    /** Returns the next token, reading a new line if necessary. */
    private String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    int nextInt() throws IOException               { return Integer.parseInt(nextToken()); }
    long nextLong() throws IOException             { return Long.parseLong(nextToken()); }
    double nextDouble() throws IOException         { return Double.parseDouble(nextToken()); }
    String nextString() throws IOException         { return nextToken(); }
}

/**
 * Helper class that contains the original modular arithmetic utilities.
 * (Kept for completeness – it isn’t used in the current logic but
 * preserves the original API.)
 */
final class Mod {
    private static final long MOD = 1_000_000_007L;

    private static long pow(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static long multiply(long a, long b) { return (a * b) % MOD; }
    static long modInverse(long a) { return pow(a, MOD - 2); }
}

/**
 * Represents a single movement direction (up, right, down, left).
 * The character associated with each direction must match the input
 * tokens ('0'–'3'), preserving the original semantics.
 */
enum Move {
    UP('0'),    RIGHT('1'),    DOWN('2'),    LEFT('3');

    private final char token;

    Move(char token) {
        this.token = token;
    }

    /** Recovers a {@link Move} from its input token. */
    static Move fromToken(char token) {
        for (Move m : values()) {
            if (m.token == token) {
                return m;
            }
        }
        throw new IllegalArgumentException("Unknown move token: " + token);
    }

    /** Row offset for the move. */
    int deltaRow() {
        return switch (this) {
            case UP -> -1;
            case RIGHT -> 0;
            case DOWN -> 1;
            case LEFT -> 0;
        };
    }

    /** Column offset for the move. */
    int deltaCol() {
        return switch (this) {
            case UP -> 0;
            case RIGHT -> 1;
            case DOWN -> 0;
            case LEFT -> -1;
        };
    }
}

/**
 * Core logic of the program:
 *   – reads the grid, start (S) and goal (E) positions,
 *   – reads the movement token sequence,
 *   – checks every permutation of the four possible moves,
 *   – counts how many permutations lead from S to E.
 */
final class Solver {
    private final FastScanner in;
    private final PrintWriter out;

    // Grid representation
    private char[][] grid;
    private int rows, cols;

    // Start (S) and goal (E) coordinates
    private int startRow, startCol;
    private int goalRow, goalCol;

    // Token sequence to be permuted
    private char[] moveTokens;

    // Result to be printed
    private long answer = 0;

    Solver(FastScanner in, PrintWriter out) {
        this.in = in;
        this.out = out;
    }

    /** Entry point used by {@link Main}. */
    void solve() throws IOException {
        readInput();
        enumeratePermutations();
        outputAnswer();
    }

    /** Reads everything from {@link FastScanner}. */
    private void readInput() throws IOException {
        rows = in.nextInt();
        cols = in.nextInt();

        grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = in.nextString().toCharArray();
        }

        // Locate start (S) and goal (E)
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char ch = grid[r][c];
                if (ch == 'S') {
                    startRow = r;
                    startCol = c;
                } else if (ch == 'E') {
                    goalRow = r;
                    goalCol = c;
                }
            }
        }

        moveTokens = in.nextString().toCharArray();   // e.g. "0123"
    }

    /** Generates all 4! permutations of {0,1,2,3} and validates each. */
    private void enumeratePermutations() {
        boolean[] used = new boolean[4];
        int[] permutation = new int[4];
        backtrack(0, used, permutation);
    }

    /** Recursive back‑tracking that builds the permutation step‑by‑step. */
    private void backtrack(int depth, boolean[] used, int[] perm) {
        if (depth == 4) {
            if (checkPath(perm)) {
                answer++;
            }
            return;
        }

        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                perm[depth] = i;               // assign the i‑th available action
                backtrack(depth + 1, used, perm);
                used[i] = false;               // backtrack
            }
        }
    }

    /** Simulates the walk according to a concrete permutation of actions. */
    private boolean checkPath(int[] perm) {
        int r = startRow;
        int c = startCol;

        for (char token : moveTokens) {
            int rawActionIdx = token - '0';          // 0 … 3
            int moveIdx      = perm[rawActionIdx];   // which physical move to take
            Move move        = Move.values()[moveIdx];

            r += move.deltaRow();
            c += move.deltaCol();

            if (!isInside(r, c) || isBlocked(r, c)) {
                return false;                         // hit a wall or went out of bounds
            }

            if (r == goalRow && c == goalCol) {
                return true;                           // goal reached early – still valid
            }
        }
        return false;                                 // finished sequence without reaching goal
    }

    /** Checks whether a cell lies inside the grid. */
    private boolean isInside(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /** Returns true if the cell is an obstacle ('#'). */
    private boolean isBlocked(int x, int y) {
        return grid[x][y] == '#';
    }

    /** Prints the final answer. */
    private void outputAnswer() {
        out.println(answer);
    }
}

