import java.util.*;

/**
 * Main class that orchestrates reading input, generating permutations of move
 * sequences and counting how many of those sequences lead the solver to the
 * exit of the maze.
 */
public class Main {

    private static final Scanner SCANNER = new Scanner(System.in);

    public static void main(String[] args) {
        int rows = readInt("Enter number of rows (n): ");
        int cols = readInt("Enter number of columns (m): ");

        Maze maze = readMaze(rows, cols);
        String instructionSequence = readInstructions();

        List<String> permutations = PermutationGenerator.generatePermutations(1000);

        int countSuccessfulPaths = 0;

        for (String perm : permutations) {
            if (processPermutation(maze, instructionSequence, perm)) {
                countSuccessfulPaths++;
            }
        }

        System.out.println(countSuccessfulPaths);
    }

    /** Reads an integer from the console, re‑prompting on invalid input. */
    private static int readInt(String prompt) {
        System.out.print(prompt);
        while (!SCANNER.hasNextInt()) {
            SCANNER.next(); // discard the invalid token
            System.out.print("Invalid input. " + prompt);
        }
        return SCANNER.nextInt();
    }

    /** Reads the maze layout from the console and returns a {@link Maze} object. */
    private static Maze readMaze(int rows, int cols) {
        System.out.println(
                "Enter the maze layout (size " + rows + "x" + cols + ").\n" +
                "Use 'S' for the start, 'E' for the exit, '#' for walls and '.' for free cells.");
        char[][] grid = new char[rows][cols];
        int startRow = -1, startCol = -1;
        int endRow = -1, endCol = -1;

        for (int i = 0; i < rows; i++) {
            String line = SCANNER.nextLine().trim();
            while (line.isEmpty()) {               // skip empty lines
                line = SCANNER.nextLine().trim();
            }
            if (line.length() < cols) {
                throw new IllegalArgumentException(
                        "Line " + (i + 1) + " does not contain the required " + cols + " characters.");
            }
            for (int j = 0; j < cols; j++) {
                char cell = line.charAt(j);
                grid[i][j] = cell;
                if (cell == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (cell == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }

        if (startRow == -1 || startCol == -1 || endRow == -1 || endCol == -1) {
            throw new IllegalArgumentException("Maze must contain exactly one 'S' and one 'E'.");
        }

        return new Maze(grid, startRow, startCol, endRow, endCol);
    }

    /** Reads the instruction sequence that the permutations must match. */
    private static String readInstructions() {
        System.out.print("Enter the instruction sequence (e.g., RULD...): ");
        return SCANNER.nextLine().trim();
    }

    /**
     * Executes a single permutation against the maze.
     *
     * @return {@code true} if the permutation leads the solver to the exit,
     *         {@code false} otherwise.
     */
    private static boolean processPermutation(Maze maze,
                                              String instructions,
                                              String permutation) {
        maze.reset();

        // The four characters of the permutation correspond to the four
        // movement directions: right, up, left, down (in that order).
        for (int idx = 0; idx < instructions.length(); idx++) {
            char cmd = instructions.charAt(idx);
            int direction = mapCommandToDirection(cmd, permutation);
            if (direction == -1) {
                // The current command does not belong to any of the four
                // directions defined by the permutation – ignore it.
                continue;
            }

            if (!maze.move(direction)) {
                // Move would hit a wall or leave the maze – this permutation fails.
                return false;
            }

            if (maze.isAtExit()) {
                // The exit has been reached – success for this permutation.
                return true;
            }
        }
        // Exhausted all instructions without reaching the exit.
        return false;
    }

    /**
     * Determines which direction (0‑3) a given command character represents,
     * based on the supplied permutation.
     *
     * @param commandChar the character from the instruction sequence
     * @param permutation a string containing exactly the four distinct digits
     *                    '0','1','2','3' in some order
     * @return the direction index (0=right, 1=up, 2=left, 3=down) or –1 if not found
     */
    private static int mapCommandToDirection(char commandChar, String permutation) {
        char right  = permutation.charAt(0);
        char up     = permutation.charAt(1);
        char left   = permutation.charAt(2);
        char down   = permutation.charAt(3);

        return switch (commandChar) {
            case right  -> 0;
            case up     -> 1;
            case left   -> 2;
            case down   -> 3;
            default     -> -1;
        };
    }

    // -------------------------------------------------------------------------
    // Helper utilities
    // -------------------------------------------------------------------------

    /**
     * Generates a collection of distinct random permutations of length four.
     * Each permutation consists of the digits 0‑3 without repetition.
     *
     * @param maxAttempts maximum number of permutations to generate
     * @return a list of distinct permutation strings
     */
    static final class PermutationGenerator {

        private PermutationGenerator() { }

        static List<String> generatePermutations(int maxAttempts) {
            Set<String> unique = new HashSet<>();
            Random rng = new Random();

            while (unique.size() < maxAttempts) {
                List<Integer> pool = List.of(0, 1, 2, 3);
                Collections.shuffle(pool, rng);
                StringBuilder sb = new StringBuilder();
                for (int digit : pool) {
                    sb.append(digit);
                }
                unique.add(sb.toString());
            }
            return new ArrayList<>(unique);
        }
    }

    // -------------------------------------------------------------------------
    // Maze model
    // -------------------------------------------------------------------------

    static final class Maze {

        // Directions: right, up, left, down
        private static final int[] DX = {1, 0, -1, 0};
        private static final int[] DY = {0, 1, 0, -1};

        private final char[][] grid;
        private final int rows;
        private final int columns;

        // Position tracking
        private int currentRow;
        private int currentColumn;
        private final int startRow;
        private final int startColumn;
        private final int exitRow;
        private final int exitColumn;

        Maze(char[][] grid,
             int startRow, int startColumn,
             int exitRow, int exitColumn) {
            this.grid = grid;
            this.rows = grid.length;
            this.columns = grid[0].length;
            this.startRow = startRow;
            this.startColumn = startColumn;
            this.exitRow = exitRow;
            this.exitColumn = exitColumn;

            // Initialise current position to the start cell
            this.currentRow = startRow;
            this.currentColumn = startColumn;
        }

        /** Resets the solver back to the start location. */
        void reset() {
            currentRow = startRow;
            currentColumn = startColumn;
        }

        /** Attempts to move one step in the given direction. Returns false if illegal. */
        boolean move(int direction) {
            int nextRow = currentRow + DX[direction];
            int nextColumn = currentColumn + DY[direction];

            // Boundary check
            if (nextRow < 0 || nextRow >= rows || nextColumn < 0 || nextColumn >= columns) {
                return false;
            }
            // Obstacle check
            if (grid[nextRow][nextColumn] == '#') {
                return false;
            }
            // Apply the move
            currentRow = nextRow;
            currentColumn = nextColumn;
            return true;
        }

        /** Returns true if the solver currently occupies the exit cell. */
        boolean isAtExit() {
            return grid[currentRow][currentColumn] == 'E';
        }
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Main class that reads input, creates a solver instance and prints the answer.
 */
public class Main {

    public static void main(String[] args) {
        InputStream inStream = System.in;
        OutputStream outStream = System.out;

        try (BufferedReader br = new BufferedReader(new InputStreamReader(inStream))) {
            InputReader reader = new InputReader(br);
            PrintWriter writer = new PrintWriter(outStream);

            // The original code expects solve(int, InputReader, PrintWriter)
            new MazeSolver().solve(1, reader, writer);

            writer.flush();               // explicit flush mirrors original behaviour
        } catch (IOException e) {
            // In a competition setting we simply ignore the exception.
        }
    }

    /**
     * Solver that counts how many permutations of movement directions enable
     * reaching the exit 'E' from the start 'S' while following the given move
     * string.
     */
    static class MazeSolver {

        // -----------------------------------------------------------------------
        // Constants & fields
        // -----------------------------------------------------------------------
        private static final int[][] MOVEMENTS = {
                {0, 1},   // 0 -> right
                {0, -1},  // 1 -> left
                {1, 0},   // 2 -> down
                {-1, 0}   // 3 -> up
        };

        private char[][] grid;
        private int rows, cols;
        private int startRow, startCol;
        private int endRow, endCol;
        private String moveSequence;

        // Directions used for permutation handling
        private final int[] permutation = {0, 1, 2, 3};

        // -----------------------------------------------------------------------
        // Public API – matches the original signature
        // -----------------------------------------------------------------------
        /**
         * Entry point used by the original program.  The {@code testNumber}
         * argument is kept only for compatibility; it is not used internally.
         */
        void solve(int testNumber, InputReader in, PrintWriter out) {
            readInput(in);

            int count = 0;
            do {
                if (canReach(permutation)) {
                    ++count;
                }
            } while (nextPermutation(permutation));

            out.println(count);
        }

        // -----------------------------------------------------------------------
        // Private helpers
        // -----------------------------------------------------------------------

        /**
         * Reads the whole test case and stores it in fields used by the solver.
         */
        private void readInput(InputReader in) {
            rows = in.ni();
            cols = in.ni();

            grid = new char[rows][];
            for (int r = 0; r < rows; ++r) {
                grid[r] = in.n().toCharArray();
            }

            moveSequence = in.n();

            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    char cell = grid[r][c];
                    if (cell == 'S') {
                        startRow = r;
                        startCol = c;
                    } else if (cell == 'E') {
                        endRow = r;
                        endCol = c;
                    }
                }
            }
        }

        /**
         * Determines whether the current permutation of directions permits the
         * traversal from the start cell to the end cell while obeying the move
         * sequence.
         */
        private boolean canReach(int[] order) {
            int r = startRow;
            int c = startCol;

            for (char ch : moveSequence.toCharArray()) {
                int digit = Character.digit(ch, 10);   // digit 0‑3
                int dirIdx = order[digit];             // mapped direction index
                int nr = r + MOVEMENTS[dirIdx][0];
                int nc = c + MOVEMENTS[dirIdx][1];

                // Boundary or obstacle check – fail fast
                if (!isInsideGrid(nr, nc) || grid[nr][nc] == '#') {
                    return false;
                }

                r = nr;
                c = nc;

                // Destination reached – success
                if (r == endRow && c == endCol) {
                    return true;
                }
            }
            return false; // sequence finished without reaching 'E'
        }

        /** Checks whether a cell coordinate lies inside the grid. */
        private boolean isInsideGrid(int row, int col) {
            return row >= 0 && row < rows && col >= 0 && col < cols;
        }

        /**
         * Generates the next lexicographical permutation of {@code permutation}.
         * Returns {@code true} if such a permutation exists, otherwise {@code false}.
         */
        private boolean nextPermutation(int[] arr) {
            int n = arr.length;
            int i = n - 1;
            while (i > 0 && arr[i] <= arr[i - 1]) {
                --i;
            }
            if (i == 0) {
                return false; // already at the last permutation
            }

            // Find the successor to arr[i‑1] in the suffix arr[i … n‑1]
            int x = arr[i - 1];
            int successor = i;
            for (int j = i + 1; j < n; ++j) {
                if (arr[j] > x && arr[j] < arr[successor]) {
                    successor = j;
                }
            }

            // Swap the pivot with its successor
            int tmp = arr[i - 1];
            arr[i - 1] = arr[successor];
            arr[successor] = tmp;

            // Reverse (sort) the suffix
            Arrays.sort(arr, i, n);
            return true;
        }
    }

    // ---------------------------------------------------------------------------
    // Input / output utilities
    // ---------------------------------------------------------------------------
    /**
     * Simple wrapper around {@link BufferedReader} that provides fast tokenised
     * reading of the input data.
     */
    static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(BufferedReader br) {
            this.br = br;
        }

        /** Reads the next token (String). */
        String n() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    // In contest code we silently ignore I/O errors.
                }
            }
            return st.nextToken();
        }

        /** Reads the next token as an {@code int}. */
        int ni() {
            return Integer.parseInt(n());
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    private static final char WALL = '#';
    private static final char START = 'S';
    private static final char END = 'E';

    /** Reproduces the 20‑row, 4‑column offset table from the original code. */
    private static int[][] buildDeltaTable() {
        return new int[][]{
                {1, -1, 100, -100}, {1, -1, -100, 100},
                {1, 100, -1, -100}, {1, 100, -100, -1},
                {1, -100, -1, 100}, {1, -100, 100, -1},
                {-1, 1, -100, 100}, {-1, 1, 100, -100},
                {-1, 100, -100, 1}, {-1, 100, 1, -100},
                {-1, -100, 100, 1}, {-1, -100, 1, 100},
                {100, 1, -1, -100}, {100, 1, -100, -1},
                {100, -1, 1, -100}, {100, -1, -100, 1},
                {100, -100, 1, -1}, {100, -100, -1, 1},
                {-100, 1, -1, 100}, {-100, 1, 100, -1},
                {-100, -1, 100, 1}, {-100, -1, 1, 100},
                {-100, 100, 1, -1}, {-100, 100, -1, 1}
        };
    }

    /** Simple wrapper that reads tokens and integers from the input stream. */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        new Solution().run();
    }

    public void run() {
        try (InputStream in = System.in;
             InputReader reader = new InputReader(in);
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] maze = new char[rows + 1][cols + 1]; // 1‑based indexing
            int startR = -1, startC = -1;
            int endR = -1, endC = -1;

            for (int r = 1; r <= rows; r++) {
                String line = reader.next();
                if (line.length() != cols) {
                    throw new IllegalArgumentException("Row length does not match declared columns");
                }
                for (int c = 1; c <= cols; c++) {
                    maze[r][c] = line.charAt(c - 1);
                    if (maze[r][c] == START) {
                        startR = r;
                        startC = c;
                    } else if (maze[r][c] == END) {
                        endR = r;
                        endC = c;
                    }
                }
            }

            String order = reader.next();

            int[][] deltaPatterns = buildDeltaTable();
            int answer = 0;

            for (int[] deltas : deltaPatterns) {
                int r = startR;
                int c = startC;
                boolean reachedEnd = false;

                for (int step = 0; step < order.length(); step++) {
                    int digit = order.charAt(step) - '0'; // assumes only digit characters
                    if (digit < 0 || digit >= deltas.length) {
                        break; // digit out of range used by the original table
                    }

                    int offset = deltas[digit];
                    int encoded = r * 100 + c + offset; // original encoding: row*100 + col
                    r = encoded / 100;
                    c = encoded % 100;

                    // boundary check
                    if (r < 1 || c < 1 || r > rows || c > cols) {
                        break;
                    }
                    // wall check
                    if (maze[r][c] == WALL) {
                        break;
                    }
                    // reached the exit?
                    if (maze[r][c] == END) {
                        reachedEnd = true;
                        break;
                    }
                }

                if (reachedEnd) {
                    answer++;
                }
            }

            out.println(answer);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /* ----- Constants & offsets ------------------------------------------------ */
    private static final int UP    = 0;
    private static final int RIGHT = 1;
    private static final int DOWN  = 2;
    private static final int LEFT  = 3;

    private static final int[] DR = {-1, 0, 1, 0};   // row change for UP,RIGHT,DOWN,LEFT
    private static final int[] DC = {0, 1, 0, -1};   // column change for UP,RIGHT,DOWN,LEFT

    /* ----- Entry point ---------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        Scanner scanner = new Scanner(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][];
        int startR = -1, startC = -1;

        /* ----- Read the grid and locate the start cell 'S' ---------------------- */
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startR = i;
                    startC = j;
                }
            }
        }

        String moves = scanner.next();               // the movement string
        int successCount = 0;

        /* ----- Try every permutation of the four direction indices -------------- */
        List<int[]> allPermutations = generateAllPermutations(new int[]{UP, RIGHT, DOWN, LEFT});
        for (int[] perm : allPermutations) {
            if (simulate(perm, grid, startR, startC, moves)) {
                successCount++;
            }
        }

        out.println(successCount);
        out.close();
    }

    /* ----- Utility: generate all 24 permutations of four distinct directions ---- */
    private static List<int[]> generateAllPermutations(int[] dirs) {
        List<int[]> result = new ArrayList<>();
        permute(dirs, 0, result);
        return result;
    }

    private static void permute(int[] a, int idx, List<int[]> result) {
        if (idx == a.length) {
            result.add(Arrays.copyOf(a, a.length));
            return;
        }
        for (int i = idx; i < a.length; i++) {
            swap(a, idx, i);
            permute(a, idx + 1, result);
            swap(a, idx, i);          // backtrack
        }
    }

    private static void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    /* ----- Core simulation ------------------------------------------------------ */
    /**
     * Executes the movement defined by {@code perm} starting from {@code sr, sc}.
     *
     * @return {@code true} if the path ends exactly on cell 'E' without stepping on
     *         a wall '#' or leaving the grid.
     */
    private static boolean simulate(int[] perm, char[][] grid, int sr, int sc, String moves) {
        int r = sr;
        int c = sc;

        for (int k = 0; k < moves.length(); k++) {
            int digit = moves.charAt(k) - '0';          // digit 0‑3
            int dir   = perm[digit];                    // mapped direction index

            int nr = r + DR[dir];
            int nc = c + DC[dir];

            // ----- Boundary and obstacle checks ---------------------------------
            if (nr < 0 || nr >= grid.length || nc < 0 || nc >= grid[0].length) {
                return false;
            }
            if (grid[nr][nc] == '#') {
                return false;
            }

            // ----- Take the step -------------------------------------------------
            r = nr;
            c = nc;

            // Early exit when the goal 'E' is reached
            if (grid[r][c] == 'E') {
                break;
            }
        }

        // The final cell must be the goal 'E'
        return grid[r][c] == 'E';
    }

    /* ----- Simple scanner wrapper (mirrors the original MyScanner) ------------- */
    private static class Scanner {
        private final BufferedReader br;
        private StringTokenizer st;

        Scanner(Reader reader) {
            this.br = new BufferedReader(reader);
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.util.List;
import java.util.Map;
import java.util.Scanner;

/**
 * Counts how many of the predefined movement strings can guide the robot
 * from the start cell 'S' to the exit cell 'E' without leaving the grid
 * or stepping on a wall '#'.
 *
 * The program is deliberately split into small, single‑responsibility
 * methods and uses only immutable data where possible.
 */
public class RoboPathCounter {

    /** All movement strings that have to be tested. */
    private static final List<String> VALID_MOVES = List.of(
            "><^v", "><v^", ">^<v", ">^v<", ">v^<", ">v<^", "<>^v",
            "<>v^", "<^>v", "<^v>", "<v^>", "<v>^", "^<>v", "^<v^",
            "^><v", "^>v<", "^v><", "^v<>", "v<^>", "v<>^", "v^<>",
            "v^><", "v>^<", "v><^"
    );

    /** Mapping from a direction character to its (row, col) delta. */
    private static final Map<Character, int[]> MOVE_DELTA = Map.of(
            '>', new int[]{1, 0},
            '<', new int[]{-1, 0},
            '^', new int[]{0, 1},
            'v', new int[]{0, -1}
    );

    /** Dimensions of the grid and the grid itself. */
    private static int rows, cols;
    private static char[][] grid;

    /** Position of the start cell 'S'. */
    private static int startRow, startCol;

    /** The movement path that the scanner reads. */
    private static String path;

    public static void main(String[] args) {
        /* Try‑with‑resources guarantees that the scanner is closed automatically. */
        try (Scanner scanner = new Scanner(System.in)) {
            readGrid(scanner);
            path = scanner.next();                     // the path to test
            int validCount = countValidMoves();
            System.out.println(validCount);
        }
    }

    /** Reads the grid dimensions and the grid, locating the start cell. */
    private static void readGrid(Scanner scanner) {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        grid = new char[rows][cols];

        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
                if (grid[r][c] == 'S') {
                    startRow = r;
                    startCol = c;
                }
            }
        }
    }

    /** Determines whether a single move‑sequence leads from 'S' to 'E'. */
    private static boolean canReachExit(String moveSequence) {
        int r = startRow;
        int c = startCol;

        for (int i = 0; i < moveSequence.length(); i++) {
            char dir = moveSequence.charAt(i);
            int[] delta = MOVE_DELTA.get(dir);
            if (delta == null) {
                return false;               // unknown direction character
            }

            r += delta[0];
            c += delta[1];

            // Out‑of‑bounds or wall → cannot proceed
            if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == '#') {
                return false;
            }

            // Reaching the exit terminates the sequence successfully
            if (grid[r][c] == 'E') {
                return true;
            }
        }
        // If the loop ends without hitting 'E', the exit was not reached
        return false;
    }

    /** Counts how many predefined move sequences successfully reach 'E'. */
    private static int countValidMoves() {
        int count = 0;
        for (String move : VALID_MOVES) {
            if (canReachExit(move)) {
                count++;
            }
        }
        return count;
    }
}

import java.io.*;
import java.util.*;

/**
 * Fast scanner that works with any InputStream.
 */
final class FastScanner {
    private final InputStream in;
    private final byte[] buffer = new byte[8192];
    private int bufferPointer = 0, bytesRead = 0;

    FastScanner(InputStream in) {
        this.in = in;
    }

    private int readByte() throws IOException {
        if (bufferPointer >= bytesRead) {
            bytesRead = in.read(buffer);
            bufferPointer = 0;
        }
        return buffer[bufferPointer++];
    }

    /** Reads the next non‑whitespace character. */
    private int skipWhiteSpace() throws IOException {
        int c;
        do {
            c = readByte();
        } while (c <= ' ' && c != -1);
        return c;
    }

    /** Reads next int. */
    int nextInt() throws IOException {
        int c = skipWhiteSpace();
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readByte();
        }
        int result = 0;
        while (c > ' ') {
            result = result * 10 + (c - '0');
            c = readByte();
        }
        return result * sign;
    }

    /** Reads next non‑whitespace string. */
    String nextString() throws IOException {
        int c = skipWhiteSpace();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    /** Checks whether the current character is whitespace. */
    private static boolean isSpace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

/**
 * Holds the algorithm for a single test case.
 * All mutable fields are kept private and accessed through well‑named methods.
 */
final class Solver {
    private static final int NORTH = 0;
    private static final int WEST  = 1;
    private static final int SOUTH = 2;
    private static final int EAST  = 3;

    /** Mapping from a digit character to a direction index. */
    private static final Map<Character, Integer> DIGIT_TO_DIRECTION = Map.of(
            '0', NORTH,
            '1', WEST,
            '2', SOUTH,
            '3', EAST
    );

    /** Grid representation – immutable after construction. */
    private final char[][] grid;
    /** Number of rows and columns. */
    private final int rows, cols;
    /** Starting position of ‘S’. */
    private final int startRow, startCol;
    /** Ordered list of all permutations of {0,1,2,3}. */
    private final List<int[]> allPermutations = new ArrayList<>();
    /** Count of permutations that can reach ‘E’. */
    private int reachableCount = 0;

    Solver(char[][] grid, int startRow, int startCol, List<int[]> allPermutations) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.startRow = startRow;
        this.startCol = startCol;
        this.allPermutations.addAll(allPermutations);
    }

    /** Entry point used by the driver code. */
    void solve(PrintWriter out) {
        // The result is stored directly into out.print(...)
        out.print(countPermutationsThatReachExit());
    }

    /** Returns the number of permutations that lead from ‘S’ to ‘E’. */
    private int countPermutationsThatReachExit() {
        int reachable = 0;
        for (int[] perm : allPermutations) {
            if (simulatePath(perm)) {
                reachable++;
            }
        }
        return reachable;
    }

    /** Simulates the walk described by a permutation. */
    private boolean simulatePath(int[] perm) {
        int r = startRow;
        int c = startCol;
        for (int i = 0; i < perm.length; i++) {
            int dir = perm[i];
            r += dr[dir];
            c += dc[dir];
            if (!inBounds(r, c)) {
                return false;
            }
            char cell = grid[r][c];
            if (cell == '#') {
                return false;
            }
            if (cell == 'E') {
                return true;                // reached the exit
            }
        }
        return false;   // ran out of moves without hitting ‘E’
    }

    /** Checks whether a cell coordinate is inside the grid. */
    private boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Directions: North, West, South, East */
    private static final int[] dr = {+1,  0, -1,  0};
    private static final int[] dc = { 0, -1,  0, +1};

    /** Generates all permutations of the supplied array and stores them in the container. */
    static void generatePermutations(int[] source, List<int[]> container) {
        permute(source, source.length, container);
    }

    /** Recursive permutation generator (classic Heap's algorithm). */
    private static void permute(int[] a, int n, List<int[]> out) {
        if (n == 1) {
            out.add(a.clone());
            return;
        }
        for (int i = 0; i < n; i++) {
            permute(a, n - 1, out);
            if (n % 2 == 0) {
                swap(a, i, n - 1);
            } else {
                swap(a, 0, n - 1);
            }
        }
    }

    private static void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }
}

/**
 * Driver class – reads input, prepares data, creates the solver and prints the answer.
 */
public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // ----- read grid dimensions -------------------------------------------------
        int n = fs.nextInt();          // number of rows
        int m = fs.nextInt();          // number of columns

        // ----- read the grid --------------------------------------------------------
        char[][] grid = new char[n][];
        int startRow = -1, startCol = -1;
        for (int i = 0; i < n; i++) {
            String line = fs.nextString();
            grid[i] = line.toCharArray();
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        // ----- read the command string (unused directly, just part of input) -------
        String commandString = fs.nextString();   // not needed for generation of perms

        // ----- generate all permutations of {0,1,2,3} ---------------------------------
        int[] base = {0, 1, 2, 3};
        List<int[]> permutations = new ArrayList<>(24);
        Solver.generatePermutations(base, permutations);

        // ----- create solver and compute answer ------------------------------------
        Solver solver = new Solver(grid, startRow, startCol, permutations);
        solver.solve(out);

        out.close();   // flush & close
    }
}

import java.io.PrintWriter;
import java.util.Arrays;

/**
 * Solves the “Path Finder” problem (originally B908).
 *
 * <p>It reads a grid containing a start cell ‘S’ and an end cell ‘E’
 * and a command string composed of digits that encode one of four
 * possible moves. By exploring all distinct permutations of the command
 * digits the program counts how many permutations lead from ‘S’ to ‘E’
 * without leaving the grid.</p>
 */
public class Solution {

    /* --------------------------------------------------------------
     *  Fast input reader – keeps the original speed while being easier
     *  to understand and maintain.
     * -------------------------------------------------------------- */
    private static final class FastScanner {
        private final byte[] buffer = new byte[1024];
        private int bufLen = 0;
        private int bufPos = 0;
        private final PrintWriter out = new PrintWriter(System.out, true);

        private byte readByte() {
            if (bufPos >= bufLen) {
                bufPos = 0;
                bufLen = System.in.read(buffer);
                if (bufLen <= 0) {
                    throw new IllegalStateException("End of input");
                }
            }
            return buffer[bufPos++];
        }

        private int skipSpaces() {
            int b;
            do {
                b = readByte();
            } while (b != -1 && (b < 33 || b > 126)); // any control char / space
            return b;
        }

        /** Reads next signed integer. */
        int nextInt() {
            long value = 0;
            boolean negative = false;
            int c = skipSpaces();
            if (c == '-') {
                negative = true;
                c = readByte();
            }
            while (c != -1 && c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return (int) (negative ? -value : value);
        }

        /** Reads next double. */
        double nextDouble() {
            return Double.parseDouble(nextToken());
        }

        /** Reads next token (non‑space characters). */
        private String nextToken() {
            StringBuilder sb = new StringBuilder();
            int b;
            do {
                b = skipSpaces();
            } while (b == -1);
            do {
                sb.append((char) b);
                b = readByte();
            } while (b != -1 && b > 32);
            return sb.toString();
        }

        char[] nextCharArray() {
            return nextToken().toCharArray();
        }
    }

    /* --------------------------------------------------------------
     *  Direction vectors used when interpreting a digit.
     *  0 → down, 1 → left, 2 → up, 3 → right.
     * -------------------------------------------------------------- */
    private static final int[][] OFFSETS = {
            { 1, 0},   // down  (0)
            { 0,-1},   // left  (1)
            { -1,0},   // up    (2)
            { 0, 1}    // right (3)
    };

    private final FastScanner fs = new FastScanner();
    private final PrintWriter out = new PrintWriter(System.out, true);

    /** Entry point – keeps method signatures small and testable. */
    public void solve() {
        int rows = fs.nextInt();
        int cols = fs.nextInt();

        // read the whole grid (rows × cols characters)
        char[][] grid = readGrid(rows);

        // read the command string
        char[] command = fs.nextCharArray();

        // locate start (S) and end (E) positions
        Position start = findPosition(grid, 'S');
        Position end   = findPosition(grid, 'E');

        // prepare permutation iterator for the four digits {0,1,2,3}
        int[] permutation = {0, 1, 2, 3};
        int reachableCount = 0;

        do {
            if (attemptPath(grid, start, end, command, permutation)) {
                reachableCount++;
            }
        } while (nextPermutation(permutation));

        out.println(reachableCount);
    }

    /** Reads exactly `rows` lines from the scanner, each containing `cols` characters. */
    private char[][] readGrid(int rows) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = fs.nextToken().toCharArray();
        }
        return grid;
    }

    /** Finds the coordinates of the first occurrence of `target` in the grid. */
    private Position findPosition(char[][] grid, char target) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == target) {
                    return new Position(r, c);
                }
            }
        }
        throw new IllegalStateException("Target cell not found");
    }

    /** Attempts to walk the path encoded by `command` when the digits are interpreted
     *  according to the current `permutation`. Returns true iff the walk:
     *  <ul>
     *      <li>stays completely inside the grid,
     *      <li>never steps on a wall ‘#’, and
     *      <li>either reaches the exit early or finishes without hitting a wall.
     *  </ul>
     */
    private boolean attemptPath(char[][] grid,
                                Position start,
                                Position end,
                                char[] command,
                                int[] permutation) {
        Position current = start;

        for (char ch : command) {
            int dirIdx = permutation[ch - '0'];               // map digit → direction
            int dr = OFFSETS[dirIdx][0];
            int dc = OFFSETS[dirIdx][1];

            current.row += dr;
            current.col += dc;

            if (!isInsideAndNotWall(grid, current.row, current.col)) {
                return false; // moved outside or hit a wall
            }

            if (grid[current.row][current.col] == 'E') {
                // Reached the exit – counting this permutation as successful.
                return true;
            }
        }

        // If we never stepped on ‘E’ during the walk, this permutation is not counted.
        return false;
    }

    /** Checks whether a cell (r, c) lies inside the grid and is not a wall. */
    private boolean isInsideAndNotWall(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length
                && c >= 0 && c < grid[r].length
                && grid[r][c] != '#';
    }

    /** Classic next‑permutation algorithm used to iterate over all distinct
     *  permutations of the four digits {0,1,2,3}. */
    private boolean nextPermutation(int[] a) {
        int n = a.length;
        int i = n - 2;
        while (i >= 0 && a[i] >= a[i + 1]) {
            i--;
        }
        if (i < 0) {
            return false; // no further permutations
        }
        int j = n - 1;
        while (a[i] >= a[j]) {
            j--;
        }
        swap(a, i, j);
        reverse(a, i + 1, n - 1);
        return true;
    }

    private void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    private void reverse(int[] arr, int from, int to) {
        while (from < to) {
            swap(arr, from++, to--);
        }
    }

    /** Simple holder for a grid coordinate. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /* --------------------------------------------------------------
     *  Boiler‑plate entry point – unchanged behaviour, only moved
     *  inside the class for better encapsulation.
     * -------------------------------------------------------------- */
    public static void main(String[] args) {
        new Solution().solve();
    }
}

import java.io.*;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Refactored solution for the maze‑permutation problem.
 *
 * The program reads a rectangular grid surrounded by a border of '#',
 * locate the start cell 'S', reads a sequence of direction digits,
 * and counts how many permutations of the four cardinal directions
 * lead from 'S' to the exit 'E' while following the digit sequence.
 */
public class Main {

    private static final char WALL   = '#';
    private static final char START  = 'S';
    private static final char EXIT   = 'E';

    private static int n, m;                 // inner grid dimensions
    private static char[][] grid;             // full grid including border
    private static int startRow, startCol;    // coordinates of 'S' (including border)
    private static String moveSequence;      // sequence of direction digits

    // Four basic moves: up, down, left, right
    private static final int[][] DIR = {
            {0, -1},   // up
            {0, 1},    // down
            {-1, 0},   // left
            {1, 0}     // right
    };

    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees the reader is closed
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // ---------- 1. Read grid size ----------
            StringTokenizer st = new StringTokenizer(br.readLine());
            n = Integer.parseInt(st.nextToken());
            m = Integer.parseInt(st.nextToken());

            // ---------- 2. Build bordered grid ----------
            grid = new char[n + 2][];
            grid[0] = borderRow(50);                     // top border
            for (int i = 1; i <= n; i++) {
                String line = br.readLine();
                String bordered = "#" + line + "#";
                grid[i] = bordered.toCharArray();
                locateStart(bordered, i);                // remember 'S' position
            }
            grid[n + 1] = borderRow(50);                 // bottom border

            // ---------- 3. Read move sequence ----------
            moveSequence = (br.readLine() != null) ? br.readLine().trim() : "";

            // ---------- 4. Count valid direction permutations ----------
            int answer = countValidPermutations();
            System.out.println(answer);
        }
    }

    /** Scans a bordered line for the start cell and records its coordinates. */
    private static void locateStart(String bordered, int rowIndex) {
        char[] row = bordered.toCharArray();
        outer:
        for (int col = 1; col <= m; col++) {
            if (row[col] == START) {
                startRow = rowIndex;
                startCol = col;
                break outer;
            }
        }
    }

    /** Generates a row filled with the wall character. */
    private static char[] borderRow(int length) {
        char[] row = new char[length];
        Arrays.fill(row, WALL);
        return row;
    }

    /** Counts how many permutations of the four directions succeed. */
    private static int countValidPermutations() {
        int[] indices = {0, 1, 2, 3};   // direction indices to permute
        int[] counter = {0};            // mutable counter for recursion
        permute(indices, 0, counter);
        return counter[0];
    }

    /** Recursive back‑tracking that generates all permutations of `arr`. */
    private static void permute(int[] arr, int depth, int[] counter) {
        if (depth == arr.length) {
            if (simulatePermutation(arr)) {
                counter[0]++;
            }
            return;
        }
        for (int i = depth; i < arr.length; i++) {
            swap(arr, depth, i);
            permute(arr, depth + 1, counter);
            swap(arr, depth, i); // backtrack
        }
    }

    /** Simple element swap. */
    private static void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    /** Simulates one permutation according to the move sequence. */
    private static boolean simulatePermutation(int[] perm) {
        int x = startRow;
        int y = startCol;

        for (int pos = 0; pos < moveSequence.length(); pos++) {
            char digitChar = moveSequence.charAt(pos);
            int digit = digitChar - '0';
            // Guard against malformed digits
            if (digit < 0 || digit > 3) {
                return false;
            }
            int dirIdx = perm[digit];            // direction vector for this digit
            int[] d = DIR[dirIdx];
            x += d[0];
            y += d[1];

            if (grid[x][y] == WALL) {
                return false;                    // hit a wall → failure
            }
            if (grid[x][y] == EXIT) {
                return true;                     // reached exit → success
            }
        }
        return false;                            // sequence ended without exit
    }
}

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

/**
 * Refactored version of the original program.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Clear separation of concerns (input handling, permutation generation,
 *       simulation, etc.).
 *   <li>Descriptive naming and constant usage.
 *   <li>Elimination of static mutable global state.
 *   <li>Use of try‑with‑resources for the {@link Scanner}.
 *   <li>Extraction of helper methods with single responsibilities.
 *   <li>Addition of explanatory comments and JavaDoc.
 * </ul>
 *
 * <p>The program reads a maze, finds the start position ('S'), then evaluates
 * all permutations of direction mappings (0‑3) to determine how many permutations
 * allow reaching the exit ('E') when following the supplied process string.
 */
public class MazeSolver {

    /** Directions: up, down, right, left */
    private static final int[][] DIRECTIONS = {
            { -1, 0 },   // UP
            { 1, 0 },    // DOWN
            { 0, 1 },    // RIGHT
            { 0, -1 }    // LEFT
    };
    private static final char START_MARK = 'S';
    private static final char EXIT_MARK = 'E';
    private static final char WALL_MARK = '#';

    public static void main(String[] args) {
        /* --------------------------------------------------------------
         * 1️⃣  Input handling
         * -------------------------------------------------------------- */
        try (Scanner scanner = new Scanner(System.in)) {

            // ----- dimensions & grid -------------------------------------------------
            String[] sizeTokens = scanner.nextLine().trim().split("\\s+");
            int rows = Integer.parseInt(sizeTokens[0]);
            int cols = Integer.parseInt(sizeTokens[1]);

            char[][] grid = new char[rows][];
            int startRow = -1, startCol = -1;

            for (int r = 0; r < rows; r++) {
                String line = scanner.nextLine();
                grid[r] = line.toCharArray();
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == START_MARK) {
                        startRow = r;
                        startCol = c;
                    }
                }
            }

            // ----- process string ----------------------------------------------------
            String process = scanner.nextLine().trim();

            /* --------------------------------------------------------------
             * 2️⃣  Generate all permutations of the digits 0‑3 (24 in total)
             * -------------------------------------------------------------- */
            List<String> permutations = generateAllPermutations();

            /* --------------------------------------------------------------
             * 3️⃣  Evaluate each permutation
             * -------------------------------------------------------------- */
            int successCount = 0;
            for (String perm : permutations) {
                if (simulateAndCheckExit(grid, startRow, startCol, process, perm)) {
                    successCount++;
                }
            }

            System.out.println(successCount);
        }
    }

    /** Generates every permutation of the characters '0'–'3'. */
    private static List<String> generateAllPermutations() {
        List<String> result = new ArrayList<>();
        backtrack(0, new char[4], new HashSet<>(), result);
        return result;
    }

    /** Recursive back‑tracking helper that fills {@code current} and adds completed
     *  permutations to {@code collector}. */
    private static void backtrack(int index, char[] current, Set<Character> used, List<String> collector) {
        if (index == current.length) {
            collector.add(new String(current));
            return;
        }
        for (int digit = 0; digit < current.length; digit++) {
            char candidate = (char) ('0' + digit);
            if (used.contains(candidate)) {
                continue;
            }
            used.add(candidate);
            current[index] = candidate;
            backtrack(index + 1, current, used, collector);
            used.remove(candidate);
        }
    }

    /**
     * Simulates movement according to {@code process} using the supplied
     * {@code permutation} as a direction‑mapping, and checks whether the exit
     * ('E') is reached.
     *
     * @return {@code true} if the exit is reached, otherwise {@code false}.
     */
    private static boolean simulateAndCheckExit(char[][] grid,
                                               int startRow,
                                               int startCol,
                                               String process,
                                               String permutation) {
        // Build a mapping: original direction index (0‑3) → actual direction from permutation
        int[] directionMap = new int[4];
        for (int i = 0; i < 4; i++) {
            directionMap[i] = DIRECTIONS[ permutation.charAt(i) - '0' ];
        }

        int row = startRow;
        int col = startCol;

        for (char step : process.toCharArray()) {
            int originalDirIdx = step - '0';          // digit represented by the step
            int[] delta = directionMap[originalDirIdx]; // real step to take
            int nextRow = row + delta[0];
            int nextCol = col + delta[1];

            // Boundary check
            if (nextRow < 0 || nextRow >= grid.length ||
                nextCol < 0 || nextCol >= grid[0].length) {
                return false;
            }

            char nextCell = grid[nextRow][nextCol];
            if (nextCell == WALL_MARK) {
                return false;
            }
            if (nextCell == EXIT_MARK) {
                return true; // success – we have hit the exit
            }

            // Continue moving
            row = nextRow;
            col = nextCol;
        }
        return false; // process finished without reaching 'E'
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the program.
 * Reads input, solves the problem and prints the answer.
 */
public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Solver().solve(1, in, out);
        out.close();
    }

    /** Small utility class that encapsulates all problem‑specific logic. */
    static class Solver {
        private static final int UP = 0;
        private static final int LEFT = 1;
        private static final int RIGHT = 2;
        private static final int DOWN = 3;

        private static final List<Integer> ALL_DIRECTIONS =
                List.of(UP, LEFT, RIGHT, DOWN);

        private int rows, cols;
        private boolean[][] reachable;   // true = walkable cell
        private int sr, sc, er, ec;        // start / end coordinates
        private int[] commands;           // sequence of direction codes (0‑3)

        /**
         * Solves one test case.
         *
         * @param testNumber the test case number (unused here)
         * @param scanner    input scanner
         * @param out        output printer
         */
        void solve(int testNumber, FastScanner scanner, PrintWriter out) {
            readInput(scanner);
            int ans = countSuccessfulPermutations();
            out.println(ans);
        }

        /** Parses the whole input and stores it in the instance fields. */
        private void readInput(FastScanner in) {
            rows = in.nextInt();
            cols = in.nextInt();
            reachable = new boolean[rows][cols];

            // Read grid and locate start / end cells
            for (int r = 0; r < rows; r++) {
                char[] line = in.next().toCharArray();
                for (int c = 0; c < cols; c++) {
                    if (line[c] == '#') {
                        continue;                     // obstacle
                    }
                    reachable[r][c] = true;           // free cell
                    if (line[c] == 'S') {
                        sr = r;
                        sc = c;
                    } else if (line[c] == 'E') {
                        er = r;
                        ec = c;
                    }
                }
            }

            // Read the command string (digits 0‑3) and convert to ints
            char[] cmdChars = in.next().toCharArray();
            commands = new int[cmdChars.length];
            for (int i = 0; i < cmdChars.length; i++) {
                commands[i] = cmdChars[i] - '0';
            }
        }

        /** Returns the number of direction permutations that lead from S to E. */
        private int countSuccessfulPermutations() {
            int successful = 0;

            // Generate all 24 permutations of the four direction constants
            List<Integer> base = new ArrayList<>(ALL_DIRECTIONS);
            do {
                if (canReachUsingPermutation(base)) {
                    successful++;
                }
            } while (nextPermutation(base));

            return successful;
        }

        /** Simulates the movement according to the given permutation. */
        private boolean canReachUsingPermutation(List<Integer> perm) {
            int r = sr, c = sc;
            if (!reachable[r][c]) {
                return false; // starting cell must be walkable
            }

            for (int cmd : commands) {
                int dir = perm.get(cmd); // direction that cmd represents now
                switch (dir) {
                    case UP -> r--;
                    case LEFT -> c--;
                    case RIGHT -> c++;
                    case DOWN -> r++;
                    default -> throw new AssertionError("Invalid direction: " + dir);
                }

                // Out of bounds or blocked → failure
                if (r < 0 || r >= rows || c < 0 || c >= cols || !reachable[r][c]) {
                    return false;
                }

                // Reached the exit → success
                if (r == er && c == ec) {
                    return true;
                }
            }
            return false; // ran out of commands without reaching the exit
        }

        /** Simple next‑permutation algorithm for a list of Comparable objects. */
        private boolean nextPermutation(List<Integer> list) {
            int n = list.size();
            // 1. Find the longest non‑increasing suffix
            int i = n - 2;
            while (i >= 0 && list.get(i) >= list.get(i + 1)) {
                i--;
            }
            if (i < 0) {
                return false; // no more permutations
            }

            // 2. Find rightmost element that is greater than pivot
            int j = n - 1;
            while (list.get(j) <= list.get(i)) {
                j--;
            }

            // 3. Swap pivot with that element
            Collections.swap(list, i, j);

            // 4. Reverse the suffix
            reverse(list, i + 1, n - 1);
            return true;
        }

        private void reverse(List<Integer> list, int from, int to) {
            while (from < to) {
                Collections.swap(list, from++, to--);
            }
        }
    }

    /**
     * Fast scanner based on a buffered byte array.
     * It works with any character encoding supported by the underlying InputStream.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[16 * 1024];
        private int bytesRead = 0;
        private int currentByte = 0;
        private int currentChar = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (currentByte >= bytesRead) {
                bytesRead = stream.read(buffer);
                currentByte = 0;
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[currentByte++];
        }

        /** Skips leading whitespace characters. */
        private int skipWhitespace() throws IOException {
            int b;
            while ((b = readByte()) != -1 && isSpaceChar(b)) {
                // consume
            }
            return b;
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads the next token (non‑whitespace characters). */
        String next() throws IOException {
            int c = skipWhitespace();
            if (c == -1) {
                return "";
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        /** Reads a line terminated by '\n' or '\r'. */
        String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int b;
            while ((b = readByte()) != -1 && b != '\n' && b != '\r') {
                sb.append((char) b);
            }
            return sb.toString();
        }

        /** Reads the next integer from the input. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;

/**
 * Scorify – counts how many permutations of the four compass directions
 * (D, U, R, L) map the digits 0‑3 such that following the instruction
 * string leads from the start cell 'S' to the end cell 'E' without
 * stepping on walls '#'.
 *
 * The program keeps the original input format but rewrites the
 * implementation for readability, maintainability and testability.
 */
public class Scorify {

    /** Direction vector for the four compass moves. */
    private enum Direction {
        DOWN(1, 0),
        UP(-1, 0),
        RIGHT(0, 1),
        LEFT(0, -1);

        final int rowDelta;
        final int colDelta;

        Direction(int rowDelta, int colDelta) {
            this.rowDelta = rowDelta;
            this.colDelta = colDelta;
        }
    }

    /** Very small, fast scanner that works with BufferedInputStream. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int bytePointer = 0;
        private int bytesRead = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte, returning -1 on EOF. */
        private int readByte() {
            if (bytePointer >= bytesRead) {
                bytePointer = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[bytePointer++];
        }

        /** Skips whitespace characters. */
        private int skipWhiteSpace() {
            int b;
            do {
                b = readByte();
            } while (!isSpace(b));
            return b;
        }

        private boolean isSpace(int b) {
            return b == ' ' || b == '\n' || b == '\r' || b == '\t' || b == -1;
        }

        /** Reads the next non‑whitespace token as a string. */
        String next() {
            int c = skipWhiteSpace();
            if (c == -1) {
                return "";
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = readByte();
            } while (!isSpace(c));
            return sb.toString();
        }

        /** Reads the next integer. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Generates all 24 permutations of the four directions. */
    private static List<Direction[]> allDirectionMappings() {
        Direction[] base = {Direction.DOWN, Direction.UP, Direction.RIGHT, Direction.LEFT};
        List<Direction[]> result = new ArrayList<>(24);

        // Java does not have a built‑in permutation generator for arrays,
        // so we use the classic next_permutation algorithm.
        List<Direction[]> permutations = new ArrayList<>();
        permutationHelper(base, 0, permutations);
        result.addAll(permutations);
        return result;
    }

    private static void permutationHelper(Direction[] arr, int k, List<Direction[]> out) {
        if (k == arr.length) {
            out.add(copy(arr));
            return;
        }
        for (int i = k; i < arr.length; i++) {
            swap(arr, k, i);
            permutationHelper(arr, k + 1, out);
            swap(arr, k, i); // backtrack
        }
    }

    private static Direction[] copy(Direction[] src) {
        Direction[] dest = new Direction[src.length];
        System.arraycopy(src, 0, dest, 0, src.length);
        return dest;
    }

    private static void swap(Direction[] a, int i, int j) {
        Direction tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);

        // ----- read grid dimensions and the grid itself -----
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        int startRow = -1, startCol = -1;
        int endRow = -1, endCol = -1;

        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            // replace the symbolic markers with '.' for uniform obstacle handling
            line = line.replace('S', '.').replace('E', '.');
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
                if (line.charAt(c) == 'S') {
                    startRow = r;
                    startCol = c;
                } else if (line.charAt(c) == 'E') {
                    endRow = r;
                    endCol = c;
                }
            }
        }

        // ----- read the instruction string (digits 0‑3) -----
        String moves = scanner.next();

        // ----- generate all possible digit → direction mappings -----
        List<Direction[]> mappings = allDirectionMappings();

        int validMappingCount = 0;

        for (Direction[] mapping : mappings) {
            // map digit index (0‑3) to its Direction
            Direction[] digitToDirection = new Direction[4];
            for (int i = 0; i < 4; i++) {
                digitToDirection[i] = mapping[i];
            }

            // simulate the walk
            int curRow = startRow;
            int curCol = startCol;
            boolean reachedEnd = false;

            for (int i = 0; i < moves.length(); i++) {
                char digitChar = moves.charAt(i);
                int digit = digitChar - '0';
                if (digit < 0 || digit > 3) {
                    // unexpected character – abort this permutation
                    break;
                }

                Direction dir = digitToDirection[digit];
                int nextRow = curRow + dir.rowDelta;
                int nextCol = curCol + dir.colDelta;

                // check bounds and obstacle
                if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols
                        || grid[nextRow][nextCol] == '#') {
                    break; // hit a wall or left the board
                }

                curRow = nextRow;
                curCol = nextCol;

                if (curRow == endRow && curCol == endCol) {
                    reachedEnd = true;
                    break; // success – no need to process further moves
                }
            }

            if (reachedEnd) {
                validMappingCount++;
            }
        }

        System.out.println(validMappingCount);
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the CodeChef problem.
 * <p>
 * The program reads a grid, a start cell 'S', a target cell 'E',
 * and a string of movement instructions.  For every permutation of
 * the four cardinal directions (up, down, left, right) it checks
 * whether following the instructions leads from 'S' to 'E' without
 * leaving the grid or hitting a wall '#'.
 * </p>
 */
public class CodechefSolution {

    /* --------------------------------------------------------------------- */
    /*                         CONSTANTS & HELPERS                           */
    /* --------------------------------------------------------------------- */

    /** Mapping from direction index to its (rowDelta, colDelta). */
    private static final Map<Integer, int[]> DIR_MAP = Map.of(
            0, new int[]{0, -1},   // up
            1, new int[]{0, 1},    // down
            2, new int[]{-1, 0},   // left
            3, new int[]{1, 0}     // right
    );

    /** All 24 possible permutations of the four direction vectors. */
    private static final List<int[][]> ALL_DIRECTION_ORDERS = generateAllDirectionOrders();

    /** Simple container for a cell coordinate. */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Generates every permutation of the four direction vectors. */
    private static List<int[][]> generateAllDirectionOrders() {
        List<int[][]> result = new ArrayList<>();
        int[] indices = {0, 1, 2, 3};

        do {
            int[][] order = new int[4][2];
            for (int i = 0; i < 4; i++) {
                order[i] = DIR_MAP.get(indices[i]);
            }
            result.add(order);
        } while (nextPermutation(indices));

        return result;
    }

    /** Classic next‑permutation algorithm (in‑place). */
    private static boolean nextPermutation(int[] a) {
        int i = a.length - 2;
        while (i >= 0 && a[i] >= a[i + 1]) i--;
        if (i < 0) return false;

        int j = a.length - 1;
        while (a[j] <= a[i]) j--;

        swap(a, i, j);
        reverse(a, i + 1, a.length - 1);
        return true;
    }

    private static void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    private static void reverse(int[] a, int left, int right) {
        while (left < right) {
            swap(a, left++, right--);
        }
    }

    /* --------------------------------------------------------------------- */
    /*                         CORE LOGIC                                    */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) throws Exception {
        try (FastReader reader = new FastReader();
             PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out))) {

            // ----- input -------------------------------------------------------
            int n = reader.nextInt();               // number of rows
            int m = reader.nextInt();               // number of columns (unused, kept for compatibility)
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }
            String instructions = reader.next();    // movement string

            // ----- locate start cell 'S' ---------------------------------------
            Cell start = findCell(grid, 'S');

            // ----- evaluate every direction permutation -----------------------
            int successful = 0;
            for (int[][] dirOrder : ALL_DIRECTION_ORDERS) {
                if (simulatePath(grid, start, instructions, dirOrder)) {
                    successful++;
                }
            }

            // ----- output ------------------------------------------------------
            writer.println(successful);
        }
    }

    /** Finds the first occurrence of the given symbol in the grid. */
    private static Cell findCell(char[][] grid, char symbol) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == symbol) {
                    return new Cell(r, c);
                }
            }
        }
        throw new IllegalStateException("Start cell 'S' not found");
    }

    /** Determines whether the supplied direction order leads from start to 'E'. */
    private static boolean simulatePath(char[][] grid,
                                        Cell start,
                                        String instructions,
                                        int[][] dirOrder) {
        int r = start.row;
        int c = start.col;

        for (char ch : instructions.toCharArray()) {
            int dirIdx = Character.getNumericValue(ch);
            if (dirIdx < 0 || dirIdx > 3) {
                return false;                     // invalid digit in instructions
            }

            int[] d = dirOrder[dirIdx];
            r += d[0];
            c += d[1];

            if (!isInside(grid, r, c)) return false;          // out of bounds
            if (grid[r][c] == '#') return false;               // hit a wall
            if (grid[r][c] == 'E') return true;                 // reached exit
        }
        return false;                                          // never reached 'E'
    }

    /** Checks whether (row, col) lies inside the grid. */
    private static boolean isInside(char[][] grid, int row, int col) {
        return row >= 0 && row < grid.length &&
               col >= 0 && col < grid[0].length;
    }

    /* --------------------------------------------------------------------- */
    /*                         FAST INPUT CLASS                              */
    /* --------------------------------------------------------------------- */

    /** Minimal fast scanner based on BufferedReader and StringTokenizer. */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** Simple scanner that tokenises lines from standard input. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(Reader source) {
            this.reader = new BufferedReader(source);
        }

        private void ensureTokens() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return;
                }
                tokenizer = new StringTokenizer(line);
            }
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        String next() throws IOException {
            ensureTokens();
            return tokenizer.nextToken();
        }
    }

    /** Executes the solution. */
    public static void main(String[] args) throws Exception {
        new Solution().run();
    }

    /** Reads input, processes it and prints the answer. */
    private void run() throws Exception {
        FastScanner scanner = new FastScanner(System.in);
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][];
        int startR = -1, startC = -1;

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startR = i;
                    startC = j;
                }
            }
        }

        String moveSequence = scanner.next(); // e.g. "0123"

        int answer = countSuccessfulTriples(grid, startR, startC, moveSequence);
        System.out.println(answer);
    }

    /**
     * Determines how many ordered triples of distinct direction codes
     * (u,d,l) allow the robot to reach an exit cell 'E' while following the
     * supplied move sequence.
     */
    private int countSuccessfulTriples(char[][] grid, int sr, int sc, String seq) {
        int successful = 0;

        // iterate over all ordered triples of distinct codes 0‑3
        for (int u = 0; u < 4; u++) {
            for (int d = 0; d < 4; d++) {
                if (d == u) continue;
                for (int l = 0; l < 4; l++) {
                    if (l == u || l == d) continue;

                    if (simulatePath(grid, sr, sc, seq, u, d, l)) {
                        successful++;
                    }
                }
            }
        }
        return successful;
    }

    /**
     * Simulates the robot moving according to {@code seq}. The numeric
     * direction codes are interpreted as:
     * <ul>
     *   <li>{@code u} – move left  (column‑1)</li>
     *   <li>{@code d} – move right (column+1)</li>
     *   <li>{@code l} – move up    (row‑1)</li>
     *   <li>any other code – move down (row+1)</li>
     * </ul>
     * The method returns {@code true} if the path reaches an 'E' cell before
     * hitting a wall or leaving the board.
     */
    private boolean simulatePath(char[][] grid, int r, int c, String seq,
                                 int uCode, int dCode, int lCode) {
        for (int i = 0; i < seq.length(); i++) {
            int dir = seq.charAt(i) - '0';

            if (dir == uCode) {
                c--;                       // left
            } else if (dir == dCode) {
                c++;                       // right
            } else if (dir == lCode) {
                r--;                       // up
            } else {
                r++;                       // down (the remaining direction)
            }

            // Check for out‑of‑bounds or obstacle
            if (!isInside(r, c, grid.length, grid[0].length) || grid[r][c] == '#') {
                return false;
            }

            // Success condition
            if (grid[r][c] == 'E') {
                return true;
            }
        }
        return false; // reached end of sequence without finding 'E'
    }

    /** Utility method that checks whether a cell lies inside the grid. */
    private boolean isInside(int row, int col, int rows, int cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for problem “B”.
 *
 * <p>
 * The program reads a grid that contains a start cell {@code S}, an end cell {@code E}
 * and walls {@code #}. It then receives a sequence of digits {@code 0‑3}. For every
 * distinct permutation of those four digits a different mapping to the four
 * directions {@code u/d/l/r} is tried. For each mapping the program follows the
 * direction sequence from the start cell and counts how many mappings lead
 * directly to the end cell without hitting a wall or leaving the board.
 * </p>
 */
public class B {

    /** Characters that represent the four possible moves. */
    private static final String DIRECTIONS = "udlr";

    /** Symbol used for walls in the grid. */
    private static final char WALL = '#';

    /** The whole grid read from input. */
    private static char[][] grid;

    /** Board dimensions. */
    private static int rows, cols;

    /** Coordinates of the start and end cells. */
    private static int startR, startC, endR, endC;

    /** Entry point. */
    public static void main(String[] args) {
        try (FastScanner fs = new FastScanner()) {
            rows = fs.nextInt();
            cols = fs.nextInt();

            grid = new char[rows][cols];
            readGrid(fs);
            String directionSequence = fs.next();

            int reachableCount = countReachableMappings(directionSequence);
            System.out.println(reachableCount);
        }
    }

    /** Reads the grid while remembering where {@code S} and {@code E} are. */
    private static void readGrid(FastScanner fs) {
        for (int r = 0; r < rows; r++) {
            String line = fs.next();
            for (int c = 0; c < cols; c++) {
                char cell = line.charAt(c);
                grid[r][c] = cell;

                if (cell == 'S') {
                    startR = r;
                    startC = c;
                } else if (cell == 'E') {
                    endR = r;
                    endC = c;
                }
            }
        }
    }

    /** Tries every distinct permutation of 0‑3 and counts successful mappings. */
    private static int countReachableMappings(String dirSequence) {
        int[] indices = {0, 1, 2, 3};
        int count = 0;

        do {
            if (simulateWithPermutation(dirSequence, indices)) {
                count++;
            }
        } while (nextPermutation(indices));

        return count;
    }

    /** Executes the direction sequence using the current permutation. */
    private static boolean simulateWithPermutation(String dirSequence, int[] perm) {
        int r = startR;
        int c = startC;

        for (char digit : dirSequence.toCharArray()) {
            char move = mapDigitToDirection(digit, perm);
            int[] newPos = applyMove(r, c, move);
            r = newPos[0];
            c = newPos[1];

            if (isOutOfBounds(r, c) || grid[r][c] == WALL) {
                return false;
            }
            if (r == endR && c == endC) {
                return true;
            }
        }
        return false;
    }

    /** Maps a digit character to a concrete direction character. */
    private static char mapDigitToDirection(char digit, int[] perm) {
        return DIRECTIONS.charAt(perm[digit - '0']);
    }

    /** Performs the step indicated by {@code move}. Returns the new coordinates. */
    private static int[] applyMove(int r, int c, char move) {
        return switch (move) {
            case 'u' -> new int[]{r - 1, c};
            case 'd' -> new int[]{r + 1, c};
            case 'l' -> new int[]{r, c - 1};
            case 'r' -> new int[]{r, c + 1};
            default -> new int[]{-1, -1}; // never happens
        };
    }

    /** Checks whether a cell lies outside the board borders. */
    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    /** Generates the next lexicographic permutation of the array (in‑place). */
    private static boolean nextPermutation(int[] a) {
        int n = a.length;
        int i = n - 2;
        while (i >= 0 && a[i] >= a[i + 1]) i--;

        if (i < 0) return false; // last permutation reached

        int j = n - 1;
        while (a[j] <= a[i]) j--;

        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;

        // reverse suffix
        int left = i + 1, right = n - 1;
        while (left < right) {
            int t = a[left];
            a[left++] = a[right];
            a[right--] = t;
        }
        return true;
    }

    /** Simple fast scanner that works with standard input. */
    static class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next whitespace‑separated token. */
        private String token() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Retrieves the next integer from the input. */
        int nextInt() {
            return Integer.parseInt(token());
        }

        /** Retrieves the next token as a string (used for the direction sequence). */
        String next() {
            return token();
        }

        /** Closes the underlying reader. */
        @Override
        public void close() {
            try {
                br.close();
            } catch (IOException ignored) {
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Main class that reads a grid, a start cell 'S', an end cell 'E' and a pattern string.
 * For every permutation of the four directions (0‑up, 1‑down, 2‑right, 3‑left) it checks
 * whether following the digits of the pattern according to that permutation leads
 * from 'S' to 'E'. The number of successful permutations is printed.
 */
public class Main {

    /** Directions: up, down, right, left */
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    /** Fast input scanner */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in), 32768);
            tokenizer = null;
        }

        private void ensureTokenizer() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
        }

        String next() {
            ensureTokenizer();
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Generates all permutations of the array [0,1,2,3] */
    private static List<int[]> allPermutations() {
        List<int[]> perms = new ArrayList<>(24);
        for (int a = 0; a < 4; a++) {
            for (int b = 0; b < 4; b++) {
                if (b == a) continue;
                for (int c = 0; c < 4; c++) {
                    if (c == a || c == b) continue;
                    for (int d = 0; d < 4; d++) {
                        if (d == a || d == b || d == c) continue;
                        perms.add(new int[]{a, b, c, d});
                    }
                }
            }
        }
        return perms;
    }

    /**
     * Simulates following the pattern using the supplied direction permutation.
     *
     * @param grid       character grid
     * @param pattern    pattern string (digits '0'‑'3')
     * @param dirMap     permutation mapping digit → direction index
     * @param startR     starting row
     * @param startC     starting column
     * @return true if the simulation reaches 'E' at any point
     */
    private static boolean canReach(char[][] grid,
                                    String pattern,
                                    int[] dirMap,
                                    int startR,
                                    int startC) {
        int r = startR;
        int c = startC;

        // If the start cell itself is 'E' we are already done
        if (grid[r][c] == 'E') {
            return true;
        }

        for (int i = 0; i < pattern.length(); i++) {
            char digit = pattern.charAt(i);
            int dirIdx = dirMap[digit - '0'];          // direction to move
            r += DR[dirIdx];
            c += DC[dirIdx];

            // Out of bounds or blocked cell
            if (r < 0 || c < 0 || r >= grid.length || c >= grid[0].length || grid[r][c] == '#') {
                return false;
            }

            // Reached the end cell – success regardless of remaining pattern
            if (grid[r][c] == 'E') {
                return true;
            }
        }
        // Pattern exhausted without hitting 'E'
        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int n = sc.nextInt();               // number of rows
        int m = sc.nextInt();               // number of columns
        char[][] grid = new char[n][];
        int startRow = -1, startCol = -1;

        // read grid and locate the start cell 'S'
        for (int i = 0; i < n; i++) {
            String rowStr = sc.next();
            grid[i] = rowStr.toCharArray();
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        String pattern = sc.next();         // pattern of digits
        List<int[]> permutations = allPermutations();

        int successfulPermutations = 0;
        for (int[] dirMap : permutations) {
            if (canReach(grid, pattern, dirMap, startRow, startCol)) {
                successfulPermutations++;
            }
        }

        out.println(successfulPermutations);
        out.flush();
    }
}

import java.io.*;
import java.util.*;

public class CFB {

    /* -------------------------------------------------
       Constants representing the four possible moves
       ------------------------------------------------- */
    private static final int DOWN = 0;
    private static final int RIGHT = 1;
    private static final int LEFT = 2;
    private static final int UP = 3;

    /** Encapsulates all solving logic */
    private static class Solver {
        private final char[][] grid;
        private final int rows, cols;
        private final String commands;
        private final int[] start = new int[2];
        private final int[] end = new int[2];
        private int answer = 0;

        Solver(char[][] grid, int rows, int cols, String commands) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.commands = commands;
        }

        void solve() {
            locateStartAndEnd();
            generateAssignments();
            System.out.println(answer);
        }

        private void locateStartAndEnd() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    char ch = grid[r][c];
                    if (ch == 'S') {
                        start[0] = r;
                        start[1] = c;
                    } else if (ch == 'E') {
                        end[0] = r;
                        end[1] = c;
                    }
                }
            }
        }

        /** Tries every permutation of the four directions for digits 0‑3 */
        private void generateAssignments() {
            boolean[] used = new boolean[4];
            int[] current = new int[4];
            backtrack(0, used, current);
        }

        private void backtrack(int depth, boolean[] used, int[] current) {
            if (depth == 4) {
                if (runSimulation(current)) {
                    answer++;
                }
                return;
            }

            for (int dir = 0; dir < 4; dir++) {
                if (!used[dir]) {
                    used[dir] = true;
                    current[depth] = dir;
                    backtrack(depth + 1, used, current);
                    used[dir] = false;
                }
            }
        }

        /** Executes the command string with the supplied direction mapping */
        private boolean runSimulation(int[] directionMap) {
            int r = start[0];
            int c = start[1];

            for (char ch : commands.toCharArray()) {
                int dirIdx = directionMap[ch - '0']; // digit 0‑3 -> direction index
                int[] nrnc = step(r, c, dirIdx);
                if (nrnc == null) {               // hit a wall or border
                    return false;
                }
                r = nrnc[0];
                c = nrnc[1];
                if (r == end[0] && c == end[1]) {
                    return true;                  // reached the goal
                }
            }
            return false;
        }

        /** Returns new coordinates after a step, or null if the move is illegal */
        private int[] step(int r, int c, int dirIdx) {
            switch (dirIdx) {
                case DOWN -> {
                    if (r + 1 >= rows || grid[r + 1][c] == '#') return null;
                    return new int[]{r + 1, c};
                }
                case RIGHT -> {
                    if (c + 1 >= cols || grid[r][c + 1] == '#') return null;
                    return new int[]{r, c + 1};
                }
                case LEFT -> {
                    if (c == 0 || grid[r][c - 1] == '#') return null;
                    return new int[]{r, c - 1};
                }
                case UP -> {
                    if (r == 0 || grid[r - 1][c] == '#') return null;
                    return new int[]{r - 1, c};
                }
            }
            return null; // should never happen
        }
    }

    /** Fast scanner that reads tokens from standard input */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = stream.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private boolean isSpace(int b) {
            return b == ' ' || b == '\n' || b == '\r' || b == '\t';
        }

        String next() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c != -1 && !isSpace(c));
            if (c == -1) return "";
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (c != -1 && !isSpace(c));
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner in = new FastScanner(System.in);

        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = in.next();
            grid[r] = line.toCharArray();
        }
        String cmd = in.next(); // digit sequence

        new Solver(grid, rows, cols, cmd).solve();
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Separated concerns into small, focused methods and classes.</li>
 *   <li>Used meaningful identifiers (e.g. {@code GridInfo}, {@code Pos},
 *       {@code Direction}).</li>
 *   <li>Encapsulated grid dimensions and input handling.</li>
 *   <li>Replaced the cryptic nested loops that built a mapping with a
 *       dedicated {@link PermutationGenerator}.</li>
 *   <li>Extracted the path‑simulation logic into its own method.</li>
 *   <li>Added JavaDoc comments and inline comments for readability.</li>
 *   <li>Made the code easier to test and maintain.</li>
 * </ul>
 */
public class Main {

    /** Character used to denote a wall in the grid. */
    private static final char WALL = '#';

    /** Scanner that reads from standard input (single shared instance). */
    private static final Scanner SCANNER = new Scanner(System.in);

    /** Entry point of the program. */
    public static void main(String[] args) {
        GridInfo gridInfo = readInput();
        Pos start = findPosition(gridInfo.grid, 'S');
        Pos end   = findPosition(gridInfo.grid, 'E');

        int successfulPermutations = countSuccessfulPermutations(
                gridInfo.directions,
                start,
                end,
                gridInfo.grid);

        System.out.println(successfulPermutations);
    }

    /** Reads all input from {@code System.in} and returns a {@link GridInfo} object. */
    private static GridInfo readInput() {
        int rows = SCANNER.nextInt();
        int cols = SCANNER.nextInt();
        SCANNER.nextLine();                 // consume the line break after the numbers

        String[] grid = new String[rows];
        for (int r = 0; r < rows; r++) {
            grid[r] = SCANNER.nextLine();
        }

        String directions = SCANNER.nextLine();
        return new GridInfo(grid, directions);
    }

    /** Finds the first occurrence of {@code target} in the grid and returns its position. */
    private static Pos findPosition(String[] grid, char target) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length(); c++) {
                if (grid[r].charAt(c) == target) {
                    return new Pos(r, c);
                }
            }
        }
        throw new IllegalArgumentException("Target character not found in grid");
    }

    /** Counts how many of the 24 permutations of movement indices lead to the end position. */
    private static int countSuccessfulPermutations(String directionString,
                                                     Pos start,
                                                     Pos end,
                                                     String[] grid) {
        int successful = 0;
        for (int[] perm : PermutationGenerator.ALL) {
            successful += simulatePath(directionString, start, end, grid, perm);
        }
        return successful;
    }

    /** Simulates a single permutation and returns 1 if the end is reached, otherwise 0. */
    private static int simulatePath(String dirString,
                                     Pos start,
                                     Pos end,
                                     String[] grid,
                                     int[] perm) {
        Pos cur = new Pos(start.row, start.col);
        for (int i = 0; i < dirString.length(); i++) {
            int step = dirString.charAt(i) - '0';   // 0‑3 corresponding to a direction

            // Apply the move according to the current permutation
            cur = switch (step) {
                case 0 -> move(cur, Direction.UP);
                case 1 -> move(cur, Direction.DOWN);
                case 2 -> move(cur, Direction.LEFT);
                case 3 -> move(cur, Direction.RIGHT);
                default -> throw new IllegalArgumentException("Unexpected digit: " + step);
            };

            // Stop if we leave the grid or hit a wall
            if (!isInside(grid, cur.row, cur.col) || grid[cur.row].charAt(cur.col) == WALL) {
                return 0;
            }

            // Success – we arrived at the target
            if (cur.row == end.row && cur.col == end.col) {
                return 1;
            }
        }
        return 0; // reached end of direction string without finding the target
    }

    /** Checks whether a given cell lies inside the grid. */
    private static boolean isInside(String[] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length();
    }

    /** Moves a position one cell in the supplied {@link Direction}. */
    private static Pos move(Pos pos, Direction dir) {
        int nr = pos.row;
        int nc = pos.col;
        switch (dir) {
            case UP    -> nr--;
            case DOWN  -> nr++;
            case LEFT  -> nc--;
            case RIGHT -> nc++;
        }
        return new Pos(nr, nc);
    }

    /** Simple holder for the grid data and the direction string read from input. */
    private static final class GridInfo {
        final String[] grid;
        final String directions;
        GridInfo(String[] grid, String directions) {
            this.grid = grid;
            this.directions = directions;
        }
    }

    /** Simple holder for a coordinate pair inside the grid. */
    private static final class Pos {
        final int row;
        final int col;
        Pos(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Enum representing the four cardinal directions. */
    private enum Direction {
        UP, DOWN, LEFT, RIGHT
    }

    /** Generates all 24 permutations of the numbers 0‑3. */
    private static final class PermutationGenerator {
        /** All permutations of size 4 (0‑3) where each number appears exactly once. */
        static final List<int[]> ALL = generateAll();

        /** Populate the static {@code ALL} list with the 24 permutations. */
        private static List<int[]> generateAll() {
            List<int[]> list = new ArrayList<>();
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    if (j == i) continue;
                    for (int k = 0; k < 4; k++) {
                        if (k == i || k == j) continue;
                        for (int l = 0; l < 4; l++) {
                            if (l == i || l == j || l == k) continue;
                            list.add(new int[]{i, j, k, l});
                        }
                    }
                }
            }
            return list;
        }
    }
}

/**
 * Refactored version of the original program.
 *
 * Improvements:
 *  • Clear separation of concerns (input handling, permutation generation,
 *    path simulation, validation).
 *  • Meaningful naming and constants instead of magic numbers.
 *  • Removed unused imports and static fields.
 *  • Added comments to explain the algorithm.
 *  • Uses recursion to generate the 4! direction‑to‑digit permutations.
 *  • Simulates a path for each permutation and counts those that reach 'E'.
 */
import java.util.Scanner;

public class MazeSolver {

    /* ----- constants ----------------------------------------------------- */
    private static final char WALL      = '#';
    private static final char START     = 'S';
    private static final char END       = 'E';

    private static char[][] maze;   // the maze grid
    private static int rows, cols;  // dimensions
    private static int startRow, startCol; // location of 'S'

    /* direction vectors: up, down, left, right */
    private static final int[] ROW_DELTAS = {-1, 1, 0, 0};
    private static final int[] COL_DELTAS = { 0, 0,-1, 1};

    /* ------------------------------------------------------------------- */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        readInput(sc);
        String directionString = sc.next();          // e.g. "012301..."
        int validCount = countValidPermutations(directionString);
        System.out.println(validCount);
    }

    /* ------------------------------------------------------------------- */
    private static void readInput(Scanner sc) {
        rows = sc.nextInt();
        cols = sc.nextInt();
        maze = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            for (int j = 0; j < line.length(); j++) {
                maze[i][j] = line.charAt(j);
                if (maze[i][j] == START) {
                    startRow = i;
                    startCol = j;
                }
            }
        }
    }

    /* ------------------------------------------------------------------- */
    /**
     * Generates all 4! permutations of the four direction indices (0‑3)
     * and counts how many of them lead from 'S' to 'E' when following the
     * supplied direction string.
     */
    private static int countValidPermutations(String dirString) {
        int[] digitToDir = new int[4];   // digit → actual direction index
        boolean[] used = new boolean[4]; // which direction indices are taken
        int[] result = {0};                // mutable holder for the count

        generatePermutations(0, used, digitToDir, dirString, result);
        return result[0];
    }

    /* ------------------------------------------------------------------- */
    /**
     * Recursively builds permutations of direction indices.
     * When a full permutation is built (digitIdx == 4) the simulation
     * is executed.
     */
    private static void generatePermutations(int digitIdx,
                                             boolean[] used,
                                             int[] digitToDir,
                                             String dirString,
                                             int[] result) {
        if (digitIdx == 4) {
            if (simulatePath(digitToDir, dirString)) {
                result[0]++; // a valid permutation found
            }
            return;
        }

        for (int dirIdx = 0; dirIdx < 4; dirIdx++) {
            if (!used[dirIdx]) {
                used[dirIdx] = true;
                digitToDir[digitIdx] = dirIdx;   // assign direction for this digit
                generatePermutations(digitIdx + 1, used, digitToDir,
                                     dirString, result);
                used[dirIdx] = false; // backtrack
            }
        }
    }

    /* ------------------------------------------------------------------- */
    /**
     * Simulates the walk defined by {@code dirString} using the supplied
     * {@code digitToDir} mapping.
     *
     * @return {@code true} if the walk reaches the target 'E' without
     *         leaving the maze or hitting a wall.
     */
    private static boolean simulatePath(int[] digitToDir, String dirString) {
        int r = startRow;
        int c = startCol;

        for (int pos = 0; pos < dirString.length(); pos++) {
            char ch = dirString.charAt(pos);
            int digit = ch - '0';
            if (digit < 0 || digit > 3) {
                continue; // ignore malformed characters
            }

            int dirIdx = digitToDir[digit];
            int nr = r + ROW_DELTAS[dirIdx];
            int nc = c + COL_DELTAS[dirIdx];

            if (!validPos(nr, nc)) {
                return false; // collision with wall or border aborts the walk
            }

            r = nr;
            c = nc;

            if (maze[r][c] == END) {
                return true; // successfully reached the end
            }
        }
        return false; // finished moves without touching 'E'
    }

    /* ------------------------------------------------------------------- */
    /** Checks whether a cell is inside the maze and not a wall. */
    private static boolean validPos(int row, int col) {
        return row >= 0 && row < rows
                && col >= 0 && col < cols
                && maze[row][col] != WALL;
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** Pre‑defined moves: up, down, left, right */
    private static final int[][] MOVES = {
            {-1, 0}, // up
            {1, 0},  // down
            {0, -1}, // left
            {0, 1}   // right
    };

    public static void main(String[] args) throws Exception {
        try (Scanner sc = new Scanner(new BufferedInputStream(System.in))) {
            int t = sc.nextInt();               // number of test cases (normally 1)
            StringBuilder out = new StringBuilder();
            for (int i = 0; i < t; i++) {
                out.append(countValidMappings(sc)).append('\n');
            }
            System.out.print(out.toString());
        }
    }

    /**
     * Reads one test case, computes the answer and returns it as a string.
     */
    private static int countValidMappings(Scanner sc) {
        int n = sc.nextInt();                     // rows
        int m = sc.nextInt();                     // columns
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = sc.next().toCharArray();    // each row as char array
        }
        String path = sc.next();                  // sequence of direction digits

        // Locate the start cell 'S'
        int sr = -1, scPos = -1;
        outer:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (board[i][j] == 'S') {
                    sr = i;
                    scPos = j;
                    break outer;
                }
            }
        }

        int answer = 0;
        int[] permutation = {0, 1, 2, 3};        // all four direction indices
        do {
            if (simulate(path, permutation, board, sr, scPos)) {
                answer++;
            }
        } while (nextPermutation(permutation));

        return answer;
    }

    /**
     * Simulates the movement described by {@code path} using the supplied
     * direction permutation. Returns {@code true} iff the path reaches the
     * exit cell 'E' without leaving the board or stepping on a wall.
     */
    private static boolean simulate(String path, int[] perm, char[][] board,
                                    int startR, int startC) {
        int n = board.length;
        int m = board[0].length;
        int r = startR, c = startC;

        for (int i = 0; i < path.length(); i++) {
            char digit = path.charAt(i);
            int dirIndex = digit - '0';           // 0 .. 3
            int dir = perm[dirIndex];             // which move to apply
            int[] mv = MOVES[dir];
            int nr = r + mv[0];
            int nc = c + mv[1];

            // boundary check
            if (nr < 0 || nr >= n || nc < 0 || nc >= m) {
                return false;
            }
            // obstacle check
            if (board[nr][nc] == '#') {
                return false;
            }
            // move
            r = nr;
            c = nc;
            // success if we stepped on the exit
            if (board[r][c] == 'E') {
                return true;
            }
        }
        return false; // never reached 'E'
    }

    /** Generates the next lexicographic permutation of the array.
     *  Returns {@code false} when the current permutation is the last one. */
    private static boolean nextPermutation(int[] a) {
        int i = a.length - 2;
        while (i >= 0 && a[i] >= a[i + 1]) {
            i--;
        }
        if (i < 0) {
            return false;
        }
        int j = a.length - 1;
        while (a[j] <= a[i]) {
            j--;
        }
        swap(a, i, j);
        reverse(a, i + 1, a.length - 1);
        return true;
    }

    private static void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    private static void reverse(int[] a, int from, int to) {
        while (from < to) {
            swap(a, from++, to--);
        }
    }
}

import java.util.*;

public class BuggyBot {

    /* --------------------------------------------------------------
       Direction representation
       -------------------------------------------------------------- */
    private enum Direction {
        LEFT(0, -1),
        RIGHT(0, 1),
        UP(-1, 0),
        DOWN(1, 0);

        private final int dRow;
        private final int dCol;

        Direction(int dRow, int dCol) {
            this.dRow = dRow;
            this.dCol = dCol;
        }

        int dRow() { return dRow; }
        int dCol() { return dCol; }
    }

    /* --------------------------------------------------------------
       Constants
       -------------------------------------------------------------- */
    // All 24 possible permutations of the four command keys (0‑3)
    private static final String[] PERMUTATIONS = {
            "0123","0132","1023","1032","0213","0312","0231","0321",
            "1203","1230","1302","1320","2013","2103","2130","2031",
            "2301","2310","3210","3201","3102","3120","3012","3021"
    };

    // Direction letters used by the original code, in fixed order:
    // 0 → LEFT, 1 → RIGHT, 2 → UP, 3 → DOWN
    private static final Direction[] DIR_ORDER = {
            Direction.LEFT, Direction.RIGHT, Direction.UP, Direction.DOWN
    };

    /* --------------------------------------------------------------
       Entry point
       -------------------------------------------------------------- */
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();
            sc.nextLine();                     // consume end‑of‑line

            List<String> maze = new ArrayList<>(rows);
            for (int i = 0; i < rows; i++) {
                maze.add(sc.nextLine());
            }

            String commands = sc.nextLine().trim();

            Point start = locate(maze, 'S');
            Point end   = locate(maze, 'E');

            if (start == null || end == null) {
                System.out.println(0);
                return;
            }

            long successes = Arrays.stream(PERMUTATIONS)
                    .filter(p -> canReach(maze, start, commands, mappingFrom(p)))
                    .count();

            System.out.println(successes);
        }
    }

    /* --------------------------------------------------------------
       Helper methods
       -------------------------------------------------------------- */
    /** Locates the coordinates of a given marker in the maze */
    private static Point locate(List<String> maze, char marker) {
        for (int r = 0; r < maze.size(); r++) {
            String line = maze.get(r);
            for (int c = 0; c < line.length(); c++) {
                if (line.charAt(c) == marker) {
                    return new Point(r, c);
                }
            }
        }
        return null;
    }

    /** Builds a mapping from digit characters (0‑3) to directions according to a permutation */
    private static Map<Character, Direction> mappingFrom(String permutation) {
        Map<Character, Direction> map = new HashMap<>(4);
        for (int idx = 0; idx < 4; idx++) {
            char digit = permutation.charAt(idx);
            map.put(digit, DIR_ORDER[idx]);
        }
        return map;
    }

    /** Simulates the command sequence using the supplied mapping; returns true if 'E' is reached */
    private static boolean canReach(List<String> maze,
                                    Point start,
                                    String commands,
                                    Map<Character, Direction> mapping) {
        int r = start.row;
        int c = start.col;

        for (int i = 0; i < commands.length(); i++) {
            char cmd = commands.charAt(i);
            Direction dir = mapping.get(cmd);
            if (dir == null) {
                return false;                       // command character not covered by this permutation
            }

            int nr = r + dir.dRow();
            int nc = c + dir.dCol();

            // Boundary / wall check
            if (nr < 0 || nr >= maze.size()
                    || nc < 0 || nc >= maze.get(nr).length()
                    || maze.get(nr).charAt(nc) == '#') {
                return false;
            }

            // Move to the new cell
            r = nr;
            c = nc;

            // Success condition
            if (maze.get(r).charAt(c) == 'E') {
                return true;
            }
        }
        return false;                               // reached end of command string without finding the exit
    }

    /** Simple immutable pair representing a cell coordinate */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Fast input / output utilities used for competitive programming.
 */
final class FastScanner {
    private final BufferedReader br;
    private String line;
    private StringTokenizer st;

    FastScanner(InputStream in) {
        this.br = new BufferedReader(new InputStreamReader(in));
    }

    /** Returns the next token from the input. */
    String nextToken() throws IOException {
        if (st == null || !st.hasMoreTokens()) {
            line = br.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    /** Shortcut for the most common case – an int token. */
    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Shortcut for the most common case – a string token. */
    String next() throws IOException {
        return nextToken();
    }
}

/**
 * Fast writer that buffers output for better performance.
 */
final class FastWriter extends PrintWriter {
    FastWriter(OutputStream out) {
        super(new BufferedOutputStream(out));
    }
}

/**
 * Core solving logic for the problem.
 * <p>
 * The algorithm counts how many permutations of the four basic
 * directions (up, down, left, right) lead from the start cell 'S'
 * to the exit cell 'E' when the moves are applied in the order
 * specified by the supplied command string.
 */
final class Solver {
    /** Mapping of the four base directions: up, down, left, right. */
    private static final int[][] DIR = {
            {-1, 0},   // up
            {1,  0},   // down
            {0, -1},   // left
            {0,  1}    // right
    };

    /**
     * Executes the solution.
     *
     * @param testIdx   dummy test number (kept for compatibility with original signature)
     * @param in        input scanner
     * @param out       output writer
     * @throws IOException if an I/O error occurs
     */
    void solve(int testIdx, FastScanner in, FastWriter out) throws IOException {
        int n = in.nextInt();               // rows
        int m = in.nextInt();               // columns
        char[][] maze = new char[n][m];
        int sx = -1, sy = -1;                 // start position
        int ex = -1, ey = -1;                 // exit position

        // ----- read the maze and locate 'S' and 'E' -----
        for (int i = 0; i < n; ++i) {
            String row = in.next();
            char[] chars = row.toCharArray();
            for (int j = 0; j < m; ++j) {
                maze[i][j] = chars[j];
                if (chars[j] == 'S') {
                    sx = i;
                    sy = j;
                } else if (chars[j] == 'E') {
                    ex = i;
                    ey = j;
                }
            }
        }

        String commands = in.next();        // sequence of movement indices (length = 4)

        int validPermutations = 0;

        // ----- enumerate all permutations of the four direction indices -----
        for (int i = 0; i < 4; ++i) {
            for (int j = 0; j < 4; ++j) {
                if (j == i) continue;
                for (int k = 0; k < 4; ++k) {
                    if (k == i || k == j) continue;
                    for (int t = 0; t < 4; ++t) {
                        if (t == i || t == j || t == k) continue;

                        int[] perm = {i, j, k, t};   // a distinct ordering of {0,1,2,3}
                        if (canReach(maze, n, m, sx, sy, ex, ey, commands, perm)) {
                            ++validPermutations;
                        }
                    }
                }
            }
        }

        out.println(validPermutations);
    }

    /**
     * Simulates movement from the start cell according to the command string,
     * using the supplied permutation of the base directions.
     *
     * @return {@code true} if the path reaches the exit without hitting a wall
     *         or leaving the grid; {@code false} otherwise.
     */
    private boolean canReach(char[][] maze, int n, int m,
                             int sx, int sy, int ex, int ey,
                             String commands, int[] perm) {
        int x = sx, y = sy;

        for (char ch : commands.toCharArray()) {
            int dirIdx = ch - '0';                 // which direction from the permutation?
            int[] d = DIR[perm[dirIdx]];
            x += d[0];
            y += d[1];

            // out of bounds → failure
            if (x < 0 || x >= n || y < 0 || y >= m) {
                return false;
            }
            // wall → failure
            if (maze[x][y] == '#') {
                return false;
            }
            // reached the exit → success
            if (x == ex && y == ey) {
                return true;
            }
        }
        // finished the whole command sequence without reaching the exit
        return false;
    }
}

