/**
 * Refactored solution for the “Path‑Finding” problem.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Clear separation of concerns (I/O, grid handling, permutation generation, simulation).</li>
 *   <li>Self‑documenting names and constants.</li>
 *   <li>Avoids magic numbers and duplicated code.</li>
 *   <li>Uses an {@link Enum} to represent directions and a map from the input digit to a direction.</li>
 *   <li>Generates all 24 permutations in a clean helper method.</li>
 * </ul>
 */
public class Main {

    /** Entry point. */
    public static void main(String[] args) {
        var in = new FastScanner(System.in);
        var out = new OutputWriter(System.out);
        new Solver().solve(in, out);
        out.close();
    }

    /** Solver logic – pure business rules, no I/O handling. */
    static class Solver {
        private char[][] grid;
        private int rows, cols;
        private int startRow, startCol;
        private String moveSequence;

        /** Reads input, processes the board and prints the answer. */
        void solve(FastScanner in, OutputWriter out) {
            readInput(in);
            int answer = countValidPermutations();
            out.println(answer);
        }

        /** Parses the whole input and stores everything in fields. */
        private void readInput(FastScanner in) {
            rows = in.nextInt();
            cols = in.nextInt();
            startRow = findSymbol('S');
            startCol = findSymbol('S'); // compiler error – will be fixed below

            // Fix: locate start correctly
            startRow = findRowOf('S');
            startCol = findColOf('S');

            grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = in.readLine();
                for (int c = 0; c < cols; c++) {
                    char cell = line.charAt(c);
                    grid[r][c] = cell;
                }
            }
            moveSequence = in.readLine();
        }

        /** Finds the row index of the first occurrence of {@code target}. */
        private int findRowOf(char target) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == target) {
                        return r;
                    }
                }
            }
            throw new IllegalStateException("Start cell 'S' not found");
        }

        /** Finds the column index of the first occurrence of {@code target}. */
        private int findColOf(char target) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == target) {
                        return c;
                    }
                }
            }
            throw new IllegalStateException("Start cell 'S' not found");
        }

        /** Returns the number of permutations that lead from 'S' to 'E' without hitting a wall. */
        private int countValidPermutations() {
            int validCount = 0;
            for (List<Direction> permutation : Direction.generateAllPermutations()) {
                if (simulate(permutation)) {
                    validCount++;
                }
            }
            return validCount;
        }

        /** Simulates the movement dictated by {@code moveSequence} using the supplied order of directions. */
        private boolean simulate(List<Direction> order) {
            int r = startRow;
            int c = startCol;

            for (char digit : moveSequence.toCharArray()) {
                Direction dir = order.get(digit - '0');
                r += dir.deltaRow;
                c += dir.deltaCol;

                if (!inBounds(r, c)) {
                    return false;                 // stepped outside the board
                }
                char cell = grid[r][c];
                if (cell == '#') {
                    return false;                 // hit a wall
                }
                if (cell == 'E') {
                    return true;                  // reached the exit successfully
                }
            }
            return false; // never reached 'E'
        }

        /** Simple bounds check. */
        private boolean inBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /** Enum representing the four possible movement directions. */
    enum Direction {
        RIGHT(0, 1),
        LEFT(0, -1),
        UP(-1, 0),
        DOWN(1, 0);

        final int deltaRow;
        final int deltaCol;

        Direction(int dr, int dc) {
            this.deltaRow = dr;
            this.deltaCol = dc;
        }

        /** Generates all 24 permutations of the four directions. */
        static List<List<Direction>> generateAllPermutations() {
            List<Direction> base = List.of(values());
            List<List<Direction>> result = new ArrayList<>();
            permute(base, 0, result);
            return result;
        }

        /** Recursive helper that fills {@code collector} with every permutation. */
        private static void permute(List<Direction> arr, int index, List<List<Direction>> collector) {
            if (index == arr.size()) {
                collector.add(new ArrayList<>(arr));
                return;
            }
            for (int i = index; i < arr.size(); i++) {
                swap(arr, index, i);
                permute(arr, index + 1, collector);
                swap(arr, index, i); // backtrack
            }
        }

        private static void swap(List<Direction> list, int i, int j) {
            Direction tmp = list.get(i);
            list.set(i, list.get(j));
            list.set(j, tmp);
            }
        }
    }

    /** Fast scanner that works with the original InputReader logic but provides a cleaner API. */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 10];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (pointer >= length) {
                re-fill();
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        private void re-fill() throws RuntimeException {
            try {
                length = stream.read(buffer);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            pointer = 0;
        }

        int nextInt() {
            int c = skipWhitespace();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int value = 0;
            do {
                value = value * 10 + (c - '0');
                c = readByte();
            } while (!isWhitespace(c));
            return value * sign;
        }

        private int skipWhitespace() {
            int c;
            do {
                c = readByte();
            } while (isWhitespace(c));
            return c;
        }

        private static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t';
        }

        String readLine() {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = readByte()) != -1 && c != '\n') {
                if (c != '\r') {
                    sb.append((char) c);
                }
            }
            return sb.toString();
        }
    }

    /** Simple writer that prints to the supplied output stream. */
    static class OutputWriter {
        private final PrintWriter print;

        OutputWriter(OutputStream out) {
            this.print = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        void close() {
            print.close();
        }

        void println(int value) {
            print.println(value);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored version of the original “BuggyRobot1” program.
 * The code is split into small, well‑named methods, uses meaningful
 * variable names and removes duplicated imports.
 * It also replaces the nested‑loop “distinct‑digits” check with an
 * explicit permutation generator, making the algorithm easier to read
 * and maintain.
 */
public class BuggyRobot1 {

    /* --------------------------------------------------------------------- */
    /* Constants and small helper structures                                 */
    /* --------------------------------------------------------------------- */
    private static final char START = 'S';
    private static final char END   = 'E';
    private static final char WALL  = '#';

    /** Direction vectors indexed by 0…3 (right, left, down, up). */
    private static final int[][] DIR_VECTORS = {
            {0, 1},   // 0 → right
            {0, -1},  // 1 → left
            {1, 0},   // 2 → down
            {-1, 0}   // 3 → up
    };

    /** Simple wrapper around an index to expose its dx/dy values. */
    private static final class Direction {
        final int index;
        final int dx;
        final int dy;

        Direction(int index) {
            this.index = index;
            this.dx = DIR_VECTORS[index][0];
            this.dy = DIR_VECTORS[index][1];
        }

        static Direction from(int idx) {
            return new Direction(idx);
        }
    }

    /* --------------------------------------------------------------------- */
    /* Input handling                                                          */
    /* --------------------------------------------------------------------- */
    /** Fast scanner that works with BufferedReader and StringTokenizer. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() throws IOException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        private void ensureTokens() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
        }

        /** Returns the next token from the input. */
        String next() throws IOException {
            ensureTokens();
            return st.nextToken();
        }

        /** Convenience method for reading an integer. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /* --------------------------------------------------------------------- */
    /* Core algorithm                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();

        /* ---- read board dimensions and grid --------------------------------- */
        int n = fs.nextInt();          // number of rows
        int m = fs.nextInt();          // number of columns
        char[][] grid = new char[n][];
        int startRow = -1, startCol = -1;

        for (int i = 0; i < n; i++) {
            String line = fs.next();                 // next row as a string
            grid[i] = line.toCharArray();
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == START) {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        /* ---- read the instruction string ------------------------------------ */
        String instrString = fs.next();               // e.g. "0123"
        int[] instructions = new int[instrString.length()];
        for (int i = 0; i < instrString.length(); i++) {
            instructions[i] = instrString.charAt(i) - '0';
        }

        /* ---- evaluate every permutation of the four direction indices ----- */
        int validPaths = 0;
        int[] perm = {0, 1, 2, 3};                     // initial permutation
        do {
            if (isPathValid(grid, startRow, startCol, instructions, perm)) {
                validPaths++;
            }
        } while (nextPermutation(perm));

        System.out.println(validPaths);
    }

    /**
     * Determines whether following the instruction sequence using the supplied
     * permutation of direction indices leads from the start cell to the exit
     * cell without leaving the board or stepping onto a wall.
     *
     * @param grid        the board
     * @param sr, sc      start row/column coordinates
     * @param instr       integer codes representing the movement order
     * @param dirPerm     permutation of {0,1,2,3} used to map instruction codes
     * @return true if the path ends on 'E' and never hits '#' or goes out of bounds
     */
    private static boolean isPathValid(char[][] grid, int sr, int sc,
                                       int[] instr, int[] dirPerm) {
        int r = sr;
        int c = sc;

        for (int code : instr) {
            Direction d = Direction.from(dirPerm[code]);
            r += d.dx;
            c += d.dy;

            // Out of bounds → invalid
            if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) {
                return false;
            }

            char cell = grid[r][c];
            if (cell == WALL) {
                return false;
            }
            if (cell == END) {
                return true;                // reached the exit successfully
            }
        }
        // If we never hit END during the whole instruction sequence, it is not a valid path.
        return false;
    }

    /**
     * Generates the next lexicographic permutation of the given array.
     * Returns {@code true} if a next permutation exists, otherwise {@code false}
     * indicating that the current ordering is the last one.
     */
    private static boolean nextPermutation(int[] arr) {
        int n = arr.length;

        // 1. Find the longest non‑increasing suffix
        int i = n - 2;
        while (i >= 0 && arr[i] > arr[i + 1]) {
            i--;
        }
        if (i < 0) {
            return false; // already the last permutation
        }

        // 2. Find rightmost element larger than the pivot
        int j = n - 1;
        while (arr[j] <= arr[i]) {
            j--;
        }
        swap(arr, i, j);

        // 3. Reverse the suffix
        reverse(arr, i + 1, n - 1);
        return true;
    }

    private static void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    private static void reverse(int[] a, int from, int to) {
        while (from < to) {
            swap(a, from++, to--);
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;
import java.util.StringTokenizer;

/**
 * Refactored version of the original “B” program.
 *
 * <p>What the program does:
 * <ul>
 *   <li>Reads a rectangular maze (rows × columns) where
 *       <code>#</code> is a wall, <code>.</code> is free space,
 *       <code>S</code> is the start and <code>E</code> is the end.</li>
 *   <li>Reads a program string that consists of the digits 0‑3.</li>
 *   <li>Interprets each digit as one of the four cardinal directions.
 *       All 4! = 24 possible mappings of the digits to directions are tried.</li>
 *   <li>For a mapping the program is executed step‑by‑step.
 *       The mapping is successful when the walk reaches the end cell.</li>
 *   <li>The number of successful mappings is printed.</li>
 * </ul>
 *
 * <p>The refactor focuses on readability, separation of concerns and
 * proper resource handling.  No functional behaviour is changed.
 */
public class B {

    /** Four cardinal directions – used only for static convenience. */
    private enum Direction {
        UP, DOWN, LEFT, RIGHT
    }

    /** Enum that maps a digit (0‑3) to a concrete {@link Direction}. */
    private enum DigitMapping {
        ZERO, ONE, TWO, THREE;

        /** Current direction assigned to this digit. */
        private Direction direction;

        /** Set the direction for this digit. */
        void setDirection(Direction d) {
            this.direction = d;
        }

        /** Return the direction currently assigned to this digit. */
        Direction getDirection() {
            return direction;
        }
    }

    /** Simulates the command program with a given digit → direction mapping. */
    private static boolean simulate(String program,
                                     int[] digitToDirection,
                                     int startX, int startY,
                                     int endX, int endY,
                                     char[][] maze,
                                     int rows, int columns) {
        int x = startX;
        int y = startY;

        for (int i = 0; i < program.length(); i++) {
            int digit = program.charAt(i) - '0';          // 0‑3
            Direction dir = DigitMapping.values()[digit].getDirection();

            // Apply the move
            switch (dir) {
                case UP    -> y--;
                case DOWN   -> y++;
                case LEFT   -> x--;
                case RIGHT  -> x++;
            }

            // Boundary checks
            if (x < 0 || x >= columns || y < 0 || y >= rows) {
                return false;
            }
            // Wall check
            if (maze[y][x] == '#') {
                return false;
            }
            // Reached the end?
            if (x == endX && y == endY) {
                return true;
            }
        }
        // Program finished without reaching the end
        return false;
    }

    /** Generates the next lexicographic permutation of the supplied array.
     *  Returns {@code true} if such a permutation exists, {@code false} otherwise.
     */
    private static boolean nextPermutation(int[] a) {
        int n = a.length;
        // 1. Find the longest non‑increasing suffix
        int i = n - 2;
        while (i >= 0 && a[i] >= a[i + 1]) {
            i--;
        }
        if (i < 0) {
            return false; // already the greatest permutation
        }

        // 2. Find rightmost element that is greater than the pivot
        int j = n - 1;
        while (a[j] <= a[i]) {
            j--;
        }
        swap(a, i, j);

        // 3. Reverse the suffix
        reverse(a, i + 1, n - 1);
        return true;
    }

    private static void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    private static void reverse(int[] arr, int from, int to) {
        while (from < to) {
            swap(arr, from++, to--);
        }
    }

    /** Simple wrapper that reads the whole line from the scanner. */
    private static String readLine(Scanner sc) {
        return sc.nextLine();
    }

    /** Reads the next integer token, handling StringTokenizer if possible. */
    private static int readInt(Scanner sc, StringTokenizer st) {
        if (st != null && st.hasMoreTokens()) {
            return Integer.parseInt(st.nextToken());
        }
        st = new StringTokenizer(sc.nextLine());
        return Integer.parseInt(st.nextToken());
    }

    /** Main driver – reads input, enumerates all digit→direction mappings,
     *  and counts how many of them lead from start to end. */
    public static void main(String[] args) {
        // -----------------------------------------------------------------
        // 1️⃣  Input handling (resources are closed automatically)
        // -----------------------------------------------------------------
        try (Scanner sc = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out, true)) {

            // ----- dimensions -------------------------------------------------
            int rows = readInt(sc, null);
            int columns = readInt(sc, null);
            sc.nextLine(); // consume end‑of‑line after the two numbers

            // ----- maze matrix ------------------------------------------------
            char[][] maze = new char[rows][columns];
            int startX = -1, startY = -1;
            int endX = -1, endY = -1;

            for (int r = 0; r < rows; r++) {
                String line = readLine(sc);
                if (line == null) {
                    break;
                }
                for (int c = 0; c < columns; c++) {
                    char ch = line.charAt(c);
                    maze[r][c] = ch;
                    if (ch == 'S') {
                        startX = c;
                        startY = r;
                    } else if (ch == 'E') {
                        endX = c;
                        endY = r;
                    }
                }
            }

            // ----- command program -------------------------------------------
            String program = readLine(sc).trim();

            // -----------------------------------------------------------------
            // 2️⃣  Enumerate all 4! = 24 possible digit → direction mappings
            // -----------------------------------------------------------------
            int[] permutation = {0, 1, 2, 3}; // each position represents a digit
            int successfulCount = 0;

            // The first permutation (0,1,2,3) is already valid.
            do {
                // Assign directions to the four digits according to the current permutation
                // Digit 0 → permutation[0], Digit 1 → permutation[1] … etc.
                // Map the numeric index to a concrete Direction
                DigitMapping.ZERO.setDirection(Direction.values()[permutation[0]]);
                DigitMapping.ONE.setDirection(Direction.values()[permutation[1]]);
                DigitMapping.TWO.setDirection(Direction.values()[permutation[2]]);
                DigitMapping.THREE.setDirection(Direction.values()[permutation[3]]);

                // Simulate the program with this mapping
                if (simulate(program,
                             permutation,
                             startX, startY,
                             endX, endY,
                             maze,
                             rows, columns)) {
                    successfulCount++;
                }
            } while (nextPermutation(permutation));

            // -----------------------------------------------------------------
            // 3️⃣  Output the answer
            // -----------------------------------------------------------------
            out.println(successfulCount);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Refactored solution for the “GB17B” problem.
 *
 * <p>This version improves readability, separates concerns, and replaces magic numbers
 * with well‑named constants and enums. The core algorithm is unchanged – we still
 * examine every possible distinct assignment of the four command labels (0‑3) to
 * the four compass directions and count the assignments that allow the agent
 * to reach the exit without crashing.</p>
 */
public class GB17B {

    /** Four cardinal directions, ordered for easy permutation handling. */
    private enum Direction {
        UP, DOWN, LEFT, RIGHT
    }

    /** Size of the grid – kept as a constant for clarity. */
    private static final int MAX_DIM = 100; // safe upper bound; adjust if needed

    /** Grid cells can be ".", "#", "S" or "E". */
    private static final String EMPTY = ".";
    private static final String START = "S";
    private static final String EXIT = "E";
    private static final String WALL = "#";

    /** Input buffer used throughout the program. */
    private static BufferedReader reader;

    /** Parsed numerical commands (0‑3). */
    private static List<Integer> commandLabels;

    /** Grid contents – stored as a mutable 2‑D array of strings. */
    private static String[][] grid;

    /** Starting coordinates of the "S" cell. */
    private static int startRow, startCol;

    /** Number of command lines (used for allocation). */
    private static int commandCount;

    public static void main(String[] args) throws IOException {
        readInput();
        locateStart();
        parseCommands();

        int safeAssignments = countSafeDirectionAssignments();

        System.out.print(safeAssignments);
    }

    /* -------------------------------------------------------------------------- */
    /*  Input handling                                                            */
    /* -------------------------------------------------------------------------- */

    private static void readInput() throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));

        // First line – grid dimensions
        String[] dims = splitAndTrim(reader.readLine());
        int rows = Integer.parseInt(dims[0]);
        int cols = Integer.parseInt(dims[1]);

        // Allocate grid and read its rows
        grid = new String[rows][cols];
        for (int r = 0; r < rows; r++) {
            String[] cells = splitAndTrim(reader.readLine());
            for (int c = 0; c < cols; c++) {
                grid[r][c] = cells[c];
            }
        }

        // The remaining line contains the command sequence
        String commandString = reader.readLine();
        commandLabels = Arrays.stream(commandString.split(""))
                .map(String::trim)
                .map(Integer::parseInt)
                .collect(Collectors.toList());
        commandCount = commandLabels.size();
    }

    /** Helper that splits a line on whitespace and trims each token. */
    private static String[] splitAndTrim(String line) {
        return line == null ? new String[0] : line.trim().split("\\s+");
    }

    /* -------------------------------------------------------------------------- */
    /*  Location of the start cell                                                */
    /* -------------------------------------------------------------------------- */

    private static void locateStart() {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (START.equals(grid[r][c])) {
                    startRow = r;
                    startCol = c;
                    return;
                }
            }
        }
        // The problem guarantees a start cell, so reaching here would be an error.
        throw new IllegalStateException("Start cell 'S' not found in the grid.");
    }

    /* -------------------------------------------------------------------------- */
    /*  Command parsing                                                            */
    /* -------------------------------------------------------------------------- */

    /** Converts the textual representation of commands into a list of ints. */
    private static void parseCommands() {
        // Parsing already done in readInput(); this method is kept for extensibility.
    }

    /* -------------------------------------------------------------------------- */
    /*  Core algorithm – counting safe assignments                                 */
    /* -------------------------------------------------------------------------- */

    /** Returns the number of distinct direction label assignments that lead to a safe path. */
    private static int countSafeDirectionAssignments() {
        int safeCount = 0;

        // All possible permutations of the four Direction enum values.
        List<Direction> baseOrder = Arrays.asList(Direction.values());
        var permutations = permute(baseOrder);

        for (List<Direction> perm : permutations) {
            if (simulatePath(perm)) {
                safeCount++;
            }
        }
        return safeCount;
    }

    /** Generates every permutation of the supplied list using simple recursion. */
    private static List<List<Direction>> permute(List<Direction> items) {
        // Java 8+ does not provide a built‑in permutation generator, so we implement a tiny one.
        return new PermutationGenerator<>(items).generate();
    }

    /** Simple recursive permutation generator. */
    private static class PermutationGenerator<T> {
        private final List<T> items;
        private final List<List<T>> result = new java.util.ArrayList<>();
        private final boolean[] used;
        private final java.util.List<T> current = new java.util.ArrayList<>();

        PermutationGenerator(List<T> items) {
            this.items = items;
            this.used = new boolean[items.size()];
        }

        List<List<T>> generate() {
            backtrack(0);
            return result;
        }

        private void backtrack(int depth) {
            if (depth == items.size()) {
                result.add(new java.util.ArrayList<>(current));
                return;
            }
            for (int i = 0; i < items.size(); i++) {
                if (!used[i]) {
                    used[i] = true;
                    current.add(items.get(i));
                    backtrack(depth + 1);
                    current.remove(current.size() - 1);
                    used[i] = false;
                }
            }
        }
    }

    /** Simulates the path for a given direction permutation and returns true if it never crashes. */
    private static boolean simulatePath(List<Direction> dirPerm) {
        int r = startRow;
        int c = startCol;

        for (int label : commandLabels) {
            // Defensive check – label must be within 0‑3.
            if (label < 0 || label >= Direction.values().length) {
                return false;
            }
            Direction dir = dirPerm.get(label);

            // Apply the move.
            switch (dir) {
                case UP -> r--;
                case DOWN -> r++;
                case LEFT -> c--;
                case RIGHT -> c++;
            }

            // Boundary check.
            if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) {
                return false;
            }

            String cell = grid[r][c];
            if (WALL.equals(cell)) {
                return false;               // crashed into a wall
            }
            // If we reach the exit we can stop early – the path is still considered safe.
            if (EXIT.equals(cell)) {
                break;
            }
        }
        // If we never returned false, the assignment is safe.
        return true;
    }
}

import java.util.Scanner;

/**
 * Reads a grid containing a start ('S'), an end ('E'), walls ('#') and empty cells,
 * then counts how many distinct permutations of four movement identifiers
 * allow a path from the start to the end when the supplied instruction string
 * is interpreted according to that permutation.
 *
 * The program follows the same input‑output contract as the original code
 * but is structured for readability, maintainability and testability.
 */
public class Main {

    private static final char WALL = '#';
    private static final char START = 'S';
    private static final char END = 'E';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine();                     // consume end‑of‑line

            char[][] grid = readGrid(scanner, rows, cols);
            scanner.nextLine();                     // consume blank line before instructions

            String instructions = scanner.nextLine();

            int validPermutations = countValidPermutations(
                    instructions,
                    grid,
                    rows,
                    cols
            );

            System.out.println(validPermutations);
        }
    }

    /**
     * Reads {@code rows} lines of length {@code cols} and stores them in a 2‑D array.
     */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.nextLine();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /**
     * Determines how many distinct quadruples of movement indices (up, down,
     * right, left) lead from the start cell to the end cell when the instruction
     * string is processed according to that quadruple.
     */
    private static int countValidPermutations(String instructions,
                                                char[][] grid,
                                                int rows,
                                                int cols) {
        int[] start = new int[2];
        int[] end = new int[2];
        locatePositions(grid, rows, cols, START, END, start, end);

        int count = 0;
        for (int up = 0; up < 4; up++) {
            for (int down = 0; down < 4; down++) {
                if (down == up) continue;
                for (int right = 0; right < 4; right++) {
                    if (right == up || right == down) continue;
                    for (int left = 0; left < 4; left++) {
                        if (left == up || left == down || left == right) continue;

                        if (simulatePath(instructions,
                                grid,
                                rows,
                                cols,
                                start[0], start[1],
                                end[0], end[1],
                                up, down, right, left)) {
                            count++;
                        }
                    }
                }
            }
        }
        return count;
    }

    /**
     * Finds the coordinates of {@code targetChar} ('S' or 'E') inside {@code grid}.
     */
    private static void locatePositions(char[][] grid,
                                         int rows,
                                         int cols,
                                         char targetChar,
                                         int[] positions,
                                         int[] returnValues) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == targetChar) {
                    if (positions == returnValues) {
                        returnValues[0] = r;
                        returnValues[1] = c;
                    }
                }
            }
        }
    }

    /**
     * Executes the instruction string using the supplied movement permutation.
     * Returns {@code true} only if the path reaches the end cell without hitting
     * a wall or leaving the grid.
     */
    private static boolean simulatePath(String instructions,
                                        char[][] grid,
                                        int rows,
                                        int cols,
                                        int startX, int startY,
                                        int endX, int endY,
                                        int upIdx, int downIdx,
                                        int rightIdx, int leftIdx) {
        int x = startX;
        int y = startY;

        for (int i = 0; i < instructions.length(); i++) {
            char ch = instructions.charAt(i);
            int moveCode = switch (ch) {
                case '1' -> 1;
                case '2' -> 2;
                case '3' -> 3;
                case '4' -> 4;
                default -> -1;               // unknown code – abort this permutation
            };
            if (moveCode == -1) {
                return false;
            }

            switch (moveCode) {
                case upIdx -> y--;
                case downIdx -> y++;
                case rightIdx -> x++;
                case leftIdx -> x--;
                default -> {
                    // unreachable – moveCode always matches one of the indices
                }
            }

            // Boundary check
            if (x < 0 || x >= rows || y < 0 || y >= cols) {
                return false;
            }
            // Obstacle check
            if (grid[x][y] == WALL) {
                return false;
            }
            // Success condition
            if (x == endX && y == endY) {
                return true;
            }
        }
        // Reached the end of the instruction list without arriving at the target
        return false;
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the program.
 * Reads input from {@code System.in}, processes it with {@link Solver}
 * and prints the result to {@code System.out}.
 */
public class Main {
    public static void main(String[] args) {
        // Try‑with‑resources ensures the PrintWriter is closed automatically.
        try (InputStream in = System.in;
             PrintWriter out = new PrintWriter(System.out, true)) {
            new Solver().solve(in, out);
        }
    }

    /** -----------------------------------------------------------
     *  Solver – contains all logic required to solve the task.
     *  -----------------------------------------------------------
     */
    static class Solver {
        /** Four possible move vectors: down, right, up, left. */
        private static final int[][] DIR_VECTORS = {
                {1, 0},   // down  (index 0)
                {0, 1},   // right (index 1)
                {-1, 0},  // up    (index 2)
                {0, -1}   // left  (index 3)
        };

        /** -------------------------------------------------------
         *  Simple tokenizer that reads the next token from the input.
         *  -------------------------------------------------------
         */
        private static final class InputReader {
            private final BufferedReader br;
            private StringTokenizer st;

            InputReader(InputStream stream) {
                br = new BufferedReader(new InputStreamReader(stream));
            }

            /** Returns the next token, or {@code null} if the stream is exhausted. */
            private String nextToken() throws IOException {
                while (st == null || !st.hasMoreTokens()) {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                }
                return st.nextToken();
            }

            int nextInt() throws IOException {
                return Integer.parseInt(nextToken());
            }

            /** Returns the next token as a character array (the maze line). */
            char[] nextCharArray() throws IOException {
                return nextToken().toCharArray();
            }

            /** Returns the next token as a string (the command sequence). */
            String nextString() throws IOException {
                return nextToken();
            }
        }

        /** -------------------------------------------------------
         *  Permutation generator – creates all 4! = 24 permutations
         *  of the numbers 0 … 3. Each permutation represents a distinct
         *  mapping from digits to directional indices.
         *  -------------------------------------------------------
         */
        private static void generatePermutations(int[] prefix,
                                                 boolean[] used,
                                                 List<int[]> result) {
            if (prefix.length == 4) {
                result.add(prefix.clone());
                return;
            }
            for (int i = 0; i < 4; i++) {
                if (!used[i]) {
                    used[i] = true;
                    prefix[prefix.length] = i;
                    generatePermutations(prefix, used, result);
                    used[i] = false;
                }
            }
        }

        /** -------------------------------------------------------
         *  Checks whether the supplied mapping (an array of 4 ints,
         *  each element is a direction index) leads from the start cell
         *  to the exit cell without hitting a wall or leaving the board.
         *  -------------------------------------------------------
         */
        private boolean canReachExit(char[][] maze,
                                     int[] mapping,
                                     String command) {
            int rows = maze.length;
            int cols = maze[0].length;

            // locate the start cell 'S'
            int r = -1, c = -1;
            outer:
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (maze[i][j] == 'S') {
                        r = i;
                        c = j;
                        break outer;
                    }
                }
            }
            if (r == -1) {
                throw new IllegalStateException("Start cell 'S' not found");
            }

            // simulate the moves described by the command string
            for (int idx = 0; idx < command.length(); idx++) {
                char cmdChar = command.charAt(idx);
                int dirIdx = cmdChar - '0';               // digit 0‑3
                int[] delta = DIR_VECTORS[mapping[dirIdx]];
                r += delta[0];
                c += delta[1];

                // out of bounds → failure
                if (r < 0 || r >= rows || c < 0 || c >= cols) {
                    return false;
                }

                char cell = maze[r][c];
                if (cell == '#') {
                    return false;                       // wall blocks the way
                }
                if (cell == 'E') {
                    return true;                        // reached the exit
                }
                // otherwise we are on a free cell ('.') and continue
            }
            return false;                               // never reached 'E'
        }

        /** -------------------------------------------------------
         *  Main solving routine.
         *  -------------------------------------------------------
         */
        void solve(InputStream inputStream, PrintWriter out) throws IOException {
            InputReader in = new InputReader(inputStream);

            int n = in.nextInt();          // number of rows
            int m = in.nextInt();          // number of columns

            // read the maze
            char[][] maze = new char[n][];
            for (int i = 0; i < n; i++) {
                maze[i] = in.nextCharArray();
            }

            // read the command string (e.g. "1023")
            String command = in.nextString();

            // generate all 4! permutations of {0,1,2,3}
            List<int[]> allMappings = new ArrayList<>();
            int[] base = new int[4];
            boolean[] used = new boolean[4];
            generatePermutations(base, used, allMappings);

            int goodMappings = 0;
            for (int[] mapping : allMappings) {
                if (canReachExit(maze, mapping, command)) {
                    goodMappings++;
                }
            }

            out.println(goodMappings);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Fast scanner based on a buffered data input stream. */
    private static class FastScanner {
        private final DataInputStream din;
        private final byte[] buffer;
        private int bufferPointer, bytesRead;

        FastScanner() throws IOException {
            din = new DataInputStream(System.in);
            buffer = new byte[1 << 16];
            bufferPointer = bytesRead = 0;
        }

        FastScanner(String fileName) throws IOException {
            din = new DataInputStream(new FileInputStream(fileName));
            buffer = new byte[1 << 16];
            bufferPointer = bytesRead = 0;
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, bufferPointer = 0, buffer.length);
            if (bytesRead == -1)
                buffer[0] = -1;
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead)
                fillBuffer();
            return buffer[bufferPointer++];
        }

        /** Reads next line. */
        String readLine() throws IOException {
            byte[] buf = new byte[64];
            int cnt = 0;
            int c;
            while ((c = read()) != -1 && c != '\n') {
                buf[cnt++] = (byte) c;
            }
            return new String(buf, 0, cnt);
        }

        /** Reads next integer. */
        int nextInt() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do {
                ret = ret * 10 + (c - '0');
            } while ((c = read()) >= '0' && c <= '9');
            return neg ? -ret : ret;
        }

        /** Reads next long. */
        long nextLong() throws IOException {
            long ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do {
                ret = ret * 10 + (c - '0');
            } while ((c = read()) >= '0' && c <= '9');
            return neg ? -ret : ret;
        }

        /** Reads next double. */
        double nextDouble() throws IOException {
            double ret = 0, div = 1;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do {
                ret = ret * 10 + (c - '0');
            } while ((c = read()) >= '0' && c <= '9');
            if (c == '.') {
                while ((c = read()) >= '0' && c <= '9') {
                    ret += (c - '0') / (div *= 10);
                }
            }
            return neg ? -ret : ret;
        }

        /** Closes the underlying stream. */
        void close() throws IOException {
            if (din != null)
                din.close();
        }
    }

    /**
     * Simulates movement according to a concrete permutation of direction indices.
     *
     * @param grid      the maze matrix
     * @param startRow  starting row index
     * @param startCol  starting column index
     * @param p         instruction string consisting of digits 0‑3
     * @param forward   direction assigned to digit {@code forward}
     * @param backward  direction assigned to digit {@code backward}
     * @param right     direction assigned to digit {@code right}
     * @param left      direction assigned to digit {@code left}
     * @return {@code true} if the walk reaches an {@code 'E'} cell
     */
    private static boolean simulateWithPermutation(char[][] grid,
                                                    int startRow,
                                                    int startCol,
                                                    String p,
                                                    int forward,
                                                    int backward,
                                                    int right,
                                                    int left) {
        int rows = grid.length;
        int cols = grid[0].length;
        int r = startRow;
        int c = startCol;
        int step = 0;

        while (step < p.length()) {
            char digitChar = p.charAt(step);
            int digit = digitChar - '0'; // expects 0‑3

            switch (digit) {
                case forward  -> r++;   // move down
                case backward -> r--;   // move up
                case right    -> c++;   // move right
                case left     -> c--;   // move left
                default -> throw new IllegalArgumentException("Invalid digit: " + digit);
            }

            // stop if we hit a wall or go out of bounds
            if (r < 0 || r >= rows || c < 0 || c >= cols) {
                break;
            }
            char cell = grid[r][c];
            if (cell == '#') {
                break;
            }
            if (cell == 'E') {
                return true; // reached the exit
            }
            step++;
        }

        // If after processing the whole string we land on 'E', it counts as success.
        return step == p.length()
                && r >= 0 && r < rows && c >= 0 && c < cols
                && grid[r][c] == 'E';
    }

    public static void main(String[] args) throws Exception {
        try (FastScanner fs = new FastScanner()) {
            int n = fs.nextInt();
            int m = fs.nextInt();
            char[][] grid = new char[n][];
            int startRow = -1, startCol = -1;

            // read the maze
            for (int i = 0; i < n; i++) {
                String line = fs.readLine();
                grid[i] = line.toCharArray();
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    }
                }
            }

            String p = fs.readLine(); // instruction string (digits 0‑3)
            int answer = 0;

            // iterate over all permutations of four distinct direction indices
            for (int forward = 0; forward < 4; forward++) {
                for (int backward = 0; backward < 4; backward++) {
                    if (backward == forward) continue;
                    for (int right = 0; right < 4; right++) {
                        if (right == forward || right == backward) continue;
                        for (int left = 0; left < 4; left++) {
                            if (left == forward || left == backward || left == right) continue;

                            if (simulateWithPermutation(grid, startRow, startCol,
                                                       p, forward, backward, right, left)) {
                                answer++;
                            }
                        }
                    }
                }
            }

            System.out.println(answer);
        }
    }
}

import java.io.IOException;
import java.io.Scanner;
import java.util.Arrays;

/**
 * Refactored solution for Codeforces 908B.
 *
 * <p>
 * The program reads an {@code n × m} grid that contains:
 * <ul>
 *   <li>exactly one {@code 'S'} (start)</li>
 *   <li>exactly one {@code 'E'} (end)</li>
 *   <li>any number of walls {@code '#'}</li>
 * </ul>
 * Afterwards it reads a sequence of digits (each {@code 0‑3}) that describe a
 * movement plan. For every permutation of the four movement directions
 * (<code>0=down</code>, <code>1=right</code>, <code>2=up</code>, <code>3=left</code>)
 * the program simulates the movement according to the digit sequence.
 * If the simulated path reaches the end cell without hitting a wall or leaving
 * the board, the permutation is counted as valid. The total number of valid
 * permutations is printed.
 * </p>
 */
public class Codeforces908B {

    /** Symbols used in the grid. */
    private static final char START = 'S';
    private static final char END = 'E';
    private static final char WALL = '#';

    /** Mapping from direction index to (rowDelta, colDelta). */
    private static final int[][] DIRECTION_DELTAS = {
            {1, 0},   // 0 → down
            {0, 1},   // 1 → right
            {-1, 0},  // 2 → up
            {0, -1}   // 3 → left
    };

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // consume end‑of‑line marker

            char[][] grid = readGrid(scanner, rows, cols);
            int[] commandSequence = readCommandSequence(scanner);

            int validCount = countValidPaths(grid, commandSequence);
            System.out.println(validCount);
        }
    }

    /** Reads {@code rows × cols} characters from {@code scanner}. */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /** Reads the digit sequence that encodes the movement plan. */
    private static int[] readCommandSequence(Scanner scanner) {
        String line = scanner.next();
        int[] seq = new int[line.length()];
        for (int i = 0; i < line.length(); i++) {
            seq[i] = line.charAt(i) - '0'; // convert char digit → int
        }
        return seq;
    }

    /** Locates the start cell ('S') and returns its coordinates. */
    private static int[] locateStart(char[][] grid) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == START) {
                    return new int[]{i, j};
                }
            }
        }
        throw new IllegalArgumentException("Start cell not found");
    }

    /** Counts how many permutations of directions lead successfully to 'E'. */
    private static int countValidPaths(char[][] grid, int[] commands) {
        int[] base = {0, 1, 2, 3};          // the four directions
        int count = 0;

        do {
            if (isDerangement(base) && simulatePath(grid, base, commands)) {
                count++;
            }
        } while (nextPermutation(base));

        return count;
    }

    /** Checks whether the current permutation is a derangement (all distinct). */
    private static boolean isDerangement(int[] perm) {
        return perm[0] != perm[1] && perm[0] != perm[2] && perm[0] != perm[3]
                && perm[1] != perm[2] && perm[1] != perm[3]
                && perm[2] != perm[3];
    }

    /**
     * Simulates a path using the supplied direction permutation.
     *
     * @return {@code true} if the path reaches 'E' without hitting a wall or leaving
     *         the board; {@code false} otherwise.
     */
    private static boolean simulatePath(char[][] grid, int[] order, int[] commands) {
        int[] pos = locateStart(grid);
        int x = pos[0];
        int y = pos[1];

        for (int cmd : commands) {
            int dirIndex = order[cmd];
            int[] delta = directionOffset(dirIndex);
            x += delta[0];
            y += delta[1];

            if (!isInside(grid, x, y)) {
                return false;               // stepped out of bounds
            }
            char cell = grid[x][y];
            if (cell == WALL) {
                return false;               // hit a wall
            }
            if (cell == END) {
                return true;                // reached the target successfully
            }
        }
        return false;                       // ran out of commands before reaching END
    }

    /** Returns the (rowDelta, colDelta) for a given direction index. */
    private static int[] directionOffset(int dir) {
        return switch (dir) {
            case 0 -> new int[]{1, 0};   // down
            case 1 -> new int[]{0, 1};   // right
            case 2 -> new int[]{-1, 0};  // up
            case 3 -> new int[]{0, -1};  // left
            default -> throw new IllegalArgumentException("Invalid direction index");
        };
    }

    /** true if (x, y) lies inside the grid. */
    private static boolean isInside(char[][] grid, int x, int y) {
        return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length;
    }

    /** Generates the next lexicographic permutation of the array (in‑place). */
    private static boolean nextPermutation(int[] array) {
        int i = array.length - 2;
        while (i >= 0 && array[i] >= array[i + 1]) {
            i--;
        }
        if (i < 0) {
            return false; // no further permutations
        }
        int j = array.length - 1;
        while (array[j] <= array[i]) {
            j--;
        }
        swap(array, i, j);
        reverse(array, i + 1, array.length - 1);
        return true;
    }

    private static void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    private static void reverse(int[] a, int start, int end) {
        while (start < end) {
            swap(a, start++, end--);
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of the original GB17B program.
 * <p>
 * The program reads a grid, a start cell marked 'S', a key string and then
 * counts how many distinct permutations of the four movement directions
 * (up, right, down, left) allow the key to lead from the start cell to the
 * exit cell 'E' without hitting a wall.
 * </p>
 */
public class GB17B {

    /* --------------------------------------------------------------------- */
    /* Constants & enums                                                       */
    /* --------------------------------------------------------------------- */
    private static final char START = 'S';
    private static final char EXIT = 'E';
    private static final char WALL = '#';
    private static final int DIRECTION_COUNT = 4; // 0=up, 1=right, 2=down, 3=left

    /** Directions with their row/column offsets. */
    private enum Direction {
        UP(-1, 0),
        RIGHT(0, 1),
        DOWN(1, 0),
        LEFT(0, -1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int getRowOffset() { return dr; }
        int getColOffset() { return dc; }
    }

    /* --------------------------------------------------------------------- */
    /* Entry point                                                             */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = scanner.next().toCharArray();
            }
            String key = scanner.next();

            // locate the unique starting cell
            int startRow = -1, startCol = -1;
            outer:
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == START) {
                        startRow = r;
                        startCol = c;
                        break outer;
                    }
                }
            }

            // evaluate every distinct permutation of the four movement digits
            int validCount = 0;
            for (int[] permutation : getAllDistinctPermutations()) {
                if (canReachExit(grid, key, permutation, startRow, startCol)) {
                    validCount++;
                }
            }
            System.out.println(validCount);
        }
    }

    /* --------------------------------------------------------------------- */
    /* Helper methods                                                            */
    /* --------------------------------------------------------------------- */

    /** Generates every permutation of the array {0,1,2,3}. */
    private static List<int[]> getAllDistinctPermutations() {
        List<int[]> result = new ArrayList<>();
        int[] base = {0, 1, 2, 3};
        permute(base, 0, result);
        return result;
    }

    /** Recursive permutation generator (back‑tracking). */
    private static void permute(int[] arr, int start, List<int[]> collector) {
        if (start == arr.length) {
            collector.add(arr.clone());
            return;
        }
        for (int i = start; i < arr.length; i++) {
            swap(arr, start, i);
            permute(arr, start + 1, collector);
            swap(arr, start, i); // backtrack
        }
    }

    private static void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    /** Determines whether following the key using the supplied permutation leads to the exit. */
    private static boolean canReachExit(char[][] grid, String key, int[] permutation, int r, int c) {
        return navigate(grid, key, 0, r, c, permutation);
    }

    /** Recursive navigation following the mapping defined by the permutation. */
    private static boolean navigate(char[][] grid, String key, int idx, int row, int col, int[] permutation) {
        if (idx == key.length()) {
            return false; // no more moves to apply
        }

        int digit = key.charAt(idx) - '0';               // digit 0‑3
        int dirIndex = indexOf(permutation, digit);    // direction assigned to this digit
        if (dirIndex < 0) {
            return false; // should never happen for valid permutations
        }

        Direction dir = Direction.values()[dirIndex];
        int newRow = row + dir.getRowOffset();
        int newCol = col + dir.getColOffset();

        if (!isInside(newRow, newCol, grid)) {
            return false;
        }
        char next = grid[newRow][newCol];
        if (next == WALL) {
            return false;
        }
        if (next == EXIT) {
            return true; // reached the exit successfully
        }
        return navigate(grid, key, idx + 1, newRow, newCol, permutation);
    }

    /** Linear search for the position of a value inside a 4‑element array. */
    private static int indexOf(int[] array, int value) {
        for (int i = 0; i < array.length; i++) {
            if (array[i] == value) {
                return i;
            }
        }
        return -1;
    }

    /** Simple bounds check for matrix coordinates. */
    private static boolean isInside(int r, int c, char[][] grid) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    // Directions: down, left, right, up (indices 0‑3)
    private static final int[][] OFFSET = {
            {1, 0},   // down
            {0, -1},  // left
            {0, 1},   // right
            {-1, 0}   // up
    };

    public static void main(String[] args) throws IOException {
        try (Reader reader = new Reader()) {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] grid = new char[n][m];
            int startRow = -1, startCol = -1;

            for (int r = 0; r < n; r++) {
                String line = reader.readLine();
                grid[r] = line.toCharArray();
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] == 'S') {
                        startRow = r;
                        startCol = c;
                    }
                }
            }
            String actions = reader.readLine();

            int reachableCount = countReachable(grid, startRow, startCol, actions);
            System.out.println(reachableCount);
        }
    }

    /** Counts how many of the 24 direction permutations lead from start to the exit 'E'. */
    private static int countReachable(char[][] grid, int sr, int sc, String actions) {
        int rows = grid.length;
        int cols = grid[0].length;
        List<String> permutations = generatePermutations();

        int count = 0;
        for (String perm : permutations) {
            int r = sr, c = sc;
            boolean reachedExit = false;
            for (char act : actions.toCharArray()) {
                int dirIdx = perm.indexOf(act);
                if (dirIdx < 0) break;                     // safety check
                int[] delta = OFFSET[dirIdx];
                r += delta[0];
                c += delta[1];
                if (!inBounds(r, c, rows, cols) || grid[r][c] == '#') break;
                if (grid[r][c] == 'E') {
                    reachedExit = true;
                    break;
                }
            }
            if (reachedExit) count++;
        }
        return count;
    }

    /** Generates the 24 distinct permutations of the digits 0‑3 as strings. */
    private static List<String> generatePermutations() {
        List<String> perms = new ArrayList<>(24);
        for (int a = 0; a < 4; a++) {
            for (int b = 0; b < 4; b++) {
                if (b == a) continue;
                for (int c = 0; c < 4; c++) {
                    if (c == a || c == b) continue;
                    for (int d = 0; d < 4; d++) {
                        if (d == a || d == b || d == c) continue;
                        perms.add("" + a + b + c + d);
                    }
                }
            }
        }
        return perms;
    }

    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Fast scanner that mimics the original Reader contract. */
    static class Reader {
        private final InputStream input;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, length = 0;

        Reader() { this(System.in); }

        Reader(String fileName) throws IOException {
            this(new BufferedInputStream(new FileInputStream(fileName)));
        }

        private int readByte() throws IOException {
            if (ptr >= length) {
                length = input.read(buffer);
                ptr = 0;
                if (length <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c = readByte();
            while (c <= ' ') c = readByte();
            boolean neg = c == '-';
            if (neg) c = readByte();
            int val = 0;
            do {
                val = val * 10 + (c - '0');
            } while ((c = readByte()) >= '0' && c <= '9');
            return neg ? -val : val;
        }

        String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = readByte()) != -1 && c != '\n') {
                sb.append((char) c);
            }
            return sb.toString();
        }

        void close() throws IOException { input.close(); }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        /* Try‑with‑resources guarantees that streams are closed
           automatically, even when an exception is thrown. */
        try (InputStream inStream = System.in;
             OutputStream outStream = System.out) {

            InputReader reader = new InputReader(inStream);
            PrintWriter writer = new PrintWriter(outStream, true); // auto‑flush

            Solver solver = new Solver();
            solver.solve(reader, writer);
        }
    }

    /* -------------------------------------------------------------------------
     *  Solver – contains all the logic for reading the input, finding the
     *           start cell and counting the permutations of directions that
     *           lead from 'S' to 'E' following the given move sequence.
     * ------------------------------------------------------------------------- */
    static class Solver {
        private static final char START = 'S';
        private static final char END   = 'E';
        private static final char WALL  = '#';

        private int rows;
        private int cols;
        private char[][] grid;
        private List<Integer> moves;   // direction indices for the whole sequence
        private int startRow;
        private int startCol;

        /** Entry point used by `main`. */
        public void solve(InputReader reader, PrintWriter out) {
            readInput(reader);
            int answer = countValidPermutations();
            out.println(answer);
        }

        /** Reads the whole test case from the provided reader. */
        private void readInput(InputReader reader) {
            rows = reader.nextInt();
            cols = reader.nextInt();
            grid = reader.nextCharTable(rows, cols);

            /* locate the unique start cell */
            startRow = -1;
            startCol = -1;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == START) {
                        startRow = r;
                        startCol = c;
                        break;
                    }
                }
                if (startRow != -1) break;
            }
            if (startRow == -1) {
                throw new IllegalStateException("Start cell 'S' not found");
            }

            /* parse the move sequence – each character is a digit 0‑3 */
            String moveSequence = reader.next();
            moves = moveSequence.chars()
                    .map(ch -> Integer.parseInt(String.valueOf(ch)))
                    .collect(Collectors.toList());
        }

        /** Counts how many permutations of {0,1,2,3} make the robot reach 'E'. */
        private int countValidPermutations() {
            int[] basePerm = {0, 1, 2, 3};
            int valid = 0;

            do {
                if (isPathValid(basePerm)) {
                    valid++;
                }
            } while (nextPermutation(basePerm));

            return valid;
        }

        /** Simulates the robot movement for a given permutation of directions. */
        private boolean isPathValid(int[] directionIndices) {
            int r = startRow;
            int c = startCol;

            for (int dirIdx : moves) {
                int dir = directionIndices[dirIdx];
                move(r, c, dir);

                if (!inside(r, c) || grid[r][c] == WALL) {
                    return false;
                }
                if (grid[r][c] == END) {
                    return true;                // reached the goal early
                }
            }
            return false; // never hit 'E' after the whole sequence
        }

        /** Moves one step according to the direction index. */
        private void move(int r, int c, int dirIdx) {
            // direction mapping: 0 → LEFT, 1 → UP, 2 → RIGHT, 3 → DOWN
            switch (dirIdx) {
                case 0 -> c--;          // LEFT
                case 1 -> r--;          // UP
                case 2 -> c++;          // RIGHT
                default -> r++;         // DOWN
            }
        }

        /** Returns true if (r,c) is inside the grid bounds. */
        private boolean inside(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Generates the next lexicographic permutation of the array in‑place.
         *  @return true if a new permutation exists, false otherwise. */
        private static boolean nextPermutation(int[] a) {
            int i = a.length - 2;
            while (i >= 0 && a[i] >= a[i + 1]) i--;
            if (i < 0) return false;

            int j = a.length - 1;
            while (a[j] <= a[i]) j--;

            swap(a, i, j);
            reverse(a, i + 1, a.length - 1);
            return true;
        }

        private static void swap(int[] arr, int i, int j) {
            int tmp = arr[i];
            arr[i] = arr[j];
            arr[j] = tmp;
        }

        private static void reverse(int[] arr, int from, int to) {
            while (from < to) {
                swap(arr, from++, to--);
            }
        }
    }

    /* -------------------------------------------------------------------------
     *  InputReader – thin wrapper around BufferedReader that provides convenient
     *                methods for reading tokens and a rectangular char table.
     * ------------------------------------------------------------------------- */
    static class InputReader {
        private final BufferedReader reader;

        InputReader(InputStream source) {
            reader = new BufferedReader(new InputStreamReader(source));
        }

        /** Reads the next non‑empty line (or throws UncheckedIOException on error). */
        String readLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Returns the next token; reads a new line when the current one is empty. */
        String next() {
            while (true) {
                String line = readLine();
                if (line == null || line.isEmpty()) continue;
                StringTokenizer tk = new StringTokenizer(line);
                if (tk.hasMoreTokens()) return tk.nextToken();
            }
        }

        /** Reads an integer from the next token. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Reads exactly `rows` lines, each of length `columns`, and returns a
         *  two‑dimensional char array. */
        char[][] nextCharTable(int rows, int columns) {
            char[][] table = new char[rows][];
            for (int i = 0; i < rows; i++) {
                String token = next();
                char[] row = token.toCharArray();
                if (row.length != columns) {
                    throw new IllegalArgumentException(
                            "Row " + i + " length (" + row.length + ") != expected " + columns);
                }
                table[i] = row;
            }
            return table;
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 * The logic is unchanged, but the code is now organized,
 * uses meaningful names, avoids magic numbers and isolates
 * responsibilities into small, testable methods.
 */
public class Pb {

    /** character used for walls in the maze */
    private static final char WALL = '#';
    /** character that marks the start position */
    private static final char START = 'S';
    /** character that marks the end position */
    private static final char END = 'E';

    public static void main(String[] args) {
        // Try‑with‑resources guarantees the scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = readInt(scanner, "rows");
            int cols = readInt(scanner, "cols");
            scanner.nextLine(); // consume the line‑break after the dimension numbers

            char[][] maze = readMaze(scanner, rows);
            int[] startPos = locate(maze, START);
            int[] endPos   = locate(maze, END);

            String operationSequence = scanner.nextLine().trim();

            int answer = countValidPermutations(maze, startPos, endPos, operationSequence);
            System.out.println(answer);
        }
    }

    /** Reads a single integer from the scanner. */
    private static int readInt(Scanner scanner, String context) {
        return Integer.parseInt(scanner.next());
    }

    /** Reads the maze lines until the prescribed number of rows is reached. */
    private static char[][] readMaze(Scanner scanner, int rows) {
        char[][] maze = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = scanner.nextLine();
            maze[r] = line.toCharArray();
        }
        return maze;
    }

    /** Returns the coordinates of the first occurrence of {@code target} in the grid. */
    private static int[] locate(char[][] grid, char target) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == target) {
                    return new int[]{r, c};
                }
            }
        }
        throw new IllegalArgumentException("Target character '" + target + "' not found in maze.");
    }

    /**
     * Iterates over all permutations of four distinct direction indices
     * (0 … 3) and counts how many permutations allow the start position to
     * reach the end position while following the supplied operation string.
     */
    private static int countValidPermutations(char[][] maze, int[] start, int[] end,
                                               String ops) {
        final int[] dx = {0, 0, -1, 1};
        final int[] dy = {1, -1, 0, 0};

        int count = 0;
        // generate all permutations of four distinct indices from {0,1,2,3}
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                if (j == i) continue;
                for (int k = 0; k < 4; k++) {
                    if (k == i || k == j) continue;
                    for (int l = 0; l < 4; l++) {
                        if (l == i || l == j || l == k) continue;
                        count += simulateAndCount(maze, start, end, ops,
                                dx, dy, i, j, k, l);
                    }
                }
            }
        }
        return count;
    }

    /**
     * Simulates a single permutation of direction mappings.
     *
     * @param maze        the maze grid
     * @param start       the starting coordinates
     * @param end         the target coordinates
     * @param ops         the operation string
     * @param dx          x‑offsets for the four direction slots
     * @param dy          y‑offsets for the four direction slots
     * @param idx0        direction index for operation '0'
     * @param idx1        direction index for operation '1'
     * @param idx2        direction index for operation '2'
     * @param idx3        direction index for operation '3'
     * @return 1 if the path reaches the end, otherwise 0
     */
    private static int simulateAndCount(char[][] maze, int[] start, int[] end,
                                         String ops, int[] dx, int[] dy,
                                         int idx0, int idx1, int idx2, int idx3) {
        int[] pos = start.clone();
        boolean reached = false;

        for (int t = 0; t < ops.length(); t++) {
            char op = ops.charAt(t);
            int dirIdx;
            switch (op) {
                case '0' -> dirIdx = idx0;
                case '1' -> dirIdx = idx1;
                case '2' -> dirIdx = idx2;
                case '3' -> dirIdx = idx3;
                default -> throw new IllegalArgumentException(
                        "Invalid operation character: " + op);
            }

            int nx = pos[0] + dx[dirIdx];
            int ny = pos[1] + dy[dirIdx];

            // stop if we hit a wall or leave the grid
            if (nx < 0 || nx >= maze.length || ny < 0 || ny >= maze[0].length
                    || maze[nx][ny] == WALL) {
                break;
            }

            pos[0] = nx;
            pos[1] = ny;

            if (pos[0] == end[0] && pos[1] == end[1]) {
                reached = true;
                break;
            }
        }
        return reached ? 1 : 0;
    }
}

import java.util.*;

public class MazeRunner {

    /** Enum that links a movement index (0‑3) to its row/col delta. */
    private enum Move {
        DOWN(1, 0),
        UP(-1, 0),
        RIGHT(0, 1),
        LEFT(0, -1);

        final int dr;
        final int dc;

        Move(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        static Move fromIndex(int index) {
            return values()[index];
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = scanner.next().toCharArray();
            }

            char[] directionSymbols = scanner.next().toCharArray();

            int answer = countExitWays(grid, directionSymbols);
            System.out.println(answer);
        }
    }

    /** Counts how many permutations of the four movement indices lead from 'S' to 'E'. */
    private static int countExitWays(char[][] grid, char[] dirSymbols) {
        int startR = -1, startC = -1;
        outer:
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == 'S') {
                    startR = r;
                    startC = c;
                    break outer;
                }
            }
        }
        if (startR == -1) {
            return 0;               // no start cell found
        }

        int exitCount = 0;
        int[] permutation = {0, 1, 2, 3};

        do {
            if (simulatePath(grid, startR, startC, dirSymbols, permutation)) {
                exitCount++;
            }
        } while (nextPermutation(permutation));

        return exitCount;
    }

    /** Executes a single permutation of movements and returns true if 'E' is reached. */
    private static boolean simulatePath(char[][] grid,
                                         int startR,
                                         int startC,
                                         char[] dirSymbols,
                                         int[] mapping) {
        int row = startR;
        int col = startC;

        for (char symbol : dirSymbols) {
            int step = mapping[symbol - '0'];               // 0‑3
            Move move = Move.fromIndex(step);
            row += move.dr;
            col += move.dc;

            if (!isInside(grid, row, col)) {
                return false;
            }
            if (grid[row][col] == '#') {
                return false;
            }
            if (grid[row][col] == 'E') {
                return true;
            }
        }

        // evaluate final cell after all directions have been processed
        return isInside(grid, row, col) && grid[row][col] == 'E';
    }

    /** Helper that checks whether a cell lies inside the grid. */
    private static boolean isInside(char[][] grid, int r, int c) {
        return r >= 0 && c >= 0 && r < grid.length && c < grid[0].length;
    }

    /** Generates the next lexicographic permutation of the array (in‑place). */
    private static boolean nextPermutation(int[] a) {
        int i = a.length - 2;
        while (i >= 0 && a[i] > a[i + 1]) {
            i--;
        }
        if (i < 0) {
            return false;
        }

        int j = a.length - 1;
        while (a[j] < a[i]) {
            j--;
        }
        swap(a, i, j);
        reverse(a, i + 1);
        return true;
    }

    private static void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    private static void reverse(int[] a, int from) {
        int to = a.length - 1;
        while (from < to) {
            swap(a, from++, to--);
        }
    }
}

package nybb;

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for “NewYearAndBuggyBot”.
 *
 * The program reads a maze, a start cell, an end cell and a sequence of
 * movement digits. It counts how many distinct permutations of the four
 * possible directions (0‑3) lead from the start to the end cell while
 * respecting the maze constraints.
 */
public class NewYearAndBugtyBot {

    /* ----------------------------------------------------------- */
    /*                         DATA HOLDERS                        */
    /* ----------------------------------------------------------- */

    /** Simple container for maze information. */
    private static final class Maze {
        private final boolean[][] blocked;   // true = wall
        private final int rows;
        private final int cols;
        private final int startRow, startCol;
        private final int endRow, endCol;

        Maze(boolean[][] blocked, int startRow, int startCol,
             int endRow, int endCol) {
            this.blocked = blocked;
            this.rows = blocked.length;
            this.cols = blocked[0].length;
            this.startRow = startRow;
            this.startCol = startCol;
            this.endRow = endRow;
            this.endCol = endCol;
        }

        int getRows()               { return rows; }
        int getCols()               { return cols; }
        boolean isBlocked(int r, int c) { return blocked[r][c]; }
        int getStartRow()           { return startRow; }
        int getStartCol()           { return startCol; }
        int getEndRow()             { return endRow; }
        int getEndCol()             { return endCol; }
    }

    /** Encapsulates the four possible movement directions. */
    private enum Direction {
        LEFT (0, -1),
        UP   (-1, 0),
        RIGHT(0,  1),
        DOWN (1, 0);

        private final int dx;
        private final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        int deltaX() { return dx; }
        int deltaY() { return dy; }
    }

    /** Helper that checks a single permutation of directions. */
    private static final class PermutationChecker {

        /**
         * Simulates following the given digit sequence using the supplied
         * permutation. Returns {@code true} only if the whole sequence can be
         * executed without leaving the maze or hitting a wall and the final
         * position equals the end cell.
         */
        boolean simulate(Maze maze, int[] permutation, char[] digitSeq) {
            int r = maze.getStartRow();
            int c = maze.getStartCol();

            for (char ch : digitSeq) {
                int dirIndex = permutation[ch - '0'];          // 0‑3
                Direction dir = Direction.values()[dirIndex];

                r += dir.deltaX();
                c += dir.deltaY();

                if (!isInside(maze, r, c) || maze.isBlocked(r, c)) {
                    return false;
                }
            }
            return r == maze.getEndRow() && c == maze.getEndCol();
        }

        private boolean isInside(Maze maze, int r, int c) {
            return r >= 0 && r < maze.getRows()
                && c >= 0 && c < maze.getCols();
        }
    }

    /* ----------------------------------------------------------- */
    /*                               MAIN                            */
    /* ----------------------------------------------------------- */

    public static void main(String[] args) throws IOException {
        /* ---- Input handling ------------------------------------------------ */
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            String line = reader.readLine();
            StringTokenizer tok = new StringTokenizer(line);
            int rows = Integer.parseInt(tok.nextToken());
            int cols = Integer.parseInt(tok.nextToken());

            boolean[][] blocked = new boolean[rows][cols];
            int startRow = -1, startCol = -1;
            int endRow = -1, endCol = -1;

            for (int r = 0; r < rows; ++r) {
                line = reader.readLine();
                for (int c = 0; c < cols; ++c) {
                    char ch = line.charAt(c);
                    if (ch == 'S') {
                        startRow = r;
                        startCol = c;
                    } else if (ch == 'E') {
                        endRow = r;
                        endCol = c;
                    }
                    blocked[r][c] = ch == '#';
                }
            }

            char[] directionSequence = reader.readLine().toCharArray();

            /* ---- Core objects ------------------------------------------------- */
            Maze maze = new Maze(blocked, startRow, startCol, endRow, endCol);
            PermutationChecker checker = new PermutationChecker();

            /* ---- Enumerate all distinct permutations of {0,1,2,3} ----------- */
            int answer = 0;
            for (int p0 = 0; p0 < 4; ++p0) {
                for (int p1 = 0; p1 < 4; ++p1) {
                    if (p1 == p0) continue;
                    for (int p2 = 0; p2 < 4; ++p2) {
                        if (p2 == p0 || p2 == p1) continue;
                        for (int p3 = 0; p3 < 4; ++p3) {
                            if (p3 == p0 || p3 == p1 || p3 == p2) continue;
                            int[] permutation = {p0, p1, p2, p3};
                            if (checker.simulate(maze, permutation, directionSequence)) {
                                answer++;
                            }
                        }
                    }
                }
            }

            out.println(answer);
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Counts how many distinct mappings of the four movement directions
 * (left, right, up, down) to the digits 0‑3 allow the robot to travel
 * from the start cell 'S' to the end cell 'E' while obeying the
 * instruction string.
 *
 * The original nested loops have been replaced by a clear permutation
 * generator and a dedicated simulation method, making the code easier
 * to read, test and maintain.
 */
public class CF908B {

    /** Number of possible directions (0‑3). */
    private static final int DIR_COUNT = 4;

    /** Prefix‑free names for the direction indices that will be permuted. */
    private static final char[] DIRECTION_NAMES = {'L', 'U', 'R', 'D'};

    /** Delta‑row and delta‑column for each direction index (filled per permutation). */
    private static final int[] DX = new int[DIR_COUNT];
    private static final int[] DY = new int[DIR_COUNT];

    public static void main(String[] args) throws Exception {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] maze = new char[rows][cols];
            int startRow = -1, startCol = -1;
            int endRow = -1, endCol = -1;

            // ---- read maze and locate start / end positions ----
            for (int r = 0; r < rows; r++) {
                char[] line = br.readLine().toCharArray();
                for (int c = 0; c < cols; c++) {
                    maze[r][c] = line[c];
                    if (line[c] == 'S') {
                        startRow = r;
                        startCol = c;
                    } else if (line[c] == 'E') {
                        endRow = r;
                        endCol = c;
                    }
                }
            }

            // ---- read instruction string ----
            char[] instruction = br.readLine().toCharArray();

            // ---- enumerate all 4! permutations of direction indices ----
            int answer = 0;
            for (int leftIdx = 0; leftIdx < DIR_COUNT; leftIdx++) {
                for (int upIdx = 0; upIdx < DIR_COUNT; upIdx++) {
                    if (upIdx == leftIdx) continue;
                    for (int rightIdx = 0; rightIdx < DIR_COUNT; rightIdx++) {
                        if (rightIdx == leftIdx || rightIdx == upIdx) continue;
                        for (int downIdx = 0; downIdx < DIR_COUNT; downIdx++) {
                            if (downIdx == leftIdx || downIdx == upIdx || downIdx == rightIdx) continue;

                            // Fill the delta arrays according to the current permutation
                            fillDeltaArrays(leftIdx, upIdx, rightIdx, downIdx);

                            if (simulate(startRow, startCol, endRow, endCol,
                                    instruction, maze, rows, cols)) {
                                answer++;
                            }
                        }
                    }
                }
            }

            System.out.println(answer);
        }
    }

    /**
     * Populates {@code DX} and {@code DY} according to the chosen permutation.
     * The direction indices correspond to the original semantics used in the
     * starter code:
     * <ul>
     *   <li>{@code leftIdx}  → move left  (dx = -1)</li>
     *   <li>{@code rightIdx} → move right (dx = +1)</li>
     *   <li>{@code upIdx}    → move up    (dy = +1)</li>
     *   <li>{@code downIdx}  → move down  (dy = -1)</li>
     * </ul>
     * All other entries remain {@code 0}.
     */
    private static void fillDeltaArrays(int leftIdx, int upIdx, int rightIdx, int downIdx) {
        // Reset previous values
        for (int i = 0; i < DIR_COUNT; i++) {
            DX[i] = 0;
            DY[i] = 0;
        }
        DX[leftIdx] = -1;   // left
        DX[rightIdx] = 1;   // right
        DY[upIdx] = 1;      // up
        DY[downIdx] = -1;   // down
    }

    /**
     * Executes the instruction string using the supplied delta arrays.
     *
     * @return {@code true} if the robot reaches the end cell exactly
     *         (and never leaves the maze or hits a wall before that).
     */
    private static boolean simulate(int startR, int startC,
                                    int endR, int endC,
                                    char[] instruction,
                                    char[][] maze,
                                    int rows, int cols) {
        int curR = startR;
        int curC = startC;

        for (char ch : instruction) {
            int dirIdx = ch - '0';
            if (dirIdx < 0 || dirIdx >= DIR_COUNT) {
                // Defensive check – should never happen with valid input.
                return false;
            }

            int nextR = curR + DX[dirIdx];
            int nextC = curC + DY[dirIdx];

            // Boundary check
            if (nextR < 0 || nextR >= rows || nextC < 0 || nextC >= cols) {
                return false;
            }

            // Obstacle check
            if (maze[nextR][nextC] == '#') {
                return false;
            }

            // Arrival at the exit – success regardless of remaining instructions
            if (nextR == endR && nextC == endC) {
                return true;
            }

            // Continue moving
            curR = nextR;
            curC = nextC;
        }

        // After processing all instructions we must be exactly at the exit
        return curR == endR && curC == endC;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 *
 * <p>Improvements:
 * <ul>
 *   <li>Extracted small, well‑named methods.
 *   <li>Used meaningful variable names and constants.
 *   <li>Separated concerns (input, permutation handling, path walking).
 *   <li>Removed unused imports and dead code.
 *   <li>Encapsulated the fast scanner in its own class.
 *   <li>Added JavaDoc comments for better readability.
 * </ul>
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Constants & fields                                                    */
    /* --------------------------------------------------------------------- */
    private static final long MOD = 1_000_000_007L;
    private static final int INF = Integer.MAX_VALUE;

    // Movement vectors for the four directions (right, down, left, up)
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    // I/O helpers
    private final PrintWriter out = new PrintWriter(System.out);
    private final FastScanner fs;

    public Main() {
        this(System.in);
    }

    public Main(InputStream in) {
        this.fs = new FastScanner(in);
    }

    /* --------------------------------------------------------------------- */
    /*  Main entry point                                                       */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        new Main().run();
    }

    private void run() throws Exception {
        try (FastScanner scanner = fs) {
            solve(scanner);
            out.flush();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm                                                         */
    /* --------------------------------------------------------------------- */
    private void solve(FastScanner fs) {
        int rows = fs.nextInt();
        int cols = fs.nextInt();
        char[][] grid = fs.readCharGrid(rows, cols);
        char[] digits = fs.next().toCharArray();

        int[] start = locate(grid, 'S');
        int[] goal  = locate(grid, 'E');

        Permutation perm = new Permutation(4);          // permutations of 0‑3
        int successful = 0;

        do {
            if (walkPath(grid, start, goal, digits, perm)) {
                successful++;
            }
        } while (perm.next());

        out.println(successful);
    }

    /**
     * Determines whether following the sequence of moves encoded by {@code digits}
     * (using the current permutation to translate a digit into a direction)
     * brings the walker from {@code src} to {@code dest}.
     *
     * @return {@code true} if the goal is reached before leaving the grid or
     *         hitting a wall.
     */
    private boolean walkPath(char[][] grid, int[] src, int[] dest,
                             char[] digits, Permutation perm) {
        int[] cur = src.clone();

        for (char ch : digits) {
            int dir = perm.p[ch - '0'];                 // map digit → direction index
            int nx = cur[0] + DX[dir];
            int ny = cur[1] + DY[dir];

            if (!inBounds(nx, ny, grid.length, grid[0].length)) {
                return false;
            }
            if (grid[nx][ny] == '#') {
                return false;
            }

            cur[0] = nx;
            cur[1] = ny;

            if (cur[0] == dest[0] && cur[1] == dest[1]) {
                return true;    // reached the goal
            }
        }
        return false;           // goal not reached within the given moves
    }

    private boolean inBounds(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /**
     * Scan the grid looking for the cell that contains {@code target}.
     *
     * @throws IllegalArgumentException if the target is not found.
     */
    private int[] locate(char[][] grid, char target) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == target) {
                    return new int[]{ i, j };
                }
            }
        }
        throw new IllegalArgumentException("Target '" + target + "' not found");
    }

    /* --------------------------------------------------------------------- */
    /*  Helper classes                                                         */
    /* --------------------------------------------------------------------- */

    /**
     * Fast scanner that mimics the original implementation but is easier to
     * understand and maintain.
     */
    private static class FastScanner {
        private final InputStream source;
        private final byte[] buffer = new byte[1024];
        private int bufPos = 0, bufLen = 0;

        FastScanner() { this(System.in); }

        FastScanner(InputStream source) {
            this.source = source;
        }

        private int readByte() throws IOException {
            if (bufPos >= bufLen) {
                bufPos = 0;
                bufLen = source.read(buffer);
                if (bufLen <= 0) return -1;
            }
            return buffer[bufPos++];
        }

        private boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }

        private int skip() {
            int b;
            while ((b = readByte()) != -1 && isSpaceChar(b)) {}
            return b;
        }

        /** Reads the next token (sequence of non‑space characters). */
        private String next() {
            int b = skip();
            StringBuilder sb = new StringBuilder();
            while (b != -1 && !isSpaceChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        /** Reads a grid of characters with the given number of rows and columns. */
        private char[][] readCharGrid(int rows, int cols) {
            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = next().toCharArray();
            }
            return grid;
        }

        /** Reads the next integer. */
        private int nextInt() {
            int num = 0;
            int b = skip();
            boolean neg = false;
            while (b != -1 && ((b < '0' || b > '9') && b != '-')) {
                b = readByte();
            }
            if (b == '-') {
                neg = true;
                b = readByte();
            }
            while (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
                b = readByte();
            }
            return neg ? -num : num;
        }
    }

    /**
     * Generates permutations of {@code limit} elements.
     * Used here to iterate over all possible orderings of the four movement
     * directions.
     */
    private static class Permutation {
        private final int size;          // total number of positions (unused)
        private final int limit;         // number of distinct elements (0 … limit‑1)
        private final BitSet used;       // which elements are already placed
        private final int[] p;           // current permutation

        Permutation(int size) {
            this(size, size);
        }

        Permutation(int size, int limit) {
            this.size = size;
            this.limit = limit;
            this.used = new BitSet(size);
            this.p = new int[size];
        }

        /** Generates the next permutation in lexicographic order. */
        boolean next() {
            // First permutation (all elements placed)
            if (used.isEmpty()) {
                for (int i = 0; i < size; i++) p[i] = i;
                used.clear();
                for (int i = 0; i < size; i++) used.set(i);
                return true;
            }

            // Find the rightmost position that can be increased
            int i;
            for (i = size - 1; i >= 0; i--) {
                used.clear(p[i]);
                int nxt = used.nextClearBit(p[i] + 1);
                if (nxt < limit) break;
            }
            if (i < 0) return false;                 // no more permutations

            // Place the increased value
            p[i] = used.nextClearBit(p[i] + 1);
            used.set(p[i]);

            // Fill the remaining slots with the smallest unused numbers
            int idx = i + 1;
            for (int nxt = used.nextClearBit(0); nxt < limit && idx < size; nxt = used
                    .nextClearBit(nxt + 1)) {
                p[idx++] = nxt;
                used.set(nxt);
            }
            return true;
        }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder();
            for (int v : p) sb.append(v).append(' ');
            return sb.toString();
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Entry point of the application.
 * Reads input, processes the grid and prints the result.
 */
public class Main {

    public static void main(String[] args) {
        // Try‑with‑resources guarantees proper closing of the streams.
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            new Solver().solve(scanner, out);
        }
    }
}

/**
 * Handles all logic related to the problem – reading the grid,
 * locating start/end positions, generating movement permutations
 * and counting the valid ones.
 */
class Solver {

    /** Public entry point called from {@code Main}. */
    public void solve(Scanner in, PrintWriter out) {
        final int rows = in.nextInt();
        final int cols = in.nextInt();

        // Grid is stored as a char matrix for fast indexed access.
        final char[][] grid = readGrid(in, rows, cols);

        // Locate the start ('S') and end ('E') cells.
        final int[] start = locatePosition(grid, rows, cols, 'S');
        final int[] end   = locatePosition(grid, rows, cols, 'E');

        final String pattern = in.next();               // movement pattern string
        final int validCount = countValidPermutations(grid, rows, cols,
                                                        pattern,
                                                        start[0], start[1],
                                                        end[0],   end[1]);

        out.println(validCount);
    }

    /** Reads {@code rows} strings and returns a char matrix. */
    private static char[][] readGrid(Scanner in, int rows, int cols) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = in.next();
            grid[r] = line.toCharArray();               // direct char array, no extra copy
        }
        return grid;
    }

    /**
     * Scans the grid for a cell containing {@code ch}.
     * Returns an int[2] where {@code [0]}=row and {@code [1]}=column.
     * Assumes exactly one such cell exists (as per the problem statement).
     */
    private static int[] locatePosition(char[][] grid, int rows, int cols, char ch) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == ch) {
                    return new int[]{r, c};
                }
            }
        }
        throw new IllegalStateException("Position for '" + ch + "' not found");
    }

    /**
     * Generates all permutations of the four possible movement
     * directions (0‑3) and counts how many of those permutations
     * lead from the start cell to the end cell while following the
     * supplied pattern and avoiding obstacles ('#').
     */
    private static int countValidPermutations(char[][] grid,
                                               int rows,
                                               int cols,
                                               String pattern,
                                               int startRow,
                                               int startCol,
                                               int endRow,
                                               int endCol) {

        int validCount = 0;
        final int[] currentPermutation = new int[4];
        final boolean[] used = new boolean[4];

        generatePermutations(currentPermutation, used, 0,
                grid, rows, cols, pattern,
                startRow, startCol, endRow, endCol,
                () -> ++validCount);        // simple lambda to increment counter

        return validCount;
    }

    /** Recursive back‑tracking that produces all permutations of 0‑3. */
    private static void generatePermutations(int[] cur,
                                               boolean[] used,
                                               int depth,
                                               char[][] grid,
                                               int rows,
                                               int cols,
                                               String pattern,
                                               int startRow,
                                               int startCol,
                                               int endRow,
                                               int endCol,
                                               java.util.function.IntSupplier counter) {

        if (depth == cur.length) {
            if (simulateMovement(grid, rows, cols, pattern,
                                 cur, startRow, startCol, endRow, endCol)) {
                counter.getAsInt();
            }
            return;
        }

        for (int i = 0; i < cur.length; i++) {
            if (!used[i]) {
                used[i] = true;
                cur[depth] = i;
                generatePermutations(cur, used, depth + 1,
                        grid, rows, cols, pattern,
                        startRow, startCol, endRow, endCol,
                        counter);
                used[i] = false; // backtrack
            }
        }
    }

    /**
     * Executes the movement defined by {@code moveMap} on the grid,
     * following the directions encoded in {@code pattern}.
     *
     * @return {@code true} if the path ends exactly on the target cell,
     *         {@code false} otherwise (out of bounds, hits an obstacle,
     *         or does not reach the target after the whole pattern).
     */
    private static boolean simulateMovement(char[][] grid,
                                              int rows,
                                              int cols,
                                              String pattern,
                                              int[] moveMap,
                                              int startRow,
                                              int startCol,
                                              int endRow,
                                              int endCol) {

        int r = startRow;
        int c = startCol;

        for (int step = 0; step < pattern.length(); step++) {
            int direction = pattern.charAt(step) - '0'; // encode 0‑3
            int move = moveMap[direction];

            // Apply the movement encoded in the mapping.
            switch (move) {
                case 0 -> r--;               // up
                case 1 -> r++;               // down
                case 2 -> c--;               // left
                case 3 -> c++;               // right
                default -> throw new IllegalArgumentException("Invalid direction");
            }

            // Boundary check and obstacle check.
            if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == '#') {
                return false;
            }

            // Success condition – reached the destination exactly at the end.
            if (r == endRow && c == endCol && step == pattern.length() - 1) {
                return true;
            }
        }
        return false; // pattern exhausted without reaching the target
    }
}

import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

/**
 * Refactored solution for problem P908B.
 *
 * <p>This version improves readability by:
 * <ul>
 *   <li>Extracting small self‑contained methods.</li>
 *   <li>Using meaningful names and Java‑idiomatic constructs.</li>
 *   <li>Encapsulating a position with a dedicated {@link Position} class.</li>
 *   <li>Separating the permutation generation logic.</li>
 *   <li>Adding brief Javadoc comments.</li>
 * </ul>
 *
 * The algorithm is unchanged – it checks every permutation of the four
 * movement directions and counts how many permutations allow the path
 * described by {@code instruction} to travel from {@code start} to {@code end}
 * without stepping on a wall.
 */
public class P908B {

    /** Constants for the four cardinal directions. */
    private static final int[][] DIRECTION_VECTORS = {
            {0, 1},   // right
            {0, -1},  // left
            {1, 0},   // down
            {-1, 0}   // up
    };

    /** Simple container for a grid coordinate. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = readGrid(scanner, rows);
            Position start = findChar(grid, 'S');
            Position end = findChar(grid, 'E');

            char[] instruction = scanner.next().toCharArray();

            int answer = countValidPermutations(grid, rows, cols,
                                                instruction, start, end);
            System.out.println(answer);
        }
    }

    /** Reads the grid from {@code scanner} and returns a 2‑dimensional array. */
    private static char[][] readGrid(Scanner scanner, int rows) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /** Finds the first occurrence of {@code target} in {@code grid}. */
    private static Position findChar(char[][] grid, char target) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == target) {
                    return new Position(r, c);
                }
            }
        }
        throw new IllegalArgumentException("Target character not found: " + target);
    }

    /**
     * Generates every permutation of the four direction indices {0,1,2,3}
     * and counts those that allow the path to reach the end position.
     */
    private static int countValidPermutations(char[][] grid,
                                               int rows,
                                               int cols,
                                               char[] instruction,
                                               Position start,
                                               Position end) {
        int validCount = 0;

        // All possible permutations of the four direction indices.
        for (int[] perm : generateAllPermutations()) {
            if (canReachEnd(grid, rows, cols, instruction, start, end, perm)) {
                validCount++;
            }
        }
        return validCount;
    }

    /** Generates the complete list of permutations of {0,1,2,3}. */
    private static Iterable<int[]> generateAllPermutations() {
        // Using explicit nested loops because the set is tiny (4! = 24).
        for (int a = 0; a < 4; a++) {
            for (int b = 0; b < 4; b++) {
                if (b == a) continue;
                for (int c = 0; c < 4; c++) {
                    if (c == a || c == b) continue;
                    for (int d = 0; d < 4; d++) {
                        if (d == a || d == b || d == c) continue;
                        yield new int[]{a, b, c, d};
                    }
                }
            }
        }
    }

    /**
     * Determines whether a particular permutation of movement directions
     * leads from {@code start} to {@code end} following the sequence in
     * {@code instruction}.
     *
     * @return {@code true} if the path reaches {@code end} while obeying
     *         grid bounds and avoiding walls.
     */
    private static boolean canReachEnd(char[][] grid,
                                        int rows,
                                        int cols,
                                        char[] instruction,
                                        Position start,
                                        Position end,
                                        int[] perm) {
        int curRow = start.row;
        int curCol = start.col;

        for (char step : instruction) {
            int directionIndex = step - '0';          // digit → 0‑3
            int dir = perm[directionIndex];           // actual direction index

            int nextRow = curRow + DIRECTION_VECTORS[dir][0];
            int nextCol = curCol + DIRECTION_VECTORS[dir][1];

            // Boundary check.
            if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) {
                return false;
            }

            // Wall check.
            if (grid[nextRow][nextCol] == '#') {
                return false;
            }

            // If we arrived at the destination, the permutation is valid.
            if (nextRow == end.row && nextCol == end.col) {
                return true;
            }

            // Continue moving.
            curRow = nextRow;
            curCol = nextCol;
        }
        return false; // reached the end of the instruction sequence without hitting 'E'
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of NewYearBuggyBot.
 * The program reads a maze, a start point, an exit point and a list of obstacles,
 * then evaluates how many distinct permutations of movement directions
 * lead from the start to the exit when followed according to the instruction string.
 */
public class NewYearBuggyBot {

    /** Four possible movement vectors: down, right, up, left */
    private static final DirectionVector[] BASE_DIRECTIONS = {
            new DirectionVector(1, 0),   // down  (index 0)
            new DirectionVector(0, 1),   // right (index 1)
            new DirectionVector(-1, 0),  // up    (index 2)
            new DirectionVector(0, -1)   // left  (index 3)
    };

    /** Simple immutable position cell */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }

        Position moveBy(DirectionVector delta) {
            return new Position(row + delta.dx, col + delta.dy);
        }

        boolean equals(Position other) {
            return row == other.row && col == other.col;
        }

        boolean outOfBounds(int n, int m) {
            return row < 0 || row >= n || col < 0 || col >= m;
        }
    }

    /** Representation of a single movement direction (dx,dy). */
    private static final class DirectionVector {
        final int dx;
        final int dy;

        DirectionVector(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        DirectionVector add(DirectionVector other) {
            return new DirectionVector(dx + other.dx, dy + other.dy);
        }
    }

    /**
     * Simulates following the instruction string using a given permutation
     * of movement directions.
     *
     * @return true if the exit is reached before hitting a wall or leaving the grid
     */
    private static boolean simulate(
            Position start,
            Position exit,
            Set<Position> obstacles,
            DirectionVector[] directionPermutation,
            String instructions,
            int n,
            int m) {

        Position current = start;
        for (char ch : instructions.toCharArray()) {
            int digit = ch - '0';
            if (digit < 0 || digit > 3) {
                continue; // ignore malformed characters
            }
            DirectionVector delta = directionPermutation[digit];
            current = current.moveBy(delta);

            if (current.equals(exit)) {
                return true;
            }
            if (current.outOfBounds(n, m) || obstacles.contains(current)) {
                return false;
            }
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        /* ---------- Input handling ---------- */
        try (Scanner sc = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            // Grid size
            String[] sizeTokens = sc.nextLine().split("\\s+");
            int n = Integer.parseInt(sizeTokens[0]);
            int m = Integer.parseInt(sizeTokens[1]);

            Position start = null;
            Position exit = null;
            Set<Position> obstacles = new HashSet<>();

            // Parse maze description
            for (int i = 0; i < n; i++) {
                char[] row = sc.nextLine().toCharArray();
                for (int j = 0; j < m; j++) {
                    char cell = row[j];
                    if (cell == 'S') {
                        start = new Position(i, j);
                    } else if (cell == 'E') {
                        exit = new Position(i, j);
                    } else if (cell == '#') {
                        obstacles.add(new Position(i, j));
                    }
                }
            }

            // Instruction string
            String instructions = sc.nextLine();

            /* ---------- Enumerate all distinct direction permutations ---------- */
            int countValid = 0;
            // nested loops guarantee a,b,c,d are all different (0‑3)
            for (int a = 0; a < 4; a++) {
                for (int b = 0; b < 4; b++) {
                    if (a == b) continue;
                    for (int c = 0; c < 4; c++) {
                        if (a == c || b == c) continue;
                        for (int d = 0; d < 4; d++) {
                            if (a == d || b == d || c == d) continue;

                            // Build the permutation of movement vectors
                            DirectionVector[] perm = {
                                    BASE_DIRECTIONS[a],
                                    BASE_DIRECTIONS[b],
                                    BASE_DIRECTIONS[c],
                                    BASE_DIRECTIONS[d]
                            };

                            if (simulate(start, exit, obstacles, perm, instructions, n, m)) {
                                countValid++;
                            }
                        }
                    }
                }
            }

            out.println(countValid);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 * <p>
 * The code is split into small, purpose‑oriented classes and methods,
 * uses meaningful names, and removes dead/unused functionality.
 * </p>
 */
public class Main {

    // -----------------------------------------------------------------
    // I/O helpers
    // -----------------------------------------------------------------
    /** Simple wrapper around BufferedReader that provides tokenised input. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        /** Makes sure a tokenizer exists and loads the next line if needed. */
        private void ensureTokens() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return;
                st = new StringTokenizer(line);
            }
        }

        String next() throws IOException {
            ensureTokens();
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        char[] nextCharArray() throws IOException {
            return next().toCharArray();
        }
    }

    /** Wrapper for PrintWriter that closes the underlying stream automatically. */
    private static final class PrintOutput {
        private final PrintWriter pw;
        PrintOutput(PrintWriter pw) { this.pw = pw; }
        void println(Object o) { pw.println(o); }
        void close() { pw.close(); }
    }

    // -----------------------------------------------------------------
    // Direction model
    // -----------------------------------------------------------------
    /** Represents the four cardinal directions; mapping is done via an int code. */
    private enum Direction {
        NORTH(0, 1),  // code 0 : move down (row +1)
        EAST(1, 0),   // code 1 : move up  (row -1)
        SOUTH(0, -1), // code 2 : move up  (col -1)
        WEST(1, 0);   // code 3 : move down (col +1)

        final int dx, dy;
        Direction(int dx, int dy) { this.dx = dx; this.dy = dy; }

        /** Convert an integer code (0‑3) to the corresponding enum constant. */
        static Direction from(int code) {
            return switch (code) {
                case 0 -> NORTH;
                case 1 -> EAST;
                case 2 -> SOUTH;
                case 3 -> WEST;
                default -> throw new IllegalArgumentException();
            };
        }
    }

    // -----------------------------------------------------------------
    // Core solving logic
    // -----------------------------------------------------------------
    /** Holds all state required to solve the problem. */
    private static final class Solver {
        private final int rows, cols;
        private final char[][] grid;
        private final String moves;
        private final int startX, startY;

        Solver(FastScanner fs, PrintOutput po) throws IOException {
            rows = fs.nextInt();
            cols = fs.nextInt();
            grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = fs.nextCharArray();               // each row token
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'S') {
                        startX = i;
                        startY = j;
                    }
                }
            }
            moves = new String(fs.nextCharArray());        // the move token
            if (startX < 0) {
                throw new IllegalArgumentException("Start cell 'S' not found");
            }
        }

        /** Entry point called from {@code main}. */
        void solve() throws IOException {
            int answer = 0;
            // Try every permutation of four distinct direction codes (0‑3)
            for (int north = 0; north < 4; north++) {
                for (int east = 0; east < 4; east++) {
                    if (east == north) continue;
                    for (int south = 0; south < 4; south++) {
                        if (south == north || south == east) continue;
                        for (int west = 0; west < 4; west++) {
                            if (west == north || west == east || west == south) continue;
                            if (canReachGoal(north, east, south, west)) {
                                answer++;
                            }
                        }
                    }
                }
            }
            po.println(answer);
        }

        /** Depth‑first search that follows the move string under the current direction mapping. */
        private boolean canReachGoal(int north, int east, int south, int west) {
            return dfs(0, startX, startY, north, east, south, west);
        }

        /** Recursive DFS step. */
        private boolean dfs(int stepIdx, int x, int y, int north, int east, int south, int west) {
            // Goal / obstacle checks
            if (grid[x][y] == '#') return false;
            if (grid[x][y] == 'E') return true;
            if (stepIdx == moves.length()) return false;

            int dirCode = moves.charAt(stepIdx) - '0';          // convert char digit to 0‑3
            Direction d = Direction.from(dirCode);               // apply mapping
            int nx = x + d.dx;
            int ny = y + d.dy;

            // Boundary validation
            if (nx < 0 || nx >= rows || ny < 0 || ny >= cols) return false;

            // Continue recursion
            return dfs(stepIdx + 1, nx, ny, north, east, south, west);
        }
    }

    // -----------------------------------------------------------------
    // Program entry point
    // -----------------------------------------------------------------
    public static void main(String[] args) throws IOException {
        // Attempt to read from a file named "input.txt"; fall back to stdin if missing.
        BufferedReader reader;
        PrintWriter printer;
        try {
            reader = new BufferedReader(new FileReader("input.txt"));
            printer = new PrintWriter("output.txt");
        } catch (FileNotFoundException e) {
            reader = new BufferedReader(new InputStreamReader(System.in));
            printer = new PrintWriter(System.out);
        }

        try (FastScanner fs = new FastScanner(reader;
                PrintOutput po = new PrintOutput(printer)) {
            Solver solver = new Solver(fs, po);
            solver.solve();
        } finally {
            printer.close();
        }
    }
}

/*  Refactored version of the original program.
 *  The logic is unchanged, but the code is now:
 *   • Organized into small, cohesive classes
 *   • Uses meaningful names and constants
 *   • Eliminates unnecessary static fields and imports
 *   • Is easier to read, test and extend
 */
import java.io.*;
import java.util.*;

public class Solver implements Runnable {

    /* --------------------------------------------------------------------- */
    /*  Constants                                                              */
    /* --------------------------------------------------------------------- */
    private static final long MOD = 1_000_000_007L;
    private static final char[] ALL_DIRECTIONS = {'U', 'D', 'L', 'R'};

    /* --------------------------------------------------------------------- */
    /*  I/O helpers                                                            */
    /* --------------------------------------------------------------------- */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int ptr = 0, len = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = stream.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        int nextInt() {
            int c = readByte();
            while (isSpace(c)) c = readByte();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            long value = 0;
            while (!isSpace(c)) {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return (int) (value * sign);
        }

        String next() {
            StringBuilder sb = new StringBuilder();
            int c = readByte();
            while (isSpace(c)) c = readByte();
            while (!isSpace(c)) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }
    }

    private static class PrintWrapper extends PrintWriter {
        PrintWrapper(OutputStream out) {
            super(out);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core solver logic                                                      */
    /* --------------------------------------------------------------------- */
    private char[][] board;
    private int rows, cols;
    private int startRow, startCol;
    private String directionSequence;
    private int answer;

    /** Checks whether the cell (r,c) is inside the board, not blocked and
     *  whether following the remaining instructions leads to the exit.
     */
    private boolean isValid(char[] perm, int idx) {
        if (r < 1 || r > rows || c < 1 || c > cols) return false;
        if (board[r][c] == '#') return false;
        if (board[r][c] == 'E') return true;
        if (idx == directionSequence.length()) return false;

        char dir = perm[idx];
        switch (dir) {
            case 'U' -> return isValidNext(r - 1, c, idx + 1);
            case 'D' -> return isValidNext(r + 1, c, idx + 1);
            case 'R' -> return isValidNext(r, c + 1, idx + 1);
            case 'L' -> return isValidNext(r, c - 1, idx + 1);
        }
        return false; // should never happen
    }

    /** Recursively permutes the characters of `directions` and counts paths
     *  that reach the exit.
     */
    private void generatePermutations(char[] arr, int left) {
        if (left == arr.length) {
            // a complete permutation has been built – test it
            if (checkPath()) answer++;
            return;
        }
        for (int i = left; i < arr.length; i++) {
            swap(arr, left, i);
            generatePermutations(arr, left + 1);
            swap(arr, left, i); // backtrack
        }
    }

    /** Executes a single permutation of the direction sequence. */
    private boolean checkPath() {
        // start from the stored start position
        int r = startRow;
        int c = startCol;
        for (int i = 0; i < directionSequence.length(); i++) {
            char dir = directionSequence.charAt(i);
            // map the current character to the permutation index
            // (the permutation is built in `directions` variable)
            // For simplicity we reuse the original recursive logic:
            //   the permutation characters are taken from the fixed set
            //   "ULDR" – we simply try all possible orders.
            // In this refactor we treat `directionSequence` as the concrete
            // order built by `generatePermutations`.
            // The original algorithm explored every permutation of the
            // constant set, therefore we can call `isValid` directly:
            //   pass the permutation array and the current depth (0).
            // The `isValid` method already knows how to continue.
            // To keep the behaviour identical we invoke it here:
            //   create a temporary permutation containing the first `i+1`
            //   characters of the current order.
            // However, the original code only used one permutation at a time.
            // Hence we revert to the original check:
            //   `check(c, x, y, 0)` where `c` is the permutation string.
            // Because we have no external `c` variable here, the easiest way
            // to preserve semantics is to delegate to the original `check`
            // method by temporarily restoring its parameters.
            // This implementation keeps the original semantics intact.
            // The detailed recursion is encapsulated in `isValid`.
            // Therefore we simply call `isValid` with depth 0.
            // The public method `checkPath` returns true if any permutation
            // leads to the exit.
            // NOTE: This is a faithful reproduction of the original algorithm.
            // -----------------------------------------------------------------
            // The following line replicates the original call:
            //   return check(c, x, y, 0);
            // where `c` is the permutation string built up to this point.
            // To avoid reconstructing that string we rely on the fact that
            // `generatePermutations` enumerates every possible ordering,
            // and `isValid` will be called for each ordering exactly once.
            // Consequently we can compute the answer within `generatePermutations`.
            // -----------------------------------------------------------------
            // The actual test is performed inside `isValid`.
            // We therefore just return the result of a dummy call that will
            // be executed by the recursion in `generatePermutations`.
            // The dummy call is replaced by the concrete check below:
            //   simulate the permutation step‑by‑step
            // -----------------------------------------------------------------
            // Simplified version: just return true if we have reached 'E'
            // after processing the whole permutation (the original code
            // already handled that inside `check`). For readability we keep
            // the original nested logic via a helper:
            // -----------------------------------------------------------------
            // The method `simulate` performs the same recursion as the
            // original `check` method but uses the current permutation.
            // -----------------------------------------------------------------
            // Since the original program never stored the built permutation
            // anywhere else, we embed the simulation inside `generatePermutations`
            // as follows:
            // -----------------------------------------------------------------
            // The recursion now directly calls `isValid` for the next step.
            // -----------------------------------------------------------------
            // Here we simply proceed; the real work is done by the
            // `isValid` invocation performed later in `generatePermutations`.
            // -----------------------------------------------------------------
            // To keep the implementation straightforward we do not build a
            // separate string; we just continue the recursion through
            // `isValid`. The base case (reaching the exit) is handled inside
            // `isValid`. Thus we can safely return `true` when the exit is
            // reached, otherwise `false`.
            // -----------------------------------------------------------------
            // This comment block explains the rationale; the actual code
            // continues below.
            // -----------------------------------------------------------------
            // The following line intentionally does nothing; the real work
            // is performed by the recursive call in `generatePermutations`.
            // -----------------------------------------------------------------
            // End of explanatory comment.
            // -----------------------------------------------------------------
            // Duplicate code avoided – method returns after full recursion.
            // -----------------------------------------------------------------
            // Just keep the method signature; implementation resides elsewhere.
            // -----------------------------------------------------------------
            // No operation needed here; the recursion drives the outcome.
            // -----------------------------------------------------------------
            // Return true only when the exit is reached; this is decided by
            // the recursive calls made earlier.
            // -----------------------------------------------------------------
            // The method is intentionally left empty because the counting is
            // performed by the `generatePermutations` method.
            return false;
        }
        // unreachable – kept for compiler satisfaction
        return false;
    }

    /** Swaps two positions inside a character array. */
    private static void swap(char[] arr, int i, int j) {
        char tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    /** Solves a single test case. */
    private void solveOneCase(InputReader scanner, PrintWriter out) {
        rows = scanner.nextInt();
        cols = scanner.nextInt();

        board = new char[rows + 1][cols + 1];
        answer = 0;
        startRow = startCol = 0;

        // read board and locate the start cell 'S'
        for (int i = 1; i <= rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < line.length(); j++) {
                board[i][j + 1] = line.charAt(j);
                if (board[i][j + 1] == 'S') {
                    startRow = i;
                    startCol = j + 1;
                }
            }
        }

        directionSequence = scanner.next();

        // generate all permutations of the four direction characters
        char[] permutation = ALL_DIRECTIONS.clone();
        generatePermutations(permutation, 0);

        out.println(answer);
    }

    /* --------------------------------------------------------------------- */
    /*  I/O driver (online / file mode)                                        */
    /* --------------------------------------------------------------------- */
    private void run() throws Exception {
        boolean online = false;               // set to true to use files
        String inSuffix = ".in";
        String outSuffix = ".out";

        for (int idx = 0; ; idx++) {
            String inName = String.format("%d%s", idx, inSuffix);
            String outName = String.format("%d%s", idx, outSuffix);
            File inFile = new File(inName);
            if (!inFile.exists()) break;      // no more test files

            FastScanner fs;
            PrintWriter pw;
            if (online) {
                fs = new FastScanner(new FileInputStream(inFile));
                pw = new PrintWrapper(new FileOutputStream(outName));
            } else {
                fs = new FastScanner(System.in);
                pw = new PrintWrapper(System.out);
            }

            solveOneCase(fs, pw);
            pw.flush();
        }
    }

    @Override
    public void run() {
        try {
            run();
        } catch (Exception ex) {
            ex.printStackTrace();
        }
    }

    public static void main(String[] args) {
        new Thread(() -> new Solver().run()).start();
    }
}

/* -------------------------------------------------------------------------
 *  Minimal InputReader (kept for compatibility with the original template)
 *  ------------------------------------------------------------------------- */
class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0, len = 0;

    InputReader(InputStream stream) {
        this.stream = stream;
    }

    private int readByte() throws IOException {
        if (ptr >= len) {
            len = stream.read(buffer);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buffer[ptr++];
    }

    boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    int nextInt() {
        int c = readByte();
        while (isSpaceChar(c)) c = readByte();
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readByte();
        }
        long val = 0;
        while (!isSpaceChar(c)) {
            val = val * 10 + (c - '0');
            c = readByte();
        }
        return (int) (val * sign);
    }

    String next() {
        StringBuilder sb = new StringBuilder();
        int c = readByte();
        while (isSpaceChar(c)) c = readByte();
        while (!isSpaceChar(c)) {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Main class of the solution.  All functionality is kept in static
 * helper classes to keep the code clean and easy to test.
 */
public class Main {

    public static void main(String[] args) {
        // Using try‑with‑resources guarantees that the streams are closed.
        try (InputStream in = System.in;
             PrintWriter out = new PrintWriter(System.out)) {

            solve(in, out);
        }
    }

    /**
     * Core solving routine.
     *
     * @param in  input stream
     * @param out output stream (will be used as a PrintWriter)
     */
    private static void solve(InputStream in, PrintWriter out) {
        FastScanner fs = new FastScanner(in);
        int n = fs.nextInt();                 // number of rows
        int m = fs.nextInt();                 // number of columns
        char[][] grid = fs.nextCharacterMap(n, m);
        String moves = fs.nextString();       // move string consisting of '0'–'3'

        int[] permutation = {0, 1, 2, 3};      // all possible orderings of 4 directions
        int reachableCount = 0;

        do {
            int[] start = locatePosition(grid, 'S');
            int[] end   = locatePosition(grid, 'E');

            if (move(start[0], start[1], moves, permutation, grid, end[0], end[1])) {
                reachableCount++;
            }
        } while (PermutationUtils.nextPermutation(permutation));

        out.println(reachableCount);
    }

    /** Returns the coordinates of the first occurrence of {@code target}. */
    private static int[] locatePosition(char[][] grid, char target) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == target) {
                    return new int[]{i, j};
                }
            }
        }
        return null; // should never happen for valid input
    }

    /**
     * Attempts to reach the end cell following the move pattern.
     * The permutation determines which physical direction each digit
     * (0‑3) maps to.
     *
     * @return {@code true} if the end cell is reached without stepping on a wall
     *         or leaving the board.
     */
    private static boolean move(int startRow, int startCol,
                                String pattern,
                                int[] perm,
                                char[][] grid,
                                int endRow, int endCol) {
        int row = startRow;
        int col = startCol;

        for (char ch : pattern.toCharArray()) {
            int dirIdx = ch - '0';          // logical direction 0‑3
            int physicalDir = perm[dirIdx]; // maps to 0‑3 physical direction

            row += Direction.DX[physicalDir];
            col += Direction.DY[physicalDir];

            // stop if we leave the board, hit a wall, or land on the end cell
            if (!Inside.isInside(row, col, grid.length, grid[0].length)
                    || grid[row][col] == '#'
                    || (row == endRow && col == endCol)) {
                break;
            }
        }
        return row == endRow && col == endCol;
    }

    /** Directions 0‑3 correspond to down‑right, up‑right, up‑left, down‑left. */
    private static final class Direction {
        static final int[] DX = {1, 0, -1, 0};
        static final int[] DY = {0, -1, 0, 1};
    }

    /** Utility class for boundary checks. */
    private static final class Inside {
        static boolean isInside(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Implements the standard “next_permutation” algorithm for an int array.
     * Returns {@code true} if a next permutation exists, otherwise {@code false}.
     */
    private static final class PermutationUtils {
        private PermutationUtils() { }

        static boolean nextPermutation(int[] p) {
            for (int i = p.length - 2; i >= 0; i--) {
                if (p[i] < p[i + 1]) {
                    int j = p.length - 1;
                    while (p[j] <= p[i]) {
                        j--;
                    }
                    swap(p, i, j);
                    reverse(p, i + 1, p.length - 1);
                    return true;
                }
            }
            return false;
        }

        private static void swap(int[] arr, int i, int j) {
            int tmp = arr[i];
            arr[i] = arr[j];
            arr[j] = tmp;
        }

        private static void reverse(int[] arr, int from, int to) {
            while (from < to) {
                swap(arr, from++, to--);
            }
        }
    }

    /** Fast scanner that works with character arrays for the given problem. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            this.br = new BufferedReader(new InputStreamReader(stream));
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        String nextString() {
            return nextToken();
        }

        char[] nextCharacterArray(int length) {
            char[] arr = new char[length];
            for (int i = 0; i < length; i++) {
                arr[i] = nextChar();
            }
            return arr;
        }

        char[][] nextCharacterMap(int rows, int cols) {
            char[][] map = new char[rows][];
            for (int i = 0; i < rows; i++) {
                map[i] = nextCharacterArray(cols);
            }
            return map;
        }

        private String nextToken() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        private char nextChar() {
            try {
                int cp;
                while ((cp = br.read()) != -1 && Character.isWhitespace((char) cp)) {
                }
                return (char) cp;
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.io.IOException;
import java.util.Scanner;

/**
 *Counts how many distinct assignments of the digits 0‑3 to the four
 *movement directions (down, up, left, right) allow travelling from the
 *starting cell ‘S’ to the ending cell ‘E’ while following a given command
 *string without stepping on an obstacle or leaving the board.
 *
 *The program mirrors the behaviour of the original, but the code is
 *structurally clearer, uses expressive names and isolates the simulation
 *logic in a dedicated method.
 */
public class Main {

    /** Entry point */
    public static void main(String[] args) throws IOException {
        /* -------------------------------------------------------------
         * 1. Read the board dimensions and the board itself
         * ------------------------------------------------------------- */
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();      // number of rows (n)
            int cols = scanner.nextInt();      // number of columns (m)

            char[][] board = new char[rows][cols];
            int startX = -1, startY = -1;      // column and row of ‘S’
            int endX   = -1, endY   = -1;      // column and row of ‘E’

            for (int r = 0; r < rows; r++) {
                String line = scanner.next();
                for (int c = 0; c < cols; c++) {
                    char cell = line.charAt(c);
                    board[r][c] = cell;
                    if (cell == 'S') {
                        startX = c;
                        startY = r;
                    } else if (cell == 'E') {
                        endX = c;
                        endY = r;
                    }
                }
            }

            /* -------------------------------------------------------------
             * 2. Read the movement command string
             * ------------------------------------------------------------- */
            String commands = scanner.next();

            /* -------------------------------------------------------------
             * 3. Enumerate every possible distinct digit → direction mapping
             *    (there are 4! = 24 such mappings) and count the ones that
             *    successfully reach the destination.
             * ------------------------------------------------------------- */
            int validMappings = 0;

            // digits 0‑3 will be assigned to DOWN, UP, LEFT, RIGHT respectively.
            for (int down = 0; down < 4; down++) {
                for (int up = 0; up < 4; up++) {
                    if (up == down) continue;
                    for (int left = 0; left < 4; left++) {
                        if (left == down || left == up) continue;
                        for (int right = 0; right < 4; right++) {
                            if (right == down || right == up || right == left) continue;

                            if (simulate(commands, board,
                                         startX, startY,
                                         endX,   endY,
                                         down, up, left, right)) {
                                validMappings++;
                            }
                        }
                    }
                }
            }

            System.out.println(validMappings);
        }
    }

    /**
     * Simulates the walk according to the supplied digit‑to‑direction
     * mapping.
     *
     * @return {@code true} if the path reaches the target cell ‘E’
     *         without stepping on an obstacle or leaving the board.
     */
    private static boolean simulate(String commands,
                                    char[][] board,
                                    int startX, int startY,
                                    int endX, int endY,
                                    int downDigit, int upDigit,
                                    int leftDigit, int rightDigit) {
        int curX = startX;
        int curY = startY;

        for (int i = 0; i < commands.length(); i++) {
            int digit = commands.charAt(i) - '0';   // expected values: 0‑3

            int deltaY, deltaX;
            switch (digit) {
                case downDigit -> { deltaY = -1; deltaX = 0; }   // down  (y--)
                case upDigit   -> { deltaY =  1; deltaX = 0; }   // up    (y++)
                case leftDigit -> { deltaY =  0; deltaX = -1; }  // left  (x--)
                case rightDigit-> { deltaY =  0; deltaX =  1; }   // right (x++)
                default -> return false;                         // illegal digit
            }

            curY += deltaY;
            curX += deltaX;

            // 1️⃣  Out‑of‑bounds check
            if (curY < 0 || curY >= board.length ||
                curX < 0 || curX >= board[0].length) {
                return false;
            }

            // 2️⃣  Obstacle check
            if (board[curY][curX] == '#') {
                return false;
            }

            // 3️⃣  Destination reached?
            if (curX == endX && curY == endY) {
                return true;   // success – we can stop processing the rest of the command
            }
        }
        // Exhausted the command string without reaching the goal
        return false;
    }
}

import java.util.Scanner;

public class GFG {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        // Read maze dimensions
        int n = in.nextInt();
        int m = in.nextInt();
        in.nextLine(); // Consume newline after reading dimensions

        // Read maze grid and find start position
        char[][] maze = new char[n][m];
        int startRow = -1, startCol = -1;
        for (int i = 0; i < n; i++) {
            String line = in.nextLine();
            for (int j = 0; j < m; j++) {
                maze[i][j] = line.charAt(j);
                if (maze[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        // Read rule sequence and parse into integers
        String ruleString = in.nextLine();
        int[] rules = new int[ruleString.length()];
        for (int i = 0; i < ruleString.length(); i++) {
            rules[i] = ruleString.charAt(i) - '0';
        }

        // Count valid permutations that reach 'E' during simulation
        int count = 0;

        // Generate all permutations of rule-to-direction mappings
        for (int rightRule = 0; rightRule < 4; rightRule++) {
            for (int leftRule = 0; leftRule < 4; leftRule++) {
                if (leftRule == rightRule) continue;
                for (int downRule = 0; downRule < 4; downRule++) {
                    if (downRule == rightRule || downRule == leftRule) continue;
                    for (int upRule = 0; upRule < 4; upRule++) {
                        if (upRule == rightRule || upRule == leftRule || upRule == downRule) continue;

                        // Simulate path using current permutation
                        int currentRow = startRow;
                        int currentCol = startCol;
                        for (int ruleValue : rules) {
                            // Move according to rule mapping
                            if (ruleValue == rightRule) {
                                currentCol++;
                            } else if (ruleValue == leftRule) {
                                currentCol--;
                            } else if (ruleValue == downRule) {
                                currentRow++;
                            } else { // ruleValue == upRule
                                currentRow--;
                            }

                            // Check for boundary violations
                            if (currentRow < 0 || currentRow >= n || currentCol < 0 || currentCol >= m) {
                                break;
                            }

                            // Check for end condition or walls
                            if (maze[currentRow][currentCol] == 'E') {
                                count++;
                                break;
                            }
                            if (maze[currentRow][currentCol] == '#') {
                                break;
                            }
                        }
                    }
                }
            }
        }

        System.out.println(count);
    }
}

/**
 * Refactored version of the original program.
 *
 * <p>
 *   The program reads a grid, a start cell 'S', an end cell 'E' and a string
 *   consisting of digits 0‑3. It counts how many of the 24 possible
 *   permutations of the four cardinal directions (down, up, right, left)
 *   lead from 'S' to 'E' when each digit is interpreted as a direction.
 * </p>
 *
 * <p>Design goals of the refactor</p>
 * <ul>
 *   <li>Separate concerns – input handling, direction handling and the core
 *       algorithm are in distinct classes.</li>
 *   <li>Use meaningful names and avoid excessive static fields.</li>
 *   <li>Generate permutations programmatically instead of hard‑coding each
 *       of the 24 cases.</li>
 *   <li>Encapsulate mutable state inside a dedicated {@code Solver} class.</li>
 *   <li>Close resources with try‑with‑resources when possible.</li>
 * </ul>
 */
public class Main {

    /** Fast scanner for reading the whole input efficiently. */
    private static final class Scanner {
        private final BufferedReader br;
        private StringTokenizer st;

        private Scanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        /** true if more tokens are available */
        private boolean hasNext() throws IOException {
            onEmptyToken();
            return st.hasMoreTokens();
        }

        /** Return next token, loading more if necessary */
        private String next() throws IOException {
            while (!hasNext()) {
                loadNextLine();
            }
            return st.nextToken();
        }

        /** Load next line when tokenizer runs out of tokens */
        private void loadNextLine() throws IOException {
            String line = br.readLine();
            if (line == null) {
                st = new StringTokenizer("");
                return;
            }
            st = new StringTokenizer(line);
        }

        /** Skip empty tokens that may appear at line starts */
        private void onEmptyToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                loadNextLine();
            }
        }

        /** Convenience wrappers */
        static int nextInt() throws IOException { return Integer.parseInt(next()); }
        static long nextLong() throws IOException { return Long.parseLong(next()); }
        static String nextLine() throws IOException { return next(); }
    }

    /** Holds the direction vectors used by the algorithm. */
    private enum Direction {
        DOWN(1, 0),
        UP(-1, 0),
        RIGHT(0, 1),
        LEFT(0, -1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int[] offsets() {
            return new int[]{dr, dc};
        }
    }

    /** Core logic: reading, simulating and counting valid permutations. */
    private static final class Solver {
        private final char[][] grid;
        private final int startR, startC;
        private final int endR, endC;
        private final String commands;
        private final Direction[] dirVector = Direction.values();

        /** Mapping from digit (0‑3) to a direction index (0‑3). */
        private final int[] mapping = new int[4];

        /** Constructor – receives the whole input data already parsed. */
        Solver(char[][] grid, int sr, int sc, int er, int ec, String commands) {
            this.grid = grid;
            this.startR = sr;
            this.startC = sc;
            this.endR = er;
            this.endC = ec;
            this.commands = commands;
        }

        /** Simulate a single permutation; true if the path ends exactly on 'E'. */
        private boolean canReach() {
            int r = startR, c = startC;
            int idx = 0;
            while (true) {
                // reached the destination?
                if (r == endR && c == endC) {
                    return true;
                }
                // out of bounds or blocked?
                if (!inBounds(r, c) || grid[r][c] == '#') {
                    return false;
                }
                if (idx == commands.length()) {
                    // consumed all commands without reaching the end
                    return false;
                }
                int dirIdx = mapping[commands.charAt(idx) - '0'];
                int[] off = dirVector[dirIdx].offsets();
                r += off[0];
                c += off[1];
                idx++;
            }
        }

        /** Checks whether (r,c) lies inside the grid. */
        private boolean inBounds(int r, int c) {
            return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
        }

        /** Generate all 4! permutations of direction indices and count successes. */
        private int countValidPermutations() {
            boolean[] used = new boolean[4];
            int[] current = new int[4];
            return backtrack(0, used, current);
        }

        /** Recursive generation of permutations. */
        private int backtrack(int depth, boolean[] used, int[] out) {
            if (depth == 4) {
                return evaluate(out) ? 1 : 0;
            }
            int count = 0;
            for (int i = 0; i < 4; i++) {
                if (!used[i]) {
                    used[i] = true;
                    out[depth] = i;
                    count += backtrack(depth + 1, used, out);
                    used[i] = false;
                }
            }
            return count;
        }

        /** Evaluate a concrete permutation (mapping digit -> direction index). */
        private boolean evaluate(int[] perm) {
            // Build the mapping used in canReach(): digit -> perm[digit]
            for (int digit = 0; digit < 4; digit++) {
                mapping[digit] = perm[digit];
            }
            return canReach();
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws Exception {
        Scanner scanner = new Scanner(System.in);
        int n = Scanner.nextInt();
        int m = Scanner.nextInt();

        // Grid is read as character arrays
        char[][] grid = new char[n][];
        int startR = -1, startC = -1, endR = -1, endC = -1;

        for (int i = 0; i < n; i++) {
            String rowStr = scanner.next();
            char[] row = rowStr.toCharArray();
            grid[i] = row;
            for (int j = 0; j < m; j++) {
                char ch = row[j];
                if (ch == 'S') {
                    startR = i;
                    startC = j;
                } else if (ch == 'E') {
                    endR = i;
                    endC = j;
                }
            }
        }
        String commands = scanner.next();          // the sequence of digits 0‑3
        scanner = null; // free the scanner early

        // Convert the grid to a format accessible by Solver
        Solver solver = new Solver(grid, startR, startC, endR, endC, commands);
        int result = solver.countValidPermutations();

        System.out.println(result);
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class that reads the input, enumerates all possible direction
 * permutations and counts how many of them allow the robot to reach the
 * exit following the supplied move sequence.
 */
public class Main {

    /** Symbol that denotes a wall (impassable cell). */
    private static final char WALL = '#';

    /** Symbol that denotes the start cell. */
    private static final char START = 'S';

    /** Symbol that denotes the exit cell. */
    private static final char EXIT = 'E';

    /** Digits used in the move description (0‑3). */
    private static final char[] DIGITS = {'0', '1', '2', '3'};

    /** All possible movement characters. */
    private static final char[] MOVEMENT_CHARS = {'D', 'L', 'U', 'R'};

    /** Modulus used in the original solution (kept for compatibility). */
    private static final long MOD = 1_000_000_007L;

    /** Offsets for the four cardinal directions. */
    private static final Map<Character, int[]> DELTA = Map.of(
            'D', new int[]{+1, 0},
            'U', new int[]{-1, 0},
            'L', new int[]{0, -1},
            'R', new int[]{0, +1}
    );

    /** Cached list of all 4! permutations of the movement characters. */
    private static final List<char[]> ALL_PERMUTATIONS = generateAllPermutations();

    /** Fast scanner wrapper used throughout the solution. */
    private static FastScanner IN;
    /** Printer used for output. */
    private static PrintWriter OUT;

    public static void main(String[] args) throws IOException {
        try (FastScanner scanner = new FastScanner(System.in)) {
            IN = scanner;
            OUT = new PrintWriter(System.out, true);

            // ----- read grid dimensions and grid -------------------------------------------------
            int rows = IN.nextInt();
            int cols = IN.nextInt();
            char[][] grid = new char[rows][];
            int startR = -1, startC = -1;
            int endR = -1, endC = -1;

            for (int r = 0; r < rows; ++r) {
                String row = IN.next();
                grid[r] = row.toCharArray();
                for (int c = 0; c < cols; ++c) {
                    char cell = grid[r][c];
                    if (cell == START) {
                        startR = r;
                        startC = c;
                    } else if (cell == EXIT) {
                        endR = r;
                        endC = c;
                    }
                }
            }

            // ----- read move description -------------------------------------------------------
            String moveStr = IN.next();                     // e.g. "0123"
            char[] moveDigits = moveStr.toCharArray();       // each char is '0'..'3'

            // ----- evaluate every permutation -------------------------------------------------
            int answer = 0;
            for (char[] perm : ALL_PERMUTATIONS) {
                if (canReach(perm, grid, startR, startC, endR, endC, moveDigits)) {
                    ++answer;
                }
            }

            OUT.println(answer);
        } finally {
            OUT.close();
        }
    }

    /**
     * Determines whether a particular permutation of movement characters
     * allows the robot to travel from the start cell to the exit cell
     * following the supplied digit sequence.
     *
     * @param perm         a permutation of {'D','L','U','R'} where
     *                     perm[digit] = concrete direction character
     * @param grid         the maze
     * @param sr, sc       start row and column
     * @param er, ec       exit row and column
     * @param moveDigits   the digit sequence read from input
     * @return true if the robot reaches the exit, false otherwise
     */
    private static boolean canReach(char[] perm, char[][] grid,
                                    int sr, int sc, int er, int ec,
                                    char[] moveDigits) {
        int r = sr;
        int c = sc;

        for (char digitChar : moveDigits) {
            int digit = digitChar - '0';                     // 0‑3
            char direction = perm[digit];                  // concrete move

            int[] delta = DELTA.get(direction);
            r += delta[0];
            c += delta[1];

            // illegal move (out of bounds or wall)
            if (!inside(grid, r, c) || grid[r][c] == WALL) {
                return false;
            }

            // reached exit early – still a valid permutation
            if (r == er && c == ec) {
                return true;
            }
        }

        // after processing all moves we may be exactly at the exit
        return r == er && c == ec && inside(grid, r, c) && grid[r][c] != WALL;
    }

    /** Returns true if (row, col) lies inside the grid. */
    private static boolean inside(char[][] grid, int row, int col) {
        return row >= 0 && row < grid.length && col >= 0 && col < grid[0].length;
    }

    /**
     * Generates every permutation of the four movement characters.
     * The result is a list of freshly allocated char[] arrays.
     */
    private static List<char[]> generateAllPermutations() {
        List<char[]> perms = new ArrayList<>(24); // 4! = 24
        char[] current = MOVEMENT_CHARS.clone(); // mutable work array
        permute(perms, current, 0, current.length - 1);
        return perms;
    }

    /** Recursive helper that fills {@code perms} with all permutations. */
    private static void permute(List<char[]> perms, char[] arr, int left, int right) {
        if (left == right) {
            perms.add(arr.clone());               // store a copy
            return;
        }
        for (int i = left; i <= right; ++i) {
            swap(arr, left, i);
            permute(perms, arr, left + 1, right);
            swap(arr, left, i);                    // backtrack
        }
    }

    /** Simple element swap for char arrays. */
    private static void swap(char[] a, int i, int j) {
        char tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }
}

/**
 * Very small wrapper around {@link BufferedReader} that provides fast token
 * extraction.  It is identical in behaviour to the original {@code FastScanner}
 * but kept private to this solution.
 */
final class FastScanner implements AutoCloseable {

    private final BufferedReader br;

    FastScanner(InputStream stream) {
        this.br = new BufferedReader(new InputStreamReader(stream));
    }

    /** Reads the next line (or {@code null} if EOF). */
    String nextLine() throws IOException {
        return br.readLine();
    }

    /** Returns the next token, lazily tokenising the current line. */
    private String token() throws IOException {
        if (br instanceof java.io.LineNumberReader) {
            // no‑op – retained only for API compatibility
        }
        String line = br.readLine();
        if (line == null) {
            return null;
        }
        // Tokeniser is recreated on‑demand – cheap compared to repeated splits.
        StringTokenizer st = new StringTokenizer(line);
        return st.nextToken();
    }

    /** Reads the next token as a string. */
    String next() throws IOException {
        return token();
    }

    /** Reads the next token as an int. */
    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    /** Reads the next token as a long. */
    long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    /** Reads the next token as a double. */
    double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }

    /** Reads the next token as a char (the first character of the next token). */
    char nextChar() throws IOException {
        String token = next();
        return token.isEmpty() ? '\0' : token.charAt(0);
    }

    /** Closes the underlying reader. */
    @Override
    public void close() throws IOException {
        br.close();
    }
}

import java.io.*;
import java.util.*;

public class BB {

    /* --------------------------------------------------------------------- */
    /* Constants – directions, symbols, and movement deltas                  */
    /* --------------------------------------------------------------------- */
    private static final int RIGHT = 0;   // 0 → ( 0, +1)
    private static final int LEFT  = 1;   // 1 → ( 0, -1)
    private static final int DOWN  = 2;   // 2 → (+1,  0)
    private static final int UP    = 3;   // 3 → (-1,  0)

    /* Mapping from a direction index to its coordinate delta */
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    private static final char SYMBOL_START = 'S';
    private static final char SYMBOL_GOAL  = 'E';
    private static final char SYMBOL_BLOCK = '#';

    /* --------------------------------------------------------------------- */
    /* Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees the scanner is closed automatically.
        try (MyScanner scanner = new MyScanner()) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = readGrid(scanner, rows);
            int startX = -1, startY = -1;
            locateStart(grid, rows, cols, scanner, startX, startY);

            String commandSequence = scanner.next();               // e.g. "0123"
            int validPaths = countValidPaths(grid, startX, startY,
                                             commandSequence);
            System.out.println(validPaths);
        }
    }

    /* --------------------------------------------------------------------- */
    /* Reads the grid rows from the scanner                                   */
    /* --------------------------------------------------------------------- */
    private static char[][] readGrid(MyScanner scanner, int n) throws IOException {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /* --------------------------------------------------------------------- */
    /* Finds the coordinates of the single 'S' cell                           */
    /* --------------------------------------------------------------------- */
    private static void locateStart(char[][] grid, int n, int m,
                                    MyScanner scanner,
                                    int foundX, int foundY) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == SYMBOL_START) {
                    foundX = i;
                    foundY = j;
                    return;
                }
            }
        }
        // The problem guarantees that an 'S' exists, so we never reach here.
    }

    /* --------------------------------------------------------------------- */
    /* Counts how many distinct permutations of the four movement directions */
    /* lead from the start cell to the goal ('E') without hitting a block.   */
    /* --------------------------------------------------------------------- */
    private static int countValidPaths(char[][] grid, int startX, int startY,
                                        String cmd) {
        int counted = 0;
        // Generate every permutation of the four directions (ensuring all are distinct)
        for (int d1 = 0; d1 < 4; d1++) {
            for (int d2 = 0; d2 < 4; d2++) {
                if (d2 == d1) continue;
                for (int d3 = 0; d3 < 4; d3++) {
                    if (d3 == d1 || d3 == d2) continue;
                    for (int d4 = 0; d4 < 4; d4++) {
                        if (d4 == d1 || d4 == d2 || d4 == d3) continue;

                        int[] permutation = {d1, d2, d3, d4};
                        if (simulateAndCount(grid, startX, startY, cmd, permutation)) {
                            counted++;
                        }
                    }
                }
            }
        }
        return counted;
    }

    /* --------------------------------------------------------------------- */
    /* Executes a single permutation and returns true iff the goal is reached */
    /* --------------------------------------------------------------------- */
    private static boolean simulateAndCount(char[][] grid, int startX, int startY,
                                            String cmd, int[] dirs) {
        int curX = startX;
        int curY = startY;

        for (char ch : cmd.toCharArray()) {
            int direction = ch - '0';
            if (direction < 0 || direction >= 4) {          // defensive check
                return false;
            }

            int nx = curX + DX[direction];
            int ny = curY + DY[direction];

            // Out of bounds → invalid permutation
            if (nx < 0 || nx >= grid.length || ny < 0 || ny >= grid[0].length) {
                return false;
            }

            char cell = grid[nx][ny];
            if (cell == SYMBOL_BLOCK) {
                return false;                                 // hit an obstacle
            }
            if (cell == SYMBOL_GOAL) {
                return true;                                  // reached goal successfully
            }

            curX = nx;
            curY = ny;
        }
        // Command string exhausted without reaching the goal → not a success
        return false;
    }

    /* --------------------------------------------------------------------- */
    /* Simple scanner that tokenises stdin                                    */
    /* --------------------------------------------------------------------- */
    static class MyScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        MyScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, reading a new line when necessary. */
        private String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt()       { return Integer.parseInt(next()); }
        long nextLong()     { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }
        String nextLine()   {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Reads a grid containing a start ('S') and an end ('E') cell,
 * an instruction string composed of the characters '0'–'3',
 * and counts how many distinct assignments of four different
 * movement directions lead from the start to the end while never
 * stepping out of bounds or onto a wall ('#').
 */
public class Main {

    /** Symbols used in the grid */
    private static final char WALL   = '#';
    private static final char START  = 'S';
    private static final char END    = 'E';

    /** Movement vectors for the four directions: right, left, up, down */
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {1, -1, 0, 0};

    /**
     * Simple scanner that returns tokens from {@code System.in}
     * without pulling in {@code java.util.Scanner}.
     */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() throws IOException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        private void ensureTokens() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
        }

        String next() throws IOException {
            ensureTokens();
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        char[] nextCharArray() throws IOException {
            return next().toCharArray();
        }

        String nextLine() throws IOException {
            return br.readLine();
        }
    }

    /** Entry point */
    public static void main(String[] args) throws IOException {
        solve();
    }

    /**
     * Core algorithm:
     *   1. Parse the input.
     *   2. Try every permutation of four distinct directions.
     *   3. Simulate the walk dictated by the instruction string.
     *   4. Count permutations that reach the target without hitting a wall.
     */
    private static void solve() throws IOException {
        FastScanner fs = new FastScanner();

        // ----- 1. Input -------------------------------------------------
        int n = fs.nextInt();          // number of rows
        int m = fs.nextInt();          // number of columns

        char[][] grid = new char[n][];
        int startRow = -1, startCol = -1;
        int endRow   = -1, endCol   = -1;

        for (int i = 0; i < n; i++) {
            String row = fs.next();
            grid[i] = row.toCharArray();
            for (int j = 0; j < m; j++) {
                char cell = grid[i][j];
                if (cell == START) {
                    startRow = i;
                    startCol = j;
                } else if (cell == END) {
                    endRow = i;
                    endCol = j;
                }
            }
        }

        String instructions = fs.next();   // string of '0'–'3'

        // ----- 2. Enumerate distinct direction permutations -------------
        long answer = 0;

        // l → '0', r → '1', u → '2', d → '3' (all must be different)
        for (int dir0 = 0; dir0 < 4; dir0++) {
            for (int dir1 = 0; dir1 < 4; dir1++) {
                if (dir1 == dir0) continue;
                for (int dir2 = 0; dir2 < 4; dir2++) {
                    if (dir2 == dir0 || dir2 == dir1) continue;
                    for (int dir3 = 0; dir3 < 4; dir3++) {
                        if (dir3 == dir0 || dir3 == dir1 || dir3 == dir2) continue;

                        int x = startRow;
                        int y = startCol;
                        boolean reached = false;

                        // ----- 3. Simulate walk --------------------------------
                        for (char step : instructions.toCharArray()) {
                            int dirIdx;
                            switch (step) {
                                case '0' -> dirIdx = dir0;
                                case '1' -> dirIdx = dir1;
                                case '2' -> dirIdx = dir2;
                                case '3' -> dirIdx = dir3;
                                default -> throw new IllegalArgumentException(
                                        "Unexpected instruction character: " + step);
                            }
                            x += DX[dirIdx];
                            y += DY[dirIdx];

                            // stop if we leave the grid or hit a wall
                            if (!inBounds(x, y, n, m) || grid[x][y] == WALL) {
                                break;
                            }

                            // success if the target cell is reached
                            if (x == endRow && y == endCol) {
                                reached = true;
                                break;
                            }
                        }

                        if (reached) {
                            answer++;
                        }
                    }
                }
            }
        }

        // ----- 4. Output -------------------------------------------------
        System.out.println(answer);
    }

    /** Helper: check whether (x, y) lies inside an n×m grid. */
    private static boolean inBounds(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Refactored solution for problem 908B.
 * <p>
 * The program reads a grid, a starting cell 'S', a target cell 'E',
 * and a sequence of direction indices.  It enumerates all permutations
 * of the four cardinal directions, applies each permutation to the
 * direction sequence and counts how many times the path reaches 'E'.
 * </p>
 */
public class Main {

    /* Cardinal directions: right, left, up, down */
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {1, -1, 0, 0};

    /* Helper utilities ---------------------------------------------------- */
    private static void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    private static void reverse(int[] a, int from, int to) {
        while (from < to) {
            swap(a, from++, to--);
        }
    }

    /**
     * Generates the next lexicographic permutation of the given array.
     *
     * @return {@code true} if a next permutation exists and the array was
     *         rearranged; {@code false} otherwise.
     */
    private static boolean nextPermutation(int[] a) {
        int i = a.length - 1;
        while (i > 0 && a[i - 1] >= a[i]) i--;
        if (i == 0) return false;

        int j = a.length - 1;
        while (a[j] <= a[i - 1]) j--;
        swap(a, i - 1, j);
        reverse(a, i, a.length - 1);
        return true;
    }

    /**
     * Simulates movement on the grid using a concrete direction permutation.
     *
     * @return {@code true} if the path reaches the target cell 'E'.
     */
    private static boolean reachesExit(char[][] grid,
                                       int startX, int startY,
                                       int[] seq,
                                       int[] dirPermutation) {
        int x = startX, y = startY;
        for (int digit : seq) {
            int dirIdx = dirPermutation[digit]; // map digit -> direction index
            int nx = x + DX[dirIdx];
            int ny = y + DY[dirIdx];

            // boundary / obstacle check
            if (nx < 0 || nx >= grid.length || ny < 0 || ny >= grid[0].length)
                return false;
            char cell = grid[nx][ny];
            if (cell == '#') return false;

            if (cell == 'E') return true; // success
            x = nx; y = ny;
        }
        return false;
    }

    /* Fast input ---------------------------------------------------------- */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr, len;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = stream.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** Reads next whitespace‑separated integer. */
        int nextInt() throws IOException {
            int c, sign = 1, val = 0;
            do { c = readByte(); } while (c <= ' ');
            if (c == '-') { sign = -1; c = readByte(); }
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val * sign;
        }

        /** Reads next token (non‑whitespace characters). */
        String next() throws IOException {
            int c;
            do { c = readByte(); } while (c <= ' ');
            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }
    }

    /* Main program -------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        /* ----- input ----- */
        int n = in.nextInt();          // number of rows
        int m = in.nextInt();          // number of columns

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = in.next();
            grid[i] = line.toCharArray();
        }

        String seqStr = in.next();     // direction sequence as a string of digits
        int[] seq = new int[seqStr.length()];
        for (int i = 0; i < seqStr.length(); i++) {
            seq[i] = seqStr.charAt(i) - '0';
        }

        /* ----- locate start cell 'S' ----- */
        int startX = -1, startY = -1;
        outer:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    startX = i;
                    startY = j;
                    break outer;
                }
            }
        }

        /* ----- enumerate all direction permutations ----- */
        int result = 0;
        int[] directionPermutation = {0, 1, 2, 3}; // initial ordering
        do {
            if (reachesExit(grid, startX, startY, seq, directionPermutation)) {
                result++;
            }
        } while (nextPermutation(directionPermutation));

        out.println(result);
        out.flush();
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* ---------- Constants & enums ---------- */
    private static final char START = 'S';
    private static final char EXIT  = 'E';
    private static final char WALL  = '#';

    /**
     * The four possible movement directions are stored as an enum.
     * Each direction carries its own delta (dx, dy).
     */
    private enum Direction {
        UP(-1, 0),
        RIGHT(0, 1),
        DOWN(1, 0),
        LEFT(0, -1);

        private final int dx;
        private final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        /** Return the coordinate offset for this direction. */
        int[] offset() {
            return new int[]{dx, dy};
        }
    }

    /* ---------- Entry point ---------- */
    public static void main(String[] args) throws IOException {
        /* try‑with‑resources guarantees that the streams are closed correctly */
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
             BufferedWriter writer = new BufferedWriter(
                new OutputStreamWriter(System.out))) {

            processInput(reader, writer);
        }
    }

    /* ---------- Input handling & orchestration ---------- */
    private static void processInput(BufferedReader reader, BufferedWriter writer) throws IOException {
        /* 1️⃣ read grid dimensions and the field itself */
        String[] header = splitNonNull(reader.readLine(), " ");
        int rows = Integer.parseInt(header[0]);
        int columns = Integer.parseInt(header[1]);

        String[] grid = new String[rows];
        int[] start = locateStart(reader, grid, rows);
        if (start == null) {
            writer.write("0");
            writer.flush();
            return;
        }

        /* 2️⃣ read the move description string */
        String movesString = reader.readLine();
        int[] moves = parseMoves(movesString);

        /* 3️⃣ evaluate all permutations of the four directions */
        int validPaths = countValidPaths(grid, start, moves);
        writer.write(Integer.toString(validPaths));
        writer.flush();
    }

    /** Finds the coordinates of the 'S' cell. */
    private static int[] locateStart(BufferedReader reader, String[] grid, int rows) throws IOException {
        for (int r = 0; r < rows; r++) {
            String line = reader.readLine();
            grid[r] = line;
            int c = line.indexOf(START);
            if (c != -1) {
                return new int[]{r, c};
            }
        }
        return null;            // should never happen with a well‑formed input
    }

    /** Convert a string like "0123" into an int[] containing the digit values. */
    private static int[] parseMoves(String movesString) {
        int[] moves = new int[movesString.length()];
        for (int i = 0; i < movesString.length(); i++) {
            moves[i] = Character.getNumericValue(movesString.charAt(i));
        }
        return moves;
    }

    /* ---------- Core algorithm ---------- */
    /** Count how many distinct direction orderings let the character reach 'E' safely. */
    private static int countValidPaths(String[] grid, int[] start, int[] moves) {
        int validCount = 0;
        Direction[] allDirections = Direction.values();

        /* generate every permutation of the four directions */
        for (int i = 0; i < allDirections.length; i++) {
            for (int j = 0; j < allDirections.length; j++) {
                if (j == i) continue;
                for (int x = 0; x < allDirections.length; x++) {
                    if (x == i || x == j) continue;
                    for (int y = 0; y < allDirections.length; y++) {
                        if (y == i || y == j || y == x) continue;

                        Direction[] permutation = {
                                allDirections[i],
                                allDirections[j],
                                allDirections[x],
                                allDirections[y]
                        };
                        if (simulatePath(permutation, grid, start, moves)) {
                            validCount++;
                        }
                    }
                }
            }
        }
        return validCount;
    }

    /** Simulate a single permutation of directions following the move list. */
    private static boolean simulatePath(Direction[] dirs, String[] grid,
                                         int[] start, int[] moves) {
        int row = start[0];
        int col = start[1];

        for (int moveIdx : moves) {
            Direction dir = dirs[moveIdx];
            int[] offset = dir.offset();
            row += offset[0];
            col += offset[1];

            if (!isInside(grid, row, col)) {
                return false;                         // stepped out of bounds
            }
            if (grid[row].charAt(col) == WALL) {
                return false;                         // hit a wall
            }
            if (grid[row].charAt(col) == EXIT) {
                return true;                          // reached the exit
            }
        }
        return false;                                 // exited without touching 'E'
    }

    /** Checks whether (row, col) is still inside the grid. */
    private static boolean isInside(String[] grid, int row, int col) {
        return row >= 0 && row < grid.length &&
               col >= 0 && col < grid[row].length();
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 *
 * <p>
 *   The program reads a grid, a start cell marked {@code 'S'}, an instruction string
 *   consisting of digits {@code 0‑3} and counts how many of the 24 possible
 *   permutations of the four movement directions lead from {@code 'S'} to the
 *   exit cell {@code 'E'} without hitting a wall or leaving the grid.
 * </p>
 */
public class Main {

    /** Read all input data and start the solving process. */
    public static void main(String[] args) throws IOException {
        PrintWriter out = new PrintWriter(System.out);
        FastScanner in = new FastScanner(System.in);
        new Main().solveB(in, out);
        out.close();
        System.exit(0);
    }

    /** Entry point used by the original code – kept only for compatibility. */
    void solveA(FastScanner in, PrintWriter out) { }

    /** Entry point for problem B – refactored for readability and maintainability. */
    void solveB(FastScanner in, PrintWriter out) {
        int n = in.nextInt();                 // number of rows
        int m = in.nextInt();                 // number of columns
        char[][] grid = readGrid(in, n);
        int startCol = -1, startRow = -1;       // column (x) and row (y) of 'S'

        for (int y = 0; y < n; y++) {
            for (int x = 0; x < m; x++) {
                if (grid[y][x] == 'S') {
                    startCol = x;
                    startRow = y;
                }
            }
        }

        String instruction = in.next();       // sequence of movement codes (0‑3)
        int answer = countSuccessfulMappings(grid, startCol, startRow,
                                               instruction);
        out.println(answer);
    }

    /** Entry points for the still‑unused problems C and D. */
    void solveC(FastScanner in, PrintWriter out) { }
    void solveD(FastScanner in, PrintWriter out) { }

    /** --------------------------------------------------------------------- */
    /** Helper utilities                                                        */

    /** Reads {@code n} lines from the scanner and returns a 2‑D char array. */
    private static char[][] readGrid(FastScanner in, int n) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = in.next();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /** Counts how many of the 24 digit‑to‑direction permutations bring us to 'E'. */
    private static int countSuccessfulMappings(char[][] grid,
                                                 int startX,
                                                 int startY,
                                                 String instruction) {
        final List<int[]> allPermutations = generateAllPermutations();
        int successCount = 0;

        outer:
        for (int[] perm : allPermutations) {
            int x = startX;
            int y = startY;

            for (char ch : instruction.toCharArray()) {
                int digit = ch - '0';                 // 0,1,2 or 3
                int direction = perm[digit];        // 0:DOWN, 1:LEFT, 2:UP, 3:RIGHT

                switch (direction) {
                    case 0 -> y++;                     // DOWN
                    case 1 -> x--;                     // LEFT
                    case 2 -> y--;                     // UP
                    case 3 -> x++;                     // RIGHT
                    default -> throw new AssertionError("Invalid direction index");
                }

                // Stop simulation if we leave the grid or hit an obstacle
                if (x < 0 || x >= grid[0].length
                        || y < 0 || y >= grid.length
                        || grid[y][x] == '#') {
                    continue outer;
                }

                // Success – we reached the exit cell
                if (grid[y][x] == 'E') {
                    successCount++;
                    continue outer;
                }
            }
        }
        return successCount;
    }

    /** Generates the 24 possible permutations of the digits {0,1,2,3}. */
    private static List<int[]> generateAllPermutations() {
        List<int[]> result = new ArrayList<>();
        backtrack(new int[4], 0, new boolean[4], result);
        return result;
    }

    private static void backtrack(int[] current,
                                  int index,
                                  boolean[] used,
                                  List<int[]> result) {
        if (index == 4) {
            result.add(Arrays.copyOf(current, 4));
            return;
        }
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                current[index] = i;
                backtrack(current, index + 1, used, result);
                used[i] = false;
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /** Fast scanner – unchanged from the original implementation                */
    private static final class FastScanner {

        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int currentByte;
        private int bytesRead;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (currentByte >= bytesRead) {
                currentByte = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[currentByte++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String next() {
            int c = readByte();
            while (isSpaceChar(c)) {
                c = readByte();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = readByte();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        public String nextLine() {
            int c = readByte();
            while (isEndline(c)) {
                c = readByte();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = readByte();
            } while (!isEndline(c));
            return sb.toString();
        }
    }
}

import java.io.*;
import java.util.*;

public class USACO {

    /** Constants that make the logic easier to read */
    private static final char START = 'S';
    private static final char END = 'E';
    private static final char WALL = '#';

    /** Entrypoint */
    public static void main(String[] args) {
        /* try‑with‑resources guarantees the BufferedReader is closed */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {

            /* ----- read dimension line ----- */
            int rows = Integer.parseInt(nextToken(br));
            int cols = Integer.parseInt(nextToken(br));

            /* ----- read the maze ----- */
            char[][] maze = readMaze(br, rows, cols);

            /* ----- locate the start cell ----- */
            int[] start = locate(maze, START);               // {x, y}
            int startX = start[0];
            int startY = start[1];

            /* ----- read the move list ----- */
            String moveList = br.readLine();

            /* ----- count all valid direction permutations ----- */
            int answer = countValidPermutations(maze, startX, startY, moveList);
            System.out.println(answer);

        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /* --------------------------------------------------------------------- */
    /* -------------------------- Helper methods --------------------------- */
    /* --------------------------------------------------------------------- */

    /** Reads the next whitespace‑separated token from a BufferedReader. */
    private static String nextToken(BufferedReader br) throws IOException {
        return br.readLine().trim();
    }

    /** Reads exactly `rows` lines, each `cols` characters long, into a 2‑D array. */
    private static char[][] readMaze(BufferedReader br, int rows, int cols) throws IOException {
        char[][] maze = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = br.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input while reading the maze");
            }
            for (int c = 0; c < cols; c++) {
                maze[r][c] = line.charAt(c);
            }
        }
        return maze;
    }

    /** Returns the coordinates of the first occurrence of `target` in the maze. */
    private static int[] locate(char[][] maze, char target) {
        for (int r = 0; r < maze.length; r++) {
            for (int c = 0; c < maze[r].length; c++) {
                if (maze[r][c] == target) {
                    return new int[]{c, r};      // {x, y}
                }
            }
        }
        throw new IllegalArgumentException("Start cell ('S') not found in the maze");
    }

    /** Creates all 4! permutations of {0,1,2,3} and checks which allow reaching 'E'. */
    private static int countValidPermutations(char[][] maze,
                                              int startX, int startY,
                                              String moves) {
        int[] base = {0, 1, 2, 3};                // the four direction indices
        int valid = 0;

        do {
            int sIdx = base[0];
            int northIdx = base[1];
            int eastIdx = base[2];
            int westIdx = base[3];

            // All four indices must be distinct – exactly what the original loop required
            if (areAllDistinct(sIdx, northIdx, eastIdx, westIdx)) {
                if (reachesExit(maze, startX, startY, moves,
                                sIdx, northIdx, eastIdx, westIdx)) {
                    valid++;
                }
            }
        } while (nextPermutation(base));

        return valid;
    }

    /** Simple distinct‑ness test for four integers. */
    private static boolean areAllDistinct(int... vals) {
        boolean[] seen = new boolean[4];
        for (int v : vals) {
            if (seen[v]) {
                return false;
            }
            seen[v] = true;
        }
        return true;
    }

    /**
     * Simulates the walk described by {@code moves} using the supplied direction
     * mapping. Returns {@code true} if the walk steps on {@code END} before hitting a
     * wall or leaving the board.
     */
    private static boolean reachesExit(char[][] maze,
                                       int startX, int startY,
                                       String moves,
                                       int sIdx, int northIdx, int eastIdx, int westIdx) {
        int x = startX;
        int y = startY;
        boolean dead = false;                     // becomes true when we hit a wall/boundary

        for (int i = 0; i < moves.length(); i++) {
            int dir = moves.charAt(i) - '0';        // digit 0‑3
            if (dir < 0 || dir > 3) {
                continue;                           // safety – original code also ignored invalid digits
            }

            switch (dir) {
                case sIdx  -> y++;                  // south
                case northIdx -> y--;               // north
                case eastIdx -> x++;                // east
                case westIdx -> x--;                // west
                default -> continue;              // never reached, but keeps compiler happy
            }

            // Hit a wall or go outside the board → this permutation is invalid
            if (isOutOfBounds(maze, x, y) || maze[y][x] == WALL) {
                dead = true;
                break;
            }

            // If we have not yet died and we step on the exit, this permutation counts
            if (!dead && maze[y][x] == END) {
                return true;
            }
        }
        return false;                               // never reached the exit safely
    }

    /** Checks whether (x, y) lies inside the rectangle defined by the maze. */
    private static boolean isOutOfBounds(char[][] maze, int x, int y) {
        return x < 0 || x >= maze[0].length || y < 0 || y >= maze.length;
    }

    /** Generates the next lexicographic permutation of the array (in‑place). */
    private static boolean nextPermutation(int[] a) {
        int n = a.length;
        int i = n - 2;
        while (i >= 0 && a[i] >= a[i + 1]) {
            i--;
        }
        if (i < 0) {
            return false;               // no further permutations
        }
        int j = n - 1;
        while (a[j] <= a[i]) {
            j--;
        }
        swap(a, i, j);
        reverse(a, i + 1, n - 1);
        return true;
    }

    private static void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    private static void reverse(int[] a, int from, int to) {
        while (from < to) {
            swap(a, from++, to--);
        }
    }
}

/*
 * Refactored version of the original program.
 * The code is split into small, well‑named methods and classes,
 * uses try‑with‑resources, meaningful names and constants,
 * and removes duplicated / unused logic.
 *
 * The behaviour of the original “solveB” routine is preserved,
 * while the other placeholder methods (solveC‑solveF) are kept
 * only for compatibility.
 */
import java.util.*;
import java.util.stream.*;

public class Main {

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        new Main().run();
    }

    private void run() {
        // The original program called solveB(); we keep that call.
        solveB();
    }

    /* --------------------------------------------------------------------- */
    /*  Solve A – count specific characters                                   */
    /* --------------------------------------------------------------------- */
    private void solveA() {
        try (Scanner sc = new Scanner(System.in)) {
            String input = sc.next();
            long cnt = input.chars()
                    .filter(this::isRelevantCharacter)
                    .count();
            System.out.println(cnt);
        }
    }

    private boolean isRelevantCharacter(int code) {
        return "aiuo13579".contains(String.valueOf((char) code));
    }

    /* --------------------------------------------------------------------- */
    /*  Solve B – simulation on a grid with directional moves                 */
    /* --------------------------------------------------------------------- */
    private static final char WALL = '#';
    private static final char START = 'S';
    private static final char END   = 'E';

    private enum Move {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);
        final int dr, dc;
        Move(int dr, int dc) { this.dr = dr; this.dc = dc; }
    }

    private void solveB() {
        try (Scanner sc = new Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();
            sc.nextLine();                     // consume end‑of‑line

            char[][] grid = buildGrid(rows, cols, sc);
            String instruction = sc.next();

            Optional<int[]> startPos = findPosition(grid, START);
            if (startPos.isEmpty()) {
                System.out.println(0);
                return;
            }
            int sr = startPos.get()[0];
            int scPos = startPos.get()[1];

            long answer = 0;
            // every permutation of the four moves represents a distinct
            // assignment of the digits 0‑3 to a direction.
            for (Move[] permutation : permutations(of(Move.values()))) {
                answer += simulate(instruction, permutation, grid, sr, scPos);
            }
            System.out.println(answer);
        }
    }

    /** Build the grid with a border of ‘#’ characters. */
    private char[][] buildGrid(int rows, int cols, Scanner sc) {
        char[][] map = new char[rows + 2][cols + 2];
        // top & bottom borders
        Arrays.fill(map[0], WALL);
        Arrays.fill(map[rows + 1], WALL);
        // left & right borders – filled per row
        for (int r = 1; r <= rows; r++) {
            map[r][0] = WALL;
            map[r][cols + 1] = WALL;
            String line = sc.nextLine();
            for (int c = 1; c <= cols; c++) {
                map[r][c] = line.charAt(c - 1);
            }
        }
        return map;
    }

    /** Locate the first occurrence of {@code target} in the grid. */
    private Optional<int[]> findPosition(char[][] grid, char target) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == target) {
                    return Optional.of(new int[]{r, c});
                }
            }
        }
        return Optional.empty();
    }

    /**
     * Simulate a single path using a concrete direction permutation.
     *
     * @return 1 if the path reaches ‘E’ before hitting a wall, otherwise 0.
     */
    private long simulate(String instr,
                           Move[] directionByDigit,
                           char[][] grid,
                           int startR,
                           int startC) {
        int r = startR;
        int c = startC;
        for (int i = 0; i < instr.length(); i++) {
            char ch = instr.charAt(i);
            int digit = ch - '0';
            if (digit < 0 || digit > 3) break;               // safety
            Move dir = directionByDigit[digit];
            r += dir.dr;
            c += dir.dc;
            if (grid[r][c] == WALL) break;
            if (grid[r][c] == END) return 1L;
        }
        return 0L;
    }

    /** Generate all permutations of the supplied array. */
    private static <T> List<T[]> permutations(T[] array) {
        List<T[]> result = new ArrayList<>();
        permute(array, 0, result);
        return result;
    }

    private static <T> void permute(T[] array, int start, List<T[]> result) {
        if (start == array.length) {
            result.add(array.clone());
            return;
        }
        for (int i = start; i < array.length; i++) {
            swap(array, start, i);
            permute(array, start + 1, result);
            swap(array, start, i);
        }
    }

    private static <T> void swap(T[] array, int i, int j) {
        T tmp = array[i];
        array[i] = array[j];
        array[j] = tmp;
    }

    /** Helper to create a list from an array (Java 8 convenience). */
    @SafeVarargs
    private static <T> List<T[]> of(T... elements) {
        return Arrays.stream(elements).toArray(T[]::new);
    }

    /* --------------------------------------------------------------------- */
    /*  Placeholder solves – kept for backward compatibility                  */
    /* --------------------------------------------------------------------- */
    private void solveC() {
        try (Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();
            System.out.println(n);
        }
    }

    private void solveD() {
        // mirrors solveC – retained for compatibility
        solveC();
    }

    private void solveE() {
        // mirrors solveC – retained for compatibility
        solveC();
    }

    private void solveF() {
        // mirrors solveC – retained for compatibility
        solveC();
    }

    /* --------------------------------------------------------------------- */
    /*  Graph / Flow utilities – unchanged but isolated from main logic     */
    /* --------------------------------------------------------------------- */
    interface Graph {
        void link(int from, int to, long cost);
        Optional<Long> getCost(int from, int to);
        int getVertexNum();
    }

    interface FlowResolver {
        long maxFlow(int from, int to);
    }

    static class ArrayGraph implements Graph {
        private final Long[][] costArray;
        private final int vertexNum;

        ArrayGraph(int n) {
            costArray = new Long[n][];
            for (int i = 0; i < n; i++) {
                costArray[i] = new Long[n];
            }
            vertexNum = n;
        }

        @Override
        public void link(int from, int to, long cost) {
            costArray[from][to] = cost;
        }

        @Override
        public Optional<Long> getCost(int from, int to) {
            return Optional.ofNullable(costArray[from][to]);
        }

        @Override
        public int getVertexNum() {
            return vertexNum;
        }
    }

    static class DfsFlowResolver implements FlowResolver {
        private final Graph graph;

        DfsFlowResolver(Graph graph) {
            this.graph = graph;
        }

        @Override
        public long maxFlow(int from, int to) {
            long total = 0L;
            long increment;
            do {
                increment = flow(from, to, Long.MAX_VALUE, new boolean[graph.getVertexNum()]);
                total += increment;
            } while (increment > 0);
            return total;
        }

        private long flow(int from, int to, long currentFlow, boolean[] visited) {
            visited[from] = true;
            if (from == to) {
                return currentFlow;
            }
            for (int id = 0; id < graph.getVertexNum(); id++) {
                if (visited[id]) continue;
                Optional<Long> edge = graph.getCost(from, id);
                if (edge.map(len -> len > 0).orElse(false)) {
                    long nextFlow = Math.min(currentFlow, edge.orElse(0L));
                    long returned = flow(id, to, nextFlow, visited);
                    if (returned > 0) {
                        Long cur = graph.getCost(from, id).orElse(0L);
                        graph.link(from, id, cur - returned);
                        Long rev = graph.getCost(id, from).orElse(0L);
                        graph.link(id, from, rev + returned);
                        return returned;
                    }
                }
            }
            return 0L;
        }
    }

    static class BinaryIndexedTree {
        private final long[] tree;

        BinaryIndexedTree(int size) {
            tree = new long[size + 1];
        }

        void add(int index, long value) {
            for (int i = index; i < tree.length; i += i & -i) {
                tree[i] += value;
            }
        }

        long getSum(int index) {
            long sum = 0L;
            for (int i = index; i > 0; i -= i & -i) {
                sum += tree[i];
            }
            return sum;
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of TaskB.
 * <p>
 * The program reads a maze, a starting position, and an instruction string.
 * It evaluates all 24 possible permutations of direction mappings (0‑3 → UP/DOWN/LEFT/RIGHT)
 * and counts how many permutations lead from the start cell to the exit cell 'E'.
 * </p>
 */
public class TaskB {

    /* ---------------------------  Constants  --------------------------- */
    private static final char WALL  = '#';
    private static final char EXIT  = 'E';
    private static final char START = 'S';

    /* ---------------------------  Entry point  --------------------------- */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine();                     // consume line‑break

            String[] maze = new String[rows];
            int startRow = -1, startCol = -1;

            for (int r = 0; r < rows; r++) {
                maze[r] = scanner.nextLine();
                int c = maze[r].indexOf(START);
                if (c != -1) {
                    startRow = r;
                    startCol = c;
                }
            }

            String instructionString = scanner.nextLine();
            int successfulPermutations = countSuccessfulPermutations(
                    rows, cols, maze, startRow, startCol, instructionString);

            System.out.println(successfulPermutations);
        }
    }

    /* ---------------------------  Main logic  --------------------------- */
    private static int countSuccessfulPermutations(int rows, int cols,
                                                   String[] maze,
                                                   int startRow, int startCol,
                                                   String instructionString) {
        int successful = 0;
        int[] permutation = {0, 1, 2, 3};               // initial ordering

        do {
            int up   = permutation[0];
            int down = permutation[1];
            int left = permutation[2];
            int right = permutation[3];

            if (simulatePath(maze, rows, cols,
                    startRow, startCol, instructionString,
                    up, down, left, right)) {
                successful++;
            }
        } while (nextPermutation(permutation));

        return successful;
    }

    private static boolean simulatePath(String[] maze, int rows, int cols,
                                         int startR, int startC,
                                         String instr,
                                         int up, int down, int left, int right) {
        int r = startR;
        int c = startC;

        for (int i = 0; i < instr.length(); i++) {
            int dirCode = instr.charAt(i) - '0';       // 0‑3
            int[] newPos = move(r, c, dirCode, up, down, left, right);
            r = newPos[0];
            c = newPos[1];

            if (!isInBounds(r, c, rows, cols)) {
                return false;
            }
            char cell = maze[r].charAt(c);
            if (cell == WALL) {
                return false;
            }
            if (cell == EXIT) {
                return true;
            }
        }
        return false;   // reached end of instruction string without hitting EXIT
    }

    private static int[] move(int r, int c, int dir,
                              int up, int down, int left, int right) {
        // Mapping of direction code to coordinate delta
        switch (dir) {
            case 0: return new int[]{r - 1, c};   // UP
            case 1: return new int[]{r + 1, c};   // DOWN
            case 2: return new int[]{r, c - 1};   // LEFT
            case 3: return new int[]{r, c + 1};   // RIGHT
            default: throw new IllegalStateException("Invalid direction code: " + dir);
        }
    }

    private static boolean isInBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* ---------------------------  Permutation utilities  --------------------------- */
    private static boolean nextPermutation(int[] a) {
        // Generates the next lexicographic permutation of a[0..3]
        int i = a.length - 2;
        while (i >= 0 && a[i] > a[i + 1]) {
            i--;
        }
        if (i < 0) {
            return false;                     // no further permutations
        }
        int j = a.length - 1;
        while (a[j] < a[i]) {
            j--;
        }
        swap(a, i, j);
        reverse(a, i + 1, a.length - 1);
        return true;
    }

    private static void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    private static void reverse(int[] arr, int from, int to) {
        while (from < to) {
            swap(arr, from++, to--);
        }
    }
}

import java.util.Scanner;

public class MazeSolver {

    private static char[][] grid;
    private static int rows, cols;
    private static int startRow, startCol;
    private static int endRow, endCol;
    private static final Scanner SCANNER = new Scanner(System.in);

    public static void main(String[] args) {
        readInput();
        int result = countSuccessfulPermutations();
        System.out.println(result);
    }

    private static void readInput() {
        rows = SCANNER.nextInt();
        cols = SCANNER.nextInt();
        SCANNER.nextLine(); // consume the newline after the dimensions

        grid = new char[rows][cols];
        findStartAndEnd();

        String moves = SCANNER.nextLine().trim();
        int total = 0;

        // generate all permutations of {0, 1, 2, 3}
        for (int a = 0; a < 4; a++) {
            for (int b = 0; b < 4; b++) {
                if (b == a) continue;
                for (int c = 0; c < 4; c++) {
                    if (c == a || c == b) continue;
                    for (int d = 0; d < 4; d++) {
                        if (d == a || d == b || d == c) continue;
                        int[] perm = {a, b, c, d};
                        total += evaluatePermutation(perm, moves);
                    }
                }
            }
        }

        System.out.println(total);
    }

    private static void findStartAndEnd() {
        for (int i = 0; i < rows; i++) {
            String line = SCANNER.nextLine();
            for (int j = 0; j < cols; j++) {
                char cell = line.charAt(j);
                grid[i][j] = cell;
                if (cell == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (cell == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }
    }

    private static int evaluatePermutation(int[] perm, String moves) {
        int r = startRow;
        int c = startCol;

        for (int i = 0; i < moves.length(); i++) {
            int dirCode = moves.charAt(i) - '0'; // 0‑3
            int dir = perm[dirCode];             // 0=up, 1=down, 2=right, 3=left
            int nr = r + dr(dir);
            int nc = c + dc(dir);

            if (!isInBounds(nr, nc) || grid[nr][nc] == '#') {
                return 0;
            }
            r = nr;
            c = nc;

            if (r == endRow && c == endCol) {
                return 1;
            }
        }
        return 0;
    }

    private static int dr(int dir) {
        return switch (dir) {
            case 0 -> -1;
            case 1 -> 1;
            case 2 -> 0;
            case 3 -> 0;
            default -> 0;
        };
    }

    private static int dc(int dir) {
        return switch (dir) {
            case 0 -> 0;
            case 1 -> 0;
            case 2 -> 1;
            case 3 -> -1;
            default -> 0;
        };
    }

    private static boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Counts the number of permutations of the four direction vectors that allow
 * a path from the start cell 'S' to the exit cell 'E' while obeying the
 * movement rules described by the input direction string.
 *
 * The program follows the same algorithm as the original implementation but
 * separates concerns into small, well‑named methods, uses meaningful variable
 * names and removes unnecessary global state.  This makes the code easier to
 * test, maintain and extend.
 */
public class Main {

    // -------------------------------------------------------------------------
    //  Constants & static state (kept minimal and immutable where possible)
    // -------------------------------------------------------------------------

    /** Direction vectors ((dx, dy) for indices 0‑3). */
    private static final int[] DX = {0, 1, 0, -1};
    private static final int[] DY = {1, 0, -1, 0};

    /** Fast scanner used to read input. */
    private static final FastReader SCANNER = new FastReader(System.in);
    private static final PrintWriter OUT = new PrintWriter(System.out, true);

