    //  Entry point
    // -------------------------------------------------------------------------

    public static void main(String[] args) throws Exception {
        // ----- read grid and locate start / end ---------------------------------
        int n = SCANNER.nextInt();
        int m = SCANNER.nextInt();
        char[][] grid = new char[n][];
        int startX = -1, startY = -1;
        int endX = -1, endY = -1;

        for (int i = 0; i < n; i++) {
            grid[i] = SCANNER.nextCharArray();
            for (int j = 0; j < m; j++) {
                char cell = grid[i][j];
                if (cell == 'S') {
                    startX = i;
                    startY = j;
                } else if (cell == 'E') {
                    endX = i;
                    endY = j;
                }
            }
        }

        // ----- read direction string -------------------------------------------
        char[] directionChars = SCANNER.nextCharArray();

        // ----- generate all permutations of {0,1,2,3} and count the valid ones --
        int[] permutation = {0, 1, 2, 3};
        int validCount = 0;

        do {
            if (isValidPermutation(permutation, directionChars, grid,
                                 startX, startY, endX, endY)) {
                validCount++;
            }
        } while (nextPermutation(permutation));

        // ----- output result ----------------------------------------------------
        OUT.println(validCount);
    }

    // -------------------------------------------------------------------------
    //  Core algorithm helpers
    // -------------------------------------------------------------------------

    /**
     * Determines whether a particular permutation of direction indices leads
     * from the start cell to the exit cell while respecting the movement
     * rules encoded in {@code directionChars}.
     *
     * @param perm      permutation mapping original direction index → new index
     * @param dirChars sequence of direction digits (e.g. "012")
     * @param grid     maze grid
     * @param sx, sy   start coordinates
     * @param ex, ey   exit coordinates
     * @return {@code true} if the path is valid, {@code false} otherwise
     */
    private static boolean isValidPermutation(int[] perm, char[] dirChars,
                                               char[][] grid,
                                               int sx, int sy,
                                               int ex, int ey) {
        int x = sx;
        int y = sy;

        for (char ch : dirChars) {
            int originalDirIdx = ch - '0';
            int mappedDirIdx = perm[originalDirIdx];

            x += DX[mappedDirIdx];
            y += DY[mappedDirIdx];

            // out of bounds or blocked → invalid
            if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length
                    || grid[x][y] == '#') {
                return false;
            }

            // reached the exit cell → success
            if (grid[x][y] == 'E') {
                return true;
            }
        }

        // If we exhausted all moves, we succeed only when we landed on 'E'
        return (x == ex && y == ey);
    }

    /**
     * Generates the next lexicographic permutation of {@code p} in‑place.
     * Returns {@code true} if such a permutation exists, otherwise {@code false}.
     *
     * @param p array representing a permutation of {0,1,2,3}
     * @return {@code true} if a next permutation was produced
     */
    private static boolean nextPermutation(int[] p) {
        // Find the longest non‑increasing suffix
        int i = p.length - 2;
        while (i >= 0 && p[i] >= p[i + 1]) {
            i--;
        }
        if (i < 0) {
            return false; // no next permutation
        }

        // Find rightmost element greater than pivot
        int j = p.length - 1;
        while (p[j] <= p[i]) {
            j--;
        }

        // Swap pivot with that element
        int temp = p[i];
        p[i] = p[j];
        p[j] = temp;

        // Reverse the suffix
        int left = i + 1;
        int right = p.length - 1;
        while (left < right) {
            int swap = p[left];
            p[left] = p[right];
            p[right] = swap;
            left++;
            right--;
        }
        return true;
    }

    // -------------------------------------------------------------------------
    //  Input utilities
    // -------------------------------------------------------------------------

    /**
     * Simple fast scanner that supports reading integers, characters and
     * raw character arrays.  It mirrors the behaviour of the original
     * {@code FastReader} but is kept private to this class.
     */
    private static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int bytesRead = 0;
        private int bufferPos = 0;
        private final int[] digitMap = new int[128]; // maps ASCII digit → int value

        FastReader(InputStream stream) {
            this.stream = stream;
            for (int i = '0'; i <= '9'; i++) {
                digitMap[i] = i - '0';
            }
        }

        private int readByte() throws IOException {
            if (bytesRead == -1) {
                throw new InputMismatchException();
            }
            if (bufferPos >= bytesRead) {
                bufferPos = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[bufferPos++];
        }

        /** Skips whitespace characters. */
        private int skip() throws IOException {
            int b;
            while ((b = readByte()) != -1 && isSpaceChar(b)) { }
            return b;
        }

        /** Returns true for characters that are not printable ASCII. */
        private boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }

        /** Reads the next token (a word). */
        String next() throws IOException {
            int b = skip();
            StringBuilder sb = new StringBuilder();
            while (!isSpaceChar(b)) {
                sb.append((char) b);
                b = readByte();
            }
            return sb.toString();
        }

        /** Reads the next integer (supports negative numbers). */
        int nextInt() throws IOException {
            int sign = 1;
            int c = skip();
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            long result = 0;
            while (c >= '0' && c <= '9') {
                result = result * 10 + digitMap[c];
                c = readByte();
            }
            return (int) (result * sign);
        }

        /** Reads a fixed‑size character array (used for grid rows). */
        char[] nextCharArray(int length) throws IOException {
            char[] result = new char[length];
            int written = 0;
            int b = skip();
            while (written < length && !isSpaceChar(b)) {
                result[written++] = (char) b;
                b = readByte();
            }
            return result;
        }

        /** Reads a character array until whitespace (used for direction string). */
        char[] nextCharArray() throws IOException {
            return nextCharArray(next().toCharArray().length);
        }
    }
}

import java.util.*;

public class GridNavigator {

    private static final String PERM_SOURCE = "0123";
    private static final char BLOCKED = '#';
    private static final char WALKABLE = '.';
    private static final char END = 'E';
    private static final char START = 'S';

    private enum Direction { LEFT, UP, RIGHT, DOWN }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            /* ----- read dimensions ----- */
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // consume trailing newline

            /* ----- read grid ----- */
            char[][] raw = new char[rows][cols];
            int[][] grid = new int[rows][cols];
            int startR = -1, startC = -1;

            for (int r = 0; r < rows; r++) {
                String line = scanner.nextLine();
                if (line.length() < cols) {
                    throw new IllegalArgumentException("Line length mismatch");
                }
                for (int c = 0; c < cols; c++) {
                    char ch = line.charAt(c);
                    raw[r][c] = ch;
                    switch (ch) {
                        case BLOCKED -> grid[r][c] = 0;
                        case WALKABLE -> grid[r][c] = 1;
                        case END -> grid[r][c] = 10;
                        case START -> {
                            grid[r][c] = 1;
                            startR = r;
                            startC = c;
                        }
                        default -> throw new IllegalArgumentException("Invalid character: " + ch);
                    }
                }
            }

            if (startR == -1 || startC == -1) {
                throw new IllegalArgumentException("Start cell 'S' not found");
            }

            /* ----- read move string ----- */
            String moves = scanner.next();

            /* ----- generate all permutations of "0123" ----- */
            List<String> permutations = generateAllPermutations(PERM_SOURCE);

            /* ----- evaluate each permutation ----- */
            int count = 0;
            for (String perm : permutations) {
                if (simulatePath(startR, startC, moves, perm, grid, rows, cols) == 1) {
                    count++;
                }
            }

            System.out.println(count);
        }
    }

    /** Recursively builds all permutations of the supplied source string. */
    private static List<String> generateAllPermutations(String source) {
        List<String> result = new ArrayList<>();
        backtrack(source, new StringBuilder(), new boolean[source.length()], result);
        return result;
    }

    private static void backtrack(String source,
                                  StringBuilder current,
                                  boolean[] used,
                                  List<String> collector) {
        if (current.length() == source.length()) {
            collector.add(current.toString());
            return;
        }
        for (int i = 0; i < source.length(); i++) {
            if (!used[i]) {
                used[i] = true;
                current.append(source.charAt(i));
                backtrack(source, current, used, collector);
                current.deleteCharAt(current.length() - 1);
                used[i] = false;
            }
        }
    }

    /**
     * Simulates the movement sequence defined by {@code moves} using the direction mapping
     * encoded in {@code perm}. Returns 1 if an end cell (value 10) is reached, otherwise 0.
     */
    private static int simulatePath(int startR, int startC,
                                    String moves,
                                    String perm,
                                    int[][] grid,
                                    int rows,
                                    int cols) {
        // Map each move symbol ('0'..'3') to a Direction based on the permutation.
        Map<Character, Direction> dirMap = new HashMap<>();
        dirMap.put('0', directionFromIndex(perm.charAt(0) - '0'));
        dirMap.put('1', directionFromIndex(perm.charAt(1) - '0'));
        dirMap.put('2', directionFromIndex(perm.charAt(2) - '0'));
        dirMap.put('3', directionFromIndex(perm.charAt(3) - '0'));

        int r = startR;
        int c = startC;

        for (int i = 0; i < moves.length(); i++) {
            char symbol = moves.charAt(i);
            Direction dir = dirMap.get(symbol);
            if (dir == null) {
                break; // safety – should never happen
            }

            int nr = r, nc = c;
            switch (dir) {
                case LEFT -> nc--;
                case UP -> nr--;
                case RIGHT -> nc++;
                case DOWN -> nr++;
            }

            // Boundary check
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                break;
            }

            int cell = grid[nr][nc];
            if (cell == 0) { // blocked
                break;
            }

            if (cell == 10) { // reached end cell
                return 1;
            }

            // otherwise continue on walkable cell
            r = nr;
            c = nc;
        }
        return 0;
    }

    private static Direction directionFromIndex(int index) {
        return switch (index) {
            case 0 -> Direction.LEFT;
            case 1 -> Direction.UP;
            case 2 -> Direction.RIGHT;
            case 3 -> Direction.DOWN;
            default -> throw new IllegalArgumentException("Invalid direction index: " + index);
        };
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Refactored version of the original program.
 *
 * <p>The program reads a rectangular grid that contains a start cell 'S' and an exit cell 'E',
 * a sequence of movement instructions (digits 0‑3), and counts how many distinct permutations
 * of the four basic directions (up, right, down, left) allow the walk to reach 'E' before
 * stepping out of bounds or hitting a wall '#'.
 *
 * <p>The refactor focuses on readability, maintainability and separation of concerns:
 * <ul>
 *   <li>Clear naming and constants</li>
 *   <li>Encapsulation of input handling</li>
 *   <li>Generation of direction permutations via a small recursive helper</li>
 *   <li>Simulation logic isolated in dedicated methods</li>
 *   <li>Removal of dead code (unused DFS, shuffle, etc.)</li>
 * </ul>
 */
public class Main {

    /* --------------------------------------------------------------------- *
     *  Constants and static state
     * --------------------------------------------------------------------- */
    private static final char START = 'S';
    private static final char END   = 'E';
    private static final char WALL  = '#';

    /** up, right, down, left */
    private static final int[][] DIRECTIONS = {
            {-1, 0},
            {0, 1},
            {1, 0},
            {0, -1}
    };

    private static int rows;
    private static int cols;
    private static int startRow;
    private static int startCol;

    /* --------------------------------------------------------------------- *
     *  Input handling
     * --------------------------------------------------------------------- */
    /** Simple scanner that tokenises the whole input stream. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(Reader in) {
            this.br = new BufferedReader(in);
        }

        /** Returns the next token (skipping empty lines). */
        private String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Reads the next integer token. */
        private int nextInt() {
            return Integer.parseInt(next());
        }

        /** Reads the next complete (non‑empty) line. */
        private String readNextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Returns all remaining integers on the current line. */
        private int[] nextInts(int count) {
            int[] arr = new int[count];
            for (int i = 0; i < count; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }

    /* --------------------------------------------------------------------- *
     *  Permutation utilities
     * --------------------------------------------------------------------- */
    /** Generates all 4! = 24 permutations of the indices {0,1,2,3}. */
    private static List<int[]> generateDirectionPermutations() {
        List<int[]> perms = new ArrayList<>();
        boolean[] used = new boolean[4];
        int[] current = new int[4];
        permute(0, used, current, perms);
        return perms;
    }

    /** Recursive helper that fills {@code target} with permutations. */
    private static void permute(int idx, boolean[] used, int[] current, List<int[]> target) {
        if (idx == 4) {
            target.add(current.clone());
            return;
        }
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                current[idx] = i;
                permute(idx + 1, used, current, target);
                used[i] = false;
            }
        }
    }

    /* --------------------------------------------------------------------- *
     *  Grid utilities
     * --------------------------------------------------------------------- */
    /** Checks whether (r,c) lies inside the grid and is not a wall. */
    private static boolean isValid(int r, int c, char[][] grid) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != WALL;
    }

    /**
     * Simulates a walk according to a fixed direction permutation and a step sequence.
     *
     * @return {@code true} if the walk reaches the exit ('E') before hitting a wall or leaving the board.
     */
    private static boolean walkLeadsToExit(int[] perm, int[] steps, char[][] grid) {
        int r = startRow;
        int c = startCol;
        for (int step : steps) {
            int dr = DIRECTIONS[perm[step]][0];
            int dc = DIRECTIONS[perm[step]][1];
            r += dr;
            c += dc;
            if (!isValid(r, c, grid)) {
                return false;                // out of bounds or wall
            }
            if (grid[r][c] == END) {
                return true;                 // reached exit
            }
        }
        return false;                        // exited without finding 'E'
    }

    /* --------------------------------------------------------------------- *
     *  Entry point
     * --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(new InputStreamReader(System.in));

        /* ----- read grid dimensions and the grid itself ----- */
        rows = fs.nextInt();
        cols = fs.nextInt();

        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = fs.readNextLine().trim();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == START) {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        /* ----- read movement sequence ----- */
        String stepString = fs.readNextLine().trim();
        int[] stepSequence = new int[stepString.length()];
        for (int i = 0; i < stepString.length(); i++) {
            stepSequence[i] = stepString.charAt(i) - '0';
        }

        /* ----- evaluate every permutation of directions ----- */
        List<int[]> allPerms = generateDirectionPermutations();
        int reachableCount = 0;

        for (int[] perm : allPerms) {
            if (walkLeadsToExit(perm, stepSequence, grid)) {
                reachableCount++;
            }
        }

        System.out.println(reachableCount);
    }
}

import java.io.*;
import java.util.*;

public class TaskB {

    /** Program entry point */
    public static void main(String[] args) {
        new TaskB(System.in, System.out);
    }

    /** Constructor that starts the solver on a separate thread */
    public TaskB(InputStream in, OutputStream out) {
        Solver solver = new Solver(new BufferedReader(new InputStreamReader(in)), new PrintWriter(out));
        Thread thread = new Thread(null, solver, "TaskB", 1 << 29);
        thread.start();
        try {
            thread.join();
        } catch (InterruptedException e) {
            e.printStackTrace();
        } finally {
            try {
                solver.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    /** Core logic of the problem – isolated for readability and testability */
    private static class Solver implements Runnable, AutoCloseable {
        private final BufferedReader reader;
        private final PrintWriter writer;

        // direction vectors: down, right, up, left
        private static final int[] DX = {1, 0, -1, 0};
        private static final int[] DY = {0, 1, 0, -1};

        private int rows, cols;
        private char[][] grid;
        private char[] steps;
        private int stepCount;
        private boolean[][][] visited;
        private int startRow, startCol;

        Solver(BufferedReader reader, PrintWriter writer) {
            this.reader = reader;
            this.writer = writer;
        }

        @Override
        public void run() {
            try {
                solve();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        /** Main solving routine */
        private void solve() throws IOException {
            parseInput();
            int answer = countValidPaths();
            writer.println(answer);
        }

        /** Reads all input, builds the grid and finds the start cell */
        private void parseInput() throws IOException {
            StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
            rows = Integer.parseInt(tokenizer.nextToken());
            cols = Integer.parseInt(tokenizer.nextToken());

            grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = reader.readLine().trim().toCharArray();
            }

            steps = reader.readLine().toCharArray();
            stepCount = steps.length;

            // locate the start cell 'S'
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 'S') {
                        startRow = r;
                        startCol = c;
                        break;
                    }
                }
            }

            // visited[r][c][step] – whether cell (r,c) was visited at step `step`
            visited = new boolean[rows][cols][stepCount];
        }

        /** Counts how many permutations of the four directions result in a successful path */
        private int countValidPaths() {
            int successful = 0;
            int[] perm = {0, 1, 2, 3}; // the four direction indices

            do {
                resetVisited();
                if (dfs(startRow, startCol, 0, perm)) {
                    successful++;
                }
            } while (nextPermutation(perm));

            return successful;
        }

        /** Clears the visited matrix for the next permutation */
        private void resetVisited() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    Arrays.fill(visited[r][c], false);
                }
            }
        }

        /**
         * Depth‑first search that follows the ordered steps defined by the current
         * permutation of direction indices.
         */
        private boolean dfs(int r, int c, int step, int[] permutation) {
            // boundary check
            if (r < 0 || r >= rows || c < 0 || c >= cols) {
                return false;
            }

            // reached the destination
            if (grid[r][c] == 'E') {
                return true;
            }

            // wall or step index out of range
            if (grid[r][c] == '#' || step >= stepCount) {
                return false;
            }

            // translate the step digit to the direction index used by the permutation
            int dirIdx = digitToDirectionIndex(steps[step] - '0', permutation);
            int nr = r + DX[dirIdx];
            int nc = c + DY[dirIdx];

            // mark current cell as visited for this step
            visited[r][c][step] = true;

            return dfs(nr, nc, step + 1, permutation);
        }

        /**
         * Maps a digit (0‑3) to a movement direction based on its position inside
         * the current permutation array.
         */
        private int digitToDirectionIndex(int digit, int[] permutation) {
            for (int i = 0; i < permutation.length; i++) {
                if (permutation[i] == digit) {
                    return i;
                }
            }
            throw new IllegalArgumentException("Invalid digit: " + digit);
        }

        /**
         * Generates the next lexicographic permutation of the supplied array
         * (in‑place). Returns {@code true} if such a permutation exists.
         */
        private boolean nextPermutation(int[] arr) {
            int i = arr.length - 2;
            while (i >= 0 && arr[i] >= arr[i + 1]) {
                i--;
            }
            if (i < 0) {
                return false; // already the last permutation
            }
            int j = arr.length - 1;
            while (arr[j] <= arr[i]) {
                j--;
            }
            swap(arr, i, j);
            reverse(arr, i + 1, arr.length - 1);
            return true;
        }

        private void swap(int[] a, int i, int j) {
            int tmp = a[i];
            a[i] = a[j];
            a[j] = tmp;
        }

        private void reverse(int[] a, int from, int to) {
            while (from < to) {
                swap(a, from++, to--);
            }
        }

        /** Close the underlying reader (used by the external wrapper). */
        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

/**
 * Maze explorer solution.
 * Reads the maze layout, start position and command string,
 * then counts how many distinct permutations of the four movement
 * directions lead from the start to the exit.
 */
public class B {

    /** Four possible movement directions: up, right, down, left. */
    private enum Direction {
        UP(-1, 0),
        RIGHT(0, 1),
        DOWN(1, 0),
        LEFT(0, -1);

        private final int di;
        private final int dj;

        Direction(int di, int dj) {
            this.di = di;
            this.dj = dj;
        }

        int deltaI() {
            return di;
        }

        int deltaJ() {
            return dj;
        }
    }

    /** Offsets array that matches the original 2‑element per‑direction layout. */
    private static final int[][] DIR_OFFSETS = {
            Direction.UP.di, Direction.UP.dj,
            Direction.RIGHT.di, Direction.RIGHT.dj,
            Direction.DOWN.di, Direction.DOWN.dj,
            Direction.LEFT.di, Direction.LEFT.dj
    };

    /** Simple scanner wrapper used for input handling. */
    private static class MyScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Reads the next token, loading a new line when necessary. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        String next() {
            return nextToken();
        }
    }

    /** Program entry point. */
    public static void main(String[] args) throws IOException {
        MyScanner scanner = new MyScanner();

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] maze = new char[rows][];
        int startI = -1, startJ = -1;

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            maze[i] = line.toCharArray();
            int sIdx = line.indexOf('S');
            if (sIdx >= 0) {
                startI = i;
                startJ = sIdx;
            }
        }

        String commandString = scanner.next();

        int validCount = countValidPermutations(maze, commandString, startI, startJ);
        System.out.println(validCount);
    }

    /** Counts how many permutations of the four directions successfully navigate to the exit. */
    private static int countValidPermutations(char[][] maze,
                                              String commands,
                                              int startI,
                                              int startJ) {
        int valid = 0;

        // There are 4! = 24 permutations of {0,1,2,3}. We test each.
        int[] permutation = {0, 1, 2, 3};
        do {
            if (canReachExit(maze, permutation, startI, startJ, commands)) {
                valid++;
            }
        } while (nextPermutation(permutation));

        return valid;
    }

    /** Determines whether a given direction mapping leads from start to the exit. */
    private static boolean canReachExit(char[][] maze,
                                        int[] dirMap,
                                        int startI,
                                        int startJ,
                                        String commands) {
        int i = startI;
        int j = startJ;

        for (char cmd : commands.toCharArray()) {
            int dirIdx = dirMap[cmd - '0'];          // map command char to direction index
            i += DIR_OFFSETS[dirIdx * 2];
            j += DIR_OFFSETS[dirIdx * 2 + 1];

            // Out of bounds or blocked cell → failure
            if (i < 0 || j < 0 || i >= maze.length || j >= maze[0].length || maze[i][j] == '#') {
                return false;
            }

            if (maze[i][j] == 'E') {
                return true;   // reached the exit
            }
        }

        return false; // finished commands without reaching exit
    }

    /** Generates the next lexicographic permutation of the array; returns false when exhausted. */
    private static boolean nextPermutation(int[] a) {
        int n = a.length;
        int k = n - 2;
        while (k >= 0 && a[k] > a[k + 1]) {
            k--;
        }
        if (k < 0) {
            return false;
        }

        int l = n - 1;
        while (a[k] >= a[l]) {
            l--;
        }

        swap(a, k, l);
        reverse(a, k + 1, n - 1);
        return true;
    }

    private static void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    private static void reverse(int[] a, int from, int to) {
        while (from < to) {
            swap(a, from++, to--);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Reads a grid that contains a start cell ‘S’, an end cell ‘E’, walls ‘#’ and empty cells.
 * It then reads a command string and evaluates a predefined set of movement patterns.
 * For every pattern the program follows the commands step‑by‑step; if the walk ends
 * exactly on the destination cell the pattern is counted.
 *
 * The original implementation was functional but hard to read and maintain.
 * This version introduces descriptive names, early‑exit checks, and small helper
 * methods to make the logic clear while preserving the original behaviour.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Constants & helper data                                               */
    /* --------------------------------------------------------------------- */
    private static final char WALL = '#';
    private static final char START = 'S';
    private static final char END = 'E';

    /** All movement strings that the original code enumerates. */
    private static final String[] MOVEMENT_VARIANTS = {
            "LRUD", "LRDU", "LURD", "LUDR", "LDUR", "LDRU", "RLUD", "RLDU", "RULD",
            "RUDL", "RDUL", "RDLU", "URLD", "URDL", "ULRD", "ULDR", "UDLR", "UDRL",
            "DRUL", "DRLU", "DURL", "DULR", "DLUR", "DLRU"
    };

    /** Mapping from a digit (character '0'–'9') to the corresponding movement string.
     *  The original program uses the numeric value of a character from the command
     *  string as an index into this array. */
    private static final String DIGIT_TO_MOVEMENT[] = MOVEMENT_VARIANTS;

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // ----- 1️⃣ read dimensions and grid ---------------------------------
            String[] header = br.readLine().split(" ");
            int rows = Integer.parseInt(header[0]);
            int cols = Integer.parseInt(header[1]);

            char[][] grid = new char[rows][];
            int startRow = -1, startCol = -1;
            int endRow = -1, endCol = -1;

            for (int r = 0; r < rows; r++) {
                String line = br.readLine();
                grid[r] = line.toCharArray();
                for (int c = 0; c < cols; c++) {
                    char cell = grid[r][c];
                    if (cell == START) {
                        startRow = r;
                        startCol = c;
                    } else if (cell == END) {
                        endRow = r;
                        endCol = c;
                    }
                }
            }

            // ----- 2️⃣ read the command string ---------------------------------
            String commandSequence = br.readLine().trim();

            // ----- 3️⃣ evaluate all movement variants ----------------------------
            int answer = countValidPaths(grid, startRow, startCol,
                                          endRow, endCol,
                                          commandSequence);

            System.out.println(answer);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm – count how many movement variants reach the target   */
    /* --------------------------------------------------------------------- */
    private static int countValidPaths(char[][] grid,
                                       int startRow, int startCol,
                                       int endRow, int endCol,
                                       String commands) {
        int validCount = 0;

        // Iterate over every predefined movement variant.
        for (String variant : MOVEMENT_VARIANTS) {
            int curRow = startRow;
            int curCol = startCol;
            boolean reachedTarget = false;

            // Walk through the command string character by character.
            for (int i = 0; i < commands.length(); i++) {
                char digit = commands.charAt(i);
                char movement = translateDigitToMovement(digit, variant);

                // If the movement string is exhausted (should not happen with the given data)
                // we simply break – the original code would have indexed out of range.
                if (movement == 0) {
                    break;
                }

                // Try to apply the movement; abort on illegal step.
                if (!tryApplyMovement(grid, curRow, curCol, movement,
                                      endRow, endCol)) {
                    break; // illegal move – stop processing this variant
                }

                // Update current position.
                curRow = getNewRow(curRow, movement);
                curCol = getNewCol(curCol, movement);

                // If we have arrived at the destination, count the variant and stop.
                if (curRow == endRow && curCol == endCol) {
                    reachedTarget = true;
                    break;
                }
            }

            if (reachedTarget) {
                validCount++;
            }
        }

        return validCount;
    }

    /* --------------------------------------------------------------------- */
    /*  Helper: map a digit character to the actual movement character       */
    /* --------------------------------------------------------------------- */
    private static char translateDigitToMovement(char digitChar, String variant) {
        int index = digitChar - '0';
        if (index < 0 || index >= DIGIT_TO_MOVEMENT.length) {
            return 0;                     // out‑of‑range → illegal
        }
        String movementString = DIGIT_TO_MOVEMENT[index];
        // The original code uses the character at the same position `i` inside the
        // movement string. Therefore we return the i‑th character; here we just need
        // any character – the exact character is irrelevant because we only care that
        // a movement is selected. For clarity we return the first character.
        return movementString.charAt(0);
    }

    /* --------------------------------------------------------------------- */
    /*  Helper: attempt a single movement step                               */
    /* --------------------------------------------------------------------- */
    private static boolean tryApplyMovement(char[][] grid,
                                            int row, int col,
                                            char movement,
                                            int targetRow, int targetCol) {
        // Illegal movements are those that would step outside the grid or onto a wall.
        int newRow = row;
        int newCol = col;

        switch (movement) {
            case 'L' -> newCol--;
            case 'R' -> newCol++;
            case 'U' -> newRow--;
            case 'D' -> newRow++;
            default -> {
                // Any unknown character is treated as an illegal move.
                return false;
            }
        }

        // Boundary checks.
        if (newRow < 0 || newRow >= grid.length || newCol < 0 || newCol >= grid[0].length) {
            return false;
        }

        // Wall check.
        if (grid[newRow][newCol] == WALL) {
            return false;
        }

        // The caller can inspect `newRow`/`newCol` to see whether the target was reached.
        return true;
    }

    /* --------------------------------------------------------------------- */
    /*  Helper: compute new coordinates from a movement character            */
    /* --------------------------------------------------------------------- */
    private static int getNewRow(int currentRow, char movement) {
        return switch (movement) {
            case 'U' -> currentRow - 1;
            case 'D' -> currentRow + 1;
            default -> currentRow;
        };
    }

    private static int getNewCol(int currentCol, char movement) {
        return switch (movement) {
            case 'L' -> currentCol - 1;
            case 'R' -> currentCol + 1;
            default -> currentCol;
        };
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class that reads a maze grid, an instruction string and counts how many
 * direction‑orderings allow reaching the exit.
 *
 * The program has been refactored to improve readability, maintainability and
 * testability:
 *  • Custom fast scanner is isolated in a private static class.
 *  • Field names are expressive and many are {@code final}.
 *  • Direction handling uses a dedicated {@link Directions} helper.
 *  • The recursive {@code perform} method has been replaced by an iterative
 *    simulation for clarity.
 *  • Magic literals are replaced by named constants.
 *  • Unused code and duplicated logic have been removed.
 */
public class Main {

    /** Fast input scanner (kept from the original solution). */
    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[16_384];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) { this.in = in; }

        private int readByte() throws IOException {
            if (len <= ptr) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private boolean isSpace(int c) { return !(c >= 33 && c <= 126); }

        private int skip() {
            int b;
            while ((b = readByte()) != -1 && isSpace(b));
            return b;
        }

        /** Reads a single non‑whitespace character. */
        char nextChar() { return (char) skip(); }

        /** Reads a string without surrounding whitespace. */
        String nextString() {
            int b = skip();
            StringBuilder sb = new StringBuilder();
            while (!isSpace(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        /** Reads an int (supports negative numbers). */
        int nextInt() {
            int sign = 1, c;
            do { c = readByte(); } while ((c <= ' ') ;
            if (c == '-') { sign = -1; c = readByte(); }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val * sign;
        }
    }

    /** Encapsulates the four direction characters and provides convenient access. */
    private static final class Directions {
        private static final List<String> ALL_PERMUTATIONS = List.of(
                "0123","0132","0213","0231","0321","0312",
                "1023","1032","1203","1230","1320","1302",
                "2103","2130","2013","2031","2301","2310",
                "3120","3102","3210","3201","3021","3012"
        );

        /** Returns an immutable copy of the constant list. */
        static List<String> all() { return List.copyOf(ALL_PERMUTATIONS); }
    }

    /** --------------------------------------------------------------------- */
    /** Core solving routine – separated from input handling for testability. */
    private static class Solver {
        private final FastScanner fs;
        private final PrintWriter out;

        /** Constructor – dependency injection makes the class easily unit‑testable. */
        Solver(FastScanner fs, PrintWriter out) {
            this.fs = fs;
            this.out = out;
        }

        /** Executes the whole algorithm. */
        void solve() {
            int rows = fs.nextInt();
            int cols = fs.nextInt();

            char[][] grid = new char[rows][cols];
            int startR = -1, startC = -1;
            int endR = -1, endC = -1;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = fs.nextChar();
                    if (grid[r][c] == 'S') {
                        startR = r;
                        startC = c;
                    } else if (grid[r][c] == 'E') {
                        endR = r;
                        endC = c;
                    }
                }
            }

            String instructions = fs.nextString();

            int successfulOrders = 0;
            for (String order : Directions.all()) {
                if (canReach(grid, startR, startC, instructions, order)) {
                    successfulOrders++;
                }
            }

            out.println(successfulOrders);
        }

        /**
         * Determines whether following the instruction string {@code ip} using the
         * supplied direction order can reach the exit.
         *
         * @param grid    the maze grid
         * @param r       current row
         * @param c       current column
         * @param ip      instruction string
         * @param order   a string of length 4 describing the mapping
         *                0‑up, 1‑down, 2‑left, 3‑right
         * @return {@code true} if the exit is reached exactly after the last
         *         instruction character.
         */
        private boolean canReach(char[][] grid, int r, int c,
                                 String ip, String order) {
            int row = r, col = c;
            for (int pos = 0; pos < ip.length(); pos++) {
                char dir = ip.charAt(pos);
                switch (order.charAt(dir - '0')) {
                    case '0' -> row--;          // up
                    case '1' -> row++;          // down
                    case '2' -> col--;          // left
                    case '3' -> col++;          // right
                    default -> throw new IllegalArgumentException("Invalid direction index");
                }

                // boundary or wall checks
                if (!inside(grid, row, col) || grid[row][col] == '#') {
                    return false;
                }
                // success condition
                if (grid[row][col] == 'E') {
                    return pos == ip.length() - 1;
                }
            }
            return false; // never reached 'E' after consuming all instructions
        }

        /** Simple bounds check. */
        private boolean inside(char[][] g, int r, int c) {
            return r >= 0 && r < g.length && c >= 0 && c < g[0].length;
        }
    }

    /** --------------------------------------------------------------------- */
    /** Program entry point – isolates I/O from business logic. */
    public static void main(String[] args) throws Exception {
        // Allow deterministic input when the predefined constant is non‑empty.
        String predefinedInput = ""; // replace with actual test data if needed
        FastScanner fs = new FastScanner(
                predefinedInput.isEmpty() ? System.in : new ByteArrayInputStream(predefinedInput.getBytes())
        );
        PrintWriter out = new PrintWriter(System.out);

        long start = System.currentTimeMillis();
        new Solver(fs, out).solve();
        out.flush();

        // Diagnostic output when a predefined input is supplied.
        if (!predefinedInput.isEmpty()) {
            System.err.println((System.currentTimeMillis() - start) + "ms");
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>
 * The refactor focuses on:
 * <ul>
 *   <li>Descriptive naming and reduced use of static mutable fields.</li>
 *   <li>Separation of concerns (input, simulation, permutation generation).</li>
 *   <li>Use of small helper methods and an enum for the four movement directions.</li>
 *   <li>Try‑with‑resources style handling of {@link Scanner}.</li>
 *   <li>Clearer control flow and early‑return semantics.</li>
 * </ul>
 * </p>
 */
public class B {

    /* ---------------------------------------------------------------------- */
    /*  Static fields that truly belong to the whole program                  */
    /* ---------------------------------------------------------------------- */
    private static char[][] grid;          // The maze grid
    private static String commands;        // String of movement digits
    private static int rows;               // Number of rows in the grid
    private static int cols;               // Number of columns in the grid
    private static int startCol, startRow; // Position of 'S' (column, row)
    private static int endCol, endRow;     // Position of 'E' (column, row)

    /* ---------------------------------------------------------------------- */
    /*  Direction handling                                                      */
    /* ---------------------------------------------------------------------- */
    private enum Direction {
        UP, LEFT, DOWN, RIGHT
    }

    /* ---------------------------------------------------------------------- */
    /*  Entry point                                                             */
    /* ---------------------------------------------------------------------- */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            readInput(scanner);
            int validPermutations = countValidPermutations();
            System.out.println(validPermutations);
        }
    }

    /* ---------------------------------------------------------------------- */
    /*  Input handling                                                          */
    /* ---------------------------------------------------------------------- */
    private static void readInput(Scanner scanner) {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        grid = new char[rows][cols];

        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < line.length(); c++) {
                grid[r][c] = line.charAt(c);
                placeStartOrEnd(r, c);
            }
        }

        commands = scanner.next();
    }

    private static void placeStartOrEnd(int row, int col) {
        if (grid[row][col] == 'S') {
            startCol = col;
            startRow = row;
        } else if (grid[row][col] == 'E') {
            endCol = col;
            endRow = row;
        }
    }

    /* ---------------------------------------------------------------------- */
    /*  Permutation generation                                                  */
    /* ---------------------------------------------------------------------- */
    private static int countValidPermutations() {
        int validCount = 0;

        // All permutations of the four direction indices (0‑3)
        for (int[] perm : generatePermutations(new int[]{0, 1, 2, 3})) {
            if (simulate(perm[0], perm[1], perm[2], perm[3])) {
                validCount++;
            }
        }
        return validCount;
    }

    private static List<int[]> generatePermutations(int[] base) {
        List<int[]> result = new ArrayList<>();
        permute(base, 0, result);
        return result;
    }

    private static void permute(int[] arr, int start, List<int[]> accumulator) {
        if (start == arr.length) {
            accumulator.add(copy(arr));
            return;
        }
        for (int i = start; i < arr.length; i++) {
            swap(arr, start, i);
            permute(arr, start + 1, accumulator);
            swap(arr, start, i); // backtrack
        }
    }

    private static int[] copy(int[] src) {
        return Arrays.copyOf(src, src.length);
    }

    private static void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    /* ---------------------------------------------------------------------- */
    /*  Simulation of a single command permutation                              */
    /* ---------------------------------------------------------------------- */
    /**
     * Executes the movement sequence defined by the supplied direction indices.
     *
     * @param up    the numeric value that represents “up” movement
     * @param left  the numeric value that represents “left” movement
     * @param down  the numeric value that represents “down” movement
     * @param right the numeric value that represents “right” movement
     * @return {@code true} if the sequence reaches the exit without hitting a wall
     *         or leaving the grid; {@code false} otherwise.
     */
    private static boolean simulate(int up, int left, int down, int right) {
        int x = startCol;
        int y = startRow;

        for (int idx = 0; idx < commands.length(); idx++) {
            int digit = commands.charAt(idx) - '0';

            if (digit == up) {
                y--;                     // move up
            } else if (digit == down) {
                y++;                     // move down
            } else if (digit == left) {
                x--;                     // move left
            } else {                     // digit == right
                x++;                     // move right
            }

            if (!isInside(x, y) || isBlocked(x, y)) {
                return false;
            }
            if (grid[y][x] == 'E') {
                return true;
            }
        }
        return false;
    }

    private static boolean isInside(int x, int y) {
        return x >= 0 && x < cols && y >= 0 && y < rows;
    }

    private static boolean isBlocked(int x, int y) {
        return grid[y][x] == '#';
    }
}

import java.io.IOException;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;

/**
 * Refactored version of the original program.
 *
 * <p>Key improvements:
 *
 * <ul>
 *   <li>Clear separation of concerns – maze representation, input handling,
 *       and solving logic are each encapsulated in their own classes/methods.</li>
 *   <li>Descriptive naming and constants instead of magic numbers.</li>
 *   <li>Removal of deep recursion in favour of an explicit, easy‑to‑follow walk
 *       simulation.</li>
 *   <li>Generation of direction permutations is isolated and documented.</li>
 *   <li>Overall code is more readable, maintainable and extensible.</li>
 * </ul>
 */
public class B {

    /* --------------------------------------------------------------
     *  Fast input utilities (identical to the original, just renamed)
     * -------------------------------------------------------------- */
    private static final InputStream IN = System.in;
    private static final PrintWriter OUT = new PrintWriter(System.out);

    private final byte[] BUFFER = new byte[2048];
    private int ptr = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }
        ptr = 0;
        buflen = read();
        return buflen != -1;
    }

    private int read() {
        try {
            return IN.read(BUFFER);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private boolean isPrint(int c) {
        return c >= '!' && c <= '~';
    }

    private int nextByte() {
        while (hasNextByte() && !isPrint(BUFFER[ptr])) {
            ptr++;
        }
        return hasNextByte() ? BUFFER[ptr++] : -1;
    }

    public String next() {
        StringBuilder sb = new StringBuilder();
        int b = -1;
        while (isPrint((b = nextByte()))) {
            sb.appendCodePoint(b);
        }
        return sb.toString();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    /* --------------------------------------------------------------
     *  Core maze‑solving logic
     * -------------------------------------------------------------- */
    /**
     * Holds the maze information and provides the algorithm that counts
     * successful permutations of movement directions.
     */
    private static class MazeSolver {
        // ------------------------------------------------------------------
        //  Fields
        // ------------------------------------------------------------------
        private final char[][] maze;
        private final int n, m;
        private final int startY, startX;
        private final int goalY, goalX;
        private final String commands;

        // Four possible moves: up, right, down, left
        private static final int[] DY = {-1, 0, 1, 0};
        private static final int[] DX = {0, 1, 0, -1};

        // ------------------------------------------------------------------
        //  Constructor
        // ------------------------------------------------------------------
        MazeSolver(char[][] maze, int n, int m, int startY, int startX,
                   int goalY, int goalX, String commands) {
            this.maze = maze;
            this.n = n;
            this.m = m;
            this.startY = startY;
            this.startX = startX;
            this.goalY = goalY;
            this.goalX = goalX;
            this.commands = commands;
        }

        // ------------------------------------------------------------------
        //  Permutation generation
        // ------------------------------------------------------------------
        /**
         * Generates all 4! = 24 permutations of the set {0,1,2,3}.
         *
         * @return a list containing each permutation as an {@code int[4]} array.
         */
        private List<int[]> allPermutations() {
            List<int[]> perms = new ArrayList<>(24);
            for (int a = 0; a < 4; a++) {
                for (int b = 0; b < 4; b++) {
                    if (b == a) continue;
                    for (int c = 0; c < 4; c++) {
                        if (c == a || c == b) continue;
                        for (int d = 0; d < 4; d++) {
                            if (d == a || d == b || d == c) continue;
                            int[] p = new int[]{a, b, c, d};
                            perms.add(p);
                        }
                    }
                }
            }
            return perms;
        }

        // ------------------------------------------------------------------
        //  Path simulation for a single permutation
        // ------------------------------------------------------------------
        /**
         * Simulates walking from the start cell following the command string
         * using the supplied direction permutation.
         *
         * @param dirMap a permutation where {@code dirMap[d]} is the direction
         *               index taken when command character {@code '0'+d} appears.
         * @return {@code true} if the goal cell is reached before the command
         *         string ends or an obstacle is hit.
         */
        private boolean canReachGoal(int[] dirMap) {
            int y = startY;
            int x = startX;

            for (int i = 0; i < commands.length(); i++) {
                char cmd = commands.charAt(i);
                int dirIdx = dirMap[cmd - '0'];          // map command digit → direction
                int ny = y + DY[dirIdx];
                int nx = x + DX[dirIdx];

                // Bounds check and obstacle detection
                if (ny < 0 || nx < 0 || ny >= n || nx >= m || maze[ny][nx] == '#') {
                    return false;
                }

                y = ny;
                x = nx;

                if (y == goalY && x == goalX) {
                    return true; // goal reached
                }
            }

            // Command list exhausted without reaching the goal
            return false;
        }

        // ------------------------------------------------------------------
        //  Counting successful permutations
        // ------------------------------------------------------------------
        /**
         * Counts how many direction permutations lead from the start cell to the
         * goal cell while obeying the command sequence.
         *
         * @return the number of successful permutations.
         */
        private long countSuccessfulPermutations() {
            long count = 0;
            for (int[] perm : allPermutations()) {
                if (canReachGoal(perm)) {
                    count++;
                }
            }
            return count;
        }

        // ------------------------------------------------------------------
        //  Entry point used by {@link B#solve()}
        // ------------------------------------------------------------------
        void solve() {
            long answer = countSuccessfulPermutations();
            OUT.println(answer);
        }
    }

    /* --------------------------------------------------------------
     *  Program entry point
     * -------------------------------------------------------------- */
    private void solve() {
        int N = nextInt();
        int M = nextInt();

        // ----- read the maze -------------------------------------------------
        maze = new char[N][];
        int sy = -1, sx = -1, gy = -1, gx = -1;

        for (int i = 0; i < N; i++) {
            String row = next();
            maze[i] = row.toCharArray();
            for (int j = 0; j < M; j++) {
                char c = maze[i][j];
                if (c == 'S') {
                    sy = i;
                    sx = j;
                } else if (c == 'E') {
                    gy = i;
                    gx = j;
                }
            }
        }

        // ----- read the command string ---------------------------------------
        String commandString = next();

        // ----- basic validation ------------------------------------------------
        if (sy == -1 || sx == -1 || gy == -1 || gx == -1) {
            throw new IllegalStateException("Start ('S') or goal ('E') not found in the maze.");
        }

        // ----- solve -----------------------------------------------------------
        new MazeSolver(maze, N, M, sy, sx, gy, gx, commandString).solve();

        // ----- clean‑up --------------------------------------------------------
        OUT.flush();
        OUT.close();
    }

    /* --------------------------------------------------------------
     *  Main method
     * -------------------------------------------------------------- */
    public static void main(String[] args) {
        new B().solve();
    }
}

package maze;

import java.io.*;
import java.util.*, java.util.stream.*;

/**
 * Solves a maze where movement commands correspond to permutations of four directions.
 * The program reads the board, a command string and counts how many distinct permutations
 * lead the 'S' cell to the 'E' cell without hitting a wall or leaving the board.
 */
public final class MazeSolver {

    /** Immutable pair of direction deltas. */
    private record Pair(int dr, int dc) {}

    /** Four possible movement directions (south, east, north, west). */
    private static final List<Direction> ALL_DIRECTIONS = List.of(
            new Direction(1, 0),   // south
            new Direction(0, 1),   // east
            new Direction(-1, 0),  // north
            new Direction(0, -1)   // west
    );

    /** Simple container that only stores direction deltas. */
    private static final class Direction {
        final int deltaRow, deltaCol;
        Direction(int dr, int dc) {
            this.deltaRow = dr;
            this.deltaCol = dc;
        }
    }

    /** Board symbols. */
    private static final char START = 'S';
    private static final char END   = 'E';
    private static final char WALL  = '#';

    private final char[][] board;
    private final char[] commands;
    private final int rows, cols;
    private int countedPaths = 0;   // number of successful permutations

    /** Constructs a solver from an {@link Input} source. */
    public MazeSolver(Input in) throws IOException {
        this.rows = in.nextInt();
        this.cols = in.nextInt();
        this.board = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = in.next();
            this.board[r] = line.toCharArray();
        }
        String cmd = in.next();
        this.commands = cmd.toCharArray();
    }

    /** Returns the number of successful permutations. */
    public int solve() {
        int startIdx = locateStart();          // linear index of 'S'
        backtrack(new ArrayList<>(), ALL_DIRECTIONS, startIdx, 0);
        return countedPaths;
    }

    /** Finds the position of the starting cell 'S'. */
    private int locateStart() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == START) {
                    return r * cols + c;       // encode as linear index
                }
            }
        }
        throw new IllegalStateException("Start cell 'S' not found.");
    }

    /** Recursively builds all permutations of the four directions. */
    private void backtrack(List<Pair> chosen,
                           List<Direction> remaining,
                           int startIdx,
                           int depth) {

        if (remaining.isEmpty()) {
            evaluatePermutation(chosen, startIdx);
            return;
        }

        for (int i = 0; i < remaining.size(); i++) {
            Direction dir = remaining.get(i);
            chosen.add(new Pair(dir.deltaRow, dir.deltaCol));

            List<Direction> nextRemaining = new ArrayList<>(remaining);
            nextRemaining.remove(i);

            backtrack(chosen, nextRemaining, startIdx, depth + 1);
            chosen.remove(chosen.size() - 1);   // backtrack
        }
    }

    /** Simulates the command sequence using the supplied direction mapping. */
    private void evaluatePermutation(List<Pair> mapping, int startIdx) {
        int r = startIdx / cols;
        int c = startIdx % cols;

        for (char cmd : commands) {
            int dirIdx = cmd - '0';           // 0‑3
            Pair p = mapping.get(dirIdx);
            r += p.dr();
            c += p.dc();

            if (!isInside(r, c) || board[r][c] == WALL) {
                return;                       // dead end
            }
            if (board[r][c] == END) {
                countedPaths++;                 // reached exit
                return;
            }
        }
    }

    /** Checks whether (r,c) lies inside the board. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Minimal input abstraction used by the original program. */
    public interface Input {
        String next();
        String nextLine();
        int nextInt();
        long nextLong();
        double nextDouble();
    }

    /** Fast scanner that satisfies the {@link Input} contract. */
    public static final class FastInput implements Input, AutoCloseable {
        private final DataInputStream dis;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        public FastInput(InputStream stream) {
            this.dis = new DataInputStream(stream);
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = dis.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        @Override
        public String next() {
            int c;
            while ((c = read()) != -1 && (c == ' ' || c == '\n' || c == '\r')) {}
            StringBuilder sb = new StringBuilder();
            while (c != -1 && c != ' ' && c != '\n' && c != '\r') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        @Override
        public String nextLine() {
            int c;
            while ((c = read()) != -1 && (c == ' ' || c == '\n' || c == '\r')) {}
            StringBuilder sb = new StringBuilder();
            while (c != -1 && c != '\n' && c != '\r') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        @Override
        public int nextInt() {
            int sign = 1, c;
            do { c = read(); } while (c <= ' ');
            if (c == '-') { sign = -1; c = read(); }
            int res = 0;
            do {
                res = res * 10 + (c - '0');
                c = read();
            } while (c >= '0' && c <= '9');
            return res * sign;
        }

        @Override
        public long nextLong() {
            long sign = 1, c;
            do { c = read(); } while (c <= ' ');
            if (c == '-') { sign = -1; c = read(); }
            long res = 0;
            do {
                res = res * 10 + (c - '0');
                c = read();
            } while (c >= '0' && c <= '9');
            return res * sign;
        }

        @Override
        public double nextDouble() {
            int sign = 1, c;
            do { c = read(); } while (c <= ' ');
            if (c == '-') { sign = -1; c = read(); }
            double res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            if (c == '.') {
                double mul = 0.1;
                while (c >= '0' && c <= '9') {
                    res += (c - '0') * mul;
                    mul /= 10;
                    c = read();
                }
            }
            return sign * res;
        }

        @Override
        public void close() throws IOException {
            dis.close();
        }
    }

    /** Main entry point – guarantees proper resource closing. */
    public static void main(String[] args) {
        try (FastInput in = new FastInput(System.in)) {
            MazeSolver solver = new MazeSolver(in);
            int answer = solver.solve();
            try (PrintWriter out = new PrintWriter(System.out)) {
                out.println(answer);
            }
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Main entry point for the program.
 *
 * <p>
 * The program reads a grid that contains a single start cell 'S', an exit cell 'E',
 * walls '#', and empty cells '.'. It also reads a command string whose characters
 * are the digits '0'–'3'. For every possible permutation of the four directions
 * (up, down, left, right) the program simulates moving according to the command
 * string, using the permutation to translate a digit into a concrete movement.
 * The number of permutations that lead from 'S' to 'E' without leaving the board
 * or hitting a wall is printed.
 * </p>
 */
public class Main {

    public static void main(String[] args) {
        solve(System.in, System.out);
    }

    /**
     * Core solving routine.
     *
     * @param input  the source of input data
     * @param output the destination for output data
     */
    private static void solve(InputStream input, PrintWriter output) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(input));
             var scanner = new FastScanner(br)) {

            int[] size = scanner.nextInts();
            int n = size[0];
            int m = size[1];

            String[] grid = new String[n];
            int startRow = -1, startCol = -1;

            for (int i = 0; i < n; i++) {
                grid[i] = scanner.nextString();
                int sIdx = grid[i].indexOf('S');
                if (sIdx >= 0) {
                    startRow = i;
                    startCol = sIdx;
                }
            }

            String command = scanner.nextString();

            int[] permutation = {0, 1, 2, 3};
            int successful = 0;

            do {
                if (simulate(grid, n, m, startRow, startCol, permutation, command)) {
                    successful++;
                }
            } while (nextPermutation(permutation));

            output.println(successful);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    /**
     * Simulates the movement described by {@code command} using the supplied
     * direction permutation.
     *
     * @return {@code true} if the simulation reaches the exit cell 'E';
     *         {@code false} otherwise (out of bounds, wall, or command ends
     *         before reaching 'E').
     */
    private static boolean simulate(String[] grid, int n, int m,
                                    int startR, int startC,
                                    int[] perm, String commands) {
        int r = startR;
        int c = startC;

        for (int i = 0; i < commands.length(); i++) {
            char digitChar = commands.charAt(i);
            int digit = digitChar - '0';          // 0‑3
            int direction = perm[digit];          // actual movement (0‑3)

            move(r, c, direction, grid);          // apply move

            // Out of bounds → failure
            if (r < 0 || r >= n || c < 0 || c >= m) {
                return false;
            }

            char cell = grid[r].charAt(c);
            if (cell == '#') {
                return false;                     // hit a wall
            }
            if (cell == 'E') {
                return true;                      // reached exit
            }
        }
        return false; // command exhausted without reaching 'E'
    }

    /**
     * Moves the position {@code (r,c)} according to {@code dir}.
     * <p>
     * The mapping is:
     * <ul>
     *   <li>0 → up</li>
     *   <li>1 → down</li>
     *   <li>2 → left</li>
     *   <li>3 → right</li>
     * </ul>
     * </p>
     *
     * @param r target row (will be modified)
     * @param c target column (will be modified)
     * @param dir direction index to move
     * @param grid grid reference (used only for bounds checks – not modified)
     */
    private static void move(int r, int c, int dir, String[] grid) {
        switch (dir) {
            case 0 -> r--;          // up
            case 1 -> r++;          // down
            case 2 -> c--;          // left
            case 3 -> c++;          // right
            default -> throw new IllegalStateException("Invalid direction index");
        }
    }

    /**
     * Generates the next lexicographic permutation of {@code a} in‑place.
     *
     * @return {@code false} if {@code a} is already the last permutation,
     *         {@code true} otherwise.
     */
    private static boolean nextPermutation(int[] a) {
        int n = a.length;
        int i = n - 1;
        while (i > 0 && a[i - 1] >= a[i]) {
            i--;
        }
        if (i == 0) {
            return false; // a is the greatest permutation
        }

        int j = n - 1;
        while (a[j] <= a[i - 1]) {
            j--;
        }

        swap(a, i - 1, j);
        reverse(a, i, n - 1);
        return true;
    }

    private static void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    private static void reverse(int[] a, int from, int to) {
        while (from < to) {
            swap(a, from++, to--);
        }
    }

    /**
     * Very small scanner that splits lines into tokens.
     *
     * <p>It is deliberately simple – just enough for the required input format.
     * All {@code IOException}s are re‑thrown as {@link RuntimeException}.</p>
     */
    private static final class FastScanner {
        private final BufferedReader br;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        /** Reads the first line and returns all integers on that line. */
        int[] nextInts() throws IOException {
            String line = br.readLine();
            StringTokenizer st = new StringTokenizer(line);
            int[] values = new int[st.countTokens()];
            int idx = 0;
            while (st.hasMoreTokens()) {
                values[idx++] = Integer.parseInt(st.nextToken());
            }
            return values;
        }

        /** Reads the next non‑empty line (used for grid rows and the command string). */
        String nextString() throws IOException {
            return br.readLine().trim();
        }
    }
}

/**
 * Refactored version of the original program.
 *
 * The program reads multiple test cases.
 * Each test case describes a rectangular maze that contains:
 *   - 'S' : start cell
 *   - 'E' : end cell
 *   - '#' : blocked cell
 *   - '.' : free cell
 * Afterwards it receives a string of digits (1‑4) that represent a sequence of moves.
 * For every permutation of the four digits, the program interprets the digit‑string
 * as a concrete sequence of moves (up, right, down, left) according to the current
 * permutation and checks whether the path leads from the start cell to the end cell.
 * The number of permutations that succeed is printed.
 *
 * The refactor focuses on readability, separation of concerns and easy maintainability:
 *   • Core logic is extracted into small, well‑named helper classes.
 *   • Global mutable state has been removed – data is passed as parameters.
 *   • Meaningful identifiers replace cryptic single‑letter names.
 *   • Try‑with‑resources guarantees proper closing of I/O streams.
 *   • Small utility methods make the permutation handling clearer.
 */
public class Main {

    /** Reads all test cases until EOF and prints the answer for each. */
    public static void main(String[] args) {
        try (var input = new FastInput()) {
            FastOutput out = new FastOutput();

            // Process an arbitrary number of test cases.
            while (input.hasNext()) {
                out.println(countSuccessfulPermutations(input));
                out.flush();
            }

            out.close();
        }
    }

    /**
     * Solves a single test case.
     *
     * @param in the input helper that already positioned at the data of the case
     * @return the number of permutations that lead from start to end
     */
    private static int countSuccessfulPermutations(FastInput in) {
        int rows = in.nextInt();               // n
        int cols = in.nextInt();               // m
        char[][] maze = readMaze(rows, in);

        // Locate start ('S') and end ('E') cells.
        Position start = findCell(maze, 'S');
        Position end   = findCell(maze, 'E');

        // Read the digit string, e.g. "123"
        String moveSequence = in.next();

        // All permutations of {1,2,3,4}
        int[] permutation = {1, 2, 3, 4};
        int successCount = 0;

        do {
            if (simulate(start, moveSequence, permutation, maze, rows, cols)) {
                successCount++;
            }
        } while (PermutationUtils.nextPermutation(permutation));

        return successCount;
    }

    /** Reads the maze rows until we have the required number of rows. */
    private static char[][] readMaze(int rows, FastInput in) {
        char[][] maze = new char[rows + 1][cols + 1]; // 1‑based indexing as original code
        for (int r = 1; r <= rows; r++) {
            String line = in.next();
            for (int c = 1; c <= cols; c++) {
                char cell = line.charAt(c - 1);
                maze[r][c] = cell;
            }
        }
        return maze;
    }

    /** Finds the coordinates of the first occurrence of {@code ch} in {@code maze}. */
    private static Position findCell(char[][] maze, char ch) {
        for (int r = 1; r < maze.length; r++) {
            for (int c = 1; c < maze[r].length; c++) {
                if (maze[r][c] == ch) {
                    return new Position(r, c);
                }
            }
        }
        throw new IllegalArgumentException("Cell '" + ch + "' not found in maze");
    }

    /**
     * Simulates the movement according to {@code moveSequence}
     * using the order defined by {@code permutation}.
     *
     * @return {@code true} if the simulated walk ends exactly on the end cell
     */
    private static boolean simulate(Position start,
                                    String moveSequence,
                                    int[] permutation,
                                    char[][] maze,
                                    int rows,
                                    int cols) {
        int curRow = start.row();
        int curCol = start.col();

        for (int stepIndex = 0; stepIndex < moveSequence.length(); stepIndex++) {
            int digit = moveSequence.charAt(stepIndex) - '0'; // 1‑4
            int order = permutation[digit - 1];               // 1‑4 mapping

            switch (order) {
                case 1 -> curRow--;        // up
                case 2 -> curCol++;        // right
                case 3 -> curRow++;        // down
                case 4 -> curCol--;        // left
                default -> throw new AssertionError("Invalid order value: " + order);
            }

            // Stop early if we hit a wall or leave the board.
            if (!inside(maze, curRow, curCol) || maze[curRow][curCol] == '#') {
                break;
            }

            // If we reached the end, we may stop early as well.
            if (curRow == endRow && curCol == endCol) {
                break;
            }
        }

        return curRow == endRow && curCol == endCol;
    }

    /** Helper to check whether a cell is inside the maze boundaries. */
    private static boolean inside(char[][] maze, int r, int c) {
        return r >= 1 && r < maze.length && c >= 1 && c < maze[0].length;
    }

    /** Simple container for a board position (row, column). */
    private static final class Position {
        private final int row;
        private final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }

        int row() { return row; }
        int col() { return col; }

        @Override
        public String toString() {
            return "(" + row + "," + col + ")";
        }
    }

    /** Utility methods that mimic the original Permutation class but are static. */
    private static final class PermutationUtils {

        /** Generates the next lexicographic permutation of {@code arr} in‑place.
         *  Returns {@code true} if such a permutation exists, otherwise {@code false}. */
        static boolean nextPermutation(int[] arr) {
            if (arr.length <= 1) {
                return false;
            }

            // 1. Find the longest non‑increasing suffix
            int i = arr.length - 2;
            while (i >= 0 && arr[i] >= arr[i + 1]) {
                i--;
            }
            if (i < 0) {
                return false; // whole array is non‑increasing → last permutation
            }

            // 2. Find rightmost element that exceeds arr[i]
            int j = arr.length - 1;
            while (arr[j] <= arr[i]) {
                j--;
            }

            // 3. Swap them
            swap(arr, i, j);

            // 4. Reverse the suffix starting at i+1
            reverse(arr, i + 1, arr.length - 1);
            return true;
        }

        private static void swap(int[] arr, int i, int j) {
            int tmp = arr[i];
            arr[i] = arr[j];
            arr[j] = tmp;
        }

        private static void reverse(int[] arr, int from, int to) {
            while (from < to) {
                swap(arr, from++, to--);
            }
        }
    }
}

/**
 * Fast input helper – wraps {@link BufferedReader} and {@link StringTokenizer}
 * to provide convenient {@code next*, nextInt()} methods.
 */
class FastInput {
    private final BufferedReader br;
    private StringTokenizer st;

    FastInput() {
        this.br = new BufferedReader(new java.io.InputStreamReader(System.in));
        this.st = new StringTokenizer("");
    }

    /** @return true if there is still data to read */
    boolean hasNext() {
        while (!st.hasMoreTokens()) {
            try {
                String line = br.readLine();
                if (line == null) {
                    return false;
                }
                st = new StringTokenizer(line);
            } catch (java.io.IOException e) {
                throw new RuntimeException(e);
            }
        }
        return true;
    }

    /** @return next token (as a string) */
    String next() {
        while (!st.hasMoreTokens()) {
            st = new StringTokenizer(hasNext() ? br.readLine() : "");
        }
        return st.nextToken();
    }

    /** @return next integer */
    int nextInt() {
        return Integer.parseInt(next());
    }
}

/**
 * Fast output helper – wraps a {@link PrintWriter} that automatically flushes
 * after each {@code println} call.
 */
class FastOutput {
    private final PrintWriter pw;

    FastOutput() {
        this.pw = new PrintWriter(System.out, true);
    }

    /** Prints a line and also flushes if needed. */
    void println(Object obj) {
        pw.println(obj);
    }

    /** Closes the underlying stream. */
    void close() {
        pw.close();
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Represents a rectangular maze.
 * <p>
 *   - {@code rows} × {@code cols} grid.
 *   - Cells may contain:
 *        • 'S' – start position (exactly one)
 *        • 'E' – exit (goal)
 *        • '#' – obstacle (wall)
 *        • '.' – empty cell
 * </p>
 */
final class Maze {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final Optional<Position> start = Optional.empty();

    Maze(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'S') {
                    start.orElseGet(() -> new Position(r, c));
                }
            }
        }
    }

    int rows() { return rows; }
    int cols() { return cols; }

    char at(int r, int c) {
        return grid[r][c];
    }

    Optional<Position> start() { return start; }

    /** Simple immutable position holder */
    static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

/**
 * Direction of movement.
 */
enum Direction {
    UP(-1, 0),
    DOWN(+1, 0),
    LEFT(0, -1),
    RIGHT(0, +1);

    final int deltaRow;
    final int deltaCol;

    Direction(int deltaRow, int deltaCol) {
        this.deltaRow = deltaRow;
        this.deltaCol = deltaCol;
    }

    /** Apply this direction to a position */
    Position move(Position p) {
        return new Position(p.row + deltaRow, p.col + deltaCol);
    }
}

/**
 * Encapsulates the logic for trying a particular mapping of digits
 * (0‑3) to {@link Direction}s and reporting whether the mapped path
 * reaches the exit.
 */
final class Simulator {
    private final Maze maze;
    private final String moves;               // e.g. "0123"
    private final Map<Integer, Direction> digitToDir; // mapping for the current permutation

    Simulator(Maze maze, String moves, Map<Integer, Direction> digitToDir) {
        this.maze = maze;
        this.moves = moves;
        this.digitToDir = digitToDir;
    }

    /**
     * Executes the movement sequence according to {@code digitToDir}.
     *
     * @return {@code true} if the exit 'E' is reached without hitting a wall
     *         or leaving the board.
     */
    boolean runs() {
        Maze.Position pos = maze.start().orElseThrow();

        for (char ch : moves.toCharArray()) {
            int digit = Character.digit(ch, 10);          // 0‑3
            Direction dir = digitToDir.get(digit);
            pos = dir.move(pos);

            // Bounds / obstacle check
            if (!inBounds(pos.row, pos.col)) {
                return false;
            }
            if (maze.at(pos.row, pos.col) == '#') {
                return false;
            }
            // Success condition
            if (maze.at(pos.row, pos.col) == 'E') {
                return true;
            }
        }
        return false; // never reached 'E'
    }

    private boolean inBounds(int r, int c) {
        return r >= 0 && r < maze.rows() && c >= 0 && c < maze.cols();
    }
}

/**
 * Main driver – reads the input, enumerates all digit→direction
 * permutations and counts those that succeed.
 */
public class EscapeMaze {
    private static final List<Direction> ALL_DIRECTIONS = List.of(Direction.values());

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer tokenizer = new StringTokenizer(br.readLine());
            int rows = Integer.parseInt(tokenizer.nextToken());
            int cols = Integer.parseInt(tokenizer.nextToken());

            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = br.readLine().toCharArray();
            }

            String moves = br.readLine(); // e.g. "0123"

            Maze maze = new Maze(grid);
            int successfulPermutations = countSuccessfulPermutations(moves);

            System.out.println(successfulPermutations);
        }
    }

    /**
     * Generates every possible mapping of the four digits (0‑3) to the four
     * {@link Direction}s and counts those mappings that lead to the exit.
     */
    private static int countSuccessfulPermutations(String moves) {
        int count = 0;

        // All permutations of the four directions (4! = 24)
        List<List<Direction>> permutations = permutations(ALL_DIRECTIONS);

        for (List<Direction> perm : permutations) {
            // Build a digit→direction map: digit 0 gets perm.get(0), digit 1 gets perm.get(1), …
            Map<Integer, Direction> digitToDir = IntStream.range(0, 4)
                    .boxed()
                    .collect(Collectors.toMap(
                            d -> d,
                            d -> perm.get(d)));

            Simulator simulator = new Simulator(maze, moves, digitToDir);
            if (simulator.runs()) {
                count++;
            }
        }
        return count;
    }

    /**
     * Utility that returns every permutation of a given list.
     * For a list of size 4 this yields 24 permutations.
     */
    private static <T> List<List<T>> permutations(List<T> items) {
        List<List<T>> result = new ArrayList<>();
        permute(items, 0, result);
        return result;
    }

    private static <T> void permute(List<T> items, int start, List<List<T>> collector) {
        if (start == items.size()) {
            collector.add(new ArrayList<>(items));
            return;
        }
        for (int i = start; i < items.size(); i++) {
            Collections.swap(items, start, i);
            permute(items, start + 1, collector);
            Collections.swap(items, start, i); // backtrack
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Bug‑Bot – counts how many permutations of the move instructions lead
 * the bot from the start cell to the exit cell without hitting a wall
 * or leaving the grid.
 *
 * The code is deliberately split into small, focused pieces:
 *   • Fast scanner / printer
 *   • Position (row, col) holder
 *   • Direction enum with attached delta vectors
 *   • Heap‑algorithm permutation generator
 *   • Simulation logic
 *
 * All “magic numbers” and raw arrays have been replaced by named constants
 * and small helper classes, making the intent explicit.
 */
public class BuggyBot {

    /* --------------------------------------------------------------------- */
    /*                         Constants & enums                             */
    /* --------------------------------------------------------------------- */

    private static final char START_CHAR = 'S';
    private static final char EXIT_CHAR  = 'E';
    private static final char WALL_CHAR  = '#';

    /** Characters used for the four move‑slots in the input. */
    private static final char[] MOVE_CHARS = {'0', '1', '2', '3'};

    /** Directions are fixed – UP, RIGHT, DOWN, LEFT. */
    private enum Direction {
        UP    ( -1,  0 ),
        RIGHT (  0,  1 ),
        DOWN  (  1,  0 ),
        LEFT  (  0, -1 );

        final int dx;
        final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        /** Convert an integer index (0‑3) to this enum value. */
        static Direction fromIndex(int idx) {
            return values()[idx];
        }
    }

    /* --------------------------------------------------------------------- */
    /*                         Entry point                                    */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) {
        // try‑with‑resources guarantees proper closing of streams
        try (InputScanner in = new InputScanner(System.in);
             OutputPrinter out = new OutputPrinter(System.out)) {

            // ----- read grid dimensions -------------------------------------------------
            int rows = in.nextInt();
            int cols = in.nextInt();

            // ----- read grid and locate start / exit ------------------------------------
            char[][] grid = new char[rows][];
            Position start = null;
            Position exit  = null;

            for (int r = 0; r < rows; r++) {
                String line = in.next();                     // each line is read as a whole
                grid[r] = line.toCharArray();

                for (int c = 0; c < cols; c++) {
                    char cell = grid[r][c];
                    if (cell == START_CHAR) {
                        start = new Position(r, c);
                    } else if (cell == EXIT_CHAR) {
                        exit = new Position(r, c);
                    }
                }
            }

            // ----- read move‑string ----------------------------------------------------
            String moveString = in.next();                     // e.g. "012301"
            char[] moves = moveString.toCharArray();

            // ----- generate all permutations of the four direction vectors -------------
            List<int[][]> directionPerms = DirectionPermutation.generate();

            // ----- simulate each permutation -------------------------------------------
            int successCount = 0;
            for (int[][] perm : directionPerms) {
                if (simulate(start, exit, grid, moves, perm)) {
                    successCount++;
                }
            }

            out.println(successCount);
        }
    }

    /* --------------------------------------------------------------------- */
    /*                         Helper classes & methods                         */
    /* --------------------------------------------------------------------- */

    /** Minimal (row, col) container. */
    private static final class Position {
        final int row;
        final int col;
        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Simulate a single permutation of direction vectors. Returns true if the
     *  bot reaches the exit before hitting a wall or leaving the board. */
    private static boolean simulate(Position start,
                                    Position exit,
                                    char[][] grid,
                                    char[] moves,
                                    int[][] directionIndices) {
        int r = start.row;
        int c = start.col;

        for (char ch : moves) {
            // translate move‑character (0‑3) to a direction index
            int idx = ch - '0';
            Direction dir = Direction.fromIndex(idx);

            // apply the move
            r += dir.dx;
            c += dir.dy;

            // hit a wall or leave the board → abort this permutation
            if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length
                    || grid[r][c] == WALL_CHAR) {
                return false;
            }

            // successfully arrived at the exit → count this permutation
            if (r == exit.row && c == exit.col) {
                return true;
            }
        }
        // ran out of moves without reaching the exit
        return false;
    }

    /** Generates every permutation of the four direction vectors using Heap’s
     *  algorithm. The result is a list of 2‑dimensional int arrays (each inner
     *  array has length 4 and holds two integers – dx and dy). */
    private static final class DirectionPermutation {
        private static List<int[][]> generate() {
            int[][] base = {
                    {-1, 0},   // UP
                    { 0, 1},   // RIGHT
                    { 1, 0},   // DOWN
                    { 0,-1}    // LEFT
            };
            List<int[][]> result = new ArrayList<>();
            permute(base, base.length, result);
            return result;
        }

        private static void permute(int[][] a, int n, List<int[][]> out) {
            if (n == 1) {
                out.add(copy(a));
                return;
            }

            permute(a, n - 1, out);

            for (int i = 0; i < n; i++) {
                swap(a, i, n - 1);
                permute(a, n - 1, out);

                if (n % 2 == 1) {
                    swap(a, 0, n - 1);
                } else {
                    swap(a, i, n - 1);
                }
            }
        }

        private static int[][] copy(int[][] src) {
            // deep copy because each permutation must be independent
            return Arrays.stream(src)
                    .map(row -> row.clone())
                    .toArray(int[][]::new);
        }

        private static void swap(int[][] a, int i, int j) {
            int[] tmp = a[i];
            a[i] = a[j];
            a[j] = tmp;
        }
    }

    /* --------------------------------------------------------------------- */
    /*                         Fast I/O utilities                              */
    /* --------------------------------------------------------------------- */

    /** Simple buffered scanner that works with the original problem's input format. */
    private static final class InputScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[16 * 1024];
        private int ptr = 0, len = 0;

        InputScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() {
            int c;
            do {
                c = readByte();
            } while (c <= ' ' && c != -1);
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return neg ? -val : val;
        }

        String next() {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = readByte();
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }
    }

    /** Minimal printer that writes a single line and flushes. */
    private static final class OutputPrinter {
        private final PrintWriter out;
        OutputPrinter(OutputStream stream) {
            this.out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(stream)));
        }
        void println(Object o) {
            out.println(o);
            out.flush();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Refactored solution for the problem.
 *
 * <p>
 *  The program reads a grid, a start cell (S), an end cell (E) and a string of
 *  instructions consisting of the digits 0‑3.  For every possible mapping of the
 *  digits to one of the four movement directions (down, up, left, right) it
 *  checks whether following the instruction string starting at S leads exactly
 *  to E without stepping on a wall ('#').  The number of such successful
 *  mappings is printed.
 * </p>
 */
public class Main {

    /** Direction vectors ordered as: 0 = down, 1 = up, 2 = left, 3 = right. */
    private static final int[][] DIR_VECTORS = {
            {1, 0},   // down
            {-1, 0},  // up
            {0, -1},  // left
            {0, 1}    // right
    };

    /** Grid and problem‑specific data – kept `static` for simplicity in a
     *  short‑lived program but encapsulated in one place. */
    private static char[][] grid;
    private static int rows, cols;
    private static int startRow, startCol, endRow, endCol;
    private static String instructions;

    /**
     * Determines whether the given digit‑to‑direction mapping allows the robot
     * to reach the exit (E) from the start (S) by following {@code instructions}
     * without hitting a wall.
     *
     * @return {@code true} if the path reaches {@code E} exactly, {@code false}
     *         otherwise.
     */
    private static boolean canReach(char[][] g,
                                    int sr, int sc,
                                    int er, int ec,
                                    String instr,
                                    int[] mapping) {
        int r = sr, c = sc;

        for (int i = 0; i < instr.length(); i++) {
            // Stop early if we leave the grid or hit a wall.
            if (r < 0 || r >= rows || c < 0 || c >= cols || g[r][c] == '#') {
                return false;
            }
            // If we have arrived at the exit before consuming all instructions,
            // the path is still valid (the problem counts this as success).
            if (g[r][c] == 'E') {
                return true;
            }

            int dirIdx = mapping[instr.charAt(i) - '0']; // 0‑3
            int[] d = DIR_VECTORS[dirIdx];
            r += d[0];
            c += d[1];
        }

        // After all instructions we must be exactly on the exit cell.
        return (r == er && c == ec);
    }

    /** Generates all 24 permutations of {0,1,2,3}. */
    private static List<int[]> generateAllMappings() {
        int[] base = {0, 1, 2, 3};
        List<int[]> perms = new ArrayList<>();
        permute(base, 0, perms);
        return perms;
    }

    /** Helper that recursively produces permutations and adds them to {@code collector}. */
    private static void permute(int[] a, int k, List<int[]> collector) {
        if (k == a.length) {
            collector.add(a.clone());
            return;
        }
        for (int i = k; i < a.length; i++) {
            swap(a, i, k);
            permute(a, k + 1, collector);
            swap(a, i, k);
        }
    }

    private static void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    /** Main entry point. */
    public static void main(String[] args) throws IOException {
        // ----- Input ---------------------------------------------------------
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        rows = Integer.parseInt(st.nextToken());
        cols = Integer.parseInt(st.nextToken());

        grid = new char[rows][cols];
        startRow = startCol = endRow = endCol = -1;

        for (int r = 0; r < rows; r++) {
            String line = br.readLine();
            grid[r] = line.toCharArray();
            for (int c = 0; c < cols; c++) {
                char ch = grid[r][c];
                if (ch == 'S') {
                    startRow = r;
                    startCol = c;
                } else if (ch == 'E') {
                    endRow = r;
                    endCol = c;
                }
            }
        }

        instructions = br.readLine().trim();

        // ----- Core logic ----------------------------------------------------
        List<int[]> allMappings = generateAllMappings();
        int answer = 0;

        for (int[] mapping : allMappings) {
            if (canReach(grid, startRow, startCol, endRow, endCol,
                    instructions, mapping)) {
                answer++;
            }
        }

        // ----- Output ---------------------------------------------------------
        System.out.println(answer);
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original competitive‑programming solution.
 * The program reads a grid, a start cell 'S', and a move string.
 * A digit (0‑3) corresponds to one of four movement directions.
 * The task is to count how many permutations of those directions lead
 * from 'S' to the exit 'E' when following the move string.
 *
 * The refactor improves readability, separates concerns and removes
 * mutable global state.
 */
public class Program {

    /** Four possible movement directions (up, left, right, down). */
    private enum Direction {
        UP(-1, 0),
        LEFT(0, -1),
        RIGHT(0, 1),
        DOWN(1, 0);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        /** Move (row, col) by this direction. */
        void apply(int r, int c, char[][] grid) {
            int nr = r + dr;
            int nc = c + dc;
            if (outOfBounds(nr, nc) || grid[nr][nc] == '#') {
                throw new IllegalStateException("Invalid move");
            }
            grid[nr][nc] = '.';               // mark visited
            if (grid[nr][nc] == 'E') {
                throw new ReachedExitException();
            }
            // continue with the next step
        }

        /** @return true if the cell is outside the grid. */
        private boolean outOfBounds(int r, int c) {
            return r < 0 || r >= gridHeight || c < 0 || c >= gridWidth;
        }
    }

    /** Exception used to break out of the search early when the exit is reached. */
    private static final class ReachedExitException extends RuntimeException { }

    /* --------------------------------------------------------------- */
    /*  Instance fields                                                 */
    /* --------------------------------------------------------------- */
    private final InputReader in;
    private final PrintWriter out;

    /** Dimensions of the grid. */
    private int rows, cols;

    /** 2‑D representation of the grid. */
    private char[][] grid;

    /** Starting cell coordinates. */
    private int startRow, startCol;

    /* --------------------------------------------------------------- */
    /*  Constructor                                                    */
    /* --------------------------------------------------------------- */
    /** Runs the program using the standard input / output streams. */
    public static void main(String[] args) {
        new Program().run();
    }

    /** Reads data either from a file pair (A.in / A.out) or from STDIO. */
    private void run() {
        // By default use the console.  Switch to file based I/O if desired.
        in = new InputReader(System.in);
        out = new PrintWriter(System.out, true);

        solve();

        out.flush();
    }

    /* --------------------------------------------------------------- */
    /*  Core algorithm                                                  */
    /* --------------------------------------------------------------- */
    private void solve() {
        readGrid();
        readMoveString();
        List<Direction> moves = decodeMoveString(rr);

        long answer = 0;
        boolean[] used = new boolean[4];
        int[] idx = new int[4];

        permutationSearch(moves, used, idx, 0, answer);

        out.println(answer);
    }

    /** Parses the grid from input and identifies the start cell. */
    private void readGrid() {
        rows = in.nextInt();
        cols = in.nextInt();
        grid = new char[rows][];

        for (int r = 0; r < rows; ++r) {
            String line = in.next();
            grid[r] = line.toCharArray();
        }

        locateStart();
    }

    /** Finds the unique 'S' cell and replaces it with a traversable cell. */
    private void locateStart() {
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] == 'S') {
                    startRow = r;
                    startCol = c;
                    grid[r][c] = '.';          // treat 'S' as empty for simulation
                }
            }
        }
    }

    /** Reads the move string and stores it in the field {@code rr}. */
    private String rr;
    private void readMoveString() {
        rr = in.next();
    }

    /**
     * Converts the raw move string (digits '0'‑'3') into a list of {@link Direction}
     * objects. The mapping follows the original program:
     * 0 → UP, 1 → LEFT, 2 → RIGHT, 3 → DOWN.
     */
    private List<Direction> decodeMoveString(String digits) {
        List<Direction> list = new ArrayList<>(digits.length());
        for (char ch : digits.toCharArray()) {
            int id = ch - '0';
            list.add(Direction.values()[id]);
        }
        return list;
    }

    /**
     * Recursively permutes the direction indices and simulates the walk.
     * The simulation stops as soon as the exit 'E' is reached and
     * increments the supplied {@code answer} counter.
     */
    private void permutationSearch(List<Direction> moves,
                                   boolean[] used,
                                   int[] idx,
                                   int depth,
                                   long[] answer) {
        if (depth == moves.size()) {
            simulatePath(moves.get(idx[0]),
                         moves.get(idx[1]),
                         moves.get(idx[2]),
                         moves.get(idx[3]));
            return;
        }

        for (int i = 0; i < 4; ++i) {
            if (!used[i]) {
                used[i] = true;
                idx[depth] = i;
                permutationSearch(moves, used, idx, depth + 1, answer);
                used[i] = false;
            }
        }
    }

    /**
     * Executes the walk according to the supplied direction permutation.
     * If the path reaches 'E' the static counter is incremented.
     */
    private void simulatePath(Direction d0, Direction d1, Direction d2, Direction d3) {
        // Work on a copy of the grid to keep the original unchanged.
        char[][] simulation = copyGrid();

        try {
            Direction[] ordered = { d0, d1, d2, d3 };
            for (Direction dir : ordered) {
                dir.apply(startRow, startCol, simulation);
            }
        } catch (ReachedExitException ignored) {
            // The exit was reached – increment the global counter.
            answer.incrementAndGet();
        }
    }

    /** Creates a deep copy of the current grid. */
    private static char[][] copyGrid() {
        char[][] copy = new char[rows][];
        for (int r = 0; r < rows; ++r) {
            copy[r] = grid[r].clone();
        }
        return copy;
    }

    /* --------------------------------------------------------------- */
    /*  Fast input reader (lightweight wrapper)                         */
    /* --------------------------------------------------------------- */
    /** Simple wrapper around {@link BufferedReader} that tokenises input. */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
        }

        /** Reads the next token, expanding the underlying buffer as needed. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Convenience methods */
        int nextInt() { return Integer.parseInt(nextToken()); }
        String next() { return nextToken(); }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Reads a maze, an instruction string and counts how many permutations of the
 * four movement directions (up, right, down, left) lead the robot from the
 * start cell 'S' to the end cell 'E' without hitting a wall or leaving the
 * grid. The mapping is performed by interpreting each character of the
 * instruction as an index (1‑4) that points to a direction from the current
 * permutation.
 */
public class ProblemB {

    /** Grid cell values */
    private static final int EMPTY   = 0;
    private static final int WALL    = -1;
    private static final int START   = 1;
    private static final int END     = 2;

    /** Movement directions */
    private enum Direction {
        UP(-1, 0), RIGHT(0, 1), DOWN(1, 0), LEFT(0, -1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int getRowDelta() { return dr; }
        int getColDelta() { return dc; }
    }

    /** Holds the maze data and start/exit positions */
    private static class Maze {
        private final int[][] grid;
        private final int rows;
        private final int cols;
        private int startRow = -1;
        private int startCol = -1;

        Maze(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new int[rows][cols];
        }

        /** Parses one line of the maze and updates internal state */
        void readRow(int rowIdx, String line) {
            for (int colIdx = 0; colIdx < cols; colIdx++) {
                char c = line.charAt(colIdx);
                int value;
                if (c == '#') {
                    value = WALL;
                } else if (c == 'S') {
                    value = START;
                    startRow = rowIdx;
                    startCol = colIdx;
                } else if (c == 'E') {
                    value = END;
                } else {
                    value = EMPTY;
                }
                grid[rowIdx][colIdx] = value;
            }
        }

        /** Returns a copy of the underlying grid (read‑only) */
        int[][] getGrid() {
            return grid.clone();
        }

        /** Provides read‑only access to start coordinates */
        int getStartRow() { return startRow; }

        /** Provides read‑only access to start coordinates */
        int getStartCol() { return startCol; }

        /** Checks bounds and whether a cell is a wall */
        boolean isInside(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Retrieves the cell value at (r,c) */
        int cellValue(int r, int c) {
            return grid[r][c];
        }
    }

    /** Generates all permutations of the four Direction enum values */
    private static List<Direction[]> allDirectionPermutations() {
        List<Direction[]> perms = new ArrayList<>();
        Direction[] base = {Direction.UP, Direction.RIGHT, Direction.DOWN, Direction.LEFT};

        generatePermutations(base, 0, perms);
        return perms;
    }

    /** Recursive helper that builds permutations in‑place */
    private static void generatePermutations(Direction[] arr, int index, List<Direction[]> collector) {
        if (index == arr.length) {
            collector.add(arr.clone());
            return;
        }

        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            generatePermutations(arr, index + 1, collector);
            swap(arr, index, i); // backtrack
        }
    }

    /** Swaps two elements in the array */
    private static void swap(Object[] a, int i, int j) {
        Object tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    /** Simulates movement using a given permutation of directions */
    private static boolean simulate(Maze maze, Direction[] perm, String instruction) {
        int r = maze.getStartRow();
        int c = maze.getStartCol();

        // early exit if start is already on the goal (unlikely in typical mazes)
        if (maze.cellValue(r, c) == Maze.END) {
            return true;
        }

        for (int i = 0; i < instruction.length(); i++) {
            int digit = instruction.charAt(i) - '1';          // 0‑based index
            if (digit < 0 || digit >= perm.length) {
                break;                                        // invalid digit, stop simulation
            }

            Direction d = perm[digit];
            r += d.getRowDelta();
            c += d.getColDelta();

            // hit a wall or leave grid → abort this permutation
            if (!maze.isInside(r, c) || maze.cellValue(r, c) == Maze.WALL) {
                break;
            }

            // reached the exit during traversal
            if (maze.cellValue(r, c) == Maze.END) {
                return true;
            }
        }

        // If we finish the whole instruction string and land on the exit,
        // the permutation is also successful.
        return maze.isInside(r, c) && maze.cellValue(r, c) == Maze.END;
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // consume the line break

            Maze maze = new Maze(rows, cols);
            for (int r = 0; r < rows; r++) {
                maze.readRow(r, scanner.nextLine());
            }

            String instruction = scanner.next(); // instruction string

            List<Direction[]> permutations = allDirectionPermutations();
            int successful = 0;

            for (Direction[] perm : permutations) {
                if (simulate(maze, perm, instruction)) {
                    successful++;
                }
            }

            System.out.println(successful);
        }
    }
}

import java.util.*;

public class MazeSolver {

    /** Four possible moves with their row/column deltas. */
    enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        private final int deltaRow;
        private final int deltaCol;

        Direction(int deltaRow, int deltaCol) {
            this.deltaRow = deltaRow;
            this.deltaCol = deltaCol;
        }

        int deltaRow() { return deltaRow; }
        int deltaCol() { return deltaCol; }
    }

    /**
     * Executes a single permutation of direction mappings.
     *
     * @param moves      sequence of direction digits ('0'‑'3')
     * @param grid       maze grid
     * @param digitToDir mapping from digit character to {@link Direction}
     * @param startRow   row of the starting cell ('S')
     * @param startCol   column of the starting cell ('S')
     * @return true if the path reaches 'E' without leaving the grid or hitting '#'
     */
    private static boolean simulate(String moves, char[][] grid,
                                    Map<Character, Direction> digitToDir,
                                    int startRow, int startCol) {
        int row = startRow;
        int col = startCol;

        for (char c : moves.toCharArray()) {
            Direction dir = digitToDir.get(c);
            if (dir == null) {
                return false;               // should never happen for valid input
            }
            row += dir.deltaRow();
            col += dir.deltaCol();

            // out of bounds or blocked by wall
            if (row < 0 || row >= grid.length ||
                col < 0 || col >= grid[0].length ||
                grid[row][col] == '#') {
                return false;
            }
            // reached the goal
            if (grid[row][col] == 'E') {
                return true;
            }
        }
        return false;   // goal not reached within the given moves
    }

    /**
     * Generates all permutations of a list using back‑tracking.
     */
    private static <T> void permute(List<T> items, int idx,
                                    boolean[] used, List<T> current,
                                    List<List<T>> result) {
        if (idx == items.size()) {
            result.add(new ArrayList<>(current));
            return;
        }
        for (int i = 0; i < items.size(); i++) {
            if (!used[i]) {
                used[i] = true;
                current.add(items.get(i));
                permute(items, idx + 1, used, current, result);
                current.remove(current.size() - 1);
                used[i] = false;
            }
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            scanner.nextLine();                     // consume end‑of‑line

            char[][] grid = new char[n][];
            int startRow = -1, startCol = -1;

            for (int i = 0; i < n; i++) {
                String line = scanner.nextLine();
                grid[i] = line.toCharArray();
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    }
                }
            }

            String moves = scanner.nextLine();        // the dr sequence

            // -----------------------------------------------------------------
            // 1. Collect all 4 possible directions and generate every permutation
            // -----------------------------------------------------------------
            List<Direction> allDirections = new ArrayList<>(Arrays.asList(
                    Direction.UP, Direction.DOWN, Direction.LEFT, Direction.RIGHT));

            List<List<Direction>> permutations = new ArrayList<>();
            boolean[] used = new boolean[allDirections.size()];
            List<Direction> current = new ArrayList<>();
            permute(allDirections, 0, used, current, permutations);

            // -----------------------------------------------------------------
            // 2. For each permutation build a digit → Direction map and test it
            // -----------------------------------------------------------------
            int successful = 0;
            for (List<Direction> perm : permutations) {
                Map<Character, Direction> digitMap = new HashMap<>();
                // digits '0' .. '3' correspond to positions 0..3 in the permutation
                for (int digit = 0; digit < 4; digit++) {
                    digitMap.put((char) ('0' + digit), perm.get(digit));
                }
                if (simulate(moves, grid, digitMap, startRow, startCol)) {
                    successful++;
                }
            }

            System.out.println(successful);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* ---------- constants ---------- */
    private static final char WALL = '*';
    private static final char END  = 'E';
    private static final char OBSTACLE = '#';   // present in original checks

    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = { 0,-1, 0, 1};

    /* ---------- position ---------- */
    private static final class Position {
        int x, y;
        Position(int x, int y) { this.x = x; this.y = y; }
        void move(int dx, int dy) { this.x += dx; this.y += dy; }
    }

    /* ---------- solver ---------- */
    private static final class Solver {
        private final char[][] grid;
        private final Position start;
        private final Position end;
        private final String commands;

        Solver(char[][] grid, Position start, Position end, String commands) {
            this.grid = grid;
            this.start = start;
            this.end = end;
            this.commands = commands;
        }

        /** Counts permutations of the four directions that lead from start to end */
        int countValidPermutations() {
            int count = 0;
            // generate all permutations of {0,1,2,3} without repetition
            for (int a = 0; a < 4; a++) {
                for (int b = 0; b < 4; b++) {
                    if (b == a) continue;
                    for (int c = 0; c < 4; c++) {
                        if (c == a || c == b) continue;
                        for (int d = 0; d < 4; d++) {
                            if (d == a || d == b || d == c) continue;
                            int[] dirMap = {a, b, c, d};
                            if (simulate(dirMap)) {
                                count++;
                            }
                        }
                    }
                }
            }
            return count;
        }

        /** Simulate movement according to a direction mapping */
        private boolean simulate(int[] dirMap) {
            Position pos = new Position(start.x, start.y);
            for (char ch : commands.toCharArray()) {
                int dirIdx = ch - '0';                 // 0 .. 3
                int[] off = dirMap[dirIdx];            // one of 0..3
                pos.move(DX[off], DY[off]);            // move according to OFFSETS
                char cell = grid[pos.x][pos.y];
                if (cell == WALL || cell == OBSTACLE || cell == END) {
                    break; // stop as soon as we hit a terminal or blocking cell
                }
            }
            // success only when we landed exactly on the END cell
            return grid[pos.x][pos.y] == END;
        }
    }

    /* ---------- fast input ---------- */
    private static final class FastInput {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastInput(InputStream stream) { this.stream = stream; }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = stream.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c, sign = 1, val = 0;
            do { c = readByte(); } while (c <= ' ' && c != -1);
            if (c == '-') { sign = -1; c = readByte(); }
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val * sign;
        }

        String next() throws IOException {
            int c;
            do { c = readByte(); } while (c <= ' ');
            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }
    }

    /* ---------- main ---------- */
    public static void main(String[] args) throws Exception {
        FastInput in = new FastInput(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Only a single test case is used (the original code reads `t` but never varies it)
        int t = in.nextInt();   // expected to be 1

        int n = in.nextInt();
        int m = in.nextInt();

        // Create padded grid surrounded by walls
        char[][] mat = new char[n + 2][m + 2];
        Arrays.fill(mat[0], WALL);
        Arrays.fill(mat[n + 1], WALL);
        for (int i = 1; i <= n; i++) {
            mat[i][0] = WALL;
            mat[i][m + 1] = WALL;
        }

        Position start = new Position(0, 0);
        Position end   = new Position(0, 0);
        for (int i = 1; i <= n; i++) {
            String line = in.next();
            char[] chars = line.toCharArray();
            for (int j = 1; j <= m; j++) {
                mat[i][j] = chars[j - 1];
                if (mat[i][j] == 'S') {
                    start.x = i; start.y = j;
                } else if (mat[i][j] == 'E') {
                    end.x = i; end.y = j;
                }
            }
        }

        String commands = in.next();

        Solver solver = new Solver(mat, start, end, commands);
        out.println(solver.countValidPermutations());

        out.flush();
        out.close();
    }
}

import java.io.*;
import java.util.*;

public class B {

    /* ------------------------------------------------------------ */
    /*                     CONSTANTS & HELPERS                     */
    /* ------------------------------------------------------------ */

    /** Up, Left, Down, Right */
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, -1, 0, 1};

    /** Fast scanner that works with any {@link Reader}. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(Reader in) {
            br = new BufferedReader(in);
        }

        /** Returns next token or reads a new line until a token is available. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        char[] nextCharArray() {
            return next().toCharArray();
        }
    }

    /** Simple callback executed for every generated permutation. */
    @FunctionalInterface
    private interface PermutationConsumer {
        void accept(int[] permutation);
    }

    /* ------------------------------------------------------------ */
    /*                               MAIN                            */
    /* ------------------------------------------------------------ */

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int rows = fs.nextInt();
        int cols = fs.nextInt();

        char[][] board = new char[rows][];
        int startR = -1, startC = -1;
        int endR = -1, endC = -1;

        /* ---- read board ------------------------------------------------ */
        for (int r = 0; r < rows; r++) {
            char[] line = fs.nextCharArray();
            board[r] = line;
            for (int c = 0; c < cols; c++) {
                char ch = line[c];
                if (ch == 'S') {
                    startR = r;
                    startC = c;
                } else if (ch == 'E') {
                    endR = r;
                    endC = c;
                }
            }
        }

        String commands = fs.next();               // digit string, e.g. "0123"
        int reachable = countReachable(board, startR, startC,
                                       commands);

        out.println(reachable);
        out.close();
    }

    /* ------------------------------------------------------------ */
    /*            Core logic: count permutations that succeed       */
    /* ------------------------------------------------------------ */

    /**
     * Tries every permutation of directions {0,1,2,3}.
     * For each permutation the supplied command string is interpreted
     * using that permutation order.  If the path reaches the exit ‘E’
     * the counter is incremented.
     */
    private static int countReachable(char[][] board,
                                      int startR, int startC,
                                      String commands) {
        int[][] dirMap = {{0}, {1}, {2}, {3}}; // each digit maps to one direction
        int reachable = 0;

        // generate all 4! permutations without using recursion
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) if (j != i) {
                for (int k = 0; k < 4; k++) if (k != i && k != j) {
                    for (int p = 0; p < 4; p++) if (p != i && p != j && p != k) {
                        int[] order = {i, j, k, p};

                        // simulate using this permutation
                        if (simulate(board, startR, startC, commands, order)) {
                            reachable++;
                        }
                    }
                }
            }
        }
        return reachable;
    }

    /**
     * Executes the movement dictated by {@code commands} when the
     * direction order is given by {@code order}.
     * Returns {@code true} iff the path reaches an ‘E’ cell.
     */
    private static boolean simulate(char[][] board,
                                   int startR, int startC,
                                   String commands,
                                   int[] order) {
        // work on a copy so the original board stays untouched
        char[][] grid = copyBoard(board);

        int r = startR;
        int c = startC;

        for (char ch : commands.toCharArray()) {
            int dirIdx = ch - '0';               // '0'..'3' → 0..3
            int nd = order[dirIdx];              // actual direction index

            int nr = r + DR[nd];
            int nc = c + DC[nd];

            // out of bounds → fail
            if (!inBounds(nr, nc, board.length, board[0].length)) {
                return false;
            }

            // wall → fail
            if (grid[nr][nc] == '#') {
                return false;
            }

            // reached exit → success
            if (grid[nr][nc] == 'E') {
                return true;
            }

            // ordinary free cell → continue
            r = nr;
            c = nc;
        }
        return false; // command string exhausted without reaching ‘E’
    }

    /** Deep copy of the board (used only for safe simulation). */
    private static char[][] copyBoard(char[][] src) {
        char[][] copy = new char[src.length][];
        for (int i = 0; i < src.length; i++) {
            copy[i] = src[i].clone();
        }
        return copy;
    }

    /** Returns true if (r,c) lies inside the given board dimensions. */
    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.util.*;

public class LabyrinthSolver {

    /* --------------------------------------------------------------------- */
    /*  Constants & static state                                                */
    /* --------------------------------------------------------------------- */
    private static final char START = 'S';
    private static final char EMPTY = '.';   // not used directly, kept for clarity
    private static final char WALL = '#';
    private static final char EXIT = 'E';

    private static char[][] grid;          // labyrinth grid
    private static int startRow, startCol;   // position of 'S'
    private static String instruction;     // movement string

    /* --------------------------------------------------------------------- */
    /*  Direction enum – maps a digit to a movement direction                  */
    /* --------------------------------------------------------------------- */
    private enum Direction {
        LEFT(-1, 0),   // dr, dc for row/col delta
        RIGHT(1, 0),
        UP(-1, 0);
        DOWN(1, 0);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int deltaRow() { return dr; }
        int deltaCol() { return dc; }

        static Direction fromDigit(char digit) {
            // The caller guarantees the digit is one of '0'..'3'.
            // The mapping is supplied by the caller via a map.
            throw new UnsupportedOperationException("Digit mapping must be provided externally");
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core logic – checks whether a concrete assignment of digits works      */
    /* --------------------------------------------------------------------- */
    private static boolean canReachExit(int left, int right, int up, int down) {
        // Map each digit character to its direction
        Map<Character, Direction> digitToDir = Map.of(
                (char) ('0' + left),  Direction.LEFT,
                (char) ('0' + right), Direction.RIGHT,
                (char) ('0' + up),    Direction.UP,
                (char) ('0' + down),  Direction.DOWN
        );

        int r = startRow;
        int c = startCol;

        for (int i = 0; i < instruction.length(); i++) {
            char digit = instruction.charAt(i);
            Direction dir = digitToDir.get(digit);
            if (dir == null) {
                return false;                 // unexpected digit
            }

            int nr = r + dir.deltaRow();
            int nc = c + dir.deltaCol();

            // Boundary or wall encounter – path invalid
            if (outOfBounds(nr, nc) || grid[nr][nc] == WALL) {
                return false;
            }

            // If we stepped on the exit before finishing the string,
            // the path is still considered valid only if we finish exactly on EXIT.
            if (grid[nr][nc] == EXIT && i == instruction.length() - 1) {
                return true;
            }

            r = nr;
            c = nc;
        }

        // After processing all instructions we must end on EXIT.
        return inBounds(r, c) && grid[r][c] == EXIT;
    }

    /* --------------------------------------------------------------------- */
    /*  Utility helpers                                                        */
    /* --------------------------------------------------------------------- */
    private static boolean outOfBounds(int r, int c) {
        return r < 0 || r >= grid.length || c < 0 || c >= grid[0].length;
    }

    private static boolean inBounds(int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /* --------------------------------------------------------------------- */
    /*  Permutation iterator – yields every distinct assignment of            */
    /*  digits 0‑3 to the four directions.                                     */
    /* --------------------------------------------------------------------- */
    private static void iterateAssignments(Runnable onAssignment) {
        int[] digits = {0, 1, 2, 3};

        do {
            int left = digits[0];
            int right = digits[1];
            int up = digits[2];
            int down = digits[3];

            if (canReachExit(left, right, up, down)) {
                onAssignment.run();
            }
        } while (nextPermutation(digits));
    }

    private static boolean nextPermutation(int[] a) {
        int n = a.length;
        // Find longest non‑increasing suffix
        int i = n - 2;
        while (i >= 0 && a[i] > a[i + 1]) {
            i--;
        }
        if (i < 0) {
            return false; // last permutation reached
        }
        // Find rightmost element greater than a[i]
        int j = n - 1;
        while (a[j] < a[i]) {
            j--;
        }
        // Swap a[i] and a[j]
        swap(a, i, j);
        // Reverse suffix starting at i+1
        reverse(a, i + 1, n - 1);
        return true;
    }

    private static void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    private static void reverse(int[] arr, int start, int end) {
        while (start < end) {
            swap(arr, start++, end--);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Program entry point                                                    */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // consume newline

            // Read grid and locate the start cell
            grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                String line = scanner.nextLine();
                grid[r] = line.toCharArray();
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == START) {
                        startRow = r;
                        startCol = c;
                    }
                }
            }

            // Read the movement instruction string
            instruction = scanner.next();

            // Count all distinct assignments that lead to the exit
            iterateAssignments(() -> {}); // the lambda is only needed for side‑effect of increment

            // The count is printed by the iterateAssignments lambda's side‑effect
            // (we keep it simple by printing inside the lambda)
            System.out.println(count);
        }
    }
}

/**
 * B – refactored version.
 *
 * <p>Reads a grid, a start cell marked 'S', an exit cell marked 'E' and a sequence of
 * digits (0‑3). For every permutation of the four movement directions {@code {u,d,l,r}}
 * it follows the steps indicated by the digit sequence using the permutation as a
 * lookup table. The program prints the number of permutations that lead from {@code S}
 * to {@code E} without leaving the grid or hitting a wall.
 *
 * <p>This version is deliberately split into small, focused classes and methods so
 * that each responsibility (I/O, grid handling, permutation generation, path
 * simulation) is isolated and easily testable.
 */
public class B {

    /** Simple scanner that works with {@link InputStream}. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            this.br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next token, reading a new line when the current one is exhausted. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Convenience wrappers for the usual primitive types. */
        int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
        long nextLong() throws IOException { return Long.parseLong(nextToken()); }
        double nextDouble() throws IOException { return Double.parseDouble(nextToken()); }
    }

    /** Enum that encapsulates the four allowed moves and their coordinate deltas. */
    private enum Direction {
        UP(1, 0),   // 'u' : move down (row+1) because the original code used opposite semantics
        DOWN(-1, 0), // 'd' : move up (row-1)
        LEFT(0, -1), // 'l' : move right (col+1)
        RIGHT(0, 1); // 'r' : move left (col-1)

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        /** Returns the delta row/col for this direction. */
        int[] delta() {
            return new int[]{dr, dc};
        }
    }

    /** Holds the solver logic – all heavy lifting lives inside this class. */
    private static final class Solver {

        /** The four direction characters used by the original program. */
        private static final char[] ALL_DIRS = {'u', 'd', 'l', 'r'};

        /** Generates every permutation of the four directions (length 4, no repeats). */
        private static void generatePermutations(List<String> out, StringBuilder cur) {
            if (cur.length() == ALL_DIRS.length) {
                out.add(cur.toString());
                return;
            }
            for (char c : ALL_DIRS) {
                if (!cur.toString().contains(String.valueOf(c))) {
                    cur.append(c);
                    generatePermutations(out, cur);
                    cur.setLength(cur.length() - 1); // backtrack
                }
            }
        }

        /** Simulates a path according to a digit sequence using a concrete permutation. */
        private static boolean simulate(
                char[][] grid,
                int startRow,
                int startCol,
                String digits,
                String permutation) {

            int row = startRow;
            int col = startCol;

            for (int step = 0; step < digits.length(); step++) {
                int dirIdx = digits.charAt(step) - '0';
                if (dirIdx < 0 || dirIdx >= permutation.length()) {
                    // Safety check – should never happen with valid input.
                    return false;
                }

                char move = permutation.charAt(dirIdx);
                int[] delta = directionDelta(move);
                row += delta[0];
                col += delta[1];

                // Out of bounds or wall -> dead end.
                if (!inBounds(grid, row, col) || grid[row][col] == '#') {
                    return false;
                }

                // Reached the exit cell.
                if (grid[row][col] == 'E') {
                    return true;
                }
            }
            // If we never hit 'E' during the simulation the path is a failure.
            return false;
        }

        /** Helper that maps a direction character to its offset. */
        private static int[] directionDelta(char ch) {
            switch (ch) {
                case 'u': return Direction.UP.delta();
                case 'd': return Direction.DOWN.delta();
                case 'l': return Direction.LEFT.delta();
                case 'r': return Direction.RIGHT.delta();
                default:  return new int[]{0, 0};
            }
        }

        /** Checks whether coordinates are inside the grid. */
        private static boolean inBounds(char[][] grid, int r, int c) {
            return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
        }

        /** Entry point called from {@code main}. */
        void solve(FastScanner in, PrintWriter out) throws IOException {
            // ----- read dimensions -------------------------------------------------
            int rows = in.nextInt();
            int cols = in.nextInt();

            // ----- read the grid ---------------------------------------------------
            char[][] grid = new char[rows][cols];
            int startR = -1, startC = -1;

            for (int r = 0; r < rows; r++) {
                String line = in.nextToken();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c);
                    if (grid[r][c] == 'S') {
                        startR = r;
                        startC = c;
                    }
                }
            }

            // ----- read the digit sequence -----------------------------------------
            String digitSeq = in.nextToken();

            // ----- generate all direction permutations ----------------------------
            List<String> perms = new ArrayList<>();
            generatePermutations(perms, new StringBuilder());

            // ----- evaluate each permutation ---------------------------------------
            int answer = 0;
            for (String perm : perms) {
                if (simulate(grid, startR, startC, digitSeq, perm)) {
                    answer++;
                }
            }
            out.println(answer);
        }
    }

    /** Starts the program – either with a tiny debug harness or with real I/O. */
    public static void main(String[] args) throws IOException {
        boolean DEBUG = false; // set to true to enable the bundled debug input
        FastScanner scanner;
        PrintWriter writer = new PrintWriter(System.out);

        if (DEBUG) {
            // ---------------------------------------------------------------
            // Simple self‑contained debug harness; replaces System.in with a
            // fixed string (the same behaviour as the original program).
            // ---------------------------------------------------------------
            String fixedInput = "10"; // <-- adjust if you want a larger example
            scanner = new FastScanner(new ByteArrayInputStream(fixedInput.getBytes()));
        } else {
            scanner = new FastScanner(System.in);
        }

        new Solver().solve(scanner, writer);
        writer.flush();
    }
}

import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Refactored version of the original BuggyBot program.
 * The program reads a grid containing a start cell ('S'), an end cell ('E')
 * and obstacles ('#'), then evaluates how many permutations of the
 * direction map "0123" allow a path that reaches the end cell while
 * obeying the given move sequence.
 */
public class BugBotRefactored {

    // -------------------------------------------------------------------------
    // Constants
    // -------------------------------------------------------------------------
    private static final char START = 'S';
    private static final char END = 'E';
    private static final char BLOCK = '#';

    // Movement vectors: down, right, up, left
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    // -------------------------------------------------------------------------
    // Entry point
    // -------------------------------------------------------------------------
    public static void main(String[] args) throws IOException {
        try (java.util.Scanner scanner = new java.util.Scanner(System.in)) {
            int rows = scanner.nextInt();   // number of inner rows
            int cols = scanner.nextInt();   // number of inner columns

            char[][] grid = readAndBorder(grid = new char[rows + 2][cols + 2], scanner, rows, cols);

            int startX = -1, startY = -1;
            locateStart(grid, rows, cols, startX, startY); // fills startX/Y

            if (startX == -1) {
                System.out.println(0);
                return;
            }

            String moveSequence = scanner.next();

            List<String> permutations = generatePermutations("0123");
            int validCount = 0;

            for (String perm : permutations) {
                if (isValidPath(grid, startX, startY, moveSequence, perm)) {
                    validCount++;
                }
            }

            System.out.println(validCount);
        }
    }

    // -------------------------------------------------------------------------
    // Input handling
    // -------------------------------------------------------------------------
    /** Adds a border of BLOCK characters around the inner grid and fills it. */
    private static char[][] readAndBorder(char[][] borderedGrid, java.util.Scanner sc,
                                          int rows, int cols) {
        // Fill the whole bordered grid with the block character
        for (char[] row : borderedGrid) {
            Arrays.fill(row, BLOCK);
        }

        // Populate the inner part
        for (int i = 1; i <= rows; i++) {
            String line = sc.next();
            for (int j = 1; j <= cols; j++) {
                borderedGrid[i][j] = line.charAt(j - 1);
            }
        }
        return borderedGrid;
    }

    /** Finds the coordinates of the START cell in the grid. */
    private static void locateStart(char[][] grid, int rows, int cols,
                                    int[] startX, int[] startY) {
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (grid[i][j] == START) {
                    startX[0] = i;
                    startY[0] = j;
                }
            }
        }
    }

    // -------------------------------------------------------------------------
    // Permutation generation
    // -------------------------------------------------------------------------
    /** Generates all permutations of the supplied string. */
    private static List<String> generatePermutations(String source) {
        List<String> result = new ArrayList<>();
        permute("", source, result);
        return result;
    }

    private static void permute(String prefix, String remaining, List<String> collector) {
        if (remaining.isEmpty()) {
            collector.add(prefix);
            return;
        }
        for (int i = 0; i < remaining.length(); i++) {
            char chosen = remaining.charAt(i);
            String newRemaining = remaining.substring(0, i) + remaining.substring(i + 1);
            permute(prefix + chosen, newRemaining, collector);
        }
    }

    // -------------------------------------------------------------------------
    // Path validation
    // -------------------------------------------------------------------------
    /**
     * Checks whether following the move sequence using the supplied permutation
     * leads to the END cell without hitting a BLOCK.
     */
    private static boolean isValidPath(char[][] grid, int startX, int startY,
                                       String moves, String perm) {
        int x = startX;
        int y = startY;

        for (char digitChar : moves.toCharArray()) {
            int dirIndex = digitChar - '0';               // 0‑3
            if (dirIndex < 0 || dirIndex > 3) {
                return false; // invalid digit encountered
            }

            int move = perm.charAt(dirIndex) - '0';       // direction 0‑3
            x += DX[move];
            y += DY[move];

            if (grid[x][y] == BLOCK) {
                return false;
            }
            if (grid[x][y] == END) {
                return true;
            }
        }
        return false; // never reached END
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** Entry point */
    public static void main(String[] args) throws Exception {
        try (MyReader reader = new MyReader(System.in)) {
            try (MyWriter writer = new MyWriter(System.out)) {
                new Solution().run(reader, writer);
            }
        }
    }

    /** Orchestrates the whole workflow */
    void run(MyReader reader, MyWriter writer) throws IOException {
        InputData data = parseInput(reader);
        int answer = countValidPermutations(data);
        writer.print(answer);
    }

    /** Reads and validates the complete input */
    private InputData parseInput(MyReader reader) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        char[][] grid = reader.nextCharMatrix(rows);
        int startRow = -1, startCol = -1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'S') {
                    startRow = r;
                    startCol = c;
                }
            }
        }

        if (startRow < 0) {
            throw new IllegalArgumentException("Start cell 'S' not found");
        }

        String target = reader.nextString();

        return new InputData(rows, cols, grid, startRow, startCol, target);
    }

    /** Counts how many of the 24 direction permutations lead to 'E' without hitting '#'. */
    private int countValidPermutations(InputData data) {
        int answer = 0;
        int[] basePerm = {0, 1, 2, 3};

        do {
            if (simulateWithPermutation(data, basePerm)) {
                answer++;
            }
        } while (nextPermutation(basePerm));

        return answer;
    }

    /** Simulates a single permutation of direction mappings. */
    private boolean simulateWithPermutation(InputData d, int[] perm) {
        int r = d.startRow;
        int c = d.startCol;

        for (int i = 0; i < d.target.length(); i++) {
            char digit = d.target.charAt(i);
            int dirIndex = digit - '0';          // 0..3
            int dir = perm[dirIndex];            // actual direction 0..3

            int nr = r, nc = c;
            switch (dir) {
                case 0 -> nr++;   // move down
                case 1 -> nr--;   // move up
                case 2 -> nc--;   // move left
                case 3 -> nc++;   // move right
                default -> throw new IllegalStateException("Invalid direction index: " + dir);
            }

            // out‑of‑bounds or obstacle => fail
            if (nr < 0 || nr >= d.rowCount || nc < 0 || nc >= d.colCount) {
                return false;
            }

            char cell = d.grid[nr][nc];
            if (cell == 'E') {
                return true;            // success – reached the exit
            }
            if (cell == '#') {
                return false;           // failure – hit a wall
            }

            // empty cell ('.' or 'S') – continue moving
            r = nr;
            c = nc;
        }

        // If the whole command string is processed without hitting 'E' or '#',
        // the permutation does not satisfy the requirement.
        return false;
    }

    /** Generates the next lexicographic permutation in‑place; returns false when finished. */
    private boolean nextPermutation(int[] a) {
        int i = a.length - 2;
        while (i >= 0 && a[i] >= a[i + 1]) {
            i--;
        }
        if (i < 0) {
            return false; // no more permutations
        }
        int j = a.length - 1;
        while (a[j] <= a[i]) {
            j--;
        }
        swap(a, i, j);
        reverse(a, i + 1, a.length - 1);
        return true;
    }

    private void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    private void reverse(int[] arr, int from, int to) {
        while (from < to) {
            swap(arr, from++, to--);
        }
    }

    /** Simple DTO that holds all parsed input data. */
    private static final class InputData {
        final int rowCount;
        final int colCount;
        final char[][] grid;
        final int startRow;
        final int startCol;
        final String target;

        InputData(int rowCount, int colCount, char[][] grid, int startRow, int startCol, String target) {
            this.rowCount = rowCount;
            this.colCount = colCount;
            this.grid = grid;
            this.startRow = startRow;
            this.startCol = startCol;
            this.target = target;
        }
    }

    /** Fast scanner based on BufferedInputStream with a reusable buffer. */
    static final class MyReader {
        private final BufferedInputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int bufPos = 0, bufLen = 0;

        MyReader(InputStream source) {
            this.in = new BufferedInputStream(source, buffer.length);
        }

        private int readByte() throws IOException {
            if (bufPos >= bufLen) {
                bufLen = in.read(buffer);
                bufPos = 0;
                if (bufLen == -1) throw new EOFException();
            }
            return buffer[bufPos++];
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }

        long nextLong() throws IOException {
            int c;
            long value = 0;
            boolean negative = false;

            // skip whitespace
            do {
                c = readByte();
            } while (c <= ' ' && c != -1);

            if (c == '-') {
                negative = true;
                c = readByte();
            } else if (c == '+') {
                c = readByte();
            }

            // read number
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return negative ? -value : value;
        }

        char nextChar() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c <= ' ' && c != -1);
            return (char) c;
        }

        String nextString() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            // skip whitespace
            do {
                c = readByte();
            } while (c <= ' ' && c != -1);
            if (c == -1) {
                return null;
            }
            // read until next whitespace
            while (c > ' ') {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        char[][] nextCharMatrix(int rows) throws IOException {
            char[][] mat = new char[rows][];
            for (int i = 0; i < rows; i++) {
                mat[i] = nextString().toCharArray();
            }
            return mat;
        }
    }

    /** Fast printer that buffers output to avoid excessive system calls. */
    static final class MyWriter {
        private final BufferedOutputStream out;
        private final byte[] buffer = new byte[1 << 16];
        private int bufPos = 0;

        MyWriter(OutputStream target) {
            this.out = new BufferedOutputStream(target, buffer.length);
        }

        private void ensureCapacity(int size) throws IOException {
            if (bufPos + size >= buffer.length) {
                out.write(buffer, 0, bufPos);
                out.flush();
                bufPos = 0;
            }
        }

        private void writeByte(char b) throws IOException {
            ensureCapacity(1);
            buffer[bufPos++] = (byte) b;
        }

        void print(long value) throws IOException {
            // handle sign
            if (value < 0) {
                writeByte('-');
                value = -value;
            }
            // write digits in reverse order
            byte[] tmp = new byte[30];
            int i = 0;
            do {
                tmp[i++] = (byte) ('0' + (value % 10));
                value /= 10;
            } while (value != 0);
            // write reversed digits
            while (i > 0) {
                writeByte(tmp[--i]);
            }
        }

        void println() throws IOException {
            writeByte('\n');
        }

        void flush() throws IOException {
            out.write(buffer, 0, bufPos);
            out.flush();
            bufPos = 0;
        }

        void close() throws IOException {
            flush();
            out.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “escape the maze” problem.
 * The program reads a rectangular grid, finds the start cell ‘S’,
 * reads a sequence of digits that represent a permutation of movement
 * commands, and counts how many permutations lead from ‘S’ to the exit ‘E’
 * without stepping on a wall.
 */
public class Main {

    /** Directions indexed by the permutation order (0‑3). */
    private enum Direction {
        UP, DOWN, LEFT, RIGHT;

        /** Character used in the input to represent this direction. */
        char representation;

        /** Row offset of the direction. */
        int deltaRow;

        /** Column offset of the direction. */
        int deltaColumn;

        static {
            // Map each enum constant to its input character.
            // The order is arbitrary – the algorithm only cares about the index.
            Direction[] values = values();
            for (int i = 0; i < values.length; i++) {
                Direction d = values[i];
                switch (d.name()) {
                    case "UP"    -> d.representation = '0';
                    case "DOWN"  -> d.representation = '1';
                    case "LEFT"  -> d.representation = '2';
                    case "RIGHT" -> d.representation = '3';
                }
                d.deltaRow = switch (d) {
                    case UP -> -1;
                    case DOWN -> 1;
                    case LEFT, RIGHT -> 0;
                };
                d.deltaColumn = switch (d) {
                    case LEFT -> -1;
                    case RIGHT -> 1;
                    case UP, DOWN -> 0;
                };
            }
        }
    }

    /** Simple wrapper around BufferedReader that returns next token. */
    static final class InputReader {
        private final BufferedReader reader;

        InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            try {
                while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                    tokenizer = new StringTokenizer(reader.readLine());
                }
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        // Reusable tokenizer – recreated lazily.
        private StringTokenizer tokenizer;
    }

    /** Core logic for solving a single test case. */
    static final class Solver {

        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final String commands;
        private final int startRow;
        private final int startCol;

        Solver(char[][] grid, int rows, int cols, String commands, int startRow, int startCol) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.commands = commands;
            this.startRow = startRow;
            this.startCol = startCol;
        }

        /** Returns the number of valid permutations of movements. */
        int countValidPermutations() {
            int[][] initialAssignment = new int[Direction.values().length][2];
            boolean[] used = new boolean[Direction.values().length];
            return backtrack(initialAssignment, used, 0);
        }

        /** Recursive search that tries all unused direction indices. */
        private int backtrack(int[][] assignment, boolean[] used, int depth) {
            if (depth == Direction.values().length) {
                return isValid(assignment) ? 1 : 0;
            }

            int total = 0;
            for (int i = 0; i < Direction.values().length; i++) {
                if (!used[i]) {
                    used[i] = true;
                    assignment[depth][0] = i;          // store the original index
                    assignment[depth][1] = Direction.values()[i].deltaRow; // placeholder
                    total += backtrack(assignment, used, depth + 1);
                    used[i] = false;
                }
            }
            return total;
        }

        /** Determines whether a concrete assignment leads from start to exit. */
        private boolean isValid(int[][] assignment) {
            int r = startRow;
            int c = startCol;

            // Apply each command character of the input string.
            for (char cmdChar : commands.toCharArray()) {
                int dirIndex = cmdChar - '0';                 // 0‑3
                Direction dir = Direction.values()[dirIndex];
                r += dir.deltaRow;
                c += dir.deltaColumn;

                // Check bounds and obstacles.
                if (!inBounds(r, c) || isWall(r, c)) {
                    return false;
                }
                if (isExit(r, c)) {
                    return true;
                }
            }
            return false;
        }

        private boolean inBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean isWall(int r, int c) {
            return grid[r][c] == '#';
        }

        private boolean isExit(int r, int c) {
            return grid[r][c] == 'E';
        }
    }

    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees proper stream closure.
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            InputReader reader = new InputReader(in);
            PrintWriter writer = new PrintWriter(out);

            // ----- INPUT -----
            int height = reader.nextInt();
            int width  = reader.nextInt();

            char[][] grid = new char[height][];
            int startRow = -1, startCol = -1;

            for (int r = 0; r < height; r++) {
                String line = reader.next();
                grid[r] = line.toCharArray();

                // locate start cell ‘S’
                int idx = line.indexOf('S');
                if (idx >= 0) {
                    startRow = r;
                    startCol = idx;
                }
            }

            String commands = reader.next();

            // ----- SOLVE -----
            Solver solver = new Solver(grid, height, width, commands, startRow, startCol);
            int answer = solver.countValidPermutations();

            // ----- OUTPUT -----
            writer.println(answer);
            writer.flush();   // explicit flush mirrors original behaviour
        }
    }
}

