import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Simple path‑finding application that reads a grid, a start cell and a target cell,
 * then computes the shortest cost to reach the target using a variant of Dijkstra’s
 * algorithm.  The implementation is deliberately split into small, single‑purpose
 * classes and methods to improve readability and maintainability.
 */
public class Main {

    /* ------------------------------------------------------------ */
    /*  Constants & helper data structures                           */
    /* ------------------------------------------------------------ */

    /** Movement description – a step (row offset, column offset) and its cost. */
    private static final class Move {
        final int dRow;
        final int dCol;
        final int cost;

        Move(int dRow, int dCol, int cost) {
            this.dRow = dRow;
            this.dCol = dCol;
            this.cost = cost;
        }
    }

    /** Offsets that can be taken from a cell.  Offsets farther than one step cost 1. */
    private static final List<Move> MOVES = List.of(
            // orthogonal moves – cost 0
            new Move(-1, 0, 0), new Move(1, 0, 0),
            new Move(0, -1, 0), new Move(0, 1, 0),
            // diagonal and farther moves – cost 1
            new Move(-1, -1, 1), new Move(-1, 1, 1),
            new Move(1, -1, 1),   new Move(1, 1, 1),
            new Move(-2, 0, 1),   new Move(2, 0, 1),
            new Move(0, -2, 1),   new Move(0, 2, 1)
    );

    /** Simple cell identifier that knows its row and column. */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /* ------------------------------------------------------------ */
    /*  Core algorithm                                                */
    /* ------------------------------------------------------------ */

    private final int height;          // number of rows
    private final int width;           // number of columns
    private final char[][] grid;       // input grid ( '#' = blocked )
    private final int[][] distance;    // shortest known distance to each cell
    private final int[] queueKey;      // auxiliary array to map (r,c) → int for the PQ

    /** Entry point – delegating input handling to {@link FastScanner}. */
    public static void main(String[] args) throws IOException {
        try (FastScanner fs = new FastScanner(System.in)) {
            new Main(fs).solve();
        }
    }

    /** Reads input, runs the algorithm and prints the result. */
    public Main(FastScanner fs) {
        this.height = fs.nextInt();
        this.width  = fs.nextInt();

        int sr = fs.nextInt() - 1;   // start row
        int sc = fs.nextInt() - 1;   // start col
        int tr = fs.nextInt() - 1;   // target row
        int tc = fs.nextInt() - 1;   // target col

        // ----- read the grid -------------------------------------------------
        this.grid = new char[height];
        for (int r = 0; r < height; r++) {
            String line = fs.next();
            this.grid[r] = line.toCharArray();
        }

        // ----- initialise distance matrix -------------------------------------
        this.distance = new int[height][width];
        for (int[] row : distance) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }
        distance[sr][sc] = 0;

        // ----- run Dijkstra ----------------------------------------------------
        runDijkstra(sr, sc, tr, tc);

        // ----- output -----------------------------------------------------------
        System.out.println(distance[tr][tc] == Integer.MAX_VALUE ? -1 : distance[tr][tc]);
    }

    /** Executes Dijkstra’s algorithm using the predefined {@link Move} list. */
    private void runDijkstra(int sr, int sc, int tr, int tc) {
        PriorityQueue<Cell> pq = new PriorityQueue<>(Comparator.comparingInt(c -> distance[c.row][c.col]));

        pq.add(new Cell(sr, sc));
        queueKey = new int[height * width]; // reuse underlying int index if desired

        while (!pq.isEmpty()) {
            Cell cur = pq.poll();

            // Early exit when the target is reached (optional optimisation)
            if (cur.row == tr && cur.col == tc) {
                break;
            }

            int curDist = distance[cur.row][cur.col];
            for (Move move : MOVES) {
                int nr = cur.row + move.dRow;
                int nc = cur.col + move.dCol;
                if (!isInside(nr, nc)) continue;
                if (grid[nr][nc] == '#') continue;               // blocked cell

                int nd = curDist + move.cost;
                if (nd < distance[nr][nc]) {
                    distance[nr][nc] = nd;
                    pq.add(new Cell(nr, nc));
                }
            }
        }
    }

    /** Checks whether a given row/column pair is inside the grid borders. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }

    /* ------------------------------------------------------------ */
    /*  Fast scanner – thin wrapper around BufferedReader               */
    /* ------------------------------------------------------------ */

    /**
     * Minimal scanner that provides primitive convenience methods.
     * It hides the boilerplate of tokenising `BufferedReader` lines.
     */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Reads the next token, retrying until a line is available. */
        private String readNextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt()          { return Integer.parseInt(readNextToken()); }
        long nextLong()        { return Long.parseLong(readNextToken()); }
        double nextDouble()    { return Double.parseDouble(readNextToken()); }
        String nextLine()      { return readNextToken(); }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.Arrays;
