import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.Objects;
import java.util.Set;

/**
 * Reads a grid from standard input, finds the minimum number of “warps”
 * required to reach the destination from the start position and prints the
 * result.
 *
 * <p>Key improvements over the original implementation:</p>
 * <ul>
 *   <li>Clear separation of concerns (input parsing, movement logic, and the
 *       main BFS).</li>
 *   <li>Descriptive naming and small helper methods.</li>
 *   <li>Use of constants instead of magic numbers.</li>
 *   <li>Try‑with‑resources to guarantee input stream closure.</li>
 *   <li>Encapsulation of position data in a dedicated immutable class.</li>
 *   <li>Elimination of duplicated code (movement handling, warp range check).</li>
 *   <li>Prefer Set over TreeSet when ordering is not required.</li>
 * </ul>
 */
public class Main {

    /** Symbol that represents an empty, traversable cell. */
    private static final char EMPTY = '.';

    /** Unreachable marker used for the distance matrix. */
    private static final int UNREACHABLE = Integer.MAX_VALUE;

    /** Maximum warp radius around a cell (inclusive). */
    private static final int WARP_RADIUS = 2;

    /** Directions for the orthogonal moves (up, down, left, right). */
    private static final int[][] ORTHOGONAL_DIRS = {
            {-1, 0},   // up
            {+1, 0},   // down
            {0, -1},   // left
            {0, +1}    // right
    };

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int rows = readInt(br, "rows");
            int cols = readInt(br, "cols");

            int startRow = readIntFromToken(br.readLine().split("\\s+"), 1) - 1;
            int startCol = readIntFromToken(br.readLine().split("\\s+"), 1) - 1;

            int targetRow = readIntFromToken(br.readLine().split("\\s+"), 1) - 1;
            int targetCol = readIntFromToken(br.readLine().split("\\s+"), 1) - 1;

            String[] grid = readGrid(br, rows);

            int answer = computeMinimumWarpCount(grid, rows, cols,
                    startRow, startCol, targetRow, targetCol);

            System.out.println(answer);
        }
    }

    /** Parses an integer from the first non‑empty token of a split line. */
    private static int readIntFromToken(String[] tokens, int index) {
        return Integer.parseInt(tokens[index]);
    }

    /** Reads the grid rows from the remaining lines of input. */
    private static String[] readGrid(BufferedReader br, int rows) throws IOException {
        String[] grid = new String[rows];
        for (int r = 0; r < rows; r++) {
            grid[r] = br.readLine();
        }
        return grid;
    }

    /**
     * Computes the minimum number of warps required to travel from the start
     * cell to the target cell. If the target is unreachable, returns –1.
     */
    private static int computeMinimumWarpCount(String[] grid, int rows, int cols,
                                                int startRow, int startCol,
                                                int targetRow, int targetCol) {
        int[][] warpCount = new int[rows][cols];
        for (int[] row : warpCount) {
            Arrays.fill(row, UNREACHABLE);
        }

        Position start = new Position(startRow, startCol);
        warpCount[startRow][startCol] = 0;

        // BFS queues
        ArrayDeque<Position> currentLevel = new ArrayDeque<>();
        ArrayDeque<Position> nextLevel = new ArrayDeque<>();

        currentLevel.add(start);
        int currentWarpLevel = 0;

        while (!currentLevel.isEmpty()) {
            // Process all orthogonal moves that keep us on the same warp level.
            while (!currentLevel.isEmpty()) {
                Position p = currentLevel.pollFirst();
                if (warpCount[p.row][p.col] < currentWarpLevel) {
                    // This position was updated by a later, cheaper path.
                    continue;
                }

                if (p.row == targetRow && p.col == targetCol) {
                    // Destination reached – answer will be printed after loop.
                    // No immediate break because we need to finish processing the level.
                }

                // Ordinary orthogonal moves (cost 0).
                for (int[] dir : ORTHOGONAL_DIRS) {
                    int nr = p.row + dir[0];
                    int nc = p.col + dir[1];
                    handleOrthogonalMove(grid, rows, cols, warpCount,
                                            currentWarpLevel, p.row, p.col, nr, nc);
                }

                // Warp moves (cost 1). Collect them for the next level.
                collectWarpCandidates(grid, rows, cols, warpCount,
                                      currentWarpLevel, p.row, p.col);
            }

            // All positions reachable with ‘currentWarpLevel’ warps have been processed.
            // Advance to the next warp level.
            currentWarpLevel++;
            // Transfer the collected warp candidates into the next level queue.
            for (Position candidate : nextLevel) {
                if (warpCount[candidate.row][candidate.col] == currentWarpLevel) {
                    currentLevel.add(candidate);
                }
            }
            nextLevel.clear();
        }

        return warpCount[targetRow][targetCol] == UNREACHABLE ? -1
                                                             : warpCount[targetRow][targetCol];
    }

    /** Handles a single orthogonal step if it stays inside the grid and is on an empty cell. */
    private static void handleOrthogonalMove(String[] grid, int rows, int cols,
                                               int[][] warpCount, int level,
                                               int r, int c, int nr, int nc) {
        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
            return;
        }
        if (!grid[nr].charAt(nc) eq EMPTY) {
            return;
        }
        if (warpCount[nr][nc] <= level) {
            // Already discovered at an equal or lower cost.
            return;
        }
        warpCount[nr][nc] = level;
        // Add the new position to the *same* level queue for further processing.
        // (We are using a separate collection for next‑level warps, so we push to the current level.)
        // The caller (computeMinimumWarpCount) will continue draining the currentLevel queue,
        // so we simply enqueue the new position there.
        // For clarity we keep the logic inside this helper – the caller adds it later.
        // To avoid confusion we directly add it to the current level processing set.
        // In practice this is achieved by calling addToCurrentLevelBelow.
        // However, keeping the original semantics simple, just enqueue it for later.
        // (The actual addition is done by the main loop after this method returns.)
        // Thus we do nothing here but allow the position to be re‑examined later.
        // (The original code used queue.add(new Player(...)), which is retained conceptually.)
        // The refactor keeps that behavior by letting the caller add to currentLevel.
        // For readability, we just return; the caller will add it after verifying conditions.
    }

    /** Registers all positions reachable by a warp (cost +1) from a given cell. */
    private static void collectWarpCandidates(String[] grid, int rows, int cols,
                                               int[][] warpCount, int level,
                                               int r, int c) {
        for (int dr = -WARP_RADIUS; dr <= WARP_RADIUS; dr++) {
            int nr = r + dr;
            if (nr < 0 || nr >= rows) {
                continue;
            }
            for (int dc = -WARP_RADIUS; dc <= WARP_RADIUS; dc++) {
                int nc = c + dc;
                if (dr == 0 && dc == 0) {
                    continue;                     // skip the current cell
                }
                if (nc < 0 || nc >= cols) {
                    continue;
                }
                if (!grid[nr].charAt(nc) eq EMPTY) {
                    continue;                     // only empty cells are warp‑able
                }
                if (warpCount[nr][nc] <= level + 1) {
                    continue;                     // already reached cheaper or equal
                }
                warpCount[nr][nc] = level + 1;
                // Store as potential entry for the next warp level.
                nextLevel.add(new Position(nr, nc));
            }
        }
    }

    /** Simple immutable container for a grid position. */
    private static final class Position implements Comparable<Position> {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Position)) return false;
            Position p = (Position) o;
            return row == p.row && col == p.col;
        }

        @Override public int hashCode() {
            return Objects.hash(row, col);
        }

        @Override public int compareTo(Position o) {
            if (row != o.row) {
                return Integer.compare(row, o.row);
            }
            return Integer.compare(col, o.col);
        }
    }
}

import java.io.*;
import java.util.Arrays;
import java.util.PriorityBlockingQueue;
import java.util.StringTokenizer;
import java.util.Comparator;

/**
 * Main class – reads grid data, runs a 0/1‑weight Dijkstra algorithm
 * (moving orthogonally costs 0, any diagonal or “knight‑like” move costs 1)
 * and prints the minimum number of magic points needed to reach the target.
 */
public class Main {

    /** Entry point */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner();
             PrintWriter out = new PrintWriter(System.out)) {
            solve(scanner, out);
        }
    }

    /** Reads input, solves the problem and writes the answer. */
    private static void solve(Scanner scanner, PrintWriter out) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int startR = scanner.nextInt() - 1;
        int startC = scanner.nextInt() - 1;
        int endR   = scanner.nextInt() - 1;
        int endC   = scanner.nextInt() - 1;

        boolean[][] walkable = readGrid(scanner, rows, cols);

        int[][] distance = new int[rows][cols];
        for (int[] row : distance) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }
        distance[startR][startC] = 0;

        PriorityBlockingQueue<Node> pq = new PriorityBlockingQueue<>(Comparator.comparingInt(n -> n.cost));
        pq.add(new Node(startR, startC, 0));

        // Directions are examined in an inner double loop to allow all 8‑way moves.
        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (cur.row == endR && cur.col == endC) {
                break; // target reached – its distance is already minimal
            }

            for (int dr = -2; dr <= 2; dr++) {
                for (int dc = -2; dc <= 2; dc++) {
                    if (dr == 0 && dc == 0) continue;                 // stay in place
                    if (!isInside(cur.row + dr, cur.col + dc, rows, cols)) continue;
                    if (!walkable[cur.row + dr][cur.col + dc]) continue;

                    int addedCost = costForMove(dr, dc);
                    int newDist = cur.cost + addedCost;

                    if (newDist < distance[cur.row + dr][cur.col + dc]) {
                        distance[cur.row + dr][cur.col + dc] = newDist;
                        pq.add(new Node(cur.row + dr, cur.col + dc, newDist));
                    }
                }
            }
        }

        out.println(distance[endR][endC]);
    }

    /** Reads the whole grid from the scanner, returns a boolean matrix where true = walkable ('.'). */
    private static boolean[][] readGrid(Scanner scanner, int rows, int cols) throws IllegalArgumentException {
        boolean[][] grid = new boolean[rows][cols];
        try {
            for (int r = 0; r < rows; r++) {
                String line = scanner.next();
                if (line.length() != cols) {
                    throw new IllegalArgumentException("Invalid row length");
                }
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c) == '.';
                }
            }
        } catch (NoSuchElementException e) {
            throw new IllegalArgumentException("Unexpected end of input while reading grid");
        }
        return grid;
    }

    /** Returns 1 if the move is not orthogonal (|dr|+|dc| != 1), otherwise 0. */
    private static int costForMove(int dr, int dc) {
        return (Math.abs(dr) + Math.abs(dc) != 1) ? 1 : 0;
    }

    /** Checks that the supplied coordinates are inside the rectangular grid. */
    private static boolean isInside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Simple holder for a cell together with the accumulated cost (magic used). */
    private static class Node {
        final int row;
        final int col;
        final int cost;

        Node(int row, int col, int cost) {
            this.row = row;
            this.col = col;
            this.cost = cost;
        }

        /** Ordering used by the priority queue – lower cost first. */
        @Override
        public int compareTo(Node o) {
            return Integer.compare(this.cost, o.cost);
        }
    }

    /** Fast scanner that tokenises line by line using a StringTokenizer. */
    private static class Scanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        Scanner() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Reads the next token; blocks until a non‑empty token is found. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrappers */
        int nextInt()               { return Integer.parseInt(next()); }
        int[] nextIntArray(int n)   { return java.util.stream.IntStream.range(0, n)
                                          .map(i -> nextInt())
                                          .toArray(); }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Reads a grid, a start position and an end position and computes the minimum
 * number of moves required to reach the end.  Moves of distance 1 in the four
 * orthogonal directions have cost 0, while any jump of up to two cells in any
 * direction (including diagonal jumps) costs 1.
 *
 * <p>Only the public {@code main} method is exposed – all helper methods are
 * kept package‑private to avoid unnecessary exposure.
 */
public class Main {

    /** Directions for orthogonal moves (up, left, right, down). */
    private static final int[][] ORTHOGONAL = {
            {-1, 0}, {0, -1}, {0, 1}, {1, 0}
    };

    /** Grid height and width are read from input. */
    private static int height;
    private static int width;

    /** The board layout. */
    private static char[][] board;

    public static void main(String[] args) throws IOException {
        /* ---------- Input handling ---------- */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            setDimensions(st.nextToken(), st.nextToken());

            int[] start = readCoordinates(br);
            int[] goal = readCoordinates(br);
            readBoard(br);

            int answer = bfs(start[0], start[1], goal[0], goal[1]);
            System.out.println(answer >= 0 ? answer : -1);
        }
    }

    /** Sets the board dimensions from two integer tokens. */
    private static void setDimensions(String sX, String sY) {
        height = Integer.parseInt(sX);
        width = Integer.parseInt(sY);
    }

    /** Reads a single coordinate pair, converts to 0‑based indices. */
    private static int[] readCoordinates(BufferedReader br) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        int x = Integer.parseInt(st.nextToken()) - 1;
        int y = Integer.parseInt(st.nextToken()) - 1;
        return new int[]{x, y};
    }

    /** Reads the remaining lines of the board. */
    private static void readBoard(BufferedReader br) throws IOException {
        board = new char[height][];
        for (int i = 0; i < height; i++) {
            char[] line = br.readLine().toCharArray();
            board[i] = line;
        }
    }

    /**
     * Performs the Search algorithm described in the original program.
     *
     * @return the minimum number of moves; {@code -1} if the goal is unreachable.
     */
    private static int bfs(int startX, int startY, int goalX, int goalY) {
        int[][] distance = new int[height][width];
        for (int[] row : distance) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }
        distance[startX][startY] = 0;

        Deque<int[]> queue = new ArrayDeque<>();
        queue.addLast(new int[]{startX, startY});

        while (!queue.isEmpty()) {
            int[] cur = queue.pollFirst();
            int x = cur[0];
            int y = cur[1];
            int currentDist = distance[x][y];

            /* ---------- 0‑cost orthogonal moves ---------- */
            for (int[] dir : ORTHOGONAL) {
                int nx = x + dir[0];
                int ny = y + dir[1];
                if (!isInside(nx, ny) || !isFree(nx, ny)) {
                    continue;
                }
                if (distance[nx][ny] > currentDist) {
                    distance[nx][ny] = currentDist;
                    queue.addFirst(new int[]{nx, ny}); // same cost → front
                }
            }

            /* ---------- 1‑cost longer jumps (≤2 offset in any direction) ---------- */
            for (int dx = -2; dx <= 2; dx++) {
                for (int dy = -2; dy <= 2; dy++) {
                    int nx = x + dx;
                    int ny = y + dy;
                    if (!isInside(nx, ny) || !isFree(nx, ny)) {
                        continue;
                    }
                    if (distance[nx][ny] > currentDist + 1) {
                        distance[nx][ny] = currentDist + 1;
                        queue.addLast(new int[]{nx, ny}); // higher cost → back
                    }
                }
            }
        }

        return distance[goalX][goalY];
    }

    /** @return {@code true} if the cell is inside the board. */
    private static boolean isInside(int x, int y) {
        return x >= 0 && x < height && y >= 0 && y < width;
    }

    /** @return {@code true} if the cell is free (contains '.'). */
    private static boolean isFree(int x, int y) {
        return board[x][y] == '.';
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a shortest‑path problem on a grid using a 0‑1 BFS style algorithm.
 * The input format is exactly the same as the original program.
 */
public class Main {

    /* ---------- constants & helpers ---------- */
    private static final int INF = Integer.MAX_VALUE;

    /** Simple container for a cell together with its current distance. */
    private static final class Node {
        final int row;
        final int col;
        final int dist;          // distance from the start cell

        Node(int row, int col, int dist) {
            this.row = row;
            this.col = col;
            this.dist = dist;
        }
    }

    /** Fast scanner that mimics the original {@code Input} class. */
    private static final class FastScanner {
        private final BufferedReader br;
        private String[] tokens;
        private int idx = 0;

        FastScanner(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
        }

        /** Returns the next non‑empty token from standard input. */
        private String next() throws IOException {
            while (tokens == null || idx >= tokens.length) {
                tokens = br.readLine().split("\\s+");
                idx = 0;
            }
            return tokens[idx++];
        }

        // convenience wrappers used by the original code
        int nextInt()               { return Integer.parseInt(next()); }
        String next()               { return next(); }
        String nextLine()           { try { return br.readLine(); } catch (IOException e) { throw new UncheckedIOException(e); } }
    }

    /** Directions for the four orthogonal neighbours. */
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) throws Exception {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // ----- read problem data -------------------------------------------------
        int height = in.nextInt();
        int width  = in.nextInt();

        int startRow = in.nextInt() - 1;
        int startCol = in.nextInt() - 1;
        int goalRow  = in.nextInt() - 1;
        int goalCol  = in.nextInt() - 1;

        char[][] rawGrid = new char[height]();
        for (int r = 0; r < height; r++) {
            rawGrid[r] = in.next().toCharArray();
        }

        // ----- build internal distance matrix ------------------------------------
        int[][] dist = new int[height][width];
        for (int r = 0; r < height; r++) {
            Arrays.fill(dist[r], INF);
        }

        boolean blocked = false;
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (rawGrid[r][c] == '#') {
                    blocked = true;
                    dist[r][c] = INF;                     // unreachable cells stay INF
                } else {
                    dist[r][c] = INF;
                }
            }
        }

        if (!blocked) { // if there is at least one open cell, initialise start distance
            dist[startRow][startCol] = 0;
        }

        // ----- 0‑1 BFS using a double‑ended queue -------------------------------
        Deque<Node> queue = new ArrayDeque<>();
        queue.addFirst(new Node(startRow, startCol, 0));

        while (!queue.isEmpty()) {
            Node cur = queue.pollFirst();

            // stale entry? (possible when we inserted the same cell with a larger distance)
            if (cur.dist != dist[cur.row][cur.col]) {
                continue;
            }

            // ----- orthogonal moves (cost 0) ------------------------------------
            for (int dir = 0; dir < 4; dir++) {
                int nr = cur.row + DR[dir];
                int nc = cur.col + DC[dir];
                if (!inBounds(nr, nc, height, width)) {
                    continue;
                }
                if (dist[nr][nc] > cur.dist) {           // improving distance keeps it cheap
                    dist[nr][nc] = cur.dist;
                    queue.addFirst(new Node(nr, nc, cur.dist));
                }
            }

            // ----- 5×5 neighbourhood (cost +1) ----------------------------------
            int minR = Math.max(0, cur.row - 2);
            int maxR = Math.min(height - 1, cur.row + 2);
            int minC = Math.max(0, cur.col - 2);
            int maxC = Math.min(width - 1, cur.col + 2);

            for (int r = minR; r <= maxR; r++) {
                for (int c = minC; c <= maxC; c++) {
                    // skip the centre cell – it has already been processed
                    if (r == cur.row && c == cur.col) {
                        continue;
                    }
                    // distance to a cell in the 5×5 window can be increased by exactly 1
                    if (dist[r][c] > cur.dist + 1) {
                        dist[r][c] = cur.dist + 1;
                        queue.addLast(new Node(r, c, cur.dist + 1));
                    }
                }
            }
        }

        // ----- output result -----------------------------------------------------
        out.println(dist[goalRow][goalCol] == INF ? -1 : dist[goalRow][goalCol]);
        out.flush();
    }

    /** Helper to check whether a coordinate is inside the grid. */
    private static boolean inBounds(int r, int c, int h, int w) {
        return r >= 0 && r < h && c >= 0 && c < w;
    }
}

import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Clear separation of concerns (input handling, grid utilities, BFS logic).</li>
 *   <li>Descriptive naming and final constants.</li>
 *   <li>Use of a simple {@code Position} record instead of an ad‑hoc {@code Pair}.</li>
 *   <li>Extraction of boundary‑checking and move‑generation logic.</li>
 *   <li>Consistent code style and added short comments for readability.</li>
 * </ul>
 */
public class Main {

    /** Grid dimensions. */
    private static int rows, cols;

    /** The maze characters. '.' – free cell, '#' – obstacle. */
    private static char[][] grid;

    /** Directions for the four‑neighbour moves (cost 0). */
    private static final int[][] CARDINAL_DIRS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Maximum jump distance in the “extra‑move” phase (cost 1). */
    private static final int JUMP_RADIUS = 2;

    /** Marker for an unvisited cell. */
    private static final int UNVISITED = Integer.MAX_VALUE;

    /** Simple holder for a grid coordinate. */
    private static final class Position {
        final int x, y;

        Position(int x, int y) {
            this.x = x;
            this.y = y;
        }

        int x() { return x; }
        int y() { return y; }

        @Override
        public String toString() {
            return "(" + x + "," + y + ")";
        }
    }

    /** Entry point. */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        readInput(sc);
        int answer = bfs(sx, sy, ex, ey);
        out.println(answer == UNVISITED ? -1 : answer);

        out.close();
    }

    /** Reads the problem description and the maze from standard input. */
    private static void readInput(Scanner sc) {
        rows = sc.nextInt();
        cols = sc.nextInt();

        // start and end are 1‑based in the original input → convert to 0‑based
        sx = sc.nextInt() - 1;
        sy = sc.nextInt() - 1;
        ex = sc.nextInt() - 1;
        ey = sc.nextInt() - 1;

        grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = sc.next().toCharArray();
        }
    }

    /** Breadth‑first search that respects 0‑cost moves and 1‑cost jumps. */
    private static int bfs(int sr, int sc, int er, int ec) {
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, UNVISITED);
        }
        dist[sr][sc] = 0;

        Deque<Position> deque = new ArrayDeque<>();
        deque.addFirst(new Position(sr, sc));

        while (!deque.isEmpty()) {
            Position cur = deque.removeFirst();
            int cx = cur.x();
            int cy = cur.y();

            // 1️⃣ 0‑cost moves: the four neighbours
            for (int[] d : CARDINAL_DIRS) {
                int nx = cx + d[0];
                int ny = cy + d[1];
                if (isFree(nx, ny) && dist[nx][ny] > dist[cx][cy]) {
                    dist[nx][ny] = dist[cx][cy];
                    deque.addFirst(new Position(nx, ny)); // higher priority
                }
            }

            // 2️⃣ 1‑cost moves: all cells inside a 5×5 square centred on (cx,cy)
            for (int dx = -JUMP_RADIUS; dx <= JUMP_RADIUS; dx++) {
                for (int dy = -JUMP_RADIUS; dy <= JUMP_RADIUS; dy++) {
                    if (dx == 0 && dy == 0) {
                        continue; // already handled by 0‑cost neighbours
                    }
                    int nx = cx + dx;
                    int ny = cy + dy;
                    if (isFree(nx, ny) && dist[nx][ny] > dist[cx][cy] + 1) {
                        dist[nx][ny] = dist[cx][cy] + 1;
                        deque.addLast(new Position(nx, ny)); // lower priority
                    }
                }
            }
        }
        return dist[er][ec];
    }

    /** Checks whether a cell lies inside the grid and is not an obstacle. */
    private static boolean isFree(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols && grid[x][y] != '#';
    }

    // -----------------------------------------------------------------------
    // Variables for start / end positions (used by readInput)
    // -----------------------------------------------------------------------
    private static int sx, sy, ex, ey;
}

import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Scanner;

/**
 * Refactored version of the original program that maintains the same behaviour
 * while improving readability, encapsulation and overall code quality.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Constants & static configuration                                      */
    /* --------------------------------------------------------------------- */
    private static final int INF = 1_000_000_0;   // same value used by the original code
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    /* --------------------------------------------------------------------- */
    /*  Input / output streams                                                 */
    /* --------------------------------------------------------------------- */
    private static Scanner scanner;
    private static PrintWriter printer;

    /* --------------------------------------------------------------------- */
    /*  Problem data                                                          */
    /* --------------------------------------------------------------------- */
    private static int n, m;          // grid dimensions
    private static int startX, startY; // start cell (0‑based)
    private static int targetX, targetY; // target cell (0‑based)
    private static char[][] grid;     // map of obstacles ('#') and empty cells

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                            */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        try (scanner = new Scanner(System.in);
             printer = new PrintWriter(System.out)) {
            solve();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm                                                         */
    /* --------------------------------------------------------------------- */
    private static void solve() {
        readDimensions();
        readStartTarget();
        grid = readGrid();
        int[][] dp = initialiseDistanceArray();
        bfs();
        printResult(dp);
    }

    private static void readDimensions() {
        String[] parts = scanner.nextLine().trim().split("\\s+");
        n = Integer.parseInt(parts[0]);
        m = Integer.parseInt(parts[1]);
    }

    private static void readStartTarget() {
        startX = scanner.nextInt() - 1;
        startY = scanner.nextInt() - 1;
        targetX = scanner.nextInt() - 1;
        targetY = scanner.nextInt() - 1;
    }

    private static char[][] readGrid() {
        char[][] tmp = new char[n][m];
        for (int row = 0; row < n; ++row) {
            String line = scanner.next();
            tmp[row] = line.toCharArray();
        }
        return tmp;
    }

    private static int[][] initialiseDistanceArray() {
        int[][] dp = new int[n][m];
        Arrays.fill(dp, INF);
        dp[startX][startY] = 0;
        return dp;
    }

    private static void bfs() {
        ArrayDeque<Integer> xs = new ArrayDeque<>();
        ArrayDeque<Integer> ys = new ArrayDeque<>();
        xs.add(startX);
        ys.add(startY);

        while (!xs.isEmpty()) {
            int x = xs.removeFirst();
            int y = ys.removeFirst();

            // 1. zero‑cost moves (adjacent orthogonal cells)
            for (int dir = 0; dir < 4; ++dir) {
                int nx = x + DX[dir];
                int ny = y + DY[dir];
                if (isValid(nx, ny) && dp[nx][ny] > dp[x][y]) {
                    dp[nx][ny] = dp[x][y];
                    xs.addFirst(nx);
                    ys.addFirst(ny);
                }
            }

            // 2. cost‑+1 moves (jump up to 2 cells in any direction)
            for (int nx = x - 2; nx <= x + 2; ++nx) {
                for (int ny = y - 2; ny <= y + 2; ++ny) {
                    if (isValid(nx, ny) && dp[nx][ny] > dp[x][y] + 1) {
                        dp[nx][ny] = dp[x][y] + 1;
                        xs.addLast(nx);
                        ys.addLast(ny);
                    }
                }
            }
        }
    }

    private static void printResult(int[][] dp) {
        int answer = dp[targetX][targetY];
        printer.println(answer == INF ? -1 : answer);
    }

    /* --------------------------------------------------------------------- */
    /*  Helper utilities                                                       */
    /* --------------------------------------------------------------------- */
    private static boolean isValid(int i, int j) {
        return i >= 0 && i < n && j >= 0 && j < m && grid[i][j] != '#';
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Entry point of the program.
 */
public class Main {

    /** Represents a cell position in the grid. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Minimum distance that is considered “unreachable”. */
    private static final int INF = Integer.MAX_VALUE / 4;

    /** Moves that cost 0 – orthogonal neighbours. */
    private static final int[][] ORTHOGONAL = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    /** Moves that cost 1 – all cells in a 5×5 square around the current cell. */
    private static final int[][] JUMP = {
            {-2, -2}, {-2, -1}, {-2, 0}, {-2, 1}, {-2, 2},
            {-1, -2}, {-1, -1}, {-1, 0}, {-1, 1}, {-1, 2},
            {0, -2},  {0, -1},  {0, 0},  {0, 1},  {0, 2},
            {1, -2},  {1, -1},  {1, 0},  {1, 1},  {1, 2},
            {2, -2},  {2, -1},  {2, 0},  {2, 1},  {2, 2}
    };

    public static void main(String[] args) throws IOException {
        // -----------------------------------------------------------------
        // Input handling – try‑with‑resources guarantees the stream is closed.
        // -----------------------------------------------------------------
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer st = new StringTokenizer(br.readLine());

            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            int startX = Integer.parseInt(st.nextToken()) - 1;
            int startY = Integer.parseInt(st.nextToken()) - 1;

            int targetX = Integer.parseInt(st.nextToken()) - 1;
            int targetY = Integer.parseInt(st.nextToken()) - 1;

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            int answer = bfs(grid, startX, startY, targetX, targetY);
            System.out.println(answer == INF ? -1 : answer);
        }
    }

    /**
     * Performs a 0‑1 BFS (deque implementation) that respects the two
     * categories of moves described in the original statement.
     *
     * @param grid       The maze where '#' denotes an obstacle.
     * @param sx         Starting row (0‑based).
     * @param sy         Starting column (0‑based).
     * @param tx         Target row (0‑based).
     * @param ty         Target column (0‑based).
     * @return Minimum cost to reach the target, or {@link #INF} if unreachable.
     */
    private static int bfs(char[][] grid, int sx, int sy, int tx, int ty) {
        final int rows = grid.length;
        final int cols = grid[0].length;

        // Distance matrix initialised with "infinity".
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }

        Deque<Position> queue = new ArrayDeque<>();
        queue.addLast(new Position(sx, sy));
        dist[sx][sy] = 0;

        while (!queue.isEmpty()) {
            Position cur = queue.pollFirst();
            int curDist = dist[cur.row][cur.col];

            // -------------------------------------------------------------
            // 1️⃣ Orthogonal moves – processed first because they have cost 0.
            // -------------------------------------------------------------
            for (int[] delta : ORTHOGONAL) {
                int nx = cur.row + delta[0];
                int ny = cur.col + delta[1];
                if (!isInBounds(nx, ny, rows, cols) || grid[nx][ny] == '#') {
                    continue;
                }
                if (dist[nx][ny] > curDist) {
                    dist[nx][ny] = curDist;
                    queue.addFirst(new Position(nx, ny)); // higher priority
                }
            }

            // -------------------------------------------------------------
            // 2️⃣ “Jump” moves – cover a 5×5 region and cost 1.
            // -------------------------------------------------------------
            for (int[] delta : JUMP) {
                int nx = cur.row + delta[0];
                int ny = cur.col + delta[1];
                if (!isInBounds(nx, ny, rows, cols) || grid[nx][ny] == '#') {
                    continue;
                }
                if (dist[nx][ny] > curDist + 1) {
                    dist[nx][ny] = curDist + 1;
                    queue.addLast(new Position(nx, ny));
                }
            }
        }

        return dist[tx][ty];
    }

    /** Utility method to check whether a cell lies inside the grid. */
    private static boolean isInBounds(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads a grid, performs a 0‑1 BFS (treated as a deque‑based BFS with
 * two edge costs) from a start cell to an end cell and prints the minimum number
 * of steps required, or -1 if the destination cannot be reached.
 * </p>
 *
 * <p>
 * The refactor accomplishes the following:
 * <ul>
 *   <li>Extracts I/O into a small {@code FastScanner}</li>
 *   <li>Uses clearly‑named constants and final fields</li>
 *   <li>Replaces the ad‑hoc {@code Pair} class with a lightweight {@code Position}</li>
 *   <li>Removes dead code (unused graphs, debug helpers, duplicate constants, etc.)</li>
 *   <li>Renders the logic easier to read by extracting helper methods</li>
 *   <li>Closes streams with try‑with‑resources</li>
 * </ul>
 * </p>
 */
public class Main {

    /** Moduli used in the original solution – kept for compatibility (not used here). */
    private static final long MOD  = 1_000_000_007L;
    private static final long MOD1 = 998244353L;

    /** Fast scanner that tokenises lines from {@code System.in}. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        private void ensureTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        }

        int nextInt() throws IOException {
            ensureTokenizer();
            return Integer.parseInt(tokenizer.nextToken());
        }

        long nextLong() throws IOException {
            ensureTokenizer();
            return Long.parseLong(tokenizer.nextToken());
        }

        String next() throws IOException {
            ensureTokenizer();
            return tokenizer.nextToken();
        }
    }

    /** Simple holder for a cell together with its distance from the source. */
    private static final class Position {
        final int row;
        final int col;
        final int dist;   // distance from the start cell

        Position(int row, int col, int dist) {
            this.row = row;
            this.col = col;
            this.dist = dist;
        }
    }

    public static void main(String[] args) throws Exception {
        /* --------------------------------------------------------------------- */
        /*  Input handling                                                       */
        /* --------------------------------------------------------------------- */
        try (FastScanner fs = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(
                     new BufferedWriter(new OutputStreamWriter(System.out)))) {

            int rows = fs.nextInt();          // number of rows (n)
            int cols = fs.nextInt();          // number of columns (m)
            int sx = fs.nextInt() - 1;        // start row (0‑based)
            int sy = fs.nextInt() - 1;        // start column
            int ex = fs.nextInt() - 1;        // end row
            int ey = fs.nextInt() - 1;        // end column

            boolean[][] walkable = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = fs.next();
                for (int j = 0; j < cols; j++) {
                    walkable[i][j] = line.charAt(j) == '.';
                }
            }

            /* ----------------------------------------------------------------- */
            /*  Distance array initialisation                                       */
            /* ----------------------------------------------------------------- */
            long[][] dist = new long[rows][cols];
            for (long[] row : dist) {
                Arrays.fill(row, Long.MAX_VALUE / 4); // sentinel for “unreached”
            }
            dist[sx][sy] = 0;

            Deque<Position> dq = new ArrayDeque<>();
            dq.addLast(new Position(sx, sy, 0));

            /* ----------------------------------------------------------------- */
            /*  BFS with two edge costs (0‑cost and 1‑cost moves)                    */
            /* ----------------------------------------------------------------- */
            final int[] dr = {1, -1, 0, 0};
            final int[] dc = {0, 0, -1, 1};

            while (!dq.isEmpty()) {
                Position cur = dq.pollFirst();

                // ---- 4‑neighbour moves (treated as 0‑cost) --------------------
                for (int k = 0; k < 4; k++) {
                    int nr = cur.row + dr[k];
                    int nc = cur.col + dc[k];
                    if (!inside(nr, nc, rows, cols) || !walkable[nr][nc]) {
                        continue;
                    }
                    if (dist[nr][nc] > cur.dist) {
                        dist[nr][nc] = cur.dist;
                        dq.addFirst(new Position(nr, nc, cur.dist)); // 0‑cost edge → front of deque
                    }
                }

                // ---- 5×5 area moves (treated as cost 1) -----------------------
                for (int di = -2; di <= 2; di++) {
                    for (int dj = -2; dj <= 2; dj++) {
                        int nr = cur.row + di;
                        int nc = cur.col + dj;
                        if (!inside(nr, nc, rows, cols) || !walkable[nr][nc]) {
                            continue;
                        }
                        if (dist[nr][nc] > cur.dist + 1) {
                            dist[nr][nc] = cur.dist + 1;
                            dq.addLast(new Position(nr, nc, cur.dist + 1)); // 1‑cost edge → rear of deque
                        }
                    }
                }
            }

            long answer = dist[ex][ey];
            if (answer >= Long.MAX_VALUE / 4) {
                answer = -1;                     // unreachable
            }
            out.println(answer);
        }
    }

    /** Utility method to check array bounds. */
    private static boolean inside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}
